INSERT INTO characters (char, data) VALUES ('爹', '{"9000": "2001.0", "Chữ Trung Quốc": "爹", "Bộ thủ & thành phần_Xie": "Bộ thủ | 父 | Số nét | 10 | nét | 父 | phụ | biểu nghĩa | cha, phụ | 多 | đa | biểu âm | nhiều (cho âm diē) | 爹 = 父(Phụ, biểu nghĩa: cha) + 多 (Đa, biểu âm); chữ hình thanh. Bộ phụ chỉ nghĩa là cha, đa cho âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tía\": cha (父) có nhiều (多) con — tía ơi, cách gọi cha thân thương của người miền Nam. | Gương Hán-Việt | tía (爹 – cha, bố trong phương ngữ) | Mở khoá kiến thức | Biết 爹 mở khoá: 爹爹 (tía tía – bố bố), 爹妈 (tía má – bố mẹ), cách gọi cha phương ngữ phổ biến.", "Tự nguyên_Xie": "Wiktionary ghi 爹 là hình thanh: 父 (cha, biểu nghĩa) + 多 (biểu âm). Đây là cách gọi cha thân mật trong nhiều phương ngữ tiếng Trung, đặc biệt miền Bắc và Tây Nam. Tiếng Việt đọc là ''tía'' — cách gọi cha miền Nam Việt Nam. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cha, bố", "Hạng Tần Suất (Jun Da)": "2001.0", "Tần Suất % (Jun Da)": "97.1420877679", "GavinGrover_Once (Chiết tự trực tiếp)": "父 + 多", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱父多", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "多", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "父", "Unihan_Simplified (Chữ Giản thể)": "爹", "Unihan_Traditional (Chữ Phồn thể)": "爹", "Pinyin_Xie": "diē", "Âm Hán Việt_Xie": "đa", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ xưng hô trong gia đình để gọi cha hoặc bố. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Gia đình tôi", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('酬', '{"9000": "2002.0", "Chữ Trung Quốc": "酬", "Bộ thủ & thành phần_Xie": "Bộ thủ | 酉 | Số nét | 13 | nét | 酉 | dậu | biểu nghĩa | bình rượu, rượu | 州 | châu | biểu âm | âm gốc chóu | 酬 = 酉 (Dậu, biểu nghĩa: bình rượu/rượu) + 州 (Châu, biểu âm); chữ hình thanh. Ý gốc là dâng rượu trang trọng, mời rượu để báo đáp ân nghĩa.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thù\": bình rượu (酉) dâng khắp mọi châu (州) — báo đáp thù ân bằng chén rượu trịnh trọng. | Gương Hán-Việt | thù trong \"báo thù\" (thù lao, báo đáp — khác nghĩa báo thù trả thù), \"ứng thù\" (ứng đáp xã hội) | Mở khoá kiến thức | Biết 酬 (thù) mở khoá: 应酬 (tiếp khách xã giao), 报酬 (thù lao), 酬谢 (cảm ơn đáp lễ), 酬劳 (phần thưởng).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 酬 là chữ hình thanh gồm 酉 (biểu nghĩa: bình rượu, rượu) và 州 (biểu âm, cho âm chóu). Nghĩa gốc là dâng rượu trang trọng để mời và báo đáp; mở rộng thành thưởng công, trả thù lao, giao tiếp xã hội. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mời rượu; đền đáp lại", "Hạng Tần Suất (Jun Da)": "2002.0", "Tần Suất % (Jun Da)": "97.1457109485", "GavinGrover_Once (Chiết tự trực tiếp)": "酉 + 州", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰酉州", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "州", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "酉", "Unihan_Simplified (Chữ Giản thể)": "酬", "Unihan_Traditional (Chữ Phồn thể)": "詶", "Pinyin_Xie": "chóu", "Âm Hán Việt_Xie": "thù", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường làm động từ trong các từ ghép chỉ sự đền đáp hoặc thù lao. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('儒', '{"9000": "2003.0", "Chữ Trung Quốc": "儒", "Bộ thủ & thành phần_Xie": "Bộ thủ | 人 | Số nét | 16 | nét | 亻 | nhân | biểu nghĩa | người | 需 | nhu | biểu âm | âm gốc rú | 儒 = 亻(Nhân, biểu nghĩa: người) + 需 (Nhu, biểu âm); chữ hình thanh. Ý gốc là người học giả Nho gia, người được xã hội cần đến (需 cũng gợi nghĩa \"cần thiết\").", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nho\": người (亻) được xã hội cần (需) đến — đó là nhà nho, người học vấn được trọng dụng. | Gương Hán-Việt | nho trong \"Nho giáo\", \"nho học\", \"Nho gia\" — hệ tư tưởng trọng học vấn của Khổng Tử | Mở khoá kiến thức | Biết 儒 (nho) mở khoá: 儒学 (Nho giáo), 儒家 (Nho gia), 儒雅 (nho nhã, lịch sự), 大儒 (bậc đại nho).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Theo Wiktionary, 儒 là chữ hình thanh gồm 人 (biểu nghĩa: người, viết tắt thành 亻) và 需 (biểu âm, cho âm rú). Nghĩa gốc là học giả Nho gia, người uyên bác; sau dùng chỉ toàn bộ hệ tư tưởng Nho giáo. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "học trò; nho nhã; đạo Nho", "Hạng Tần Suất (Jun Da)": "2003.0", "Tần Suất % (Jun Da)": "97.1493305116", "GavinGrover_Once (Chiết tự trực tiếp)": "亻 + 需", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰亻需", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "需", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "亻", "Unihan_Simplified (Chữ Giản thể)": "儒", "Unihan_Traditional (Chữ Phồn thể)": "儒", "Pinyin_Xie": "rú", "Âm Hán Việt_Xie": "nho", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Thường làm danh từ chỉ người theo Nho giáo hoặc tính từ chỉ sự nho nhã. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('姻', '{"9000": "2004.0", "Chữ Trung Quốc": "姻", "Bộ thủ & thành phần_Xie": "Bộ thủ | 女 | Số nét | 9 | nét | 女 | nữ | biểu nghĩa | người phụ nữ | 因 | nhân | biểu âm | nguyên nhân, vì; cho âm yīn | 姻 = 女 (Nữ, biểu nghĩa: phụ nữ) + 因 (Nhân, biểu âm: cho âm yīn). Chữ hình thanh — bộ nữ chỉ liên quan đến hôn nhân của phụ nữ, 因 cho âm. Nghĩa: hôn nhân, quan hệ thông gia.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nhân\": 姻 = 女(nữ) + 因(nhân) — nhân (duyên) hôn nhân là cái nhân 因 (nguyên nhân) kết đôi người nữ với gia đình mới. | Gương Hán-Việt | nhân trong 婚姻 (hôn nhân — hôn nhân), 姻緣 (nhân duyên — duyên hôn). | Mở khoá kiến thức | Biết 姻 mở khoá: 婚姻 (hôn nhân), 姻亲 (bà con thông gia), 姻缘 (duyên hôn).", "Tự nguyên_Xie": "Wiktionary xác nhận: 姻 là hình thanh, 女 (phụ nữ, biểu nghĩa) + 因 (biểu âm). Ý nghĩa bổ sung: hôn nhân liên quan đến phụ nữ (nhà gái). Nghĩa gốc: hôn nhân — quan hệ kết đôi giữa nam và nữ. Mở rộng: quan hệ thông gia (姻亲 — bà con thông gia), duyên phận (姻缘 — duyên hôn). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "368.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Nữ (60) Nhân (42)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Nhân (số 134 - nguyên nhân) chỉ âm, chữ Nữ (số 86) chỉ ý. Người con gái (nữ) là nguyên nhân để người con trai chọn làm vợ (hôn nhân). Giải thích sự chuyển ý: Chữ Nhân (nguyên nhân) chỉ âm, chữ Nữ (phụ nữ) chỉ ý. Người phụ nữ (Nữ) chính là nguyên nhân (Nhân) tạo nên mối quan hệ hôn nhân giữa hai gia đình (Nhân).", "Nghĩa Tiếng Việt_Xie": "nhà trai (trong đám cưới); bố chồng", "Hạng Tần Suất (Jun Da)": "2004.0", "Tần Suất % (Jun Da)": "97.1529469739", "GavinGrover_Once (Chiết tự trực tiếp)": "女 + 因", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰女因", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "因", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "女", "Unihan_Simplified (Chữ Giản thể)": "姻", "Unihan_Traditional (Chữ Phồn thể)": "姻", "Pinyin_Xie": "yīn", "Âm Hán Việt_Xie": "nhân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường kết hợp với các từ khác để tạo thành danh từ chỉ quan hệ hôn nhân. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('卵', '{"9000": "2005.0", "Chữ Trung Quốc": "卵", "Bộ thủ & thành phần_Xie": "Bộ thủ | 卩 | Số nét | 7 | nét | 卵 | noãn | tượng hình | hai quả trứng | 卵 là tượng hình: hai quả trứng/trứng cá (spawn). Cấu trúc ⿰𠂑卪 là hai phần đối xứng biểu thị hai trứng đặt cạnh nhau. Đây là chữ tượng hình thuần tuý.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"noãn\": hai quả trứng (⿰𠂑卪) đặt cạnh — noãn sào, noãn bào, trứng trong y học và sinh học. | Gương Hán-Việt | noãn sào (卵巢 – buồng trứng), noãn bào | Mở khoá kiến thức | Biết 卵 mở khoá: 卵巢 (noãn sào – buồng trứng), 排卵 (bài noãn – rụng trứng), 受精卵 (thụ tinh noãn).", "Tự nguyên_Xie": "Kim văn | Tiểu triện | Wiktionary ghi 卵 là tượng hình: hình ảnh hai quả trứng hoặc trứng cá. Nghĩa gốc là trứng (tổng quát). Hán-Việt đọc là ''noãn'' — noãn sào (buồng trứng), noãn bào (tế bào trứng). Trong tiếng Trung hiện đại còn dùng 蛋 (đản) thông dụng hơn. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1161.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Mão (1075) Chủ (003)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Có hai dấu chấm (bộ Chủ số 003) nằm bên trong chữ Mão (số 1075). Hình ảnh hạt giống đang nằm trong vỏ bọc. Giải thích sự chuyển ý: Đây là chữ Tượng hình. Noãn là quả trứng (noãn hoàn).", "Nghĩa Tiếng Việt_Xie": "quả trứng; hột dái", "Hạng Tần Suất (Jun Da)": "2005.0", "Tần Suất % (Jun Da)": "97.1565494831", "GavinGrover_Once (Chiết tự trực tiếp)": "卪", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴卪", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "卵", "Unihan_Traditional (Chữ Phồn thể)": "卵", "Pinyin_Xie": "luǎn", "Âm Hán Việt_Xie": "noãn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Thường làm danh từ chỉ trứng của động vật hoặc tế bào sinh dục cái. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | luǎn | / | trứng | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Nội dung II", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('氛', '{"9000": "2006.0", "Chữ Trung Quốc": "氛", "Bộ thủ & thành phần_Xie": "Bộ thủ | 气 | Số nét | 8 | nét | 气 | khí | biểu nghĩa | hơi, khí (bộ khí giản thể) | 分 | phân | biểu âm | phân chia; cho âm fēn | 氛 = 气 (Khí, biểu nghĩa: hơi/khí) + 分 (Phân, biểu âm: cho âm fēn). Chữ hình thanh — bộ khí chỉ liên quan đến không khí, hơi, khí quyển, 分 cho âm. Nghĩa: khí quyển, bầu không khí (theo nghĩa cả vật lý lẫn ẩn dụ).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phân\": 氛 = 气(khí) + 分(phân) — phân khí toả ra xung quanh bao phủ bầu 氛围 (không khí), khí 气氛 lan phân tán khắp nơi. | Gương Hán-Việt | phân trong 氛圍 (phân vi — bầu không khí, môi trường), 氣氛 (khí phân — không khí). | Mở khoá kiến thức | Biết 氛 mở khoá: 气氛 (không khí/bầu không khí), 氛围 (môi trường, bầu không khí xung quanh).", "Tự nguyên_Xie": "Wiktionary xác nhận: 氛 là hình thanh, 气 (hơi/khí, biểu nghĩa) + 分 (biểu âm). Nghĩa gốc (cổ): bầu không khí, khí xấu (miasma), hơi độc. Hiện đại: bầu không khí, không khí xung quanh — thường dùng trong 气氛 (không khí, bầu không khí) và 氛围 (không khí/môi trường cảm xúc). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "khí, hơi", "Hạng Tần Suất (Jun Da)": "2006.0", "Tần Suất % (Jun Da)": "97.1601504419", "GavinGrover_Once (Chiết tự trực tiếp)": "气 + 分", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴气分", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "分", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "气", "Unihan_Simplified (Chữ Giản thể)": "氛", "Unihan_Traditional (Chữ Phồn thể)": "氛", "Pinyin_Xie": "fēn", "Âm Hán Việt_Xie": "phân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường kết hợp với các từ khác để chỉ bầu không khí hoặc trạng thái môi trường. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('泄', '{"9000": "2007.0", "Chữ Trung Quốc": "泄", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 8 | nét | 氵 | thuỷ | biểu nghĩa | nước | 世 | thế | biểu âm | âm gốc xiè | 泄 = 氵(Thuỷ, biểu nghĩa: nước, chất lỏng) + 世 (Thế, biểu âm); chữ hình thanh. Ý gốc là để chất lỏng chảy ra ngoài, xả ra.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tiết\": nước (氵) theo thế (世) mà chảy ra — tiết lộ, xả ra như nước vỡ bờ. | Gương Hán-Việt | tiết trong \"tiết lộ\" (để lộ), \"phát tiết\" (xả ra, biểu lộ) | Mở khoá kiến thức | Biết 泄 (tiết) mở khoá: 泄露 (tiết lộ), 泄气 (nản chí, xì hơi), 发泄 (xả giận), 宣泄 (bộc lộ cảm xúc).", "Tự nguyên_Xie": "Tiểu triện | 泄 có cấu trúc hình thanh với 氵(nước) và 世 (biểu âm). Wiktionary cung cấp chi tiết phát âm và nghĩa: nghĩa gốc là để chất lỏng hoặc khí thoát ra (泄洪: xả lũ, 排泄: bài tiết); mở rộng thành để lộ bí mật (泄露: tiết lộ) và giải tỏa cảm xúc (泄愤: xả giận). chưa có nguồn học thuật rõ về biến đổi ngữ nghĩa này. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "phát tiết ra, lộ ra ngoài", "Hạng Tần Suất (Jun Da)": "2007.0", "Tần Suất % (Jun Da)": "97.1637446826", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 世", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵世", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "世", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "泄", "Unihan_Traditional (Chữ Phồn thể)": "泄", "Pinyin_Xie": "xiè", "Âm Hán Việt_Xie": "tiết", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước tân ngữ để chỉ việc làm lộ thông tin hoặc xả chất lỏng. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | xiè | / | xả | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Từ III", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('杆', '{"9000": "2008.0", "Chữ Trung Quốc": "杆", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 7 | nét | 木 | mộc | biểu nghĩa | gỗ, cây | 干 | can | biểu âm | âm gốc gān/gǎn | 杆 = 木 (Mộc, biểu nghĩa: gỗ, cây) + 干 (Can, biểu âm); chữ hình thanh. Ý gốc là cây gậy, thanh gỗ dài.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"can\": gỗ (木) thẳng như cây can (干) — đó là cái gậy, cột lan can. | Gương Hán-Việt | can trong \"lan can\" (lan can cầu thang), \"đòn can\" (đòn bẩy bằng gỗ) | Mở khoá kiến thức | Biết 杆 (can) mở khoá: 杠杆 (đòn bẩy), 栏杆 (lan can), 电线杆 (cột điện), 旗杆 (cột cờ).", "Tự nguyên_Xie": "Theo Wiktionary, 杆 là chữ hình thanh gồm 木 (biểu nghĩa: gỗ, cây) và 干 (biểu âm, cho âm gān). Nghĩa gốc là cây gậy, thanh gỗ thẳng; mở rộng thành bất kỳ vật hình que dài (lan can, đòn bẩy, cột). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1262.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Mộc (075) Can (051)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Mộc (số 075 - cây gỗ/chỉ ý) ở bên trái chữ Can (số 051 - can thiệp/chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Can chỉ âm, bộ Mộc chỉ ý. Can là cái gậy, cái sào làm bằng gỗ tròn nhỏ.", "Nghĩa Tiếng Việt_Xie": "cái gậy gỗ, cái côn, cái mộc; chấn song cửa sổ", "Hạng Tần Suất (Jun Da)": "2008.0", "Tần Suất % (Jun Da)": "97.1673332385", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 干", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木干", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "干", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "杆", "Unihan_Traditional (Chữ Phồn thể)": "杆", "Pinyin_Xie": "gān", "Âm Hán Việt_Xie": "can", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Lượng từ | 量词 | Thường làm danh từ chỉ vật dạng thân dài hoặc làm lượng từ cho các vật có cán như súng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Lượng từ | 量词 | Đứng giữa số từ (hoặc 这/那) và danh từ: 一杯茶, 这本书. Mỗi danh từ đi với lượng từ riêng; 个 là lượng từ dùng chung phổ biến nhất.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | gǎn | / | thanh | Xuất hiện trong lộ trình | New HSK | New HSK 6 | · | Từ chức năng II", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('挨', '{"9000": "2009.0", "Chữ Trung Quốc": "挨", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 10 | nét | 扌 | thủ | biểu nghĩa | tay, hành động của tay | 矣 | hĩ | biểu âm | âm gốc āi | 挨 = 扌(Thủ, biểu nghĩa: tay) + 矣 (Hĩ, biểu âm); chữ hình thanh. Nghĩa gốc là đánh từ phía sau; mở rộng thành sát cạnh, chịu đựng, lần lượt.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ai\": tay (扌) nhẹ nhàng đụng vào (矣) — sát bên nhau, hay phải chịu đựng từng bước. | Gương Hán-Việt | ai trong thành ngữ \"挨家挨户\" (từng nhà từng hộ) — âm ai gần tiếng Hán-Việt | Mở khoá kiến thức | Biết 挨 (ai) mở khoá: 挨打 (bị đánh), 挨着 (kề cạnh), 挨饿 (chịu đói), 挨家挨户 (từng nhà).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 挨 là chữ hình thanh gồm 手 (biểu nghĩa: tay, viết tắt thành 扌) và 矣 (biểu âm, cho âm āi). Có hai âm đọc chính: āi (gần bên, lần lượt) và ái (chịu đựng, kéo dài). Nghĩa gốc là đánh vào lưng; mở rộng thành tiếp cận, kề cận, và chịu đựng khó khăn. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sát, liền, kề; lần lượt, từng cái một; chạm vào, sờ vào; bị, chịu", "Hạng Tần Suất (Jun Da)": "2009.0", "Tần Suất % (Jun Da)": "97.1709145595", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 矣", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌矣", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "矣", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "挨", "Unihan_Traditional (Chữ Phồn thể)": "挨", "Pinyin_Xie": "āi", "Âm Hán Việt_Xie": "ai", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Giới từ | 介词 | Thường làm động từ chỉ hành động chịu đựng hoặc giới từ chỉ sự kề cận, lần lượt. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Giới từ | 介词 | Ghép với danh từ hoặc đại từ thành cụm chỉ nơi chốn, thời gian, đối tượng: 在家, 跟他. Cụm giới từ đứng TRƯỚC động từ — 我在家吃饭 — ngược với trật tự tiếng Việt.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | āi | / | gần | / | ái | / | chịu đựng | Xuất hiện trong lộ trình | HSK | HSK 6 | · | Địa điểm | New HSK | New HSK 6 | · | Tội ác va hình phạt", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('僧', '{"9000": "2010.0", "Chữ Trung Quốc": "僧", "Bộ thủ & thành phần_Xie": "Bộ thủ | 人 | Số nét | 14 | nét | 亻 | nhân | biểu nghĩa | người | 曾 | tằng | biểu âm | tằng (cho âm sēng) | 僧 = 亻(Nhân, biểu nghĩa: người) + 曾 (Tằng, biểu âm); chữ hình thanh. Bộ nhân chỉ đây là một loại người, tằng cho âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tăng\": người (亻) đã từng (曾) xuất gia — nhà sư tăng ni, đã từng rũ bỏ bụi trần. | Gương Hán-Việt | tăng ni (僧尼 – nhà sư nam nữ), tăng già | Mở khoá kiến thức | Biết 僧 mở khoá: 僧人 (tăng nhân – nhà sư), 僧尼 (tăng ni), 老僧 (lão tăng), 高僧 (cao tăng).", "Tự nguyên_Xie": "Đại triện | Tiểu triện | Wiktionary ghi 僧 là hình thanh: 人 (người, biểu nghĩa) + 曾 (biểu âm) — một loại người (tu sĩ Phật giáo). Đây là từ phiên âm từ tiếng Phạn ''saṃgha'' (tăng già, cộng đồng tu sĩ). Hán-Việt đọc là Tăng. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nam sư", "Hạng Tần Suất (Jun Da)": "2010.0", "Tần Suất % (Jun Da)": "97.1744907126", "GavinGrover_Once (Chiết tự trực tiếp)": "亻 + 曾", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰亻曾", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "曾", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "亻", "Unihan_Simplified (Chữ Giản thể)": "僧", "Unihan_Traditional (Chữ Phồn thể)": "僧", "Pinyin_Xie": "sēng", "Âm Hán Việt_Xie": "tăng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng độc lập hoặc kết hợp để chỉ người tu hành theo đạo Phật. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蜜', '{"9000": "2011.0", "Chữ Trung Quốc": "蜜", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 14 | nét | 宓 | mật | biểu âm | yên tĩnh (gần âm mì) | 虫 | trùng | biểu nghĩa | côn trùng | 蜜 = 宓 (Mật, biểu âm) + 虫 (Trùng, biểu nghĩa: côn trùng); chữ hình thanh. Mật do côn trùng (ong) tạo ra, gốc nghĩa ''mật ong''. Dạng cổ là 𧖅.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mật\": 宓 (Mật) + 虫 (côn trùng) — côn trùng tạo ra mật, đúng nghĩa ''mật ong, ngọt ngào'' trong 蜜蜂 (ong mật), 蜂蜜 (mật ong), 甜蜜 (ngọt ngào), 蜜月 (trăng mật). | Gương Hán-Việt | ''mật'' trong ''mật ong'', ''ngọt mật'', ''mật ngọt chết ruồi'' | Mở khoá kiến thức | Nắm 蜜 mở khoá loạt từ HSK 5-7: 蜜, 蜜蜂, 甜蜜, 蜂蜜, 蜜月.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Theo Wiktionary, 蜜 là hình thanh: 宓 (Mật, biểu âm) + 虫 (côn trùng, biểu nghĩa). Dạng nguyên gốc là 𧖅. Nghĩa ''mật ong'' giữ nguyên đến nay; mở rộng sang nghĩa trừu tượng ''ngọt ngào, ngọt như mật'' trong 甜蜜 (ngọt ngào), 蜜月 (tuần trăng mật). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1066.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Mật (1065) Trùng (142)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Mật (số 1065 - yên ổn/chỉ âm) ở trên bộ Trùng (số 142 - côn trùng). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Mật (宓) chỉ âm, bộ Trùng chỉ ý. Mật là mật ong (vị ngọt do loài ong/côn trùng làm ra). Mật cũng mang nghĩa là vị ngọt ngào.", "Nghĩa Tiếng Việt_Xie": "mật ong; ngọt", "Hạng Tần Suất (Jun Da)": "2011.0", "Tần Suất % (Jun Da)": "97.178066349", "GavinGrover_Once (Chiết tự trực tiếp)": "宀 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱宀", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "蜜", "Unihan_Traditional (Chữ Phồn thể)": "蜜", "Pinyin_Xie": "mì", "Âm Hán Việt_Xie": "mật", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Thường làm danh từ chỉ mật hoặc tính từ bổ nghĩa cho danh từ để tả vị ngọt, sự mật thiết. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | mì | / | mật ong, ngọt ngào | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Thức ăn tôi", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('吟', '{"9000": "2012.0", "Chữ Trung Quốc": "吟", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 7 | nét | 口 | khẩu | biểu nghĩa | miệng, lời nói | 今 | kim | biểu âm | âm gốc yín | 吟 = 口 (Khẩu, biểu nghĩa: miệng) + 今 (Kim, biểu âm); chữ hình thanh. Ý gốc là cất giọng ngâm vịnh, đọc thơ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ngâm\": miệng (口) cất tiếng hôm nay (今) — ngâm nga thơ ca bên hiên vắng. | Gương Hán-Việt | ngâm trong \"ngâm thơ\", \"ngâm vịnh\", \"rên ngâm\" — đều chỉ âm thanh kéo dài trầm bổng | Mở khoá kiến thức | Biết 吟 (ngâm) mở khoá: 呻吟 (rên rỉ), 吟诗 (ngâm thơ), 沉吟 (trầm ngâm), 吟唱 (ngâm hát).", "Tự nguyên_Xie": "Đại triện | Theo Wiktionary, 吟 là chữ hình thanh gồm 口 (biểu nghĩa: miệng) và 今 (biểu âm, cho âm yín). Nghĩa gốc là ngâm thơ, đọc to một cách nhịp điệu; mở rộng thành rên rỉ, thể loại thơ trữ tình, và tiếng kêu của động vật. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ngâm thơ", "Hạng Tần Suất (Jun Da)": "2012.0", "Tần Suất % (Jun Da)": "97.181640435", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 今", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口今", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "今", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "吟", "Unihan_Traditional (Chữ Phồn thể)": "吟", "Pinyin_Xie": "yín", "Âm Hán Việt_Xie": "ngâm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường làm động từ chỉ hành động ngâm thơ hoặc phát ra âm thanh trầm bổng. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('猩', '{"9000": "2013.0", "Chữ Trung Quốc": "猩", "Bộ thủ & thành phần_Xie": "Bộ thủ | 犬 | Số nét | 12 | nét | 犭 | khuyển | biểu nghĩa | thú vật | 星 | tinh | biểu âm/nghĩa | tinh (cho âm xīng) | 猩 = 犭(Khuyển, biểu nghĩa: thú vật) + 星 (Tinh, biểu âm). Wiktionary không cung cấp phân tích hình thanh rõ ràng. Bộ khuyển chỉ đây là loài thú, tinh cho âm. Chữ tạo muộn để ghi tên loài đười ươi.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tinh\": thú (犭) sáng như sao (星) — tinh tinh, đười ươi thông minh sáng dạ như sao trên trời. | Gương Hán-Việt | tinh tinh (猩猩 – đười ươi), tinh huyết (máu đỏ tươi) | Mở khoá kiến thức | Biết 猩 mở khoá: 猩猩 (tinh tinh – đười ươi/tinh tinh), 猩红 (tinh hồng – đỏ tươi như máu).", "Tự nguyên_Xie": "Tiểu triện | Wiktionary không cung cấp phân tích nguồn gốc chi tiết cho 猩. Cấu trúc gồm 犭 (thú) + 星 (tinh/sao, biểu âm). Chữ chủ yếu dùng trong 猩猩 (đười ươi, tinh tinh), loài linh trưởng lớn. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn cổ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con tinh tinh, con đười ươi", "Hạng Tần Suất (Jun Da)": "2013.0", "Tần Suất % (Jun Da)": "97.1852109035", "GavinGrover_Once (Chiết tự trực tiếp)": "犭 + 星", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰犭星", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "星", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "犭", "Unihan_Simplified (Chữ Giản thể)": "猩", "Unihan_Traditional (Chữ Phồn thể)": "猩", "Pinyin_Xie": "xīng", "Âm Hán Việt_Xie": "tinh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ hoặc kết hợp thành từ ghép để chỉ các loài linh trưởng lớn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('遂', '{"9000": "2014.0", "Chữ Trung Quốc": "遂", "Bộ thủ & thành phần_Xie": "Bộ thủ | 辵 | Số nét | 12 | nét | 辶 | sước | biểu nghĩa | đi, di chuyển | 㒸 | toại | biểu âm | toại (cho âm suì) | 遂 = 辶(Sước, biểu nghĩa: đi) + 㒸 (Toại, biểu âm); chữ hình thanh. Bộ sước chỉ sự tiến hành, toại cho âm. Bộ phận âm 㒸 vốn chứa hình lợn nhưng đó chỉ là thành phần biểu âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"toại\": đi (辶) đến đích (㒸) — toại nguyện, toại chí, đi đến nơi và hoàn thành tâm nguyện. | Gương Hán-Việt | toại nguyện (遂愿 – như nguyện), toại tâm (遂心 – theo ý muốn) | Mở khoá kiến thức | Biết 遂 mở khoá: 遂心 (toại tâm – như ý), 遂愿 (toại nguyện), 功遂身退 (công thành thân thoái).", "Tự nguyên_Xie": "Wiktionary ghi 遂 là hình thanh: 辵 (đi, biểu nghĩa) + 㒸 (biểu âm). Phần âm 㒸 vốn không liên quan đến lợn — lợn chỉ là thành phần biểu âm. Nghĩa gốc là hoàn thành, thực hiện xong; sau thêm nghĩa thuận theo, theo đó. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1187.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Xước (162) Bát (012) Thỉ (373)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Xước (số 162 - bước đi) bao lấy bộ Bát (số 012 - tám/viết ngược 丷) và chữ Thỉ (số 373 - con lợn). Con lợn được thả rông chạy tung tăng khắp 8 hướng thật thỏa thích. Giải thích sự chuyển ý: Đây là chữ Hội ý (hoặc Hình thanh). Toại là thỏa thích, vừa lòng, thuận theo (toại nguyện, mãn toại).", "Nghĩa Tiếng Việt_Xie": "bèn (trợ từ)", "Hạng Tần Suất (Jun Da)": "2014.0", "Tần Suất % (Jun Da)": "97.188778788", "GavinGrover_Once (Chiết tự trực tiếp)": "辶 + 㒸", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴辶㒸", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "㒸", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "辶", "Unihan_Simplified (Chữ Giản thể)": "遂", "Unihan_Traditional (Chữ Phồn thể)": "遂", "Pinyin_Xie": "suì", "Âm Hán Việt_Xie": "toại", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Phó từ | 副词 | Thường làm động từ trong các từ ghép như toại nguyện hoặc làm phó từ liên kết trong văn ngôn. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Phó từ | 副词 | Bổ nghĩa cho động từ hoặc tính từ và luôn đứng TRƯỚC chúng — 都是, 很好. Không đứng sau như tiếng Việt và không bổ nghĩa cho danh từ.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('狭', '{"9000": "2015.0", "Chữ Trung Quốc": "狭", "Bộ thủ & thành phần_Xie": "Bộ thủ | 犬 | Số nét | 9 | nét | 犭 | khuyển | biểu nghĩa | chó — chỉ không gian chật hẹp như hang chó | 夹 | giáp | biểu âm | âm gốc xiá | 狭 = 犭(Khuyển, biểu nghĩa: chó — gợi ý kẽ hở chật) + 夹 (Giáp, biểu âm); chữ hình thanh. Ý gốc là khoảng không gian hẹp, chật như hang chó.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hẹp\": chó (犭) bị kẹp (夹) trong lối đi chật hẹp — hep (âm Hán-Việt thể hiện nghĩa luôn). | Gương Hán-Việt | hẹp trong \"chật hẹp\", \"hẹp hòi\" — âm Hán-Việt thực ra mô tả chính nghĩa | Mở khoá kiến thức | Biết 狭 (hẹp) mở khoá: 狭窄 (hẹp), 狭隘 (chật hẹp, hẹp hòi), 狭小 (chật nhỏ), 峡谷 (thung lũng hẹp).", "Tự nguyên_Xie": "Theo Wiktionary, 狹 (phồn thể) là chữ hình thanh gồm 犬 (biểu nghĩa: chó, viết tắt thành 犭) và 夾 (biểu âm, cho âm xiá). Hình ảnh không gian chật hẹp gắn với bộ khuyển. Nghĩa gốc và hiện tại đều là hẹp, chật hẹp; mở rộng thành hẹp hòi về tư tưởng. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "hẹp, bé", "Hạng Tần Suất (Jun Da)": "2015.0", "Tần Suất % (Jun Da)": "97.1923451223", "GavinGrover_Once (Chiết tự trực tiếp)": "犭 + 夹", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰犭夹", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "夹", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "犭", "Unihan_Simplified (Chữ Giản thể)": "狭", "Unihan_Traditional (Chữ Phồn thể)": "狹", "Pinyin_Xie": "xiá", "Âm Hán Việt_Xie": "hiệp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường làm tính từ đứng trước danh từ hoặc làm vị ngữ để miêu tả không gian, phạm vi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('肖', '{"9000": "2016.0", "Chữ Trung Quốc": "肖", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 7 | nét | ⺌ | biểu âm | biến thể của 小 (tiểu), cho âm xiào | 月 | nguyệt | biểu nghĩa | thịt/cơ thể (bộ nhục 肉 viết tắt) | 肖 = 小 (Tiểu, biểu âm — viết thành ⺌) + 月 (biểu nghĩa: thịt/cơ thể, bộ nhục); chữ hình thanh. Wiktionary ghi rõ Thuyết văn đã phân tích sai thành 小+肉. Chữ có thể là dạng gốc của 宵 (đêm).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tiêu\": nhỏ (⺌) và thịt (月) — bản sao thu nhỏ của cơ thể, trông y hệt như tiêu bản. | Gương Hán-Việt | tiêu trong \"tiêu tượng\" (chân dung, hình tượng thu nhỏ) | Mở khoá kiến thức | Biết 肖 (tiêu) mở khoá: 肖像 (chân dung), 不肖 (bất tiêu, không xứng), 惟妙惟肖 (sinh động như thật).", "Tự nguyên_Xie": "Đại triện | Theo Wiktionary, 肖 là chữ hình thanh gồm 小 (biểu âm, cho âm xiào) và 月/肉 (biểu nghĩa: thịt/cơ thể). Thuyết văn giải thích như 小+肉 nhưng đây là phân tích sai. Nghĩa gốc có thể là bản sao thu nhỏ (小) của cơ thể (肉), gợi ý trông giống, làm hình. Chữ có thể là dạng gốc của 宵 (đêm tối). | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "922.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Tiểu (060) Nhục (250)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Tiểu (số 060 - nhỏ/chỉ âm) ở trên bộ Nhục (số 250 - thịt/viết giống chữ Nguyệt 月). Xương thịt là giống nhau, nếu có sai khác thì rất nhỏ. Giải thích sự chuyển ý: Đây là chữ Hình thanh (hoặc Hội ý). Chữ Tiểu chỉ âm, bộ Nhục chỉ ý. Tiếu là giống nhau, tương tự, bắt chước (bất tiếu).", "Nghĩa Tiếng Việt_Xie": "giống nhau; giống; con giáp", "Hạng Tần Suất (Jun Da)": "2016.0", "Tần Suất % (Jun Da)": "97.1959104229", "GavinGrover_Once (Chiết tự trực tiếp)": "⺌ + 月", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺌月", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "月", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺌", "Unihan_Simplified (Chữ Giản thể)": "肖", "Unihan_Traditional (Chữ Phồn thể)": "肖", "Pinyin_Xie": "xiào", "Âm Hán Việt_Xie": "tiếu, tiêu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường làm động từ biểu thị sự tương đồng hoặc làm danh từ trong tổ hợp chỉ con giáp. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('甜', '{"9000": "2017.0", "Chữ Trung Quốc": "甜", "Bộ thủ & thành phần_Xie": "Bộ thủ | 甘 | Số nét | 11 | nét | 舌 | thiệt | biểu nghĩa | cái lưỡi – cảm nhận vị giác | 甘 | cam | biểu nghĩa | vị ngọt | 甜 = 舌 (Thiệt, lưỡi) + 甘 (Cam, ngọt); chữ hội ý: lưỡi nếm thấy vị ngọt; là dạng sắp xếp lại của chữ 甛. Nghĩa là ngọt, ngon ngọt.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"điềm\": lưỡi 舌 chạm vào vị ngọt 甘 – cảm nhận được vị; nên 甜 nghĩa là ngọt, ngon ngọt, êm dịu. | Gương Hán-Việt | \"điềm\" trong điềm đạm, điềm tĩnh; cùng họ với 甘 (cam – ngọt) trong cam thảo, cam tâm. | Mở khoá kiến thức | Nhớ 甜 mở khoá: 甜, 甜美, 甜蜜, 甜头, 酸甜, 酸甜苦辣.", "Tự nguyên_Xie": "甜 là chữ hội ý (ic) ghép 舌 \"lưỡi\" + 甘 \"vị ngọt\": hình ảnh đầu lưỡi nếm vị ngọt – đó chính là \"ngọt\". Chữ này là dạng sắp xếp lại (đảo vị trí hai bộ phận) của chữ 甛. Từ nghĩa gốc \"ngọt\", chữ mở rộng sang các nghĩa biểu cảm như \"ngọt ngào, êm dịu\" (giọng nói, giấc ngủ). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1521.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thiệt (118) Cam (406)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Thiệt (số 118 - cái lưỡi/ 舌) ở bên trái bộ Cam (số 406 - ngọt/ 甘). Lưỡi nếm và cảm nhận được vị ngọt. Giải thích sự chuyển ý: Đây là chữ Hội ý. Điềm là có vị ngọt, dịu ngọt, dễ chịu (điềm mật).", "Nghĩa Tiếng Việt_Xie": "rất ngọt", "Hạng Tần Suất (Jun Da)": "2017.0", "Tần Suất % (Jun Da)": "97.1994731396", "GavinGrover_Once (Chiết tự trực tiếp)": "舌 + 甘", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰舌甘", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "甘", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "舌", "Unihan_Simplified (Chữ Giản thể)": "甜", "Unihan_Traditional (Chữ Phồn thể)": "甜", "Pinyin_Xie": "tián", "Âm Hán Việt_Xie": "điềm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường làm tính từ bổ nghĩa cho danh từ chỉ món ăn hoặc làm vị ngữ trong câu. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | tián | / | ngọt | Xuất hiện trong lộ trình | New HSK | New HSK 3 | · | Thức ăn và đồ uống | YCT | YCT 4 | · | Đồ ăn và đồ uống | HSK | HSK 3 | · | Thức ăn và đồ uống", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('霞', '{"9000": "2018.0", "Chữ Trung Quốc": "霞", "Bộ thủ & thành phần_Xie": "Bộ thủ | 雨 | Số nét | 17 | nét | 雨 | vũ | biểu nghĩa | mưa — bộ khí tượng trên bầu trời | 叚 | giả | biểu âm | âm gốc xiá | 霞 = 雨 (Vũ, biểu nghĩa: mưa — bộ chỉ hiện tượng khí quyển) + 叚 (Giả, biểu âm); chữ hình thanh. Ý gốc là ráng đỏ trên bầu trời, ánh sáng hồng của mặt trời chiếu qua mây.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hà\": bầu trời (雨) giả trang (叚) thành màu hồng — đó là ráng hà lúc hoàng hôn. | Gương Hán-Việt | hà trong \"triêu hà\" (ráng buổi sớm), \"vân hà\" (mây ráng) — dùng nhiều trong thơ văn cổ | Mở khoá kiến thức | Biết 霞 (hà) mở khoá: 霞光 (ánh ráng đỏ), 朝霞 (ráng buổi sáng), 彩霞 (mây hồng), 晚霞 (ráng chiều).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 霞 là chữ hình thanh gồm 雨 (biểu nghĩa: mưa/khí tượng) và 叚 (biểu âm, cho âm xiá). Nghĩa gốc là ráng đỏ buổi sớm hoặc chiều tà — ánh sáng mặt trời nhuốm màu hồng trên mây. Hình ảnh thơ mộng thường gặp trong thơ cổ Trung Hoa. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ráng mặt trời hoặc ráng mây mù", "Hạng Tần Suất (Jun Da)": "2018.0", "Tần Suất % (Jun Da)": "97.2030312053", "GavinGrover_Once (Chiết tự trực tiếp)": "雨 + 叚", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱雨叚", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "叚", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "雨", "Unihan_Simplified (Chữ Giản thể)": "霞", "Unihan_Traditional (Chữ Phồn thể)": "霞", "Pinyin_Xie": "xiá", "Âm Hán Việt_Xie": "hà", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng độc lập hoặc kết hợp tạo thành từ ghép chỉ hiện tượng tự nhiên. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | xiá | / | ráng mây | Xuất hiện trong lộ trình | HSK | HSK 6 | · | Thiên nhiên và khí hậu", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('驳', '{"9000": "2019.0", "Chữ Trung Quốc": "驳", "Bộ thủ & thành phần_Xie": "Bộ thủ | 馬 | Số nét | 7 | nét | 马 | mã | biểu nghĩa | ngựa | 爻 | hào | biểu nghĩa | hoa văn chéo — gợi màu loang lổ | 驳 là dạng giản thể của 駁. Chữ gốc 駁 gồm 馬 (biểu nghĩa: ngựa) và 爻 (hào, gợi hoa văn chéo — loang lổ); chữ hội ý hoặc hình thanh. Nghĩa gốc là ngựa có màu loang lổ; mở rộng thành phản bác, bác bỏ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bác\": ngựa (马) có hoa văn chéo (爻) loang lổ — như lý luận nhiều chiều, phản bác nhau. | Gương Hán-Việt | bác trong \"phản bác\" (bác bỏ), \"bác bỏ\" — bác là bác bỏ, không phải bác sĩ | Mở khoá kiến thức | Biết 驳 (bác) mở khoá: 反驳 (phản bác), 驳回 (bác bỏ), 驳斥 (bác bỏ mạnh), 批驳 (phê phán phản bác).", "Tự nguyên_Xie": "Đại triện | Tiểu triện | 驳 là dạng giản thể của 駁. Wiktionary chú rõ xem 駁. Chữ gốc 駁 gồm 馬 (ngựa) và 爻 (hào văn chéo, gợi lốm đốm). Nghĩa gốc là ngựa nhiều màu loang lổ; mở rộng thành lẫn lộn, hỗn tạp; sau dùng cho phản bác (vì phản bác là \"đánh lại\" luận điểm trái chiều). chưa có nguồn học thuật rõ về chuyển nghĩa này. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "loang lổ; lẫn lộn; phản bác, chống lại", "Hạng Tần Suất (Jun Da)": "2019.0", "Tần Suất % (Jun Da)": "97.2065861702", "GavinGrover_Once (Chiết tự trực tiếp)": "马 + 爻", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰马爻", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "爻", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "马", "Unihan_Simplified (Chữ Giản thể)": "驳", "Unihan_Traditional (Chữ Phồn thể)": "駁", "Pinyin_Xie": "bó", "Âm Hán Việt_Xie": "bác", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Thường làm động từ đứng trước tân ngữ để biểu thị sự phản đối hoặc làm tính từ miêu tả màu sắc. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('裕', '{"9000": "2020.0", "Chữ Trung Quốc": "裕", "Bộ thủ & thành phần_Xie": "Bộ thủ | 衣 | Số nét | 12 | nét | 衤 | y | biểu nghĩa | quần áo — gợi ý giàu có dư dả | 谷 | cốc | biểu âm | âm gốc yù | 裕 = 衤(Y, biểu nghĩa: quần áo) + 谷 (Cốc, biểu âm); chữ hình thanh. Dân gian giải thích 谷 là khoảng trống trong áo — áo rộng thùng thình là dấu hiệu của sự giàu có.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"dụ\": áo (衤) rộng như thung lũng (谷) — dư dả, sung túc, áo rộng là biểu tượng phú dụ. | Gương Hán-Việt | dụ trong \"phú dụ\" (giàu có), \"dụ túc\" (sung túc đủ đầy) | Mở khoá kiến thức | Biết 裕 (dụ) mở khoá: 富裕 (giàu có), 宽裕 (rộng rãi, dư dả), 余裕 (dư giả).", "Tự nguyên_Xie": "Đại triện | Tiểu triện | Theo Wiktionary, 裕 là chữ hình thanh gồm 谷 (biểu âm, cho âm yù) và 衣 (biểu nghĩa: quần áo, viết tắt thành 衤). Dân gian giải nghĩa 谷 là khoảng trống rộng rãi trong quần áo, gợi ý sự dư dả. Nghĩa gốc và hiện tại là giàu có, dồi dào, sung túc. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nhiều đồ đạc, giàu có; thong thả", "Hạng Tần Suất (Jun Da)": "2020.0", "Tần Suất % (Jun Da)": "97.2101370009", "GavinGrover_Once (Chiết tự trực tiếp)": "衤 + 谷", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰衤谷", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "谷", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "衤", "Unihan_Simplified (Chữ Giản thể)": "裕", "Unihan_Traditional (Chữ Phồn thể)": "裕", "Pinyin_Xie": "yù", "Âm Hán Việt_Xie": "dụ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường làm tính từ trong các từ ghép chỉ sự sung túc hoặc làm vị ngữ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('顽', '{"9000": "2021.0", "Chữ Trung Quốc": "顽", "Bộ thủ & thành phần_Xie": "Bộ thủ | 頁 | Số nét | 10 | nét | 元 | nguyên | biểu âm | âm gốc wán; nguyên gốc nghĩa là đầu người | 页 | hiệt | biểu nghĩa | đầu người | 顽 = 元 (Nguyên, biểu âm; vốn nghĩa là \"đầu\") + 页 (Hiệt, biểu nghĩa: đầu người); chữ hình thanh. Wiktionary giải thích: khi 元 chuyển nghĩa thành \"nguyên gốc\", người ta thêm 页 để giữ nguyên nghĩa \"cái đầu cứng đầu\" — đầu người ngoan cố không chịu cúi.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ngoan\": cái đầu (页) cứng như gốc (元) — ngoan cố không chịu thay đổi, hay nghịch ngợm. | Gương Hán-Việt | ngoan trong \"ngoan cố\" (bướng bỉnh) — chú ý ngoan (顽) trong tiếng Hán có nghĩa tiêu cực, khác ngoan ngoãn của tiếng Việt | Mở khoá kiến thức | Biết 顽 (ngoan) mở khoá: 顽固 (ngoan cố, bướng bỉnh), 顽强 (kiên cường bền bỉ), 顽皮 (nghịch ngợm), 顽疾 (bệnh nan y).", "Tự nguyên_Xie": "Đại triện | Tiểu triện | Theo Wiktionary, 頑 là chữ hình thanh gồm 元 (biểu âm, vốn nghĩa là \"đầu\") và 頁 (biểu nghĩa: đầu người). Khi 元 chuyển sang nghĩa \"nguyên gốc\", 頁 được thêm vào để xác nhận nghĩa \"cái đầu\" — nhưng với nghĩa đã thay đổi thành \"cái đầu ngoan cố\". Nghĩa mở rộng: bướng bỉnh, ngu muội, nghịch ngợm. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "dốt nát, ngu xuẩn; ngoan cố, bảo thủ", "Hạng Tần Suất (Jun Da)": "2021.0", "Tần Suất % (Jun Da)": "97.2136862812", "GavinGrover_Once (Chiết tự trực tiếp)": "元 + 页", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰元页", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "元", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "页", "Unihan_Simplified (Chữ Giản thể)": "顽", "Unihan_Traditional (Chữ Phồn thể)": "頑", "Pinyin_Xie": "wán", "Âm Hán Việt_Xie": "ngoan", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường làm tính từ đứng trước danh từ để chỉ tính cách hoặc làm vị ngữ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('摘', '{"9000": "2022.0", "Chữ Trung Quốc": "摘", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 14 | nét | 扌 | thủ | biểu nghĩa | tay, hành động bằng tay | 啇 | biểu âm | (cấu tử phức hợp) cho âm zhāi | 摘 = 扌(Thủ, biểu nghĩa: tay) + 啇 (biểu âm: cho âm zhāi). Chữ hình thanh — bộ thủ chỉ hành động bằng tay (hái, ngắt, chọn), 啇 cho âm. Nghĩa: hái, ngắt (hoa quả), trích dẫn, tóm tắt.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trích\": 摘 = 扌(tay) + âm trích — trích (hái) từng quả bằng tay, cũng trích dẫn từng câu từ văn bản. | Gương Hán-Việt | trích trong 摘要 (trích yếu — tóm tắt), 摘錄 (trích lục — trích dẫn). | Mở khoá kiến thức | Biết 摘 mở khoá: 摘要 (tóm tắt), 摘录 (trích dẫn), 摘花 (hái hoa), 摘除 (cắt bỏ/phẫu thuật cắt).", "Tự nguyên_Xie": "Wiktionary xác nhận: 摘 là hình thanh, 手 (tay, biểu nghĩa, viết dưới dạng 扌) + 啇 (biểu âm). Nghĩa gốc: hái — dùng tay ngắt hoa, trái cây, lá cây khỏi cành. Mở rộng: (1) tháo ra — 摘下帽子 (tháo mũ ra); (2) trích dẫn, tóm lược — 摘要 (tóm tắt), 摘录 (trích dẫn). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1074.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thủ (064) Đích (1073)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Thủ (số 064 - bàn tay/ 扌) ở bên trái chữ Đích (số 1073 - cái gốc/chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Đích chỉ âm, bộ Thủ chỉ ý. Trích là dùng tay để hái, ngắt, hoặc chọn lọc lấy phần cốt lõi (trích lục, hái hoa).", "Nghĩa Tiếng Việt_Xie": "trích ra; ngắt, hái, vặt", "Hạng Tần Suất (Jun Da)": "2022.0", "Tần Suất % (Jun Da)": "97.2207677879", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 啇", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌啇", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "啇", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "摘", "Unihan_Traditional (Chữ Phồn thể)": "摘", "Pinyin_Xie": "zhāi", "Âm Hán Việt_Xie": "trích", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước danh từ chỉ hoa quả hoặc đoạn văn để làm tân ngữ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | Từ đơn | Từ vựng HSK 5: nhặt | / | zhāi | / | nhặt | Xuất hiện trong lộ trình | HSK | HSK 5 | · | Động từ hàng ngày | New HSK | New HSK 5 | · | Động từ", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('矮', '{"9000": "2023.0", "Chữ Trung Quốc": "矮", "Bộ thủ & thành phần_Xie": "Bộ thủ | 矢 | Số nét | 13 | nét | 矢 | thỉ | biểu nghĩa | mũi tên — vật ngắn để đo | 委 | uỷ | biểu âm | mượn âm | 矮 = 矢 (Thỉ, mũi tên, biểu nghĩa: vật ngắn dùng làm chuẩn đo) + 委 (Uỷ, biểu âm); chữ hình thanh. Bộ 矢 (mũi tên) cũng có trong 短 (đoản - ngắn), gắn với khái niệm ''ngắn/thấp''.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ải\" = thấp, lùn. Nhớ: bên trái là 矢 (mũi tên — vật ngắn dùng làm chuẩn đo); ai 矢 ngắn thì người ''ải'' (thấp). | Gương Hán-Việt | Hán-Việt ''ải'' của 矮 ít dùng trong tiếng Việt; nghĩa ''thấp, lùn'' là cách dịch tiếng Việt thường dùng. | Mở khoá kiến thức | Biết 矮 mở khoá 矮小 (ải tiểu - lùn và nhỏ), 高矮 (cao ải - cao thấp), 矮个子 (ải cá tử - người lùn).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Theo Wiktionary, 矮 là chữ hình thanh ghép 矢 (mũi tên, biểu nghĩa) với 委 (biểu âm). Bộ 矢 (mũi tên) trong tiếng Hán cổ thường dùng làm chuẩn đo độ dài; vì thế nó được dùng làm thành phần biểu nghĩa cho các chữ chỉ kích thước nhỏ/ngắn như 短 (đoản), 矮 (ải). Nghĩa ''thấp, lùn'' bắt nguồn từ đó. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lùn, thấp; thụp xuống", "Hạng Tần Suất (Jun Da)": "2023.0", "Tần Suất % (Jun Da)": "97.2242994975", "GavinGrover_Once (Chiết tự trực tiếp)": "矢 + 委", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰矢委", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "委", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "矢", "Unihan_Simplified (Chữ Giản thể)": "矮", "Unihan_Traditional (Chữ Phồn thể)": "矮", "Pinyin_Xie": "ǎi", "Âm Hán Việt_Xie": "ải, nụy", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường làm tính từ miêu tả chiều cao của người hoặc vật, đứng trước danh từ hoặc làm vị ngữ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | ǎi | / | thấp | Xuất hiện trong lộ trình | HSK | HSK 3 | · | Cơ thể và sức khỏe | YCT | YCT 4 | · | Tính từ | New HSK | New HSK 4 | · | Quần áo và ngoại hình", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('秒', '{"9000": "2024.0", "Chữ Trung Quốc": "秒", "Bộ thủ & thành phần_Xie": "Bộ thủ | 禾 | Số nét | 9 | nét | 禾 | hoà | biểu nghĩa | cây lúa — tua nhỏ | 少 | thiểu | biểu âm | gợi âm miǎo | 秒 = 禾 (Hoà: lúa) + 少 (Thiểu, biểu âm); chữ hình thanh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"miểu\": cây lúa 禾 chỉ một chút 少 — đơn vị nhỏ xíu, đó là ''miểu'' (giây). | Gương Hán-Việt | miểu trong \"miểu tả\" 秒殺 (Hán-Việt cổ); người Việt thường dùng \"giây\" | Mở khoá kiến thức | Biết 秒 mở khoá đơn vị thời gian và tốc độ: 秒, 一秒, 争分夺秒.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary chú 秒 = 禾 + 少 (ls=psc, c1=s c2=p, t1=''cereal; grain'') — 禾 cho nghĩa ''tua lúa nhỏ'', 少 cho âm miǎo. Nghĩa gốc ''tua nhỏ trên hạt lúa'', sau dùng làm đơn vị thời gian rất ngắn (giây). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tua lúa; giây (bằng 1/60 phút)", "Hạng Tần Suất (Jun Da)": "2024.0", "Tần Suất % (Jun Da)": "97.2278286232", "GavinGrover_Once (Chiết tự trực tiếp)": "禾 + 少", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰禾少", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "少", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "禾", "Unihan_Simplified (Chữ Giản thể)": "秒", "Unihan_Traditional (Chữ Phồn thể)": "秒", "Pinyin_Xie": "miǎo", "Âm Hán Việt_Xie": "miểu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Lượng từ | 量词 | Danh từ | 名词 | Thường làm lượng từ chỉ thời gian đứng sau số từ để biểu thị số giây. | Lượng từ | 量词 | Đứng giữa số từ (hoặc 这/那) và danh từ: 一杯茶, 这本书. Mỗi danh từ đi với lượng từ riêng; 个 là lượng từ dùng chung phổ biến nhất. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | Từ đơn | Từ vựng HSK 5: giây | / | miǎo | / | giây | Xuất hiện trong lộ trình | HSK | HSK 5 | · | Thời gian | New HSK | New HSK 5 | · | Thời gian", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('卿', '{"9000": "2025.0", "Chữ Trung Quốc": "卿", "Bộ thủ & thành phần_Xie": "Bộ thủ | 卩 | Số nét | 10 | nét | 𠂎 | ấy | biểu nghĩa | hai người đối diện (ăn chung) | 卩 | tiết | biểu nghĩa | người quỳ (tham dự lễ tiệc) | 卿 là hội ý: hai người (𠂍) đối diện quanh đồ đựng thức ăn (皀), biểu thị cảnh lễ tiệc nghi lễ. Wiktionary ghi ls=ic (hội ý) làm chính. Nghĩa gốc là người tham dự lễ tiệc nghi lễ, sau mở rộng thành tước vị khanh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khanh\": hai người (𠂎) quỳ đối diện (卩) trong lễ tiệc — khanh tướng, quan khanh phục vụ vua trong triều đình. | Gương Hán-Việt | khanh tướng (卿相 – quan khanh), khanh khanh (thân mật, như vua gọi thần) | Mở khoá kiến thức | Biết 卿 mở khoá: 卿相 (khanh tướng – quan lớn), 公卿 (công khanh – quan cao cấp), cách vua gọi thần hạ thân mật.", "Tự nguyên_Xie": "Giáp cốt văn | Kim văn | Tiểu triện | Wiktionary ghi 卿 là hội ý: 𠨍 (hai người đối diện, biểu nghĩa) + 皀 (đồ đựng thức ăn có chân, biểu nghĩa) — người tham dự lễ tiệc nghi lễ. Chữ từng không phân biệt với 鄉 (hương). Từ cảnh ăn uống nghi lễ, mở rộng chỉ tước vị khanh tướng. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "quan khanh; tiếng vua gọi bầy tôi", "Hạng Tần Suất (Jun Da)": "2025.0", "Tần Suất % (Jun Da)": "97.2313556817", "GavinGrover_Once (Chiết tự trực tiếp)": "卯 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴卯", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "卿", "Unihan_Traditional (Chữ Phồn thể)": "卿", "Pinyin_Xie": "qīng", "Âm Hán Việt_Xie": "khanh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Đại từ | 代词 | Chữ này thường dùng làm danh từ chỉ chức quan thời xưa hoặc đại từ xưng hô thân mật giữa vợ chồng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Đại từ | 代词 | Thay cho người hoặc vật đã nhắc tới (我, 这, 谁). Dùng đúng ở vị trí của danh từ. Chỉ người thì thêm 们 để thành số nhiều: 我们.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('畜', '{"9000": "2026.0", "Chữ Trung Quốc": "畜", "Bộ thủ & thành phần_Xie": "Bộ thủ | 田 | Số nét | 10 | nét | 玄 | huyền | biểu nghĩa | sợi dây — buộc bao thức ăn hoặc buộc gia súc | 田 | điền | biểu nghĩa | bao thức ăn hoặc chuồng trại | 畜 là chữ thuần hình ý (hoặc biểu ý phức): 玄 (dây buộc) + 田 (bao thức ăn/chuồng). Wiktionary cho hai cách đọc: dây (玄) buộc bao thức ăn (田) — chỉ gia súc được nuôi nhốt và cho ăn; hoặc dây buộc trong chuồng trại.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"súc\": dây (玄) buộc bao thức ăn (田) trong chuồng — nuôi súc vật, chăn gia súc. | Gương Hán-Việt | súc trong \"gia súc\" (động vật nuôi), \"súc vật\", \"chăn nuôi súc\" | Mở khoá kiến thức | Biết 畜 (súc) mở khoá: 牲畜 (gia súc), 畜牧 (chăn nuôi), 家畜 (vật nuôi trong nhà).", "Tự nguyên_Xie": "Kim văn | Bạch thư | Tiểu triện | Theo Wiktionary, 畜 là chữ hình ý gồm 玄 (sợi dây buộc túi thức ăn) và 田 (túi thức ăn, hoặc chuồng trại). Ý gốc là bao thức ăn cho gia súc, dẫn đến nghĩa gia súc, vật nuôi. Cách đọc thứ hai: dây buộc (玄) + chuồng (囿) = nuôi nhốt súc vật. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1353.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Huyền (165) Điền (097)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Huyền (số 165 - sâu xa mầu nhiệm/ 玄) ở trên chữ Điền (số 097 - thửa ruộng/ 田). Ruộng đất rất huyền diệu, nó tạo ra nguồn thức ăn để nuôi sống được mọi sinh vật. Giải thích sự chuyển ý: Đây là chữ Hội ý. Súc là chăn nuôi, nuôi dưỡng thú vật (súc mục). Cũng chỉ các loài thú được nuôi (gia súc, súc sinh).", "Nghĩa Tiếng Việt_Xie": "súc vật; nuôi nấng", "Hạng Tần Suất (Jun Da)": "2026.0", "Tần Suất % (Jun Da)": "97.2348806731", "GavinGrover_Once (Chiết tự trực tiếp)": "玄 + 田", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱玄田", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "田", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "玄", "Unihan_Simplified (Chữ Giản thể)": "畜", "Unihan_Traditional (Chữ Phồn thể)": "畜", "Pinyin_Xie": "chù", "Âm Hán Việt_Xie": "húc, súc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường dùng làm danh từ chỉ các loài gia súc hoặc động từ với nghĩa nuôi dưỡng, chăn nuôi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('咽', '{"9000": "2027.0", "Chữ Trung Quốc": "咽", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 9 | nét | 口 | khẩu | biểu nghĩa | miệng | 因 | nhân | biểu âm | âm gốc yān/yàn | 咽 = 口 (Khẩu, biểu nghĩa: miệng) + 因 (Nhân, biểu âm); chữ hình thanh. Wiktionary: phần nối với miệng — đó là cổ họng. Có ba âm đọc: yān (họng), yàn (nuốt), yè (nghẹn ngào).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"yết\": miệng (口) bị nhân (因) kẹt lại — yết hầu, cổ họng bị nghẹn. | Gương Hán-Việt | yết trong \"yết hầu\" (cổ họng), \"yết kiến\" — nhưng trong 咽 âm Hán-Việt \"yết\" phổ biến nhất | Mở khoá kiến thức | Biết 咽 (yết) mở khoá: 咽喉 (yết hầu, cổ họng), 吞咽 (nuốt), 呜咽 (khóc nức nở).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 咽 là chữ hình thanh gồm 口 (biểu nghĩa: miệng) và 因 (biểu âm, cho âm yān). Nghĩa gốc là cổ họng — phần nối với miệng. Ba âm đọc: yān (danh từ: họng, cổ họng), yàn (động từ: nuốt), yè (nghẹn ngào, khóc nức nở). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nghẹn cổ không nói được", "Hạng Tần Suất (Jun Da)": "2027.0", "Tần Suất % (Jun Da)": "97.2384041142", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 因", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口因", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "因", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "咽", "Unihan_Traditional (Chữ Phồn thể)": "咽", "Pinyin_Xie": "yàn", "Âm Hán Việt_Xie": "yết, yên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường làm động từ chỉ hành động nuốt thức ăn hoặc trạng thái nghẹn ngào không nói nên lời. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | yàn | / | nuốt | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Thực phẩm II", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('披', '{"9000": "2028.0", "Chữ Trung Quốc": "披", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 8 | nét | 扌 | thủ | biểu nghĩa | tay, hành động bằng tay | 皮 | bì | biểu âm | da, vỏ; cho âm pī | 披 = 扌(Thủ, biểu nghĩa: tay) + 皮 (Bì, biểu âm: cho âm pī). Chữ hình thanh — bộ thủ chỉ hành động tay choàng/phủ qua, 皮 cho âm. Nghĩa gốc: mặc hờ qua vai, choàng lên vai (như da thú khoác lên người cổ đại).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phi\": 披 = 扌(tay) + 皮(da) — phi (khoác) tấm da 皮 lên vai bằng tay 扌, như hiệp sĩ phi ngựa khoác áo choàng. | Gương Hán-Việt | phi trong 披露 (phi lộ — tiết lộ, công bố), 披肩 (phi kiên — khăn choàng vai). | Mở khoá kiến thức | Biết 披 mở khoá: 披露 (tiết lộ, công bố), 披肩 (khăn choàng vai), 披头散发 (tóc xõa rối).", "Tự nguyên_Xie": "Wiktionary xác nhận: 披 là hình thanh, 手 (tay, biểu nghĩa, viết dạng 扌) + 皮 (biểu âm). Hình ảnh liên tưởng: dùng tay khoác da thú lên vai — hành động của người cổ đại mặc da thú. Nghĩa gốc và hiện đại: choàng, khoác qua vai (披肩 — khăn choàng vai), phủ lên (披头散发 — tóc xõa). Mở rộng: công bố, tiết lộ (披露). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1194.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thủ (064) Bì (107)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Thủ (số 064 - cái tay/ 扌) ở bên trái chữ Bì (số 107 - da/chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Bì chỉ âm, bộ Thủ chỉ ý. Phi là dùng tay vạch ra, phơi bày. Cũng có nghĩa là khoác lên vai (phi phong - áo choàng).", "Nghĩa Tiếng Việt_Xie": "rẽ ra, vạch ra, mở ra; khoác áo", "Hạng Tần Suất (Jun Da)": "2028.0", "Tần Suất % (Jun Da)": "97.2419130852", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 皮", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌皮", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "皮", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "披", "Unihan_Traditional (Chữ Phồn thể)": "披", "Pinyin_Xie": "pī", "Âm Hán Việt_Xie": "phi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước danh từ chỉ trang phục hoặc đồ vật để diễn tả hành động khoác lên người hoặc mở ra. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | Từ đơn | Từ vựng HSK 5: choàng qua vai | / | pī | / | choàng qua vai | Xuất hiện trong lộ trình | HSK | HSK 5 | · | Quần áo và thời trang | New HSK | New HSK 5 | · | Vẻ bề ngoài", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('辅', '{"9000": "2029.0", "Chữ Trung Quốc": "辅", "Bộ thủ & thành phần_Xie": "Bộ thủ | 車 | Số nét | 11 | nét | 车 | xa | biểu nghĩa | xe (bộ xa giản thể) | 甫 | phủ | biểu âm | mới bắt đầu, người cha; cho âm fǔ | 辅 = 车 (Xa, biểu nghĩa: xe) + 甫 (Phủ, biểu âm: cho âm fǔ). Đây là giản thể của 輔. Cấu trúc hình thanh — bộ xa gợi ý thanh gỗ bên cạnh bánh xe (bộ phận phụ trợ bánh xe), 甫 cho âm. Nghĩa gốc: thanh gỗ phụ trợ bánh xe; mở rộng thành: hỗ trợ, phụ tá.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phụ\": 辅 = 车(xe) + 甫(âm phụ) — phụ (hỗ trợ) như thanh gỗ phụ bên bánh xe 车, không thể thiếu nhưng không phải bánh chính. | Gương Hán-Việt | phụ trong 輔導 (phụ đạo — hướng dẫn/dạy thêm), 輔助 (phụ trợ — hỗ trợ). | Mở khoá kiến thức | Biết 辅 mở khoá: 辅导 (hướng dẫn, dạy kèm), 辅助 (hỗ trợ), 相辅相成 (bổ sung cho nhau).", "Tự nguyên_Xie": "辅 là giản thể của 輔. Chữ truyền thống 輔 = 車 (xe, biểu nghĩa) + 甫 (biểu âm). Nghĩa gốc: thanh gỗ gia cố bên cạnh bánh xe — bộ phận phụ trợ nâng đỡ bánh xe khi xe nặng. Từ hình ảnh này phát triển nghĩa: hỗ trợ, phụ trợ, phụ đạo (辅导), vai phò tá (辅佐). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "xương má; giúp đỡ; giáp, gần kề", "Hạng Tần Suất (Jun Da)": "2029.0", "Tần Suất % (Jun Da)": "97.245417922", "GavinGrover_Once (Chiết tự trực tiếp)": "车 + 甫", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰车甫", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "甫", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "车", "Unihan_Simplified (Chữ Giản thể)": "辅", "Unihan_Traditional (Chữ Phồn thể)": "輔", "Pinyin_Xie": "fǔ", "Âm Hán Việt_Xie": "phụ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường làm động từ biểu thị sự giúp đỡ, bổ trợ hoặc kết hợp thành danh từ chỉ bộ phận nâng đỡ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('勾', '{"9000": "2030.0", "Chữ Trung Quốc": "勾", "Bộ thủ & thành phần_Xie": "Bộ thủ | 勹 | Số nét | 4 | nét | 勹 | bao | biểu nghĩa | bao quanh, uốn cong | 厶 | mỗ | biểu nghĩa | góc, phần bên trong bị bao | 勾 là dị thể của 句, thay thành phần 口 bằng 厶. Chữ gốc 句 gồm 勹 (bao quanh) và 口 (miệng). Wiktionary mô tả 勾 là biến thể phổ thông của 句 qua quá trình 口 → 厶. Nghĩa gốc là uốn cong, móc; dùng chủ yếu trong nghĩa móc câu, đánh dấu.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"câu\": hình dáng uốn cong (勹+厶) như cái câu móc — dùng để câu cá hay câu kết với ai đó. | Gương Hán-Việt | câu trong \"câu kết\" (thông đồng), \"câu móc\" (hook) | Mở khoá kiến thức | Biết 勾 (câu) mở khoá: 勾结 (câu kết, thông đồng), 勾画 (phác thảo), 勾引 (dụ dỗ).", "Tự nguyên_Xie": "Theo Wiktionary, 勾 là biến thể của 句. Quá trình biến đổi: 口 → 厶 tạo ra 勾. Nghĩa gốc của 句 là uốn cong; 勾 kế thừa nghĩa này và phát triển thêm: móc vào, câu kết, đánh dấu móc (✓), gợi dụ. chưa có nguồn học thuật rõ về lịch sử phân hóa. | Theo Wiktionary · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cong, móc; đánh dấu móc", "Hạng Tần Suất (Jun Da)": "2030.0", "Tần Suất % (Jun Da)": "97.2489217252", "GavinGrover_Once (Chiết tự trực tiếp)": "勹 + 厶", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴勹厶", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "厶", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "勹", "Unihan_Simplified (Chữ Giản thể)": "勾", "Unihan_Traditional (Chữ Phồn thể)": "勾", "Pinyin_Xie": "gōu", "Âm Hán Việt_Xie": "câu, cấu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường làm động từ chỉ hành động móc nối, dụ dỗ hoặc đánh dấu móc để lựa chọn. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | gōu | / | đánh dấu | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Words II", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('盆', '{"9000": "2031.0", "Chữ Trung Quốc": "盆", "Bộ thủ & thành phần_Xie": "Bộ thủ | 皿 | Số nét | 9 | nét | 分 | phân | biểu âm | chia (gần âm pén) | 皿 | mãnh | biểu nghĩa | đồ đựng | 盆 = 分 (Phân, biểu âm) + 皿 (Mãnh, biểu nghĩa: đồ đựng); chữ hình thanh. Một loại đồ đựng — cái chậu, gốc nghĩa ''chậu, bồn''.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bồn\": 分 (Phân) + 皿 (đồ đựng) — đồ đựng chia phần, đúng nghĩa ''chậu, bồn, lòng chảo'' trong 盆, 盆地 (bồn địa), 脸盆 (chậu rửa mặt). | Gương Hán-Việt | ''bồn'' trong ''bồn hoa'', ''bồn tắm'', ''bồn địa'' — y nguyên trong tiếng Việt | Mở khoá kiến thức | Nắm 盆 mở khoá loạt từ HSK 5-6: 盆, 盆地, 脸盆.", "Tự nguyên_Xie": "Đại triện | Theo Wiktionary, 盆 là hình thanh: 分 (Phân, biểu âm) + 皿 (đồ đựng, biểu nghĩa). Nghĩa gốc ''chậu, bồn — đồ đựng nông và rộng''. Mở rộng sang ''lòng chảo địa lý'' (盆地) và lượng từ chỉ một chậu (一盆花). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "534.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Phân (51) Mãnh (134)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Phân (số 51 - phân chia) ở trên chữ Mãnh (số 134 - cái chậu). Giải thích sự chuyển ý: Chữ Phân (phân chia) chỉ âm, chữ Mãnh (cái chậu) chỉ ý. Đồ chứa (Mãnh) được dùng để đựng một phần (Phân) nước hoặc đồ vật, gọi chung là cái chậu, bồn (Bồn). (Biến âm Hán Việt: Phân -> Bồn)", "Nghĩa Tiếng Việt_Xie": "cái chậu sành", "Hạng Tần Suất (Jun Da)": "2031.0", "Tần Suất % (Jun Da)": "97.2524255284", "GavinGrover_Once (Chiết tự trực tiếp)": "分 + 皿", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱分皿", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "分", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "皿", "Unihan_Simplified (Chữ Giản thể)": "盆", "Unihan_Traditional (Chữ Phồn thể)": "盆", "Pinyin_Xie": "pén", "Âm Hán Việt_Xie": "bồn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Lượng từ | 量词 | Thường làm danh từ chỉ cái chậu hoặc làm lượng từ cho chất lỏng, đồ vật đựng trong chậu. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Lượng từ | 量词 | Đứng giữa số từ (hoặc 这/那) và danh từ: 一杯茶, 这本书. Mỗi danh từ đi với lượng từ riêng; 个 là lượng từ dùng chung phổ biến nhất.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | Từ đơn | Từ vựng HSK 5: chậu | / | pén | / | chậu | Xuất hiện trong lộ trình | New HSK | New HSK 5 | · | Hộ gia đình | HSK | HSK 5 | · | Ngôi nhà và cuộc sống hàng ngày", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('疆', '{"9000": "2032.0", "Chữ Trung Quốc": "疆", "Bộ thủ & thành phần_Xie": "Bộ thủ | 田 | Số nét | 19 | nét | 弓 | cung | biểu nghĩa | cung tên — đo đạc ranh giới | 土 | thổ | biểu nghĩa | đất | 畺 | cương | biểu âm | âm gốc jiāng; gợi các dải ruộng phân chia ranh giới | 疆 = 土 (Thổ, biểu nghĩa: đất) + 彊 (Cương, biểu âm); chữ hình thanh. Cấu trúc thực tế trong giản thể: ⿰[弓+土]畺. Wiktionary chú: 土 biểu nghĩa đất, 彊 biểu âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cương\": đất (土) kéo dài như cung tên (弓) hướng đến — ranh giới cương thổ xa xôi. | Gương Hán-Việt | cương trong \"biên cương\" (vùng biên giới), \"cương thổ\" (lãnh thổ), \"Tân Cương\" (Xinjiang) | Mở khoá kiến thức | Biết 疆 (cương) mở khoá: 边疆 (biên cương), 疆土 (cương thổ), 新疆 (Tân Cương), 疆域 (lãnh thổ).", "Tự nguyên_Xie": "Kim văn | Theo Wiktionary, 疆 là chữ hình thanh gồm 土 (biểu nghĩa: đất) và 彊 (biểu âm, cho âm jiāng). Nghĩa gốc là ranh giới đất đai, biên giới; ý tưởng cung tên (弓) dùng để đo đạc và phân chia lãnh thổ. Nghĩa mở rộng: vùng đất, cương thổ, biên cương. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ranh giới đất đai", "Hạng Tần Suất (Jun Da)": "2032.0", "Tần Suất % (Jun Da)": "97.2559288149", "GavinGrover_Once (Chiết tự trực tiếp)": "No glyph available + 畺", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰畺", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "疆", "Unihan_Traditional (Chữ Phồn thể)": "疆", "Pinyin_Xie": "jiāng", "Âm Hán Việt_Xie": "cương", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ biên giới quốc gia hoặc vùng đất giới hạn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('赌', '{"9000": "2033.0", "Chữ Trung Quốc": "赌", "Bộ thủ & thành phần_Xie": "Bộ thủ | 貝 | Số nét | 12 | nét | 贝 | bối | biểu nghĩa | tiền bạc, của cải | 者 | giả | biểu âm | âm gốc dǔ | 赌 là dạng giản thể của 賭. Chữ gốc 賭 = 貝 (biểu nghĩa: tiền bạc) + 者 (biểu âm); chữ hình thanh. Ý gốc là dùng tiền để đặt cược.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đổ\": tiền (贝) của kẻ đánh bạc (者) — đổ bạc, cá cược tiền bạc. | Gương Hán-Việt | đổ trong \"đổ bạc\" (đánh bạc), \"cờ bạc đổ đen\" | Mở khoá kiến thức | Biết 赌 (đổ) mở khoá: 赌博 (đánh bạc), 赌注 (số tiền cược), 赌场 (sòng bạc).", "Tự nguyên_Xie": "Đại triện | 赌 là dạng giản thể của 賭. Wiktionary chú rõ xem 賭 để biết nghĩa gốc. 賭 gồm 貝 (tiền bạc, của cải) và 者 (biểu âm, cho âm dǔ). Nghĩa gốc là đặt tiền cược, đánh bạc; mở rộng thành cạnh tranh, so tài. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đánh bạc", "Hạng Tần Suất (Jun Da)": "2033.0", "Tần Suất % (Jun Da)": "97.2594217656", "GavinGrover_Once (Chiết tự trực tiếp)": "贝 + 者", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰贝者", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "者", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "贝", "Unihan_Simplified (Chữ Giản thể)": "赌", "Unihan_Traditional (Chữ Phồn thể)": "賭", "Pinyin_Xie": "dǔ", "Âm Hán Việt_Xie": "đổ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường làm động từ chỉ hành động cá cược ăn tiền hoặc đánh bạc. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | Xuất hiện trong lộ trình | New HSK | New HSK 6 | · | Giải trí và sở thích", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('塑', '{"9000": "2034.0", "Chữ Trung Quốc": "塑", "Bộ thủ & thành phần_Xie": "Bộ thủ | 土 | Số nét | 13 | nét | 朔 | sóc | biểu âm | phần biểu âm — gần âm ''tố/sóc'' | 土 | thổ | biểu nghĩa | đất — nặn đất sét | 塑 là chữ hình thanh (psc): 朔 (biểu âm) + 土 (đất, biểu nghĩa). Nặn đất sét thành tượng — nghĩa ''nặn tượng, tạo hình''.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Tố\": dùng đất (土) nặn tượng theo từng tháng (朔, mồng một) — đó là ''tố'', nặn, tạo hình. | Gương Hán-Việt | ''Tố'' trong ''tố nữ'' (nặn tượng nữ), ''điêu tố'' (điêu khắc), ''tố tạo'' (tạo hình). | Mở khoá kiến thức | Biết 塑 mở khoá 塑造 (tố tạo), 雕塑 (điêu tố, điêu khắc), 塑料 (tố liệu, nhựa), 塑料袋 (túi nhựa).", "Tự nguyên_Xie": "Theo Wiktionary, 塑 là chữ hình thanh gồm 朔 (biểu âm) + 土 (đất — biểu nghĩa: dùng đất sét để nặn). Nghĩa gốc ''nặn tượng bằng đất sét'' phái sinh các nghĩa ''tạo hình, đắp, đúc, đồ nhựa (vật liệu được tạo hình)''. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đắp tượng, nặn tượng", "Hạng Tần Suất (Jun Da)": "2034.0", "Tần Suất % (Jun Da)": "97.2629069645", "GavinGrover_Once (Chiết tự trực tiếp)": "朔 + 土", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱朔土", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "朔", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "土", "Unihan_Simplified (Chữ Giản thể)": "塑", "Unihan_Traditional (Chữ Phồn thể)": "塑", "Pinyin_Xie": "sù", "Âm Hán Việt_Xie": "tố", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ chỉ hành động nặn, đắp tượng đất sét hoặc tạo hình nghệ thuật. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('畏', '{"9000": "2035.0", "Chữ Trung Quốc": "畏", "Bộ thủ & thành phần_Xie": "Bộ thủ | 田 | Số nét | 9 | nét | 田 | điền | biểu âm | âm gốc — thành phần biến đổi từ 卜 trong kim văn | 鬼 | quỷ | biểu nghĩa | ma quỷ, điều đáng sợ | 畏 nguyên gốc là chữ hình thanh gồm 卜 (biểu âm) và 鬼 (biểu nghĩa: ma quỷ). Trong kim văn có thêm 心 và 攴. Thời Chiến Quốc, 卜 biến dạng thành dạng gần 田 trong giản thể hiện đại. Chữ gợi nỗi sợ hãi trước ma quỷ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"uý\": gặp ma quỷ (鬼) giữa đồng ruộng (田) — sợ hãi, kính uý đến run rẩy. | Gương Hán-Việt | uý trong \"kính uý\" (kính sợ), \"uý kỵ\" (kiêng sợ) — âm Hán-Việt \"uý\" gắn với sự e dè tôn trọng | Mở khoá kiến thức | Biết 畏 (uý) mở khoá: 畏惧 (sợ hãi), 畏缩 (rụt rè, co lại vì sợ), 敬畏 (kính sợ, kính trọng), 无所畏惧 (không sợ gì).", "Tự nguyên_Xie": "Kim văn | Theo Wiktionary, 畏 nguyên là chữ hình thanh gồm 卜 (biểu âm) và 鬼 (biểu nghĩa: ma quỷ). Trong kim văn, 心 và 攴 đôi khi được thêm vào. Thời Chiến Quốc, thành phần 卜 biến dạng thành dạng hiện đại. Nghĩa gốc và hiện tại: sợ hãi, kính sợ, e ngại. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1085.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Điền (024) Y (034)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Điền (số 024 - hình cái đầu to) ở trên bộ Y (số 034 - áo/viết giảm nét). Hình con ma chỉ thấy cái đầu gớm ghiếc, bên dưới là cái áo bùng nhùng, khiến người ta vô cùng sợ hãi. Giải thích sự chuyển ý: Đây là chữ Tượng hình (hoặc Hội ý). Úy là sợ hãi, kính sợ (kính úy).", "Nghĩa Tiếng Việt_Xie": "sợ sệt", "Hạng Tần Suất (Jun Da)": "2035.0", "Tần Suất % (Jun Da)": "97.2663807942", "GavinGrover_Once (Chiết tự trực tiếp)": "田 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱田", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "畏", "Unihan_Traditional (Chữ Phồn thể)": "畏", "Pinyin_Xie": "wèi", "Âm Hán Việt_Xie": "uý", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước danh từ để biểu thị tâm lý lo sợ hoặc tôn kính. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('吵', '{"9000": "2036.0", "Chữ Trung Quốc": "吵", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 7 | nét | 口 | khẩu | biểu nghĩa | miệng, lời nói | 少 | thiểu | biểu âm | ít; cho âm chǎo | 吵 = 口 (Khẩu, biểu nghĩa: miệng) + 少 (Thiểu, biểu âm: cho âm chǎo). Chữ hình thanh — bộ khẩu chỉ hành động liên quan đến miệng/lời nói, 少 cho âm. Nghĩa: ồn ào, tranh cãi, cãi nhau.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sảo\": 吵 = 口(miệng) + 少(ít) — sảo (ồn ào) nghịch lý: ít miệng 口 mà chẳng ít tiếng, 吵架 cãi nhau không ngừng. | Gương Hán-Việt | sảo ít gặp trong Hán-Việt thông dụng; 吵 chủ yếu là từ khẩu ngữ hiện đại. | Mở khoá kiến thức | Biết 吵 mở khoá: 吵架 (cãi nhau), 吵闹 (ồn ào náo loạn), 争吵 (tranh cãi), 吵嘴 (cãi nhau).", "Tự nguyên_Xie": "Wiktionary xác nhận: 吵 là hình thanh, 口 (miệng, biểu nghĩa) + 少 (biểu âm). Nghĩa gốc: ồn ào, huyên náo — tiếng nhiều người cùng nói lớn. Mở rộng: cãi nhau, tranh cãi (吵架 — cãi nhau), làm ồn (吵闹 — ồn ào). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1022.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Khẩu (030) Thiểu (058)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Khẩu (số 030 - cái miệng) ở bên trái chữ Thiểu (số 058 - ít/chỉ âm). Miệng (Khẩu) phát ra âm thanh không ngừng (trái ngược với Thiểu). Giải thích sự chuyển ý: Đây là chữ Hình thanh (hoặc Hội ý). Sảo là tiếng người nói ồn ào, ầm ĩ, cãi nhau (huyên sảo).", "Nghĩa Tiếng Việt_Xie": "(xem: sảo náo 吵鬧)", "Hạng Tần Suất (Jun Da)": "2036.0", "Tần Suất % (Jun Da)": "97.2698479057", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 少", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口少", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "少", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "吵", "Unihan_Traditional (Chữ Phồn thể)": "吵", "Pinyin_Xie": "chǎo", "Âm Hán Việt_Xie": "sảo, sao", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Thường làm động từ chỉ việc cãi nhau hoặc làm tính từ miêu tả không gian ồn ào, náo nhiệt. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | Chỉ tiếng ồn gây khó chịu: trẻ con khóc, tiếng xây dựng, nhạc lớn. Là tính từ khi miêu tả âm thanh, là động từ khi hành động gây ồn. Synonym: 喧闹 (ồn ào), 吵闹 (náo động). Ngược nghĩa: 安静 (yên tĩnh). | / | chǎo | / | ồn ào | Xuất hiện trong lộ trình | New HSK | New HSK 3 | · | Liên lạc | HSK | HSK 4 | · | Giải trí", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('囊', '{"9000": "2037.0", "Chữ Trung Quốc": "囊", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 22 | nét | 中 | trung | biểu nghĩa | giữa, bên trong (thành phần túi) | 冖 | mịch | biểu nghĩa | che phủ (nắp túi) | 吅 | tụng | biểu nghĩa | miệng túi | 𧘇 | ấy | biểu nghĩa | vải túi (bộ y) | 囊 là hình thanh phức tạp: ban đầu là hội ý — túi buộc chặt với nhiều vật bên trong. Dạng hiện đại là hình thanh: 㯻 (túi, biểu nghĩa, viết tắt) + 襄 (biểu âm, viết tắt). Cấu trúc hiện nay rất phức tạp do nhiều lần biến dạng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nang\": bao túi chứa đầy — nang y (túi thuốc), nang quát (bọc hết lại), nang trung vật (đồ trong túi). | Gương Hán-Việt | nang (囊 – túi, bao), nang trung (trong túi) | Mở khoá kiến thức | Biết 囊 mở khoá: 胶囊 (giao nang – viên nang), 囊括 (nang quát – bao gồm tất cả), 行囊 (hành nang – túi hành lý).", "Tự nguyên_Xie": "Tiểu triện | Wiktionary ghi 囊 ban đầu là hội ý: túi buộc chặt (𣒚) với các vật bên trong (𤕦). Phần 𤕦 cũng là biểu âm. Dạng hiện đại là hình thanh rút gọn: 㯻 (túi, biểu nghĩa) + 襄 (biểu âm). Nghĩa duy nhất là túi, bao, nang. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái túi", "Hạng Tần Suất (Jun Da)": "2037.0", "Tần Suất % (Jun Da)": "97.2733150172", "GavinGrover_Once (Chiết tự trực tiếp)": "No glyph available + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "囊", "Unihan_Traditional (Chữ Phồn thể)": "囊", "Pinyin_Xie": "náng", "Âm Hán Việt_Xie": "nang", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường dùng làm danh từ chỉ các loại túi hoặc làm động từ với nghĩa bao bọc, thu gom. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('嗯', '{"9000": "2038.0", "Chữ Trung Quốc": "嗯", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 13 | nét | 口 | khẩu | biểu nghĩa | miệng, âm thanh phát ra | 恩 | ân | biểu âm | ân huệ, ơn; cho âm ńg/ěn/ǹg | 嗯 = 口 (Khẩu, biểu nghĩa: miệng) + 恩 (Ân, biểu âm: cho âm en/ng). Chữ hình thanh — bộ khẩu chỉ âm thanh phát ra từ miệng, 恩 cho âm. Đây là chữ tạo để ghi âm thán từ ''ừ, ừm, hm'' trong tiếng Hán hiện đại.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ân\": 嗯 = 口(miệng) + 恩(ân) — ân (ừ) nhỉ, gật đầu bày tỏ sự đồng ý hoặc thắc mắc, như tiếng ''ừm ân'' trong miệng. | Gương Hán-Việt | ân ít gặp trong Hán-Việt học thuật; 嗯 là thán từ khẩu ngữ hiện đại. | Mở khoá kiến thức | Biết 嗯 mở khoá: hiểu thán từ trong hội thoại tiếng Hán, 嗯 là tín hiệu lắng nghe và phản hồi không lời.", "Tự nguyên_Xie": "Wiktionary xác nhận: 嗯 là hình thanh, 口 (miệng, biểu nghĩa) + 恩 (biểu âm). Chữ tạo muộn để ghi âm những thán từ không có chữ gốc: (1) ''ừm'' — thể hiện nghi ngờ, tò mò (âm ńg); (2) ''ừ'' — đồng ý (âm ňg); (3) thán từ biểu đạt bất ngờ (âm ǹg). Không thấy trong giáp cốt hay kim văn — chữ tạo muộn phục vụ giao tiếp khẩu ngữ hiện đại. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "này, hử, hở, sao (thán từ); ừ, hừ (thán từ); ô, ơ (thán từ)", "Hạng Tần Suất (Jun Da)": "2038.0", "Tần Suất % (Jun Da)": "97.2767810951", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 恩", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口恩", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "恩", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "嗯", "Unihan_Traditional (Chữ Phồn thể)": "嗯", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "ân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Thán từ | 叹词 | Thường đứng đầu câu làm thán từ để biểu thị sự đồng ý, tiếp thu hoặc nghi vấn trong đối thoại. | Thán từ | 叹词 | Bộc lộ cảm xúc hoặc dùng để gọi đáp: 啊, 哦, 喂. Đứng tách riêng ở đầu câu, không làm thành phần câu.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('泊', '{"9000": "2039.0", "Chữ Trung Quốc": "泊", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 8 | nét | 氵 | thuỷ | biểu nghĩa | nước | 白 | bạch | biểu âm | âm gốc bó/bó | 泊 = 氵(Thuỷ, biểu nghĩa: nước) + 白 (Bạch, biểu âm); chữ hình thanh. Wiktionary: tàu mắc cạn ở vùng nước cạn, đứng yên. Ý gốc là thuyền neo đậu, sau mở rộng thành hồ, tĩnh lặng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bạc\": nước (氵) trắng (白) phẳng lặng — thuyền neo đậu bạc lặng trên mặt hồ. | Gương Hán-Việt | bạc trong \"đạm bạc\" (sống giản dị, không màng danh lợi), \"bạc bẽo\" — âm bạc gần nghĩa nhẹ nhàng | Mở khoá kiến thức | Biết 泊 (bạc) mở khoá: 停泊 (neo đậu), 淡泊 (đạm bạc, không màng danh lợi), 湖泊 (hồ ao).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 泊 là chữ hình thanh gồm 水 (biểu nghĩa: nước, viết tắt thành 氵) và 白 (biểu âm, cho âm bó). Nghĩa gốc là thuyền đứng yên sau khi mắc cạn ở vùng nước cạn; mở rộng thành neo đậu thuyền, hồ nước, và trạng thái tĩnh lặng (淡泊: đạm bạc, không màng danh lợi). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ghé thuyền, đỗ thuyền; đạm bạc", "Hạng Tần Suất (Jun Da)": "2039.0", "Tần Suất % (Jun Da)": "97.2802409715", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 白", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵白", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "白", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "泊", "Unihan_Traditional (Chữ Phồn thể)": "泊", "Pinyin_Xie": "pō", "Âm Hán Việt_Xie": "bạc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Tính từ | 形容词 | Thường làm động từ chỉ việc neo đậu tàu thuyền hoặc làm tính từ chỉ sự thanh tĩnh, đạm bạc. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('肺', '{"9000": "2040.0", "Chữ Trung Quốc": "肺", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 8 | nét | 月 | nguyệt | biểu nghĩa | thịt/cơ thể (bộ nhục 肉 viết tắt) | 巿 | phế | biểu âm | âm gốc fèi | 肺 = ⺼ (Nhục/Nguyệt, biểu nghĩa: thịt, cơ thể) + 巿 (Phế, biểu âm); chữ hình thanh. 巿 khác 市 (chợ) — 巿 có nét dọc qua giữa. Ý gốc là nội tạng trong cơ thể — phổi.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phế\": cơ thể (月) thở bằng cái túi thị (巿) — phổi phế phình to khi hít vào. | Gương Hán-Việt | phế trong \"phế quản\" (phế quản), \"phế lao\" (bệnh lao phổi), \"phế dung\" (dung tích phổi) | Mở khoá kiến thức | Biết 肺 (phế) mở khoá: 肺炎 (viêm phổi), 肺癌 (ung thư phổi), 肺部 (vùng phổi), 心肺 (tim phổi).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 肺 là chữ hình thanh gồm 肉 (biểu nghĩa: thịt/cơ thể, viết tắt thành ⺼) và 巿 (biểu âm, cho âm fèi). Lưu ý 巿 (fèi) khác với 市 (shì — chợ). Nghĩa duy nhất: phổi — cơ quan hô hấp. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lá phổi", "Hạng Tần Suất (Jun Da)": "2040.0", "Tần Suất % (Jun Da)": "97.2836992977", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 巿", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月巿", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "巿", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "肺", "Unihan_Traditional (Chữ Phồn thể)": "肺", "Pinyin_Xie": "fèi", "Âm Hán Việt_Xie": "phế", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ cơ quan hô hấp hoặc dùng trong các từ ghép chỉ tâm can, lòng dạ con người. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | Từ đơn | Từ vựng HSK 5: phổi | / | fèi | / | phổi | Xuất hiện trong lộ trình | HSK | HSK 5 | · | Thân hình | New HSK | New HSK 6 | · | Thân hình", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('骤', '{"9000": "2041.0", "Chữ Trung Quốc": "骤", "Bộ thủ & thành phần_Xie": "Bộ thủ | 馬 | Số nét | 17 | nét | 马 | mã | biểu nghĩa | ngựa (bộ mã giản thể) | 聚 | tụ | biểu âm | tụ tập, tập hợp; cho âm zhòu | 骤 = 马 (Mã, biểu nghĩa: ngựa) + 聚 (Tụ, biểu âm: cho âm zhòu). Đây là giản thể của 驟. Cấu trúc hình thanh — bộ mã gợi ý tốc độ/ngựa phi nhanh, 聚 cho âm. Nghĩa: đột ngột, nhanh chóng (như ngựa phi vụt qua).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sậu\": 骤 = 马(ngựa) + 聚(tụ) — sậu (ngựa phi nước đại) tụ lại sức rồi vụt phóng đột ngột, 步骤 là từng bước ngựa phi. | Gương Hán-Việt | sậu trong 驟然 (sậu nhiên — đột nhiên), 步驟 (bộ sậu — các bước tiến hành). | Mở khoá kiến thức | Biết 骤 mở khoá: 步骤 (các bước), 骤然 (đột nhiên), 骤雨 (mưa rào đột ngột), 暴风骤雨 (bão tố).", "Tự nguyên_Xie": "骤 là giản thể của 驟. Chữ truyền thống 驟 = 馬 (ngựa, biểu nghĩa) + 聚 (biểu âm). Nghĩa gốc: ngựa phi nước đại — hành động nhanh và đột ngột. Từ hình ảnh ngựa phi vụt qua, 骤 phát triển nghĩa: đột ngột (骤然 — bỗng nhiên), bước/giai đoạn (步骤 — các bước). Hình ảnh 骤雨 (mưa rào đột ngột) rất phổ biến. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chợt, bỗng nhiên, bất ngờ", "Hạng Tần Suất (Jun Da)": "2041.0", "Tần Suất % (Jun Da)": "97.2871555566", "GavinGrover_Once (Chiết tự trực tiếp)": "马 + 聚", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰马聚", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "聚", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "马", "Unihan_Simplified (Chữ Giản thể)": "骤", "Unihan_Traditional (Chữ Phồn thể)": "驟", "Pinyin_Xie": "zhòu", "Âm Hán Việt_Xie": "sậu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Phó từ | 副词 | Tính từ | 形容词 | Thường làm phó từ đứng trước động từ hoặc tính từ để chỉ trạng thái diễn ra đột ngột, nhanh chóng. | Phó từ | 副词 | Bổ nghĩa cho động từ hoặc tính từ và luôn đứng TRƯỚC chúng — 都是, 很好. Không đứng sau như tiếng Việt và không bổ nghĩa cho danh từ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('缠', '{"9000": "2042.0", "Chữ Trung Quốc": "缠", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 13 | nét | 纟 | mịch | biểu nghĩa | tơ, sợi — quấn quanh | 㢆 | triền | biểu âm | âm gốc chán; biểu âm phức tạp chứa 廛 | 缠 = 纟(Mịch, biểu nghĩa: tơ sợi) + 㢆/廛 (Triền, biểu âm); chữ hình thanh. Wiktionary ghi 糸 biểu nghĩa tơ và 廛 biểu âm. Ý gốc là dây tơ quấn quanh, bó chặt.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"triền\": tơ (纟) quấn triền miên — như mối tình triền miên không dứt. | Gương Hán-Việt | triền trong \"triền miên\" (liên tục không dứt), \"vướng triền\" (vướng bận) | Mở khoá kiến thức | Biết 缠 (triền) mở khoá: 缠绕 (quấn quanh), 纠缠 (vướng víu, làm phiền), 缠绵 (triền miên, quyến luyến).", "Tự nguyên_Xie": "Theo Wiktionary, 缠 (phồn thể 纏) là chữ hình thanh gồm 糸 (biểu nghĩa: tơ, sợi) và 廛 (biểu âm, cho âm chán). Nghĩa gốc là quấn, cuộn tơ sợi xung quanh; mở rộng thành dính líu, quấy rầy, vướng víu không dứt được. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "quấn, vấn, buộc, bó quanh", "Hạng Tần Suất (Jun Da)": "2042.0", "Tần Suất % (Jun Da)": "97.2906050974", "GavinGrover_Once (Chiết tự trực tiếp)": "纟 + 㢆", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰纟㢆", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "㢆", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "纟", "Unihan_Simplified (Chữ Giản thể)": "缠", "Unihan_Traditional (Chữ Phồn thể)": "纏", "Pinyin_Xie": "chán", "Âm Hán Việt_Xie": "triền", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ chỉ hành động quấn quanh vật khác hoặc đeo bám gây phiền toái. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | chán | / | quấn quanh | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Động từ tôi", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('冈', '{"9000": "2043.0", "Chữ Trung Quốc": "冈", "Bộ thủ & thành phần_Xie": "Bộ thủ | 冂 | Số nét | 4 | nét | 冂 | quynh | biểu nghĩa | vòng bao quanh (núi) | 㐅 | biểu âm | chữ X, thành phần âm | 冈 = 网 (Võng, biểu âm) + 山 (Sơn, biểu nghĩa: núi) theo Wiktionary — chữ hình thanh. Dạng hiện đại bị rút gọn thành 冂+㐅, nhưng nghĩa vẫn liên quan đến gò, đồi thấp.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cương\": núi đồi bao quanh (冂) — sơn cương, gò đất nhỏ, cương vị như vị trí trên cao. | Gương Hán-Việt | sơn cương (山冈 – đồi thấp), cương vị | Mở khoá kiến thức | Biết 冈 mở khoá: 山冈 (sơn cương – đồi thấp), 冈峦 (cương loan – gò núi), dùng nhiều trong địa danh miền Trung Quốc.", "Tự nguyên_Xie": "Giáp cốt văn | Kim văn | Wiktionary ghi 冈 là hình thanh: 网 (biểu âm) + 山 (núi, biểu nghĩa). Nghĩa gốc là gò đất nhỏ, đồi thấp (sơn cương). Dùng trong địa danh và từ tả địa hình (山冈 – đồi thấp). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sườn núi", "Hạng Tần Suất (Jun Da)": "2043.0", "Tần Suất % (Jun Da)": "97.2940422353", "GavinGrover_Once (Chiết tự trực tiếp)": "冂 + 乂", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿵ (Bao quanh phía trên)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴冂乂", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "乂", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "冂", "Unihan_Simplified (Chữ Giản thể)": "冈", "Unihan_Traditional (Chữ Phồn thể)": "岡", "Pinyin_Xie": "gāng", "Âm Hán Việt_Xie": "cương", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ địa hình đồi núi thấp hoặc xuất hiện trong các địa danh. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('羞', '{"9000": "2044.0", "Chữ Trung Quốc": "羞", "Bộ thủ & thành phần_Xie": "Bộ thủ | 羊 | Số nét | 10 | nét | 羊 | dương | biểu nghĩa | con dê — vốn chỉ đồ ăn quý dâng tế | 丑 | sửu | biểu âm | gợi âm ''xiū'' (cũng là ''bàn tay'' trong cổ tự) | 羞 = 羊 (Dương, con dê) + 丑 (Sửu, biểu âm; cũng vẽ bàn tay). Chữ hội ý: hai tay dâng con dê làm đồ tế quý — nghĩa gốc ''đồ ăn ngon, dâng tặng''. Sau mượn dùng cho ''xấu hổ, ngượng'' (do âm).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt ''Tu'': hai tay (丑 ~ tay) dâng con dê (羊) quý — vinh dự quá hoá ngượng — đó là ''tu'', là xấu hổ. | Gương Hán-Việt | ''Tu'' trong tu sỉ (xấu hổ); cùng âm Hán-Việt với ''tu'' (修, sửa). Trong tiếng Việt 羞 dịch ''xấu hổ, thẹn''. | Mở khoá kiến thức | Biết 羞 mở khóa 害羞 (hại tu / xấu hổ), 羞耻 (tu sỉ / xấu hổ), 羞愧 (tu quý / xấu hổ ăn năn), 恼羞成怒 (não tu thành nộ).", "Tự nguyên_Xie": "Giáp cốt văn | Kim văn | Đại triện | Tiểu triện | Theo Wiktionary, 羞 là chữ hội ý kiêm hình thanh: 羊 (dê) + 丑 (bàn tay) — bàn tay dâng dê làm đồ tế. Nghĩa gốc ''đồ ăn ngon, dâng tặng''; sau mượn cho nghĩa ''xấu hổ, ngượng'' (đồng âm). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đồ ăn ngon", "Hạng Tần Suất (Jun Da)": "2044.0", "Tần Suất % (Jun Da)": "97.2974793733", "GavinGrover_Once (Chiết tự trực tiếp)": "羊 + 丑", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱羊丑", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "丑", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "羊", "Unihan_Simplified (Chữ Giản thể)": "羞", "Unihan_Traditional (Chữ Phồn thể)": "羞", "Pinyin_Xie": "xiū", "Âm Hán Việt_Xie": "tu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Danh từ | 名词 | Thường làm tính từ biểu thị sự e thẹn, xấu hổ hoặc làm động từ mang nghĩa cảm thấy ngượng ngùng. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('瞪', '{"9000": "2045.0", "Chữ Trung Quốc": "瞪", "Bộ thủ & thành phần_Xie": "Bộ thủ | 目 | Số nét | 17 | nét | 目 | mục | biểu nghĩa | mắt | 登 | đăng | biểu âm | âm gốc dèng | 瞪 = 目 (Mục, biểu nghĩa: mắt) + 登 (Đăng, biểu âm); chữ hình thanh. Ý gốc là mắt mở to, trừng mắt nhìn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trừng\": mắt (目) trèo lên (登) — trừng mắt nhìn chằm chằm như leo lên đỉnh núi. | Gương Hán-Việt | trừng trong \"trừng mắt\" (nhìn chằm chằm, tức tối), \"trừng phạt\" — nhưng 瞪 chỉ nghĩa trừng mắt | Mở khoá kiến thức | Biết 瞪 (trừng) mở khoá: 瞪眼 (trừng mắt), 瞪大眼睛 (mở to mắt kinh ngạc).", "Tự nguyên_Xie": "Theo Wiktionary, 瞪 là chữ hình thanh gồm 目 (biểu nghĩa: mắt) và 登 (biểu âm, cho âm dèng). Nghĩa gốc và hiện tại là trừng mắt, mở to mắt nhìn chằm chằm; biểu đạt sự tức giận, ngạc nhiên, hay chăm chú nhìn. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "giương mắt, trợn mắt", "Hạng Tần Suất (Jun Da)": "2045.0", "Tần Suất % (Jun Da)": "97.3009128937", "GavinGrover_Once (Chiết tự trực tiếp)": "目 + 登", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰目登", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "登", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "目", "Unihan_Simplified (Chữ Giản thể)": "瞪", "Unihan_Traditional (Chữ Phồn thể)": "瞪", "Pinyin_Xie": "dèng", "Âm Hán Việt_Xie": "trừng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ chỉ hành động mở to mắt nhìn thẳng để biểu thị sự tức giận hoặc kinh ngạc. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | dèng | / | nhìn chằm chằm | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Hành vi tôi | HSK | HSK 6 | · | Động từ", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('吊', '{"9000": "2046.0", "Chữ Trung Quốc": "吊", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 6 | nét | 口 | khẩu | biểu nghĩa | miệng — người tụ lại than khóc | 巾 | cân | biểu nghĩa | vải — vải che thi hài | 吊 là biến thể của 弔. Chữ gốc 弔 gợi hình người cúi đầu bên cạnh thi hài được bọc vải (弓 biến dạng). Wiktionary mô tả 吊 là dạng phổ thông trung gian, với 口 (người tụ họp khóc thương) và 巾 (vải liệm). Nghĩa gốc: phúng điếu; mở rộng: treo, treo cổ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"điếu\": miệng (口) và vải (巾) — đám người kêu khóc bên tấm vải liệm — phúng điếu người mất. | Gương Hán-Việt | điếu trong \"phúng điếu\" (viếng tang), \"điếu văn\" (bài văn tế), \"câu điếu\" (câu cá) | Mở khoá kiến thức | Biết 吊 (điếu) mở khoá: 吊唁 (phúng điếu), 吊车 (cần cẩu), 吊桥 (cầu treo), 吊灯 (đèn treo).", "Tự nguyên_Xie": "Theo Wiktionary, 吊 là biến thể phổ thông của 弔. 弔 là chữ tượng hình vẽ người cúi đầu bên cạnh thi hài được bọc. Trong 吊, thành phần phân tích thành 口 (người tụ tập) và 巾 (vải che). Nghĩa gốc là phúng điếu, thăm viếng người chết; mở rộng thành treo, treo cao (như vải liệm treo). | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "viếng người chết; treo ngược", "Hạng Tần Suất (Jun Da)": "2046.0", "Tần Suất % (Jun Da)": "97.3043427966", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 巾", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱口巾", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "巾", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "吊", "Unihan_Traditional (Chữ Phồn thể)": "吊", "Pinyin_Xie": "diào", "Âm Hán Việt_Xie": "điếu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Lượng từ | 量词 | Thường làm động từ chỉ hành động treo vật gì đó lên cao hoặc đi phúng viếng người đã khuất. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Lượng từ | 量词 | Đứng giữa số từ (hoặc 这/那) và danh từ: 一杯茶, 这本书. Mỗi danh từ đi với lượng từ riêng; 个 là lượng từ dùng chung phổ biến nhất.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | diào | / | treo | Xuất hiện trong lộ trình | New HSK | New HSK 6 | · | Động từ | HSK | HSK 6 | · | Động từ hàng ngày", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('贾', '{"9000": "2047.0", "Chữ Trung Quốc": "贾", "Bộ thủ & thành phần_Xie": "Bộ thủ | 貝 | Số nét | 10 | nét | 覀 | á | biểu nghĩa | che phủ (dạng biến thể của 西) | 贝 | bối | biểu nghĩa | tiền tệ, vỏ sò (tài sản) | 贾 là dạng giản thể của 賈. Wiktionary không cung cấp phân tích hình thanh/hội ý rõ ràng. Cấu trúc 覀+贝 gợi ý ''che giấu tài sản'' — thương nhân cất giấu hàng hoá. Chủ yếu dùng làm họ người và nghĩa thương nhân.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"giả\": che (覀) tài sản (贝) — thương giả, người buôn bán che giấu nguồn gốc hàng hoá để kiếm lời. | Gương Hán-Việt | thương giả (商贾 – thương nhân), Giả Bảo Ngọc (Hồng Lâu Mộng) | Mở khoá kiến thức | Biết 贾 mở khoá: 商贾 (thương giả – thương nhân), họ Giả (贾宝玉 – Giả Bảo Ngọc).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Wiktionary ghi 贾 là dạng giản thể của 賈 (thay 貝 bằng 贝). Nguồn gốc 賈 chưa rõ hình thanh hay hội ý. Nghĩa là thương nhân, buôn bán; cũng dùng làm họ phổ biến. Hán-Việt đọc là ''giả'' (giả/cổ). | Suy từ bộ phận cấu thành · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cửa hàng buôn bán", "Hạng Tần Suất (Jun Da)": "2047.0", "Tần Suất % (Jun Da)": "97.3077675317", "GavinGrover_Once (Chiết tự trực tiếp)": "覀 + 贝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱覀贝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "贝", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "覀", "Unihan_Simplified (Chữ Giản thể)": "贾", "Unihan_Traditional (Chữ Phồn thể)": "賈", "Pinyin_Xie": "jiǎ", "Âm Hán Việt_Xie": "cổ, giả", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường dùng làm danh từ chỉ người buôn bán trong văn ngôn hoặc dùng làm họ của người. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('漏', '{"9000": "2048.0", "Chữ Trung Quốc": "漏", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 14 | nét | 氵 | thuỷ | biểu nghĩa | nước | 屚 | lậu | biểu nghĩa kiêm biểu âm | vốn là 尸+雨 (nước mưa rò dưới mái) | 漏 = 氵 (Thuỷ, biểu nghĩa: nước) + 屚 (biểu nghĩa kiêm biểu âm: nước mưa rò qua mái nhà — 尸/mái + 雨/mưa); chữ hội ý có yếu tố hình thanh. Hình ảnh nước mưa thấm dột qua mái nhà — gốc nghĩa ''rò rỉ, dột''.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lậu\": 氵 (nước) + 屚 (mưa rò qua mái) — nước mưa thấm dột, đúng nghĩa ''rò, dột, để lộ'' trong 漏洞 (lỗ hổng), 走漏 (tiết lộ), 泄漏 (rò rỉ thông tin). | Gương Hán-Việt | ''lậu'' trong ''tiết lậu'', ''lậu thông tin'' | Mở khoá kiến thức | Nắm 漏 mở khoá loạt từ HSK 5-7: 漏, 走漏, 漏洞, 泄漏.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 漏 là hội ý (kiêm hình thanh — ls=ic, ls2=psc): 水/氵 (nước, biểu nghĩa) + 屚 (vốn là 尸/mái nhà + 雨/mưa — ''rò mưa''). Nghĩa gốc ''rò rỉ, dột, để lộ'', mở rộng sang nghĩa trừu tượng ''tiết lộ'' (走漏, 泄漏) và ''lỗ hổng'' (漏洞). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "rò rỉ, dột", "Hạng Tần Suất (Jun Da)": "2048.0", "Tần Suất % (Jun Da)": "97.3111922668", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 屚", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵屚", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "屚", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "漏", "Unihan_Traditional (Chữ Phồn thể)": "漏", "Pinyin_Xie": "lòu", "Âm Hán Việt_Xie": "lậu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường làm động từ chỉ sự rò rỉ chất lỏng hoặc bỏ sót thông tin, chi tiết trong công việc. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | Từ đơn | Từ vựng HSK 5: rò rỉ, để lộ | / | lòu | / | rò rỉ, để lộ | Xuất hiện trong lộ trình | HSK | HSK 5 | · | Ngôi nhà và cuộc sống hàng ngày | New HSK | New HSK 5 | · | Động từ", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('斑', '{"9000": "2049.0", "Chữ Trung Quốc": "斑", "Bộ thủ & thành phần_Xie": "Bộ thủ | 文 | Số nét | 12 | nét | 王 | vương | biểu nghĩa | ngọc bích (珏/玨 — hai mảnh ngọc) | 文 | văn | biểu nghĩa | hoa văn, hình xăm — vằn màu | 斑 là chữ hội ý gồm 珏 (hai mảnh ngọc) và 文 (hoa văn/hình xăm). Wiktionary: thành phần 珏 xuất hiện dưới dạng bảo thủ hơn là 玨. Nghĩa gốc là \"màu lẫn lộn\" — vết hoa văn đốm trên ngọc bích, sau mở rộng thành đốm, vết, vằn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ban\": hai khối ngọc (王王) kẹp hoa văn (文) — tạo nên những đốm ban vằn nhiều màu. | Gương Hán-Việt | ban trong \"ban điểm\" (điểm đốm), \"ban lan\" (nhiều màu rực rỡ) | Mở khoá kiến thức | Biết 斑 (ban) mở khoá: 斑点 (đốm, vết), 斑马 (ngựa vằn), 雀斑 (tàn nhang), 斑纹 (vằn hoa).", "Tự nguyên_Xie": "Theo Wiktionary, 斑 là chữ hội ý gồm 珏 (hai mảnh ngọc bích — 珏/玨) và 文 (hoa văn, hình xăm). Nghĩa gốc là màu sắc lẫn lộn, vằn vện; cụ thể là hoa văn nhiều màu trên ngọc hoặc da. Trong chữ hiện đại, 珏 được viết thành hai 王 kẹp 文 ở giữa. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lốm đốm; sắc lẫn lộn, có pha màu khác", "Hạng Tần Suất (Jun Da)": "2049.0", "Tần Suất % (Jun Da)": "97.314614418", "GavinGrover_Once (Chiết tự trực tiếp)": "玨 + 文", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴玨文", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "玨", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "文", "Unihan_Simplified (Chữ Giản thể)": "斑", "Unihan_Traditional (Chữ Phồn thể)": "斑", "Pinyin_Xie": "bān", "Âm Hán Việt_Xie": "ban", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Chữ này thường làm danh từ chỉ vết lốm đốm hoặc làm tính từ bổ nghĩa cho danh từ để chỉ màu sắc loang lổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('涛', '{"9000": "2050.0", "Chữ Trung Quốc": "涛", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 10 | nét | 氵 | thuỷ | biểu nghĩa | nước | 寿 | thọ | biểu nghĩa | thành phần thay thế trong giản thể — gốc là 壽 | 涛 là dạng giản thể của 濤. Chữ gốc 濤 = 氵(Thuỷ, biểu nghĩa: nước) + 壽 (Thọ, biểu âm cho âm tāo). Giản thể dùng 寿 thay 壽. chưa có nguồn học thuật rõ về cấu trúc của dạng giản thể.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đào\": nước (氵) cuộn trào như sóng (涛) — âm đào gợi sóng đào dạt dào. | Gương Hán-Việt | đào trong \"hải đào\" (sóng biển), \"phong đào\" (gió sóng) | Mở khoá kiến thức | Biết 涛 (đào) mở khoá: 波涛 (sóng gió), 海涛 (sóng biển), 涛声 (tiếng sóng).", "Tự nguyên_Xie": "Tiểu triện | 涛 là dạng giản thể của 濤. Wiktionary không có mục riêng cho 涛 — xem 濤. 濤 gồm 氵(nước) và 壽 (biểu âm, cho âm tāo). Nghĩa gốc và hiện tại là sóng lớn, sóng cả; thường dùng trong thơ văn để chỉ sóng biển hùng vĩ. chưa có nguồn học thuật rõ về lịch sử phát triển. | Theo Wiktionary · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sóng lớn", "Hạng Tần Suất (Jun Da)": "2050.0", "Tần Suất % (Jun Da)": "97.3180308845", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 寿", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵寿", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "寿", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "涛", "Unihan_Traditional (Chữ Phồn thể)": "濤", "Pinyin_Xie": "tāo", "Âm Hán Việt_Xie": "đào", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong văn thơ hoặc làm thành phần trong tên riêng để chỉ những con sóng lớn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('悠', '{"9000": "2051.0", "Chữ Trung Quốc": "悠", "Bộ thủ & thành phần_Xie": "Bộ thủ | 心 | Số nét | 11 | nét | 攸 | du | biểu âm | xa xôi; cho âm yōu | 心 | tâm | biểu nghĩa | tim, tâm trí, cảm xúc | 悠 = 攸 (Du, biểu âm: cho âm yōu) + 心 (Tâm, biểu nghĩa: tâm trí/cảm xúc). Chữ hình thanh — bộ tâm chỉ trạng thái tâm lý, 攸 cho âm. Nghĩa: thong thả, yên bình, sâu xa, lâu dài.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"du\": 悠 = 攸(du) + 心(tâm) — du (thong dong) tâm trí, như du hành thư thái, 悠久 (lâu dài) như hành trình du ngoạn không vội vã. | Gương Hán-Việt | du trong 悠久 (du cửu — lâu dài), 悠閒 (du nhàn — nhàn hạ, thư thái). | Mở khoá kiến thức | Biết 悠 mở khoá: 悠久 (lâu dài), 悠闲 (nhàn hạ), 悠扬 (du dương — âm thanh vang vọng), 忽悠 (lừa phỉnh).", "Tự nguyên_Xie": "Wiktionary xác nhận: 悠 là hình thanh, 攸 (biểu âm) + 心 (tâm trí, biểu nghĩa). Nghĩa gốc: tâm trạng thong thả, bình yên — cảm giác xa xôi, không vội vàng. Mở rộng: (1) lâu dài, xa xôi — 悠久 (lâu dài); (2) nhàn nhã, thong thả — 悠闲 (nhàn hạ); (3) lơ lửng, đung đưa nhẹ nhàng. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "xa vời", "Hạng Tần Suất (Jun Da)": "2051.0", "Tần Suất % (Jun Da)": "97.3214437335", "GavinGrover_Once (Chiết tự trực tiếp)": "攸 + 心", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱攸心", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "攸", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "心", "Unihan_Simplified (Chữ Giản thể)": "悠", "Unihan_Traditional (Chữ Phồn thể)": "悠", "Pinyin_Xie": "yōu", "Âm Hán Việt_Xie": "du", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường dùng làm tính từ miêu tả trạng thái thong thả, xa xăm hoặc làm động từ với nghĩa đung đưa. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鹿', '{"9000": "2052.0", "Chữ Trung Quốc": "鹿", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鹿 | Số nét | 11 | nét | 鹿 | lộc | tượng hình | con hươu — đầu, gạc, thân và chân | 鹿 là tượng hình: hình ảnh con hươu được trừu tượng hoá. Phần trên là đầu và gạc (biến thành 广), giữa là thân, dưới là chân (biến thành 比). Một trong những chữ tượng hình cổ điển đặc sắc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lộc\": con hươu (鹿) — lộc (may mắn, tài lộc) đồng âm với 禄 (bổng lộc), nên hươu là biểu tượng may mắn. | Gương Hán-Việt | lộc (鹿 – hươu; đồng âm với 禄 bổng lộc) | Mở khoá kiến thức | Biết 鹿 mở khoá: 鹿茸 (lộc nhung – nhung hươu), 鹿皮 (lộc bì – da hươu), thành ngữ 逐鹿中原 (tranh thiên hạ).", "Tự nguyên_Xie": "Giáp cốt văn | Kim văn | Đại triện | Tiểu triện | Wiktionary ghi 鹿 là tượng hình: hình con hươu rất trực quan trong giáp cốt văn. Quá trình tiểu triện hoá trừu tượng hoá rất mạnh: chân hươu biến thành 比, đầu và gạc biến thành phần giống 广, thân giữa thành dạng giống 凸. Nghĩa duy nhất là hươu nai. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1000.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Là hình vẽ mô phỏng một con hươu đang chạy. Giải thích sự chuyển ý: Đây là chữ Tượng hình. Lộc là con hươu (tuần lộc, hươu sao).", "Nghĩa Tiếng Việt_Xie": "con hươu", "Hạng Tần Suất (Jun Da)": "2052.0", "Tần Suất % (Jun Da)": "97.3248539986", "GavinGrover_Once (Chiết tự trực tiếp)": "No glyph available + 比", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴比", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "鹿", "Unihan_Traditional (Chữ Phồn thể)": "鹿", "Pinyin_Xie": "lù", "Âm Hán Việt_Xie": "lộc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường đứng độc lập làm danh từ chỉ loài hươu hoặc làm thành phần cấu tạo từ ghép. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | lù | / | hươu | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Động vật và côn trùng", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('俘', '{"9000": "2053.0", "Chữ Trung Quốc": "俘", "Bộ thủ & thành phần_Xie": "Bộ thủ | 人 | Số nét | 9 | nét | 亻 | nhân | biểu nghĩa | người | 孚 | phu | biểu âm | âm gốc fú; 孚 gốc có nghĩa là bắt giữ | 俘 = 亻(Nhân, biểu nghĩa: người) + 孚 (Phu, biểu âm); chữ hình thanh. Wiktionary: 俘 gốc viết là 孚 (bắt giữ), sau thêm 人 để nhấn mạnh đây là người bị bắt. Nghĩa gốc và hiện tại: tù binh, người bị bắt làm con tin.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phu\": người (亻) bị phu (孚) bắt giữ — đó là tù binh, kẻ bị bắt làm tù phu. | Gương Hán-Việt | phu trong \"tù binh phu\" — âm Hán-Việt \"phu\" ít dùng độc lập, gặp trong \"tù phu\" (俘虏) | Mở khoá kiến thức | Biết 俘 (phu) mở khoá: 俘虏 (tù binh), 战俘 (chiến tù, tù binh chiến tranh), 被俘 (bị bắt làm tù binh).", "Tự nguyên_Xie": "Kim văn | Theo Wiktionary, 俘 là chữ hình thanh gồm 人 (biểu nghĩa: người, viết tắt thành 亻) và 孚 (biểu âm, cho âm fú). Chữ gốc là 孚 (bắt giữ); sau 人 được thêm vào để làm rõ đây là người bị bắt. Nghĩa gốc là bắt tù binh; hiện tại dùng cho cả tù binh lẫn vật bị tịch thu. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bắt được", "Hạng Tần Suất (Jun Da)": "2053.0", "Tần Suất % (Jun Da)": "97.3282616798", "GavinGrover_Once (Chiết tự trực tiếp)": "亻 + 孚", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰亻孚", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "孚", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "亻", "Unihan_Simplified (Chữ Giản thể)": "俘", "Unihan_Traditional (Chữ Phồn thể)": "俘", "Pinyin_Xie": "fú", "Âm Hán Việt_Xie": "phu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường làm động từ chỉ hành động bắt sống quân địch hoặc làm danh từ chỉ tù binh trong chiến tranh. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('锡', '{"9000": "2054.0", "Chữ Trung Quốc": "锡", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 13 | nét | 钅 | kim | biểu nghĩa | kim loại | 易 | dịch | biểu âm | dịch (cho âm xī) | 锡 = 钅(Kim, biểu nghĩa: kim loại) + 易 (Dịch, biểu âm); chữ hình thanh. Bộ kim chỉ đây là kim loại, dịch cho âm. Wiktionary không có glyphOrigin chi tiết nhưng cấu trúc rõ ràng là hình thanh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tích\": kim loại (钅) dễ thay đổi (易) — thiếc (錫) mềm dẻo dễ đúc, Vô Tích thành phố nổi tiếng vùng Giang Nam. | Gương Hán-Việt | tích (锡 – thiếc) | Mở khoá kiến thức | Biết 锡 mở khoá: 无锡 (Vô Tích – thành phố Giang Tô), 锡纸 (tích chỉ – giấy bạc/giấy thiếc), 锡矿 (tích khoáng – mỏ thiếc).", "Tự nguyên_Xie": "Giáp cốt văn | Kim văn | Bạch thư | Đại triện | Tiểu triện | 锡 là dạng giản thể, bộ kim (钅) + 易 (biểu âm). Wiktionary không cung cấp phân tích nguồn gốc đặc biệt. Nghĩa gốc và duy nhất là thiếc (kim loại). Dùng trong tên thành phố Vô Tích (无锡 – Wúxī) và tên người. Hán-Việt đọc là ''tích''. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thiếc, Zn", "Hạng Tần Suất (Jun Da)": "2054.0", "Tần Suất % (Jun Da)": "97.3316652267", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 易", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅易", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "易", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "锡", "Unihan_Traditional (Chữ Phồn thể)": "錫", "Pinyin_Xie": "xī", "Âm Hán Việt_Xie": "tích", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường dùng làm danh từ chỉ nguyên tố hóa học thiếc hoặc làm động từ trong văn ngôn với nghĩa ban tặng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | xī | / | thiếc | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Hóa học và Sinh học II", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('卑', '{"9000": "2055.0", "Chữ Trung Quốc": "卑", "Bộ thủ & thành phần_Xie": "Bộ thủ | 十 | Số nét | 8 | nét | 甲 | giáp | biểu nghĩa | cái quạt — kẻ cầm quạt hầu hạ | 𠂇 | biểu nghĩa | bàn tay cầm | 卑 là chữ hội ý gồm 甲 (cái quạt) và 𠂇 (bàn tay). Wiktionary: người cầm quạt hầu hạ — chỉ địa vị thấp kém, phục vụ. Từ hình ảnh người tôi tớ cầm quạt, nghĩa mở rộng thành thấp hèn, ti tiện.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ti\": tay (𠂇) cầm quạt (甲) hầu hạ — thân phận ti tiện, thấp kém như đứa hầu. | Gương Hán-Việt | ti trong \"ti tiện\" (hèn hạ), \"ti bỉ\" (thấp kém, xấu xa) | Mở khoá kiến thức | Biết 卑 (ti) mở khoá: 卑鄙 (đê tiện), 卑微 (ti tiện, hèn mọn), 自卑 (tự ti), 卑下 (thấp kém).", "Tự nguyên_Xie": "Kim văn | Theo Wiktionary, 卑 là chữ hội ý gồm 甲 (cái quạt) và 𠂇 (bàn tay) — hình ảnh một người cầm quạt phục vụ, chỉ địa vị thấp kém. Nghĩa gốc là người hầu; mở rộng thành thấp hèn, ti tiện, khiêm tốn thái quá. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thấp; thấp hèn (vị trí; địa vị); kém; bỉ ổi; ti tiện; thấp hèn; hèn mọn; tầm thường; khiêm tốn; khiêm nhường; lễ độ", "Hạng Tần Suất (Jun Da)": "2055.0", "Tần Suất % (Jun Da)": "97.3350615386", "GavinGrover_Once (Chiết tự trực tiếp)": "No glyph available + 十", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴十", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "卑", "Unihan_Traditional (Chữ Phồn thể)": "卑", "Pinyin_Xie": "bēi", "Âm Hán Việt_Xie": "ti", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường làm tính từ đứng trước danh từ hoặc làm vị ngữ để chỉ địa vị thấp kém hay thái độ khiêm nhường. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('葬', '{"9000": "2056.0", "Chữ Trung Quốc": "葬", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 12 | nét | 艹 | thảo | biểu nghĩa | cỏ — che phủ thi hài | 死 | tử | biểu nghĩa | người chết | 廾 | củng | biểu nghĩa | hai tay — cẩn thận đặt xuống | 葬 là chữ hội ý: 艹 (cỏ, bên trên) + 死 (người chết) + 廾 (hai tay, bên dưới). Wiktionary: chôn người chết 死 vào trong cỏ 茻; phần trên nay dùng bộ thảo 艹, phần dưới giản hóa thành 廾. Hình ảnh rõ ràng: tay đặt thi hài dưới cỏ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"táng\": cỏ (艹) che phủ người chết (死), tay (廾) nhẹ nhàng hạ xuống — đó là lễ mai táng. | Gương Hán-Việt | táng trong \"mai táng\" (chôn cất), \"tang lễ\" (lễ mai táng), \"an táng\" (chôn cất yên nghỉ) | Mở khoá kiến thức | Biết 葬 (táng) mở khoá: 埋葬 (chôn cất), 安葬 (an táng), 葬礼 (tang lễ), 海葬 (thủy táng).", "Tự nguyên_Xie": "Kim văn | Theo Wiktionary, 葬 là chữ hội ý gồm 茻 (cỏ um tùm) và 死 (người chết). Nghĩa gốc là chôn người chết trong cỏ — cách mai táng thời cổ đại. Phần trên hiện nay dùng bộ thảo 艹, phần dưới 廾 (hai tay, giản hóa từ 茻 bên dưới). Hình ảnh: đặt thi hài xuống đất, đắp cỏ lên. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1776.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thảo (140) Tử (078) Củng (055)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Thảo (số 140 - cây cỏ/ 艹) ở trên chữ Tử (số 078 - chết/ 死 /viết giảm nét) và chữ Củng (số 055 - chắp tay/ 廾). Hai tay cung kính đắp cỏ lên thi thể người đã mất. Giải thích sự chuyển ý: Đây là chữ Hội ý. Táng là hành động chôn cất người đã mất xuống đất (mai táng, an táng).", "Nghĩa Tiếng Việt_Xie": "chôn, vùi, mai táng", "Hạng Tần Suất (Jun Da)": "2056.0", "Tần Suất % (Jun Da)": "97.3384506155", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "葬", "Unihan_Traditional (Chữ Phồn thể)": "塟", "Pinyin_Xie": "zàng", "Âm Hán Việt_Xie": "táng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước danh từ chỉ người chết để biểu thị việc chôn cất. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | zàng | / | chôn cất | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Sự sống và cái chết", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('铭', '{"9000": "2057.0", "Chữ Trung Quốc": "铭", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 11 | nét | 钅 | kim | biểu nghĩa | kim loại — khắc vào kim loại | 名 | danh | biểu âm | âm gốc míng | 铭 là dạng giản thể của 銘. Chữ gốc 銘 = 金 (Kim, biểu nghĩa: kim loại) + 名 (Danh, biểu âm); chữ hình thanh. Ý gốc là khắc chữ vào đồ kim loại để ghi nhớ, lưu danh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"minh\": kim loại (钅) khắc tên (名) — danh minh khắc sâu không phai, như văn bia trường tồn. | Gương Hán-Việt | minh trong \"minh văn\" (văn khắc trên đồ vật), \"tâm minh\" (khắc ghi trong lòng) | Mở khoá kiến thức | Biết 铭 (minh) mở khoá: 铭记 (khắc ghi, ghi nhớ mãi), 座右铭 (tâm niệm, phương châm sống), 铭文 (văn khắc).", "Tự nguyên_Xie": "Kim văn | 铭 là dạng giản thể của 銘. Wiktionary chú rõ xem 銘. 銘 gồm 金 (kim loại) và 名 (biểu âm, cho âm míng). Nghĩa gốc là khắc chữ vào đồng thau, đồ kim loại; mở rộng thành ghi khắc sâu vào lòng (铭记: khắc ghi), thể loại văn bia (座右铭: tâm niệm ngồi bên phải). | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bài minh (khắc chữ vào bia để tự răn mình hoặc ghi chép công đức); ghi nhớ", "Hạng Tần Suất (Jun Da)": "2057.0", "Tần Suất % (Jun Da)": "97.3418381421", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 名", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅名", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "名", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "铭", "Unihan_Traditional (Chữ Phồn thể)": "銘", "Pinyin_Xie": "míng", "Âm Hán Việt_Xie": "minh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường làm động từ với nghĩa ghi khắc sâu sắc vào lòng hoặc làm danh từ chỉ bài văn khắc trên bia đá. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('滩', '{"9000": "2058.0", "Chữ Trung Quốc": "滩", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 13 | nét | 氵 | thuỷ | biểu nghĩa | nước (bộ thuỷ giản thể) | 难 | nan | biểu âm | khó khăn; cho âm tān | 滩 = 氵(Thuỷ, biểu nghĩa: nước) + 难 (Nan, biểu âm: cho âm tān). Đây là giản thể của 灘. Cấu trúc hình thanh — bộ thuỷ chỉ liên quan đến nước/mặt nước, 难 cho âm. Nghĩa: bãi cát, bờ biển, vùng nước cạn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"than\": 滩 = 氵(nước) + 难(nan/khó) — than (bãi) cát khó lội qua vì nước lăn sóng, 沙滩 (bãi cát) là nơi sóng vỗ. | Gương Hán-Việt | than trong 沙灘 (sa than — bãi cát), 海灘 (hải than — bãi biển). | Mở khoá kiến thức | Biết 滩 mở khoá: 沙滩 (bãi cát), 海滩 (bãi biển), 滩涂 (vùng đất bùn ven biển), 险滩 (ghềnh thác nguy hiểm).", "Tự nguyên_Xie": "滩 là giản thể của 灘. Chữ truyền thống 灘 = 水 (nước, biểu nghĩa) + 難 (biểu âm). Nghĩa gốc: vùng đất bằng phẳng ven sông/biển — bãi cát, bờ bãi ven nước. Mở rộng: bãi đá ngầm, ghềnh thác (nơi nước chảy siết qua vùng đá). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thác nước", "Hạng Tần Suất (Jun Da)": "2058.0", "Tần Suất % (Jun Da)": "97.3452230847", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 难", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵难", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "难", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "滩", "Unihan_Traditional (Chữ Phồn thể)": "灘", "Pinyin_Xie": "tān", "Âm Hán Việt_Xie": "than", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ vùng đất bồi ven nước hoặc kết hợp với các từ chỉ địa hình. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('嫁', '{"9000": "2059.0", "Chữ Trung Quốc": "嫁", "Bộ thủ & thành phần_Xie": "Bộ thủ | 女 | Số nét | 13 | nét | 女 | nữ | biểu nghĩa | người phụ nữ | 家 | gia | biểu âm | nhà, gia đình; cho âm jià | 嫁 = 女 (Nữ, biểu nghĩa: phụ nữ) + 家 (Gia, biểu âm: cho âm jià). Chữ hình thanh — bộ nữ chỉ liên quan đến phụ nữ, 家 cho âm. Nghĩa gốc và hiện đại: (phụ nữ) lấy chồng, về nhà chồng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"giá\": 嫁 = 女(nữ) + 家(gia) — giá (lấy chồng) là cô gái 女 về nhà 家 mới, hai chữ ghép thành hành trình của người con gái. | Gương Hán-Việt | giá trong 出嫁 (xuất giá — lấy chồng), 嫁妝 (giá trang — của hồi môn). | Mở khoá kiến thức | Biết 嫁 mở khoá: 嫁妆 (của hồi môn), 出嫁 (lấy chồng), 嫁祸于人 (đổ lỗi cho người khác).", "Tự nguyên_Xie": "Wiktionary xác nhận: 嫁 là hình thanh, 女 (phụ nữ, biểu nghĩa) + 家 (nhà/gia đình, biểu âm). Hình ảnh trực tiếp: người phụ nữ 女 về nhà 家 (mới) — tức là lấy chồng, theo chồng về nhà chồng. Nghĩa gốc: phụ nữ lấy chồng. Mở rộng: chuyển nhượng trách nhiệm (嫁祸 — đổ lỗi cho người khác), của hồi môn (嫁妆). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "369.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Nữ (60) Gia (73)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Gia (số 228 - nhà) chỉ âm, chữ Nữ (số 86) chỉ ý. Người con gái đi lấy chồng và đến ở nhà chồng (xuất giá). Giải thích sự chuyển ý: Chữ Gia (nhà) chỉ âm, chữ Nữ (phụ nữ) chỉ ý. Người con gái (Nữ) lớn lên phải rời nhà mình để đi lấy chồng, coi nhà chồng là nhà (Gia) của mình (Giá). *(Biến âm Hán Việt: Trong Hán ngữ cổ, chữ Gia và chữ Giá có cách phát âm tương đồng hoặc chung gốc phụ âm. Quá trình Việt hóa đã làm âm đọc bị chênh lệch thành Gia và Giá).*", "Nghĩa Tiếng Việt_Xie": "lấy chồng; gieo rắc", "Hạng Tần Suất (Jun Da)": "2059.0", "Tần Suất % (Jun Da)": "97.3486023427", "GavinGrover_Once (Chiết tự trực tiếp)": "女 + 家", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰女家", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "家", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "女", "Unihan_Simplified (Chữ Giản thể)": "嫁", "Unihan_Traditional (Chữ Phồn thể)": "嫁", "Pinyin_Xie": "jià", "Âm Hán Việt_Xie": "giá", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ biểu thị việc người phụ nữ kết hôn hoặc hành vi đổ lỗi, gieo họa cho người khác. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | Từ đơn | Từ vựng HSK 5: kết hôn | / | jià | / | kết hôn | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Gia đình tôi | HSK | HSK 5 | · | Gia đình", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('催', '{"9000": "2060.0", "Chữ Trung Quốc": "催", "Bộ thủ & thành phần_Xie": "Bộ thủ | 人 | Số nét | 13 | nét | 亻 | nhân | biểu nghĩa | người | 崔 | thôi | biểu âm | cao chót vót (gần âm cuī) | 催 = 亻 (Nhân, biểu nghĩa: người) + 崔 (Thôi, biểu âm); chữ hình thanh. Người thúc giục người khác, gốc nghĩa ''thúc giục, giục giã''.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thôi\": 亻 (người) + 崔 (Thôi) — người đến thúc giục, đúng nghĩa ''thúc giục'' trong 催, 催促, 催眠 (thôi miên). | Gương Hán-Việt | ''thôi'' trong ''thôi thúc'', ''thôi miên'', ''cổ thôi'' | Mở khoá kiến thức | Nắm 催 mở khoá loạt từ HSK 5-7: 催, 催促, 催眠.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 催 là hình thanh: 人/亻 (người, biểu nghĩa) + 崔 (Thôi, biểu âm). Nghĩa gốc ''thúc giục, đốc thúc người khác làm gì'' giữ nguyên trong 催, 催促 (giục giã), 催眠 (thôi miên — đưa người vào giấc ngủ). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thúc giục; suy nghĩ", "Hạng Tần Suất (Jun Da)": "2060.0", "Tần Suất % (Jun Da)": "97.3519810839", "GavinGrover_Once (Chiết tự trực tiếp)": "亻 + 崔", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰亻崔", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "崔", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "亻", "Unihan_Simplified (Chữ Giản thể)": "催", "Unihan_Traditional (Chữ Phồn thể)": "催", "Pinyin_Xie": "cuī", "Âm Hán Việt_Xie": "thôi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước một động từ khác hoặc tân ngữ chỉ người để biểu thị sự hối thúc hành động. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | Từ đơn | Từ vựng HSK 5: thúc giục, thúc đẩy | / | cuī | / | thúc giục, thúc đẩy | Xuất hiện trong lộ trình | HSK | HSK 5 | · | Hành vi | New HSK | New HSK 7-9 | · | Ảnh hưởng và kiểm soát I", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('璇', '{"9000": "2061.0", "Chữ Trung Quốc": "璇", "Bộ thủ & thành phần_Xie": "Bộ thủ | 玉 | Số nét | 15 | nét | 王 | vương | biểu nghĩa | ngọc (bộ vương = bộ ngọc) | 旋 | hoàn | biểu âm | hoàn/tuyền (cho âm xuán) | 璇 = 玉/王(Vương/Ngọc, biểu nghĩa: ngọc đá) + 旋 (Hoàn, biểu âm); chữ hình thanh. Bộ ngọc chỉ đây là loại ngọc đá, hoàn cho âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tuyền\": ngọc (王/玉) xoay vòng (旋) — ngọc tuyền, viên ngọc đẹp như suối trong vắt xoáy tròn. | Gương Hán-Việt | tuyền (璇 – ngọc đẹp, tên người) | Mở khoá kiến thức | Biết 璇 mở khoá: 璇玑 (tuyền ki – vòng thiên văn cổ), tên người nữ như Lý Tuyền, Vương Tuyền.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary ghi 璇 là hình thanh: 玉 (ngọc, biểu nghĩa) + 旋 (biểu âm). Nghĩa gốc là loại ngọc đẹp, ngọc bích. Dùng trong tên người (Tuyền) và thiên văn cổ đại (璇玑 – vòng thiên văn). Chữ tương đối hiếm, chủ yếu gặp trong tên người phụ nữ. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ngọc tuyền", "Hạng Tần Suất (Jun Da)": "2061.0", "Tần Suất % (Jun Da)": "97.3553587916", "GavinGrover_Once (Chiết tự trực tiếp)": "王 + 旋", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰王旋", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "旋", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "王", "Unihan_Simplified (Chữ Giản thể)": "璇", "Unihan_Traditional (Chữ Phồn thể)": "璇", "Pinyin_Xie": "xuán", "Âm Hán Việt_Xie": "tuyền", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Chữ này thường dùng làm danh từ chỉ các loại ngọc đẹp hoặc làm tính từ trong tên người. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('翅', '{"9000": "2062.0", "Chữ Trung Quốc": "翅", "Bộ thủ & thành phần_Xie": "Bộ thủ | 羽 | Số nét | 10 | nét | 支 | chi | biểu âm | nhánh, chống đỡ; cho âm chì | 羽 | vũ | biểu nghĩa | lông vũ, cánh chim | 翅 = 支 (Chi, biểu âm: cho âm chì) + 羽 (Vũ, biểu nghĩa: lông vũ/cánh chim). Chữ hình thanh — bộ vũ chỉ liên quan đến cánh/lông chim, 支 cho âm. Nghĩa: cánh (chim, côn trùng), cánh tay gà/vịt (trong ẩm thực).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sí\": 翅 = 羽(lông vũ) + 支(chi) — sí (cánh) là nhánh chi 支 của lông vũ 羽, chiếc 翅膀 là cánh tung bay. | Gương Hán-Việt | sí trong 翅膀 (sí bàng — cánh), 魚翅 (ngư sí — vi cá mập). | Mở khoá kiến thức | Biết 翅 mở khoá: 翅膀 (cánh), 鸡翅 (cánh gà), 鱼翅 (vi cá mập), 插翅难逃 (thành ngữ: có cánh cũng khó thoát).", "Tự nguyên_Xie": "Wiktionary xác nhận: 翅 là hình thanh, 支 (biểu âm) + 羽 (lông vũ, biểu nghĩa). Nghĩa gốc: cánh chim — phần chi thể có lông vũ dùng để bay. Mở rộng: cánh côn trùng, cánh gà/vịt trong ẩm thực (翅膀 — cánh tay gà), cánh cá mập (鱼翅 — vi cá mập, dùng trong ẩm thực Trung Hoa). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "848.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Chi (847) Vũ (279)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Chi (số 847 - cành nhánh/chỉ âm) ở bên trái bộ Vũ (số 279 - lông vũ). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Chi chỉ âm, bộ Vũ chỉ ý. Sí/Súy là cánh chim, cánh của côn trùng.", "Nghĩa Tiếng Việt_Xie": "cánh chim, cánh côn trùng; vây cá", "Hạng Tần Suất (Jun Da)": "2062.0", "Tần Suất % (Jun Da)": "97.3587302978", "GavinGrover_Once (Chiết tự trực tiếp)": "支 + 羽", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴支羽", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "羽", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "支", "Unihan_Simplified (Chữ Giản thể)": "翅", "Unihan_Traditional (Chữ Phồn thể)": "翄", "Pinyin_Xie": "chì", "Âm Hán Việt_Xie": "sí", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng sau danh từ chỉ động vật hoặc đứng trước bộ phận để cấu tạo từ ghép. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('盒', '{"9000": "2063.0", "Chữ Trung Quốc": "盒", "Bộ thủ & thành phần_Xie": "Bộ thủ | 皿 | Số nét | 11 | nét | 合 | cáp | biểu âm | gợi âm hé, vốn nghĩa ''khép lại'' | 皿 | mãnh | biểu nghĩa | đồ đựng | 盒 = 合 (Cáp, biểu âm; gợi ''khép'') + 皿 (Mãnh, biểu nghĩa: đồ đựng); chữ hình thanh (ls=psc). Đồ đựng có nắp khép lại — ''cái hộp''.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hạp\" (cũng đọc ''hộp''): 合 (khép) + 皿 (đồ đựng) — đồ đựng khép kín, ấy là ''hộp''; nhớ 盒子 (hộp), 盒饭 (cơm hộp). | Gương Hán-Việt | ''hộp'' (biến âm Nôm) trong ''hộp đựng'', ''hộp quà'', ''hộp giấy'' | Mở khoá kiến thức | Biết 盒 là mở 盒子, 盒饭 — nhóm danh từ HSK 4-6.", "Tự nguyên_Xie": "Lục thư thông | Theo Wiktionary, 盒 là chữ hình thanh: 皿 (biểu nghĩa: đồ đựng) ghép với 合 (biểu âm; cũng gợi nghĩa ''khép lại''). Nghĩa: cái hộp có nắp đậy. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "570.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Hợp (569) Mãnh (98)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Hợp (số 569 - vừa vặn) ở trên chữ Mãnh (số 98 - đồ đựng/chậu). Đồ đựng mà có nắp đậy khít vừa vặn (Hợp). Giải thích sự chuyển ý: Chữ Hợp (phù hợp) chỉ âm, chữ Mãnh (đồ đựng) chỉ ý. Hạp là cái hộp, tráp có nắp đậy. (Biến âm Hán Việt: Hợp -> Hạp)", "Nghĩa Tiếng Việt_Xie": "cái hộp", "Hạng Tần Suất (Jun Da)": "2063.0", "Tần Suất % (Jun Da)": "97.3620925019", "GavinGrover_Once (Chiết tự trực tiếp)": "合 + 皿", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱合皿", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "合", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "皿", "Unihan_Simplified (Chữ Giản thể)": "盒", "Unihan_Traditional (Chữ Phồn thể)": "盒", "Pinyin_Xie": "hé", "Âm Hán Việt_Xie": "hạp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Lượng từ | 量词 | Thường dùng làm danh từ chỉ vật dụng đựng đồ hoặc làm lượng từ cho các vật đựng trong hộp. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Lượng từ | 量词 | Đứng giữa số từ (hoặc 这/那) và danh từ: 一杯茶, 这本书. Mỗi danh từ đi với lượng từ riêng; 个 là lượng từ dùng chung phổ biến nhất.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | hé | / | hộp | Xuất hiện trong lộ trình | New HSK | New HSK 5 | · | Công việc", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蛮', '{"9000": "2064.0", "Chữ Trung Quốc": "蛮", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 12 | nét | 𰁜 | biểu nghĩa | thành phần giản hóa từ 龻 — chỉ vùng đất xa xôi phương nam | 虫 | trùng | biểu nghĩa | sâu bọ, sinh vật — gợi vùng hoang dã có nhiều sâu bọ | 蛮 là dạng giản thể cực độ của 蠻. Chữ gốc 蠻 gồm thành phần phức tạp 龻 (biểu âm) và 虫 (biểu nghĩa: sâu bọ). Ý gốc là người man di phương nam sống trong vùng hoang vu nhiều sâu bọ. Giản thể đơn giản hóa toàn bộ phần trên thành 𰁜. chưa có nguồn học thuật rõ về dạng giản thể.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"man\": vùng đất sâu bọ (虫) hoang vu xa xôi — người man di thô lỗ, chưa khai hóa. | Gương Hán-Việt | man trong \"man di\" (người hoang dã), \"dã man\" (tàn bạo, hoang dã), \"Nam Man\" (người man di phương nam) | Mở khoá kiến thức | Biết 蛮 (man) mở khoá: 野蛮 (dã man, tàn bạo), 蛮横 (ngang ngược, hung hăng), 蛮力 (sức lực thô bạo).", "Tự nguyên_Xie": "Tiểu triện | 蛮 là dạng giản thể của 蠻. Wiktionary chú xem 蠻. 蠻 gồm phần âm phức tạp (龻) và 虫 (sâu bọ, biểu nghĩa vùng hoang dã). Nghĩa gốc là người man di phương nam (Man tộc); mở rộng thành hoang dã, thô lỗ, khá/rất (phương ngữ Ngô: 蛮好 = khá tốt). | Theo Wiktionary · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thô lỗ, ngang ngạnh; rất, lắm", "Hạng Tần Suất (Jun Da)": "2064.0", "Tần Suất % (Jun Da)": "97.3654531556", "GavinGrover_Once (Chiết tự trực tiếp)": "亦 + 虫", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱亦虫", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "亦", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蛮", "Unihan_Traditional (Chữ Phồn thể)": "蠻", "Pinyin_Xie": "mán", "Âm Hán Việt_Xie": "man", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Phó từ | 副词 | Thường làm phó từ đứng trước tính từ để biểu thị mức độ cao hoặc làm tính từ chỉ sự thô lỗ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Phó từ | 副词 | Bổ nghĩa cho động từ hoặc tính từ và luôn đứng TRƯỚC chúng — 都是, 很好. Không đứng sau như tiếng Việt và không bổ nghĩa cho danh từ.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | mán | / | rất | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Level và dergee", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('矣', '{"9000": "2065.0", "Chữ Trung Quốc": "矣", "Bộ thủ & thành phần_Xie": "Bộ thủ | 矢 | Số nét | 7 | nét | 厶 | mỗ | biểu âm | biểu âm (cho âm yǐ) | 矢 | thỉ | biểu nghĩa | mũi tên | 矣 = 㠯/以 (biểu âm, cho âm yǐ) + 矢 (Thỉ, biểu nghĩa: mũi tên); chữ hình thanh. Theo Wiktionary, 矢 cũng có thể là biểu âm. Dùng như trợ từ ngữ khí văn ngôn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hĩ\": mũi tên (矢) đã bắn ra — hĩ, rồi đó, đã xong rồi! Trợ từ văn ngôn kết thúc câu như dấu chấm than nhẹ. | Gương Hán-Việt | hĩ (矣 – trợ từ văn ngôn: rồi, vậy thôi) | Mở khoá kiến thức | Biết 矣 giúp đọc văn ngôn: 已矣 (đã hết rồi), 甚矣 (quá lắm thay!), câu kết thúc có thái độ trong Luận Ngữ.", "Tự nguyên_Xie": "Wiktionary ghi 矣 là hình thanh: 㠯/以 (biểu âm) + 矢 (mũi tên, biểu nghĩa hoặc biểu âm). Đây là hư từ ngữ khí văn ngôn, biểu thị sự hoàn thành, xác nhận (''rồi đó'', ''vậy thôi''). Không liên quan trực tiếp đến mũi tên trong dùng thực tế. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1445.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Tư (028) Thỉ (111)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Tư (số 028 - riêng tư/ 厶 /chỉ ý) ở trên chữ Thỉ (số 111 - mũi tên/ 矢 /chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Hĩ là một từ hư, thường dùng đặt ở cuối câu để làm trợ từ, biểu thị sự khẳng định, nghi vấn hoặc than thở (có nghĩa là: vậy, mất rồi).", "Nghĩa Tiếng Việt_Xie": "rồi (đặt ở cuối câu); quá; thay (biểu thị cảm thán)", "Hạng Tần Suất (Jun Da)": "2065.0", "Tần Suất % (Jun Da)": "97.3688070911", "GavinGrover_Once (Chiết tự trực tiếp)": "厶 + 矢", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱厶矢", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "矢", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "厶", "Unihan_Simplified (Chữ Giản thể)": "矣", "Unihan_Traditional (Chữ Phồn thể)": "矣", "Pinyin_Xie": "yǐ", "Âm Hán Việt_Xie": "hĩ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Trợ từ | 助词 | Thường đứng ở cuối câu trong văn ngôn để biểu thị ngữ khí khẳng định hoặc cảm thán. | Trợ từ | 助词 | Không mang nghĩa riêng, gắn vào câu để đánh dấu ngữ pháp hoặc ngữ khí: 的 / 地 / 得 (kết cấu), 了 / 着 / 过 (thể), 吗 / 呢 / 吧 (nghi vấn, ngữ khí).", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | yǐ | / | một hạt ''yi'' | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Từ chức năng và phụ từ II", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('潘', '{"9000": "2066.0", "Chữ Trung Quốc": "潘", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 15 | nét | 氵 | thuỷ | biểu nghĩa | nước | 番 | phan | biểu âm | phan (cho âm pān) | 潘 = 氵(Thuỷ, biểu nghĩa: nước) + 番 (Phan, biểu âm); chữ hình thanh. Bộ thuỷ chỉ đây liên quan đến nước, phan cho âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phan\": nước (氵) vo gạo phan (番) — nước võ gạo đục, họ Phan, Phan Thiết thân thương. | Gương Hán-Việt | Phan (họ người phổ biến ở Việt Nam và Trung Quốc) | Mở khoá kiến thức | Biết 潘 mở khoá: họ Phan (Phan Bội Châu, Phan Châu Trinh), 潘阳 (Phan Dương), nước vo gạo trong văn ngôn.", "Tự nguyên_Xie": "Wiktionary ghi 潘 là hình thanh: 水 (nước, biểu nghĩa) + 番 (biểu âm). Nghĩa gốc là nước vo gạo (nước đục sau khi rửa gạo). Cũng dùng làm họ phổ biến (họ Phan) và tên đất (Phiên Ngu, Panyu). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "họ Phan", "Hạng Tần Suất (Jun Da)": "2066.0", "Tần Suất % (Jun Da)": "97.3721543084", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 番", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵番", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "番", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "潘", "Unihan_Traditional (Chữ Phồn thể)": "潘", "Pinyin_Xie": "pān", "Âm Hán Việt_Xie": "phan", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chủ yếu dùng làm danh từ riêng chỉ họ người hoặc tên địa danh. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('歧', '{"9000": "2067.0", "Chữ Trung Quốc": "歧", "Bộ thủ & thành phần_Xie": "Bộ thủ | 止 | Số nét | 8 | nét | 止 | chỉ | biểu nghĩa | bước chân, con đường | 支 | chi | biểu âm | âm gốc qí — phân nhánh | 歧 = 止 (Chỉ, biểu nghĩa: bước chân, con đường) + 支 (Chi, biểu âm/biểu nghĩa: phân nhánh); chữ hình thanh hoặc hội ý. Ý gốc là con đường rẽ nhánh, ngã đường. chưa có nguồn học thuật rõ về cấu trúc chính xác.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"kỳ\": bước (止) phân chi (支) thành nhiều hướng — đường kỳ quặc rẽ nhánh, khó chọn. | Gương Hán-Việt | kỳ trong \"kỳ thị\" (phân biệt đối xử), \"kỳ lộ\" (con đường lạc) — ít dùng độc lập | Mở khoá kiến thức | Biết 歧 (kỳ) mở khoá: 歧视 (kỳ thị, phân biệt đối xử), 歧途 (đường lạc, đường lầm lỡ), 分歧 (bất đồng, phân kỳ).", "Tự nguyên_Xie": "歧 gồm 止 (bước chân, con đường) và 支 (phân nhánh, cho âm qí). Wiktionary chỉ có mục ngắn gọn {{Han etym}}. Nghĩa gốc là đường rẽ đôi, ngã tư; mở rộng thành phân kỳ, khác biệt, sai lạc (歧视: phân biệt đối xử, 歧途: đường lạc). chưa có nguồn học thuật rõ ràng. | Theo Wiktionary · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "khác nhau; không giống nhau; không đồng nhất", "Hạng Tần Suất (Jun Da)": "2067.0", "Tần Suất % (Jun Da)": "97.3754880893", "GavinGrover_Once (Chiết tự trực tiếp)": "止 + 支", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰止支", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "支", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "止", "Unihan_Simplified (Chữ Giản thể)": "歧", "Unihan_Traditional (Chữ Phồn thể)": "歧", "Pinyin_Xie": "qí", "Âm Hán Việt_Xie": "kì", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Thường làm tính từ đứng trước danh từ để chỉ sự phân nhánh hoặc bất đồng ý kiến. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('赐', '{"9000": "2068.0", "Chữ Trung Quốc": "赐", "Bộ thủ & thành phần_Xie": "Bộ thủ | 貝 | Số nét | 12 | nét | 贝 | bối | biểu nghĩa | tiền của, tài sản (vỏ sò cổ đại) | 易 | dịch | biểu âm | dịch (cho âm cì) | 赐 = 贝(Bối, biểu nghĩa: tiền của) + 易 (Dịch, biểu âm); chữ hình thanh (dạng giản thể của 賜). Bộ bối chỉ liên quan đến ban phát tài vật, dịch cho âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tứ\": ban phát (贝tiền) dễ dàng (易) — ân tứ, vua ban thưởng tứ cho công thần. | Gương Hán-Việt | ân tứ (恩赐 – ơn ban), tứ giáo (赐教 – ban phát chỉ dạy) | Mở khoá kiến thức | Biết 赐 mở khoá: 恩赐 (ân tứ – ơn ban), 赐教 (tứ giáo – chỉ dạy cho), 赐婚 (tứ hôn – vua ban hôn).", "Tự nguyên_Xie": "Wiktionary ghi 赐 là dạng giản thể của 賜 (thay 貝 bằng 贝). Đây là hình thanh: 貝 (tiền của, biểu nghĩa) + 易 (biểu âm). Nghĩa là ban cho, trao tặng (từ bề trên xuống bề dưới) — chỉ vua ban cho thần, người lớn ban cho người nhỏ. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ban ơn", "Hạng Tần Suất (Jun Da)": "2068.0", "Tần Suất % (Jun Da)": "97.3788115345", "GavinGrover_Once (Chiết tự trực tiếp)": "贝 + 易", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰贝易", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "易", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "贝", "Unihan_Simplified (Chữ Giản thể)": "赐", "Unihan_Traditional (Chữ Phồn thể)": "賜", "Pinyin_Xie": "cì", "Âm Hán Việt_Xie": "tứ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường làm động từ mang tân ngữ chỉ người nhận hoặc vật được ban tặng. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | cì | / | ban cho | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Thành công và thành tựu I", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鲍', '{"9000": "2069.0", "Chữ Trung Quốc": "鲍", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 13 | nét | 鱼 | ngư | biểu nghĩa | cá, hải sản | 包 | bao | biểu âm | bao (cho âm bào) | 鲍 = 鱼(Ngư, biểu nghĩa: cá/hải sản) + 包 (Bao, biểu âm); chữ hình thanh. Bộ ngư chỉ đây là loài hải sản, bao cho âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bào\": cá (鱼) gói bao (包) — bào ngư gói trong vỏ bào, Bào Thúc Nha bạn chí thiết của Quản Trọng. | Gương Hán-Việt | bào ngư (鲍鱼 – bào ngư/abalone), họ Bào | Mở khoá kiến thức | Biết 鲍 mở khoá: 鲍鱼 (bào ngư – abalone), 鲍叔牙 (Bào Thúc Nha – điển cố bạn bè trung thành).", "Tự nguyên_Xie": "Wiktionary ghi 鲍 là biến thể của 鰒 (ban đầu từ glyph khác). Bộ ngư (hải sản) + 包 (biểu âm). Nghĩa gốc là bào ngư (abalone), loài ốc biển quý. Cũng dùng làm họ người (Bào Thúc Nha — bạn của Quản Trọng). | Suy từ bộ phận cấu thành · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cá đã ướp", "Hạng Tần Suất (Jun Da)": "2069.0", "Tần Suất % (Jun Da)": "97.382127228", "GavinGrover_Once (Chiết tự trực tiếp)": "鱼 + 包", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰鱼包", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "包", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鱼", "Unihan_Simplified (Chữ Giản thể)": "鲍", "Unihan_Traditional (Chữ Phồn thể)": "鮑", "Pinyin_Xie": "bào", "Âm Hán Việt_Xie": "bào", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ chỉ các loại cá muối hoặc loài bào ngư trong ẩm thực. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('锅', '{"9000": "2070.0", "Chữ Trung Quốc": "锅", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 12 | nét | 钅 | kim | biểu nghĩa | kim loại (bộ kim giản thể) | 呙 | qua | biểu âm | miệng lệch; cho âm guō | 锅 = 钅(Kim, biểu nghĩa: kim loại) + 呙 (Qua, biểu âm: cho âm guō). Đây là giản thể của 鍋. Cấu trúc hình thanh — bộ kim chỉ vật dụng làm bằng kim loại, 呙 cho âm. Nghĩa: nồi (đặc biệt là nồi tròn bằng kim loại).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"oa\": 锅 = 钅(kim loại) + 呙(âm oa) — oa (nồi) là chiếc nồi kim loại, 火锅 là lẩu oa nước sôi sùng sục. | Gương Hán-Việt | oa trong 鍋爐 (oa lô — lò hơi/nồi hơi), 火鍋 (hoả oa — lẩu). | Mở khoá kiến thức | Biết 锅 mở khoá: 火锅 (lẩu), 电饭锅 (nồi cơm điện), 炒锅 (chảo xào), 一锅粥 (thành ngữ: mớ hỗn độn).", "Tự nguyên_Xie": "锅 là giản thể của 鍋. Chữ truyền thống 鍋 = 釒(kim loại, biểu nghĩa) + 咼 (biểu âm). Nghĩa gốc và hiện đại: nồi — dụng cụ nấu nướng bằng kim loại, thường tròn và sâu. Mở rộng: nồi lẩu (火锅), nồi cơm điện (电饭锅), và thành ngữ 一锅粥 (một nồi cháo = mớ hỗn độn). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái nồi", "Hạng Tần Suất (Jun Da)": "2070.0", "Tần Suất % (Jun Da)": "97.3854429214", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 呙", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅呙", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "呙", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "锅", "Unihan_Traditional (Chữ Phồn thể)": "鍋", "Pinyin_Xie": "guō", "Âm Hán Việt_Xie": "oa", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Lượng từ | 量词 | Thường làm danh từ chỉ dụng cụ nấu nướng hoặc làm lượng từ cho thức ăn đựng trong nồi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Lượng từ | 量词 | Đứng giữa số từ (hoặc 这/那) và danh từ: 一杯茶, 这本书. Mỗi danh từ đi với lượng từ riêng; 个 là lượng từ dùng chung phổ biến nhất.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | Từ đơn | Từ vựng HSK 5: nồi | / | guō | / | nồi | Xuất hiện trong lộ trình | HSK | HSK 5 | · | Thức ăn và đồ uống | New HSK | New HSK 5 | · | Thức ăn và đồ uống", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('廊', '{"9000": "2071.0", "Chữ Trung Quốc": "廊", "Bộ thủ & thành phần_Xie": "Bộ thủ | 广 | Số nét | 11 | nét | 广 | nghiễm | biểu nghĩa | mái hiên, nhà có mái che | 郎 | lang | biểu âm | chàng trai | 廊 là chữ hình thanh: 广 (Nghiễm) biểu nghĩa — mái hiên, công trình có mái che; 郎 (Lang) biểu âm. Hành lang là lối đi có mái che bên sườn tòa nhà.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lang\": mái 广 che lối đi, chàng 郎 đi dưới — hành lang cổ kính rộng dài. | Gương Hán-Việt | \"lang\" trong \"hành lang\", \"phòng lang\" | Mở khoá kiến thức | Biết 廊 (lang) mở khoá: 走廊 (hành lang), 画廊 (phòng tranh), 长廊 (hành lang dài).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 廊 là chữ hình thanh: 广 (mái hiên, biểu nghĩa) và 郎 (biểu âm). Có giả thuyết 良 là dạng gốc. Nghĩa cốt lõi là lối đi có mái che dọc theo công trình kiến trúc. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1329.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Nghiễm (053) Lang (1328)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Nghiễm (số 053 - mái hiên/ 广 /chỉ ý) che trên chữ Lang (số 1328 - quan lang/chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Lang chỉ âm, bộ Nghiễm chỉ ý. Lang là lối đi phụ ở dọc bên nhà có mái che (hành lang, hồi lang).", "Nghĩa Tiếng Việt_Xie": "mái hiên, hành lang", "Hạng Tần Suất (Jun Da)": "2071.0", "Tần Suất % (Jun Da)": "97.3887570645", "GavinGrover_Once (Chiết tự trực tiếp)": "广 + 郎", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴广郎", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "郎", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "广", "Unihan_Simplified (Chữ Giản thể)": "廊", "Unihan_Traditional (Chữ Phồn thể)": "廊", "Pinyin_Xie": "láng", "Âm Hán Việt_Xie": "lang", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ lối đi có mái che hoặc kết hợp tạo từ chỉ kiến trúc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('拆', '{"9000": "2072.0", "Chữ Trung Quốc": "拆", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 8 | nét | 扌 | thủ | biểu nghĩa | tay, hành động bằng tay | 斥 | xích | biểu âm | quở trách, đẩy ra; cho âm chāi | 拆 = 扌(Thủ, biểu nghĩa: tay) + 斥 (Xích, biểu âm: cho âm chāi). Chữ hình thanh — bộ thủ chỉ hành động tay tháo ra, phá ra, 斥 cho âm. Wiktionary ghi: 拆 vốn viết là 𢯪, sau đổi 土 thành 手 để nhấn mạnh hành động bằng tay. Nghĩa: tháo dỡ, phá dỡ, bóc ra.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sách\": 拆 = 扌(tay) + 斥(xích — đẩy ra) — sách (tháo) tay xích đẩy ra, như khi mở phong bì thư hay phá dỡ công trình. | Gương Hán-Việt | sách trong 拆除 (sách trừ — phá dỡ), 拆遷 (sách thiên — phá dỡ di dân). | Mở khoá kiến thức | Biết 拆 mở khoá: 拆除 (phá dỡ), 拆迁 (phá dỡ di dân), 拆开 (tháo ra, mở ra), 拆信 (bóc thư).", "Tự nguyên_Xie": "Wiktionary xác nhận: 拆 là hình thanh, 手 (tay, biểu nghĩa, viết dạng 扌) + 斥 (biểu âm). Dạng gốc 𢯪 dùng 土 thay 手; được thay bằng 手 để làm rõ là hành động tay. Nghĩa gốc: tháo ra, bóc ra. Mở rộng: phá dỡ công trình (拆除), tháo gỡ (拆开), di dân tái định cư (拆迁). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nứt ra; huỷ đi", "Hạng Tần Suất (Jun Da)": "2072.0", "Tần Suất % (Jun Da)": "97.3920706907", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 斥", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌斥", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "斥", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "拆", "Unihan_Traditional (Chữ Phồn thể)": "拆", "Pinyin_Xie": "chāi", "Âm Hán Việt_Xie": "sách", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước danh từ chỉ công trình, thư từ hoặc máy móc để biểu thị hành động tháo dỡ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | Từ đơn | Từ vựng HSK 5: tháo gỡ | / | chāi | / | tháo ra | / | chāi | / | tháo gỡ | Xuất hiện trong lộ trình | New HSK | New HSK 5 | · | Động từ | HSK | HSK 5 | · | Động từ hàng ngày", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('灌', '{"9000": "2073.0", "Chữ Trung Quốc": "灌", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 20 | nét | 氵 | thuỷ | biểu nghĩa | nước | 雚 | (không rõ) | biểu âm | loài chim lội nước — cho âm đọc | 灌 là chữ hình thanh: 氵 (Thuỷ) biểu nghĩa — liên quan đến nước; 雚 biểu âm (gồm 艹 thảo, 吅 tụng, 隹 chuy). Nghĩa gốc là đổ nước, tưới tắm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quán\": ba chấm 氵 nước + chim 雚 lội đồng — quán tưới nước như chim chân ướt. | Gương Hán-Việt | \"quán\" trong \"quán thủy\", \"quán tưới\" | Mở khoá kiến thức | Biết 灌 (quán) mở khoá: 灌溉 (tưới tiêu), 灌输 (truyền đạt), 灌木 (cây bụi).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 灌 là chữ hình thanh: 水 (nước, biểu nghĩa) + 雚 (biểu âm). Nghĩa gốc là rót đầy nước, tưới tiêu. Mở rộng sang: thu âm (灌唱片), cài đặt phần mềm (tiếng Đài Loan). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1400.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thủy (082) Quán (718)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Thủy (số 082 - nước/ 氵/chỉ ý) ở bên trái chữ Quán (số 718 - con chim cò/ 雚 /chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Quán chỉ âm, bộ Thủy chỉ ý. Quán là lấy nước rót xuống, tưới nước lên cây (tưới quán, quán điền).", "Nghĩa Tiếng Việt_Xie": "đổ nước; tưới cây", "Hạng Tần Suất (Jun Da)": "2073.0", "Tần Suất % (Jun Da)": "97.395379666", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 雚", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵雚", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "雚", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "灌", "Unihan_Traditional (Chữ Phồn thể)": "灌", "Pinyin_Xie": "guàn", "Âm Hán Việt_Xie": "quán", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này thường làm động từ đứng trước danh từ chỉ cây cối hoặc đồng ruộng để biểu thị hành động tưới tiêu. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | guàn | / | đổ | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Nông nghiệp", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('勉', '{"9000": "2074.0", "Chữ Trung Quốc": "勉", "Bộ thủ & thành phần_Xie": "Bộ thủ | 力 | Số nét | 9 | nét | 免 | miễn | biểu âm | tránh, miễn | 力 | lực | biểu nghĩa | sức mạnh | 勉 là chữ hình thanh: 力 (Lực) biểu nghĩa — sức mạnh; 免 (Miễn) biểu âm. Ý nghĩa: dùng sức mạnh vượt qua giới hạn, cố gắng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"miễn\": miễn 免 khó khăn bằng 力 sức lực — cố gắng vượt qua chứ không bỏ cuộc. | Gương Hán-Việt | \"miễn\" trong \"miễn cưỡng\", \"nỗ lực\" | Mở khoá kiến thức | Biết 勉 (miễn) mở khoá: 勉励 (khuyến khích), 勉强 (miễn cưỡng), 自勉 (tự nhắc nhở).", "Tự nguyên_Xie": "Theo Wiktionary, 勉 là hình thanh: 免 (biểu âm) + 力 (sức mạnh, biểu nghĩa) — gắng sức để vượt qua. Mở rộng: khuyến khích (勉励), làm miễn cưỡng (勉强). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cố sức, cố gắng", "Hạng Tần Suất (Jun Da)": "2074.0", "Tần Suất % (Jun Da)": "97.3986860573", "GavinGrover_Once (Chiết tự trực tiếp)": "免 + 力", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴免力", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "免", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "力", "Unihan_Simplified (Chữ Giản thể)": "勉", "Unihan_Traditional (Chữ Phồn thể)": "勉", "Pinyin_Xie": "miǎn", "Âm Hán Việt_Xie": "miễn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Thường kết hợp với các từ khác để tạo thành động từ hoặc tính từ chỉ sự cố gắng, gượng ép. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('盲', '{"9000": "2075.0", "Chữ Trung Quốc": "盲", "Bộ thủ & thành phần_Xie": "Bộ thủ | 目 | Số nét | 8 | nét | 亡 | vong | biểu âm | mất, chết | 目 | mục | biểu nghĩa | mắt | 盲 là chữ hình thanh: 目 (Mục) biểu nghĩa — con mắt; 亡 (Vong) biểu âm. Mắt bị mất — nghĩa là mù.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"manh\": mắt 目 bị vong 亡 mất — mắt đã mất rồi, thành mù manh. | Gương Hán-Việt | \"manh\" trong \"manh mục\" (mù quáng), \"văn manh\" (mù chữ) | Mở khoá kiến thức | Biết 盲 (manh) mở khoá: 盲目 (mù quáng), 盲人 (người mù), 文盲 (mù chữ), 色盲 (mù màu).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 盲 là hình thanh: 亡 (biểu âm) + 目 (mắt, biểu nghĩa). Nghĩa đen: mắt mất chức năng nhìn. Mở rộng: mù quáng (盲目), mù chữ (文盲). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mù loà", "Hạng Tần Suất (Jun Da)": "2075.0", "Tần Suất % (Jun Da)": "97.4019908982", "GavinGrover_Once (Chiết tự trực tiếp)": "亡 + 目", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱亡目", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "亡", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "目", "Unihan_Simplified (Chữ Giản thể)": "盲", "Unihan_Traditional (Chữ Phồn thể)": "盲", "Pinyin_Xie": "máng", "Âm Hán Việt_Xie": "manh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Thường làm định ngữ đứng trước danh từ để chỉ người hoặc trạng thái mất thị lực, thiếu hiểu biết. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('宰', '{"9000": "2076.0", "Chữ Trung Quốc": "宰", "Bộ thủ & thành phần_Xie": "Bộ thủ | 宀 | Số nét | 10 | nét | 宀 | miên | biểu nghĩa | mái nhà, công sở | 辛 | tân | biểu hình | công cụ lưỡi dao (dạng xưa là 乂/䇂) | 宰 là chữ hội ý: 宀 (Miên) biểu nhà cầm quyền + 乂/䇂 (công cụ quản lý, nay biến thành 辛) — nơi có quyền lực điều hành. Nghĩa gốc: quan cai trị; mở rộng sang mổ thịt.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tể\": dưới mái 宀 có lưỡi dao 辛 — tể tướng vừa cai trị vừa có quyền sinh sát. | Gương Hán-Việt | \"tể\" trong \"tể tướng\" (宰相) | Mở khoá kiến thức | Biết 宰 (tể) mở khoá: 宰相 (tể tướng), 主宰 (thống trị), 宰杀 (giết mổ).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 宰 là hội ý: 宀 (nhà) + 乂 (quản lý) — nhà cầm quyền. Trong giáp cốt văn, 乂 hình tương tự 䇂; về sau biến thành 辛 trong dạng hiện đại. Nghĩa gốc: quan cai trị, sau mở rộng sang giết mổ. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chúa tể, người đứng đầu; một chức quan thời phong kiến; làm thịt, mổ thịt, giết thịt", "Hạng Tần Suất (Jun Da)": "2076.0", "Tần Suất % (Jun Da)": "97.4052931552", "GavinGrover_Once (Chiết tự trực tiếp)": "宀 + 辛", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱宀辛", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "辛", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "宀", "Unihan_Simplified (Chữ Giản thể)": "宰", "Unihan_Traditional (Chữ Phồn thể)": "宰", "Pinyin_Xie": "zǎi", "Âm Hán Việt_Xie": "tể", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Làm động từ mang tân ngữ chỉ động vật bị mổ thịt hoặc làm danh từ chỉ chức quan đứng đầu thời xưa. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | zǎi | / | giết mổ | / | zǎi | / | ép khách hàng | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Kinh tế và Tài chính II | New HSK 7-9 | · | Nông nghiệp | HSK | HSK 6 | · | Nông nghiệp", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('佐', '{"9000": "2077.0", "Chữ Trung Quốc": "佐", "Bộ thủ & thành phần_Xie": "Bộ thủ | 人 | Số nét | 7 | nét | 亻 | nhân | biểu nghĩa | người | 左 | tả | biểu âm | trái (cho âm zuǒ) | 佐 = 亻(Nhân, biểu nghĩa: người) + 左 (Tả, biểu âm); chữ hình thanh. Bộ nhân chỉ đây là vai trò của người, tả cho âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tá\": người (亻) bên trái (左) — người phụ tá đứng bên trái, phò tá chủ nhân, tá điền, tá lý. | Gương Hán-Việt | phụ tá (辅佐 – phò trợ), tá lý (佐理 – trợ lý) | Mở khoá kiến thức | Biết 佐 mở khoá: 辅佐 (phụ tá – phò tá), 佐料 (tá liệu – gia vị), 佐证 (tá chứng – bằng chứng phụ).", "Tự nguyên_Xie": "Wiktionary ghi 佐 là hình thanh: 人 (người, biểu nghĩa) + 左 (biểu âm). Nghĩa gốc là phụ tá, giúp đỡ — người đứng bên trái phò tá. Trong phân công cổ đại, bên trái (左) là vị trí phụ tá của cấp phó. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "353.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Nhân (42) Tả (168)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Tả (số 168 - bên trái) chỉ âm, chữ Nhân (số 12 - nhân đứng) chỉ ý. Tá là người giúp đỡ, trợ giúp (như phụ tá). Giải thích sự chuyển ý: Chữ Tả (bên trái) chỉ âm, chữ Nhân (người) chỉ ý. Người (Nhân) luôn đứng bên trái (Tả) để sẵn sàng giúp đỡ, hỗ trợ gọi là người phụ tá (Tá). *(Biến âm Hán Việt: Trong Hán ngữ cổ, chữ Tả và chữ Tá có cách phát âm tương đồng hoặc chung gốc phụ âm. Quá trình Việt hóa đã làm âm đọc bị chênh lệch thành Tả và Tá).*", "Nghĩa Tiếng Việt_Xie": "giúp đỡ", "Hạng Tần Suất (Jun Da)": "2077.0", "Tần Suất % (Jun Da)": "97.4085892108", "GavinGrover_Once (Chiết tự trực tiếp)": "亻 + 左", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰亻左", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "左", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "亻", "Unihan_Simplified (Chữ Giản thể)": "佐", "Unihan_Traditional (Chữ Phồn thể)": "佐", "Pinyin_Xie": "zuǒ", "Âm Hán Việt_Xie": "tá", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường dùng làm động từ biểu thị sự trợ giúp hoặc làm danh từ chỉ người trợ thủ, phụ tá. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('啥', '{"9000": "2078.0", "Chữ Trung Quốc": "啥", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 11 | nét | 口 | khẩu | biểu nghĩa | miệng, lời nói | 舍 | xá | biểu âm | nhà ở, bỏ lại | 啥 là chữ hình thanh: 口 (Khẩu) biểu nghĩa — lời nói thốt ra; 舍 (Xá) biểu âm. Là từ khẩu ngữ phương bắc nghĩa là \"gì\".", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"xá\": miệng 口 hỏi xá (shá) — khẩu ngữ Bắc Kinh hỏi \"啥\" tức là gì vậy? | Gương Hán-Việt | \"xá\" ít dùng trong tiếng Việt Hán; 啥 chủ yếu là khẩu ngữ Trung Quốc | Mở khoá kiến thức | Biết 啥 (xá) mở khoá khẩu ngữ: 啥事 (chuyện gì), 干啥 (làm gì), 啥意思 (ý gì).", "Tự nguyên_Xie": "啥 không có glyph cổ trong Wiktionary. Là chữ tạo muộn dạng hình thanh: 口 (miệng) + 舍 (biểu âm). Xuất hiện trong văn nói và văn xuôi hiện đại, là dạng thông tục của 什么. Chưa có nguồn học thuật về glyph nguồn gốc. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "gì, nấy, nào", "Hạng Tần Suất (Jun Da)": "2078.0", "Tần Suất % (Jun Da)": "97.4118609775", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 舍", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口舍", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "舍", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "啥", "Unihan_Traditional (Chữ Phồn thể)": "啥", "Pinyin_Xie": "shà", "Âm Hán Việt_Xie": "xá", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Đại từ | 代词 | Dùng làm đại từ nghi vấn trong khẩu ngữ, thường đứng sau động từ làm tân ngữ hoặc đứng trước danh từ làm định ngữ. | Đại từ | 代词 | Thay cho người hoặc vật đã nhắc tới (我, 这, 谁). Dùng đúng ở vị trí của danh từ. Chỉ người thì thêm 们 để thành số nhiều: 我们.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | shá | / | cái gì? | Xuất hiện trong lộ trình | HSK | HSK 6 | · | Các từ chức năng và bổ trợ", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('胀', '{"9000": "2079.0", "Chữ Trung Quốc": "胀", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 8 | nét | 月 | nguyệt | biểu nghĩa | thịt, cơ thể (bộ 肉 viết thành 月) | 长 | trường | biểu âm | dài, lớn lên | 胀 là chữ hình thanh: 月/肉 (Nhục) biểu nghĩa — thân thể; 长 (Trường) biểu âm. Nghĩa gốc: thân thể phình ra, trương phồng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trướng\": thịt 月 bị trương 长 lên — bụng trướng phồng, căng tức. | Gương Hán-Việt | \"trướng\" trong \"bụng trướng\", \"trướng phong\" | Mở khoá kiến thức | Biết 胀 (trướng) mở khoá: 膨胀 (phình ra/lạm phát), 通货膨胀 (lạm phát tiền tệ), 肿胀 (sưng phồng).", "Tự nguyên_Xie": "Theo Wiktionary, 胀 (phồn thể 脹) là hình thanh: 肉 (thịt, biểu nghĩa) + 長 (biểu âm). Nghĩa gốc là trương phồng do tích khí/chất lỏng. Mở rộng: giá tăng, nước dâng. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "phình ra, trương ra; tăng giá; nước dâng lên", "Hạng Tần Suất (Jun Da)": "2079.0", "Tần Suất % (Jun Da)": "97.415130677", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 长", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月长", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "长", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "胀", "Unihan_Traditional (Chữ Phồn thể)": "脹", "Pinyin_Xie": "zhàng", "Âm Hán Việt_Xie": "trướng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Thường làm động từ hoặc tính từ miêu tả trạng thái thể tích tăng lên do chứa nhiều khí hoặc nước. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | zhàng | / | chướng bụng | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Bệnh II", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('扯', '{"9000": "2080.0", "Chữ Trung Quốc": "扯", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 7 | nét | 扌 | thủ | biểu nghĩa | tay | 止 | chỉ | biểu âm | dừng lại, bước chân | 扯 là chữ hình thanh (gốc là 撦): 扌 (Thủ) biểu nghĩa — tay; 止 (Chỉ) biểu âm. Nghĩa gốc: kéo giật bằng tay, xé rách.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"xả\": tay 扌 giật 止 dừng — xả tay kéo giật xé toạc. | Gương Hán-Việt | \"xả\" ít dùng độc lập; xuất hiện trong từ ghép khẩu ngữ | Mở khoá kiến thức | Biết 扯 (xả) mở khoá: 牵扯 (liên quan), 扯淡 (nói nhảm), 扯皮 (cãi nhau vô ích).", "Tự nguyên_Xie": "Theo Wiktionary, 扯 nguyên viết là 撦, hình thanh: 手 (tay, biểu nghĩa) + 止 (biểu âm). Nghĩa là kéo giật bằng tay, xé rách. Mở rộng: nói linh tinh (扯淡), kéo liên quan (牵扯). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "xé ra", "Hạng Tần Suất (Jun Da)": "2080.0", "Tần Suất % (Jun Da)": "97.418399343", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 止", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌止", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "止", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "扯", "Unihan_Traditional (Chữ Phồn thể)": "扯", "Pinyin_Xie": "chě", "Âm Hán Việt_Xie": "xả", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ biểu thị hành động kéo, xé vật lý hoặc nói chuyện lan man không vào chủ đề. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | chě | / | xé | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Động từ tôi", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('禧', '{"9000": "2081.0", "Chữ Trung Quốc": "禧", "Bộ thủ & thành phần_Xie": "Bộ thủ | 示 | Số nét | 16 | nét | 礻 | thị | biểu nghĩa | thần linh, lễ nghi | 喜 | hỷ | biểu âm | hỷ (cho âm xǐ) | 禧 = 礻(Thị, biểu nghĩa: thần linh, lễ) + 喜 (Hỷ, biểu âm); chữ hình thanh. Bộ thị chỉ đây là phúc lành từ thần linh, hỷ cho âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hỷ\": thần (礻) mang hỷ sự (喜) — hỷ khánh, tân hỷ, phúc lành thần linh ban cho năm mới. | Gương Hán-Việt | tân hỷ (新禧 – năm mới an lành), hỷ niên (禧年 – năm hỷ) | Mở khoá kiến thức | Biết 禧 mở khoá: 新禧 (tân hỷ – năm mới an lành), 恭贺新禧 (kính chúc năm mới), 慈禧 (Từ Hi – Thái Hậu nhà Thanh).", "Tự nguyên_Xie": "Wiktionary ghi 禧 là hình thanh: 示 (thần linh/lễ nghi, biểu nghĩa) + 喜 (biểu âm). Nghĩa gốc là may mắn, phúc lành, điều tốt đẹp từ thần linh ban phát. Dùng trong chúc tết (新禧 – năm mới an lành), tên người, và danh hiệu như Từ Hi Thái Hậu (慈禧). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "hạnh phúc; may mắn", "Hạng Tần Suất (Jun Da)": "2081.0", "Tần Suất % (Jun Da)": "97.4216592236", "GavinGrover_Once (Chiết tự trực tiếp)": "礻 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰礻", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "禧", "Unihan_Traditional (Chữ Phồn thể)": "禧", "Pinyin_Xie": "xǐ", "Âm Hán Việt_Xie": "hi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong các từ ghép chúc mừng năm mới hoặc dịp lễ hội mang ý nghĩa may mắn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('辽', '{"9000": "2082.0", "Chữ Trung Quốc": "辽", "Bộ thủ & thành phần_Xie": "Bộ thủ | 辵 | Số nét | 5 | nét | 辶 | sước | biểu nghĩa | đi, di chuyển | 了 | liễu | biểu âm | xong, rõ | 辽 là giản thể của 遼, rút gọn 尞 thành 了. 辶 (Sước) biểu nghĩa — đi, khoảng cách; 了 (Liễu) biểu âm. Nghĩa: xa xôi, rộng lớn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"liêu\": bước chân 辶 đi liễu 了 mãi không thấy — đường xa liêu xiêu, mênh mông. | Gương Hán-Việt | \"liêu\" trong \"Liêu Ninh\" (辽宁), \"liêu khoát\" (辽阔) | Mở khoá kiến thức | Biết 辽 (liêu) mở khoá: 辽阔 (rộng lớn bao la), 辽宁 (tỉnh Liêu Ninh), 辽远 (xa xôi).", "Tự nguyên_Xie": "Tiểu triện | 辽 là giản thể của 遼 (Liêu). Wiktionary ghi dạng giản thể rút gọn 尞 thành 了. 遼 nguyên là hình thanh: 辵 (đi, biểu nghĩa) + 尞 (biểu âm). Nghĩa gốc: xa xôi mênh mông. Cũng là tên triều Liêu và tỉnh Liêu Ninh. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "xa xôi", "Hạng Tần Suất (Jun Da)": "2082.0", "Tần Suất % (Jun Da)": "97.42491497", "GavinGrover_Once (Chiết tự trực tiếp)": "辶 + 了", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴辶了", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "了", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "辶", "Unihan_Simplified (Chữ Giản thể)": "辽", "Unihan_Traditional (Chữ Phồn thể)": "遼", "Pinyin_Xie": "liáo", "Âm Hán Việt_Xie": "liêu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường làm tính từ đứng trước danh từ hoặc kết hợp trong từ ghép để miêu tả không gian bao la, xa xăm. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('抹', '{"9000": "2083.0", "Chữ Trung Quốc": "抹", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 8 | nét | 扌 | thủ | biểu nghĩa | tay | 末 | mạt | biểu âm | ngọn cây, cuối | 抹 là chữ hình thanh: 扌 (Thủ) biểu nghĩa — tay; 末 (Mạt) biểu âm. Nghĩa gốc: dùng tay xoa bôi đều lên bề mặt.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mạt\": tay 扌 xoa đến mạt 末 ngọn — bôi từ đầu đến cuối, trát đều. | Gương Hán-Việt | \"mạt\" trong \"mạt sát\" (抹杀 — xoá bỏ) | Mở khoá kiến thức | Biết 抹 (mạt) mở khoá: 抹杀 (xoá bỏ hoàn toàn), 涂抹 (bôi phết), 抹黑 (bôi nhọ).", "Tự nguyên_Xie": "Theo Wiktionary, 抹 là hình thanh: 手/扌 (tay, biểu nghĩa) + 末 (biểu âm). Nghĩa gốc là xoa bôi bằng tay. Nhiều cách đọc: mǒ (bôi, xoá), mā (lau), mò (góc đường). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bôi, xoa; trát; vòng qua", "Hạng Tần Suất (Jun Da)": "2083.0", "Tần Suất % (Jun Da)": "97.4281701995", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 末", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌末", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "末", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "抹", "Unihan_Traditional (Chữ Phồn thể)": "抹", "Pinyin_Xie": "mǒ", "Âm Hán Việt_Xie": "mạt", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đi kèm tân ngữ chỉ chất lỏng, bụi bẩn hoặc bề mặt cần lau chùi, tô vẽ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('筒', '{"9000": "2084.0", "Chữ Trung Quốc": "筒", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 12 | nét | 竹 | trúc | biểu nghĩa | tre | 同 | đồng | biểu âm | cùng nhau | 筒 là chữ hình thanh: 竹/𥫗 (Trúc) biểu nghĩa — tre; 同 (Đồng) biểu âm. Nghĩa gốc: đoạn tre cắt thành ống rỗng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đồng\": tre 竹 rỗng đồng 同 đều — những đốt tre rỗng thành ống đồng đều. | Gương Hán-Việt | \"đồng\" trong \"ống đồng\" | Mở khoá kiến thức | Biết 筒 (đồng) mở khoá: 话筒 (micro), 竹筒 (ống tre), 邮筒 (thùng thư hình ống).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 筒 là hình thanh: 竹 (tre, biểu nghĩa) + 同 (biểu âm). Nghĩa gốc là đoạn tre rỗng hình ống. Mở rộng: bất kỳ vật hình ống. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ống tre; ống", "Hạng Tần Suất (Jun Da)": "2084.0", "Tần Suất % (Jun Da)": "97.4314238788", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 同", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮同", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "同", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "筒", "Unihan_Traditional (Chữ Phồn thể)": "筒", "Pinyin_Xie": "tǒng", "Âm Hán Việt_Xie": "đồng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Lượng từ | 量词 | Thường làm danh từ chỉ các vật dụng hình ống hoặc làm lượng từ cho vật chứa trong ống. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Lượng từ | 量词 | Đứng giữa số từ (hoặc 这/那) và danh từ: 一杯茶, 这本书. Mỗi danh từ đi với lượng từ riêng; 个 là lượng từ dùng chung phổ biến nhất.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | tǒng | / | ống | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Tính chất vật lý", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('棋', '{"9000": "2085.0", "Chữ Trung Quốc": "棋", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 12 | nét | 木 | mộc | biểu nghĩa | gỗ | 其 | kỳ | biểu âm | cái đó (gần âm qí) | 棋 = 木 (Mộc, biểu nghĩa: gỗ) + 其 (Kỳ, biểu âm); chữ hình thanh. Quân cờ vốn được làm bằng gỗ, gốc nghĩa ''quân cờ, cờ''.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"kỳ\": 木 (gỗ) + 其 (Kỳ) — quân cờ bằng gỗ, đúng nghĩa ''cờ, quân cờ'' trong 象棋 (cờ tướng), 下棋 (chơi cờ), 棋子 (quân cờ). | Gương Hán-Việt | ''kỳ'' trong ''cờ kỳ'' (kỳ thủ), ''cờ vây — kỳ'' | Mở khoá kiến thức | Nắm 棋 mở khoá loạt từ HSK 5-7: 棋, 象棋, 下棋, 棋子.", "Tự nguyên_Xie": "Giáp cốt văn | Tiểu triện | Theo Wiktionary, 棋 là hình thanh: 木 (gỗ, biểu nghĩa — quân cờ gỗ) + 其 (Kỳ, biểu âm). Nghĩa gốc ''quân cờ, bàn cờ'', dùng cho mọi loại cờ trò chơi (không bao gồm bài). Phổ biến trong 象棋 (cờ tướng), 围棋 (cờ vây), 下棋 (chơi cờ). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "quân cờ; con cờ", "Hạng Tần Suất (Jun Da)": "2085.0", "Tần Suất % (Jun Da)": "97.4346765244", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 其", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木其", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "其", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "棋", "Unihan_Traditional (Chữ Phồn thể)": "棊", "Pinyin_Xie": "qí", "Âm Hán Việt_Xie": "kỳ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng sau động từ chỉ hoạt động chơi cờ như hạ hoặc đánh. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | qí | / | cờ | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Giải trí và thói quen II", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('裤', '{"9000": "2086.0", "Chữ Trung Quốc": "裤", "Bộ thủ & thành phần_Xie": "Bộ thủ | 衣 | Số nét | 12 | nét | 衤 | y | biểu nghĩa | quần áo (bộ y) | 库 | khố | biểu âm | kho (giản hoá từ 庫) | 裤 = 衤 (Y, biểu nghĩa: quần áo) + 库 (Khố, biểu âm; giản hoá từ 庫). Đây là dạng giản thể của 褲: chữ hình thanh — quần dài/quần đùi. 库 cho âm ''ku''.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt ''Khố'' nghĩa là ''cái khố, cái quần''. Nhớ: 衤 (y phục) bên trái + 库 (kho) bên phải — y phục cất trong kho, đó là ''khố'' (quần). | Gương Hán-Việt | Chữ 裤 (Khố) trong tiếng Việt ''khố'' là loại quần đơn giản của đàn ông xưa; cùng âm với 库 (khố — kho) nhưng khác nghĩa. | Mở khoá kiến thức | Nắm 裤 mở khoá nhóm từ về quần áo: 裤子, 短裤, 牛仔裤, 内裤.", "Tự nguyên_Xie": "Theo Wiktionary, 裤 là dạng giản thể của 褲, đổi 庫 → 库. Bản phồn 褲 là chữ hình thanh: {{Han compound|衣|庫|ls=psc|c1=s|c2=p|t1=clothing}} — 衤 (quần áo) biểu nghĩa, 庫 biểu âm. Vốn được viết là 袴 hoặc 絝, đều là chữ hình thanh chỉ ''quần''. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái khố; cái quần đùi", "Hạng Tần Suất (Jun Da)": "2086.0", "Tần Suất % (Jun Da)": "97.4379229686", "GavinGrover_Once (Chiết tự trực tiếp)": "衤 + 库", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰衤库", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "库", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "衤", "Unihan_Simplified (Chữ Giản thể)": "裤", "Unihan_Traditional (Chữ Phồn thể)": "袴", "Pinyin_Xie": "kù", "Âm Hán Việt_Xie": "khố", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường kết hợp với lượng từ điều để chỉ chiếc quần và đứng sau động từ mặc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('唉', '{"9000": "2087.0", "Chữ Trung Quốc": "唉", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 10 | nét | 口 | khẩu | biểu nghĩa | miệng, âm thanh thốt ra | 矣 | hĩ | biểu âm | trợ từ kết thúc câu (văn cổ); cho âm āi/ài | 唉 = 口 (Khẩu, biểu nghĩa: miệng) + 矣 (Hĩ, biểu âm: cho âm āi/ài). Chữ hình thanh — bộ khẩu chỉ âm thanh thốt ra từ miệng, 矣 cho âm. Nghĩa: thán từ biểu đạt sự đồng ý, thở dài, than thở.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ai\": 唉 = 口(miệng) + 矣(hĩ — thán từ cổ) — ai (than ôi!) là tiếng thốt ra từ miệng khi buồn hay thở dài. | Gương Hán-Việt | ai trong thành ngữ và văn học: 唉聲嘆氣 (ai thanh thán khí — than thở rên rỉ). | Mở khoá kiến thức | Biết 唉 mở khoá: dùng trong hội thoại hàng ngày như 唉，算了 (thôi vậy), 唉声叹气 (than thở rên rỉ), 唉哟 (ôi trời).", "Tự nguyên_Xie": "Wiktionary xác nhận: 唉 là hình thanh, 口 (miệng, biểu nghĩa) + 矣 (biểu âm). Chữ dùng để ghi âm thán từ ''ai'' trong tiếng Hán. Hai phát âm chính: (1) āi — đồng ý, vâng/ừ; (2) ài — thở dài, than thở (唉声叹气 — than thở sầu muộn). Wiktionary ghi cả nguồn gốc cổ (oc, mc). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ừ (thán từ); hừ (thán từ); ôi, ối (thán từ)", "Hạng Tần Suất (Jun Da)": "2087.0", "Tần Suất % (Jun Da)": "97.4411626946", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 矣", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口矣", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "矣", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "唉", "Unihan_Traditional (Chữ Phồn thể)": "唉", "Pinyin_Xie": "āi", "Âm Hán Việt_Xie": "ai", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Thán từ | 叹词 | Thường đứng ở đầu câu để biểu thị sự đồng ý, thở dài hoặc than vãn. | Thán từ | 叹词 | Bộc lộ cảm xúc hoặc dùng để gọi đáp: 啊, 哦, 喂. Đứng tách riêng ở đầu câu, không làm thành phần câu.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | Từ đơn | Từ vựng HSK 5: ai | / | ài | / | ai | Xuất hiện trong lộ trình | HSK | HSK 5 | · | Các từ chức năng và bổ trợ | New HSK | New HSK 7-9 | · | Từ chức năng và phụ từ I", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('朴', '{"9000": "2088.0", "Chữ Trung Quốc": "朴", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 6 | nét | 木 | mộc | biểu nghĩa | gỗ, cây | 卜 | bốc | biểu âm | bói toán | 朴 là chữ hình thanh: 木 (Mộc) biểu nghĩa — gỗ, chất liệu tự nhiên; 卜 (Bốc) biểu âm. Nghĩa gốc: cây phác, vỏ làm thuốc. Năm 1956 dùng làm giản thể của 樸 (chất phác).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phác\": gỗ 木 thô ráp 卜 — phác mộc, giản dị chưa qua chạm trổ. | Gương Hán-Việt | \"phác\" trong \"chất phác\" (朴实), \"phác thực\" | Mở khoá kiến thức | Biết 朴 (phác) mở khoá: 朴素 (giản dị), 朴实 (đơn giản thực chất), 纯朴 (chân chất), 质朴 (mộc mạc).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 朴 là hình thanh: 木 (gỗ, biểu nghĩa) + 卜 (biểu âm). Nghĩa gốc là cây phác. Năm 1956 chính thức dùng làm giản thể của 樸 (chất phác, giản dị) theo Phương án giản hoá chữ Hán. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cây phác (vỏ dùng làm thuốc); chất phác", "Hạng Tần Suất (Jun Da)": "2088.0", "Tần Suất % (Jun Da)": "97.4443982863", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 卜", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木卜", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "卜", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "朴", "Unihan_Traditional (Chữ Phồn thể)": "朴", "Pinyin_Xie": "pǔ", "Âm Hán Việt_Xie": "phác, phu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường làm định ngữ bổ nghĩa cho danh từ hoặc làm vị ngữ trong câu. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('咐', '{"9000": "2089.0", "Chữ Trung Quốc": "咐", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 8 | nét | 口 | khẩu | biểu nghĩa | miệng, lời nói | 付 | phó | biểu âm | giao cho, phó thác | 咐 là chữ hình thanh: 口 (Khẩu) biểu nghĩa — miệng, lời nói; 付 (Phó) biểu âm. Nghĩa: dùng lời ra lệnh, dặn dò. Thường dùng trong 吩咐 và 嘱咐.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phó\": miệng 口 phó 付 giao nhiệm vụ — nói ra lệnh, dặn dò phó thác. | Gương Hán-Việt | \"phó\" trong \"phó thác\", \"căn dặn\" | Mở khoá kiến thức | Biết 咐 (phó) mở khoá: 吩咐 (ra lệnh, dặn dò), 嘱咐 (căn dặn kỹ càng).", "Tự nguyên_Xie": "Theo Wiktionary, 咐 là hình thanh: 口 (miệng, biểu nghĩa) + 付 (biểu âm). Nghĩa là ra lệnh bằng lời, dặn dò. Ít dùng độc lập, thường ghép trong 吩咐 (dặn dò) và 嘱咐 (căn dặn kỹ). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: phân phó 吩咐)", "Hạng Tần Suất (Jun Da)": "2089.0", "Tần Suất % (Jun Da)": "97.4476318109", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 付", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口付", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "付", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "咐", "Unihan_Traditional (Chữ Phồn thể)": "咐", "Pinyin_Xie": "fù", "Âm Hán Việt_Xie": "phó", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Hầu như chỉ xuất hiện trong từ ghép phân phó để chỉ việc dặn dò hay giao việc. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('孕', '{"9000": "2090.0", "Chữ Trung Quốc": "孕", "Bộ thủ & thành phần_Xie": "Bộ thủ | 子 | Số nét | 5 | nét | 乃 | nãi | biểu nghĩa | vú, cho bú (hình tượng vú phụ nữ) | 子 | tử | biểu nghĩa | con, đứa trẻ | 孕 = 乃 (Nãi, biểu nghĩa: vú/người mẹ cho bú) + 子 (Tử, biểu nghĩa: đứa trẻ). Chữ hội ý — nhưng Wiktionary giải thích là tượng hình (liushu p): hình ảnh người phụ nữ mang thai với thai nhi. Không phân tích thành hội ý thuần tuý. Nghĩa: mang thai, có mang.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"dựng\": 孕 vẽ người phụ nữ 乃 mang thai nhi 子 — dựng (thai nghén), như ươm dựng mầm sống bên trong. | Gương Hán-Việt | dựng trong 孕育 (dựng dục — thai nghén, ươm ủ), 妊孕 (nhâm dựng — mang thai). | Mở khoá kiến thức | Biết 孕 mở khoá: 怀孕 (mang thai), 孕妇 (phụ nữ mang thai), 孕育 (thai nghén, ươm ủ), 避孕 (tránh thai).", "Tự nguyên_Xie": "Wiktionary xác nhận: 孕 là tượng hình (liushu p) — hình ảnh người phụ nữ đang mang thai với thai nhi bên trong. Đây không phải hội ý của 乃 + 子 theo nghĩa nghĩa học, mà là biểu tượng hoá hình thể người mang thai. Nghĩa gốc và hiện đại: mang thai, thụ thai. Mở rộng: ươm ủ, thai nghén (孕育 — thai nghén, hình thành). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chửa, có mang", "Hạng Tần Suất (Jun Da)": "2090.0", "Tần Suất % (Jun Da)": "97.4508648187", "GavinGrover_Once (Chiết tự trực tiếp)": "乃 + 子", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱乃子", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "乃", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "子", "Unihan_Simplified (Chữ Giản thể)": "孕", "Unihan_Traditional (Chữ Phồn thể)": "孕", "Pinyin_Xie": "yùn", "Âm Hán Việt_Xie": "dựng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường kết hợp với các từ khác để chỉ trạng thái mang thai hoặc thai phụ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('誓', '{"9000": "2091.0", "Chữ Trung Quốc": "誓", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 14 | nét | 折 | chiết | biểu âm | bẻ gãy | 言 | ngôn | biểu nghĩa | lời nói | 誓 là chữ hình thanh: 言 (Ngôn) biểu nghĩa — lời nói; 折 (Chiết) biểu âm. Nghĩa gốc: lời cam kết trang trọng, thề thốt.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thệ\": lời ngôn 言 chiết 折 không gãy — lời thề không thể bẻ gãy, bất di bất dịch. | Gương Hán-Việt | \"thệ\" trong \"tuyên thệ\" (宣誓), \"thệ ngôn\" (誓言) | Mở khoá kiến thức | Biết 誓 (thệ) mở khoá: 发誓 (thề), 宣誓 (tuyên thệ), 誓言 (lời thề), 誓死 (thề chết).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 誓 là hình thanh: 折 (biểu âm) + 言 (lời nói, biểu nghĩa). Nghĩa gốc: tuyên thề trước đông người. Mở rộng: danh từ lời thề (誓言), động từ thề (发誓). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thề, hứa", "Hạng Tần Suất (Jun Da)": "2091.0", "Tần Suất % (Jun Da)": "97.454094209", "GavinGrover_Once (Chiết tự trực tiếp)": "折 + 言", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱折言", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "折", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "言", "Unihan_Simplified (Chữ Giản thể)": "誓", "Unihan_Traditional (Chữ Phồn thể)": "誓", "Pinyin_Xie": "shì", "Âm Hán Việt_Xie": "thệ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường làm động từ đứng trước lời hứa hoặc làm danh từ đi sau động từ lập. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('喉', '{"9000": "2092.0", "Chữ Trung Quốc": "喉", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 12 | nét | 口 | khẩu | biểu nghĩa | miệng, khoang miệng | 侯 | hầu | biểu âm | hầu tước, lãnh chúa | 喉 là chữ hình thanh: 口 (Khẩu) biểu nghĩa — miệng, vùng họng; 侯 (Hầu) biểu âm. Nghĩa gốc: hầu họng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hầu\": miệng 口 của hầu 侯 tước — họng hầu, giọng nói sang trọng. | Gương Hán-Việt | \"hầu\" trong \"yết hầu\" (咽喉), \"hầu họng\" | Mở khoá kiến thức | Biết 喉 (hầu) mở khoá: 喉咙 (cổ họng), 咽喉 (yết hầu), 喉结 (yết hầu — trái cổ).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 喉 là hình thanh: 口 (miệng, biểu nghĩa) + 侯 (biểu âm). Nghĩa gốc là hầu họng — thanh quản và thực quản phần trên. Từ ghép: 喉咙 (cổ họng), 咽喉 (yết hầu). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "hầu, họng", "Hạng Tần Suất (Jun Da)": "2092.0", "Tần Suất % (Jun Da)": "97.4573153308", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 侯", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口侯", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "侯", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "喉", "Unihan_Traditional (Chữ Phồn thể)": "喉", "Pinyin_Xie": "hóu", "Âm Hán Việt_Xie": "hầu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ bộ phận cơ thể hoặc kết hợp tạo từ ghép chỉ bộ phận hô hấp. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('妄', '{"9000": "2093.0", "Chữ Trung Quốc": "妄", "Bộ thủ & thành phần_Xie": "Bộ thủ | 女 | Số nét | 6 | nét | 亡 | vong | biểu âm | mất, chết | 女 | nữ | biểu nghĩa | người phụ nữ | 妄 là chữ hình thanh: 女 (Nữ) biểu nghĩa; 亡 (Vong) biểu âm. Nghĩa gốc: hành động sai trái. Mở rộng: viển vông, liều lĩnh, ngông cuồng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"vọng\": nữ 女 vong 亡 mất lý trí — vọng tưởng, hành động điên rồ. | Gương Hán-Việt | \"vọng\" trong \"vọng tưởng\" (妄想), \"vọng động\" (妄动) | Mở khoá kiến thức | Biết 妄 (vọng) mở khoá: 妄想 (ảo tưởng), 妄图 (mưu toan), 妄自尊大 (kiêu ngạo).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary (Han etyl), 妄 là hình thanh: 亡 (biểu âm) + 女 (biểu nghĩa). Nghĩa gốc: không đúng đắn, vô lý, liều lĩnh. Mở rộng: ảo tưởng (妄想), tùy tiện (妄动), kiêu ngạo (妄自尊大). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "viển vông, xa vời; ngông, lung tung, ẩu, sằng bậy", "Hạng Tần Suất (Jun Da)": "2093.0", "Tần Suất % (Jun Da)": "97.4605338686", "GavinGrover_Once (Chiết tự trực tiếp)": "亡 + 女", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱亡女", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "亡", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "女", "Unihan_Simplified (Chữ Giản thể)": "妄", "Unihan_Traditional (Chữ Phồn thể)": "妄", "Pinyin_Xie": "wàng", "Âm Hán Việt_Xie": "vọng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Phó từ | 副词 | Thường làm phó từ đứng trước động từ để chỉ hành vi vô lý, càn rỡ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Phó từ | 副词 | Bổ nghĩa cho động từ hoặc tính từ và luôn đứng TRƯỚC chúng — 都是, 很好. Không đứng sau như tiếng Việt và không bổ nghĩa cho danh từ.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('拘', '{"9000": "2094.0", "Chữ Trung Quốc": "拘", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 8 | nét | 扌 | thủ | biểu nghĩa | tay | 句 | câu | biểu âm | câu văn, cong | 拘 là chữ hình thanh: 扌 (Thủ) biểu nghĩa — tay, giữ chặt; 句 (Câu) biểu âm. Nghĩa gốc: bắt giữ, giam cầm. Mở rộng: ràng buộc, câu nệ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"câu\": tay 扌 câu 句 giữ chặt — câu nệ, bị câu thúc, bị bắt giam. | Gương Hán-Việt | \"câu\" trong \"câu nệ\" (拘泥), \"câu thúc\" (拘束) | Mở khoá kiến thức | Biết 拘 (câu) mở khoá: 拘束 (ràng buộc), 拘留 (giam giữ), 拘泥 (câu nệ cứng nhắc).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 拘 là hình thanh: 手/扌 (tay, biểu nghĩa) + 句 (biểu âm). Nghĩa gốc là bắt giữ, giam cầm. Mở rộng: hạn chế (拘束), câu nệ (拘泥), giam giữ (拘留). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "câu nệ, hay tin nhảm", "Hạng Tần Suất (Jun Da)": "2094.0", "Tần Suất % (Jun Da)": "97.4637503393", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 句", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌句", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "句", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "拘", "Unihan_Traditional (Chữ Phồn thể)": "拘", "Pinyin_Xie": "jū", "Âm Hán Việt_Xie": "câu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Thường làm động từ chỉ hành động bắt giữ hoặc làm tính từ trong từ ghép chỉ sự gò bó. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('链', '{"9000": "2095.0", "Chữ Trung Quốc": "链", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 12 | nét | 钅 | kim | biểu nghĩa | kim loại (bộ kim giản thể) | 连 | liên | biểu âm | liên kết, nối tiếp; cho âm liàn | 链 = 钅(Kim, biểu nghĩa: kim loại) + 连 (Liên, biểu âm: cho âm liàn). Chữ hình thanh — bộ kim chỉ vật làm bằng kim loại, 连 cho âm. Nghĩa: dây xích, chuỗi (bằng kim loại); chuỗi, chuỗi liên kết (mở rộng).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"liên\": 链 = 钅(kim loại) + 连(liên) — liên kết 连 các vòng kim loại 钅lại thành 项链 (dây chuyền cổ). | Gương Hán-Việt | liên trong 項鍊 (hạng liên — dây chuyền cổ), 鏈條 (liên điều — xích xe). | Mở khoá kiến thức | Biết 链 mở khoá: 项链 (dây chuyền), 链条 (xích), 食物链 (chuỗi thức ăn), 区块链 (blockchain).", "Tự nguyên_Xie": "Wiktionary xác nhận: 链 (繩) là hình thanh, 金 (kim loại, biểu nghĩa) + 連 (biểu âm). Nghĩa gốc: xích kim loại — những vòng kim loại móc nối nhau. Mở rộng: dây chuyền (项链 — vòng cổ), chuỗi mắt xích (链条), blockchain (区块链), chuỗi DNA (链式反应). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái xích; chì chưa nấu", "Hạng Tần Suất (Jun Da)": "2095.0", "Tần Suất % (Jun Da)": "97.4669662932", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 连", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅连", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "连", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "链", "Unihan_Traditional (Chữ Phồn thể)": "鏈", "Pinyin_Xie": "liàn", "Âm Hán Việt_Xie": "liên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường làm danh từ chỉ sợi xích hoặc làm động từ trong ngữ cảnh liên kết dữ liệu. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('驰', '{"9000": "2096.0", "Chữ Trung Quốc": "驰", "Bộ thủ & thành phần_Xie": "Bộ thủ | 馬 | Số nét | 6 | nét | 马 | mã | biểu nghĩa | ngựa | 也 | dã | biểu âm | cũng, thì | 驰 là giản thể của 馳 (trì). 马 (Mã) biểu nghĩa — ngựa, di chuyển nhanh; 也 (Dã) biểu âm. Nghĩa gốc: ngựa phóng nhanh; mở rộng sang danh tiếng lan xa.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trì\": ngựa 马 phóng dã 也 ngoài đồng — phi nước đại, danh tiếng trì xa vạn dặm. | Gương Hán-Việt | \"trì\" trong \"phong trì\" (奔驰), \"trì danh\" (驰名) | Mở khoá kiến thức | Biết 驰 (trì) mở khoá: 奔驰 (chạy nhanh), 驰名 (nổi tiếng), 驰骋 (phi nước đại).", "Tự nguyên_Xie": "Tiểu triện | 驰 là giản thể của 馳. Wiktionary không có giải thích glyph chi tiết cho dạng giản thể. Cấu trúc: 马 (ngựa, biểu nghĩa) + 也 (biểu âm). Nghĩa gốc: phi nước đại. Mở rộng: danh tiếng lan xa (驰名), tư nhớ (神驰). | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chạy mau, phóng nhanh; đuổi; truyền đi, vang khắp (tên tuổi)", "Hạng Tần Suất (Jun Da)": "2096.0", "Tần Suất % (Jun Da)": "97.4701698442", "GavinGrover_Once (Chiết tự trực tiếp)": "马 + 也", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰马也", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "也", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "马", "Unihan_Simplified (Chữ Giản thể)": "驰", "Unihan_Traditional (Chữ Phồn thể)": "馳", "Pinyin_Xie": "chí", "Âm Hán Việt_Xie": "trì", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ trong văn viết để tả xe cộ chạy nhanh hoặc tâm trí hướng về nơi xa. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('栏', '{"9000": "2097.0", "Chữ Trung Quốc": "栏", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 9 | nét | 木 | mộc | biểu nghĩa | gỗ | 兰 | lan | biểu âm | hoa lan | 栏 là giản thể của 欄, rút gọn 闌 thành 兰. 木 (Mộc) biểu nghĩa — gỗ làm lan can, hàng rào; 兰 (Lan) biểu âm. Nghĩa gốc: lan can, hàng rào gỗ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lan\": gỗ 木 chắn lan 兰 hoa — hàng rào lan can bằng gỗ, chuyên mục lan rộng từng trang. | Gương Hán-Việt | \"lan\" trong \"lan can\" (栏杆), \"chuyên mục\" (栏目) | Mở khoá kiến thức | Biết 栏 (lan) mở khoá: 栏目 (chuyên mục), 专栏 (cột chuyên đề), 栏杆 (lan can), 护栏 (hàng rào).", "Tự nguyên_Xie": "栏 là giản thể của 欄. Wiktionary ghi rút gọn 闌 thành 兰. 欄 là hình thanh: 木 (gỗ, biểu nghĩa) + 闌 (biểu âm). Nghĩa gốc: thanh rào, lan can. Mở rộng: mục, chuyên mục (栏目). | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lan can", "Hạng Tần Suất (Jun Da)": "2097.0", "Tần Suất % (Jun Da)": "97.4733646099", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 兰", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木兰", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "兰", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "栏", "Unihan_Traditional (Chữ Phồn thể)": "欄", "Pinyin_Xie": "lán", "Âm Hán Việt_Xie": "lan", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này thường làm danh từ đứng sau các từ chỉ vị trí hoặc kết hợp tạo thành danh từ ghép chỉ các loại khung, bảng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | lán | / | cột | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Thông tin và Phương tiện III | New HSK 7-9 | · | Ngôi nhà và cuộc sống hàng ngày I", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('逝', '{"9000": "2098.0", "Chữ Trung Quốc": "逝", "Bộ thủ & thành phần_Xie": "Bộ thủ | 辵 | Số nét | 10 | nét | 辶 | sước | biểu nghĩa | đi, di chuyển | 折 | chiết | biểu âm | bẻ gãy | 逝 là chữ hình thanh: 辵/辶 (Sước) biểu nghĩa — đi, rời xa; 折 (Chiết) biểu âm. Nghĩa gốc: dòng nước chảy đi không trở lại; mở rộng sang qua đời.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thệ\": bước chân 辶 chiết 折 đi không quay lại — thệ thế, ra đi mãi mãi như nước chảy. | Gương Hán-Việt | \"thệ\" trong \"thệ thế\" (逝世 — qua đời) | Mở khoá kiến thức | Biết 逝 (thệ) mở khoá: 逝世 (qua đời), 流逝 (trôi qua), 消逝 (tan biến).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 逝 là hình thanh: 辵 (đi, biểu nghĩa) + 折 (biểu âm). Thơ cổ: \"滚滚长江东逝水\" — nước chảy đi không trở lại. Mở rộng: thời gian trôi qua (时光流逝), qua đời (逝世). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1831.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Xước (162) Chiết (217)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Xước (số 162 - bước đi/ 辶 /chỉ ý) bao bên ngoài chữ Chiết (số 217 - bẻ gãy/ 折 /chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Chiết chỉ âm, bộ Xước chỉ ý. Thệ là bước đi không trở lại, thời gian trôi qua không quay về. Từ đó dùng để chỉ cái chết, người đã mất (thệ thế - qua đời, trường thệ).", "Nghĩa Tiếng Việt_Xie": "trôi qua; đi không trở lại; chết, tạ thế", "Hạng Tần Suất (Jun Da)": "2098.0", "Tần Suất % (Jun Da)": "97.4765593756", "GavinGrover_Once (Chiết tự trực tiếp)": "辶 + 折", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴辶折", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "折", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "辶", "Unihan_Simplified (Chữ Giản thể)": "逝", "Unihan_Traditional (Chữ Phồn thể)": "逝", "Pinyin_Xie": "shì", "Âm Hán Việt_Xie": "thệ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ thường đứng sau chủ ngữ chỉ thời gian hoặc sinh mệnh để diễn tả sự trôi đi không trở lại. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('窃', '{"9000": "2099.0", "Chữ Trung Quốc": "窃", "Bộ thủ & thành phần_Xie": "Bộ thủ | 穴 | Số nét | 9 | nét | 穴 | huyệt | biểu nghĩa | hang, lỗ hổng (biến dạng từ 宀) | 切 | tiếp | biểu âm | cắt (biểu âm gần) | 窃 là chữ có lịch sử glyph phức tạp: gốc gồm 米 + 攴 + 禼 (biểu âm). Thời Hán thêm 宀 (nhà), về sau 宀 biến thành 穴. Nghĩa: lẻn vào nơi ở để ăn cắp.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thiết\": chui vào hang huyệt 穴 cắt thiết 切 lấy — kẻ trộm chui hang ăn cắp. | Gương Hán-Việt | \"thiết\" trong \"đạo thiết\" (盗窃 — trộm cắp) | Mở khoá kiến thức | Biết 窃 (thiết) mở khoá: 盗窃 (trộm cắp), 窃取 (đánh cắp), 窃听 (nghe lén), 窃喜 (thầm vui).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 窃 có glyph cổ là 𢿑/𱡡, là hợp thể 米 (gạo) + 攴 (hành động) + 禼 (biểu âm). Thời Tây Hán thêm 宀 (nhà) nhấn nghĩa trộm trong nhà. Thời Đông Hán, 宀 biến dạng thành 穴. Nghĩa gốc: ăn trộm, lẻn vào. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ăn cắp, ăn trộm", "Hạng Tần Suất (Jun Da)": "2099.0", "Tần Suất % (Jun Da)": "97.4797500071", "GavinGrover_Once (Chiết tự trực tiếp)": "穴 + 切", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱穴切", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "切", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "穴", "Unihan_Simplified (Chữ Giản thể)": "窃", "Unihan_Traditional (Chữ Phồn thể)": "竊", "Pinyin_Xie": "qiè", "Âm Hán Việt_Xie": "thiết", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Phó từ | 副词 | Chữ này làm động từ chỉ hành vi trộm cắp hoặc làm phó từ đứng trước động từ để chỉ hành động thực hiện một cách lén lút. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Phó từ | 副词 | Bổ nghĩa cho động từ hoặc tính từ và luôn đứng TRƯỚC chúng — 都是, 很好. Không đứng sau như tiếng Việt và không bổ nghĩa cho danh từ.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('艳', '{"9000": "2100.0", "Chữ Trung Quốc": "艳", "Bộ thủ & thành phần_Xie": "Bộ thủ | 色 | Số nét | 10 | nét | 丰 | phong | biểu hình (do giản hoá) | giản từ 豐 (phong phú) | 色 | sắc | biểu nghĩa | màu sắc | 艳 là dạng giản thể của 艷. Phồn 艷 vốn là hội ý: 豐 (phong phú) + 色 (sắc) — màu sắc phong phú, rực rỡ. Trong giản thể, 豐 thay bằng 丰 cho gọn, cấu trúc hội ý vẫn giữ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"diễm\": 丰 (phong) + 色 (sắc) — sắc màu phong phú rực rỡ, đúng nghĩa ''tươi đẹp, rực rỡ'' trong 鲜艳, 艳丽. | Gương Hán-Việt | ''diễm'' trong ''diễm lệ'', ''kiều diễm'', ''diễm phúc'' | Mở khoá kiến thức | Nắm 艳 mở khoá loạt từ HSK 5-7: 鲜艳, 艳丽.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 艳 là giản thể của 艷 (cũng được coi biến thể là 豔) — hội ý: 豐/丰 (phong phú) + 色 (màu sắc) — đầy đặn sắc màu, rực rỡ. Nghĩa gốc ''đẹp đẽ, tươi tắn, rực rỡ'' trong 鲜艳 (tươi rói), 艳丽 (rực rỡ và đẹp). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đẹp đẽ, tươi đẹp; con gái đẹp; chuyện tình yêu; hâm mộ, ham chuộng; khúc hát nước Sở", "Hạng Tần Suất (Jun Da)": "2100.0", "Tần Suất % (Jun Da)": "97.4829396049", "GavinGrover_Once (Chiết tự trực tiếp)": "丰 + 色", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰丰色", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "丰", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "色", "Unihan_Simplified (Chữ Giản thể)": "艳", "Unihan_Traditional (Chữ Phồn thể)": "艶", "Pinyin_Xie": "yàn", "Âm Hán Việt_Xie": "diễm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này làm tính từ thường đứng trước danh từ hoặc đứng sau phó từ chỉ mức độ để miêu tả màu sắc sặc sỡ hoặc vẻ đẹp kiều diễm. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('臭', '{"9000": "2101.0", "Chữ Trung Quốc": "臭", "Bộ thủ & thành phần_Xie": "Bộ thủ | 自 | Số nét | 10 | nét | 自 | tự | biểu nghĩa | mũi (nghĩa gốc của 自 là mũi) | 犬 | khuyển | biểu nghĩa | chó | 臭 = 自 (Tự — nghĩa gốc là mũi, biểu nghĩa) + 犬 (Khuyển, biểu nghĩa: chó). Chữ hội ý — chó 犬 dùng mũi 自 đánh hơi = khứu giác, mùi. Wiktionary xác nhận: hội ý giữa chó và mũi, gợi ý khứu giác nhạy bén của chó. Dạng gốc là chữ của 嗅 (ngửi).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"xú\": 臭 = 自(mũi) + 犬(chó) — xú (hôi thối) là con chó 犬 đánh mũi 自 vào thứ gì đó hôi — từ đây thành nghĩa mùi hôi. | Gương Hán-Việt | xú trong 臭氣 (xú khí — mùi hôi), 遺臭萬年 (di xú vạn niên — để tiếng xấu muôn đời). | Mở khoá kiến thức | Biết 臭 mở khoá: 臭 (hôi thối), 口臭 (hôi miệng), 体臭 (mùi cơ thể), 遗臭万年 (để tiếng xấu muôn đời).", "Tự nguyên_Xie": "Wiktionary xác nhận: 臭 là hội ý, 犬 (chó, biểu nghĩa) + 自 (mũi, nghĩa gốc — biểu nghĩa). Chỉ khứu giác của chó — con vật có khứu giác bậc nhất. Là dạng gốc của 嗅 (ngửi). Nghĩa gốc: mùi (cả mùi thơm lẫn mùi hôi). Dần thu hẹp thành: mùi hôi, hôi thối. Phát âm xiù (âm khác) vẫn giữ nghĩa gốc ''mùi'' trong 无声无臭. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mùi; hôi thối, khai, khét; tiếng xấu", "Hạng Tần Suất (Jun Da)": "2101.0", "Tần Suất % (Jun Da)": "97.486126102", "GavinGrover_Once (Chiết tự trực tiếp)": "自 + 犬", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱自犬", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "犬", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "自", "Unihan_Simplified (Chữ Giản thể)": "臭", "Unihan_Traditional (Chữ Phồn thể)": "臭", "Pinyin_Xie": "chòu", "Âm Hán Việt_Xie": "xú", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Chữ này làm tính từ đứng trước danh từ để miêu tả mùi hôi thối hoặc tính chất đáng ghét của sự vật. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | Từ đơn | Từ vựng HSK 5: hôi thối | / | chòu | / | hôi thối | Xuất hiện trong lộ trình | New HSK | New HSK 5 | · | Thức ăn và đồ uống | HSK | HSK 5 | · | Thức ăn và đồ uống", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('纤', '{"9000": "2102.0", "Chữ Trung Quốc": "纤", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 6 | nét | 纟 | mịch | biểu nghĩa | tơ, sợi | 千 | thiên | biểu âm | nghìn | 纤 là chữ hình thanh (phồn thể 纖): 糸/纟 (Mịch) biểu nghĩa — tơ, sợi mỏng; 韱/千 biểu âm. Nghĩa gốc: tơ lụa mịn. Mở rộng: nhỏ mảnh, chất xơ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khiên\": sợi 纟 mỏng nghìn 千 lần — chất xơ khiên mảnh dẻ như sợi chỉ nghìn sợi. | Gương Hán-Việt | \"khiên\" trong \"khiên vi\" (纤维 — chất xơ) | Mở khoá kiến thức | Biết 纤 (khiên) mở khoá: 纤维 (chất xơ), 化纤 (sợi hóa học), 光纤 (cáp quang).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 纤 (phồn thể 纖) là hình thanh: 糸 (tơ, biểu nghĩa) + 韱 (biểu âm, rút gọn thành 千 trong giản thể). Nghĩa gốc: tơ mịn. Mở rộng: mảnh mai, chất xơ, sợi nhân tạo. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nhỏ nhặt", "Hạng Tần Suất (Jun Da)": "2102.0", "Tần Suất % (Jun Da)": "97.4893125992", "GavinGrover_Once (Chiết tự trực tiếp)": "纟 + 千", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰纟千", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "千", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "纟", "Unihan_Simplified (Chữ Giản thể)": "纤", "Unihan_Traditional (Chữ Phồn thể)": "縴", "Pinyin_Xie": "xiān", "Âm Hán Việt_Xie": "tiêm, khiên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Chữ này làm tính từ đứng trước danh từ để miêu tả những sự vật có hình dáng nhỏ bé, mảnh mai hoặc tinh tế. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('玑', '{"9000": "2103.0", "Chữ Trung Quốc": "玑", "Bộ thủ & thành phần_Xie": "Bộ thủ | 玉 | Số nét | 6 | nét | 王 | vương | biểu nghĩa | ngọc (bộ 玉 viết giản) | 几 | cơ | biểu âm | cho âm jī | 玑 = 王/玉 (Vương/Ngọc, biểu nghĩa: ngọc) + 几 (Cơ, biểu âm); chữ hình thanh. Phần 玉 cho biết nghĩa liên quan đến ngọc, phần 几 cho âm đọc jī.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ky\": viên ngọc (王) chưa tròn — như cái bàn cắt (几) chưa đánh bóng xong. | Gương Hán-Việt | 璇璣 (huyền ky) — dụng cụ thiên văn cổ; 珠璣 (châu ky) — châu ngọc | Mở khoá kiến thức | Biết 玑 mở khoá các từ chỉ ngọc quý và thiên văn học cổ đại Trung Hoa như 璇璣圖, 珠璣.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Theo Wiktionary, dạng đầy đủ là 璣: hội ý hình thanh gồm 玉 (ngọc, biểu nghĩa) và 幾 (biểu âm). Nghĩa gốc là hạt ngọc không hoàn toàn tròn; về sau dùng chỉ dụng cụ thiên văn cổ đại (hỗn thiên cầu). Trong tiếng Việt, 璣/玑 được phiên là ''ky''. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ngọc (hạt ngọc không tròn); dụng cụ xem thiên văn; kính thiên văn", "Hạng Tần Suất (Jun Da)": "2103.0", "Tần Suất % (Jun Da)": "97.4924985795", "GavinGrover_Once (Chiết tự trực tiếp)": "王 + 几", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰王几", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "几", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "王", "Unihan_Simplified (Chữ Giản thể)": "玑", "Unihan_Traditional (Chữ Phồn thể)": "璣", "Pinyin_Xie": "jī", "Âm Hán Việt_Xie": "ki", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ thường xuất hiện trong các từ ghép cổ chỉ các loại ngọc quý hoặc dụng cụ quan sát thiên văn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('棵', '{"9000": "2104.0", "Chữ Trung Quốc": "棵", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 12 | nét | 木 | mộc | biểu nghĩa | cây | 果 | quả | biểu âm | gợi âm kē | 棵 = 木 (Mộc: cây) + 果 (Quả, biểu âm); chữ hình thanh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khoả\": cây 木 mang trái 果 — đếm một cây, đó là ''khoả'' (lượng từ cho cây). | Gương Hán-Việt | khoả/quả trong từ Hán-Việt cổ; người Việt thường dịch \"cây\" | Mở khoá kiến thức | Biết 棵 mở khoá khái niệm lượng từ cho cây: 一棵, 几棵, 一棵树.", "Tự nguyên_Xie": "Wiktionary chỉ ghi ''Han etym'' đơn giản. Phân tích thành phần: 木 (cây) cho nghĩa ''lượng từ cho cây'', 果 (quả, biểu âm kē). Dùng làm lượng từ đếm cây. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1826.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Mộc (075) Quả (1001)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Mộc (số 075 - cây cối/ 木 /chỉ ý) ở bên trái chữ Quả (số 1001 - trái cây/ 果 /chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Quả chỉ âm, bộ Mộc chỉ ý. Khỏa là lượng từ dùng để đếm số lượng cây cối, gốc cây (nhất khỏa thụ - một cái cây).", "Nghĩa Tiếng Việt_Xie": "một cây, một gốc (dùng để đếm cây)", "Hạng Tần Suất (Jun Da)": "2104.0", "Tần Suất % (Jun Da)": "97.4956814592", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 果", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木果", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "果", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "棵", "Unihan_Traditional (Chữ Phồn thể)": "棵", "Pinyin_Xie": "kē", "Âm Hán Việt_Xie": "khỏa", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Lượng từ | 量词 | Chữ này làm lượng từ đứng sau số từ và đứng trước danh từ để đếm các loại thực vật có thân gỗ hoặc thân thảo. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Lượng từ | 量词 | Đứng giữa số từ (hoặc 这/那) và danh từ: 一杯茶, 这本书. Mỗi danh từ đi với lượng từ riêng; 个 là lượng từ dùng chung phổ biến nhất.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | kē | / | cây | Xuất hiện trong lộ trình | New HSK | New HSK 4 | · | Thiên nhiên | HSK | HSK 4 | · | Khí hậu và môi trường", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('趁', '{"9000": "2105.0", "Chữ Trung Quốc": "趁", "Bộ thủ & thành phần_Xie": "Bộ thủ | 走 | Số nét | 12 | nét | 走 | tẩu | biểu nghĩa | chạy, đi | 㐱 | biểu âm | gồm Nhân (người) + Sam (ba nét sọc) | 趁 = 走 (Tẩu, biểu nghĩa: chạy) + 㐱 (biểu âm, gồm 人+彡); chữ hình thanh. Bộ 走 cho nghĩa liên quan đến chuyển động, 㐱 cho âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sấn\": hình ảnh chân 走 (tẩu) chạy tới nhân lúc cơ hội 㐱 xuất hiện — 趁 cơ hội mà tiến. | Gương Hán-Việt | sấn trong ''趁早 sấn tảo'' (càng sớm càng tốt) | Mở khoá kiến thức | Biết 趁 (sấn) mở khoá: 趁机 (nhân cơ hội), 趁早 (càng sớm càng tốt), 趁着 (lợi dụng lúc).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 趁 là chữ hình thanh (psc): 走 (tẩu, biểu nghĩa: chạy/đi) + 㐱 (biểu âm). Nghĩa gốc là ''đuổi theo'', sau chuyển sang nghĩa ''nhân lúc, tận dụng thời cơ'' — lấy đà mà chạy tới. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1660.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Tẩu (156) Chẩn (1659)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Tẩu (số 156 - chạy/ 走 /chỉ ý) ôm lấy chữ Chẩn (số 1659 - mái tóc/ 㐱 /chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Chẩn chỉ âm, bộ Tẩu chỉ ý. Sấn là chạy đuổi theo (sấn trục). Mở rộng mang nghĩa là nhân tiện, lợi dụng một lúc, một cơ hội nào đó (sấn cơ, sấn dịp).", "Nghĩa Tiếng Việt_Xie": "đuổi theo; nhân tiện", "Hạng Tần Suất (Jun Da)": "2105.0", "Tần Suất % (Jun Da)": "97.4988617549", "GavinGrover_Once (Chiết tự trực tiếp)": "走 + 㐱", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴走㐱", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "㐱", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "走", "Unihan_Simplified (Chữ Giản thể)": "趁", "Unihan_Traditional (Chữ Phồn thể)": "趁", "Pinyin_Xie": "chèn", "Âm Hán Việt_Xie": "sấn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Giới từ | 介词 | Động từ | 动词 | Chữ này làm giới từ đứng đầu một cụm từ hoặc phân câu để chỉ việc tận dụng một điều kiện thời gian, cơ hội thuận lợi. | Giới từ | 介词 | Ghép với danh từ hoặc đại từ thành cụm chỉ nơi chốn, thời gian, đối tượng: 在家, 跟他. Cụm giới từ đứng TRƯỚC động từ — 我在家吃饭 — ngược với trật tự tiếng Việt. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | Từ đơn | Từ vựng HSK 5: tận dụng | / | chèn | / | tận dụng | Xuất hiện trong lộ trình | HSK | HSK 5 | · | Kỹ năng và thành tích | New HSK | New HSK 7-9 | · | Thành công và thành tựu I", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('匠', '{"9000": "2106.0", "Chữ Trung Quốc": "匠", "Bộ thủ & thành phần_Xie": "Bộ thủ | 匚 | Số nét | 6 | nét | 匚 | phương | biểu nghĩa | hộp/khung chứa đồ nghề | 斤 | cân | biểu âm / biểu nghĩa | cái rìu — công cụ của thợ | 匠 = 匚 (Phương, hộp đựng đồ nghề, biểu nghĩa) + 斤 (Cân, rìu, biểu nghĩa/âm); có hai cách giải: hội ý (người thợ cầm rìu trong hộp đồ nghề) hoặc hình thanh (匚 biểu âm, 斤 biểu nghĩa). Học giới hiện đại nghiêng về hình thanh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tượng\": người thợ (匠) cầm rìu 斤 để trong hộp 匚 — tay nghề tinh xảo như tượng gỗ. | Gương Hán-Việt | thợ mộc (木匠 mộc tượng), thợ thủ công (工匠 công tượng) | Mở khoá kiến thức | Biết 匠 mở khoá các từ chỉ nghề thủ công: 木匠 (thợ mộc), 石匠 (thợ đá), 工匠 (người thợ), 匠心 (tâm khéo).", "Tự nguyên_Xie": "Đại triện | Tiểu triện | Wiktionary ghi nhận hai thuyết: thuyết truyền thống (Thuyết Văn) coi 匠 là hội ý — 匚 (hộp) + 斤 (rìu), tức người thợ với đồ nghề trong hộp. Thuyết mới hơn (Zhengzhang 2003, Baxter-Sagart 2014) đề xuất hình thanh — 匚 biểu âm, 斤 (rìu) biểu nghĩa. Nghĩa gốc: người thợ thủ công khéo léo. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "người thợ; khéo, lành nghề", "Hạng Tần Suất (Jun Da)": "2106.0", "Tần Suất % (Jun Da)": "97.5020358492", "GavinGrover_Once (Chiết tự trực tiếp)": "匚 + 斤", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿷ (Bao quanh phía trái)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴匚斤", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "斤", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "匚", "Unihan_Simplified (Chữ Giản thể)": "匠", "Unihan_Traditional (Chữ Phồn thể)": "匠", "Pinyin_Xie": "jiàng", "Âm Hán Việt_Xie": "tượng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ thường đứng sau các danh từ chỉ vật liệu hoặc ngành nghề để chỉ người thợ chuyên nghiệp. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('盈', '{"9000": "2107.0", "Chữ Trung Quốc": "盈", "Bộ thủ & thành phần_Xie": "Bộ thủ | 皿 | Số nét | 9 | nét | 夃 | (không rõ) | biểu hình | bộ phận ý nghĩa chưa rõ | 皿 | mãnh | biểu nghĩa | đồ đựng, bát | 盈 là chữ hội ý: 皿 (Mãnh) — đồ đựng; 夃 (bộ phận trên, gồm 乃 và 又, ý nghĩa chưa rõ theo Wiktionary). Nghĩa: đồ đựng đã đầy tràn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"doanh\": bát 皿 đã đầy tràn — doanh lợi, thắng lợi đầy đủ, mắt đẫm lệ. | Gương Hán-Việt | \"doanh\" trong \"doanh lợi\" (盈利), \"doanh dư\" (thặng dư) | Mở khoá kiến thức | Biết 盈 (doanh) mở khoá: 盈利 (lợi nhuận), 热泪盈眶 (mắt đẫm lệ), 盈余 (thặng dư).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 盈 là hội ý không chắc chắn: 夃 + 皿 (đồ đựng). Ý nghĩa của 夃 còn chưa rõ. Nghĩa gốc: đồ đựng đã đầy. Mở rộng: đầy tràn (盈眶), lợi nhuận (盈利). | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1471.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Nãi (004) Khảm (017) Mãnh (107)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Gồm chữ Cổ (夃 - hoặc Nãi 乃 kết hợp với Khảm 凵) ở trên bộ Mãnh (số 107 - cái chậu/ 皿). Hình ảnh nước đã được đổ đầy tràn ra khỏi một cái chậu. Giải thích sự chuyển ý: Đây là chữ Hội ý. Doanh là đầy tràn, dư dả (doanh đầy, lãi doanh nghiệp). Cũng để chỉ vóc dáng mềm mại, thướt tha, đầy đặn của người phụ nữ.", "Nghĩa Tiếng Việt_Xie": "đồ đã đựng đầy", "Hạng Tần Suất (Jun Da)": "2107.0", "Tần Suất % (Jun Da)": "97.5052099435", "GavinGrover_Once (Chiết tự trực tiếp)": "夃 + 皿", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱夃皿", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "夃", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "皿", "Unihan_Simplified (Chữ Giản thể)": "盈", "Unihan_Traditional (Chữ Phồn thể)": "盈", "Pinyin_Xie": "yíng", "Âm Hán Việt_Xie": "doanh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Chữ này làm động từ hoặc tính từ để miêu tả trạng thái đầy ắp, tràn đầy hoặc sự gia tăng của sự vật. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('翁', '{"9000": "2108.0", "Chữ Trung Quốc": "翁", "Bộ thủ & thành phần_Xie": "Bộ thủ | 羽 | Số nét | 10 | nét | 公 | công | biểu âm | cho âm wēng | 羽 | vũ | biểu nghĩa | lông chim | 翁 = 公 (Công, biểu âm) + 羽 (Vũ, lông vũ, biểu nghĩa); chữ hình thanh. Nghĩa gốc là lông chim, sau được mượn dùng chỉ ''ông lão'' do liên tưởng với bộ 公 (kính trọng).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ông\": chữ 翁 gồm 公 (ông kính lão) đội lên lông vũ 羽 — ông già tóc bạc như lông chim trắng. | Gương Hán-Việt | phú ông (富翁), ngư ông (渔翁 — lão ngư phủ) | Mở khoá kiến thức | Biết 翁 mở khoá các từ chỉ người đàn ông lớn tuổi: 富翁 (phú ông), 老翁 (lão ông), 渔翁 (ngư ông).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 翁 là hình thanh: 公 cho âm, 羽 (lông vũ) cho nghĩa. Nghĩa gốc là ''lông chim'', về sau từ này được mượn để chỉ ''ông lão'' qua liên tưởng với từ 公 (người đáng kính). Đây là trường hợp giả tá (mượn âm dùng nghĩa khác). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1070.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Công (090) Vũ (176)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Công (số 090 - chung/chỉ âm) ở trên bộ Vũ (số 176 - lông vũ). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Công chỉ âm, bộ Vũ chỉ ý. Ông vốn là lông vũ mọc ở cổ con chim. Sau được mượn làm tiếng tôn xưng người đàn ông lớn tuổi (ông lão, phú ông).", "Nghĩa Tiếng Việt_Xie": "ông cụ", "Hạng Tần Suất (Jun Da)": "2108.0", "Tần Suất % (Jun Da)": "97.5083814539", "GavinGrover_Once (Chiết tự trực tiếp)": "公 + 羽", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱公羽", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "公", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "羽", "Unihan_Simplified (Chữ Giản thể)": "翁", "Unihan_Traditional (Chữ Phồn thể)": "翁", "Pinyin_Xie": "wēng", "Âm Hán Việt_Xie": "ông", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ thường đứng sau họ của người khác để gọi một cách tôn kính các cụ ông hoặc người đàn ông lớn tuổi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('愁', '{"9000": "2109.0", "Chữ Trung Quốc": "愁", "Bộ thủ & thành phần_Xie": "Bộ thủ | 心 | Số nét | 13 | nét | 秋 | thu | biểu âm | mùa thu | 心 | tâm | biểu nghĩa | lòng, tâm hồn | 愁 = 秋 (Thu, biểu âm) + 心 (Tâm, biểu nghĩa: lòng); chữ hình thanh. Bộ 心 cho nghĩa cảm xúc, 秋 cho âm (chóu ~ qiū).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sầu\": trái tim 心 (tâm) cảm nhận mùa thu 秋 (thu) — nỗi sầu như lá mùa thu rơi trong lòng. | Gương Hán-Việt | sầu trong ''u sầu'' (buồn bã), ''ưu sầu'' | Mở khoá kiến thức | Biết 愁 (sầu) mở khoá: 发愁 (lo lắng), 忧愁 (u sầu), 愁眉苦脸 (mặt buồn rầu).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 愁 là chữ hình thanh (psc): 秋 (thu, biểu âm) + 心 (tâm, biểu nghĩa: trái tim). Hình ảnh mùa thu gợi nỗi buồn, tâm hồn chứa đựng nỗi sầu muộn như đất trời vào thu tàn. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "149.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thu (147) Tâm (148)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Thu (số 147) ở trên chữ Tâm (số 148) . Mùa thu hoạch nông dân trong lòng (tâm) luôn phải lo lắng thời tiết (sầu). Giải thích sự chuyển ý: Chữ Thu (mùa thu) chỉ âm, chữ Tâm (lòng) chỉ ý. Cảnh vật mùa thu (Thu) hiu quạnh dễ làm cho lòng người (Tâm) sinh ra cảm giác buồn bã, sầu thảm (Sầu). *(Biến âm Hán Việt: Trong Hán ngữ cổ, chữ Thu và chữ Sầu có cách phát âm tương đồng hoặc chung gốc phụ âm. Quá trình Việt hóa đã làm âm đọc bị chênh lệch thành Thu và Sầu).*", "Nghĩa Tiếng Việt_Xie": "buồn bã", "Hạng Tần Suất (Jun Da)": "2109.0", "Tần Suất % (Jun Da)": "97.5115519307", "GavinGrover_Once (Chiết tự trực tiếp)": "秋 + 心", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱秋心", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "秋", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "心", "Unihan_Simplified (Chữ Giản thể)": "愁", "Unihan_Traditional (Chữ Phồn thể)": "愁", "Pinyin_Xie": "chóu", "Âm Hán Việt_Xie": "sầu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Danh từ | 名词 | Chữ này thường làm động từ biểu thị sự lo lắng hoặc làm tính từ để chỉ tâm trạng buồn rầu. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | chóu | / | nhớ nhung, lo lắng | Xuất hiện trong lộ trình | New HSK | New HSK 5 | · | Những cảm xúc và cảm giác", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('瞬', '{"9000": "2110.0", "Chữ Trung Quốc": "瞬", "Bộ thủ & thành phần_Xie": "Bộ thủ | 目 | Số nét | 17 | nét | 目 | mục | biểu nghĩa | mắt | 舜 | thuấn | biểu âm | vua Thuấn | 瞬 là chữ hình thanh: 目 (Mục) biểu nghĩa — mắt; 舜 (Thuấn) biểu âm. Nghĩa gốc: nháy mắt, khoảnh khắc ngắn nhất.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thuấn\": mắt 目 vua Thuấn 舜 chớp — thuấn gian, khoảnh khắc chớp mắt. | Gương Hán-Việt | \"thuấn\" trong \"thuấn gian\" (瞬间 — khoảnh khắc) | Mở khoá kiến thức | Biết 瞬 (thuấn) mở khoá: 瞬间 (khoảnh khắc), 一瞬间 (trong nháy mắt), 瞬息万变 (thay đổi cực nhanh).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 瞬 là hình thanh: 目 (mắt, biểu nghĩa) + 舜 (biểu âm). Nghĩa gốc: nháy mắt (wink). Mở rộng: khoảnh khắc (瞬间), nhanh như chớp mắt. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nháy mắt", "Hạng Tần Suất (Jun Da)": "2110.0", "Tần Suất % (Jun Da)": "97.5147141389", "GavinGrover_Once (Chiết tự trực tiếp)": "目 + 舜", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰目舜", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "舜", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "目", "Unihan_Simplified (Chữ Giản thể)": "瞬", "Unihan_Traditional (Chữ Phồn thể)": "瞬", "Pinyin_Xie": "shùn", "Âm Hán Việt_Xie": "thuấn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường kết hợp với các từ khác để cấu tạo thành danh từ chỉ khoảnh khắc hoặc thời gian ngắn ngủi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('婴', '{"9000": "2111.0", "Chữ Trung Quốc": "婴", "Bộ thủ & thành phần_Xie": "Bộ thủ | 女 | Số nét | 11 | nét | 贝 | bối | biểu hình | vỏ sò (bên trái) | 贝 | bối | biểu hình | vỏ sò (bên phải) | 女 | nữ | biểu nghĩa | phụ nữ | 婴 là chữ hội ý: 賏 (hai vỏ sò 贝贝 — xâu vòng cổ) + 女 (Nữ). Hình ảnh người phụ nữ đeo vòng cổ vỏ sò — biểu trưng đứa trẻ sơ sinh được đeo bùa hộ mệnh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"anh\": bé gái 女 đeo vòng sò 贝贝 — trẻ anh nhi đeo vòng cổ từ lúc chào đời. | Gương Hán-Việt | \"anh\" trong \"anh nhi\" (婴儿 — trẻ sơ sinh) | Mở khoá kiến thức | Biết 婴 (anh) mở khoá: 婴儿 (trẻ sơ sinh), 婴幼儿 (trẻ sơ sinh và trẻ nhỏ).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 婴 là hội ý: 賏 (xâu vỏ sò — biểu trưng vòng cổ) + 女 (phụ nữ). Nghĩa gốc: trẻ sơ sinh quàng vòng cổ. Nghĩa thu hẹp: trẻ nhỏ, trẻ sơ sinh. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "trẻ con; thêm vào; vòng quanh", "Hạng Tần Suất (Jun Da)": "2111.0", "Tần Suất % (Jun Da)": "97.5178737632", "GavinGrover_Once (Chiết tự trực tiếp)": "No glyph available + 女", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱女", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "婴", "Unihan_Traditional (Chữ Phồn thể)": "嬰", "Pinyin_Xie": "yīng", "Âm Hán Việt_Xie": "anh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Trong tiếng Trung hiện đại chữ này chủ yếu làm danh từ để chỉ trẻ nhỏ trong các từ ghép. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('孝', '{"9000": "2112.0", "Chữ Trung Quốc": "孝", "Bộ thủ & thành phần_Xie": "Bộ thủ | 子 | Số nét | 7 | nét | 耂 | lão | biểu nghĩa | ông già tóc dài, cúi xuống | 子 | tử | biểu nghĩa | đứa trẻ | 孝 = 耂 (Lão: ông già tóc dài cúi xuống) + 子 (Tử: đứa trẻ); chữ hội ý — ông già và đứa trẻ, lòng hiếu thảo giữa các thế hệ. So sánh phần trên với 老.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hiếu\": 耂 (ông già) đứng trên 子 (đứa trẻ) — đứa con đỡ ông già lưng còng, đúng nghĩa ''hiếu thảo'' trong 孝顺, 孝敬. | Gương Hán-Việt | ''hiếu'' trong ''hiếu thảo'', ''hiếu kính'', ''bất hiếu'' | Mở khoá kiến thức | Nắm 孝 mở khoá loạt từ HSK 5-7: 孝顺, 孝敬.", "Tự nguyên_Xie": "Kim văn | Lệ thư | Theo Wiktionary, 孝 là hội ý: 耂 (ông già tóc dài cúi xuống — biến thể của 老) + 子 (đứa trẻ) — đứa trẻ đỡ ông già, lòng hiếu thảo giữa các thế hệ. Phần trên giống với 老 (lão). Nghĩa ''hiếu thảo, hiếu'' giữ nguyên trong 孝顺, 孝敬. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "633.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Lão (632) Tử (038)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Tử (số 038 - đứa con) ở dưới chữ Lão (số 632 - người già, viết giảm nét). Hình ảnh người con trai đang cõng người cha già trên lưng. Giải thích sự chuyển ý: Đây là chữ Hội ý. Con cái (Tử) vâng lời và phụng dưỡng cha mẹ già (Lão). Hiếu là sự hiếu thảo.", "Nghĩa Tiếng Việt_Xie": "lòng biết ơn cha mẹ", "Hạng Tần Suất (Jun Da)": "2112.0", "Tần Suất % (Jun Da)": "97.521032354", "GavinGrover_Once (Chiết tự trực tiếp)": "耂 + 子", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴耂子", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "子", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "耂", "Unihan_Simplified (Chữ Giản thể)": "孝", "Unihan_Traditional (Chữ Phồn thể)": "孝", "Pinyin_Xie": "xiào", "Âm Hán Việt_Xie": "hiếu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Động từ | 动词 | Thường dùng làm tính từ bổ nghĩa cho hành động hoặc làm động từ chỉ sự phụng dưỡng cha mẹ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('颈', '{"9000": "2113.0", "Chữ Trung Quốc": "颈", "Bộ thủ & thành phần_Xie": "Bộ thủ | 頁 | Số nét | 11 | nét | 𢀖 | kinh | biểu âm | biến thể của 巠 | 页 | hiệt | biểu nghĩa | đầu, trang | 颈 là giản thể của 頸: 页 (Hiệt) biểu nghĩa — đầu người; 𢀖 (biến thể của 巠) biểu âm. Nghĩa: cổ, phần nối đầu với thân.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cảnh\": đầu 页 trên cổ kinh 𢀖 — phần cảnh cổ nối đầu với thân. | Gương Hán-Việt | \"cảnh\" trong \"kinh cảnh\" (颈椎) | Mở khoá kiến thức | Biết 颈 (cảnh) mở khoá: 颈椎 (đốt sống cổ), 瓶颈 (điểm nghẽn), 颈部 (vùng cổ).", "Tự nguyên_Xie": "颈 là giản thể của 頸. Wiktionary ghi rút gọn 巠 thành 𢀖. 頸 nguyên là hình thanh: 頁 (đầu, biểu nghĩa) + 巠 (biểu âm). Nghĩa gốc: cổ phần trước. Mở rộng: đốt sống cổ (颈椎), điểm nghẽn (瓶颈). | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cổ trước", "Hạng Tần Suất (Jun Da)": "2113.0", "Tần Suất % (Jun Da)": "97.5241868104", "GavinGrover_Once (Chiết tự trực tiếp)": "No glyph available + 页", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰页", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "颈", "Unihan_Traditional (Chữ Phồn thể)": "頸", "Pinyin_Xie": "jǐng", "Âm Hán Việt_Xie": "cảnh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ bộ phận cổ, thường xuất hiện trong các thuật ngữ y học hoặc từ ghép. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('倘', '{"9000": "2114.0", "Chữ Trung Quốc": "倘", "Bộ thủ & thành phần_Xie": "Bộ thủ | 人 | Số nét | 10 | nét | 亻 | nhân | biểu nghĩa | người | 尚 | thượng | biểu âm | còn, vẫn còn | 倘 là chữ hình thanh: 亻 (Nhân) biểu nghĩa — người; 尚 (Thượng) biểu âm. Nghĩa: giả sử, nếu như (dùng trong câu điều kiện).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thảng\": người 亻 thượng 尚 còn — thảng nếu người ta còn ở đây, giả sử. | Gương Hán-Việt | \"thảng\" trong \"thảng nhược\" (倘若 — giả sử) | Mở khoá kiến thức | Biết 倘 (thảng) mở khoá: 倘若 (giả sử, nếu như), 倘使 (nếu mà), 倘或 (nếu lỡ mà).", "Tự nguyên_Xie": "Theo Wiktionary, 倘 là hình thanh: 人/亻 (người, biểu nghĩa) + 尚 (biểu âm). Nghĩa gốc: nếu như, giả sử (倘若). Dùng chủ yếu trong văn viết. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1825.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Nhân (009) Thượng (410)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Nhân đứng (số 009 - con người/ 亻/chỉ ý) ở bên trái chữ Thượng (số 410 - chuộng/ 尚 /chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Thượng chỉ âm, bộ Nhân chỉ ý. Thảng là từ dùng để giả định một điều kiện nào đó có thể xảy ra, mang nghĩa là \"giả sử\", \"nếu như\", \"bằng như\" (thảng sử - giả sử nếu như).", "Nghĩa Tiếng Việt_Xie": "ví như", "Hạng Tần Suất (Jun Da)": "2114.0", "Tần Suất % (Jun Da)": "97.5273247298", "GavinGrover_Once (Chiết tự trực tiếp)": "亻 + 尚", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰亻尚", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "尚", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "亻", "Unihan_Simplified (Chữ Giản thể)": "倘", "Unihan_Traditional (Chữ Phồn thể)": "倘", "Pinyin_Xie": "tǎng", "Âm Hán Việt_Xie": "thảng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Liên từ | 连词 | Thường đứng đầu phân câu để liên kết và biểu thị điều kiện giả định trong câu ghép. | Liên từ | 连词 | Nối từ, cụm từ hoặc mệnh đề: 和, 但是, 因为…所以…. Lưu ý 和 chỉ nối danh từ, không nối hai câu như ''và'' tiếng Việt.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('浙', '{"9000": "2115.0", "Chữ Trung Quốc": "浙", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 10 | nét | 氵 | thuỷ | biểu nghĩa | nước, sông | 折 | chiết | biểu âm | cho âm zhè (biến thể) | 浙 = 氵(Thuỷ, biểu nghĩa: nước/sông) + 折 (Chiết, biểu âm); chữ hình thanh. Bộ 氵 cho biết đây là tên sông, phần 折 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chiết\": sông 浙 có 氵 (nước) và 折 (gãy gập) — dòng sông uốn khúc gãy gập như tên tỉnh Chiết Giang. | Gương Hán-Việt | Chiết Giang (浙江 — tên tỉnh), Lưỡng Chiết (兩浙 — vùng đất lịch sử) | Mở khoá kiến thức | Biết 浙 chủ yếu mở khoá địa danh: 浙江 (tỉnh Chiết Giang), 浙东 (miền đông Chiết Giang), 江浙 (Giang Chiết — vùng Giang Tô + Chiết Giang).", "Tự nguyên_Xie": "Đại triện | Tiểu triện | Theo Wiktionary, 浙 là hình thanh: 水/氵 (nước, biểu nghĩa) + 折 (biểu âm). Nghĩa gốc và duy nhất là tên sông Chiết Giang (浙江) ở tỉnh Chiết Giang, Trung Quốc — con sông có nhiều khúc uốn (折 = gãy/gập). Chữ này chủ yếu dùng trong địa danh. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sông Chiết Giang (tỉnh Chiết Giang)", "Hạng Tần Suất (Jun Da)": "2115.0", "Tần Suất % (Jun Da)": "97.5304486959", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 折", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵折", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "折", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "浙", "Unihan_Traditional (Chữ Phồn thể)": "浙", "Pinyin_Xie": "zhè", "Âm Hán Việt_Xie": "chiết", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ riêng để chỉ địa danh hoặc tên viết tắt của tỉnh Chiết Giang. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('谅', '{"9000": "2116.0", "Chữ Trung Quốc": "谅", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 10 | nét | 讠 | ngôn | biểu nghĩa | lời nói — lời thông cảm | 京 | kinh | biểu âm | phần biểu âm — gần âm ''lượng/kinh'' | 谅 là dạng giản thể của 諒, gồm 讠 (言, lời nói — biểu nghĩa) + 京 (biểu âm). Là chữ hình thanh — dùng lời cảm thông, tha thứ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Lượng\": lời nói (讠) khoan dung như kinh đô (京) rộng lớn — đó là ''lượng'', tha thứ, thông cảm. | Gương Hán-Việt | ''Lượng'' trong ''khoan lượng'' (rộng lượng), ''lượng thứ'' (tha thứ), ''thể lượng'' (thông cảm). | Mở khoá kiến thức | Biết 谅 mở khoá 原谅 (nguyên lượng, tha thứ), 谅解 (lượng giải, thông cảm), 体谅 (thể lượng, cảm thông).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 谅 là dạng giản thể của 諒, được tạo bằng cách thay 言 bằng 讠. Chữ phồn thể 諒 là chữ hình thanh: 言 (lời nói — biểu nghĩa) + 京 (biểu âm). Nghĩa gốc ''thành thực, đáng tin'' phái sinh các nghĩa ''tha thứ, thông cảm, ước đoán''. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tha thứ; ước đoán; (tên đất)", "Hạng Tần Suất (Jun Da)": "2116.0", "Tần Suất % (Jun Da)": "97.5335618096", "GavinGrover_Once (Chiết tự trực tiếp)": "讠 + 京", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰讠京", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "京", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "讠", "Unihan_Simplified (Chữ Giản thể)": "谅", "Unihan_Traditional (Chữ Phồn thể)": "諒", "Pinyin_Xie": "liàng", "Âm Hán Việt_Xie": "lượng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Thường làm động từ mang tân ngữ để biểu thị sự thông cảm, tha thứ hoặc phỏng đoán. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蔽', '{"9000": "2117.0", "Chữ Trung Quốc": "蔽", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 14 | nét | 艹 | thảo | biểu nghĩa | cỏ, thực vật | 敝 | tệ | biểu âm | rách, tồi | 蔽 là chữ hình thanh: 艸/艹 (Thảo) biểu nghĩa — cỏ cây che phủ; 敝 (Tệ) biểu âm. Nghĩa gốc: cỏ cây che lấp, giấu khuất.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tế\": cỏ 艹 tệ 敝 che phủ — tế bít, che lấp như cỏ che khuất tất cả. | Gương Hán-Việt | \"tế\" ít dùng độc lập; xuất hiện trong \"che tế\", \"ẩn tế\" | Mở khoá kiến thức | Biết 蔽 (tế) mở khoá: 隐蔽 (ẩn giấu), 遮蔽 (che lấp), 蒙蔽 (che giấu lừa dối), 一言以蔽之 (một câu tóm lại).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 蔽 là hình thanh: 艸 (cỏ, biểu nghĩa) + 敝 (biểu âm). Nghĩa gốc: che lấp, giấu khuất. Mở rộng: tóm gọn (一言以蔽之), che giấu (蒙蔽), ẩn náu (隐蔽). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1479.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thảo (140) Tệ (1478)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Thảo (số 140 - cỏ/ 艹 /chỉ ý) ở trên chữ Tệ (số 1478 - rách nát/ 敝 /chỉ âm). Dùng cỏ để phủ che lấp đồ cũ bị rách nát. Giải thích sự chuyển ý: Đây là chữ Hình thanh kiêm Hội ý. Tế là cỏ che lấp, bao trùm, giấu kín (che tế, che lấp).", "Nghĩa Tiếng Việt_Xie": "che lấp", "Hạng Tần Suất (Jun Da)": "2117.0", "Tần Suất % (Jun Da)": "97.5366707889", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 敝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹敝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "敝", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "蔽", "Unihan_Traditional (Chữ Phồn thể)": "蔽", "Pinyin_Xie": "bì", "Âm Hán Việt_Xie": "tế", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước danh từ để chỉ hành động che đậy hoặc ngăn cản tầm nhìn. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('畅', '{"9000": "2118.0", "Chữ Trung Quốc": "畅", "Bộ thủ & thành phần_Xie": "Bộ thủ | 日 | Số nét | 8 | nét | 申 | thân | biểu hình | nói rõ, mở rộng | 𠃓 | dương | biểu hình | biến thể của 昜 | 畅 là giản thể của 暢, rút gọn 昜 thành 𠃓. Nghĩa gốc: thông suốt, trôi chảy không bị cản trở, vui sướng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sướng\": 申 mở rộng thông suốt — sướng khi mọi thứ trôi chảy không bị cản. | Gương Hán-Việt | \"sướng\" trong \"thư sướng\" (舒畅), \"lưu sướng\" (流畅) | Mở khoá kiến thức | Biết 畅 (sướng) mở khoá: 畅通 (thông suốt), 畅销 (bán chạy), 舒畅 (thoải mái), 流畅 (trôi chảy).", "Tự nguyên_Xie": "Tiểu triện | 畅 là giản thể của 暢 (Sướng). Wiktionary ghi rút gọn 昜 thành 𠃓. Chữ tạo muộn. Nghĩa gốc: thông suốt, không trở ngại. Mở rộng: thoải mái (舒畅), trôi chảy (流畅), bán chạy (畅销). | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sướng, thích", "Hạng Tần Suất (Jun Da)": "2118.0", "Tần Suất % (Jun Da)": "97.5397777012", "GavinGrover_Once (Chiết tự trực tiếp)": "申 + 𠃓", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰申𠃓", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "𠃓", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "申", "Unihan_Simplified (Chữ Giản thể)": "畅", "Unihan_Traditional (Chữ Phồn thể)": "暢", "Pinyin_Xie": "chàng", "Âm Hán Việt_Xie": "sướng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Phó từ | 副词 | Thường làm tính từ miêu tả sự trôi chảy hoặc làm phó từ bổ nghĩa cho động từ để chỉ sự thỏa thích. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Phó từ | 副词 | Bổ nghĩa cho động từ hoặc tính từ và luôn đứng TRƯỚC chúng — 都是, 很好. Không đứng sau như tiếng Việt và không bổ nghĩa cho danh từ.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('赠', '{"9000": "2119.0", "Chữ Trung Quốc": "赠", "Bộ thủ & thành phần_Xie": "Bộ thủ | 貝 | Số nét | 16 | nét | 贝 | bối | biểu nghĩa | vỏ sò, tài vật | 曾 | tằng | biểu âm | từng, đã từng | 赠 là chữ hình thanh: 贝/貝 (Bối) biểu nghĩa — tài vật; 曾 (Tằng) biểu âm. Nghĩa gốc: tặng tài vật cho người khác.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tặng\": của cải 贝 từng 曾 dành tặng — tằng đã tặng, vật phẩm từng được trao tay. | Gương Hán-Việt | \"tặng\" trong \"tặng phẩm\", \"quyên tặng\" | Mở khoá kiến thức | Biết 赠 (tặng) mở khoá: 赠送 (tặng), 捐赠 (quyên góp), 馈赠 (tặng biếu trang trọng).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 赠 (phồn thể 贈) là hình thanh: 貝 (tài vật, biểu nghĩa) + 曾 (biểu âm). Nghĩa gốc: tặng biếu. Mở rộng: tặng quà (赠送), quyên góp (捐赠). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tặng, biếu", "Hạng Tần Suất (Jun Da)": "2119.0", "Tần Suất % (Jun Da)": "97.5428804791", "GavinGrover_Once (Chiết tự trực tiếp)": "贝 + 曾", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰贝曾", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "曾", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "贝", "Unihan_Simplified (Chữ Giản thể)": "赠", "Unihan_Traditional (Chữ Phồn thể)": "贈", "Pinyin_Xie": "zèng", "Âm Hán Việt_Xie": "tặng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ mang tân ngữ để chỉ hành động trao tặng quà cáp hoặc đồ vật cho người khác. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | zèng | / | tặng | Xuất hiện trong lộ trình | New HSK | New HSK 5 | · | Các mối quan hệ", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('妮', '{"9000": "2120.0", "Chữ Trung Quốc": "妮", "Bộ thủ & thành phần_Xie": "Bộ thủ | 女 | Số nét | 8 | nét | 女 | nữ | biểu nghĩa | phụ nữ, con gái | 尼 | ni | biểu âm | cho âm nī | 妮 = 女 (Nữ, biểu nghĩa: người nữ) + 尼 (Ni, biểu âm); chữ hình thanh. Bộ 女 xác định nghĩa liên quan đến phụ nữ/con gái, phần 尼 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ni\": cô gái (妮) mang bộ 女 (nữ) và 尼 (ni) — cô ni cô trẻ trong nhà. | Gương Hán-Việt | 妮子 (ni tử — cô gái nhỏ, tiếng địa phương) | Mở khoá kiến thức | Biết 妮 mở khoá từ thân mật gọi con gái: 妮子 (ni tử), 小妮子 (tiểu ni tử — cô bé).", "Tự nguyên_Xie": "Theo Wiktionary, 妮 là hình thanh: 女 (phụ nữ, biểu nghĩa) + 尼 (biểu âm). Nghĩa gốc là con ở, người hầu gái; trong tiếng địa phương hiện dùng thân mật để gọi ''cô gái''. Tiếng Hán-Việt đọc là ''ni''. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con đòi, con ở", "Hạng Tần Suất (Jun Da)": "2120.0", "Tần Suất % (Jun Da)": "97.5459811899", "GavinGrover_Once (Chiết tự trực tiếp)": "女 + 尼", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰女尼", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "尼", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "女", "Unihan_Simplified (Chữ Giản thể)": "妮", "Unihan_Traditional (Chữ Phồn thể)": "妮", "Pinyin_Xie": "nī", "Âm Hán Việt_Xie": "ni", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong khẩu ngữ để gọi con gái nhỏ hoặc dùng trong tên riêng của nữ giới. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('莎', '{"9000": "2121.0", "Chữ Trung Quốc": "莎", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 10 | nét | 艹 | thảo | biểu nghĩa | cỏ, thực vật | 沙 | sa | biểu âm | cho âm shā/suō | 莎 = 艹 (Thảo, biểu nghĩa: thực vật) + 沙 (Sa, biểu âm); chữ hình thanh. Bộ 艹 xác định đây là loại cỏ/cây, phần 沙 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sa\": cây cỏ 莎 mọc trên bãi cát 沙 — cỏ gấu sa mạc, rễ làm thuốc. | Gương Hán-Việt | sa thảo (莎草 — cỏ gấu), phiên âm 莎士比亚 (Sa Sĩ Tỉ Á — Shakespeare) | Mở khoá kiến thức | Biết 莎 mở khoá từ dược liệu 莎草 (cỏ gấu) và tên phiên âm phương Tây như 莎士比亚.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 莎 là hình thanh: 艸/艹 (cỏ, biểu nghĩa) + 沙 (biểu âm). Nghĩa gốc là cỏ gấu (Cyperus rotundus) — loại cỏ thuốc dùng trong y học cổ truyền. Âm đọc có hai dạng: suō (cỏ gấu) và shā (dùng trong tên phiên âm như 莎士比亚 Shakespeare). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cỏ gấu, củ gấu (dùng làm thuốc)", "Hạng Tần Suất (Jun Da)": "2121.0", "Tần Suất % (Jun Da)": "97.5490767329", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 沙", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹沙", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "沙", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "莎", "Unihan_Traditional (Chữ Phồn thể)": "莎", "Pinyin_Xie": "shā", "Âm Hán Việt_Xie": "sa, toa", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này thường dùng làm danh từ để chỉ một loại cỏ hoặc dùng trong tên riêng phiên âm. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('尉', '{"9000": "2122.0", "Chữ Trung Quốc": "尉", "Bộ thủ & thành phần_Xie": "Bộ thủ | 寸 | Số nét | 11 | nét | 尸 | thi | biểu nghĩa | thân thể | 示 | thị | biểu nghĩa | bàn thờ/lễ nghi | 寸 | thốn | biểu nghĩa | bàn tay/tấc | 尉 theo Wiktionary có thể là hội ý: 𡰥 (thân người) + 寸 (bàn tay) + 火 (lửa) — hình ảnh người dùng tay ép lửa vào vải để là phẳng. Cấu trúc hiện đại đã biến dạng, khó nhận rõ lửa. Chữ hội ý.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"uý\": người cấp 尉 (uý) dùng tay 寸 giữ kỷ cương — như bàn tay giữ trật tự trong quân đội. | Gương Hán-Việt | uý quan (尉官 — sĩ quan cấp uý), trung uý (中尉), thiếu uý (少尉) | Mở khoá kiến thức | Biết 尉 mở khoá các cấp bậc quân sự: 少尉 (thiếu uý), 中尉 (trung uý), 上尉 (thượng uý), 大尉 (đại uý).", "Tự nguyên_Xie": "Đại triện | Tiểu triện | Theo Wiktionary, 尉 có thể là hội ý: 𡰥 (thân người) + 寸 (bàn tay) + 火 (lửa) — gợi hình ảnh là vải bằng than nóng. Nghĩa gốc liên quan đến ''ủi/là'' (慰), sau mượn dùng cho chức vụ quân sự cấp uý. Hán-Việt đọc là ''uý''. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cấp uý", "Hạng Tần Suất (Jun Da)": "2122.0", "Tần Suất % (Jun Da)": "97.5521712423", "GavinGrover_Once (Chiết tự trực tiếp)": "No glyph available + 寸", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰寸", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "尉", "Unihan_Traditional (Chữ Phồn thể)": "尉", "Pinyin_Xie": "wèi", "Âm Hán Việt_Xie": "uý, uất", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ chỉ cấp bậc quân hàm hoặc chức quan thời cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('冻', '{"9000": "2123.0", "Chữ Trung Quốc": "冻", "Bộ thủ & thành phần_Xie": "Bộ thủ | 冫 | Số nét | 7 | nét | 冫 | băng | biểu nghĩa | băng, lạnh | 东 | đông | biểu âm | phương đông | 冻 = 冫 (Băng, biểu nghĩa: lạnh/đóng băng) + 东 (Đông, biểu âm); chữ hình thanh. Bộ 冫 cho biết liên quan đến băng lạnh, 东 cho âm (dòng ~ dōng).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đông\": hai chấm 冫 (băng) bên cạnh phương 东 (đông) — phương đông lạnh giá đóng 冻 băng. | Gương Hán-Việt | đông trong ''đông kết'' (đóng băng), ''lãnh đông'' | Mở khoá kiến thức | Biết 冻 (đông) mở khoá: 冻结 (đóng băng, phong tỏa), 冷冻 (đông lạnh), 解冻 (tan băng).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 冻 là chữ giản thể của 凍. Theo Wiktionary, 凍 là chữ hình thanh: 冫 (biểu nghĩa: băng/lạnh) + 東 (biểu âm). Nghĩa gốc là đóng băng, cứng lại vì lạnh. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nước đá", "Hạng Tần Suất (Jun Da)": "2123.0", "Tần Suất % (Jun Da)": "97.5552636845", "GavinGrover_Once (Chiết tự trực tiếp)": "冫 + 东", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰冫东", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "东", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "冫", "Unihan_Simplified (Chữ Giản thể)": "冻", "Unihan_Traditional (Chữ Phồn thể)": "凍", "Pinyin_Xie": "dòng", "Âm Hán Việt_Xie": "đống", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Danh từ | 名词 | Thường làm động từ chỉ trạng thái đông cứng do lạnh hoặc làm tính từ miêu tả thời tiết. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | Từ đơn | Từ vựng HSK 5: đông lạnh | / | dòng | / | đông lạnh | Xuất hiện trong lộ trình | HSK | HSK 5 | · | Thiên nhiên và động vật | YCT | YCT 4 | · | Động từ tôi | New HSK | New HSK 5 | · | Thiên nhiên", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('跪', '{"9000": "2124.0", "Chữ Trung Quốc": "跪", "Bộ thủ & thành phần_Xie": "Bộ thủ | 足 | Số nét | 13 | nét | 𧾷 | túc | biểu nghĩa | chân | 危 | nguy | biểu âm | nguy hiểm, nghiêng | 跪 là chữ hình thanh: 足/𧾷 (Túc) biểu nghĩa — chân; 危 (Nguy) biểu âm. Điều thú vị: 危 tình cờ miêu tả hình người đang quỳ gối.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quỵ\": chân 足 nguy 危 nghiêng xuống — quỵ gối, cúi mình trước người trên. | Gương Hán-Việt | \"quỵ\" trong \"quỵ gối\", \"quỵ lụy\" | Mở khoá kiến thức | Biết 跪 (quỵ) mở khoá: 下跪 (quỳ xuống), 跪拜 (quỳ lạy), 跪地 (quỳ dưới đất).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 跪 là hình thanh: 足 (chân, biểu nghĩa) + 危 (biểu âm). Bộ phận 危 tình cờ miêu tả hình người quỳ gối trên đất. Nghĩa gốc: quỳ gối, ngồi xổm. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "quỳ gối; chân cua", "Hạng Tần Suất (Jun Da)": "2124.0", "Tần Suất % (Jun Da)": "97.55834114", "GavinGrover_Once (Chiết tự trực tiếp)": "⻊ + 危", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰⻊危", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "危", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⻊", "Unihan_Simplified (Chữ Giản thể)": "跪", "Unihan_Traditional (Chữ Phồn thể)": "跪", "Pinyin_Xie": "guì", "Âm Hán Việt_Xie": "quỵ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ chỉ hành động quỳ gối trong câu. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | guì | / | quỳ xuống | Xuất hiện trong lộ trình | HSK | HSK 6 | · | Chính trị | New HSK | New HSK 6 | · | Thân hình", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('闯', '{"9000": "2125.0", "Chữ Trung Quốc": "闯", "Bộ thủ & thành phần_Xie": "Bộ thủ | 門 | Số nét | 6 | nét | 门 | môn | biểu nghĩa | cửa, cổng | 马 | mã | biểu nghĩa | ngựa | 闯 = 门 (Môn: cửa) + 马 (Mã: ngựa); chữ hội ý. Hình ảnh con ngựa xông qua cửa, diễn tả hành động xông vào, liều lĩnh vượt qua chướng ngại.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sấm\": con 马 (mã) ngựa xông thẳng qua 门 (môn) cửa — tiếng sấm vang, dũng mãnh xông pha. | Gương Hán-Việt | sấm trong ''闯将 sấm tướng'' (vị tướng xông xáo) | Mở khoá kiến thức | Biết 闯 (sấm) mở khoá: 闯入 (xông vào), 闯关 (vượt ải), 闯荡 (bôn ba lăn lộn).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Theo Wiktionary, 闯 là chữ hội ý (ic): 馬 (mã: ngựa) xông qua 門 (môn: cửa). Hình ảnh sinh động: con ngựa húc vỡ cửa lao vào — nghĩa gốc là xông xáo, liều lĩnh vượt qua, sau dùng rộng cho ''闯入'' (xông vào), ''闯荡'' (bôn ba). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ló đầu ra; xông pha", "Hạng Tần Suất (Jun Da)": "2125.0", "Tần Suất % (Jun Da)": "97.5614180787", "GavinGrover_Once (Chiết tự trực tiếp)": "门 + 马", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿵ (Bao quanh phía trên)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴门马", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "马", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "门", "Unihan_Simplified (Chữ Giản thể)": "闯", "Unihan_Traditional (Chữ Phồn thể)": "闖", "Pinyin_Xie": "chuǎng", "Âm Hán Việt_Xie": "sấm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ vị ngữ biểu thị hành động xông pha hoặc đột nhập nhanh chóng. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | Từ đơn | Từ vựng HSK 5: xông vào | / | chuǎng | / | xông vào | Xuất hiện trong lộ trình | HSK | HSK 5 | · | Động từ hàng ngày | New HSK | New HSK 5 | · | Vận chuyển và di chuyển", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('葡', '{"9000": "2126.0", "Chữ Trung Quốc": "葡", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 12 | nét | 艹 | thảo | biểu nghĩa | cỏ — cây nho | 匍 | bồ | biểu âm | gợi âm ''pú'' | 葡 = 艹 (Thảo, cỏ) + 匍 (Bồ, biểu âm). Chữ hình thanh: một loài cây leo bò — nho. Phần lớn chỉ dùng trong từ ghép 葡萄 (nho).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt ''Bồ'': cây cỏ (艹) bò lan (匍 — bò lê) — đó là ''bồ'', cây nho leo dàn. | Gương Hán-Việt | ''Bồ'' trong bồ đào (葡萄, nho); cùng âm Hán-Việt với ''bồ'' (蒲, cây bồ). | Mở khoá kiến thức | Biết 葡 mở khóa 葡萄 (bồ đào / nho), 葡萄酒 (bồ đào tửu / rượu nho), 葡萄牙 (Bồ Đào Nha).", "Tự nguyên_Xie": "Theo Wiktionary, 葡 là chữ hình thanh: 艸 (艹) biểu nghĩa, 匍 biểu âm. Dùng trong 葡萄 — phiên âm từ tiếng Ba Tư ''budāwa'' cổ. Đến tiếng Trung dùng cả chữ 葡 và 萄 cho ''nho''. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: bồ đào 葡萄)", "Hạng Tần Suất (Jun Da)": "2126.0", "Tần Suất % (Jun Da)": "97.5644893327", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 匍", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹匍", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "匍", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "葡", "Unihan_Traditional (Chữ Phồn thể)": "葡", "Pinyin_Xie": "pú", "Âm Hán Việt_Xie": "bồ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ liên kết trong từ ghép để chỉ quả nho. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('厨', '{"9000": "2127.0", "Chữ Trung Quốc": "厨", "Bộ thủ & thành phần_Xie": "Bộ thủ | 厂 | Số nét | 12 | nét | 厂 | hán | biểu nghĩa | mái nhà (vốn 广) | 𭔰 | trù | biểu âm | vốn 尌, gồm 豆+寸; gợi âm chú | 厨 = 厂 (vốn 广, mái nhà) + 𭔰 (vốn 尌, biểu âm); chữ hình thanh (ls=psc). Nhà có cái bếp đứng đặt — ''nhà bếp''.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trù\": 厂 (mái) + 𭔰 (trù) — căn nhà có cái ''trù'' (bếp); nhớ 厨房 (trù phòng = nhà bếp), 厨师 (trù sư = đầu bếp). | Gương Hán-Việt | ''trù'' trong ''nhà trù'' (bếp), ''trù phòng'', ''trù sư'' | Mở khoá kiến thức | Biết 厨 là mở 厨房, 厨师 — nhóm danh từ về bếp và nghề nghiệp HSK 4-6.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 厨 là chữ hình thanh: 广 (biểu nghĩa: mái nhà; trong tự dạng hiện đại viết thành 厂) ghép với 尌 (biểu âm; gồm 豆 + 寸, hiện đại viết là 𭔰). Nghĩa: nhà bếp, người làm bếp; cũng dùng cho ''cái tủ đứng'' (橱). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái bếp; cái hòm", "Hạng Tần Suất (Jun Da)": "2127.0", "Tần Suất % (Jun Da)": "97.5706235723", "GavinGrover_Once (Chiết tự trực tiếp)": "厂 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴厂", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "厨", "Unihan_Traditional (Chữ Phồn thể)": "㕑", "Pinyin_Xie": "chú", "Âm Hán Việt_Xie": "trù", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ nơi nấu ăn hoặc người làm nghề nấu ăn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鸭', '{"9000": "2128.0", "Chữ Trung Quốc": "鸭", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鳥 | Số nét | 10 | nét | 甲 | giáp | biểu âm | gợi âm yā | 鸟 | điểu | biểu nghĩa | chim — vịt là loài chim | 鸭 là giản thể của 鴨. Bản gốc 鴨 = 甲 + 鳥 (psc). Bản giản thể rút 鳥 thành 鸟. Chữ hình thanh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"áp\": chữ 甲 (vỏ giáp) cùng chim 鸟 — con chim nước có lớp lông như giáp, đó là ''áp'' (vịt). | Gương Hán-Việt | áp trong \"bắc kinh khảo áp\" 北京烤鴨 | Mở khoá kiến thức | Biết 鸭 mở khoá nhóm từ về vịt: 鸭子, 烤鸭, 鸭蛋.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Wiktionary chú 鴨 là giản thể của 鴨, gồm 甲 + 鳥. 甲 cho âm yā, 鳥 (chim) cho nghĩa. Loài chim nước, tức con vịt. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con vịt", "Hạng Tần Suất (Jun Da)": "2128.0", "Tần Suất % (Jun Da)": "97.5736891417", "GavinGrover_Once (Chiết tự trực tiếp)": "甲 + 鸟", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰甲鸟", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "甲", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鸟", "Unihan_Simplified (Chữ Giản thể)": "鸭", "Unihan_Traditional (Chữ Phồn thể)": "鴨", "Pinyin_Xie": "yā", "Âm Hán Việt_Xie": "áp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ loài vịt, có thể đứng độc lập hoặc làm định ngữ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('颠', '{"9000": "2129.0", "Chữ Trung Quốc": "颠", "Bộ thủ & thành phần_Xie": "Bộ thủ | 頁 | Số nét | 16 | nét | 真 | chân | biểu âm | thật, thực | 页 | hiệt | biểu nghĩa | đầu | 颠 là chữ hình thanh: 页 (Hiệt) biểu nghĩa — đầu người; 真 (Chân) biểu âm. Nghĩa gốc: đỉnh đầu, đỉnh cao nhất. Mở rộng: đảo ngược, rung lắc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"điên\": đầu 页 chân 真 bị lộn ngược — điên đảo, đầu đuôi lộn tùng phèo. | Gương Hán-Việt | \"điên\" trong \"điên đảo\" (颠倒), \"điên phúc\" (颠覆) | Mở khoá kiến thức | Biết 颠 (điên) mở khoá: 颠倒 (đảo ngược), 颠簸 (lắc lư), 颠覆 (lật đổ), 颠峰 (đỉnh cao).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 颠 (phồn thể 顛) là hình thanh: 真 (biểu âm) + 頁 (đầu, biểu nghĩa). Nghĩa gốc: đỉnh đầu, đỉnh núi. Mở rộng: lộn ngược (颠倒), rung lắc (颠簸), lật đổ (颠覆). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đỉnh đầu; ngã", "Hạng Tần Suất (Jun Da)": "2129.0", "Tần Suất % (Jun Da)": "97.5767490265", "GavinGrover_Once (Chiết tự trực tiếp)": "真 + 页", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰真页", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "真", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "页", "Unihan_Simplified (Chữ Giản thể)": "颠", "Unihan_Traditional (Chữ Phồn thể)": "顛", "Pinyin_Xie": "diān", "Âm Hán Việt_Xie": "điên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường làm danh từ chỉ phần đỉnh hoặc động từ chỉ hành động chao đảo, xóc nảy. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('遮', '{"9000": "2130.0", "Chữ Trung Quốc": "遮", "Bộ thủ & thành phần_Xie": "Bộ thủ | 辵 | Số nét | 14 | nét | 辶 | sước | biểu nghĩa | đi, che đường | 庶 | thứ | biểu âm | dân thường, đông đúc | 遮 là chữ hình thanh: 辵/辶 (Sước) biểu nghĩa — chắn đường; 庶 (Thứ) biểu âm. Nghĩa gốc: chắn lại, che lấp.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"già\": bước 辶 chắn đông 庶 người — già nua che lấp, chia cắt đường đi. | Gương Hán-Việt | \"già\" trong \"già chắn\", \"già che\" | Mở khoá kiến thức | Biết 遮 (già) mở khoá: 遮挡 (che chắn), 遮盖 (che đậy), 遮掩 (che giấu), 遮蔽 (che lấp).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 遮 là hình thanh: 辵 (đường, biểu nghĩa) + 庶 (biểu âm). Nghĩa gốc: che chắn, ngăn trở. Mở rộng: che đậy (遮盖), che chắn (遮挡), che trời (遮天蔽日). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "che lấp; ngăn trở", "Hạng Tần Suất (Jun Da)": "2130.0", "Tần Suất % (Jun Da)": "97.5798052938", "GavinGrover_Once (Chiết tự trực tiếp)": "辶 + 庶", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴辶庶", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "庶", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "辶", "Unihan_Simplified (Chữ Giản thể)": "遮", "Unihan_Traditional (Chữ Phồn thể)": "遮", "Pinyin_Xie": "zhē", "Âm Hán Việt_Xie": "già", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ vị ngữ đi kèm tân ngữ chỉ vật bị che khuất. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | zhē | / | che | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Từ III", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('谊', '{"9000": "2131.0", "Chữ Trung Quốc": "谊", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 10 | nét | 讠 | ngôn | biểu nghĩa | lời nói — lời tình nghĩa | 宜 | nghi | biểu âm | phần biểu âm — gần âm ''nghị/nghi'' | 谊 là dạng giản thể của 誼, gồm 讠 (言, lời nói — biểu nghĩa) + 宜 (biểu âm). Là chữ hình thanh — lời nói thích hợp giữa bạn bè, biểu thị ''tình nghĩa, tình bạn''.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Nghị\": lời nói (讠) hợp lẽ (宜) giữa bạn bè — đó là ''nghị'', tình nghĩa, tình bạn. | Gương Hán-Việt | ''Nghị'' trong ''tình nghị'', ''hữu nghị'' (tình bạn), ''đạo nghị'', ''thâm nghị''. | Mở khoá kiến thức | Biết 谊 mở khoá 友谊 (hữu nghị, tình bạn), 情谊 (tình nghị), 深情厚谊 (thâm tình hậu nghị).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 谊 là dạng giản thể của 誼, là chữ hình thanh gồm 言 (讠, lời nói — biểu nghĩa) + 宜 (biểu âm, đồng thời gợi ý ''thích hợp, đúng mực''). Nghĩa gốc ''điều thích đáng, lễ nghĩa thích hợp'' phái sinh các nghĩa ''tình nghĩa, tình bạn, tình thân''. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tình bạn bè", "Hạng Tần Suất (Jun Da)": "2131.0", "Tần Suất % (Jun Da)": "97.5828553596", "GavinGrover_Once (Chiết tự trực tiếp)": "讠 + 宜", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰讠宜", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "宜", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "讠", "Unihan_Simplified (Chữ Giản thể)": "谊", "Unihan_Traditional (Chữ Phồn thể)": "誼", "Pinyin_Xie": "yì", "Âm Hán Việt_Xie": "nghị", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ mối quan hệ giao hảo hoặc tình cảm bạn bè. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('圳', '{"9000": "2132.0", "Chữ Trung Quốc": "圳", "Bộ thủ & thành phần_Xie": "Bộ thủ | 土 | Số nét | 6 | nét | 土 | thổ | biểu nghĩa | đất | 川 | xuyên | biểu nghĩa/âm | dòng nước, sông ngòi | 圳 = 土 (Thổ, đất, biểu nghĩa) + 川 (Xuyên, dòng nước, biểu nghĩa/âm); có thể là hội ý: rãnh đất dẫn nước. Không có nguồn Wiktionary cấu trúc rõ ràng — suy từ bộ thủ, đây là chữ tạo muộn dùng trong địa danh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quyến\": rãnh 圳 là vết cắt trên đất 土 cho nước 川 chảy qua — như tên thành phố Thâm Quyến (深圳). | Gương Hán-Việt | Thâm Quyến (深圳 — tên thành phố lớn TQ) | Mở khoá kiến thức | Biết 圳 mở khoá địa danh quan trọng: 深圳 (Shēnzhèn — Thâm Quyến, trung tâm công nghệ TQ).", "Tự nguyên_Xie": "圳 không có mục Wiktionary đầy đủ. Suy từ cấu trúc: 土 (đất) + 川 (dòng chảy) — rãnh đất dẫn nước ngoài đồng. Chữ tạo muộn, chủ yếu dùng trong địa danh như 深圳 (Thâm Quyến). Hán-Việt đọc là ''quyến''. Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "rãnh nước ngoài đồng", "Hạng Tần Suất (Jun Da)": "2132.0", "Tần Suất % (Jun Da)": "97.5859049087", "GavinGrover_Once (Chiết tự trực tiếp)": "土 + 川", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰土川", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "川", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "土", "Unihan_Simplified (Chữ Giản thể)": "圳", "Unihan_Traditional (Chữ Phồn thể)": "圳", "Pinyin_Xie": "zhèn", "Âm Hán Việt_Xie": "quyến", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này thường dùng làm danh từ trong địa danh hoặc chỉ các con mương nhỏ dẫn nước. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('吁', '{"9000": "2133.0", "Chữ Trung Quốc": "吁", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 6 | nét | 口 | khẩu | biểu nghĩa | miệng | 于 | vu | biểu âm | ở, tại | 吁 là chữ hình thanh: 口 (Khẩu) biểu nghĩa — miệng; 于 (Vu) biểu âm. Nghĩa: thở dài, kêu than (xū); hoặc kêu gọi (yù trong 呼吁).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hu\": miệng 口 vu 于 — hu hú, thở dài kêu than, hoặc kêu gọi lên tiếng. | Gương Hán-Việt | \"hu\" trong \"hô hu\" (呼吁 — kêu gọi) | Mở khoá kiến thức | Biết 吁 (hu) mở khoá: 呼吁 (kêu gọi), 长吁短叹 (than thở liên miên).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 吁 là hình thanh: 口 (miệng, biểu nghĩa) + 于 (biểu âm). Hai cách đọc: xū (thán từ, thở dài); yù (kêu gọi, trong 呼吁). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ôi, chao ôi (thán từ)", "Hạng Tần Suất (Jun Da)": "2133.0", "Tần Suất % (Jun Da)": "97.5889492899", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 于", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口于", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "于", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "吁", "Unihan_Traditional (Chữ Phồn thể)": "吁", "Pinyin_Xie": "xū", "Âm Hán Việt_Xie": "hu, dụ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Thán từ | 叹词 | Động từ | 动词 | Thường dùng làm thán từ biểu thị sự than thở hoặc động từ chỉ hành động thở dài. | Thán từ | 叹词 | Bộc lộ cảm xúc hoặc dùng để gọi đáp: 啊, 哦, 喂. Đứng tách riêng ở đầu câu, không làm thành phần câu. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('仑', '{"9000": "2134.0", "Chữ Trung Quốc": "仑", "Bộ thủ & thành phần_Xie": "Bộ thủ | 人 | Số nét | 4 | nét | 人 | nhân | biểu nghĩa | người (giản lược từ 亼 — tụ hợp) | 匕 | chuỷ | biểu nghĩa | (dạng giản của 冊 — sách) | 仑 là giản thể của 侖. Dạng đầy đủ 侖 là hội ý: 亼 (tụ họp) + 冊 (sách) — tụ hợp sách lại thành trật tự. Ý nghĩa gốc: sắp xếp theo thứ tự. Chữ hội ý.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"luân\": 仑 là trật tự luân thường — người (人) biết sắp xếp sách 冊 theo thứ tự luân phiên. | Gương Hán-Việt | luân lý (倫理), luân xa (輪子), lý luận (理論) | Mở khoá kiến thức | Biết 仑 (âm gốc luân) mở khoá các chữ quan trọng: 伦 (luân lý), 轮 (bánh xe luân chuyển), 论 (lý luận).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, dạng truyền thống 侖 là hội ý: 亼 (tụ hợp) + 冊 (sách). Có thể hiểu là ''gom sách lại'' hoặc ''miệng đọc từng chữ theo thứ tự'' — cả hai đều dẫn đến nghĩa ''trật tự, sắp xếp''. Đây là phần âm gốc trong nhiều chữ như 倫, 輪, 論. Hán-Việt: ''luân''. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sắp xếp", "Hạng Tần Suất (Jun Da)": "2134.0", "Tần Suất % (Jun Da)": "97.5919890201", "GavinGrover_Once (Chiết tự trực tiếp)": "人 + 匕", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱人匕", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "匕", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "人", "Unihan_Simplified (Chữ Giản thể)": "仑", "Unihan_Traditional (Chữ Phồn thể)": "侖", "Pinyin_Xie": "lún", "Âm Hán Việt_Xie": "luân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường dùng trong các từ ghép chỉ sự suy xét, trật tự hoặc làm danh từ riêng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('辟', '{"9000": "2135.0", "Chữ Trung Quốc": "辟", "Bộ thủ & thành phần_Xie": "Bộ thủ | 辛 | Số nét | 13 | nét | 尸 | thi | biểu hình | xác, hình người | 口 | khẩu | biểu hình | miệng | 辛 | tân | biểu hình | công cụ hình lưỡi dao | 辟 là chữ hội ý có lịch sử phức tạp: gốc giáp cốt là 卩 (người quỳ) + 䇂 (dụng cụ hình lưỡi dao) — người bị xét xử bởi công cụ quyền lực. Nghĩa gốc: cai quản, trừng phạt.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tích\": người quỳ trước dao — tích khai hoang, khai khẩn đất mới bằng quyền lực. | Gương Hán-Việt | \"tích\" trong \"khai tích\" (khai hoang) | Mở khoá kiến thức | Biết 辟 (tích) mở khoá: 开辟 (mở ra, khai phá), 辟谣 (đính chính tin đồn), 开天辟地 (khai thiên lập địa).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 辟 trong giáp cốt văn là hội ý: 卩 (người quỳ) + 䇂 (dao/lưỡi). Ý: cai trị, trừng phạt. Có thuyết 辟 là gốc của 璧 (ngọc bích). Về sau phân nhiều nghĩa: mở ra (开辟), phủ nhận (辟谣), lãnh chúa (cổ nghĩa). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1180.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thi (044) Khẩu (030) Tân (160)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Thi (số 044 - thi thể/ 尸), chữ Khẩu (số 030 - cái miệng) và chữ Tân (số 160 - hình phạt/cay đắng). Giải thích sự chuyển ý: Đây là chữ Hội ý. Tịch là hình phạt, tội lỗi (đại tịch). Cũng mang nghĩa là lánh xa (tịch tà), hoặc mở mang (khai tịch - đọc là phích).", "Nghĩa Tiếng Việt_Xie": "mở mang; khai hoang", "Hạng Tần Suất (Jun Da)": "2135.0", "Tần Suất % (Jun Da)": "97.5950256495", "GavinGrover_Once (Chiết tự trực tiếp)": "𡰪 + 辛", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰𡰪辛", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "𡰪", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "辛", "Unihan_Simplified (Chữ Giản thể)": "辟", "Unihan_Traditional (Chữ Phồn thể)": "辟", "Pinyin_Xie": "pì", "Âm Hán Việt_Xie": "tịch, tích, thí, phích, bễ, bách, tỵ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước danh từ để chỉ việc khai phá, mở mang hoặc trừ bỏ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('瘤', '{"9000": "2136.0", "Chữ Trung Quốc": "瘤", "Bộ thủ & thành phần_Xie": "Bộ thủ | 疒 | Số nét | 15 | nét | 疒 | nạch | biểu nghĩa | bệnh, nằm bệnh | 留 | lưu | biểu âm | ở lại, lưu giữ | 瘤 là chữ hình thanh: 疒 (Nạch) biểu nghĩa — bệnh tật; 留 (Lưu) biểu âm. Nghĩa: khối u bệnh lý tích tụ trong cơ thể.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lựu\": bệnh 疒 lưu 留 đọng lại — lựu đọng trong cơ thể, khối u tích tụ không tan. | Gương Hán-Việt | \"lựu\" trong \"lựu u\" (khối u), \"chủng lựu\" (肿瘤) | Mở khoá kiến thức | Biết 瘤 (lựu) mở khoá: 肿瘤 (khối u/bướu), 脂肪瘤 (u mỡ), 良性瘤 (u lành), 恶性瘤 (u ác tính).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 瘤 là hình thanh: 疒 (bệnh, biểu nghĩa) + 留 (biểu âm). Nghĩa gốc: khối u, cục thịt nổi lên bất thường. Mở rộng: bướu, khối u ác tính (肿瘤). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nổi cục máu; khối u", "Hạng Tần Suất (Jun Da)": "2136.0", "Tần Suất % (Jun Da)": "97.5980617622", "GavinGrover_Once (Chiết tự trực tiếp)": "疒 + 留", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴疒留", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "留", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "疒", "Unihan_Simplified (Chữ Giản thể)": "瘤", "Unihan_Traditional (Chữ Phồn thể)": "瘤", "Pinyin_Xie": "liú", "Âm Hán Việt_Xie": "lựu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng sau các từ chỉ bộ phận cơ thể để gọi tên các loại khối u. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('嫂', '{"9000": "2137.0", "Chữ Trung Quốc": "嫂", "Bộ thủ & thành phần_Xie": "Bộ thủ | 女 | Số nét | 12 | nét | 女 | nữ | biểu nghĩa | phụ nữ | 叟 | tẩu | biểu âm | ông già | 嫂 là chữ hình thanh: 女 (Nữ) biểu nghĩa — người phụ nữ; 叟 (Tẩu) biểu âm. Nghĩa: chị dâu, cách gọi trân trọng phụ nữ đã có chồng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tẩu\": nữ 女 tẩu 叟 — tẩu tức chị dâu, người phụ nữ đứng đầu nhà. | Gương Hán-Việt | \"tẩu\" trong \"tẩu tử\" (嫂子 — chị dâu) | Mở khoá kiến thức | Biết 嫂 (tẩu) mở khoá: 嫂子 (chị dâu), 大嫂 (chị dâu lớn), 嫂嫂 (cách gọi thân mật).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 嫂 là hình thanh: 女 (phụ nữ, biểu nghĩa) + 叟 (biểu âm). Nghĩa gốc: chị dâu (vợ anh trai). Cũng dùng để gọi phụ nữ cùng tuổi hoặc lớn hơn (嫂子). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chị dâu; chị (gọi phụ nữ đã có chồng nhưng tuổi chưa nhiều)", "Hạng Tần Suất (Jun Da)": "2137.0", "Tần Suất % (Jun Da)": "97.6010916735", "GavinGrover_Once (Chiết tự trực tiếp)": "女 + 叟", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰女叟", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "叟", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "女", "Unihan_Simplified (Chữ Giản thể)": "嫂", "Unihan_Traditional (Chữ Phồn thể)": "嫂", "Pinyin_Xie": "sǎo", "Âm Hán Việt_Xie": "tẩu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ xưng hô độc lập hoặc kết hợp với họ để gọi chị dâu. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('陀', '{"9000": "2138.0", "Chữ Trung Quốc": "陀", "Bộ thủ & thành phần_Xie": "Bộ thủ | 阜 | Số nét | 7 | nét | 阝 | phụ | biểu nghĩa | gò đất, địa hình | 它 | tha | biểu âm | cho âm tuó | 陀 = 阝(Phụ, bộ phụ bên trái chỉ địa hình đất dốc, biểu nghĩa) + 它 (Tha, biểu âm); chữ hình thanh. Bộ 阝trái (阜) chỉ đồi/địa hình gập ghềnh, phần 它 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đà\": địa hình 阝gập ghềnh 陀 như con quay đà ngã — 陀螺 (con quay) quay tròn theo quán tính. | Gương Hán-Việt | đà la ni (陀羅尼 — thần chú Phật giáo), Phật Đà (佛陀) | Mở khoá kiến thức | Biết 陀 mở khoá các từ Phật giáo: 佛陀 (Phật Đà), 陀羅尼 (đà la ni), và từ vật lý 陀螺 (con quay — đà luân).", "Tự nguyên_Xie": "Wiktionary không có mục cấu trúc rõ ràng cho 陀. Suy từ bộ thủ: 阜/阝 (đồi, địa hình) + 它 (biểu âm) — chỉ địa thế gập ghềnh, dốc cao. Nghĩa mở rộng: quán tính (陀螺 — con quay). Trong phiên âm Phật giáo, 陀 dùng phiên chữ Phạn (ध, त). Hán-Việt: ''đà''. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chỗ gập ghềnh; đà, quán tính", "Hạng Tần Suất (Jun Da)": "2138.0", "Tần Suất % (Jun Da)": "97.6041215847", "GavinGrover_Once (Chiết tự trực tiếp)": "阝 + 它", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰阝它", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "它", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "阝", "Unihan_Simplified (Chữ Giản thể)": "陀", "Unihan_Traditional (Chữ Phồn thể)": "陀", "Pinyin_Xie": "tuó", "Âm Hán Việt_Xie": "đà", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Thường dùng làm danh từ chỉ sườn dốc hoặc kết hợp trong các từ phiên âm Phật giáo. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('框', '{"9000": "2139.0", "Chữ Trung Quốc": "框", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 10 | nét | 木 | mộc | biểu nghĩa | gỗ | 匡 | khuông | biểu âm | giỏ, sửa chữa, khuông khổ | 框 là chữ hình thanh: 木 (Mộc) biểu nghĩa — gỗ làm khung; 匡 (Khuông) biểu âm. Nghĩa gốc: khung gỗ. Mở rộng: khung bất kỳ chất liệu, framework.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khung\": gỗ 木 khuông 匡 đóng khung — khung gỗ, khuông khổ định hình. | Gương Hán-Việt | \"khung\" trong \"khung ảnh\", \"khung kiến trúc\" (框架) | Mở khoá kiến thức | Biết 框 (khung) mở khoá: 框架 (khung, framework), 相框 (khung ảnh), 门框 (khung cửa).", "Tự nguyên_Xie": "Theo Wiktionary, 框 không có giải thích glyph cổ chi tiết. Cấu trúc: 木 (gỗ, biểu nghĩa) + 匡 (biểu âm). Nghĩa gốc: khung gỗ. Mở rộng: khung cửa (门框), khung ảnh (相框), kiến trúc (框架). | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái khung", "Hạng Tần Suất (Jun Da)": "2139.0", "Tần Suất % (Jun Da)": "97.6071463281", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 匡", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木匡", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "匡", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "框", "Unihan_Traditional (Chữ Phồn thể)": "框", "Pinyin_Xie": "kuāng", "Âm Hán Việt_Xie": "khuông", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường làm danh từ chỉ khung cửa, khung tranh hoặc động từ với nghĩa đóng khung. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | kuàng | / | khung | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Ngôi nhà và cuộc sống hàng ngày II", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('谭', '{"9000": "2140.0", "Chữ Trung Quốc": "谭", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 14 | nét | 讠 | ngôn | biểu nghĩa | lời nói | 覃 | đàm | biểu âm | cho âm tán | 谭 = 讠(Ngôn, biểu nghĩa: lời nói) + 覃 (Đàm, biểu âm); chữ hình thanh. Bộ 讠xác định nghĩa liên quan đến lời nói/ngôn ngữ, phần 覃 cho âm đọc. Đây là dạng giản thể của 譚.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đàm\": miệng 讠nói chuyện đàm đạo — họ Đàm hay đàm luận. | Gương Hán-Việt | đàm thoại (談話), họ Đàm (譚姓) | Mở khoá kiến thức | Biết 谭 mở khoá: nhận ra họ Đàm phổ biến ở Trung Quốc và Việt Nam, liên kết với 谈 (đàm thoại).", "Tự nguyên_Xie": "Theo Wiktionary, 譚 (dạng phồn thể của 谭) là hình thanh. Nghĩa chính là dạng thay thế của 談 (bàn luận), dùng phổ biến làm họ tên (họ Đàm). Trong văn cổ có nghĩa ''nói lớn'', ''bàn chuyện''. Hán-Việt đọc là ''đàm''. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "to lớn; bàn bạc; trễ tràng; họ Đàm", "Hạng Tần Suất (Jun Da)": "2140.0", "Tần Suất % (Jun Da)": "97.6101690043", "GavinGrover_Once (Chiết tự trực tiếp)": "讠 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰讠", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "谭", "Unihan_Traditional (Chữ Phồn thể)": "譚", "Pinyin_Xie": "tán", "Âm Hán Việt_Xie": "đàm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường dùng làm động từ chỉ việc đàm luận, nói chuyện hoặc dùng làm danh từ chỉ họ Đàm. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('亨', '{"9000": "2141.0", "Chữ Trung Quốc": "亨", "Bộ thủ & thành phần_Xie": "Bộ thủ | 亠 | Số nét | 7 | nét | 亨 | hanh | tượng hình | hình ảnh miếu tổ tiên — cả chữ tự thân là tượng hình | 亨 là tượng hình (象形): theo Wiktionary, đây là hình ảnh miếu thờ tổ tiên. Không có bộ thủ phân tách rõ ràng — toàn bộ chữ mô tả ngôi miếu với mái (亠), cửa (口) và nền (了). Nghĩa gốc: thông suốt, hanh thông (lễ tế thuận lợi).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hanh\": miếu tổ tiên 亨 tế lễ hanh thông — mọi việc thuận lợi, vận hanh thông. | Gương Hán-Việt | hanh thông (亨通 — thuận lợi), vận hanh (運亨 — vận tốt) | Mở khoá kiến thức | Biết 亨 mở khoá thành ngữ may mắn: 萬事亨通 (vạn sự hanh thông), 財運亨通 (tài vận hanh thông).", "Tự nguyên_Xie": "Đại triện | Theo Wiktionary, 亨 là tượng hình (象形) — hình ảnh một ngôi miếu thờ tổ tiên. Nghĩa gốc liên quan đến lễ tế diễn ra suôn sẻ, từ đó mở rộng thành ''hanh thông, thuận lợi''. Âm đọc cổ liên hệ với 享 (hưởng) và 烹 (nấu). Hán-Việt: ''hanh''. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1552.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Cao (1392) Liễu (617)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Cao (số 1392 - cao lớn/viết giảm nét) ở trên chữ Liễu (số 617 - xong rồi/ 了). Giải thích sự chuyển ý: Hanh là thông suốt, trôi chảy không bị vướng mắc, thuận lợi, làm ăn suôn sẻ (hanh thông, vạn sự hanh thông).", "Nghĩa Tiếng Việt_Xie": "thông", "Hạng Tần Suất (Jun Da)": "2141.0", "Tần Suất % (Jun Da)": "97.6131896135", "GavinGrover_Once (Chiết tự trực tiếp)": "No glyph available + 了", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱了", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "亨", "Unihan_Traditional (Chữ Phồn thể)": "亨", "Pinyin_Xie": "hēng", "Âm Hán Việt_Xie": "hanh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường làm tính từ bổ nghĩa cho sự việc, biểu thị sự suôn sẻ, thuận lợi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('钦', '{"9000": "2142.0", "Chữ Trung Quốc": "钦", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 9 | nét | 钅 | kim | biểu nghĩa | kim loại | 欠 | khiếm | biểu âm | thiếu, cúi người | 钦 là chữ hình thanh (phồn thể 欽): 金/钅 (Kim) biểu nghĩa — kim loại quý; 欠 (Khiếm) biểu âm. Nghĩa gốc: kính trọng, của vua ban.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khâm\": vàng 钅 cúi 欠 kính trọng — khâm phục, cúi mình trước điều quý giá như vàng. | Gương Hán-Việt | \"khâm\" trong \"khâm phục\" (钦佩), \"khâm sai\" (钦差) | Mở khoá kiến thức | Biết 钦 (khâm) mở khoá: 钦佩 (khâm phục), 钦差 (quan đặc phái), 钦点 (được vua chỉ định).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 钦 (phồn thể 欽) là hình thanh có thể hội ý: 金 (quý giá, biểu nghĩa) + 欠 (cúi người, biểu âm). Nghĩa gốc: kính trọng, ngưỡng mộ. Mở rộng: của vua ban (钦差), ngưỡng mộ (钦佩). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "của vua, thuộc về vua", "Hạng Tần Suất (Jun Da)": "2142.0", "Tần Suất % (Jun Da)": "97.6162076386", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 欠", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅欠", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "欠", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "钦", "Unihan_Traditional (Chữ Phồn thể)": "欽", "Pinyin_Xie": "qīn", "Âm Hán Việt_Xie": "khâm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Thường làm tính từ chỉ những gì thuộc về vua chúa hoặc động từ thể hiện sự kính trọng. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('庸', '{"9000": "2143.0", "Chữ Trung Quốc": "庸", "Bộ thủ & thành phần_Xie": "Bộ thủ | 广 | Số nét | 11 | nét | 广 | nghiễm | biểu hình | mái hiên, toà nhà rộng | 肀 | duật | biểu hình | bút viết | 月 | nguyệt | biểu hình | trăng, thân chuông | 庸 là chữ hình thanh phức hợp: 庚 (tỉnh lược, biểu nghĩa) + 同/用 (biểu âm). Theo Wiktionary có thể là dạng gốc của 鏞 (chuông lớn). Nghĩa gốc: dùng cho, thuê mướn. Mở rộng: tầm thường, bình phàm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"dung\": không nổi bật, dung bình thường — dung tục, tầm thường, trung dung không cực đoan. | Gương Hán-Việt | \"dung\" trong \"trung dung\" (中庸), \"dung tục\" (庸俗) | Mở khoá kiến thức | Biết 庸 (dung) mở khoá: 庸俗 (tầm thường), 中庸 (trung dung), 平庸 (tầm thường), 庸才 (người tài thường).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 庸 là hình thanh (và có thể hội ý): 庚 (biểu nghĩa, tỉnh lược) + 同/用 (biểu âm). Có thể là dạng gốc của 鏞 (chuông lớn nghi lễ). Nghĩa gốc: sử dụng, thuê mướn. Mở rộng: thường thường (中庸), tầm thường (庸俗), vô dụng (庸才). | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nước Dong, nước Dung đời Chu (nay ở phía bắc huyện Cấp, tỉnh Hà Nam của Trung Quốc)", "Hạng Tần Suất (Jun Da)": "2143.0", "Tần Suất % (Jun Da)": "97.6192230799", "GavinGrover_Once (Chiết tự trực tiếp)": "广 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴广", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "庸", "Unihan_Traditional (Chữ Phồn thể)": "庸", "Pinyin_Xie": "yōng", "Âm Hán Việt_Xie": "dung", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường làm tính từ đứng trước danh từ để chỉ sự tầm thường, không có gì nổi bật. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('歉', '{"9000": "2144.0", "Chữ Trung Quốc": "歉", "Bộ thủ & thành phần_Xie": "Bộ thủ | 欠 | Số nét | 14 | nét | 兼 | kiêm | biểu âm | gợi âm ''qiàn'' | 欠 | khiếm | biểu nghĩa | người mở miệng — thiếu, khuyết | 歉 = 兼 (Kiêm, biểu âm) + 欠 (Khiếm, biểu nghĩa: thiếu, khuyết). Chữ hình thanh: thiếu, kém, không đủ — nghĩa ''thiếu, kém, thất bát, áy náy, xin lỗi''.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt ''Khiểm'': khi mình thiếu / kém (欠) đối với người khác — đó là ''khiểm'', là áy náy, xin lỗi. | Gương Hán-Việt | ''Khiểm'' trong khiểm thiệt (mất mùa), khiểm nhã (kém nhã); thường dùng để dịch ''xin lỗi'' (道歉). | Mở khoá kiến thức | Biết 歉 mở khóa 抱歉 (bão khiểm / xin lỗi), 道歉 (đạo khiểm / xin lỗi), 歉意 (khiểm ý / lời xin lỗi).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 歉 là chữ hình thanh: 欠 biểu nghĩa ''thiếu'', 兼 biểu âm. Nghĩa gốc ''thất bát, thiếu, kém''; mở rộng thành ''áy náy, xin lỗi'' (歉意). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đói, kém, thiếu", "Hạng Tần Suất (Jun Da)": "2144.0", "Tần Suất % (Jun Da)": "97.6222374876", "GavinGrover_Once (Chiết tự trực tiếp)": "兼 + 欠", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰兼欠", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "兼", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "欠", "Unihan_Simplified (Chữ Giản thể)": "歉", "Unihan_Traditional (Chữ Phồn thể)": "歉", "Pinyin_Xie": "qiàn", "Âm Hán Việt_Xie": "khiểm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Chữ này thường làm tính từ chỉ sự thiếu hụt hoặc kết hợp tạo danh từ chỉ lòng tự hổ thẹn. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('芝', '{"9000": "2145.0", "Chữ Trung Quốc": "芝", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 6 | nét | 艹 | thảo | biểu nghĩa | cỏ, thực vật | 之 | chi | biểu âm | cho âm zhī | 芝 = 艹(Thảo, biểu nghĩa: thực vật) + 之 (Chi, biểu âm); chữ hình thanh. Bộ 艹xác định đây là loại thực vật, phần 之 cho âm đọc zhī.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chi\": nấm 芝 chi quý — linh chi (靈芝) mọc trên cây cổ thụ, biểu tượng trường sinh. | Gương Hán-Việt | linh chi (靈芝 — nấm linh chi), chi ma (芝麻 — vừng) | Mở khoá kiến thức | Biết 芝 mở khoá: 靈芝 (linh chi — nấm thuốc), 芝麻 (chi ma — vừng), 芝士 (phô mai — phiên âm).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 芝 là hình thanh: 艸/艹 (cỏ, biểu nghĩa) + 之 (biểu âm) — chỉ một loại thực vật. Nghĩa chính là linh chi (靈芝, Ganoderma), nấm thuốc quý trong y học cổ truyền. Cũng dùng trong 芝麻 (vừng/mè) và tên địa danh 芝加哥 (Chicago). Hán-Việt: ''chi''. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "một loại cỏ thơm", "Hạng Tần Suất (Jun Da)": "2145.0", "Tần Suất % (Jun Da)": "97.6252513785", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 之", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹之", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "之", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "芝", "Unihan_Traditional (Chữ Phồn thể)": "芝", "Pinyin_Xie": "zhī", "Âm Hán Việt_Xie": "chi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ để chỉ các loại nấm quý hoặc cỏ thơm trong văn học cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('吼', '{"9000": "2146.0", "Chữ Trung Quốc": "吼", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 7 | nét | 口 | khẩu | biểu nghĩa | miệng | 孔 | khổng | biểu âm | lỗ, họng | 吼 là chữ hình thanh: 口 (Khẩu) biểu nghĩa — miệng; 孔 (Khổng) biểu âm. Nghĩa gốc: rống lên, hét to.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hống\": miệng 口 khổng 孔 rỗng to — hống hách, gầm hét vang lên như hổ. | Gương Hán-Việt | \"hống\" trong \"hống hách\", \"tiếng hống\" | Mở khoá kiến thức | Biết 吼 (hống) mở khoá: 狮吼 (sư tử gầm), 怒吼 (hét giận dữ), 咆哮 (gầm thét).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 吼 là hình thanh: 口 (miệng, biểu nghĩa) + 孔 (biểu âm). Nghĩa gốc: rống, gầm thét (tiếng thú). Mở rộng: la hét, hét lên. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "rống, kêu to", "Hạng Tần Suất (Jun Da)": "2146.0", "Tần Suất % (Jun Da)": "97.6282559673", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 孔", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口孔", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "孔", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "吼", "Unihan_Traditional (Chữ Phồn thể)": "吼", "Pinyin_Xie": "hǒu", "Âm Hán Việt_Xie": "hống", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường làm động từ đứng trước tân ngữ hoặc đứng độc lập để miêu tả tiếng kêu lớn. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | hǒu | / | gầm thét | Xuất hiện trong lộ trình | HSK | HSK 6 | · | Sinh học | New HSK | New HSK 7-9 | · | Âm thanh", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('甫', '{"9000": "2147.0", "Chữ Trung Quốc": "甫", "Bộ thủ & thành phần_Xie": "Bộ thủ | 用 | Số nét | 7 | nét | 甫 | phủ | tượng hình | hình ảnh vườn cây với cây non mọc trên ruộng | 甫 là hội ý trong giáp cốt văn: 屮 (cây non) + 田 (ruộng) — khu vườn trồng rau. Dạng hiện đại đã biến dạng, các thành phần hợp nhất thành một hình. Nghĩa gốc: vườn tược (nguyên hình của 圃). Về sau dùng làm mỹ xưng cho đàn ông.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phủ\": vườn 甫 mới gieo xong — cây 屮 trên ruộng 田 vừa nảy mầm, dùng khen đàn ông tài giỏi. | Gương Hán-Việt | đại phủ (大甫 — mỹ xưng người lớn tuổi); trong địa danh: Lữ Phủ (呂甫) | Mở khoá kiến thức | Biết 甫 mở khoá: âm phủ trong tên người cổ điển (Đỗ Phủ — 杜甫), và chữ 圃 (vườn rau).", "Tự nguyên_Xie": "Giáp cốt văn | Kim văn | Đại triện | Theo Wiktionary, trong giáp cốt văn 甫 là hội ý: 屮 (cây non, biểu nghĩa) + 田 (ruộng) — vườn rau, dạng gốc của 圃 (vườn). Trong kim văn, các bộ phận biến dạng thành 父 (biểu âm) + 用, tạo thành chữ hình thanh. Dạng hiện đại tiếp tục biến dạng, các thành phần hợp nhất. Nghĩa phái sinh: ''mới vừa'', mỹ xưng cho đàn ông. Hán-Việt: ''phủ''. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "783.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thốn (051) Dụng (117)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Thốn (số 051 - bàn tay/tấc) viết ngược và chữ Dụng (số 117 - dùng). Các cụ già có nhiều kinh nghiệm sử dụng bàn tay rất tinh vi (điều tinh vi thể hiện qua chữ Thốn viết ngược). Giải thích sự chuyển ý: Đây là chữ Hội ý. Phủ là tiếng gọi tôn xưng người đàn ông lớn tuổi.", "Nghĩa Tiếng Việt_Xie": "(tiếng mỹ xưng của đàn ông)", "Hạng Tần Suất (Jun Da)": "2147.0", "Tần Suất % (Jun Da)": "97.631255905", "GavinGrover_Once (Chiết tự trực tiếp)": "No glyph available + 丶", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴丶", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "甫", "Unihan_Traditional (Chữ Phồn thể)": "甫", "Pinyin_Xie": "fǔ", "Âm Hán Việt_Xie": "phủ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Phó từ | 副词 | Danh từ | 名词 | Thường làm phó từ đứng trước động từ để chỉ hành động vừa mới bắt đầu xảy ra. | Phó từ | 副词 | Bổ nghĩa cho động từ hoặc tính từ và luôn đứng TRƯỚC chúng — 都是, 很好. Không đứng sau như tiếng Việt và không bổ nghĩa cho danh từ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('衫', '{"9000": "2148.0", "Chữ Trung Quốc": "衫", "Bộ thủ & thành phần_Xie": "Bộ thủ | 衣 | Số nét | 8 | nét | 衤 | y | biểu nghĩa | áo (biến thể của 衣) | 彡 | sam | biểu âm | ba nét, vẻ trang sức | 衫 = 衤 (Y, biểu nghĩa: áo) + 彡 (Sam, biểu âm và gợi ý nếp gấp); chữ hình thanh — một loại áo mỏng đơn lớp.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sam\": áo 衤 có nếp 彡 — áo mỏng một lớp, là sam, là sơ mi. | Gương Hán-Việt | Dùng trong ''sam áo'', ''sấn sam'' (衬衫, áo sơ mi). | Mở khoá kiến thức | Biết 衫 mở khoá từ vựng trang phục tiếng Trung: 衬衫 (sơ mi), T 恤衫 (áo phông), 长衫 (áo dài).", "Tự nguyên_Xie": "Đại triện | Tiểu triện | Theo Wiktionary, 衫 là chữ hình thanh: bộ 衤 (vạt áo, biến thể của 衣) cho nghĩa, 彡 cho âm và cũng gợi ý nếp gấp/đường vân của vải. Nghĩa gốc ''áo đơn lớp không lót'', mở rộng thành ''áo sơ mi, áo lót'' nói chung trong tiếng Trung hiện đại (衬衫, T 恤衫). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "áo đơn", "Hạng Tần Suất (Jun Da)": "2148.0", "Tần Suất % (Jun Da)": "97.6342542923", "GavinGrover_Once (Chiết tự trực tiếp)": "衤 + 彡", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰衤彡", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "彡", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "衤", "Unihan_Simplified (Chữ Giản thể)": "衫", "Unihan_Traditional (Chữ Phồn thể)": "衫", "Pinyin_Xie": "shān", "Âm Hán Việt_Xie": "sam", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Làm danh từ chỉ các loại áo mặc ở phần thân trên, thường kết hợp với các từ khác. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('摊', '{"9000": "2149.0", "Chữ Trung Quốc": "摊", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 13 | nét | 扌 | thủ | biểu nghĩa | tay, hành động bằng tay | 难 | nan | biểu âm | khó khăn (cho âm tān) | 摊 = 扌(Thủ, biểu nghĩa: tay) + 难 (Nan, biểu âm); chữ hình thanh. Bộ thủ cho biết nghĩa liên quan đến hành động bằng tay; 难 cho âm. Đây là dạng giản thể của 攤 (thay 難 bằng 难).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"than\": tay (扌) trải ra quầy hàng, than thở vì bán ế — nhớ 摊 là bày hàng, san sẻ. | Gương Hán-Việt | than trong 摊牌 (than bài — lật bài ngửa) | Mở khoá kiến thức | Biết 摊 (than) mở khoá: 摊牌 (lật bài), 摊贩 (người bán hàng rong), 摊位 (quầy hàng).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 摊 là giản thể của 攤. Theo Wiktionary, 攤 là chữ hình thanh: bộ 手 (扌) biểu nghĩa hành động tay, còn 難 (giản: 难) biểu âm. Nghĩa gốc là trải ra, giăng ra bằng tay; sau mở rộng sang nghĩa quầy hàng (nơi bày hàng ra). | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "hàng quán", "Hạng Tần Suất (Jun Da)": "2149.0", "Tần Suất % (Jun Da)": "97.6372506125", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 难", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌难", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "难", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "摊", "Unihan_Traditional (Chữ Phồn thể)": "攤", "Pinyin_Xie": "tān", "Âm Hán Việt_Xie": "than", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường làm động từ chỉ hành động bày biện hàng hóa hoặc làm danh từ chỉ quầy hàng nhỏ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | Từ ghép nghĩa | / | tān | / | trải ra | / | tān | / | quầy hàng | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Thương mại và kinh doanh II | New HSK 7-9 | · | Thứ tự và cấu trúc", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('宴', '{"9000": "2150.0", "Chữ Trung Quốc": "宴", "Bộ thủ & thành phần_Xie": "Bộ thủ | 宀 | Số nét | 10 | nét | 宀 | miên | biểu nghĩa | mái nhà, nơi che chở | 妟 | biểu âm | gồm 日 (nhật) + 女 (nữ) | 宴 = 宀 (Miên, biểu nghĩa: mái nhà) + 妟 (biểu âm, gồm 日+女); chữ hình thanh. Mái nhà che chở cho cuộc vui yên bình bên trong — tiệc tùng tổ chức trong gia đình, nơi an lành.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"yến\": dưới mái nhà 宀 (miên) sum vầy bên nắng 日 và nữ 女 — 宴 tiệc yến sum họp ấm cúng. | Gương Hán-Việt | yến trong ''yến tiệc'' (tiệc lớn), ''yến hội'' | Mở khoá kiến thức | Biết 宴 (yến) mở khoá: 宴会 (tiệc/buổi dạ tiệc), 宴席 (tiệc ngồi), 晚宴 (tiệc tối).", "Tự nguyên_Xie": "Kim văn | Tiểu triện | Lục thư thông | Theo Wiktionary, 宴 là chữ hình thanh (psc): 宀 (miên, biểu nghĩa: mái nhà) + 妟 (biểu âm). Glyph cổ gợi hình ảnh người phụ nữ bên ánh nắng dưới mái nhà — khung cảnh bình yên, tiệc mừng gia đình. Nguồn cũng liên hệ với 安 (an, bình yên). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "85.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Miên (68) Nhật (80) Nữ (60)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Dưới chữ Miên (số 68) có chữ Nhật (số 80) và chữ Nữ (số 60) . Ngày (nhật) người con gái về nhà chồng, bố mẹ mở tiệc đãi họ hàng.", "Nghĩa Tiếng Việt_Xie": "yến tiệc", "Hạng Tần Suất (Jun Da)": "2150.0", "Tần Suất % (Jun Da)": "97.6402469328", "GavinGrover_Once (Chiết tự trực tiếp)": "宀 + 妟", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱宀妟", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "妟", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "宀", "Unihan_Simplified (Chữ Giản thể)": "宴", "Unihan_Traditional (Chữ Phồn thể)": "宴", "Pinyin_Xie": "yàn", "Âm Hán Việt_Xie": "yến", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường làm danh từ chỉ bữa tiệc lớn hoặc làm động từ với nghĩa chiêu đãi tiệc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('嘱', '{"9000": "2151.0", "Chữ Trung Quốc": "嘱", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 15 | nét | 口 | khẩu | biểu nghĩa | miệng, lời nói | 属 | thuộc | biểu âm | thuộc về (cho âm zhǔ) | 嘱 = 口 (Khẩu, biểu nghĩa: miệng) + 属 (Thuộc, biểu âm); chữ hình thanh. Bộ khẩu chỉ đây là hành vi ngôn ngữ — dặn dò bằng lời; 属 cung cấp âm đọc (zhǔ).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chúc\": miệng (口) dặn dò người thân — như lời chúc cuối cùng trước khi đi xa, nhớ 嘱 là căn dặn. | Gương Hán-Việt | chúc trong 嘱咐 (chúc phó — dặn dò, căn dặn) | Mở khoá kiến thức | Biết 嘱 (chúc) mở khoá: 嘱咐 (căn dặn), 叮嘱 (nhắc đi nhắc lại), 遗嘱 (di chúc).", "Tự nguyên_Xie": "嘱 (phồn thể 囑) là chữ hình thanh: theo Wiktionary, bộ 口 biểu nghĩa (miệng/lời nói), còn 屬 biểu âm. Nghĩa gốc là dặn dò, căn dặn, sau mở rộng sang ủy thác, di ngôn. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "dặn dò", "Hạng Tần Suất (Jun Da)": "2151.0", "Tần Suất % (Jun Da)": "97.6432380851", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 属", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口属", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "属", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "嘱", "Unihan_Traditional (Chữ Phồn thể)": "囑", "Pinyin_Xie": "zhǔ", "Âm Hán Việt_Xie": "chúc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường làm động từ đứng trước tân ngữ chỉ người để thể hiện sự dặn dò, nhắn nhủ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('衷', '{"9000": "2152.0", "Chữ Trung Quốc": "衷", "Bộ thủ & thành phần_Xie": "Bộ thủ | 衣 | Số nét | 10 | nét | 亠 | đầu | biểu hình | phần trên của áo | 中 | trung | biểu nghĩa+âm | ở giữa — nội tâm bên trong | 𧘇 | ấy | biểu hình | phần dưới của áo (bộ y) | 衷 = 衣 (Y, biểu nghĩa: áo) + 中 (Trung, biểu nghĩa và âm); chữ hội ý (và đồng thời có yếu tố âm). Theo Wiktionary, 衷 là 衣 bao bọc 中, gợi ý ''phần giữa trong áo'' — tức tâm can bên trong. Cấu trúc thực tế: chữ 中 nằm bên trong vỏ 衣 (亠 + 𧘇).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trung\": chữ 中 (trung tâm) nằm trong vải áo (衣) — lòng thành thật ở chính giữa tâm can. | Gương Hán-Việt | trung trong 衷心 (trung tâm — từ đáy lòng) | Mở khoá kiến thức | Biết 衷 (trung) mở khoá: 衷心 (tận tâm), 初衷 (ý định ban đầu), 无动于衷 (thờ ơ), 由衷 (từ đáy lòng).", "Tự nguyên_Xie": "Theo Wiktionary, 衷 là chữ hội ý: 衣 (áo) bao quanh 中 (ở giữa), hàm ý ''lòng bên trong'', tức tâm tư thật sự. Cũng có thể phân tích là hình thanh (衣 biểu nghĩa, 中 biểu âm). Nghĩa gốc là nội tâm, lòng chân thật. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tốt, lành; ngay thẳng", "Hạng Tần Suất (Jun Da)": "2152.0", "Tần Suất % (Jun Da)": "97.64622562", "GavinGrover_Once (Chiết tự trực tiếp)": "衣 + 中", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴衣中", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "中", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "衣", "Unihan_Simplified (Chữ Giản thể)": "衷", "Unihan_Traditional (Chữ Phồn thể)": "衷", "Pinyin_Xie": "zhōng", "Âm Hán Việt_Xie": "trung", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Thường làm danh từ chỉ tâm can, lòng dạ bên trong hoặc làm tính từ chỉ sự chân thành. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('娇', '{"9000": "2153.0", "Chữ Trung Quốc": "娇", "Bộ thủ & thành phần_Xie": "Bộ thủ | 女 | Số nét | 9 | nét | 女 | nữ | biểu nghĩa | nữ tính, phụ nữ | 乔 | kiều | biểu âm | cao, kiều diễm (cho âm jiāo) | 娇 = 女 (Nữ, biểu nghĩa) + 乔 (Kiều, biểu âm); chữ hình thanh. Đây là giản thể của 嬌. Bộ nữ chỉ nét duyên dáng của người phụ nữ; 乔 cung cấp âm đọc (jiāo).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"kiều\": người con gái (女) kiều diễm (乔/kiều) được nuông chiều — nhớ 娇 là mong manh, yêu chiều. | Gương Hán-Việt | kiều trong 娇气 (kiều khí — tính mong manh, hay nhõng nhẽo) | Mở khoá kiến thức | Biết 娇 (kiều) mở khoá: 娇气 (hay nhũng nhẽo), 娇惯 (nuông chiều), 娇嫩 (mềm mại).", "Tự nguyên_Xie": "娇 là giản thể của 嬌, thay thành phần 喬 bằng 乔. Theo Wiktionary, 嬌 là chữ hình thanh: bộ 女 biểu nghĩa (nữ tính, duyên dáng), 喬 biểu âm. Nghĩa gốc là mềm mại, kiều diễm; sau mở rộng sang nghĩa được nuông chiều, mong manh. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mềm mại đáng yêu; nũng nịu", "Hạng Tần Suất (Jun Da)": "2153.0", "Tần Suất % (Jun Da)": "97.6492085038", "GavinGrover_Once (Chiết tự trực tiếp)": "女 + 乔", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰女乔", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "乔", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "女", "Unihan_Simplified (Chữ Giản thể)": "娇", "Unihan_Traditional (Chữ Phồn thể)": "嬌", "Pinyin_Xie": "jiāo", "Âm Hán Việt_Xie": "kiều", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường làm tính từ miêu tả vẻ đẹp mềm mại, đáng yêu của phụ nữ hoặc trẻ em. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('陕', '{"9000": "2154.0", "Chữ Trung Quốc": "陕", "Bộ thủ & thành phần_Xie": "Bộ thủ | 阜 | Số nét | 8 | nét | 阝 | phụ | biểu nghĩa | địa hình, đất cao | 夹 | giáp | biểu âm | cho âm shǎn (giản lược từ 㚒) | 陕 là giản thể của 陝: 阜/阝(Phụ, biểu nghĩa: địa hình) + 㚒/夹 (biểu âm). Chữ hình thanh dùng chủ yếu trong địa danh 陕西 (Thiểm Tây). Dạng giản thể xuất hiện đầu tiên trong bi ký thời Hán.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thiểm\": đất 阝bị kẹp 夹 giữa hai phía núi — như tỉnh Thiểm Tây nằm giữa hai vùng cao nguyên. | Gương Hán-Việt | Thiểm Tây (陕西 — tên tỉnh), Quan Trung (關中 — vùng đất Thiểm Tây cổ) | Mở khoá kiến thức | Biết 陕 chủ yếu mở khoá địa danh: 陕西 (Thiểm Tây — quê hương Tần Thuỷ Hoàng), 陕北 (Thiểm Bắc).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Theo Wiktionary, 陕 là giản thể của 陝: thay 㚒 bằng 夹. Đây là biến thể được dùng trong bi ký (碑别字) thời Hán, xuất hiện lần đầu trong 張遷碑. Nghĩa duy nhất là địa danh 陝西 (tỉnh Thiểm Tây). Hán-Việt: ''thiểm''. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tên gọi tắt của tỉnh Thiểm Tây của Trung Quốc", "Hạng Tần Suất (Jun Da)": "2154.0", "Tần Suất % (Jun Da)": "97.6521898372", "GavinGrover_Once (Chiết tự trực tiếp)": "阝 + 夹", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰阝夹", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "夹", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "阝", "Unihan_Simplified (Chữ Giản thể)": "陕", "Unihan_Traditional (Chữ Phồn thể)": "陝", "Pinyin_Xie": "shǎn", "Âm Hán Việt_Xie": "thiểm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ riêng để chỉ tỉnh Thiểm Tây của Trung Quốc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('矩', '{"9000": "2155.0", "Chữ Trung Quốc": "矩", "Bộ thủ & thành phần_Xie": "Bộ thủ | 矢 | Số nét | 9 | nét | 矢 | thỉ | biểu hình (do biến đổi) | vốn là 大/夫 — người cầm thước | 巨 | cự | biểu hình (giản hoá muộn) | hình cái thước thợ | 矩 vốn là tượng hình một người cầm thước thợ (carpenter''s square). Phần 大 dần bị viết thành 夫 rồi 矢; 巨 là dạng giản hoá muộn của hình thước. Thuyết Văn nhầm xem là hội ý. Đây vốn là chữ tượng hình bị biến dạng nhiều.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"củ\": 矢 (vốn là người cầm) + 巨 (thước thợ) — thước thợ đo góc vuông, đúng nghĩa ''khuôn mẫu, quy tắc'' trong 规矩 (quy củ, quy tắc). | Gương Hán-Việt | ''củ'' trong ''quy củ'' — y nghĩa ''khuôn phép'' trong tiếng Việt | Mở khoá kiến thức | Nắm 矩 mở khoá từ HSK 5: 规矩, và liên hệ thành ngữ 没有规矩不成方圆.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary (Chen 2021), 矩 là tượng hình một người cầm thước thợ. Phần 大 trong nguyên gốc dần bị viết thành 夫 rồi 矢; 巨 là dạng giản hoá muộn của hình thước thợ. Thuyết Văn nhầm xem 矩 là chữ hội ý. Nghĩa gốc ''thước vuông góc của thợ mộc'', mở rộng sang nghĩa trừu tượng ''khuôn phép, quy tắc'' trong 规矩. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái khuôn; khuôn phép", "Hạng Tần Suất (Jun Da)": "2155.0", "Tần Suất % (Jun Da)": "97.6551696203", "GavinGrover_Once (Chiết tự trực tiếp)": "矢 + 巨", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰矢巨", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "巨", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "矢", "Unihan_Simplified (Chữ Giản thể)": "矩", "Unihan_Traditional (Chữ Phồn thể)": "榘", "Pinyin_Xie": "jǔ", "Âm Hán Việt_Xie": "củ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ để chỉ các quy tắc, phép tắc ứng xử trong đời sống. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('浦', '{"9000": "2156.0", "Chữ Trung Quốc": "浦", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 10 | nét | 氵 | thuỷ | biểu nghĩa | nước, sông | 甫 | phủ | biểu âm | cho âm pǔ | 浦 = 氵(Thuỷ, biểu nghĩa: nước/sông) + 甫 (Phủ, biểu âm); chữ hình thanh. Bộ 氵xác định nghĩa liên quan đến nước, phần 甫 cho âm đọc pǔ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phổ\": bến sông 浦 có nước 氵và đất 甫 — phổ biến trong địa danh vùng sông nước Giang Nam. | Gương Hán-Việt | Phổ Đông (浦东 — khu Phố Đông Thượng Hải), Hoàng Phổ (黄浦 — sông Hoàng Phố) | Mở khoá kiến thức | Biết 浦 mở khoá địa danh quan trọng: 浦东 (Phố Đông), 黄浦 (Hoàng Phổ), 上浦 (Thượng Phổ).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 浦 là hình thanh: 水/氵 (nước, biểu nghĩa) + 甫 (biểu âm). Nghĩa gốc là bờ sông, bến nước, cửa sông — nơi nước và đất gặp nhau. Dùng nhiều trong địa danh ở vùng đồng bằng sông nước như 浦东 (Phố Đông — Thượng Hải). Hán-Việt: ''phổ''. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bến sông; cửa sông; ven sông", "Hạng Tần Suất (Jun Da)": "2156.0", "Tần Suất % (Jun Da)": "97.6581494034", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 甫", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵甫", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "甫", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "浦", "Unihan_Traditional (Chữ Phồn thể)": "浦", "Pinyin_Xie": "pǔ", "Âm Hán Việt_Xie": "phố", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này thường dùng làm danh từ để chỉ bến sông hoặc xuất hiện trong các địa danh. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('讶', '{"9000": "2157.0", "Chữ Trung Quốc": "讶", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 6 | nét | 讠 | biểu nghĩa | lời nói (bộ ngôn giản thể) | 牙 | nha | biểu âm | răng (cho âm yà) | 讶 = 讠(Ngôn, biểu nghĩa: lời nói) + 牙 (Nha, biểu âm); chữ hình thanh. Đây là giản thể của 訝. Bộ ngôn chỉ đây là phản ứng ngôn ngữ khi ngạc nhiên; 牙 cung cấp âm (yà).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ngạc\": miệng (讠) há ra ''ồ'' như thấy răng nanh (牙) khổng lồ — ngạc nhiên đến bật lời. | Gương Hán-Việt | ngạc trong 惊讶 (kinh ngạc — ngạc nhiên, sửng sốt) | Mở khoá kiến thức | Biết 讶 (ngạc) mở khoá: 惊讶 (kinh ngạc), 诧异 (ngạc nhiên), 讶异 (kinh ngạc).", "Tự nguyên_Xie": "讶 là giản thể của 訝, thay 訁 bằng 讠. Theo Wiktionary, 訝 là chữ hình thanh: bộ 言 biểu nghĩa (lời nói, phản ứng bằng lời), 牙 biểu âm. Nghĩa gốc là ngạc nhiên, lấy làm lạ. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nghi ngờ, thấy lạ", "Hạng Tần Suất (Jun Da)": "2157.0", "Tần Suất % (Jun Da)": "97.6611260858", "GavinGrover_Once (Chiết tự trực tiếp)": "讠 + 牙", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰讠牙", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "牙", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "讠", "Unihan_Simplified (Chữ Giản thể)": "讶", "Unihan_Traditional (Chữ Phồn thể)": "訝", "Pinyin_Xie": "yà", "Âm Hán Việt_Xie": "nhạ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Thường dùng làm động từ biểu thị sự kinh ngạc hoặc làm tính từ trong các từ ghép. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('耸', '{"9000": "2158.0", "Chữ Trung Quốc": "耸", "Bộ thủ & thành phần_Xie": "Bộ thủ | 耳 | Số nét | 10 | nét | 从 | tòng | biểu âm | theo, cùng theo (cho âm sǒng) | 耳 | nhĩ | biểu nghĩa | tai — lắng nghe, chú ý | 耸 = 从 (Tòng, biểu âm) + 耳 (Nhĩ, biểu nghĩa); chữ hình thanh (phồn thể 聳). Bộ nhĩ liên quan đến tai, hàm ý ''làm người ta lắng tai'' hay ''vươn thẳng lên trên''; 从 cung cấp âm (sǒng).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tủng\": tai (耳) dựng đứng lên vì sợ — như tòa nhà tủng cao vút trời. | Gương Hán-Việt | tủng trong 耸立 (tủng lập — vươn thẳng lên, đứng sừng sững) | Mở khoá kiến thức | Biết 耸 (tủng) mở khoá: 耸立 (đứng sừng sững), 耸肩 (nhún vai), 危言耸听 (lời nói gây kinh sợ).", "Tự nguyên_Xie": "耸 (phồn thể 聳) là chữ hình thanh: theo Wiktionary, 從 biểu âm, 耳 biểu nghĩa. Nghĩa gốc: khiến tai dựng lên (sợ hãi, kinh sợ), sau mở rộng sang nghĩa vươn cao, dựng đứng. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cao thẳng lên, cao vót; nhún; ghê, rợn; thủng; như \"thủng thẳng; thủng lỗ\" (gdhn) tủng; như \"tủng (sừng sững; doạ cho sợ)\" (gdhn)(Động) Đứng thẳng lên; đứng sừng sững; nhô lên cao. ◎Như: tủng kiên 聳肩 nhún vai. ◇Đào Uyên Minh 陶淵明: Lăng sầm tủng dật phong; Diêu chiêm giai kì tuyệt 陵岑聳逸峰; 遙瞻皆奇絕 (Họa Quách Chủ Bộ 遊斜川) Gò núi sừng sững đỉnh cao; Xa ngắm đều đẹp vô cùng.(Động) Khen ngợi; khuyến khích; tán dương. ◇Quốc ngữ 國學: Nhi vi chi tủng thiện; nhi ức ác yên 而為之聳善; 而抑惡焉 (Sở ngữ thượng 楚語上) Để tán dương đức lành; mà đè nén điều xấu vậy.(Động) Sợ hãi; kinh động. ◎Như: tủng cụ 聳懼 kinh sợ; tủng nhân thính văn 聳人聽聞 làm cho kinh hoàng sửng sốt. § Cũng viết là 悚懼. ◇Tô Thức 蘇軾: Dư kí tủng nhiên dị chi 余既聳然異之 (Phương Sơn Tử truyện 方山子傳) Tôi lấy làm kinh dị.(Tính) Điếc.(Tính) Cao; chót vót. ◇Giản Văn Đế 簡文帝: Tủng lâu bài thụ xuất; Khích điệp đái giang thanh 聳樓排樹出; 郤堞帶江清 (Đăng phong hỏa lâu 登烽火樓) Lầu cao bày ra rừng cây; Tường thấp đeo dải sông xanh.", "Hạng Tần Suất (Jun Da)": "2158.0", "Tần Suất % (Jun Da)": "97.6641017346", "GavinGrover_Once (Chiết tự trực tiếp)": "从 + 耳", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱从耳", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "从", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "耳", "Unihan_Simplified (Chữ Giản thể)": "耸", "Unihan_Traditional (Chữ Phồn thể)": "聳", "Pinyin_Xie": "sǒng", "Âm Hán Việt_Xie": "tủng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Thường dùng làm động từ chỉ hành động nhún vai hoặc làm tính từ miêu tả ngọn núi cao vút. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | sǒng | / | cao lên | / | sǒng | / | kích động | Xuất hiện trong lộ trình | HSK | HSK 6 | · | Hành vi II", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('裸', '{"9000": "2159.0", "Chữ Trung Quốc": "裸", "Bộ thủ & thành phần_Xie": "Bộ thủ | 衣 | Số nét | 13 | nét | 衤 | y | biểu nghĩa | quần áo | 果 | quả | biểu âm | cho âm luǒ | 裸 = 衤(Y, biểu nghĩa: quần áo) + 果 (Quả, biểu âm); chữ hình thanh. Bộ 衤cho biết nghĩa liên quan đến y phục, phần 果 cho âm đọc. Nghĩa: thiếu quần áo, trần truồng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"loã\": áo 衤không che được — như quả 果 rụng vỏ, lộ ra trần truồng. | Gương Hán-Việt | loã thể (裸体 — thân trần), bộc loã (裸露 — phơi bày) | Mở khoá kiến thức | Biết 裸 mở khoá: 裸体 (loã thể — nude), 裸露 (loã lộ — phơi bày), 赤裸 (xích loã — trần như nhộng).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 裸 là hình thanh: 衣/衤 (quần áo, biểu nghĩa) + 果 (biểu âm). Nghĩa rõ: ''thiếu quần áo'', tức trần truồng. Logic ngữ nghĩa: bộ 衣 (y phục) + không có → lộ ra. Hán-Việt: ''loã''. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "300.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Y (295) Quả", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Y (số 295 - bộ y 衤) và chữ Quả . Cái vỏ áo (y) đã bị cởi vứt ra nằm cạnh quả, phần thân để lộ trần trụi ra. *(Biến âm Hán Việt: Trong Hán ngữ cổ, chữ Quả và chữ Lõa có cách phát âm tương đồng hoặc chung gốc phụ âm. Quá trình Việt hóa đã làm âm đọc bị chênh lệch thành Quả và Lõa).*", "Nghĩa Tiếng Việt_Xie": "lộ ra, hiện ra; trần truồng", "Hạng Tần Suất (Jun Da)": "2159.0", "Tần Suất % (Jun Da)": "97.6670742827", "GavinGrover_Once (Chiết tự trực tiếp)": "衤 + 果", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰衤果", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "果", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "衤", "Unihan_Simplified (Chữ Giản thể)": "裸", "Unihan_Traditional (Chữ Phồn thể)": "臝", "Pinyin_Xie": "luǒ", "Âm Hán Việt_Xie": "loả, khoả", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường làm tính từ đứng trước danh từ hoặc kết hợp với động từ khác để chỉ trạng thái trần trụi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | luǒ | / | trần truồng | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Quần áo và đồ trang sức", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('碧', '{"9000": "2160.0", "Chữ Trung Quốc": "碧", "Bộ thủ & thành phần_Xie": "Bộ thủ | 石 | Số nét | 14 | nét | 珀 | phách | biểu âm | cho âm bì (phách → bích) | 石 | thạch | biểu nghĩa | đá, đá quý | 碧 = 珀 (Phách, gồm 玉+白, biểu âm và nghĩa: đá sáng) + 石 (Thạch, biểu nghĩa: đá); theo Wiktionary là hình thanh có ba bộ: 玉 (ngọc, biểu nghĩa) + 石 (đá, biểu nghĩa) + 白 (trắng, biểu âm). Chữ hình thanh phức hợp chỉ loại đá ngọc xanh biếc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bích\": ngọc đá 碧 xanh biếc — bích ngọc trong vắt như trời xanh, tiếng Việt mượn thành màu ''biếc''. | Gương Hán-Việt | bích ngọc (碧玉 — ngọc bích), bích không (碧空 — trời xanh biếc) | Mở khoá kiến thức | Biết 碧 mở khoá: 碧玉 (bích ngọc), 碧空 (bích không — trời trong), 碧绿 (bích lục — xanh thẫm), và từ Việt ''biếc''.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Theo Wiktionary, 碧 là hình thanh với ba bộ: 玉 (ngọc, biểu nghĩa) + 石 (đá, biểu nghĩa) + 白 (biểu âm). Hai bộ biểu nghĩa cùng xác định đây là loại đá/ngọc quý; 白 cho âm. Nghĩa gốc: ngọc bích màu xanh lá-xanh lam. Tiếng Việt mượn âm 碧 thành ''biếc'' (xanh biếc). Hán-Việt: ''bích''. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "màu xanh biếc; ngọc bích", "Hạng Tần Suất (Jun Da)": "2160.0", "Tần Suất % (Jun Da)": "97.670046314", "GavinGrover_Once (Chiết tự trực tiếp)": "珀 + 石", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱珀石", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "珀", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "石", "Unihan_Simplified (Chữ Giản thể)": "碧", "Unihan_Traditional (Chữ Phồn thể)": "碧", "Pinyin_Xie": "bì", "Âm Hán Việt_Xie": "bích", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Thường dùng làm tính từ miêu tả màu xanh biếc của bầu trời hoặc làm danh từ chỉ ngọc bích. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('摧', '{"9000": "2161.0", "Chữ Trung Quốc": "摧", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 14 | nét | 扌 | thủ | biểu nghĩa | tay, hành động bằng tay | 崔 | thôi | biểu âm | cao vút (họ Thôi) | 摧 = 扌(Thủ, biểu nghĩa: tay) + 崔 (Thôi, biểu âm); chữ hình thanh. Bộ thủ chỉ hành động phá hủy bằng sức mạnh; 崔 cung cấp âm (cuī).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tồi\": bàn tay (扌) mạnh mẽ tàn phá — tồi tàn, hủy diệt hoàn toàn. | Gương Hán-Việt | tồi trong 摧残 (tồi tàn — tàn phá, hủy hoại) | Mở khoá kiến thức | Biết 摧 (tồi) mở khoá: 摧残 (tàn phá), 摧毁 (phá hủy), 坚不可摧 (vững chắc không gì phá được).", "Tự nguyên_Xie": "Theo Wiktionary, 摧 là chữ hình thanh: bộ 手 (扌) biểu nghĩa (hành động tay — phá vỡ), 崔 biểu âm. Nghĩa gốc và duy nhất là bẻ gãy, phá hủy, nghiền nát. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bẻ gãy; diệt hết; phát cỏ", "Hạng Tần Suất (Jun Da)": "2161.0", "Tần Suất % (Jun Da)": "97.673014211", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 崔", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌崔", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "崔", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "摧", "Unihan_Traditional (Chữ Phồn thể)": "摧", "Pinyin_Xie": "cuī", "Âm Hán Việt_Xie": "tồi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường dùng làm động từ đứng trước tân ngữ để chỉ hành động tàn phá hoặc bẻ gãy. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('薪', '{"9000": "2162.0", "Chữ Trung Quốc": "薪", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 16 | nét | 艹 | thảo | biểu nghĩa | cỏ, cây cỏ | 新 | tân | biểu âm | mới (cho âm xīn) | 薪 = 艹 (Thảo, biểu nghĩa: cỏ cây) + 新 (Tân, biểu âm); chữ hình thanh. Bộ thảo chỉ đây là loại thực vật — cụ thể là củi, cành cây khô; 新 cung cấp âm (xīn).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tân\": cây cỏ (艹) mới chặt (新/tân) thành củi đốt — tiền lương như củi nuôi lửa cuộc sống. | Gương Hán-Việt | tân trong 薪水 (tân thuỷ — tiền lương) | Mở khoá kiến thức | Biết 薪 (tân) mở khoá: 薪水 (lương), 年薪 (lương năm), 薪资 (tiền lương), 柴薪 (củi đốt).", "Tự nguyên_Xie": "Theo Wiktionary, 薪 là chữ hình thanh: bộ 艸 (艹) biểu nghĩa (cây cỏ), 新 biểu âm. Nghĩa gốc là củi, cành khô dùng để đốt. Nghĩa mở rộng ''lương bổng'' xuất phát từ thời xưa người ta trả công bằng củi và lương thực. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "củi đun; tiền lương", "Hạng Tần Suất (Jun Da)": "2162.0", "Tần Suất % (Jun Da)": "97.6759810745", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 新", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹新", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "新", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "薪", "Unihan_Traditional (Chữ Phồn thể)": "薪", "Pinyin_Xie": "xīn", "Âm Hán Việt_Xie": "tân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong các từ ghép chỉ củi lửa hoặc tiền lương. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('淋', '{"9000": "2163.0", "Chữ Trung Quốc": "淋", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 11 | nét | 氵 | thuỷ | biểu nghĩa | nước | 林 | lâm | biểu âm | rừng (cho âm lín) | 淋 = 氵(Thuỷ, biểu nghĩa: nước) + 林 (Lâm, biểu âm); chữ hình thanh. Bộ thuỷ chỉ đây liên quan đến nước; 林 cung cấp âm (lín). Hình ảnh nước nhỏ giọt qua tán rừng rất trực quan.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lâm\": nước (氵) đổ xuống như mưa rừng (林/lâm) — ướt lâm lép, dầm mưa. | Gương Hán-Việt | lâm trong 淋漓 (lâm li — nhỏ giọt, thấm ướt); 淋雨 (lâm vũ — bị mưa ướt) | Mở khoá kiến thức | Biết 淋 (lâm) mở khoá: 淋雨 (bị mưa ướt), 淋漓 (ướt đẫm), 淋巴 (bạch huyết).", "Tự nguyên_Xie": "Theo Wiktionary, 淋 là chữ hình thanh: bộ 水 (氵) biểu nghĩa (nước), 林 biểu âm. Nghĩa gốc là dội nước, thấm ướt; sau mở rộng sang ướt sũng vì mưa. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "416.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thủy (306) Lâm (109)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Thủy (số 76) và chữ Lâm (số 109 - rừng núi) . Nước (Thủy) mưa rơi xuống khu rừng (Lâm) làm mọi thứ ướt sũng (lâm li). Giải thích sự chuyển ý: Chữ Lâm (rừng cây) chỉ âm, chữ Thủy (nước) chỉ ý. Nước (Thủy) tuôn chảy ướt đẫm liên tục (Lâm).", "Nghĩa Tiếng Việt_Xie": "ướt", "Hạng Tần Suất (Jun Da)": "2163.0", "Tần Suất % (Jun Da)": "97.6789458708", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 林", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵林", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "林", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "淋", "Unihan_Traditional (Chữ Phồn thể)": "淋", "Pinyin_Xie": "lín", "Âm Hán Việt_Xie": "lâm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường dùng làm động từ chỉ hành động bị nước mưa dội vào hoặc tưới nước lên vật gì. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | lín | / | tưới | / | lín | / | ướt sũng | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Từ III | HSK | HSK 6 | · | Động từ hàng ngày", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('耻', '{"9000": "2164.0", "Chữ Trung Quốc": "耻", "Bộ thủ & thành phần_Xie": "Bộ thủ | 耳 | Số nét | 10 | nét | 耳 | nhĩ | biểu nghĩa | tai — nghe thấy điều xấu hổ | 止 | chỉ | biểu âm | dừng lại (cho âm chǐ) | 耻 là biến thể tục tự của 恥 (thay bộ tâm bằng bộ nhĩ); phân tích bề mặt: 耳 (Nhĩ, biểu nghĩa) + 止 (Chỉ, biểu âm), chữ hình thanh. Tai đỏ bừng khi xấu hổ — hình ảnh trực quan cho cảm giác sỉ nhục.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sỉ\": tai (耳) đỏ bừng, dừng lại (止) — bẽ mặt, sỉ nhục không dám đi tiếp. | Gương Hán-Việt | sỉ trong 羞耻 (tu sỉ — xấu hổ), 耻辱 (sỉ nhục — nhục nhã) | Mở khoá kiến thức | Biết 耻 (sỉ) mở khoá: 羞耻 (xấu hổ), 无耻 (vô sỉ), 耻辱 (nhục nhã), 不耻下问 (không ngại học hỏi kẻ dưới).", "Tự nguyên_Xie": "耻 là dạng tục tự của 恥 (xuất hiện từ thời Đông Hán). Wiktionary ghi nhận đây là chữ hình thanh bề mặt: 耳 biểu nghĩa, 止 biểu âm. Chữ gốc 恥 dùng bộ 心 (tâm) vì xấu hổ là cảm xúc nội tâm. Dạng 耻 dùng 耳 (tai) — tai đỏ lên khi mắc cỡ. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "xấu hổ, thẹn", "Hạng Tần Suất (Jun Da)": "2164.0", "Tần Suất % (Jun Da)": "97.6819096335", "GavinGrover_Once (Chiết tự trực tiếp)": "耳 + 止", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰耳止", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "止", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "耳", "Unihan_Simplified (Chữ Giản thể)": "耻", "Unihan_Traditional (Chữ Phồn thể)": "恥", "Pinyin_Xie": "chǐ", "Âm Hán Việt_Xie": "sỉ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Tính từ | 形容词 | Thường dùng làm danh từ chỉ nỗi nhục nhã hoặc động từ biểu thị sự xấu hổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('胶', '{"9000": "2165.0", "Chữ Trung Quốc": "胶", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 10 | nét | 月 | nguyệt | biểu nghĩa | bộ nhục (thịt), mô sinh học | 交 | giao | biểu âm | giao thoa, gặp nhau | 胶 = 月/肉 (Nguyệt/nhục, biểu nghĩa: mô thịt/sinh học) + 交 (Giao, biểu âm); chữ hình thanh. Bộ 月 ở đây là bộ nhục (thịt), chỉ chất keo lấy từ động vật; 交 cho âm (jiāo ~ giao).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"giao\": bộ nhục 月 (nguyệt/nhục) giao 交 (giao) tiếp với nhau — keo 胶 dính kết mọi thứ lại với nhau. | Gương Hán-Việt | giao trong ''橡胶 tượng giao'' (cao su), ''胶水 giao thủy'' (keo nước) | Mở khoá kiến thức | Biết 胶 (giao) mở khoá: 胶水 (keo), 橡胶 (cao su), 胶带 (băng keo), 胶片 (phim chụp).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Theo Wiktionary, 胶 (phồn thể 膠) là chữ hình thanh: 肉 (biểu nghĩa: thịt/mô động vật) + 交 (biểu âm). Nghĩa gốc là chất keo lấy từ xương, da động vật — keo dán tự nhiên thời cổ. Sau mở rộng sang cao su và các chất dính tổng hợp. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "keo, nhựa; dán, dính; cao su", "Hạng Tần Suất (Jun Da)": "2165.0", "Tần Suất % (Jun Da)": "97.6848661613", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 交", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月交", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "交", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "胶", "Unihan_Traditional (Chữ Phồn thể)": "膠", "Pinyin_Xie": "jiāo", "Âm Hán Việt_Xie": "giao", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường dùng làm danh từ chỉ các loại chất dính hoặc làm động từ với nghĩa gắn kết. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('屠', '{"9000": "2166.0", "Chữ Trung Quốc": "屠", "Bộ thủ & thành phần_Xie": "Bộ thủ | 尸 | Số nét | 11 | nét | 尸 | thi | biểu nghĩa | thân xác, thi thể | 者 | giả | biểu âm | cho âm tú | 屠 = 尸 (Thi, biểu nghĩa: thân xác/con vật bị giết) + 者 (Giả, biểu âm); chữ hình thanh. Bộ 尸 gợi hình ảnh xác chết/con vật, phần 者 cho âm đọc tú.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đồ\": xác 尸 + người 者 — kẻ đồ tể (屠夫) giết mổ, từ đó mở rộng thành ''thảm sát''. | Gương Hán-Việt | đồ sát (屠杀 — thảm sát), đồ phu (屠夫 — kẻ đồ tể) | Mở khoá kiến thức | Biết 屠 mở khoá: 屠杀 (đồ sát — thảm sát), 屠夫 (đồ phu — người giết mổ), 屠宰 (đồ tể — giết mổ).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Theo Wiktionary, 屠 là hình thanh: 尸 (thân xác, biểu nghĩa) + 者 (biểu âm). Nghĩa gốc: giết mổ, giết súc vật lấy thịt. Mở rộng: tàn sát, họ Đồ. Hán-Việt: ''đồ''. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "giết, mổ thịt", "Hạng Tần Suất (Jun Da)": "2166.0", "Tần Suất % (Jun Da)": "97.6878211387", "GavinGrover_Once (Chiết tự trực tiếp)": "尸 + 者", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴尸者", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "者", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "尸", "Unihan_Simplified (Chữ Giản thể)": "屠", "Unihan_Traditional (Chữ Phồn thể)": "屠", "Pinyin_Xie": "tú", "Âm Hán Việt_Xie": "đồ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường dùng làm động từ chỉ hành động tàn sát hoặc làm danh từ chỉ người làm nghề mổ gia súc. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鹅', '{"9000": "2167.0", "Chữ Trung Quốc": "鹅", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鳥 | Số nét | 12 | nét | 我 | ngã | biểu âm | cho âm é | 鸟 | điểu | biểu nghĩa | chim | 鹅 = 我 (Ngã, biểu âm) + 鸟 (Điểu, biểu nghĩa: chim); chữ hình thanh. Bộ 鸟 xác định đây là loại chim, phần 我 cho âm đọc é.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nga\": con ngỗng 鹅 — chim 鸟 kêu ngọng như chữ 我 (ngã) vang to trên mặt nước. | Gương Hán-Việt | thiên nga (天鵝 — chim thiên nga), nga mi (鵝眉 — lông mày cong đẹp) | Mở khoá kiến thức | Biết 鹅 mở khoá: 天鹅 (thiên nga — white swan), 鹅毛 (lông ngỗng), 鹅黄 (vàng ngỗng — màu vàng nhạt).", "Tự nguyên_Xie": "Theo Wiktionary, dạng phồn thể 鵝 là hình thanh: 我 (biểu âm) + 鳥 (chim, biểu nghĩa). Nghĩa: con ngỗng — loài chim nước lớn. Hán-Việt: ''nga''. Tiếng Việt còn có từ ''ngỗng'' bên cạnh cách đọc Hán-Việt ''nga'' (như trong ''thiên nga''). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con ngỗng", "Hạng Tần Suất (Jun Da)": "2167.0", "Tần Suất % (Jun Da)": "97.6907683643", "GavinGrover_Once (Chiết tự trực tiếp)": "我 + 鸟", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰我鸟", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "我", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鸟", "Unihan_Simplified (Chữ Giản thể)": "鹅", "Unihan_Traditional (Chữ Phồn thể)": "䳘", "Pinyin_Xie": "é", "Âm Hán Việt_Xie": "nga", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ đứng độc lập hoặc làm định ngữ trong cụm danh từ để chỉ con ngỗng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | é | / | ngỗng | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Động vật và côn trùng", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('饥', '{"9000": "2168.0", "Chữ Trung Quốc": "饥", "Bộ thủ & thành phần_Xie": "Bộ thủ | 食 | Số nét | 5 | nét | 饣 | thực | biểu nghĩa | ăn uống, thức ăn (bộ thực giản thể) | 几 | cơ | biểu âm | mấy, cái bàn nhỏ (cho âm jī) | 饥 = 饣(Thực, biểu nghĩa: ăn uống) + 几 (Cơ, biểu âm); chữ hình thanh. Phồn thể là 飢. Bộ thực chỉ đây liên quan đến thức ăn — thiếu ăn; 几 cung cấp âm (jī).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cơ\": cái bàn nhỏ (几) không có thức ăn (饣) — cơ đói, lương thực thiếu thốn. | Gương Hán-Việt | cơ trong 饥饿 (cơ ngạ — đói khát) | Mở khoá kiến thức | Biết 饥 (cơ) mở khoá: 饥饿 (đói khát), 饥荒 (nạn đói), 忍饥挨饿 (chịu đói nhịn ăn).", "Tự nguyên_Xie": "饥 (phồn thể 飢) là chữ hình thanh: theo Wiktionary, bộ 食 biểu nghĩa (ăn uống — thiếu thức ăn), 几 biểu âm. Nghĩa gốc và duy nhất là đói, thiếu lương thực. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đói; mất mùa", "Hạng Tần Suất (Jun Da)": "2168.0", "Tần Suất % (Jun Da)": "97.6937083549", "GavinGrover_Once (Chiết tự trực tiếp)": "饣 + 几", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰饣几", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "几", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "饣", "Unihan_Simplified (Chữ Giản thể)": "饥", "Unihan_Traditional (Chữ Phồn thể)": "飢", "Pinyin_Xie": "jī", "Âm Hán Việt_Xie": "cơ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Thường làm tính từ bổ nghĩa cho danh từ hoặc làm vị ngữ để chỉ trạng thái đói. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('盼', '{"9000": "2169.0", "Chữ Trung Quốc": "盼", "Bộ thủ & thành phần_Xie": "Bộ thủ | 目 | Số nét | 9 | nét | 目 | mục | biểu nghĩa | mắt | 分 | phân | biểu âm | phân chia, tách ra | 盼 = 目 (Mục, biểu nghĩa: mắt) + 分 (Phân, biểu âm); chữ hình thanh. Bộ 目 cho nghĩa liên quan đến mắt/nhìn, 分 cho âm (pàn ~ phān). Nghĩa gốc chỉ đôi mắt có tròng đen trắng rõ ràng, sau chuyển sang ''ngóng trông''.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phán\": đôi mắt 目 (mục) nhìn xa mong ngóng — 盼 望 trông đợi từng ngày. | Gương Hán-Việt | phán trong ''盼望 phán vọng'' (mong ngóng), ''期盼 kỳ phán'' (kỳ vọng) | Mở khoá kiến thức | Biết 盼 (phán) mở khoá: 盼望 (mong ngóng), 期盼 (kỳ vọng), 左顾右盼 (nhìn quanh).", "Tự nguyên_Xie": "Theo Wiktionary, 盼 là chữ hình thanh (psc): 目 (mục, biểu nghĩa: mắt) + 分 (phân, biểu âm). Nghĩa cổ chỉ đôi mắt có đồng tử đen và lòng trắng tách biệt rõ ràng — con mắt đẹp. Sau chuyển nghĩa sang ''nhìn mong, ngóng trông''. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mắt đẹp; tầm mắt; mong ngóng, trông", "Hạng Tần Suất (Jun Da)": "2169.0", "Tần Suất % (Jun Da)": "97.6966483456", "GavinGrover_Once (Chiết tự trực tiếp)": "目 + 分", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰目分", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "分", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "目", "Unihan_Simplified (Chữ Giản thể)": "盼", "Unihan_Traditional (Chữ Phồn thể)": "盼", "Pinyin_Xie": "pàn", "Âm Hán Việt_Xie": "phán", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước danh từ hoặc động từ khác để biểu thị sự mong đợi. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | pàn | / | mong mỏi | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Khát vọng", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('脖', '{"9000": "2170.0", "Chữ Trung Quốc": "脖", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 11 | nét | 月 | nguyệt | biểu nghĩa | bộ nhục (thịt), bộ phận cơ thể | 孛 | bột | biểu âm | ngôi sao chổi, phát sáng | 脖 = 月/肉 (Nguyệt/nhục, biểu nghĩa: bộ phận cơ thể) + 孛 (Bột, biểu âm); chữ hình thanh. Bộ 月 ở đây là bộ nhục chỉ bộ phận thân thể, 孛 cho âm (bó ~ bột).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bột\": bộ nhục 月 (nguyệt/nhục) kết hợp bột 孛 (bột) âm — cái cổ 脖 là phần thịt nối đầu với thân. | Gương Hán-Việt | bột trong ''脖子 bột tử'' (cái cổ) | Mở khoá kiến thức | Biết 脖 (bột) mở khoá: 脖子 (cái cổ), 颈脖 (cổ), 脖颈 (cổ gáy).", "Tự nguyên_Xie": "Theo Wiktionary, 脖 là chữ hình thanh (psc): 肉 (nhục, biểu nghĩa: thịt/cơ thể) + 孛 (bột, biểu âm). Cổ tự chưa thấy trong giáp cốt hay kim văn, đây là chữ tạo muộn hơn để chỉ cổ (phần cơ thể nối đầu với vai). | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1766.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Nhục (130) Bột (1765)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Nhục (số 130 - phần cơ thể thịt/ 月 /chỉ ý) ở bên trái chữ Bột (số 1765 - sao chổi/ 孛 /chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Bột chỉ âm, bộ Nhục chỉ ý. Bột là cái cổ họng, phần cổ của cơ thể (bột tử).", "Nghĩa Tiếng Việt_Xie": "cái cổ", "Hạng Tần Suất (Jun Da)": "2170.0", "Tần Suất % (Jun Da)": "97.6995847187", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 孛", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月孛", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "孛", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "脖", "Unihan_Traditional (Chữ Phồn thể)": "脖", "Pinyin_Xie": "bó", "Âm Hán Việt_Xie": "bột", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường kết hợp với các từ khác tạo thành danh từ ghép chỉ bộ phận cơ thể. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('虹', '{"9000": "2171.0", "Chữ Trung Quốc": "虹", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 9 | nét | 虫 | trùng | biểu nghĩa | côn trùng/sinh vật (gốc là ''con rồng hai đầu'') | 工 | công | biểu âm | công việc (gần âm hóng) | 虹 nguyên trong giáp cốt là tượng hình con rồng hai đầu uốn cong (cách người xưa hiểu cầu vồng). Đến tiểu triện, chữ được tái cấu trúc thành hình thanh: 虫 (sinh vật, biểu nghĩa) + 工 (Công, biểu âm).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hồng\": 虫 (sinh vật) + 工 (Công) — con ''rồng hai đầu'' uốn cong trên trời, đúng nghĩa ''cầu vồng'' trong 彩虹. | Gương Hán-Việt | ''hồng'' trong ''cầu hồng'' (cầu vồng) — y nghĩa | Mở khoá kiến thức | Nắm 虹 mở khoá từ HSK 5: 彩虹.", "Tự nguyên_Xie": "Giáp cốt văn | Theo Wiktionary, 虹 ban đầu là tượng hình trong giáp cốt — người Trung Quốc cổ xem cầu vồng là một con rồng hai đầu (có thư kinh: ''một con cầu vồng từ phương Bắc đến uống nước sông''). Đến tiểu triện, chữ được tái cấu trúc thành hình thanh: 虫 (sinh vật, biểu nghĩa) + 工 (Công, biểu âm). Nghĩa ''cầu vồng'' giữ nguyên trong 彩虹. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cầu vồng", "Hạng Tần Suất (Jun Da)": "2171.0", "Tần Suất % (Jun Da)": "97.7025148904", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 工", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫工", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "工", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "虹", "Unihan_Traditional (Chữ Phồn thể)": "虹", "Pinyin_Xie": "hóng", "Âm Hán Việt_Xie": "hồng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Làm danh từ chỉ hiện tượng tự nhiên, thường làm chủ ngữ hoặc tân ngữ trong câu. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('翠', '{"9000": "2172.0", "Chữ Trung Quốc": "翠", "Bộ thủ & thành phần_Xie": "Bộ thủ | 羽 | Số nét | 14 | nét | 羽 | vũ | biểu nghĩa | lông chim | 卒 | thốt | biểu âm | cho âm cuì | 翠 = 羽 (Vũ, biểu nghĩa: lông chim) + 卒 (Thốt, biểu âm); chữ hình thanh. Bộ 羽 gợi lông chim màu xanh biếc, phần 卒 cho âm đọc. Wiktionary không có mục cấu trúc chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thuý\": lông 羽 xanh thuý của chim bói cá — màu xanh thuý biếc óng ánh như đá quý. | Gương Hán-Việt | phỉ thuý (翡翠 — đá ngọc xanh), thuý điểu (翠鸟 — chim bói cá) | Mở khoá kiến thức | Biết 翠 mở khoá: 翡翠 (phỉ thuý — ngọc phỉ thuý), 翠绿 (thuý lục — xanh ngọc), 翠鸟 (thuý điểu — chim bói cá).", "Tự nguyên_Xie": "Kim văn | Tiểu triện | Wiktionary ghi nhận 翠 có nguồn gốc nhưng không cung cấp phân tích đầy đủ (chỉ ghi {{Han etym}}). Suy từ cấu trúc: 羽 (lông vũ) + 卒 (biểu âm). Nghĩa gốc: màu xanh biếc của lông chim bói cá (chim thuý — 翡翠). Hán-Việt: ''thuý''. Chưa có nguồn học thuật xác nhận đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "xanh biếc", "Hạng Tần Suất (Jun Da)": "2172.0", "Tần Suất % (Jun Da)": "97.7054404111", "GavinGrover_Once (Chiết tự trực tiếp)": "羽 + 卒", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱羽卒", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "卒", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "羽", "Unihan_Simplified (Chữ Giản thể)": "翠", "Unihan_Traditional (Chữ Phồn thể)": "翠", "Pinyin_Xie": "cuì", "Âm Hán Việt_Xie": "thúy", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Thường làm tính từ đứng trước danh từ để miêu tả màu sắc xanh biếc của sự vật. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('崩', '{"9000": "2173.0", "Chữ Trung Quốc": "崩", "Bộ thủ & thành phần_Xie": "Bộ thủ | 山 | Số nét | 11 | nét | 山 | sơn | biểu nghĩa | núi | 朋 | bằng | biểu âm | bạn bè (cho âm bēng) | 崩 = 山 (Sơn, biểu nghĩa: núi) + 朋 (Bằng, biểu âm); chữ hình thanh. Bộ sơn chỉ đây liên quan đến sự sụp đổ của núi non hay địa hình; 朋 cung cấp âm (bēng). Hình ảnh núi sụp đổ rất trực quan.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"băng\": núi (山) và bạn bè (朋) cùng băng đổ sụp — băng hoại, tan vỡ hoàn toàn. | Gương Hán-Việt | băng trong 崩溃 (băng quỹ — sụp đổ tan tành) | Mở khoá kiến thức | Biết 崩 (băng) mở khoá: 崩溃 (sụp đổ), 崩塌 (lở đất), 土崩瓦解 (tan rã hoàn toàn).", "Tự nguyên_Xie": "Theo Wiktionary, 崩 là chữ hình thanh: bộ 山 biểu nghĩa (núi — sụp đổ), 朋 biểu âm. Nghĩa gốc là núi lở, sụp đổ. Mở rộng sang sụp đổ hoàn toàn (sức khoẻ, tinh thần, hệ thống). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "439.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Sơn (44) Bằng (96)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Sơn (số 46 - ngọn núi) ở trên chữ Bằng (số 74 - bạn bè/hai mặt trăng) . Tưởng chừng vững chãi như núi (Sơn) nhưng nếu bạn bè (Bằng) không đoàn kết thì cũng sẽ sụp đổ, sạt lở (băng). Vua mất gọi là núi sập (băng hà). Giải thích sự chuyển ý: Chữ Bằng (bạn bè) chỉ âm, chữ Sơn (núi) chỉ ý. Núi (Sơn) bị sạt lở sụp xuống gọi là băng.", "Nghĩa Tiếng Việt_Xie": "núi lở; đổ, vỡ, gãy; vua chết", "Hạng Tần Suất (Jun Da)": "2173.0", "Tần Suất % (Jun Da)": "97.7083643814", "GavinGrover_Once (Chiết tự trực tiếp)": "山 + 朋", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱山朋", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "朋", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "山", "Unihan_Simplified (Chữ Giản thể)": "崩", "Unihan_Traditional (Chữ Phồn thể)": "崩", "Pinyin_Xie": "bēng", "Âm Hán Việt_Xie": "băng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ làm vị ngữ chỉ sự sụp đổ của đất đá hoặc cấu trúc. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('账', '{"9000": "2174.0", "Chữ Trung Quốc": "账", "Bộ thủ & thành phần_Xie": "Bộ thủ | 貝 | Số nét | 8 | nét | 贝 | bối | biểu nghĩa | vỏ sò, tiền tệ | 长 | trường | biểu âm | dài, lớn | 账 = 贝 (Bối, biểu nghĩa: tiền/tài vật) + 长 (Trường, biểu âm); chữ hình thanh. Bộ 贝 cho nghĩa liên quan đến tiền bạc tài chính, 长 cho âm (zhàng ~ trường).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trướng\": bộ bối 贝 (tiền sò) kéo dài 长 (trường) thành sổ — 账 là sổ sách ghi chép tiền tệ. | Gương Hán-Việt | trướng trong ''账户 trướng hộ'' (tài khoản) | Mở khoá kiến thức | Biết 账 (trướng) mở khoá: 账户 (tài khoản), 结账 (thanh toán), 账单 (hóa đơn), 账号 (số tài khoản).", "Tự nguyên_Xie": "账 là chữ giản thể của 賬. Phồn thể 賬 là chữ hình thanh: 貝 (bối, biểu nghĩa: vỏ sò/tiền tệ) + 長 (trường, biểu âm). Nghĩa gốc là sổ sách ghi chép tài chính, thu chi. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sổ sách", "Hạng Tần Suất (Jun Da)": "2174.0", "Tần Suất % (Jun Da)": "97.7112852509", "GavinGrover_Once (Chiết tự trực tiếp)": "贝 + 长", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰贝长", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "长", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "贝", "Unihan_Simplified (Chữ Giản thể)": "账", "Unihan_Traditional (Chữ Phồn thể)": "賬", "Pinyin_Xie": "zhàng", "Âm Hán Việt_Xie": "trướng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Làm danh từ chỉ sổ sách kế toán hoặc nợ nần, thường đi sau động từ như tính hoặc trả. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | zhàng | / | tài khoản | Xuất hiện trong lộ trình | New HSK | New HSK 6 | · | Kinh tế và tài chính", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('萍', '{"9000": "2175.0", "Chữ Trung Quốc": "萍", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 11 | nét | 艹 | thảo | biểu nghĩa | cỏ, thực vật | 泙 | bình | biểu âm | cho âm píng | 萍 = 艹 (Thảo, biểu nghĩa: thực vật) + 泙 (Bình, biểu âm); chữ hình thanh. Bộ 艹 xác định đây là thực vật, phần 泙 cho âm đọc píng. Wiktionary không có phân tích đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bình\": cây bèo 萍 trôi nổi bình bồng — 萍水相逢 (bình thuỷ tương phùng) gặp nhau như bèo nước. | Gương Hán-Việt | bình thuỷ tương phùng (萍水相逢 — gặp gỡ tình cờ), phù bình (浮萍 — bèo nổi) | Mở khoá kiến thức | Biết 萍 mở khoá thành ngữ quan trọng: 萍水相逢 (bình thuỷ tương phùng — gặp tình cờ như bèo nước) và 浮萍 (phù bình — bèo trôi nổi, ý chỉ cuộc đời lênh đênh).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Wiktionary không có mục phân tích cấu trúc đầy đủ cho 萍. Suy từ bộ thủ: 艹 (cỏ/thực vật, biểu nghĩa) + 泙 (biểu âm). Nghĩa: cây bèo (bèo tấm, bèo dâu) — thực vật trôi nổi trên mặt nước. Dùng trong thành ngữ chỉ sự gặp gỡ tình cờ. Hán-Việt: ''bình''. Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cây bèo", "Hạng Tần Suất (Jun Da)": "2175.0", "Tần Suất % (Jun Da)": "97.7142030198", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 泙", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹泙", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "泙", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "萍", "Unihan_Traditional (Chữ Phồn thể)": "萍", "Pinyin_Xie": "píng", "Âm Hán Việt_Xie": "bình", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Làm danh từ chỉ loài bèo hoặc dùng trong ẩn dụ về sự trôi nổi, không định cư. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('逢', '{"9000": "2176.0", "Chữ Trung Quốc": "逢", "Bộ thủ & thành phần_Xie": "Bộ thủ | 辵 | Số nét | 10 | nét | 辶 | sước | biểu nghĩa | đi, bước (bộ xước) | 夆 | phùng | biểu âm | chạm vào (cho âm féng) | 逢 = 辶(Sước, biểu nghĩa: đi đường) + 夆 (Phùng, biểu âm); chữ hình thanh. Bộ xước chỉ sự di chuyển, gặp gỡ trên đường; 夆 cung cấp âm (féng).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phùng\": đi trên đường (辶) chợt gặp (夆/phùng) — phùng ngộ, tao phùng, gặp nhau đúng lúc. | Gương Hán-Việt | phùng trong 每逢 (mỗi phùng — mỗi khi gặp dịp) | Mở khoá kiến thức | Biết 逢 (phùng) mở khoá: 每逢 (mỗi khi), 逢年过节 (dịp lễ tết), 萍水相逢 (gặp gỡ tình cờ).", "Tự nguyên_Xie": "Theo Wiktionary, 逢 là chữ hình thanh: bộ 辵 (辶) biểu nghĩa (đi đường — gặp trên đường), 夆 biểu âm. Nghĩa gốc là gặp gỡ tình cờ; sau mở rộng sang gặp dịp, nhân khi. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1206.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Xước (162) Phùng (643)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Xước (số 162 - bước đi/chỉ ý) bao quanh chữ Phùng (số 643 - viết dạng 夆 /chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Phùng chỉ âm, bộ Xước chỉ ý. Phùng là đi gặp mặt, gặp gỡ (tương phùng, trùng phùng).", "Nghĩa Tiếng Việt_Xie": "gặp gỡ", "Hạng Tần Suất (Jun Da)": "2176.0", "Tần Suất % (Jun Da)": "97.7171135537", "GavinGrover_Once (Chiết tự trực tiếp)": "辶 + 夆", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴辶夆", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "夆", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "辶", "Unihan_Simplified (Chữ Giản thể)": "逢", "Unihan_Traditional (Chữ Phồn thể)": "逢", "Pinyin_Xie": "féng", "Âm Hán Việt_Xie": "phùng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Làm động từ chỉ sự gặp gỡ ngẫu nhiên hoặc đón nhận một thời điểm, sự kiện. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | féng | / | gặp | Xuất hiện trong lộ trình | HSK | HSK 6 | · | Động từ | New HSK | New HSK 7-9 | · | Các cuộc họp", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('赚', '{"9000": "2177.0", "Chữ Trung Quốc": "赚", "Bộ thủ & thành phần_Xie": "Bộ thủ | 貝 | Số nét | 14 | nét | 贝 | bối | biểu nghĩa | vỏ sò, tiền | 兼 | kiêm | biểu âm | gợi âm zhuàn | 赚 = 贝 (Bối, biểu nghĩa: tiền) + 兼 (Kiêm, biểu âm); là dạng giản thể của 賺, chữ hình thanh. Tiền kiếm thêm — ''kiếm lời''.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trám\": 贝 (tiền) + 兼 (kiêm) — kiêm thêm tiền, ấy là ''trám'' (kiếm); nhớ 赚钱 (kiếm tiền). | Gương Hán-Việt | ''trám'' theo Hán-Việt; trong nghĩa hiện đại tương ứng ''kiếm/lời'' trong tiếng Việt | Mở khoá kiến thức | Biết 赚 là mở 赚钱 — chìa khoá nhóm từ về kinh doanh, lợi nhuận HSK 4-6.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Theo Wiktionary, 赚 là dạng giản thể của 賺 (rút 貝 thành 贝). 賺 phồn thể là chữ hình thanh: 貝 (biểu nghĩa: tiền) ghép với 兼 (biểu âm; cũng gợi nghĩa ''gộp thêm''). Nghĩa: kiếm lời, kiếm tiền; cũng có nghĩa cổ ''lừa gạt''. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bán đồ giả; lường gạt", "Hạng Tần Suất (Jun Da)": "2177.0", "Tần Suất % (Jun Da)": "97.720023054", "GavinGrover_Once (Chiết tự trực tiếp)": "贝 + 兼", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰贝兼", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "兼", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "贝", "Unihan_Simplified (Chữ Giản thể)": "赚", "Unihan_Traditional (Chữ Phồn thể)": "賺", "Pinyin_Xie": "zhuàn", "Âm Hán Việt_Xie": "trám", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ mang tân ngữ chỉ tiền bạc hoặc lợi ích kiếm được. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | zhuàn | / | kiếm lợi | Xuất hiện trong lộ trình | New HSK | New HSK 6 | · | Công việc | HSK | HSK 4 | · | Phân tích và kinh tế", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('撑', '{"9000": "2178.0", "Chữ Trung Quốc": "撑", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 15 | nét | 扌 | thủ | biểu nghĩa | tay, hành động bằng tay | 掌 | chưởng | biểu âm | lòng bàn tay (cho âm chēng) | 撑 = 扌(Thủ, biểu nghĩa: tay) + 掌 (Chưởng, biểu âm); chữ hình thanh. Phồn thể là 撐 (dùng 牚 biểu âm). Bộ thủ chỉ hành động chống đỡ bằng tay; 掌 cung cấp âm (chēng).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chống\": bàn tay (扌) chống đỡ như lòng bàn tay (掌/chưởng) — chống chịu, chèo chống không ngã. | Gương Hán-Việt | chống trong 支撑 (chi chống — chống đỡ, duy trì) | Mở khoá kiến thức | Biết 撑 (chống) mở khoá: 支撑 (chống đỡ), 撑起 (nâng đỡ), 撑船 (chèo thuyền).", "Tự nguyên_Xie": "撑 (phồn thể 撐) là chữ hình thanh: theo Wiktionary, bộ 手 (扌) biểu nghĩa (tay — chống đỡ), 牚 (trong phồn thể) biểu âm. Nghĩa gốc là chống đỡ, chèo chống; sau mở rộng sang chịu đựng, căng phồng. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chống giữ; no đủ", "Hạng Tần Suất (Jun Da)": "2178.0", "Tần Suất % (Jun Da)": "97.7229315207", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 掌", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌掌", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "掌", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "撑", "Unihan_Traditional (Chữ Phồn thể)": "撐", "Pinyin_Xie": "chēng", "Âm Hán Việt_Xie": "sanh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Làm động từ chỉ hành động chống đỡ vật thể hoặc làm tính từ chỉ trạng thái quá no. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | chēng | / | hỗ trợ | Xuất hiện trong lộ trình | New HSK | New HSK 6 | · | Động từ", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('翔', '{"9000": "2179.0", "Chữ Trung Quốc": "翔", "Bộ thủ & thành phần_Xie": "Bộ thủ | 羽 | Số nét | 12 | nét | 羊 | dương | biểu âm | con dê (cho âm xiáng) | 羽 | vũ | biểu nghĩa | lông vũ, cánh chim | 翔 = 羊 (Dương, biểu âm) + 羽 (Vũ, biểu nghĩa: lông vũ, cánh); chữ hình thanh. Bộ vũ chỉ đây liên quan đến cánh, bay lượn; 羊 cung cấp âm (xiáng).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tường\": cánh (羽) dang rộng như đôi cánh dê trời (羊/dương) — tường vi bay lượn, tự do tung cánh. | Gương Hán-Việt | tường trong 飞翔 (phi tường — bay lượn) | Mở khoá kiến thức | Biết 翔 (tường) mở khoá: 飞翔 (bay lượn), 翱翔 (tung cánh), 翔实 (chính xác, đầy đủ).", "Tự nguyên_Xie": "Theo Wiktionary, 翔 là chữ hình thanh: bộ 羽 biểu nghĩa (lông vũ, cánh — bay), 羊 biểu âm. Nghĩa gốc là bay lượn chậm rãi, tung cánh trên không. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "liệng quanh; đi vung tay", "Hạng Tần Suất (Jun Da)": "2179.0", "Tần Suất % (Jun Da)": "97.7258384371", "GavinGrover_Once (Chiết tự trực tiếp)": "羊 + 羽", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰羊羽", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "羽", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "羊", "Unihan_Simplified (Chữ Giản thể)": "翔", "Unihan_Traditional (Chữ Phồn thể)": "翔", "Pinyin_Xie": "xiáng", "Âm Hán Việt_Xie": "tường", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ miêu tả tư thế bay lượn thong thả của loài chim. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('倡', '{"9000": "2180.0", "Chữ Trung Quốc": "倡", "Bộ thủ & thành phần_Xie": "Bộ thủ | 人 | Số nét | 10 | nét | 亻 | nhân | biểu nghĩa | người | 昌 | xương | biểu âm | hưng thịnh, phát triển | 倡 = 亻 (Nhân, biểu nghĩa: người) + 昌 (Xương, biểu âm); chữ hình thanh. Bộ 亻 cho nghĩa liên quan đến người/hành động của người, 昌 cho âm (chàng ~ xướng).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"xướng\": người 亻 (nhân) xướng 昌 (xương) lên — 倡 là đề xướng, khởi xướng ý tưởng đầu tiên. | Gương Hán-Việt | xướng trong ''提倡 đề xướng'' (đề xướng), ''倡导 xướng đạo'' | Mở khoá kiến thức | Biết 倡 (xướng) mở khoá: 提倡 (đề xướng), 倡导 (khởi xướng dẫn dắt), 倡议 (đề xuất kiến nghị).", "Tự nguyên_Xie": "Đại triện | Tiểu triện | Theo Wiktionary, 倡 là chữ hình thanh (psc): 人 (nhân, biểu nghĩa: người) + 昌 (xương, biểu âm). Nghĩa gốc là người khởi xướng, dẫn đầu phong trào hay ý tưởng — người đứng lên xướng lên trước tiên. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nêu ra đầu tiên", "Hạng Tần Suất (Jun Da)": "2180.0", "Tần Suất % (Jun Da)": "97.7287438031", "GavinGrover_Once (Chiết tự trực tiếp)": "亻 + 昌", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰亻昌", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "昌", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "亻", "Unihan_Simplified (Chữ Giản thể)": "倡", "Unihan_Traditional (Chữ Phồn thể)": "倡", "Pinyin_Xie": "chàng", "Âm Hán Việt_Xie": "xướng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chữ này thường làm động từ đứng trước tân ngữ để biểu thị hành động khởi xướng hoặc đề xướng một phong trào. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('绵', '{"9000": "2181.0", "Chữ Trung Quốc": "绵", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 11 | nét | 纟 | mịch | biểu nghĩa | tơ, sợi | 帛 | bạch | biểu nghĩa/âm | lụa, vải (và cho âm mián) | 绵 là giản thể của 綿. Dạng phồn thể 綿 = 糹(tơ, biểu nghĩa) + 帛 (lụa, biểu nghĩa/âm). Hai bộ đều liên quan đến tơ lụa — hội ý: tơ mềm mại liên tiếp. Wiktionary dẫn đến 綿.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"miên\": tơ 纟mịn như lụa 帛 — sợi miên man kéo dài không dứt, mềm như bông tơ. | Gương Hán-Việt | miên miên (綿綿 — liên tục bất tuyệt), hải miên (海绵 — bọt biển) | Mở khoá kiến thức | Biết 绵 mở khoá: 海绵 (hải miên — bọt biển), 连绵 (liên miên — kéo dài liên tục), 绵延 (miên diên — trải dài).", "Tự nguyên_Xie": "Wiktionary ghi 绵 là giản thể của 綿. Dạng phồn thể 綿 là hội ý/hình thanh: 糹(tơ sợi, biểu nghĩa) + 帛 (lụa, biểu nghĩa). Nghĩa gốc: tơ thô, bông tơ tằm chưa xe. Mở rộng: mềm mại, kéo dài liên tục. Hán-Việt: ''miên''. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tơ tằm; kéo dài, liền; mềm mại", "Hạng Tần Suất (Jun Da)": "2181.0", "Tần Suất % (Jun Da)": "97.7316491692", "GavinGrover_Once (Chiết tự trực tiếp)": "纟 + 帛", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰纟帛", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "帛", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "纟", "Unihan_Simplified (Chữ Giản thể)": "绵", "Unihan_Traditional (Chữ Phồn thể)": "綿", "Pinyin_Xie": "mián", "Âm Hán Việt_Xie": "miên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Thường làm tính từ đứng trước danh từ hoặc sau phó từ để miêu tả trạng thái mềm mại hoặc kéo dài liên miên. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('猴', '{"9000": "2182.0", "Chữ Trung Quốc": "猴", "Bộ thủ & thành phần_Xie": "Bộ thủ | 犬 | Số nét | 12 | nét | 犭 | khuyển | biểu nghĩa | bộ thú (chó/thú vật) | 侯 | hầu | biểu âm | vương hầu, tước hầu | 猴 = 犭 (Khuyển, biểu nghĩa: thú vật) + 侯 (Hầu, biểu âm); chữ hình thanh. Bộ 犭 cho nghĩa là động vật, 侯 cho âm (hóu ~ hầu).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hầu\": thú 犭 (khuyển) mang tước hầu 侯 (hầu) — con khỉ 猴 trong 12 con giáp đứng hàng hầu tước. | Gương Hán-Việt | hầu trong ''hầu'' (khỉ trong 12 con giáp) | Mở khoá kiến thức | Biết 猴 (hầu) mở khoá: 猴子 (con khỉ), 猴年 (năm Thân), 猕猴 (khỉ đuôi dài).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 猴 là chữ hình thanh (psc): 犬 (khuyển, biểu nghĩa: thú/thú vật) + 侯 (hầu, biểu âm). Chữ dùng bộ khuyển chỉ loài thú nói chung, ghép với 侯 (hầu) cho âm để chỉ riêng con khỉ. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1323.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Khuyển (058) Hầu (1322)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Khuyển (số 058 - con chó/thú/ 犭/chỉ ý) ở bên trái chữ Hầu (số 1322 - tước hầu/chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Hầu (侯) chỉ âm, bộ Khuyển (犭) chỉ ý. Hầu là con khỉ (macaque).", "Nghĩa Tiếng Việt_Xie": "con khỉ", "Hạng Tần Suất (Jun Da)": "2182.0", "Tần Suất % (Jun Da)": "97.7345338638", "GavinGrover_Once (Chiết tự trực tiếp)": "犭 + 侯", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰犭侯", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "侯", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "犭", "Unihan_Simplified (Chữ Giản thể)": "猴", "Unihan_Traditional (Chữ Phồn thể)": "猴", "Pinyin_Xie": "hóu", "Âm Hán Việt_Xie": "hầu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ con khỉ, làm chủ ngữ hoặc tân ngữ trong câu và kết hợp với lượng từ chỉ động vật. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | Từ ghép nghĩa | 猴 = con khỉ. 属猴 = tuổi Khỉ (12 con giáp). 猴子 = con khỉ (noun with diminutive). | / | hóu | / | khỉ | Xuất hiện trong lộ trình | New HSK | New HSK 5 | · | Thiên nhiên", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('枯', '{"9000": "2183.0", "Chữ Trung Quốc": "枯", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 9 | nét | 木 | mộc | biểu nghĩa | cây, gỗ | 古 | cổ | biểu âm | cổ xưa (cho âm kū) | 枯 = 木 (Mộc, biểu nghĩa: cây) + 古 (Cổ, biểu âm); chữ hình thanh. Bộ mộc chỉ đây liên quan đến cây; 古 cung cấp âm (kū). Cây khô héo — hình ảnh cổ xưa của sự tàn lụi.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khô\": cây (木) cổ xưa (古/cổ) — cây khô héo từ lâu, tẻ nhạt không còn sức sống. | Gương Hán-Việt | khô trong 枯燥 (khô táo — nhàm chán, tẻ nhạt) | Mở khoá kiến thức | Biết 枯 (khô) mở khoá: 枯燥 (nhàm chán), 枯竭 (khô cạn), 枯萎 (héo tàn), 摧枯拉朽 (phá dễ như bẻ cành khô).", "Tự nguyên_Xie": "Theo Wiktionary, 枯 là chữ hình thanh: bộ 木 biểu nghĩa (cây — khô héo), 古 biểu âm. Nghĩa gốc là khô héo (cây cối thiếu nước). Mở rộng sang khô cạn, tẻ nhạt. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "394.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Mộc (108) Cổ (8)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Mộc (số 79 - cây gỗ) và chữ Cổ (số 22 - cũ, xưa) . Cây cối già cỗi theo thời gian, mất nhựa sống và héo tàn gọi là khô héo. Giải thích sự chuyển ý: Chữ Cổ (cũ xưa) chỉ âm, chữ Mộc (gỗ) chỉ ý. Cây (Mộc) sống quá lâu năm (Cổ) thì khô héo, cạn kiệt sự sống (Khô). *(Biến âm Hán Việt: Cổ -> Khô)*", "Nghĩa Tiếng Việt_Xie": "héo hon (cây); khô, cạn", "Hạng Tần Suất (Jun Da)": "2183.0", "Tần Suất % (Jun Da)": "97.7374185584", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 古", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木古", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "古", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "枯", "Unihan_Traditional (Chữ Phồn thể)": "枯", "Pinyin_Xie": "kū", "Âm Hán Việt_Xie": "khô", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường làm tính từ bổ nghĩa cho danh từ hoặc làm vị ngữ để miêu tả trạng thái khô héo của cây cối, nguồn nước. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('巫', '{"9000": "2184.0", "Chữ Trung Quốc": "巫", "Bộ thủ & thành phần_Xie": "Bộ thủ | 工 | Số nét | 7 | nét | 工 | công | biểu nghĩa | công cụ nghi lễ | 从 | tòng | biểu nghĩa | người (hai người đứng hai bên) | 巫 theo Wiktionary có nguồn gốc chưa rõ ràng. Cấu trúc hiện tại gồm 工 (công cụ) + 从 (hai người), có thể hội ý: thầy cúng đứng giữa hai thế giới, cầm công cụ nghi lễ. Một thuyết cho đây là hình ảnh bốn phương trời (四荒).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"vu\": thầy vu (巫) đứng giữa công cụ 工 và hai thế giới 从 — cầu nối âm dương. | Gương Hán-Việt | vu thuật (巫術 — phép phù thuỷ), vu bà (巫婆 — mụ phù thuỷ) | Mở khoá kiến thức | Biết 巫 mở khoá: 巫术 (vu thuật — ma thuật), 巫婆 (vu bà — mụ phù thuỷ), 巫医 (vu y — thầy thuốc phù thuỷ).", "Tự nguyên_Xie": "Kim văn | Bạch thư | Đại triện | Tiểu triện | Theo Wiktionary, nguồn gốc của 巫 còn tranh cãi. Một thuyết cho là hình ảnh ''bốn phương trời'' (四荒) trong văn bản cổ. Cấu trúc nhìn thấy được: 工 + 从 — có thể là thầy cúng đứng giữa hai người, thực hiện nghi lễ cầu nối giữa trời và đất. Nghĩa: đồng cốt, thầy phù thuỷ. Hán-Việt: ''vu''. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đồng cốt, cầu cúng", "Hạng Tần Suất (Jun Da)": "2184.0", "Tần Suất % (Jun Da)": "97.7403001523", "GavinGrover_Once (Chiết tự trực tiếp)": "工 + 从", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴工从", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "从", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "工", "Unihan_Simplified (Chữ Giản thể)": "巫", "Unihan_Traditional (Chữ Phồn thể)": "巫", "Pinyin_Xie": "wū", "Âm Hán Việt_Xie": "vu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ người làm nghề cúng bái, tế lễ hoặc làm định ngữ trong các cụm danh từ liên quan đến tâm linh. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('昭', '{"9000": "2185.0", "Chữ Trung Quốc": "昭", "Bộ thủ & thành phần_Xie": "Bộ thủ | 日 | Số nét | 9 | nét | 日 | nhật | biểu nghĩa | mặt trời, ánh sáng | 召 | thiệu | biểu âm | cho âm zhāo | 昭 = 日 (Nhật, biểu nghĩa: mặt trời/ánh sáng) + 召 (Thiệu, biểu âm); chữ hình thanh. Bộ 日 xác định nghĩa liên quan đến ánh sáng/sáng suốt, phần 召 cho âm đọc zhāo.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chiêu\": mặt trời 日 chiêu sáng — ánh 昭 chiêu rõ rệt không che giấu được. | Gương Hán-Việt | chiêu tuyết (昭雪 — minh oan), chiêu nhiên (昭然 — rõ ràng) | Mở khoá kiến thức | Biết 昭 mở khoá: 昭示 (chiêu thị — chỉ rõ), 昭雪 (chiêu tuyết — minh oan), 昭然若揭 (chiêu nhiên nhược kiệt — rõ như ban ngày).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Theo Wiktionary, 昭 là hình thanh: 日 (mặt trời/ánh sáng, biểu nghĩa) + 召 (biểu âm). Nghĩa gốc: rõ ràng, sáng sủa (như ánh mặt trời chiếu soi). Mở rộng: hiển lộ, rõ rệt. Hán-Việt: ''chiêu''. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "453.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Nhật (80) Triệu (325)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Nhật (số 72 - mặt trời) và chữ Triệu (số 329 - gọi) . Ánh sáng mặt trời (Nhật) chiếu rọi làm mọi thứ được gọi (Triệu) ra hiển hiện thật sáng sủa, rõ ràng. Giải thích sự chuyển ý: Chữ Triệu (triệu tập/gọi) chỉ âm, chữ Nhật (mặt trời) chỉ ý. Ánh sáng rực rỡ, phơi bày vạn vật cho thấy rõ rệt (Chiêu). *(Biến âm Hán Việt: Triệu -> Chiêu)*", "Nghĩa Tiếng Việt_Xie": "sáng sủa, rõ rệt", "Hạng Tần Suất (Jun Da)": "2185.0", "Tần Suất % (Jun Da)": "97.7431781287", "GavinGrover_Once (Chiết tự trực tiếp)": "日 + 召", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰日召", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "召", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "日", "Unihan_Simplified (Chữ Giản thể)": "昭", "Unihan_Traditional (Chữ Phồn thể)": "昭", "Pinyin_Xie": "zhāo", "Âm Hán Việt_Xie": "chiêu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường làm tính từ miêu tả sự rõ ràng, minh bạch hoặc làm động từ với nghĩa làm cho sáng tỏ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('怔', '{"9000": "2186.0", "Chữ Trung Quốc": "怔", "Bộ thủ & thành phần_Xie": "Bộ thủ | 心 | Số nét | 8 | nét | 忄 | tâm | biểu nghĩa | tâm trạng, cảm xúc | 正 | chinh | biểu âm | cho âm zhēng | 怔 = 忄(Tâm, biểu nghĩa: tâm trạng/cảm xúc) + 正 (Chinh, biểu âm); chữ hình thanh. Bộ 忄xác định nghĩa liên quan đến tâm lý, phần 正 cho âm đọc zhēng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chinh\": tim 忄đóng băng chinh — đứng đơ sợ hãi như bị đứng chinh, không nhúc nhích được. | Gương Hán-Việt | chinh chinh (怔怔 — đờ người, ngơ ngẩn) | Mở khoá kiến thức | Biết 怔 mở khoá: 怔忪 (chinh tung — bất an), 怔怔 (chinh chinh — đờ người ngơ ngẩn), 吓怔 (giật mình đứng đơ).", "Tự nguyên_Xie": "Theo Wiktionary, 怔 là hình thanh: 心/忄(tâm, biểu nghĩa) + 正 (biểu âm). Nghĩa: sợ run, ngơ ngẩn, đờ người ra vì bất ngờ hoặc sợ hãi. Hán-Việt: ''chinh''. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sợ run", "Hạng Tần Suất (Jun Da)": "2186.0", "Tần Suất % (Jun Da)": "97.7460519709", "GavinGrover_Once (Chiết tự trực tiếp)": "忄 + 正", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰忄正", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "正", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "忄", "Unihan_Simplified (Chữ Giản thể)": "怔", "Unihan_Traditional (Chữ Phồn thể)": "怔", "Pinyin_Xie": "zhēng", "Âm Hán Việt_Xie": "chinh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Thường dùng làm động từ trạng thái biểu thị sự sững sờ, ngơ ngác do giật mình hoặc lo sợ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('渊', '{"9000": "2187.0", "Chữ Trung Quốc": "渊", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 11 | nét | 氵 | thuỷ | biểu nghĩa | nước | 𫂱 | biểu hình | hình ảnh vực nước (chứa 米 biến thể) | 渊 là giản thể của 淵. Trong giáp cốt văn, 渊 (dạng cổ 𣶒) là tượng hình: hình ảnh một vực nước. Kim văn thêm các nét dọc như bờ vực và bộ 氵. Chữ tượng hình biến thể thành hình thanh phức hợp qua nhiều giai đoạn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"uyên\": vực 渊 sâu uyên thâm — nước 氵sâu đến không dò được đáy, như kiến thức uyên bác. | Gương Hán-Việt | uyên thâm (淵深 — sâu sắc uyên bác), uyên nguyên (淵源 — nguồn gốc sâu xa) | Mở khoá kiến thức | Biết 渊 mở khoá: 渊源 (uyên nguyên — nguồn gốc), 天渊 (thiên uyên — trời vực, cách biệt xa), 渊博 (uyên bác — uyên thâm).", "Tự nguyên_Xie": "Giáp cốt văn | Kim văn | Lục thư thông | Theo Wiktionary, dạng gốc trong giáp cốt văn là 𣶒 — tượng hình vực nước (như hình miệng giếng tròn với nước). Kim văn thêm các nét thẳng đứng giống bờ vực và bộ 氵(nước). So sánh với chữ tượng hình Ai Cập 𓈙. Nghĩa: vực sâu, nơi nước sâu thẳm. Hán-Việt: ''uyên''. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "vực sâu", "Hạng Tần Suất (Jun Da)": "2187.0", "Tần Suất % (Jun Da)": "97.7489206452", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 𫃢", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵𫃢", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "𫃢", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "渊", "Unihan_Traditional (Chữ Phồn thể)": "淵", "Pinyin_Xie": "yuān", "Âm Hán Việt_Xie": "uyên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Thường làm danh từ chỉ vực nước sâu hoặc làm tính từ miêu tả sự sâu sắc, uyên bác của tri thức. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('凑', '{"9000": "2188.0", "Chữ Trung Quốc": "凑", "Bộ thủ & thành phần_Xie": "Bộ thủ | 冫 | Số nét | 11 | nét | 冫 | băng | biểu nghĩa | nước, lạnh (bộ băng giản thể) | 奏 | tấu | biểu âm | tâu, diễn tấu (cho âm còu) | 凑 là giản thể của 湊, vốn dùng bộ 水 (氵). Dạng giản thể dùng 冫 (băng giản thể của 氵/water radical). 凑 = 冫(biểu nghĩa: nước) + 奏 (Tấu, biểu âm); chữ hình thanh. Bộ nước gợi ý tụ hội như nước chảy về; 奏 cung cấp âm (còu).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thấu\": mọi thứ tụ về (冫) như nốt nhạc hội tấu (奏/tấu) — thấu hội, tụ lại cho đủ số. | Gương Hán-Việt | thấu trong 凑合 (thấu hợp — tạm bợ, qua loa) | Mở khoá kiến thức | Biết 凑 (thấu) mở khoá: 凑合 (tạm bợ), 凑巧 (may mắn tình cờ), 紧凑 (gọn gàng, chặt chẽ).", "Tự nguyên_Xie": "凑 là dị thể giản hoá của 湊 (theo Wiktionary, 湊 dùng bộ 水). Nghĩa gốc là tụ hội, dồn lại; sau mở rộng sang xáp lại gần, lợi dụng cơ hội, tạm được. Chưa có nguồn glyph-origin chi tiết cho dạng 凑 trong Wiktionary. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "gần, cùng", "Hạng Tần Suất (Jun Da)": "2188.0", "Tần Suất % (Jun Da)": "97.7517857019", "GavinGrover_Once (Chiết tự trực tiếp)": "冫 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰冫", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "凑", "Unihan_Traditional (Chữ Phồn thể)": "湊", "Pinyin_Xie": "còu", "Âm Hán Việt_Xie": "thấu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước tân ngữ để biểu thị hành động thu gom cho đủ số lượng hoặc tiến lại gần một vị trí. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | còu | / | tập hợp | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Sự liên quan", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('溪', '{"9000": "2189.0", "Chữ Trung Quốc": "溪", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 13 | nét | 氵 | thuỷ | biểu nghĩa | nước | 奚 | hề | biểu âm | sao vậy, kẻ hầu (cho âm xī) | 溪 = 氵(Thuỷ, biểu nghĩa: nước) + 奚 (Hề, biểu âm); chữ hình thanh. Bộ thuỷ chỉ đây là dòng nước; 奚 cung cấp âm (xī). Dòng suối nhỏ chảy nhẹ nhàng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khê\": nước (氵) trong trẻo như người hầu (奚/hề) chăm chỉ — khê suối chảy mãi không ngừng. | Gương Hán-Việt | khê trong 小溪 (tiểu khê — suối nhỏ); 溪流 (khê lưu — dòng suối) | Mở khoá kiến thức | Biết 溪 (khê) mở khoá: 小溪 (suối nhỏ), 溪流 (dòng suối), 山溪 (suối núi).", "Tự nguyên_Xie": "Theo Wiktionary, 溪 là chữ hình thanh: bộ 水 (氵) biểu nghĩa (nước — dòng nước nhỏ), 奚 biểu âm. Nghĩa gốc và duy nhất là suối, lạch — dòng nước nhỏ. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "dòng suối, lạch", "Hạng Tần Suất (Jun Da)": "2189.0", "Tần Suất % (Jun Da)": "97.7546502419", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 奚", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵奚", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "奚", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "溪", "Unihan_Traditional (Chữ Phồn thể)": "溪", "Pinyin_Xie": "xī", "Âm Hán Việt_Xie": "khê", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ địa hình dòng nước chảy, có thể đứng độc lập hoặc kết hợp với các từ chỉ phương hướng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | xī | / | suối nhỏ | Xuất hiện trong lộ trình | HSK | HSK 6 | · | Địa lý", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蠢', '{"9000": "2190.0", "Chữ Trung Quốc": "蠢", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 21 | nét | 春 | xuân | biểu âm | mùa xuân (cho âm chǔn) | 䖵 | biểu nghĩa | hai con trùng (biểu nghĩa: sâu bọ ngọ nguậy) | 蠢 = 春 (Xuân, biểu âm) + 䖵 (hai bộ 虫 xếp chồng, biểu nghĩa: sâu bọ); chữ hình thanh. Bộ trùng (×2) gợi hình ảnh sâu bọ ngọ nguậy; 春 cung cấp âm (chǔn). Từ sâu bọ ngọ nguậy mở rộng sang ngu ngốc, vụng về.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"xuẩn\": sâu bọ (䖵) mùa xuân (春/xuân) ngọ nguậy không định hướng — xuẩn ngốc, hành động vô nghĩa. | Gương Hán-Việt | xuẩn trong 愚蠢 (ngu xuẩn — ngu ngốc) | Mở khoá kiến thức | Biết 蠢 (xuẩn) mở khoá: 愚蠢 (ngu ngốc), 蠢蠢欲动 (ngọ nguậy muốn hành động), 蠢货 (thằng ngốc).", "Tự nguyên_Xie": "Theo Wiktionary, 蠢 là chữ hình thanh: 春 biểu âm, 䖵 (hai chữ 虫 xếp chồng — sâu bọ) biểu nghĩa. Nghĩa gốc là ngọ nguậy, cựa quậy (như sâu bọ mùa xuân thức dậy); mở rộng sang ngu ngốc, vụng về. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ngọ nguậy; con sâu; ngu, ngốc, đần độn; vụng về, chậm chạp", "Hạng Tần Suất (Jun Da)": "2190.0", "Tần Suất % (Jun Da)": "97.7575142652", "GavinGrover_Once (Chiết tự trực tiếp)": "春 + 䖵", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱春䖵", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "䖵", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "春", "Unihan_Simplified (Chữ Giản thể)": "蠢", "Unihan_Traditional (Chữ Phồn thể)": "惷", "Pinyin_Xie": "chǔn", "Âm Hán Việt_Xie": "xuẩn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường làm tính từ đứng trước danh từ để tu sức hoặc đứng sau phó từ chỉ mức độ để làm vị ngữ trong câu. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | chǔn | / | ngu ngốc | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Tính cách II", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('禅', '{"9000": "2191.0", "Chữ Trung Quốc": "禅", "Bộ thủ & thành phần_Xie": "Bộ thủ | 示 | Số nét | 12 | nét | 礻 | thị | biểu nghĩa | thần/lễ nghi | 单 | thiện | biểu âm | cho âm chán | 禅 là giản thể của 禪: 礻(Thị, biểu nghĩa: nghi lễ/thần linh) + 单/單 (Thiện, biểu âm); chữ hình thanh. Bộ 礻xác định nghĩa liên quan đến lễ tế, phần 单 cho âm đọc chán.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thiền\": lễ 礻thiền định — ngồi tĩnh lặng đơn độc 单, tâm trở về trạng thái thiền. | Gương Hán-Việt | thiền định (禪定), thiền nhượng (禪讓 — nhường ngôi) | Mở khoá kiến thức | Biết 禅 mở khoá: 禅定 (thiền định — thiền tập), 禅宗 (thiền tông), 禅让 (thiền nhượng — nhường ngôi).", "Tự nguyên_Xie": "Đại triện | Tiểu triện | Theo Wiktionary, 禅 là giản thể của 禪. Dạng phồn thể 禪 = 示 (nghi lễ, biểu nghĩa) + 單 (biểu âm). Nghĩa gốc: 禪 chỉ việc tế lễ trên đất bằng (đối với phong 封 là tế trên núi). Về sau dùng trong Phật giáo cho âm ''Thiền'' (dhyāna). Nghĩa khác: thiện nhượng (禪讓 — nhường ngôi). Hán-Việt: ''thiền''. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "quét đất để tế; trao cho, truyền cho", "Hạng Tần Suất (Jun Da)": "2191.0", "Tần Suất % (Jun Da)": "97.7603772548", "GavinGrover_Once (Chiết tự trực tiếp)": "礻 + 单", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰礻单", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "单", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "礻", "Unihan_Simplified (Chữ Giản thể)": "禅", "Unihan_Traditional (Chữ Phồn thể)": "禪", "Pinyin_Xie": "chán", "Âm Hán Việt_Xie": "thiền, thiện", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường làm danh từ chỉ giáo lý nhà Phật hoặc trạng thái tĩnh tâm, cũng có thể kết hợp với các động từ khác. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('阐', '{"9000": "2192.0", "Chữ Trung Quốc": "阐", "Bộ thủ & thành phần_Xie": "Bộ thủ | 門 | Số nét | 11 | nét | 门 | môn | biểu nghĩa | cửa, cổng | 单 | thiện | biểu âm | đơn, thiện (cho âm chǎn) | 阐 = 门 (Môn, biểu nghĩa: cửa) + 单 (Thiện, biểu âm); chữ hình thanh. Phồn thể là 闡. Bộ môn gợi ý mở cửa để soi sáng, giải thích; 单 cung cấp âm (chǎn).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"xiển\": mở cánh cửa (门) rộng ra — xiển dương, giải thích làm sáng tỏ điều còn kín. | Gương Hán-Việt | xiển trong 阐述 (xiển thuật — trình bày, giải thích rõ) | Mở khoá kiến thức | Biết 阐 (xiển) mở khoá: 阐述 (trình bày), 阐明 (làm sáng tỏ), 阐释 (giải thích).", "Tự nguyên_Xie": "阐 (phồn thể 闡) là chữ hình thanh: theo Wiktionary, bộ 門 biểu nghĩa (cửa — mở ra, khai sáng), 單 biểu âm. Nghĩa gốc là mở rộng, khai triển; sau mở rộng sang giải thích, trình bày rõ. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mở ra", "Hạng Tần Suất (Jun Da)": "2192.0", "Tần Suất % (Jun Da)": "97.7632361102", "GavinGrover_Once (Chiết tự trực tiếp)": "门 + 单", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿵ (Bao quanh phía trên)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴门单", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "单", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "门", "Unihan_Simplified (Chữ Giản thể)": "阐", "Unihan_Traditional (Chữ Phồn thể)": "闡", "Pinyin_Xie": "chǎn", "Âm Hán Việt_Xie": "xiển", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này thường làm động từ đứng trước tân ngữ để diễn tả hành động giải thích hoặc làm rõ một lý luận. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('旺', '{"9000": "2193.0", "Chữ Trung Quốc": "旺", "Bộ thủ & thành phần_Xie": "Bộ thủ | 日 | Số nét | 8 | nét | 日 | nhật | biểu nghĩa | mặt trời, ngày | 王 | vương | biểu âm | vua (cho âm wàng) | 旺 = 日 (Nhật, biểu nghĩa: mặt trời) + 王 (Vương, biểu âm); chữ hình thanh. Ban đầu là giản hoá của 暀 (日 + 往). Bộ nhật gợi ý ánh sáng, hưng thịnh; 王 cung cấp âm (wàng) và hình thức hiện tại.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"vượng\": mặt trời (日) chiếu sáng trên vị vua (王/vương) — vượng phát, thịnh vượng rực rỡ. | Gương Hán-Việt | vượng trong 兴旺 (hưng vượng — hưng thịnh, phát đạt) | Mở khoá kiến thức | Biết 旺 (vượng) mở khoá: 兴旺 (hưng thịnh), 旺季 (mùa cao điểm), 旺盛 (mạnh mẽ, dồi dào).", "Tự nguyên_Xie": "Theo Wiktionary, 旺 ban đầu là dạng giản hoá của 暀, vốn là chữ hình thanh (日 biểu nghĩa, 往 biểu âm). Dạng hiện tại tái phân tích thành 日 (biểu nghĩa: mặt trời) + 王 (biểu âm). Nghĩa gốc là tươi sáng, hưng thịnh; mở rộng sang thịnh vượng, mùa cao điểm. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "452.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Nhật (80) Vương (137)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Nhật (số 72 - mặt trời) và chữ Vương (số 96 - vua) . Mặt trời (Nhật) tỏa sáng rực rỡ uy quyền như sức mạnh của một vị vua (Vương), tượng trưng cho sự thịnh vượng. Giải thích sự chuyển ý: Chữ Vương (vua) chỉ âm, chữ Nhật (mặt trời) chỉ ý. Khí thế bừng bừng như mặt trời sáng rực (Vượng). *(Biến âm Hán Việt: Vương -> Vượng)*", "Nghĩa Tiếng Việt_Xie": "thịnh vượng; nở rộ (hoa)", "Hạng Tần Suất (Jun Da)": "2193.0", "Tần Suất % (Jun Da)": "97.7660934152", "GavinGrover_Once (Chiết tự trực tiếp)": "日 + 王", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰日王", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "王", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "日", "Unihan_Simplified (Chữ Giản thể)": "旺", "Unihan_Traditional (Chữ Phồn thể)": "旺", "Pinyin_Xie": "wàng", "Âm Hán Việt_Xie": "vượng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này làm tính từ bổ nghĩa cho danh từ hoặc đứng sau phó từ chỉ mức độ để miêu tả sự phát triển mạnh mẽ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | wàng | / | thịnh vượng | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Đặc điểm III", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('寓', '{"9000": "2194.0", "Chữ Trung Quốc": "寓", "Bộ thủ & thành phần_Xie": "Bộ thủ | 宀 | Số nét | 12 | nét | 宀 | miên | biểu nghĩa | mái nhà | 禺 | ngẫu | biểu âm | loài khỉ (gần âm yù) | 寓 = 宀 (Miên, biểu nghĩa: mái nhà) + 禺 (Ngẫu, biểu âm); chữ hình thanh. Ngôi nhà ở tạm, gốc nghĩa ''ngụ cư, ở tạm'', mở rộng sang ''ngụ ý, ẩn dụ''.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ngụ\": 宀 (mái nhà) + 禺 (Ngẫu) — gửi thân dưới mái nhà, đúng nghĩa ''ngụ cư, ngụ ý'' trong 公寓 (căn hộ), 寓言 (ngụ ngôn), 寓意 (ngụ ý). | Gương Hán-Việt | ''ngụ'' trong ''ngụ cư'', ''ngụ ngôn'', ''ký ngụ'' | Mở khoá kiến thức | Nắm 寓 mở khoá loạt từ HSK 5-7: 公寓, 寓言, 寓意.", "Tự nguyên_Xie": "Kim văn | Tiểu triện | Lục thư thông | Theo Wiktionary, 寓 là hình thanh: 宀 (mái nhà, biểu nghĩa) + 禺 (Ngẫu, biểu âm). Nghĩa gốc ''ngụ cư, ở tạm trong một ngôi nhà'', mở rộng sang nghĩa trừu tượng ''gửi gắm, ẩn dụ'' (寓言 — ngụ ngôn, 寓意 — ý nghĩa ẩn dụ). 公寓 là ''căn hộ'' trong tiếng Trung hiện đại. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nhờ cậy; nói bóng gió", "Hạng Tần Suất (Jun Da)": "2194.0", "Tần Suất % (Jun Da)": "97.7689455523", "GavinGrover_Once (Chiết tự trực tiếp)": "宀 + 禺", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱宀禺", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "禺", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "宀", "Unihan_Simplified (Chữ Giản thể)": "寓", "Unihan_Traditional (Chữ Phồn thể)": "寓", "Pinyin_Xie": "yù", "Âm Hán Việt_Xie": "ngụ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chữ này thường làm động từ thể hiện việc gửi gắm ý tứ hoặc trú ngụ, và làm danh từ trong các từ ghép chỉ nơi ở. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('藤', '{"9000": "2195.0", "Chữ Trung Quốc": "藤", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 18 | nét | 艹 | thảo | biểu nghĩa | cỏ/thực vật | 滕 | đằng | biểu âm | cho âm téng | 藤 = 艹(Thảo, biểu nghĩa: thực vật) + 滕 (Đằng, biểu âm); chữ hình thanh. Bộ 艹xác định đây là loại cây/dây leo, phần 滕 cho âm đọc téng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đằng\": dây leo 藤 đằng dài — 艹mọc theo 滕 vươn lên, đan kết thành ghế mây đằng đẵng. | Gương Hán-Việt | đằng la (藤蘿 — dây leo tử đằng), thường xuân đằng (常春藤 — dây thường xuân) | Mở khoá kiến thức | Biết 藤 mở khoá: 藤椅 (đằng ỷ — ghế mây), 藤条 (đằng điều — roi mây), 常春藤 (thường xuân đằng — ivy), 攀藤 (leo dây).", "Tự nguyên_Xie": "Theo Wiktionary, 藤 là hình thanh: 艸/艹 (cỏ, biểu nghĩa) + 滕 (biểu âm) — chỉ loại cây leo. Nghĩa gốc: dây leo, mây (rattan). Dùng trong đồ nội thất (ghế mây, giỏ mây). Hán-Việt: ''đằng''. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bụi cây; dây buộc", "Hạng Tần Suất (Jun Da)": "2195.0", "Tần Suất % (Jun Da)": "97.7717951056", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 滕", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹滕", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "滕", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "藤", "Unihan_Traditional (Chữ Phồn thể)": "籐", "Pinyin_Xie": "téng", "Âm Hán Việt_Xie": "đằng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ các loại cây dây leo hoặc chất liệu mây tre, thường đứng độc lập hoặc làm định ngữ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('匪', '{"9000": "2196.0", "Chữ Trung Quốc": "匪", "Bộ thủ & thành phần_Xie": "Bộ thủ | 匚 | Số nét | 10 | nét | 匚 | phương | biểu nghĩa | hộp/khung (vật chứa) | 非 | phi | biểu âm | cho âm fěi | 匪 = 匚 (Phương, biểu nghĩa: hộp chứa — gợi ý giấu đồ/cất giữ bất hợp pháp) + 非 (Phi, biểu âm); chữ hình thanh. Bộ 匚 và 非 kết hợp: người cất giữ đồ không hợp lệ — kẻ cướp.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phỉ\": kẻ phỉ (匪) cất đồ gian vào hộp 匚 — phi (非) pháp, cướp bóc. | Gương Hán-Việt | phỉ đảng (匪徒 — bọn cướp), thổ phỉ (土匪 — tên cướp địa phương) | Mở khoá kiến thức | Biết 匪 mở khoá: 土匪 (thổ phỉ — tên cướp), 匪徒 (phỉ đồ — bọn cướp), 匪夷所思 (phỉ di sở tư — khó tưởng tượng).", "Tự nguyên_Xie": "Đại triện | Tiểu triện | Theo Wiktionary, 匪 là hình thanh: 匚 (hộp, biểu nghĩa) + 非 (biểu âm). Nghĩa gốc: kẻ cướp, tên phỉ. Trong văn cổ còn có nghĩa phủ định ''không phải''. Hán-Việt: ''phỉ''. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "không phải; phỉ, giặc, cướp", "Hạng Tần Suất (Jun Da)": "2196.0", "Tần Suất % (Jun Da)": "97.7746431084", "GavinGrover_Once (Chiết tự trực tiếp)": "匚 + 非", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿷ (Bao quanh phía trái)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴匚非", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "非", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "匚", "Unihan_Simplified (Chữ Giản thể)": "匪", "Unihan_Traditional (Chữ Phồn thể)": "匪", "Pinyin_Xie": "fěi", "Âm Hán Việt_Xie": "phỉ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Phó từ | 副词 | Chữ này chủ yếu làm danh từ chỉ kẻ cướp, phiến quân hoặc làm phó từ phủ định trong văn ngôn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Phó từ | 副词 | Bổ nghĩa cho động từ hoặc tính từ và luôn đứng TRƯỚC chúng — 都是, 很好. Không đứng sau như tiếng Việt và không bổ nghĩa cho danh từ.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('伞', '{"9000": "2197.0", "Chữ Trung Quốc": "伞", "Bộ thủ & thành phần_Xie": "Bộ thủ | 人 | Số nét | 6 | nét | 人 | nhân | biểu hình | phần trên giống hình nón che – mái dù | 十 | thập | biểu hình | phần thân ô – cán dù | 伞 là dạng giản thể của 傘, vốn là chữ tượng hình vẽ một chiếc ô đang mở: phần đỉnh 人 là vòm dù, các nét 丷 là gọng dù, và 十 là cán dù. Khi giản hoá, các gọng phụ được rút gọn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tản\": mái vòm 人 ở trên, các gọng 丷 bung ra, cán 十 ở dưới – đó là cái ô; nên 伞 nghĩa là cái ô, cái dù, cái tán. | Gương Hán-Việt | \"tản\" trong tản (cái tán, mái che, ví dụ kim tản hoa cái); cùng âm với 散 \"tản\" trong tản mạn. | Mở khoá kiến thức | Nhớ 伞 mở khoá: 伞, 雨伞, 太阳伞, 跳伞, 打伞.", "Tự nguyên_Xie": "Tiểu triện | 伞 là dạng giản thể của 傘, một chữ tượng hình mô tả chiếc ô đang mở: phần đỉnh giống mái vòm, các nét bên trong là gọng dù (vốn là 𠈌 – 4 người tượng trưng 4 gọng) và phần dưới là cán dù 十. Khi giản hoá, các gọng phụ 𠈌 được rút gọn thành 丷, tạo nên dạng 伞 hiện nay. Nghĩa của chữ là \"cái ô, cái dù\". | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái tán; (tên núi)", "Hạng Tần Suất (Jun Da)": "2197.0", "Tần Suất % (Jun Da)": "97.7774911113", "GavinGrover_Once (Chiết tự trực tiếp)": "人 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱人", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "伞", "Unihan_Traditional (Chữ Phồn thể)": "傘", "Pinyin_Xie": "sǎn", "Âm Hán Việt_Xie": "tản", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ cái ô che mưa nắng hoặc vật có hình dáng tương tự, thường đi kèm lượng từ bả. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | sǎn | / | cái ô | Xuất hiện trong lộ trình | New HSK | New HSK 4 | · | Quần áo và ngoại hình | YCT | YCT 4 | · | Quần áo và phụ kiện | HSK | HSK 3 | · | Nhà và gia đình", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('碑', '{"9000": "2198.0", "Chữ Trung Quốc": "碑", "Bộ thủ & thành phần_Xie": "Bộ thủ | 石 | Số nét | 13 | nét | 石 | thạch | biểu nghĩa | đá | 卑 | ti | biểu âm | thấp kém (cho âm bēi) | 碑 = 石 (Thạch, biểu nghĩa: đá) + 卑 (Ti, biểu âm); chữ hình thanh. Bộ thạch chỉ đây là vật bằng đá; 卑 cung cấp âm (bēi). Bia đá dựng để kỷ niệm hay đánh dấu.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bi\": tảng đá (石) thấp kém (卑/ti) dựng lên — bia bi thương, bia mộ đứng mãi theo năm tháng. | Gương Hán-Việt | bi trong 里程碑 (lý trình bi — cột mốc), 纪念碑 (kỷ niệm bi — đài tưởng niệm) | Mở khoá kiến thức | Biết 碑 (bi) mở khoá: 里程碑 (cột mốc), 纪念碑 (đài tưởng niệm), 墓碑 (bia mộ), 口碑 (tiếng thơm).", "Tự nguyên_Xie": "Theo Wiktionary, 碑 là chữ hình thanh: bộ 石 biểu nghĩa (đá — tấm đá dựng đứng), 卑 biểu âm. Nghĩa gốc là tấm đá dựng đứng để đánh dấu; mở rộng sang bia mộ, đài tưởng niệm, cột mốc. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái bia, đài bia; cột mốc; ca tụng", "Hạng Tần Suất (Jun Da)": "2198.0", "Tần Suất % (Jun Da)": "97.7803380806", "GavinGrover_Once (Chiết tự trực tiếp)": "石 + 卑", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰石卑", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "卑", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "石", "Unihan_Simplified (Chữ Giản thể)": "碑", "Unihan_Traditional (Chữ Phồn thể)": "碑", "Pinyin_Xie": "bēi", "Âm Hán Việt_Xie": "bi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ tấm bia đá khắc chữ, thường kết hợp với lượng từ khối hoặc tòa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | bēi | / | bia đá | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Вuildings và công trình xây dựng", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('挪', '{"9000": "2199.0", "Chữ Trung Quốc": "挪", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 9 | nét | 扌 | thủ | biểu nghĩa | tay, hành động bằng tay | 那 | na | biểu âm | đó, kia (cho âm nuó) | 挪 = 扌(Thủ, biểu nghĩa: tay) + 那 (Na, biểu âm); chữ hình thanh. Bộ thủ chỉ hành động di chuyển bằng tay; 那 cung cấp âm (nuó).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"na\": tay (扌) đẩy ''na đây na đó'' — na dịch, chuyển vật từ chỗ này sang chỗ khác. | Gương Hán-Việt | na trong 挪动 (na động — dịch chuyển, di dời) | Mở khoá kiến thức | Biết 挪 (na) mở khoá: 挪动 (dịch chuyển), 挪用 (chiếm dụng vốn), 腾挪 (xoay xở).", "Tự nguyên_Xie": "Theo Wiktionary, 挪 là chữ hình thanh: bộ 手 (扌) biểu nghĩa (tay — đẩy, dịch chuyển), 那 biểu âm. Nghĩa gốc và duy nhất là dời chỗ, di chuyển sang một bên. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chuyển dời", "Hạng Tần Suất (Jun Da)": "2199.0", "Tần Suất % (Jun Da)": "97.7831803989", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 那", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌那", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "那", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "挪", "Unihan_Traditional (Chữ Phồn thể)": "挪", "Pinyin_Xie": "nuó", "Âm Hán Việt_Xie": "na", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ chỉ hành động di chuyển vị trí của đồ vật hoặc tiền bạc, thường mang tân ngữ phía sau. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | nuó | / | di chuyển | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Phong trào I | HSK | HSK 6 | · | Sự chuyển động", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('琼', '{"9000": "2200.0", "Chữ Trung Quốc": "琼", "Bộ thủ & thành phần_Xie": "Bộ thủ | 玉 | Số nét | 12 | nét | 王 | vương | biểu nghĩa | ngọc (bộ 玉 viết giản) | 京 | kinh | biểu âm | cho âm qióng | 琼 = 王/玉 (Vương/Ngọc, biểu nghĩa: đá quý) + 京 (Kinh, biểu âm); chữ hình thanh. Wiktionary ghi đây là dạng rút gọn (corrupt) từ 琁. Bộ 玉 xác định liên quan đến ngọc quý.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quỳnh\": ngọc 王quỳnh — đẹp như hoa quỳnh nở đêm, quý hiếm như ngọc quỳnh đỏ hồng. | Gương Hán-Việt | quỳnh hoa (瓊花 — hoa quỳnh), Hải Nam (琼州 — đảo Hải Nam) | Mở khoá kiến thức | Biết 琼 mở khoá: 琼脂 (quỳnh chi — thạch agar), 琼州 (Quỳnh Châu — Hải Nam), và tên riêng thanh tao.", "Tự nguyên_Xie": "Theo Wiktionary, 琼 bị biến dạng từ 琁 (theo 简化字源 1999). Đây là giản thể của 瓊. Nghĩa: ngọc quỳnh — loại ngọc đẹp màu đỏ hồng; cũng dùng trong địa danh 琼州 (đảo Hải Nam). Hán-Việt: ''quỳnh''. Chưa có nguồn học thuật xác nhận cấu trúc đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ngọc quỳnh; hoa quỳnh", "Hạng Tần Suất (Jun Da)": "2200.0", "Tần Suất % (Jun Da)": "97.7860201332", "GavinGrover_Once (Chiết tự trực tiếp)": "王 + 京", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰王京", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "京", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "王", "Unihan_Simplified (Chữ Giản thể)": "琼", "Unihan_Traditional (Chữ Phồn thể)": "瓊", "Pinyin_Xie": "qióng", "Âm Hán Việt_Xie": "quỳnh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Chữ này làm danh từ chỉ loại ngọc quý hoặc làm tính từ miêu tả vẻ đẹp thanh khiết, sang trọng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('脂', '{"9000": "2201.0", "Chữ Trung Quốc": "脂", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 10 | nét | 月 | nguyệt | biểu nghĩa | thịt (bộ nhục biến thể giống 月) | 旨 | chỉ | biểu âm | ý chỉ (cho âm zhī) | 脂 = 月 (Nhục, biểu nghĩa: thịt — bộ nhục biến thành 月) + 旨 (Chỉ, biểu âm); chữ hình thanh. Bộ nhục chỉ đây liên quan đến chất béo động vật; 旨 cung cấp âm (zhī).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chi\": thịt (月/nhục) béo ngậy chứa đầy chất chi béo (旨/chỉ) — chi phương tức là son phấn, mỡ bôi. | Gương Hán-Việt | chi trong 脂肪 (chi phòng — chất béo), 口脂 (khẩu chi — son môi) | Mở khoá kiến thức | Biết 脂 (chi) mở khoá: 脂肪 (chất béo), 胭脂 (son phấn), 脂粉 (phấn son).", "Tự nguyên_Xie": "Theo Wiktionary, 脂 là chữ hình thanh: bộ 肉 (月) biểu nghĩa (thịt — chất béo động vật), 旨 biểu âm. Nghĩa gốc là mỡ, chất béo; mở rộng sang son phấn, dầu mỡ thực vật. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mỡ tảng; sáp, nhựa", "Hạng Tần Suất (Jun Da)": "2201.0", "Tần Suất % (Jun Da)": "97.7888583171", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 旨", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月旨", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "旨", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "脂", "Unihan_Traditional (Chữ Phồn thể)": "脂", "Pinyin_Xie": "zhī", "Âm Hán Việt_Xie": "chi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ chất béo, mỡ hoặc các chất dạng keo sáp, thường dùng trong từ ghép. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('谎', '{"9000": "2202.0", "Chữ Trung Quốc": "谎", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 11 | nét | 讠 | biểu nghĩa | lời nói (bộ ngôn giản thể) | 荒 | hoang | biểu âm | hoang vu (cho âm huǎng) | 谎 = 讠(Ngôn, biểu nghĩa: lời nói) + 荒 (Hoang, biểu âm); chữ hình thanh. Đây là giản thể của 謊. Bộ ngôn chỉ đây là lời nói; 荒 cung cấp âm (huǎng) và gợi ý nghĩa: lời nói hoang đường, sai sự thật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hoang\": lời (讠) hoang đường (荒/hoang) — hoang ngôn, lời nói dối trắng trợn. | Gương Hán-Việt | hoang trong 谎言 (hoang ngôn — lời nói dối) | Mở khoá kiến thức | Biết 谎 (hoang) mở khoá: 说谎 (nói dối), 撒谎 (nói dối), 谎言 (lời nói dối), 谎话 (lời dối trá).", "Tự nguyên_Xie": "谎 là giản thể của 謊, thay 言 bằng 讠. Theo Wiktionary, đây là chữ hình thanh: bộ 言 biểu nghĩa (lời nói — lời không thật), 荒 biểu âm. Nghĩa gốc và duy nhất là nói dối, lời nói không có thật. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nói dối", "Hạng Tần Suất (Jun Da)": "2202.0", "Tần Suất % (Jun Da)": "97.7916908165", "GavinGrover_Once (Chiết tự trực tiếp)": "讠 + 荒", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰讠荒", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "荒", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "讠", "Unihan_Simplified (Chữ Giản thể)": "谎", "Unihan_Traditional (Chữ Phồn thể)": "謊", "Pinyin_Xie": "huǎng", "Âm Hán Việt_Xie": "hoang", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này thường làm danh từ chỉ lời nói dối đi sau động từ thuyết, hoặc tự bản thân làm động từ nói dối. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('慨', '{"9000": "2203.0", "Chữ Trung Quốc": "慨", "Bộ thủ & thành phần_Xie": "Bộ thủ | 心 | Số nét | 12 | nét | 忄 | tâm | biểu nghĩa | tim, cảm xúc (bộ tâm giản thể) | 既 | ký | biểu âm | đã, xong rồi (cho âm kǎi) | 慨 = 忄(Tâm, biểu nghĩa: lòng, cảm xúc) + 既 (Ký, biểu âm); chữ hình thanh. Bộ tâm chỉ đây là cảm xúc nội tâm; 既 cung cấp âm (kǎi). Cảm xúc dâng trào khi nhớ chuyện đã qua.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khái\": lòng (忄) dâng lên vì những điều đã qua (既/ký) — khái thán, cảm khái sâu sắc. | Gương Hán-Việt | khái trong 感慨 (cảm khái — cảm thán, ngậm ngùi), 慷慨 (khang khái — hào phóng) | Mở khoá kiến thức | Biết 慨 (khái) mở khoá: 感慨 (cảm thán), 慷慨 (hào phóng), 愤慨 (phẫn nộ), 慨叹 (than thở).", "Tự nguyên_Xie": "Theo Wiktionary, 慨 là chữ hình thanh: bộ 心 (忄) biểu nghĩa (lòng — cảm xúc), 既 biểu âm. Nghĩa gốc là cảm thán, bức xúc; sau mở rộng sang hào phóng, nhiệt tình, rộng lượng. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tức giận, căm phẫn; than thở; hào hiệp, khảng khái", "Hạng Tần Suất (Jun Da)": "2203.0", "Tần Suất % (Jun Da)": "97.7945222822", "GavinGrover_Once (Chiết tự trực tiếp)": "忄 + 既", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰忄既", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "既", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "忄", "Unihan_Simplified (Chữ Giản thể)": "慨", "Unihan_Traditional (Chữ Phồn thể)": "慨", "Pinyin_Xie": "kǎi", "Âm Hán Việt_Xie": "khái", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Chữ này làm tính từ miêu tả tính cách hào hiệp, thẳng thắn hoặc làm động từ biểu thị sự cảm thán, bùi ngùi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('菩', '{"9000": "2204.0", "Chữ Trung Quốc": "菩", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 11 | nét | 艹 | thảo | biểu nghĩa | cỏ/thực vật | 咅 | phủ | biểu âm | cho âm pú | 菩 = 艹(Thảo, biểu nghĩa: thực vật) + 咅 (Phủ, biểu âm); chữ hình thanh. Bộ 艹gốc chỉ cây cỏ, phần 咅 cho âm. Ngày nay 菩 chủ yếu dùng trong phiên âm Phật giáo (菩薩 — Bồ Tát).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bồ\": 菩 bồ tát từ bi — cây cỏ 艹nhỏ bé nhưng mang trí tuệ 咅 giác ngộ như cây Bồ Đề. | Gương Hán-Việt | bồ tát (菩薩 — Bodhisattva), bồ đề (菩提 — Bodhi) | Mở khoá kiến thức | Biết 菩 mở khoá: 菩萨 (bồ tát — Bodhisattva), 菩提 (bồ đề — cây giác ngộ), 菩提树 (cây bồ đề).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 菩 là hình thanh: 艸/艹(cỏ, biểu nghĩa) + 咅 (biểu âm). Chủ yếu dùng trong phiên âm tiếng Phạn: 菩薩 (Bodhisattva — Bồ Tát), 菩提 (Bodhi — Bồ Đề). Hán-Việt: ''bồ''. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "người tốt bụng", "Hạng Tần Suất (Jun Da)": "2204.0", "Tần Suất % (Jun Da)": "97.7973527144", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 咅", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹咅", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "咅", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "菩", "Unihan_Traditional (Chữ Phồn thể)": "菩", "Pinyin_Xie": "pú", "Âm Hán Việt_Xie": "bồ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này chủ yếu dùng làm danh từ trong các từ ghép Phật giáo như Bồ Tát hoặc Bồ Đề. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('萄', '{"9000": "2205.0", "Chữ Trung Quốc": "萄", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 11 | nét | 艹 | thảo | biểu nghĩa | cây cỏ — nho | 匋 | đào | biểu âm | gợi âm táo | 萄 = 艹 (Thảo: cây cỏ) + 匋 (Đào, biểu âm); chữ hình thanh. Chuyên dùng trong từ 葡萄 (nho).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đào\": cây 艹 và vò gốm 匋 — vò gốm cất rượu nho, đó là ''đào'' (trong 葡萄, nho). | Gương Hán-Việt | đào trong \"bồ đào\" 葡萄 — nho | Mở khoá kiến thức | Biết 萄 mở khoá từ chuyên dụng cho nho: 葡萄, 葡萄酒.", "Tự nguyên_Xie": "Đại triện | Tiểu triện | Wiktionary chú 萄 = 艹 (草) + 匋 (ls=psc, c1=s c2=p) — 艹 cho nghĩa ''thực vật'', 匋 cho âm táo (匋 là người chế đồ gốm). Cây nho được du nhập vào Trung Quốc qua Trương Khiên thời Hán. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: bồ đào 葡萄)", "Hạng Tần Suất (Jun Da)": "2205.0", "Tần Suất % (Jun Da)": "97.8001759116", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 匋", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹匋", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "匋", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "萄", "Unihan_Traditional (Chữ Phồn thể)": "萄", "Pinyin_Xie": "táo", "Âm Hán Việt_Xie": "đào", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này hầu như chỉ xuất hiện trong danh từ ghép Bồ đào để chỉ quả nho hoặc rượu nho. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('狮', '{"9000": "2206.0", "Chữ Trung Quốc": "狮", "Bộ thủ & thành phần_Xie": "Bộ thủ | 犬 | Số nét | 9 | nét | 犭 | khuyển | biểu nghĩa | bộ thú (thú vật) | 师 | sư | biểu âm | thầy, đội quân | 狮 = 犭 (Khuyển, biểu nghĩa: thú vật) + 师 (Sư, biểu âm); chữ hình thanh. Bộ 犭 cho nghĩa là động vật, 师 (sư) cho âm (shī ~ sư).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sư\": bộ thú 犭 (khuyển) kết hợp thầy/sư 师 (sư) — sư tử 狮 là ''thầy của muôn thú'', chúa sơn lâm. | Gương Hán-Việt | sư trong ''sư tử'' (con sư tử) | Mở khoá kiến thức | Biết 狮 (sư) mở khoá: 狮子 (sư tử), 狮子座 (cung Sư Tử), 石狮 (sư tử đá).", "Tự nguyên_Xie": "Theo Wiktionary, 狮 (phồn thể 獅) là chữ hình thanh (psc): 犬 (khuyển, biểu nghĩa: thú vật) + 師 (sư, biểu âm). Con sư tử không có nguồn gốc ở Trung Quốc — chữ được tạo khi sư tử được đưa về từ Tây Vực, ghép bộ khuyển với 師 cho âm. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con sư tử", "Hạng Tần Suất (Jun Da)": "2206.0", "Tần Suất % (Jun Da)": "97.8029954913", "GavinGrover_Once (Chiết tự trực tiếp)": "犭 + 师", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰犭师", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "师", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "犭", "Unihan_Simplified (Chữ Giản thể)": "狮", "Unihan_Traditional (Chữ Phồn thể)": "獅", "Pinyin_Xie": "shī", "Âm Hán Việt_Xie": "sư", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng độc lập hoặc kết hợp với các từ khác tạo thành cụm danh từ như sư tử. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('掘', '{"9000": "2207.0", "Chữ Trung Quốc": "掘", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 11 | nét | 扌 | thủ | biểu nghĩa | tay, hành động bằng tay | 屈 | khuất | biểu âm | khuất phục, cúi xuống (cho âm jué) | 掘 = 扌(Thủ, biểu nghĩa: tay) + 屈 (Khuất, biểu âm); chữ hình thanh. Bộ thủ chỉ hành động đào bằng tay; 屈 cung cấp âm (jué). Cúi thấp và đào bới — hình ảnh rất trực quan.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quật\": tay (扌) cúi xuống quật (屈/khuất) đất — quật lên, đào bới khai quật. | Gương Hán-Việt | quật trong 挖掘 (oa quật — khai quật), 发掘 (phát quật — phát hiện qua khai quật) | Mở khoá kiến thức | Biết 掘 (quật) mở khoá: 挖掘 (khai quật), 发掘 (phát hiện), 掘进 (tiến về phía trước bằng cách đào).", "Tự nguyên_Xie": "Theo Wiktionary, 掘 là chữ hình thanh: bộ 手 (扌) biểu nghĩa (tay — hành động đào), 屈 biểu âm. Nghĩa gốc là đào, bới; mở rộng sang khai quật, phát hiện. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đào lên", "Hạng Tần Suất (Jun Da)": "2207.0", "Tần Suất % (Jun Da)": "97.8058047353", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 屈", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌屈", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "屈", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "掘", "Unihan_Traditional (Chữ Phồn thể)": "掘", "Pinyin_Xie": "jué", "Âm Hán Việt_Xie": "quật", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước tân ngữ chỉ đất đai, mộ phần hoặc kho báu để biểu thị hành động đào bới. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('抄', '{"9000": "2208.0", "Chữ Trung Quốc": "抄", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 7 | nét | 扌 | thủ | biểu nghĩa | tay | 少 | thiểu | biểu âm | ít, nhỏ | 抄 = 扌 (Thủ, biểu nghĩa: tay) + 少 (Thiểu, biểu âm); chữ hình thanh. Bộ 扌 cho nghĩa hành động bằng tay, 少 cho âm (chāo ~ thiểu).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sao\": bàn tay 扌 (thủ) ít 少 (thiểu) chữ — dùng tay 抄 chép lại từng chữ. | Gương Hán-Việt | sao trong ''抄写 sao tả'' (sao chép), ''抄袭 sao tập'' (đạo văn) | Mở khoá kiến thức | Biết 抄 (sao) mở khoá: 抄写 (sao chép), 抄袭 (đạo văn), 抄近路 (đi tắt).", "Tự nguyên_Xie": "Theo Wiktionary, 抄 là chữ hình thanh (psc): 手 (thủ, biểu nghĩa: tay) + 少 (thiểu, biểu âm). Nghĩa gốc là dùng tay viết lại, sao chép. Sau mở rộng sang nghĩa ''khám xét tịch thu'', ''đi tắt''. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sao, chép lại; sao (đơn vị đo, bằng 1/1000 của thăng)", "Hạng Tần Suất (Jun Da)": "2208.0", "Tần Suất % (Jun Da)": "97.8086124289", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 少", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌少", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "少", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "抄", "Unihan_Traditional (Chữ Phồn thể)": "抄", "Pinyin_Xie": "chāo", "Âm Hán Việt_Xie": "sao", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Lượng từ | 量词 | Thường làm động từ đứng trước danh từ để chỉ hành động chép lại văn bản hoặc đi đường tắt. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Lượng từ | 量词 | Đứng giữa số từ (hoặc 这/那) và danh từ: 一杯茶, 这本书. Mỗi danh từ đi với lượng từ riêng; 个 là lượng từ dùng chung phổ biến nhất.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | Từ đơn | Từ vựng HSK 5: chép, phiên âm | / | chāo | / | chép, phiên âm | Xuất hiện trong lộ trình | HSK | HSK 5 | · | Phương tiện thông tin đại chúng | New HSK | New HSK 4 | · | Thông tin", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('岭', '{"9000": "2209.0", "Chữ Trung Quốc": "岭", "Bộ thủ & thành phần_Xie": "Bộ thủ | 山 | Số nét | 8 | nét | 山 | sơn | biểu nghĩa | núi | 令 | lệnh | biểu âm | cho âm lǐng | 岭 = 山 (Sơn, biểu nghĩa: núi) + 令 (Lệnh, biểu âm); chữ hình thanh. Bộ 山 xác định đây là địa hình núi, phần 令 cho âm đọc lǐng. Wiktionary không có phân tích chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"linh\": đỉnh núi 岭 linh thiêng — sơn 山 tiếp nhận lệnh 令 trời, đứng hiên ngang như linh sơn. | Gương Hán-Việt | Nam Linh (南岭 — dãy núi Nam Lĩnh), sơn linh (山岭 — đồi núi) | Mở khoá kiến thức | Biết 岭 mở khoá địa danh: 南岭 (Nam Linh — dãy núi biên giới TQ-VN), 五岭 (Ngũ Linh — năm dãy núi), 岭南 (Linh Nam — vùng Quảng Đông-Quảng Tây).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Wiktionary không có mục phân tích đầy đủ cho 岭. Suy từ bộ thủ: 山 (núi, biểu nghĩa) + 令 (biểu âm). Nghĩa: đỉnh núi, dãy núi — đặc biệt dùng trong địa danh vùng Nam Trung Quốc như 南岭, 五岭. Hán-Việt: ''linh''. Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đỉnh núi", "Hạng Tần Suất (Jun Da)": "2209.0", "Tần Suất % (Jun Da)": "97.8114180554", "GavinGrover_Once (Chiết tự trực tiếp)": "山 + 令", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰山令", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "令", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "山", "Unihan_Simplified (Chữ Giản thể)": "岭", "Unihan_Traditional (Chữ Phồn thể)": "岭", "Pinyin_Xie": "lǐng", "Âm Hán Việt_Xie": "lĩnh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ địa hình núi non, đứng sau tên riêng để chỉ một dãy núi cụ thể. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('晕', '{"9000": "2210.0", "Chữ Trung Quốc": "晕", "Bộ thủ & thành phần_Xie": "Bộ thủ | 日 | Số nét | 10 | nét | 日 | nhật | biểu nghĩa | mặt trời, ngày | 军 | quân | biểu âm | quân đội | 晕 = 日 (Nhật, biểu nghĩa: mặt trời) + 军 (Quân, biểu âm); chữ hình thanh. Bộ 日 cho nghĩa liên quan đến ánh sáng, 军 cho âm (yūn ~ vựng).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"vựng\": mặt trời 日 (nhật) quay vòng với quân 军 (quân) — nhìn lâu vào 晕 mặt trời dễ váng đầu chóng mặt. | Gương Hán-Việt | vựng trong ''vựng quang'' (quầng sáng quanh mặt trời/trăng) | Mở khoá kiến thức | Biết 晕 (vựng) mở khoá: 头晕 (chóng mặt), 晕车 (say xe), 晕倒 (ngất xỉu).", "Tự nguyên_Xie": "Tiểu triện | 晕 là chữ giản thể của 暈. Theo nguồn, 暈 là chữ hình thanh: 日 (nhật, biểu nghĩa: mặt trời) + 軍 (quân, biểu âm). Nghĩa gốc là quầng sáng quanh mặt trời hay mặt trăng. Sau mở rộng sang nghĩa ''chóng mặt, váng đầu''. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "vầng sáng của mặt trời, mặt trăng", "Hạng Tần Suất (Jun Da)": "2210.0", "Tần Suất % (Jun Da)": "97.8142190308", "GavinGrover_Once (Chiết tự trực tiếp)": "日 + 军", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱日军", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "军", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "日", "Unihan_Simplified (Chữ Giản thể)": "晕", "Unihan_Traditional (Chữ Phồn thể)": "暈", "Pinyin_Xie": "yūn", "Âm Hán Việt_Xie": "vựng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Tính từ | 形容词 | Thường làm động từ hoặc tính từ đứng sau chủ ngữ để chỉ trạng thái chóng mặt, hoa mắt hoặc ngất xỉu. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | Từ đơn | Từ vựng HSK 5: cảm thấy chóng mặt | / | yūn | / | cảm thấy chóng mặt | Xuất hiện trong lộ trình | New HSK | New HSK 6 | · | Sức khỏe và y học | HSK | HSK 5 | · | Sức khỏe", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('逮', '{"9000": "2211.0", "Chữ Trung Quốc": "逮", "Bộ thủ & thành phần_Xie": "Bộ thủ | 辵 | Số nét | 11 | nét | 辶 | sước | biểu nghĩa | đi, bước (bộ xước) | 隶 | lệ | biểu âm | nô lệ (cho âm dǎi/dài) | 逮 = 辶(Sước, biểu nghĩa: đi, đuổi theo) + 隶 (Lệ, biểu âm); chữ hình thanh. Bộ xước chỉ sự di chuyển, đuổi theo; 隶 cung cấp âm (dǎi/dài). Đuổi theo và bắt giữ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đãi\": đuổi theo đường (辶) như nô lệ (隶/lệ) chạy trốn bị bắt — đãi bắt, bắt giữ kẻ phạm tội. | Gương Hán-Việt | đãi trong 逮捕 (đãi bộ — bắt giữ) | Mở khoá kiến thức | Biết 逮 (đãi) mở khoá: 逮捕 (bắt giữ), 就逮 (bị bắt), 力有未逮 (sức không đủ đạt tới).", "Tự nguyên_Xie": "Theo Wiktionary, 逮 là chữ hình thanh: bộ 辵 (辶) biểu nghĩa (đi đường — đuổi theo), 隶 biểu âm. Nghĩa gốc là bắt kịp, đuổi được; mở rộng sang bắt giữ (tội phạm), đạt đến. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "theo kịp; đuổi", "Hạng Tần Suất (Jun Da)": "2211.0", "Tần Suất % (Jun Da)": "97.8170189727", "GavinGrover_Once (Chiết tự trực tiếp)": "辶 + 隶", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴辶隶", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "隶", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "辶", "Unihan_Simplified (Chữ Giản thể)": "逮", "Unihan_Traditional (Chữ Phồn thể)": "逮", "Pinyin_Xie": "dǎi", "Âm Hán Việt_Xie": "đãi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước tân ngữ chỉ người hoặc động vật bị truy bắt. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | dài | / | bắt giữ | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Tòa án và Pháp luật I", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('砍', '{"9000": "2212.0", "Chữ Trung Quốc": "砍", "Bộ thủ & thành phần_Xie": "Bộ thủ | 石 | Số nét | 9 | nét | 石 | thạch | biểu nghĩa | đá (vật cứng) | 欠 | khiếm | biểu âm | há miệng (gần âm kǎn) | 砍 = 石 (Thạch, biểu nghĩa: đá — vốn dùng đá làm búa rìu) + 欠 (Khiếm, biểu âm); chữ hình thanh. Dùng vật cứng chặt vào, gốc nghĩa ''chặt, bổ''.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khảm\": 石 (đá) + 欠 (há miệng/hành động) — dùng rìu đá chặt xuống, đúng nghĩa ''chặt, bổ'' trong 砍, 砍价 (mặc cả), 砍伐 (chặt cây). | Gương Hán-Việt | ''khảm'' trong ''khảm trai'', ''khảm xà cừ'' — gần với ''chặt khảm'' trong khẩu ngữ | Mở khoá kiến thức | Nắm 砍 mở khoá từ HSK 5-7: 砍, 砍价, 砍伐.", "Tự nguyên_Xie": "Theo Wiktionary, 砍 là hình thanh: 石 (đá, biểu nghĩa — vốn dùng đá làm rìu cổ) + 欠 (Khiếm, biểu âm). Nghĩa gốc ''chặt, bổ, đốn'' (砍伐 — đốn cây). Mở rộng sang nghĩa khẩu ngữ ''cắt giảm giá'' (砍价 — mặc cả) và ''sa thải, bỏ'' (砍掉). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1822.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thạch (112) Khiếm (076)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Thạch (số 112 - hòn đá/ 石 /chỉ ý) ở bên trái bộ Khiếm (số 076 - thiếu, ngáp/ 欠 /chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Bộ Khiếm chỉ âm, bộ Thạch chỉ ý. Khảm là dùng rìu hoặc dao cụ để chặt, bổ, đốn (khảm mộc - đốn cây, khảm tặc).", "Nghĩa Tiếng Việt_Xie": "chặt, bổ", "Hạng Tần Suất (Jun Da)": "2212.0", "Tần Suất % (Jun Da)": "97.8198189146", "GavinGrover_Once (Chiết tự trực tiếp)": "石 + 欠", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰石欠", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "欠", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "石", "Unihan_Simplified (Chữ Giản thể)": "砍", "Unihan_Traditional (Chữ Phồn thể)": "砍", "Pinyin_Xie": "kǎn", "Âm Hán Việt_Xie": "khảm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước danh từ chỉ cây cối hoặc vật thể cần chặt đứt. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | Từ đơn | Từ vựng HSK 5: chặt | / | kǎn | / | chặt | Xuất hiện trong lộ trình | HSK | HSK 5 | · | Ngôi nhà và cuộc sống hàng ngày | New HSK | New HSK 7-9 | · | Nông nghiệp", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('掏', '{"9000": "2213.0", "Chữ Trung Quốc": "掏", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 11 | nét | 扌 | thủ | biểu nghĩa | tay, hành động bằng tay | 匋 | đào | biểu âm | đồ gốm (cho âm tāo) | 掏 = 扌(Thủ, biểu nghĩa: tay) + 匋 (Đào, biểu âm); chữ hình thanh. Bộ thủ chỉ hành động thò tay lấy ra; 匋 cung cấp âm (tāo). Hình ảnh thò tay vào túi lấy đồ rất trực quan.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đào\": thò tay (扌) đào (匋/đào) vào túi — đào lấy, thò tay móc tiền ra. | Gương Hán-Việt | đào trong 掏钱 (đào tiền — thò tay lấy tiền), 掏腰包 (đào yêu bao — móc ví) | Mở khoá kiến thức | Biết 掏 (đào) mở khoá: 掏钱 (trả tiền), 掏腰包 (móc ví), 掏心 (mở lòng thật sự), 掏空 (rút sạch).", "Tự nguyên_Xie": "Theo Wiktionary, 掏 là chữ hình thanh: bộ 手 (扌) biểu nghĩa (tay — thò vào lấy ra), 匋 biểu âm. Nghĩa gốc là thò tay vào lấy ra; mở rộng sang đào bới, rút ví trả tiền. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lấy, móc, đào, cuốc", "Hạng Tần Suất (Jun Da)": "2213.0", "Tần Suất % (Jun Da)": "97.8226178229", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 匋", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌匋", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "匋", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "掏", "Unihan_Traditional (Chữ Phồn thể)": "掏", "Pinyin_Xie": "tāo", "Âm Hán Việt_Xie": "đào", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước tân ngữ chỉ túi áo, ví tiền để biểu thị hành động thò tay vào lấy đồ vật ra. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | tāo | / | lấy ra | Xuất hiện trong lộ trình | HSK | HSK 6 | · | Động từ | New HSK | New HSK 6 | · | Động từ", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('狄', '{"9000": "2214.0", "Chữ Trung Quốc": "狄", "Bộ thủ & thành phần_Xie": "Bộ thủ | 犬 | Số nét | 7 | nét | 犭 | khuyển | biểu nghĩa | chó/dã thú | 火 | hoả | biểu âm | cho âm dí | 狄 = 犭(Khuyển, biểu nghĩa: dã thú, gợi tính man rợ) + 火 (Hoả, biểu âm hoặc nghĩa: lửa — tộc người dùng lửa); chữ hình thanh. Bộ 犭gợi hình ảnh tộc người bộ lạc, phần 火 cho âm. Wiktionary không có phân tích chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"địch\": tộc địch 狄 phương bắc — chó 犭dữ lửa 火 hừng hực, chỉ tộc người Bắc Địch trong sử cổ TQ. | Gương Hán-Việt | Bắc Địch (北狄 — tộc người phương bắc), họ Địch | Mở khoá kiến thức | Biết 狄 mở khoá: hiểu bối cảnh lịch sử tứ di (四夷 — Đông Di, Tây Nhung, Nam Man, Bắc Địch); nhận ra họ Địch trong văn học cổ điển.", "Tự nguyên_Xie": "Kim văn | Tiểu triện | Wiktionary không có mục phân tích đầy đủ cho 狄. Suy từ bộ thủ: 犭(dã thú/chó, biểu nghĩa — hàm ý tộc người hoang dã theo quan điểm trung tâm Hoa Hạ) + 火 (biểu âm). Nghĩa: tộc Địch (Di Địch) — tên người Trung Quốc cổ đại gọi các bộ tộc phía bắc; họ Địch. Hán-Việt: ''địch''. Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "rợ Địch (ở phương Bắc Trung Quốc)", "Hạng Tần Suất (Jun Da)": "2214.0", "Tần Suất % (Jun Da)": "97.8254156976", "GavinGrover_Once (Chiết tự trực tiếp)": "犭 + 火", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰犭火", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "火", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "犭", "Unihan_Simplified (Chữ Giản thể)": "狄", "Unihan_Traditional (Chữ Phồn thể)": "狄", "Pinyin_Xie": "dí", "Âm Hán Việt_Xie": "địch", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ các bộ tộc cổ đại ở phía bắc Trung Quốc hoặc dùng làm họ của người. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('晰', '{"9000": "2215.0", "Chữ Trung Quốc": "晰", "Bộ thủ & thành phần_Xie": "Bộ thủ | 日 | Số nét | 12 | nét | 日 | nhật | biểu nghĩa | mặt trời, ánh sáng, ngày | 析 | tích | biểu âm | phân tích, chẻ ra (cho âm xī) | 晰 = 日 (Nhật, biểu nghĩa: ánh sáng) + 析 (Tích, biểu âm); chữ hình thanh. Bộ nhật gợi ý sự rõ ràng, sáng sủa; 析 cung cấp âm (xī). Ánh sáng rọi vào khiến mọi thứ rõ ràng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tích\": ánh sáng (日) rọi tích tắc phân tích (析/tích) từng chi tiết — tích rõ, rõ ràng minh bạch. | Gương Hán-Việt | tích trong 清晰 (thanh tích — rõ ràng, sắc nét) | Mở khoá kiến thức | Biết 晰 (tích) mở khoá: 清晰 (rõ ràng), 明晰 (minh bạch), 清晰可见 (nhìn thấy rõ ràng).", "Tự nguyên_Xie": "Theo Wiktionary, 晰 là chữ hình thanh: bộ 日 biểu nghĩa (ánh sáng — rõ ràng, sáng tỏ), không có lsCodes cụ thể. Nghĩa gốc và duy nhất là rõ ràng, minh bạch. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sáng, rõ ràng", "Hạng Tần Suất (Jun Da)": "2215.0", "Tần Suất % (Jun Da)": "97.8282125387", "GavinGrover_Once (Chiết tự trực tiếp)": "日 + 析", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰日析", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "析", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "日", "Unihan_Simplified (Chữ Giản thể)": "晰", "Unihan_Traditional (Chữ Phồn thể)": "晰", "Pinyin_Xie": "xī", "Âm Hán Việt_Xie": "tích", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường làm tính từ kết hợp với các từ khác để tạo thành từ ghép chỉ sự rõ ràng của âm thanh hoặc hình ảnh. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('罕', '{"9000": "2216.0", "Chữ Trung Quốc": "罕", "Bộ thủ & thành phần_Xie": "Bộ thủ | 网 | Số nét | 7 | nét | 㓁 | biểu nghĩa | lưới (biến thể của 网 — mạng lưới) | 干 | can | biểu âm | can thiệp, cái mộc (cho âm hǎn) | 罕 = 网/㓁 (Mạng, biểu nghĩa: lưới) + 干 (Can, biểu âm); chữ hình thanh. Bộ lưới gợi ý dụng cụ bắt chim bằng lưới dài cán; 干 cung cấp âm (hǎn). Nghĩa gốc là lưới bắt chim, sau mở rộng sang hiếm có.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hãn\": lưới (㓁) bắt chim với cán (干/can) dài — hãn hữu, hiếm khi bắt được loài chim quý. | Gương Hán-Việt | hãn trong 罕见 (hãn kiến — hiếm gặp) | Mở khoá kiến thức | Biết 罕 (hãn) mở khoá: 罕见 (hiếm gặp), 稀罕 (hiếm có), 人迹罕至 (ít người đặt chân đến).", "Tự nguyên_Xie": "Theo Wiktionary, 罕 là chữ hình thanh: bộ 网 biểu nghĩa (lưới — lưới có cán dài dùng bắt chim), 干 biểu âm. Nghĩa gốc là lưới bắt chim, cũng là cờ hiệu. Mở rộng sang hiếm, ít khi gặp (chim khó bắt). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ít ỏi, hiếm; lưới bắt chim", "Hạng Tần Suất (Jun Da)": "2216.0", "Tần Suất % (Jun Da)": "97.8310078295", "GavinGrover_Once (Chiết tự trực tiếp)": "⺳ + 干", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺳干", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "干", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺳", "Unihan_Simplified (Chữ Giản thể)": "罕", "Unihan_Traditional (Chữ Phồn thể)": "罕", "Pinyin_Xie": "hǎn", "Âm Hán Việt_Xie": "hãn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Phó từ | 副词 | Chữ này thường làm tính từ hoặc phó từ đứng trước động từ để chỉ sự hiếm hoi, ít gặp. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Phó từ | 副词 | Bổ nghĩa cho động từ hoặc tính từ và luôn đứng TRƯỚC chúng — 都是, 很好. Không đứng sau như tiếng Việt và không bổ nghĩa cho danh từ.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('挽', '{"9000": "2217.0", "Chữ Trung Quốc": "挽", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 10 | nét | 扌 | thủ | biểu nghĩa | tay, hành động bằng tay | 免 | miễn | biểu âm | thoát khỏi, miễn (cho âm wǎn) | 挽 = 扌(Thủ, biểu nghĩa: tay) + 免 (Miễn, biểu âm); chữ hình thanh. Bộ thủ chỉ hành động kéo, níu giữ bằng tay; 免 cung cấp âm (wǎn). Tay níu kéo lại để tránh mất đi.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"vãn\": tay (扌) níu kéo miễn (免/miễn) cho khỏi mất — vãn hồi, cứu vãn tình thế. | Gương Hán-Việt | vãn trong 挽回 (vãn hồi — lấy lại, cứu vãn), 挽救 (vãn cứu — cứu vãn) | Mở khoá kiến thức | Biết 挽 (vãn) mở khoá: 挽回 (lấy lại), 挽救 (cứu vãn), 力挽狂澜 (gắng sức cứu vãn).", "Tự nguyên_Xie": "Theo Wiktionary, 挽 là chữ hình thanh: bộ 手 (扌) biểu nghĩa (tay — kéo, níu giữ), 免 biểu âm. Nghĩa gốc là kéo lại, níu giữ; mở rộng sang cứu vãn, lấy lại (những gì đã mất). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1208.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thủ (064) Miễn (225)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Thủ (số 064 - cái tay/ 扌/chỉ ý) ở bên trái chữ Miễn (số 225 - trốn tránh/chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Miễn chỉ âm, bộ Thủ chỉ ý. Vãn là dùng tay lôi kéo lại, thu hồi về phía mình (cứu vãn, vãn hồi).", "Nghĩa Tiếng Việt_Xie": "kéo", "Hạng Tần Suất (Jun Da)": "2217.0", "Tần Suất % (Jun Da)": "97.8337927846", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 免", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌免", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "免", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "挽", "Unihan_Traditional (Chữ Phồn thể)": "挽", "Pinyin_Xie": "wǎn", "Âm Hán Việt_Xie": "vãn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ đứng trước tân ngữ để biểu thị hành động kéo, giữ lại hoặc cứu vãn. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Từ III", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('脾', '{"9000": "2218.0", "Chữ Trung Quốc": "脾", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 12 | nét | 月 | nhục | biểu nghĩa | thịt/cơ quan nội tạng (vốn là ⺼) | 卑 | ti | biểu âm | phần biểu âm — gần âm ''tỳ/ti'' | 脾 là chữ hình thanh (psc): 月 (⺼, thịt/nội tạng — biểu nghĩa) + 卑 (biểu âm). Tên một cơ quan trong cơ thể — lá lách. Trong khẩu ngữ Trung Quốc cũng dùng cho ''tính khí'' (脾气).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Tỳ\": cơ quan thịt (月) ở vị trí thấp (卑) trong nội tạng — đó là ''tỳ'', lá lách, cũng dùng cho tính khí. | Gương Hán-Việt | ''Tỳ'' trong ''tỳ vị'', ''tỳ tạng'', ''tỳ vị bất hoà'', ''kiện tỳ''. | Mở khoá kiến thức | Biết 脾 mở khoá 脾气 (tỳ khí, tính khí), 发脾气 (phát tỳ khí, nổi nóng), 脾胃 (tỳ vị).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 脾 là chữ hình thanh gồm 肉 (⺼, viết thành 月 — thịt, biểu nghĩa: cơ quan nội tạng) + 卑 (biểu âm). Nghĩa gốc ''lá lách — một cơ quan nội tạng'' phái sinh nghĩa khẩu ngữ ''tính khí, tính tình'' (do y học cổ truyền liên hệ tì với tính khí — 脾气). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lá lách", "Hạng Tần Suất (Jun Da)": "2218.0", "Tần Suất % (Jun Da)": "97.8365761893", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 卑", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月卑", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "卑", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "脾", "Unihan_Traditional (Chữ Phồn thể)": "脾", "Pinyin_Xie": "pí", "Âm Hán Việt_Xie": "tì", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ cơ quan nội tạng hoặc tính khí, thường kết hợp với các từ khác như tỳ vị, tỳ khí. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Cơ thể tôi", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('舟', '{"9000": "2219.0", "Chữ Trung Quốc": "舟", "Bộ thủ & thành phần_Xie": "Bộ thủ | 舟 | Số nét | 6 | nét | 舟 | chu | tượng hình | hình dạng con thuyền nhìn từ trên — thân thuyền và hai bên mạn | 舟 là chữ tượng hình độc lập: hình ảnh cách điệu của con thuyền nhìn từ bên cạnh hoặc trên — thân thuyền có hai đầu cong và khoang giữa. Không có thành phần biểu âm hay biểu nghĩa khác.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chu\": hình dạng con thuyền (舟) — chu du trên sóng nước, đơn giản mà cổ kính. | Gương Hán-Việt | chu trong 龙舟 (long chu — thuyền rồng), 舟车 (chu xa — thuyền và xe) | Mở khoá kiến thức | Biết 舟 (chu) mở khoá: 龙舟 (thuyền rồng), 舟车 (thuyền xe — phương tiện), 刻舟求剑 (hành động lỗi thời), 同舟共济 (cùng chung sức).", "Tự nguyên_Xie": "Theo Wiktionary, 舟 là chữ tượng hình (象形) — vẽ hình dạng con thuyền. Trong giáp cốt văn và kim văn, chữ này giống hình con thuyền có thân dài và hai đầu vút lên. Sau thường bị viết nhầm thành 月, 肉 hoặc 凡 khi là thành phần trong các chữ ghép. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "694.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Hình con thuyền nhỏ, trên thuyền có thanh gỗ ngang vắt qua. Giải thích sự chuyển ý: Đây là chữ Tượng hình. Chu có nghĩa là cái thuyền (thường là loại thuyền nhỏ).", "Nghĩa Tiếng Việt_Xie": "cái thuyền", "Hạng Tần Suất (Jun Da)": "2219.0", "Tần Suất % (Jun Da)": "97.839347708", "GavinGrover_Once (Chiết tự trực tiếp)": "No glyph available + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "Ký hiệu: built", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "舟", "Unihan_Traditional (Chữ Phồn thể)": "舟", "Pinyin_Xie": "zhōu", "Âm Hán Việt_Xie": "châu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ phương tiện giao thông đường thủy, thường dùng trong văn viết hoặc làm bộ thủ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | zhōu | / | thuyền | Xuất hiện trong lộ trình | HSK | HSK 6 | · | Vận chuyển", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('痴', '{"9000": "2220.0", "Chữ Trung Quốc": "痴", "Bộ thủ & thành phần_Xie": "Bộ thủ | 疒 | Số nét | 13 | nét | 疒 | nạch | biểu nghĩa | bệnh tật | 知 | tri | biểu âm | cho âm chī | 痴 = 疒(Nạch, biểu nghĩa: bệnh) + 知 (Tri, biểu âm); chữ hình thanh. Bộ 疒xác định đây là chứng bệnh (bệnh tâm thần), phần 知 cho âm đọc chī.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"si\": bệnh 疒si mê — người si 痴 không dùng được tri thức 知 của mình, đứng ngơ ngẩn. | Gương Hán-Việt | si tình (痴情 — tình si), bạch si (白痴 — thiểu năng) | Mở khoá kiến thức | Biết 痴 mở khoá: 痴迷 (si mê), 白痴 (bạch si — người ngớ ngẩn), 痴心 (si tâm — lòng si mê), 如痴如醉 (như si như say).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Theo Wiktionary, 痴 là hình thanh: mặc dù không có mục cấu trúc rõ ràng nhưng cấu trúc thấy rõ là 疒 (bệnh, biểu nghĩa) + 知 (biểu âm). Nghĩa: ngây ngô, ngớ ngẩn, si mê — trạng thái ''bệnh tri thức'' (không biết phân biệt). Trong Phật giáo: si (vô minh). Hán-Việt: ''si''. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ngây ngô, ngớ ngẩn, bị điên; si, mê", "Hạng Tần Suất (Jun Da)": "2220.0", "Tần Suất % (Jun Da)": "97.8421171596", "GavinGrover_Once (Chiết tự trực tiếp)": "疒 + 知", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴疒知", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "知", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "疒", "Unihan_Simplified (Chữ Giản thể)": "痴", "Unihan_Traditional (Chữ Phồn thể)": "痴", "Pinyin_Xie": "chī", "Âm Hán Việt_Xie": "si", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Chữ này làm tính từ bổ nghĩa cho danh từ hoặc làm vị ngữ để chỉ trạng thái mê muội, khờ khạo. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蔡', '{"9000": "2221.0", "Chữ Trung Quốc": "蔡", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 14 | nét | 艹 | thảo | biểu nghĩa | cỏ/thực vật | 祭 | sái | biểu âm | cho âm cài | 蔡 = 艹(Thảo, biểu nghĩa: thực vật) + 祭 (Sái, biểu âm); chữ hình thanh. Bộ 艹chỉ thực vật (loại cỏ dùng tế lễ), phần 祭 cho âm đọc cài.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thái\": cỏ 艹dùng tế 祭 — nước Thái cổ đại dùng cỏ thiêng trong lễ tế, nay là họ Thái phổ biến. | Gương Hán-Việt | họ Thái (蔡姓), nước Thái (蔡國 — thời Chu) | Mở khoá kiến thức | Biết 蔡 chủ yếu mở khoá nhận biết họ Thái/Sái trong tiếng Trung và tên nước cổ 蔡 thời Chu.", "Tự nguyên_Xie": "Kim văn | Theo Wiktionary, 蔡 là hình thanh: 艸/艹(cỏ, biểu nghĩa) + 祭 (biểu âm). Nghĩa gốc: loại cây cỏ dùng trong tế lễ. Là tên nước Thái (蔡) thời Chu. Về sau phổ biến làm họ Thái/Sái. Hán-Việt: ''thái''. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nước Thái (tên nước triều Chu, nay ở phía tây nam Thượng Thái thuộc Hà Nam Trung Quốc, sau dời về Tân Thái); họ Thái; thái (một giống rùa lớn)", "Hạng Tần Suất (Jun Da)": "2221.0", "Tần Suất % (Jun Da)": "97.8448690404", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 祭", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹祭", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "祭", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "蔡", "Unihan_Traditional (Chữ Phồn thể)": "蔡", "Pinyin_Xie": "cài", "Âm Hán Việt_Xie": "thái", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này chủ yếu làm danh từ riêng chỉ họ người hoặc tên nước thời cổ đại. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('剪', '{"9000": "2222.0", "Chữ Trung Quốc": "剪", "Bộ thủ & thành phần_Xie": "Bộ thủ | 刀 | Số nét | 11 | nét | 前 | tiền | biểu âm | trước, tiến lên | 刀 | đao | biểu nghĩa | dao, lưỡi cắt | 剪 = 前/歬 (Tiền, biểu âm) + 刀 (Đao, biểu nghĩa: dao/cắt); chữ hình thanh. Theo Wiktionary, chữ gốc là 𣦃 sau cách điệu thành 前+刀. Bộ 刀 cho nghĩa cắt, 前 cho âm (jiǎn ~ tiễn).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tiễn\": dao 刀 (đao) tiến 前 (tiền) tới — kéo 剪 là hai lưỡi dao tiến vào nhau mà cắt. | Gương Hán-Việt | tiễn trong ''剪刀 tiễn đao'' (cái kéo), ''剪彩 tiễn thải'' (cắt băng) | Mở khoá kiến thức | Biết 剪 (tiễn) mở khoá: 剪刀 (kéo), 剪彩 (cắt băng khánh thành), 剪纸 (cắt giấy nghệ thuật).", "Tự nguyên_Xie": "Theo Wiktionary, 剪 ban đầu viết là 𣦃, sau đó cách điệu thành 前 (tiền, biểu âm) + 刀 (đao, biểu nghĩa: dao). Vì 前 thay thế cho 歬 cổ, bộ 刀 thứ hai được thêm vào để nhấn mạnh nghĩa cắt. Đây là chữ hình thanh phức. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "625.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Tiền (577) Đao (052)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Tiền (số 577 - phía trước) ở trên bộ Đao (số 052 - con dao). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Tiền (phía trước) chỉ âm, bộ Đao (con dao) chỉ ý. Tiễn là cái kéo (hai lưỡi đao) dùng để cắt.", "Nghĩa Tiếng Việt_Xie": "cắt đứt; cái kéo", "Hạng Tần Suất (Jun Da)": "2222.0", "Tần Suất % (Jun Da)": "97.8476204045", "GavinGrover_Once (Chiết tự trực tiếp)": "前 + 刀", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱前刀", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "前", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "刀", "Unihan_Simplified (Chữ Giản thể)": "剪", "Unihan_Traditional (Chữ Phồn thể)": "剪", "Pinyin_Xie": "jiǎn", "Âm Hán Việt_Xie": "tiễn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chữ này làm động từ chỉ hành động cắt bằng kéo hoặc làm danh từ chỉ chính cái kéo. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | Từ ghép nghĩa | Hán-Việt ''tiễn'': 剪刀 (tiễn đao = cái kéo), 剪彩 (tiễn thải = cắt băng). | / | jiǎn | / | cắt | Xuất hiện trong lộ trình | New HSK | New HSK 5 | · | Động từ", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('脊', '{"9000": "2223.0", "Chữ Trung Quốc": "脊", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 10 | nét | 人 | nhân | biểu âm | người (âm phù 朿 qua biến dạng) | 月 | nguyệt | biểu nghĩa | thịt/thân thể (bộ 肉 viết gần giống 月) | 脊 nguyên là tượng hình xương cá. Theo Wiktionary, sau thêm bộ 肉 (thịt, biểu nghĩa) để phân biệt. Phần trên biến dạng thành 𠦬 — trở thành hình thanh với 朿 (biểu âm) + 肉/月 (biểu nghĩa). Chữ tượng hình → hình thanh sau biến dạng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tích\": xương 脊 tích lưng — sống lưng 月(肉) giữ cả thân thể đứng thẳng, như gáy sách giữ toàn bộ trang. | Gương Hán-Việt | tích lương (脊梁 — xương sống, cột trụ), tích tuỷ (脊髓 — tuỷ sống) | Mở khoá kiến thức | Biết 脊 mở khoá: 脊梁 (tích lương — xương sống/cột trụ), 脊椎 (tích chuỷ — cột sống), 屋脊 (ốc tích — đỉnh mái nhà).", "Tự nguyên_Xie": "Kim văn | Đại triện | Tiểu triện | Theo Wiktionary, 脊 gốc là tượng hình (象形) xương cá sống. Sau thêm 肉 (thịt) để làm rõ nghĩa xương sống người/động vật. Phần trên biến dạng thành 𠦬, khiến chữ trở thành hình thanh: 朿 (biểu âm) + 肉/月 (biểu nghĩa). Nghĩa: xương sống, sống lưng; sườn núi; gáy sách. Hán-Việt: ''tích''. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "xương sống; cao và bằng", "Hạng Tần Suất (Jun Da)": "2223.0", "Tần Suất % (Jun Da)": "97.8503676342", "GavinGrover_Once (Chiết tự trực tiếp)": "No glyph available + 月", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱月", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "脊", "Unihan_Traditional (Chữ Phồn thể)": "脊", "Pinyin_Xie": "jí", "Âm Hán Việt_Xie": "tích", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ bộ phận xương sống của động vật hoặc phần nhô cao của vật thể như mái nhà, sườn núi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('弓', '{"9000": "2224.0", "Chữ Trung Quốc": "弓", "Bộ thủ & thành phần_Xie": "Bộ thủ | 弓 | Số nét | 3 | nét | 弓 | cung | tượng hình | hình dáng chiếc cung — toàn bộ chữ là tượng hình | 弓 là tượng hình (象形): hình ảnh chiếc cung bắn tên. Toàn bộ chữ mô phỏng cung với dây căng và thân cung uốn cong. Không có bộ thủ riêng biệt — 弓 chính là bộ thủ độc lập.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cung\": chữ 弓 trông như chiếc cung — đầu cong hai phía với dây cung căng giữa, sẵn sàng bắn tên. | Gương Hán-Việt | cung tiễn (弓箭 — cung tên), Thiên Cung (天弓 — cầu vồng) | Mở khoá kiến thức | Biết 弓 mở khoá bộ thủ 弓 trong nhiều chữ: 弹 (bắn/đàn), 张 (căng), 强 (mạnh), 引 (kéo), 弱 (yếu).", "Tự nguyên_Xie": "Giáp cốt văn | Kim văn | Bạch thư | Đại triện | Theo Wiktionary, 弓 là tượng hình (象形): hình dạng của chiếc cung bắn tên — phần thân cong và phần dây căng. So sánh với dạng ban đầu của 射 (bắn). Không liên quan đến 弗. Hán-Việt: ''cung''. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "542.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Hình dáng một cây cung tên có dây cung uốn cong dùng để bắn đạn, bắn tên. Giải thích sự chuyển ý: Chữ Tượng hình, khắc họa trực tiếp hình ảnh cây cung.", "Nghĩa Tiếng Việt_Xie": "cong; cái cung; cung (đơn vị đo, bằng 10 xích)", "Hạng Tần Suất (Jun Da)": "2224.0", "Tần Suất % (Jun Da)": "97.8531143472", "GavinGrover_Once (Chiết tự trực tiếp)": "No glyph available + ㇉", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱㇉", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "弓", "Unihan_Traditional (Chữ Phồn thể)": "弓", "Pinyin_Xie": "gōng", "Âm Hán Việt_Xie": "cung", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này làm danh từ chỉ vũ khí bắn tên hoặc làm động từ chỉ hành động khom lưng, uốn cong. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | gōng | / | cung | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Giải trí và thói quen II", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('懒', '{"9000": "2225.0", "Chữ Trung Quốc": "懒", "Bộ thủ & thành phần_Xie": "Bộ thủ | 心 | Số nét | 16 | nét | 忄 | tâm | biểu nghĩa | trái tim — tâm trạng uể oải | 赖 | lại | biểu âm | gợi âm ''lǎn'' | 懒 (giản thể của 懶) = 忄 (Tâm, trái tim) + 赖 (Lại, biểu âm). Chữ hình thanh: trong lòng uể oải, ỷ lại — nghĩa ''lười, biếng, uể oải''.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt ''Lãn'': trong lòng (忄) ỷ lại (赖) — không muốn làm gì, đó là ''lãn'', là lười. | Gương Hán-Việt | ''Lãn'' trong lãn công (lười làm), lãn đãng (lười nhác), lười biếng. | Mở khoá kiến thức | Biết 懒 mở khóa 懒惰 (lãn đoạ / lười biếng), 偷懒 (thâu lãn / trốn việc), 懒得 (lười đến mức), 懒洋洋 (uể oải).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 懶 là chữ hình thanh: 心 biểu nghĩa, 賴 biểu âm. Nghĩa ''lười biếng, uể oải''. Bản giản thể 懒 dùng 赖. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lười, biếng; uể oải, mệt mỏi", "Hạng Tần Suất (Jun Da)": "2225.0", "Tần Suất % (Jun Da)": "97.8558569259", "GavinGrover_Once (Chiết tự trực tiếp)": "忄 + 赖", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰忄赖", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "赖", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "忄", "Unihan_Simplified (Chữ Giản thể)": "懒", "Unihan_Traditional (Chữ Phồn thể)": "嬾", "Pinyin_Xie": "lǎn", "Âm Hán Việt_Xie": "lãn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này làm tính từ đứng trước danh từ hoặc đứng sau phó từ chỉ mức độ để mô tả trạng thái lười nhác. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | lǎn | / | lười biếng | Xuất hiện trong lộ trình | New HSK | New HSK 6 | · | Tính cách | HSK | HSK 4 | · | Bản tính", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('叉', '{"9000": "2226.0", "Chữ Trung Quốc": "叉", "Bộ thủ & thành phần_Xie": "Bộ thủ | 又 | Số nét | 3 | nét | 又 | hựu | biểu nghĩa | bàn tay, lại, lần nữa | 丶 | biểu nghĩa | một chấm biểu thị vật chèn qua | 叉 = 又 (Hựu: bàn tay) + 丶 (một chấm); chữ hội ý. Hình ảnh bàn tay cầm vật có đầu xòe ra, hoặc hai thứ cắt chéo nhau như hình chữ X.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"xoa\": bàn tay 又 (hựu) cầm vật chấm 丶 xuyên — cái nĩa 叉 xoa xoa chéo chéo. | Gương Hán-Việt | xoa trong ''交叉 giao xoa'' (giao thoa, chéo nhau) | Mở khoá kiến thức | Biết 叉 (xoa) mở khoá: 叉子 (cái nĩa), 交叉 (giao nhau, chéo nhau), 叉腰 (chống hông).", "Tự nguyên_Xie": "Đại triện | Tiểu triện | Theo Wiktionary, 叉 là chữ hội ý (ic): 又 (hựu: bàn tay) + 丶 (một chấm biểu thị vật xuyên qua). Hình ảnh bàn tay giữ vật đầu chẽ ra — nĩa, dĩa, hay hình chéo nhau. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bắt chéo tay; những thứ có đầu toè ra; dạng ra, khuỳnh ra; cái dĩa, cái nĩa", "Hạng Tần Suất (Jun Da)": "2226.0", "Tần Suất % (Jun Da)": "97.8585953704", "GavinGrover_Once (Chiết tự trực tiếp)": "又 + 丶", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴又丶", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "丶", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "又", "Unihan_Simplified (Chữ Giản thể)": "叉", "Unihan_Traditional (Chữ Phồn thể)": "叉", "Pinyin_Xie": "chā", "Âm Hán Việt_Xie": "xoa", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này làm danh từ chỉ dụng cụ có đầu nhọn hoặc làm động từ chỉ hành động đâm, chắp tay chéo nhau. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | chā | / | cái nĩa | Xuất hiện trong lộ trình | New HSK | New HSK 5 | · | Thức ăn và đồ uống", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('拐', '{"9000": "2227.0", "Chữ Trung Quốc": "拐", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 8 | nét | 扌 | thủ | biểu nghĩa | tay | 另 | lánh | biểu âm | khác, riêng | 拐 = 扌 (Thủ, biểu nghĩa: tay) + 另/冎 (biểu âm: xương); chữ hình thanh. Theo Wiktionary, thành phần biểu âm gốc là 冎 (xương), sau cách điệu thành 另 trong dạng hiện đại. Bộ 扌 cho nghĩa hành động tay, liên quan đến cầm gậy hay rẽ ngoặt.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quải\": tay 扌 (thủ) rẽ sang hướng khác 另 (lánh) — 拐 là ngoặt rẽ hay chống gậy. | Gương Hán-Việt | quải trong ''拐弯 quải loan'' (rẽ ngoặt) | Mở khoá kiến thức | Biết 拐 (quải) mở khoá: 拐弯 (rẽ ngoặt), 拐杖 (gậy chống), 拐卖 (buôn bán người).", "Tự nguyên_Xie": "Theo Wiktionary, 拐 là chữ hình thanh (psc): 手 (thủ, biểu nghĩa: tay) + 冎 (biểu âm, sau viết thành 另). Nghĩa gốc liên quan đến hành động dùng tay rẽ ngoặt, sau mở rộng sang ''cái gậy'', ''người khập khiễng'', ''dụ dỗ lừa gạt''. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "kẻ dụ dỗ; cái gậy", "Hạng Tần Suất (Jun Da)": "2227.0", "Tần Suất % (Jun Da)": "97.8613250294", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 另", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌另", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "另", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "拐", "Unihan_Traditional (Chữ Phồn thể)": "拐", "Pinyin_Xie": "guǎi", "Âm Hán Việt_Xie": "quải", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chữ này làm động từ chỉ hành động rẽ hướng, lừa gạt hoặc làm danh từ chỉ chiếc gậy chống. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | guǎi | / | khập khiễng | Xuất hiện trong lộ trình | New HSK | New HSK 6 | · | Sức khỏe và y học", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('喃', '{"9000": "2228.0", "Chữ Trung Quốc": "喃", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 12 | nét | 口 | khẩu | biểu nghĩa | miệng, lời nói | 南 | nam | biểu âm | cho âm nán | 喃 = 口 (Khẩu, biểu nghĩa: miệng/lời nói) + 南 (Nam, biểu âm); chữ hình thanh. Bộ 口 xác định nghĩa liên quan đến âm thanh/lời nói, phần 南 cho âm đọc nán.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nam\": miệng 口 lầm bầm hướng nam 南 — tiếng nói riêng của người phương Nam, đó là chữ Nôm của người Việt. | Gương Hán-Việt | nôm na (喃喃 — lầm bầm), chữ Nôm (字喃 — chữ viết riêng của người Việt) | Mở khoá kiến thức | Biết 喃 mở khoá khái niệm văn hoá Việt: 字喃 (chữ Nôm), 喃喃 (nam nam — nói lầm bầm), và hiểu nguồn gốc tên ''chữ Nôm''.", "Tự nguyên_Xie": "Theo Wiktionary, 喃 là hình thanh: 口 (miệng, biểu nghĩa) + 南 (biểu âm). Nghĩa: tiếng lầm bầm, nói lầu bầu không rõ. Đặc biệt, 喃 là âm Hán-Việt ''nôm'' — chữ Nôm là hệ chữ viết riêng của người Việt (chữ 喃/nôm). Hán-Việt: ''nam'' (âm Hán-Việt) / ''nôm'' (âm thuần Việt). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tiếng nói lầm bầm", "Hạng Tần Suất (Jun Da)": "2228.0", "Tần Suất % (Jun Da)": "97.8640546885", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 南", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口南", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "南", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "喃", "Unihan_Traditional (Chữ Phồn thể)": "喃", "Pinyin_Xie": "nán", "Âm Hán Việt_Xie": "nam", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Từ tượng thanh | 象声词 | Chữ này thường lặp lại thành 喃喃 để làm động từ miêu tả tiếng nói nhỏ hoặc làm trạng ngữ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Từ tượng thanh | 象声词 | Mô phỏng âm thanh: 哗哗, 汪汪. Có thể làm định ngữ, trạng ngữ hoặc đứng độc lập.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('僚', '{"9000": "2229.0", "Chữ Trung Quốc": "僚", "Bộ thủ & thành phần_Xie": "Bộ thủ | 人 | Số nét | 14 | nét | 亻 | nhân | biểu nghĩa | người | 尞 | biểu âm | dấu hiệu âm liêu | 僚 = 亻 (Nhân, biểu nghĩa: người) + 尞 (biểu âm, cho âm liêu); chữ hình thanh. Phần 亻 chỉ đây là chữ liên quan đến con người, phần 尞 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"liêu\": 亻 (người) bên cạnh 尞 (lửa lớn) — đồng liêu là những người cùng nhau chịu đựng áp lực quan trường như đứng cạnh đám lửa. | Gương Hán-Việt | đồng liêu (bạn đồng nghiệp), quan liêu (bộ máy quan chức) | Mở khoá kiến thức | Biết 僚 mở khoá: quan liêu (官僚), đồng liêu (同僚), liêu thuộc (僚屬).", "Tự nguyên_Xie": "Giáp cốt văn | Tiểu triện | 僚 là chữ hình thanh: bộ 亻 (nhân) biểu nghĩa ''người'', phần 尞 biểu âm. Nguyên nghĩa chỉ quan lại, đồng liêu — những người cùng làm việc trong bộ máy quan trường. Wiktionary xác nhận cấu trúc 人 + 尞 (c1=s, c2=p, ls=psc). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bạn cùng làm việc, người cùng làm quan", "Hạng Tần Suất (Jun Da)": "2229.0", "Tần Suất % (Jun Da)": "97.8667822805", "GavinGrover_Once (Chiết tự trực tiếp)": "亻 + 尞", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰亻尞", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "尞", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "亻", "Unihan_Simplified (Chữ Giản thể)": "僚", "Unihan_Traditional (Chữ Phồn thể)": "僚", "Pinyin_Xie": "liáo", "Âm Hán Việt_Xie": "liêu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường kết hợp với các danh từ khác để chỉ quan chức hoặc đồng nghiệp như trong quan liêu, đồng liêu. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('捐', '{"9000": "2230.0", "Chữ Trung Quốc": "捐", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 10 | nét | 扌 | thủ | biểu nghĩa | tay (bộ thủ) | 肙 | quyên | biểu âm | sâu nhỏ (gần âm juān) | 捐 = 扌 (Thủ, biểu nghĩa: tay) + 肙 (biểu âm); chữ hình thanh. Dùng tay đưa ra/bỏ ra, gốc nghĩa ''quyên góp, hiến tặng''.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quyên\": 扌 (tay) + 肙 — dùng tay hiến tặng ra, đúng nghĩa ''quyên góp, hiến tặng'' trong 捐款, 捐赠, 捐献, 募捐. | Gương Hán-Việt | ''quyên'' trong ''quyên góp'', ''quyên tặng'', ''lạc quyên'' | Mở khoá kiến thức | Nắm 捐 mở khoá loạt từ HSK 5-7: 捐, 捐助, 捐款, 捐赠, 募捐, 捐献.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Theo Wiktionary, 捐 là hình thanh: 手/扌 (tay, biểu nghĩa) + 肙 (biểu âm). Nghĩa gốc ''dùng tay bỏ/hiến ra'', mở rộng sang ''quyên góp, đóng góp, từ thiện'' trong 捐, 捐助, 捐款, 捐赠, 募捐, 捐献. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "quyên góp; bỏ, hiến", "Hạng Tần Suất (Jun Da)": "2230.0", "Tần Suất % (Jun Da)": "97.8695072885", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 肙", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌肙", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "肙", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "捐", "Unihan_Traditional (Chữ Phồn thể)": "捐", "Pinyin_Xie": "juān", "Âm Hán Việt_Xie": "quyên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước danh từ chỉ tiền bạc hoặc tài sản để biểu thị việc hiến tặng. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | Từ đơn | Từ vựng HSK 5: quyên góp | / | juān | / | quyên góp | / | juān | / | thuế | Xuất hiện trong lộ trình | HSK | HSK 5 | · | Thương mại và tài chính | New HSK | New HSK 6 | · | Kinh tế và tài chính", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('姊', '{"9000": "2231.0", "Chữ Trung Quốc": "姊", "Bộ thủ & thành phần_Xie": "Bộ thủ | 女 | Số nét | 7 | nét | 女 | nữ | biểu nghĩa | người nữ | 𠂔 | biểu âm | thành phần âm cổ | 姊 = 女 (Nữ, biểu nghĩa: người nữ) + 𠂔 (biểu âm, thành phần âm cổ); chữ hình thanh. Bộ 女 chỉ đây là từ chỉ người phụ nữ, phần 𠂔 cung cấp âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tỷ\": bộ 女 (nữ) — người chị trong nhà, người phụ nữ đi trước. | Gương Hán-Việt | tỷ muội (chị em gái) | Mở khoá kiến thức | Biết 姊 mở khoá: tỷ muội (姊妹 — chị em gái), biểu tỷ (表姊 — chị họ).", "Tự nguyên_Xie": "Kim văn | Tiểu triện | Lục thư thông | 姊 là chữ hình thanh: bộ 女 (nữ) biểu nghĩa ''người phụ nữ'', phần 𠂔 biểu âm. Wiktionary ghi cấu trúc 女 + 𠂔 (c1=s, c2=p, ls=psc), phần âm 𠂔 phản ánh âm trung cổ. Nghĩa gốc là chị gái — người phụ nữ lớn hơn trong gia đình. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "619.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Nữ (031) Tỉ (084)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Nữ (số 031 - phụ nữ) đứng bên cạnh chữ Tỉ (số 084). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Tỉ chỉ âm, bộ Nữ (con gái) chỉ ý. Hình ảnh người con gái đang ngồi bên bàn có cái guồng quay trục cuốn (Tỉ) để se sợi dệt vải. Tỷ là người chị gái.", "Nghĩa Tiếng Việt_Xie": "chị; chị gái", "Hạng Tần Suất (Jun Da)": "2231.0", "Tần Suất % (Jun Da)": "97.8722317797", "GavinGrover_Once (Chiết tự trực tiếp)": "女 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰女", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "姊", "Unihan_Traditional (Chữ Phồn thể)": "姉", "Pinyin_Xie": "zǐ", "Âm Hán Việt_Xie": "tỉ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ xưng hô hoặc kết hợp thành từ ghép như tỷ muội. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('骚', '{"9000": "2232.0", "Chữ Trung Quốc": "骚", "Bộ thủ & thành phần_Xie": "Bộ thủ | 馬 | Số nét | 12 | nét | 马 | mã | biểu nghĩa | ngựa | 蚤 | tảo | biểu âm | bọ chét (cho âm sāo) | 骚 = 马 (Mã, biểu nghĩa: ngựa) + 蚤 (Tảo, biểu âm); chữ hình thanh. Phồn thể là 騷. Bộ mã gợi hình ngựa bị bọ chét cắn, cựa quậy bồn chồn; 蚤 cung cấp âm (sāo). Nghĩa buồn phiền là mượn âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tao\": ngựa (马) bị bọ chét (蚤/tảo) cắn bồn chồn — tao loạn, náo động, cũng dùng ''phát tao'' (phàn nàn). | Gương Hán-Việt | tao trong 牢骚 (lao tao — phàn nàn, khiếu nại) | Mở khoá kiến thức | Biết 骚 (tao) mở khoá: 牢骚 (phàn nàn), 骚乱 (náo loạn), 骚扰 (quấy rối), 离骚 (Ly Tao — tên tác phẩm Khuất Nguyên).", "Tự nguyên_Xie": "Theo Wiktionary, 骚 (phồn thể 騷) là chữ hình thanh: bộ 馬 biểu nghĩa (ngựa — bồn chồn, cựa quậy như ngựa bị bọ cắn), 蚤 biểu âm. Nghĩa gốc là ngựa bất an. Nghĩa ''buồn phiền, u uất'' là mượn âm (theo Wiktionary: phonetic loan). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "quấy nhiễu; phong nhã, thanh cao", "Hạng Tần Suất (Jun Da)": "2232.0", "Tần Suất % (Jun Da)": "97.8749542038", "GavinGrover_Once (Chiết tự trực tiếp)": "马 + 蚤", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰马蚤", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "蚤", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "马", "Unihan_Simplified (Chữ Giản thể)": "骚", "Unihan_Traditional (Chữ Phồn thể)": "騷", "Pinyin_Xie": "sāo", "Âm Hán Việt_Xie": "tao", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Động từ | 动词 | Có thể làm tính từ chỉ sự lẳng lơ, tao nhã hoặc làm động từ chỉ sự quấy nhiễu. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('拓', '{"9000": "2233.0", "Chữ Trung Quốc": "拓", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 8 | nét | 扌 | thủ | biểu nghĩa | tay, hành động bằng tay | 石 | thạch | biểu âm | đá (cho âm tà/tuò) | 拓 = 扌(Thủ, biểu nghĩa: tay) + 石 (Thạch, biểu âm); chữ hình thanh. Bộ thủ chỉ hành động mở rộng, khai phá; 石 cung cấp âm (tà/tuò). Tay khai mở đất đá, mở rộng lãnh thổ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thác\": tay (扌) khai thác (石/thạch) đất đá — thác mở, khai thác và mở rộng không gian. | Gương Hán-Việt | thác trong 开拓 (khai thác — mở rộng, phát triển) | Mở khoá kiến thức | Biết 拓 (thác) mở khoá: 开拓 (khai thác/mở rộng), 拓展 (mở rộng), 拓宽 (mở rộng ra), 拓荒 (khai hoang).", "Tự nguyên_Xie": "Theo Wiktionary, 拓 là chữ hình thanh: bộ 手 (扌) biểu nghĩa (tay — mở rộng, khai phá), 石 biểu âm. Có hai âm đọc: tà (rập in khắc đá) và tuò (mở rộng, khai thác). Nghĩa ''mở rộng'' là âm tuò. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nâng, nhấc; bày ra; cái khay để bưng đồ; trách nhiệm", "Hạng Tần Suất (Jun Da)": "2233.0", "Tần Suất % (Jun Da)": "97.8776704265", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 石", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌石", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "石", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "拓", "Unihan_Traditional (Chữ Phồn thể)": "拓", "Pinyin_Xie": "tà", "Âm Hán Việt_Xie": "thác", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước danh từ để chỉ hoạt động khai phá hoặc sao chép bia đá. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('歪', '{"9000": "2234.0", "Chữ Trung Quốc": "歪", "Bộ thủ & thành phần_Xie": "Bộ thủ | 止 | Số nét | 9 | nét | 不 | bất | biểu nghĩa | không, phủ định | 正 | chinh | biểu nghĩa | thẳng, chính trực | 歪 = 不 (Bất: không) + 正 (Chinh: thẳng/đúng); chữ hội ý. Không thẳng = méo lệch — đây là cách giải thích dân gian trực quan, mặc dù chữ gốc là 竵.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"oai\": không 不 (bất) thẳng 正 (chinh) — 歪 nghĩa là méo lệch, không thẳng đứng. | Gương Hán-Việt | oai trong ''oai lệch'' (méo lệch, không thẳng) | Mở khoá kiến thức | Biết 歪 (oai) mở khoá: 歪曲 (xuyên tạc), 歪理 (lý lẽ vẹo vò), 歪斜 (nghiêng lệch).", "Tự nguyên_Xie": "Lục thư thông | Theo Wiktionary, 歪 vốn viết là 竵. Dạng hiện đại là hội ý (ic): 不 (bất: không) + 正 (chinh: thẳng). Không thẳng = méo, lệch. Đây là chữ hội ý minh bạch, dễ nhớ. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "méo, lệch", "Hạng Tần Suất (Jun Da)": "2234.0", "Tần Suất % (Jun Da)": "97.8803840652", "GavinGrover_Once (Chiết tự trực tiếp)": "不 + 正", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱不正", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "正", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "不", "Unihan_Simplified (Chữ Giản thể)": "歪", "Unihan_Traditional (Chữ Phồn thể)": "歪", "Pinyin_Xie": "wāi", "Âm Hán Việt_Xie": "oai", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường làm tính từ đứng trước danh từ hoặc làm vị ngữ để miêu tả trạng thái không ngay ngắn. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | Từ đơn | Từ vựng HSK 5: cong | / | wāi | / | cong | Xuất hiện trong lộ trình | HSK | HSK 5 | · | Hình thức và tính chất vật lý | New HSK | New HSK 7-9 | · | Tính chất vật lý", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('粘', '{"9000": "2235.0", "Chữ Trung Quốc": "粘", "Bộ thủ & thành phần_Xie": "Bộ thủ | 米 | Số nét | 11 | nét | 米 | mễ | biểu nghĩa | gạo, hạt gạo | 占 | chiêm | biểu âm | chiếm giữ, bói toán | 粘 = 米 (Mễ, biểu nghĩa: gạo) + 占 (Chiêm, biểu âm); chữ hình thanh. Bộ 米 cho nghĩa liên quan đến gạo/tinh bột dính, 占 cho âm (zhān ~ chiêm).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"niêm\": hạt gạo 米 (mễ) chiêm 占 (chiêm) lấy mọi thứ — gạo nếp niêm 粘 dính như keo. | Gương Hán-Việt | niêm trong ''niêm phong'' (dán kín, phong niêm) | Mở khoá kiến thức | Biết 粘 (niêm) mở khoá: 粘贴 (dán, paste), 粘土 (đất sét dính), 粘液 (dịch nhầy).", "Tự nguyên_Xie": "Theo Wiktionary, 粘 là chữ hình thanh (psc): 米 (mễ, biểu nghĩa: gạo) + 占 (chiêm, biểu âm). Nghĩa gốc là gạo nếp dính — loại gạo có chất dính nhớt. Sau mở rộng sang nghĩa ''dán, dính''. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "468.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Mễ (116) Chiêm (106)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Mễ (số 119 - hạt gạo) và chữ Chiêm (số 25 - bói toán) . Gạo (Mễ) nếp nấu chín mang đi cúng tế bói toán (Chiêm) thường rất dẻo và kết dính lại với nhau (niêm). Giải thích sự chuyển ý: Chữ Chiêm (bói toán) chỉ âm, chữ Mễ (gạo) chỉ ý. Hạt gạo (Mễ) nếp khi nấu chín có tính chất dính chặt vào nhau (Niêm). *(Biến âm Hán Việt: Chiêm -> Niêm)*", "Nghĩa Tiếng Việt_Xie": "chất dính; dán vào", "Hạng Tần Suất (Jun Da)": "2235.0", "Tần Suất % (Jun Da)": "97.8830873682", "GavinGrover_Once (Chiết tự trực tiếp)": "米 + 占", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰米占", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "占", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "米", "Unihan_Simplified (Chữ Giản thể)": "粘", "Unihan_Traditional (Chữ Phồn thể)": "粘", "Pinyin_Xie": "zhān", "Âm Hán Việt_Xie": "niêm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Thường làm động từ chỉ hành động dán hoặc làm tính từ miêu tả đặc tính kết dính. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | zhān | / | dán | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Words II", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('柄', '{"9000": "2236.0", "Chữ Trung Quốc": "柄", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 9 | nét | 木 | mộc | biểu nghĩa | gỗ, cây | 丙 | bính | biểu âm | can thứ ba, âm bính | 柄 = 木 (Mộc, biểu nghĩa: gỗ) + 丙 (Bính, biểu âm); chữ hình thanh. Bộ 木 chỉ đây là vật dụng làm từ gỗ, phần 丙 cho âm đọc bǐng. Gốc nghĩa là cán (tay cầm) làm bằng gỗ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bính\": 木 (gỗ) + 丙 (can Bính) — cái cán gỗ, bính là thứ ta nắm trong tay để điều khiển. | Gương Hán-Việt | bính quyền (nắm quyền hành) | Mở khoá kiến thức | Biết 柄 mở khoá: bả bính (把柄 — bằng chứng, cơ sở), chính bính (政柄 — quyền bính chính trị).", "Tự nguyên_Xie": "柄 là chữ hình thanh: bộ 木 (mộc) biểu nghĩa ''gỗ'', phần 丙 biểu âm. Wiktionary mô tả là ''cán gỗ'' (a wooden handle). Từ nghĩa cán, mở rộng sang nghĩa bằng chứng, cơ sở — như người ta ''nắm'' được bằng chứng. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cán, báng, tay cầm; người cầm quyền", "Hạng Tần Suất (Jun Da)": "2236.0", "Tần Suất % (Jun Da)": "97.8857896377", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 丙", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木丙", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "丙", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "柄", "Unihan_Traditional (Chữ Phồn thể)": "柄", "Pinyin_Xie": "bǐng", "Âm Hán Việt_Xie": "bính", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Lượng từ | 量词 | Thường làm danh từ chỉ bộ phận cầm nắm hoặc làm lượng từ cho các vật có cán như rìu, quạt. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Lượng từ | 量词 | Đứng giữa số từ (hoặc 这/那) và danh từ: 一杯茶, 这本书. Mỗi danh từ đi với lượng từ riêng; 个 là lượng từ dùng chung phổ biến nhất.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('坑', '{"9000": "2237.0", "Chữ Trung Quốc": "坑", "Bộ thủ & thành phần_Xie": "Bộ thủ | 土 | Số nét | 7 | nét | 土 | thổ | biểu nghĩa | đất, đất cát | 亢 | kháng | biểu âm | cao, cứng đầu (cho âm kēng) | 坑 = 土 (Thổ, biểu nghĩa: đất) + 亢 (Kháng, biểu âm); chữ hình thanh. Bộ thổ chỉ đây là địa hình, cái hố trong đất; 亢 cung cấp âm (kēng). Hố lõm trong mặt đất.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khanh\": đất (土) trũng xuống cao thấp (亢/kháng) — khanh hào, cái hố bẫy chân người. | Gương Hán-Việt | khanh trong 坑道 (khanh đạo — đường hầm) và 坑骗 (khanh phiến — lừa đảo) | Mở khoá kiến thức | Biết 坑 (khanh) mở khoá: 坑道 (đường hầm), 坑骗 (lừa đảo), 火坑 (hố lửa — cạm bẫy), 坑洼 (mặt đất lồi lõm).", "Tự nguyên_Xie": "Theo Wiktionary, 坑 là chữ hình thanh: trong dạng hiện tại, bộ 土 biểu nghĩa (đất — hố trong đất), 亢 biểu âm. Dạng cổ hơn là 阬. Nghĩa gốc là hố, lỗ; mở rộng sang hầm, bẫy, và ''lừa đảo'' (theo nghĩa bóng). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1834.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thổ (032) Kháng (1833)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Thổ (số 032 - đất/ 土 /chỉ ý) ở bên trái chữ Kháng (số 1833 - quá mức/ 亢 /chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Kháng chỉ âm, bộ Thổ chỉ ý. Khanh là cái hố, cái hốc, cái vũng được đào dưới đất (hố khanh, nê khanh - vũng bùn).", "Nghĩa Tiếng Việt_Xie": "cái hố; đường hầm; hãm hại; chôn sống", "Hạng Tần Suất (Jun Da)": "2237.0", "Tần Suất % (Jun Da)": "97.8884888065", "GavinGrover_Once (Chiết tự trực tiếp)": "土 + 亢", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰土亢", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "亢", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "土", "Unihan_Simplified (Chữ Giản thể)": "坑", "Unihan_Traditional (Chữ Phồn thể)": "坑", "Pinyin_Xie": "kēng", "Âm Hán Việt_Xie": "khanh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường làm danh từ chỉ cái hố hoặc làm động từ mang nghĩa lừa gạt, hãm hại người khác. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | kēng | / | hố, lỗ, hõm | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Địa lý II | HSK | HSK 6 | · | Địa lý", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('陌', '{"9000": "2238.0", "Chữ Trung Quốc": "陌", "Bộ thủ & thành phần_Xie": "Bộ thủ | 阜 | Số nét | 8 | nét | 阝 | phụ | biểu nghĩa | bộ phụ, đất/vùng đất | 百 | bách | biểu âm | trăm | 陌 = 阝 (Phụ, biểu nghĩa: bờ đất/địa mạo) + 百 (Bách, biểu âm); chữ hình thanh. Bộ 阝 (bên trái là bộ phụ) cho nghĩa đất đai địa hình, 百 cho âm (mò ~ mạch).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mạch\": bờ đất 阝 (phụ) trăm 百 (bách) lối — con đường mạch 陌 xa lạ qua trăm bờ ruộng. | Gương Hán-Việt | mạch trong ''mạch lạc'' (mạch, hướng đi); trong từ 陌生 là ''lạ lẫm'' | Mở khoá kiến thức | Biết 陌 (mạch) mở khoá: 陌生 (xa lạ, không quen), 陌路 (đường lạ, người xa lạ).", "Tự nguyên_Xie": "Theo Wiktionary, 陌 là chữ hình thanh (psc): 阜 (phụ, biểu nghĩa: đất cao/bờ) + 百 (bách, biểu âm). Nghĩa gốc là bờ ruộng chạy theo hướng đông-tây. Sau mở rộng sang ''đường nhỏ giữa đồng ruộng'', rồi ''xa lạ, không quen biết'' trong 陌生. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bờ ruộng", "Hạng Tần Suất (Jun Da)": "2238.0", "Tần Suất % (Jun Da)": "97.8911864249", "GavinGrover_Once (Chiết tự trực tiếp)": "阝 + 百", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰阝百", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "百", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "阝", "Unihan_Simplified (Chữ Giản thể)": "陌", "Unihan_Traditional (Chữ Phồn thể)": "陌", "Pinyin_Xie": "mò", "Âm Hán Việt_Xie": "mạch", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng trong văn viết cổ để chỉ đường sá hoặc người xa lạ không quen biết. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('窄', '{"9000": "2239.0", "Chữ Trung Quốc": "窄", "Bộ thủ & thành phần_Xie": "Bộ thủ | 穴 | Số nét | 10 | nét | 穴 | huyệt | biểu nghĩa | hang, lỗ | 乍 | sạ | biểu âm | vừa, chợt (gần âm zhǎi) | 窄 = 穴 (Huyệt, biểu nghĩa: hang/lỗ) + 乍 (Sạ, biểu âm); chữ hình thanh. Hang lỗ nhỏ hẹp, gốc nghĩa ''hẹp, chật''.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trách\": 穴 (hang) + 乍 (vừa) — vừa kịp chui qua lỗ hẹp, đúng nghĩa ''hẹp, chật'' trong 窄, 狭窄. | Gương Hán-Việt | ''trách'' (Hán-Việt cho chữ này — ít gặp trong tiếng Việt) | Mở khoá kiến thức | Nắm 窄 mở khoá từ HSK 4-6: 窄, 狭窄.", "Tự nguyên_Xie": "Theo Wiktionary, 窄 là hình thanh: 穴 (hang/lỗ, biểu nghĩa) + 乍 (Sạ, biểu âm). Nghĩa gốc ''hẹp, chật'' (về không gian, quần áo); mở rộng sang nghĩa trừu tượng ''hẹp hòi'' (tâm hồn hẹp) và ''khó khăn, bí bách'' trong khẩu ngữ. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "trật hẹp", "Hạng Tần Suất (Jun Da)": "2239.0", "Tần Suất % (Jun Da)": "97.8938835265", "GavinGrover_Once (Chiết tự trực tiếp)": "穴 + 乍", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱穴乍", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "乍", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "穴", "Unihan_Simplified (Chữ Giản thể)": "窄", "Unihan_Traditional (Chữ Phồn thể)": "窄", "Pinyin_Xie": "zhǎi", "Âm Hán Việt_Xie": "trách", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường làm tính từ đứng trước danh từ hoặc làm vị ngữ để miêu tả không gian, phạm vi hạn chế. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | zhǎi | / | hẹp | Xuất hiện trong lộ trình | HSK | HSK 4 | · | Tính từ | New HSK | New HSK 7-9 | · | Đặc điểm III", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('湘', '{"9000": "2240.0", "Chữ Trung Quốc": "湘", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 12 | nét | 氵 | thuỷ | biểu nghĩa | nước | 相 | tương | biểu âm | tương — âm xiang | 湘 = 氵 (Thuỷ, biểu nghĩa: nước) + 相 (Tương, biểu âm); chữ hình thanh. Bộ 氵 chỉ đây là tên sông, phần 相 (tương) cho âm xiang. Đây là tên sông Tương — con sông lớn ở Hồ Nam, Trung Quốc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tương\": 氵 (nước) + 相 (tương) — sông Tương chảy qua đất Hồ Nam, mang nặng hồn thơ Khuất Nguyên. | Gương Hán-Việt | Tương giang (sông Tương), Tương kịch (hý kịch Hồ Nam) | Mở khoá kiến thức | Biết 湘 mở khoá: Hồ Nam (湖南省) còn gọi tắt là Tương (湘); Tương kịch (湘剧 — tuồng Hồ Nam).", "Tự nguyên_Xie": "Kim văn | 湘 là chữ hình thanh: bộ 水/氵 (thuỷ) biểu nghĩa ''nước'', phần 相 biểu âm. Wiktionary xác nhận cấu trúc 水 + 相 (c1=s, c2=p, ls=psc). 湘 là tên sông Tương (Xiangjiang), con sông chính của tỉnh Hồ Nam — nên Hồ Nam còn gọi là Tương (湘). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "417.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thủy (306) Tướng (259)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Thủy (số 76) và chữ Tướng (số 259 - nhìn nhau) . Dòng nước (Thủy) mà hai người nhìn nhau (Tướng) rớt nước mắt tiễn biệt (tương tư sông Tương). Giải thích sự chuyển ý: Chữ Tướng (hình tướng) chỉ âm, chữ Thủy (nước) chỉ ý. Tên một dòng sông (Thủy) nổi tiếng ở Trung Quốc (Tương). *(Biến âm Hán Việt: Tướng -> Tương)*", "Nghĩa Tiếng Việt_Xie": "sông Tương", "Hạng Tần Suất (Jun Da)": "2240.0", "Tần Suất % (Jun Da)": "97.8965744267", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 相", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵相", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "相", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "湘", "Unihan_Traditional (Chữ Phồn thể)": "湘", "Pinyin_Xie": "xiāng", "Âm Hán Việt_Xie": "tương", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Thường dùng làm danh từ riêng chỉ sông Tương hoặc viết tắt của tỉnh Hồ Nam. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('兆', '{"9000": "2241.0", "Chữ Trung Quốc": "兆", "Bộ thủ & thành phần_Xie": "Bộ thủ | 儿 | Số nét | 6 | nét | 兆 | triệu | tượng hình | hình ảnh vết nứt trên mai rùa khi bói toán — điềm báo | 兆 là chữ tượng hình độc lập. Theo Wiktionary, trong giáp cốt văn, 兆 hình tượng trưng cho vết nứt trên mai rùa khi hơ lửa trong nghi lễ bói toán — những vết nứt mang điềm báo. Một số dạng biến thể giống 化 (hóa). Không có thành phần biểu âm hay biểu nghĩa riêng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"triệu\": vết nứt trên mai rùa báo điềm — triệu chứng, triệu hiệu của điều sắp xảy ra. | Gương Hán-Việt | triệu trong 预兆 (dự triệu — điềm báo trước), 兆头 (triệu đầu — điềm) | Mở khoá kiến thức | Biết 兆 (triệu) mở khoá: 预兆 (điềm báo), 吉兆 (điềm lành), 凶兆 (điềm xấu), cũng là đơn vị số lớn (triệu).", "Tự nguyên_Xie": "Theo Wiktionary, 兆 là chữ tượng hình (象形): hình dạng gốc trong giáp cốt văn là vết nứt trên mai rùa khi hơ lửa — dùng để bói toán điềm lành dữ. Nghĩa gốc là điềm báo, triệu chứng. Nghĩa số lớn (triệu, 10^6 hoặc 10^12) là mở rộng sau. Sách Thuyết Văn không có giáp cốt, nên giải thích sai là tượng hình vết nứt xương. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "668.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Nhân (011) Bát (012)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Hình những vết nứt nẻ trên mai rùa. Giải thích sự chuyển ý: Đây là chữ Tượng hình. Người xưa dùng mai rùa để đốt rồi xem những vết nứt để bói xem điềm lành hay dữ. Triệu là điềm báo, triệu chứng, hoặc số triệu (1.000.000).", "Nghĩa Tiếng Việt_Xie": "điềm, triệu chứng; một triệu", "Hạng Tần Suất (Jun Da)": "2241.0", "Tần Suất % (Jun Da)": "97.8992637765", "GavinGrover_Once (Chiết tự trực tiếp)": "儿 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴儿", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "兆", "Unihan_Traditional (Chữ Phồn thể)": "兆", "Pinyin_Xie": "zhào", "Âm Hán Việt_Xie": "triệu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Số từ | 数词 | Động từ | 动词 | Thường làm danh từ chỉ điềm báo hoặc số từ biểu thị đơn vị số lượng lớn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Số từ | 数词 | Chỉ số lượng hoặc thứ tự. Hầu như không đứng thẳng trước danh từ mà phải chèn lượng từ ở giữa: 两个人. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('崖', '{"9000": "2242.0", "Chữ Trung Quốc": "崖", "Bộ thủ & thành phần_Xie": "Bộ thủ | 山 | Số nét | 11 | nét | 山 | sơn | biểu nghĩa | núi | 厓 | nhai | biểu âm | vách đá (cho âm yá) | 崖 = 山 (Sơn, biểu nghĩa: núi) + 厓 (Nhai, biểu âm); chữ hình thanh. Bộ sơn chỉ đây là địa hình núi non; 厓 cung cấp âm (yá) và có nghĩa gốc là vách đá, bờ dốc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nhai\": núi (山) dốc như vách nhai (厓/nhai) — nhai đá dựng đứng, vực thẳm nguy hiểm. | Gương Hán-Việt | nhai trong 悬崖 (huyền nhai — vách đá treo lơ lửng) | Mở khoá kiến thức | Biết 崖 (nhai) mở khoá: 悬崖 (vách đá), 悬崖峭壁 (vách đá dốc đứng), 崖边 (mép vực).", "Tự nguyên_Xie": "Theo Wiktionary, 崖 là chữ hình thanh: bộ 山 biểu nghĩa (núi — vách núi dốc đứng), 厓 biểu âm. Cũng được phân tích là 屵 (vách đá) + 圭 (biểu âm). Phần 土 trong 厓 không có liên hệ với đất trong nghĩa gốc — đó là dạng tiểu triện có thể là ngọc phẩm. Nghĩa gốc là vách đá, bờ dốc. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ven núi, cạnh núi, vách núi", "Hạng Tần Suất (Jun Da)": "2242.0", "Tần Suất % (Jun Da)": "97.9019505424", "GavinGrover_Once (Chiết tự trực tiếp)": "山 + 厓", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱山厓", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "厓", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "山", "Unihan_Simplified (Chữ Giản thể)": "崖", "Unihan_Traditional (Chữ Phồn thể)": "崖", "Pinyin_Xie": "yá", "Âm Hán Việt_Xie": "nhai", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ địa hình vách đá hiểm trở hoặc kết hợp thành từ ghép. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('骄', '{"9000": "2243.0", "Chữ Trung Quốc": "骄", "Bộ thủ & thành phần_Xie": "Bộ thủ | 馬 | Số nét | 9 | nét | 马 | mã | biểu nghĩa | con ngựa | 乔 | kiều | biểu âm | gợi âm jiāo, vốn nghĩa ''cao'' | 骄 = 马 (Mã, biểu nghĩa: ngựa) + 乔 (Kiều, biểu âm); là dạng giản thể của 驕, chữ hình thanh. Ngựa cao lớn, kiêu hãnh — phái sinh nghĩa ''kiêu ngạo, tự hào''.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"kiêu\": 马 (ngựa) + 乔 (cao) — ngựa cao đầu kiêu hãnh, ấy là ''kiêu''; nhớ 骄傲 (kiêu ngạo, tự hào). | Gương Hán-Việt | ''kiêu'' trong ''kiêu ngạo'', ''kiêu hãnh'', ''kiêu binh'' | Mở khoá kiến thức | Biết 骄 là mở 骄傲 — chìa khoá cảm xúc tự hào/kiêu HSK 4.", "Tự nguyên_Xie": "Đại triện | Tiểu triện | Theo Wiktionary, 骄 là dạng giản thể của 驕, trong đó 馬 rút thành 马 và 喬 rút thành 乔. 驕 phồn thể là chữ hình thanh: 馬 (biểu nghĩa: ngựa) ghép với 喬 (biểu âm). Nghĩa gốc ''ngựa cao lớn, kiêu hãnh'' phát triển thành ''kiêu ngạo, tự hào'' — cả nghĩa tích cực (自豪) và tiêu cực (傲慢). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "kiêu căng", "Hạng Tần Suất (Jun Da)": "2243.0", "Tần Suất % (Jun Da)": "97.904635758", "GavinGrover_Once (Chiết tự trực tiếp)": "马 + 乔", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰马乔", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "乔", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "马", "Unihan_Simplified (Chữ Giản thể)": "骄", "Unihan_Traditional (Chữ Phồn thể)": "驕", "Pinyin_Xie": "jiāo", "Âm Hán Việt_Xie": "kiêu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường làm tính từ đứng trước danh từ để tu sức hoặc làm vị ngữ biểu thị thái độ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('刹', '{"9000": "2244.0", "Chữ Trung Quốc": "刹", "Bộ thủ & thành phần_Xie": "Bộ thủ | 刀 | Số nét | 8 | nét | 杀 | sát | biểu âm+hình | giết (biểu âm cho âm shā/chà) | 刂 | đao | biểu nghĩa | dao, chém (bộ đao giản thể) | 刹 = 杀 (Sát, biểu âm) + 刂(Đao, biểu nghĩa: dao); chữ hình thanh. Đây là giản thể/dị thể của 剎. Bộ đao chỉ hành động dừng lại gấp như lưỡi dao chém; 杀 cung cấp âm (shā — phanh, hoặc chà — khoảnh khắc).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sát\": lưỡi dao (刂) sát xuống dừng gấp (杀/sát) — sát-na, một khoảnh khắc phanh đứng. | Gương Hán-Việt | sát trong 刹那 (sát-na — khoảnh khắc), 刹车 (sát xa — phanh xe) | Mở khoá kiến thức | Biết 刹 (sát) mở khoá: 刹车 (phanh xe), 刹那 (khoảnh khắc), 一刹那 (trong chớp mắt), 古刹 (chùa cổ).", "Tự nguyên_Xie": "刹 là dị thể của 剎 (theo Wiktionary). 剎 có hai nghĩa và hai âm: shā (phanh dừng) và chà (khoảnh khắc — mượn từ tiếng Phạn ''kṣaṇa'' qua Phật giáo). Cấu tạo gốc dùng bộ đao biểu nghĩa. Chưa có glyph-origin chi tiết rõ ràng trong Wiktionary cho dạng giản thể này. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái tháp thờ Phật, ngôi chùa; (xem: sát na 刹那)", "Hạng Tần Suất (Jun Da)": "2244.0", "Tần Suất % (Jun Da)": "97.9073152889", "GavinGrover_Once (Chiết tự trực tiếp)": "杀 + 刂", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰杀刂", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "杀", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "刂", "Unihan_Simplified (Chữ Giản thể)": "刹", "Unihan_Traditional (Chữ Phồn thể)": "剎", "Pinyin_Xie": "shā", "Âm Hán Việt_Xie": "sát", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường làm động từ chỉ hành động phanh xe hoặc danh từ trong từ ghép chỉ thời gian cực ngắn. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鞭', '{"9000": "2245.0", "Chữ Trung Quốc": "鞭", "Bộ thủ & thành phần_Xie": "Bộ thủ | 革 | Số nét | 18 | nét | 革 | cách | biểu nghĩa | da thuộc, đồ da | 便 | tiện | biểu âm | tiện lợi, phân | 鞭 = 革 (Cách, biểu nghĩa: da thuộc) + 便 (Tiện, biểu âm); chữ hình thanh. Bộ 革 cho nghĩa là đồ làm từ da (roi da), 便 cho âm (biān ~ tiện).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tiên\": da 革 (cách) tiện 便 (tiện) tay cầm — cái roi 鞭 tiên làm bằng da để thúc ngựa. | Gương Hán-Việt | tiên trong ''tiên roi'' (roi da), ''鞭炮 tiên pháo'' (pháo nổ) | Mở khoá kiến thức | Biết 鞭 (tiên) mở khoá: 鞭炮 (pháo nổ), 鞭策 (thúc giục), 鞭打 (quất roi).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Theo Wiktionary, 鞭 là chữ hình thanh (psc): 革 (cách, biểu nghĩa: da thuộc) + 便 (tiện, biểu âm). Nghĩa gốc là roi da — vật làm từ da để đánh ngựa hoặc trừng phạt. Sau mở rộng sang ''pháo nổ'' (鞭炮) và ''thúc giục, cưỡng bức''. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái roi; gậy, que; pháo đốt; quất, đánh", "Hạng Tần Suất (Jun Da)": "2245.0", "Tần Suất % (Jun Da)": "97.9099901688", "GavinGrover_Once (Chiết tự trực tiếp)": "革 + 便", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰革便", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "便", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "革", "Unihan_Simplified (Chữ Giản thể)": "鞭", "Unihan_Traditional (Chữ Phồn thể)": "鞭", "Pinyin_Xie": "biān", "Âm Hán Việt_Xie": "tiên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường làm danh từ chỉ công cụ hoặc động từ chỉ hành động quất roi, thúc giục. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('芒', '{"9000": "2246.0", "Chữ Trung Quốc": "芒", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 6 | nét | 艹 | thảo | biểu nghĩa | cỏ, thực vật | 亡 | vong | biểu âm | mất, chết (cho âm máng) | 芒 = 艹 (Thảo, biểu nghĩa: cỏ cây) + 亡 (Vong, biểu âm); chữ hình thanh. Bộ thảo chỉ đây là thực vật; 亡 cung cấp âm (máng). Có thể dạng gốc dùng 方. Nghĩa gốc là đầu nhọn của ngọn cỏ, tua cỏ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mang\": cỏ (艹) mọc hoang vong (亡/vong) không kiểm soát — mang quang, ánh sáng tua rua như đầu nhọn cỏ. | Gương Hán-Việt | mang trong 光芒 (quang mang — tia sáng, ánh hào quang) | Mở khoá kiến thức | Biết 芒 (mang) mở khoá: 光芒 (tia sáng), 芒果 (xoài), 芒刺在背 (gai đâm vào lưng — bất an), 锋芒 (mũi nhọn — sắc bén).", "Tự nguyên_Xie": "Theo Wiktionary, 芒 là chữ hình thanh: bộ 艸 (艹) biểu nghĩa (cỏ — đầu nhọn của cây cỏ), 亡 biểu âm. Có thể dạng gốc là 方. Nghĩa gốc là mũi nhọn, tua cỏ (đầu sắc của hạt lúa). Mở rộng sang ánh sáng rực rỡ (đầu nhọn của tia sáng). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ngọn cỏ; mũi nhọn của gươm, dao", "Hạng Tần Suất (Jun Da)": "2246.0", "Tần Suất % (Jun Da)": "97.9126640151", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 亡", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹亡", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "亡", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "芒", "Unihan_Traditional (Chữ Phồn thể)": "芒", "Pinyin_Xie": "máng", "Âm Hán Việt_Xie": "mang", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ trong các từ ghép chỉ tia sáng hoặc phần nhọn của thực vật. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('筋', '{"9000": "2247.0", "Chữ Trung Quốc": "筋", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 12 | nét | 竹 | trúc | biểu nghĩa | tre, gân dai như tre | 肋 | lặc | biểu âm+nghĩa | sườn (gân cơ bên sườn) | 筋 = 竹 (Trúc, biểu nghĩa: tre — dai và dẻo) + 肋 (Lặc/力, biểu nghĩa phụ và âm); chữ hội ý (有意). Theo Wiktionary, 筋 là hội ý: 竹 (tre — sợi dai như gân tre khi lột) + 𠛧 (thịt lột — gân); bộ 力 là biến thể của 刀. Gân cơ dai như sợi tre khi tước ra.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cân\": sợi tre (竹) dai dẻo như gân bắp thịt (肋/lặc) — cân cơ bắp căng kéo. | Gương Hán-Việt | cân trong 筋骨 (cân cốt — gân cốt), 脑筋 (não cân — não trí) | Mở khoá kiến thức | Biết 筋 (cân) mở khoá: 脑筋 (trí não), 筋骨 (gân cốt), 橡皮筋 (dây thun), 伤脑筋 (đau đầu/rắc rối).", "Tự nguyên_Xie": "Theo Wiktionary, 筋 là chữ hội ý: 竹 (tre) + 𠛧 (thịt lột — gân); gân cơ được so sánh với sợi tre khi lột ra: dai và dẻo. Lưu ý: bộ 力 trong 筋 là biến thể bị đọc nhầm của 刀/刂. Nghĩa gốc là gân, gân cơ; mở rộng sang cơ bắp, đường gân nổi lên. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "gân (thớ thịt)", "Hạng Tần Suất (Jun Da)": "2247.0", "Tần Suất % (Jun Da)": "97.9153357942", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 肋", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮肋", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "肋", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "筋", "Unihan_Traditional (Chữ Phồn thể)": "筋", "Pinyin_Xie": "jīn", "Âm Hán Việt_Xie": "cân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ bộ phận cơ thể hoặc các vật có tính chất dai, đàn hồi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | jīn | / | cơ bắp | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Cơ thể tôi", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('聘', '{"9000": "2248.0", "Chữ Trung Quốc": "聘", "Bộ thủ & thành phần_Xie": "Bộ thủ | 耳 | Số nét | 13 | nét | 耳 | nhĩ | biểu nghĩa | tai — lắng nghe khi tuyển dụng | 甹 | phinh | biểu âm | gợi âm pìn | 聘 = 耳 (Nhĩ: tai) + 甹 (Phinh, biểu âm); chữ hình thanh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sính\": cái tai 耳 hướng về lời 甹 — lắng nghe lời mời, đó là ''sính'' (mời, tuyển). | Gương Hán-Việt | sính trong \"sính lễ\" 聘禮, \"sính dụng\" 聘用 | Mở khoá kiến thức | Biết 聘 mở khoá nhóm từ về tuyển dụng: 招聘, 应聘, 聘请, 聘用.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Wiktionary chỉ ghi ''Han etym'' đơn giản. Phân tích thành phần: 耳 (tai) cho nghĩa ''mời nghe lời thỉnh cầu'', 甹 cho âm pìn. Nghĩa gốc ''mời mọc, lễ hỏi cưới'', mở rộng thành ''thuê người, tuyển dụng''. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tìm hỏi, mời đón; lễ cưới", "Hạng Tần Suất (Jun Da)": "2248.0", "Tần Suất % (Jun Da)": "97.9179962041", "GavinGrover_Once (Chiết tự trực tiếp)": "耳 + 甹", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰耳甹", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "甹", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "耳", "Unihan_Simplified (Chữ Giản thể)": "聘", "Unihan_Traditional (Chữ Phồn thể)": "聘", "Pinyin_Xie": "pìn", "Âm Hán Việt_Xie": "sính", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ chỉ việc thuê mướn nhân sự hoặc dạm hỏi lễ cưới. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | pìn | / | thuê | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Làm việc tôi", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('钩', '{"9000": "2249.0", "Chữ Trung Quốc": "钩", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 9 | nét | 钅 | kim | biểu nghĩa | kim loại | 勾 | câu | biểu âm | móc, câu | 钩 = 钅(Kim, biểu nghĩa: kim loại) + 勾 (Câu, biểu âm); chữ hình thanh. 勾 cho âm đọc ''gōu'', bộ kim 钅 chỉ vật liệu kim loại — chiếc móc bằng kim loại.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"câu\": chiếc móc sắt (钅) uốn cong như chữ 勾 — câu cá hay treo đồ đều dùng cái câu (钩). | Gương Hán-Việt | câu trong ''câu liêm'', ''câu thúc'' | Mở khoá kiến thức | Biết 钩 (câu) mở khoá: 钩子 (móc), 挂钩 (thiết lập liên hệ), câu liêm trong vũ khí cổ.", "Tự nguyên_Xie": "Bạch thư | Tiểu triện | 钩 là dạng giản thể của 鈎, trong đó bộ 金 được rút gọn thành 钅. Wiktionary ghi 钩 đơn giản là dạng viết tắt, tra về 鉤 để thấy gốc chính. Chữ mô tả cái móc kim loại, phù hợp với cấu trúc 钅(kim loại) + 勾 (biểu âm). Chưa có nguồn học thuật về gốc giáp cốt hoặc kim văn riêng cho dạng giản thể này; độ tin cậy dựa trên phân tích cấu trúc. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái móc, lưỡi câu", "Hạng Tần Suất (Jun Da)": "2249.0", "Tần Suất % (Jun Da)": "97.9206524797", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 勾", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅勾", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "勾", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "钩", "Unihan_Traditional (Chữ Phồn thể)": "鈎", "Pinyin_Xie": "gōu", "Âm Hán Việt_Xie": "câu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường làm danh từ chỉ vật dụng hình móc hoặc động từ chỉ hành động móc nối, câu kéo. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | gōu | / | móc, vướng vào | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Words II", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('棍', '{"9000": "2250.0", "Chữ Trung Quốc": "棍", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 12 | nét | 木 | mộc | biểu nghĩa | gỗ, cây | 昆 | côn | biểu âm | anh em; đông đúc | 棍 = 木 (Mộc, biểu nghĩa: gỗ) + 昆 (Côn, biểu âm); chữ hình thanh. 昆 cho âm đọc gần với ''gùn'', bộ mộc 木 chỉ chất liệu gỗ — cây gậy bằng gỗ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"côn\": cây gậy (木) dài như tên gọi 棍 — võ côn (棍棒) là vũ khí gỗ nổi tiếng trong võ thuật Trung Hoa. | Gương Hán-Việt | côn trong ''côn đồ'', ''vũ côn'' | Mở khoá kiến thức | Biết 棍 (côn) mở khoá: 棍棒 (gậy gộc), 棍子 (cây gậy), 冰棍 (kem que), ác棍 (kẻ xấu xa).", "Tự nguyên_Xie": "Theo Wiktionary, 棍 là chữ hình thanh (psc): 木 (gỗ) là thành phần biểu nghĩa chỉ chất liệu, 昆 là thành phần biểu âm. Chữ chỉ cây gậy, đòn gỗ. Nghĩa phái sinh ''kẻ côn đồ'' (ác棍) xuất phát từ hình ảnh kẻ cầm gậy hung hăng. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1638.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Mộc (075) Côn (1637)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Mộc (số 075 - cây cối/gỗ/ 木 /chỉ ý) ở bên trái chữ Côn (số 1637/ 昆 /chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Côn chỉ âm, bộ Mộc chỉ ý. Côn là một loại vũ khí hoặc đồ dùng dài, nhẵn, làm bằng gỗ như gậy gộc (côn gỗ, mộc côn).", "Nghĩa Tiếng Việt_Xie": "cái gậy; kẻ côn đồ", "Hạng Tần Suất (Jun Da)": "2250.0", "Tần Suất % (Jun Da)": "97.9233087553", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 昆", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木昆", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "昆", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "棍", "Unihan_Traditional (Chữ Phồn thể)": "棍", "Pinyin_Xie": "gùn", "Âm Hán Việt_Xie": "côn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ công cụ dạng gậy hoặc chỉ hạng người xấu trong xã hội. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | gùn | / | gậy | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Ngôi nhà và cuộc sống hàng ngày I", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('嚷', '{"9000": "2251.0", "Chữ Trung Quốc": "嚷", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 20 | nét | 口 | khẩu | biểu nghĩa | miệng, tiếng nói | 襄 | tương | biểu âm | giúp đỡ; mặc áo | 嚷 = 口 (Khẩu, biểu nghĩa: miệng) + 襄 (Tương, biểu âm); chữ hình thanh. 襄 cho âm (ráng/rǎng gần với jóeng trong Quảng Đông), bộ 口 chỉ hành động phát ra tiếng — hét ầm ĩ bằng miệng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nhượng\": cái miệng (口) to như 襄 — khi ai đó nhượng bộ hay tranh luận thì họ hay la 嚷 (hét to lên). | Gương Hán-Việt | nhượng trong ''nhượng bộ'', ''thoái nhượng'' (khác nghĩa với hét) | Mở khoá kiến thức | Biết 嚷 (nhượng) mở khoá: 叫嚷 (la hét), 嚷嚷 (ồn ào), 嚷叫 (hét lên).", "Tự nguyên_Xie": "Theo Wiktionary, 嚷 là chữ hình thanh (psc): 口 (miệng) là thành phần biểu nghĩa, 襄 là thành phần biểu âm. Chữ chỉ hành động hét to, la ó, gây ồn ào. Có hai cách đọc: rǎng (hét lên) và rāng (trong từ láy 嚷嚷). Chữ xuất hiện tương đối muộn trong văn tự Hán. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ầm ĩ", "Hạng Tần Suất (Jun Da)": "2251.0", "Tần Suất % (Jun Da)": "97.9259639973", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 襄", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口襄", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "襄", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "嚷", "Unihan_Traditional (Chữ Phồn thể)": "嚷", "Pinyin_Xie": "rǎng", "Âm Hán Việt_Xie": "nhưỡng, nhương", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ làm vị ngữ biểu thị hành động kêu to hoặc tranh cãi ồn ào. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | Từ đơn | Từ vựng HSK 5: hét lên | / | rǎng | / | hét lên | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Âm thanh | HSK | HSK 5 | · | Liên lạc", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('腺', '{"9000": "2252.0", "Chữ Trung Quốc": "腺", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 13 | nét | 月 | nguyệt | biểu nghĩa | thịt, cơ thể (bộ nhục) | 泉 | tuyền | biểu âm | suối — âm quán/tuyền | 腺 = 月/肉 (Nguyệt/Nhục, biểu nghĩa: cơ thể) + 泉 (Tuyền, biểu âm gần); chữ mượn từ tiếng Nhật (xiàn). Bộ 月 ở đây là bộ nhục (thịt), chỉ cơ quan trong cơ thể; phần 泉 gợi hình ảnh tuyến như suối tiết dịch.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tuyến\": 月 (cơ thể) + 泉 (suối) — tuyến là bộ phận trong cơ thể tiết ra dịch như suối nhỏ. | Gương Hán-Việt | tuyến giáp (tuyến giáp trạng), hạch tuyến | Mở khoá kiến thức | Biết 腺 mở khoá: tuyến giáp (甲状腺), lâm ba tuyến (淋巴腺), tuyến nước bọt (唾液腺).", "Tự nguyên_Xie": "腺 là chữ Hán mượn từ tiếng Nhật (借用字, obor ja): chữ Nhật 腺 (せん, sen) được nhập vào tiếng Trung để chỉ khái niệm ''tuyến'' trong y học. Bộ 月 (nhục, cơ thể) + 泉 (suối) — gợi hình ảnh cơ quan tiết dịch như suối chảy. Đây là chữ tạo muộn, không có dạng giáp cốt hay kim văn. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tuyến dịch trong cơ thể", "Hạng Tần Suất (Jun Da)": "2252.0", "Tần Suất % (Jun Da)": "97.9286161386", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 泉", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月泉", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "泉", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "腺", "Unihan_Traditional (Chữ Phồn thể)": "腺", "Pinyin_Xie": "xiàn", "Âm Hán Việt_Xie": "tuyến", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng sau các từ chỉ bộ phận cơ thể để chỉ tuyến nội tiết hoặc ngoại tiết. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | Từ vựng Hán 腺 (xiàn). Hán-Việt: tuyến. | / | xiàn | / | tuyến | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Nội dung II", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('弦', '{"9000": "2253.0", "Chữ Trung Quốc": "弦", "Bộ thủ & thành phần_Xie": "Bộ thủ | 弓 | Số nét | 8 | nét | 弓 | cung | biểu nghĩa | cung tên | 玄 | huyền | biểu âm | huyền bí, đen | 弦 = 弓 (Cung, biểu nghĩa: cung tên) + 玄 (Huyền, biểu âm); chữ hình thanh. 玄 cho âm ''xián'' (huyền), bộ 弓 chỉ cung tên — dây căng trên cung, tức dây đàn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"huyền\": dây cung (弓) màu huyền (玄, đen) căng thẳng — tiếng đàn huyền (弦) ngân lên khi gảy. | Gương Hán-Việt | huyền trong ''huyền cầm'', ''quản huyền'' | Mở khoá kiến thức | Biết 弦 (huyền) mở khoá: 弦乐 (nhạc dây), 心弦 (dây đàn lòng), 上弦月 (trăng lưỡi liềm), 扣人心弦 (hồi hộp).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Theo Wiktionary, 弦 là chữ hình thanh (psc): 弓 (cung tên) là thành phần biểu nghĩa, 玄 là thành phần biểu âm. Nghĩa gốc là dây cung (bowstring), sau mở rộng sang dây đàn nhạc cụ, rồi các nghĩa hình học như hợp âm (chord), cạnh huyền (hypotenuse) trong tam giác, và hình ảnh trăng lưỡi liềm (half-moon). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "dây đàn, dây cung; trăng non", "Hạng Tần Suất (Jun Da)": "2253.0", "Tần Suất % (Jun Da)": "97.9312605281", "GavinGrover_Once (Chiết tự trực tiếp)": "弓 + 玄", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰弓玄", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "玄", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "弓", "Unihan_Simplified (Chữ Giản thể)": "弦", "Unihan_Traditional (Chữ Phồn thể)": "弦", "Pinyin_Xie": "xián", "Âm Hán Việt_Xie": "huyền", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ làm tân ngữ cho động từ hoặc kết hợp với danh từ khác để chỉ các loại dây nhạc cụ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | xián | / | dây đàn | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Nghệ thuật và Văn học II | HSK | HSK 6 | · | Thể thao, giải trí, sở thích", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('焰', '{"9000": "2254.0", "Chữ Trung Quốc": "焰", "Bộ thủ & thành phần_Xie": "Bộ thủ | 火 | Số nét | 12 | nét | 火 | hoả | biểu nghĩa | lửa | 臽 | hãm | biểu âm | cái bẫy, hố sâu | 焰 = 火 (Hoả, biểu nghĩa: lửa) + 臽 (Hãm, biểu âm); chữ hình thanh. 臽 cho âm gần ''yàn'', bộ 火 chỉ bản chất — ngọn lửa bùng cháy.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"diễm\": ngọn lửa (火) bị ''hãm'' (臽) trong lòng — khi bùng thoát ra thành diễm (焰) rực cháy. Diễm lệ cũng mang nghĩa rực rỡ như lửa. | Gương Hán-Việt | diễm trong ''hỏa diễm'', ''khí diễm'' | Mở khoá kiến thức | Biết 焰 (diễm) mở khoá: 火焰 (ngọn lửa), 焰火 (pháo hoa), 气焰 (khí thế hống hách).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Theo Wiktionary, 焰 là chữ hình thanh (psc): 火 (lửa) là thành phần biểu nghĩa, 臽 là thành phần biểu âm. Nghĩa gốc và duy nhất là ngọn lửa (flame). Hình thức tiểu triện và lục thư thông đều ghi lại. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ngọn lửa, ánh lửa", "Hạng Tần Suất (Jun Da)": "2254.0", "Tần Suất % (Jun Da)": "97.9339044009", "GavinGrover_Once (Chiết tự trực tiếp)": "火 + 臽", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰火臽", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "臽", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "火", "Unihan_Simplified (Chữ Giản thể)": "焰", "Unihan_Traditional (Chữ Phồn thể)": "焰", "Pinyin_Xie": "yàn", "Âm Hán Việt_Xie": "diễm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng sau các từ chỉ lửa hoặc ánh sáng để cấu tạo từ ghép chỉ ngọn lửa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('耍', '{"9000": "2255.0", "Chữ Trung Quốc": "耍", "Bộ thủ & thành phần_Xie": "Bộ thủ | 而 | Số nét | 9 | nét | 而 | nhi | biểu hình | bộ nhi, râu | 女 | nữ | biểu hình | phụ nữ | 耍 = 而 (Nhi, trên) + 女 (Nữ, dưới); cấu trúc hội ý hoặc nguồn gốc chưa rõ — không có glyph Wiktionary. Hai thành phần 而 và 女 kết hợp không theo kiểu hình thanh thông thường; chưa có nguồn học thuật xác nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"soạ\": chữ như người phụ nữ (女) đang múa (而 như tóc bay) — hành động soạ (耍) là đùa bỡn, chơi trò vui. | Gương Hán-Việt | soạ trong ''hí soạ'', ''soạn diễn'' (ít dùng) | Mở khoá kiến thức | Biết 耍 (soạ) mở khoá: 玩耍 (chơi đùa), 耍赖 (giở trò vô lý), 耍花样 (làm trò).", "Tự nguyên_Xie": "Wiktionary không ghi chép glyph origin cho 耍. Cấu trúc gồm 而 (nhi, bộ râu) ở trên và 女 (nữ, phụ nữ) ở dưới. Nghĩa gốc là đùa bỡn, chơi giỡn. Chưa có nguồn học thuật về gốc giáp cốt hay kim văn. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đùa bỡn", "Hạng Tần Suất (Jun Da)": "2255.0", "Tần Suất % (Jun Da)": "97.9365446561", "GavinGrover_Once (Chiết tự trực tiếp)": "而 + 女", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱而女", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "女", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "而", "Unihan_Simplified (Chữ Giản thể)": "耍", "Unihan_Traditional (Chữ Phồn thể)": "耍", "Pinyin_Xie": "shuǎ", "Âm Hán Việt_Xie": "xọa", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ vị ngữ trong câu để diễn tả hành động chơi đùa hoặc giở các mánh khóe. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | shuǎ | / | chơi | Xuất hiện trong lộ trình | HSK | HSK 6 | · | Thể thao, giải trí, sở thích | New HSK | New HSK 7-9 | · | Giải trí và thói quen II", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('俯', '{"9000": "2256.0", "Chữ Trung Quốc": "俯", "Bộ thủ & thành phần_Xie": "Bộ thủ | 人 | Số nét | 10 | nét | 亻 | nhân | biểu nghĩa | người | 府 | phủ | biểu âm | phủ, nhà, kho | 俯 = 亻(Nhân, biểu nghĩa: người) + 府 (Phủ, biểu âm); chữ hình thanh. Trong kim văn xưa dùng 勹 (người cúi) thay 亻, sau chuyển thành bộ nhân 亻. 府 cho âm ''fǔ'', gợi ý người (亻) cúi xuống.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phủ\": người (亻) như quan phủ (府) — khi đến phủ quan phải cúi đầu (俯首) kính lễ. | Gương Hán-Việt | phủ trong ''phủ thị'', ''phủ ngưỡng'' | Mở khoá kiến thức | Biết 俯 (phủ) mở khoá: 俯仰 (nhìn lên cúi xuống), 俯首 (cúi đầu), 俯视 (nhìn từ trên xuống).", "Tự nguyên_Xie": "Kim văn | Tiểu triện | Theo Wiktionary, trong các minh văn đồng (bronze inscriptions), 俯 là chữ hình thanh: 府 cho âm (biểu âm), 勹 (người đang cúi gập người) cho nghĩa (biểu nghĩa). Về sau chữ viết hiện đại thay 勹 bằng 亻 (nhân). Nghĩa cốt lõi là cúi xuống, ở tư thế nhìn xuống. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "709.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Nhân (011) Phủ (708)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Nhân (số 011 - người) ở bên trái chữ Phủ (số 708 - phủ quan). Đến phủ quan (Phủ), người dân (Nhân) luôn phải cúi đầu nhìn xuống. Giải thích sự chuyển ý: Đây là chữ Hình thanh (hoặc Hội ý). Chữ Phủ (phủ quan) chỉ âm, bộ Nhân chỉ ý. Phủ là cúi xuống, cúi đầu (trái với ngưỡng).", "Nghĩa Tiếng Việt_Xie": "cúi xuống", "Hạng Tần Suất (Jun Da)": "2256.0", "Tần Suất % (Jun Da)": "97.9391802603", "GavinGrover_Once (Chiết tự trực tiếp)": "亻 + 府", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰亻府", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "府", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "亻", "Unihan_Simplified (Chữ Giản thể)": "俯", "Unihan_Traditional (Chữ Phồn thể)": "俯", "Pinyin_Xie": "fǔ", "Âm Hán Việt_Xie": "phủ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước các động từ khác để chỉ tư thế cúi đầu hoặc hướng từ trên xuống. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('厘', '{"9000": "2257.0", "Chữ Trung Quốc": "厘", "Bộ thủ & thành phần_Xie": "Bộ thủ | 厂 | Số nét | 9 | nét | 厂 | hán | biểu nghĩa | vách núi, bờ dốc | 里 | lý | biểu âm | trong, lý (đơn vị đo) | 厘 = 厂 (Hán, bộ vách núi) + 里 (Lý, biểu âm); chữ hình thanh rút gọn từ 釐. Bộ 厂 là yếu tố cấu trúc, 里 cho âm (lí ~ lý).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ly\": vách 厂 (hán) kết hợp lý 里 (lý) — đơn vị ly 厘 là phần nhỏ nhất trong đo lường, tinh vi như hẻm núi. | Gương Hán-Việt | ly trong ''ly (厘) mét'', ''phân ly'' | Mở khoá kiến thức | Biết 厘 (ly) mở khoá: 厘米 (xentimét), 毫厘 (rất nhỏ, từng ly từng tí).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 厘 là biến thể rút gọn của 釐, bỏ phần trên. Chữ 釐 vốn chỉ đơn vị đo lường nhỏ (1/100 của 分, tức 0.01 phân). Dùng rộng trong đơn vị đo độ dài (厘米 = centimét), tỷ lệ phần trăm (一厘 = 0,1%). Chữ tạo muộn, chưa thấy trong giáp cốt hay kim văn. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "li (đơn vị chiều dài); li (đơn vị trọng lượng); li (đơn vị đo diện tích); li (đơn vị tính lãi suất); Rin (đơn vị tiền tệ của Nhật Bản); chút xíu; ít ỏi; tí tẹo; rất nhỏ", "Hạng Tần Suất (Jun Da)": "2257.0", "Tần Suất % (Jun Da)": "97.9418137974", "GavinGrover_Once (Chiết tự trực tiếp)": "厂 + 里", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴厂里", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "里", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "厂", "Unihan_Simplified (Chữ Giản thể)": "厘", "Unihan_Traditional (Chữ Phồn thể)": "厘", "Pinyin_Xie": "lí", "Âm Hán Việt_Xie": "li", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Lượng từ | 量词 | Danh từ | 名词 | Thường làm lượng từ đứng sau số từ để chỉ đơn vị đo chiều dài, trọng lượng hoặc lãi suất rất nhỏ. | Lượng từ | 量词 | Đứng giữa số từ (hoặc 这/那) và danh từ: 一杯茶, 这本书. Mỗi danh từ đi với lượng từ riêng; 个 là lượng từ dùng chung phổ biến nhất. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('愣', '{"9000": "2258.0", "Chữ Trung Quốc": "愣", "Bộ thủ & thành phần_Xie": "Bộ thủ | 心 | Số nét | 12 | nét | 忄 | tâm | biểu nghĩa | tâm, tim, cảm xúc | 楞 | lăng | biểu âm | cạnh sắc, góc cạnh (dạng đầy đủ) | 愣 = 忄(Tâm, biểu nghĩa: tâm trí) + thành phần biểu âm phái sinh từ 楞 (Lăng); chữ hình thanh. Tâm trí (忄) bị ''cạnh'' (楞) làm cho đứng ngây — trạng thái sững sờ, ngẩn người.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lăng\": tâm trí (忄) như bị góc cạnh (楞 = lăng) đâm vào — sững lăng (愣) là ngẩn người vì bất ngờ. | Gương Hán-Việt | lăng trong ''ngây lăng'', ít dùng trong từ Hán-Việt thuần | Mở khoá kiến thức | Biết 愣 (lăng) mở khoá: 发愣 (ngây người), 愣住 (đứng sững), 愣神 (ngơ ngẩn).", "Tự nguyên_Xie": "Wiktionary ghi 愣 là chữ hình thanh (psc): 心/忄 (tâm) là thành phần biểu nghĩa chỉ trạng thái tâm lý, dạng rút gọn của 楞 là thành phần biểu âm. Nghĩa là trạng thái ngây người, sững sờ, đần độn — tâm trí như bị chặn lại. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ngây, ngơ ngẩn, sửng sốt; ngang ngạnh, bướng bỉnh, lỗ mãng", "Hạng Tần Suất (Jun Da)": "2258.0", "Tần Suất % (Jun Da)": "97.9444432001", "GavinGrover_Once (Chiết tự trực tiếp)": "忄 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰忄", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "愣", "Unihan_Traditional (Chữ Phồn thể)": "愣", "Pinyin_Xie": "lèng", "Âm Hán Việt_Xie": "lăng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Phó từ | 副词 | Thường làm động từ chỉ trạng thái ngây người ra hoặc làm phó từ đứng trước động từ để chỉ hành động liều lĩnh. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Phó từ | 副词 | Bổ nghĩa cho động từ hoặc tính từ và luôn đứng TRƯỚC chúng — 都是, 很好. Không đứng sau như tiếng Việt và không bổ nghĩa cho danh từ.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | lèng | / | sững sờ | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Cảm xúc và cảm giác Tôi | HSK | HSK 6 | · | Cảm xúc và tình cảm II", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('厦', '{"9000": "2259.0", "Chữ Trung Quốc": "厦", "Bộ thủ & thành phần_Xie": "Bộ thủ | 厂 | Số nét | 12 | nét | 厂 | hán | biểu nghĩa | vách núi, bờ dốc (nơi có mái che) | 夏 | hạ | biểu âm | mùa hạ, nhà lớn | 厦 = 厂 (Hán, biểu nghĩa: mái che/vách đá) + 夏 (Hạ, biểu âm kiêm biểu nghĩa: lớn/hùng vĩ); chữ hình thanh. Bộ 厂 cho nghĩa công trình có mái, 夏 cho âm (shà ~ hạ) và thêm nghĩa ''to lớn''.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hạ\": mái nhà rộng 厂 (hán) mùa hạ 夏 (hạ) — 厦 là tòa nhà cao lớn đồ sộ như cung điện mùa hạ. | Gương Hán-Việt | hạ trong ''大厦 đại hạ'' (tòa nhà lớn), ''厦门 Hạ Môn'' (thành phố Xiamen) | Mở khoá kiến thức | Biết 厦 (hạ) mở khoá: 大厦 (tòa nhà lớn), 厦门 (Hạ Môn/Xiamen), 高楼大厦 (cao ốc tòa nhà).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Theo Wiktionary, 厦 là chữ hình thanh (psc): 广 (quảng, biểu nghĩa: mái nhà rộng) + 夏 (hạ, biểu âm). Thành phần biểu âm 夏 cũng mang nghĩa ''lớn, hùng vĩ'' nên góp thêm vào nghĩa tổng thể. Nghĩa là tòa nhà lớn, lầu cao. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "từ gọi chung chỉ nhà ở", "Hạng Tần Suất (Jun Da)": "2259.0", "Tần Suất % (Jun Da)": "97.947070019", "GavinGrover_Once (Chiết tự trực tiếp)": "厂 + 夏", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴厂夏", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "夏", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "厂", "Unihan_Simplified (Chữ Giản thể)": "厦", "Unihan_Traditional (Chữ Phồn thể)": "廈", "Pinyin_Xie": "shà", "Âm Hán Việt_Xie": "hạ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng sau tên riêng hoặc từ chỉ tính chất để cấu tạo danh từ chỉ các tòa nhà lớn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('恳', '{"9000": "2260.0", "Chữ Trung Quốc": "恳", "Bộ thủ & thành phần_Xie": "Bộ thủ | 心 | Số nét | 10 | nét | 艮 | cấn | biểu hình (do giản hoá từ 貇) | phần trên giản từ 貇 | 心 | tâm | biểu nghĩa | tim | 恳 là dạng giản thể của 懇 — hình thanh: 貇 (biểu âm) + 心 (biểu nghĩa: tim). Trong giản thể, 貇 thu gọn thành 艮. Cấu trúc hình thanh giữ nguyên: tim chân thành tha thiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khẩn\": 艮 (giản từ 貇) trên 心 (tim) — lòng chân thành tha thiết, đúng nghĩa ''thành khẩn, khẩn cầu'' trong 诚恳, 恳切, 恳求. | Gương Hán-Việt | ''khẩn'' trong ''khẩn cầu'', ''thành khẩn'', ''khẩn thiết'' | Mở khoá kiến thức | Nắm 恳 mở khoá loạt từ HSK 5-7: 诚恳, 勤恳, 恳切, 恳求.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Theo Wiktionary, 恳 là giản thể của 懇 — hình thanh: 貇 (biểu âm) + 心 (tim, biểu nghĩa). Trong giản thể hiện đại, 貇 được rút gọn thành 艮. Nghĩa gốc ''chân thành, tha thiết, khẩn cầu'' trong 诚恳, 勤恳, 恳切, 恳求. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thành khẩn", "Hạng Tần Suất (Jun Da)": "2260.0", "Tần Suất % (Jun Da)": "97.9496958042", "GavinGrover_Once (Chiết tự trực tiếp)": "艮 + 心", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艮心", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "心", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艮", "Unihan_Simplified (Chữ Giản thể)": "恳", "Unihan_Traditional (Chữ Phồn thể)": "懇", "Pinyin_Xie": "kěn", "Âm Hán Việt_Xie": "khẩn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường làm tính từ bổ nghĩa cho động từ hoặc kết hợp tạo từ ghép chỉ thái độ thành khẩn. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('饶', '{"9000": "2261.0", "Chữ Trung Quốc": "饶", "Bộ thủ & thành phần_Xie": "Bộ thủ | 食 | Số nét | 9 | nét | 饣 | thực | biểu nghĩa | ăn uống, thức ăn | 尧 | nghiêu | biểu âm | vua Nghiêu (tên riêng) | 饶 = 饣(Thực, biểu nghĩa: thực phẩm, no đủ) + 尧 (Nghiêu, biểu âm); chữ hình thanh dạng giản thể của 饒. Gốc 飠 (ăn uống) chỉ sự phong phú, no đủ; 尧 cho âm gần ''ráo''.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nhiêu\": bộ ăn uống (饣) cùng vua Nghiêu (尧) — dưới triều vua Nghiêu no đủ, nhiêu nhặn (饶) — tha thứ, đủ đầy. | Gương Hán-Việt | nhiêu trong ''phong nhiêu'', ''nhiêu thứ'' (tha thứ) | Mở khoá kiến thức | Biết 饶 (nhiêu) mở khoá: 饶恕 (tha thứ), 丰饶 (phong phú), 饶有趣味 (thú vị).", "Tự nguyên_Xie": "Đại triện | Tiểu triện | 饶 là dạng giản thể của 饒, trong đó 飠 đơn giản hóa thành 饣 và 堯 đơn giản hóa thành 尧. Wiktionary ghi đây là chữ hình thanh: bộ thực 飠 biểu nghĩa (sự phong phú, giàu có về ăn uống), 堯 biểu âm. Nghĩa chính là phong phú, dồi dào; nghĩa phái sinh là tha thứ, buông tha. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nhiều, đầy đủ; khoan dung, tha thứ", "Hạng Tần Suất (Jun Da)": "2261.0", "Tần Suất % (Jun Da)": "97.9523205559", "GavinGrover_Once (Chiết tự trực tiếp)": "饣 + 尧", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰饣尧", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "尧", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "饣", "Unihan_Simplified (Chữ Giản thể)": "饶", "Unihan_Traditional (Chữ Phồn thể)": "饒", "Pinyin_Xie": "ráo", "Âm Hán Việt_Xie": "nhiêu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Thường làm động từ mang tân ngữ với nghĩa tha thứ, hoặc làm tính từ chỉ sự giàu có, dư dật. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | ráo | / | tha thứ | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Thái độ với người khác III", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('钉', '{"9000": "2262.0", "Chữ Trung Quốc": "钉", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 7 | nét | 钅 | kim | biểu nghĩa | kim loại | 丁 | đinh | biểu âm | đinh, người đàn ông | 钉 = 钅(Kim, biểu nghĩa: kim loại) + 丁 (Đinh, biểu âm); chữ hình thanh dạng giản thể của 釘. 丁 vừa cho âm ''dīng'' vừa gợi hình chiếc đinh — vật kim loại nhỏ hình chữ T.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đinh\": bộ kim (钅) + chữ Đinh (丁) — 丁 trông như đầu đinh nhìn từ trên, kim loại (钅) tạo nên cái đinh (钉). | Gương Hán-Việt | đinh trong ''đinh ninh'', ''đinh thần'' | Mở khoá kiến thức | Biết 钉 (đinh) mở khoá: 钉子 (cái đinh), 螺丝钉 (ốc vít), 碰钉子 (bị từ chối), 斩钉截铁 (dứt khoát).", "Tự nguyên_Xie": "Kim văn | Tiểu triện | 钉 là dạng giản thể của 釘, trong đó bộ 釒 đơn giản hóa thành 钅. Wiktionary ghi 钉 đơn giản là dạng viết tắt, tra về 釘 để thấy gốc. Cấu trúc hình thanh: 金/钅 (kim loại) biểu nghĩa, 丁 biểu âm. Thú vị là 丁 trông giống hình chiếc đinh từ trên nhìn xuống, tạo nên hội ý bổ trợ. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái đinh", "Hạng Tần Suất (Jun Da)": "2262.0", "Tần Suất % (Jun Da)": "97.9549349719", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 丁", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅丁", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "丁", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "钉", "Unihan_Traditional (Chữ Phồn thể)": "釘", "Pinyin_Xie": "dīng", "Âm Hán Việt_Xie": "đính, đinh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ vật thể bằng kim loại hoặc gỗ dùng để đóng, găm giữ đồ vật. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | dìng | / | đóng đinh | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Words II", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('寡', '{"9000": "2263.0", "Chữ Trung Quốc": "寡", "Bộ thủ & thành phần_Xie": "Bộ thủ | 宀 | Số nét | 14 | nét | 宀 | miên | biểu nghĩa | mái nhà, nhà | 頁 | hiệt | biểu nghĩa | đầu người (dạng cổ) | 寡 là chữ hội ý: trong kim văn thời Tây Chu, chữ gốc gồm 宀 (mái nhà) + 頁 (đầu người) — một người một mình trong căn nhà. Sau đó thêm nét trang trí quanh 頁, dẫn đến dạng hiện tại với 分 ở dưới. Không phải hình thanh mà là hội ý thực sự.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quả\": 宀 (mái nhà) với một cái đầu 頁 bên trong — người đàn bà quả phụ ở một mình trong căn nhà trống. | Gương Hán-Việt | quả phụ (góa phụ), quả nhân (người cô đơn — vua tự xưng) | Mở khoá kiến thức | Biết 寡 mở khoá: quả phụ (寡妇 — góa phụ), cô quả (孤寡 — cô đơn), quả văn (寡闻 — ít nghe biết).", "Tự nguyên_Xie": "Trong kim văn thời Tây Chu, 寡 ban đầu gồm 宀 (mái nhà) + 頁 (đầu người) — chỉ cảnh một người đơn độc trong nhà. Về sau nét trang trí được thêm quanh 頁 trong kim văn thời Chiến Quốc. Wiktionary xác nhận đây là hội ý (ls=ic): ''only one person in the house; alone''. Nghĩa gốc là ít, thiếu, cô đơn; mở rộng sang nghĩa góa phụ. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ít; suông, nhạt nhẽo; goá chồng, quả phụ", "Hạng Tần Suất (Jun Da)": "2263.0", "Tần Suất % (Jun Da)": "97.9575442201", "GavinGrover_Once (Chiết tự trực tiếp)": "宀 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱宀", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "寡", "Unihan_Traditional (Chữ Phồn thể)": "寡", "Pinyin_Xie": "guǎ", "Âm Hán Việt_Xie": "quả", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Thường làm tính từ bổ nghĩa cho danh từ để chỉ sự ít ỏi, đơn độc hoặc làm danh từ chỉ người phụ nữ góa chồng. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('憾', '{"9000": "2264.0", "Chữ Trung Quốc": "憾", "Bộ thủ & thành phần_Xie": "Bộ thủ | 心 | Số nét | 16 | nét | 忄 | tâm | biểu nghĩa | lòng, tâm trạng | 感 | cảm | biểu âm | cảm xúc, cảm nhận | 憾 = 忄 (Tâm, biểu nghĩa: lòng/cảm xúc) + 感 (Cảm, biểu âm); chữ hình thanh. Bộ 忄 cho nghĩa cảm xúc trong lòng, 感 cho âm (hàn ~ hám).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hám\": lòng 忄 (tâm) cảm 感 (cảm) mà không trọn — 憾 là tiếc nuối, điều còn hám hở trong tâm. | Gương Hán-Việt | hám trong ''di hám'' (nỗi tiếc để lại), 遗憾 (tiếc nuối) | Mở khoá kiến thức | Biết 憾 (hám) mở khoá: 遗憾 (tiếc nuối, đáng tiếc), 憾事 (chuyện đáng tiếc), 抱憾 (ôm nỗi tiếc).", "Tự nguyên_Xie": "Theo Wiktionary, 憾 là chữ hình thanh (psc): 心 (tâm, biểu nghĩa: lòng) + 感 (cảm, biểu âm). Nghĩa là tiếc nuối, hối hận — nỗi cảm xúc trong lòng về điều đã qua không thể thay đổi. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ăn năn, hối hận", "Hạng Tần Suất (Jun Da)": "2264.0", "Tần Suất % (Jun Da)": "97.96014675", "GavinGrover_Once (Chiết tự trực tiếp)": "忄 + 感", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰忄感", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "感", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "忄", "Unihan_Simplified (Chữ Giản thể)": "憾", "Unihan_Traditional (Chữ Phồn thể)": "憾", "Pinyin_Xie": "hàn", "Âm Hán Việt_Xie": "hám", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này thường làm danh từ trong các từ ghép chỉ sự nuối tiếc hoặc làm động từ trong văn viết cổ phong. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('摔', '{"9000": "2265.0", "Chữ Trung Quốc": "摔", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 14 | nét | 扌 | thủ | biểu nghĩa | tay | 率 | luật | biểu âm | tỷ lệ, dẫn đầu | 摔 = 扌 (Thủ, biểu nghĩa: tay) + 率 (Luật, biểu âm); chữ hình thanh. Bộ 扌 cho nghĩa hành động tay (ném mạnh, ngã), 率 cho âm (shuāi ~ suất).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"suất\": tay 扌 (thủ) suất 率 (luật) mạnh xuống — 摔 là ngã đập mạnh xuống đất. | Gương Hán-Việt | suất trong ''suất đảo'' (ngã xuống) | Mở khoá kiến thức | Biết 摔 (suất) mở khoá: 摔倒 (ngã), 摔跤 (đấu vật/ngã), 摔碎 (làm vỡ khi rơi).", "Tự nguyên_Xie": "Theo Wiktionary, 摔 là chữ hình thanh (psc): 手 (thủ, biểu nghĩa: tay) + 率 (luật, biểu âm). Nghĩa gốc là dùng tay ném mạnh xuống, sau mở rộng sang ''ngã'' và ''摔跤'' (đấu vật — vật nhau xuống đất). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1861.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thủ (064) Suất (095)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Thủ (số 064 - cái tay/ 扌/chỉ ý) ở bên trái chữ Suất (số 095 - noi theo/thống soái/ 率 /chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Suất chỉ âm, bộ Thủ chỉ ý. Suất là hành động dùng tay quẳng đồ vật, vứt bỏ đi (suất toái - ném vỡ). Nó cũng mang nghĩa là té ngã gục xuống (suất đảo).", "Nghĩa Tiếng Việt_Xie": "vứt xuống đất, quẳng đi", "Hạng Tần Suất (Jun Da)": "2265.0", "Tần Suất % (Jun Da)": "97.9627487632", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 率", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌率", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "率", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "摔", "Unihan_Traditional (Chữ Phồn thể)": "摔", "Pinyin_Xie": "shuāi", "Âm Hán Việt_Xie": "suất", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước tân ngữ chỉ đồ vật bị ném hoặc đứng độc lập để chỉ hành động ngã, rơi. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | Từ đơn | Từ vựng HSK 5: ngã | / | shuāi | / | ngã | Xuất hiện trong lộ trình | New HSK | New HSK 5 | · | Động từ | HSK | HSK 5 | · | Động từ hàng ngày", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('叠', '{"9000": "2266.0", "Chữ Trung Quốc": "叠", "Bộ thủ & thành phần_Xie": "Bộ thủ | 又 | Số nét | 13 | nét | 叒 | nhược | biểu hình | cây mọc chồng (hình ảnh cổ) | 冝 | biểu hình | bộ phận thêm vào | 叠 là dạng giản thể của 疊. Gốc 疊 gồm ba chữ 田 (ruộng) xếp chồng lên nhau, biểu thị ý nghĩa ''chồng lớp''. Trong chữ giản thể, cấu trúc được đơn giản hóa. Chữ hội ý: hình ảnh các lớp xếp chồng lên nhau.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"điệp\": điệp khúc, điệp lại — chữ 叠 như hình các lớp xếp điệp nhau, lặp đi lặp lại. | Gương Hán-Việt | điệp trong ''trùng điệp'', ''điệp khúc'', ''điệp tự'' | Mở khoá kiến thức | Biết 叠 (điệp) mở khoá: 重叠 (trùng điệp), 折叠 (gấp lại), 叠加 (chồng thêm), 叠字 (từ láy).", "Tự nguyên_Xie": "Giáp cốt văn | Kim văn | Tiểu triện | 叠 là dạng giản thể của 疊, trong đó bộ 畾 (ba chữ 田 xếp chồng) thay bằng 叒. Wiktionary ghi đây là dạng rút gọn, tra về 疊 để thấy gốc. Chữ 疊 là hội ý: nhiều lớp 田 (ruộng) xếp chồng — biểu thị sự chồng điệp. Nghĩa gốc là xếp chồng, chập lại. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chồng chất", "Hạng Tần Suất (Jun Da)": "2266.0", "Tần Suất % (Jun Da)": "97.9653466421", "GavinGrover_Once (Chiết tự trực tiếp)": "叒 + 冝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱叒冝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "冝", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "叒", "Unihan_Simplified (Chữ Giản thể)": "叠", "Unihan_Traditional (Chữ Phồn thể)": "曡", "Pinyin_Xie": "dié", "Âm Hán Việt_Xie": "điệp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Lượng từ | 量词 | Thường làm động từ chỉ hành động gấp quần áo hoặc làm lượng từ cho các vật được xếp chồng lên nhau. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Lượng từ | 量词 | Đứng giữa số từ (hoặc 这/那) và danh từ: 一杯茶, 这本书. Mỗi danh từ đi với lượng từ riêng; 个 là lượng từ dùng chung phổ biến nhất.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | dié | / | chồng | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Từ chức năng và phụ từ I", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('惹', '{"9000": "2267.0", "Chữ Trung Quốc": "惹", "Bộ thủ & thành phần_Xie": "Bộ thủ | 心 | Số nét | 12 | nét | 若 | nhược | biểu âm | như, tựa như; nếu | 心 | tâm | biểu nghĩa | tim, cảm xúc | 惹 = 若 (Nhược, trên) + 心 (Tâm, dưới); cấu trúc hình thanh: 若 có thể cho âm gần ''rě'', 心 biểu nghĩa trạng thái tâm lý — sự kích động, gây bực dọc trong tâm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nhạ\": tâm (心) bị ''nhược'' (若) gây ra — khi ai đó 惹 (kích động) ta, cái tâm rung chuyển như bị chạm. | Gương Hán-Việt | nhạ ít dùng trong từ Hán-Việt phổ biến | Mở khoá kiến thức | Biết 惹 (nhạ) mở khoá: 惹祸 (gây họa), 惹麻烦 (gây rắc rối), 招惹 (chọc ghẹo, gây ra).", "Tự nguyên_Xie": "Kim văn | Tiểu triện | Wiktionary ghi glyphOrigin rất vắn tắt ({{Han etyl}}). Cấu trúc 若 + 心: 若 (nhược) ở trên, 心 (tâm) ở dưới. Nhiều khả năng là chữ hình thanh với 心 biểu nghĩa và 若 biểu âm. Nghĩa là khơi dậy cảm xúc tiêu cực, gây ra rắc rối, kích thích. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "383.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Tâm (148) Nhược (253)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Nhược (số 253 - nếu như) ở trên chữ Tâm (số 148) . Nhạ là gây ra sự việc gì đó, trêu chọc, gây sự. Giải thích sự chuyển ý: Chữ Nhược (nếu như) chỉ âm, chữ Tâm (lòng) chỉ ý. Lòng (Tâm) sinh ra ý muốn trêu ghẹo, chọc phá người khác gọi là nhạ. *(Biến âm Hán Việt: Nhược -> Nhạ)*", "Nghĩa Tiếng Việt_Xie": "xảy ra, sinh chuyện; chọc vào, dây vào; khiến cho, làm cho", "Hạng Tần Suất (Jun Da)": "2267.0", "Tần Suất % (Jun Da)": "97.9679398699", "GavinGrover_Once (Chiết tự trực tiếp)": "若 + 心", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱若心", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "若", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "心", "Unihan_Simplified (Chữ Giản thể)": "惹", "Unihan_Traditional (Chữ Phồn thể)": "惹", "Pinyin_Xie": "rě", "Âm Hán Việt_Xie": "nhạ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước tân ngữ để chỉ việc gây ra rắc rối hoặc trêu chọc ai đó. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | rě | / | khiêu khích | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Ảnh hưởng và Kiểm soát II", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('喻', '{"9000": "2268.0", "Chữ Trung Quốc": "喻", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 12 | nét | 口 | khẩu | biểu nghĩa | miệng, lời nói | 俞 | du | biểu âm | vui lòng, ưng thuận | 喻 = 口 (Khẩu, biểu nghĩa: miệng/lời nói) + 俞 (Du, biểu âm); chữ hình thanh. 俞 cho âm ''yù'', bộ 口 chỉ hành động diễn đạt bằng lời — dùng lời so sánh, ẩn dụ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"dụ\": miệng (口) dùng lời du dương (俞) — khi dụ dỗ hay ẩn dụ (喻) đều cần lời khéo léo. | Gương Hán-Việt | dụ trong ''ẩn dụ'', ''tỷ dụ'', ''giáo dụ'' | Mở khoá kiến thức | Biết 喻 (dụ) mở khoá: 比喻 (phép so sánh/ẩn dụ), 家喻户晓 (nổi tiếng khắp nơi), 隐喻 (ẩn dụ).", "Tự nguyên_Xie": "Theo Wiktionary, 喻 là chữ hình thanh (psc): 口 (miệng) là thành phần biểu nghĩa, 俞 là thành phần biểu âm. Nghĩa là dùng lời so sánh để giải thích (ẩn dụ, tỷ dụ), hoặc hiểu ra, giác ngộ. Chữ dùng nhiều trong văn học cổ điển với nghĩa ''thuyết phục bằng ẩn dụ''. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nói rõ; hiểu rõ; thí dụ, ví dụ; họ Dụ", "Hạng Tần Suất (Jun Da)": "2268.0", "Tần Suất % (Jun Da)": "97.970529997", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 俞", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口俞", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "俞", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "喻", "Unihan_Traditional (Chữ Phồn thể)": "喻", "Pinyin_Xie": "yù", "Âm Hán Việt_Xie": "dụ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường làm động từ trong các từ ghép chỉ sự thấu hiểu, so sánh hoặc làm danh từ chỉ dụ ngôn, ví dụ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('谱', '{"9000": "2269.0", "Chữ Trung Quốc": "谱", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 14 | nét | 讠 | biểu nghĩa | lời nói, văn tự (bộ ngôn giản thể) | 普 | phổ | biểu âm | phổ biến, rộng rãi | 谱 = 讠(Ngôn giản thể, biểu nghĩa: lời nói, văn tự) + 普 (Phổ, biểu âm); chữ hình thanh dạng giản thể của 譜. 普 cho âm ''pǔ'', bộ 言/讠chỉ văn tự được ghi chép — bản ghi chép phổ biến như phả hệ, bản nhạc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phả\": lời viết (讠) phổ biến (普) — gia phả (谱) là bản ghi phổ biến rộng về dòng họ; nhạc phổ ghi lại âm nhạc. | Gương Hán-Việt | phả trong ''gia phả'', ''nhạc phả'', ''phả hệ'' | Mở khoá kiến thức | Biết 谱 (phả) mở khoá: 乐谱 (bản nhạc), 家谱 (gia phả), 年谱 (niên phả), 离谱 (vô lý, quá mức).", "Tự nguyên_Xie": "Tiểu triện | 谱 là dạng giản thể của 譜, trong đó 言 đơn giản hóa thành 讠. Wiktionary ghi đây là dạng rút gọn, tra về 譜 để thấy gốc. Cấu trúc hình thanh: 言 (ngôn, lời nói/văn tự) biểu nghĩa, 普 biểu âm. Nghĩa gốc là bảng ghi có hệ thống — phổ hệ (gia phả), nhạc phổ. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "phả chép phân chia thứ tự; khúc nhạc", "Hạng Tần Suất (Jun Da)": "2269.0", "Tần Suất % (Jun Da)": "97.9731185737", "GavinGrover_Once (Chiết tự trực tiếp)": "讠 + 普", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰讠普", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "普", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "讠", "Unihan_Simplified (Chữ Giản thể)": "谱", "Unihan_Traditional (Chữ Phồn thể)": "譜", "Pinyin_Xie": "pǔ", "Âm Hán Việt_Xie": "phổ, phả", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường làm danh từ chỉ các loại sách ghi chép, nhạc phổ hoặc làm động từ với nghĩa phổ nhạc, soạn nhạc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | pǔ | / | biểu đồ | / | pǔ | / | nốt nhạc | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Gọi món | New HSK 7-9 | · | Nghệ thuật và Văn học II", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('愧', '{"9000": "2270.0", "Chữ Trung Quốc": "愧", "Bộ thủ & thành phần_Xie": "Bộ thủ | 心 | Số nét | 12 | nét | 忄 | tâm | biểu nghĩa | lòng, tâm trạng | 鬼 | quỷ | biểu âm | ma quỷ, hồn ma | 愧 = 忄 (Tâm, biểu nghĩa: lòng) + 鬼 (Quỷ, biểu âm kiêm biểu nghĩa); chữ hình thanh. Theo Wiktionary, Thuyết Văn giải nghĩa đây là hội ý: 恥 (xấu hổ) + 鬼 (quỷ/hồn). Bộ 忄 là lòng xấu hổ, 鬼 cho âm (kuì ~ quỷ).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quý\": lòng 忄 (tâm) thấy quỷ 鬼 (quỷ) — trái tim xấu hổ đến mức như nhìn thấy ma quỷ, đó là 愧 hổ thẹn. | Gương Hán-Việt | quý trong ''tàm quý'' (xấu hổ, hổ thẹn), ''bất quý'' (xứng đáng) | Mở khoá kiến thức | Biết 愧 (quý) mở khoá: 惭愧 (xấu hổ, hổ thẹn), 不愧 (xứng đáng, không hổ thẹn), 羞愧 (xấu hổ).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Theo Wiktionary, 愧 ban đầu viết là 媿. Dạng hiện đại là chữ hình thanh (psc): 心 (tâm, biểu nghĩa: lòng) + 鬼 (quỷ, biểu âm). Thuyết Văn giải nghĩa theo hội ý: lòng xấu hổ như gặp ma quỷ. Nghĩa là xấu hổ, hổ thẹn. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "hổ thẹn, xấu hổ", "Hạng Tần Suất (Jun Da)": "2270.0", "Tần Suất % (Jun Da)": "97.9757066336", "GavinGrover_Once (Chiết tự trực tiếp)": "忄 + 鬼", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰忄鬼", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "鬼", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "忄", "Unihan_Simplified (Chữ Giản thể)": "愧", "Unihan_Traditional (Chữ Phồn thể)": "媿", "Pinyin_Xie": "kuì", "Âm Hán Việt_Xie": "quý", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường làm tính từ biểu thị tâm trạng xấu hổ hoặc làm động từ trong cấu trúc cảm thấy hổ thẹn vì điều gì. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('煌', '{"9000": "2271.0", "Chữ Trung Quốc": "煌", "Bộ thủ & thành phần_Xie": "Bộ thủ | 火 | Số nét | 13 | nét | 火 | hoả | biểu nghĩa | lửa, ánh sáng | 皇 | hoàng | biểu âm | hoàng đế, tráng lệ | 煌 = 火 (Hoả, biểu nghĩa: lửa/ánh sáng) + 皇 (Hoàng, biểu âm); chữ hình thanh. 皇 cho âm ''huáng'', bộ 火 chỉ bản chất ánh sáng rực rỡ — ngọn lửa huy hoàng như ánh sáng hoàng đế.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hoàng\": lửa (火) của hoàng đế (皇) — ánh sáng hoàng đế rực rỡ, hoàng hoàng (煌) huy hoàng. | Gương Hán-Việt | hoàng trong ''huy hoàng'', ''hoàng hoàng'' | Mở khoá kiến thức | Biết 煌 (hoàng) mở khoá: 辉煌 (huy hoàng), 灿烂辉煌 (rực rỡ huy hoàng).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 煌 là chữ hình thanh (psc): 火 (lửa) là thành phần biểu nghĩa, 皇 là thành phần biểu âm. Nghĩa là rực rỡ, sáng lóa. Thường dùng trong từ 辉煌 (huy hoàng) hoặc 灯火辉煌 (đèn lửa rực rỡ). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sáng sủa", "Hạng Tần Suất (Jun Da)": "2271.0", "Tần Suất % (Jun Da)": "97.9782915929", "GavinGrover_Once (Chiết tự trực tiếp)": "火 + 皇", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰火皇", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "皇", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "火", "Unihan_Simplified (Chữ Giản thể)": "煌", "Unihan_Traditional (Chữ Phồn thể)": "煌", "Pinyin_Xie": "huáng", "Âm Hán Việt_Xie": "hoàng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường làm tính từ bổ nghĩa cho danh từ hoặc kết hợp thành từ ghép để miêu tả sự huy hoàng, sáng lạng. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('徽', '{"9000": "2272.0", "Chữ Trung Quốc": "徽", "Bộ thủ & thành phần_Xie": "Bộ thủ | 彳 | Số nét | 17 | nét | 彳 | xích | biểu nghĩa | bước đi, hành động | 糸 | mịch | biểu nghĩa | sợi tơ, dây | 攵 | phộc | biểu ý | tay cầm gậy, hành động | 徽 = 彳 (Xích, bước đi) + 微 (vi, rút gọn, biểu âm) + 糸 (Mịch, sợi tơ); chữ hình thanh. Wiktionary ghi 微 + 糸 (c1=p, c2=s, ls=psc) — 微 biểu âm (rút gọn), 糸 biểu nghĩa ''vải, dây''. Gốc nghĩa là dây buộc, sau là huy hiệu, biểu trưng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"huy\": bộ 糸 (sợi tơ, dây) kết hợp 彳 và 攵 — huy hiệu như sợi dây danh dự buộc chặt danh tiếng một người. | Gương Hán-Việt | quốc huy (biểu trưng quốc gia), huy hiệu | Mở khoá kiến thức | Biết 徽 mở khoá: quốc huy (国徽), Huy Châu (徽州 — vùng An Huy cổ), Huy kịch (徽剧 — tuồng An Huy).", "Tự nguyên_Xie": "徽 là chữ hình thanh: phần 微 (rút gọn) biểu âm, bộ 糸 (mịch, sợi tơ) biểu nghĩa. Wiktionary xác nhận ls=psc, 微|糸 (c1=p, c2=s). Gốc nghĩa là sợi dây buộc, sau mở rộng sang nghĩa dây đàn, biểu trưng, huy hiệu. 安徽省 (tỉnh An Huy) lấy tên từ đây. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "hay, tốt; phím đàn", "Hạng Tần Suất (Jun Da)": "2272.0", "Tần Suất % (Jun Da)": "97.9808755186", "GavinGrover_Once (Chiết tự trực tiếp)": "彳 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰彳", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "徽", "Unihan_Traditional (Chữ Phồn thể)": "幑", "Pinyin_Xie": "huī", "Âm Hán Việt_Xie": "huy", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng một mình hoặc ghép với từ khác để chỉ các loại huy hiệu, biểu trưng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('溶', '{"9000": "2273.0", "Chữ Trung Quốc": "溶", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 13 | nét | 氵 | thuỷ | biểu nghĩa | nước, chất lỏng | 容 | dung | biểu âm | chứa đựng, vẻ mặt | 溶 = 氵(Thuỷ, biểu nghĩa: nước) + 容 (Dung, biểu âm); chữ hình thanh. 容 cho âm ''róng'', bộ 氵chỉ môi trường — nước (氵) chứa đựng (容) chất khác → hoà tan.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"dung\": nước (氵) dung chứa (容) chất khác — khi muối tan vào nước, đó là sự dung hoà (溶). | Gương Hán-Việt | dung trong ''dung dịch'', ''dung giải'', ''hoà dung'' | Mở khoá kiến thức | Biết 溶 (dung) mở khoá: 溶解 (hoà tan), 溶液 (dung dịch), 溶化 (tan chảy).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 溶 là chữ hình thanh (psc): 氵/水 (nước) là thành phần biểu nghĩa, 容 là thành phần biểu âm. Nghĩa là hoà tan trong nước, dung giải. Thường dùng trong hoá học: 溶解 (hoà tan), 溶液 (dung dịch). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "418.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thủy (306) Dung (322)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Thủy (số 76) và chữ Dung (số 132 - bao dung) . Dùng nước (Thủy) để chứa đựng, bao dung (Dung) làm tan chảy vật khác gọi là hòa tan. Giải thích sự chuyển ý: Chữ Dung (bao dung) chỉ âm, chữ Thủy (nước) chỉ ý. Chất lỏng (Thủy) có thể hòa tan chứa đựng chất khác (Dung).", "Nghĩa Tiếng Việt_Xie": "hoà tan; tan", "Hạng Tần Suất (Jun Da)": "2273.0", "Tần Suất % (Jun Da)": "97.9834584107", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 容", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵容", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "容", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "溶", "Unihan_Traditional (Chữ Phồn thể)": "溶", "Pinyin_Xie": "róng", "Âm Hán Việt_Xie": "dung", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ chỉ quá trình chất rắn hòa tan vào chất lỏng, thường đi kèm bổ ngữ kết quả. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('坠', '{"9000": "2274.0", "Chữ Trung Quốc": "坠", "Bộ thủ & thành phần_Xie": "Bộ thủ | 土 | Số nét | 7 | nét | 队 | đội | biểu âm | đội, nhóm; rơi xuống (gốc 隊) | 土 | thổ | biểu nghĩa | đất | 坠 = 队 (Đội, biểu âm) + 土 (Thổ, biểu nghĩa: đất); chữ hình thanh dạng giản thể của 墜. 队 gốc là 隊 (rơi xuống, đội ngũ), cho âm ''zhuì''; 土 (đất) chỉ hướng rơi — rơi xuống đất.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"truỵ\": đất (土) nhận vật rơi (队) — truỵ lạc, rơi xuống (坠) là rơi xuống đất, sa ngã. | Gương Hán-Việt | truỵ trong ''truỵ lạc'', ''sa truỵ'' | Mở khoá kiến thức | Biết 坠 (truỵ) mở khoá: 下坠 (rơi xuống), 坠落 (rơi), 摇摇欲坠 (lung lay sắp đổ).", "Tự nguyên_Xie": "Kim văn | Tiểu triện | 坠 là dạng giản thể của 墜. Wiktionary ghi 坠 phái sinh từ 墜: 队/隊 biểu âm, 土 biểu nghĩa. Nghĩa gốc là rơi xuống, sa xuống đất. Thú vị là gốc 隊 cũng mang nghĩa rơi xuống (rơi vào vực) trước khi có nghĩa ''đội ngũ''. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "rơi; ngã xuống", "Hạng Tần Suất (Jun Da)": "2274.0", "Tần Suất % (Jun Da)": "97.9860320006", "GavinGrover_Once (Chiết tự trực tiếp)": "队 + 土", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱队土", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "队", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "土", "Unihan_Simplified (Chữ Giản thể)": "坠", "Unihan_Traditional (Chữ Phồn thể)": "墜", "Pinyin_Xie": "zhuì", "Âm Hán Việt_Xie": "truỵ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường làm động từ chỉ hành động rơi từ trên cao xuống hoặc làm danh từ chỉ vật trang sức treo rủ xuống. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | zhuì | / | rơi xuống | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Phong trào II", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('煞', '{"9000": "2275.0", "Chữ Trung Quốc": "煞", "Bộ thủ & thành phần_Xie": "Bộ thủ | 火 | Số nét | 13 | nét | 刍 | sô | biểu ý | cắt, gom cỏ | 攵 | phộc | biểu ý | tay cầm gậy, đánh | 灬 | hoả | biểu nghĩa | lửa | 煞 = 𭣦 (gồm 刍+攵, biểu ý: hành động mạnh) + 灬 (Hoả, biểu nghĩa: lửa/lực mạnh); chữ hội ý theo hình. Wiktionary không cung cấp lsCodes rõ ràng cho 煞. Gốc nghĩa là sát hại, tiêu diệt; 灬 nhấn mạnh sức mạnh tàn phá.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sát\": 灬 (lửa) bùng lên bên dưới tay đánh (攵) và cái liềm (刍) — sát khí hừng hực như lửa cháy, không gì cản được. | Gương Hán-Việt | sát khí (khí thế hung dữ), hung sát (hung thần) | Mở khoá kiến thức | Biết 煞 mở khoá: sát khí (煞气), hung sát (凶煞), phong sát (风煞 — trong phong thủy), 煞白 (trắng bệch vì sợ).", "Tự nguyên_Xie": "煞 không có nguồn phân tích rõ ràng từ Wiktionary (lsCodes rỗng). Dựa trên cấu trúc: phần trên 𭣦 (gồm 刍 — cắt gom + 攵 — đánh) gợi hành động tiêu diệt; bộ 灬 (hoả) ở dưới nhấn mạnh sức mạnh tàn phá như lửa. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn rõ ràng. Nghĩa gốc: giết, sát hại; nghĩa mở rộng: ác thần, hung thần; dùng như trợ từ tăng cấp (煞白 = trắng bệch). | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "giết chết", "Hạng Tần Suất (Jun Da)": "2275.0", "Tần Suất % (Jun Da)": "97.988599906", "GavinGrover_Once (Chiết tự trực tiếp)": "No glyph available + 灬", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱灬", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "煞", "Unihan_Traditional (Chữ Phồn thể)": "煞", "Pinyin_Xie": "shā", "Âm Hán Việt_Xie": "sát", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Phó từ | 副词 | Danh từ | 名词 | Thường làm động từ chỉ sự ngăn chặn, làm phó từ biểu thị mức độ cực kỳ hoặc làm danh từ chỉ hung thần. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Phó từ | 副词 | Bổ nghĩa cho động từ hoặc tính từ và luôn đứng TRƯỚC chúng — 都是, 很好. Không đứng sau như tiếng Việt và không bổ nghĩa cho danh từ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('巾', '{"9000": "2276.0", "Chữ Trung Quốc": "巾", "Bộ thủ & thành phần_Xie": "Bộ thủ | 巾 | Số nét | 3 | nét | 巾 | cân | tượng hình | vẽ một mảnh vải treo rủ xuống — cái khăn | 巾 là chữ tượng hình — vẽ một mảnh vải treo rủ xuống. Là bộ thủ độc lập, xuất hiện trong nhiều chữ liên quan đến vải vóc, khăn, cờ (布, 帽, 帆, 帝, 师, 带).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Cân\": vẽ một mảnh vải treo rủ xuống — đó là ''cân'', cái khăn. | Gương Hán-Việt | ''Cân'' trong ''mao cân'' (khăn lông), ''cân quắc'' (khăn đai — nữ giới), ''phục cân'' (đội khăn). | Mở khoá kiến thức | Biết 巾 mở khoá 毛巾 (mao cân, khăn mặt), 围巾 (vi cân, khăn quàng cổ), 餐巾 (khăn ăn).", "Tự nguyên_Xie": "Giáp cốt văn | Đại triện | Tiểu triện | Theo Wiktionary, 巾 là chữ tượng hình vẽ một mảnh vải treo rủ xuống — chính là cái khăn. Là bộ thủ độc lập, xuất hiện trong rất nhiều chữ liên quan tới vải vóc, khăn, cờ phướn: 布 (vải), 帽 (mũ), 帆 (buồm), 帝 (đế — có khăn áo), 师 (sư), 带 (đai). Nghĩa gốc ''cái khăn vải'', sau dùng cho khăn nói chung. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "225.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Chữ đơn thể / Nét căn bản", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Hình ảnh một tấm khăn (vải/lụa) đang treo rủ xuống trên chiếc mắc.", "Nghĩa Tiếng Việt_Xie": "cái khăn", "Hạng Tần Suất (Jun Da)": "2276.0", "Tần Suất % (Jun Da)": "97.9911667777", "GavinGrover_Once (Chiết tự trực tiếp)": "冂 + 丨", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "Ký hiệu: lock", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "冂丨", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "丨", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "冂", "Unihan_Simplified (Chữ Giản thể)": "巾", "Unihan_Traditional (Chữ Phồn thể)": "巾", "Pinyin_Xie": "jīn", "Âm Hán Việt_Xie": "cân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này thường làm danh từ chỉ các loại khăn hoặc vải lau và làm thành phần cấu tạo từ ghép. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('滥', '{"9000": "2277.0", "Chữ Trung Quốc": "滥", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 13 | nét | 氵 | thuỷ | biểu nghĩa | nước, chất lỏng | 监 | giam | biểu âm | giám sát, giam giữ | 滥 = 氵(Thuỷ, biểu nghĩa: nước) + 监 (Giam, biểu âm); chữ hình thanh dạng giản thể của 濫. 监 cho âm gần ''làn'', bộ 氵chỉ nước tràn bờ — nước không kiểm soát được, tràn lan.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lạm\": nước (氵) vượt kiểm soát (监 = giam) — lạm dụng (滥) là dùng vượt mức kiểm soát, như nước tràn bờ. | Gương Hán-Việt | lạm trong ''lạm dụng'', ''tràn lạm'', ''phiếm lạm'' | Mở khoá kiến thức | Biết 滥 (lạm) mở khoá: 泛滥 (tràn lan), 滥用 (lạm dụng), 滥竽充数 (chiếm chỗ không xứng đáng).", "Tự nguyên_Xie": "Tiểu triện | 滥 là dạng giản thể của 濫, trong đó 監 đơn giản hóa thành 监. Wiktionary ghi đây là dạng rút gọn, tra về 濫 để thấy gốc. Cấu trúc hình thanh: 水/氵 (nước) biểu nghĩa, 監 biểu âm. Nghĩa gốc là nước tràn bờ, mở rộng sang nghĩa lạm dụng, quá mức. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "giàn giụa; nước tràn, nước ngập; lạm, quá; phóng túng", "Hạng Tần Suất (Jun Da)": "2277.0", "Tần Suất % (Jun Da)": "97.9937320991", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 监", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵监", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "监", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "滥", "Unihan_Traditional (Chữ Phồn thể)": "濫", "Pinyin_Xie": "làn", "Âm Hán Việt_Xie": "lạm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Phó từ | 副词 | Động từ | 动词 | Chữ này thường làm tính từ hoặc phó từ đứng trước động từ để chỉ hành vi quá giới hạn hoặc bừa bãi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Phó từ | 副词 | Bổ nghĩa cho động từ hoặc tính từ và luôn đứng TRƯỚC chúng — 都是, 很好. Không đứng sau như tiếng Việt và không bổ nghĩa cho danh từ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('洒', '{"9000": "2278.0", "Chữ Trung Quốc": "洒", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 9 | nét | 氵 | thuỷ | biểu nghĩa | nước | 西 | tây | biểu âm | phương Tây (gần âm sǎ) | 洒 = 氵 (Thuỷ, biểu nghĩa: nước) + 西 (Tây, biểu âm); chữ hình thanh. Tưới, rảy nước, gốc nghĩa ''rảy nước, vẩy, phun''.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sái\": 氵 (nước) + 西 (Tây) — rảy nước theo gió tây, đúng nghĩa ''rảy, phun, thoải mái'' trong 洒, 潇洒. | Gương Hán-Việt | ''sái'' trong ''tiêu sái'' (thoải mái), ''sái nước'' | Mở khoá kiến thức | Nắm 洒 mở khoá từ HSK 5-7: 洒, 潇洒.", "Tự nguyên_Xie": "Giáp cốt văn | Tiểu triện | Lục thư thông | Theo Wiktionary, 洒 là hình thanh: 水/氵 (nước, biểu nghĩa) + 西 (Tây, biểu âm). Nghĩa gốc ''tưới, rảy nước, vẩy'' trong 洒水 (tưới nước), 洒泪 (rơi lệ). Mở rộng sang nghĩa ''thanh thoát, phóng khoáng'' trong 潇洒 (tiêu sái — phong thái thoải mái). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "rảy nước", "Hạng Tần Suất (Jun Da)": "2278.0", "Tần Suất % (Jun Da)": "97.9962958702", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 西", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵西", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "西", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "洒", "Unihan_Traditional (Chữ Phồn thể)": "灑", "Pinyin_Xie": "sǎ", "Âm Hán Việt_Xie": "sái", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này thường làm động từ đứng trước danh từ chỉ chất lỏng để biểu thị hành động phun, rắc hoặc làm đổ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | Từ đơn | Từ vựng HSK 5: tưới, rắc, phun | / | sǎ | / | tưới, rắc, phun | Xuất hiện trong lộ trình | New HSK | New HSK 5 | · | Thành phố và nông thôn | HSK | HSK 5 | · | Động từ hàng ngày", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('堵', '{"9000": "2279.0", "Chữ Trung Quốc": "堵", "Bộ thủ & thành phần_Xie": "Bộ thủ | 土 | Số nét | 11 | nét | 土 | thổ | biểu nghĩa | đất — bức tường đất | 者 | giả | biểu âm | gợi âm ''dǔ'' | 堵 = 土 (Thổ, đất) + 者 (Giả, biểu âm). Chữ hình thanh: bức tường đất chặn lối — nghĩa gốc ''tường'', mở rộng thành ''chặn, ngăn, kẹt''.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt ''Đổ'': dùng đất (土) đắp lên (者) làm tường ngăn — đó là ''đổ'', là chặn lối. | Gương Hán-Việt | ''Đổ'' trong đổ tắc (chặn nghẽn); cùng âm Hán-Việt với ''đổ'' (赌, đánh bạc). | Mở khoá kiến thức | Biết 堵 mở khóa 堵车 (đổ xa / kẹt xe), 堵塞 (đổ tắc / tắc nghẽn).", "Tự nguyên_Xie": "Kim văn | Tiểu triện | Lục thư thông | Theo Wiktionary, 堵 là chữ hình thanh: 土 biểu nghĩa, 者 biểu âm. Nghĩa gốc ''bức tường''; mở rộng thành ''chặn, ngăn, tắc, kẹt''. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tường ngăn; ngăn ngừa", "Hạng Tần Suất (Jun Da)": "2279.0", "Tần Suất % (Jun Da)": "97.9988591245", "GavinGrover_Once (Chiết tự trực tiếp)": "土 + 者", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰土者", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "者", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "土", "Unihan_Simplified (Chữ Giản thể)": "堵", "Unihan_Traditional (Chữ Phồn thể)": "堵", "Pinyin_Xie": "dǔ", "Âm Hán Việt_Xie": "đổ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Lượng từ | 量词 | Danh từ | 名词 | Chữ này thường làm động từ chỉ sự tắc nghẽn hoặc làm lượng từ cho các bức tường. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Lượng từ | 量词 | Đứng giữa số từ (hoặc 这/那) và danh từ: 一杯茶, 这本书. Mỗi danh từ đi với lượng từ riêng; 个 là lượng từ dùng chung phổ biến nhất. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | dǔ | / | chặn lại | Xuất hiện trong lộ trình | New HSK | New HSK 4 | · | Vận chuyển", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('瓷', '{"9000": "2280.0", "Chữ Trung Quốc": "瓷", "Bộ thủ & thành phần_Xie": "Bộ thủ | 瓦 | Số nét | 10 | nét | 次 | thứ | biểu âm | thứ tự, lần sau | 瓦 | ngoã | biểu nghĩa | gạch, ngói, đồ đất nung | 瓷 = 次 (Thứ, biểu âm) + 瓦 (Ngoã, biểu nghĩa: đồ đất nung); chữ hình thanh. 次 cho âm ''cí'', bộ 瓦 chỉ chất liệu — loại đồ đất nung tinh xảo hơn, tức đồ sứ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"từ\": đất (瓦) nung theo thứ (次) tự đặc biệt — sứ (瓷) là loại gốm cao cấp nhất, tượng trưng cho văn minh Trung Hoa. | Gương Hán-Việt | từ trong ''đồ từ'', ''sứ từ'', ''đào từ'' | Mở khoá kiến thức | Biết 瓷 (từ) mở khoá: 陶瓷 (gốm sứ), 瓷器 (đồ sứ), 瓷砖 (gạch men).", "Tự nguyên_Xie": "Đại triện | Tiểu triện | Theo Wiktionary, 瓷 là chữ hình thanh (psc): 瓦 (gạch ngói, đồ đất nung) là thành phần biểu nghĩa chỉ chất liệu, 次 là thành phần biểu âm. Nghĩa là đồ sứ (porcelain/china). Đây là phát minh đặc trưng của Trung Quốc, nên tiếng Anh gọi là ''china''. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đồ sứ", "Hạng Tần Suất (Jun Da)": "2280.0", "Tần Suất % (Jun Da)": "98.0014197948", "GavinGrover_Once (Chiết tự trực tiếp)": "次 + 瓦", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱次瓦", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "次", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "瓦", "Unihan_Simplified (Chữ Giản thể)": "瓷", "Unihan_Traditional (Chữ Phồn thể)": "瓷", "Pinyin_Xie": "cí", "Âm Hán Việt_Xie": "từ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này thường làm danh từ đứng độc lập hoặc kết hợp với các danh từ khác để chỉ đồ vật làm bằng sứ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | cí | / | sứ | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Ngôi nhà và cuộc sống hàng ngày II", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('咒', '{"9000": "2281.0", "Chữ Trung Quốc": "咒", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 8 | nét | 吅 | tụng | biểu nghĩa | hai miệng, la hét | 几 | cơ | biểu ý | cái bàn nhỏ, dựa xuống | 咒 = 吅 (Tụng, hai miệng la hét) + 几 (Cơ, bàn nhỏ/cúi xuống); chữ hội ý. Hình ảnh hai miệng đồng loạt cất tiếng trong tư thế cúi xuống — gợi nghi thức đọc lời nguyền, chú thuật. Chữ gốc viết là 呪, xem thêm ở đó.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chú\": 吅 (hai miệng đồng thanh) cúi trên 几 (bàn thờ) — hai người cùng lẩm nhẩm câu chú trước bàn thờ. | Gương Hán-Việt | thần chú (câu niệm có phép), nguyền chú | Mở khoá kiến thức | Biết 咒 mở khoá: thần chú (咒语), nguyền rủa (诅咒), niệm chú (念咒).", "Tự nguyên_Xie": "咒 gốc viết là 呪. Wiktionary ghi ''Originally written 呪''. Cấu trúc 吅 (hai miệng, tiếng la hét đồng thanh) + 几 (cái bàn, tư thế cúi lạy) gợi cảnh người ta cùng nhau đọc to lời chú trong nghi lễ. Nghĩa gốc: lời nguyền, câu thần chú; động từ: nguyền rủa, niệm chú. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nguyền rủa; thần chú", "Hạng Tần Suất (Jun Da)": "2281.0", "Tần Suất % (Jun Da)": "98.0039680623", "GavinGrover_Once (Chiết tự trực tiếp)": "吅 + 几", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱吅几", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "吅", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "几", "Unihan_Simplified (Chữ Giản thể)": "咒", "Unihan_Traditional (Chữ Phồn thể)": "呪", "Pinyin_Xie": "zhòu", "Âm Hán Việt_Xie": "chú", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này thường làm danh từ chỉ câu thần chú hoặc làm động từ khi kết hợp để chỉ hành vi nguyền rủa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('姨', '{"9000": "2282.0", "Chữ Trung Quốc": "姨", "Bộ thủ & thành phần_Xie": "Bộ thủ | 女 | Số nét | 9 | nét | 女 | nữ | biểu nghĩa | phụ nữ | 夷 | di | biểu âm | mượn âm | 姨 = 女 (Nữ, phụ nữ, biểu nghĩa) + 夷 (Di, biểu âm); chữ hình thanh. Nghĩa chính là ''dì (chị em mẹ)'', cũng dùng cho ''chị em vợ''. Bộ Nữ rõ ràng gắn với danh xưng phụ nữ trong gia đình.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"di\" = dì. Nhớ: 女 (phụ nữ) là người chị em của mẹ — đó là ''di'' (dì); 夷 mượn âm. | Gương Hán-Việt | ''Di'' trong di nương (dì), tiểu di (em dì); chữ Hán cho ''dì'' trong từ Hán-Việt. | Mở khoá kiến thức | Biết 姨 mở khoá 阿姨 (a di - dì, cô), 姨妈 (di ma - dì), 姨夫 (di phu - chú/dượng).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 姨 là chữ hình thanh ghép 女 (phụ nữ, biểu nghĩa) với 夷 (biểu âm). Nghĩa chính: (1) chị em gái của mẹ — ''dì'' trong tiếng Việt; (2) chị em vợ — ''em vợ''. Đây là danh xưng phụ nữ trong gia đình, có từ rất sớm trong tiếng Hán cổ. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "dì (chị em mẹ); chị em vợ", "Hạng Tần Suất (Jun Da)": "2282.0", "Tần Suất % (Jun Da)": "98.0065147795", "GavinGrover_Once (Chiết tự trực tiếp)": "女 + 夷", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰女夷", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "夷", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "女", "Unihan_Simplified (Chữ Giản thể)": "姨", "Unihan_Traditional (Chữ Phồn thể)": "姨", "Pinyin_Xie": "yí", "Âm Hán Việt_Xie": "di", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này thường làm danh từ xưng hô trong gia đình hoặc dùng để gọi người phụ nữ lớn tuổi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | Từ vựng Hán 姨 (yí). Hán-Việt: di. | / | yí | / | chị em vợ | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Gia đình II", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('棒', '{"9000": "2283.0", "Chữ Trung Quốc": "棒", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 12 | nét | 木 | mộc | biểu nghĩa | gỗ | 奉 | phụng | biểu âm | gợi âm bàng | 棒 = 木 (Mộc, biểu nghĩa: gỗ) + 奉 (Phụng, biểu âm); chữ hình thanh (ls=psc). Cây gậy gỗ — ''gậy''; phái sinh khẩu ngữ ''cừ, giỏi, tuyệt''.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bổng\": 木 (gỗ) + 奉 (phụng) — gậy gỗ; cũng dùng khen ''cừ, tuyệt''. Nhớ 棒球 (bóng chày), 棍棒 (côn bổng). | Gương Hán-Việt | ''bổng'' trong ''côn bổng'', ''gậy bổng''; nghĩa khẩu ngữ tương ứng ''cừ, giỏi'' | Mở khoá kiến thức | Biết 棒 là mở 棒球, 棍棒, 棒极了 — nhóm danh từ và tính từ HSK 4-6.", "Tự nguyên_Xie": "Lục thư thông | Theo Wiktionary, 棒 là chữ hình thanh: 木 (biểu nghĩa: gỗ) ghép với 奉 (biểu âm). Nghĩa gốc ''cây gậy gỗ'' phát triển thêm nghĩa khẩu ngữ hiện đại ''cừ, giỏi, tuyệt vời'' (棒极了!). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái gậy ngắn, côn; cừ, giỏi", "Hạng Tần Suất (Jun Da)": "2283.0", "Tần Suất % (Jun Da)": "98.009055812", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 奉", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木奉", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "奉", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "棒", "Unihan_Traditional (Chữ Phồn thể)": "棒", "Pinyin_Xie": "bàng", "Âm Hán Việt_Xie": "bổng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Chữ này thường làm tính từ đứng sau phó từ chỉ mức độ để khen ngợi ai đó hoặc làm danh từ chỉ cây gậy. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | Từ đơn | Từ vựng HSK 5: tuyệt vời | / | bàng | / | tuyệt vời | Xuất hiện trong lộ trình | HSK | HSK 5 | · | Quá trình hành động II | New HSK | New HSK 5 | · | Quá trình hành động", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('郡', '{"9000": "2284.0", "Chữ Trung Quốc": "郡", "Bộ thủ & thành phần_Xie": "Bộ thủ | 邑 | Số nét | 9 | nét | 君 | quân | biểu âm | vua, quân tử — âm jūn/quân | 阝 | phụ | biểu nghĩa | ấp, vùng đất (bộ邑) | 郡 = 君 (Quân, biểu âm) + 阝/邑 (Phụ, biểu nghĩa: ấp, vùng hành chính); chữ hình thanh. Wiktionary xác nhận 邑 + 君 (c1=s, c2=p, ls=psc). 郡 là đơn vị hành chính cổ — cấp dưới quận của nhà Tần/Hán.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quận\": 阝 (vùng đất) dưới quyền 君 (quân vương) — quận là đất đai vua phong cho chư hầu cai quản. | Gương Hán-Việt | quận huyện (đơn vị hành chính), quận công (tước vị) | Mở khoá kiến thức | Biết 郡 mở khoá: quận huyện (郡县 — chế độ hành chính), quận thủ (郡守 — tri quận), quận công (郡公 — tước).", "Tự nguyên_Xie": "郡 là chữ hình thanh: bộ 邑/阝 (phụ, ấp/vùng đất) biểu nghĩa, phần 君 (quân) biểu âm. Wiktionary xác nhận cấu trúc 邑 + 君 (ls=psc). 郡 chỉ đơn vị hành chính cổ đại Trung Quốc — cấp quận lớn hơn huyện. Nhà Tần thống nhất thiên hạ, chia làm 36 quận. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "quận (đơn vị hành chính)", "Hạng Tần Suất (Jun Da)": "2284.0", "Tần Suất % (Jun Da)": "98.0115942605", "GavinGrover_Once (Chiết tự trực tiếp)": "君 + 阝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰君阝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "君", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "阝", "Unihan_Simplified (Chữ Giản thể)": "郡", "Unihan_Traditional (Chữ Phồn thể)": "郡", "Pinyin_Xie": "jùn", "Âm Hán Việt_Xie": "quận", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này thường làm danh từ chỉ đơn vị hành chính thời phong kiến hoặc dùng trong địa danh. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('浴', '{"9000": "2285.0", "Chữ Trung Quốc": "浴", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 10 | nét | 氵 | thuỷ | biểu nghĩa | nước | 谷 | cốc | biểu âm | thung lũng, hạt ngũ cốc | 浴 = 氵(Thuỷ, biểu nghĩa: nước) + 谷 (Cốc, biểu âm); chữ hình thanh. Wiktionary giải thích rõ: tắm trong nước (氵+ 谷 = tắm trong dòng nước thung lũng). 谷 cho âm ''yù''.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"dục\": nước (氵) trong thung lũng (谷) — tắm dục (浴) là ngâm mình trong nước thung lũng, thanh tịnh thân thể. | Gương Hán-Việt | dục trong ''mộc dục'', ''dục thất'', ''hải dục'' | Mở khoá kiến thức | Biết 浴 (dục) mở khoá: 沐浴 (tắm rửa), 浴室 (phòng tắm), 沐浴露 (sữa tắm), 日光浴 (tắm nắng).", "Tự nguyên_Xie": "Bạch thư | Tiểu triện | Theo Wiktionary, 浴 là chữ hình thanh (psc): 水/氵 (nước) là thành phần biểu nghĩa, 谷 là thành phần biểu âm — biểu thị hành động tắm trong nước. Wiktionary ghi chú rõ: ''– bathe in water''. Nghĩa gốc và chính là tắm rửa, ngâm mình. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "859.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thủy (082) Cốc (437)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Thủy (số 082 - nước) ở bên trái chữ Cốc (số 437 - khe suối). Lấy nước ở khe suối để tắm. Giải thích sự chuyển ý: Đây là chữ Hội ý. Dục là tắm (mộc dục).", "Nghĩa Tiếng Việt_Xie": "tắm", "Hạng Tần Suất (Jun Da)": "2285.0", "Tần Suất % (Jun Da)": "98.0141321923", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 谷", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵谷", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "谷", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "浴", "Unihan_Traditional (Chữ Phồn thể)": "浴", "Pinyin_Xie": "yù", "Âm Hán Việt_Xie": "dục", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chữ này thường làm động từ chỉ việc tắm rửa hoặc kết hợp tạo danh từ ghép liên quan đến việc tắm. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('媚', '{"9000": "2286.0", "Chữ Trung Quốc": "媚", "Bộ thủ & thành phần_Xie": "Bộ thủ | 女 | Số nét | 12 | nét | 女 | nữ | biểu nghĩa | người nữ | 眉 | mi | biểu âm | lông mày — âm méi/mi | 媚 = 女 (Nữ, biểu nghĩa: người nữ) + 眉 (Mi, biểu âm); chữ hình thanh. Bộ 女 chỉ đây là từ liên quan đến phụ nữ, phần 眉 (lông mày) cho âm méi. Gốc nghĩa: quyến rũ, duyên dáng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mị\": 女 (người nữ) với đôi 眉 (lông mày) — người con gái dùng đôi mày cong để quyến rũ, mị hoặc. | Gương Hán-Việt | mị lực (sức hấp dẫn), a dua nịnh hót | Mở khoá kiến thức | Biết 媚 mở khoá: mị lực (魅力, nhưng 媚 khác 魅), minh mị (明媚 — tươi sáng), a mị (阿媚 — nịnh hót).", "Tự nguyên_Xie": "媚 là chữ hình thanh: bộ 女 (nữ) biểu nghĩa, phần 眉 (mi, lông mày) biểu âm — ls=psc. Wiktionary xác nhận cấu trúc 女 + 眉 (c1=s, c2=p). Gốc nghĩa là xinh đẹp, hấp dẫn; mở rộng sang nghĩa nịnh nọt, vuốt ve (vì người quyến rũ thường biết cách lấy lòng). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "371.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Nữ (60) Mi (55)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Mi (số 128 - lông mày, biến âm thành mị) chỉ âm, chữ Nữ (số 86) chỉ ý. Người con gái có nhan sắc xinh đẹp làm cho người khác yêu mến. Giải thích sự chuyển ý: Chữ Mi (lông mày) chỉ âm, chữ Nữ (phụ nữ) chỉ ý. Người con gái (Nữ) có cặp lông mày (Mi) đẹp và cử chỉ điệu đà làm mê hoặc người khác (Mị). *(Biến âm Hán Việt: Trong Hán ngữ cổ, chữ Mi và chữ Mị có cách phát âm tương đồng hoặc chung gốc phụ âm. Quá trình Việt hóa đã làm âm đọc bị chênh lệch thành Mi và Mị).*", "Nghĩa Tiếng Việt_Xie": "nịnh nọt, lấy lòng", "Hạng Tần Suất (Jun Da)": "2286.0", "Tần Suất % (Jun Da)": "98.0166690906", "GavinGrover_Once (Chiết tự trực tiếp)": "女 + 眉", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰女眉", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "眉", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "女", "Unihan_Simplified (Chữ Giản thể)": "媚", "Unihan_Traditional (Chữ Phồn thể)": "媚", "Pinyin_Xie": "mèi", "Âm Hán Việt_Xie": "mị", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Chữ này thường làm tính từ miêu tả vẻ ngoài quyến rũ hoặc làm động từ chỉ hành vi lấy lòng. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('稣', '{"9000": "2287.0", "Chữ Trung Quốc": "稣", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 13 | nét | 鱼 | ngư | biểu âm | cá — gợi âm sū | 禾 | hoà | biểu nghĩa | lúa, cây ngũ cốc | 稣 = 鱼 (Ngư, biểu âm theo phân tích Wiktionary c1=p) + 禾 (Hoà, biểu nghĩa c2=s); chữ hình thanh theo ls=psc. Nghĩa gốc liên quan đến tô tía tô hoặc hồi tỉnh; ngày nay 稣 chủ yếu dùng trong phiên âm tên 耶稣 (Giê-su).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tô\": 禾 (lúa) + 鱼 (cá) — hai nguồn lương thực dân dã, gợi sự hồi sinh tươi mới; 耶稣 (Giê-su) dùng chữ này. | Gương Hán-Việt | Giê-su (耶稣), hồi tô (hồi sinh) | Mở khoá kiến thức | Biết 稣 chủ yếu mở khoá: 耶稣 (Giê-su — phiên âm Cơ Đốc giáo), 耶稣基督 (Chúa Giê-su Ki-tô).", "Tự nguyên_Xie": "稣 là chữ hình thanh: phần 鱼 (ngư) biểu âm (c1=p), bộ 禾 (hoà, lúa) biểu nghĩa (c2=s), ls=psc. Wiktionary ghi đây là dạng thay thế của 蘇 (tô, tía tô; hồi sinh) và 甦 (hồi tỉnh). Nghĩa chính hiện đại: phiên âm tên riêng Giê-su (耶稣). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: gia tô 耶穌)", "Hạng Tần Suất (Jun Da)": "2287.0", "Tần Suất % (Jun Da)": "98.0192049552", "GavinGrover_Once (Chiết tự trực tiếp)": "鱼 + 禾", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰鱼禾", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "禾", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鱼", "Unihan_Simplified (Chữ Giản thể)": "稣", "Unihan_Traditional (Chữ Phồn thể)": "穌", "Pinyin_Xie": "sū", "Âm Hán Việt_Xie": "tô", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chữ này thường dùng làm động từ chỉ sự hồi sinh hoặc xuất hiện trong danh từ riêng chỉ Chúa Giê-su. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('淮', '{"9000": "2288.0", "Chữ Trung Quốc": "淮", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 11 | nét | 氵 | thuỷ | biểu nghĩa | nước | 隹 | chuy | biểu âm | chim đuôi ngắn — âm zhuī | 淮 = 氵 (Thuỷ, biểu nghĩa: nước) + 隹 (Chuy, biểu âm); chữ hình thanh. Bộ 氵 chỉ đây là tên sông, phần 隹 (chuy, chim đuôi ngắn) cho âm huái. 淮 là tên sông Hoài — con sông lớn ở miền Trung Trung Quốc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hoài\": 氵 (nước) + 隹 (chim) — sông Hoài nơi chim trời tụ tập, ranh giới Nam Bắc thiên hạ. | Gương Hán-Việt | Hoài Hà (sông Hoài), Hoài Hải (vùng Hoài Hải) | Mở khoá kiến thức | Biết 淮 mở khoá: Hoài Hà (淮河), Hoài Hải (淮海 — chiến dịch lịch sử), Giang Hoài (江淮 — vùng Giang Tô — An Huy).", "Tự nguyên_Xie": "淮 là chữ hình thanh: bộ 水/氵 (thuỷ) biểu nghĩa ''nước'', phần 隹 biểu âm (c1=s, c2=p, ls=psc). Wiktionary xác nhận cấu trúc này. 淮 (Hoài) là tên sông Hoài Hà — ranh giới địa lý-khí hậu quan trọng giữa miền Bắc và miền Nam Trung Quốc (đường Tần Lĩnh — Hoài Hà). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sông Hoài", "Hạng Tần Suất (Jun Da)": "2288.0", "Tần Suất % (Jun Da)": "98.0217387527", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 隹", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵隹", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "隹", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "淮", "Unihan_Traditional (Chữ Phồn thể)": "淮", "Pinyin_Xie": "huái", "Âm Hán Việt_Xie": "hoài", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này chủ yếu dùng làm danh từ riêng để chỉ sông Hoài hoặc vùng Hoài Hà. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('哎', '{"9000": "2289.0", "Chữ Trung Quốc": "哎", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 8 | nét | 口 | khẩu | biểu nghĩa | miệng, tiếng phát ra | 艾 | ngải | biểu âm | cây ngải, dừng lại | 哎 = 口 (Khẩu, biểu nghĩa: miệng) + 艾 (Ngải, biểu âm); chữ hình thanh. Bộ 口 cho nghĩa là âm thanh phát ra từ miệng, 艾 cho âm (āi ~ ai).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ai\": miệng 口 (khẩu) phát âm ngải 艾 (ai) — 哎 là tiếng than ai thốt lên khi bất ngờ. | Gương Hán-Việt | ai trong ''哎呀 ai da'' (thán từ ngạc nhiên/đau) | Mở khoá kiến thức | Biết 哎 (ai) mở khoá: 哎呀 (ai ya, ối da — ngạc nhiên/đau), 哎哟 (ôi yo — phàn nàn).", "Tự nguyên_Xie": "Theo Wiktionary, 哎 là chữ hình thanh (psc): 口 (khẩu, biểu nghĩa: miệng) + 艾 (ngải, biểu âm). Đây là chữ tạo muộn để ghi thán từ bằng miệng — tiếng kêu ngạc nhiên hoặc phản đối nhẹ. Chưa thấy trong giáp cốt hay kim văn. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "úi, ái, ai (thán từ biểu thị sự bất mãn hoặc kinh ngạc); nhé (thán từ biểu thị sự nhắc nhở); chà (thán từ biểu thị vừa ngạc nhiên vừa ca ngợi)", "Hạng Tần Suất (Jun Da)": "2289.0", "Tần Suất % (Jun Da)": "98.0242642817", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 艾", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口艾", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "艾", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "哎", "Unihan_Traditional (Chữ Phồn thể)": "哎", "Pinyin_Xie": "āi", "Âm Hán Việt_Xie": "ai", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Thán từ | 叹词 | Thường đứng ở đầu câu để biểu thị sự ngạc nhiên, bất mãn hoặc để gọi người khác. | Thán từ | 叹词 | Bộc lộ cảm xúc hoặc dùng để gọi đáp: 啊, 哦, 喂. Đứng tách riêng ở đầu câu, không làm thành phần câu.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | āi | / | ai | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Từ chức năng và phụ từ I", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('屁', '{"9000": "2290.0", "Chữ Trung Quốc": "屁", "Bộ thủ & thành phần_Xie": "Bộ thủ | 尸 | Số nét | 7 | nét | 尸 | thi | biểu nghĩa | xác chết, thân thể (bộ thi) | 比 | tỷ | biểu âm | so sánh | 屁 = 尸 (Thi, biểu nghĩa: thân thể) + 比 (Tỷ, biểu âm); chữ hình thanh. 比 cho âm ''pì'', bộ 尸 chỉ thân người — khí thải từ thân người (đánh rắm, mông).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thí\": thân thể (尸) so sánh (比) lạ — chữ thí (屁) dùng để chỉ thứ ''vô giá trị'' như hơi xì hay mông đít. | Gương Hán-Việt | thí ít dùng trong từ Hán-Việt phổ thông | Mở khoá kiến thức | Biết 屁 (thí) mở khoá: 屁股 (mông), 放屁 (đánh rắm/nói nhảm), 臭屁 (kiêu ngạo, tự cao).", "Tự nguyên_Xie": "Theo Wiktionary, 屁 là chữ hình thanh (psc): 尸 (thân thể) là thành phần biểu nghĩa, 比 là thành phần biểu âm. Nghĩa là hơi từ cơ thể, đánh rắm; cũng chỉ mông (屁股). Từ thông tục phổ biến trong tiếng Trung hiện đại. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "phả hơi xuống phía dưới; đánh rắm", "Hạng Tần Suất (Jun Da)": "2290.0", "Tần Suất % (Jun Da)": "98.0267882603", "GavinGrover_Once (Chiết tự trực tiếp)": "尸 + 比", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴尸比", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "比", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "尸", "Unihan_Simplified (Chữ Giản thể)": "屁", "Unihan_Traditional (Chữ Phồn thể)": "屁", "Pinyin_Xie": "pì", "Âm Hán Việt_Xie": "thí", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường dùng làm danh từ trong khẩu ngữ hoặc kết hợp với động từ phóng để chỉ việc đánh rắm. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('漆', '{"9000": "2291.0", "Chữ Trung Quốc": "漆", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 14 | nét | 氵 | thuỷ | biểu nghĩa | nước, chất lỏng | 桼 | biểu âm | cây sơn (dạng cổ, gồm 木 + người + chất nhựa) | 漆 = 氵(Thuỷ, biểu nghĩa: chất lỏng) + 桼 (biểu âm; gốc là cây sơn 木 với người đang cạo nhựa); chữ hình thanh. Wiktionary ghi: 桼 vốn chỉ chính từ này, sau thêm 水/氵để làm rõ chất lỏng. Chữ chỉ nhựa sơn, chất lỏng đặc dùng để sơn phủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tất\": chất lỏng (氵) từ cây sơn (桼) — nhựa tất (漆) đen như đêm, dùng sơn phủ đồ vật. | Gương Hán-Việt | tất trong ''sơn tất'', ''tất hắc'' (ít dùng); phổ biến hơn trong ''sơn漆'' | Mở khoá kiến thức | Biết 漆 (tất) mở khoá: 油漆 (sơn), 漆黑 (đen tuyền), 漆器 (đồ sơn mài).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Theo Wiktionary, 漆 là chữ hình thanh (psc): 水/氵 (chất lỏng) là thành phần biểu nghĩa, 桼 là thành phần biểu âm. Đặc biệt, Wiktionary chú thích: ''{{och-l|*桼}} originally referred to this word, {{och-l|*水}} was added later'' — tức 桼 là chữ gốc ban đầu đã chỉ nhựa sơn, sau mới thêm bộ 水 để nhấn chất lỏng. Nghĩa là nhựa sơn từ cây sơn (lacquer), và màu đen tuyền. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sông Tất; quét sơn; cây sơn; đen", "Hạng Tần Suất (Jun Da)": "2291.0", "Tần Suất % (Jun Da)": "98.0293122389", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 桼", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵桼", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "桼", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "漆", "Unihan_Traditional (Chữ Phồn thể)": "漆", "Pinyin_Xie": "qī", "Âm Hán Việt_Xie": "tất", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Tính từ | 形容词 | Làm danh từ chỉ chất sơn, động từ chỉ việc quét sơn, hoặc tính từ chỉ màu đen như sơn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | qī | / | sơn | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Xây dựng và cải tạo", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('淫', '{"9000": "2292.0", "Chữ Trung Quốc": "淫", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 11 | nét | 氵 | thuỷ | biểu nghĩa | nước | 㸒 | biểu âm | thành phần âm cổ (爫+壬) | 淫 = 氵 (Thuỷ, biểu nghĩa: nước) + 㸒 (biểu âm, gồm 爫+壬); chữ hình thanh. Bộ 氵 chỉ đây là chữ liên quan đến nước/chảy tràn; phần 㸒 cho âm yín. Gốc nghĩa: ngập tràn, dâm dật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"dâm\": 氵 (nước) dâng lên 㸒 — nước tràn bờ, dâm là vượt quá giới hạn, như lũ lụt vỡ đê. | Gương Hán-Việt | dâm dật (buông thả), dâm thư (sách khiêu dâm) | Mở khoá kiến thức | Biết 淫 mở khoá: dâm dật (淫逸), dâm ô (淫污), dâm thư (淫书); trong văn cổ: phú quý bất năng dâm (giàu sang không làm hư).", "Tự nguyên_Xie": "淫 là chữ hình thanh: bộ 氵 (thuỷ) biểu nghĩa ''nước'', phần 㸒 (gồm 爫+壬) biểu âm — ls=psc. Wiktionary xác nhận cấu trúc 水 + 㸒. Nghĩa gốc là ngập tràn quá mức (nước dâng); từ đó mở rộng sang nghĩa dâm dật, buông thả. Trong văn cổ, 淫 cũng có nghĩa trung tính là ''quá mức, thái quá''. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "quá mức, quá thừa; buông thả, bừa bãi", "Hạng Tần Suất (Jun Da)": "2292.0", "Tần Suất % (Jun Da)": "98.0318336336", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 㸒", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵㸒", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "㸒", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "淫", "Unihan_Traditional (Chữ Phồn thể)": "淫", "Pinyin_Xie": "yín", "Âm Hán Việt_Xie": "dâm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường làm tính từ bổ nghĩa cho danh từ hoặc động từ để chỉ sự quá giới hạn hoặc hành vi phóng đãng. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('巢', '{"9000": "2293.0", "Chữ Trung Quốc": "巢", "Bộ thủ & thành phần_Xie": "Bộ thủ | 巛 | Số nét | 11 | nét | 巛 | xuyên | biểu hình | chim non (ba chấm tượng hình chim trong tổ) | 果 | quả | biểu hình | quả cây, trên cây | 巢 là chữ tượng hình (liushu p): hình vẽ chim non (巛, ba chấm) nằm trong tổ (田) trên đỉnh cây (木). Cấu trúc hiện đại gồm 巛 (chim) trên 果 (trái cây/cây). Đây là hội ý tượng hình, không phải hình thanh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sào\": chim (巛) đậu trên cây quả (果) — cái sào (巢) là tổ chim trên cao, nơi chim làm tổ. | Gương Hán-Việt | sào trong ''sào huyệt'', ''cổ sào'' | Mở khoá kiến thức | Biết 巢 (sào) mở khoá: 鸟巢 (tổ chim, sân vận động Bắc Kinh), 巢穴 (hang ổ), 蜂巢 (tổ ong).", "Tự nguyên_Xie": "Đại triện | Tiểu triện | Theo Wiktionary, 巢 là chữ tượng hình (liushu p): hình vẽ con chim non (巛) nằm trong tổ (田) trên đỉnh cây (木). Wiktionary dẫn nguồn Guo 1931 và Qiu 1992. Trong hình thức hiện đại, phần trên trông như 巛 (chim), phần dưới là 果. Đây là hình ảnh trực quan của tổ chim trên cây. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "702.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Xuyên (029) Quả (384)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Xuyên (số 029 - dòng sông/mái tóc) ở trên chữ Quả (số 384 - quả cây). Hình ảnh những cái mỏ của con chim non thò ra ngoài tổ ở trên cây (Quả). Giải thích sự chuyển ý: Đây là chữ Tượng hình. Sào là cái tổ chim ở trên cây (sào huyệt).", "Nghĩa Tiếng Việt_Xie": "tổ chim, ổ", "Hạng Tần Suất (Jun Da)": "2293.0", "Tần Suất % (Jun Da)": "98.0343524443", "GavinGrover_Once (Chiết tự trực tiếp)": "巛 + 果", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱巛果", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "果", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "巛", "Unihan_Simplified (Chữ Giản thể)": "巢", "Unihan_Traditional (Chữ Phồn thể)": "巢", "Pinyin_Xie": "cháo", "Âm Hán Việt_Xie": "sào", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng sau định ngữ để chỉ nơi trú ẩn của chim muông hoặc tội phạm. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('吩', '{"9000": "2294.0", "Chữ Trung Quốc": "吩", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 7 | nét | 口 | khẩu | biểu nghĩa | miệng, lời nói | 分 | phân | biểu âm | phân chia, phần | 吩 = 口 (Khẩu, biểu nghĩa: miệng) + 分 (Phân, biểu âm); cấu trúc hình thanh. 分 cho âm ''fēn'', bộ 口 chỉ hành động dùng lời — phân bảo bằng miệng (thường chỉ dùng trong từ 吩咐).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phân\": miệng (口) phân (分) bảo — khi người trên phân (吩) bảo, tức là ra lệnh, dặn dò cấp dưới. | Gương Hán-Việt | phân trong ''phân phó'' (吩咐) | Mở khoá kiến thức | Biết 吩 (phân) mở khoá: 吩咐 (dặn dò, ra lệnh) — gần như chỉ dùng trong từ ghép này.", "Tự nguyên_Xie": "Wiktionary chỉ ghi {{Han etym}} không có nội dung chi tiết cho 吩. Cấu trúc gồm 口 (miệng) + 分 (phân chia). Theo cấu trúc, đây có thể là chữ hình thanh với 口 biểu nghĩa và 分 biểu âm. Nghĩa là dặn dò, truyền lệnh bằng lời; thường dùng trong từ 吩咐 (ra lệnh, dặn dò). Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: phân phó 吩咐)", "Hạng Tần Suất (Jun Da)": "2294.0", "Tần Suất % (Jun Da)": "98.0368671208", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 分", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口分", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "分", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "吩", "Unihan_Traditional (Chữ Phồn thể)": "吩", "Pinyin_Xie": "fēn", "Âm Hán Việt_Xie": "phân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Hầu như chỉ dùng trong từ ghép phân phó để biểu thị việc sai bảo hoặc dặn dò. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('撰', '{"9000": "2295.0", "Chữ Trung Quốc": "撰", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 15 | nét | 扌 | thủ | biểu nghĩa | tay | 巽 | tốn | biểu âm | quẻ Tốn — âm xùn/zhuàn | 撰 = 扌 (Thủ, biểu nghĩa: tay) + 巽 (Tốn, biểu âm); chữ hình thanh. Bộ 扌 chỉ đây là hành động dùng tay, phần 巽 cho âm zhuàn. Gốc nghĩa: dùng tay viết, soạn thảo.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"soạn\": 扌 (tay) + 巽 (quẻ Tốn — thuận chiều, khiêm tốn) — soạn văn là tay khiêm tốn chắt lọc chữ nghĩa. | Gương Hán-Việt | soạn thảo (viết, biên soạn), soạn giả (tác giả) | Mở khoá kiến thức | Biết 撰 mở khoá: soạn thảo (撰写), soạn giả (撰者), biên soạn (编撰).", "Tự nguyên_Xie": "撰 là chữ hình thanh: bộ 手/扌 (thủ, tay) biểu nghĩa, phần 巽 biểu âm — ls=psc. Wiktionary xác nhận 手 + 巽 (c1=s, c2=p). Gốc nghĩa là soạn thảo, viết lách bằng tay; nghĩa mở rộng: biên soạn tác phẩm. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "biên soạn, soạn thảo", "Hạng Tần Suất (Jun Da)": "2295.0", "Tần Suất % (Jun Da)": "98.0393802469", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 巽", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌巽", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "巽", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "撰", "Unihan_Traditional (Chữ Phồn thể)": "撰", "Pinyin_Xie": "zhuàn", "Âm Hán Việt_Xie": "soạn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Làm động từ đứng trước danh từ chỉ tác phẩm văn học, bài viết để chỉ hành động sáng tác. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('啸', '{"9000": "2296.0", "Chữ Trung Quốc": "啸", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 11 | nét | 口 | khẩu | biểu nghĩa | miệng, tiếng | 肃 | túc | biểu âm | nghiêm trang, thanh tịnh | 啸 = 口 (Khẩu, biểu nghĩa: miệng) + 肃 (Túc, biểu âm); chữ hình thanh dạng giản thể của 嘯. 肃 cho âm gần ''xiào'', bộ 口 chỉ hành động phát âm — tiếng gầm vang, hú lên.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khiếu\": miệng (口) phát tiếng nghiêm túc (肃) — khiếu (啸) là tiếng hú, tiếng thét vang dội, như tiếng hổ gầm hay sóng biển gào. | Gương Hán-Việt | khiếu trong ''hô khiếu'', ''hải khiếu'' | Mở khoá kiến thức | Biết 啸 (khiếu) mở khoá: 呼啸 (huýt sáo, vù qua), 海啸 (sóng thần), 虎啸 (tiếng hổ gầm).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 嘯/啸 là chữ hình thanh (psc): 口 (miệng) là thành phần biểu nghĩa, 肅/肃 là thành phần biểu âm. Nghĩa gốc là huýt sáo, thổi sáo miệng (whistle). Nghĩa mở rộng: gầm thét, hú gào như hổ hay sóng biển. Trong Đạo gia còn có thuật luyện khí qua tiếng hú đặc biệt. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "rít, thở dài, huýt gió; gầm, thét gào, kêu, hú", "Hạng Tần Suất (Jun Da)": "2296.0", "Tần Suất % (Jun Da)": "98.0418866548", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 肃", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口肃", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "肃", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "啸", "Unihan_Traditional (Chữ Phồn thể)": "嘯", "Pinyin_Xie": "xiào", "Âm Hán Việt_Xie": "khiếu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Làm động từ chỉ tiếng kêu lớn của muông thú hoặc tiếng rít của gió bão. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('滞', '{"9000": "2297.0", "Chữ Trung Quốc": "滞", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 12 | nét | 氵 | thuỷ | biểu nghĩa | nước, chất lỏng | 带 | đới | biểu âm | dải, đai, vùng | 滞 = 氵(Thuỷ, biểu nghĩa: nước) + 带 (Đới, biểu âm); chữ hình thanh dạng giản thể của 滯. 帶/带 cho âm ''zhì'' (thông qua biến đổi âm lịch sử), bộ 水/氵chỉ nước đọng — dòng nước bị chặn lại, ứ đọng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trệ\": nước (氵) bị đới (带) chặn lại — dải đất (đới) cản dòng nước, gây trệ (滞) — đình trệ, chậm chạp. | Gương Hán-Việt | trệ trong ''đình trệ'', ''trệ hậu'', ''ứ trệ'' | Mở khoá kiến thức | Biết 滞 (trệ) mở khoá: 停滞 (đình trệ), 滞留 (mắc kẹt), 滞后 (tụt hậu), 滞销 (ế ẩm).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 滯/滞 là chữ hình thanh (psc): 水/氵 (nước) là thành phần biểu nghĩa, 帶/带 là thành phần biểu âm. Nghĩa gốc là nước đọng, ứ trệ; mở rộng sang nghĩa bị tắc nghẽn, trì trệ về tiến độ hay hoạt động. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chậm, trễ", "Hạng Tần Suất (Jun Da)": "2297.0", "Tần Suất % (Jun Da)": "98.0443930627", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 带", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵带", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "带", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "滞", "Unihan_Traditional (Chữ Phồn thể)": "滯", "Pinyin_Xie": "zhì", "Âm Hán Việt_Xie": "trệ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường làm tính từ hoặc động từ để chỉ trạng thái ứ đọng, không lưu thông của hàng hóa hoặc công việc. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('玫', '{"9000": "2298.0", "Chữ Trung Quốc": "玫", "Bộ thủ & thành phần_Xie": "Bộ thủ | 玉 | Số nét | 8 | nét | 王 | vương | biểu nghĩa | ngọc (bộ玉 viết gọn) | 攵 | phộc | biểu âm | gợi âm méi | 玫 = 𤣩/王 (Ngọc, biểu nghĩa: ngọc quý) + 文/攵 (biểu âm); chữ hình thanh. Wiktionary ghi 玉 + 文 (alt1=𤣩, c1=s, c2=p, ls=psc). Bộ 王 ở đây thực chất là bộ 玉 (ngọc) viết không có dấu chấm, chỉ đây là loại đá quý.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mai\": 王 (ngọc) + 攵 — viên ngọc đỏ như cánh hoa hồng; 玫瑰 là hoa hồng — loài hoa quý như ngọc. | Gương Hán-Việt | mai quý (ngọc quý đỏ), 玫瑰 (hoa hồng) | Mở khoá kiến thức | Biết 玫 hầu như chỉ dùng trong: 玫瑰 (méiguī — hoa hồng), 玫瑰花 (bông hoa hồng), 玫瑰红 (màu đỏ hồng).", "Tự nguyên_Xie": "玫 là chữ hình thanh: bộ 玉/𤣩 (ngọc) biểu nghĩa, phần 文 biểu âm — ls=psc. Wiktionary xác nhận cấu trúc 玉 + 文 (alt1=𤣩). Nghĩa gốc là một loại đá quý đỏ đẹp; ngày nay 玫 hầu như chỉ xuất hiện trong từ 玫瑰 (hoa hồng). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: mai khôi 玫瑰)", "Hạng Tần Suất (Jun Da)": "2298.0", "Tần Suất % (Jun Da)": "98.0468937859", "GavinGrover_Once (Chiết tự trực tiếp)": "王 + ⺙", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰王⺙", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "⺙", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "王", "Unihan_Simplified (Chữ Giản thể)": "玫", "Unihan_Traditional (Chữ Phồn thể)": "玫", "Pinyin_Xie": "méi", "Âm Hán Việt_Xie": "mai", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chủ yếu dùng trong từ ghép mai khôi để chỉ hoa hồng hoặc một loại ngọc quý. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('硕', '{"9000": "2299.0", "Chữ Trung Quốc": "硕", "Bộ thủ & thành phần_Xie": "Bộ thủ | 石 | Số nét | 11 | nét | 石 | thạch | biểu âm | gợi âm shuò | 页 | hiệt | biểu nghĩa | cái đầu — biểu trưng to lớn | 硕 là giản thể của 碩. 碩 = 石 + 頁 (psc) — 石 biểu âm, 頁 biểu nghĩa. Bản giản thể rút 頁 thành 页. Chữ hình thanh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thạc\": tảng đá 石 nặng cùng cái đầu 页 to — vạm vỡ, đó là ''thạc'' (to lớn, thạc sĩ). | Gương Hán-Việt | thạc trong \"thạc sĩ\" 碩士 | Mở khoá kiến thức | Biết 硕 mở khoá nhóm từ về to lớn/học vị: 硕士, 丰硕, 硕果.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary chú 碩 = 石 + 頁 (ls=psc, c1=p c2=s) — 石 cho âm shuò, 頁 (đầu) cho nghĩa ''to, lớn''. Nghĩa gốc ''đầu to'', mở rộng thành ''to lớn, eminence, thành tựu''. Trong tiếng Trung hiện đại còn dùng để chỉ học vị thạc sĩ. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "to lớn", "Hạng Tần Suất (Jun Da)": "2299.0", "Tần Suất % (Jun Da)": "98.0493841735", "GavinGrover_Once (Chiết tự trực tiếp)": "石 + 页", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰石页", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "页", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "石", "Unihan_Simplified (Chữ Giản thể)": "硕", "Unihan_Traditional (Chữ Phồn thể)": "碩", "Pinyin_Xie": "shuò", "Âm Hán Việt_Xie": "thạc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Làm tính từ bổ nghĩa cho danh từ để chỉ quy mô to lớn hoặc thành quả vĩ đại. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('钓', '{"9000": "2300.0", "Chữ Trung Quốc": "钓", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 8 | nét | 钅 | kim | biểu nghĩa | kim loại | 勺 | thược | biểu âm | cái muỗng, cái vá | 钓 = 钅/金 (Kim, biểu nghĩa: kim loại) + 勺 (Thược, biểu âm); chữ hình thanh. Bộ 钅 cho nghĩa liên quan đến kim loại (lưỡi câu bằng sắt), 勺 cho âm (diào ~ điếu).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"điếu\": kim loại 钅 (kim) cong như muỗng 勺 (thược) — lưỡi câu 钓 móc cá, đó là câu cá điếu. | Gương Hán-Việt | điếu trong ''câu điếu'' (câu cá), ''钓鱼台 Điếu Ngư Đài'' | Mở khoá kiến thức | Biết 钓 (điếu) mở khoá: 钓鱼 (câu cá), 垂钓 (thả câu), 钓鱼台 (Điếu Ngư Đài).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 钓 là chữ giản thể của 釣. Phồn thể 釣 là chữ hình thanh: 金 (kim, biểu nghĩa: kim loại) + 勺 (thược, biểu âm). Lưỡi câu làm bằng kim loại — đây là hình ảnh trực quan của hành động câu cá với lưỡi câu kim loại. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "câu cá", "Hạng Tần Suất (Jun Da)": "2300.0", "Tần Suất % (Jun Da)": "98.0518714604", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 勺", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅勺", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "勺", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "钓", "Unihan_Traditional (Chữ Phồn thể)": "釣", "Pinyin_Xie": "diào", "Âm Hán Việt_Xie": "điếu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chữ này thường làm động từ đứng trước tân ngữ chỉ cá hoặc làm danh từ trong các từ ghép liên quan đến việc câu cá. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | Từ đơn | Từ vựng HSK 5: câu cá | Xuất hiện trong lộ trình | HSK | HSK 5 | · | Thể thao và giải trí", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蝶', '{"9000": "2301.0", "Chữ Trung Quốc": "蝶", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 15 | nét | 虫 | trùng | biểu nghĩa | sâu bọ, côn trùng | 枼 | biểu âm | gồm 世 (thế) + 木 (mộc): tấm gỗ mỏng | 蝶 = 虫 (Trùng, biểu nghĩa: côn trùng) + 枼 (biểu âm: gồm 世+木); chữ hình thanh. Bộ 虫 cho nghĩa côn trùng, 枼 cho âm (dié ~ điệp) gợi hình ảnh cánh mỏng như lá.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"điệp\": bộ trùng 虫 (trùng) bay nhẹ như lá mộc 枼 — con điệp 蝶 bướm cánh mỏng như lá bay. | Gương Hán-Việt | điệp trong ''hồ điệp'' (con bướm), ''điệp khúc'' (điệp khúc) | Mở khoá kiến thức | Biết 蝶 (điệp) mở khoá: 蝴蝶 (con bướm), 蝶泳 (bơi ếch bướm), 蝴蝶结 (nơ bướm).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Theo Wiktionary, 蝶 là chữ hình thanh (psc): 虫 (trùng, biểu nghĩa: côn trùng) + 枼 (biểu âm, gồm 世+木: tấm lá/cánh mỏng). Hình ảnh thành phần âm 枼 gợi cánh bướm mỏng như lá, kết hợp bộ trùng để chỉ loài côn trùng có cánh đẹp. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1062.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Trùng (142) Diệp (485)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Trùng (số 142 - côn trùng) ở bên trái chữ Diệp (số 485 - mỏng manh/chỉ âm - viết là 枼). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Diệp chỉ âm, bộ Trùng chỉ ý. Điệp là từ để chỉ loài bươm bướm (hồ điệp).", "Nghĩa Tiếng Việt_Xie": "con bươm bướm", "Hạng Tần Suất (Jun Da)": "2301.0", "Tần Suất % (Jun Da)": "98.0543577136", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 枼", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫枼", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "枼", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蝶", "Unihan_Traditional (Chữ Phồn thể)": "蜨", "Pinyin_Xie": "dié", "Âm Hán Việt_Xie": "điệp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ, thường kết hợp với các từ khác để chỉ loài bướm hoặc hình dáng giống cánh bướm. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('膝', '{"9000": "2302.0", "Chữ Trung Quốc": "膝", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 15 | nét | 月 | nguyệt | biểu nghĩa | thịt, cơ thể (bộ nhục viết như nguyệt) | 桼 | biểu âm | cây sơn (dạng cổ) | 膝 = 月/肉 (Nhục, biểu nghĩa: thịt/cơ thể) + 桼 (biểu âm, cùng thành phần âm với 漆); chữ hình thanh. Wiktionary ghi chú nguồn gốc sâu hơn: ban đầu là 厀 = 桼 (biểu âm) + 卩 (người quỳ, biểu nghĩa), sau thay bằng 肉 cho rõ nghĩa bộ phận cơ thể.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tất\": thịt (月) của cái đầu gối — chữ tất (膝) có cùng âm Hán-Việt với 漆 (sơn), cần phân biệt bộ: 膝 dùng bộ nhục 月. | Gương Hán-Việt | tất trong ''tất cái'' (đầu gối), ít dùng độc lập | Mở khoá kiến thức | Biết 膝 (tất) mở khoá: 膝盖 (đầu gối), 膝关节 (khớp gối), 跪膝 (quỳ gối).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Theo Wiktionary, 膝 là chữ hình thanh: 肉/⺼ (thịt, bộ phận cơ thể) là thành phần biểu nghĩa, 桼 là thành phần biểu âm. Hình thức gốc là 厀 = 桼 (biểu âm) + 卩 (người đang quỳ gối, biểu nghĩa) — hình ảnh trực quan của đầu gối. Sau này thay 卩 bằng bộ nhục 肉 để rõ đây là bộ phận cơ thể. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đầu gối", "Hạng Tần Suất (Jun Da)": "2302.0", "Tần Suất % (Jun Da)": "98.0568429334", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 桼", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月桼", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "桼", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "膝", "Unihan_Traditional (Chữ Phồn thể)": "厀", "Pinyin_Xie": "xī", "Âm Hán Việt_Xie": "tất", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ bộ phận cơ thể, thường kết hợp thành từ ghép như tất cái hoặc đứng sau giới từ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('姚', '{"9000": "2303.0", "Chữ Trung Quốc": "姚", "Bộ thủ & thành phần_Xie": "Bộ thủ | 女 | Số nét | 9 | nét | 女 | nữ | biểu nghĩa | người nữ | 兆 | triệu | biểu âm | điềm triệu — âm zhào/yáo | 姚 = 女 (Nữ, biểu nghĩa: người nữ) + 兆 (Triệu, biểu âm); chữ hình thanh. Bộ 女 chỉ đây là tên người nữ hoặc họ, phần 兆 cho âm yáo. 姚 là họ lớn ở Trung Quốc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"diêu\": 女 (nữ) + 兆 (điềm lành vạn triệu) — họ Diêu là dòng dõi quý tộc từ thời vua Thuấn, người nữ mang điềm lành. | Gương Hán-Việt | họ Diêu (姚姓), Diêu Minh (tên người nổi tiếng) | Mở khoá kiến thức | Biết 姚 chủ yếu dùng làm: họ 姚 (Yáo), tên riêng; 姚明 (Yao Ming — cầu thủ bóng rổ).", "Tự nguyên_Xie": "姚 là chữ hình thanh: bộ 女 (nữ) biểu nghĩa, phần 兆 (triệu) biểu âm — ls=psc. Wiktionary xác nhận 女 + 兆 (c1=s, c2=p). Nghĩa gốc là tên người; mở rộng sang họ 姚 — một trong những họ cổ xưa nhất Trung Quốc, liên quan đến Đế Thuấn (vua Thuấn họ Diêu). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "vẻ mặt đẹp", "Hạng Tần Suất (Jun Da)": "2303.0", "Tần Suất % (Jun Da)": "98.0593266027", "GavinGrover_Once (Chiết tự trực tiếp)": "女 + 兆", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰女兆", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "兆", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "女", "Unihan_Simplified (Chữ Giản thể)": "姚", "Unihan_Traditional (Chữ Phồn thể)": "姚", "Pinyin_Xie": "yáo", "Âm Hán Việt_Xie": "diêu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Chữ này chủ yếu dùng làm họ người hoặc làm tính từ mô tả vẻ đẹp thanh tao trong văn cổ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('茂', '{"9000": "2304.0", "Chữ Trung Quốc": "茂", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 8 | nét | 艹 | thảo | biểu nghĩa | cỏ, thực vật | 戊 | mậu | biểu âm | Mậu, can thứ 5 trong Thiên Can | 茂 = 艹(Thảo, biểu nghĩa: thực vật) + 戊 (Mậu, biểu âm); chữ hình thanh chính (psc). Wiktionary cũng ghi thêm một ứng dụng hội ý (ic) trong hoá học hữu cơ: 艹 chỉ hợp chất thơm + 戊 chỉ vòng 5 carbon = cyclopentadiene. Nghĩa gốc là cây cỏ tươi tốt, sum suê.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mậu\": cỏ cây (艹) của năm Mậu (戊) — năm Mậu tượng trưng đất đai màu mỡ, cỏ cây mậu thịnh (茂) sum suê. | Gương Hán-Việt | mậu trong ''mậu thịnh'', ''phong mậu'', ''tươi mậu'' | Mở khoá kiến thức | Biết 茂 (mậu) mở khoá: 茂盛 (sum suê), 茂密 (rậm rạp), 茂林 (rừng cây tươi tốt).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 茂 là chữ hình thanh (psc): 艸/艹 (cỏ, thực vật) là thành phần biểu nghĩa, 戊 là thành phần biểu âm. Nghĩa gốc là cây cỏ sum suê, tươi tốt; sau mở rộng sang tài năng xuất sắc. Wiktionary còn ghi thêm cách phân tích hội ý (ic) trong hoá học: 艹 (vòng thơm) + 戊 (5 carbon) = cyclopentadiene, nhưng đây là ứng dụng hậu kỳ không phải nguồn gốc. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tươi tốt", "Hạng Tần Suất (Jun Da)": "2304.0", "Tần Suất % (Jun Da)": "98.0618061378", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 戊", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹戊", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "戊", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "茂", "Unihan_Traditional (Chữ Phồn thể)": "茂", "Pinyin_Xie": "mào", "Âm Hán Việt_Xie": "mậu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này làm tính từ thường đứng trước danh từ hoặc làm vị ngữ để tả cây cối, sự phát triển sum suê. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('躯', '{"9000": "2305.0", "Chữ Trung Quốc": "躯", "Bộ thủ & thành phần_Xie": "Bộ thủ | 身 | Số nét | 11 | nét | 身 | thân | biểu nghĩa | thân xác, cơ thể | 区 | âu | biểu âm | khu vực — âm qū | 躯 = 身 (Thân, biểu nghĩa: cơ thể) + 区 (Âu, biểu âm); chữ hình thanh. Đây là dạng giản thể của 軀 (thân xác). Bộ 身 chỉ đây là từ chỉ cơ thể người, phần 区 cho âm qū.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khu\": 身 (thân xác) chiếm một 区 (vùng không gian) — khu thể là vùng không gian mà cơ thể chiếm giữ. | Gương Hán-Việt | khu thể (thân xác), thân khu (toàn thân) | Mở khoá kiến thức | Biết 躯 mở khoá: thân khu (身躯 — thân mình), khu thể (躯体 — thể xác), khu khán (驱赶 khác, đừng nhầm).", "Tự nguyên_Xie": "躯 là dạng giản thể của 軀. Wiktionary ghi ''Han simp 軀, f=區, t=区''. Cấu trúc hình thanh: bộ 身 (thân) biểu nghĩa, phần 區/区 biểu âm. Nghĩa: thân xác, cơ thể vật lý; 身躯 chỉ thân mình, thể xác phân biệt với tâm hồn hay trí tuệ. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thân thể, hình vóc", "Hạng Tần Suất (Jun Da)": "2305.0", "Tần Suất % (Jun Da)": "98.0642851561", "GavinGrover_Once (Chiết tự trực tiếp)": "身 + 区", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰身区", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "区", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "身", "Unihan_Simplified (Chữ Giản thể)": "躯", "Unihan_Traditional (Chữ Phồn thể)": "軀", "Pinyin_Xie": "qū", "Âm Hán Việt_Xie": "khu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ, thường kết hợp với các từ khác để chỉ thân thể hoặc vóc dáng của con người. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('吏', '{"9000": "2306.0", "Chữ Trung Quốc": "吏", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 6 | nét | 吏 | lại | tượng hình | người cầm cờ hiệu — quan lại cấp thấp | 吏 là biến thể của 叓 (dạng cổ của 事). Trong giáp cốt, chữ mô tả bàn tay cầm cờ hiệu hoặc công cụ để ra lệnh — biểu trưng cho người đại diện, quan sai. 吏 và 史 (sử) có cùng gốc, đều từ hình ảnh tay cầm vật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lại\": chữ lại = 史 (sử quan) cộng thêm nét ngang — như quan lại cấp thấp cầm bảng gỗ thực thi lệnh trên. | Gương Hán-Việt | quan lại (quan chức), lại dịch (nha lại, thư lại) | Mở khoá kiến thức | Biết 吏 mở khoá: quan lại (官吏), lại dịch (吏役 — nha lại), tham lại (貪吏 — quan tham nhũng).", "Tự nguyên_Xie": "吏 là biến thể của 叓 — dạng cổ của 事. Wiktionary mô tả: ''a hand holding a flag to mean representative, ambassador''. Cả 吏 và 史 đều xuất phát từ hình ảnh bàn tay cầm vật (cờ hiệu, thẻ ghi chép). 吏 chỉ quan lại cấp thấp, người thi hành công vụ; phân biệt với 官 (quan cấp cao hơn). | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1443.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Khẩu (030) Trượng (598)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Khẩu (số 030 - cái miệng/ 口) lọt vào giữa chữ Trượng (số 598 - người trưởng bối/cái gậy/ 丈). Hình ảnh ông quan tay cầm cây gậy, dùng miệng lớn tiếng ra lệnh cho binh lính dân đen làm việc. Giải thích sự chuyển ý: Đây là chữ Hội ý. Lại là chức quan cai trị (hoặc giúp việc) thời phong kiến (quan lại, lại dịch).", "Nghĩa Tiếng Việt_Xie": "viên quan, người làm việc cho nhà nước", "Hạng Tần Suất (Jun Da)": "2306.0", "Tần Suất % (Jun Da)": "98.0667631408", "GavinGrover_Once (Chiết tự trực tiếp)": "No glyph available + 乂", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱乂", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "吏", "Unihan_Traditional (Chữ Phồn thể)": "吏", "Pinyin_Xie": "lì", "Âm Hán Việt_Xie": "lại", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ chức vị thời phong kiến, thường đứng sau các danh từ chỉ bộ ngành hoặc tính chất công việc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('猿', '{"9000": "2307.0", "Chữ Trung Quốc": "猿", "Bộ thủ & thành phần_Xie": "Bộ thủ | 犬 | Số nét | 13 | nét | 犭 | khuyển | biểu nghĩa | thú vật (bộ chó) | 袁 | viên | biểu âm | áo dài — âm yuán/viên | 猿 = 犭 (Khuyển, biểu nghĩa: thú vật) + 袁 (Viên, biểu âm); chữ hình thanh. Bộ 犭 chỉ đây là loài động vật, phần 袁 cho âm yuán. 猿 chỉ loài vượn — linh trưởng không đuôi.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"viên\": 犭 (thú) + 袁 (viên) — con vượn có tiếng kêu vang vọng trên núi, gợi thơ Lý Bạch ''lưỡng ngạn viên thanh đề bất trú''. | Gương Hán-Việt | viên hầu (vượn và khỉ), nhân vượn (người vượn — khái niệm tiến hóa) | Mở khoá kiến thức | Biết 猿 mở khoá: nhân viên (人猿 — vượn người), viên hầu (猿猴 — vượn và khỉ), nguyên nhân (猿人 — người vượn).", "Tự nguyên_Xie": "猿 là chữ hình thanh: bộ 犬/犭 (khuyển, thú) biểu nghĩa, phần 袁 biểu âm — ls=psc. Wiktionary xác nhận 犬 + 袁 (c1=s, c2=p). Gốc nghĩa chỉ loài vượn (vượn tay dài, không đuôi); phân biệt với 猴 (khỉ có đuôi). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con vượn", "Hạng Tần Suất (Jun Da)": "2307.0", "Tần Suất % (Jun Da)": "98.069240092", "GavinGrover_Once (Chiết tự trực tiếp)": "犭 + 袁", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰犭袁", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "袁", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "犭", "Unihan_Simplified (Chữ Giản thể)": "猿", "Unihan_Traditional (Chữ Phồn thể)": "猨", "Pinyin_Xie": "yuán", "Âm Hán Việt_Xie": "viên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ động vật, thường đứng độc lập hoặc làm thành phần trong các thành ngữ, từ ghép. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('寨', '{"9000": "2308.0", "Chữ Trung Quốc": "寨", "Bộ thủ & thành phần_Xie": "Bộ thủ | 宀 | Số nét | 14 | nét | 宀 | miên | biểu nghĩa | mái nhà, che phủ | 木 | mộc | biểu nghĩa | gỗ, cây | 井 | tỉnh | biểu ý | giếng, bố cục ngăn nắp | 寨 = 𡨄 (gồm 宀+井+八) + 木 (Mộc, biểu nghĩa: gỗ); chữ hình-thanh kiêm hội ý (ls=psc, ls2=ic). Wiktionary ghi 𡨄 biểu âm (c1=p) + 木 biểu nghĩa (c2=s, t2=wood) — hàng rào gỗ, doanh trại. Nghĩa gốc: chắn, bít lại; gợi hàng rào gỗ bảo vệ làng trại.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trại\": 宀 (mái nhà) + 木 (gỗ) + bố cục ngăn nắp — trại lính với hàng rào gỗ chắc chắn, như sơn trại của Lương Sơn Bạc. | Gương Hán-Việt | trại tử (làng trại), sơn trại (căn cứ trên núi) | Mở khoá kiến thức | Biết 寨 mở khoá: sơn trại (山寨 — sơn trại/hàng nhái), doanh trại (营寨), cổ trại (古寨 — làng cổ).", "Tự nguyên_Xie": "寨 là chữ hình thanh kiêm hội ý: 𡨄 biểu âm (cho âm zhài), bộ 木 (mộc) biểu nghĩa ''gỗ''. Wiktionary xác nhận ls=psc, ls2=ic. Gốc nghĩa: làng trại có hàng rào gỗ bao quanh; nghĩa mở rộng: doanh trại, sơn trại (căn cứ trên núi). Hiện đại: 山寨 (hàng giả, bản nhái — từ hình ảnh xưởng sản xuất lậu trong các vùng núi). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lán trại", "Hạng Tần Suất (Jun Da)": "2308.0", "Tần Suất % (Jun Da)": "98.0717118753", "GavinGrover_Once (Chiết tự trực tiếp)": "No glyph available + 朩", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱朩", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "寨", "Unihan_Traditional (Chữ Phồn thể)": "寨", "Pinyin_Xie": "zhài", "Âm Hán Việt_Xie": "trại", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ nơi cư trú hoặc đồn lũy, thường đứng sau các danh từ chỉ địa danh hoặc đặc điểm. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('恕', '{"9000": "2309.0", "Chữ Trung Quốc": "恕", "Bộ thủ & thành phần_Xie": "Bộ thủ | 心 | Số nét | 10 | nét | 如 | như | biểu âm | như, giống như | 心 | tâm | biểu nghĩa | tim, lòng | 恕 = 如 (Như, biểu âm) + 心 (Tâm, biểu nghĩa); chữ hình thanh. 如 cho âm gần ''shù'' (qua biến đổi lịch sử), 心 chỉ lòng từ bi. Ý nghĩa sâu hơn: đặt mình (心) vào vị trí người khác (如 = như) — đồng cảm, tha thứ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thứ\": lòng (心) như (如) lòng người khác — thứ (恕) là đặt mình vào vị trí người khác, từ đó mà tha thứ; Khổng Tử coi đây là đạo làm người trọn đời. | Gương Hán-Việt | thứ trong ''tha thứ'', ''khoan thứ'', ''bao thứ'' | Mở khoá kiến thức | Biết 恕 (thứ) mở khoá: 饶恕 (tha thứ), 宽恕 (khoan thứ), 恕罪 (xin tha tội).", "Tự nguyên_Xie": "Kim văn | Tiểu triện | Lục thư thông | Theo Wiktionary, 恕 là chữ hình thanh (psc): 心 (tim/lòng) là thành phần biểu nghĩa, 如 là thành phần biểu âm. Khổng Tử trong Luận Ngữ giải thích 恕 là ''kỷ sở bất dục, vật thi ư nhân'' (điều mình không muốn, đừng làm cho người khác) — đây là khái niệm trung tâm của Nho giáo: đặt bản thân vào vị trí người khác để tha thứ và đồng cảm. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "381.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Tâm (148) Như (66)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Như (số 100 - giống như) ở trên chữ Tâm (số 148) . Lấy bụng mình (tâm) suy ra giống như (như) bụng người để bao dung, tha thứ cho nhau. Giải thích sự chuyển ý: Chữ Như (giống) chỉ âm, chữ Tâm (lòng) chỉ ý. Lấy bụng mình (Tâm) suy ra bụng người (Như) để bao dung, tha thứ (Thứ). *(Biến âm Hán Việt: Như -> Thứ)*", "Nghĩa Tiếng Việt_Xie": "tha thứ, thứ tội", "Hạng Tần Suất (Jun Da)": "2309.0", "Tần Suất % (Jun Da)": "98.0741815914", "GavinGrover_Once (Chiết tự trực tiếp)": "如 + 心", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱如心", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "如", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "心", "Unihan_Simplified (Chữ Giản thể)": "恕", "Unihan_Traditional (Chữ Phồn thể)": "恕", "Pinyin_Xie": "shù", "Âm Hán Việt_Xie": "thứ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ thường mang tân ngữ phía sau hoặc dùng trong các câu cầu khiến lịch sự để xin lỗi. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('渠', '{"9000": "2310.0", "Chữ Trung Quốc": "渠", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 11 | nét | 氵 | thuỷ | biểu nghĩa | nước | 巨 | cự | biểu âm | lớn, thước vuông | 木 | mộc | biểu hình | gỗ, cây (trong cấu trúc phức) | 渠 = 氵(Thuỷ) + thành phần phức gồm 巨 (biểu âm) và 木 (phụ thêm); chữ hình thanh. Theo Wiktionary, 渠 phái sinh từ 榘 (thước vuông lớn) rút gọn + 水/氵biểu nghĩa. 巨 (cự = lớn) cho âm ''qú'', bộ 水 chỉ dòng nước — kênh mương lớn đào bằng tay.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cừ\": nước (氵) lớn (巨) chảy qua gỗ/gỗ đào (木) — cừ (渠) là kênh đào lớn dẫn nước tưới tiêu. | Gương Hán-Việt | cừ trong ''cừ đạo'', ''kênh cừ'', ''cừ soái'' | Mở khoá kiến thức | Biết 渠 (cừ) mở khoá: 渠道 (kênh, kênh dẫn nước; kênh phân phối), 沟渠 (mương rãnh).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 渠 là chữ hình thanh (psc): 水/氵 (nước) là thành phần biểu nghĩa, 榘 (rút gọn thành 巨 + 木) là thành phần biểu âm. Nghĩa gốc là kênh đào, mương nước. Nghĩa phái sinh trong văn học cổ: ''hắn, người đó'' (đại từ ngôi thứ ba). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "kênh, ngòi; to lớn; hắn, người đó", "Hạng Tần Suất (Jun Da)": "2310.0", "Tần Suất % (Jun Da)": "98.0766461397", "GavinGrover_Once (Chiết tự trực tiếp)": "洰 + 木", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱洰木", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "洰", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "渠", "Unihan_Traditional (Chữ Phồn thể)": "渠", "Pinyin_Xie": "qú", "Âm Hán Việt_Xie": "cừ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Đại từ | 代词 | Tính từ | 形容词 | Chữ này làm danh từ chỉ đường dẫn nước hoặc làm đại từ ngôi thứ ba trong văn bạch thoại cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Đại từ | 代词 | Thay cho người hoặc vật đã nhắc tới (我, 这, 谁). Dùng đúng ở vị trí của danh từ. Chỉ người thì thêm 们 để thành số nhiều: 我们. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('戚', '{"9000": "2311.0", "Chữ Trung Quốc": "戚", "Bộ thủ & thành phần_Xie": "Bộ thủ | 戈 | Số nét | 11 | nét | 戊 | mậu | biểu nghĩa | vũ khí (cây kích/búa) — vốn nghĩa gốc | 尗 | thúc | biểu âm | phần biểu âm — gần âm ''thích/thúc'' | 戚 là chữ hình thanh (psc): 戊 (vũ khí, biểu nghĩa) + 尗 (biểu âm). Nghĩa gốc ''một loại búa chiến'', sau được mượn dùng cho nghĩa ''họ hàng, thân thích, buồn thương''.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Thích\": cây búa lễ (戊) thuộc dòng họ (尗) — đó là ''thích'', họ hàng thân thích. | Gương Hán-Việt | ''Thích'' trong ''thân thích'' (họ hàng), ''thích thuộc'' (họ thân), ''bi thích'' (buồn thương). | Mở khoá kiến thức | Biết 戚 mở khoá 亲戚 (thân thích, họ hàng), 悲戚 (bi thích, đau buồn).", "Tự nguyên_Xie": "Giáp cốt văn | Kim văn | Tiểu triện | Theo Wiktionary, 戚 là chữ hình thanh gồm 戊 (vũ khí, búa lưỡi cong — biểu nghĩa) + 尗 (biểu âm). Nghĩa gốc ''một loại búa chiến cổ, vũ khí lễ nghi''. Về sau được mượn dùng để biểu thị các nghĩa ''thân thuộc, họ hàng, đau buồn thương xót''. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thương, xót; thân thích", "Hạng Tần Suất (Jun Da)": "2311.0", "Tần Suất % (Jun Da)": "98.0791039698", "GavinGrover_Once (Chiết tự trực tiếp)": "戊 + 尗", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿵ (Bao quanh phía trên)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴戊尗", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "尗", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "戊", "Unihan_Simplified (Chữ Giản thể)": "戚", "Unihan_Traditional (Chữ Phồn thể)": "慼", "Pinyin_Xie": "qī", "Âm Hán Việt_Xie": "thích", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Chữ này làm danh từ chỉ người thân hoặc làm tính từ biểu thị sự lo lắng, buồn rầu trong văn cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('辰', '{"9000": "2312.0", "Chữ Trung Quốc": "辰", "Bộ thủ & thành phần_Xie": "Bộ thủ | 辰 | Số nét | 7 | nét | 辰 | thìn | tượng hình | chính là chữ 辰 — hình nông cụ cổ hoặc người bám vào vách đá | 辰 là chữ tượng hình (liushu p) — hình ảnh công cụ nông nghiệp cổ đại dùng để cuốc đất hoặc nhổ cỏ. Theo một giả thuyết khác, là hình người đang bám vào vách đá. Chữ đứng độc lập, không phân tích thêm được.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thìn\": chữ 辰 hình cái nông cụ cổ — con rồng Thìn (辰) trong 12 địa chi, giờ Thìn là buổi sớm khi nông dân ra đồng cày bừa. | Gương Hán-Việt | thìn trong ''Thìn'' (địa chi), ''thần'' trong ''tinh thần, sinh thần'' | Mở khoá kiến thức | Biết 辰 (thìn) mở khoá: 诞辰 (ngày sinh nhật), 星辰 (tinh tú), 时辰 (giờ trong hệ địa chi).", "Tự nguyên_Xie": "Giáp cốt văn | Kim văn | Đại triện | Tiểu triện | Theo Wiktionary, 辰 là chữ tượng hình (liushu p): hình vẽ một loại nông cụ dùng cày bừa, nhổ cỏ (Guo 1931, Qiu 1992), có thể làm bằng vỏ sò lớn (蜃, zhèn). Một giả thuyết khác (Shang 1983) cho rằng là hình người đang bám vào vách — chữ gốc của 振 (nâng đỡ). Nghĩa phái sinh: Thìn (chi thứ 5 trong Địa Chi), giờ Thìn (7-9 sáng). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "796.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Hình vẽ sấm sét rung chuyển. Giải thích sự chuyển ý: Đây là chữ Tượng hình. Thần là tiếng rung động, sấm sét. Chữ có một âm đọc là Thìn, là tên của chi thứ 5 trong 12 địa chi.", "Nghĩa Tiếng Việt_Xie": "Thìn (ngôi thứ 5 của hàng Chi)", "Hạng Tần Suất (Jun Da)": "2312.0", "Tần Suất % (Jun Da)": "98.0815612831", "GavinGrover_Once (Chiết tự trực tiếp)": "厂 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴厂", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "辰", "Unihan_Traditional (Chữ Phồn thể)": "辰", "Pinyin_Xie": "chén", "Âm Hán Việt_Xie": "thần", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này thường dùng làm danh từ để chỉ chi Thìn trong lịch pháp hoặc chỉ thời gian, ngày giờ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('舶', '{"9000": "2313.0", "Chữ Trung Quốc": "舶", "Bộ thủ & thành phần_Xie": "Bộ thủ | 舟 | Số nét | 11 | nét | 舟 | chu | biểu nghĩa | thuyền, thuyền nhỏ | 白 | bạch | biểu âm | trắng | 舶 = 舟 (Chu, biểu nghĩa: thuyền) + 白 (Bạch, biểu âm); chữ hình thanh. 白 cho âm ''bó'', bộ 舟 chỉ loại phương tiện — con thuyền lớn vượt biển.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bạc\": thuyền (舟) trắng (白) như cánh buồm — con bạc (舶) là tàu lớn vượt biển từ phương xa. | Gương Hán-Việt | bạc trong ''thuyền bạc'', ''bạc lai'' (hàng nhập khẩu) | Mở khoá kiến thức | Biết 舶 (bạc) mở khoá: 船舶 (tàu thuyền), 舶来品 (hàng ngoại nhập).", "Tự nguyên_Xie": "Theo Wiktionary, 舶 là chữ hình thanh (psc): 舟 (thuyền) là thành phần biểu nghĩa, 白 là thành phần biểu âm. Nghĩa là tàu thuyền lớn đi biển (large oceangoing ship). Thường xuất hiện trong từ 船舶 (tàu thuyền nói chung), 舶来品 (hàng nhập ngoại, đồ hàng từ tàu lớn mang đến). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thuyền lớn", "Hạng Tần Suất (Jun Da)": "2313.0", "Tần Suất % (Jun Da)": "98.084012395", "GavinGrover_Once (Chiết tự trực tiếp)": "舟 + 白", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰舟白", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "白", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "舟", "Unihan_Simplified (Chữ Giản thể)": "舶", "Unihan_Traditional (Chữ Phồn thể)": "舶", "Pinyin_Xie": "bó", "Âm Hán Việt_Xie": "bạc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ thường kết hợp với các từ khác để chỉ các loại tàu thuyền lớn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('颁', '{"9000": "2314.0", "Chữ Trung Quốc": "颁", "Bộ thủ & thành phần_Xie": "Bộ thủ | 頁 | Số nét | 10 | nét | 分 | phân | biểu âm | phân chia, phân phát | 页 | hiệt | biểu nghĩa | trang, đầu (bộ hiệt/kiến) | 颁 = 分 (Phân, biểu âm) + 页 (Hiệt, biểu nghĩa: đầu, trang); chữ hình thanh dạng giản thể của 頒. 分 cho âm ''bān'' (qua biến đổi lịch sử), bộ 頁 chỉ bậc vị — phân phát từ trên xuống, công bố chính thức.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ban\": phân (分) từ đầu (页) — ban (颁) là phân phát từ người đứng đầu xuống dưới, như ban hành chính sách hay trao tặng giải thưởng. | Gương Hán-Việt | ban trong ''ban bố'', ''ban hành'', ''ban phát'' | Mở khoá kiến thức | Biết 颁 (ban) mở khoá: 颁发 (trao tặng), 颁布 (ban hành, công bố), 颁奖 (trao giải).", "Tự nguyên_Xie": "颁 là dạng giản thể của 頒, trong đó 頁 giản thể thành 页. Wiktionary ghi đây là dạng rút gọn, tra về 頒 để thấy gốc. Cấu trúc hình thanh: 頁/页 (đầu, trang) biểu nghĩa chỉ tính chính thức từ bậc trên, 分 biểu âm. Nghĩa là ban phát, công bố chính thức (trao bằng khen, ban hành luật). | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ban bố ra, ban phát", "Hạng Tần Suất (Jun Da)": "2314.0", "Tần Suất % (Jun Da)": "98.0864629901", "GavinGrover_Once (Chiết tự trực tiếp)": "分 + 页", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰分页", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "分", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "页", "Unihan_Simplified (Chữ Giản thể)": "颁", "Unihan_Traditional (Chữ Phồn thể)": "頒", "Pinyin_Xie": "bān", "Âm Hán Việt_Xie": "ban", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ thường đứng trước danh từ làm tân ngữ để chỉ việc công bố hoặc trao tặng. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('惶', '{"9000": "2315.0", "Chữ Trung Quốc": "惶", "Bộ thủ & thành phần_Xie": "Bộ thủ | 心 | Số nét | 12 | nét | 忄 | tâm | biểu nghĩa | tim, tâm trạng | 皇 | hoàng | biểu âm | vua hoàng đế — âm huáng/hoàng | 惶 = 忄 (Tâm, biểu nghĩa: tim, cảm xúc) + 皇 (Hoàng, biểu âm); chữ hình thanh. Bộ 忄 chỉ đây là từ chỉ cảm xúc, phần 皇 cho âm huáng. Gốc nghĩa: sợ hãi, bối rối.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hoàng\": 忄 (tim) run rẩy trước 皇 (hoàng đế) — hoàng sợ là trạng thái tim đập nhanh khi đứng trước uy quyền tối cao. | Gương Hán-Việt | hoảng hốt (sợ hãi), bàng hoàng (choáng ngợp) | Mở khoá kiến thức | Biết 惶 mở khoá: bàng hoàng (彷惶/惶惶), hoảng hốt (慌惶), hoàng cụ (惶惶 — sợ hãi bất an), thành hoảng (诚惶诚恐).", "Tự nguyên_Xie": "惶 là chữ hình thanh: bộ 心/忄 (tâm, tim) biểu nghĩa, phần 皇 (hoàng) biểu âm — ls=psc. Wiktionary xác nhận 心 + 皇 (c1=s, c2=p). Nghĩa: sợ hãi, lo lắng bất an — trạng thái tim đập loạn như đứng trước uy quyền của hoàng đế. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "388.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Tâm (148) Hoàng (139)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Tâm (số 148 - tâm đứng) và chữ Hoàng (số 309 - vua) . Tâm trạng hoang mang, sợ sệt trước quyền uy của bề trên (vua chúa) gọi là hoàng (hoảng sợ). Giải thích sự chuyển ý: Chữ Hoàng (vua) vừa chỉ âm vừa gợi ý, chữ Tâm (lòng) chỉ ý. Sự kính sợ quyền lực tuyệt đối (Hoàng) sinh ra sự kinh hãi trong tâm trí (Tâm).", "Nghĩa Tiếng Việt_Xie": "sợ hãi", "Hạng Tần Suất (Jun Da)": "2315.0", "Tần Suất % (Jun Da)": "98.0889073838", "GavinGrover_Once (Chiết tự trực tiếp)": "忄 + 皇", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰忄皇", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "皇", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "忄", "Unihan_Simplified (Chữ Giản thể)": "惶", "Unihan_Traditional (Chữ Phồn thể)": "惶", "Pinyin_Xie": "huáng", "Âm Hán Việt_Xie": "hoàng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này làm tính từ thường kết hợp với các từ khác để miêu tả trạng thái tâm lý lo lắng. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('狐', '{"9000": "2316.0", "Chữ Trung Quốc": "狐", "Bộ thủ & thành phần_Xie": "Bộ thủ | 犬 | Số nét | 8 | nét | 犭 | khuyển | biểu nghĩa | thú vật (bộ chó) | 瓜 | qua | biểu âm | dưa hấu — âm guā/hú | 狐 = 犭 (Khuyển, biểu nghĩa: thú vật) + 瓜 (Qua, biểu âm); chữ hình thanh. Bộ 犭 chỉ đây là loài động vật có vú, phần 瓜 cho âm hú. 狐 chỉ con cáo — loài vật được coi là tinh quái trong văn hóa Á Đông.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hồ\": 犭 (thú) ăn dưa 瓜 — con cáo hồ ly tinh quái, khéo léo như kẻ trộm dưa ban đêm. | Gương Hán-Việt | hồ ly (cáo), hồ nghi (nghi ngờ) | Mở khoá kiến thức | Biết 狐 mở khoá: hồ ly (狐狸 — con cáo), hồ nghi (狐疑 — nghi ngờ, do dự), cáo tinh (狐狸精).", "Tự nguyên_Xie": "狐 là chữ hình thanh: bộ 犬/犭 (khuyển, thú) biểu nghĩa, phần 瓜 biểu âm — ls=psc. Wiktionary xác nhận 犬 + 瓜 (c1=s, c2=p). Gốc nghĩa: con cáo; văn hóa Trung Hoa coi cáo là linh vật biến hóa, tinh ranh — 狐狸精 (cáo tinh) là hình tượng phụ nữ quyến rũ dùng mưu mô. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con hồ ly, con cáo", "Hạng Tần Suất (Jun Da)": "2316.0", "Tần Suất % (Jun Da)": "98.0913455761", "GavinGrover_Once (Chiết tự trực tiếp)": "犭 + 瓜", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰犭瓜", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "瓜", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "犭", "Unihan_Simplified (Chữ Giản thể)": "狐", "Unihan_Traditional (Chữ Phồn thể)": "狐", "Pinyin_Xie": "hú", "Âm Hán Việt_Xie": "hồ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ con cáo, thường xuất hiện trong các từ ghép hoặc thành ngữ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('讽', '{"9000": "2317.0", "Chữ Trung Quốc": "讽", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 6 | nét | 讠 | ngôn | biểu nghĩa | lời nói (giản thể của 訁) | 风 | phong | biểu âm | gió (gần âm fěng) | 讽 là dạng giản thể của 諷 — hình thanh: 讠 (Ngôn, biểu nghĩa: lời nói) + 风 (Phong, biểu âm). Lời nói có ý châm chích, gốc nghĩa ''châm biếm, mỉa mai''.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phúng\": 讠 (lời nói) + 风 (gió) — lời nói theo gió chích vào người, đúng nghĩa ''châm biếm, mỉa mai'' trong 讽刺. | Gương Hán-Việt | ''phúng'' trong ''phúng dụ'', ''phúng thơ'' (ngâm thơ) | Mở khoá kiến thức | Nắm 讽 mở khoá từ HSK 5: 讽刺.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Theo Wiktionary, 讽 là giản thể của 諷 — hình thanh: 言/讠 (lời nói, biểu nghĩa) + 風/风 (Phong, biểu âm). Nghĩa gốc liên quan tới ''ngâm thơ, đọc to'' (讽诵), về sau chủ yếu mang nghĩa ''châm biếm, mỉa mai'' (讽刺). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chế giễu, cười nhạo", "Hạng Tần Suất (Jun Da)": "2317.0", "Tần Suất % (Jun Da)": "98.0937811844", "GavinGrover_Once (Chiết tự trực tiếp)": "讠 + 风", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰讠风", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "风", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "讠", "Unihan_Simplified (Chữ Giản thể)": "讽", "Unihan_Traditional (Chữ Phồn thể)": "諷", "Pinyin_Xie": "fěng", "Âm Hán Việt_Xie": "phúng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ thường dùng trong các từ ghép để chỉ hành vi châm biếm hoặc khuyên nhủ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('笨', '{"9000": "2318.0", "Chữ Trung Quốc": "笨", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 11 | nét | 竹 | trúc | biểu nghĩa | tre — phần ruột mộc của tre | 本 | bản | biểu âm | gợi âm ''bèn'' | 笨 = 竹 (Trúc, tre) + 本 (Bản, biểu âm). Chữ hình thanh: nghĩa gốc ''ruột mộc của tre'' (phần xốp bên trong), mượn dùng cho ''đần độn, ngu ngốc, chậm chạp, cồng kềnh''.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt ''Đần'': cây tre (竹) chỉ còn phần gốc (本) vô dụng — đó là ''đần'', là ngu, là vụng. | Gương Hán-Việt | Hán-Việt ''bản'' (do âm biểu âm); thường dịch sang tiếng Việt là ''đần, ngốc, vụng về''. | Mở khoá kiến thức | Biết 笨 mở khóa 笨拙 (bản chuyết / vụng về), 笨蛋 (bản đản / ngốc), 笨重 (bản trọng / nặng nề), 笨手笨脚 (vụng về).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 笨 là chữ hình thanh: 竹 biểu nghĩa, 本 biểu âm. Nghĩa gốc ''phần ruột mộc của thân tre'' (vô dụng). Sau mượn cho nghĩa ''đần độn, vụng về, nặng nề''. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đần, dốt, ngốc; chậm chạp, vụng về; cồng kềnh, cục kịch, nặng nề", "Hạng Tần Suất (Jun Da)": "2318.0", "Tần Suất % (Jun Da)": "98.096216276", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 本", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮本", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "本", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "笨", "Unihan_Traditional (Chữ Phồn thể)": "笨", "Pinyin_Xie": "bèn", "Âm Hán Việt_Xie": "bát", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này làm tính từ đứng trước danh từ để bổ nghĩa hoặc đứng sau phó từ chỉ mức độ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | bèn | / | ngốc | Xuất hiện trong lộ trình | New HSK | New HSK 4 | · | Bản tính | HSK | HSK 4 | · | Bản tính", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('袍', '{"9000": "2319.0", "Chữ Trung Quốc": "袍", "Bộ thủ & thành phần_Xie": "Bộ thủ | 衣 | Số nét | 10 | nét | 衤 | y | biểu nghĩa | áo, y phục (bộ y) | 包 | bao | biểu âm | bao, gói; bọc | 袍 = 衤(Y, biểu nghĩa: áo) + 包 (Bao, biểu âm); chữ hình thanh. 包 cho âm ''páo'', bộ 衣/衤chỉ y phục — chiếc áo dài bao phủ toàn thân.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bào\": áo (衤) bao (包) kín toàn thân — áo bào (袍) là áo dài rộng bao phủ từ vai đến chân, mặc trong nghi lễ cổ đại. | Gương Hán-Việt | bào trong ''long bào'', ''đạo bào'', ''chiến bào'' | Mở khoá kiến thức | Biết 袍 (bào) mở khoá: 旗袍 (xường xám), 龙袍 (áo long bào hoàng đế), 同袍 (chiến hữu).", "Tự nguyên_Xie": "Đại triện | Tiểu triện | Theo Wiktionary, 袍 là chữ hình thanh (psc): 衣/衤 (áo, y phục) là thành phần biểu nghĩa, 包 là thành phần biểu âm. Nghĩa là áo dài kiểu Trung Hoa bao phủ toàn thân (long gown, robe). Từ ghép nổi tiếng: 旗袍 (xường xám), 龙袍 (long bào của hoàng đế), 同袍 (chiến hữu, cùng áo chiến bào). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "áo bào, áo dài chấm gót", "Hạng Tần Suất (Jun Da)": "2319.0", "Tần Suất % (Jun Da)": "98.098650334", "GavinGrover_Once (Chiết tự trực tiếp)": "衤 + 包", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰衤包", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "包", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "衤", "Unihan_Simplified (Chữ Giản thể)": "袍", "Unihan_Traditional (Chữ Phồn thể)": "袍", "Pinyin_Xie": "páo", "Âm Hán Việt_Xie": "bào", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ các loại áo vạt dài thời xưa hoặc áo choàng rộng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('嘲', '{"9000": "2320.0", "Chữ Trung Quốc": "嘲", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 15 | nét | 口 | khẩu | biểu nghĩa | miệng, lời nói | 朝 | triều | biểu âm | triều đình; buổi sáng | 嘲 = 口 (Khẩu, biểu nghĩa: miệng) + 朝 (Triều, biểu âm); chữ hình thanh. 朝 cho âm ''cháo'', bộ 口 chỉ hành động phát ngôn — dùng lời (口) chế nhạo, giống như giọng điệu ''triều'' cười nhạo.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trào\": miệng (口) như triều đình (朝) — trào (嘲) là giọng điệu khinh thường, như bầy thần giễu cợt nhau trong triều. | Gương Hán-Việt | trào trong ''trào phúng'', ''tự trào'', ''giải trào'' | Mở khoá kiến thức | Biết 嘲 (trào) mở khoá: 嘲笑 (cười nhạo), 嘲讽 (châm biếm), 嘲弄 (giễu cợt), 自嘲 (tự chế nhạo).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 嘲 là chữ hình thanh (psc): 口 (miệng) là thành phần biểu nghĩa, 朝 là thành phần biểu âm. Nghĩa chính là chế nhạo, giễu cợt. Nghĩa thứ hai trong văn học: tiếng chim hót (zhāo). Thường xuất hiện trong 嘲笑 (cười nhạo), 嘲讽 (châm biếm), 嘲弄 (giễu cợt). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chế nhạo, cười nhạo", "Hạng Tần Suất (Jun Da)": "2320.0", "Tần Suất % (Jun Da)": "98.1010838752", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 朝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口朝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "朝", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "嘲", "Unihan_Traditional (Chữ Phồn thể)": "嘲", "Pinyin_Xie": "cháo", "Âm Hán Việt_Xie": "trào", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ thường kết hợp với các từ khác để chỉ hành vi cười nhạo. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('啡', '{"9000": "2321.0", "Chữ Trung Quốc": "啡", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 11 | nét | 口 | khẩu | biểu nghĩa | miệng – âm thanh, phiên âm tiếng nước ngoài | 非 | phi | biểu âm | phi – cho âm | 啡 = 口 (Khẩu, biểu nghĩa: miệng) + 非 (Phi, biểu âm); chữ hình thanh – âm tiết phiên âm, chuyên dùng trong 咖啡 (cà phê).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phê\": cái “miệng” 口 phát âm “phi” 非 – chính là 啡, một âm tiết phiên âm dùng trong 咖啡 (cà phê). | Gương Hán-Việt | “phê” mượn âm trực tiếp vào tiếng Việt: cà phê. | Mở khoá kiến thức | Biết 啡 mở khoá 咖啡, 咖啡馆, 吗啡 – các từ phiên âm hiện đại.", "Tự nguyên_Xie": "啡 là chữ hình thanh thuần: 口 (miệng) cho nghĩa “âm phát ra/uống” + 非 (phi) cho âm. Đây là chữ tạo muộn, gần như chỉ dùng để phiên âm: 咖啡 (cà phê – coffee), 吗啡 (mạ phê – morphine). Vì là chữ phiên âm hiện đại, không có trong giáp cốt/kim văn. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: già phê 咖啡); (xem: mạ phê 嗎啡,吗啡)", "Hạng Tần Suất (Jun Da)": "2321.0", "Tần Suất % (Jun Da)": "98.1035065639", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 非", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口非", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "非", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "啡", "Unihan_Traditional (Chữ Phồn thể)": "啡", "Pinyin_Xie": "fēi", "Âm Hán Việt_Xie": "phê", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này hầu như chỉ dùng làm danh từ liên kết trong các từ phiên âm như cà phê. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('泼', '{"9000": "2322.0", "Chữ Trung Quốc": "泼", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 8 | nét | 氵 | thuỷ | biểu nghĩa | nước | 发 | phát | biểu âm | gợi âm pō (giản thể của 發) | 泼 = 氵 (Thuỷ, biểu nghĩa: nước) + 发 (Phát, biểu âm); là dạng giản thể của 潑, chữ hình thanh. Hắt nước ra — ''tạt, hắt''.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bát\": 氵 (nước) + 发 (phát) — nước phát ra, ấy là ''bát'' (tạt); nhớ 活泼 (hoạt bát = sôi nổi), 泼冷水 (dội gáo nước lạnh). | Gương Hán-Việt | ''bát'' trong ''hoạt bát'' (活泼 sôi nổi), ''bát thuỷ'' (tạt nước) | Mở khoá kiến thức | Biết 泼 là mở 活泼, 泼冷水, 泼妇 — nhóm động từ và tính từ HSK 4-6.", "Tự nguyên_Xie": "Theo Wiktionary, 泼 là dạng giản thể của 潑 (giản hoá 發 thành 发). 潑 phồn thể là chữ hình thanh: 水 (biểu nghĩa: nước) ghép với 發 (biểu âm). Nghĩa: hắt nước, tạt; phái sinh ''mạnh bạo, sôi nổi'' (活泼), ''ngang ngược'' (撒泼). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "té, dội, hắt (nước); ngang ngược; xông xáo", "Hạng Tần Suất (Jun Da)": "2322.0", "Tần Suất % (Jun Da)": "98.1059292526", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 发", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵发", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "发", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "泼", "Unihan_Traditional (Chữ Phồn thể)": "潑", "Pinyin_Xie": "pō", "Âm Hán Việt_Xie": "bát", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Chữ này làm động từ chỉ hành động hắt nước hoặc làm tính từ chỉ tính cách đanh đá. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | Từ ghép nghĩa | 泼 thường dùng với hành động dội nước (泼水). 活泼 nghĩa là ''sôi nổi, lanh chan'', dùng miêu tả tính cách trẻ em hoặc người trẻ. | / | pō | / | đổ | Xuất hiện trong lộ trình | New HSK | New HSK 5 | · | Động từ | HSK | HSK 6 | · | Động từ hàng ngày", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('衔', '{"9000": "2323.0", "Chữ Trung Quốc": "衔", "Bộ thủ & thành phần_Xie": "Bộ thủ | 彳 | Số nét | 11 | nét | 彳 | xích | biểu hình | bước đi, hành động | 钅 | kim | biểu nghĩa | kim loại | 亍 | xúc | biểu hình | bước chân nhỏ | 衔 là dạng giản thể của 銜. Cấu trúc gốc là 銜: 金 (kim loại) + 行 (đường đi). Nghĩa gốc là chiếc hàm sắt gắn vào miệng ngựa (bit). Trong dạng giản thể, cấu trúc được tái tổ hợp thành 彳+ 钅+ 亍.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hàm\": kim loại (钅) ngậm trong miệng — hàm (衔) là hàm thiếc cho ngựa; mở rộng sang quân hàm, học hàm — những danh hiệu ''cắn chặt vào người''. | Gương Hán-Việt | hàm trong ''quân hàm'', ''học hàm'', ''đầu hàm'' | Mở khoá kiến thức | Biết 衔 (hàm) mở khoá: 衔接 (kết nối liền mạch), 头衔 (chức danh, tước vị), 军衔 (quân hàm).", "Tự nguyên_Xie": "Tiểu triện | 衔 là dạng giản thể của 銜. Wiktionary ghi đây là dạng rút gọn với 金/钅biểu nghĩa (kim loại). Nghĩa gốc là dây cương kim loại trong miệng ngựa (bit/bridle). Từ hình ảnh ''vật kim loại giữ trong miệng'' mà mở rộng sang: ngậm (động vật ngậm vật gì), danh hiệu (quân hàm, học hàm) — những thứ ''mang trên người'', và kết nối liền mạch (衔接). | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái hàm thiết ngựa; quan hàm, quân hàm, phẩm hàm; nuốt", "Hạng Tần Suất (Jun Da)": "2323.0", "Tần Suất % (Jun Da)": "98.1083498742", "GavinGrover_Once (Chiết tự trực tiếp)": "行 + 钅", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴行钅", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "钅", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "行", "Unihan_Simplified (Chữ Giản thể)": "衔", "Unihan_Traditional (Chữ Phồn thể)": "啣", "Pinyin_Xie": "xián", "Âm Hán Việt_Xie": "hàm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chữ này làm động từ chỉ hành động ngậm hoặc làm danh từ chỉ quân hàm, học vị. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('倦', '{"9000": "2324.0", "Chữ Trung Quốc": "倦", "Bộ thủ & thành phần_Xie": "Bộ thủ | 人 | Số nét | 10 | nét | 亻 | nhân | biểu nghĩa | người | 卷 | cuộn | biểu âm | cuộn, quyển sách | 倦 = 亻(Nhân, biểu nghĩa: người) + 卷 (Cuộn, biểu âm); chữ hình thanh. Trong hình thức Sở quốc (Chu state), dùng 龹 thay 卷, nhưng Tiểu triện đã dùng 卷. Người (亻) cuộn lại (卷) như muốn co ro — trạng thái mệt mỏi.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quyện\": người (亻) muốn cuộn (卷) lại — quyện mỏi (倦) là khi cơ thể muốn co lại như cuốn sách, quá mệt để tiếp tục. | Gương Hán-Việt | quyện trong ''quyện mỏi'', ''bất quyện'' (không mỏi) | Mở khoá kiến thức | Biết 倦 (quyện) mở khoá: 疲倦 (mệt mỏi), 厌倦 (chán nản), 孜孜不倦 (cần cù không biết mỏi).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Theo Wiktionary, 倦 là chữ hình thanh (psc): trong hình thức Sở quốc dùng 龹 (biểu âm) + 人 (người, biểu nghĩa); Tiểu triện dùng 卷 (biểu âm) + 人 (biểu nghĩa). Nghĩa là mệt mỏi, chán nản, kiệt sức. Thường dùng trong 疲倦 (mệt mỏi), 厌倦 (chán nản). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mệt mỏi", "Hạng Tần Suất (Jun Da)": "2324.0", "Tần Suất % (Jun Da)": "98.1107694622", "GavinGrover_Once (Chiết tự trực tiếp)": "亻 + 卷", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰亻卷", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "卷", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "亻", "Unihan_Simplified (Chữ Giản thể)": "倦", "Unihan_Traditional (Chữ Phồn thể)": "倦", "Pinyin_Xie": "juàn", "Âm Hán Việt_Xie": "quyện", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường làm vị ngữ hoặc định ngữ để miêu tả trạng thái mệt mỏi thể xác lẫn tinh thần. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('涵', '{"9000": "2325.0", "Chữ Trung Quốc": "涵", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 11 | nét | 氵 | thuỷ | biểu nghĩa | nước, chất lỏng | 函 | hàm | biểu âm | hộp đựng, thư từ; chứa đựng | 涵 = 氵(Thuỷ, biểu nghĩa: nước/chứa đựng) + 函 (Hàm, biểu âm); chữ hình thanh. 函 cho âm ''hán'', bộ 水/氵chỉ tính chất ngấm ướt, bao hàm — nước ngấm sâu, bao dung.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hàm\": nước (氵) chứa trong hộp (函) — hàm (涵) là bao hàm, chứa đựng ngầm bên trong như nước ngấm sâu vào đất. | Gương Hán-Việt | hàm trong ''nội hàm'', ''bao hàm'', ''hàm dưỡng'' | Mở khoá kiến thức | Biết 涵 (hàm) mở khoá: 内涵 (nội hàm, chiều sâu), 涵养 (tu dưỡng), 涵盖 (bao gồm), 涵洞 (cống thoát nước).", "Tự nguyên_Xie": "Giáp cốt văn | Đại triện | Tiểu triện | Theo Wiktionary, 涵 là chữ hình thanh (psc): 水/氵 (nước) là thành phần biểu nghĩa, 函 là thành phần biểu âm. Nghĩa gốc là ngâm ướt, thấm dần; mở rộng sang dung nạp, bao dung, chứa đựng; còn có nghĩa kỹ thuật là cống (culvert). Từ ghép phổ biến: 内涵 (nội hàm, hàm ý), 涵养 (dưỡng khí, tu dưỡng), 涵盖 (bao gồm hoàn toàn). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bao hàm; bao dung", "Hạng Tần Suất (Jun Da)": "2325.0", "Tần Suất % (Jun Da)": "98.1131885334", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "涵", "Unihan_Traditional (Chữ Phồn thể)": "涵", "Pinyin_Xie": "hán", "Âm Hán Việt_Xie": "hàm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường dùng làm động từ mang tân ngữ hoặc kết hợp cấu tạo từ ghép chỉ sự tu dưỡng, bao dung. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('雀', '{"9000": "2326.0", "Chữ Trung Quốc": "雀", "Bộ thủ & thành phần_Xie": "Bộ thủ | 隹 | Số nét | 11 | nét | 小 | tiểu | biểu nghĩa | nhỏ | 隹 | chuy | biểu nghĩa | chim đuôi ngắn | 雀 = 小 (Tiểu, biểu nghĩa: nhỏ) + 隹 (Chuy, biểu nghĩa: chim đuôi ngắn); chữ hội ý (ic). Wiktionary giải thích rõ: ''小 (nhỏ) + 隹 (chim) = chim nhỏ, chim sẻ''. Lưu ý: phần trên chữ trông giống 少 nhưng thực ra nét dưới của 少 là nét kéo dài của bộ 隹.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tước\": chim (隹) nhỏ (小) — tước (雀) là chim sẻ nhỏ xinh; ''tước'' cũng nghĩa là tước bỏ, cắt nhỏ. | Gương Hán-Việt | tước trong ''tước vị'', ''ma tước'' (chim sẻ) | Mở khoá kiến thức | Biết 雀 (tước) mở khoá: 麻雀 (chim sẻ), 鸦雀无声 (im lặng tuyệt đối), 孔雀 (con công).", "Tự nguyên_Xie": "Giáp cốt văn | Kim văn | Bạch thư | Theo Wiktionary, 雀 là chữ hội ý (ic): 小 (nhỏ) + 隹 (chim đuôi ngắn) = con chim nhỏ, chim sẻ. Wiktionary ghi chú thêm: ''In the current form, the upper part looks like 少, but what looks like the bottom stroke of 少 is actually the upper left stroke of 隹, extended.'' Đây là phân tích hội ý trực quan: chim nhỏ bé = chim sẻ. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1497.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Tiểu (011) Truy (034)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Tiểu (số 011 - nhỏ bé/ 小) ở trên bộ Truy (số 034 - con chim/ 隹). Giải thích sự chuyển ý: Đây là chữ Hội ý. Tước là con chim nhỏ, thường dùng để chỉ con chim sẻ (khổng tước, chim tước).", "Nghĩa Tiếng Việt_Xie": "con chim sẻ", "Hạng Tần Suất (Jun Da)": "2326.0", "Tần Suất % (Jun Da)": "98.1156045039", "GavinGrover_Once (Chiết tự trực tiếp)": "少 + 隹", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱少隹", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "少", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "隹", "Unihan_Simplified (Chữ Giản thể)": "雀", "Unihan_Traditional (Chữ Phồn thể)": "雀", "Pinyin_Xie": "què", "Âm Hán Việt_Xie": "tước", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ loài chim sẻ hoặc làm định ngữ trong các từ ghép liên quan đến chim. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('旬', '{"9000": "2327.0", "Chữ Trung Quốc": "旬", "Bộ thủ & thành phần_Xie": "Bộ thủ | 日 | Số nét | 6 | nét | 勹 | bao | biểu âm | bao bọc, ôm vào | 日 | nhật | biểu nghĩa | mặt trời, ngày | 旬 = 勹 (Bao, biểu âm) + 日 (Nhật, biểu nghĩa: ngày); chữ hình thanh. Theo Wiktionary, glyph cổ từ một chữ tượng hình về 螾 (con giun), sau thêm 日 (nhật: ngày) làm biểu nghĩa, 勹 là dạng đơn giản hóa của thành phần âm cổ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tuần\": ngày 日 (nhật) được bao 勹 (bao) bọc lại — 旬 là mười ngày, một tuần lịch cổ. | Gương Hán-Việt | tuần trong ''thượng tuần'' (đầu tháng), ''trung tuần'' (giữa tháng), ''hạ tuần'' (cuối tháng) | Mở khoá kiến thức | Biết 旬 (tuần) mở khoá: 上旬 (đầu tháng, ngày 1-10), 中旬 (giữa tháng, 11-20), 下旬 (cuối tháng, 21-30).", "Tự nguyên_Xie": "Giáp cốt văn | Kim văn | Tiểu triện | Theo Wiktionary, chữ tượng hình gốc 旬 trong giáp cốt chỉ chu kỳ mười ngày. Trong kim văn, thêm 日 (nhật: ngày) làm biểu nghĩa. Thành phần 勹 là dạng đơn giản của âm cổ bị hiểu nhầm trong thời Chiến Quốc. Nghĩa: một tuần theo lịch cổ Trung Quốc = 10 ngày. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "83.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Bao (24) Nhật (80)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Nhật (số 80) nằm trong chữ Bao (số 24) . Một tuần bao gồm nhiều ngày (lịch xưa 1 tuần = 10 ngày).", "Nghĩa Tiếng Việt_Xie": "sự lặp lại; tuần tuổi; 10 ngày", "Hạng Tần Suất (Jun Da)": "2327.0", "Tần Suất % (Jun Da)": "98.1180184072", "GavinGrover_Once (Chiết tự trực tiếp)": "勹 + 日", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴勹日", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "日", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "勹", "Unihan_Simplified (Chữ Giản thể)": "旬", "Unihan_Traditional (Chữ Phồn thể)": "旬", "Pinyin_Xie": "xún", "Âm Hán Việt_Xie": "tuần", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Lượng từ | 量词 | Thường làm danh từ chỉ khoảng thời gian mười ngày trong tháng hoặc mười năm trong tuổi tác. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Lượng từ | 量词 | Đứng giữa số từ (hoặc 这/那) và danh từ: 一杯茶, 这本书. Mỗi danh từ đi với lượng từ riêng; 个 là lượng từ dùng chung phổ biến nhất.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('僵', '{"9000": "2328.0", "Chữ Trung Quốc": "僵", "Bộ thủ & thành phần_Xie": "Bộ thủ | 人 | Số nét | 15 | nét | 亻 | nhân | biểu nghĩa | người | 畺 | cương | biểu âm | ranh giới, biên giới cứng nhắc | 僵 = 亻(Nhân, biểu nghĩa: người) + 畺 (Cương, biểu âm); cấu trúc hình thanh theo suy luận từ cấu trúc — Wiktionary không cung cấp lsCodes rõ ràng cho 僵. 畺 chỉ ranh giới cứng, bộ nhân 亻chỉ trạng thái người — người bị đông cứng như ranh giới.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cương\": người (亻) cứng như ranh giới (畺) — cương (僵) là đông cứng, bất động, hoặc tình trạng bế tắc không ai nhường ai. | Gương Hán-Việt | cương trong ''tử cương'' (chết cứng), ''cương cục'' (bế tắc) | Mở khoá kiến thức | Biết 僵 (cương) mở khoá: 僵硬 (cứng nhắc), 僵化 (trở nên cứng nhắc), 僵局 (bế tắc), 僵持 (giữ nguyên bế tắc).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Wiktionary không cung cấp glyphOrigin chi tiết cho 僵, chỉ có mục phát âm và định nghĩa. Cấu trúc gồm 亻(người) + 畺 (ranh giới cứng). Theo Wiktionary, nghĩa cổ là ngã xuống; nghĩa hiện đại là cứng đờ, bất động, bế tắc. Wiktionary dẫn giải từ Zhanguoce cho nghĩa ''ngã''. chưa có nguồn học thuật rõ ràng về glyph origin. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ngã; cứng", "Hạng Tần Suất (Jun Da)": "2328.0", "Tần Suất % (Jun Da)": "98.1204307603", "GavinGrover_Once (Chiết tự trực tiếp)": "亻 + 畺", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰亻畺", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "畺", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "亻", "Unihan_Simplified (Chữ Giản thể)": "僵", "Unihan_Traditional (Chữ Phồn thể)": "僵", "Pinyin_Xie": "jiāng", "Âm Hán Việt_Xie": "cương", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường làm tính từ miêu tả trạng thái co cứng của cơ thể hoặc tình thế bế tắc không tiến triển. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | jiāng | / | cứng | / | jiāng | / | bế tắc | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Tính chất vật lý | New HSK 7-9 | · | Nỗi khó khăn", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('撕', '{"9000": "2329.0", "Chữ Trung Quốc": "撕", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 15 | nét | 扌 | thủ | biểu nghĩa | tay | 斯 | tư | biểu âm | đây, thế này | 撕 = 扌 (Thủ, biểu nghĩa: tay) + 斯 (Tư, biểu âm); chữ hình thanh. Bộ 扌 cho nghĩa hành động bằng tay, 斯 cho âm (sī ~ tư). Hành động dùng hai tay kéo giật ngược chiều để xé.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tê\": tay 扌 (thủ) theo kiểu tư 斯 (tê) — xé 撕 là dùng hai tay tê tê kéo ngược chiều. | Gương Hán-Việt | tê trong ''撕裂 tê liệt'' (xé toạc, rách) | Mở khoá kiến thức | Biết 撕 (tê) mở khoá: 撕开 (xé ra), 撕裂 (xé toạc), 撕碎 (xé vụn).", "Tự nguyên_Xie": "Theo cấu trúc chữ, 撕 là chữ hình thanh: 手 (thủ, biểu nghĩa: tay) + 斯 (tư, biểu âm). Chữ tạo muộn để chỉ hành động xé bằng tay. Chưa thấy glyph cổ trong giáp cốt hay kim văn; chữ tạo muộn, chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "xé, gỡ; thức tỉnh; xoa xát", "Hạng Tần Suất (Jun Da)": "2329.0", "Tần Suất % (Jun Da)": "98.1228431133", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 斯", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌斯", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "斯", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "撕", "Unihan_Traditional (Chữ Phồn thể)": "撕", "Pinyin_Xie": "sī", "Âm Hán Việt_Xie": "ti", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ vị ngữ biểu thị hành động dùng tay xé rách giấy, vải hoặc các vật liệu mềm. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | Từ đơn | Từ vựng HSK 5: xé | / | sī | / | xé | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Động từ tôi | HSK | HSK 5 | · | Động từ hàng ngày", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('肢', '{"9000": "2330.0", "Chữ Trung Quốc": "肢", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 8 | nét | 月 | nguyệt | biểu nghĩa | thịt, cơ thể (bộ nhục viết như nguyệt) | 支 | chi | biểu âm | nhánh, chi, hỗ trợ | 肢 = 月/肉 (Nhục, biểu nghĩa: thịt/cơ thể) + 支 (Chi, biểu âm); chữ hình thanh. 支 cho âm ''zhī'', bộ 肉/月 chỉ bộ phận cơ thể — chi thể, tứ chi của người và động vật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chi\": thịt (月) như nhánh cành (支) — chi (肢) là tứ chi, bốn chi tay chân như bốn nhánh của thân cây. | Gương Hán-Việt | chi trong ''tứ chi'', ''chi thể'' | Mở khoá kiến thức | Biết 肢 (chi) mở khoá: 四肢 (tứ chi), 肢体 (chi thể), 上肢 (chi trên = tay), 下肢 (chi dưới = chân).", "Tự nguyên_Xie": "Đại triện | Theo Wiktionary, 肢 là chữ hình thanh (psc): 肉/⺼ (thịt, bộ phận cơ thể) là thành phần biểu nghĩa, 支 là thành phần biểu âm. Nghĩa là chi thể — tay, chân của người; chân của động vật. Thường dùng trong 四肢 (tứ chi), 肢体 (chi thể). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chân tay", "Hạng Tần Suất (Jun Da)": "2330.0", "Tần Suất % (Jun Da)": "98.1252466809", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 支", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月支", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "支", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "肢", "Unihan_Traditional (Chữ Phồn thể)": "肢", "Pinyin_Xie": "zhī", "Âm Hán Việt_Xie": "chi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường kết hợp với các từ khác để chỉ các chi của người hoặc động vật. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('垄', '{"9000": "2331.0", "Chữ Trung Quốc": "垄", "Bộ thủ & thành phần_Xie": "Bộ thủ | 龍 | Số nét | 8 | nét | 龙 | long | biểu âm | rồng | 土 | thổ | biểu nghĩa | đất | 垄 = 龙 (Long, biểu âm) + 土 (Thổ, biểu nghĩa: đất); chữ hình thanh. Bộ Thổ chỉ ý nghĩa đất đai, Long cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lũng\": hình ảnh con Rồng (龙) nằm cuộn mình trên mặt đất (土) như luống cày dài — ai kiểm soát luống đó thì độc quyền. | Gương Hán-Việt | \"lũng\" trong từ \"lung lạc\" (lay chuyển, kiểm soát); \"垄断\" = lũng đoạn = độc quyền | Mở khoá kiến thức | Biết 垄 (lũng) mở khoá: 垄断 (lũng đoạn — độc quyền), 丘垄 (khâu lũng — gò mả).", "Tự nguyên_Xie": "垄 là dạng giản thể của 壟. Theo Wiktionary, chữ này ghép 龍 (biểu âm) và 土 (biểu nghĩa: đất) theo kiểu hình thanh. Nghĩa gốc là luống đất được vun cao trên ruộng, hoặc nấm mộ đắp đất. Từ đó mở rộng sang nghĩa độc quyền (垄断 — chiếm đoạt đỉnh luống, kiểm soát toàn bộ). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "luống cày", "Hạng Tần Suất (Jun Da)": "2331.0", "Tần Suất % (Jun Da)": "98.1276455975", "GavinGrover_Once (Chiết tự trực tiếp)": "龙 + 土", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱龙土", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "土", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "龙", "Unihan_Simplified (Chữ Giản thể)": "垄", "Unihan_Traditional (Chữ Phồn thể)": "壟", "Pinyin_Xie": "lǒng", "Âm Hán Việt_Xie": "lũng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ luống đất trồng trọt hoặc gò đất cao ngoài đồng ruộng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('夷', '{"9000": "2332.0", "Chữ Trung Quốc": "夷", "Bộ thủ & thành phần_Xie": "Bộ thủ | 大 | Số nét | 6 | nét | 大 | đại | biểu ý | người, lớn | 弓 | cung | biểu ý | cung tên | 夷 là chữ hội ý: ban đầu từ 矢 (tên) + 弓 (cung) — hành động bắn tên; sau đó diễn biến thành 大 (người) + 弓 (cung) — người cầm cung. Wiktionary ghi hai giai đoạn: gốc là hội ý 矢+弓 (ic), sau là hội ý 大+弓 (ic).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"di\": 大 (người) cầm 弓 (cung) — người Di cung thiện xạ, sau chỉ các dân tộc bên ngoài Hoa Hạ. | Gương Hán-Việt | di địch (các tộc ngoài Hoa Hạ), di hại (phá bình địa) | Mở khoá kiến thức | Biết 夷 mở khoá: Đông Di (东夷 — tộc phương Đông), hóa hiểm vi di (化险为夷 — thoát hiểm), tứ di (四夷 — tứ phương man di).", "Tự nguyên_Xie": "夷 ban đầu là hội ý 矢 (tên) + 弓 (cung), nghĩa gốc là ''bắn tên''. Wiktionary xác nhận ls=ic (hai lần). Về sau dạng chữ đổi thành 大+弓. Từ nghĩa ''người bắn cung'', 夷 chỉ các tộc người phương Đông (Đông Di) — những người cầm cung thiện xạ. Nghĩa mở rộng: san bằng, bình phẳng; người man di (khinh thị). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mọi rợ; công bằng; bị thương; giết hết (khi bị tội, giết 3 họ hay 9 họ)", "Hạng Tần Suất (Jun Da)": "2332.0", "Tần Suất % (Jun Da)": "98.130042447", "GavinGrover_Once (Chiết tự trực tiếp)": "大 + 弓", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴大弓", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "弓", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "大", "Unihan_Simplified (Chữ Giản thể)": "夷", "Unihan_Traditional (Chữ Phồn thể)": "夷", "Pinyin_Xie": "yí", "Âm Hán Việt_Xie": "di", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Danh từ | 名词 | Thường làm động từ với nghĩa san bằng, tiêu diệt hoặc làm tính từ chỉ sự bằng phẳng, an bình. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('逸', '{"9000": "2333.0", "Chữ Trung Quốc": "逸", "Bộ thủ & thành phần_Xie": "Bộ thủ | 辵 | Số nét | 11 | nét | 辶 | sước | biểu nghĩa | đi lại, đường | 兔 | thỏ | biểu ý | con thỏ — chạy nhanh, thoát đi | 逸 = 辶 (Sước, biểu nghĩa: đi, chuyển động) + 兔 (Thỏ, biểu ý: chạy trốn nhanh); chữ hội ý. Wiktionary xác nhận ls=ic (hội ý): 辵+兔 — thỏ chạy trốn. Gốc nghĩa: chạy thoát, trốn; nghĩa mở rộng: an nhàn, thoải mái (như thỏ tự do).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"dật\": 辶 (đường đi) + 兔 (thỏ) — thỏ dật đã bỏ chạy mất rồi, như cuộc sống dật dào tự do không ràng buộc. | Gương Hán-Việt | dật lạc (an nhàn, thoải mái), ẩn dật (ở ẩn) | Mở khoá kiến thức | Biết 逸 mở khoá: an dật (安逸 — an nhàn), ẩn dật (隐逸 — ở ẩn), dật văn (逸文 — văn thất truyền), tuấn dật (俊逸 — xuất chúng).", "Tự nguyên_Xie": "逸 là chữ hội ý: 辵 (đi) + 兔 (thỏ) — hình ảnh thỏ bỏ chạy. Wiktionary xác nhận hai giai đoạn (ls=ic): gốc là 止+㚔 (giáp cốt), sau là 辵+兔. Nghĩa gốc: chạy trốn, bỏ đi; nghĩa mở rộng: tự do, an nhàn, dật lạc; cũng có nghĩa ''bị thất lạc, bị bỏ sót'' (dật văn = văn bản mất). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lầm lỗi; ẩn dật; nhàn rỗi; buông thả", "Hạng Tần Suất (Jun Da)": "2333.0", "Tần Suất % (Jun Da)": "98.1324392964", "GavinGrover_Once (Chiết tự trực tiếp)": "辶 + 兔", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴辶兔", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "兔", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "辶", "Unihan_Simplified (Chữ Giản thể)": "逸", "Unihan_Traditional (Chữ Phồn thể)": "逸", "Pinyin_Xie": "yì", "Âm Hán Việt_Xie": "dật", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường làm tính từ miêu tả trạng thái nhàn nhã, tự tại hoặc làm động từ chỉ sự trốn chạy, thoát ra. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('茅', '{"9000": "2334.0", "Chữ Trung Quốc": "茅", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 8 | nét | 艹 | thảo | biểu nghĩa | cỏ, thực vật | 矛 | mâu | biểu âm | ngọn giáo — âm máo/mâu | 茅 = 艹 (Thảo, biểu nghĩa: cỏ, thực vật) + 矛 (Mâu, biểu âm); chữ hình thanh. Bộ 艹 chỉ đây là loài thực vật, phần 矛 cho âm máo. 茅 là cỏ tranh — loại cỏ lá nhọn như ngọn giáo.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mao\": 艹 (cỏ) nhọn như 矛 (giáo) — cỏ tranh mao lá sắc như giáo, thuở xưa lợp nhà dân nghèo. | Gương Hán-Việt | mao ốc (nhà tranh), mao đài (Mao Đài — rượu nổi tiếng) | Mở khoá kiến thức | Biết 茅 mở khoá: mao ốc (茅屋 — nhà tranh), Mao Đài (茅台 — rượu Quý Châu), khai mao tắc (开茅塞 — mở mang trí tuệ).", "Tự nguyên_Xie": "茅 là chữ hình thanh: bộ 艸/艹 (thảo, cỏ) biểu nghĩa, phần 矛 biểu âm — ls=psc. Wiktionary xác nhận 艸 + 矛 (c1=s, c2=p). Gốc nghĩa: cỏ tranh (Imperata cylindrica) — loài cỏ lá nhọn sắc như mũi giáo; dùng để lợp mái nhà trong dân gian Trung Quốc và Việt Nam xưa. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1151.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thảo (028) Mâu (1150)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Thảo (số 028 - cỏ) ở trên chữ Mâu (số 1150 - cây giáo/chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Mâu chỉ âm, bộ Thảo chỉ ý. Mao là cây cỏ tranh, cỏ nhô lên nhọn như mũi giáo (lều mao, mao ốc).", "Nghĩa Tiếng Việt_Xie": "cỏ lợp nhà, cỏ tranh; họ Mao; núi Mao", "Hạng Tần Suất (Jun Da)": "2334.0", "Tần Suất % (Jun Da)": "98.1348356291", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 矛", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹矛", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "矛", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "茅", "Unihan_Traditional (Chữ Phồn thể)": "茅", "Pinyin_Xie": "máo", "Âm Hán Việt_Xie": "mao", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ cỏ tranh hoặc làm định ngữ để chỉ những thứ đơn sơ, mộc mạc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('侨', '{"9000": "2335.0", "Chữ Trung Quốc": "侨", "Bộ thủ & thành phần_Xie": "Bộ thủ | 人 | Số nét | 8 | nét | 亻 | nhân | biểu nghĩa | người | 乔 | kiều | biểu âm | cao, kiều | 侨 = 亻(Nhân, biểu nghĩa: người) + 乔 (Kiều, biểu âm); chữ hình thanh. Bộ Nhân chỉ đây là từ liên quan đến người, 乔 cho âm kiều.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"kiều\": người (亻) sống cao hơn quê hương (乔 = cao) — hình ảnh người Việt kiều xa xứ, sống trên đất người. | Gương Hán-Việt | \"kiều\" trong \"Việt kiều\" (người Việt ở nước ngoài), \"kiều bào\" (đồng bào ở nước ngoài) | Mở khoá kiến thức | Biết 侨 (kiều) mở khoá: 华侨 (hoa kiều — người Hoa ở nước ngoài), 侨居 (kiều cư — sống ở nước ngoài), 归侨 (quy kiều — Hoa kiều hồi hương).", "Tự nguyên_Xie": "Đại triện | Tiểu triện | 侨 là dạng giản thể của 僑. Chữ gốc 僑 dùng 喬 (âm kiều, nghĩa: cao) làm âm phù, bộ Nhân 亻 làm nghĩa phù. Người sống ở nơi xa quê (cư ngụ tạm thời) được gọi là kiều — như người ngụ cư ở nơi đất khách. Từ đây sinh ra các từ như 华侨 (người Hoa ở nước ngoài), 侨居 (kiều cư). | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ở nhờ, đi ở nơi khác; kiều dân", "Hạng Tần Suất (Jun Da)": "2335.0", "Tần Suất % (Jun Da)": "98.1372298946", "GavinGrover_Once (Chiết tự trực tiếp)": "亻 + 乔", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰亻乔", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "乔", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "亻", "Unihan_Simplified (Chữ Giản thể)": "侨", "Unihan_Traditional (Chữ Phồn thể)": "僑", "Pinyin_Xie": "qiáo", "Âm Hán Việt_Xie": "kiều", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường làm danh từ chỉ người sống ở nước ngoài hoặc làm động từ chỉ việc cư trú tạm thời. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('舆', '{"9000": "2336.0", "Chữ Trung Quốc": "舆", "Bộ thủ & thành phần_Xie": "Bộ thủ | 八 | Số nét | 14 | nét | 𦥑 | biểu hình | hai bàn tay (hình dạng) | 八 | bát | biểu hình | tám, phân kỳ | 车 | xa | biểu nghĩa | xe | 舆 = tay người (𦥑) + tám/phân kỳ (八) + xa (车 — xe); chữ hội ý theo giáp cốt văn. Hình ảnh nhiều bàn tay cùng khiêng/đẩy một chiếc xe — gợi ý chiếc kiệu hay xe chở người. lsCodes trống nên phân tích dựa trên cấu trúc hình vẽ cổ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"dư\": nhiều tay người (𦥑) cùng đẩy xe (车) — \"dư luận\" là tiếng nói của đám đông, nhiều bàn tay cùng chuyển tải ý kiến. | Gương Hán-Việt | \"dư\" trong \"dư luận\" (舆论 — tiếng nói công chúng), \"dư địa\" (舆地 — bản đồ đất đai) | Mở khoá kiến thức | Biết 舆 (dư) mở khoá: 舆论 (dư luận — public opinion), 舆图 (dư đồ — bản đồ).", "Tự nguyên_Xie": "Giáp cốt văn | Tiểu triện | Lục thư thông | 舆 là dạng giản thể của 輿. Giáp cốt văn cho thấy hình ảnh nhiều bàn tay (𦥑) khiêng chiếc xe (車). Nghĩa gốc là cái kiệu hoặc xe chở người do nhiều người khiêng. Từ đó mở rộng sang nghĩa \"đám đông, công chúng\" (舆论 — dư luận, tiếng nói của nhiều người), rồi nghĩa \"trái đất, thiên hạ\" (舆地). | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "xe chở đồ; trời đất", "Hạng Tần Suất (Jun Da)": "2336.0", "Tần Suất % (Jun Da)": "98.1396215762", "GavinGrover_Once (Chiết tự trực tiếp)": "No glyph available + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "舆", "Unihan_Traditional (Chữ Phồn thể)": "輿", "Pinyin_Xie": "yú", "Âm Hán Việt_Xie": "dư", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này thường làm danh từ trong các từ ghép chỉ dư luận xã hội hoặc bản đồ, địa dư. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('窑', '{"9000": "2337.0", "Chữ Trung Quốc": "窑", "Bộ thủ & thành phần_Xie": "Bộ thủ | 穴 | Số nét | 11 | nét | 穴 | huyệt | biểu nghĩa | hang, hố | 缶 | phữu | biểu ý | bình gốm, đồ đất nung | 窑 = 穴 (Huyệt, biểu nghĩa: hang, hố) + 羔 (biểu âm, thực tế theo Wiktionary — ls=psc: 穴+羔, c1=s, c2=p). Dạng hiện tại gồm 穴 + 缶 (bình gốm). Gốc nghĩa: hang đất dùng để nung gốm — lò nung.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"diêu\": 穴 (hang) để nung 缶 (bình gốm) — lò diêu là hang đất đặc biệt để nung gốm sứ từ ngàn xưa. | Gương Hán-Việt | lò diêu (lò nung gốm), diêu nghệ (nghề gốm) | Mở khoá kiến thức | Biết 窑 mở khoá: diêu (窑 — lò nung), vật diêu (瓦窑 — lò gạch ngói), than diêu (炭窑 — lò than), dầu diêu (油窑).", "Tự nguyên_Xie": "窑 là chữ hình thanh: bộ 穴 (huyệt, hang) biểu nghĩa ''hố, lò'', phần 羔 biểu âm — ls=psc. Wiktionary xác nhận 穴+羔 (c1=s, c2=p). Gốc nghĩa: hố hang dùng để nung đồ gốm. Chữ tạo để chỉ một công nghệ trọng yếu của Trung Quốc cổ đại: lò nung đồ gốm sứ. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái lò nung; đồ sành sứ", "Hạng Tần Suất (Jun Da)": "2337.0", "Tần Suất % (Jun Da)": "98.1420044725", "GavinGrover_Once (Chiết tự trực tiếp)": "穴 + 缶", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱穴缶", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "缶", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "穴", "Unihan_Simplified (Chữ Giản thể)": "窑", "Unihan_Traditional (Chữ Phồn thể)": "窯", "Pinyin_Xie": "yáo", "Âm Hán Việt_Xie": "dao", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ các loại lò nung gốm sứ hoặc hang động đào để ở. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | yáo | / | lò nung | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Sản xuất và công nghiệp", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('涅', '{"9000": "2338.0", "Chữ Trung Quốc": "涅", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 10 | nét | 氵 | thuỷ | biểu nghĩa | nước | 日 | nhật | biểu ý | mặt trời | 土 | thổ | biểu ý | đất | 涅 = 氵 (Thuỷ, biểu nghĩa: nước) + 圼 (gồm 日+土, biểu ý/âm); chữ hội ý kiêm hình thanh (ls=ic, ls2=psc theo Wiktionary). Bộ 氵 chỉ nước, phần 土 chỉ đất — bùn đen dưới nước. Gốc nghĩa: bùn đen, đất đen dưới nước; dùng để nhuộm màu đen.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"niết\": 氵 (nước) + 土 (đất) + 日 — bùn đất đen ngâm trong nước, như bùn lầy; Niết Bàn (涅槃) là trạng thái thoát ra khỏi bùn lầy sinh tử. | Gương Hán-Việt | niết bàn (Nirvana — giải thoát), niết như nê (涅而不缁 — nhuộm không đen được) | Mở khoá kiến thức | Biết 涅 mở khoá: Niết Bàn (涅槃 — Nirvana trong Phật giáo), niết như nê (涅而不缁 — thành ngữ: không bị tha hóa dù trong môi trường xấu).", "Tự nguyên_Xie": "涅 là chữ hội ý kiêm hình thanh: bộ 氵 (thuỷ, nước) + 土 (thổ, đất) + 日 (nhật, mặt trời) — ls=ic và ls2=psc. Wiktionary xác nhận c1=s (nước), c2=s (đất), c3=p. Gốc nghĩa: bùn đen dưới nước, khoáng chất đen dùng nhuộm; 涅槃 (Niết Bàn) là phiên âm Sanskrit ''nirvāṇa''. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nhuộm đen", "Hạng Tần Suất (Jun Da)": "2338.0", "Tần Suất % (Jun Da)": "98.1443822009", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 圼", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵圼", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "圼", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "涅", "Unihan_Traditional (Chữ Phồn thể)": "涅", "Pinyin_Xie": "niè", "Âm Hán Việt_Xie": "niết", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chữ này chủ yếu làm động từ chỉ việc nhuộm đen hoặc dùng trong thuật ngữ Phật giáo Niết bàn. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蒲', '{"9000": "2339.0", "Chữ Trung Quốc": "蒲", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 13 | nét | 艹 | thảo | biểu nghĩa | cỏ, thực vật | 浦 | phổ | biểu âm | bờ sông — âm pǔ/bồ | 蒲 = 艹 (Thảo, biểu nghĩa: thực vật) + 浦 (Phổ, biểu âm); chữ hình thanh. Bộ 艹 chỉ đây là loài thực vật, phần 浦 cho âm pú. 蒲 là cây bồ (Typha) — cỏ thủy sinh mọc ở bờ ao, đầm lầy.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bồ\": 艹 (cỏ) mọc ven 浦 (bờ nước) — cỏ bồ ven hồ, dân gian đan chiếu bồ từ ngàn đời. | Gương Hán-Việt | bồ đoàn (nệm cỏ ngồi thiền), bồ lưu (sắn dây) | Mở khoá kiến thức | Biết 蒲 mở khoá: bồ đoàn (蒲团 — nệm ngồi thiền), bồ tát (菩萨 — Bodhisattva, nhưng khác chữ), Bồ Điền (蒲田 — địa danh), quạt bồ (蒲扇).", "Tự nguyên_Xie": "蒲 là chữ hình thanh: bộ 艸/艹 (thảo) biểu nghĩa, phần 浦 biểu âm — ls=psc. Wiktionary xác nhận 艸 + 浦 (c1=s, c2=p). Gốc nghĩa: cây bồ (cói, lác) — loài cỏ nước thường mọc ở bờ hồ, ao đầm; dùng đan chiếu, làm đồ thủ công. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cỏ bồ", "Hạng Tần Suất (Jun Da)": "2339.0", "Tần Suất % (Jun Da)": "98.1467568286", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 浦", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹浦", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "浦", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "蒲", "Unihan_Traditional (Chữ Phồn thể)": "蒲", "Pinyin_Xie": "pú", "Âm Hán Việt_Xie": "bồ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ các loại cây thuộc họ bồ hoàng hoặc các vật dụng làm từ cỏ bồ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('谦', '{"9000": "2340.0", "Chữ Trung Quốc": "谦", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 12 | nét | 讠 | biểu nghĩa | bộ ngôn (lời nói) | 兼 | kiêm | biểu âm | kiêm nhiệm, đồng thời | 谦 = 讠/言 (Ngôn, biểu nghĩa: lời nói) + 兼 (Kiêm, biểu âm); chữ hình thanh. Bộ 讠 cho nghĩa liên quan đến lời nói, 兼 cho âm (qiān ~ khiêm). Lời nói khiêm tốn, không kiêu ngạo.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khiêm\": lời nói 讠 (ngôn) kiêm 兼 (kiêm) nhường nhịn — 谦 là khiêm tốn, nói năng nhún nhường. | Gương Hán-Việt | khiêm trong ''khiêm tốn'' (謙虛), ''khiêm nhường'' | Mở khoá kiến thức | Biết 谦 (khiêm) mở khoá: 谦虚 (khiêm tốn), 谦逊 (khiêm nhường), 谦让 (nhường nhịn).", "Tự nguyên_Xie": "Theo Wiktionary, 谦 (phồn thể 謙) là chữ hình thanh (psc): 言 (ngôn, biểu nghĩa: lời nói) + 兼 (kiêm, biểu âm). Chữ biểu đạt trạng thái cung kính, khiêm tốn trong lời nói và thái độ. Nguồn dẫn Digital Shinjigen. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nhún nhường", "Hạng Tần Suất (Jun Da)": "2340.0", "Tần Suất % (Jun Da)": "98.1491278388", "GavinGrover_Once (Chiết tự trực tiếp)": "讠 + 兼", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰讠兼", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "兼", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "讠", "Unihan_Simplified (Chữ Giản thể)": "谦", "Unihan_Traditional (Chữ Phồn thể)": "謙", "Pinyin_Xie": "qiān", "Âm Hán Việt_Xie": "khiêm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này làm tính từ bổ nghĩa cho danh từ hoặc đứng sau phó từ chỉ mức độ để thể hiện sự khiêm nhường. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('杭', '{"9000": "2341.0", "Chữ Trung Quốc": "杭", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 8 | nét | 木 | mộc | biểu nghĩa | gỗ, cây | 亢 | kháng | biểu âm | can đảm, cứng — âm kàng/háng | 杭 = 木 (Mộc, biểu nghĩa: gỗ) + 亢 (Kháng, biểu âm); chữ hình thanh. Bộ 木 chỉ đây gốc là vật gỗ (cọc gỗ qua sông), phần 亢 cho âm háng. 杭 chủ yếu là tên địa danh — Hàng Châu.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hàng\": 木 (gỗ) vươn 亢 (cao, vững) — cây cầu gỗ bắc qua sông Tiền Đường dẫn vào Hàng Châu hoa lệ. | Gương Hán-Việt | Hàng Châu (thành phố thiên đường), hàng trình (hành trình qua sông) | Mở khoá kiến thức | Biết 杭 mở khoá: Hàng Châu (杭州 — cố đô Nam Tống), hàng kế (杭州丝绸 — lụa Hàng), Hàng Chuyết Đường (tiểu thuyết nổi tiếng).", "Tự nguyên_Xie": "杭 là chữ hình thanh: bộ 木 (mộc) biểu nghĩa, phần 亢 biểu âm — ls=psc. Wiktionary ghi ban đầu là biến thể của 抗 (kháng cự). Gốc nghĩa: gỗ bắc qua sông, thuyền gỗ; nghĩa mở rộng: qua sông. Ngày nay 杭 chủ yếu là tên thành phố Hàng Châu (杭州) — cố đô thời Nam Tống. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái xuồng (như: 航); châu Hàng (Trung Quốc)", "Hạng Tần Suất (Jun Da)": "2341.0", "Tần Suất % (Jun Da)": "98.1514962651", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 亢", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木亢", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "亢", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "杭", "Unihan_Traditional (Chữ Phồn thể)": "杭", "Pinyin_Xie": "háng", "Âm Hán Việt_Xie": "hàng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này chủ yếu làm danh từ riêng chỉ địa danh Hàng Châu hoặc làm động từ cổ chỉ việc vượt sông. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('噢', '{"9000": "2342.0", "Chữ Trung Quốc": "噢", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 15 | nét | 口 | khẩu | biểu nghĩa | miệng, tiếng phát ra | 奥 | ảo | biểu âm | thâm sâu — âm ào/ō | 噢 = 口 (Khẩu, biểu nghĩa: miệng, âm thanh) + 奥 (Ảo, biểu âm); chữ hình thanh. Bộ 口 chỉ đây là âm thanh phát ra từ miệng, phần 奥 cho âm ō. 噢 là thán từ biểu thị sự hiểu ra, ngạc nhiên.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"úc\": 口 (miệng) + 奥 (sâu kín) — tiếng ''ồ!'' thoát ra khi bỗng hiểu điều sâu kín; thán từ bộc phát. | Gương Hán-Việt | thán từ úc/ồ (tiếng kêu ngạc nhiên hay hiểu ra) | Mở khoá kiến thức | 噢 dùng chủ yếu như thán từ: 噢，我明白了 (Ồ, tôi hiểu rồi). Không có từ ghép phổ biến.", "Tự nguyên_Xie": "噢 là chữ hình thanh tạo muộn: bộ 口 (khẩu, miệng) biểu nghĩa, phần 奥 biểu âm. Wiktionary không có phân tích chi tiết lsCodes cho chữ này. Đây là chữ tạo muộn, dùng để ghi thán từ — tiếng ''ồ'' khi ngạc nhiên hay vừa hiểu ra. Chưa thấy trong giáp cốt/kim văn. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nhé; nhá; nha", "Hạng Tần Suất (Jun Da)": "2342.0", "Tần Suất % (Jun Da)": "98.1538641745", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 奥", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口奥", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "奥", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "噢", "Unihan_Traditional (Chữ Phồn thể)": "噢", "Pinyin_Xie": "ō", "Âm Hán Việt_Xie": "úc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Thán từ | 叹词 | Chữ này làm thán từ đứng đầu câu để biểu thị sự hiểu ra hoặc ngạc nhiên. | Thán từ | 叹词 | Bộc lộ cảm xúc hoặc dùng để gọi đáp: 啊, 哦, 喂. Đứng tách riêng ở đầu câu, không làm thành phần câu.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('弊', '{"9000": "2343.0", "Chữ Trung Quốc": "弊", "Bộ thủ & thành phần_Xie": "Bộ thủ | 廾 | Số nét | 14 | nét | 敝 | tệ | biểu âm | rách nát, tệ hại | 廾 | củng | biểu nghĩa | hai bàn tay | 弊 = 敝 (Tệ, biểu âm: rách nát) + 廾 (Củng, biểu nghĩa: hai bàn tay); chủ yếu là hình thanh nhưng có yếu tố hội ý. Theo Wiktionary, đây là dạng nhấn mạnh của 敝 — hai tay cùng phá huỷ vật gì, gợi ý gian lận, tệ hại.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tệ\": hai tay (廾) cùng phá nát (敝) mọi thứ — \"tệ nạn\" chính là cái do tay người tạo ra mà hư hỏng. | Gương Hán-Việt | \"tệ\" trong \"tệ nạn\" (弊端), \"lợi tệ\" (lợi ích và bất lợi), \"tệ hại\" (xấu xa) | Mở khoá kiến thức | Biết 弊 (tệ) mở khoá: 作弊 (tác tệ — gian lận), 弊病 (tệ bệnh — nhược điểm), 利弊 (lợi tệ — lợi và hại).", "Tự nguyên_Xie": "Theo Wiktionary, 弊 là dạng nhấn mạnh của 敝 (rách nát, phá huỷ). Chữ này ghép 敝 (phá huỷ, tệ — biểu âm) với 廾 (hai bàn tay — biểu nghĩa theo kiểu hội ý): hành động dùng hai tay phá huỷ quy tắc, gây gian lận. Nghĩa chính là gian lận, tệ nạn, nhược điểm. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "giả mạo, dối trá; có hại", "Hạng Tần Suất (Jun Da)": "2343.0", "Tần Suất % (Jun Da)": "98.1562305337", "GavinGrover_Once (Chiết tự trực tiếp)": "敝 + 艹", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱敝艹", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "敝", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "弊", "Unihan_Traditional (Chữ Phồn thể)": "弊", "Pinyin_Xie": "bì", "Âm Hán Việt_Xie": "tệ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Chữ này làm danh từ chỉ tệ nạn, sai sót hoặc làm tính từ chỉ sự mệt mỏi, rách nát trong văn ngôn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('勋', '{"9000": "2344.0", "Chữ Trung Quốc": "勋", "Bộ thủ & thành phần_Xie": "Bộ thủ | 力 | Số nét | 9 | nét | 员 | viên | biểu âm | nhân viên — gợi âm xūn | 力 | lực | biểu nghĩa | sức mạnh, công lao | 勋 = 熏 (biểu âm, rút gọn) + 力 (Lực, biểu nghĩa: sức mạnh, công lao); chữ hình thanh. Wiktionary ghi 熏+力 (c1=p, c2=s, ls=psc). Dạng giản thể 勋 dùng 员 thay 熏. Gốc nghĩa: công lao, thành tích chiến đấu.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"huân\": 力 (sức lực) gắng sức như khói 熏 (hun) — công lao huân nghiệp là kết quả của sức lực bỏ ra không ngừng. | Gương Hán-Việt | huân chương (huy chương), huân nghiệp (công nghiệp lớn) | Mở khoá kiến thức | Biết 勋 mở khoá: huân chương (勋章), công huân (功勋 — công lao), huân tước (勋爵 — tước quý tộc Anh).", "Tự nguyên_Xie": "勋 là dạng giản thể của 勛. Wiktionary xác nhận cấu trúc 熏 (biểu âm) + 力 (lực, sức mạnh) — ls=psc. Gốc nghĩa: công lao, chiến công; nghĩa mở rộng: huy chương, huân chương (phần thưởng cho công lao). 勋章 là huy chương trao cho người có công. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "công lao; huân chương", "Hạng Tần Suất (Jun Da)": "2344.0", "Tần Suất % (Jun Da)": "98.1585912082", "GavinGrover_Once (Chiết tự trực tiếp)": "员 + 力", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰员力", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "员", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "力", "Unihan_Simplified (Chữ Giản thể)": "勋", "Unihan_Traditional (Chữ Phồn thể)": "勛", "Pinyin_Xie": "xūn", "Âm Hán Việt_Xie": "huân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ để chỉ công lao đóng góp cho đất nước hoặc phần thưởng danh dự. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('刮', '{"9000": "2345.0", "Chữ Trung Quốc": "刮", "Bộ thủ & thành phần_Xie": "Bộ thủ | 刀 | Số nét | 8 | nét | 舌 | thiệt | biểu âm | (vốn là 𠯑, biến từ) | 刂 | đao | biểu nghĩa | con dao (bộ đao đứng) | 刮 = 舌 (Thiệt, biểu âm; phồn vốn là 𠯑) + 刂 (Đao, biểu nghĩa: dao). Chữ hình thanh: dùng dao cạo/nạo bề mặt — nghĩa ''cạo, nạo, vót, gió thổi mạnh''.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt ''Quát'' nghĩa là ''cạo, vót, gió thổi mạnh''. Nhớ: 舌 (lưỡi) bên trái + 刂 (dao) bên phải — lưỡi dao ''quát'' cạo bề mặt; cũng như cơn gió ''quát'' qua mặt. | Gương Hán-Việt | Chữ 刮 (Quát) trong tiếng Việt: ''khái quát'' (cùng âm ''quát''), ''quát mắng'' — đều mang ý ''phủ quét, quét qua''. Khẩu ngữ ''cạo, vét''. | Mở khoá kiến thức | Nắm 刮 mở khoá cụm động từ thường gặp: 刮风 (gió thổi), 刮胡子 (cạo râu), 刮目相看 (đổi cái nhìn).", "Tự nguyên_Xie": "Theo Wiktionary, 刮 là chữ hình thanh (psc): {{Han compound|𠯑|刀|c1=p|c2=s|t2=knife|ls=psc}} — 𠯑 biểu âm (nay viết thành 舌), 刀 (刂, dao) biểu nghĩa. Nghĩa gốc ''dùng dao cạo, vót'', mở rộng thành ''gió thổi mạnh'' (như dao cứa vào da). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "vót, gọt, nạo, cạo", "Hạng Tần Suất (Jun Da)": "2345.0", "Tần Suất % (Jun Da)": "98.1609503323", "GavinGrover_Once (Chiết tự trực tiếp)": "舌 + 刂", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰舌刂", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "刂", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "舌", "Unihan_Simplified (Chữ Giản thể)": "刮", "Unihan_Traditional (Chữ Phồn thể)": "刮", "Pinyin_Xie": "guā", "Âm Hán Việt_Xie": "quát", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ chỉ hành động cạo, gạt bề mặt hoặc dùng cho hiện tượng gió thổi. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | guā | / | cạo | Xuất hiện trong lộ trình | New HSK | New HSK 6 | · | Vẻ bề ngoài", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('郊', '{"9000": "2346.0", "Chữ Trung Quốc": "郊", "Bộ thủ & thành phần_Xie": "Bộ thủ | 邑 | Số nét | 8 | nét | 交 | giao | biểu âm | gợi âm jiāo | 阝 | phụ | biểu nghĩa | ấp, vùng — biến thể của 邑 | 郊 = 交 (Giao, biểu âm) + 阝 (Phụ, biểu nghĩa: vùng đất); chữ hình thanh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"giao\": chữ 交 (giao, gặp) cùng 阝 (vùng) — nơi tiếp giáp ngoài thành, đó là ''giao'' (ngoại ô). | Gương Hán-Việt | giao trong \"giao khu\" 郊區, \"tứ giao\" 四郊 | Mở khoá kiến thức | Biết 郊 mở khoá nhóm từ về ngoại ô: 郊区, 郊外, 郊游.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Wiktionary chú 郊 = 交 + 邑/阝 (ls=psc, c1=p c2=s) — 交 cho âm jiāo, 邑 (ấp, vùng đất) cho nghĩa ''vùng ngoại ô''. Nghĩa: ngoại thành, ngoại ô. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ngoại thành, ngoại ô", "Hạng Tần Suất (Jun Da)": "2346.0", "Tần Suất % (Jun Da)": "98.1633094564", "GavinGrover_Once (Chiết tự trực tiếp)": "交 + 阝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰交阝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "交", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "阝", "Unihan_Simplified (Chữ Giản thể)": "郊", "Unihan_Traditional (Chữ Phồn thể)": "郊", "Pinyin_Xie": "jiāo", "Âm Hán Việt_Xie": "giao", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ khu vực ngoại thành, thường kết hợp với các từ chỉ phương hướng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('凄', '{"9000": "2347.0", "Chữ Trung Quốc": "凄", "Bộ thủ & thành phần_Xie": "Bộ thủ | 冫 | Số nét | 10 | nét | 冫 | băng | biểu nghĩa | băng, lạnh | 妻 | thê | biểu âm | vợ | 凄 = 冫(Băng, biểu nghĩa: băng lạnh) + 妻 (Thê, biểu âm); chữ hình thanh. Bộ Băng chỉ cái lạnh, 妻 cho âm thê.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thê\": băng giá (冫) bao quanh người vợ (妻) — \"thê lương\" là nỗi lạnh lẽo, buồn bã tận xương tuỷ. | Gương Hán-Việt | \"thê\" trong \"thê lương\" (悲凄), \"thê thảm\" (凄惨 — thảm thiết); \"凄\" cùng gốc với \"thê\" trong tiếng Việt | Mở khoá kiến thức | Biết 凄 (thê) mở khoá: 凄凉 (thê lương — buồn lạnh), 凄惨 (thê thảm — đau thương).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Theo Wiktionary, 凄 ghép 仌/冫 (băng lạnh — biểu nghĩa) với 妻 (biểu âm, đọc thê). Nghĩa gốc là lạnh buốt, rét mướt. Từ đó mở rộng sang nghĩa thê lương, buồn thảm — cái lạnh của khung cảnh gợi nỗi buồn cô đơn. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lạnh; thê lương, thê thảm", "Hạng Tần Suất (Jun Da)": "2347.0", "Tần Suất % (Jun Da)": "98.1656618624", "GavinGrover_Once (Chiết tự trực tiếp)": "冫 + 妻", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰冫妻", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "妻", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "冫", "Unihan_Simplified (Chữ Giản thể)": "凄", "Unihan_Traditional (Chữ Phồn thể)": "凄", "Pinyin_Xie": "qī", "Âm Hán Việt_Xie": "thê", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này làm tính từ miêu tả cảnh tượng lạnh lẽo hoặc tâm trạng buồn bã, cô đơn. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('捧', '{"9000": "2348.0", "Chữ Trung Quốc": "捧", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 11 | nét | 扌 | thủ | biểu nghĩa | tay | 奉 | phụng | biểu âm | phụng sự, dâng lên | 捧 = 扌(Thủ, biểu nghĩa: tay) + 奉 (Phụng, gần âm); chữ hình thanh. Bộ Thủ chỉ hành động của tay, 奉 gợi âm và ý nghĩa dâng lên, bưng bê cẩn thận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bưng\": đôi tay (扌) cung kính phụng sự (奉) — \"bưng\" là bê thứ gì đó bằng cả hai lòng bàn tay, cẩn thận như dâng lễ. | Gương Hán-Việt | \"bưng\" là từ thuần Việt tương đương; 捧 trong \"吹捧\" (xuy bổng = tâng bốc) | Mở khoá kiến thức | Biết 捧 (bưng/bổng) mở khoá: 吹捧 (xuy bổng — tâng bốc), 捧场 (bổng trường — ủng hộ, cổ vũ).", "Tự nguyên_Xie": "Wiktionary chỉ ghi {{Han etym}} mà không có mô tả chi tiết. Dựa trên cấu trúc, 捧 ghép 扌 (tay — biểu nghĩa) với 奉 (phụng — gần âm và gợi ý nghĩa dâng lên). Nghĩa là dùng hai tay bưng, nâng, hay tâng bốc người khác. Chưa có nguồn học thuật xác nhận chính xác vai trò của 奉. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1338.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thủ (064) Phụng (1337)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Thủ (số 064 - cái tay/ 扌/chỉ ý) ở bên trái chữ Phụng (số 1337 - dâng lên/chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh kiêm Hội ý. Phủng là dùng hai tay bưng, nâng đồ vật, đưa lên.", "Nghĩa Tiếng Việt_Xie": "bưng, mang", "Hạng Tần Suất (Jun Da)": "2348.0", "Tần Suất % (Jun Da)": "98.1680044494", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 奉", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌奉", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "奉", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "捧", "Unihan_Traditional (Chữ Phồn thể)": "捧", "Pinyin_Xie": "pěng", "Âm Hán Việt_Xie": "phủng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Lượng từ | 量词 | Thường làm động từ chỉ hành động nâng vật bằng hai tay hoặc làm lượng từ cho vật nằm gọn trong hai bàn tay khum lại. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Lượng từ | 量词 | Đứng giữa số từ (hoặc 这/那) và danh từ: 一杯茶, 这本书. Mỗi danh từ đi với lượng từ riêng; 个 là lượng từ dùng chung phổ biến nhất.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | pěng | / | nâng lên bằng hai tay | Xuất hiện trong lộ trình | HSK | HSK 6 | · | Tôn giáo và nghi lễ | New HSK | New HSK 7-9 | · | Words II", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('浸', '{"9000": "2349.0", "Chữ Trung Quốc": "浸", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 10 | nét | 氵 | thuỷ | biểu nghĩa | nước | 𡩠 | biểu âm | âm phù (hình dạng 𠬶) | 浸 = 氵(Thuỷ, biểu nghĩa: nước) + 𡩠 (biểu âm); chữ hình thanh. Bộ Thuỷ chỉ liên quan đến nước, phần còn lại cho âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tẩm\": nước (氵) thấm vào từng chút một — \"tẩm\" là ngâm, tẩm ướt, như tẩm bổ hay tẩm quất. | Gương Hán-Việt | \"tẩm\" trong \"tẩm bổ\" (bồi dưỡng sức khoẻ); 浸泡 (tẩm bào = ngâm), 沉浸 (trầm tẩm = đắm chìm) | Mở khoá kiến thức | Biết 浸 (tẩm) mở khoá: 浸泡 (tẩm bào — ngâm), 沉浸 (trầm tẩm — đắm mình).", "Tự nguyên_Xie": "Lục thư thông | Theo Wiktionary, 浸 ghép 水 (nước — biểu nghĩa) với 𡩠 (biểu âm) theo kiểu hình thanh. Nghĩa gốc là ngâm, thấm nước. Hình ảnh vật thể chìm dần trong nước. Từ đó mở rộng sang nghĩa thấm dần, tiêm nhiễm dần dần (浸润 — thấm nhuần). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ngâm, thấm (nước); dần dần", "Hạng Tần Suất (Jun Da)": "2349.0", "Tần Suất % (Jun Da)": "98.1703449693", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "浸", "Unihan_Traditional (Chữ Phồn thể)": "浸", "Pinyin_Xie": "jìn", "Âm Hán Việt_Xie": "tẩm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước tân ngữ chỉ chất lỏng hoặc làm trạng ngữ trong cấu trúc giới từ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('砖', '{"9000": "2350.0", "Chữ Trung Quốc": "砖", "Bộ thủ & thành phần_Xie": "Bộ thủ | 石 | Số nét | 9 | nét | 石 | thạch | biểu nghĩa | đá, vật liệu cứng | 专 | chuyên | biểu âm | chuyên | 砖 = 石 (Thạch, biểu nghĩa: đá, vật cứng) + 专 (Chuyên, biểu âm); chữ hình thanh. Bộ Thạch chỉ vật liệu cứng như gạch đá, 专 cho âm chuyên.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chuyên\": đá (石) chuyên dụng (专) để xây dựng — gạch là vật liệu đá chuyên biệt, nung từ đất. | Gương Hán-Việt | \"chuyên\" trong \"chuyên dụng\"; 砖 đọc là \"chuyên\" vì 专 làm âm phù; 砖瓦 (chuyên ngõa = gạch và ngói) | Mở khoá kiến thức | Biết 砖 (chuyên) mở khoá: 砖瓦 (chuyên ngõa — gạch và ngói), 砖块 (chuyên khối — viên gạch).", "Tự nguyên_Xie": "砖 là dạng giản thể của 磚. Chữ gốc 磚 dùng 石 (đá — biểu nghĩa) và 專 (biểu âm). Gạch (砖) được làm từ đất sét nung, cứng như đá. Chưa có mô tả Wiktionary chi tiết ngoài thông tin đây là giản thể. Chưa có nguồn học thuật xác nhận thêm. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "gạch đã nung chín", "Hạng Tần Suất (Jun Da)": "2350.0", "Tần Suất % (Jun Da)": "98.1726767038", "GavinGrover_Once (Chiết tự trực tiếp)": "石 + 专", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰石专", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "专", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "石", "Unihan_Simplified (Chữ Giản thể)": "砖", "Unihan_Traditional (Chữ Phồn thể)": "塼", "Pinyin_Xie": "zhuān", "Âm Hán Việt_Xie": "chuyên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng sau lượng từ hoặc kết hợp với các danh từ khác để chỉ vật liệu xây dựng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | zhuān | / | gạch | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Xây dựng và cải tạo", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鼎', '{"9000": "2351.0", "Chữ Trung Quốc": "鼎", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鼎 | Số nét | 12 | nét | 鼎 | đỉnh | tượng hình | cái đỉnh ba chân — đồ đồng cổ đại dùng nấu ăn và tế lễ | 鼎 là chữ tượng hình (liushu: p): mô tả chiếc đỉnh ba chân bằng đồng của thời cổ đại Trung Quốc. Phần trên là thân đỉnh với mặt trang trí, phần dưới là ba chân. Đây là chữ độc thể, không tách được thành bộ phận có nghĩa khác.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đỉnh\": hình vẽ chiếc đỉnh ba chân — biểu tượng đỉnh cao quyền lực, chín chiếc đỉnh là cả thiên hạ. | Gương Hán-Việt | đỉnh chung (đỉnh và chuông — phú quý), đỉnh lập (thế chân vạc) | Mở khoá kiến thức | Biết 鼎 mở khoá: đại danh đỉnh đỉnh (大名鼎鼎 — rất nổi tiếng), cửu đỉnh (九鼎 — chín đỉnh, quyền lực tối cao), đỉnh lực (鼎力 — ra sức giúp đỡ).", "Tự nguyên_Xie": "鼎 là chữ tượng hình: hình ảnh chiếc đỉnh đồng ba chân — loại đồ đồng quan trọng nhất thời cổ đại Trung Quốc, dùng để nấu ăn và thực hiện tế lễ. Wiktionary xác nhận ''liushu: p'' (tượng hình). Đỉnh còn được dùng như biểu tượng quyền lực: chín chiếc đỉnh (九鼎) tượng trưng cho chủ quyền thiên hạ. Cũng mượn âm để chỉ ''bói toán'' (sau viết là 貞/贞). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái vạc, cái đỉnh", "Hạng Tần Suất (Jun Da)": "2351.0", "Tần Suất % (Jun Da)": "98.1750058544", "GavinGrover_Once (Chiết tự trực tiếp)": "𤕰 + 目", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿶ (Bao quanh phía dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴𤕰目", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "𤕰", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "目", "Unihan_Simplified (Chữ Giản thể)": "鼎", "Unihan_Traditional (Chữ Phồn thể)": "鼎", "Pinyin_Xie": "dǐng", "Âm Hán Việt_Xie": "đỉnh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng sau lượng từ hoặc dùng trong các thành ngữ chỉ sự to lớn, vững chắc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('篮', '{"9000": "2352.0", "Chữ Trung Quốc": "篮", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 16 | nét | 竹 | trúc | biểu nghĩa | bộ trúc — vật làm bằng tre | 监 | giam | biểu âm | thanh phù, gợi âm ''jiān/lán'' | 篮 (giản thể của 籃) = 竹 (Trúc, biểu nghĩa: tre — chất liệu đan giỏ) + 监 (Giam, biểu âm); chữ hình thanh. Nghĩa ''cái rổ, cái giỏ đan''.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lam\": dùng tre trúc (竹) đan thành vật để giam (监) đồ — đó là cái giỏ, nên 篮 nghĩa ''giỏ, rổ''. | Gương Hán-Việt | ''lam'' trong ''lam thiên'' (蓝天 — bầu trời xanh, gần âm), ''la lam'' — chú ý phân biệt với 蓝 màu xanh | Mở khoá kiến thức | Nắm 篮 mở khoá 篮球 (bóng rổ) — môn thể thao phổ biến, cùng 摇篮, 菜篮.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Theo Wiktionary, 篮 là dạng giản thể của 籃, là chữ hình thanh: 竹 (trúc — tre) làm nghĩa phù vì giỏ truyền thống đan bằng tre, 監/监 (giam) làm thanh phù. Nghĩa gốc ''cái giỏ tre, cái rổ'', mở rộng sang ''cái rổ bóng rổ'' trong các từ hiện đại như 篮球. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái giỏ", "Hạng Tần Suất (Jun Da)": "2352.0", "Tần Suất % (Jun Da)": "98.1773262197", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 监", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮监", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "监", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "篮", "Unihan_Traditional (Chữ Phồn thể)": "籃", "Pinyin_Xie": "lán", "Âm Hán Việt_Xie": "lam", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng sau lượng từ hoặc kết hợp với các danh từ khác để chỉ các loại giỏ đựng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蒸', '{"9000": "2353.0", "Chữ Trung Quốc": "蒸", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 13 | nét | 艹 | thảo | biểu nghĩa | cỏ, thực vật | 烝 | chưng | biểu âm | hơi nóng bốc lên | 蒸 = 艹(Thảo, biểu nghĩa: thực vật) + 烝 (Chưng, biểu âm); chữ hình thanh. Bộ Thảo chỉ nguồn gốc thực vật (cỏ dùng nấu hơi), 烝 cho âm chưng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chưng\": cỏ cây (艹) làm củi đốt dưới nồi chưng (烝) — \"chưng\" là hấp, như chưng cách thuỷ hay chưng đồ ăn. | Gương Hán-Việt | \"chưng\" trong \"chưng cất\" (蒸馏 — chưng lưu = chưng cất), \"bay hơi\" (蒸发 — chưng phát) | Mở khoá kiến thức | Biết 蒸 (chưng) mở khoá: 蒸发 (chưng phát — bay hơi), 蒸馏 (chưng lưu — chưng cất).", "Tự nguyên_Xie": "Đại triện | Tiểu triện | Theo Wiktionary, 蒸 ghép 艸 (cỏ — biểu nghĩa) với 烝 (biểu âm) theo kiểu hình thanh. Nghĩa gốc là hơi nóng bốc lên từ nồi, liên quan đến nấu bằng hơi. Từ đó mở rộng sang nghĩa hấp thức ăn, bay hơi (蒸发), và hơi nước nóng. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lũ, bọn; hơi nóng bốc lên; hương lên, đùn đùn; cây gai róc vỏ; ngọn đuốc; củi nhỏ; lễ tế chưng (vào mùa đông)", "Hạng Tần Suất (Jun Da)": "2353.0", "Tần Suất % (Jun Da)": "98.179622296", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 烝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹烝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "烝", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "蒸", "Unihan_Traditional (Chữ Phồn thể)": "蒸", "Pinyin_Xie": "zhēng", "Âm Hán Việt_Xie": "chưng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước danh từ chỉ món ăn để biểu thị phương pháp nấu nướng bằng hơi nước. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | zhēng | / | hấp | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Thực phẩm II", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('饼', '{"9000": "2354.0", "Chữ Trung Quốc": "饼", "Bộ thủ & thành phần_Xie": "Bộ thủ | 食 | Số nét | 9 | nét | 饣 | thực | biểu nghĩa | đồ ăn — bánh | 并 | tinh | biểu âm | phần biểu âm — gần âm ''bính/tinh'' | 饼 là dạng giản thể của 餅, gồm 饣 (食/飠, đồ ăn — biểu nghĩa) + 并 (biểu âm). Là chữ hình thanh — chỉ loại bánh tròn dẹt làm bằng bột.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Bính\": đồ ăn (饣) được hợp (并) bột thành miếng dẹt tròn — đó là ''bính'', bánh. | Gương Hán-Việt | ''Bính/bánh'' trong ''nguyệt bính'' (bánh trung thu), ''bính khô'' (bánh quy), ''bính cảo'' (bánh có nhân). | Mở khoá kiến thức | Biết 饼 mở khoá 月饼 (nguyệt bính, bánh trung thu), 饼干 (bính can, bánh quy), 烧饼 (thiêu bính, bánh nướng).", "Tự nguyên_Xie": "Đại triện | Tiểu triện | Theo Wiktionary, 饼 là dạng giản thể của 餅, được tạo bằng cách thay 飠 bằng 饣. Chữ phồn thể 餅 là chữ hình thanh: 食 (饣, ăn — biểu nghĩa: thức ăn từ bột) + 幷 (并, biểu âm). Nghĩa gốc ''bánh tròn dẹt làm bằng bột (mì, gạo)'', sau mở rộng thành ''bất kỳ vật tròn dẹt nào'' (như 月饼 — bánh trung thu, 铁饼 — đĩa nén tạ). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bánh làm bằng bột", "Hạng Tần Suất (Jun Da)": "2354.0", "Tần Suất % (Jun Da)": "98.1819163052", "GavinGrover_Once (Chiết tự trực tiếp)": "饣 + 并", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰饣并", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "并", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "饣", "Unihan_Simplified (Chữ Giản thể)": "饼", "Unihan_Traditional (Chữ Phồn thể)": "餅", "Pinyin_Xie": "bǐng", "Âm Hán Việt_Xie": "bính", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng sau lượng từ hoặc kết hợp với các từ chỉ nguyên liệu để tạo thành tên món ăn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | bǐng | / | bánh tròn dẹt | Xuất hiện trong lộ trình | New HSK | New HSK 5 | · | Thức ăn và đồ uống", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('亩', '{"9000": "2355.0", "Chữ Trung Quốc": "亩", "Bộ thủ & thành phần_Xie": "Bộ thủ | 亠 | Số nét | 7 | nét | 亠 | đầu | biểu ý | nắp, đỉnh | 田 | điền | biểu nghĩa | ruộng đồng | 亩 gốc viết là 畮 — hình thanh: bộ 田 (điền, ruộng) biểu nghĩa, phần 每 biểu âm, sau đổi thành 又 rồi thêm 十. Dạng hiện đại 亩 gồm 亠 + 田. Gốc nghĩa: đơn vị đo diện tích ruộng đất của Trung Quốc (1 mẫu = 1/15 hecta).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mẫu\": 亠 (nắp, che) trên 田 (ruộng) — mẫu là ô ruộng được đo đạc và ấn định, đơn vị đất đai của dân Trung Hoa. | Gương Hán-Việt | mẫu ruộng (đơn vị diện tích), cố mẫu (mẫu đất cũ) | Mở khoá kiến thức | Biết 亩 mở khoá: mẫu (亩 — đơn vị diện tích), mỗi mẫu (每亩 — trên mỗi mẫu), bán mẫu (半亩 — nửa mẫu).", "Tự nguyên_Xie": "亩 gốc viết là 畮, dạng hình thanh với bộ 田 (điền, ruộng) biểu nghĩa và 每 biểu âm. Theo Wiktionary: phần âm 每 được thay bằng 又, sau đó thêm 十 phía trên. Dạng giản thể 亩 = 亠+田. Nghĩa: mẫu — đơn vị diện tích ruộng đất truyền thống Trung Quốc (1 mẫu ≈ 667 m², tức 1/15 hecta). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mẫu (đơn vị đo, bằng 60 trượng vuông)", "Hạng Tần Suất (Jun Da)": "2355.0", "Tần Suất % (Jun Da)": "98.1842103144", "GavinGrover_Once (Chiết tự trực tiếp)": "亠 + 田", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱亠田", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "田", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "亠", "Unihan_Simplified (Chữ Giản thể)": "亩", "Unihan_Traditional (Chữ Phồn thể)": "畂", "Pinyin_Xie": "mǔ", "Âm Hán Việt_Xie": "mẫu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Lượng từ | 量词 | Danh từ | 名词 | Thường làm lượng từ đứng sau số từ để đo diện tích đất đai canh tác. | Lượng từ | 量词 | Đứng giữa số từ (hoặc 这/那) và danh từ: 一杯茶, 这本书. Mỗi danh từ đi với lượng từ riêng; 个 là lượng từ dùng chung phổ biến nhất. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | mǔ | / | mẫu (đơn vị diện tích = 1/15 ha) | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Địa lý II", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('肾', '{"9000": "2356.0", "Chữ Trung Quốc": "肾", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 8 | nét | 又 | hựu | biểu ý | bàn tay, tái diễn | 月 | nguyệt | biểu nghĩa | thịt, cơ thể (bộ nhục) | 肾 là dạng giản thể của 腎. Cấu trúc: phần trên gồm 𰀡 (rút gọn từ 臤 — tay và vật cứng) + bộ 月 (nhục, thịt) ở dưới; hình thanh. Bộ 月 ở đây là bộ nhục chỉ cơ quan trong cơ thể, phần trên biểu âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thận\": 月 (cơ thể) + phần trên cứng như 臤 — thận là cơ quan vững chắc bên trong cơ thể, bảo vệ tinh khí. | Gương Hán-Việt | thận tạng (quả thận), bổ thận (bồi bổ thận) | Mở khoá kiến thức | Biết 肾 mở khoá: thận tạng (肾脏 — quả thận), thận suy (肾衰 — suy thận), thận viêm (肾炎 — viêm thận), dương hư (阳虚 liên quan thận trong Đông y).", "Tự nguyên_Xie": "肾 là dạng giản thể của 腎, viết gọn từ 臤 thành 𰀡. Cấu trúc hình thanh: phần trên (từ 臤 — tay cứng) biểu âm, bộ 月/肉 (nhục, thịt) biểu nghĩa chỉ cơ quan trong cơ thể. Nghĩa: thận — cơ quan lọc máu và bài tiết của cơ thể. Trong y học cổ truyền, thận chứa tinh khí, liên quan đến sự phát triển và sinh sản. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "quả thận", "Hạng Tần Suất (Jun Da)": "2356.0", "Tần Suất % (Jun Da)": "98.1865032901", "GavinGrover_Once (Chiết tự trực tiếp)": "No glyph available + 月", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱月", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "肾", "Unihan_Traditional (Chữ Phồn thể)": "腎", "Pinyin_Xie": "shèn", "Âm Hán Việt_Xie": "thận", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ cơ quan nội tạng trong cơ thể người và động vật. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | Từ vựng Hán 肾 (shèn). Hán-Việt: thận. | / | shèn | / | thận | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Nội dung II", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('陡', '{"9000": "2357.0", "Chữ Trung Quốc": "陡", "Bộ thủ & thành phần_Xie": "Bộ thủ | 阜 | Số nét | 9 | nét | 阝 | phụ | biểu nghĩa | gò đồi, địa hình | 走 | tẩu | biểu âm | đi, chạy | 陡 = 阝(Phụ, biểu nghĩa: gò đồi, địa hình dốc) + 走 (Tẩu, gần âm); chữ hình thanh theo suy luận cấu trúc. Bộ Phụ chỉ địa hình núi đồi, phần còn lại gợi âm. Chưa có nguồn học thuật xác nhận vì Wiktionary không có anchor cho chữ này.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đẩu\": trên sườn gò đồi (阝) mà đi (走) phải khó nhọc — \"đẩu\" gợi cảnh dốc đứng, cheo leo, phải bước thận trọng từng bước. | Gương Hán-Việt | \"đẩu\" ít dùng độc lập; 陡峭 (đẩu tiêu = dốc đứng cheo leo), 陡然 (đẩu nhiên = đột ngột) | Mở khoá kiến thức | Biết 陡 (đẩu) mở khoá: 陡峭 (đẩu tiêu — dốc đứng), 陡然 (đẩu nhiên — đột ngột).", "Tự nguyên_Xie": "Không có nguồn Wiktionary cho 陡. Dựa trên cấu trúc: 阝(bộ phụ — đồi, địa hình) + 走 (tẩu — chạy). Có thể hình dung: địa hình mà khi đi (走) trên đó phải leo gắng sức, tức là dốc đứng. Đây là suy luận từ thành phần; chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cao chót vót", "Hạng Tần Suất (Jun Da)": "2357.0", "Tần Suất % (Jun Da)": "98.1887879972", "GavinGrover_Once (Chiết tự trực tiếp)": "阝 + 走", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰阝走", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "走", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "阝", "Unihan_Simplified (Chữ Giản thể)": "陡", "Unihan_Traditional (Chữ Phồn thể)": "陡", "Pinyin_Xie": "dǒu", "Âm Hán Việt_Xie": "đẩu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Phó từ | 副词 | Thường làm tính từ miêu tả địa hình dốc đứng hoặc làm phó từ chỉ sự thay đổi đột ngột. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Phó từ | 副词 | Bổ nghĩa cho động từ hoặc tính từ và luôn đứng TRƯỚC chúng — 都是, 很好. Không đứng sau như tiếng Việt và không bổ nghĩa cho danh từ.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | dǒu | / | đột ngột | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Quá trình hành động I", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('爪', '{"9000": "2358.0", "Chữ Trung Quốc": "爪", "Bộ thủ & thành phần_Xie": "Bộ thủ | 爪 | Số nét | 4 | nét | 爪 | trảo | tượng hình | bàn tay/vuốt từ trên cào xuống — móng vuốt, bàn tay | 爪 là chữ tượng hình (liushu: p): mô tả bàn tay hoặc móng vuốt đang cào từ trên xuống. Trong giáp cốt và kim văn, hình vẽ rõ ràng là tay người hoặc vuốt thú nhìn từ bên cạnh. Đây là chữ độc thể — chính nó là bộ thủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trảo\": hình vuốt thú đang cào xuống — trảo là móng vuốt sắc nhọn, hình ảnh sức mạnh tàn bạo. | Gương Hán-Việt | trảo nha (móng vuốt và răng — thủ hạ), trảo ký (ký móng vuốt) | Mở khoá kiến thức | Biết 爪 mở khoá: trảo nha (爪牙 — tay chân, thủ hạ), móng vuốt (爪子), kê trảo (鸡爪 — chân gà).", "Tự nguyên_Xie": "爪 là chữ tượng hình: mô tả bàn tay đang cào từ trên xuống (hoặc móng vuốt thú). Wiktionary xác nhận ''liushu: p'', mô tả ''a hand grabbing from above''. Chú ý: dù hình ảnh có thể gợi móng vuốt, nhưng gốc thực sự là bàn tay người. Nghĩa: móng vuốt; bàn chân thú; bàn tay (nghĩa cổ). So sánh với 手 (thủ, tay từ bên) và 寸 (thốn, tay với vạch đo). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "340.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Chữ đơn thể / Nét căn bản", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Hình vẽ bàn tay được viết giảm nét (còn 3 ngón) đang chụp lại. Cũng có ý chỉ móng vuốt của loài thú, chim chóc.", "Nghĩa Tiếng Việt_Xie": "móng chân thú", "Hạng Tần Suất (Jun Da)": "2358.0", "Tần Suất % (Jun Da)": "98.1910716707", "GavinGrover_Once (Chiết tự trực tiếp)": "No glyph available + 丨", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿵ (Bao quanh phía trên)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴丨", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "爪", "Unihan_Traditional (Chữ Phồn thể)": "爪", "Pinyin_Xie": "zhǎo", "Âm Hán Việt_Xie": "trảo", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng sau lượng từ hoặc kết hợp với danh từ chỉ động vật để chỉ bộ phận móng vuốt. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('兔', '{"9000": "2359.0", "Chữ Trung Quốc": "兔", "Bộ thủ & thành phần_Xie": "Bộ thủ | 儿 | Số nét | 8 | nét | 兔 | thỏ | tượng hình | con thỏ (với chấm phải thể hiện đuôi) | 兔 là chữ tượng hình một con thỏ — phần thân là 免-like, dấu chấm bên phải tượng trưng cho đuôi thỏ ngắn. Không tách thành thành tố có nghĩa, ta xem 兔 như tượng hình thống nhất.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thỏ\": 兔 vẽ con thỏ, có thêm dấu chấm bên phải làm cái đuôi ngắn — đúng nghĩa ''con thỏ'' trong 兔子, 守株待兔. | Gương Hán-Việt | ''thỏ'' y nguyên trong tiếng Việt — ''con thỏ'' | Mở khoá kiến thức | Nắm 兔 mở khoá từ HSK 5-7: 兔, 兔子, 守株待兔.", "Tự nguyên_Xie": "Kim văn | Theo Wiktionary, 兔 là chữ tượng hình một con thỏ. Đáng chú ý dấu chấm ở góc trên-phải (so với 免 không có chấm) tượng trưng cho đuôi thỏ ngắn — đây là điểm phân biệt 兔 với 免. Nghĩa ''con thỏ'' giữ nguyên trong 兔, 兔子, và có trong thành ngữ 守株待兔 (ôm cây đợi thỏ). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "638.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Trấp (013) Khẩu (012) Nhân (011) Chủ (607)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Hình con thỏ đang ngồi, có cái mỏ, cái đầu, hai chân (Nhân) và một dấu chấm chỉ cái đuôi thỏ. Giải thích sự chuyển ý: Đây là chữ Tượng hình. Khắc họa trực tiếp hình dáng con thỏ. Thố là con thỏ.", "Nghĩa Tiếng Việt_Xie": "con thỏ", "Hạng Tần Suất (Jun Da)": "2359.0", "Tần Suất % (Jun Da)": "98.1933548274", "GavinGrover_Once (Chiết tự trực tiếp)": "免 + 丶", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴免丶", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "免", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "丶", "Unihan_Simplified (Chữ Giản thể)": "兔", "Unihan_Traditional (Chữ Phồn thể)": "兎", "Pinyin_Xie": "tù", "Âm Hán Việt_Xie": "thỏ, thố", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng sau lượng từ chỉ con vật hoặc kết hợp với các từ khác để chỉ sản phẩm từ thỏ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | tù | / | thỏ | Xuất hiện trong lộ trình | New HSK | New HSK 5 | · | Thiên nhiên", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('殷', '{"9000": "2360.0", "Chữ Trung Quốc": "殷", "Bộ thủ & thành phần_Xie": "Bộ thủ | 殳 | Số nét | 10 | nét | 㐆 | biểu ý | thân người bụng phình (dạng cổ) | 殳 | thù | biểu ý | tay cầm gậy, đánh | 殷 là chữ hội ý: giáp cốt gốc gồm 㐆 (người bụng phình, gợi ốm đau) + 矢 (tên, mũi nhọn) + 又 (tay) — tay hướng mũi nhọn vào bụng người. Wiktionary ghi ls=ic (hội ý). Về sau đơn giản hoá thành 㐆+殳 (tay cầm gậy). Nghĩa gốc: tên gọi nhà Ân (triều đại trước nhà Chu).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ân\": tay cầm gậy 殳 hướng vào người 㐆 — ân cần là chăm sóc tận tình từng người một, như thầy thuốc nhà Ân trị bệnh. | Gương Hán-Việt | ân cần (niềm nở), Ân triều (nhà Thương) | Mở khoá kiến thức | Biết 殷 mở khoá: ân cần (殷勤 — niềm nở, tận tình), Ân Thương (殷商 — triều đại cổ), ân thực (殷实 — giàu có, sung túc).", "Tự nguyên_Xie": "殷 là chữ hội ý phức tạp: trong giáp cốt gồm 㐆 (người bụng sưng) + 矢 (tên) + 又 (tay) — gợi cảnh chữa bệnh bằng châm cứu hoặc phẫu thuật, hoặc hành quyết. Wiktionary xác nhận ls=ic (hai giai đoạn). Nghĩa chính trong lịch sử: triều đại Ân (Shāng) — nhà Thương; nghĩa mở rộng: phồn thịnh, đông đúc, niềm nở (殷勤). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thịnh, đầy đủ; đời nhà Ân (Trung Quốc)", "Hạng Tần Suất (Jun Da)": "2360.0", "Tần Suất % (Jun Da)": "98.1956374673", "GavinGrover_Once (Chiết tự trực tiếp)": "㐆 + 殳", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰㐆殳", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "㐆", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "殳", "Unihan_Simplified (Chữ Giản thể)": "殷", "Unihan_Traditional (Chữ Phồn thể)": "殷", "Pinyin_Xie": "yīn", "Âm Hán Việt_Xie": "ân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Chữ này thường làm tính từ bổ nghĩa cho sự thịnh vượng hoặc làm danh từ chỉ triều đại nhà Ân. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('贞', '{"9000": "2361.0", "Chữ Trung Quốc": "贞", "Bộ thủ & thành phần_Xie": "Bộ thủ | 卜 | Số nét | 6 | nét | ⺊ | biểu ý | que bói, hình đỉnh trên | 贝 | bối | biểu ý | vỏ sò, tiền tệ | 贞 là chữ tượng hình: gốc là hình chiếc đỉnh đồng (giống 鼎), sau mượn âm để chỉ ''bói toán''. Wiktionary ghi ''liushu: p — a ding (oracle bone script)''. Dạng hiện đại gồm ⺊ (que bói) trên 贝 (vỏ sò/tiền) — bói bằng xương và mai rùa (vỏ sò) là tục lệ giáp cốt cổ đại.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trinh\": ⺊ (que bói) + 贝 (vỏ sò mai rùa) — trinh tiết như kết quả bói — đã định sẵn không thay đổi được. | Gương Hán-Việt | trinh tiết (trinh khiết), trinh nữ (cô gái chưa chồng), trung trinh (trung thành) | Mở khoá kiến thức | Biết 贞 mở khoá: trung trinh (忠贞 — trung thành tuyệt đối), trinh tiết (贞节 — phẩm hạnh trinh khiết), trinh nữ (贞女 — người phụ nữ tiết hạnh).", "Tự nguyên_Xie": "贞 gốc là tượng hình chiếc đỉnh đồng (cùng gốc với 鼎), được mượn âm để chỉ ''bói toán''. Wiktionary xác nhận: ''liushu: p — same as 鼎, borrowed phonetically for to divine''. Dạng phiên âm: các chiếc đỉnh trong lễ tế thời cổ đại đôi khi được dùng trong nghi lễ bói toán. Từ nghĩa bói, 贞 phát triển sang nghĩa trung thành, tiết hạnh (người chung thủy như mệnh trời đã định). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "trong trắng, tiết hạnh; trung thành", "Hạng Tần Suất (Jun Da)": "2361.0", "Tần Suất % (Jun Da)": "98.1979185569", "GavinGrover_Once (Chiết tự trực tiếp)": "⺊ + 贝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺊贝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "贝", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺊", "Unihan_Simplified (Chữ Giản thể)": "贞", "Unihan_Traditional (Chữ Phồn thể)": "貞", "Pinyin_Xie": "zhēn", "Âm Hán Việt_Xie": "trinh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Thường dùng làm tính từ để mô tả phẩm chất kiên trinh, trong sạch của con người. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('荐', '{"9000": "2362.0", "Chữ Trung Quốc": "荐", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 9 | nét | 艹 | thảo | biểu nghĩa | cỏ, thực vật | 存 | tồn | biểu âm | tồn tại, cất giữ | 荐 = 艹 (Thảo, biểu nghĩa: cỏ/thực vật) + 存 (Tồn, biểu âm); chữ hình thanh. Bộ 艹 cho nghĩa liên quan đến cỏ/đồ dâng lên bằng thực vật, 存 cho âm (jiàn ~ tồn).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tiến\": cỏ 艹 (thảo) còn tồn 存 (tồn) — đưa lên dâng lên như dâng cỏ tươi, 荐 là tiến cử giới thiệu. | Gương Hán-Việt | tiến trong ''推荐 thôi tiến'' (tiến cử, đề xuất) | Mở khoá kiến thức | Biết 荐 (tiến) mở khoá: 推荐 (tiến cử, đề xuất), 荐举 (tiến cử), 自荐 (tự tiến cử).", "Tự nguyên_Xie": "Giáp cốt văn | Tiểu triện | Theo Wiktionary, 荐 (phồn thể 薦) là chữ hình thanh (psc): 艸 (thảo, biểu nghĩa: cỏ) + 存 (tồn, biểu âm). Nghĩa gốc là dâng lên cỏ (để tế thần, để ăn). Sau mở rộng sang nghĩa ''tiến cử, giới thiệu'' — như dâng người lên trên. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "hai lần; tiến cử; cỏ cho súc vật; chiếu cói", "Hạng Tần Suất (Jun Da)": "2362.0", "Tần Suất % (Jun Da)": "98.2001955122", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 存", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹存", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "存", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "荐", "Unihan_Traditional (Chữ Phồn thể)": "薦", "Pinyin_Xie": "jiàn", "Âm Hán Việt_Xie": "tiến", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường làm động từ mang tân ngữ để chỉ hành động tiến cử hoặc giới thiệu ai đó. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('哑', '{"9000": "2363.0", "Chữ Trung Quốc": "哑", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 9 | nét | 口 | khẩu | biểu nghĩa | miệng | 亚 | á | biểu âm | á, thứ hai, dưới | 哑 = 口 (Khẩu, biểu nghĩa: miệng) + 亚 (Á, biểu âm); chữ hình thanh. Bộ Khẩu chỉ liên quan đến lời nói, 亚 cho âm á/nha.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nha\": miệng (口) nhưng giọng bị ắc lại như chữ Á (亚) — \"câm nha\" là im lặng tuyệt đối, không thốt được lời. | Gương Hán-Việt | \"nha\" trong \"nha ẩu\" (哑呕 — câm lại); 哑 cùng Hán-Việt với 鸦 (quạ — nha) | Mở khoá kiến thức | Biết 哑 (nha) mở khoá: 聋哑 (lung nha — điếc và câm), 哑巴 (nha ba — người câm).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 哑 (dạng phồn thể: 啞) ghép 口 (miệng — biểu nghĩa) với 亞 (biểu âm) theo kiểu hình thanh. Nghĩa gốc là câm, không nói được — miệng nhưng không phát ra tiếng. Từ đó mở rộng sang nghĩa khàn giọng, tắt tiếng. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: nha ẩu 啞嘔,哑呕); (xem: nha nha 啞啞,哑哑)", "Hạng Tần Suất (Jun Da)": "2363.0", "Tần Suất % (Jun Da)": "98.2024724675", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 亚", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口亚", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "亚", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "哑", "Unihan_Traditional (Chữ Phồn thể)": "啞", "Pinyin_Xie": "yǎ", "Âm Hán Việt_Xie": "á, nha", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường làm tính từ đứng trước danh từ hoặc làm vị ngữ để chỉ trạng thái câm hoặc khản tiếng. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | yǎ | / | câm | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Bệnh II", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('炭', '{"9000": "2364.0", "Chữ Trung Quốc": "炭", "Bộ thủ & thành phần_Xie": "Bộ thủ | 火 | Số nét | 9 | nét | 山 | sơn | biểu nghĩa | núi, vật thể cứng | 灰 | hôi | biểu nghĩa | tro, lửa tàn | 炭 = 山/岸 (biểu nghĩa: núi đá) + 火 (Hỏa, biểu nghĩa: lửa); chữ hình thanh theo Wiktionary — 火 (hỏa: lửa) + 岸 rút gọn (biểu âm). Dạng hiện đại trông như sơn+灰, nhưng cấu trúc thực là lửa + đá núi — than đốt từ gỗ núi.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thán\": núi 山 (sơn) đốt lửa thành tro 灰 — 炭 là than hoa/than củi, sản phẩm cháy của gỗ núi. | Gương Hán-Việt | thán trong ''than thán'' (than thở, thán từ) | Mở khoá kiến thức | Biết 炭 (thán) mở khoá: 煤炭 (than đá), 木炭 (than củi), 炭火 (lửa than), 活性炭 (than hoạt tính).", "Tự nguyên_Xie": "Giáp cốt văn | Tiểu triện | Theo Wiktionary, 炭 là chữ hình thanh (psc): 火 (hỏa, biểu nghĩa: lửa) + 岸 rút gọn (biểu âm). Nghĩa gốc là than củi — sản phẩm đốt gỗ không hoàn toàn. Sau mở rộng sang 煤炭 (than đá). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1557.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Sơn (046) Hán (115) Hỏa (085)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Gồm bộ Sơn (số 046 - núi/ 山), bộ Hán (số 115 - sườn núi/ 厂) và bộ Hỏa (số 085 - ngọn lửa/ 火). Sự kết hợp của Sơn và Hán là chữ Ngạn (屵 - bờ ranh núi đá / chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh kiêm Hội ý. Thán là thứ củi, gỗ đã bị đốt cháy trong lò và thành than, dùng để làm chất đốt (than củi, thán khí, các-bon).", "Nghĩa Tiếng Việt_Xie": "than củi", "Hạng Tần Suất (Jun Da)": "2364.0", "Tần Suất % (Jun Da)": "98.204748906", "GavinGrover_Once (Chiết tự trực tiếp)": "山 + 灰", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱山灰", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "灰", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "山", "Unihan_Simplified (Chữ Giản thể)": "炭", "Unihan_Traditional (Chữ Phồn thể)": "炭", "Pinyin_Xie": "tàn", "Âm Hán Việt_Xie": "thán", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ chất đốt hoặc làm định ngữ trong các cụm từ liên quan đến than. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Sản xuất và công nghiệp", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('坟', '{"9000": "2365.0", "Chữ Trung Quốc": "坟", "Bộ thủ & thành phần_Xie": "Bộ thủ | 土 | Số nét | 7 | nét | 土 | thổ | biểu nghĩa | đất | 文 | văn | biểu âm | văn, chữ viết | 坟 = 土 (Thổ, biểu nghĩa: đất) + 文 (Văn, gần âm); chữ hình thanh. Bộ Thổ chỉ đất đai, 文 gợi âm (chữ phồn thể dùng 賁 làm âm phù).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phần\": đất (土) đắp lên cao như trang văn (文) khắc bia — \"phần mộ\" là nơi đất đắp thành nấm, có bia ghi tên. | Gương Hán-Việt | \"phần\" trong \"phần mộ\" (坟墓 — mộ phần), \"phần địa\" (đất mộ) | Mở khoá kiến thức | Biết 坟 (phần) mở khoá: 坟墓 (phần mộ — mộ phần), 上坟 (thượng phần — đi tảo mộ).", "Tự nguyên_Xie": "Đại triện | Tiểu triện | Theo Wiktionary, 坟 (dạng phồn thể: 墳) ghép 土 (đất — biểu nghĩa) với 賁 (biểu âm) theo kiểu hình thanh. Dạng giản thể thay 賁 bằng 文. Nghĩa gốc là đất đắp nổi lên, gò đất, rồi chuyển nghĩa thành nấm mộ. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mồ mả", "Hạng Tần Suất (Jun Da)": "2365.0", "Tần Suất % (Jun Da)": "98.2070237942", "GavinGrover_Once (Chiết tự trực tiếp)": "土 + 文", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰土文", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "文", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "土", "Unihan_Simplified (Chữ Giản thể)": "坟", "Unihan_Traditional (Chữ Phồn thể)": "墳", "Pinyin_Xie": "fén", "Âm Hán Việt_Xie": "phần", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ nơi chôn cất, thường kết hợp với các từ chỉ vị trí hoặc hành động viếng mộ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | fén | / | mộ | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Sự sống và cái chết", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('眨', '{"9000": "2366.0", "Chữ Trung Quốc": "眨", "Bộ thủ & thành phần_Xie": "Bộ thủ | 目 | Số nét | 9 | nét | 目 | mục | biểu nghĩa | mắt | 乏 | phạp | biểu âm | thiếu, mỏi mệt | 眨 = 目 (Mục, biểu nghĩa: mắt) + 乏 (Phạp, gần âm); chữ hình thanh theo suy luận cấu trúc. Bộ Mục chỉ mắt, 乏 gợi âm. Chưa có mô tả Wiktionary chi tiết về ls codes.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trát\": mắt (目) lướt nhanh rồi mỏi (乏) — \"nháy mắt\" là chuyển động chớp nhoáng, nhanh tàn. | Gương Hán-Việt | \"trát\" ít dùng độc lập; 眨眼 (trát nhãn = chớp mắt), 一眨眼 (nhất trát nhãn = trong nháy mắt) | Mở khoá kiến thức | Biết 眨 (trát) mở khoá: 眨眼 (trát nhãn — nháy mắt), 一眨眼 (nhất trát nhãn — trong nháy mắt).", "Tự nguyên_Xie": "Tiểu triện | Wiktionary có thông tin phát âm nhưng không mô tả rõ cấu trúc hình thanh của 眨. Dựa trên thành phần: 目 (mắt — biểu nghĩa) + 乏 (gần âm). Nghĩa là chớp mắt, nháy mắt — chuyển động nhẹ của mắt. Chưa có nguồn học thuật xác nhận vai trò chính xác của 乏. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nháy mắt", "Hạng Tần Suất (Jun Da)": "2366.0", "Tần Suất % (Jun Da)": "98.2092940313", "GavinGrover_Once (Chiết tự trực tiếp)": "目 + 乏", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰目乏", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "乏", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "目", "Unihan_Simplified (Chữ Giản thể)": "眨", "Unihan_Traditional (Chữ Phồn thể)": "眨", "Pinyin_Xie": "zhǎ", "Âm Hán Việt_Xie": "trát", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước danh từ chỉ bộ phận cơ thể như mắt để diễn tả hành động chớp nháy. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | Xuất hiện trong lộ trình | HSK | HSK 6 | · | Cơ thể và ngoại hình tôi", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('搏', '{"9000": "2367.0", "Chữ Trung Quốc": "搏", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 13 | nét | 扌 | thủ | biểu nghĩa | tay | 尃 | phu | biểu âm | trải ra, phân phát | 搏 = 扌(Thủ, biểu nghĩa: tay) + 尃 (Phu, biểu âm); chữ hình thanh. Bộ Thủ chỉ hành động của tay, 尃 cho âm bác/bô.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bác\": tay (扌) tung ra (尃 = trải) — \"bác\" là đánh dứt khoát, như mạch máu bác từng nhịp. | Gương Hán-Việt | \"bác\" trong \"bác bỏ\" (bác đi); 搏斗 (bác đấu = chiến đấu), 脉搏 (mạch bác = mạch đập) | Mở khoá kiến thức | Biết 搏 (bác) mở khoá: 拼搏 (bính bác — chiến đấu hết mình), 搏斗 (bác đấu — đấu tranh), 脉搏 (mạch bác — mạch đập).", "Tự nguyên_Xie": "Kim văn | Tiểu triện | Lục thư thông | Theo Wiktionary, 搏 ghép 手 (tay — biểu nghĩa) với 尃 (biểu âm) theo kiểu hình thanh. Nghĩa gốc là đánh, tấn công bằng tay. Từ đó mở rộng sang nghĩa đấu tranh, vật lộn (搏斗), đập nhanh (脉搏 — mạch đập), và chiến đấu hết mình (拼搏). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đánh, tát; bắt lấy", "Hạng Tần Suất (Jun Da)": "2367.0", "Tần Suất % (Jun Da)": "98.2115637516", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 尃", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌尃", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "尃", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "搏", "Unihan_Traditional (Chữ Phồn thể)": "搏", "Pinyin_Xie": "bó", "Âm Hán Việt_Xie": "bác", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ biểu thị hành động đấm đá, vật lộn hoặc nhịp đập của tim. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('咳', '{"9000": "2368.0", "Chữ Trung Quốc": "咳", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 9 | nét | 口 | khẩu | biểu nghĩa | miệng — phát ra tiếng ho | 亥 | hợi | biểu âm | gợi âm ''ké/hāi'' | 咳 = 口 (Khẩu, miệng) + 亥 (Hợi, biểu âm). Chữ hình thanh: tiếng phát ra từ miệng — nghĩa ''ho, ho khan''. Đọc ''hāi'' khi làm tiếng than thở.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt ''Hài'': từ miệng (口) bật ra tiếng ''hài/khái'' — đó là ''hài'', là tiếng ho. | Gương Hán-Việt | Cũng đọc ''khái'' khi nghĩa ''ho''. Trong tiếng Việt hiện đại 咳 thường dịch ''ho''. | Mở khoá kiến thức | Biết 咳 mở khóa 咳嗽 (khái thấu / ho), 止咳 (chỉ khái / cầm ho), 咳血 (khái huyết / ho ra máu).", "Tự nguyên_Xie": "Giáp cốt văn | Tiểu triện | Lục thư thông | Theo Wiktionary, 咳 là chữ hình thanh: 口 biểu nghĩa, 亥 biểu âm. Nghĩa ''ho''; cũng dùng làm thán từ (hāi). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ho", "Hạng Tần Suất (Jun Da)": "2368.0", "Tần Suất % (Jun Da)": "98.2138324384", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 亥", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口亥", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "亥", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "咳", "Unihan_Traditional (Chữ Phồn thể)": "咳", "Pinyin_Xie": "hāi", "Âm Hán Việt_Xie": "khái", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thán từ | 叹词 | Thường làm động từ chỉ hành động ho hoặc làm thán từ biểu thị sự tiếc nuối, thở dài ở đầu câu. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Thán từ | 叹词 | Bộc lộ cảm xúc hoặc dùng để gọi đáp: 啊, 哦, 喂. Đứng tách riêng ở đầu câu, không làm thành phần câu.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | hāi | / | tiếng than thở ''hai'' | Xuất hiện trong lộ trình | New HSK | New HSK 5 | · | Từ chức năng và phụ từ I", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('拢', '{"9000": "2369.0", "Chữ Trung Quốc": "拢", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 8 | nét | 扌 | thủ | biểu nghĩa | tay | 龙 | long | biểu âm | rồng | 拢 = 扌(Thủ, biểu nghĩa: tay) + 龙 (Long, biểu âm); chữ hình thanh. Bộ Thủ chỉ hành động của tay, 龙 cho âm long/lǒng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"long\": bàn tay (扌) vươn ra như con rồng (龙) thu mọi thứ lại — \"long\" là vươn tay gom gộp, kéo về một chỗ. | Gương Hán-Việt | \"long\" ít dùng độc lập; 靠拢 (kháo long = tiếp cận gần), 拢共 (long cộng = gộp tất cả lại) | Mở khoá kiến thức | Biết 拢 (long) mở khoá: 靠拢 (kháo long — tiếp cận gần), 拢共 (long cộng — tổng cộng).", "Tự nguyên_Xie": "拢 là dạng giản thể của 攏. Wiktionary chỉ ghi đây là giản thể không có mô tả chi tiết etymology. Dựa trên cấu trúc: 扌 (tay — biểu nghĩa) + 龙 (biểu âm). Nghĩa gốc là tụ lại, kéo gần lại bằng tay. Chưa có nguồn học thuật xác nhận thêm. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "họp lại; đánh đòn; đỗ thuyền", "Hạng Tần Suất (Jun Da)": "2369.0", "Tần Suất % (Jun Da)": "98.2161011251", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 龙", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌龙", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "龙", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "拢", "Unihan_Traditional (Chữ Phồn thể)": "攏", "Pinyin_Xie": "lǒng", "Âm Hán Việt_Xie": "long", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước tân ngữ để chỉ hành động thu gom, gộp chung hoặc đến gần. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('舅', '{"9000": "2370.0", "Chữ Trung Quốc": "舅", "Bộ thủ & thành phần_Xie": "Bộ thủ | 臼 | Số nét | 13 | nét | 臼 | cữu | biểu âm | cái cối (đá giã) | 男 | nam | biểu nghĩa | người đàn ông | 舅 = 臼 (Cữu, biểu âm) + 男 (Nam, biểu nghĩa: đàn ông); chữ hình thanh. Bộ 男 cho nghĩa người đàn ông trong họ hàng, 臼 cho âm (jiù ~ cữu).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cữu\": người đàn ông 男 (nam) của bên cối 臼 (cữu) — cậu 舅 là người đàn ông bên ngoại. | Gương Hán-Việt | cữu trong ''cậu cữu'' (cậu — anh/em trai của mẹ) | Mở khoá kiến thức | Biết 舅 (cữu) mở khoá: 舅舅 (cậu ruột), 舅妈 (vợ của cậu), 舅父 (cậu, cách gọi trang trọng).", "Tự nguyên_Xie": "Giáp cốt văn | Kim văn | Tiểu triện | Theo Wiktionary, 舅 là chữ hình thanh (psc): 臼 (cữu, biểu âm) + 男 (nam, biểu nghĩa: đàn ông). Nghĩa là anh/em trai của mẹ (cậu) hoặc cha vợ/cha chồng. Chữ chỉ người đàn ông trong quan hệ hôn nhân bên ngoài dòng họ cha. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1589.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Cữu (134) Nam (219)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Cữu (số 134 - cái cối/ 臼 /chỉ âm) ở trên bộ Nam (số 219 - đàn ông/ 男 /chỉ ý). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Cữu chỉ âm, bộ Nam chỉ ý. Cữu là anh hoặc em trai của mẹ (cậu). Cữu phụ là xưng hô tôn kính với cậu.", "Nghĩa Tiếng Việt_Xie": "cậu (anh, em của mẹ); bố chồng", "Hạng Tần Suất (Jun Da)": "2370.0", "Tần Suất % (Jun Da)": "98.2183672279", "GavinGrover_Once (Chiết tự trực tiếp)": "臼 + 男", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱臼男", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "男", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "臼", "Unihan_Simplified (Chữ Giản thể)": "舅", "Unihan_Traditional (Chữ Phồn thể)": "舅", "Pinyin_Xie": "jiù", "Âm Hán Việt_Xie": "cữu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ người thân trong gia đình, thường kết hợp thành từ ghép như cữu cữu. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('昧', '{"9000": "2371.0", "Chữ Trung Quốc": "昧", "Bộ thủ & thành phần_Xie": "Bộ thủ | 日 | Số nét | 9 | nét | 日 | nhật | biểu nghĩa | mặt trời, ngày | 未 | vị | biểu âm | chưa, chưa đến | 昧 = 日 (Nhật, biểu nghĩa: mặt trời) + 未 (Vị, biểu âm); chữ hình thanh. Bộ Nhật chỉ ánh sáng mặt trời bị che khuất, 未 cho âm muội/mèi.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"muội\": mặt trời (日) chưa (未) mọc lên — còn tối, \"muội\" là tối tăm, u mê, không thấy rõ. | Gương Hán-Việt | \"muội\" trong \"ngu muội\" (愚昧 — ngu dốt, tối tăm), \"muội lòng\" (昧心 — bán lương tâm) | Mở khoá kiến thức | Biết 昧 (muội) mở khoá: 愚昧 (ngu muội — ngu dốt), 暧昧 (ái muội — mơ hồ không rõ ràng), 冒昧 (mạo muội — tự tiện).", "Tự nguyên_Xie": "Theo Wiktionary, 昧 ghép 日 (mặt trời — biểu nghĩa) với 未 (biểu âm) theo kiểu hình thanh. Nghĩa gốc là mặt trời bị che khuất — trời tối, mờ mịt. Từ đó mở rộng sang nghĩa tối tăm, ngu dốt, tối tăm về đạo đức (昧良心 — bán lương tâm), mơ hồ không rõ ràng (暧昧). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "115.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Nhật (80) Vị (113)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Gồm chữ Nhật (số 80) và chữ Vị (số 113) . Lúc mặt trời chưa (vị) xuất hiện thì vạn vật còn tối tăm. Giải thích sự chuyển ý: Chữ Vị (chưa tới) chỉ âm, chữ Nhật (mặt trời) chỉ ý. Mặt trời (Nhật) chưa lên cao (Vị) nên không gian vẫn còn tối tăm, mờ mịt (Muội). *(Biến âm Hán Việt: Trong Hán ngữ cổ, chữ Vị và chữ Muội có cách phát âm tương đồng hoặc chung gốc phụ âm. Quá trình Việt hóa đã làm âm đọc bị chênh lệch thành Vị và Muội).*", "Nghĩa Tiếng Việt_Xie": "mờ mờ, tối tăm; ngu dốt", "Hạng Tần Suất (Jun Da)": "2371.0", "Tần Suất % (Jun Da)": "98.2206281629", "GavinGrover_Once (Chiết tự trực tiếp)": "日 + 未", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰日未", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "未", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "日", "Unihan_Simplified (Chữ Giản thể)": "昧", "Unihan_Traditional (Chữ Phồn thể)": "昧", "Pinyin_Xie": "mèi", "Âm Hán Việt_Xie": "muội", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường làm tính từ chỉ sự ngu tối, không rõ ràng hoặc làm động từ với nghĩa che giấu lương tâm. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('擅', '{"9000": "2372.0", "Chữ Trung Quốc": "擅", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 16 | nét | 扌 | thủ | biểu nghĩa | tay | 亶 | đản | biểu âm | thật sự, thành thật | 擅 = 扌(Thủ, biểu nghĩa: tay) + 亶 (Đản, biểu âm); chữ hình thanh. Bộ Thủ chỉ hành động nắm giữ, 亶 cho âm thiện/shàn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thiện\": tay (扌) nắm thành thật (亶) — \"thiện\" trong \"擅长\" là thực sự giỏi, tay nghề vững chắc; \"擅自\" là tự tay làm mà không xin phép. | Gương Hán-Việt | \"thiện\" trong \"擅长\" (thiện trường = giỏi về), \"擅自\" (thiện tự = tự ý); gần với \"thiện\" trong \"cải thiện\" | Mở khoá kiến thức | Biết 擅 (thiện) mở khoá: 擅长 (thiện trường — giỏi về), 擅自 (thiện tự — tự ý làm).", "Tự nguyên_Xie": "Đại triện | Theo Wiktionary, 擅 ghép 手 (tay — biểu nghĩa) với 亶 (biểu âm) theo kiểu hình thanh. Nghĩa gốc là tự mình nắm giữ, làm theo ý mình (不经许可自行处置). Từ đó mở rộng sang nghĩa giỏi về (擅长), tự ý làm (擅自). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "giỏi giang", "Hạng Tần Suất (Jun Da)": "2372.0", "Tần Suất % (Jun Da)": "98.2228875475", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 亶", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌亶", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "亶", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "擅", "Unihan_Traditional (Chữ Phồn thể)": "擅", "Pinyin_Xie": "shàn", "Âm Hán Việt_Xie": "thiện", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Thường làm động từ đứng trước một động từ khác để chỉ việc giỏi về lĩnh vực nào đó hoặc tự ý làm gì. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('爽', '{"9000": "2373.0", "Chữ Trung Quốc": "爽", "Bộ thủ & thành phần_Xie": "Bộ thủ | 爻 | Số nét | 11 | nét | 大 | đại | biểu hình | người lớn đứng dang tay | 㸚 | biểu hình | bốn nét hào (爻爻), ánh sáng xuyên qua | 爽 = 大 (Đại — người lớn đứng thẳng) + 㸚 (bốn nét hào, ánh sáng); chữ hội ý. Hình ảnh người đứng giữa ánh sáng chiếu bốn bề — sáng sủa, thông thoáng, sảng khoái.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sảng\": người (大) đứng giữa ánh sáng bốn phía (㸚) — \"sảng\" là cảm giác thoáng đãng, sảng khoái, như \"sảng khoái\" trong tiếng Việt. | Gương Hán-Việt | \"sảng\" trong \"sảng khoái\" (爽快 — dễ chịu, thẳng thắn); \"凉爽\" (lương sảng = mát mẻ) | Mở khoá kiến thức | Biết 爽 (sảng) mở khoá: 爽快 (sảng khoái — thẳng thắn, dứt khoát), 凉爽 (lương sảng — mát mẻ dễ chịu).", "Tự nguyên_Xie": "Đại triện | Tiểu triện | Theo Wiktionary, 爽 là chữ hội ý (ic) ghép 大 (người đứng — hình dạng lớn lao) với 㸚 (ánh sáng xuyên qua). Nghĩa là sáng, thông thoáng, dễ chịu. Từ đó mở rộng sang nghĩa sảng khoái, thẳng thắn (爽快), mát mẻ thoải mái (凉爽). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chỗ cao ráo sáng sủa", "Hạng Tần Suất (Jun Da)": "2373.0", "Tần Suất % (Jun Da)": "98.225144865", "GavinGrover_Once (Chiết tự trực tiếp)": "大 + 㸚", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴大㸚", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "㸚", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "大", "Unihan_Simplified (Chữ Giản thể)": "爽", "Unihan_Traditional (Chữ Phồn thể)": "爽", "Pinyin_Xie": "shuǎng", "Âm Hán Việt_Xie": "sảng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường làm tính từ bổ nghĩa cho danh từ hoặc làm vị ngữ để miêu tả trạng thái tinh thần, thời tiết dễ chịu. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | shuǎng | / | cảm thấy tốt | Xuất hiện trong lộ trình | New HSK | New HSK 6 | · | Tính cách", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('咖', '{"9000": "2374.0", "Chữ Trung Quốc": "咖", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 8 | nét | 口 | khẩu | biểu nghĩa | miệng — đánh dấu chữ phiên âm | 加 | gia | biểu âm | thêm vào — gợi âm ''gia/ca'' | 咖 = 口 (Khẩu, biểu nghĩa: âm thanh phiên âm) + 加 (Gia, biểu âm). Đây là chữ hình thanh (psc) tạo muộn để phiên âm từ ngoại lai ''cà'' (coffee, curry). Bộ 口 đánh dấu đây là chữ phiên âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt ''Ca'' (đọc ''kā'') chỉ dùng phiên âm. Nhớ: 口 (Khẩu, miệng) thêm 加 (Gia, thêm) — miệng phát âm ''ca'' để mượn tiếng nước ngoài cà-phê. | Gương Hán-Việt | Chữ 咖 (Ca) không có nghĩa Hán-Việt truyền thống — chỉ là kí tự phiên âm. Tiếng Việt cũng dùng âm ''cà'' tương tự trong ''cà phê''. | Mở khoá kiến thức | Nắm 咖 (Ca) mở khoá 咖啡 (cà phê), 咖喱 (cà ri), 大咖 (đại ca — VIP/nhân vật lớn — nghĩa lóng hiện đại).", "Tự nguyên_Xie": "Theo Wiktionary, 咖 là chữ hình thanh ghép 口 (miệng, biểu nghĩa — dùng để đánh dấu chữ phiên âm) và 加 (biểu âm). Đây là chữ được tạo ra muộn để phiên âm các từ ngoại lai như ''coffee'' (咖啡) và ''curry'' (咖喱). Chữ không có trong từ điển cổ và không xuất hiện trong giáp cốt văn, kim văn hay tiểu triện cổ. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: già phê 咖啡)", "Hạng Tần Suất (Jun Da)": "2374.0", "Tần Suất % (Jun Da)": "98.2274011488", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 加", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口加", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "加", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "咖", "Unihan_Traditional (Chữ Phồn thể)": "咖", "Pinyin_Xie": "kā", "Âm Hán Việt_Xie": "ca, già", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường không đứng độc lập mà kết hợp thành từ ghép để phiên âm hoặc chỉ nhân vật có tầm ảnh hưởng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('搁', '{"9000": "2375.0", "Chữ Trung Quốc": "搁", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 12 | nét | 扌 | thủ | biểu nghĩa | tay | 阁 | các | biểu âm | gác, tầng lầu | 搁 = 扌(Thủ, biểu nghĩa: tay) + 阁 (Các, biểu âm); chữ hình thanh. Bộ Thủ chỉ hành động dùng tay đặt vật, 阁 cho âm gác/các.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"các\": tay (扌) đặt thứ gì lên gác (阁) — \"các\" gợi hình ảnh để vật lên kệ cao, bỏ tạm đó. | Gương Hán-Việt | \"các\" trong \"搁置\" (các trí = để sang một bên), \"搁浅\" (các thiển = mắc cạn) | Mở khoá kiến thức | Biết 搁 (các) mở khoá: 搁置 (các trí — để sang một bên), 耽搁 (đam các — trì hoãn), 搁浅 (các thiển — mắc cạn).", "Tự nguyên_Xie": "搁 là dạng giản thể của 擱. Wiktionary chỉ ghi thông tin giản thể không có mô tả etymology chi tiết. Dựa trên cấu trúc: 扌 (tay — biểu nghĩa) + 阁 (biểu âm). Nghĩa gốc là đặt, để một vật ở đâu đó. Từ đó mở rộng sang nghĩa trì hoãn, bỏ xó (搁置), mắc cạn (搁浅). Chưa có nguồn học thuật xác nhận thêm. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đặt, để", "Hạng Tần Suất (Jun Da)": "2375.0", "Tần Suất % (Jun Da)": "98.2296538153", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 阁", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌阁", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "阁", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "搁", "Unihan_Traditional (Chữ Phồn thể)": "擱", "Pinyin_Xie": "gē", "Âm Hán Việt_Xie": "các", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ vị ngữ trong câu, có thể mang tân ngữ chỉ đồ vật hoặc đi kèm bổ ngữ xu hướng. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | gē | / | đặt | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Words II | HSK | HSK 6 | · | Căn nhà", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('禄', '{"9000": "2376.0", "Chữ Trung Quốc": "禄", "Bộ thủ & thành phần_Xie": "Bộ thủ | 示 | Số nét | 12 | nét | 礻 | thị | biểu nghĩa | thần linh, phúc lành (bộ thị) | 录 | lục | biểu âm | ghi chép — âm lù/lộc | 禄 = 礻/示 (Thị, biểu nghĩa: phúc lành từ thần linh) + 录/彔 (Lục, biểu âm); chữ hình thanh. Wiktionary xác nhận 示 + 彔 (c1=s, c2=p, ls=psc). Bộ 礻 gợi phúc lộc đến từ trời đất, phần 录 cho âm lù. Gốc nghĩa: bổng lộc, lương bổng của quan chức.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lộc\": 礻 (thần ban phúc) + 录 (ghi chép) — lộc là điều may mắn mà thần ghi tên vào sổ trời để ban cho người. | Gương Hán-Việt | phúc lộc (hạnh phúc và tài lộc), bổng lộc (lương bổng) | Mở khoá kiến thức | Biết 禄 mở khoá: phúc lộc thọ (福禄寿 — ba điều cầu chúc), bổng lộc (俸禄 — lương quan chức), thiên lộc (天禄 — phúc lành trời ban).", "Tự nguyên_Xie": "禄 là chữ hình thanh: bộ 示/礻 (thị, thần linh, phúc lành) biểu nghĩa, phần 彔 biểu âm — ls=psc. Wiktionary xác nhận cấu trúc này. Gốc nghĩa: bổng lộc (lương thưởng cho quan chức), hạnh phúc từ trời ban; nghĩa mở rộng: vinh hoa phú quý. Dùng trong khái niệm 福禄寿 (phúc lộc thọ — ba điều may mắn). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "phúc, tốt lành; bổng lộc", "Hạng Tần Suất (Jun Da)": "2376.0", "Tần Suất % (Jun Da)": "98.2319049313", "GavinGrover_Once (Chiết tự trực tiếp)": "礻 + 录", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰礻录", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "录", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "礻", "Unihan_Simplified (Chữ Giản thể)": "禄", "Unihan_Traditional (Chữ Phồn thể)": "祿", "Pinyin_Xie": "lù", "Âm Hán Việt_Xie": "lộc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng sau các động từ như hưởng, nhận hoặc kết hợp thành từ ghép chỉ quan chức, tài lộc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('雌', '{"9000": "2377.0", "Chữ Trung Quốc": "雌", "Bộ thủ & thành phần_Xie": "Bộ thủ | 隹 | Số nét | 14 | nét | 此 | thử | biểu âm | này, đây | 隹 | chuy | biểu nghĩa | chim đuôi ngắn | 雌 = 此 (Thử, biểu âm) + 隹 (Chuy, biểu nghĩa: chim); chữ hình thanh. Bộ Chuy chỉ loài chim, 此 cho âm thư/cí.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thư\": con chim (隹) \"này\" (此) là con cái — \"thư\" trong tiếng Việt cổ cũng chỉ giống cái (như \"thư hùng\" = âm dương). | Gương Hán-Việt | \"thư\" trong \"thư hùng\" (雌雄 = cái và đực); \"雌\" là giống cái của các loài chim | Mở khoá kiến thức | Biết 雌 (thư) mở khoá: 雌雄 (thư hùng — đực và cái), 雌性 (thư tính — giống cái).", "Tự nguyên_Xie": "Bạch thư | Tiểu triện | Theo Wiktionary, 雌 ghép 此 (biểu âm) với 隹 (chim — biểu nghĩa) theo kiểu hình thanh. Nghĩa gốc là con chim mái (cái). Từ đó mở rộng sang nghĩa giống cái nói chung, nhẹ nhàng, nhu mì. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1160.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thử (1159) Truy (202)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Thử (số 1159 - chỗ này/chỉ âm) ở bên trái chữ Truy (số 202 - chim đuôi ngắn/chỉ ý). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Thử chỉ âm, bộ Truy chỉ ý. Thư là con chim mái, giống cái, giống cái ở động vật (thư hùng).", "Nghĩa Tiếng Việt_Xie": "con chim mái", "Hạng Tần Suất (Jun Da)": "2377.0", "Tần Suất % (Jun Da)": "98.2341555306", "GavinGrover_Once (Chiết tự trực tiếp)": "此 + 隹", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰此隹", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "此", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "隹", "Unihan_Simplified (Chữ Giản thể)": "雌", "Unihan_Traditional (Chữ Phồn thể)": "雌", "Pinyin_Xie": "cí", "Âm Hán Việt_Xie": "thư", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Thường làm tính từ đứng trước danh từ để chỉ giới tính cái của động vật hoặc tính chất mềm yếu. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('哨', '{"9000": "2378.0", "Chữ Trung Quốc": "哨", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 10 | nét | 口 | khẩu | biểu nghĩa | miệng | 肖 | tiêu | biểu âm | nhỏ, giống | 哨 = 口 (Khẩu, biểu nghĩa: miệng) + 肖 (Tiêu, gần âm); chữ hình thanh. Bộ Khẩu chỉ âm thanh bằng miệng, 肖 gợi âm sáo/shào.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sáo\": miệng (口) thổi ra tiếng nhỏ cao vút (肖 = nhỏ, giống) — \"sáo\" gợi âm thanh còi, như tiếng thổi sáo hay còi hiệu lệnh. | Gương Hán-Việt | \"sáo\" là âm Hán-Việt của 哨; 口哨 (khẩu sáo = còi bằng miệng), 哨兵 (sáo binh = lính canh) | Mở khoá kiến thức | Biết 哨 (sáo) mở khoá: 口哨 (khẩu sáo — còi miệng), 哨兵 (sáo binh — lính gác), 放哨 (phóng sáo — canh gác).", "Tự nguyên_Xie": "Tiểu triện | Wiktionary có thông tin phát âm nhưng không mô tả cấu trúc etymology chi tiết cho 哨. Dựa trên cấu trúc: 口 (miệng — biểu nghĩa) + 肖 (biểu âm). Nghĩa gốc là tiếng chim kêu, âm thanh cao vang. Từ đó mở rộng sang nghĩa còi, trạm gác (哨所), tiếng thổi còi. Chưa có nguồn học thuật xác nhận thêm. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chòi canh, trạm gác; chim kêu; thổi còi", "Hạng Tần Suất (Jun Da)": "2378.0", "Tần Suất % (Jun Da)": "98.236405613", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 肖", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口肖", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "肖", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "哨", "Unihan_Traditional (Chữ Phồn thể)": "哨", "Pinyin_Xie": "shào", "Âm Hán Việt_Xie": "tiêu, sáo", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường làm danh từ chỉ trạm gác hoặc làm động từ khi kết hợp với từ chỉ hành động thổi còi, canh gác. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | shào | / | trạm gác | Xuất hiện trong lộ trình | HSK | HSK 6 | · | Lục quân và chiến tranh II", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('巩', '{"9000": "2379.0", "Chữ Trung Quốc": "巩", "Bộ thủ & thành phần_Xie": "Bộ thủ | 工 | Số nét | 6 | nét | 工 | công | biểu âm | công việc, thợ | 凡 | phàm | biểu hình | phàm, bình thường | 巩 = 工 (Công — thợ, công việc) + 凡 (Phàm — phàm trần); chữ hình thanh theo suy luận. Wiktionary dẫn đến 𢀜 mà không mô tả rõ. Dựa trên kim văn: hình ảnh thứ được trói chặt, vững bền. lsCodes trống nên đây là phân tích suy luận từ cấu trúc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"củng\": thợ (工) làm cho bình thường (凡) trở nên vững chắc — \"củng cố\" là gia cố, làm cho bền bỉ hơn. | Gương Hán-Việt | \"củng\" trong \"củng cố\" (巩固 — củng cố, tăng cường); 拱手 (củng thủ = khoanh tay kính lễ) | Mở khoá kiến thức | Biết 巩 (củng) mở khoá: 巩固 (củng cố — tăng cường), 巩义 (Củng Nghĩa — địa danh Trung Quốc).", "Tự nguyên_Xie": "Kim văn | Tiểu triện | Wiktionary dẫn đến 𢀜 nhưng không mô tả chi tiết etymology của 巩. Kim văn cho thấy hình dạng vật được buộc chặt. Nghĩa gốc là trói, buộc chắc. Từ đó mở rộng sang nghĩa vững chắc, kiên cố (巩固 — củng cố). Chưa có nguồn học thuật xác nhận đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "vững chắc, bền chặt", "Hạng Tần Suất (Jun Da)": "2379.0", "Tần Suất % (Jun Da)": "98.2386505277", "GavinGrover_Once (Chiết tự trực tiếp)": "工 + 凡", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰工凡", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "凡", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "工", "Unihan_Simplified (Chữ Giản thể)": "巩", "Unihan_Traditional (Chữ Phồn thể)": "鞏", "Pinyin_Xie": "gǒng", "Âm Hán Việt_Xie": "củng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Thường làm động từ mang tân ngữ là các danh từ trừu tượng như địa vị, quốc phòng, tình hữu nghị. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('绢', '{"9000": "2380.0", "Chữ Trung Quốc": "绢", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 10 | nét | 纟 | mịch | biểu nghĩa | sợi tơ, vải lụa | 肙 | biểu âm | gợi âm juàn (gồm 口+月) | 绢 = 纟/糸 (Mịch, biểu nghĩa: sợi tơ, lụa) + 肙 (biểu âm, gồm 口+月); chữ hình thanh. Wiktionary xác nhận 糸 + 肙 (c1=s, c2=p, ls=psc). Bộ 纟 chỉ đây là loại vải lụa, phần 肙 cho âm juàn. Gốc nghĩa: lụa thô — loại vải tơ mịn màng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quyên\": 纟 (sợi tơ) quấn quanh 肙 (ruột, lòng) — lụa quyên mỏng mịn như thứ tơ quấn quanh trái tim; dùng vẽ tranh thủy mặc. | Gương Hán-Việt | quyên bạch (lụa trắng), quyên hoa (lụa thêu hoa) | Mở khoá kiến thức | Biết 绢 mở khoá: quyên bạch (绢白 — trắng như lụa), tranh lụa (绢画 — tranh vẽ trên lụa), quyên hoa (绢花 — hoa giả bằng lụa).", "Tự nguyên_Xie": "绢 là chữ hình thanh: bộ 糸/纟 (mịch, sợi tơ) biểu nghĩa ''lụa'', phần 肙 biểu âm — ls=psc. Wiktionary xác nhận cấu trúc 糸 + 肙 (c1=s, c2=p). Gốc nghĩa: lụa thô (một loại lụa mỏng, mịn); khác với 丝 (sợi tơ) và 绸 (lụa nặng hơn). 绢 là loại vải tơ truyền thống dùng làm tranh thủy mặc, quạt, và đồ trang trí. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "vải lụa", "Hạng Tần Suất (Jun Da)": "2380.0", "Tần Suất % (Jun Da)": "98.2408907912", "GavinGrover_Once (Chiết tự trực tiếp)": "纟 + 肙", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰纟肙", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "肙", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "纟", "Unihan_Simplified (Chữ Giản thể)": "绢", "Unihan_Traditional (Chữ Phồn thể)": "絹", "Pinyin_Xie": "juàn", "Âm Hán Việt_Xie": "quyên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng độc lập hoặc làm định ngữ bổ nghĩa cho các danh từ chỉ đồ vật làm bằng lụa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('螺', '{"9000": "2381.0", "Chữ Trung Quốc": "螺", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 17 | nét | 虫 | trùng | biểu nghĩa | sâu bọ, sinh vật nhỏ | 累 | luỵ | biểu âm | chồng chất | 螺 = 虫 (Trùng, biểu nghĩa: sinh vật) + 累 (Luỵ, biểu âm); chữ hình thanh. Bộ 虫 xác định đây là loài sinh vật, 累 cho âm đọc gần với luó.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"loa\": con Trùng (虫) mang vỏ xoắn Luỵ (累) — hình ảnh con ốc cuộn tròn từng vòng. | Gương Hán-Việt | loa trong \"loa kèn\", \"loa phóng thanh\" — hình dạng xoắn như vỏ ốc | Mở khoá kiến thức | Biết 螺 mở khoá: 螺丝 (đinh vít), 螺旋 (xoắn ốc), 田螺 (ốc đồng).", "Tự nguyên_Xie": "Theo Wiktionary, 螺 là chữ hình thanh: 虫 (trùng) biểu nghĩa chỉ loài sinh vật, 累 biểu âm. Chữ chỉ con ốc xoắn, vỏ ốc hình xoắn ốc đặc trưng. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con ốc", "Hạng Tần Suất (Jun Da)": "2381.0", "Tần Suất % (Jun Da)": "98.2431269205", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 累", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫累", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "累", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "螺", "Unihan_Traditional (Chữ Phồn thể)": "螺", "Pinyin_Xie": "luó", "Âm Hán Việt_Xie": "loa", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ các loài thân mềm có vỏ xoắn hoặc làm định ngữ chỉ vật có hình dạng xoắn ốc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('裹', '{"9000": "2382.0", "Chữ Trung Quốc": "裹", "Bộ thủ & thành phần_Xie": "Bộ thủ | 衣 | Số nét | 14 | nét | 衣 | y | biểu nghĩa | quần áo, vải (bao quanh) | 果 | quả | biểu âm | trái cây (gần âm guǒ) | 裹 = 衣 (Y, biểu nghĩa: vải/áo — bao quanh) + 果 (Quả, biểu âm); chữ hình thanh. Đặc biệt 果 nằm GIỮA 衣 (bộ áo bị tách trên 亠 dưới 𧘇) — gợi rõ ý ''vải bao quanh quả'', nghĩa ''bọc, gói''.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khoả\": 衣 (vải/áo) bọc quanh 果 (quả) — đúng nghĩa ''bọc, gói'' trong 裹, 包裹. | Gương Hán-Việt | ''khoả'' trong ''khoả thân'' (cùng âm khác nghĩa) — gần ''gói'' trong tiếng Việt | Mở khoá kiến thức | Nắm 裹 mở khoá từ HSK 5-7: 裹, 包裹.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 裹 là hình thanh: 衣 (vải/áo, biểu nghĩa) + 果 (Quả, biểu âm). Cấu trúc đặc biệt: 衣 bị ''tách'' để bọc 果 vào giữa — như hình ảnh vải bọc quả. Nghĩa gốc ''bọc, gói'' giữ nguyên đến nay trong 裹, 包裹. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "299.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Y (295) Quả", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Quả (trái cây) nằm ở trong chữ Y (số 295 - tách ra) . Trái quả có cái vỏ bao bọc bên ngoài giống như người đang mặc áo. Giải thích sự chuyển ý: Chữ Quả (trái cây) chỉ âm, chữ Y (áo) chỉ ý. Dùng áo (Y) hoặc vải để bọc kín trái cây (Quả) hoặc đồ vật lại gọi là bọc, gói (Khỏa). *(Biến âm Hán Việt: Trong Hán ngữ cổ, chữ Quả và chữ Khỏa có cách phát âm tương đồng hoặc chung gốc phụ âm. Quá trình Việt hóa đã làm âm đọc bị chênh lệch thành Quả và Khỏa).*", "Nghĩa Tiếng Việt_Xie": "bọc, gói; cái bao", "Hạng Tần Suất (Jun Da)": "2382.0", "Tần Suất % (Jun Da)": "98.2453604658", "GavinGrover_Once (Chiết tự trực tiếp)": "衣 + 果", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴衣果", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "果", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "衣", "Unihan_Simplified (Chữ Giản thể)": "裹", "Unihan_Traditional (Chữ Phồn thể)": "裹", "Pinyin_Xie": "guǒ", "Âm Hán Việt_Xie": "khoả", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ vị ngữ, có thể kết hợp với bổ ngữ kết quả hoặc bổ ngữ xu hướng để chỉ hành động bao bọc. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | guǒ | / | bọc | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Words II", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('昔', '{"9000": "2383.0", "Chữ Trung Quốc": "昔", "Bộ thủ & thành phần_Xie": "Bộ thủ | 日 | Số nét | 8 | nét | 龷 | biểu hình | thảm hoạ, lũ lụt (hình dạng cổ) | 日 | nhật | biểu hình | mặt trời | 昔 là chữ hội ý theo giáp cốt văn. Hình ảnh thảm hoạ/lũ lụt (𡿧) nhấn chìm mặt trời (日) — những ngày tháng xa xưa khi lụt lội đã qua đi. Shuowen giải thích khác: hai miếng thịt (仌) phơi khô dưới nắng (日). Cả hai đều gợi ý quá khứ, ngày xưa.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tích\": mặt trời (日) bị lũ lụt (龷) nhấn chìm — những ngày tháng xa xưa, \"tích\" là ngày cũ đã qua, như \"tích sự\" hay \"hoài tích\". | Gương Hán-Việt | \"tích\" trong \"tích sự\" (chuyện xưa), \"hoài tích\" (nhớ chuyện cũ); 昔日 (tích nhật = ngày xưa) | Mở khoá kiến thức | Biết 昔 (tích) mở khoá: 昔日 (tích nhật — ngày xưa), 今昔 (kim tích — xưa và nay), 往昔 (vãng tích — ngày xưa).", "Tự nguyên_Xie": "Giáp cốt văn | Kim văn | Bạch thư | Đại triện | Tiểu triện | Theo Wiktionary, giáp cốt văn của 昔 là hội ý: thảm hoạ/lũ lụt (𡿧) nhấn chìm mặt trời (日) — thời điểm lụt lội đã trở thành quá khứ. Shuowen giải thích khác: hai miếng thịt (仌) phơi dưới nắng (日), là dạng gốc của 腊 (thịt khô). Chữ này không liên quan đến 展, 共, hay 散 dù hình dạng giống nhau. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1561.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Nhật (072)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Phần trên là bộ 廿 (chữ Cộng 共 giảm nét/ thịt khô tàn dư 𠈌). Phần dưới là bộ Nhật (số 072 - mặt trời/ ngày/ 日). Hình ảnh nhiều ngày gộp lại. Giải thích sự chuyển ý: Tích là những chuyện từ thuở rất lâu, rất xưa cũ, từ ngày xưa (tích thời, cổ tích, tích cựu).", "Nghĩa Tiếng Việt_Xie": "xưa, cũ, trước kia; đêm", "Hạng Tần Suất (Jun Da)": "2383.0", "Tần Suất % (Jun Da)": "98.2475929776", "GavinGrover_Once (Chiết tự trực tiếp)": "龷 + 日", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱龷日", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "龷", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "日", "Unihan_Simplified (Chữ Giản thể)": "昔", "Unihan_Traditional (Chữ Phồn thể)": "昔", "Pinyin_Xie": "xī", "Âm Hán Việt_Xie": "tích", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Phó từ | 副词 | Thường làm danh từ chỉ thời gian hoặc phó từ đứng trước động từ để chỉ hành động đã xảy ra trong quá khứ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Phó từ | 副词 | Bổ nghĩa cho động từ hoặc tính từ và luôn đứng TRƯỚC chúng — 都是, 很好. Không đứng sau như tiếng Việt và không bổ nghĩa cho danh từ.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('轩', '{"9000": "2384.0", "Chữ Trung Quốc": "轩", "Bộ thủ & thành phần_Xie": "Bộ thủ | 車 | Số nét | 7 | nét | 车 | xa | biểu nghĩa | xe | 干 | can | biểu âm | can thiệp, thân cây | 轩 = 车 (Xa, biểu nghĩa: xe) + 干 (Can, biểu âm); chữ hình thanh. Bộ 车 xác định đây là loại xe, 干 cho âm xuān gần với hiên.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hiên\": chiếc Xe (车) mui cao như cây Can (干) thẳng — tưởng tượng mái Hiên nhà cao ráo thoáng đãng. | Gương Hán-Việt | hiên trong \"hiên ngang\", \"thư hiên\" — mái hiên thoáng rộng | Mở khoá kiến thức | Biết 轩 mở khoá: 轩昂 (hiên ngang, oai vệ), 轩辕 (Hiên Viên — tên vua Hoàng Đế).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Theo Wiktionary, 轩 (dạng phồn thể 軒) là chữ hình thanh: 車 (xa) biểu nghĩa chỉ xe, 干 biểu âm. Ban đầu chỉ loại xe mui cao có rèm che dành cho quý tộc thời cổ; về sau mở rộng nghĩa thành hiên nhà, phòng học nhỏ. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "xe có mái che; mái hiên bằng phẳng", "Hạng Tần Suất (Jun Da)": "2384.0", "Tần Suất % (Jun Da)": "98.2498172208", "GavinGrover_Once (Chiết tự trực tiếp)": "车 + 干", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰车干", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "干", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "车", "Unihan_Simplified (Chữ Giản thể)": "轩", "Unihan_Traditional (Chữ Phồn thể)": "軒", "Pinyin_Xie": "xuān", "Âm Hán Việt_Xie": "hiên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Chữ này thường dùng làm danh từ chỉ hiên nhà hoặc tính từ chỉ sự cao ráo, hiên ngang. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('谬', '{"9000": "2385.0", "Chữ Trung Quốc": "谬", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 13 | nét | 讠 | biểu nghĩa | ngôn (lời nói) | 翏 | liệu | biểu âm | âm phù | 谬 = 讠(Ngôn, biểu nghĩa: lời nói) + 翏 (Liệu, biểu âm); chữ hình thanh. Bộ Ngôn chỉ lời nói, 翏 cho âm liệu/mậu gần miù.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mậu\": lời nói (讠) bay liệng lạc lối (翏 = liệng) — \"mậu\" là lời sai, \"mậu luận\" là lý luận sai bét. | Gương Hán-Việt | \"mậu\" trong \"mậu luận\" (謬論 = lý luận sai); 荒谬 (hoang mậu = vô lý hoang đường) | Mở khoá kiến thức | Biết 谬 (mậu) mở khoá: 荒谬 (hoang mậu — vô lý), 谬论 (mậu luận — luận điểm sai), 谬误 (mậu ngộ — lầm lẫn).", "Tự nguyên_Xie": "Tiểu triện | 谬 là dạng giản thể của 謬. Wiktionary chỉ ghi thông tin giản thể không mô tả chi tiết etymology. Dựa trên cấu trúc: 讠/言 (lời nói — biểu nghĩa) + 翏 (biểu âm). Nghĩa gốc là lời nói sai lầm, cường điệu. Từ đó mở rộng sang nghĩa sai lầm, vô lý, bậy bạ (荒谬 — vô lý, hoang đường). Chưa có nguồn học thuật xác nhận thêm. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nói xằng, nói bậy; sai lầm", "Hạng Tần Suất (Jun Da)": "2385.0", "Tần Suất % (Jun Da)": "98.2520342291", "GavinGrover_Once (Chiết tự trực tiếp)": "讠 + 翏", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰讠翏", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "翏", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "讠", "Unihan_Simplified (Chữ Giản thể)": "谬", "Unihan_Traditional (Chữ Phồn thể)": "謬", "Pinyin_Xie": "miù", "Âm Hán Việt_Xie": "mậu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Động từ | 动词 | Thường dùng làm tính từ để chỉ sự sai lệch, nhầm lẫn hoặc kết hợp tạo danh từ như sai lầm. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('谍', '{"9000": "2386.0", "Chữ Trung Quốc": "谍", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 11 | nét | 讠 | biểu nghĩa | ngôn (lời nói, tin tức) | 枼 | biểu âm | âm phù (gồm 世 + 木) | 谍 = 讠(Ngôn, biểu nghĩa: lời nói, thông tin) + 枼 (biểu âm: gồm 世 — Thế và 木 — Mộc); chữ hình thanh. Bộ Ngôn chỉ tin tức, thông tin bí mật, phần còn lại cho âm điệp/dié.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"điệp\": lời nói (讠) luồn qua nhiều thế hệ (世) như lá cây (木) — \"điệp viên\" là người lén lút truyền tin bí mật. | Gương Hán-Việt | \"điệp\" trong \"gián điệp\" (间谍 = điệp viên), \"điệp báo\" (谍报 = tin tình báo) | Mở khoá kiến thức | Biết 谍 (điệp) mở khoá: 间谍 (gián điệp — spy), 谍报 (điệp báo — tin tình báo), 特谍 (đặc điệp — điệp viên đặc biệt).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 谍 là dạng giản thể của 諜. Wiktionary chỉ ghi thông tin giản thể không có mô tả etymology chi tiết. Dựa trên cấu trúc: 言/讠 (lời nói, thông tin — biểu nghĩa) + 枼 (biểu âm). Nghĩa gốc là báo cáo tình báo, do thám. Từ đó sinh ra 间谍 (gián điệp — người do thám bí mật). Chưa có nguồn học thuật xác nhận thêm. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "gián điệp, điệp viên", "Hạng Tần Suất (Jun Da)": "2386.0", "Tần Suất % (Jun Da)": "98.2542429687", "GavinGrover_Once (Chiết tự trực tiếp)": "讠 + 枼", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰讠枼", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "枼", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "讠", "Unihan_Simplified (Chữ Giản thể)": "谍", "Unihan_Traditional (Chữ Phồn thể)": "諜", "Pinyin_Xie": "dié", "Âm Hán Việt_Xie": "điệp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường làm danh từ chỉ người làm nhiệm vụ do thám hoặc động từ chỉ hành vi do thám tin tức. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('龟', '{"9000": "2387.0", "Chữ Trung Quốc": "龟", "Bộ thủ & thành phần_Xie": "Bộ thủ | 龜 | Số nét | 7 | nét | 龟 | quy | tượng hình | con rùa nhìn nghiêng, thấy rõ mai và đầu | 龟 là chữ tượng hình độc lập: phác hoạ hình con rùa nhìn từ bên và trên (giáp cốt văn và kim văn rõ nét). Không phân tích thành các bộ phận có nghĩa rời.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quy\": nhìn từ trên xuống thấy con Rùa (龜) — mai tròn, đầu nhô ra, bốn chân xòe; chữ vẽ thẳng hình con vật. | Gương Hán-Việt | quy trong \"quy tắc\" (quy → rùa sống lâu → luật lâu bền), \"quy hoạch\" | Mở khoá kiến thức | Biết 龟 mở khoá: 乌龟 (con rùa), 龟裂 (nứt nẻ như mai rùa), 龟缩 (thu mình như rùa).", "Tự nguyên_Xie": "Giáp cốt văn | Kim văn | Đại triện | Tiểu triện | Theo Wiktionary, 龟 (phồn thể 龜) là chữ tượng hình: hình vẽ con rùa nhìn nghiêng từ trên xuống, thấy rõ mai, đầu và chân trong văn tự giáp cốt và kim văn thời Thương. Đây là một trong những chữ tượng hình cổ nhất còn lưu giữ dạng gốc. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: khưu từ 龜茲,龟兹)", "Hạng Tần Suất (Jun Da)": "2387.0", "Tần Suất % (Jun Da)": "98.2564470573", "GavinGrover_Once (Chiết tự trực tiếp)": "⺈ + 电", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺈电", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "电", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺈", "Unihan_Simplified (Chữ Giản thể)": "龟", "Unihan_Traditional (Chữ Phồn thể)": "龜", "Pinyin_Xie": "guī", "Âm Hán Việt_Xie": "quy, quân, khâu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng độc lập hoặc làm thành phần cấu tạo từ để chỉ loài rùa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | guī | / | rùa | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Động vật và côn trùng", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('媳', '{"9000": "2388.0", "Chữ Trung Quốc": "媳", "Bộ thủ & thành phần_Xie": "Bộ thủ | 女 | Số nét | 13 | nét | 女 | nữ | biểu nghĩa | phụ nữ | 息 | tức | biểu âm | hơi thở, nghỉ ngơi, sinh lãi | 媳 = 女 (Nữ, biểu nghĩa: phụ nữ) + 息 (Tức, biểu âm); chữ hình thanh. Bộ Nữ chỉ đây là người phụ nữ, 息 cho âm tức/xí.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tức\": người phụ nữ (女) về nhà thở hơi (息 = hơi thở) cùng gia đình chồng — \"con dâu\" (媳妇) là người nữ mang theo hơi thở mới vào nhà. | Gương Hán-Việt | \"tức\" trong \"con tức\" (con dâu — cách gọi cũ); 媳妇 (tức phụ = con dâu, vợ) | Mở khoá kiến thức | Biết 媳 (tức) mở khoá: 媳妇 (tức phụ — con dâu, vợ), 儿媳 (nhi tức — con dâu).", "Tự nguyên_Xie": "Theo Wiktionary, 媳 ghép 女 (phụ nữ — biểu nghĩa) với 息 (biểu âm) theo kiểu hình thanh. Nghĩa gốc là con dâu — người phụ nữ đến sống trong gia đình chồng. Từ 媳妇 chỉ con dâu, sau dùng rộng hơn để chỉ vợ (trong khẩu ngữ phương bắc). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con dâu", "Hạng Tần Suất (Jun Da)": "2388.0", "Tần Suất % (Jun Da)": "98.2586495956", "GavinGrover_Once (Chiết tự trực tiếp)": "女 + 息", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰女息", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "息", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "女", "Unihan_Simplified (Chữ Giản thể)": "媳", "Unihan_Traditional (Chữ Phồn thể)": "媳", "Pinyin_Xie": "xí", "Âm Hán Việt_Xie": "tức", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong các từ ghép chỉ quan hệ gia đình như con dâu hoặc vợ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('姜', '{"9000": "2389.0", "Chữ Trung Quốc": "姜", "Bộ thủ & thành phần_Xie": "Bộ thủ | 女 | Số nét | 9 | nét | 羊 | dương | biểu âm | con dê/cừu | 女 | nữ | biểu nghĩa | phụ nữ | 姜 = 羊 (Dương, biểu âm) + 女 (Nữ, biểu nghĩa); chữ hình thanh. Bộ 女 chỉ phạm trù người, 羊 cho âm jiāng gần với khương.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khương\": con Dương (羊) và người Nữ (女) — họ Khương là dòng tộc cổ gắn với đồng cỏ và chăn nuôi dê cừu. | Gương Hán-Việt | khương trong \"sinh khương\" (gừng tươi), họ Khương | Mở khoá kiến thức | Biết 姜 mở khoá: 生姜 (gừng tươi), 姜黄 (nghệ), 老姜 (gừng già).", "Tự nguyên_Xie": "Giáp cốt văn | Kim văn | Theo Wiktionary, 姜 là chữ hình thanh: 女 (nữ) biểu nghĩa, 羊 (dương) biểu âm. Ban đầu là họ tộc cổ đại Trung Hoa gắn với bộ tộc chăn nuôi; về sau kiêm nghĩa cây gừng (gừng vị cay, tên gốc là 薑, nhưng 姜 thường dùng thay). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cây gừng; họ Khương", "Hạng Tần Suất (Jun Da)": "2389.0", "Tần Suất % (Jun Da)": "98.260851617", "GavinGrover_Once (Chiết tự trực tiếp)": "羊 + 女", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱羊女", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "女", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "羊", "Unihan_Simplified (Chữ Giản thể)": "姜", "Unihan_Traditional (Chữ Phồn thể)": "姜", "Pinyin_Xie": "jiāng", "Âm Hán Việt_Xie": "khương", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ chỉ cây gừng, củ gừng hoặc dùng làm họ của người. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | jiāng | / | gừng | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Thực phẩm II", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('瞎', '{"9000": "2390.0", "Chữ Trung Quốc": "瞎", "Bộ thủ & thành phần_Xie": "Bộ thủ | 目 | Số nét | 15 | nét | 目 | mục | biểu nghĩa | mắt | 害 | hại | biểu âm | gây hại, nguy hại | 瞎 = 目 (Mục, biểu nghĩa: mắt) + 害 (Hại, biểu âm); chữ hình thanh. Bộ 目 cho nghĩa liên quan đến mắt/thị giác, 害 cho âm (xiā ~ hạt). Mắt bị hư hại, mù.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hạt\": mắt 目 (mục) bị hại 害 (hại) — 瞎 là mù, mắt không nhìn thấy, làm bừa không nhìn. | Gương Hán-Việt | hạt trong ''hạt mục'' (mù mắt) | Mở khoá kiến thức | Biết 瞎 (hạt) mở khoá: 瞎说 (nói bừa), 瞎搞 (làm bừa), 瞎想 (nghĩ bậy), 眼瞎 (mù mắt).", "Tự nguyên_Xie": "Theo cấu trúc chữ, 瞎 là chữ hình thanh: 目 (mục, biểu nghĩa: mắt) + 害 (hại, biểu âm). Nghĩa gốc là mù — mắt bị hại/tổn thương. Sau mở rộng sang nghĩa ''làm bừa, làm liều không có mục đích'' (瞎说 = nói bừa). | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mù loà", "Hạng Tần Suất (Jun Da)": "2390.0", "Tần Suất % (Jun Da)": "98.2630531217", "GavinGrover_Once (Chiết tự trực tiếp)": "目 + 害", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰目害", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "害", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "目", "Unihan_Simplified (Chữ Giản thể)": "瞎", "Unihan_Traditional (Chữ Phồn thể)": "瞎", "Pinyin_Xie": "xiā", "Âm Hán Việt_Xie": "hạt", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Phó từ | 副词 | Thường làm tính từ chỉ trạng thái mù lòa hoặc làm phó từ đứng trước động từ với nghĩa làm càn, làm bừa. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Phó từ | 副词 | Bổ nghĩa cho động từ hoặc tính từ và luôn đứng TRƯỚC chúng — 都是, 很好. Không đứng sau như tiếng Việt và không bổ nghĩa cho danh từ.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | Từ đơn | Từ vựng HSK 5: mù quáng, không mục đích | / | xiā | / | mù quáng, không mục đích | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Quá trình hành động II | HSK | HSK 5 | · | Quá trình hành động I", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('冤', '{"9000": "2391.0", "Chữ Trung Quốc": "冤", "Bộ thủ & thành phần_Xie": "Bộ thủ | 冖 | Số nét | 10 | nét | 冖 | mịch | biểu hình | mái che, áp xuống | 兔 | thỏ | biểu hình | con thỏ | 冤 là chữ hội ý: 冖 (mái che, áp xuống) + 兔 (Thỏ — con thỏ). Hình ảnh con thỏ bị nhốt dưới mái che không thoát ra được — oan ức, bị ép buộc oan uổng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"oan\": con thỏ (兔) bị nhốt dưới mái (冖) không thoát ra — \"oan\" là bị ép oan, như \"oan Thị Kính\" trong văn học Việt. | Gương Hán-Việt | \"oan\" trong \"oan ức\" (冤屈 = oan khuất), \"oan hồn\" (冤魂 = hồn oan), \"giải oan\" (雪冤 = minh oan) | Mở khoá kiến thức | Biết 冤 (oan) mở khoá: 冤枉 (oan uổng — oan uổng, tốn vô ích), 冤屈 (oan khuất), 申冤 (thân oan — kêu oan).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 冤 là chữ hội ý ghép 冖 (che phủ) với 兔 (con thỏ). Hình ảnh con thỏ bị nhốt dưới mái không thoát ra — gợi ý bị ràng buộc, không được giải oan. Nghĩa gốc là oan uổng, bị đối xử bất công. Từ đó mở rộng sang nghĩa thù oán, không đáng (冤枉 — oan uổng, tốn công vô ích). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "oan uổng, oan khuất", "Hạng Tần Suất (Jun Da)": "2391.0", "Tần Suất % (Jun Da)": "98.265245841", "GavinGrover_Once (Chiết tự trực tiếp)": "冖 + 兔", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱冖兔", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "兔", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "冖", "Unihan_Simplified (Chữ Giản thể)": "冤", "Unihan_Traditional (Chữ Phồn thể)": "冤", "Pinyin_Xie": "yuān", "Âm Hán Việt_Xie": "oan", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Động từ | 动词 | Thường dùng làm danh từ chỉ nỗi oan hoặc tính từ chỉ sự oan uổng, đôi khi làm động từ với nghĩa đổ oan. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | yuān | / | xui xẻo, mất mát | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Thái độ với người khác II", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鸦', '{"9000": "2392.0", "Chữ Trung Quốc": "鸦", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鳥 | Số nét | 9 | nét | 牙 | nha | biểu âm | răng | 鸟 | điểu | biểu nghĩa | chim | 鸦 = 牙 (Nha, biểu âm: răng) + 鸟 (Điểu, biểu nghĩa: chim); chữ hình thanh. Bộ Điểu chỉ đây là loài chim, 牙 cho âm nha.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nha\": con chim (鸟) kêu như răng cắn nhau (牙 — răng) — \"nha\" là tiếng quạ kêu \"nha nha\", chim đen kêu khàn khàn. | Gương Hán-Việt | \"nha\" trong \"ô nha\" (鸦 = con quạ); 鸦雀无声 (nha tước vô thanh = im lặng tuyệt đối) | Mở khoá kiến thức | Biết 鸦 (nha) mở khoá: 鸦雀无声 (nha tước vô thanh — im lặng như tờ), 乌鸦 (ô nha — con quạ đen).", "Tự nguyên_Xie": "鸦 là dạng giản thể của 鴉. Wiktionary chỉ ghi thông tin giản thể không mô tả etymology chi tiết. Dựa trên cấu trúc: 鸟 (chim — biểu nghĩa) + 牙 (biểu âm). Con quạ (鸦) có màu đen tuyền, tiếng kêu khàn khàn như \"nha nha\". Chưa có nguồn học thuật xác nhận thêm. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con quạ khoang; màu đen", "Hạng Tần Suất (Jun Da)": "2392.0", "Tần Suất % (Jun Da)": "98.2674349429", "GavinGrover_Once (Chiết tự trực tiếp)": "牙 + 鸟", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰牙鸟", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "鸟", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "牙", "Unihan_Simplified (Chữ Giản thể)": "鸦", "Unihan_Traditional (Chữ Phồn thể)": "鴉", "Pinyin_Xie": "yā", "Âm Hán Việt_Xie": "nha", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ để chỉ loài chim quạ hoặc cấu tạo từ chỉ màu đen như mực. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蓬', '{"9000": "2393.0", "Chữ Trung Quốc": "蓬", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 13 | nét | 艹 | thảo | biểu nghĩa | cỏ, thực vật | 逢 | phùng | biểu âm | gặp gỡ | 蓬 = 艹(Thảo, biểu nghĩa: cỏ, thực vật) + 逢 (Phùng, biểu âm); chữ hình thanh. Bộ Thảo chỉ đây là loài thực vật, 逢 cho âm bồng/péng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bồng\": cỏ (艹) gặp gỡ (逢) gió và bốc lên — \"bồng\" như cỏ bồng tung bay, hoặc \"bồng bột\" khi nói về sức sống. | Gương Hán-Việt | \"bồng\" trong \"bồng bột\" (蓬勃 = phát triển mạnh), \"tóc bồng\" (bù xù); 蓬勃 (bồng bột = hừng hực) | Mở khoá kiến thức | Biết 蓬 (bồng) mở khoá: 蓬勃 (bồng bột — phát triển mạnh mẽ), 朝气蓬勃 (triều khí bồng bột — tràn đầy sức sống).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Theo Wiktionary, 蓬 ghép 艸 (cỏ — biểu nghĩa) với 逢 (biểu âm) theo kiểu hình thanh. Nghĩa gốc là cỏ bồng — loại cỏ dại mọc lung tung, thường bị gió thổi đi (飞蓬 — bồng bềnh như cỏ bồng). Từ đó mở rộng sang nghĩa bù xù, mọc tơi tả, rồi cả ý nghĩa phát triển mạnh mẽ (蓬勃 — bồng bột, hừng hực). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cỏ bồng; bù xù", "Hạng Tần Suất (Jun Da)": "2393.0", "Tần Suất % (Jun Da)": "98.2696183601", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 逢", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹逢", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "逢", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "蓬", "Unihan_Traditional (Chữ Phồn thể)": "蓬", "Pinyin_Xie": "péng", "Âm Hán Việt_Xie": "bồng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Thường làm danh từ chỉ một loại cỏ hoặc làm tính từ miêu tả trạng thái tóc tai bù xù, rối rắm. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('巷', '{"9000": "2394.0", "Chữ Trung Quốc": "巷", "Bộ thủ & thành phần_Xie": "Bộ thủ | 己 | Số nét | 9 | nét | 共 | cộng | biểu âm | cùng nhau | 巳 | tỵ | biểu nghĩa | chi Tỵ; gợi ý đường đi uốn lượn | 巷 = 共 (Cộng, biểu âm) + 己/巳 (biểu nghĩa theo Wiktionary: bản thân, gợi đường ngoằn ngoèo); chữ hình thanh. Bộ dưới gợi ý con đường quanh co trong khu dân cư, 共 cho âm hạng/xiàng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hạng\": mọi người (共 = cùng nhau) đi trong ngõ hẻm uốn khúc (巳 = con đường nhỏ) — \"hạng\" trong \"hạng nhất\", nhưng ở đây là đường hẻm cộng đồng. | Gương Hán-Việt | \"hạng\" trong \"巷道\" (hạng đạo = đường hầm mỏ); \"đại lộ tiểu hạng\" (大街小巷 = đường lớn ngõ nhỏ) | Mở khoá kiến thức | Biết 巷 (hạng) mở khoá: 大街小巷 (đại nhai tiểu hạng — phố lớn ngõ nhỏ), 巷道 (hạng đạo — đường hầm).", "Tự nguyên_Xie": "Đại triện | Theo Wiktionary, 巷 ghép 共 (biểu âm) với 己 (bản thân, tự mình — biểu nghĩa theo kiểu hình thanh). Nghĩa gốc là con đường hẻm nhỏ trong khu dân cư — con đường \"của riêng\" từng hộ. Từ đó chỉ ngõ nhỏ, hẻm, đường trong khu xóm. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1212.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Cộng (372) Tị (049)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Cộng (số 372 - chung) ở trên chữ Tị (số 049 - can Tỵ/ 己). Lối đi chung hẹp quanh co. Giải thích sự chuyển ý: Đây là chữ Hội ý. Hạng là ngõ hẻm, lối xóm, đường đi chật hẹp trong xóm (phố hạng).", "Nghĩa Tiếng Việt_Xie": "đường hẻm, ngõ hẻm", "Hạng Tần Suất (Jun Da)": "2394.0", "Tần Suất % (Jun Da)": "98.2717997101", "GavinGrover_Once (Chiết tự trực tiếp)": "共 + 巳", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱共巳", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "共", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "巳", "Unihan_Simplified (Chữ Giản thể)": "巷", "Unihan_Traditional (Chữ Phồn thể)": "巷", "Pinyin_Xie": "xiàng", "Âm Hán Việt_Xie": "hạng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ chỉ lối đi nhỏ, ngõ ngách trong đô thị hoặc làng mạc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | xiàng | / | hẻm | Xuất hiện trong lộ trình | HSK | HSK 6 | · | Địa điểm", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('琳', '{"9000": "2395.0", "Chữ Trung Quốc": "琳", "Bộ thủ & thành phần_Xie": "Bộ thủ | 玉 | Số nét | 12 | nét | 王 | vương | biểu nghĩa | ngọc (bộ 王 = 玉 khi làm bộ thủ) | 林 | lâm | biểu âm | rừng cây | 琳 = 王/玉 (Vương/Ngọc, biểu nghĩa: ngọc quý) + 林 (Lâm, biểu âm); chữ hình thanh. Bộ 王 đứng trái là biến thể của 玉, xác định đây là loại ngọc đẹp, 林 cho âm lín gần với lâm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lâm\": bộ Ngọc (王) kết hợp Lâm (林) — viên ngọc quý sáng như ánh nắng xuyên qua rừng cây. | Gương Hán-Việt | lâm trong tên người (琳 thường dùng trong tên con gái — ngọc sáng) | Mở khoá kiến thức | Biết 琳 mở khoá: 琳琅满目 (琳琅: đồ đẹp đầy mắt), 璆琳 (ngọc quý).", "Tự nguyên_Xie": "Tiểu triện | Wiktionary ghi nhận 琳 có bộ 王 (玉) biểu nghĩa chỉ ngọc, 林 biểu âm. Chữ chỉ loại ngọc đẹp quý giá; xuất hiện trong Kinh Thư \"Cống Vũ\" với cụm \"璆琳琅玕\" chỉ các loại ngọc quý của đất. Chưa có nguồn học thuật chi tiết hơn về giai đoạn giáp cốt. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ngọc lâm", "Hạng Tần Suất (Jun Da)": "2395.0", "Tần Suất % (Jun Da)": "98.2739795098", "GavinGrover_Once (Chiết tự trực tiếp)": "王 + 林", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰王林", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "林", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "王", "Unihan_Simplified (Chữ Giản thể)": "琳", "Unihan_Traditional (Chữ Phồn thể)": "琳", "Pinyin_Xie": "lín", "Âm Hán Việt_Xie": "lâm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ chỉ một loại ngọc đẹp, xuất hiện nhiều trong tên người hoặc từ ghép chỉ vẻ đẹp quý giá. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('栽', '{"9000": "2396.0", "Chữ Trung Quốc": "栽", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 10 | nét | 𢦏 | biểu âm | âm phù (戈 + 十) | 木 | mộc | biểu nghĩa | cây | 栽 = 𢦏 (gồm 戈 Qua + 十 Thập, biểu âm) + 木 (Mộc, biểu nghĩa: cây); chữ hình thanh. Bộ Mộc chỉ liên quan đến cây cối, 𢦏 cho âm tài/zāi.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tài\": cây (木) được cắm xuống đất bằng công cụ sắc bén (𢦏 = vũ khí cắm) — \"tài\" gợi hành động cắm, trồng mạ xuống đất. | Gương Hán-Việt | \"tài\" trong 栽培 (tài bồi = trồng trọt, vun đắp); gần với 才 (tài năng) nhưng khác nghĩa | Mở khoá kiến thức | Biết 栽 (tài) mở khoá: 栽培 (tài bồi — trồng trọt, đào tạo), 盆栽 (bồn tài — chậu bonsai).", "Tự nguyên_Xie": "Kim văn | Tiểu triện | Lục thư thông | Theo Wiktionary, 栽 ghép 木 (cây — biểu nghĩa) với 𢦏 (biểu âm) theo kiểu hình thanh. Nghĩa gốc là trồng cây, gieo trồng. Từ đó mở rộng sang nghĩa cây giống, chăm sóc cây (栽培), cắm xuống, và theo nghĩa rộng là ngã (栽跟头 — vấp ngã), thất bại. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "trồng trọt; cây", "Hạng Tần Suất (Jun Da)": "2396.0", "Tần Suất % (Jun Da)": "98.2761577592", "GavinGrover_Once (Chiết tự trực tiếp)": "𢦏 + 木", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴𢦏木", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "𢦏", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "栽", "Unihan_Traditional (Chữ Phồn thể)": "栽", "Pinyin_Xie": "zāi", "Âm Hán Việt_Xie": "tài", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường làm động từ đứng trước danh từ chỉ cây cối để biểu thị hành động trồng trọt. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('沾', '{"9000": "2397.0", "Chữ Trung Quốc": "沾", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 8 | nét | 氵 | thuỷ | biểu nghĩa | nước | 占 | chiêm | biểu âm | chiêm, xem bói, chiếm | 沾 = 氵(Thuỷ, biểu nghĩa: nước) + 占 (Chiêm, biểu âm); chữ hình thanh. Bộ Thuỷ chỉ liên quan đến nước, 占 cho âm triêm/zhān.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"triêm\": nước (氵) chiếm lĩnh (占) vào vật — \"triêm\" là thấm, dính, như \"triêm ân\" (hưởng ân huệ) hay \"thấm triêm\". | Gương Hán-Việt | \"triêm\" trong \"triêm ân\" (hưởng ân huệ); 沾光 (triêm quang = hưởng ké lợi ích), 沾染 (triêm nhiễm = tiêm nhiễm) | Mở khoá kiến thức | Biết 沾 (triêm) mở khoá: 沾光 (triêm quang — hưởng ké), 沾染 (triêm nhiễm — bị tiêm nhiễm).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 沾 ghép 水 (nước — biểu nghĩa) với 占 (biểu âm) theo kiểu hình thanh. Chữ Ganlu Zishu coi đây là dạng không chuẩn của 霑 (cùng nghĩa, với bộ vũ 雨 — mưa). Nghĩa gốc là thấm ướt, dính nước. Từ đó mở rộng sang nghĩa tiêm nhiễm, hưởng lợi từ người khác (沾光 — hưởng ké). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thấm ướt, ngấm vào; tiêm nhiễm; đụng chạm; được, có thể", "Hạng Tần Suất (Jun Da)": "2397.0", "Tần Suất % (Jun Da)": "98.2783287735", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 占", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵占", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "占", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "沾", "Unihan_Traditional (Chữ Phồn thể)": "沾", "Pinyin_Xie": "zhān", "Âm Hán Việt_Xie": "triêm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đi kèm tân ngữ chỉ chất lỏng hoặc lợi ích để biểu thị sự tiếp xúc. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | zhān | / | thấm | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Từ III", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('诈', '{"9000": "2398.0", "Chữ Trung Quốc": "诈", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 7 | nét | 讠 | biểu nghĩa | ngôn (lời nói) | 乍 | sạ | biểu âm | đột ngột, vừa mới | 诈 = 讠(Ngôn, biểu nghĩa: lời nói) + 乍 (Sạ, biểu âm); chữ hình thanh. Bộ Ngôn chỉ lời nói lừa đảo, 乍 cho âm trá/zhà.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trá\": lời nói (讠) đột ngột biến đổi (乍 = đột ngột) — \"trá\" là lừa dối, như \"gian trá\" hay \"lừa trá\". | Gương Hán-Việt | \"trá\" trong \"gian trá\" (奸诈 = gian manh), \"lừa trá\"; 诈骗 (trá phiến = lừa đảo) | Mở khoá kiến thức | Biết 诈 (trá) mở khoá: 诈骗 (trá phiến — lừa đảo), 奸诈 (gian trá — gian manh), 欺诈 (khi trá — lừa gạt).", "Tự nguyên_Xie": "Kim văn | Tiểu triện | 诈 là dạng giản thể của 詐. Wiktionary chỉ ghi thông tin giản thể không mô tả etymology chi tiết. Dựa trên cấu trúc: 言/讠 (lời nói — biểu nghĩa) + 乍 (biểu âm). Nghĩa gốc là lừa gạt bằng lời nói — nói điều gian dối. Từ đó mở rộng sang nghĩa lừa đảo, gian trá (诈骗 — lừa đảo). Chưa có nguồn học thuật xác nhận thêm. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lừa dối, giả dối", "Hạng Tần Suất (Jun Da)": "2398.0", "Tần Suất % (Jun Da)": "98.2804992711", "GavinGrover_Once (Chiết tự trực tiếp)": "讠 + 乍", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰讠乍", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "乍", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "讠", "Unihan_Simplified (Chữ Giản thể)": "诈", "Unihan_Traditional (Chữ Phồn thể)": "詐", "Pinyin_Xie": "zhà", "Âm Hán Việt_Xie": "trá", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Thường làm động từ hoặc tính từ để chỉ hành vi gian dối, lừa lọc trong giao tiếp. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('斋', '{"9000": "2399.0", "Chữ Trung Quốc": "斋", "Bộ thủ & thành phần_Xie": "Bộ thủ | 文 | Số nét | 10 | nét | 齐 | tề | biểu âm | chỉnh tề, đều nhau | 示 | thị | biểu nghĩa | thần linh, bàn thờ | 斋 (phồn thể 齋) = 齊 (Tề, biểu âm) + 示 (Thị, biểu nghĩa: thần linh, lễ tế); chữ hình thanh. Bộ 示 xác định liên quan đến tế lễ, 齊 cho âm zhāi gần với trai.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trai\": bàn Thờ (示) và sự Tề chỉnh (齊) — trai giới là giữ thân tâm thanh tịnh trước khi dâng lễ. | Gương Hán-Việt | trai trong \"trai giới\", \"ăn chay\" — thanh tịnh để thờ phụng | Mở khoá kiến thức | Biết 斋 mở khoá: 吃斋 (ăn chay), 书斋 (thư trai — phòng đọc sách), 斋戒 (trai giới).", "Tự nguyên_Xie": "Kim văn | Tiểu triện | Theo Wiktionary, 齋 là chữ hình thanh: 示 (thị) biểu nghĩa chỉ lễ tế thần linh, 齊 biểu âm. Gốc nghĩa là trai giới — thanh tịnh thân tâm trước khi tế lễ (kiêng ăn thịt, tắm rửa, không tạp niệm); từ đó mở rộng thành ăn chay, phòng học yên tĩnh. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ăn chay; nhà học", "Hạng Tần Suất (Jun Da)": "2399.0", "Tần Suất % (Jun Da)": "98.2826666679", "GavinGrover_Once (Chiết tự trực tiếp)": "文 + 而", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱文而", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "而", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "文", "Unihan_Simplified (Chữ Giản thể)": "斋", "Unihan_Traditional (Chữ Phồn thể)": "齋", "Pinyin_Xie": "zhāi", "Âm Hán Việt_Xie": "trai", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường làm danh từ chỉ phòng học hoặc động từ chỉ việc ăn chay, giữ giới. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('瞒', '{"9000": "2400.0", "Chữ Trung Quốc": "瞒", "Bộ thủ & thành phần_Xie": "Bộ thủ | 目 | Số nét | 15 | nét | 目 | mục | biểu nghĩa | mắt | 𬜯 | biểu âm | âm phù (gồm 艹 + 两) | 瞒 = 目 (Mục, biểu nghĩa: mắt) + 𬜯 (biểu âm: gồm 艹 Thảo + 两 Lưỡng); chữ hình thanh. Bộ Mục chỉ đôi mắt (che khuất tầm nhìn người khác), phần còn lại cho âm man/mán.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"man\": che kín trước mắt (目) người — \"man\" là che đậy, giấu giếm, như \"man trá\" hay \"dối man\". | Gương Hán-Việt | \"man\" trong \"man trá\" (giấu giếm gian dối); 隐瞒 (ẩn man = che giấu), 欺瞒 (khi man = lừa dối) | Mở khoá kiến thức | Biết 瞒 (man) mở khoá: 隐瞒 (ẩn man — che giấu), 欺瞒 (khi man — lừa dối).", "Tự nguyên_Xie": "Tiểu triện | 瞒 là dạng giản thể của 瞞. Wiktionary chỉ ghi thông tin giản thể không mô tả chi tiết etymology. Dựa trên cấu trúc: 目 (mắt — biểu nghĩa) + 𬜯/䓣 (biểu âm). Nghĩa gốc là mắt nhìn nửa chừng (eyes half-closed), từ đó mở rộng sang nghĩa lừa dối, che giấu — làm cho người khác không nhìn thấy thực chất. Chưa có nguồn học thuật xác nhận thêm. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "dối, lừa", "Hạng Tần Suất (Jun Da)": "2400.0", "Tần Suất % (Jun Da)": "98.2848325144", "GavinGrover_Once (Chiết tự trực tiếp)": "目 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰目", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "瞒", "Unihan_Traditional (Chữ Phồn thể)": "瞞", "Pinyin_Xie": "mán", "Âm Hán Việt_Xie": "man", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước tân ngữ chỉ người hoặc sự việc bị che giấu. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | mán | / | giấu | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Bí mật", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('彪', '{"9000": "2401.0", "Chữ Trung Quốc": "彪", "Bộ thủ & thành phần_Xie": "Bộ thủ | 彡 | Số nét | 11 | nét | 虎 | hổ | biểu nghĩa | con hổ | 彡 | sam | biểu nghĩa | lông thú, vằn | 彪 = 虎 (Hổ, biểu nghĩa: con hổ) + 彡 (Sam, biểu nghĩa: lông vằn); chữ hội ý. Hai bộ phận kết hợp ý nghĩa: vằn (彡) trên mình hổ (虎) — chỉ những vằn sọc đặc trưng của hổ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bưu\": con Hổ (虎) với những Vằn (彡) óng ánh — chữ Bưu vẽ đúng hình ảnh hổ vằn oai phong. | Gương Hán-Việt | bưu trong \"bưu điện\" (chữ khác), nhưng 彪 thường trong tên người — mạnh mẽ như hổ | Mở khoá kiến thức | Biết 彪 mở khoá: 彪悍 (dũng mãnh), 彪形大汉 (người đàn ông to cao vạm vỡ), 彪炳 (rực rỡ).", "Tự nguyên_Xie": "Tiểu triện | Wiktionary không cung cấp nguồn glyphOrigin chi tiết cho 彪 ngoài dữ liệu phát âm. Dựa trên cấu trúc 虎 + 彡: đây là chữ hội ý, 虎 chỉ con hổ, 彡 chỉ lông vằn/màu sắc sặc sỡ. Nghĩa gốc là vằn hổ; mở rộng thành hổ con, rồi chỉ người vạm vỡ to lớn. Chưa có nguồn học thuật xác nhận độc lập. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "vằn con hổ; con hổ con", "Hạng Tần Suất (Jun Da)": "2401.0", "Tần Suất % (Jun Da)": "98.286995777", "GavinGrover_Once (Chiết tự trực tiếp)": "虎 + 彡", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴虎彡", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "虎", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "彡", "Unihan_Simplified (Chữ Giản thể)": "彪", "Unihan_Traditional (Chữ Phồn thể)": "彪", "Pinyin_Xie": "biāo", "Âm Hán Việt_Xie": "bưu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Thường dùng làm danh từ chỉ loài hổ hoặc tính từ mô tả vóc dáng vạm vỡ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('厄', '{"9000": "2402.0", "Chữ Trung Quốc": "厄", "Bộ thủ & thành phần_Xie": "Bộ thủ | 厂 | Số nét | 4 | nét | 厂 | hán | biểu âm | vách đá, mái che | 㔾 | biểu nghĩa | người quỳ gối (biến thể 卩) | 厄 = 厂 (Hán, biểu âm) + 㔾/卩 (người quỳ, biểu nghĩa); chữ hình thanh theo Thuyết Văn. Hình người quỳ gối dưới vách đá — gợi cảnh khốn cùng bí lối.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ách\": người quỳ dưới vách đá chật hẹp — hình ảnh của Ách nạn, bế tắc không lối thoát. | Gương Hán-Việt | ách trong \"ách tắc\", \"tai ách\" — khốn cùng, bế tắc | Mở khoá kiến thức | Biết 厄 mở khoá: 厄运 (vận xui), 厄境 (hoàn cảnh khó khăn), 困厄 (khốn khó).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 厄 có thể là chữ chỉ người quỳ gối (卩) với nét nhấn vào đầu gối (厂). Thuyết Văn Giải Tự giải là hình thanh: 厂 biểu âm, 卪 biểu nghĩa (mấu nối). Nghĩa gốc là cây gỗ có mấu; về sau mang nghĩa khốn cùng, ách nạn — có thể do đồng nghĩa với 戹 (ách). | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "khốn ách; hẹp", "Hạng Tần Suất (Jun Da)": "2402.0", "Tần Suất % (Jun Da)": "98.289158006", "GavinGrover_Once (Chiết tự trực tiếp)": "厂 + 㔾", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴厂㔾", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "㔾", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "厂", "Unihan_Simplified (Chữ Giản thể)": "厄", "Unihan_Traditional (Chữ Phồn thể)": "厄", "Pinyin_Xie": "è", "Âm Hán Việt_Xie": "ách", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Thường làm danh từ chỉ tai họa hoặc tính từ chỉ sự khốn đốn, chật hẹp. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('咨', '{"9000": "2403.0", "Chữ Trung Quốc": "咨", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 9 | nét | 次 | thứ | biểu âm | thứ tự, lần | 口 | khẩu | biểu nghĩa | miệng, lời nói | 咨 = 次 (Thứ, biểu âm) + 口 (Khẩu, biểu nghĩa: miệng/lời nói); chữ hình thanh. Bộ 口 cho nghĩa liên quan đến lời nói/hỏi han, 次 cho âm (zī ~ thứ).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tư\": miệng 口 (khẩu) hỏi từng thứ 次 (thứ) — 咨 là tư vấn, hỏi ý kiến chuyên gia từng bước. | Gương Hán-Việt | tư trong ''tư vấn'' (咨询), ''tư hỏi'' (thỉnh tư) | Mở khoá kiến thức | Biết 咨 (tư) mở khoá: 咨询 (tư vấn, tham khảo ý kiến), 咨文 (thông điệp/tấu trình chính thức).", "Tự nguyên_Xie": "Giáp cốt văn | Kim văn | Tiểu triện | Theo Wiktionary, 咨 là chữ hình thanh (psc): 次 (thứ, biểu âm) + 口 (khẩu, biểu nghĩa: miệng). Nghĩa gốc là hỏi ý kiến, thỉnh vấn. Cũng dùng là thán từ trong văn ngôn để biểu lộ tán thưởng. Sau dùng phổ biến trong 咨询 (tư vấn, hỏi ý kiến chuyên gia). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "364.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Khẩu (6) Thứ (30)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Thứ (số 30 - kế tiếp) chỉ âm, chữ Khẩu (số 6) chỉ ý. Dùng miệng bàn bạc, thương lượng. Tư cũng là tên loại công văn (thông tư). Giải thích sự chuyển ý: Chữ Thứ (kế tiếp) chỉ âm, chữ Khẩu (miệng) chỉ ý. Dùng miệng (Khẩu) để hỏi han, bàn bạc lần lượt người này đến người khác (Thứ) gọi là tư vấn (Tư). *(Biến âm Hán Việt: Trong Hán ngữ cổ, chữ Thứ và chữ Tư có cách phát âm tương đồng hoặc chung gốc phụ âm. Quá trình Việt hóa đã làm âm đọc bị chênh lệch thành Thứ và Tư).*", "Nghĩa Tiếng Việt_Xie": "bàn bạc, tư vấn; tường trình", "Hạng Tần Suất (Jun Da)": "2403.0", "Tần Suất % (Jun Da)": "98.2913181679", "GavinGrover_Once (Chiết tự trực tiếp)": "次 + 口", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱次口", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "次", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "咨", "Unihan_Traditional (Chữ Phồn thể)": "咨", "Pinyin_Xie": "zī", "Âm Hán Việt_Xie": "tư", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ kết hợp với các từ khác để chỉ việc trao đổi, tư vấn ý kiến. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('纺', '{"9000": "2404.0", "Chữ Trung Quốc": "纺", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 7 | nét | 纟 | mịch | biểu nghĩa | sợi tơ, vải | 方 | phương | biểu âm | vuông, phương | 纺 = 纟(Mịch, biểu nghĩa: sợi tơ, vải sợi) + 方 (Phương, biểu âm); chữ hình thanh. Bộ Mịch chỉ liên quan đến sợi vải, 方 cho âm phưởng/fǎng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phưởng\": sợi tơ (纟) được xe theo hướng vuông vắn (方 = phương) — \"phưởng\" gợi hình ảnh xa quay tơ đều đặn, ngay ngắn. | Gương Hán-Việt | \"phưởng\" ít dùng độc lập; 纺织 (phưởng chức = dệt vải), 纺纱 (phưởng sa = xe sợi) | Mở khoá kiến thức | Biết 纺 (phưởng) mở khoá: 纺织 (phưởng chức — dệt vải), 纺纱 (phưởng sa — xe sợi), 纺织品 (phưởng chức phẩm — hàng dệt may).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 纺 là dạng giản thể của 紡. Wiktionary chỉ ghi thông tin giản thể không mô tả chi tiết etymology. Dựa trên cấu trúc: 糸/纟 (sợi tơ — biểu nghĩa) + 方 (biểu âm). Nghĩa gốc là xe sợi, quay tơ — hành động kéo sợi thành chỉ. Từ đó mở rộng sang nghĩa dệt (纺织 — dệt vải). Chưa có nguồn học thuật xác nhận thêm. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "xe thành sợi", "Hạng Tần Suất (Jun Da)": "2404.0", "Tần Suất % (Jun Da)": "98.2934757458", "GavinGrover_Once (Chiết tự trực tiếp)": "纟 + 方", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰纟方", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "方", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "纟", "Unihan_Simplified (Chữ Giản thể)": "纺", "Unihan_Traditional (Chữ Phồn thể)": "紡", "Pinyin_Xie": "fǎng", "Âm Hán Việt_Xie": "phưởng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường làm động từ chỉ hành động kéo sợi hoặc kết hợp tạo danh từ chỉ ngành dệt. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('罐', '{"9000": "2405.0", "Chữ Trung Quốc": "罐", "Bộ thủ & thành phần_Xie": "Bộ thủ | 缶 | Số nét | 23 | nét | 缶 | phữu | biểu nghĩa | bình gốm, đồ đựng bằng đất nung | 雚 | biểu âm | âm phù (gồm 艹 + chim) | 罐 = 缶 (Phữu, biểu nghĩa: bình gốm, đồ đựng) + 雚 (biểu âm: gồm 艹 Thảo + chim 𨾴); chữ hình thanh. Bộ Phữu chỉ đây là đồ đựng bằng gốm, 雚 cho âm quán/guàn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quán\": bình gốm (缶) với tiếng chim trên nắp (雚) — \"quán\" gợi cái lọ, cái hộp, như \"hộp quán\" hay \"quán café\" (từ quá hóa). | Gương Hán-Việt | \"quán\" ít dùng độc lập theo nghĩa lọ; 罐头 (quán đầu = đồ hộp), 茶罐 (trà quán = lọ đựng trà) | Mở khoá kiến thức | Biết 罐 (quán) mở khoá: 罐头 (quán đầu — đồ hộp), 易拉罐 (dị lạp quán — lon kéo mở), 水罐 (thuỷ quán — bình nước).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 罐 ghép 缶 (bình gốm — biểu nghĩa) với 雚 (biểu âm) theo kiểu hình thanh. Nghĩa gốc là cái lọ, cái bình gốm. Từ đó mở rộng sang các loại đồ đựng hình trụ: hộp thiếc (罐头 — đồ hộp), bình, chai. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái lọ nhỏ, cái gáo múc nước", "Hạng Tần Suất (Jun Da)": "2405.0", "Tần Suất % (Jun Da)": "98.295630223", "GavinGrover_Once (Chiết tự trực tiếp)": "缶 + 雚", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰缶雚", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "雚", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "缶", "Unihan_Simplified (Chữ Giản thể)": "罐", "Unihan_Traditional (Chữ Phồn thể)": "罐", "Pinyin_Xie": "guàn", "Âm Hán Việt_Xie": "quán", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Lượng từ | 量词 | Thường làm danh từ chỉ đồ chứa hoặc lượng từ cho các vật đựng trong hũ, lon. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Lượng từ | 量词 | Đứng giữa số từ (hoặc 这/那) và danh từ: 一杯茶, 这本书. Mỗi danh từ đi với lượng từ riêng; 个 là lượng từ dùng chung phổ biến nhất.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | guàn | / | lọ | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Ngôi nhà và cuộc sống hàng ngày I | HSK | HSK 6 | · | Căn nhà", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('桶', '{"9000": "2406.0", "Chữ Trung Quốc": "桶", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 11 | nét | 木 | mộc | biểu nghĩa | gỗ | 甬 | dũng | biểu âm | gợi âm tǒng | 桶 = 木 (Mộc, biểu nghĩa: gỗ) + 甬 (Dũng, biểu âm); chữ hình thanh (ls=psc). Đồ đựng bằng gỗ hình tròn — ''cái thùng''.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thũng\" (theo nghĩa Nôm ''thùng''): 木 (gỗ) + 甬 (dũng) — thùng gỗ; nhớ 垃圾桶 (thùng rác), 马桶 (bồn cầu). | Gương Hán-Việt | ''thùng'' (đọc Nôm); Hán-Việt cổ là ''thũng'' — dùng cho đồ đựng hình trụ | Mở khoá kiến thức | Biết 桶 là mở 垃圾桶, 马桶, 水桶, 油桶 — nhóm danh từ về đồ đựng HSK 4-6.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 桶 là chữ hình thanh: 木 (biểu nghĩa: gỗ) ghép với 甬 (biểu âm). Nghĩa: cái thùng (hình trụ, vốn làm bằng gỗ). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "533.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Mộc (54) Dũng (532)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Mộc (số 54 - cây gỗ) đứng cạnh chữ Dũng (số 532 - đường ngõ). Giải thích sự chuyển ý: Chữ Dũng (lối đi) chỉ âm, chữ Mộc (cây gỗ) chỉ ý. Đồ vật làm bằng gỗ, có miệng tròn và lòng sâu gọi là cái thùng (Thống). (Biến âm Hán Việt: Dũng -> Thống)", "Nghĩa Tiếng Việt_Xie": "cái thùng", "Hạng Tần Suất (Jun Da)": "2406.0", "Tần Suất % (Jun Da)": "98.2977836667", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 甬", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木甬", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "甬", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "桶", "Unihan_Traditional (Chữ Phồn thể)": "桶", "Pinyin_Xie": "tǒng", "Âm Hán Việt_Xie": "dũng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Lượng từ | 量词 | Thường làm danh từ chỉ vật dụng chứa chất lỏng hoặc lượng từ chỉ đơn vị thùng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Lượng từ | 量词 | Đứng giữa số từ (hoặc 这/那) và danh từ: 一杯茶, 这本书. Mỗi danh từ đi với lượng từ riêng; 个 là lượng từ dùng chung phổ biến nhất.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | tǒng | / | thùng | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Ngôi nhà và cuộc sống hàng ngày II", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('壤', '{"9000": "2407.0", "Chữ Trung Quốc": "壤", "Bộ thủ & thành phần_Xie": "Bộ thủ | 土 | Số nét | 20 | nét | 土 | thổ | biểu nghĩa | đất | 襄 | tương | biểu âm | giúp đỡ, kéo lên | 壤 = 土 (Thổ, biểu nghĩa: đất) + 襄 (Tương, biểu âm); chữ hình thanh. Bộ Thổ chỉ đất đai, 襄 cho âm nhưỡng/rǎng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nhưỡng\": đất (土) được vun lên giúp (襄 = giúp đỡ, nâng lên) — \"nhưỡng\" là đất tơi màu mỡ, nuôi dưỡng cây trồng. | Gương Hán-Việt | \"nhưỡng\" trong \"thổ nhưỡng\" (土壤 = đất đai); 天壤之别 (thiên nhưỡng chi biệt = cách nhau một trời một vực) | Mở khoá kiến thức | Biết 壤 (nhưỡng) mở khoá: 土壤 (thổ nhưỡng — đất đai, loại đất), 天壤之别 (thiên nhưỡng chi biệt — cách nhau một trời một vực).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Theo Wiktionary, 壤 ghép 土 (đất — biểu nghĩa) với 襄 (biểu âm) theo kiểu hình thanh. Nghĩa gốc là đất tơi xốp, đất màu mỡ. Từ đó mở rộng sang nghĩa đất đai nói chung (土壤 — đất), vùng lãnh thổ, và sự đối lập thiên địa (天壤之别 — cách nhau trời và đất). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đất mềm; Trái Đất", "Hạng Tần Suất (Jun Da)": "2407.0", "Tần Suất % (Jun Da)": "98.2999360768", "GavinGrover_Once (Chiết tự trực tiếp)": "土 + 襄", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰土襄", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "襄", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "土", "Unihan_Simplified (Chữ Giản thể)": "壤", "Unihan_Traditional (Chữ Phồn thể)": "壤", "Pinyin_Xie": "rǎng", "Âm Hán Việt_Xie": "nhưỡng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng sau các tính từ hoặc danh từ khác để chỉ loại đất hoặc khu vực địa lý. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('糕', '{"9000": "2408.0", "Chữ Trung Quốc": "糕", "Bộ thủ & thành phần_Xie": "Bộ thủ | 米 | Số nét | 16 | nét | 米 | mễ | biểu nghĩa | gạo | 羔 | cao | biểu âm | dê con | 糕 = 米 (Mễ, biểu nghĩa: gạo) + 羔 (Cao, biểu âm); chữ hình thanh — bánh làm từ bột gạo, đó là bánh ngọt.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cao\": gạo 米 thành bánh có vị ngon như thịt dê con 羔 — đó là bánh, là cao; bánh kem, bánh năm đều là ''cao''. | Gương Hán-Việt | Âm ''cao'' xuất hiện trong ''bánh cao'', ''cao điểm'' (đồng âm khác chữ), riêng 糕 chuyên chỉ bánh. | Mở khoá kiến thức | Biết 糕 mở khoá từ vựng bánh trái tiếng Trung: 蛋糕 (bánh kem), 年糕 (bánh năm), 米糕 (bánh gạo), 糕点 (điểm tâm).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 糕 là chữ hình thanh: bộ 米 (gạo) cho nghĩa liên quan đến sản phẩm từ ngũ cốc, 羔 cho âm. Nghĩa gốc ''bánh làm từ bột gạo, bột mì'', mở rộng thành ''bánh ngọt'' nói chung (蛋糕 bánh kem, 年糕 bánh tét/bánh năm, 米糕 bánh gạo). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bánh bột lọc", "Hạng Tần Suất (Jun Da)": "2408.0", "Tần Suất % (Jun Da)": "98.3020766008", "GavinGrover_Once (Chiết tự trực tiếp)": "米 + 羔", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰米羔", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "羔", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "米", "Unihan_Simplified (Chữ Giản thể)": "糕", "Unihan_Traditional (Chữ Phồn thể)": "糕", "Pinyin_Xie": "gāo", "Âm Hán Việt_Xie": "cao", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm hậu tố trong các danh từ chỉ các loại bánh ngọt như蛋糕 hay 切糕. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('颂', '{"9000": "2409.0", "Chữ Trung Quốc": "颂", "Bộ thủ & thành phần_Xie": "Bộ thủ | 頁 | Số nét | 10 | nét | 公 | công | biểu âm | công khai, chung | 页 | hiệt | biểu nghĩa | đầu, trang sách, bài ca | 颂 = 公 (Công, biểu âm) + 页 (Hiệt, biểu nghĩa: đầu, trang, bài); chữ hình thanh. Bộ Hiệt gợi ý bài ca hay lời tụng, 公 cho âm tụng/sòng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tụng\": bài ca (页) được ngâm to trước công chúng (公 = công khai) — \"tụng\" trong \"ca tụng\", \"tán tụng\" là lời ngợi ca vang vọng. | Gương Hán-Việt | \"tụng\" trong \"ca tụng\" (歌颂 = ca ngợi), \"tán tụng\" (赞颂 = khen ngợi); gần với \"tụng\" trong \"tụng kinh\" | Mở khoá kiến thức | Biết 颂 (tụng) mở khoá: 歌颂 (ca tụng — ca ngợi), 赞颂 (tán tụng — tán dương), 颂扬 (tụng dương — khen ngợi).", "Tự nguyên_Xie": "Kim văn | Tiểu triện | Lục thư thông | 颂 là dạng giản thể của 頌. Wiktionary chỉ ghi thông tin giản thể không mô tả etymology chi tiết. Kim văn cho thấy chữ này liên quan đến lời ca ngợi chính thức. Dựa trên cấu trúc: 页/頁 (đầu, bài — biểu nghĩa) + 公 (biểu âm). Nghĩa gốc là bài ca ngợi, lời ca tụng. Chưa có nguồn học thuật xác nhận thêm. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "khen ngợi, ca tụng", "Hạng Tần Suất (Jun Da)": "2409.0", "Tần Suất % (Jun Da)": "98.3042171248", "GavinGrover_Once (Chiết tự trực tiếp)": "公 + 页", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰公页", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "公", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "页", "Unihan_Simplified (Chữ Giản thể)": "颂", "Unihan_Traditional (Chữ Phồn thể)": "頌", "Pinyin_Xie": "sòng", "Âm Hán Việt_Xie": "tụng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường làm động từ trong văn viết để ca ngợi công đức hoặc làm danh từ chỉ thể loại thơ ca tụng. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('膨', '{"9000": "2410.0", "Chữ Trung Quốc": "膨", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 16 | nét | 月 | nguyệt | biểu nghĩa | thịt (bộ nhục) | 彭 | bành | biểu âm | Bành, tiếng trống | 膨 = 月 (Nguyệt/Nhục, biểu nghĩa: thịt, cơ thể) + 彭 (Bành, biểu âm); chữ hình thanh. Bộ Nhục (viết là 月) chỉ thân thể phình ra, 彭 cho âm bành/péng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bành\": thịt (月/肉) phình ra như cái trống (彭 = tiếng trống căng phồng) — \"bành\" trong \"phình bành\" hay \"lạm phát\" (通货膨胀). | Gương Hán-Việt | \"bành\" trong 膨胀 (bành trướng = phình ra), 通货膨胀 (thông hoá bành trướng = lạm phát) | Mở khoá kiến thức | Biết 膨 (bành) mở khoá: 膨胀 (bành trướng — phình to, lạm phát), 通货膨胀 (thông hoá bành trướng — lạm phát tiền tệ).", "Tự nguyên_Xie": "Theo Wiktionary, 膨 ghép 肉 (thịt — biểu nghĩa, viết là 月 trong chữ ghép) với 彭 (biểu âm) theo kiểu hình thanh. Nghĩa gốc là phình ra, to lên — thân thể hay vật gì đó sưng phồng. Từ đó mở rộng sang nghĩa lạm phát (通货膨胀 — lạm phát tiền tệ, đồng tiền phình to mà mất giá). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: bành hanh 膨脝)", "Hạng Tần Suất (Jun Da)": "2410.0", "Tần Suất % (Jun Da)": "98.3063571321", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 彭", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月彭", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "彭", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "膨", "Unihan_Traditional (Chữ Phồn thể)": "膨", "Pinyin_Xie": "péng", "Âm Hán Việt_Xie": "bành", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường kết hợp với các từ khác để chỉ sự giãn nở vật lý hoặc lạm phát kinh tế. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('谐', '{"9000": "2411.0", "Chữ Trung Quốc": "谐", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 11 | nét | 讠 | biểu nghĩa | ngôn (lời nói) | 皆 | giai | biểu âm | đều, tất cả | 谐 = 讠(Ngôn, biểu nghĩa: lời nói) + 皆 (Giai, biểu âm); chữ hình thanh. Bộ Ngôn chỉ lời nói hoà hợp, 皆 cho âm hài/xié.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hài\": lời nói (讠) của tất cả mọi người (皆 = đều) hoà hợp — \"hài\" trong \"hài hoà\", \"hài hước\" là khi mọi lời nói khớp nhịp với nhau. | Gương Hán-Việt | \"hài\" trong \"hài hoà\" (和谐 = hoà hợp), \"hài hước\" (幽默); 谐音 (hài âm = đồng âm, chơi chữ) | Mở khoá kiến thức | Biết 谐 (hài) mở khoá: 和谐 (hoà hài — hài hoà), 谐音 (hài âm — đồng âm, chơi chữ), 亦庄亦谐 (vừa nghiêm vừa hài hước).", "Tự nguyên_Xie": "Kim văn | Tiểu triện | Lục thư thông | 谐 là dạng giản thể của 諧. Wiktionary chỉ ghi thông tin giản thể không mô tả chi tiết etymology. Kim văn và tiểu triện cho thấy chữ này liên quan đến sự đồng thuận, hoà hợp. Dựa trên cấu trúc: 言/讠 (lời nói — biểu nghĩa) + 皆 (tất cả đều, biểu âm giai/xié). Nghĩa gốc là hoà hợp, nhất trí. Từ đó mở rộng sang nghĩa hài hoà, vui vẻ, hài hước. Chưa có nguồn học thuật xác nhận thêm. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "hoà hợp, hài hoà", "Hạng Tần Suất (Jun Da)": "2411.0", "Tần Suất % (Jun Da)": "98.3084940386", "GavinGrover_Once (Chiết tự trực tiếp)": "讠 + 皆", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰讠皆", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "皆", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "讠", "Unihan_Simplified (Chữ Giản thể)": "谐", "Unihan_Traditional (Chữ Phồn thể)": "諧", "Pinyin_Xie": "xié", "Âm Hán Việt_Xie": "hài", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường kết hợp để tạo tính từ chỉ sự hài hòa như 和谐 hoặc tính khôi hài như 谐谑. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('垒', '{"9000": "2412.0", "Chữ Trung Quốc": "垒", "Bộ thủ & thành phần_Xie": "Bộ thủ | 土 | Số nét | 9 | nét | 厽 | biểu nghĩa | ba cục đất chồng lên (ba 厶) | 土 | thổ | biểu nghĩa | đất | 垒 = 厽 (ba cục đất chồng) + 土 (Thổ); chữ hội ý. Ba khối 厶 chồng lên trên bộ 土 gợi hình ảnh đất đắp cao thành tường đất — luỹ phòng thủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"luỹ\": từng khối Đất (土) chồng cao thêm mãi — hình ảnh đắp Luỹ đất phòng thủ quân sự. | Gương Hán-Việt | luỹ trong \"luỹ thành\", \"luỹ tre\" — thành đất hoặc hàng rào bảo vệ | Mở khoá kiến thức | Biết 垒 mở khoá: 堡垒 (pháo đài), 壁垒 (rào cản), 垒球 (bóng chày).", "Tự nguyên_Xie": "Wiktionary chỉ ghi 垒 là dạng giản thể của 壘, không cung cấp glyphOrigin chi tiết. Dựa trên cấu trúc: đất (土) được chồng chất nhiều lớp (厽 = ba cục đất) tạo thành luỹ đất phòng thủ. Chưa có nguồn học thuật xác nhận độc lập — chỉ dựa trên phân tích cấu trúc. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thành đất cao; xây cất", "Hạng Tần Suất (Jun Da)": "2412.0", "Tần Suất % (Jun Da)": "98.3106304284", "GavinGrover_Once (Chiết tự trực tiếp)": "厽 + 土", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱厽土", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "厽", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "土", "Unihan_Simplified (Chữ Giản thể)": "垒", "Unihan_Traditional (Chữ Phồn thể)": "壘", "Pinyin_Xie": "lěi", "Âm Hán Việt_Xie": "luỹ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Dùng làm danh từ chỉ công trình phòng thủ hoặc động từ chỉ hành động xếp chồng các vật lên nhau. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('咕', '{"9000": "2413.0", "Chữ Trung Quốc": "咕", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 8 | nét | 口 | khẩu | biểu nghĩa | miệng | 古 | cổ | biểu âm | cổ xưa | 咕 = 口 (Khẩu, biểu nghĩa: miệng) + 古 (Cổ, biểu âm); chữ hình thanh. Bộ 口 xác định liên quan đến âm thanh miệng, 古 cho âm gū gần với cô.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cô\": Miệng (口) phát ra âm thanh Cổ (古) — tiếng Cô cô của bồ câu, tiếng lầm bầm trong miệng. | Gương Hán-Việt | cô trong \"cô đơn\" (chữ khác), nhưng 咕 xuất hiện trong từ ghép tượng thanh | Mở khoá kiến thức | Biết 咕 mở khoá: 咕噜 (tiếng ầm ầm/lục sục), 嘀咕 (lầm bầm), 咕咚 (tiếng rơi bịch).", "Tự nguyên_Xie": "Theo Wiktionary, 咕 là chữ hậu khởi (後起字 — chữ tạo muộn hơn): 口 biểu nghĩa chỉ miệng/âm thanh, 古 biểu âm. Chữ dùng làm từ tượng thanh biểu thị tiếng ầm ầm, sục sục, tiếng bồ câu kêu; có nghĩa mở rộng là bỏ hẹn/không đến (từ tiếng bồ câu gắn với 放鸽子). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lải nhải", "Hạng Tần Suất (Jun Da)": "2413.0", "Tần Suất % (Jun Da)": "98.3127657845", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 古", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口古", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "古", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "咕", "Unihan_Traditional (Chữ Phồn thể)": "咕", "Pinyin_Xie": "gū", "Âm Hán Việt_Xie": "cô", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Từ tượng thanh | 象声词 | Động từ | 动词 | Thường dùng làm từ tượng thanh mô phỏng tiếng chim, tiếng bụng kêu hoặc kết hợp thành từ láy chỉ sự lầm bầm. | Từ tượng thanh | 象声词 | Mô phỏng âm thanh: 哗哗, 汪汪. Có thể làm định ngữ, trạng ngữ hoặc đứng độc lập. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('隙', '{"9000": "2414.0", "Chữ Trung Quốc": "隙", "Bộ thủ & thành phần_Xie": "Bộ thủ | 阜 | Số nét | 12 | nét | 阝 | phụ | biểu nghĩa | gò đất, tường đất | 𡭴 | biểu âm | âm phù (gồm 小 + 日 + 小) | 隙 = 阝(Phụ, biểu nghĩa: gò đất, tường — gợi ý khe trong tường) + 𡭴 (biểu âm: gồm 小 Tiểu + 日 Nhật + 小 Tiểu); chữ hình thanh. Bộ Phụ chỉ tường đất có khe hở, 𡭴 cho âm khích/xì.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khích\": trong tường gò (阝) có ánh sáng nhỏ (小日小) lọt qua — \"khích\" là khe hở nhỏ, như \"khích lệ\" (kích thích qua khe hở), hay \"mâu khích\" (mâu thuẫn). | Gương Hán-Việt | \"khích\" trong \"không khích\" (khoảng hở), \"mâu khích\" (矛隙 = mâu thuẫn bất hoà); 空隙 (không khích = khoảng trống) | Mở khoá kiến thức | Biết 隙 (khích) mở khoá: 空隙 (không khích — khoảng trống), 间隙 (gián khích — khoảng cách), 嫌隙 (hiềm khích — mối bất hoà).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 隙 ghép 阜 (⻖ — gò, tường — biểu nghĩa) với 𡭴 (biểu âm) theo kiểu hình thanh. Chữ diễn đạt ý tưởng về lỗ hổng hay khe hở trong tường. Nghĩa gốc là khe hở, rãnh nhỏ. Từ đó mở rộng sang nghĩa khoảng trống (空隙), mối bất hoà (嫌隙 — sự bất đồng), và cơ hội (乘隙 — nhân cơ hội). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "khe hở, khoảng", "Hạng Tần Suất (Jun Da)": "2414.0", "Tần Suất % (Jun Da)": "98.3149001071", "GavinGrover_Once (Chiết tự trực tiếp)": "阝 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰阝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "隙", "Unihan_Traditional (Chữ Phồn thể)": "隙", "Pinyin_Xie": "xì", "Âm Hán Việt_Xie": "khích", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ khoảng trống vật lý, thời gian rảnh rỗi hoặc sự bất hòa trong tình cảm. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('辣', '{"9000": "2415.0", "Chữ Trung Quốc": "辣", "Bộ thủ & thành phần_Xie": "Bộ thủ | 辛 | Số nét | 14 | nét | 辛 | tân | biểu nghĩa | vị cay, đắng | 束 | thúc | biểu âm | biến thể của 剌, gợi âm là | 辣 = 辛 (Tân: cay đắng) + 束 (Thúc, biểu âm — biến thể của 剌); chữ hình thanh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lạt\": chữ 辛 (cay) cộng 束 (bó) — vị cay xé lưỡi, đó là ''lạt'' (cay). | Gương Hán-Việt | lạt trong \"tân lạt\" 辛辣, \"lạt thủ\" 辣手 | Mở khoá kiến thức | Biết 辣 mở khoá nhóm vị cay và ớt: 辣椒, 麻辣, 火辣辣.", "Tự nguyên_Xie": "Lục thư thông | Wiktionary chú 辣 = 辛 + 剌 (ls=psc, c1=s c2=p, alt2=束, abb2=y) — 辛 cho nghĩa ''vị cay đắng nồng'', 剌/束 cho âm. Nghĩa gốc ''vị cay nồng xé lưỡi'', mở rộng thành ''cay (vị/tính)'', cũng dùng cho ''độc ác, hiểm''. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cay xé; nham hiểm, độc ác", "Hạng Tần Suất (Jun Da)": "2415.0", "Tần Suất % (Jun Da)": "98.317031329", "GavinGrover_Once (Chiết tự trực tiếp)": "辛 + 束", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰辛束", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "束", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "辛", "Unihan_Simplified (Chữ Giản thể)": "辣", "Unihan_Traditional (Chữ Phồn thể)": "辢", "Pinyin_Xie": "là", "Âm Hán Việt_Xie": "lạt", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Dùng làm tính từ miêu tả vị cay của thức ăn hoặc tính cách, hành động tàn nhẫn, cay độc. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | là | / | cay | Xuất hiện trong lộ trình | New HSK | New HSK 4 | · | Thức ăn và đồ uống | YCT | YCT 4 | · | Đồ ăn và đồ uống | HSK | HSK 4 | · | Thức ăn và đồ uống", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('绑', '{"9000": "2416.0", "Chữ Trung Quốc": "绑", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 9 | nét | 纟 | mịch | biểu nghĩa | sợi tơ, dây | 邦 | bang | biểu âm | nước, quốc gia | 绑 = 纟 (Mịch, biểu nghĩa: sợi tơ/dây) + 邦 (Bang, biểu âm); chữ hình thanh. Bộ 纟 chỉ ý nghĩa liên quan đến dây sợi, 邦 cho âm đọc gần với bǎng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bảng\": tưởng tượng dùng dây tơ (纟) như dây thừng của một nước (邦) để trói chặt kẻ thù — 绑架 (bắt cóc) là trói rồi mang đi. | Gương Hán-Việt | Bảng xuất hiện trong 捆绑 (côn bảng – trói buộc), 绑架 (bảng giá – bắt cóc). | Mở khoá kiến thức | Biết 绑 mở khoá các từ: 绑架 (bắt cóc), 捆绑 (trói buộc), 松绑 (nới lỏng dây).", "Tự nguyên_Xie": "Chữ 绑 (phồn thể 綁) là chữ hình thanh: bộ 糸 (mịch – sợi tơ) biểu nghĩa hành động dùng dây buộc, bộ 邦 (bang) biểu âm. Hán-Việt đọc là Bảng. Nghĩa gốc là trói, buộc chặt bằng dây. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "trói, buộc; dây trói", "Hạng Tần Suất (Jun Da)": "2416.0", "Tần Suất % (Jun Da)": "98.3191563495", "GavinGrover_Once (Chiết tự trực tiếp)": "纟 + 邦", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰纟邦", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "邦", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "纟", "Unihan_Simplified (Chữ Giản thể)": "绑", "Unihan_Traditional (Chữ Phồn thể)": "綁", "Pinyin_Xie": "bǎng", "Âm Hán Việt_Xie": "bảng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước tân ngữ chỉ người hoặc vật bị trói, hoặc kết hợp thành từ ghép. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | bǎng | / | buộc | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Động từ tôi", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('宠', '{"9000": "2417.0", "Chữ Trung Quốc": "宠", "Bộ thủ & thành phần_Xie": "Bộ thủ | 宀 | Số nét | 8 | nét | 宀 | miên | biểu nghĩa | mái nhà, nơi che chở | 龙 | long | biểu âm | rồng | 宠 = 宀 (Miên, biểu nghĩa: mái nhà/nơi bảo vệ) + 龙 (Long, biểu âm); chữ hình thanh. Bộ 宀 cho nghĩa sự chở che nuông chiều trong gia đình, 龙 cho âm (chǒng ~ long).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sủng\": dưới mái nhà 宀 (miên) nuôi rồng 龙 (long) — 宠 là sủng ái, nuông chiều như nuôi rồng trong nhà. | Gương Hán-Việt | sủng trong ''sủng ái'' (được cưng yêu đặc biệt), ''sủng vật'' (thú cưng) | Mở khoá kiến thức | Biết 宠 (sủng) mở khoá: 宠物 (thú cưng), 宠爱 (sủng ái, yêu chiều), 受宠 (được cưng).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 宠 là chữ giản thể của 寵. Phồn thể 寵 là chữ hình thanh: 宀 (miên, biểu nghĩa: mái nhà) + 龍 (long, biểu âm). Nghĩa là nuông chiều, cưng nựng — được che chở và yêu thương đặc biệt dưới mái nhà. Sau dùng cho 宠物 (thú cưng). | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chiều chuộng", "Hạng Tần Suất (Jun Da)": "2417.0", "Tần Suất % (Jun Da)": "98.3212793028", "GavinGrover_Once (Chiết tự trực tiếp)": "宀 + 龙", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱宀龙", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "龙", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "宀", "Unihan_Simplified (Chữ Giản thể)": "宠", "Unihan_Traditional (Chữ Phồn thể)": "寵", "Pinyin_Xie": "chǒng", "Âm Hán Việt_Xie": "sủng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường làm động từ chỉ sự yêu chiều của bề trên với bề dưới hoặc làm yếu tố cấu tạo danh từ chỉ thú cưng. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | chǒng | / | nuông chiều | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Thái độ với người khác II", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('嘿', '{"9000": "2418.0", "Chữ Trung Quốc": "嘿", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 15 | nét | 口 | khẩu | biểu nghĩa | miệng, âm thanh | 黑 | hắc | biểu âm | màu đen | 嘿 = 口 (Khẩu, biểu nghĩa: miệng/âm thanh) + 黑 (Hắc, biểu âm); có thể là chữ hình thanh. Wiktionary ghi nhận chưa rõ nguồn gốc (rfe). 口 chỉ đây là âm thanh phát ra bằng miệng, 黑 cho âm gần với hēi.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hắc\": miệng (口) kêu lên \"hắc\" như màu đen (黑) bất ngờ xuất hiện — 嘿 là tiếng kêu ngạc nhiên \"ê!\", \"này!\". | Gương Hán-Việt | Hắc xuất hiện trong tên riêng và thán từ; trong tiếng Việt 嘿 thường phiên âm là \"hây\" hoặc \"này\". | Mở khoá kiến thức | Biết 嘿 giúp nhận ra thán từ thông dụng trong hội thoại tiếng Trung hiện đại.", "Tự nguyên_Xie": "Chữ 嘿 chưa có nguồn khảo cứu rõ ràng từ Wiktionary. Theo cấu trúc, đây có thể là chữ hình thanh: bộ 口 (khẩu) chỉ âm thanh phát ra miệng, bộ 黑 (hắc) biểu âm. Dùng làm thán từ biểu thị sự ngạc nhiên hoặc gọi chú ý, tương đương \"này!\", \"ê!\". Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ấy, này, ô, ơ, ô hay, ô kìa, ơ kia, ơ này, ủa (thán từ)", "Hạng Tần Suất (Jun Da)": "2418.0", "Tần Suất % (Jun Da)": "98.3233991555", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 黑", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口黑", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "黑", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "嘿", "Unihan_Traditional (Chữ Phồn thể)": "嘿", "Pinyin_Xie": "hēi", "Âm Hán Việt_Xie": "hắc, mặc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Thán từ | 叹词 | Tính từ | 形容词 | Thường đứng đầu câu làm thán từ để gây sự chú ý, chào hỏi hoặc biểu thị sự ngạc nhiên. | Thán từ | 叹词 | Bộc lộ cảm xúc hoặc dùng để gọi đáp: 啊, 哦, 喂. Đứng tách riêng ở đầu câu, không làm thành phần câu. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | Từ đơn | Thán từ dùng để gọi ai đó hoặc gây chú ý, tương đương ''này'' trong tiếng Việt. | / | hēi | / | này | Xuất hiện trong lộ trình | YCT | YCT 4 | · | Các từ chức năng và câu hỏi | YCT 3 | · | Các từ chức năng và câu hỏi | HSK | HSK 6 | · | Các từ chức năng và bổ trợ | New HSK | New HSK 7-9 | · | Từ chức năng và phụ từ I", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('兑', '{"9000": "2419.0", "Chữ Trung Quốc": "兑", "Bộ thủ & thành phần_Xie": "Bộ thủ | 儿 | Số nét | 7 | nét | 丷 | biểu hình | phần đầu (gợi miệng hé) | 兄 | huynh | biểu hình | phần dưới | 兑 là dạng biến thể của 兌. Trong cổ văn (oracle/bronze), 兑 vẽ một người đang nói (mở miệng) — gợi nghĩa ''thông qua, đổi''. Cấu trúc hiện đại 丷+兄 không còn rõ ý cổ; xem như chữ độc lập.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đoái\": 兑 vẽ một người há miệng nói/đổi — đúng nghĩa ''đoái, đổi, đổi tiền'' trong 兑换 (đổi tiền), 兑现 (đổi tiền mặt). | Gương Hán-Việt | ''đoái'' trong ''hối đoái'', ''đoái tệ'' (đổi tiền) | Mở khoá kiến thức | Nắm 兑 mở khoá loạt từ HSK 6: 兑换, 兑现.", "Tự nguyên_Xie": "Giáp cốt văn | Kim văn | Bạch thư | Đại triện | Tiểu triện | Theo Wiktionary, 兑 là biến thể của 兌. Trong giáp cốt và kim văn, chữ vẽ một người đang mở miệng nói (兄 + dấu phía trên gợi hơi/giọng) — nghĩa cổ ''thông qua, truyền đạt'', mở rộng sang nghĩa ''đổi, đoái'' (兑换, 兑现). Cũng là quẻ ''Đoài'' (đầm) trong Kinh Dịch — tượng cho con gái út, hướng Tây. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "quẻ Đoài (thượng khuyết) trong Kinh Dịch (chỉ có vạch trên đứt, tượng Trạch (đầm), tượng trưng cho con gái út, hành Kim và Thuỷ, tuổi Dậu, hướng Tây)", "Hạng Tần Suất (Jun Da)": "2419.0", "Tần Suất % (Jun Da)": "98.3255184913", "GavinGrover_Once (Chiết tự trực tiếp)": "丷 + 兄", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱丷兄", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "兄", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "丷", "Unihan_Simplified (Chữ Giản thể)": "兑", "Unihan_Traditional (Chữ Phồn thể)": "兌", "Pinyin_Xie": "duì", "Âm Hán Việt_Xie": "đoái", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường làm động từ chỉ việc quy đổi tiền tệ, nhận thưởng hoặc pha thêm nước vào dung dịch. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('霉', '{"9000": "2420.0", "Chữ Trung Quốc": "霉", "Bộ thủ & thành phần_Xie": "Bộ thủ | 雨 | Số nét | 15 | nét | 雨 | vũ | biểu nghĩa | mưa, độ ẩm | 每 | mỗi | biểu âm | mỗi, từng | 霉 = 雨 (Vũ, biểu nghĩa: mưa/độ ẩm) + 每 (Mỗi, biểu âm); chữ hình thanh. Bộ 雨 cho nghĩa liên quan đến độ ẩm, mưa (điều kiện để nấm mốc phát triển), 每 cho âm (méi ~ mỗi).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mốc\": mưa 雨 (vũ) mỗi 每 (mỗi) ngày — ẩm ướt mãi sẽ mọc 霉 nấm mốc. | Gương Hán-Việt | mốc trong ''发霉 phát mốc'' (bị mốc), ''倒霉 đảo mốc'' (xui xẻo) | Mở khoá kiến thức | Biết 霉 (mốc) mở khoá: 发霉 (bị mốc), 倒霉 (xui xẻo, vận rủi), 霉菌 (nấm mốc vi sinh).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Theo Wiktionary, 霉 là chữ hình thanh (psc): 雨 (vũ, biểu nghĩa: mưa/độ ẩm) + 每 (mỗi, biểu âm). Nghĩa là nấm mốc — phát triển trong môi trường ẩm ướt như sau mưa. Từ 倒霉 (xui xẻo) xuất phát từ hình ảnh thứ bị mốc/hỏng. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mốc, meo, nấm", "Hạng Tần Suất (Jun Da)": "2420.0", "Tần Suất % (Jun Da)": "98.3276362768", "GavinGrover_Once (Chiết tự trực tiếp)": "雨 + 每", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱雨每", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "每", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "雨", "Unihan_Simplified (Chữ Giản thể)": "霉", "Unihan_Traditional (Chữ Phồn thể)": "霉", "Pinyin_Xie": "méi", "Âm Hán Việt_Xie": "môi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Động từ | 动词 | Chữ này thường làm danh từ chỉ nấm mốc hoặc tính từ chỉ sự xui xẻo trong khẩu ngữ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('挫', '{"9000": "2421.0", "Chữ Trung Quốc": "挫", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 10 | nét | 扌 | thủ | biểu nghĩa | tay | 坐 | toạ | biểu âm | ngồi | 挫 = 扌 (Thủ, biểu nghĩa: tay) + 坐 (Toạ, biểu âm); chữ hình thanh. Bộ 扌 chỉ hành động của tay — đây là đè xuống, bẻ gãy — còn 坐 (toạ) cho âm gần với cuò.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"toả\": bàn tay (扌) ngồi chặn (坐) lại — hình ảnh bị chặn đứng, vấp ngã; 挫折 là đòn vấp ngã trên đường đời. | Gương Hán-Việt | Toả xuất hiện trong 挫折 (toả chiết – thất bại, vấp ngã), 受挫 (thụ toả – bị thất bại). | Mở khoá kiến thức | Biết 挫 mở khoá: 挫折 (thất bại), 抑扬顿挫 (lên bổng xuống trầm), 受挫 (bị vấp ngã).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Chữ 挫 là chữ hình thanh: bộ 手 (thủ – tay, viết tắt thành 扌) biểu nghĩa hành động dùng tay đè, bẻ, còn 坐 (toạ) biểu âm. Nghĩa gốc là bẻ gãy, đè xuống; mở rộng ra có nghĩa là thất bại, vấp ngã (挫折). Tiểu triện của chữ còn được lưu trong nguồn hanziyuan. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bẻ gãy", "Hạng Tần Suất (Jun Da)": "2421.0", "Tần Suất % (Jun Da)": "98.3297494112", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 坐", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌坐", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "坐", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "挫", "Unihan_Traditional (Chữ Phồn thể)": "挫", "Pinyin_Xie": "cuò", "Âm Hán Việt_Xie": "toả", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường làm động từ mang tân ngữ để chỉ việc làm giảm nhuệ khí hoặc gây trở ngại. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('稽', '{"9000": "2422.0", "Chữ Trung Quốc": "稽", "Bộ thủ & thành phần_Xie": "Bộ thủ | 禾 | Số nét | 15 | nét | 禾 | hoà | biểu nghĩa | cây lúa, cây cong xuống | 尤 | vưu | biểu nghĩa | đặc biệt, nổi trội | 旨 | chỉ | biểu âm | ý chỉ, ngon | 稽 là chữ hình thanh phức hợp: dạng hiện đại gồm 𥝌 (cây cong, biểu nghĩa) + 尤 (biểu nghĩa) + 旨 (Chỉ, biểu âm); dạng gốc là 旨 + 頁 (đầu người) — hình thanh. Nguyên nghĩa gắn với việc cúi đầu suy xét.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"kê\": cúi Đầu (頁→𥝌) tra Chỉ (旨) — kê cứu là cúi đầu tìm kiếm tra xét từng điểm một. | Gương Hán-Việt | kê trong \"kê khai\", \"kê cứu\" — tra xét, lập danh sách | Mở khoá kiến thức | Biết 稽 mở khoá: 滑稽 (hài hước), 稽查 (kiểm tra), 无稽之谈 (chuyện vô căn cứ).", "Tự nguyên_Xie": "Kim văn | Đại triện | Tiểu triện | Theo Wiktionary, 稽 ban đầu là 𩒨: 旨 (chỉ) biểu âm + 頁 (đầu người) biểu nghĩa — hình ảnh cúi đầu tra xét. Dạng hiện đại thay 頁 bằng 𥝌 (cây cong, cây còi cọc) + 尤, vẫn giữ 旨 làm biểu âm. Nghĩa: xem xét, tra cứu; cũng có nghĩa là chậm trễ. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "xem xét, suy xét; cãi cọ", "Hạng Tần Suất (Jun Da)": "2422.0", "Tần Suất % (Jun Da)": "98.3318604785", "GavinGrover_Once (Chiết tự trực tiếp)": "禾 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰禾", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "稽", "Unihan_Traditional (Chữ Phồn thể)": "稽", "Pinyin_Xie": "jī", "Âm Hán Việt_Xie": "kê", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ trong các từ ghép chỉ việc kiểm tra, tra cứu hoặc làm chậm trễ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('辐', '{"9000": "2423.0", "Chữ Trung Quốc": "辐", "Bộ thủ & thành phần_Xie": "Bộ thủ | 車 | Số nét | 13 | nét | 车 | xa | biểu nghĩa | xe, bánh xe | 畐 | biểu âm | thành phần biểu âm (không có Hán-Việt độc lập) | 辐 = 车 (Xa, biểu nghĩa: xe/bánh xe) + 畐 (biểu âm); chữ hình thanh. Bộ 车 chỉ đây là bộ phận của bánh xe, cụ thể là nan hoa. Không có dữ liệu glyphOrigin từ Wiktionary cho chữ này.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phúc\": các nan hoa (辐) của bánh xe (车) tỏa ra như tia phóng xạ — 辐射 là bức xạ toả ra mọi hướng như nan hoa xe. | Gương Hán-Việt | Phúc xuất hiện trong 辐射 (phúc xạ – phóng xạ, bức xạ). | Mở khoá kiến thức | Biết 辐 mở khoá từ chuyên ngành: 辐射 (bức xạ/phóng xạ) dùng nhiều trong vật lý, y học, môi trường.", "Tự nguyên_Xie": "Đại triện | Chữ 辐 là chữ hình thanh: bộ 车 (xa – xe) biểu nghĩa vật liên quan đến bánh xe; 畐 biểu âm. Nghĩa gốc là nan hoa xe — những thanh gỗ hoặc kim loại nối trục với vành bánh xe. Hiện đại dùng phổ biến trong 辐射 (phóng xạ) — hình ảnh các tia phát ra từ tâm như nan hoa từ trục bánh xe. Dữ liệu Wiktionary chưa có, chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nan hoa xe", "Hạng Tần Suất (Jun Da)": "2423.0", "Tần Suất % (Jun Da)": "98.333971029", "GavinGrover_Once (Chiết tự trực tiếp)": "车 + 畐", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰车畐", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "畐", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "车", "Unihan_Simplified (Chữ Giản thể)": "辐", "Unihan_Traditional (Chữ Phồn thể)": "輻", "Pinyin_Xie": "fú", "Âm Hán Việt_Xie": "bức", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường dùng làm danh từ chỉ nan hoa bánh xe hoặc kết hợp tạo động từ chỉ sự lan tỏa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('乞', '{"9000": "2424.0", "Chữ Trung Quốc": "乞", "Bộ thủ & thành phần_Xie": "Bộ thủ | 乙 | Số nét | 3 | nét | 乞 | khất | tượng hình | biến thể của 气 (khí), mượn nghĩa \"xin\" | 乞 là chữ độc thể, biến thể của 气 (khí). Theo Wiktionary, dạng chữ này được phân hóa từ 气 để chỉ nghĩa mượn (giả tá) \"xin, cầu xin\". Thành phần trên (𠂉) không liên quan đến bộ 旅 hay 人. Đây là chữ tượng hình/giả tá, không phải hình thanh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khất\": chữ 乞 trông như người khom lưng chìa tay ra xin — \"khất\" trong \"hành khất\" là đi ăn xin; 乞丐 là người ăn xin. | Gương Hán-Việt | Khất xuất hiện trong \"hành khất\" (乞食 – đi xin ăn), \"khất thực\" (xin cơm). | Mở khoá kiến thức | Biết 乞 mở khoá: 乞丐 (người ăn xin), 乞讨 (đi xin ăn), 乞求 (cầu xin).", "Tự nguyên_Xie": "Chữ 乞 là biến thể phân hóa từ 气 (khí), được tạo ra để chỉ riêng nghĩa \"xin, cầu xin\" vốn là nghĩa mượn của 气. Wiktionary giải thích: khi 气 được dùng với nghĩa \"xin\", người ta tạo ra 乞 riêng để phân biệt. Thành phần trên (𠂉) không liên quan đến bộ 旅 hay 人 dù trông tương tự. Hán-Việt đọc là Khất — cùng gốc với từ \"khất sĩ\" (người hành khất). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "21.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Nhân (42)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Nhân (chữ số 12) + nét cong móc ở dưới. Tượng trưng người đang quỳ gối, nâng tay hướng về người khác để cầu xin.", "Nghĩa Tiếng Việt_Xie": "kẻ ăn mày, người ăn xin", "Hạng Tần Suất (Jun Da)": "2424.0", "Tần Suất % (Jun Da)": "98.3360758948", "GavinGrover_Once (Chiết tự trực tiếp)": "𠂉 + ㇠", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱𠂉㇠", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "㇠", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "𠂉", "Unihan_Simplified (Chữ Giản thể)": "乞", "Unihan_Traditional (Chữ Phồn thể)": "乞", "Pinyin_Xie": "qǐ", "Âm Hán Việt_Xie": "khất", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường làm động từ đứng trước danh từ chỉ thứ mình muốn xin hoặc làm danh từ chỉ người ăn xin. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('纱', '{"9000": "2425.0", "Chữ Trung Quốc": "纱", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 7 | nét | 纟 | mịch | biểu nghĩa | sợi tơ | 少 | thiểu | biểu âm | ít, nhỏ | 纱 = 纟 (Mịch, biểu nghĩa: sợi tơ) + 少 (Thiểu, biểu âm); chữ hình thanh. Bộ 纟 xác định liên quan đến vải sợi, 少 cho âm shā gần với sa.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sa\": sợi Tơ (纟) mà Ít (少) — vải Sa là vải mỏng thưa sợi, nhẹ tựa không khí. | Gương Hán-Việt | sa trong \"the sa\", \"sa tanh\" — vải mỏng, lụa nhẹ | Mở khoá kiến thức | Biết 纱 mở khoá: 婚纱 (váy cưới), 纱布 (gạc y tế), 棉纱 (sợi bông).", "Tự nguyên_Xie": "Wiktionary không có glyphOrigin cho 纱. Dựa trên cấu trúc: 纟 (sợi tơ) biểu nghĩa, 少 biểu âm — chữ chỉ loại vải mỏng dệt từ sợi thưa, ít sợi (少) nên thoáng nhẹ. Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sợi vải; lụa mỏng; the, rèm", "Hạng Tần Suất (Jun Da)": "2425.0", "Tần Suất % (Jun Da)": "98.3381786935", "GavinGrover_Once (Chiết tự trực tiếp)": "纟 + 少", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰纟少", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "少", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "纟", "Unihan_Simplified (Chữ Giản thể)": "纱", "Unihan_Traditional (Chữ Phồn thể)": "紗", "Pinyin_Xie": "shā", "Âm Hán Việt_Xie": "sa", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng độc lập hoặc làm định ngữ bổ nghĩa cho các loại trang phục, màn che. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | shā | / | sợi | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Ngôi nhà và cuộc sống hàng ngày II", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('裙', '{"9000": "2426.0", "Chữ Trung Quốc": "裙", "Bộ thủ & thành phần_Xie": "Bộ thủ | 衣 | Số nét | 12 | nét | 衤 | y | biểu nghĩa | bộ áo – quần áo | 君 | quân | biểu âm | gợi âm qún | 裙 = 衤 (Y, biểu nghĩa: áo) + 君 (Quân, biểu âm); chữ hình thanh, nghĩa là cái váy (loại quần áo che nửa dưới của phụ nữ).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quần\": cái áo 衤 mà bậc quân tử 君 mặc bên dưới – cái váy; nên 裙 nghĩa là váy, xiêm. | Gương Hán-Việt | \"quần\" trong xiêm quần (váy), quần áo, hồng quần (váy hồng – chỉ phụ nữ); khác với 群 (đám đông). | Mở khoá kiến thức | Nhớ 裙 mở khoá: 裙子, 短裙, 长裙, 连衣裙, 围裙.", "Tự nguyên_Xie": "Tiểu triện | 裙 là chữ hình thanh (psc) gồm 衤 (biến thể của 衣 \"quần áo\") làm bộ biểu nghĩa và 君 làm bộ biểu âm. Vì bộ biểu nghĩa là \"y phục\", nghĩa của chữ liên quan đến một loại trang phục cụ thể: cái váy hoặc cái xiêm – phần dưới của bộ y phục, đặc biệt dành cho phụ nữ. Sau này 裙 còn dùng cho các loại váy/xiêm nói chung. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "447.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Y (295) Quân (28)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Y (số 145 - bộ y 衤) và chữ Quân (số 30 - vua / quân tử) . Người đàn ông quân tử (Quân) ngày xưa cũng mặc lớp áo dài bên ngoài như cái váy (Y) gọi là quần (váy). Giải thích sự chuyển ý: Chữ Quân (vua/quân tử) chỉ âm, chữ Y (quần áo) chỉ ý. Trang phục quần áo (Y) may nối liền dạng ống như cái váy (Quần). *(Biến âm Hán Việt: Quân -> Quần)*", "Nghĩa Tiếng Việt_Xie": "cái quần để mặc; cái váy của phụ nữ", "Hạng Tần Suất (Jun Da)": "2426.0", "Tần Suất % (Jun Da)": "98.3402778747", "GavinGrover_Once (Chiết tự trực tiếp)": "衤 + 君", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰衤君", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "君", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "衤", "Unihan_Simplified (Chữ Giản thể)": "裙", "Unihan_Traditional (Chữ Phồn thể)": "帬", "Pinyin_Xie": "qún", "Âm Hán Việt_Xie": "quần", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng sau lượng từ chỉ trang phục để chỉ các loại váy. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('嘻', '{"9000": "2427.0", "Chữ Trung Quốc": "嘻", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 15 | nét | 口 | khẩu | biểu nghĩa | miệng | 喜 | hỷ | biểu âm | vui mừng | 嘻 = 口 (Khẩu, biểu nghĩa: miệng) + 喜 (Hỷ, biểu âm); chữ hình thanh. Bộ 口 xác định là âm thanh miệng, 喜 cho âm xī gần với hi và gợi ý nghĩa vui.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hi\": Miệng (口) cười Hỷ (喜) — tiếng \"hi hi\" khi vui, thán từ Hi biểu lộ ngạc nhiên hay vui thích. | Gương Hán-Việt | hi trong \"hoan hi\" (歡喜, chữ khác), 嘻 dùng trong tượng thanh tiếng cười | Mở khoá kiến thức | Biết 嘻 mở khoá: 嘻嘻哈哈 (cười đùa vui vẻ), 嘻哈 (hip-hop), 笑嘻嘻 (cười tươi).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 嘻 là chữ hình thanh: 口 (khẩu) biểu nghĩa chỉ tiếng miệng, 喜 biểu âm. Dùng làm thán từ biểu thị ngạc nhiên, hoặc từ tượng thanh biểu thị tiếng cười (hì hì, ha ha). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "362.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Khẩu (6) Hỉ (210)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Hỷ (số 210 - vui mừng) chỉ âm, chữ Khẩu (số 6 - cái miệng) chỉ ý. Hy là tiếng than hoặc tiếng cười. Giải thích sự chuyển ý: Chữ Hỷ vốn mang nghĩa vui vẻ. Khi thêm bộ Khẩu vào bên cạnh, nó cụ thể hóa thành âm thanh phát ra khi vui (tiếng cười). Tuy nhiên, trong văn cổ, nó cũng dùng để chỉ tiếng thở dài cảm thán tùy ngữ cảnh. *(Biến âm Hán Việt: Trong Hán ngữ cổ, chữ Hỷ và chữ Hi có cách phát âm tương đồng hoặc chung gốc phụ âm. Quá trình Việt hóa đã làm âm đọc bị chênh lệch thành Hỷ và Hi).*", "Nghĩa Tiếng Việt_Xie": "ôi (biểu thị sự kinh ngạc); hì hì; ha ha (từ tượng thanh, tiếng cười)", "Hạng Tần Suất (Jun Da)": "2427.0", "Tần Suất % (Jun Da)": "98.3423739553", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 喜", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口喜", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "喜", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "嘻", "Unihan_Traditional (Chữ Phồn thể)": "嘻", "Pinyin_Xie": "xī", "Âm Hán Việt_Xie": "hi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Từ tượng thanh | 象声词 | Thán từ | 叹词 | Thường dùng làm từ tượng thanh mô phỏng tiếng cười hoặc thán từ biểu thị sự vui vẻ. | Từ tượng thanh | 象声词 | Mô phỏng âm thanh: 哗哗, 汪汪. Có thể làm định ngữ, trạng ngữ hoặc đứng độc lập. | Thán từ | 叹词 | Bộc lộ cảm xúc hoặc dùng để gọi đáp: 啊, 哦, 喂. Đứng tách riêng ở đầu câu, không làm thành phần câu.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('哇', '{"9000": "2428.0", "Chữ Trung Quốc": "哇", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 9 | nét | 口 | khẩu | biểu nghĩa | miệng, âm thanh | 圭 | khuê | biểu âm | ngọc khuê (lễ khí hình chữ nhật dài) | 哇 = 口 (Khẩu, biểu nghĩa: miệng) + 圭 (Khuê, biểu âm); chữ hình thanh. Wiktionary lưu ý: 圭 ban đầu biểu trưng cho cặp rìu nghi lễ bằng ngọc, không phải đất 土 — nên liên hệ với đất là dân gian tự đặt ra sau này.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"oa\": miệng (口) kêu lên \"oa!\" như ngọc khuê (圭) rơi vỡ gây tiếng vang — 哇 là tiếng kêu ngạc nhiên hoặc tiếng khóc oa oa của trẻ sơ sinh. | Gương Hán-Việt | Oa xuất hiện trong \"哇哇\" (oa oa – tiếng khóc), và trong tên địa lý như 爪哇 (Java). | Mở khoá kiến thức | Biết 哇 giúp nhận ra thán từ phổ biến trong giao tiếp tiếng Trung hiện đại và tên địa danh 爪哇 (đảo Java).", "Tự nguyên_Xie": "Tiểu triện | Chữ 哇 là chữ hình thanh: bộ 口 (khẩu) biểu nghĩa âm thanh phát ra từ miệng, bộ 圭 (khuê) biểu âm. Wiktionary ghi chú thú vị: 圭 ban đầu là hình một cặp rìu nghi lễ bằng ngọc, không liên quan đến đất (土) — sự liên hệ với đất là dân gian tự đặt sau này qua dạng Tiểu triện. Dùng làm thán từ biểu thị ngạc nhiên (wow!) hoặc tiếng trẻ khóc. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tiếng trẻ khóc; thổ ra", "Hạng Tần Suất (Jun Da)": "2428.0", "Tần Suất % (Jun Da)": "98.344469519", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 圭", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口圭", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "圭", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "哇", "Unihan_Traditional (Chữ Phồn thể)": "哇", "Pinyin_Xie": "wa", "Âm Hán Việt_Xie": "oa", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Trợ từ | 助词 | Từ tượng thanh | 象声词 | Thán từ | 叹词 | Thường làm trợ từ ngữ khí ở cuối câu hoặc từ tượng thanh mô phỏng tiếng khóc, tiếng nôn. | Trợ từ | 助词 | Không mang nghĩa riêng, gắn vào câu để đánh dấu ngữ pháp hoặc ngữ khí: 的 / 地 / 得 (kết cấu), 了 / 着 / 过 (thể), 吗 / 呢 / 吧 (nghi vấn, ngữ khí). | Từ tượng thanh | 象声词 | Mô phỏng âm thanh: 哗哗, 汪汪. Có thể làm định ngữ, trạng ngữ hoặc đứng độc lập. | Thán từ | 叹词 | Bộc lộ cảm xúc hoặc dùng để gọi đáp: 啊, 哦, 喂. Đứng tách riêng ở đầu câu, không làm thành phần câu.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | wa | / | wa | Xuất hiện trong lộ trình | HSK | HSK 6 | · | Các từ chức năng và bổ trợ | New HSK | New HSK 6 | · | Từ chức năng I", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('绣', '{"9000": "2429.0", "Chữ Trung Quốc": "绣", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 10 | nét | 纟 | mịch | biểu nghĩa | sợi tơ, vải | 秀 | tú | biểu âm | tú lệ, đẹp | 绣 = 纟 (Mịch, biểu nghĩa: sợi tơ/vải) + 秀 (Tú, biểu âm); chữ hình thanh. Bộ 纟 chỉ chất liệu thêu là vải sợi tơ, 秀 (tú) cho âm xiù và cũng gợi ý nét đẹp.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tú\": những sợi tơ (纟) tú lệ (秀) được thêu thành hoa văn — 绣 là nghệ thuật thêu, tạo nên vẻ đẹp bằng tơ sợi. | Gương Hán-Việt | Tú xuất hiện trong \"thêu tú\" (刺绣 – cắt thêu), 锦绣 (cẩm tú – đẹp đẽ như gấm thêu). | Mở khoá kiến thức | Biết 绣 mở khoá: 刺绣 (thêu), 锦绣前程 (tương lai tươi sáng), 绣花 (thêu hoa).", "Tự nguyên_Xie": "Tiểu triện | Chữ 绣 là dạng giản thể của 繡 (phồn thể). Wiktionary ghi nhận 绣 là giản hóa từ 綉, tra 繡 để biết nguồn gốc đầy đủ. Cấu trúc hình thanh: bộ 纟 (mịch – sợi tơ) biểu nghĩa hành động dùng chỉ tơ để thêu, bộ 秀 (tú) biểu âm. Hán-Việt đọc là Tú — cùng gốc với \"tú\" trong \"thêu tú\". | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thêu thùa", "Hạng Tần Suất (Jun Da)": "2429.0", "Tần Suất % (Jun Da)": "98.3465604316", "GavinGrover_Once (Chiết tự trực tiếp)": "纟 + 秀", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰纟秀", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "秀", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "纟", "Unihan_Simplified (Chữ Giản thể)": "绣", "Unihan_Traditional (Chữ Phồn thể)": "綉", "Pinyin_Xie": "xiù", "Âm Hán Việt_Xie": "tú", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường làm động từ chỉ hoạt động thêu thùa hoặc làm danh từ chỉ đồ thêu. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | xiù | / | thêu | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Giải trí và thói quen II | HSK | HSK 6 | · | Thể thao, giải trí, sở thích", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('杖', '{"9000": "2430.0", "Chữ Trung Quốc": "杖", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 7 | nét | 木 | mộc | biểu nghĩa | gỗ, cây | 丈 | trượng | biểu âm | đơn vị đo chiều dài xưa, trượng | 杖 = 木 (Mộc, biểu nghĩa: gỗ/cây) + 丈 (Trượng, biểu âm); chữ hình thanh. Bộ 木 chỉ gậy được làm bằng gỗ, 丈 (trượng) cho cả âm và có thể gợi ý độ cao của cây gậy.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trượng\": khúc gỗ (木) cao đúng một trượng (丈) — đó là cây gậy 杖; 拐杖 là gậy chống của người già. | Gương Hán-Việt | Trượng xuất hiện trong 拐杖 (quải trượng – gậy chống), \"thiền trượng\" (禅杖 – gậy thiền của nhà sư). | Mở khoá kiến thức | Biết 杖 mở khoá: 拐杖 (gậy chống/nạng), 魔杖 (gậy phép thuật), 杖刑 (hình phạt đánh gậy).", "Tự nguyên_Xie": "Tiểu triện | Chữ 杖 là chữ hình thanh: bộ 木 (mộc – gỗ) biểu nghĩa vật làm bằng gỗ, bộ 丈 (trượng) biểu âm. Nghĩa gốc là cây gậy chống; mở rộng ra cũng chỉ đơn vị dùng để đo. Hán-Việt đọc là Trượng — cùng gốc với \"gậy trượng\". | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "392.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Mộc (108) Trượng (161)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Mộc (số 79 - cây gỗ) và chữ Trượng (số 63 - 10 thước) . Cây gậy làm bằng gỗ dùng để chống đi hoặc đánh người (trượng hình) gọi là trượng. Giải thích sự chuyển ý: Chữ Trượng (đơn vị đo) chỉ âm, chữ Mộc (gỗ) chỉ ý. Một đoạn gỗ (Mộc) dài dùng làm gậy để chống hoặc đánh phạt (Trượng).", "Nghĩa Tiếng Việt_Xie": "cái gậy chống; gậy, que; người chống gậy", "Hạng Tần Suất (Jun Da)": "2430.0", "Tần Suất % (Jun Da)": "98.3486466932", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 丈", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木丈", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "丈", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "杖", "Unihan_Traditional (Chữ Phồn thể)": "杖", "Pinyin_Xie": "zhàng", "Âm Hán Việt_Xie": "trượng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường làm danh từ chỉ cây gậy chống hoặc làm động từ chỉ hành động chống gậy, đánh phạt. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('塘', '{"9000": "2431.0", "Chữ Trung Quốc": "塘", "Bộ thủ & thành phần_Xie": "Bộ thủ | 土 | Số nét | 13 | nét | 土 | thổ | biểu nghĩa | đất, đất đai | 唐 | đường | biểu âm | cho âm đường | 塘 = 土 (Thổ, biểu nghĩa: đất) + 唐 (Đường, biểu âm); chữ hình thanh. Bộ thổ chỉ vật thể làm bằng đất; 唐 cho âm táng/đường.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đường\": bờ đất (土-Thổ) bao quanh ao — hình dung đường bờ đắp đất quanh ao sen làng. | Gương Hán-Việt | đường trong ''ao đường'' — ao hình vuông đắp bờ đất | Mở khoá kiến thức | Biết 塘 mở khoá: 池塘 (chí đường – cái ao), 鱼塘 (ngư đường – ao cá), 荷塘 (hà đường – ao sen).", "Tự nguyên_Xie": "塘 là chữ hình thanh: bộ 土 (thổ) biểu nghĩa ''đất'', 唐 (đường) biểu âm. Từ nguyên chỉ đê đất đắp giữ nước — ao, hồ nhỏ được bao quanh bởi bờ đất. Wiktionary ghi rõ: {{Han compound|土|唐|c1=s|c2=p|t1=dirt|ls=psc}}. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1250.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thổ (032) Đường (1145)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Thổ (số 032 - đất/chỉ ý) ở bên trái chữ Đường (số 1145 - lối đi/chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Đường chỉ âm, bộ Thổ chỉ ý. Đường là con đê ngăn nước đắp bằng đất, bờ đê, hoặc ao hồ ngăn nước đọng lại.", "Nghĩa Tiếng Việt_Xie": "ao hình vuông", "Hạng Tần Suất (Jun Da)": "2431.0", "Tần Suất % (Jun Da)": "98.3507308877", "GavinGrover_Once (Chiết tự trực tiếp)": "土 + 唐", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰土唐", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "唐", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "土", "Unihan_Simplified (Chữ Giản thể)": "塘", "Unihan_Traditional (Chữ Phồn thể)": "塘", "Pinyin_Xie": "táng", "Âm Hán Việt_Xie": "đường", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ ao hồ nhỏ hoặc kết hợp để chỉ các công trình chứa nước, đê điều. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('衍', '{"9000": "2432.0", "Chữ Trung Quốc": "衍", "Bộ thủ & thành phần_Xie": "Bộ thủ | 行 | Số nét | 9 | nét | 彳 | xích | biểu nghĩa | bước đi, đường | 氵 | thuỷ | biểu nghĩa | nước | 亍 | xúc | biểu nghĩa | bước nhỏ | 衍 = 行 (hành – đường đi) + 水 (thuỷ – nước); chữ hội ý. Bộ 行 phân tích thành 彳 và 亍 (hai bên đường), kết hợp với 氵 (nước) tạo hình ảnh nước chảy tràn ra đường đi — đó là nghĩa tràn ra, lan rộng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"diễn\": nước (氵) tràn ra dọc theo đường đi (行) — 衍 là nước chảy tràn; 敷衍 là làm việc cứ cho \"trôi\" qua, không cẩn thận. | Gương Hán-Việt | Diễn xuất hiện trong 衍生 (diễn sinh – phái sinh, phát sinh từ), 敷衍 (phu diễn – làm qua loa). | Mở khoá kiến thức | Biết 衍 mở khoá: 敷衍 (làm qua loa), 衍生 (phái sinh), 繁衍 (sinh sôi nảy nở).", "Tự nguyên_Xie": "Giáp cốt văn | Kim văn | Đại triện | Chữ 衍 là chữ hội ý: bộ 行 (hành – đường, lối đi) kết hợp với 水 (thuỷ – nước). Hình ảnh nước tràn ra đường đi diễn đạt nghĩa gốc: nước chảy tràn, lan ra. Giáp cốt văn, kim văn và đại triện đều ghi lại chữ này, cho thấy từ rất sớm đã được dùng với nghĩa tràn ra, mở rộng. Nghĩa mở rộng: thừa thãi, lan ra (敷衍 – làm qua loa). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nước chảy tràn", "Hạng Tần Suất (Jun Da)": "2432.0", "Tần Suất % (Jun Da)": "98.3528140485", "GavinGrover_Once (Chiết tự trực tiếp)": "行 + 氵", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴行氵", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "氵", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "行", "Unihan_Simplified (Chữ Giản thể)": "衍", "Unihan_Traditional (Chữ Phồn thể)": "衍", "Pinyin_Xie": "yǎn", "Âm Hán Việt_Xie": "diễn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Thường làm động từ trong các từ ghép chỉ sự phát triển, suy rộng hoặc làm tính từ chỉ sự dư thừa. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('轴', '{"9000": "2433.0", "Chữ Trung Quốc": "轴", "Bộ thủ & thành phần_Xie": "Bộ thủ | 車 | Số nét | 9 | nét | 车 | xa | biểu nghĩa | xe | 由 | do | biểu âm | từ, do | 轴 = 车 (Xa, biểu nghĩa: xe) + 由 (Do, biểu âm); chữ hình thanh. Bộ 车 xác định liên quan đến xe cộ, 由 cho âm zhóu gần với trục.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trục\": bộ Xe (车) với thanh Do (由) xuyên qua — cái Trục là thanh xuyên tâm bánh xe, mọi thứ quay quanh nó. | Gương Hán-Việt | trục trong \"trục xuất\", \"trục xe\" — thanh chính, cái lõi | Mở khoá kiến thức | Biết 轴 mở khoá: 车轴 (trục xe), 轴心 (trục tâm), 地轴 (trục trái đất).", "Tự nguyên_Xie": "Tiểu triện | Wiktionary không có glyphOrigin chi tiết cho 轴. Dựa trên cấu trúc: 车 (xa, xe) biểu nghĩa, 由 biểu âm — chữ chỉ trục xe, thanh kim loại hoặc gỗ xuyên qua tâm bánh xe. Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái trục xe", "Hạng Tần Suất (Jun Da)": "2433.0", "Tần Suất % (Jun Da)": "98.3548868737", "GavinGrover_Once (Chiết tự trực tiếp)": "车 + 由", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰车由", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "由", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "车", "Unihan_Simplified (Chữ Giản thể)": "轴", "Unihan_Traditional (Chữ Phồn thể)": "軸", "Pinyin_Xie": "zhóu", "Âm Hán Việt_Xie": "trục", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Lượng từ | 量词 | Thường làm danh từ chỉ bộ phận trung tâm để xoay hoặc làm lượng từ cho các cuộn tranh, cuộn chỉ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Lượng từ | 量词 | Đứng giữa số từ (hoặc 这/那) và danh từ: 一杯茶, 这本书. Mỗi danh từ đi với lượng từ riêng; 个 là lượng từ dùng chung phổ biến nhất.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('攀', '{"9000": "2434.0", "Chữ Trung Quốc": "攀", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 19 | nét | 樊 | phiền | biểu âm | rào giậu, phức tạp | 手 | thủ | biểu nghĩa | tay | 攀 = 樊 (Phiền, biểu âm) + 手 (Thủ, biểu nghĩa: tay); chữ hình thanh. Bộ 手 ở dưới chỉ hành động dùng tay leo trèo, bấu víu; 樊 (phiền) cho âm pān.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phan\": đôi tay (手) bám vào cành cây phức tạp (樊) mà leo lên — 攀登 là leo núi, 攀比 là so sánh ganh đua với người hơn mình. | Gương Hán-Việt | Phan xuất hiện trong 攀登 (phan đăng – leo trèo), 攀比 (phan tỉ – so sánh ganh đua). | Mở khoá kiến thức | Biết 攀 mở khoá: 攀登 (leo núi/tiến lên), 攀比 (ganh đua), 攀附 (bám víu), 高攀 (kết thân người trên).", "Tự nguyên_Xie": "Lục thư thông | Chữ 攀 là chữ hình thanh: bộ 手 (thủ – tay) biểu nghĩa hành động dùng tay leo trèo, bấu víu, còn 樊 (phiền) biểu âm. Nghĩa gốc là leo trèo bằng cách bám vào; mở rộng ra có nghĩa là tìm cách kết thân với người có địa vị cao hơn (攀高枝). Chỉ có ảnh Lục thư thông (chữ tạo muộn). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "leo; trèo; vịn; bám; víu (bám vào vật để leo lên); bấu víu; nhờ vả; kết thân với những người có địa vị cao hơn mình; dính líu; bắt chuyện", "Hạng Tần Suất (Jun Da)": "2434.0", "Tần Suất % (Jun Da)": "98.3569529807", "GavinGrover_Once (Chiết tự trực tiếp)": "棥 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱棥", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "攀", "Unihan_Traditional (Chữ Phồn thể)": "攀", "Pinyin_Xie": "pān", "Âm Hán Việt_Xie": "phàn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước danh từ chỉ vật để bám vào hoặc đối tượng muốn kết giao. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | pān | / | leo | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Phong trào I", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('膊', '{"9000": "2435.0", "Chữ Trung Quốc": "膊", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 14 | nét | 月 | nhục | biểu nghĩa | thịt — bộ phận cơ thể | 尃 | phu | biểu âm | phần biểu âm — gần âm ''bác/phu'' | 膊 là chữ hình thanh (psc): 月 (⺼, thịt — biểu nghĩa: bộ phận cơ thể) + 尃 (biểu âm). Tên một bộ phận trên cơ thể — cánh tay/bắp tay.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Bác\": phần thịt (月) trải rộng (尃) — đó là ''bác'', cánh tay, bắp tay. | Gương Hán-Việt | ''Bác'' (膊) thường đi cùng 胳 thành 胳膊 (cẳng tay). | Mở khoá kiến thức | Biết 膊 mở khoá 胳膊 (cách bác, cẳng tay), 膊子 (bác tử).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 膊 là chữ hình thanh gồm 肉 (月/⺼, thịt — biểu nghĩa: bộ phận cơ thể) + 尃 (biểu âm). Nghĩa gốc ''bắp tay, cánh tay trên''. Thường dùng trong từ ghép 胳膊 (cẳng tay). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cánh tay; bắp tay", "Hạng Tần Suất (Jun Da)": "2435.0", "Tần Suất % (Jun Da)": "98.3590144366", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 尃", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月尃", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "尃", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "膊", "Unihan_Traditional (Chữ Phồn thể)": "膊", "Pinyin_Xie": "bó", "Âm Hán Việt_Xie": "bác", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường kết hợp với các chữ khác để tạo thành danh từ chỉ bộ phận cánh tay của cơ thể. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('譬', '{"9000": "2436.0", "Chữ Trung Quốc": "譬", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 20 | nét | 辟 | tích | biểu âm | mở ra, khai thác; hình phạt | 言 | ngôn | biểu nghĩa | lời nói | 譬 = 辟 (Tích, biểu âm) + 言 (Ngôn, biểu nghĩa: lời nói); chữ hình thanh. Bộ 言 chỉ đây là hành động dùng lời nói để so sánh, ví von; 辟 (tích/bích) cho âm pì.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thí\": dùng lời (言) mở ra (辟) một ví dụ — 譬如 là \"thí như\" tức \"ví như\"; trong tiếng Việt \"thí dụ\" cũng từ gốc này. | Gương Hán-Việt | Thí xuất hiện trong \"thí dụ\" (譬如 – ví như), \"thí von\" (so sánh bằng ví dụ). | Mở khoá kiến thức | Biết 譬 giúp nhận ra gốc Hán-Việt của \"thí dụ\" và \"ví dụ như\" trong văn viết trang trọng.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Chữ 譬 là chữ hình thanh: bộ 言 (ngôn – lời nói) biểu nghĩa hành động dùng ngôn ngữ để so sánh, ví dụ; bộ 辟 (tích) biểu âm. Nghĩa là dùng lời để ví von, so sánh — 譬如 là \"ví như, ví dụ như\". Tiểu triện và Lục thư thông được lưu trong hanziyuan. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ví như, coi như", "Hạng Tần Suất (Jun Da)": "2436.0", "Tần Suất % (Jun Da)": "98.3610738254", "GavinGrover_Once (Chiết tự trực tiếp)": "辟 + 言", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱辟言", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "辟", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "言", "Unihan_Simplified (Chữ Giản thể)": "譬", "Unihan_Traditional (Chữ Phồn thể)": "譬", "Pinyin_Xie": "pì", "Âm Hán Việt_Xie": "thí", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ trong các từ ghép để đưa ra ví dụ hoặc so sánh đối chiếu. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('斌', '{"9000": "2437.0", "Chữ Trung Quốc": "斌", "Bộ thủ & thành phần_Xie": "Bộ thủ | 文 | Số nét | 12 | nét | 文 | văn | biểu nghĩa | văn chương, hoa văn | 武 | võ | biểu nghĩa | võ thuật, quân sự | 斌 = 文 (Văn, biểu nghĩa) + 武 (Võ, biểu nghĩa); chữ hội ý. Văn và Võ đặt cạnh nhau — người vừa có văn chương vừa có võ lược, lịch sự hào hoa.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bân\": Văn (文) gặp Võ (武) — người Bân nhã là kẻ cân bằng cả văn lẫn võ, tao nhã mà quyết đoán. | Gương Hán-Việt | bân trong tên người, \"bân bân\" (彬彬 — hào hoa lịch sự) | Mở khoá kiến thức | Biết 斌 mở khoá: 斌斌 (văn võ song toàn), 文质彬彬 (phong thái lịch thiệp — dùng chữ 彬 liên quan).", "Tự nguyên_Xie": "Wiktionary ghi 斌 là dạng khác của 彬, dùng trong tên người. Cấu trúc 文 + 武: hội ý, kết hợp văn (学thức) và võ (sức mạnh) — chỉ người tài đức toàn vẹn. Chưa có nguồn glyphOrigin học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lịch thiệp", "Hạng Tần Suất (Jun Da)": "2437.0", "Tần Suất % (Jun Da)": "98.363131147", "GavinGrover_Once (Chiết tự trực tiếp)": "文 + 武", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰文武", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "武", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "文", "Unihan_Simplified (Chữ Giản thể)": "斌", "Unihan_Traditional (Chữ Phồn thể)": "斌", "Pinyin_Xie": "bīn", "Âm Hán Việt_Xie": "bân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường dùng làm tính từ trong văn cổ hoặc xuất hiện phổ biến trong tên riêng của nam giới. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('祈', '{"9000": "2438.0", "Chữ Trung Quốc": "祈", "Bộ thủ & thành phần_Xie": "Bộ thủ | 示 | Số nét | 8 | nét | 礻 | thị | biểu nghĩa | bàn thờ, thần linh | 斤 | cân | biểu âm | cái rìu | 祈 = 礻 (Thị, biểu nghĩa: bàn thờ) + 斤 (Cân, biểu âm); chữ hình thanh. Bộ 礻 xác định liên quan đến lễ nghi thần linh, 斤 cho âm qí gần với kỳ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"kỳ\": đứng trước bàn Thờ (礻) cầm Rìu (斤) dâng lễ — hành động Kỳ nguyện, cầu xin thần linh ban phước. | Gương Hán-Việt | kỳ trong \"kỳ nguyện\", \"kỳ cầu\" — cầu khấn, mong ước | Mở khoá kiến thức | Biết 祈 mở khoá: 祈祷 (cầu nguyện), 祈求 (cầu xin), 祈福 (cầu phước).", "Tự nguyên_Xie": "Giáp cốt văn | Kim văn | Tiểu triện | Lục thư thông | Theo Wiktionary, 祈 là chữ hình thanh: 示 (thị, bàn thờ) biểu nghĩa, 斤 (cân) biểu âm. Nghĩa: cầu khấn, cầu nguyện với thần linh — người đứng trước bàn thờ dâng lễ cầu phúc. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cầu khấn; thỉnh cầu; cầu nguyện; cầu xin; van nài; cầu mong", "Hạng Tần Suất (Jun Da)": "2438.0", "Tần Suất % (Jun Da)": "98.3651802", "GavinGrover_Once (Chiết tự trực tiếp)": "礻 + 斤", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰礻斤", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "斤", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "礻", "Unihan_Simplified (Chữ Giản thể)": "祈", "Unihan_Traditional (Chữ Phồn thể)": "祈", "Pinyin_Xie": "qí", "Âm Hán Việt_Xie": "kì", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước đối tượng hoặc điều mà mình mong muốn cầu xin. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('踢', '{"9000": "2439.0", "Chữ Trung Quốc": "踢", "Bộ thủ & thành phần_Xie": "Bộ thủ | 足 | Số nét | 15 | nét | 𧾷 | túc | biểu nghĩa | bàn chân (dạng bộ của 足) | 易 | dịch | biểu âm | dễ, đổi (gợi âm yì → tī) | 踢 = 𧾷 (Túc, biểu nghĩa: bàn chân) + 易 (Dịch, biểu âm); chữ hình thanh — dùng chân tác động, đó là ''đá''.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thích\": dùng bàn chân (𧾷) làm một động tác đổi hướng (易) cho vật — đó là ''đá''. | Gương Hán-Việt | \"thích\" trong \"thích cước\" (踢脚) — chỉ động tác đá; chữ này ít gặp trong từ Hán-Việt thông dụng. | Mở khoá kiến thức | Nắm 踢 mở khoá: 踢 (đá), 踢足球 (đá bóng), 踢球 (đá bóng), 踢开 (đá ra).", "Tự nguyên_Xie": "Theo Wiktionary, 踢 là hợp thể hình thanh: 足 (bàn chân) biểu nghĩa, 易 biểu âm — chỉ động tác dùng chân đá. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "719.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Túc (295) Dịch (718)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Túc (số 295 - bàn chân) ở bên trái chữ Dịch (số 718 - biến đổi/dễ dàng). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Dịch chỉ âm, bộ Túc chỉ ý. Thích là dùng chân để đá.", "Nghĩa Tiếng Việt_Xie": "đá; đá bóng, đá cầu", "Hạng Tần Suất (Jun Da)": "2439.0", "Tần Suất % (Jun Da)": "98.3672261524", "GavinGrover_Once (Chiết tự trực tiếp)": "⻊ + 易", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰⻊易", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "易", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⻊", "Unihan_Simplified (Chữ Giản thể)": "踢", "Unihan_Traditional (Chữ Phồn thể)": "踢", "Pinyin_Xie": "tī", "Âm Hán Việt_Xie": "thích", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước danh từ chỉ quả bóng hoặc vật bị tác động lực bằng chân. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | tī | / | đá | Xuất hiện trong lộ trình | New HSK | New HSK 6 | · | Các môn thể thao", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('肆', '{"9000": "2440.0", "Chữ Trung Quốc": "肆", "Bộ thủ & thành phần_Xie": "Bộ thủ | 聿 | Số nét | 13 | nét | 镸 | trường | biểu nghĩa | dài | 聿 | duật | biểu âm | bút lông, cây bút | 肆 = 镸 (Trường, biểu nghĩa: dài) + 隶/聿 (biểu âm); chữ hình thanh theo Wiktionary (c1=s: 镸 biểu nghĩa, c2=p: 隶 biểu âm). Nghĩa gốc liên quan đến buông thả không giới hạn — cực độ, phóng túng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tứ\": buông dài (镸) không giới hạn như bốn phương (tứ phương) — 放肆 là buông thả hoàn toàn, hành động tùy ý không giới hạn; 大肆 là làm ầm ĩ tứ phía. | Gương Hán-Việt | Tứ xuất hiện trong 放肆 (phóng tứ – phóng túng), 大肆 (đại tứ – ầm ĩ, mạnh mẽ), 肆无忌惮 (tứ vô kị đảm – không kiêng nể ai). | Mở khoá kiến thức | Biết 肆 mở khoá: 放肆 (phóng túng), 大肆 (ầm ĩ, quy mô lớn), 肆虐 (hoành hành), 肆无忌惮 (không kiêng nể).", "Tự nguyên_Xie": "Tiểu triện | Chữ 肆 là chữ hình thanh: bộ 镸 (trường – dài) biểu nghĩa khái niệm vươn dài ra không giới hạn, bộ 隶 biểu âm. Nghĩa gốc là phô bày, phơi bày; mở rộng ra có nghĩa là phóng túng, không kiềm chế (放肆), và cũng được dùng làm số bốn (四) trong văn bản trang trọng chống sửa chữa. Tiểu triện được lưu tại wikimedia. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cùng cực, phóng túng; phơi bày, bêu; bốn, 4 (như 四, dùng trong văn tự)", "Hạng Tần Suất (Jun Da)": "2440.0", "Tần Suất % (Jun Da)": "98.3692705544", "GavinGrover_Once (Chiết tự trực tiếp)": "镸 + 聿", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰镸聿", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "聿", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "镸", "Unihan_Simplified (Chữ Giản thể)": "肆", "Unihan_Traditional (Chữ Phồn thể)": "肆", "Pinyin_Xie": "sì", "Âm Hán Việt_Xie": "tứ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Số từ | 数词 | Thường làm tính từ chỉ sự buông thả hoặc làm danh từ chỉ cửa hàng và số bốn viết hoa. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Số từ | 数词 | Chỉ số lượng hoặc thứ tự. Hầu như không đứng thẳng trước danh từ mà phải chèn lượng từ ở giữa: 两个人.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('坎', '{"9000": "2441.0", "Chữ Trung Quốc": "坎", "Bộ thủ & thành phần_Xie": "Bộ thủ | 土 | Số nét | 7 | nét | 土 | thổ | biểu nghĩa | đất | 欠 | khiếm | biểu âm | thiếu, ngáp | 坎 = 土 (Thổ, biểu nghĩa: đất) + 欠 (Khiếm, biểu âm); chữ hình thanh. Bộ 土 xác định liên quan đến đất/địa hình, 欠 cho âm kǎn gần với khảm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khảm\": mặt Đất (土) có chỗ Khiếm (欠) lõm xuống — cái hố, quẻ Khảm tượng nước chảy vào chỗ trũng. | Gương Hán-Việt | khảm trong \"quẻ khảm\", \"khảm khổ\" — hiểm trở, gian nan | Mở khoá kiến thức | Biết 坎 mở khoá: 坎坷 (gian nan trắc trở), 坎儿井 (giếng thấm ngầm), 坎坎 (tiếng chặt cây).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 坎 là chữ hình thanh: 土 (thổ, đất) biểu nghĩa, 欠 biểu âm. Nghĩa gốc: hố đất, chỗ trũng; đây cũng là quẻ Khảm trong Kinh Dịch tượng trưng cho nước và hiểm trở. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "quẻ Khảm (trung mãn) trong Kinh Dịch (chỉ có vạch giữa liền, tượng Thuỷ (nước), tượng trưng con trai giữa, hành Thuỷ, tuổi Tý, hướng Bắc)", "Hạng Tần Suất (Jun Da)": "2441.0", "Tần Suất % (Jun Da)": "98.3713108221", "GavinGrover_Once (Chiết tự trực tiếp)": "土 + 欠", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰土欠", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "欠", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "土", "Unihan_Simplified (Chữ Giản thể)": "坎", "Unihan_Traditional (Chữ Phồn thể)": "坎", "Pinyin_Xie": "kǎn", "Âm Hán Việt_Xie": "khảm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ địa hình gồ ghề, quẻ bói hoặc ẩn dụ cho những khó khăn trong cuộc đời. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('轿', '{"9000": "2442.0", "Chữ Trung Quốc": "轿", "Bộ thủ & thành phần_Xie": "Bộ thủ | 車 | Số nét | 10 | nét | 车 | xa | biểu nghĩa | xe | 乔 | kiều | biểu âm | cao, kiều | 轿 = 车 (Xa, biểu nghĩa: xe) + 乔 (Kiều, biểu âm); chữ hình thanh. Bộ 车 xác định là loại phương tiện, 乔 cho âm jiào gần với kiệu.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"kiệu\": chiếc Xe (车) được khiêng Cao (乔) trên vai — cái Kiệu không lăn bánh mà do người vác. | Gương Hán-Việt | kiệu trong \"kiệu hoa\" (轿子), \"đi kiệu\" — phương tiện sang trọng thời xưa | Mở khoá kiến thức | Biết 轿 mở khoá: 轿车 (xe hơi), 花轿 (kiệu hoa cưới), 轿子 (cái kiệu).", "Tự nguyên_Xie": "Wiktionary ghi 轿 là giản thể của 轎 (車 + 喬). Cấu trúc hình thanh: 車 biểu nghĩa, 喬 biểu âm. Kiệu là loại xe được khiêng trên vai người, không có bánh — thường dùng cho quan lại và cô dâu thời cổ. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái kiệu", "Hạng Tần Suất (Jun Da)": "2442.0", "Tần Suất % (Jun Da)": "98.3733479891", "GavinGrover_Once (Chiết tự trực tiếp)": "车 + 乔", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰车乔", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "乔", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "车", "Unihan_Simplified (Chữ Giản thể)": "轿", "Unihan_Traditional (Chữ Phồn thể)": "轎", "Pinyin_Xie": "jiào", "Âm Hán Việt_Xie": "kiệu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng sau lượng từ để chỉ phương tiện di chuyển bằng sức người khi xưa hoặc xe hơi ngày nay. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('棚', '{"9000": "2443.0", "Chữ Trung Quốc": "棚", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 12 | nét | 木 | mộc | biểu nghĩa | cây gỗ | 朋 | bằng | biểu âm | bạn bè | 棚 = 木 (Mộc, biểu nghĩa: gỗ) + 朋 (Bằng, biểu âm); chữ hình thanh. Bộ 木 xác định đây là kết cấu bằng gỗ, 朋 cho âm péng gần với bằng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bằng\": gỗ Mộc (木) do bạn Bằng (朋) dựng lên — cái lán, rạp che tạm, nơi mọi người tụ họp. | Gương Hán-Việt | bằng trong \"bằng hữu\" (朋友, chữ khác), nhưng 棚 là danh từ chỉ lán/rạp | Mở khoá kiến thức | Biết 棚 mở khoá: 大棚 (nhà kính), 牛棚 (chuồng bò), 天棚 (trần nhà/mái che).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 棚 là chữ hình thanh: 木 (mộc) biểu nghĩa, 朋 biểu âm. Nghĩa: lán, rạp, mái che làm bằng gỗ — kết cấu mái che tạm thời hoặc nhà kho nhỏ. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "gác, nhà rạp; đơn vị quân gồm 14 lính", "Hạng Tần Suất (Jun Da)": "2443.0", "Tần Suất % (Jun Da)": "98.3753784379", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 朋", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木朋", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "朋", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "棚", "Unihan_Traditional (Chữ Phồn thể)": "棚", "Pinyin_Xie": "péng", "Âm Hán Việt_Xie": "bằng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ các công trình tạm bợ che mưa nắng hoặc giàn cho cây leo. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('泣', '{"9000": "2444.0", "Chữ Trung Quốc": "泣", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 8 | nét | 氵 | thuỷ | biểu nghĩa | nước, nước mắt | 立 | lập | biểu âm | đứng | 泣 = 氵 (Thuỷ, biểu nghĩa: nước/nước mắt) + 立 (Lập, biểu âm); chữ hình thanh. Bộ 氵 chỉ nước mắt chảy, 立 (lập) cho âm qì. Wiktionary ghi: chữ 泣 ban đầu có nghĩa là \"nước mắt\", từ đó mở rộng thành \"khóc\".", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khấp\": nước (氵) đọng lại đứng yên (立) rồi rơi xuống thành giọt — 泣 là khóc thầm lặng, nước mắt chảy không thành tiếng; khác với 哭 (khóc to). | Gương Hán-Việt | Khấp xuất hiện trong \"ám khấp\" (khóc thầm), 哭泣 (khốc khấp – khóc), 可歌可泣 (đáng ca đáng khóc – cảm động). | Mở khoá kiến thức | Biết 泣 mở khoá: 哭泣 (khóc), 泣不成声 (khóc không thành tiếng), 可歌可泣 (cảm động sâu sắc).", "Tự nguyên_Xie": "Đại triện | Tiểu triện | Chữ 泣 là chữ hình thanh: bộ 水 (thuỷ – nước, viết tắt thành 氵) biểu nghĩa nước mắt chảy, bộ 立 (lập) biểu âm. Theo Wiktionary (dẫn Digital Shinjigen 2017): chữ này ban đầu có nghĩa là \"nước mắt\", rồi mở rộng sang nghĩa \"khóc\". Đại triện và tiểu triện được lưu tại wikimedia. Hán-Việt đọc là Khấp — cùng gốc với \"khấp khởi\" hoặc \"ám khấp\" (khóc thầm). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "411.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thủy (306) Lập (284)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Thủy (số 76) và chữ Lập (số 99 - đứng) . Người đứng (Lập) im lặng rớt nước mắt (Thủy) gọi là khóc thầm (khấp). Giải thích sự chuyển ý: Chữ Lập (đứng) chỉ âm, chữ Thủy (nước mắt) chỉ ý. Nước mắt (Thủy) tuôn rơi một cách âm thầm (Khấp). *(Biến âm Hán Việt: Lập -> Khấp)*", "Nghĩa Tiếng Việt_Xie": "khóc không thành tiếng", "Hạng Tần Suất (Jun Da)": "2444.0", "Tần Suất % (Jun Da)": "98.3774088867", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 立", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵立", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "立", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "泣", "Unihan_Traditional (Chữ Phồn thể)": "泣", "Pinyin_Xie": "qì", "Âm Hán Việt_Xie": "khấp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chữ này thường làm động từ chỉ hành động khóc không thành tiếng hoặc làm danh từ trong các từ ghép chỉ sự khóc lóc. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('屡', '{"9000": "2445.0", "Chữ Trung Quốc": "屡", "Bộ thủ & thành phần_Xie": "Bộ thủ | 尸 | Số nét | 12 | nét | 尸 | thi | biểu nghĩa | xác chết, hình người ngồi | 娄 | lâu | biểu âm | tầng lầu, lỗ trống | 屡 = 尸 (Thi, biểu nghĩa) + 娄 (Lâu, biểu âm); dạng giản thể của 屢. Wiktionary chỉ ghi nhận đây là dạng giản thể (simp) của 屢 (娄 thay thế 婁). Chữ gốc 屢 là hình thanh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lũ\": như người (尸) nhiều tầng (娄) chồng chất lên nhau — 屡次 là \"lũ thứ\" tức nhiều lần liên tiếp; \"屡屡\" là lặp đi lặp lại mãi. | Gương Hán-Việt | Lũ xuất hiện trong 屡次 (lũ thứ – nhiều lần), 屡屡 (lũ lũ – liên tiếp). | Mở khoá kiến thức | Biết 屡 mở khoá: 屡次 (nhiều lần), 屡见不鲜 (thường thấy không lạ), 屡教不改 (dạy mãi không sửa).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Chữ 屡 là dạng giản thể của 屢 (phồn thể). Cấu trúc hình thanh: bộ 尸 (thi – hình người) biểu nghĩa liên quan đến con người, bộ 婁 (lâu, giản thể là 娄) biểu âm. Nghĩa là thường xuyên, liên tiếp, nhiều lần. Tiểu triện và Lục thư thông được lưu tại hanziyuan. Hán-Việt đọc là Lũ — cùng gốc với \"lũ lần\" (nhiều lần). | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thường, luôn", "Hạng Tần Suất (Jun Da)": "2445.0", "Tần Suất % (Jun Da)": "98.3794372683", "GavinGrover_Once (Chiết tự trực tiếp)": "尸 + 娄", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴尸娄", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "娄", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "尸", "Unihan_Simplified (Chữ Giản thể)": "屡", "Unihan_Traditional (Chữ Phồn thể)": "屢", "Pinyin_Xie": "lǚ", "Âm Hán Việt_Xie": "lũ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Phó từ | 副词 | Chữ này làm phó từ đứng trước động từ để chỉ hành động xảy ra lặp đi lặp lại nhiều lần. | Phó từ | 副词 | Bổ nghĩa cho động từ hoặc tính từ và luôn đứng TRƯỚC chúng — 都是, 很好. Không đứng sau như tiếng Việt và không bổ nghĩa cho danh từ.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | lǚ | / | nhiều lần | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Từ chức năng và phụ từ II", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('躁', '{"9000": "2446.0", "Chữ Trung Quốc": "躁", "Bộ thủ & thành phần_Xie": "Bộ thủ | 足 | Số nét | 20 | nét | 𧾷 | biểu nghĩa | bộ túc (chân) biến thể — chỉ hành động di chuyển | 喿 | táo | biểu âm | âm thanh chim hót ồn ào | 躁 = 𧾷 (biến thể bộ Túc – chân, biểu nghĩa) + 喿 (Táo, biểu âm); có thể là chữ hình thanh. Bộ 𧾷 (liên quan đến chân, bước đi) gợi ý sự cử động không yên, còn 喿 (táo) cho âm zào. Wiktionary chưa có nguồn gốc rõ ràng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"táo\": chân (𧾷) cứ chạy lên chạy xuống ồn ào (喿) — 躁 là trạng thái bồn chồn, nóng nảy không ngồi yên được; 急躁 là nóng vội. | Gương Hán-Việt | Táo xuất hiện trong 急躁 (cấp táo – nóng vội), 暴躁 (bạo táo – cáu kỉnh, dữ dằn), 浮躁 (phù táo – bốc đồng). | Mở khoá kiến thức | Biết 躁 mở khoá: 急躁 (nóng vội), 暴躁 (dữ dằn), 浮躁 (bốc đồng), 烦躁 (bực bội), 焦躁 (lo lắng nóng nảy).", "Tự nguyên_Xie": "Chữ 躁 chưa có nguồn gốc rõ ràng từ Wiktionary (chỉ ghi {{Han etym}} trống). Theo cấu trúc: bộ 𧾷 (biến thể bộ Túc – chân) gợi ý sự cử động không yên; bộ 喿 (táo) biểu âm. Nghĩa là bốc đồng, nóng nảy, không kiên nhẫn. Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "vội tiến, xao động", "Hạng Tần Suất (Jun Da)": "2446.0", "Tần Suất % (Jun Da)": "98.3814615157", "GavinGrover_Once (Chiết tự trực tiếp)": "⻊ + 喿", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰⻊喿", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "喿", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⻊", "Unihan_Simplified (Chữ Giản thể)": "躁", "Unihan_Traditional (Chữ Phồn thể)": "躁", "Pinyin_Xie": "zào", "Âm Hán Việt_Xie": "táo", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này làm tính từ bổ nghĩa cho danh từ hoặc làm vị ngữ để miêu tả tính cách, trạng thái nôn nóng. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('邱', '{"9000": "2447.0", "Chữ Trung Quốc": "邱", "Bộ thủ & thành phần_Xie": "Bộ thủ | 邑 | Số nét | 7 | nét | 丘 | khâu | biểu âm | gò đất nhỏ | 阝 | phụ | biểu nghĩa | ấp, làng (bộ thủ bên phải) | 邱 = 丘 (Khâu, biểu âm) + 邑/阝 (Phụ, biểu nghĩa: làng ấp); chữ hình thanh. Bộ 阝 bên phải là biến thể của 邑 (ấp), 丘 cho âm qiū gần với khâu.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khâu\": cái gò Khâu (丘) có làng Ấp (阝) — 邱 là họ người, nơi định cư trên gò đất. | Gương Hán-Việt | khâu trong họ Khâu, tên đất — gò đất, địa danh | Mở khoá kiến thức | Biết 邱 mở khoá: 邱比特 (Cupid), các địa danh và họ người họ Khâu.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 邱 là chữ hình thanh: 邑 (ấp, làng) biểu nghĩa, 丘 biểu âm. Chữ được tạo ra để tránh tên huý của Khổng Tử (Khổng Khâu 孔丘) — thay 丘 bằng 邱 khi dùng làm họ. Nguyên nghĩa: tên đất, gò đất có làng. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(tên đất)", "Hạng Tần Suất (Jun Da)": "2447.0", "Tần Suất % (Jun Da)": "98.3834831791", "GavinGrover_Once (Chiết tự trực tiếp)": "丘 + 阝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰丘阝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "丘", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "阝", "Unihan_Simplified (Chữ Giản thể)": "邱", "Unihan_Traditional (Chữ Phồn thể)": "邱", "Pinyin_Xie": "qiū", "Âm Hán Việt_Xie": "khâu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này chủ yếu dùng làm danh từ riêng để chỉ họ người hoặc địa danh. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('凰', '{"9000": "2448.0", "Chữ Trung Quốc": "凰", "Bộ thủ & thành phần_Xie": "Bộ thủ | 几 | Số nét | 11 | nét | 几 | cơ | biểu nghĩa | bàn nhỏ, cái kệ (hình chim khoanh cánh) | 皇 | hoàng | biểu âm | hoàng đế, rực rỡ | 凰 = 几 (Cơ, bộ khung ngoài) + 皇 (Hoàng, biểu âm và biểu nghĩa: rực rỡ, hoàng); chữ hội ý lẫn hình thanh. Ban đầu 凰 chỉ là 皇, phần 𠘨/几 thêm vào sau do ảnh hưởng của 鳳 (phụng).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hoàng\": chim Hoàng (皇 — rực rỡ như vua) bay trong khung Cơ (几) — con phượng cái uy nghi, nửa trên là bộ chim. | Gương Hán-Việt | hoàng trong \"phượng hoàng\" (鳳凰), \"hoàng kim\" — rực rỡ, cao quý | Mở khoá kiến thức | Biết 凰 mở khoá: 凤凰 (phượng hoàng), 凤凰木 (cây phượng vĩ), 求凰 (cầu hoàng — tìm người đẹp).", "Tự nguyên_Xie": "Theo Wiktionary, 凰 ban đầu cùng chữ với 皇. Phần 𠘨 (hình con chim) được thêm vào do đồng hoá với 鳳 (phượng đực). Chữ chỉ phượng hoàng cái trong thần thoại Trung Hoa — đôi 鳳凰 (phượng đực + hoàng cái) tượng trưng cho hạnh phúc, thiên hạ thái bình. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chim phượng hoàng (con cái)", "Hạng Tần Suất (Jun Da)": "2448.0", "Tần Suất % (Jun Da)": "98.3855043258", "GavinGrover_Once (Chiết tự trực tiếp)": "几 + 皇", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿵ (Bao quanh phía trên)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴几皇", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "皇", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "几", "Unihan_Simplified (Chữ Giản thể)": "凰", "Unihan_Traditional (Chữ Phồn thể)": "凰", "Pinyin_Xie": "huáng", "Âm Hán Việt_Xie": "hoàng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ, thường kết hợp với chữ phượng tạo thành từ ghép chỉ loài chim thần thoại. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('溢', '{"9000": "2449.0", "Chữ Trung Quốc": "溢", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 13 | nét | 氵 | thuỷ | biểu nghĩa | nước | 益 | ích | biểu âm và biểu nghĩa | thêm, tăng thêm | 溢 = 氵 (Thuỷ, biểu nghĩa: nước) + 益 (Ích, vừa biểu âm vừa biểu nghĩa: tăng thêm); chữ hội ý kiêm hình thanh. 氵 chỉ nước, 益 gợi ý nước tăng lên tràn ra — hình ảnh bình nước đầy tràn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"dật\": Nước (氵) Ích (益) thêm mãi — khi nước Ích đầy quá thì Dật tràn ra ngoài. | Gương Hán-Việt | dật trong \"dật lạc\" (tràn đầy niềm vui), \"dật ra\" — tràn, vượt quá | Mở khoá kiến thức | Biết 溢 mở khoá: 洋溢 (tràn ngập), 溢出 (tràn ra), 溢价 (giá premium).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Theo Wiktionary, 溢 là chữ hội ý lẫn hình thanh: 水/氵 (thuỷ, nước) biểu nghĩa, 益 vừa biểu âm vừa góp nghĩa \"tăng thêm\" — nước tăng lên tràn ra. Nghĩa gốc: tràn đầy, nước chảy vượt bờ. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đầy tràn; phóng túng", "Hạng Tần Suất (Jun Da)": "2449.0", "Tần Suất % (Jun Da)": "98.3875244389", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 益", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵益", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "益", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "溢", "Unihan_Traditional (Chữ Phồn thể)": "溢", "Pinyin_Xie": "yì", "Âm Hán Việt_Xie": "dật", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Chữ này làm động từ chỉ chất lỏng tràn ra ngoài hoặc làm tính từ chỉ sự dồi dào, tràn đầy. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | yì | / | tràn | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Sự kiện tự nhiên II", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('椎', '{"9000": "2450.0", "Chữ Trung Quốc": "椎", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 12 | nét | 木 | mộc | biểu nghĩa | gỗ, cây | 隹 | chuy | biểu âm | chim đuôi ngắn | 椎 = 木 (Mộc, biểu nghĩa: gỗ) + 隹 (Chuy, biểu âm); chữ hình thanh. Wiktionary giải thích: bộ 木 biểu nghĩa vật dụng làm bằng gỗ để đập (búa/chày), 隹 cho âm. Chữ có hai nghĩa chính: búa gỗ và đốt sống cột sống.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chuỳ\": khúc gỗ (木) hình con chim (隹) — cái chày gỗ; hiện đại dùng trong 颈椎 (đốt sống cổ) vì đốt sống tròn như đầu chày. | Gương Hán-Việt | Chuỳ xuất hiện trong 颈椎 (cảnh chuy – đốt sống cổ), 脊椎 (tích chuy – cột sống). | Mở khoá kiến thức | Biết 椎 mở khoá từ y học: 颈椎 (đốt sống cổ), 腰椎 (đốt sống lưng), 脊椎 (cột sống).", "Tự nguyên_Xie": "Tiểu triện | Chữ 椎 là chữ hình thanh: bộ 木 (mộc – gỗ) biểu nghĩa một khúc gỗ dùng để đập, đó là \"búa\" hoặc \"chày\"; bộ 隹 (chuy – chim đuôi ngắn) biểu âm. Theo Wiktionary (dẫn Digital Shinjigen 2017): chữ biểu đạt ý một mảnh gỗ dùng để đập vỡ. Nghĩa y khoa \"đốt sống\" phát triển muộn hơn. Tiểu triện được lưu tại hanziyuan. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "xương sống", "Hạng Tần Suất (Jun Da)": "2450.0", "Tần Suất % (Jun Da)": "98.3895336995", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 隹", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木隹", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "隹", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "椎", "Unihan_Traditional (Chữ Phồn thể)": "椎", "Pinyin_Xie": "chuí", "Âm Hán Việt_Xie": "chùy", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ các đốt xương sống hoặc dụng cụ hình cái chùy để gõ đập. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('砸', '{"9000": "2451.0", "Chữ Trung Quốc": "砸", "Bộ thủ & thành phần_Xie": "Bộ thủ | 石 | Số nét | 10 | nét | 石 | thạch | biểu nghĩa | đá | 匝 | táp | biểu âm | vòng quanh, bao quanh | 砸 = 石 (Thạch, biểu nghĩa: đá) + 匝 (Táp, biểu âm); có thể là chữ hình thanh. Bộ 石 chỉ dùng đá hoặc vật cứng để đập vỡ, 匝 cho âm gần với zá. Wiktionary chưa có glyphOrigin đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tạp\": lấy đá (石) đập vòng quanh (匝) cho tan vỡ — 砸 là đập nát; 砸烂 là đập tan tành, 砸锅 là hỏng bét việc. | Gương Hán-Việt | Tạp ít xuất hiện trong từ Hán-Việt thông dụng; 砸 chủ yếu dùng trong tiếng Trung khẩu ngữ. | Mở khoá kiến thức | Biết 砸 mở khoá từ khẩu ngữ: 砸 (đập vỡ), 砸锅 (hỏng việc), 砸场 (phá đám).", "Tự nguyên_Xie": "Chữ 砸 chưa có nguồn gốc đầy đủ trong Wiktionary (chỉ ghi {{Han etym}} trống). Theo cấu trúc: bộ 石 (thạch – đá) biểu nghĩa dùng vật cứng đập vỡ; bộ 匝 (táp) biểu âm. Nghĩa là đập vỡ, nghiền nát, phá vỡ. Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đóng, lèn chặt; hỏng, vỡ", "Hạng Tần Suất (Jun Da)": "2451.0", "Tần Suất % (Jun Da)": "98.3915393426", "GavinGrover_Once (Chiết tự trực tiếp)": "石 + 匝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰石匝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "匝", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "石", "Unihan_Simplified (Chữ Giản thể)": "砸", "Unihan_Traditional (Chữ Phồn thể)": "砸", "Pinyin_Xie": "zá", "Âm Hán Việt_Xie": "tạp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ chỉ hành động đập mạnh làm vỡ vật thể hoặc biểu thị việc bị thất bại, đổ bể. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | zá | / | đập vỡ | Xuất hiện trong lộ trình | HSK | HSK 6 | · | Động từ hàng ngày | New HSK | New HSK 7-9 | · | Từ III", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('趟', '{"9000": "2452.0", "Chữ Trung Quốc": "趟", "Bộ thủ & thành phần_Xie": "Bộ thủ | 走 | Số nét | 15 | nét | 走 | tẩu | biểu nghĩa | chạy / đi | 尚 | thượng | biểu âm | gợi âm ''tàng'' | 趟 = 走 (Tẩu, đi) + 尚 (Thượng, biểu âm). Chữ hình thanh: một chuyến đi — làm lượng từ cho ''chuyến'' (đi/về). Đọc ''tāng'' với nghĩa ''lội qua (nước)''.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt ''Thảng'': một chuyến đi (走) trang trọng (尚) — đó là ''thảng'', là một chuyến. | Gương Hán-Việt | ''Thảng'' (Hán-Việt cổ); trong tiếng Việt hiện đại 趟 dịch ''chuyến, lượt'' (lượng từ). | Mở khoá kiến thức | Biết 趟 mở khóa cách dùng làm lượng từ: 一趟 (một chuyến), 去一趟 (đi một chuyến).", "Tự nguyên_Xie": "Theo Wiktionary, 趟 là chữ hình thanh: 走 biểu nghĩa, 尚 biểu âm. Dùng làm lượng từ cho ''chuyến đi'', và động từ ''lội qua''. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nhảy choi choi; chạy một mạch", "Hạng Tần Suất (Jun Da)": "2452.0", "Tần Suất % (Jun Da)": "98.3935439521", "GavinGrover_Once (Chiết tự trực tiếp)": "走 + 尚", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴走尚", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "尚", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "走", "Unihan_Simplified (Chữ Giản thể)": "趟", "Unihan_Traditional (Chữ Phồn thể)": "趟", "Pinyin_Xie": "tàng", "Âm Hán Việt_Xie": "thảng, tranh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Lượng từ | 量词 | Danh từ | 名词 | Chữ này làm lượng từ cho chuyến đi hoặc danh từ chỉ hàng lối, bước đi. | Lượng từ | 量词 | Đứng giữa số từ (hoặc 这/那) và danh từ: 一杯茶, 这本书. Mỗi danh từ đi với lượng từ riêng; 个 là lượng từ dùng chung phổ biến nhất. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | tàng | / | chuyến | Xuất hiện trong lộ trình | New HSK | New HSK 6 | · | Từ chức năng II | HSK | HSK 4 | · | Từ chức năng", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('帘', '{"9000": "2453.0", "Chữ Trung Quốc": "帘", "Bộ thủ & thành phần_Xie": "Bộ thủ | 巾 | Số nét | 8 | nét | 穴 | huyệt | biểu nghĩa | lỗ hổng, cửa vào | 巾 | cân | biểu nghĩa | vải, khăn | 帘 = 穴 (Huyệt, lỗ/cửa) + 巾 (Cân, vải); chữ hội ý. Tấm vải che cửa — rèm. Không có ls code rõ ràng từ Wiktionary; cấu trúc hội ý gợi ý tấm vải (巾) treo trước lỗ/cửa (穴).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"liêm\": tấm vải (巾-Cân) che lấp cửa (穴-Huyệt) — rèm che cửa sổ. Liêm = rèm. | Gương Hán-Việt | liêm trong ''liêm sỉ'' — nhưng đây là ''rèm'' (窗帘 cửa sổ + rèm) | Mở khoá kiến thức | Biết 帘 mở khoá: 窗帘 (song liêm – rèm cửa sổ), 门帘 (môn liêm – rèm cửa).", "Tự nguyên_Xie": "帘 ban đầu chỉ tấm cờ vải treo trước cửa quán rượu để báo hiệu. Wiktionary ghi nghĩa cổ là ''sign hung in front of a tavern''s entrance''. Chữ gồm 穴 (huyệt — lỗ, cửa) trên và 巾 (cân — vải) dưới, gợi hình tấm vải che trước khoảng trống. Nghĩa hiện đại mở rộng sang rèm cửa nói chung (窗帘). Chưa có glyphOrigin chi tiết từ Wiktionary, chưa có nguồn học thuật đầy đủ. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái cờ bài rượu", "Hạng Tần Suất (Jun Da)": "2453.0", "Tần Suất % (Jun Da)": "98.3955464945", "GavinGrover_Once (Chiết tự trực tiếp)": "穴 + 巾", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱穴巾", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "巾", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "穴", "Unihan_Simplified (Chữ Giản thể)": "帘", "Unihan_Traditional (Chữ Phồn thể)": "帘", "Pinyin_Xie": "lián", "Âm Hán Việt_Xie": "liêm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ các loại rèm cửa hoặc tấm màn dùng để che chắn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('帆', '{"9000": "2454.0", "Chữ Trung Quốc": "帆", "Bộ thủ & thành phần_Xie": "Bộ thủ | 巾 | Số nét | 6 | nét | 巾 | cân | biểu nghĩa | vải, khăn | 凡 | phàm | biểu âm | bình thường, tất cả | 帆 = 巾 (Cân, biểu nghĩa: vải) + 凡 (Phàm, biểu âm); chữ hình thanh. Bộ 巾 chỉ cánh buồm là miếng vải căng ra hứng gió, 凡 (phàm) cho âm fān.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phàm\": tấm vải (巾) phàm thường (凡) mà tạo nên cánh buồm kỳ diệu — 帆船 là thuyền buồm; 一帆风顺 là thuận buồm xuôi gió, mọi việc thuận lợi. | Gương Hán-Việt | Phàm xuất hiện trong 帆船 (phàm thuyền – thuyền buồm), 一帆风顺 (nhất phàm phong thuận – thuận buồm xuôi gió). | Mở khoá kiến thức | Biết 帆 mở khoá: 帆船 (thuyền buồm), 一帆风顺 (thuận buồm xuôi gió), 风帆 (cánh buồm).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Chữ 帆 là chữ hình thanh: bộ 巾 (cân – vải, khăn) biểu nghĩa cánh buồm làm bằng vải, bộ 凡 (phàm) biểu âm. Tiểu triện và Lục thư thông được lưu tại hanziyuan. Hán-Việt đọc là Phàm — cùng âm với 凡 (phàm – bình thường) nhưng nghĩa hoàn toàn khác. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "448.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Cân (196) Phàm (50)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Cân (số 50 - cái khăn / tấm vải) và chữ Phàm (số 16 - bình thường) . Dùng tấm vải (Cân) to bình thường (Phàm) treo lên cột buồm để đón gió đẩy thuyền đi gọi là cánh buồm (phàm). Giải thích sự chuyển ý: Chữ Phàm (bình thường) chỉ âm, chữ Cân (khăn/vải) chỉ ý. Tấm vải (Cân) lớn giăng trên thuyền đón gió gọi là cánh buồm (Phàm).", "Nghĩa Tiếng Việt_Xie": "cánh buồm", "Hạng Tần Suất (Jun Da)": "2454.0", "Tần Suất % (Jun Da)": "98.3975485202", "GavinGrover_Once (Chiết tự trực tiếp)": "巾 + 凡", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰巾凡", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "凡", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "巾", "Unihan_Simplified (Chữ Giản thể)": "帆", "Unihan_Traditional (Chữ Phồn thể)": "㠶", "Pinyin_Xie": "fān", "Âm Hán Việt_Xie": "phàm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ cánh buồm của thuyền hoặc dùng để ẩn dụ cho con thuyền. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | fān | / | buồm | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Phong trào I", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('栖', '{"9000": "2455.0", "Chữ Trung Quốc": "栖", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 10 | nét | 木 | mộc | biểu nghĩa | cây | 西 | tây | biểu âm | phía tây | 栖 = 木 (Mộc, biểu nghĩa: cây) + 西 (Tây, biểu âm); chữ hình thanh. Bộ 木 xác định liên quan đến cây, 西 cho âm qī gần với thê.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thê\": cành Cây (木) phía Tây (西) lúc hoàng hôn — chim Thê đậu trên cành cây, yên nghỉ sau ngày dài. | Gương Hán-Việt | thê trong \"thê lương\" (buồn bã), \"thê thảm\" — 栖 nghĩa khác nhưng âm thê gợi cảnh hoàng hôn buồn | Mở khoá kiến thức | Biết 栖 mở khoá: 两栖 (lưỡng cư), 栖息 (trú ngụ, đậu nghỉ), 栖居 (cư trú).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 栖 là chữ hình thanh: 木 (mộc, cây) biểu nghĩa, 西 biểu âm. Nghĩa: đậu (chim đậu trên cây), ở lại nghỉ ngơi — hình ảnh chim đậu trên cành cây lúc chiều tà. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nghỉ ngơi; đậu (chim); cái giường", "Hạng Tần Suất (Jun Da)": "2455.0", "Tần Suất % (Jun Da)": "98.3995469283", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 西", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木西", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "西", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "栖", "Unihan_Traditional (Chữ Phồn thể)": "棲", "Pinyin_Xie": "qī", "Âm Hán Việt_Xie": "thê, tây", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ chỉ chim đậu trên cây hoặc người tìm nơi trú ngụ, sinh sống. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('窜', '{"9000": "2456.0", "Chữ Trung Quốc": "窜", "Bộ thủ & thành phần_Xie": "Bộ thủ | 穴 | Số nét | 12 | nét | 穴 | huyệt | biểu nghĩa | hang hố, lỗ trống | 串 | xuyến | biểu âm | xâu chuỗi | 窜 = 穴 (Huyệt, biểu nghĩa: hang hố) + 串 (Xuyến, biểu âm); dạng giản thể của 竄 (鼠 thay bằng 串). Bộ 穴 gợi ý hành động chạy trốn vào hang hẻm như chuột.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thoán\": con chuột (鼠→串) chui vào hang (穴) trốn biệt — 窜 là chạy trốn, lẩn trốn nhanh; 东窜西跑 là chạy loạn như chuột. | Gương Hán-Việt | Thoán xuất hiện trong 窜改 (thoán cải – sửa chữa xuyên tạc), 逃窜 (đào thoán – chạy trốn). | Mở khoá kiến thức | Biết 窜 mở khoá: 窜改 (xuyên tạc), 逃窜 (chạy trốn), 东奔西窜 (chạy loạn).", "Tự nguyên_Xie": "Tiểu triện | Chữ 窜 là dạng giản thể của 竄 (phồn thể). Chữ gốc 竄 gồm 穴 (hang hố) và 鼠 (chuột) — hình ảnh con chuột chạy trốn vào hang. Dạng giản thể thay 鼠 bằng 串 (xuyến) để đơn giản hóa. Nghĩa là chạy trốn, lẩn trốn; cũng có nghĩa sửa chữa văn bản (窜改 – sửa chữa, xuyên tạc). Tiểu triện được lưu tại wikimedia. Hán-Việt đọc là Thoán. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chạy trốn; đuổi đi, đuổi ra; sửa (bài), chữa (văn); sực mùi, nức mùi; giấu giếm; giết; hun, xông (bằng thuốc)", "Hạng Tần Suất (Jun Da)": "2456.0", "Tần Suất % (Jun Da)": "98.4015443028", "GavinGrover_Once (Chiết tự trực tiếp)": "穴 + 串", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱穴串", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "串", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "穴", "Unihan_Simplified (Chữ Giản thể)": "窜", "Unihan_Traditional (Chữ Phồn thể)": "竄", "Pinyin_Xie": "cuàn", "Âm Hán Việt_Xie": "thoán", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ biểu thị hành động chạy trốn hoặc sửa đổi văn bản. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | cuàn | / | trốn | Xuất hiện trong lộ trình | HSK | HSK 6 | · | Sự chuyển động | New HSK | New HSK 7-9 | · | Phong trào I", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('丸', '{"9000": "2457.0", "Chữ Trung Quốc": "丸", "Bộ thủ & thành phần_Xie": "Bộ thủ | 丶 | Số nét | 3 | nét | 丸 | hoàn | tượng hình | vật hình tròn, viên nhỏ — biến thể phân hóa từ 夗 (người nằm cuộn) | 丸 là chữ hội ý độc thể. Wiktionary giải thích: đây là chữ hội ý phân hóa từ 夗 (người nằm cuộn tròn) — gợi ý vật gì đó có thể lăn, hình tròn. Không phải hình thanh. Thành phần 九 trong cấu trúc không độc lập mang nghĩa ở đây.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hoàn\": viên thuốc (丸) tròn lăn được — \"hoàn\" trong Đông y là dạng thuốc viên; 丸子 là viên thịt trong ẩm thực. | Gương Hán-Việt | Hoàn xuất hiện trong \"thuốc hoàn\" (丸药 – thuốc viên), \"hoàn tán\" (dạng thuốc viên và bột trong Đông y). | Mở khoá kiến thức | Biết 丸 mở khoá: 丸药 (thuốc hoàn), 定心丸 (thuốc an thần/điều gì yên lòng), 弹丸 (viên đạn).", "Tự nguyên_Xie": "Đại triện | Tiểu triện | Chữ 丸 là chữ hội ý phân hóa từ 夗 (người nằm cuộn tròn). Theo Shuowen: đây là chữ hội ý từ 仄 (lệch, nghiêng) lật ngược — vật có thể lật và lăn, tức vật hình tròn. Wiktionary lưu ý chữ này không liên quan đến thành phần bên phải của 執 hay 孰. Đại triện và tiểu triện được lưu tại wikimedia. Hán-Việt đọc là Hoàn. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "608.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Cửu (005) Chủ (607)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Cửu (số 005 - số 9) và nét chấm (Chủ - 607). Giải thích sự chuyển ý: Đây là chữ Hội ý. Lớn tròn trịa như 9 cộng 1 là 10. Hoàn là vật tròn trịa. Cũng có nghĩa là sự thẳng thắn (đến 9 cộng 1 là 10).", "Nghĩa Tiếng Việt_Xie": "viên, vật nhỏ và tròn", "Hạng Tần Suất (Jun Da)": "2457.0", "Tần Suất % (Jun Da)": "98.4035323752", "GavinGrover_Once (Chiết tự trực tiếp)": "九 + 丶", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴九丶", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "九", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "丶", "Unihan_Simplified (Chữ Giản thể)": "丸", "Unihan_Traditional (Chữ Phồn thể)": "丸", "Pinyin_Xie": "wán", "Âm Hán Việt_Xie": "hoàn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Lượng từ | 量词 | Thường làm danh từ chỉ viên thuốc hoặc làm lượng từ cho các vật nhỏ hình tròn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Lượng từ | 量词 | Đứng giữa số từ (hoặc 这/那) và danh từ: 一杯茶, 这本书. Mỗi danh từ đi với lượng từ riêng; 个 là lượng từ dùng chung phổ biến nhất.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | wán | / | viên thuốc | Xuất hiện trong lộ trình | HSK | HSK 6 | · | Sức khỏe II | New HSK | New HSK 7-9 | · | Từ chức năng và phụ từ II", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('斩', '{"9000": "2458.0", "Chữ Trung Quốc": "斩", "Bộ thủ & thành phần_Xie": "Bộ thủ | 車 | Số nét | 8 | nét | 车 | xa | biểu nghĩa | xe | 斤 | cân | biểu nghĩa | cái rìu | 斩 = 车 (Xa) + 斤 (Cân – rìu); dạng giản thể của 斬. Chữ gốc 斬 gồm 車 và 斤 — hội ý: dùng rìu (斤) chặt đứt như bánh xe (車) quay cắt. Theo Wiktionary, đây là dạng giản thể chỉ thay 車 thành 车.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trảm\": rìu (斤) bên cạnh xe (车) — hình ảnh vũ khí chém đứt đầu xe; 斩草除根 là nhổ cỏ tận gốc (trảm cỏ trừ rễ), 斩钉截铁 là quyết đoán như chém đinh. | Gương Hán-Việt | Trảm xuất hiện trong \"trảm quyết\" (hình phạt chém đầu), 斩草除根 (trảm thảo trừ căn – diệt tận gốc). | Mở khoá kiến thức | Biết 斩 mở khoá: 斩钉截铁 (quyết đoán dứt khoát), 斩草除根 (diệt tận gốc), 斩首 (chém đầu).", "Tự nguyên_Xie": "Đại triện | Tiểu triện | Chữ 斩 là dạng giản thể của 斬 (phồn thể). Chữ gốc 斬 gồm 車 (xe) và 斤 (rìu) — có thể là hội ý: dùng rìu (斤) chém đứt nhanh như bánh xe quay. Nghĩa là chém, chặt; ngày xưa chỉ hình phạt chém đầu. Đại triện và tiểu triện được lưu tại wikimedia. Hán-Việt đọc là Trảm — cùng gốc với \"trảm quyết\" (chém đầu). | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chém, chặt", "Hạng Tần Suất (Jun Da)": "2458.0", "Tần Suất % (Jun Da)": "98.4055188973", "GavinGrover_Once (Chiết tự trực tiếp)": "车 + 斤", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰车斤", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "斤", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "车", "Unihan_Simplified (Chữ Giản thể)": "斩", "Unihan_Traditional (Chữ Phồn thể)": "斬", "Pinyin_Xie": "zhǎn", "Âm Hán Việt_Xie": "trảm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước tân ngữ để chỉ hành động chém giết hoặc cắt đứt. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | zhǎn | / | chặt | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Chiến tranh và cuộc đấu tranh II", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('堤', '{"9000": "2459.0", "Chữ Trung Quốc": "堤", "Bộ thủ & thành phần_Xie": "Bộ thủ | 土 | Số nét | 12 | nét | 土 | thổ | biểu nghĩa | đất | 是 | thị | biểu âm | là, đúng | 堤 = 土 (Thổ, biểu nghĩa: đất) + 是 (Thị, biểu âm); chữ hình thanh. Bộ 土 chỉ công trình đắp bằng đất, 是 (thị) cho âm dī. Nghĩa là đê điều — con đê ngăn lũ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đê\": đất (土) đắp đúng chỗ (是) thành con đê — 堤 là đê, bờ đê; 堤坝 là hệ thống đê đập ngăn lũ. | Gương Hán-Việt | Đê xuất hiện trong 堤坝 (đê bá – đê đập), 河堤 (hà đê – bờ đê sông), 防洪堤 (đê phòng lũ). | Mở khoá kiến thức | Biết 堤 mở khoá: 堤坝 (đê đập), 河堤 (bờ đê sông), 防洪堤 (đê phòng lũ), 决堤 (vỡ đê).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Chữ 堤 là chữ hình thanh: bộ 土 (thổ – đất) biểu nghĩa công trình đất đắp ngăn nước, bộ 是 (thị) biểu âm. Tiểu triện và Lục thư thông được lưu tại hanziyuan. Hán-Việt đọc là Đê — cùng gốc với \"đê\" trong tiếng Việt (con đê ngăn lũ). Wiktionary ghi nhận nhiều cách đọc địa phương khác nhau. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con đê ngăn nước", "Hạng Tần Suất (Jun Da)": "2459.0", "Tần Suất % (Jun Da)": "98.4075033522", "GavinGrover_Once (Chiết tự trực tiếp)": "土 + 是", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰土是", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "是", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "土", "Unihan_Simplified (Chữ Giản thể)": "堤", "Unihan_Traditional (Chữ Phồn thể)": "堤", "Pinyin_Xie": "dī", "Âm Hán Việt_Xie": "đê", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ làm chủ ngữ hoặc tân ngữ trong câu để chỉ công trình ngăn nước. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | dī | / | đê | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Вuildings và công trình xây dựng", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('塌', '{"9000": "2460.0", "Chữ Trung Quốc": "塌", "Bộ thủ & thành phần_Xie": "Bộ thủ | 土 | Số nét | 13 | nét | 土 | thổ | biểu nghĩa | đất | 𦐇 | biểu âm | thành phần biểu âm (日 + 羽) | 塌 = 土 (Thổ, biểu nghĩa: đất) + 𦐇 (biểu âm, gồm 日 và 羽); chữ hình thanh. Bộ 土 chỉ đất sụp xuống, 𦐇 cho âm tā. Nghĩa gốc là đất trũng, sụp đổ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tháp\": đất (土) ngã lụp xuống — 塌 là sụp đổ; 倒塌 là đổ sụp; thành ngữ 一塌糊涂 là hỏng bét hoàn toàn, như đất sụp không cứu được. | Gương Hán-Việt | Tháp xuất hiện trong 倒塌 (đảo tháp – đổ sụp), 坍塌 (thản tháp – sụt lở), 一塌糊涂 (lộn xộn hết sức). | Mở khoá kiến thức | Biết 塌 mở khoá: 倒塌 (đổ sụp), 坍塌 (sụt lở), 一塌糊涂 (hỏng bét hoàn toàn), 死心塌地 (quyết tâm).", "Tự nguyên_Xie": "Chữ 塌 là chữ hình thanh: bộ 土 (thổ – đất) biểu nghĩa đất sụp, sụt lún; bộ 𦐇 (gồm 日 và 羽) biểu âm. Nghĩa là sụp đổ, đổ xuống, lún sâu. Tiểu triện được lưu tại wikimedia. Hán-Việt đọc là Tháp — cùng gốc với từ \"sụp tháp\" gợi hình ảnh đổ vỡ. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đất trũng", "Hạng Tần Suất (Jun Da)": "2460.0", "Tần Suất % (Jun Da)": "98.4094872903", "GavinGrover_Once (Chiết tự trực tiếp)": "土 + 𦐇", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰土𦐇", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "𦐇", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "土", "Unihan_Simplified (Chữ Giản thể)": "塌", "Unihan_Traditional (Chữ Phồn thể)": "塌", "Pinyin_Xie": "tā", "Âm Hán Việt_Xie": "tháp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Thường làm động từ chỉ sự sụp đổ của công trình hoặc làm tính từ chỉ trạng thái lõm xuống. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | tā | / | sụp đổ | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Thiên tai | HSK | HSK 6 | · | Xây dựng và cải tạo", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('贩', '{"9000": "2461.0", "Chữ Trung Quốc": "贩", "Bộ thủ & thành phần_Xie": "Bộ thủ | 貝 | Số nét | 8 | nét | 贝 | bối | biểu nghĩa | vỏ sò, tiền tệ (xưa dùng làm tiền) | 反 | phản | biểu âm | ngược lại, trái lại | 贩 = 贝 (Bối, biểu nghĩa: tiền/giao thương) + 反 (Phản, biểu âm); dạng giản thể của 販. Bộ 贝 chỉ hoạt động thương mại dùng tiền, 反 (phản) cho âm fàn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phiến\": tiền tệ (贝) lật ngược (反) qua tay — 贩 là người buôn bán hàng rong; 小贩 là tiểu thương, 贩卖 là buôn bán. | Gương Hán-Việt | Phiến xuất hiện trong 贩卖 (phiến mại – buôn bán), 小贩 (tiểu phiến – tiểu thương), 商贩 (thương phiến – người buôn bán). | Mở khoá kiến thức | Biết 贩 mở khoá: 贩卖 (buôn bán), 小贩 (hàng rong), 商贩 (tiểu thương), 贩毒 (buôn ma tuý).", "Tự nguyên_Xie": "Tiểu triện | Chữ 贩 là dạng giản thể của 販 (phồn thể). Cấu trúc hình thanh: bộ 貝 (bối – tiền, của cải) biểu nghĩa hoạt động mua bán, bộ 反 (phản) biểu âm. Nghĩa là mua rẻ bán đắt — loại buôn bán nhỏ lẻ, bán hàng rong. Tiểu triện được lưu tại wikimedia. Hán-Việt đọc là Phiến. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mua rẻ bán đắt; buôn bán", "Hạng Tần Suất (Jun Da)": "2461.0", "Tần Suất % (Jun Da)": "98.4114701949", "GavinGrover_Once (Chiết tự trực tiếp)": "贝 + 反", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰贝反", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "反", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "贝", "Unihan_Simplified (Chữ Giản thể)": "贩", "Unihan_Traditional (Chữ Phồn thể)": "販", "Pinyin_Xie": "fàn", "Âm Hán Việt_Xie": "phiến, phán", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường làm động từ chỉ hoạt động thương mại hoặc kết hợp thành danh từ chỉ người buôn bán. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('厢', '{"9000": "2462.0", "Chữ Trung Quốc": "厢", "Bộ thủ & thành phần_Xie": "Bộ thủ | 厂 | Số nét | 11 | nét | 厂 | hán | biểu nghĩa | vách núi/mái che bên | 相 | tương | biểu âm | lẫn nhau (gần âm xiāng) | 厢 là dạng giản thể của 廂 — hình thanh: 厂/广 (mái che bên, biểu nghĩa) + 相 (Tương, biểu âm). Phòng phụ bên cạnh nhà chính, gốc nghĩa ''phòng bên, gian bên''.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sương\": 厂 (mái che) + 相 (Tương) — gian phụ bên cạnh, đúng nghĩa ''gian bên, toa, phòng'' trong 车厢 (toa tàu). | Gương Hán-Việt | ''sương'' trong ''sương lầu'' (chái nhà bên) — ít gặp trong tiếng Việt | Mở khoá kiến thức | Nắm 厢 mở khoá từ HSK 5: 车厢.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 厢 (phồn 廂) là hình thanh: 厂 hoặc 广 (mái che, biểu nghĩa) + 相 (Tương, biểu âm). Nghĩa gốc ''phòng phụ, gian bên cạnh nhà chính, chỗ ngồi bên trong rạp hát''. Mở rộng sang ''toa tàu, ngăn tàu'' (车厢) và ''khu vực gần thành phố''. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mái nhà", "Hạng Tần Suất (Jun Da)": "2462.0", "Tần Suất % (Jun Da)": "98.4134530995", "GavinGrover_Once (Chiết tự trực tiếp)": "厂 + 相", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴厂相", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "相", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "厂", "Unihan_Simplified (Chữ Giản thể)": "厢", "Unihan_Traditional (Chữ Phồn thể)": "廂", "Pinyin_Xie": "xiāng", "Âm Hán Việt_Xie": "sương", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ các gian phòng phụ hoặc toa tàu, toa xe. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('掀', '{"9000": "2463.0", "Chữ Trung Quốc": "掀", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 11 | nét | 扌 | thủ | biểu nghĩa | tay | 欣 | hân | biểu âm | vui mừng | 掀 = 扌 (Thủ, biểu nghĩa: tay) + 欣 (Hân, biểu âm); chữ hình thanh. Bộ 扌 chỉ hành động dùng tay nhấc lên, 欣 (hân) cho âm xiān.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hiên\": bàn tay (扌) vui mừng (欣) nhấc lên tấm màn — 掀 là nhấc lên, lật lên; 掀起 là nổi lên (làn sóng, phong trào). | Gương Hán-Việt | Hiên xuất hiện trong 掀起 (hiên khởi – nâng lên, dấy lên), 掀开 (hiên khai – lật mở). | Mở khoá kiến thức | Biết 掀 mở khoá: 掀起 (dấy lên, nổi lên), 掀翻 (lật đổ), 掀开 (mở ra, lật lên).", "Tự nguyên_Xie": "Tiểu triện | Chữ 掀 là chữ hình thanh: bộ 手 (thủ – tay, viết tắt thành 扌) biểu nghĩa hành động dùng tay nhấc lên, lật lên; bộ 欣 (hân) biểu âm. Nghĩa gốc là nhấc lên, lật lên (rèm cửa, vật che phủ); mở rộng sang nghĩa lật đổ, khuấy động. Tiểu triện được lưu tại hanziyuan. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "xốc lên, nhấc lên", "Hạng Tần Suất (Jun Da)": "2463.0", "Tần Suất % (Jun Da)": "98.4154329033", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 欣", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌欣", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "欣", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "掀", "Unihan_Traditional (Chữ Phồn thể)": "掀", "Pinyin_Xie": "xiān", "Âm Hán Việt_Xie": "hiên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ biểu thị hành động lật, vén hoặc làm dấy lên một phong trào. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | xiān | / | nhấc lên | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Từ III", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('喀', '{"9000": "2464.0", "Chữ Trung Quốc": "喀", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 12 | nét | 口 | khẩu | biểu nghĩa | miệng | 客 | khách | biểu âm | khách | 喀 = 口 (Khẩu, biểu nghĩa: miệng) + 客 (Khách, biểu âm); chữ hình thanh. Bộ 口 xác định là âm thanh miệng, 客 cho âm kā gần với ca.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ca\": Miệng (口) phát tiếng Khách (客) kā — âm Ca tượng thanh tiếng ho khạc, dùng phiên âm tên nước ngoài. | Gương Hán-Việt | ca trong phiên âm (喀 = kha/ca trong địa danh nước ngoài) | Mở khoá kiến thức | Biết 喀 mở khoá: 喀麦隆 (Cameroon), 喀布尔 (Kabul), 喀什 (Kashgar).", "Tự nguyên_Xie": "Theo Wiktionary, 喀 là chữ hình thanh: 口 (khẩu) biểu nghĩa, 客 biểu âm. Dùng chủ yếu làm từ tượng thanh (tiếng nôn, tiếng khạc) và làm ký tự phiên âm tên nước ngoài (喀麦隆 Cameroon, 喀布尔 Kabul). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tiếng nôn oẹ", "Hạng Tần Suất (Jun Da)": "2464.0", "Tần Suất % (Jun Da)": "98.4174121904", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 客", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口客", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "客", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "喀", "Unihan_Traditional (Chữ Phồn thể)": "喀", "Pinyin_Xie": "kā", "Âm Hán Việt_Xie": "ca", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Từ tượng thanh | 象声词 | Thường dùng làm từ tượng thanh mô tả tiếng ho hoặc tiếng nôn khan. | Từ tượng thanh | 象声词 | Mô phỏng âm thanh: 哗哗, 汪汪. Có thể làm định ngữ, trạng ngữ hoặc đứng độc lập.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('乖', '{"9000": "2465.0", "Chữ Trung Quốc": "乖", "Bộ thủ & thành phần_Xie": "Bộ thủ | 丿 | Số nét | 8 | nét | 千 | thiên | hình thể | nghìn, thành phần tạo hình | 北 | bắc | hình thể | phương bắc, thành phần tạo hình | 乖 không có ls code từ Wiktionary. Theo Từ Thận, chữ gốc kết hợp từ 𦫳 và 𠔁. Cấu trúc hiện tại ⿻千北 là tổ hợp hình thể. Không thể xác định rõ hình thanh hay hội ý từ dữ liệu có sẵn — khả năng là chữ tượng hình hoặc chỉ sự biến dạng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quai\": đứa bé ngoan (乖) — ngược với cái quái (怪) kỳ lạ. Nhớ: quai ~ quái mà bỏ tâm = ngoan. | Gương Hán-Việt | quai trong ''quái lạ'' — 乖 và 怪 cùng gốc âm, nhưng 乖 thiên về nghĩa ngoan | Mở khoá kiến thức | Biết 乖 mở khoá: 乖巧 (quai xảo – thông minh khéo léo), 乖乖 (quai quai – ngoan nào).", "Tự nguyên_Xie": "乖 theo Wiktionary: ''According to Xu Shen, 𦫳 together with 𠔁.'' Chữ gốc rất cổ, nghĩa ban đầu là ''ngược lại, trái chiều''. Theo thời gian phát triển nghĩa phản nghĩa: vừa có nghĩa ''ngoan ngoãn'' (thuận theo) vừa có nghĩa ''quái lạ, trái ngược'' (nghịch nghĩa). Cấu trúc 千+北 là dạng biến thể không còn phản ánh cấu tạo nguyên thủy. Chưa có nguồn học thuật đầy đủ về glyphOrigin. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1140.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thiên (123) Bắc (183)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Thiên (số 123 - nghìn) xen ở giữa chữ Bắc (số 183 - quay lưng). Ngàn lần ngoảnh lưng trái ngược nhau. Giải thích sự chuyển ý: Đây là chữ Hội ý. Quai nghĩa gốc là trái ngược. Nghĩa thường dùng hiện nay lại là ngoan ngoãn, vâng lời (đối với trẻ em).", "Nghĩa Tiếng Việt_Xie": "trái ngược; láu lỉnh", "Hạng Tần Suất (Jun Da)": "2465.0", "Tần Suất % (Jun Da)": "98.4193904439", "GavinGrover_Once (Chiết tự trực tiếp)": "千 + 北", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴千北", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "北", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "千", "Unihan_Simplified (Chữ Giản thể)": "乖", "Unihan_Traditional (Chữ Phồn thể)": "乖", "Pinyin_Xie": "guāi", "Âm Hán Việt_Xie": "quai", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường làm tính từ đứng sau động từ liên kết hoặc làm định ngữ bổ nghĩa cho danh từ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | Từ đơn | Từ vựng HSK 5: ngoan | / | guāi | / | ngoan | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Tính cách III | HSK | HSK 5 | · | Gia đình", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('谜', '{"9000": "2466.0", "Chữ Trung Quốc": "谜", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 11 | nét | 讠 | biểu nghĩa | lời nói (bộ ngôn giản thể) | 迷 | mê | biểu âm | lạc đường, mê hoặc | 谜 = 讠 (Ngôn giản thể, biểu nghĩa: lời nói) + 迷 (Mê, biểu âm); dạng giản thể của 謎. Bộ 讠 (言) chỉ câu đố là lời nói ẩn ý, 迷 (mê) cho cả âm mí và gợi ý khó đoán.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mê\": lời nói (讠) làm mê hoặc (迷) — 谜 là câu đố, điều bí ẩn; 谜语 là câu đố, 谜团 là điều bí ẩn chưa giải được. | Gương Hán-Việt | Mê xuất hiện trong 谜语 (mê ngữ – câu đố), 谜团 (mê đoàn – điều bí ẩn), 猜谜 (suy mê – đoán câu đố). | Mở khoá kiến thức | Biết 谜 mở khoá: 谜语 (câu đố), 谜团 (điều bí ẩn), 谜底 (đáp án câu đố), 猜谜 (đoán câu đố).", "Tự nguyên_Xie": "Tiểu triện | Chữ 谜 là dạng giản thể của 謎 (phồn thể). Cấu trúc hình thanh: bộ 言 (ngôn – lời nói, giản thể thành 讠) biểu nghĩa câu đố là lời nói có ý ẩn; bộ 迷 (mê) biểu âm. Tiểu triện được lưu tại wikimedia. Hán-Việt đọc là Mê — cùng âm với 迷, gợi ý sự mê hoặc, khó đoán. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "câu đố", "Hạng Tần Suất (Jun Da)": "2466.0", "Tần Suất % (Jun Da)": "98.4213686974", "GavinGrover_Once (Chiết tự trực tiếp)": "讠 + 迷", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰讠迷", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "迷", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "讠", "Unihan_Simplified (Chữ Giản thể)": "谜", "Unihan_Traditional (Chữ Phồn thể)": "謎", "Pinyin_Xie": "mí", "Âm Hán Việt_Xie": "mê", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ làm tân ngữ cho các động từ như đoán hoặc giải. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Bí mật", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('捏', '{"9000": "2467.0", "Chữ Trung Quốc": "捏", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 10 | nét | 扌 | thủ | biểu nghĩa | tay | 涅 | niết | biểu âm | đen đậm, nhuộm đen | 捏 = 扌 (Thủ, biểu nghĩa: tay) + 涅 rút gọn thành 圼 (Niết, biểu âm); chữ hình thanh. Bộ 扌 chỉ hành động dùng tay véo, nắn; 涅 (rút gọn thành phần) cho âm niē.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"niết\": bàn tay (扌) véo niết (涅) chặt — 捏 là véo, nắn; 捏造 là bịa đặt (nắn tạo ra điều không có), 捏一把汗 là toát mồ hôi lo lắng. | Gương Hán-Việt | Niết xuất hiện trong 捏造 (niết tạo – bịa đặt), 捏一把汗 (lo đến toát mồ hôi). | Mở khoá kiến thức | Biết 捏 mở khoá: 捏造 (bịa đặt), 捏合 (nắn lại, ghép lại), 捏一把汗 (lo lắng).", "Tự nguyên_Xie": "Chữ 捏 là chữ hình thanh: bộ 手 (thủ – tay, viết tắt thành 扌) biểu nghĩa hành động dùng ngón tay véo, bóp, nắn; bộ 涅 rút gọn (abb2=y) biểu âm. Nghĩa là véo, bóp bằng ngón tay; cũng có nghĩa là nặn, tạo hình (nặn đất sét). Hán-Việt đọc là Niết. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cấu, véo; nắm chặt", "Hạng Tần Suất (Jun Da)": "2467.0", "Tần Suất % (Jun Da)": "98.4233448837", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 圼", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌圼", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "圼", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "捏", "Unihan_Traditional (Chữ Phồn thể)": "捏", "Pinyin_Xie": "niē", "Âm Hán Việt_Xie": "niết", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ chỉ động tác dùng các ngón tay để giữ, nặn hoặc cấu véo. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | niē | / | véo | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Từ III | HSK | HSK 6 | · | Thể thao, giải trí, sở thích", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('阎', '{"9000": "2468.0", "Chữ Trung Quốc": "阎", "Bộ thủ & thành phần_Xie": "Bộ thủ | 門 | Số nét | 11 | nét | 门 | môn | biểu nghĩa | cổng, cửa | 臽 | hãm | biểu âm | hố bẫy | 阎 (phồn thể 閻) = 门/門 (Môn, biểu nghĩa: cổng làng) + 臽 (Hãm, biểu âm); chữ hình thanh. Bộ 门 xác định liên quan đến cổng/cửa làng, 臽 cho âm yán gần với diêm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"diêm\": cái Cổng (门) vào cõi tối — Diêm Vương là chúa tể đứng sau cánh cổng âm phủ. | Gương Hán-Việt | diêm trong \"Diêm Vương\", \"diêm phù\" — liên quan đến cõi âm | Mở khoá kiến thức | Biết 阎 mở khoá: 阎王 (Diêm Vương), 阎罗 (Diêm La Vương), họ Diêm.", "Tự nguyên_Xie": "Đại triện | Tiểu triện | Theo Wiktionary, 閻 có bộ 門 biểu nghĩa, phần còn lại biểu âm. Nghĩa gốc: cổng ngõ trong làng, phố trong ngõ hẻm. Chữ nổi tiếng qua 阎王 (Diêm Vương — vua cõi âm) và họ Diêm. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "âm phủ, địa ngục", "Hạng Tần Suất (Jun Da)": "2468.0", "Tần Suất % (Jun Da)": "98.4253205533", "GavinGrover_Once (Chiết tự trực tiếp)": "门 + 臽", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿵ (Bao quanh phía trên)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴门臽", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "臽", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "门", "Unihan_Simplified (Chữ Giản thể)": "阎", "Unihan_Traditional (Chữ Phồn thể)": "閻", "Pinyin_Xie": "yán", "Âm Hán Việt_Xie": "diêm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này thường làm danh từ để chỉ Diêm Vương hoặc dùng làm họ của người. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('滨', '{"9000": "2469.0", "Chữ Trung Quốc": "滨", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 13 | nét | 氵 | thuỷ | biểu nghĩa | nước | 宾 | tân | biểu âm | khách | 滨 = 氵 (Thuỷ, biểu nghĩa: nước) + 宾 (Tân, biểu âm); dạng giản thể của 濱. Bộ 氵 chỉ bờ nước, ven sông biển; 宾 (tân) cho âm bīn. Cả bộ biểu âm và biểu nghĩa đều đọc Tân.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tân\": nước (氵) đón khách (宾) tại bến bờ — 滨 là bờ nước; 海滨 là bờ biển, nơi đón gió sóng như đón khách phương xa. | Gương Hán-Việt | Tân xuất hiện trong 海滨 (hải tân – bờ biển), 滨海 (tân hải – giáp biển). | Mở khoá kiến thức | Biết 滨 mở khoá: 海滨 (bờ biển), 湖滨 (bờ hồ), 滨海 (ven biển), tên địa danh như 哈尔滨 (Cáp Nhĩ Tân).", "Tự nguyên_Xie": "Chữ 滨 là dạng giản thể của 濱 (phồn thể). Cấu trúc hình thanh: bộ 水 (thuỷ – nước, viết tắt thành 氵) biểu nghĩa bờ nước; bộ 賓 (tân, giản thể thành 宾) biểu âm. Hán-Việt đọc là Tân — cùng âm với 宾 (tân – khách). Nghĩa là bờ sông, bờ biển, ven nước. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bờ, bến nước; gần, ven", "Hạng Tần Suất (Jun Da)": "2469.0", "Tần Suất % (Jun Da)": "98.4272900214", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 宾", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵宾", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "宾", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "滨", "Unihan_Traditional (Chữ Phồn thể)": "濱", "Pinyin_Xie": "bīn", "Âm Hán Việt_Xie": "tân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường làm danh từ chỉ bờ nước hoặc kết hợp làm tên địa danh ven biển. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('虏', '{"9000": "2470.0", "Chữ Trung Quốc": "虏", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虍 | Số nét | 8 | nét | 虍 | hô | biểu nghĩa | đầu hổ (bộ hổ) | 力 | lực | biểu âm | sức mạnh | 虏 = 虍 (Hô, biểu nghĩa: bộ hổ) + 力 (Lực, biểu âm); dạng giản thể của 虜 (phồn thể có 男). Bộ 虍 (đầu hổ) gợi ý kẻ thù hung dữ bị bắt; chữ gốc 虜 gồm 虍 + 男 (người đàn ông bị bắt làm nô lệ).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lỗ\": đầu hổ (虍) vượt qua sức mạnh (力) của kẻ thù để bắt tù — 虏 là tù binh; 俘虏 là bắt sống (俘) làm tù binh (虏). | Gương Hán-Việt | Lỗ xuất hiện trong 俘虏 (phù lỗ – bắt làm tù binh), 北虏 (cách gọi cũ của các tộc người phương Bắc). | Mở khoá kiến thức | Biết 虏 mở khoá: 俘虏 (tù binh), 掳掠 (cướp bóc), 虏获 (bắt được).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Chữ 虏 là dạng giản thể của 虜 (phồn thể). Chữ gốc 虜 gồm 虍 (hô – bộ hổ, chỉ kẻ địch hung dữ) và 男 (nam – đàn ông bị bắt). Dạng giản thể thay 男 bằng 力. Nghĩa là bắt tù binh; người bị bắt làm tù binh. Tiểu triện và Lục thư thông được lưu tại hanziyuan. Hán-Việt đọc là Lỗ. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "giặc giã; tù binh", "Hạng Tần Suất (Jun Da)": "2470.0", "Tần Suất % (Jun Da)": "98.4292594896", "GavinGrover_Once (Chiết tự trực tiếp)": "虍 + 力", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴虍力", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "力", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虍", "Unihan_Simplified (Chữ Giản thể)": "虏", "Unihan_Traditional (Chữ Phồn thể)": "虜", "Pinyin_Xie": "lǔ", "Âm Hán Việt_Xie": "lỗ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường làm động từ chỉ việc bắt giữ hoặc làm danh từ chỉ tù binh. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('匙', '{"9000": "2471.0", "Chữ Trung Quốc": "匙", "Bộ thủ & thành phần_Xie": "Bộ thủ | 匕 | Số nét | 11 | nét | 是 | thị | biểu âm | gợi âm chí/shi | 匕 | chuỷ | biểu nghĩa | cái muỗng | 匙 = 是 (Thị, biểu âm) + 匕 (Chuỷ, biểu nghĩa: cái muỗng); chữ hình thanh (ls=psc). 匕 vốn là hình ảnh cái thìa/muỗng cổ — gợi nghĩa rõ ràng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thi\" (cũng đọc ''chuỷ''): 是 (thị) + 匕 (muỗng cổ) — thị muỗng tức là ''thìa''; nhớ 钥匙 (chìa khoá), 汤匙 (thang thi = thìa canh). | Gương Hán-Việt | ''thi'' theo Hán-Việt; trong tiếng Việt thông dụng dịch là ''thìa, muỗng'' | Mở khoá kiến thức | Biết 匙 là mở 钥匙, 汤匙 — nhóm danh từ về dụng cụ ăn uống và chìa khoá HSK 4-6.", "Tự nguyên_Xie": "Đại triện | Tiểu triện | Theo Wiktionary, 匙 là chữ hình thanh: 匕 (biểu nghĩa: cái muỗng, hình ảnh muỗng cổ) ghép với 是 (biểu âm). Hai âm: chí (cái thìa) và shi (trong từ 钥匙 yàoshi = chìa khoá; do liên tưởng đến chìa khoá nhỏ giống muỗng). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái thìa", "Hạng Tần Suất (Jun Da)": "2471.0", "Tần Suất % (Jun Da)": "98.4312279242", "GavinGrover_Once (Chiết tự trực tiếp)": "是 + 匕", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴是匕", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "是", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "匕", "Unihan_Simplified (Chữ Giản thể)": "匙", "Unihan_Traditional (Chữ Phồn thể)": "匙", "Pinyin_Xie": "shi", "Âm Hán Việt_Xie": "thi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng sau danh từ khác để cấu tạo từ chỉ cái thìa hoặc chìa khóa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('芦', '{"9000": "2472.0", "Chữ Trung Quốc": "芦", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 7 | nét | 艹 | thảo | biểu nghĩa | cỏ, thực vật | 户 | hộ | biểu âm | hộ gia đình, cửa | 芦 = 艹 (Thảo, biểu nghĩa: thực vật) + 户 (Hộ, biểu âm); chữ hình thanh. Bộ 艹 xác định đây là loài thực vật, 户 cho âm lú gần với lô.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lô\": bụi Cỏ (艹) mọc quanh Hộ (户) nhà ven sông — cây Lô lau mọc ven bờ nước, thân thẳng rỗng. | Gương Hán-Việt | lô trong \"lô hội\", \"lô diên\" — cây lau, sậy mọc ven nước | Mở khoá kiến thức | Biết 芦 mở khoá: 芦花 (hoa lau), 芦苇 (cây lau sậy), 糖葫芦 (kẹo hồ lô).", "Tự nguyên_Xie": "Đại triện | Tiểu triện | Theo Wiktionary, 芦 là chữ hình thanh: 艸/艹 (thảo) biểu nghĩa, 户 biểu âm. Nghĩa: cây lau, sậy — loại cây mọc ven sông hồ, thân rỗng, dùng làm nhạc cụ (tiêu, sáo). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cây lau", "Hạng Tần Suất (Jun Da)": "2472.0", "Tần Suất % (Jun Da)": "98.4331948084", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 户", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹户", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "户", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "芦", "Unihan_Traditional (Chữ Phồn thể)": "蘆", "Pinyin_Xie": "lú", "Âm Hán Việt_Xie": "lô", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng trước danh từ khác để chỉ các loại cây thuộc họ lau sậy. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('苹', '{"9000": "2473.0", "Chữ Trung Quốc": "苹", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 8 | nét | 艹 | thảo | biểu nghĩa | cây cỏ (艸) | 平 | bình | biểu âm | bằng phẳng (gợi âm) | 苹 = 艹(艸, Thảo, biểu nghĩa: cây cỏ) + 平 (Bình, biểu âm); chữ hình thanh. Bộ Thảo cho biết là loài thực vật, 平 gợi âm; nay chủ yếu dùng trong 苹果 (táo).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bình\": Bình (苹) có bộ Thảo 艹(cây cỏ): loài cây; ngày nay quen thuộc nhất trong 苹果 — quả táo. | Gương Hán-Việt | ''bình'' trong ''bình'' (cây tần, bèo); cùng âm với 平 (bình: bằng phẳng). | Mở khoá kiến thức | Biết 苹 (bình) giúp nhận ra bộ Thảo 艹 và liên hệ thanh phù 平.", "Tự nguyên_Xie": "Theo Wiktionary, 苹 là chữ hình thanh: 艸 (艹, cây cỏ) làm nghĩa phù, 平 (bình) làm thanh phù. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cây rau tần; bèo tấm", "Hạng Tần Suất (Jun Da)": "2473.0", "Tần Suất % (Jun Da)": "98.4351611758", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 平", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹平", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "平", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "苹", "Unihan_Traditional (Chữ Phồn thể)": "苹", "Pinyin_Xie": "píng", "Âm Hán Việt_Xie": "bình", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ ghép để chỉ quả táo hoặc các loại thực vật thủy sinh. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('卸', '{"9000": "2474.0", "Chữ Trung Quốc": "卸", "Bộ thủ & thành phần_Xie": "Bộ thủ | 卩 | Số nét | 9 | nét | 卩 | tiết | biểu nghĩa | quỳ gối, cúi xuống | 卸 là chữ phức tạp: theo Wiktionary, đây là dạng lược bỏ 彳 từ 御. Bộ 卩 (tiết – quỳ) gợi ý hành động cúi xuống tháo dỡ. Phần 𦈢 không có Hán-Việt riêng. Cấu trúc tổng thể không rõ ràng là hình thanh hay hội ý.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tá\": quỳ xuống (卩) tháo dỡ — 卸 là dỡ hàng, tháo ra; 装卸 là bốc dỡ, 推卸 là đổ trách nhiệm cho người khác. | Gương Hán-Việt | Tá xuất hiện trong 装卸 (trang tá – bốc dỡ hàng), 推卸 (thôi tá – đổ trách nhiệm). | Mở khoá kiến thức | Biết 卸 mở khoá: 装卸 (bốc dỡ), 推卸 (đổ trách nhiệm), 卸任 (thôi chức), 卸妆 (tẩy trang).", "Tự nguyên_Xie": "Tiểu triện | Chữ 卸 là dạng lược bỏ bộ 彳 từ 御 theo Wiktionary. Âm ngữ 午 (ngọ) vẫn cho âm đọc. Nghĩa gốc là tháo xuống, dỡ hàng; mở rộng ra là từ chức, thoái nhiệm, trốn tránh trách nhiệm (推卸). Tiểu triện được lưu tại hanziyuan. Hán-Việt đọc là Tá. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1483.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Tiết (290) Ngọ (192) Chỉ (231)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bao gồm chữ Ngọ (số 192 - con ngựa/ 午) nằm giữa bộ Tiết (số 290 - đốt tre/ 卩) và bộ Chỉ (số 231 - dừng lại/ 止). Di chuyển bằng ngựa trên đường thì phải chia ra thành từng cung đoạn (Tiết) để dừng ngựa (Chỉ) và tháo ngựa ra khỏi xe nghỉ ngơi. Giải thích sự chuyển ý: Đây là chữ Hội ý. Tá là tháo ra, cởi ra, dỡ hàng hóa trên xe ngựa xuống (tháo tá).", "Nghĩa Tiếng Việt_Xie": "tháo, cởi", "Hạng Tần Suất (Jun Da)": "2474.0", "Tần Suất % (Jun Da)": "98.4371223754", "GavinGrover_Once (Chiết tự trực tiếp)": "𦈢 + 卩", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰𦈢卩", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "𦈢", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "卩", "Unihan_Simplified (Chữ Giản thể)": "卸", "Unihan_Traditional (Chữ Phồn thể)": "卸", "Pinyin_Xie": "xiè", "Âm Hán Việt_Xie": "tá", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước danh từ chỉ hàng hóa, trách nhiệm hoặc trang phục. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | xiè | / | dỡ hàng | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Phong trào II", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('沼', '{"9000": "2475.0", "Chữ Trung Quốc": "沼", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 8 | nét | 氵 | thuỷ | biểu nghĩa | nước | 召 | thiệu | biểu âm | triệu tập, gọi tên | 沼 = 氵 (Thuỷ, biểu nghĩa: nước) + 召 (Thiệu, biểu âm); chữ hình thanh. Bộ 氵 chỉ vùng nước đọng, 召 (thiệu/chiếu) cho âm zhǎo.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chiểu\": nước (氵) gọi tụ lại (召) thành cái ao — 沼 là chiểu, ao hồ; 沼泽 là đầm lầy, vùng nước đọng lầy lội. | Gương Hán-Việt | Chiểu xuất hiện trong \"ao chiểu\" (沼池), 沼泽 (chiểu trạch – đầm lầy). | Mở khoá kiến thức | Biết 沼 mở khoá: 沼泽 (đầm lầy), 沼气 (khí biogas), 湖沼 (hồ đầm).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Chữ 沼 là chữ hình thanh: bộ 水 (thuỷ – nước, viết tắt thành 氵) biểu nghĩa vùng nước đọng, ao hồ; bộ 召 (thiệu/chiếu) biểu âm. Nghĩa là ao, đầm, hồ nhỏ. Tiểu triện và Lục thư thông được lưu tại hanziyuan. Hán-Việt đọc là Chiểu — cùng gốc với \"ao chiểu\" trong thơ cổ Việt Nam. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái ao hình cong", "Hạng Tần Suất (Jun Da)": "2475.0", "Tần Suất % (Jun Da)": "98.4390815079", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 召", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵召", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "召", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "沼", "Unihan_Traditional (Chữ Phồn thể)": "沼", "Pinyin_Xie": "zhǎo", "Âm Hán Việt_Xie": "chiểu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ ghép để chỉ đầm lầy hoặc các loại khí sinh học. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('钥', '{"9000": "2476.0", "Chữ Trung Quốc": "钥", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 9 | nét | 钅 | kim | biểu nghĩa | kim loại | 月 | nguyệt | biểu âm | giản hoá từ 龠, gợi âm yào | 钥 là giản thể của 鑰. 鑰 = 釒 + 龠 (psc). Bản giản thể rút 釒 thành 钅 và 龠 thành 月. Chữ hình thanh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thược\": kim loại 钅 hình mảnh trăng 月 — chiếc chìa khoá nhỏ, đó là ''thược'' (chìa khoá). | Gương Hán-Việt | thược trong \"thược thi\" 鑰匙 | Mở khoá kiến thức | Biết 钥 mở khoá khái niệm chìa khoá: 钥匙.", "Tự nguyên_Xie": "Wiktionary chú 鑰 giản thể là 钥, ghép 金/钅 (kim loại) với 月 (rút gọn của 龠, biểu âm). Nghĩa: chìa khoá, ổ khoá. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái khoá", "Hạng Tần Suất (Jun Da)": "2476.0", "Tần Suất % (Jun Da)": "98.4410308214", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 月", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅月", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "月", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "钥", "Unihan_Traditional (Chữ Phồn thể)": "鑰", "Pinyin_Xie": "yào", "Âm Hán Việt_Xie": "thược", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ ghép để chỉ chìa khóa hoặc ẩn dụ cho yếu tố mấu chốt. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('株', '{"9000": "2477.0", "Chữ Trung Quốc": "株", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 10 | nét | 木 | mộc | biểu nghĩa | gỗ, cây | 朱 | chu | biểu âm | đỏ thắm, chu sa | 株 = 木 (Mộc, biểu nghĩa: cây/gỗ) + 朱 (Chu, biểu âm); chữ hình thanh. Bộ 木 chỉ gốc cây, cây, 朱 (chu) cho âm zhū.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chu\": cây gỗ (木) đỏ như chu sa (朱) — 株 là gốc cây, cây; thành ngữ 守株待兔 là \"thủ chu đãi thố\" — ngồi đợi thỏ ở gốc cây, tức làm biếng chờ may mắn. | Gương Hán-Việt | Chu xuất hiện trong 守株待兔 (thủ chu đãi thố – ngồi chờ), 一株 (nhất chu – một cây). | Mở khoá kiến thức | Biết 株 mở khoá: 守株待兔 (chờ đợi vô ích), 株连 (liên lụy), lượng từ đếm cây.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Chữ 株 là chữ hình thanh: bộ 木 (mộc – gỗ/cây) biểu nghĩa gốc cây, cây đứng; bộ 朱 (chu) biểu âm. Nghĩa gốc là gốc cây (phần dưới sát đất); mở rộng ra dùng làm lượng từ đếm cây (一株树 – một cây). Tiểu triện và Lục thư thông được lưu tại hanziyuan. Hán-Việt đọc là Chu — cùng âm với 朱. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "894.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Mộc (075) Chu (893)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Mộc (số 075 - cây gỗ) ở bên trái chữ Chu (số 893 - màu đỏ/chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Chu chỉ âm, bộ Mộc chỉ ý. Chu là gốc cây (thủ chu đãi thố).", "Nghĩa Tiếng Việt_Xie": "gốc cây; gốc (chữ dùng để đếm cây)", "Hạng Tần Suất (Jun Da)": "2477.0", "Tần Suất % (Jun Da)": "98.4429796181", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 朱", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木朱", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "朱", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "株", "Unihan_Traditional (Chữ Phồn thể)": "株", "Pinyin_Xie": "zhū", "Âm Hán Việt_Xie": "châu, chu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Lượng từ | 量词 | Danh từ | 名词 | Thường làm lượng từ đứng trước danh từ chỉ cây cối hoặc làm danh từ chỉ gốc cây. | Lượng từ | 量词 | Đứng giữa số từ (hoặc 这/那) và danh từ: 一杯茶, 这本书. Mỗi danh từ đi với lượng từ riêng; 个 là lượng từ dùng chung phổ biến nhất. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | zhū | / | cây | Xuất hiện trong lộ trình | HSK | HSK 6 | · | Sinh học | New HSK | New HSK 7-9 | · | Thực vật", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('祷', '{"9000": "2478.0", "Chữ Trung Quốc": "祷", "Bộ thủ & thành phần_Xie": "Bộ thủ | 示 | Số nét | 11 | nét | 礻 | thị | biểu nghĩa | bàn thờ, thần linh | 寿 | thọ | biểu âm | tuổi thọ | 祷 (phồn thể 禱) = 礻/示 (Thị, biểu nghĩa: bàn thờ) + 壽/寿 (Thọ, biểu âm); chữ hình thanh. Bộ 礻 xác định liên quan đến lễ tế thần, 寿 cho âm dǎo gần với đảo.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đảo\": trước bàn Thờ (礻) cầu Thọ (寿) — Đảo cầu là cúi đầu trước thần linh xin sống lâu, bình an. | Gương Hán-Việt | đảo trong \"cầu đảo\", \"đảo từ\" — khẩn cầu, lời cầu nguyện | Mở khoá kiến thức | Biết 祷 mở khoá: 祈祷 (cầu nguyện), 祷告 (cầu xin), 祷文 (lời cầu nguyện).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Wiktionary ghi 祷 là giản thể của 禱 (示 + 壽). Cấu trúc hình thanh: 示 biểu nghĩa chỉ lễ nghi thần linh, 壽 biểu âm. Nghĩa: cầu cúng, cầu xin thần linh ban phước lành hoặc cầu nguyện. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cầu cúng", "Hạng Tần Suất (Jun Da)": "2478.0", "Tần Suất % (Jun Da)": "98.4449273813", "GavinGrover_Once (Chiết tự trực tiếp)": "礻 + 寿", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰礻寿", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "寿", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "礻", "Unihan_Simplified (Chữ Giản thể)": "祷", "Unihan_Traditional (Chữ Phồn thể)": "禱", "Pinyin_Xie": "dǎo", "Âm Hán Việt_Xie": "đảo", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước tân ngữ hoặc kết hợp thành từ ghép chỉ sự cầu nguyện. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('剖', '{"9000": "2479.0", "Chữ Trung Quốc": "剖", "Bộ thủ & thành phần_Xie": "Bộ thủ | 刀 | Số nét | 10 | nét | 咅 | phủ | biểu âm | mở miệng, nhả ra | 刂 | đao | biểu nghĩa | dao (bộ đao bên phải) | 剖 = 咅 (Phủ, biểu âm) + 刂 (Đao, biểu nghĩa: dao); chữ hình thanh. Bộ 刂 chỉ hành động dùng dao cắt mổ, 咅 (phủ) cho âm pōu. Wiktionary giải thích: biểu đạt ý cắt hai đôi bằng dao.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phẫu\": dao (刂) mổ ra (咅 gợi ý mở ra) — 剖 là mổ, giải phẫu; 解剖 là giải phẫu, 剖析 là phân tích tỉ mỉ như mổ xẻ. | Gương Hán-Việt | Phẫu xuất hiện trong 解剖 (giải phẫu), 解剖学 (giải phẫu học), 剖析 (phân tích, mổ xẻ). | Mở khoá kiến thức | Biết 剖 mở khoá: 解剖 (giải phẫu), 剖析 (phân tích), 剖开 (cắt ra, mổ ra), 剖面 (mặt cắt).", "Tự nguyên_Xie": "Tiểu triện | Chữ 剖 là chữ hình thanh: bộ 刀 (đao – dao, viết thành 刂 ở bên phải) biểu nghĩa hành động dùng dao cắt, mổ; bộ 咅 (phủ) biểu âm. Theo Wiktionary (dẫn Digital Shinjigen 2017): biểu đạt ý cắt vật thành hai phần bằng dao. Tiểu triện được lưu tại hanziyuan. Hán-Việt đọc là Phẫu — cùng gốc với \"giải phẫu\" trong y học. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mổ, giải phẫu; trình bày rõ ràng", "Hạng Tần Suất (Jun Da)": "2479.0", "Tần Suất % (Jun Da)": "98.4468741109", "GavinGrover_Once (Chiết tự trực tiếp)": "咅 + 刂", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰咅刂", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "咅", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "刂", "Unihan_Simplified (Chữ Giản thể)": "剖", "Unihan_Traditional (Chữ Phồn thể)": "剖", "Pinyin_Xie": "pōu", "Âm Hán Việt_Xie": "phẫu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước tân ngữ để chỉ việc mổ xẻ y khoa hoặc phân tích vấn đề. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('熙', '{"9000": "2480.0", "Chữ Trung Quốc": "熙", "Bộ thủ & thành phần_Xie": "Bộ thủ | 火 | Số nét | 14 | nét | 巸 | biểu âm | thành phần âm (巸 = 𦣞 + 巳) | 灬 | hoả | biểu nghĩa | lửa (bốn chấm) | 熙 = 巸 (biểu âm) + 灬/火 (Hoả, biểu nghĩa: lửa, ánh sáng); chữ hình thanh. Bộ 灬 xác định liên quan đến lửa/ánh sáng, 巸 cho âm xī gần với hy.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hy\": Lửa (灬) cháy sáng rực — Hy vọng, thịnh Hưng; 熙 là ánh sáng của thời thái bình thịnh trị. | Gương Hán-Việt | hy trong \"Khang Hy\" (康熙 — triều đại nhà Thanh), \"hy vọng\" (chữ khác) | Mở khoá kiến thức | Biết 熙 mở khoá: 熙熙攘攘 (náo nhiệt đông đúc), 康熙 (niên hiệu vua Khang Hy).", "Tự nguyên_Xie": "Kim văn | Tiểu triện | Theo Wiktionary, 熙 là chữ hình thanh: 火/灬 (hoả) biểu nghĩa chỉ lửa/ánh sáng rực rỡ, 巸 biểu âm. Nghĩa: sáng rỡ, thịnh vượng, vui tươi — như ánh lửa rực sáng trong đêm. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sáng; thịnh vượng; thịnh hưng; vui vẻ", "Hạng Tần Suất (Jun Da)": "2480.0", "Tần Suất % (Jun Da)": "98.4488203237", "GavinGrover_Once (Chiết tự trực tiếp)": "巸 + 灬", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱巸灬", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "巸", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "灬", "Unihan_Simplified (Chữ Giản thể)": "熙", "Unihan_Traditional (Chữ Phồn thể)": "熈", "Pinyin_Xie": "xī", "Âm Hán Việt_Xie": "hi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Chữ này thường làm tính từ bổ nghĩa cho danh từ hoặc dùng trong tên người để chỉ sự thịnh vượng, tươi sáng. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('哗', '{"9000": "2481.0", "Chữ Trung Quốc": "哗", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 9 | nét | 口 | khẩu | biểu nghĩa | miệng, âm thanh | 华 | hoa | biểu âm | hoa lệ, Trung Hoa | 哗 = 口 (Khẩu, biểu nghĩa: miệng) + 华 (Hoa, biểu âm); dạng giản thể của 嘩 (hoặc 譁). Bộ 口 chỉ âm thanh ồn ào phát ra, 华 (hoa) cho âm huā/huá.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hoa\": miệng (口) hoa (华) lên huyên náo — 哗 là âm thanh ầm ĩ; 喧哗 là tiếng ồn ào náo nhiệt; 哗然 là cả đám nhôn nhao. | Gương Hán-Việt | Hoa xuất hiện trong 哗变 (hoa biến – binh biến), 喧哗 (huyên hoa – ồn ào), 哗然 (hoa nhiên – náo loạn). | Mở khoá kiến thức | Biết 哗 mở khoá: 喧哗 (ồn ào náo nhiệt), 哗变 (binh biến), 哗然 (náo loạn), 哗众取宠 (làm trò để lấy lòng).", "Tự nguyên_Xie": "Tiểu triện | Chữ 哗 là dạng giản thể của 嘩 (phồn thể, cũng viết 譁). Chữ gốc theo Wiktionary tra ngược lên 嘩: bộ 口 (khẩu) biểu nghĩa âm thanh ồn ào, bộ 華 (hoa) biểu âm. Nghĩa là ồn ào, huyên náo; cũng dùng trong 哗变 (binh biến – lính nổi loạn ồn ào). Tiểu triện được lưu tại hanziyuan. Hán-Việt đọc là Hoa. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ầm ĩ", "Hạng Tần Suất (Jun Da)": "2481.0", "Tần Suất % (Jun Da)": "98.450762919", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 华", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口华", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "华", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "哗", "Unihan_Traditional (Chữ Phồn thể)": "嘩", "Pinyin_Xie": "huā", "Âm Hán Việt_Xie": "hoa", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Từ tượng thanh | 象声词 | Thường dùng làm tính từ miêu tả âm thanh ồn ào hoặc làm từ tượng thanh mô phỏng tiếng nước chảy. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Từ tượng thanh | 象声词 | Mô phỏng âm thanh: 哗哗, 汪汪. Có thể làm định ngữ, trạng ngữ hoặc đứng độc lập.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('劈', '{"9000": "2482.0", "Chữ Trung Quốc": "劈", "Bộ thủ & thành phần_Xie": "Bộ thủ | 刀 | Số nét | 15 | nét | 辟 | tích | biểu âm | khai thác, mở ra | 刀 | đao | biểu nghĩa | dao | 劈 = 辟 (Tích, biểu âm) + 刀 (Đao, biểu nghĩa: dao); chữ hình thanh. Bộ 刀 chỉ hành động dùng dao chặt, bổ; 辟 (tích/pì) cho âm pī.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phách\": dao (刀) mở ra (辟) chẻ đôi — 劈 là bổ, chẻ; 劈柴 là chẻ củi; 晴天霹雳 là sét đánh giữa trời quang (chẻ trời). | Gương Hán-Việt | Phách xuất hiện trong 劈柴 (phách sài – chẻ củi), ít thấy trong từ Hán-Việt thông dụng; âm chữ chủ yếu dùng trong tiếng Trung. | Mở khoá kiến thức | Biết 劈 mở khoá: 劈柴 (chẻ củi), 劈开 (chẻ ra), 劈叉 (xoạc chân).", "Tự nguyên_Xie": "Tiểu triện | Chữ 劈 là chữ hình thanh: bộ 刀 (đao – dao) biểu nghĩa hành động dùng dao bổ chẻ; bộ 辟 (tích) biểu âm. Nghĩa là bổ, chẻ, chặt đứt. Tiểu triện được lưu tại hanziyuan. Hán-Việt đọc là Phách — gợi hình ảnh tiếng dao chặt bổ. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bổ, bửa ra", "Hạng Tần Suất (Jun Da)": "2482.0", "Tần Suất % (Jun Da)": "98.4527055144", "GavinGrover_Once (Chiết tự trực tiếp)": "辟 + 刀", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱辟刀", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "辟", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "刀", "Unihan_Simplified (Chữ Giản thể)": "劈", "Unihan_Traditional (Chữ Phồn thể)": "劈", "Pinyin_Xie": "pī", "Âm Hán Việt_Xie": "phách", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước danh từ chỉ vật bị tác động lực mạnh như củi hoặc sét đánh. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | pī | / | chẻ, bổ | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Nông nghiệp | HSK | HSK 6 | · | Động từ hàng ngày", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('怯', '{"9000": "2483.0", "Chữ Trung Quốc": "怯", "Bộ thủ & thành phần_Xie": "Bộ thủ | 心 | Số nét | 8 | nét | 忄 | tâm | biểu nghĩa | tim, cảm xúc | 去 | khứ | biểu âm | đi, rời đi | 怯 = 忄 (Tâm, biểu nghĩa: trái tim/cảm xúc) + 去 (Khứ, biểu âm); chữ hình thanh. Bộ 忄 chỉ trạng thái tâm lý sợ hãi, muốn bỏ chạy, 去 (khứ) cho âm qiè.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khiếp\": tim (忄) muốn bỏ đi (去) vì sợ — 怯 là nhút nhát, khiếp sợ; 胆怯 là đảm khiếp tức nhút nhát; 羞怯 là xấu hổ e thẹn. | Gương Hán-Việt | Khiếp xuất hiện trong \"khiếp sợ\" (怯懦 – nhút nhát), \"khiếp đảm\" (胆怯 – nhát gan). | Mở khoá kiến thức | Biết 怯 mở khoá: 胆怯 (nhút nhát), 羞怯 (e thẹn), 怯场 (sân khấu rụt rè), 畏怯 (sợ hãi).", "Tự nguyên_Xie": "Chữ 怯 là chữ hình thanh: bộ 心 (tâm – trái tim, viết tắt thành 忄) biểu nghĩa trạng thái tâm lý nhút nhát, sợ hãi; bộ 去 (khứ) biểu âm. Nghĩa là nhút nhát, hèn nhát; sợ sệt. Wiktionary ghi hậu duệ Hán-Việt trực tiếp là \"khiếp\". Hán-Việt đọc là Khiếp — cùng gốc với \"khiếp sợ\" trong tiếng Việt. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "e sợ, khiếp", "Hạng Tần Suất (Jun Da)": "2483.0", "Tần Suất % (Jun Da)": "98.4546481097", "GavinGrover_Once (Chiết tự trực tiếp)": "忄 + 去", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰忄去", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "去", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "忄", "Unihan_Simplified (Chữ Giản thể)": "怯", "Unihan_Traditional (Chữ Phồn thể)": "怯", "Pinyin_Xie": "qiè", "Âm Hán Việt_Xie": "khiếp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường làm tính từ đứng sau phó từ chỉ mức độ hoặc làm động từ biểu thị tâm lý e sợ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('棠', '{"9000": "2484.0", "Chữ Trung Quốc": "棠", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 12 | nét | 尚 | thượng | biểu âm | còn, vẫn còn, cao thượng | 木 | mộc | biểu nghĩa | cây | 棠 = 尚 (Thượng, biểu âm) + 木 (Mộc, biểu nghĩa: cây); chữ hình thanh. Bộ 木 xác định đây là loài cây, 尚 cho âm táng gần với đường.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đường\": cây Mộc (木) Thượng (尚) phẩm — cây Đường táo dại quý giá, gắn với điển tích thanh liêm của quan lại. | Gương Hán-Việt | đường trong \"hải đường\" (海棠 — hoa hải đường), \"cam đường\" (甘棠) | Mở khoá kiến thức | Biết 棠 mở khoá: 海棠 (hoa hải đường), 甘棠 (điển tích nhân chính), 棠棣 (anh em).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Theo Wiktionary, 棠 là chữ hình thanh: 木 biểu nghĩa, 尚 biểu âm. Nghĩa: cây táo dại, cây mận rừng — loại cây ăn quả hoang dã. Nổi tiếng qua điển tích 甘棠 (cam đường) — cây táo dại mà Thiệu Công ngồi xử kiện dưới bóng, dân kính trọng không dám chặt. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "476.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Mộc (108) Thượng (338)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Thượng (ưa chuộng, coi trọng) ở trên chữ Mộc (cây gỗ) . Cây (Mộc) hải đường nở hoa vô cùng rực rỡ, được người ta vô cùng yêu thích, ưa chuộng (Thượng). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Thượng (coi trọng) chỉ âm, chữ Mộc (cây cỏ) chỉ ý. Tên một loài cây (Mộc) có hoa rất đẹp gọi là hoa hải đường (Đường). *(Biến âm Hán Việt: Thượng -> Đường)*", "Nghĩa Tiếng Việt_Xie": "(xem: hải đường 海棠)", "Hạng Tần Suất (Jun Da)": "2484.0", "Tần Suất % (Jun Da)": "98.4565901882", "GavinGrover_Once (Chiết tự trực tiếp)": "龸 + 呆", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱龸呆", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "呆", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "龸", "Unihan_Simplified (Chữ Giản thể)": "棠", "Unihan_Traditional (Chữ Phồn thể)": "棠", "Pinyin_Xie": "táng", "Âm Hán Việt_Xie": "đường", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ ghép để chỉ các loại cây hoa thân gỗ như hải đường. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('胳', '{"9000": "2485.0", "Chữ Trung Quốc": "胳", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 10 | nét | 月 | nhục | biểu nghĩa | thịt — bộ phận cơ thể | 各 | các | biểu âm | phần biểu âm — gần âm ''cách/các'' | 胳 là chữ hình thanh (psc): 月 (⺼, thịt — biểu nghĩa: bộ phận cơ thể) + 各 (biểu âm). Tên một phần trên cơ thể — cẳng tay/dưới cánh tay. Thường ghép với 膊 thành 胳膊.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Cách\": phần thịt (月) trên từng người (各) — đó là ''cách'', cánh tay, cẳng tay. | Gương Hán-Việt | ''Cách'' (胳) thường đi với 膊 thành 胳膊 — cẳng tay. | Mở khoá kiến thức | Biết 胳 mở khoá 胳膊 (cách bác, cẳng tay), 胳肢窝 (cách chi oa, nách).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 胳 là chữ hình thanh gồm 肉 (月/⺼, thịt — biểu nghĩa: bộ phận cơ thể) + 各 (biểu âm). Nghĩa gốc ''cẳng tay, dưới cánh tay''. Thường dùng trong từ ghép 胳膊 (gē·bo) — cẳng tay, cánh tay nói chung. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cánh tay", "Hạng Tần Suất (Jun Da)": "2485.0", "Tần Suất % (Jun Da)": "98.4585296828", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 各", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月各", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "各", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "胳", "Unihan_Traditional (Chữ Phồn thể)": "肐", "Pinyin_Xie": "gē", "Âm Hán Việt_Xie": "cách", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường kết hợp với các từ khác để tạo thành danh từ chỉ bộ phận cơ thể như cánh tay hoặc nách. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('桩', '{"9000": "2486.0", "Chữ Trung Quốc": "桩", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 10 | nét | 木 | mộc | biểu nghĩa | cây, gỗ | 庄 | trang | biểu âm | trang trại, trang nghiêm | 桩 (phồn thể 樁) = 木 (Mộc, biểu nghĩa: gỗ) + 庄/莊 (Trang, biểu âm); chữ hình thanh. Bộ 木 xác định làm bằng gỗ, 庄 cho âm zhuāng gần với trang.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trang\": cây Gỗ (木) đóng Trang (庄) nghiêm xuống đất — cái cọc Trang đứng vững như nền móng. | Gương Hán-Việt | trang trong \"trang trại\", \"trang nghiêm\" — 桩 nghĩa cọc gỗ, không trực tiếp vào trang trại | Mở khoá kiến thức | Biết 桩 mở khoá: 打桩 (đóng cọc), 树桩 (gốc cây), 一桩事 (một vụ việc).", "Tự nguyên_Xie": "Tiểu triện | Wiktionary không có glyphOrigin chi tiết cho 樁. Dựa trên cấu trúc hình thanh: 木 biểu nghĩa, 莊/庄 biểu âm. Nghĩa: cọc gỗ đóng xuống đất — vật liệu xây dựng nền móng; cũng dùng làm lượng từ (một vụ việc, một vụ kiện). Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đánh đập; cái cọc", "Hạng Tần Suất (Jun Da)": "2486.0", "Tần Suất % (Jun Da)": "98.4604655599", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 庄", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木庄", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "庄", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "桩", "Unihan_Traditional (Chữ Phồn thể)": "樁", "Pinyin_Xie": "zhuāng", "Âm Hán Việt_Xie": "trang", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Lượng từ | 量词 | Thường dùng làm lượng từ cho các vụ việc, sự kiện hoặc làm danh từ chỉ cái cọc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Lượng từ | 量词 | Đứng giữa số từ (hoặc 这/那) và danh từ: 一杯茶, 这本书. Mỗi danh từ đi với lượng từ riêng; 个 là lượng từ dùng chung phổ biến nhất.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | zhuāng | / | cọc | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Xây dựng và cải tạo", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('瑰', '{"9000": "2487.0", "Chữ Trung Quốc": "瑰", "Bộ thủ & thành phần_Xie": "Bộ thủ | 玉 | Số nét | 13 | nét | 王 | vương | biểu nghĩa | ngọc (bộ 王 = biến thể của 玉) | 鬼 | quỷ | biểu âm | ma quỷ | 瑰 = 王/玉 (Vương/Ngọc, biểu nghĩa: ngọc) + 鬼 (Quỷ, biểu âm); chữ hình thanh. Bộ 𤣩/王 bên trái là biến thể của 玉 chỉ ngọc, 鬼 cho âm guī gần với khôi.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khôi\": bộ Ngọc (王/玉) ghép Quỷ (鬼) — viên đá Khôi kỳ lạ như vật quỷ dị, đẹp đến phi thường. | Gương Hán-Việt | khôi trong \"khôi ngô\" (to lớn oai nghiêm), \"khôi vĩ\" — phi thường, xuất sắc | Mở khoá kiến thức | Biết 瑰 mở khoá: 玫瑰 (hoa hồng), 瑰宝 (báu vật), 瑰丽 (huy hoàng tráng lệ).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Theo Wiktionary, 瑰 là chữ hình thanh: 𤣩 (玉, ngọc) biểu nghĩa, 鬼 biểu âm. Nghĩa gốc: loại đá bán quý kém ngọc; sau mở rộng thành kỳ diệu, phi thường. Nổi tiếng qua 玫瑰 (hoa hồng — tên phiên âm từ ngôn ngữ khác, dùng hai chữ ngọc đẹp). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "một loại đá đẹp; quý lạ", "Hạng Tần Suất (Jun Da)": "2487.0", "Tần Suất % (Jun Da)": "98.4624004035", "GavinGrover_Once (Chiết tự trực tiếp)": "王 + 鬼", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰王鬼", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "鬼", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "王", "Unihan_Simplified (Chữ Giản thể)": "瑰", "Unihan_Traditional (Chữ Phồn thể)": "瑰", "Pinyin_Xie": "guī", "Âm Hán Việt_Xie": "côi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Thường làm tính từ bổ nghĩa cho danh từ để chỉ sự quý giá, kỳ diệu hoặc ghép thành từ chỉ hoa hồng. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('娱', '{"9000": "2488.0", "Chữ Trung Quốc": "娱", "Bộ thủ & thành phần_Xie": "Bộ thủ | 女 | Số nét | 10 | nét | 女 | nữ | biểu nghĩa | người phụ nữ, liên quan đến người | 吴 | ngô | biểu âm | cho âm ngô/ngu | 娱 = 女 (Nữ, biểu nghĩa: người) + 吴 (Ngô, biểu âm); chữ hình thanh. Wiktionary không ghi lsCodes rõ nhưng cấu trúc 女+吴 điển hình cho hình thanh với 女 biểu nghĩa. Âm ngu (yú) gần với 吴 (ngô).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ngu\": bộ Nữ (女) + Ngô (吴) — cô gái họ Ngô mang lại niềm vui (娱乐 giải trí). Nhớ: ngu không phải ngốc mà là ngô nghê vui vẻ. | Gương Hán-Việt | ngu trong ''ngu xuẩn'' — âm đọc giống nhau, nhưng 娱 là vui chơi, không liên quan ngữ nghĩa | Mở khoá kiến thức | Biết 娱 mở khoá: 娱乐 (ngu lạc – giải trí), 自娱 (tự ngu – tự giải khuây).", "Tự nguyên_Xie": "娱 là chữ hình thanh: bộ 女 (nữ) biểu nghĩa, 吴 (ngô) biểu âm. Nghĩa gốc là ''mua vui, giải trí'' — trong xã hội cổ đại, hoạt động giải trí thường gắn với ca múa do phụ nữ thực hiện. Wiktionary ghi: to amuse, to entertain. Không có glyphOrigin chi tiết hơn. Chưa có nguồn học thuật đầy đủ. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "vui vẻ", "Hạng Tần Suất (Jun Da)": "2488.0", "Tần Suất % (Jun Da)": "98.4643331799", "GavinGrover_Once (Chiết tự trực tiếp)": "女 + 吴", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰女吴", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "吴", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "女", "Unihan_Simplified (Chữ Giản thể)": "娱", "Unihan_Traditional (Chữ Phồn thể)": "娛", "Pinyin_Xie": "yú", "Âm Hán Việt_Xie": "ngu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường kết hợp với các từ khác để tạo thành danh từ hoặc động từ liên quan đến hoạt động giải trí. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('娶', '{"9000": "2489.0", "Chữ Trung Quốc": "娶", "Bộ thủ & thành phần_Xie": "Bộ thủ | 女 | Số nét | 11 | nét | 取 | thủ | biểu âm | lấy, lấy đi — cho âm thú/thủ | 女 | nữ | biểu nghĩa | người phụ nữ | 娶 = 取 (Thủ, biểu âm: lấy) + 女 (Nữ, biểu nghĩa: phụ nữ); chữ hình thanh (và hội ý). Wiktionary ghi ls=psc và ls2=ic: vừa là hình thanh (取 cho âm) vừa là hội ý (lấy [取] người phụ nữ [女] = cưới vợ). Đây là trường hợp hai cơ chế tạo chữ cùng hoạt động.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thú\": Thủ (取-lấy) + Nữ (女-phụ nữ) = thú vợ — lấy vợ. Động từ cưới hỏi phía nhà trai. | Gương Hán-Việt | thú trong ''thú vị'' — âm giống nhưng nghĩa khác; 娶 đặc chỉ hành động cưới vợ (phía nam) | Mở khoá kiến thức | Biết 娶 mở khoá: 娶亲 (thú thân – cưới vợ), 娶妻 (thú thê – lấy vợ), phân biệt với 嫁 (giá – lấy chồng, phía nữ).", "Tự nguyên_Xie": "娶 là chữ hình thanh kiêm hội ý: 取 (thủ – lấy, bắt) biểu âm; 女 (nữ – phụ nữ) biểu nghĩa. Wiktionary ghi: {{Han compound|取|女|ls=psc|ls2=ic|c1=p|c2=s|t1=to take|t2=woman}} — ''lấy người phụ nữ'' = cưới vợ. Nghĩa hội ý rất trực tiếp: người đàn ông đến ''lấy'' người phụ nữ về làm vợ theo phong tục cổ đại. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "190.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thủ (189) Nữ (60)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Thủ (số 189) ở trên chữ Nữ (số 60) . Thời cổ đại có tục lệ bắt người con gái (Nữ) kia về làm vợ (Thú).", "Nghĩa Tiếng Việt_Xie": "lấy vợ", "Hạng Tần Suất (Jun Da)": "2489.0", "Tần Suất % (Jun Da)": "98.4662623388", "GavinGrover_Once (Chiết tự trực tiếp)": "取 + 女", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱取女", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "取", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "女", "Unihan_Simplified (Chữ Giản thể)": "娶", "Unihan_Traditional (Chữ Phồn thể)": "娶", "Pinyin_Xie": "qǔ", "Âm Hán Việt_Xie": "thú", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Làm động từ mang tân ngữ phía sau chỉ người phụ nữ được cưới về làm vợ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | Từ đơn | Từ vựng HSK 5: cưới | / | qǔ | / | cưới | Xuất hiện trong lộ trình | HSK | HSK 5 | · | Gia đình | New HSK | New HSK 7-9 | · | Gia đình II", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('沫', '{"9000": "2490.0", "Chữ Trung Quốc": "沫", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 8 | nét | 氵 | thuỷ | biểu nghĩa | nước | 末 | mạt | biểu âm | cuối, mút, đỉnh | 沫 = 氵 (Thuỷ, biểu nghĩa: nước) + 末 (Mạt, biểu âm); chữ hình thanh. Bộ 氵 chỉ chất lỏng, 末 (mạt) cho âm mò. Bọt nổi lên mặt nước như \"mạt\" — phần nhỏ nhoi, cuối cùng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mạt\": nước (氵) nhỏ nhoi mạt (末) nổi lên thành bọt — 沫 là bọt nước; 泡沫 là bọt bọt; 唾沫 là nước bọt. | Gương Hán-Việt | Mạt xuất hiện trong 泡沫 (bào mạt – bọt), 唾沫 (thóa mạt – nước bọt). | Mở khoá kiến thức | Biết 沫 mở khoá: 泡沫 (bọt), 唾沫 (nước bọt), 口沫 (bọt miệng), 泡沫经济 (kinh tế bong bóng).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Chữ 沫 là chữ hình thanh: bộ 水 (thuỷ – nước, viết tắt thành 氵) biểu nghĩa chất lỏng; bộ 末 (mạt) biểu âm. Nghĩa gốc là bọt nước nổi trên mặt. Tiểu triện và Lục thư thông được lưu tại hanziyuan. Hán-Việt đọc là Mạt — bọt nước là phần nhỏ nhoi, \"mạt\" như đầu cùng ngọn cây. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bọt nổi lên mặt nước; nước bọt", "Hạng Tần Suất (Jun Da)": "2490.0", "Tần Suất % (Jun Da)": "98.4681904641", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 末", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵末", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "末", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "沫", "Unihan_Traditional (Chữ Phồn thể)": "沫", "Pinyin_Xie": "mò", "Âm Hán Việt_Xie": "mạt", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng sau các danh từ khác để chỉ loại bọt cụ thể như bọt nước hoặc nước bọt. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('嗓', '{"9000": "2491.0", "Chữ Trung Quốc": "嗓", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 13 | nét | 口 | khẩu | biểu nghĩa | miệng, cổ họng | 桑 | tang | biểu âm | cây dâu (gần âm sǎng) | 嗓 = 口 (Khẩu, biểu nghĩa: miệng/họng) + 桑 (Tang, biểu âm); chữ hình thanh. Bộ phận trong miệng/họng, gốc nghĩa ''cổ họng, giọng''.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tảng\": 口 (miệng) + 桑 (Tang) — phần trong miệng, đúng nghĩa ''cổ họng, giọng'' trong 嗓子. | Gương Hán-Việt | ''tảng'' (Hán-Việt cho chữ này — ít gặp trong tiếng Việt) | Mở khoá kiến thức | Nắm 嗓 mở khoá từ HSK 5: 嗓子.", "Tự nguyên_Xie": "Theo Wiktionary, 嗓 là hình thanh: 口 (miệng, biểu nghĩa — chỉ cổ họng) + 桑 (Tang, biểu âm). Nghĩa gốc ''cổ họng, giọng nói'' giữ nguyên trong 嗓子, 嗓音. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cổ họng", "Hạng Tần Suất (Jun Da)": "2491.0", "Tần Suất % (Jun Da)": "98.470114972", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 桑", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口桑", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "桑", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "嗓", "Unihan_Traditional (Chữ Phồn thể)": "嗓", "Pinyin_Xie": "sǎng", "Âm Hán Việt_Xie": "tảng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường kết hợp với các từ khác để chỉ giọng hát, giọng nói hoặc bộ phận cổ họng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蹲', '{"9000": "2492.0", "Chữ Trung Quốc": "蹲", "Bộ thủ & thành phần_Xie": "Bộ thủ | 足 | Số nét | 19 | nét | 𧾷 | biểu nghĩa | bộ túc (chân), biến thể của 足 | 尊 | tôn | biểu âm | tôn kính — cho âm tôn/tồn | 蹲 = 足 (biểu nghĩa: chân) + 尊 (Tôn, biểu âm); chữ hình thanh. Wiktionary ghi: {{Han compound|足|尊|c1=s|t1=foot|c2=p|ls=psc}} — bộ túc (足/𧾷) biểu nghĩa chân, 尊 cho âm dūn gần tôn. Ngồi xổm là tư thế của chân.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tồn\": chân (足-Túc) tôn kính (尊-Tôn) — dùng chân cúi thấp như đang ngồi xổm khom lưng trước bậc tôn trưởng. | Gương Hán-Việt | tồn trong ''tồn tại'' — âm giống; nhưng 蹲 đặc chỉ tư thế ngồi xổm | Mở khoá kiến thức | Biết 蹲 mở khoá: 蹲下 (tồn hạ – ngồi xổm xuống), 蹲守 (tồn thủ – phục kích, canh gác).", "Tự nguyên_Xie": "蹲 là chữ hình thanh: 足 (túc – chân) biểu nghĩa, 尊 (tôn) biểu âm. Wiktionary ghi rõ cấu trúc này với ý nghĩa ''ngồi''. Bộ 足 (hay dạng biến thể 𧾷) xuất hiện ở bên trái chỉ hành động liên quan đến chân — ngồi xổm tức là gập chân xuống. Âm dūn có liên hệ xa với 尊. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ngồi xổm", "Hạng Tần Suất (Jun Da)": "2492.0", "Tần Suất % (Jun Da)": "98.4720374127", "GavinGrover_Once (Chiết tự trực tiếp)": "⻊ + 尊", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰⻊尊", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "尊", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⻊", "Unihan_Simplified (Chữ Giản thể)": "蹲", "Unihan_Traditional (Chữ Phồn thể)": "蹲", "Pinyin_Xie": "dūn", "Âm Hán Việt_Xie": "tồn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này thường làm động từ chỉ tư thế ngồi xổm hoặc ở lỳ tại một nơi nào đó. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | Từ đơn | Từ vựng HSK 5: ngồi xổm | Xuất hiện trong lộ trình | New HSK | New HSK 6 | · | Thân hình | HSK | HSK 5 | · | Động từ hàng ngày", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('焚', '{"9000": "2493.0", "Chữ Trung Quốc": "焚", "Bộ thủ & thành phần_Xie": "Bộ thủ | 火 | Số nét | 12 | nét | 林 | lâm | biểu nghĩa | rừng cây | 火 | hoả | biểu nghĩa | lửa | 焚 = 林 (Lâm, biểu nghĩa: rừng cây) + 火 (Hoả, biểu nghĩa: lửa); chữ hội ý. Rừng cây bốc lửa — hình ảnh trực quan của đốt cháy, thiêu rụi.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phần\": Rừng (林) bốc Lửa (火) — chữ Phần mô tả cảnh đám cháy rừng rực, thiêu Phần tất cả. | Gương Hán-Việt | phần trong \"phần đốt\", \"thiêu phần\" — đốt cháy, hoả táng | Mở khoá kiến thức | Biết 焚 mở khoá: 焚烧 (đốt cháy), 心急如焚 (sốt ruột), 焚书坑儒 (đốt sách chôn nho).", "Tự nguyên_Xie": "Giáp cốt văn | Kim văn | Tiểu triện | Theo Wiktionary, 焚 là chữ hội ý: 林 (rừng, nhiều cây) + 火 (lửa) — rừng bắt lửa cháy rụi. Một trong những chữ hội ý sinh động nhất: nhìn vào chữ là hình dung ngay cảnh lửa cháy rừng. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "144.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Lâm (109) Hỏa (140)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Lâm (số 109) ở trên chữ Hỏa (số 140) . Lấy lửa (hỏa) đốt rừng (lâm) để làm nương rẫy hoặc săn thú.", "Nghĩa Tiếng Việt_Xie": "đốt cháy", "Hạng Tần Suất (Jun Da)": "2493.0", "Tần Suất % (Jun Da)": "98.4739588198", "GavinGrover_Once (Chiết tự trực tiếp)": "林 + 火", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱林火", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "林", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "火", "Unihan_Simplified (Chữ Giản thể)": "焚", "Unihan_Traditional (Chữ Phồn thể)": "焚", "Pinyin_Xie": "fén", "Âm Hán Việt_Xie": "phần", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước tân ngữ để chỉ hành động thiêu đốt hoặc kết hợp tạo từ ghép. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('淘', '{"9000": "2494.0", "Chữ Trung Quốc": "淘", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 11 | nét | 氵 | thuỷ | biểu nghĩa | nước | 匋 | đào | biểu âm | cho âm đào | 淘 = 氵(Thuỷ, biểu nghĩa: nước) + 匋 (Đào, biểu âm); chữ hình thanh. Wiktionary ghi: {{Han compound|水|alt1=氵|匋|c1=s|t1=water|c2=p|ls=psc}}. Bộ thủy chỉ hành động liên quan đến nước — vo gạo, đãi cát là dùng nước lọc tạp chất.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đào\": nước (氵-Thuỷ) + Đào (匋) — đào đãi vàng trong nước; 淘金 (đào kim – đãi vàng). | Gương Hán-Việt | đào trong ''đào thoát'' — âm gần; 淘 đặc chỉ nghĩa vo/đãi bằng nước | Mở khoá kiến thức | Biết 淘 mở khoá: 淘汰 (đào thải – loại bỏ), 淘气 (đào khí – nghịch ngợm), 淘金 (đào kim – đãi vàng).", "Tự nguyên_Xie": "淘 là chữ hình thanh: 氵 (thuỷ – nước) biểu nghĩa, 匋 (đào) biểu âm. Nghĩa gốc là dùng nước để loại bỏ tạp chất — vo gạo, đãi vàng (淘金). Từ đó mở rộng sang nghĩa tinh lọc, loại bỏ (淘汰 – đào thải). Biến thể nghĩa ''nghịch ngợm'' (淘气) phát triển về sau trong tiếng Quan thoại hiện đại. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "vo, đãi (gạo); giặt bằng cái rây (sàng)", "Hạng Tần Suất (Jun Da)": "2494.0", "Tần Suất % (Jun Da)": "98.4758802269", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 匋", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵匋", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "匋", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "淘", "Unihan_Traditional (Chữ Phồn thể)": "淘", "Pinyin_Xie": "táo", "Âm Hán Việt_Xie": "đào", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Thường làm động từ chỉ hành động đãi lọc hoặc làm tính từ chỉ sự nghịch ngợm của trẻ con. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | táo | / | tìm kiếm | / | táo | / | nghịch ngợm | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Tiếng cười | New HSK 7-9 | · | Từ III", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('嫩', '{"9000": "2495.0", "Chữ Trung Quốc": "嫩", "Bộ thủ & thành phần_Xie": "Bộ thủ | 女 | Số nét | 14 | nét | 女 | nữ | hình thể | phụ nữ, thành phần cấu trúc | 敕 | sắc | hình thể | chiếu chỉ, thành phần cấu trúc | 嫩 là dạng biến dạng của 㜛. Wiktionary ghi: ''Corrupted form of 㜛.'' Cấu trúc 女+敕 hiện tại không phản ánh cơ chế tạo chữ gốc. Không có ls code xác định — chưa thể phân loại chắc chắn hình thanh hay hội ý từ dữ liệu hiện có.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nộn\": nộn = non — nhớ thẳng: nộn đọc gần giống non (tiếng Việt). Rau non, thịt nộn mềm. | Gương Hán-Việt | nộn gần với ''non'' tiếng Việt — lá non, rau non; chữ gợi ý mềm mại | Mở khoá kiến thức | Biết 嫩 mở khoá: 嫩绿 (nộn lục – xanh non), 娇嫩 (kiều nộn – mềm mại non tơ), 细嫩 (tế nộn – mịn màng).", "Tự nguyên_Xie": "嫩 là dạng chữ biến thể của 㜛 (nộn). Wiktionary ghi: ''Corrupted form of 㜛''. Chữ gốc có nghĩa ''non, mềm, còn non tơ''. Cấu trúc hiện tại 女+敕 là kết quả của quá trình biến dạng qua các thời kỳ, không phản ánh cơ chế tạo chữ nguyên thủy. Nghĩa ''non, mềm, e thẹn'' có thể liên hệ hình ảnh người phụ nữ trẻ non. Chưa có nguồn học thuật đầy đủ về glyphOrigin. | Theo Wiktionary · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1412.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Nữ (038) Sắc (1411)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Nữ (số 038 - phụ nữ/ 女) ở bên trái chữ Sắc (số 1411 - sắc lệnh/ 敕). Phụ nữ khi đang độ trẻ trung nhan sắc thì có thể ra lệnh, sai khiến đàn ông làm theo ý mình. Giải thích sự chuyển ý: Đây là chữ Hội ý. Nộn là sự trẻ trung, mềm mại, mới sinh, vật còn non nớt (nộn trúc - măng tre).", "Nghĩa Tiếng Việt_Xie": "non; mềm; e thẹn", "Hạng Tần Suất (Jun Da)": "2495.0", "Tần Suất % (Jun Da)": "98.4777959494", "GavinGrover_Once (Chiết tự trực tiếp)": "女 + 敕", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰女敕", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "敕", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "女", "Unihan_Simplified (Chữ Giản thể)": "嫩", "Unihan_Traditional (Chữ Phồn thể)": "嫩", "Pinyin_Xie": "nèn", "Âm Hán Việt_Xie": "nộn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường làm tính từ đứng trước danh từ hoặc sau phó từ chỉ mức độ để miêu tả trạng thái non, mềm. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | Từ đơn | Từ vựng HSK 5: mềm | / | nèn | / | mềm | Xuất hiện trong lộ trình | HSK | HSK 5 | · | Thức ăn và đồ uống | New HSK | New HSK 7-9 | · | Thực phẩm II", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('韵', '{"9000": "2496.0", "Chữ Trung Quốc": "韵", "Bộ thủ & thành phần_Xie": "Bộ thủ | 音 | Số nét | 13 | nét | 音 | âm | biểu nghĩa | âm thanh | 匀 | quân | biểu âm | đều đặn, đều nhau | 韵 (phồn thể 韻) = 音 (Âm, biểu nghĩa: âm thanh) + 匀 (Quân, biểu âm); chữ hình thanh. Bộ 音 xác định liên quan đến âm thanh/tiếng nói, 匀 cho âm yùn gần với vận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"vận\": Âm (音) thanh đều Quân (匀) nhịp — Vận thơ là những âm cuối đều nhau, tạo điệu êm tai. | Gương Hán-Việt | vận trong \"vần vận\", \"vận điệu\", \"phong vận\" — âm điệu, phong thái | Mở khoá kiến thức | Biết 韵 mở khoá: 韵味 (vẻ đẹp thâm thuý), 韵律 (vần luật), 押韵 (gieo vần).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Wiktionary ghi 韵 là giản thể của 韻 (音 + 員). Cấu trúc hình thanh: 音 biểu nghĩa, 員 biểu âm. Nghĩa: vần thơ, âm điệu đẹp, phong thái tao nhã — âm thanh có nhịp điệu đều đặn. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "vần; phong nhã", "Hạng Tần Suất (Jun Da)": "2496.0", "Tần Suất % (Jun Da)": "98.4797106384", "GavinGrover_Once (Chiết tự trực tiếp)": "音 + 匀", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰音匀", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "匀", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "音", "Unihan_Simplified (Chữ Giản thể)": "韵", "Unihan_Traditional (Chữ Phồn thể)": "韻", "Pinyin_Xie": "yùn", "Âm Hán Việt_Xie": "vận", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ vần điệu trong thơ ca hoặc vẻ đẹp thanh nhã của con người. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('衬', '{"9000": "2497.0", "Chữ Trung Quốc": "衬", "Bộ thủ & thành phần_Xie": "Bộ thủ | 衣 | Số nét | 8 | nét | 衤 | y | biểu nghĩa | bộ Y — áo quần | 寸 | thốn | biểu âm | mượn âm | 衬 = 衤 (bộ Y, áo, biểu nghĩa) + 寸 (Thốn, biểu âm); chữ hình thanh. Là giản thể của 襯. Nghĩa ''áo trong, áo lót'' và ''lót, lót dưới'' liên quan trực tiếp đến bộ Y (áo).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sấn\" = áo lót, lót dưới. Nhớ: bộ Y 衤 (áo) + 寸 (tấc) — áo lót sát từng tấc bên trong, đó là ''sấn''. | Gương Hán-Việt | Hán-Việt ''sấn'' của 衬 ít dùng trong tiếng Việt thuần; thường dịch là ''áo sơ mi, áo lót, lót''. | Mở khoá kiến thức | Biết 衬 mở khoá 衬衫 (sấn sam - áo sơ mi), 衬衣 (sấn y - áo trong), 衬托 (sấn thác - làm nổi bật).", "Tự nguyên_Xie": "Theo Wiktionary, 衬 là chữ giản thể của 襯 — chữ hình thanh ghép 衣 (áo, viết thành 衤 khi làm bộ thủ, biểu nghĩa) với 寸 (biểu âm). Nghĩa chính: (1) áo trong, áo lót; (2) lớp lót; (3) lót dưới, đặt dưới; (4) làm nền, tương phản (như 衬托). Trong tiếng Trung hiện đại 衬 chủ yếu dùng trong 衬衫 (áo sơ mi) và 衬托 (làm nền). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "áo trong, áo lót", "Hạng Tần Suất (Jun Da)": "2497.0", "Tần Suất % (Jun Da)": "98.4816227434", "GavinGrover_Once (Chiết tự trực tiếp)": "衤 + 寸", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰衤寸", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "寸", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "衤", "Unihan_Simplified (Chữ Giản thể)": "衬", "Unihan_Traditional (Chữ Phồn thể)": "襯", "Pinyin_Xie": "chèn", "Âm Hán Việt_Xie": "sấn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường làm động từ chỉ việc làm nền để tôn lên vẻ đẹp hoặc làm danh từ chỉ áo lót, áo sơ mi. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('匈', '{"9000": "2498.0", "Chữ Trung Quốc": "匈", "Bộ thủ & thành phần_Xie": "Bộ thủ | 勹 | Số nét | 6 | nét | 勹 | bao | biểu nghĩa | bao bọc, vòng quanh | 凶 | hung | biểu âm | hung dữ, xấu | 匈 = 勹 (Bao, biểu nghĩa: bao bọc, hình ngực bao quanh) + 凶 (Hung, biểu âm); chữ hình thanh. Bộ 勹 mô phỏng vòng ngực, 凶 cho âm xiōng gần với hung. Chữ phái sinh 胸 (ngực) dùng bộ 肉 thay 勹.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hung\": vòng Bao (勹) che Hung (凶) — chữ Hung ban đầu chỉ ngực người bọc lấy tim, sau dùng để phiên âm tộc Hung Nô. | Gương Hán-Việt | hung trong \"Hung Nô\", \"Hung Gia Lợi\" — phiên âm tên tộc/nước | Mở khoá kiến thức | Biết 匈 mở khoá: 匈奴 (Hung Nô), 匈牙利 (Hungary).", "Tự nguyên_Xie": "Giáp cốt văn | Đại triện | Tiểu triện | Theo Wiktionary, 匈 là chữ hình thanh: 勹 biểu nghĩa (bao bọc, hình thể ngực), 凶 biểu âm. Nghĩa gốc là ngực người; chữ phái sinh 胸 mang nghĩa đó. 匈 sau dùng để phiên âm tên bộ tộc Hung Nô (匈奴) và tên nước Hungary (匈牙利). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "rầm rĩ; tộc Hung Nô; nước Hungari", "Hạng Tần Suất (Jun Da)": "2498.0", "Tần Suất % (Jun Da)": "98.4835348484", "GavinGrover_Once (Chiết tự trực tiếp)": "勹 + 凶", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴勹凶", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "凶", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "勹", "Unihan_Simplified (Chữ Giản thể)": "匈", "Unihan_Traditional (Chữ Phồn thể)": "匈", "Pinyin_Xie": "xiōng", "Âm Hán Việt_Xie": "hung", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chủ yếu dùng làm danh từ trong các danh từ riêng như Hung Nô hoặc Hung-ga-ri. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('钧', '{"9000": "2499.0", "Chữ Trung Quốc": "钧", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 9 | nét | 钅 | kim | biểu nghĩa | kim loại | 匀 | quân | biểu âm | đều đặn | 钧 (phồn thể 鈞) = 钅/金 (Kim, biểu nghĩa: kim loại) + 匀 (Quân, biểu âm); chữ hình thanh. Bộ 钅 xác định liên quan đến kim loại, 匀 cho âm jūn gần với quân.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quân\": Kim (钅) loại đồng đều Quân (匀) — đơn vị Quân nặng 30 cân, bàn gốm xoay đều tay. | Gương Hán-Việt | quân trong \"thiên quân\" (nghìn cân nặng), \"quân bình\" — cân bằng, đơn vị trọng lượng | Mở khoá kiến thức | Biết 钧 mở khoá: 千钧一发 (ngàn cân treo sợi tóc), 钧天 (nhạc trời), 雷霆万钧 (sức mạnh sấm sét).", "Tự nguyên_Xie": "Kim văn | Tiểu triện | Lục thư thông | Wiktionary ghi 钧 là giản thể của 鈞 (金 + 匀). Hình thanh: 金 biểu nghĩa, 匀 biểu âm. Nghĩa: đơn vị đo lường cổ bằng 30 cân; bàn xoay của thợ gốm (hình tròn đều nhau — ý nghĩa của 匀 gợi sự đều đặn). | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "quân (đơn vị đo, bằng 30 cân); cái compas của thợ gốm (để nặn các đồ hình tròn)", "Hạng Tần Suất (Jun Da)": "2499.0", "Tần Suất % (Jun Da)": "98.4854459198", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 匀", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅匀", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "匀", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "钧", "Unihan_Traditional (Chữ Phồn thể)": "鈞", "Pinyin_Xie": "jūn", "Âm Hán Việt_Xie": "quân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Lượng từ | 量词 | Tính từ | 形容词 | Danh từ | 名词 | Thường dùng làm tính từ kính ngữ trong thư từ xã giao hoặc làm lượng từ đo lường thời cổ đại. | Lượng từ | 量词 | Đứng giữa số từ (hoặc 这/那) và danh từ: 一杯茶, 这本书. Mỗi danh từ đi với lượng từ riêng; 个 là lượng từ dùng chung phổ biến nhất. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('竖', '{"9000": "2500.0", "Chữ Trung Quốc": "竖", "Bộ thủ & thành phần_Xie": "Bộ thủ | 立 | Số nét | 9 | nét | 又 | hựu | biểu nghĩa | tay phải | 立 | lập | biểu nghĩa | đứng thẳng | 竖 là dạng giản thể của 豎. Chữ gốc 豎 theo Wiktionary có thể là hình thanh: 臤 (biểu nghĩa) + 豆 (biểu âm). Dạng hiện đại đơn giản hóa thành 又 + 立. Bộ 立 gợi ý đứng thẳng đứng — đó là nghĩa chính của 竖.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thụ\": bàn tay (又) dựng thẳng đứng (立) lên — 竖 là dọc, thẳng đứng; 竖起 là dựng lên; 横七竖八 là nằm ngang nằm dọc bừa bãi. | Gương Hán-Việt | Thụ xuất hiện trong 竖立 (thụ lập – dựng thẳng đứng), ít thấy trong từ Hán-Việt thông dụng. | Mở khoá kiến thức | Biết 竖 mở khoá: 竖立 (dựng thẳng), 竖琴 (đàn harp), 横七竖八 (bừa bộn), nét dọc trong thư pháp.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Chữ 竖 là dạng giản thể của 豎 (phồn thể). Theo Wiktionary, chữ gốc 豎 có thể là hình thanh: 臤 biểu nghĩa và 豆 biểu âm. Nghĩa là dựng thẳng đứng; chiều dọc; nét dọc trong thư pháp. Tiểu triện và Lục thư thông được lưu tại hanziyuan. Hán-Việt đọc là Thụ — gợi ý \"thụ lập\" (đứng thẳng). | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "dựng đứng, chiều dọc; nét dọc", "Hạng Tần Suất (Jun Da)": "2500.0", "Tần Suất % (Jun Da)": "98.4873569912", "GavinGrover_Once (Chiết tự trực tiếp)": "No glyph available + 立", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱立", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "竖", "Unihan_Traditional (Chữ Phồn thể)": "竪", "Pinyin_Xie": "shù", "Âm Hán Việt_Xie": "thụ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Danh từ | 名词 | Thường làm động từ chỉ hành động dựng thẳng vật gì đó hoặc làm danh từ chỉ nét dọc trong chữ Hán. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | shù | / | nét dọc | / | shù | / | thẳng đứng | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Toán học và Hình học | HSK | HSK 6 | · | Nghiên cứu", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('峻', '{"9000": "2501.0", "Chữ Trung Quốc": "峻", "Bộ thủ & thành phần_Xie": "Bộ thủ | 山 | Số nét | 10 | nét | 山 | sơn | biểu nghĩa | núi | 夋 | biểu âm | thành phần biểu âm (không có Hán-Việt độc lập) | 峻 = 山 (Sơn, biểu nghĩa: núi) + 夋 (biểu âm); chữ hình thanh. Bộ 山 chỉ đây là tính chất của núi — cao và dốc đứng; 夋 cho âm jùn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tuấn\": núi (山) tuấn tú cao vút (夋) — 峻 là núi cao dốc đứng; 严峻 là tình huống nghiêm trọng cao như núi; 险峻 là hiểm trở dốc đứng. | Gương Hán-Việt | Tuấn xuất hiện trong 严峻 (nghiêm tuấn – nghiêm trọng), 险峻 (hiểm tuấn – hiểm trở), 高峻 (cao tuấn – cao vút). | Mở khoá kiến thức | Biết 峻 mở khoá: 严峻 (nghiêm trọng), 险峻 (hiểm trở), 峻岭 (núi cao dốc đứng), 峻急 (gấp gáp, nghiêm khắc).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Chữ 峻 là chữ hình thanh: bộ 山 (sơn – núi) biểu nghĩa núi cao, dốc đứng; bộ 夋 biểu âm. Nghĩa là cao và dốc đứng (núi); mở rộng sang nghĩa nghiêm khắc, gay gắt. Tiểu triện và Lục thư thông được lưu tại hanziyuan. Hán-Việt đọc là Tuấn — cùng gốc với \"tuấn\" trong \"tuấn tú\" (cao đẹp), \"tuấn kiệt\" (tài năng xuất sắc). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cao (núi)", "Hạng Tần Suất (Jun Da)": "2501.0", "Tần Suất % (Jun Da)": "98.4892628948", "GavinGrover_Once (Chiết tự trực tiếp)": "山 + 夋", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰山夋", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "夋", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "山", "Unihan_Simplified (Chữ Giản thể)": "峻", "Unihan_Traditional (Chữ Phồn thể)": "峻", "Pinyin_Xie": "jùn", "Âm Hán Việt_Xie": "tuấn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường làm tính từ bổ nghĩa cho danh từ chỉ địa hình núi non hoặc thái độ nghiêm khắc. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('豹', '{"9000": "2502.0", "Chữ Trung Quốc": "豹", "Bộ thủ & thành phần_Xie": "Bộ thủ | 豸 | Số nét | 10 | nét | 豸 | trĩ | biểu nghĩa | thú lớn không chân trước (bộ thú hoang) | 勺 | thược | biểu âm | cái muỗng | 豹 = 豸 (Trĩ, biểu nghĩa: thú lớn) + 勺 (Thược, biểu âm); chữ hình thanh. Bộ 豸 xác định đây là loài thú lớn, 勺 cho âm bào gần với báo. Trong giáp cốt văn, 豹 cũng có dạng tượng hình con báo.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"báo\": con Thú (豸) nhanh như múc Thược (勺) — Báo là thú chạy nhanh nhất, vằn đốm như hoa văn trên chén. | Gương Hán-Việt | báo trong \"báo tin\", \"báo chí\" (chữ khác); 豹 riêng chỉ con báo | Mở khoá kiến thức | Biết 豹 mở khoá: 豹子 (con báo), 花豹 (báo hoa), 豹变 (thay đổi đột ngột).", "Tự nguyên_Xie": "Đại triện | Tiểu triện | Theo Wiktionary, 豹 là chữ hình thanh: 豸 (trĩ, thú lớn) biểu nghĩa, 勺 biểu âm. Trong giáp cốt văn còn có dạng tượng hình. Nghĩa: con báo (Panthera pardus), thú họ mèo có đốm. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con báo", "Hạng Tần Suất (Jun Da)": "2502.0", "Tần Suất % (Jun Da)": "98.4911662144", "GavinGrover_Once (Chiết tự trực tiếp)": "豸 + 勺", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰豸勺", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "勺", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "豸", "Unihan_Simplified (Chữ Giản thể)": "豹", "Unihan_Traditional (Chữ Phồn thể)": "豹", "Pinyin_Xie": "bào", "Âm Hán Việt_Xie": "báo", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng độc lập hoặc làm thành phần trong các cụm từ chỉ loài báo. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | bào | / | báo | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Động vật và côn trùng", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('捞', '{"9000": "2503.0", "Chữ Trung Quốc": "捞", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 10 | nét | 扌 | thủ | biểu nghĩa | tay | 劳 | lao | biểu âm | lao động, mệt nhọc | 捞 = 扌 (Thủ, biểu nghĩa: tay) + 劳 (Lao, biểu âm); dạng giản thể của 撈. Bộ 扌 chỉ hành động dùng tay vớt, mò; 劳 (lao) cho âm lāo.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lao\": bàn tay (扌) lao vào (劳) nước vớt lên — 捞 là vớt, mò; 打捞 là vớt cứu (thuyền chìm); 捞好处 là kiếm chác lợi dụng. | Gương Hán-Việt | Lao xuất hiện trong 打捞 (đả lao – vớt cứu, trục vớt), 捞鱼 (lao ngư – vớt cá). | Mở khoá kiến thức | Biết 捞 mở khoá: 打捞 (trục vớt), 捞取 (vớt lấy, kiếm chác), 捞鱼 (vớt cá).", "Tự nguyên_Xie": "Chữ 捞 là dạng giản thể của 撈 (phồn thể). Cấu trúc hình thanh: bộ 手 (thủ – tay, viết tắt thành 扌) biểu nghĩa hành động dùng tay hoặc công cụ vớt, mò từ dưới nước; bộ 勞 (lao, giản thể thành 劳) biểu âm. Nghĩa là vớt, mò (từ dưới nước); cũng có nghĩa ẩn: kiếm chác lợi dụng. Hán-Việt đọc là Lao. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mò, lặn bắt", "Hạng Tần Suất (Jun Da)": "2503.0", "Tần Suất % (Jun Da)": "98.4930685005", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 劳", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌劳", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "劳", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "捞", "Unihan_Traditional (Chữ Phồn thể)": "撈", "Pinyin_Xie": "lāo", "Âm Hán Việt_Xie": "lao, lạo", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ chỉ hành động vớt đồ vật từ dưới nước lên hoặc ẩn dụ cho việc kiếm lợi bất chính. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | lāo | / | vớt | Xuất hiện trong lộ trình | HSK | HSK 6 | · | Động từ hàng ngày | New HSK | New HSK 7-9 | · | Từ III", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('菊', '{"9000": "2504.0", "Chữ Trung Quốc": "菊", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 11 | nét | 艹 | thảo | biểu nghĩa | cỏ, thực vật | 匊 | cúc | biểu âm | hai tay bưng | 菊 = 艹 (Thảo, biểu nghĩa: thực vật) + 匊 (Cúc, biểu âm); chữ hình thanh. Bộ 艹 xác định đây là loài thực vật, 匊 cho âm jú gần với cúc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cúc\": bộ Cỏ (艹) với âm Cúc (匊) — hoa Cúc mùa thu, bưng hai tay dâng lên như chén rượu thanh đạm. | Gương Hán-Việt | cúc trong \"hoa cúc\", \"cúc điệu\" — hoa thanh cao mùa thu | Mở khoá kiến thức | Biết 菊 mở khoá: 菊花 (hoa cúc), 野菊 (cúc dại), 雏菊 (cúc tây).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary (nguồn cổ), 菊 là chữ hình thanh: 艸/艹 (thảo) biểu nghĩa, 匊 biểu âm. Nghĩa: hoa cúc (Chrysanthemum) — loài hoa nở mùa thu, tượng trưng cho phẩm giá thanh cao, một trong Tứ Quân Tử. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "879.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thảo (028) Cúc (878)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Thảo (số 028 - cỏ cây) ở trên chữ Cúc (số 878 - nắm tay/chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Cúc chỉ âm, bộ Thảo chỉ ý. Cúc là cây cúc, hoa cúc (thu cúc).", "Nghĩa Tiếng Việt_Xie": "hoa cúc", "Hạng Tần Suất (Jun Da)": "2504.0", "Tần Suất % (Jun Da)": "98.4949682027", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 匊", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹匊", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "匊", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "菊", "Unihan_Traditional (Chữ Phồn thể)": "菊", "Pinyin_Xie": "jú", "Âm Hán Việt_Xie": "cúc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này thường làm danh từ đứng độc lập hoặc kết hợp thành các từ ghép chỉ hoa cúc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鄙', '{"9000": "2505.0", "Chữ Trung Quốc": "鄙", "Bộ thủ & thành phần_Xie": "Bộ thủ | 邑 | Số nét | 13 | nét | 啚 | biểu âm | thành phần biểu âm (口 + 十 + 回) | 阝 | phụ | biểu nghĩa | ấp, làng (bộ ấp bên phải) | 鄙 = 啚 (biểu âm: thị trấn biên giới) + 阝 (Phụ/邑, biểu nghĩa: làng ấp); chữ hội ý kiêm hình thanh. Wiktionary giải thích: ban đầu viết là 啚 (thị trấn biên giới), sau thêm bộ 邑 (làng) tạo thành hội ý + hình thanh — thị trấn biên giới xa xôi. Nghĩa phát triển sang hèn kém, khinh bỉ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bỉ\": làng ấp (阝) ở nơi khuất (啚 – biên giới xa) — 鄙 là nơi hẻo lánh, rồi mang nghĩa hèn kém, khinh bỉ; 卑鄙 là \"tỉ bỉ\" tức bỉ ổi, thấp hèn. | Gương Hán-Việt | Bỉ xuất hiện trong 卑鄙 (tỉ bỉ – bỉ ổi, đê tiện), 鄙视 (bỉ thị – khinh thường). | Mở khoá kiến thức | Biết 鄙 mở khoá: 卑鄙 (bỉ ổi), 鄙视 (khinh thường), 粗鄙 (thô tục), 鄙夷 (khinh bỉ).", "Tự nguyên_Xie": "Tiểu triện | Chữ 鄙 ban đầu viết là 啚 — hình ảnh thị trấn biên giới. Theo Wiktionary: nay là 啚 (biểu âm, có nghĩa gốc \"thị trấn biên giới\") + 邑 (phụ/ấp – làng, viết thành 阝 bên phải) biểu nghĩa. Cấu trúc kết hợp hội ý lẫn hình thanh. Nghĩa gốc là vùng biên giới xa xôi hẻo lánh; từ đó phát triển sang hèn kém (người ở nơi hẻo lánh ít học), khinh bỉ. Tiểu triện tại wikimedia. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cõi ngoài biên cương, nơi xa xôi hẻo lánh; khinh bỉ; thô tục, thô lỗ; hèn hạ, hèn mọn", "Hạng Tần Suất (Jun Da)": "2505.0", "Tần Suất % (Jun Da)": "98.4968648041", "GavinGrover_Once (Chiết tự trực tiếp)": "啚 + 阝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰啚阝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "啚", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "阝", "Unihan_Simplified (Chữ Giản thể)": "鄙", "Unihan_Traditional (Chữ Phồn thể)": "鄙", "Pinyin_Xie": "bǐ", "Âm Hán Việt_Xie": "bỉ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Danh từ | 名词 | Thường làm tính từ chỉ sự hèn hạ, thô tục hoặc làm động từ thể hiện sự khinh bỉ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('魄', '{"9000": "2506.0", "Chữ Trung Quốc": "魄", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鬼 | Số nét | 14 | nét | 白 | bạch | biểu âm | trắng — góp âm | 鬼 | quỷ | biểu nghĩa | hồn ma, quỷ | 魄 = 白 (Bạch, biểu âm) + 鬼 (Quỷ, biểu nghĩa: hồn ma). Cấu trúc hình thanh — 白 góp âm (pò), 鬼 gợi nghĩa liên quan đến linh hồn, vía người. Nguồn Wiktionary chỉ ghi {{Han etym}} mà không cung cấp phân tích chi tiết, nên phán đoán dựa trên cấu trúc tự dạng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phách\": 鬼 (quỷ) mang màu 白 (trắng) — đó là vía người, phần hồn âm trú trong xác, khác với hồn bay lên trời. | Gương Hán-Việt | phách trong 魂魄 (hồn phách), 气魄 (khí phách) | Mở khoá kiến thức | Biết 魄 (phách) mở khoá: 气魄 (khí phách — khí thế), 魄力 (phách lực — quyết đoán), 魂魄 (hồn phách — linh hồn).", "Tự nguyên_Xie": "Tiểu triện | 魄 gồm 白 (bạch, trắng) và 鬼 (quỷ, hồn ma). Chữ biểu nghĩa — 鬼 gợi khái niệm linh hồn vô hình, còn 白 mang âm đọc gần pò. Trong tư tưởng Trung Hoa cổ, 魄 là vía âm (phần hồn gắn với thể xác), đối lập với 魂 là hồn dương (phần hồn bay lên trời). Chưa có nguồn học thuật chi tiết từ Wiktionary về quá trình hình thành chữ này. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "vùng tối trên mặt trăng; vía (hồn vía)", "Hạng Tần Suất (Jun Da)": "2506.0", "Tần Suất % (Jun Da)": "98.4987583049", "GavinGrover_Once (Chiết tự trực tiếp)": "白 + 鬼", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰白鬼", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "鬼", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "白", "Unihan_Simplified (Chữ Giản thể)": "魄", "Unihan_Traditional (Chữ Phồn thể)": "魄", "Pinyin_Xie": "pò", "Âm Hán Việt_Xie": "phách", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ trong các từ ghép chỉ tinh thần, khí phách hoặc hồn vía. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('兜', '{"9000": "2507.0", "Chữ Trung Quốc": "兜", "Bộ thủ & thành phần_Xie": "Bộ thủ | 儿 | Số nét | 11 | nét | 𠑹 | biểu nghĩa | che phủ — nắp đậy | 皃 | biểu nghĩa | đầu người | 兜 là chữ hội ý — gồm phần che phủ (𠑹) và phần đầu người (皃), mô tả hình ảnh mũ giáp che đầu. Trong dạng hiện đại, 𠑹 đơn giản hoá thành phần trên, 皃 biến thành 儿 (nhân). Cấu trúc hội ý rõ ràng theo phân tích Wiktionary: a cover + a head = mũ giáp.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đâu\": hình ảnh cái mũ giáp (兜) bọc kín đầu chiến binh — bao quanh, ôm trùm như túi đựng. | Gương Hán-Việt | đâu trong 兜鍪 (đâu mâu — mũ giáp), 兜售 (đâu thụ — bán dạo) | Mở khoá kiến thức | Biết 兜 (đâu) mở khoá: 兜售 (đâu thụ — bán dạo, chào mời), 兜风 (đâu phong — đi dạo bằng xe), 兜底 (bao hết từ dưới lên).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Theo Wiktionary, 兜 là chữ hội ý (hội ý): 𠑹 (che phủ) + 皃 (đầu người) → hình ảnh mũ giáp che đầu chiến binh. Từ nghĩa gốc \"mũ\" mở rộng ra nghĩa \"túi\", \"bao\", \"bọc quanh\". Dạng hiện đại 兜 có thêm 儿 (nhân) ở dưới, thay thế cho 皃. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đứng đằng sau ôm; (xem: đâu mâu 兜鍪)", "Hạng Tần Suất (Jun Da)": "2507.0", "Tần Suất % (Jun Da)": "98.5006512888", "GavinGrover_Once (Chiết tự trực tiếp)": "No glyph available + 儿", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱儿", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "兜", "Unihan_Traditional (Chữ Phồn thể)": "兜", "Pinyin_Xie": "dōu", "Âm Hán Việt_Xie": "đâu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường làm danh từ chỉ cái túi hoặc làm động từ với nghĩa bao bọc, ôm lấy. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | dōu | / | di chuyển xung quanh | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Quần áo và đồ trang sức | HSK | HSK 6 | · | Quần áo", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('哄', '{"9000": "2508.0", "Chữ Trung Quốc": "哄", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 9 | nét | 口 | khẩu | biểu nghĩa | miệng — liên quan đến âm thanh, lời nói | 共 | cộng | biểu âm | cùng nhau — góp âm hōng | 哄 = 口 (Khẩu, biểu nghĩa: miệng) + 共 (Cộng, biểu âm). Chữ hình thanh — 口 chỉ nghĩa liên quan đến miệng/tiếng ồn, 共 góp âm gần hōng/hǒng/hòng. Chữ này đa âm: hōng (ồn ào), hǒng (dỗ dành), hòng (chọc cười).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hống\": nhiều cái 口 (miệng) cùng nói (共 — cùng nhau) tạo ra tiếng ồn hống hách, hoặc một miệng ngọt dỗ dành người khác. | Gương Hán-Việt | hống trong 哄堂大笑 (hống đường đại tiếu), 起哄 (khởi hống) | Mở khoá kiến thức | Biết 哄 (hống) mở khoá: 起哄 (gây rối ồn ào), 哄堂大笑 (cả phòng cười ầm), 哄骗 (lừa gạt bằng lời ngọt).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 哄 là chữ hình thanh (hình thanh): 口 (khẩu, miệng) là phần biểu nghĩa, 共 (cộng) là phần biểu âm. Nghĩa gốc liên quan đến tiếng ồn nhiều người, sau mở rộng sang nghĩa dỗ dành, mua chuộc bằng lời nói ngọt. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đánh nhau ầm ĩ", "Hạng Tần Suất (Jun Da)": "2508.0", "Tần Suất % (Jun Da)": "98.5025427224", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 共", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口共", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "共", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "哄", "Unihan_Traditional (Chữ Phồn thể)": "哄", "Pinyin_Xie": "hōng", "Âm Hán Việt_Xie": "hống", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Từ tượng thanh | 象声词 | Thường làm động từ chỉ hành động dỗ dành trẻ con hoặc lừa gạt, làm ầm ĩ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Từ tượng thanh | 象声词 | Mô phỏng âm thanh: 哗哗, 汪汪. Có thể làm định ngữ, trạng ngữ hoặc đứng độc lập.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | hǒng | / | dỗ dành | / | hōng | / | ồn ào | / | hòng | / | chọc cười, lừa dối | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Giao tiếp II | New HSK 7-9 | · | Âm thanh | New HSK 7-9 | · | Tiếng cười | HSK | HSK 6 | · | Động từ", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('颖', '{"9000": "2509.0", "Chữ Trung Quốc": "颖", "Bộ thủ & thành phần_Xie": "Bộ thủ | 頁 | Số nét | 13 | nét | 匕 | chuỷ | biểu nghĩa | dao nhỏ — gợi hình mũi nhọn | 禾 | hoà | biểu nghĩa | cây lúa | 页 | hiệt | biểu âm | trang, đầu — góp âm | 颖 là dạng giản thể của 穎. Cấu trúc: phần trên gồm 匕 (chuỷ) + 禾 (hoà — cây lúa) tạo thành hình bông lúa nhọn, phần bên phải là 页 (hiệt) góp âm. Chữ hình thanh — miêu tả đầu nhọn của bông lúa, từ đó mở nghĩa thành \"sắc bén, thông minh\". Wiktionary chỉ ghi là dạng giản thể của 穎, không phân tích sâu hơn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"dĩnh\": bông 禾 (lúa) nhọn như dao 匕 — đó là đầu bông lúa dĩnh (xuất sắc, nhô lên trên đám đông). | Gương Hán-Việt | dĩnh trong 新颖 (tân dĩnh — mới lạ), 颖悟 (dĩnh ngộ — thông minh) | Mở khoá kiến thức | Biết 颖 (dĩnh) mở khoá: 新颖 (tân dĩnh — mới lạ), 脱颖而出 (thoát dĩnh nhi xuất — bộc lộ tài năng), 聪颖 (thông minh xuất sắc).", "Tự nguyên_Xie": "Tiểu triện | 颖 là dạng giản thể của 穎 (穎 = 禾 + 頃, chữ hình thanh). Nghĩa gốc là đầu bông lúa nhọn — phần trên cùng của cây lúa. Từ hình ảnh \"mũi nhọn\" này mở rộng sang nghĩa xuất sắc, thông minh nổi bật (như bông lúa nhô ra khỏi đám cỏ). Chưa có nguồn học thuật chi tiết về chữ giản thể này. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bông lúa, ngọn lúa", "Hạng Tần Suất (Jun Da)": "2509.0", "Tần Suất % (Jun Da)": "98.5044331224", "GavinGrover_Once (Chiết tự trực tiếp)": "No glyph available + 页", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰页", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "颖", "Unihan_Traditional (Chữ Phồn thể)": "穎", "Pinyin_Xie": "yǐng", "Âm Hán Việt_Xie": "dĩnh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Thường làm tính từ chỉ sự thông minh, nổi bật hoặc làm danh từ chỉ ngọn lúa. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('镑', '{"9000": "2510.0", "Chữ Trung Quốc": "镑", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 15 | nét | 钅 | kim | biểu nghĩa | kim loại, tiền | 旁 | bàng | biểu âm | bên cạnh | 镑 (phồn thể 鎊) = 钅/金 (Kim, biểu nghĩa: kim loại/tiền) + 旁 (Bàng, biểu âm); chữ hình thanh. Bộ 钅 xác định liên quan đến kim loại/tiền tệ, 旁 cho âm bàng gần với bảng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bảng\": bộ Kim (钅) với âm Bàng (旁) — đồng Bảng Anh là tiền Kim loại quý, phiên âm từ \"pound\". | Gương Hán-Việt | bảng trong \"bảng Anh\" — đơn vị tiền tệ Vương quốc Anh | Mở khoá kiến thức | Biết 镑 mở khoá: 英镑 (bảng Anh), 港镑 (đô la Hồng Kông — ít dùng), 镑汇 (tỷ giá bảng Anh).", "Tự nguyên_Xie": "Wiktionary chỉ ghi 鎊 có bộ 金 và phần phonetic. Đây là chữ dùng để phiên âm đơn vị tiền tệ \"pound\" của Anh — 镑 (bảng). Cấu trúc hình thanh: 金 biểu nghĩa (tiền kim loại), phần còn lại biểu âm. Chưa có nguồn glyphOrigin chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đồng bảng Anh", "Hạng Tần Suất (Jun Da)": "2510.0", "Tần Suất % (Jun Da)": "98.5063230057", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 旁", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅旁", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "旁", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "镑", "Unihan_Traditional (Chữ Phồn thể)": "鎊", "Pinyin_Xie": "bàng", "Âm Hán Việt_Xie": "bảng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Lượng từ | 量词 | Danh từ | 名词 | Thường dùng làm lượng từ chỉ đơn vị tiền tệ bảng Anh hoặc làm danh từ. | Lượng từ | 量词 | Đứng giữa số từ (hoặc 这/那) và danh từ: 一杯茶, 这本书. Mỗi danh từ đi với lượng từ riêng; 个 là lượng từ dùng chung phổ biến nhất. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('屑', '{"9000": "2511.0", "Chữ Trung Quốc": "屑", "Bộ thủ & thành phần_Xie": "Bộ thủ | 尸 | Số nét | 10 | nét | 尸 | thi | biểu nghĩa | xác, thân người — vật bị phân rã | 肖 | tiêu | biểu âm | giống, nhỏ dần — góp âm xiè | 屑 = 尸 (Thi, biểu nghĩa: hình thân người bị phân rã) + 肖 (Tiêu, biểu âm: góp âm xiè). Chữ hình thanh — 尸 gợi nghĩa mảnh vụn, thứ rơi ra từ vật bị bào mòn. Wiktionary ghi nguyên dạng là 㞕.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tiết\": thân 尸 bị bào mòn rụng ra từng mảnh tiết (vụn) — không đáng kể, bị khinh thường như bụi bẩn. | Gương Hán-Việt | tiết trong 不屑 (bất tiết — không thèm), 屑屑 (tiết tiết — nhỏ nhặt) | Mở khoá kiến thức | Biết 屑 (tiết) mở khoá: 不屑 (không thèm, khinh thường), 不屑一顾 (không thèm nhìn), 木屑 (mùn cưa), 纸屑 (mảnh giấy vụn).", "Tự nguyên_Xie": "Theo Wiktionary, 屑 nguyên bản viết là 㞕. Cấu trúc gồm 尸 (thi, thân/xác) làm biểu nghĩa, gợi hình ảnh thứ tróc ra, vỡ vụn từ bề mặt. Nghĩa gốc là mảnh vụn, phế liệu rơi ra. Mở rộng sang nghĩa thèm muốn, coi trọng (như trong 不屑 — không thèm, khinh thường). Chưa có nguồn học thuật chi tiết hơn. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mạt, vụn vặt; thèm, muốn", "Hạng Tần Suất (Jun Da)": "2511.0", "Tần Suất % (Jun Da)": "98.5082118553", "GavinGrover_Once (Chiết tự trực tiếp)": "尸 + 肖", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴尸肖", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "肖", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "尸", "Unihan_Simplified (Chữ Giản thể)": "屑", "Unihan_Traditional (Chữ Phồn thể)": "屑", "Pinyin_Xie": "xiè", "Âm Hán Việt_Xie": "tiết", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường làm danh từ chỉ các mảnh vụn nhỏ hoặc làm động từ biểu thị sự coi thường. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | xiè | / | mảnh vụn | Xuất hiện trong lộ trình | HSK | HSK 6 | · | Xây dựng và cải tạo", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蚁', '{"9000": "2512.0", "Chữ Trung Quốc": "蚁", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 9 | nét | 虫 | trùng | biểu nghĩa | sâu bọ, côn trùng | 义 | nghĩa | biểu âm | nghĩa lý — góp âm yǐ | 蚁 là dạng giản thể của 蟻. Cấu trúc: 虫 (trùng, biểu nghĩa: côn trùng) + 义 (nghĩa, biểu âm: góp âm yǐ). Chữ hình thanh — 虫 xác định loài vật, 义 góp âm. Dạng phồn thể 蟻 dùng 義 thay 义.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nghĩ\": con 虫 (trùng) nhỏ xíu mà có 义 (nghĩa — tình đoàn kết) — loài kiến \"nghĩ\" đến cộng đồng, cùng nhau vác thức ăn. | Gương Hán-Việt | nghĩ trong 蚂蚁 (mã nghĩ — con kiến), 蚁穴 (nghĩ huyệt — tổ kiến) | Mở khoá kiến thức | Biết 蚁 (nghĩ) mở khoá: 蚂蚁 (con kiến), 蚁巢 (tổ kiến), 蚁穴溃堤 (tổ kiến làm vỡ đê — lỗ nhỏ gây hoạ lớn).", "Tự nguyên_Xie": "蚁 là dạng giản thể của 蟻, vốn gồm 虫 (trùng, côn trùng) làm biểu nghĩa và 義 (nghĩa) làm biểu âm — chữ hình thanh. Phần biểu âm giản thể hoá từ 義 thành 义. Nghĩa duy nhất là con kiến. Chưa có nguồn học thuật chi tiết hơn về chữ giản thể này. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con kiến", "Hạng Tần Suất (Jun Da)": "2512.0", "Tần Suất % (Jun Da)": "98.5100996714", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 义", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫义", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "义", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蚁", "Unihan_Traditional (Chữ Phồn thể)": "蟻", "Pinyin_Xie": "yǐ", "Âm Hán Việt_Xie": "nghị", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ con kiến hoặc dùng để tự xưng một cách khiêm tốn thời xưa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('壶', '{"9000": "2513.0", "Chữ Trung Quốc": "壶", "Bộ thủ & thành phần_Xie": "Bộ thủ | 士 | Số nét | 10 | nét | 士 | sĩ | biểu hình | phần đầu (vốn là 大 — cái nắp) | 冖 | mịch | biểu hình | phần thân (mái che, miệng bình) | 业 | nghiệp | biểu hình (do giản hoá) | phần đáy (vốn là phần thân bình) | 壶 là dạng giản thể của 壺. Chữ phồn 壺 vốn là tượng hình một cái bình rượu cổ — phần trên có nắp, thân tròn dưới có chân. Trong giản thể đã rút gọn nhưng vẫn gợi hình cái bình.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hồ\": 壶 vẽ hình cái bình rượu có nắp + thân + chân, đúng nghĩa ''bình, ấm, hồ'' trong 水壶 (ấm đun nước), 茶壶 (ấm trà). | Gương Hán-Việt | ''hồ'' trong ''hồ lô'', ''tửu hồ'' (bình rượu) | Mở khoá kiến thức | Nắm 壶 mở khoá loạt từ HSK 5-7: 壶, 水壶.", "Tự nguyên_Xie": "Kim văn | Tiểu triện | Theo Wiktionary, 壶 là giản thể của 壺. Chữ phồn 壺 trong giáp cốt và kim văn vẽ một cái bình rượu cổ — có nắp, thân tròn và chân đỡ. Là chữ tượng hình. Nghĩa gốc ''bình, ấm, hồ lô'' giữ nguyên trong 壶, 水壶, 茶壶. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái hồ lô; một loại quả như quả bầu", "Hạng Tần Suất (Jun Da)": "2513.0", "Tần Suất % (Jun Da)": "98.5119869707", "GavinGrover_Once (Chiết tự trực tiếp)": "士 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱士", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "壶", "Unihan_Traditional (Chữ Phồn thể)": "壺", "Pinyin_Xie": "hú", "Âm Hán Việt_Xie": "hồ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Lượng từ | 量词 | Thường làm danh từ chỉ cái ấm, cái bình hoặc làm lượng từ cho chất lỏng đựng trong ấm. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Lượng từ | 量词 | Đứng giữa số từ (hoặc 这/那) và danh từ: 一杯茶, 这本书. Mỗi danh từ đi với lượng từ riêng; 个 là lượng từ dùng chung phổ biến nhất.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | Từ đơn | Từ vựng HSK 5: ấm | / | hú | / | ấm | Xuất hiện trong lộ trình | New HSK | New HSK 6 | · | Thức ăn và đồ uống | HSK | HSK 5 | · | Ngôi nhà và cuộc sống hàng ngày", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('怡', '{"9000": "2514.0", "Chữ Trung Quốc": "怡", "Bộ thủ & thành phần_Xie": "Bộ thủ | 心 | Số nét | 8 | nét | 忄 | tâm | biểu nghĩa | tâm hồn, cảm xúc | 台 | đài | biểu âm | đài, sân khấu | 怡 = 忄 (Tâm, biểu nghĩa: tim/cảm xúc) + 台 (Đài, biểu âm); chữ hình thanh. Bộ 忄 xác định liên quan đến cảm xúc/tâm trạng, 台 cho âm yí gần với di.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"di\": Tâm (忄) lên Đài (台) thưởng ngoạn — Di dưỡng tâm hồn, lòng Di nhiên tự đắc khi được làm điều mình thích. | Gương Hán-Việt | di trong \"di dưỡng\", \"di nhiên\" — vui vẻ thoải mái, nuôi dưỡng tinh thần | Mở khoá kiến thức | Biết 怡 mở khoá: 怡然自得 (vui vẻ tự tại), 心旷神怡 (thư thái tâm hồn), 怡情 (di dưỡng tình cảm).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Theo Wiktionary, 怡 là chữ hình thanh: 心/忄 (tâm, tim) biểu nghĩa, 台 biểu âm. Nghĩa: vui vẻ, dễ chịu, hòa nhã — trạng thái tâm lý thoải mái, không gượng ép. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "vui vẻ, dễ dãi", "Hạng Tần Suất (Jun Da)": "2514.0", "Tần Suất % (Jun Da)": "98.5138727197", "GavinGrover_Once (Chiết tự trực tiếp)": "忄 + 台", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰忄台", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "台", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "忄", "Unihan_Simplified (Chữ Giản thể)": "怡", "Unihan_Traditional (Chữ Phồn thể)": "怡", "Pinyin_Xie": "yí", "Âm Hán Việt_Xie": "di", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường làm tính từ chỉ trạng thái vui vẻ, thư thái, thường dùng trong văn viết. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('渗', '{"9000": "2515.0", "Chữ Trung Quốc": "渗", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 11 | nét | 氵 | thuỷ | biểu nghĩa | nước — liên quan đến chất lỏng | 参 | tam | biểu âm | tham gia — góp âm shèn | 渗 = 氵(Thuỷ, biểu nghĩa: nước) + 参 (Tam, biểu âm: góp âm shèn). Chữ hình thanh — 氵chỉ nghĩa liên quan đến chất lỏng di chuyển chậm, 参 góp âm. Hình ảnh nước thấm dần qua vật liệu từng chút một.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sấm\": 氵(nước) lặng lẽ 参 (thâm nhập, tham gia) vào vật liệu — thấm từng chút như mưa sấm ngấm vào đất. | Gương Hán-Việt | sấm trong 渗透 (sấm thấu — thẩm thấu), 渗漏 (sấm lậu — rò rỉ) | Mở khoá kiến thức | Biết 渗 (sấm) mở khoá: 渗透 (thẩm thấu, xâm nhập), 渗漏 (rò rỉ), 渗水 (thấm nước), 渗入 (thấm vào).", "Tự nguyên_Xie": "Tiểu triện | 渗 là chữ hình thanh: 氵(thuỷ, nước) làm biểu nghĩa, 参 (tam/sâm) làm biểu âm. Nghĩa gốc là nước thấm qua, rỉ ra từng giọt. Trong tiếng Trung hiện đại, 渗透 (thẩm thấu) dùng rộng rãi cả nghĩa vật lý (thẩm thấu qua màng) lẫn nghĩa bóng (xâm nhập tư tưởng). Wiktionary không cung cấp phân tích hình thành chữ chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chảy, rỉ ra", "Hạng Tần Suất (Jun Da)": "2515.0", "Tần Suất % (Jun Da)": "98.5157574351", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 参", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵参", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "参", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "渗", "Unihan_Traditional (Chữ Phồn thể)": "滲", "Pinyin_Xie": "shèn", "Âm Hán Việt_Xie": "sấm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ chỉ sự thẩm thấu, rò rỉ của chất lỏng qua các khe hở. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | shèn | / | thấm, ngấm | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Từ III", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('秃', '{"9000": "2516.0", "Chữ Trung Quốc": "秃", "Bộ thủ & thành phần_Xie": "Bộ thủ | 禾 | Số nét | 7 | nét | 毛 | mao | biểu nghĩa | lông tóc — nay viết thành 禾 do biến dạng | 儿 | nhân | biểu nghĩa | người | 秃 là chữ hội ý, nguyên dạng 禿 = 毛 (mao, tóc) + 儿 (nhân, người): hình ảnh người không có tóc. Về sau, 毛 bị viết sai thành 禾 (hoà, lúa) trong dạng hiện đại 秃. Cấu trúc hội ý rõ theo phân tích Wiktionary: tóc + người = đầu trọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thốc\": người 儿 (nhân) không còn tóc 毛 (mao, nay viết thành 禾) — đầu thốc trọc, bóng láng như quả bí. | Gương Hán-Việt | thốc trong 秃头 (thốc đầu — đầu hói), 光秃 (quang thốc — trơ trụi) | Mở khoá kiến thức | Biết 秃 (thốc) mở khoá: 秃头 (đầu hói), 光秃秃 (trơ trụi không còn gì), 秃鹰 (diều hâu đầu trọc).", "Tự nguyên_Xie": "Đại triện | Theo Wiktionary, 秃 (dạng phồn thể 禿) là chữ hội ý: 毛 (mao, tóc) + 儿 (nhân, người) → người không có tóc, đầu trọc. Sau này, phần 毛 bị viết sai thành 禾 (hoà) trong quá trình viết tay. Nghĩa gốc là đầu hói, trọc, mở rộng sang núi trơ trụi, bút mòn. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "trọc, trụi, hói; cùn, cụt", "Hạng Tần Suất (Jun Da)": "2516.0", "Tần Suất % (Jun Da)": "98.517638533", "GavinGrover_Once (Chiết tự trực tiếp)": "禾 + 几", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱禾几", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "几", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "禾", "Unihan_Simplified (Chữ Giản thể)": "秃", "Unihan_Traditional (Chữ Phồn thể)": "禿", "Pinyin_Xie": "tū", "Âm Hán Việt_Xie": "ngốc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này thường làm định ngữ đứng trước danh từ để chỉ trạng thái trọc hoặc hói. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | tū | / | hói | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Vẻ bề ngoài | HSK | HSK 6 | · | Cơ thể và ngoại hình II", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('迦', '{"9000": "2517.0", "Chữ Trung Quốc": "迦", "Bộ thủ & thành phần_Xie": "Bộ thủ | 辵 | Số nét | 8 | nét | 辶 | sước | biểu nghĩa | đi, di chuyển (bộ thủ đi đường) | 加 | gia | biểu âm | thêm vào | 迦 = 辶 (Sước, biểu nghĩa: đi đường) + 加 (Gia, biểu âm); chữ hình thanh. Bộ 辶 xác định liên quan đến di chuyển/đường đi, 加 cho âm jiā gần với ca.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ca\": bộ Đường (辶) với âm Gia (加) — chữ Ca dùng phiên âm tiếng Phạn, mở ra thế giới Thích Ca Mâu Ni. | Gương Hán-Việt | ca trong \"Thích Ca\" (釋迦), \"Ca Diếp\" — phiên âm Phật giáo từ tiếng Phạn | Mở khoá kiến thức | Biết 迦 mở khoá: 释迦牟尼 (Thích Ca Mâu Ni), 迦叶 (Ca Diếp), 迦南 (Canaan — đất hứa).", "Tự nguyên_Xie": "Theo Wiktionary, 迦 là chữ hình thanh: 辵/辶 (sước, đi) biểu nghĩa, 加 biểu âm. Dùng chủ yếu làm ký tự phiên âm Phạn ngữ và tên người/nơi trong Phật giáo: 释迦 (Thích Ca), 迦叶 (Ca Diếp), 迦南 (Canaan). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: thích ca 釋迦)", "Hạng Tần Suất (Jun Da)": "2517.0", "Tần Suất % (Jun Da)": "98.5195180805", "GavinGrover_Once (Chiết tự trực tiếp)": "辶 + 加", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴辶加", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "加", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "辶", "Unihan_Simplified (Chữ Giản thể)": "迦", "Unihan_Traditional (Chữ Phồn thể)": "迦", "Pinyin_Xie": "jiā", "Âm Hán Việt_Xie": "già", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này chủ yếu dùng trong các danh từ riêng phiên âm từ tiếng Phạn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('旱', '{"9000": "2518.0", "Chữ Trung Quốc": "旱", "Bộ thủ & thành phần_Xie": "Bộ thủ | 日 | Số nét | 7 | nét | 日 | nhật | biểu nghĩa | mặt trời — nắng nóng | 干 | can | biểu âm | khô, can — góp âm hàn | 旱 = 日 (Nhật, biểu nghĩa: mặt trời) + 干 (Can, biểu âm: góp âm hàn/hạn). Chữ hình thanh — 日 gợi nghĩa nắng nóng gây khô hạn, 干 góp âm. Hình ảnh mặt trời thiêu đốt khiến đất đai cạn khô.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hạn\": 日 (mặt trời) cháy bỏng trên 干 (can — cái cọc khô) — đất đai hạn hán, cạn kiệt nước. | Gương Hán-Việt | hạn trong 干旱 (can hạn — khô hạn), 旱灾 (hạn tai — thiên tai hạn hán) | Mở khoá kiến thức | Biết 旱 (hạn) mở khoá: 干旱 (khô hạn), 旱灾 (thiên tai hạn hán), 旱地 (đất cạn — không dùng tưới), 旱季 (mùa khô).", "Tự nguyên_Xie": "Tiểu triện | 旱 gồm 日 (nhật, mặt trời) và 干 (can). Cấu trúc hình thanh — 日 biểu nghĩa cho nắng, khô hạn; 干 góp âm gần hàn. Wiktionary chỉ ghi {{Han etym}} không có phân tích chi tiết. Nghĩa gốc là hạn hán, đất khô không có mưa. Chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1089.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Nhật (072) Can (051)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Nhật (số 072 - mặt trời/chỉ ý) ở trên chữ Can (số 051 - khô cạn/chỉ âm). Lâu ngày không mưa, chỉ có nắng chói chang. Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Can chỉ âm, bộ Nhật chỉ ý. Hạn là lâu ngày không mưa, khô hạn (hạn hán, đại hạn).", "Nghĩa Tiếng Việt_Xie": "nắng; hạn hán, cạn khô", "Hạng Tần Suất (Jun Da)": "2518.0", "Tần Suất % (Jun Da)": "98.5213971112", "GavinGrover_Once (Chiết tự trực tiếp)": "日 + 干", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱日干", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "干", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "日", "Unihan_Simplified (Chữ Giản thể)": "旱", "Unihan_Traditional (Chữ Phồn thể)": "旱", "Pinyin_Xie": "hàn", "Âm Hán Việt_Xie": "hạn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Thường làm định ngữ bổ nghĩa cho danh từ hoặc tự bản thân làm danh từ chỉ thiên tai. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | hàn | / | hạn hán | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Sự kiện tự nhiên II", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('哟', '{"9000": "2519.0", "Chữ Trung Quốc": "哟", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 9 | nét | 口 | khẩu | biểu nghĩa | miệng, âm thanh phát ra | 约 | yêu | biểu âm | ước, xấp xỉ — cho âm | 哟 = 口 (Khẩu, biểu nghĩa: miệng) + 约 (Yêu, biểu âm); chữ hình thanh. Bộ khẩu chỉ đây là âm thanh phát ra từ miệng, phần 约 cho âm gần. Không có nguồn Wiktionary cấu trúc rõ ràng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ôi\": miệng (口) bật ra tiếng \"ôi!\" — thán từ ngạc nhiên hoặc cổ vũ dô-ta. | Gương Hán-Việt | ôi trong \"ôi thôi\" — thán từ tiếc nuối | Mở khoá kiến thức | Biết 哟 mở khoá cách dùng trợ từ cảm thán cuối câu trong hội thoại tiếng Trung thường ngày.", "Tự nguyên_Xie": "哟 là chữ hình thanh: bộ 口 (khẩu) chỉ âm thanh miệng, phần 约 (yêu) cho âm. Chữ dùng để ghi thán từ hoặc trợ từ cuối câu, không có giáp cốt hay kim văn. Chưa có nguồn học thuật Wiktionary cụ thể về nguyên hình. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nào, này (trợ từ); dô hò, dô ta (trợ từ); ối chao, chao ôi", "Hạng Tần Suất (Jun Da)": "2519.0", "Tần Suất % (Jun Da)": "98.5232756252", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 约", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口约", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "约", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "哟", "Unihan_Traditional (Chữ Phồn thể)": "喲", "Pinyin_Xie": "yō", "Âm Hán Việt_Xie": "yêu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Trợ từ | 助词 | Thán từ | 叹词 | Thường đứng cuối câu làm trợ từ ngữ khí hoặc đứng đầu câu làm thán từ. | Trợ từ | 助词 | Không mang nghĩa riêng, gắn vào câu để đánh dấu ngữ pháp hoặc ngữ khí: 的 / 地 / 得 (kết cấu), 了 / 着 / 过 (thể), 吗 / 呢 / 吧 (nghi vấn, ngữ khí). | Thán từ | 叹词 | Bộc lộ cảm xúc hoặc dùng để gọi đáp: 啊, 哦, 喂. Đứng tách riêng ở đầu câu, không làm thành phần câu.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('咸', '{"9000": "2520.0", "Chữ Trung Quốc": "咸", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 9 | nét | 戌 | tuất | biểu nghĩa | vốn là một loại vũ khí (rìu lớn) | 口 | khẩu | biểu nghĩa | miệng | 咸 = 戌 (Tuất, rìu) + 口 (Khẩu, miệng). Chữ hội ý cổ: dùng rìu uy hiếp miệng — buộc mọi người phải đồng lòng. Nghĩa gốc ''tất cả, đều''. Trong giản thể, 咸 còn gánh thêm nghĩa ''mặn'' (vốn là 鹹).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt ''Hàm'': rìu (戌) đặt trước miệng (口) — ai cũng phải im đều — nghĩa cổ ''tất cả''. Trong giản thể còn nghĩa ''mặn'' (gánh từ 鹹). | Gương Hán-Việt | ''Hàm'' trong hàm sủng (cùng được sủng ái); cũng dùng cho ''mặn'' (vị mặn). Cùng âm Hán-Việt với ''hàm'' (含, ngậm). | Mở khoá kiến thức | Biết 咸 mở khóa nghĩa ''mặn'' (味咸, có vị mặn); mở rộng đến nghĩa cổ ''tất cả'' trong văn ngôn.", "Tự nguyên_Xie": "Giáp cốt văn | Kim văn | Tiểu triện | Theo Wiktionary, 咸 là chữ hội ý: 戌 (vũ khí) + 口. Nghĩa cổ ''tất cả, đều''. Trong bản giản thể, 咸 hợp nhất với 鹹 (mặn), nên có thêm nghĩa ''có vị mặn''. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1675.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Tuất (062) Khẩu (030)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Khẩu (số 030 - cái miệng/ 口) nằm trong lòng chữ Tuất (số 062 - vũ khí/ 戌). Mọi người đều há miệng hô to, tay cầm vũ khí bảo vệ đất nước. Giải thích sự chuyển ý: Đây là chữ Hội ý. Hàm mang nghĩa là phổ cập, tất cả, đều đồng lòng cùng nhau (hàm tụ). (Chữ này trong Giản thể còn được dùng thay cho chữ Hàm 鹹 - mặn).", "Nghĩa Tiếng Việt_Xie": "đều (chỉ tất cả đều sao đó)", "Hạng Tần Suất (Jun Da)": "2520.0", "Tần Suất % (Jun Da)": "98.5251500049", "GavinGrover_Once (Chiết tự trực tiếp)": "戊 + 𠮛", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿵ (Bao quanh phía trên)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴戊𠮛", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "𠮛", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "戊", "Unihan_Simplified (Chữ Giản thể)": "咸", "Unihan_Traditional (Chữ Phồn thể)": "咸", "Pinyin_Xie": "xián", "Âm Hán Việt_Xie": "hàm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Phó từ | 副词 | Tính từ | 形容词 | Thường làm phó từ đứng trước động từ trong văn cổ hoặc làm tính từ chỉ vị mặn. | Phó từ | 副词 | Bổ nghĩa cho động từ hoặc tính từ và luôn đứng TRƯỚC chúng — 都是, 很好. Không đứng sau như tiếng Việt và không bổ nghĩa cho danh từ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | xián | / | mặn | Xuất hiện trong lộ trình | New HSK | New HSK 4 | · | Thức ăn và đồ uống | HSK | HSK 4 | · | Thức ăn và đồ uống", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('焉', '{"9000": "2521.0", "Chữ Trung Quốc": "焉", "Bộ thủ & thành phần_Xie": "Bộ thủ | 火 | Số nét | 11 | nét | 正 | chinh | biểu nghĩa | ngay thẳng, chính xác | 灬 | hoả | biểu nghĩa | lửa — phần đuôi chim | 焉 = 正 (Chinh, có thể biểu nghĩa) + phần đuôi lửa 灬 (Hoả); theo Wiktionary có thể là hình thanh: 正 biểu nghĩa, 於 biểu âm (nay mất). Chữ gốc mô tả một loài chim (chim yên), sau dùng làm hư từ. Chữ hình thanh với cấu trúc đã biến đổi.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"yên\": chim yên đứng ngay ngắn (正) trên đống lửa (灬) — bình thản như câu hỏi \"vậy sao?\" trong văn ngôn. | Gương Hán-Việt | yên trong \"yên hà\" (khói sương) — chữ dùng nhiều trong văn ngôn cổ | Mở khoá kiến thức | Biết 焉 mở khoá hàng loạt hư từ văn ngôn: \"焉知\" (sao biết được), \"心不在焉\" (lơ đãng).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 焉 có thể là hình thanh (psc): 正 biểu nghĩa, 於 biểu âm. Tuy nhiên hình dạng thực tế trong tiểu triện gợi hình ảnh con chim với đuôi lửa 灬. Nghĩa gốc là tên một loài chim; về sau được mượn dùng làm hư từ chỉ nơi chốn hoặc trạng thái (\"ở đó\", \"như thế\"). Dạng tiểu triện còn lưu. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chim yên; sao, thế nào (trợ từ)", "Hạng Tần Suất (Jun Da)": "2521.0", "Tần Suất % (Jun Da)": "98.5270238678", "GavinGrover_Once (Chiết tự trực tiếp)": "正 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱正", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "焉", "Unihan_Traditional (Chữ Phồn thể)": "焉", "Pinyin_Xie": "yān", "Âm Hán Việt_Xie": "yên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Đại từ | 代词 | Phó từ | 副词 | Trợ từ | 助词 | Thường dùng làm đại từ nghi vấn hoặc trợ từ ngữ khí ở cuối câu trong văn ngôn. | Đại từ | 代词 | Thay cho người hoặc vật đã nhắc tới (我, 这, 谁). Dùng đúng ở vị trí của danh từ. Chỉ người thì thêm 们 để thành số nhiều: 我们. | Phó từ | 副词 | Bổ nghĩa cho động từ hoặc tính từ và luôn đứng TRƯỚC chúng — 都是, 很好. Không đứng sau như tiếng Việt và không bổ nghĩa cho danh từ. | Trợ từ | 助词 | Không mang nghĩa riêng, gắn vào câu để đánh dấu ngữ pháp hoặc ngữ khí: 的 / 地 / 得 (kết cấu), 了 / 着 / 过 (thể), 吗 / 呢 / 吧 (nghi vấn, ngữ khí).", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('谴', '{"9000": "2522.0", "Chữ Trung Quốc": "谴", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 15 | nét | 讠 | ngôn | biểu nghĩa | lời nói — dùng ngôn từ để trách phạt | 遣 | khiển | biểu âm | phái đi, sai khiến — góp âm khiển | 谴 = 讠(Ngôn, biểu nghĩa: lời nói) + 遣 (Khiển, biểu âm). Chữ hình thanh — 讠chỉ nghĩa dùng lời nói để trách phạt, 遣 góp âm khiển. Dạng giản thể của 譴, thay 訁bằng 讠.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khiển\": 讠(lời nói) + 遣 (khiển phái) — dùng lời khiển trách, quở phạt mạnh mẽ. | Gương Hán-Việt | khiển trong 谴责 (khiển trách — lên án), 谴怒 (khiển nộ — phẫn nộ) | Mở khoá kiến thức | Biết 谴 (khiển) mở khoá: 谴责 (khiển trách, lên án — từ quan trọng HSK 6), 受到谴责 (bị lên án).", "Tự nguyên_Xie": "Tiểu triện | 谴 là dạng giản thể của 譴 (訁+ 遣). Cấu trúc hình thanh: 訁(ngôn, lời nói) là biểu nghĩa — dùng lời để khiển trách, 遣 (khiển) là biểu âm. Nghĩa gốc là dùng lời nói trách phạt, lên án. Wiktionary chỉ ghi là dạng giản thể, không có phân tích sâu hơn. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "khiển trách, lên án", "Hạng Tần Suất (Jun Da)": "2522.0", "Tần Suất % (Jun Da)": "98.5288941132", "GavinGrover_Once (Chiết tự trực tiếp)": "讠 + 遣", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰讠遣", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "遣", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "讠", "Unihan_Simplified (Chữ Giản thể)": "谴", "Unihan_Traditional (Chữ Phồn thể)": "譴", "Pinyin_Xie": "qiǎn", "Âm Hán Việt_Xie": "khiển", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ vị ngữ trong câu để biểu thị sự trách phạt. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('宛', '{"9000": "2523.0", "Chữ Trung Quốc": "宛", "Bộ thủ & thành phần_Xie": "Bộ thủ | 宀 | Số nét | 8 | nét | 宀 | miên | biểu nghĩa | mái nhà, nơi ở | 夗 | uyển | biểu âm | nằm nghiêng — cho âm | 宛 = 宀 (Miên, biểu nghĩa: mái nhà) + 夗 (Uyển, biểu âm); chữ hình thanh. Nghĩa gốc có thể liên quan đến nhà ở (đọc như 館 thời cổ), về sau mang nghĩa \"uyển chuyển, nhỏ nhắn, dường như\".", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"uyển\": dưới mái nhà (宀) có người nằm nghiêng (夗) — uyển chuyển, mềm mại như dáng nằm nghỉ ngơi. | Gương Hán-Việt | uyển trong \"uyển chuyển\" — mềm mại, linh hoạt | Mở khoá kiến thức | Biết 宛 mở khoá: 宛如 (như thể), 宛转 (uyển chuyển), 腕 (cổ tay — cùng âm).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Theo Wiktionary, 宛 là hình thanh: 宀 (miên) biểu nghĩa nơi ở, 夗 (uyển) biểu âm. Nghĩa gốc có thể là \"nhà ở\" — thời cổ đọc gần với 館 (quán, nhà trọ). Về sau nghĩa chuyển sang \"uyển chuyển, mềm mại, dường như\". Dạng tiểu triện và lục thư thông còn lưu qua hanziyuan. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "530.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Miên (19) Tiết (529) Tịch (53)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Miên (số 19 - mái nhà) che chữ Uyển (gồm Tịch số 53 và Tiết số 529). Kẻ làm quan có tiết tháo (Tiết), đêm (Tịch) nằm lo cho dân cho nước trong nhà (Miên) thì trở mình trằn trọc hết nghiêng bên này đến bên kia. Giải thích sự chuyển ý: Việc nằm trở mình trằn trọc tạo ra hình dáng cong vẹo, uốn khúc. Từ đó mang ý nghĩa uốn lượn, uyển chuyển (Uyển).", "Nghĩa Tiếng Việt_Xie": "nhỏ bé", "Hạng Tần Suất (Jun Da)": "2523.0", "Tần Suất % (Jun Da)": "98.5307643586", "GavinGrover_Once (Chiết tự trực tiếp)": "宀 + 夗", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱宀夗", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "夗", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "宀", "Unihan_Simplified (Chữ Giản thể)": "宛", "Unihan_Traditional (Chữ Phồn thể)": "宛", "Pinyin_Xie": "wǎn", "Âm Hán Việt_Xie": "uyển", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Phó từ | 副词 | Tính từ | 形容词 | Thường dùng làm phó từ đứng trước động từ để biểu thị sự tương tự. | Phó từ | 副词 | Bổ nghĩa cho động từ hoặc tính từ và luôn đứng TRƯỚC chúng — 都是, 很好. Không đứng sau như tiếng Việt và không bổ nghĩa cho danh từ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('稻', '{"9000": "2524.0", "Chữ Trung Quốc": "稻", "Bộ thủ & thành phần_Xie": "Bộ thủ | 禾 | Số nét | 15 | nét | 禾 | hoà | biểu nghĩa | cây lúa, ngũ cốc | 舀 | yểu | biểu âm | múc, vét — góp âm dào | 稻 = 禾 (Hoà, biểu nghĩa: cây lúa) + 舀 (Yểu, biểu âm: góp âm dào). Chữ hình thanh — 禾 chỉ rõ loại cây ngũ cốc, 舀 góp âm. Xuất hiện từ giáp cốt văn, là một trong những chữ lúa cổ nhất.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đạo\": 禾 (lúa) ghép với 舀 (múc) — hình ảnh múc thóc đạo từ cánh đồng lúa nước vào bồ. | Gương Hán-Việt | đạo trong 水稻 (thuỷ đạo — lúa nước), 稻谷 (đạo cốc — thóc gạo) | Mở khoá kiến thức | Biết 稻 (đạo) mở khoá: 水稻 (lúa nước), 稻谷 (thóc), 稻草 (rơm rạ), 稻田 (ruộng lúa).", "Tự nguyên_Xie": "Giáp cốt văn | Kim văn | Tiểu triện | Lục thư thông | Theo Wiktionary, 稻 là chữ hình thanh: 禾 (hoà, cây lúa/ngũ cốc) làm biểu nghĩa, 舀 (yểu) làm biểu âm. Chữ xuất hiện sớm trong giáp cốt văn, phản ánh vai trò quan trọng của lúa nước trong nền văn minh Hoa Hạ. Nghĩa chuyên chỉ lúa nước (Oryza sativa), phân biệt với 黍 (kê) và 麦 (lúa mì). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1098.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Hòa (115) Yểu (1097)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Hòa (số 115 - cây lúa) ở bên trái chữ Yểu (số 1097 - múc nước/chỉ âm). Lúa rất cần nước, phải luôn múc nước tưới cho nó mới tươi tốt. Giải thích sự chuyển ý: Đây là chữ Hình thanh (hoặc Hội ý). Chữ Yểu chỉ âm, bộ Hòa chỉ ý. Đạo là lúa nước.", "Nghĩa Tiếng Việt_Xie": "lúa nước, lúa gié", "Hạng Tần Suất (Jun Da)": "2524.0", "Tần Suất % (Jun Da)": "98.5326284026", "GavinGrover_Once (Chiết tự trực tiếp)": "禾 + 舀", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰禾舀", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "舀", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "禾", "Unihan_Simplified (Chữ Giản thể)": "稻", "Unihan_Traditional (Chữ Phồn thể)": "稻", "Pinyin_Xie": "dào", "Âm Hán Việt_Xie": "đạo", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ cây lúa nước, đóng vai trò chủ ngữ hoặc tân ngữ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('铸', '{"9000": "2525.0", "Chữ Trung Quốc": "铸", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 12 | nét | 钅 | kim | biểu nghĩa | kim loại — liên quan đến luyện kim | 寿 | thọ | biểu âm | thọ — góp âm zhù | 铸 là dạng giản thể của 鑄. Cấu trúc: 钅(kim, biểu nghĩa: kim loại) + 寿 (thọ, biểu âm: góp âm zhù). Chữ hình thanh — 钅chỉ nghĩa nấu chảy kim loại, 寿 góp âm. Dạng phồn thể 鑄 dùng 釒thay 钅.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chú\": 钅(kim loại) nấu chảy trong khuôn 寿 (thọ — hình cái bình lâu bền) — đúc chú ra đồ vật bền chắc. | Gương Hán-Việt | chú trong 铸造 (chú tạo — đúc), 铸成 (chú thành — đúc nên) | Mở khoá kiến thức | Biết 铸 (chú) mở khoá: 铸造 (đúc kim loại), 铸成大错 (đúc nên lỗi lầm lớn), 铸铁 (gang đúc).", "Tự nguyên_Xie": "Kim văn | 铸 là dạng giản thể của 鑄, chữ hình thanh: 釒(kim, kim loại) là biểu nghĩa, 壽 (thọ) là biểu âm. Nghĩa gốc là đúc kim loại vào khuôn (bronze casting). Xuất hiện trong kim văn — thời đồ đồng, kỹ thuật đúc kim loại rất phát triển. Wiktionary chỉ ghi là dạng giản thể, không có phân tích sâu hơn. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đúc", "Hạng Tần Suất (Jun Da)": "2525.0", "Tần Suất % (Jun Da)": "98.5344908962", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 寿", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅寿", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "寿", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "铸", "Unihan_Traditional (Chữ Phồn thể)": "鑄", "Pinyin_Xie": "zhù", "Âm Hán Việt_Xie": "chú", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ vị ngữ mang tân ngữ chỉ sản phẩm kim loại được đúc. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('锻', '{"9000": "2526.0", "Chữ Trung Quốc": "锻", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 14 | nét | 钅 | kim | biểu nghĩa | kim loại (giản hoá từ 釒) | 段 | đoạn | biểu âm | đoạn, khúc | 锻 = 钅 (Kim, biểu nghĩa: kim loại) + 段 (Đoạn, biểu âm). Đây là dạng giản thể của 鍛: nung kim loại rồi đập rèn — nghĩa ''rèn, luyện''. 段 vừa cho âm vừa gợi ý chia khúc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt ''Đoán'' (锻) nghĩa là ''rèn, luyện''. Nhớ: 钅 (kim loại) bên trái + 段 (đoạn) bên phải — đập kim loại thành từng ''đoạn'', đó là ''đoán'' (rèn). | Gương Hán-Việt | Chữ 锻 (Đoán) trong tiếng Việt: ''đoán luyện / rèn luyện'', ''tôi đoán'' (luyện kim loại). Khác âm với ''đoán'' (đoán xem — 猜). | Mở khoá kiến thức | Nắm 锻 mở khoá cụm 锻炼 (đoán luyện — rèn luyện, cực kỳ phổ biến) và 锻打 (rèn đập).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 锻 là dạng giản thể của 鍛, đổi 釒 → 钅. Bản phồn 鍛 là chữ hình thanh: 金 (kim loại) biểu nghĩa, 段 biểu âm. Nghĩa ''rèn, đập kim loại nóng đỏ''. Sau mở rộng nghĩa trừu tượng ''rèn luyện (cơ thể, ý chí)''. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "rèn", "Hạng Tần Suất (Jun Da)": "2526.0", "Tần Suất % (Jun Da)": "98.5363492555", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 段", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅段", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "段", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "锻", "Unihan_Traditional (Chữ Phồn thể)": "鍛", "Pinyin_Xie": "duàn", "Âm Hán Việt_Xie": "đoạn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ kết hợp với các từ khác để chỉ hoạt động rèn luyện. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('伽', '{"9000": "2527.0", "Chữ Trung Quốc": "伽", "Bộ thủ & thành phần_Xie": "Bộ thủ | 人 | Số nét | 7 | nét | 亻 | nhân | biểu nghĩa | người | 加 | gia | biểu âm | thêm vào — cho âm | 伽 = 亻 (Nhân, biểu nghĩa: người) + 加 (Gia, biểu âm); chữ hình thanh. Chữ dùng chủ yếu để phiên âm tiếng Phạn (gà-lam 伽藍 = vihāra, tu viện Phật giáo).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"già\": người (亻) thêm vào (加) âm \"già\" — chữ phiên âm tiếng Phạn, nhớ qua \"già lam\" là chùa chiền. | Gương Hán-Việt | già trong \"già lam\" (伽藍) — tu viện Phật giáo | Mở khoá kiến thức | Biết 伽 mở khoá loạt từ Phật giáo gốc Phạn: 伽藍 (già lam), 伽陀 (kệ tụng).", "Tự nguyên_Xie": "Theo Wiktionary, 伽 là hình thanh: 人 (nhân) biểu nghĩa người, 加 (gia) biểu âm. Chữ được tạo ra để phiên âm từ tiếng Phạn, đặc biệt trong từ Phật giáo 伽藍 (già-lam, tức vihāra — tu viện). Đây là chữ phiên âm thuần tuý, không có hình ảnh cổ. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: già lam 伽藍)", "Hạng Tần Suất (Jun Da)": "2527.0", "Tần Suất % (Jun Da)": "98.5382076149", "GavinGrover_Once (Chiết tự trực tiếp)": "亻 + 加", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰亻加", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "加", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "亻", "Unihan_Simplified (Chữ Giản thể)": "伽", "Unihan_Traditional (Chữ Phồn thể)": "伽", "Pinyin_Xie": "jiā", "Âm Hán Việt_Xie": "già", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng trong các từ ghép phiên âm Phật giáo để chỉ chùa chiền. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('詹', '{"9000": "2528.0", "Chữ Trung Quốc": "詹", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 13 | nét | 厂 | hán | biểu nghĩa | vách đá dốc — phần trên | 儿 | nhân | biểu nghĩa | người | 言 | ngôn | biểu nghĩa | lời nói | 詹 = 言 (Ngôn, biểu nghĩa: lời nói) + 八 (hơi thở từ miệng) + 厃 (nguy hiểm); chữ hội ý. Theo Wiktionary: kết hợp lời nói (言), hơi thở (八) và nguy cấp (厃) để diễn đạt ý \"nói quá nhiều, nói liên hồi\". Phần trên gốc không có 厃, sau thêm vào.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chiêm\": miệng (言) không ngừng tuôn lời như hơi thở (八) dưới mái nguy (厃) — chiêm ngôn, nói dài không dứt. | Gương Hán-Việt | chiêm trong \"chiêm ngưỡng\" — nhưng 詹 chủ yếu dùng làm họ người | Mở khoá kiến thức | Biết 詹 mở khoá họ Chiêm/Zhan: 詹天佑 (kỹ sư đường sắt nổi tiếng), và từ 詹詹 (lắm lời).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 詹 là hội ý (ic): gồm 言 (ngôn, lời nói), 八 (hơi thở từ miệng, phân chia) và 厃 (nguy hiểm) — ý chỉ người nói quá nhiều, lời tuôn ra như nguy cơ. Trong bản gốc cổ hơn, thành phần 厃 chưa có. Dạng tiểu triện còn lưu. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1116.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Nhân (019) Hãn (018) Bát (012) Ngôn (149)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Gồm các chữ Nhân (số 019/dạng ⺈), Hãn (số 018), Bát (số 012) và Ngôn (số 149). Người đứng chênh vênh trên sườn núi khiến ở dưới luôn miệng khấn vái. Giải thích sự chuyển ý: Đây là chữ Hội ý. Chiêm là nói nhiều, dông dài. Chiêm cũng là một họ của người (họ Chiêm).", "Nghĩa Tiếng Việt_Xie": "giúp; nói nhiều", "Hạng Tần Suất (Jun Da)": "2528.0", "Tần Suất % (Jun Da)": "98.5400654575", "GavinGrover_Once (Chiết tự trực tiếp)": "⺈ + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺈", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "詹", "Unihan_Traditional (Chữ Phồn thể)": "詹", "Pinyin_Xie": "zhān", "Âm Hán Việt_Xie": "chiêm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này thường dùng làm họ người hoặc làm động từ với nghĩa nói nhiều trong văn ngôn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('毙', '{"9000": "2529.0", "Chữ Trung Quốc": "毙", "Bộ thủ & thành phần_Xie": "Bộ thủ | 比 | Số nét | 10 | nét | 比 | tỷ | biểu nghĩa | so sánh, cạnh nhau | 死 | tử | biểu nghĩa | chết | 毙 = 比 (Tỷ) + 死 (Tử); chữ này là dạng giản thể của 斃. Theo nguồn, 毙 giản hoá từ 斃 (thay 敝 bằng 比). Hai người (比) cùng ngã xuống chết (死) — hình ảnh gục ngã hàng loạt. Cấu trúc gợi nghĩa hội ý nhưng nguồn Wiktionary không xác nhận rõ lscodes.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tễ\": hai người (比) cùng ngã chết (死) — tễ mạng, bị bắn hạ gục tại chỗ. | Gương Hán-Việt | tễ trong \"tễ mạng\" — chết bạo, bị xử bắn | Mở khoá kiến thức | Biết 毙 mở khoá: 枪毙 (xử bắn), 击毙 (bắn hạ) — nhóm từ về cái chết bạo lực.", "Tự nguyên_Xie": "Kim văn | 毙 là dạng giản thể của 斃 (tễ), thay thành phần 敝 bằng 比 để đơn giản hoá. Chữ phồn thể 斃 mang nghĩa \"ngã xuống chết giữa đường, chết bạo\". Dạng kim văn của chữ này đã được lưu. Về mặt cấu tạo: 比 (hai người cạnh nhau) + 死 (chết) — gợi cảnh người gục ngã hàng loạt. Chưa có nguồn học thuật Wiktionary xác nhận rõ lscodes cho dạng giản. | Suy từ bộ phận cấu thành · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ngã sấp, chết giữa đường; xử bắn, bắn chết", "Hạng Tần Suất (Jun Da)": "2529.0", "Tần Suất % (Jun Da)": "98.5419196825", "GavinGrover_Once (Chiết tự trực tiếp)": "比 + 死", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱比死", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "死", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "比", "Unihan_Simplified (Chữ Giản thể)": "毙", "Unihan_Traditional (Chữ Phồn thể)": "斃", "Pinyin_Xie": "bì", "Âm Hán Việt_Xie": "tễ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng sau tân ngữ hoặc làm vị ngữ biểu thị việc bị bắn chết hoặc tử vong. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('恍', '{"9000": "2530.0", "Chữ Trung Quốc": "恍", "Bộ thủ & thành phần_Xie": "Bộ thủ | 心 | Số nét | 9 | nét | 忄 | tâm | biểu nghĩa | tâm — liên quan đến trạng thái tâm trí | 光 | quang | biểu âm | ánh sáng — góp âm huǎng | 恍 = 忄(Tâm, biểu nghĩa: tâm trí) + 光 (Quang, biểu âm: góp âm huǎng). Chữ hình thanh — 忄chỉ nghĩa trạng thái tâm lý, 光 góp âm. Chữ này thay thế chữ 怳 từ Trung Cổ Hán ngữ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hoảng\": 忄(tâm) lóa vì 光 (quang — ánh sáng chói) — trạng thái hoảng hốt, hoảng loạn, mơ hồ như vừa tỉnh giấc. | Gương Hán-Việt | hoảng trong 恍然大悟 (hoảng nhiên đại ngộ), 恍惚 (hoảng hốt) | Mở khoá kiến thức | Biết 恍 (hoảng) mở khoá: 恍然大悟 (bỗng nhiên hiểu ra), 恍惚 (ngơ ngẩn, mơ hồ), 恍如隔世 (dường như cách một kiếp).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Theo Wiktionary, 恍 là chữ hình thanh: 心 (tâm, tâm trí) viết tắt thành 忄làm biểu nghĩa, 光 (quang) làm biểu âm. Chữ này thay thế dạng cũ 怳 từ cuối thời Trung Cổ Hán ngữ. Nghĩa gốc là mơ hồ, dường như, không rõ ràng — trạng thái tâm trí chợt sáng chợt tối như ánh sáng nhấp nháy. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: hoảng hốt 恍忽)", "Hạng Tần Suất (Jun Da)": "2530.0", "Tần Suất % (Jun Da)": "98.5437718404", "GavinGrover_Once (Chiết tự trực tiếp)": "忄 + 光", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰忄光", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "光", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "忄", "Unihan_Simplified (Chữ Giản thể)": "恍", "Unihan_Traditional (Chữ Phồn thể)": "怳", "Pinyin_Xie": "huǎng", "Âm Hán Việt_Xie": "hoảng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Phó từ | 副词 | Thường làm tính từ trong từ ghép hoặc làm phó từ đứng trước động từ để chỉ sự bừng tỉnh, chợt nhận ra. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Phó từ | 副词 | Bổ nghĩa cho động từ hoặc tính từ và luôn đứng TRƯỚC chúng — 都是, 很好. Không đứng sau như tiếng Việt và không bổ nghĩa cho danh từ.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('贬', '{"9000": "2531.0", "Chữ Trung Quốc": "贬", "Bộ thủ & thành phần_Xie": "Bộ thủ | 貝 | Số nét | 8 | nét | 贝 | bối | biểu nghĩa | vỏ sò — tiền tệ, giá trị | 乏 | phạp | biểu âm | thiếu thốn — góp âm biǎn | 贬 = 贝 (Bối, biểu nghĩa: vỏ sò/tiền) + 乏 (Phạp, biểu âm: góp âm biǎn). Chữ hình thanh — 贝 chỉ nghĩa liên quan đến giá trị, tiền tệ bị giảm, 乏 góp âm. Dạng giản thể của 貶.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"biếm\": 贝 (bối — đồng tiền) bị 乏 (phạp — thiếu, kém) — giá trị bị biếm xuống, bị phá giá. | Gương Hán-Việt | biếm trong 贬低 (biếm đê — hạ thấp), 贬义 (biếm nghĩa — nghĩa tiêu cực) | Mở khoá kiến thức | Biết 贬 (biếm) mở khoá: 贬低 (hạ thấp, coi thường), 贬义 (nghĩa tiêu cực), 贬值 (phá giá), 褒贬 (khen chê).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Theo Wiktionary, 贬 (dạng phồn thể 貶) là chữ hình thanh: 貝 (bối, vỏ sò/tiền) làm biểu nghĩa — liên quan đến giảm giá trị; 乏 (phạp) làm biểu âm. Nghĩa gốc là hạ giảm (giá trị, địa vị), sau mở rộng sang chê bai, phê phán. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "biếm xuống, giảm xuống; giáng chức; chê bai", "Hạng Tần Suất (Jun Da)": "2531.0", "Tần Suất % (Jun Da)": "98.5456219312", "GavinGrover_Once (Chiết tự trực tiếp)": "贝 + 乏", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰贝乏", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "乏", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "贝", "Unihan_Simplified (Chữ Giản thể)": "贬", "Unihan_Traditional (Chữ Phồn thể)": "貶", "Pinyin_Xie": "biǎn", "Âm Hán Việt_Xie": "biếm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước tân ngữ để chỉ việc hạ thấp giá trị hoặc giáng chức ai đó. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('烛', '{"9000": "2532.0", "Chữ Trung Quốc": "烛", "Bộ thủ & thành phần_Xie": "Bộ thủ | 火 | Số nét | 10 | nét | 火 | hoả | biểu nghĩa | lửa — ngọn lửa soi sáng | 虫 | trùng | biểu âm | côn trùng — góp âm zhú | 烛 = 火 (Hoả, biểu nghĩa: lửa) + 虫 (Trùng, biểu âm: góp âm zhú). Chữ hình thanh — 火 chỉ nghĩa ánh sáng, ngọn lửa; 虫 góp âm. Dạng giản thể của 燭. Wiktionary chỉ ghi {{Han etym}} không có phân tích chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chúc\": 火 (hoả — lửa) cháy trên cây như 虫 (trùng — con sâu) đứng thẳng — cây nến chúc sáng trong đêm tối. | Gương Hán-Việt | chúc trong 蜡烛 (lạp chúc — nến sáp), 烛光 (chúc quang — ánh nến) | Mở khoá kiến thức | Biết 烛 (chúc) mở khoá: 蜡烛 (nến sáp), 烛光 (ánh nến), 烛台 (đế nến), 春烛 (nến mùa xuân).", "Tự nguyên_Xie": "烛 (dạng phồn thể 燭) gồm 火 (hoả, lửa) làm biểu nghĩa và 虫 (trùng) làm biểu âm — chữ hình thanh. Nghĩa gốc là ngọn đuốc, nến soi sáng. Wiktionary không cung cấp phân tích chi tiết về nguồn gốc chữ này. Chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ngọn đuốc", "Hạng Tần Suất (Jun Da)": "2532.0", "Tần Suất % (Jun Da)": "98.5474709884", "GavinGrover_Once (Chiết tự trực tiếp)": "火 + 虫", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰火虫", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "虫", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "火", "Unihan_Simplified (Chữ Giản thể)": "烛", "Unihan_Traditional (Chữ Phồn thể)": "燭", "Pinyin_Xie": "zhú", "Âm Hán Việt_Xie": "chúc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường làm danh từ chỉ cây nến hoặc làm động từ với nghĩa soi chiếu trong văn cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('骇', '{"9000": "2533.0", "Chữ Trung Quốc": "骇", "Bộ thủ & thành phần_Xie": "Bộ thủ | 馬 | Số nét | 9 | nét | 马 | mã | biểu nghĩa | ngựa | 亥 | hợi | biểu âm | giờ Hợi — cho âm hài | 骇 = 马 (Mã, biểu nghĩa: ngựa) + 亥 (Hợi, biểu âm); chữ hình thanh. Bộ mã chỉ ngựa hoảng sợ phi loạn, phần 亥 cho âm. Phồn thể là 駭.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hãi\": ngựa (马) hoảng đến giờ Hợi (亥) — hãi hùng, kinh hãi như ngựa phi điên cuồng ban đêm. | Gương Hán-Việt | hãi trong \"kinh hãi\" — sợ hãi cực độ | Mở khoá kiến thức | Biết 骇 mở khoá: 骇人听闻 (kinh thiên động địa), 惊骇 (kinh hãi) — nhóm từ về sự kinh sợ.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Theo Wiktionary, 骇 (phồn thể 駭) là hình thanh: 馬 (mã) biểu nghĩa ngựa, 亥 (hợi) biểu âm. Nghĩa gốc là ngựa hoảng loạn, từ đó mở rộng sang \"kinh hãi, hoảng sợ\". Dạng tiểu triện và lục thư thông còn lưu qua hanziyuan. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "giật mình", "Hạng Tần Suất (Jun Da)": "2533.0", "Tần Suất % (Jun Da)": "98.5493195289", "GavinGrover_Once (Chiết tự trực tiếp)": "马 + 亥", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰马亥", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "亥", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "马", "Unihan_Simplified (Chữ Giản thể)": "骇", "Unihan_Traditional (Chữ Phồn thể)": "駭", "Pinyin_Xie": "hài", "Âm Hán Việt_Xie": "hãi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Thường làm động từ hoặc tính từ đứng trước danh từ để biểu thị trạng thái hoảng sợ, kinh ngạc. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('芯', '{"9000": "2534.0", "Chữ Trung Quốc": "芯", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 7 | nét | 艹 | thảo | biểu nghĩa | cỏ, thực vật | 心 | tâm | biểu âm | trái tim — cho âm xīn | 芯 = 艹 (Thảo, biểu nghĩa: thực vật) + 心 (Tâm, biểu âm); chữ hình thanh. Bộ thảo chỉ nguồn gốc thực vật (bấc đèn từ cây cỏ), phần tâm cho âm xīn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tâm\": cây cỏ (艹) có cái tâm (心) bên trong — bấc đèn là lõi cây, sau mở rộng sang chip điện tử. | Gương Hán-Việt | tâm trong \"đăng tâm\" (灯芯) — bấc đèn | Mở khoá kiến thức | Biết 芯 mở khoá: 芯片 (chip), 笔芯 (ruột bút), 电池芯 (lõi pin) — nhóm từ kỹ thuật hiện đại.", "Tự nguyên_Xie": "Theo Wiktionary, 芯 là hình thanh: 艸 (thảo) biểu nghĩa cỏ/thực vật, 心 (tâm) biểu âm. Nghĩa gốc là phần lõi cây lõi bấc (juncus effusus) dùng làm bấc đèn. Mở rộng sang \"lõi, phần trung tâm\" — nay dùng nhiều trong kỹ thuật (芯片 = chip, mạch tích hợp). Không có hình ảnh cổ. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bấc đèn; (xem: đăng tâm 燈芯,灯芯)", "Hạng Tần Suất (Jun Da)": "2534.0", "Tần Suất % (Jun Da)": "98.5511634182", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 心", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹心", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "心", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "芯", "Unihan_Traditional (Chữ Phồn thể)": "芯", "Pinyin_Xie": "xīn", "Âm Hán Việt_Xie": "tâm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng sau các danh từ khác để chỉ phần lõi hoặc bộ phận trung tâm của vật thể. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('汁', '{"9000": "2535.0", "Chữ Trung Quốc": "汁", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 5 | nét | 氵 | thuỷ | biểu nghĩa | chất lỏng | 十 | thập | biểu âm | gợi âm zhī | 汁 = 氵 (Thuỷ, biểu nghĩa: chất lỏng) + 十 (Thập, biểu âm); chữ hình thanh (ls=psc). Một loại chất lỏng — ''nước, dịch, nước ép''.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trấp\" (cũng đọc ''chấp''): 氵 (nước) + 十 (thập) — nước ép từ vật, ấy là ''trấp/nước''; nhớ 果汁 (quả trấp = nước ép trái cây), 橙汁 (cam trấp = nước cam). | Gương Hán-Việt | ''trấp/chấp'' trong từ vựng nhà nông cổ; nghĩa hiện đại = ''nước ép, nước ngọt từ trái cây'' | Mở khoá kiến thức | Biết 汁 là mở 果汁, 橙汁, 原汁原味 — nhóm danh từ về đồ uống HSK 4-6.", "Tự nguyên_Xie": "Theo Wiktionary, 汁 là chữ hình thanh: 水 (氵, biểu nghĩa: chất lỏng) ghép với 十 (biểu âm). Nghĩa: chất lỏng từ một vật ép ra — nước ép, dịch, mật, nhựa cây. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "hoà hợp; giúp đỡ", "Hạng Tần Suất (Jun Da)": "2535.0", "Tần Suất % (Jun Da)": "98.5530052404", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 十", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵十", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "十", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "汁", "Unihan_Traditional (Chữ Phồn thể)": "汁", "Pinyin_Xie": "zhī", "Âm Hán Việt_Xie": "trấp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng sau tên các loại quả hoặc rau củ để chỉ nước ép của chúng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | zhī | / | nước ép | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Thực phẩm II", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('桓', '{"9000": "2536.0", "Chữ Trung Quốc": "桓", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 10 | nét | 木 | mộc | biểu nghĩa | cây, gỗ | 亘 | biểu âm | kéo dài liên tục — cho âm hoán | 桓 = 木 (Mộc, biểu nghĩa: cây) + 亘 (không có Hán-Việt riêng, biểu âm); chữ hình thanh. Bộ mộc chỉ đây là loại cây hoặc vật bằng gỗ, phần 亘 cho âm huán/hoán.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hoàn\": cây gỗ (木) chạy dài không dứt (亘) — cột hoàn tiêu đứng sừng sững trên con đường cổ. | Gương Hán-Việt | hoàn trong \"bàn hoàn\" (盘桓) — lưu lại, quanh quẩn | Mở khoá kiến thức | Biết 桓 mở khoá: 盘桓 (bàn hoàn — lưu lại loanh quanh), họ Hoàn, tên riêng lịch sử như 齐桓公.", "Tự nguyên_Xie": "Kim văn | Tiểu triện | Theo Wiktionary, 桓 là hình thanh: 木 (mộc) biểu nghĩa cây, 亘 biểu âm. Nghĩa gốc là cây xà phòng Trung Quốc (Sapindus mukorossi) và cột gỗ dùng làm biển chỉ đường thời cổ. Dạng kim văn và tiểu triện còn lưu. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái nêu (cắm trên mồ mả); cây hoàn", "Hạng Tần Suất (Jun Da)": "2536.0", "Tần Suất % (Jun Da)": "98.5548403445", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 亘", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木亘", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "亘", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "桓", "Unihan_Traditional (Chữ Phồn thể)": "桓", "Pinyin_Xie": "huán", "Âm Hán Việt_Xie": "hoàn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Thường làm danh từ chỉ một loại cây hoặc làm tính từ biểu thị sự to lớn, uy vũ trong văn cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('坊', '{"9000": "2537.0", "Chữ Trung Quốc": "坊", "Bộ thủ & thành phần_Xie": "Bộ thủ | 土 | Số nét | 7 | nét | 土 | thổ | biểu nghĩa | đất, nền đất | 方 | phương | biểu âm | phương hướng — cho âm fāng | 坊 = 土 (Thổ, biểu nghĩa: đất) + 方 (Phương, biểu âm); chữ hình thanh. Bộ thổ chỉ đây là khu đất, phần phương cho âm. Nghĩa là phường hội, khu dân cư, cũng có nghĩa cái đê ngăn nước.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phường\": mảnh đất (土) theo hướng (方) — phường hội, khu dân cư được quy hoạch theo ô vuông. | Gương Hán-Việt | phường trong \"phường hội\" — tổ chức nghề nghiệp thời phong kiến | Mở khoá kiến thức | Biết 坊 mở khoá: 坊间 (trong dân gian), 街坊 (hàng xóm), 磨坊 (cối xay), 作坊 (xưởng thủ công).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Theo Wiktionary, 坊 là hình thanh: 土 (thổ) biểu nghĩa đất, 方 (phương) biểu âm. Nghĩa gốc liên quan đến khu đất, phường dân cư đô thị thời cổ. Dạng tiểu triện và lục thư thông còn lưu qua hanziyuan. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "phường hội; cái đê ngăn nước", "Hạng Tần Suất (Jun Da)": "2537.0", "Tần Suất % (Jun Da)": "98.5566728645", "GavinGrover_Once (Chiết tự trực tiếp)": "土 + 方", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰土方", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "方", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "土", "Unihan_Simplified (Chữ Giản thể)": "坊", "Unihan_Traditional (Chữ Phồn thể)": "坊", "Pinyin_Xie": "fāng", "Âm Hán Việt_Xie": "phường", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng sau tên địa danh để chỉ khu phố hoặc đứng sau tên sản phẩm để chỉ cửa hàng, xưởng sản xuất. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('驴', '{"9000": "2538.0", "Chữ Trung Quốc": "驴", "Bộ thủ & thành phần_Xie": "Bộ thủ | 馬 | Số nét | 7 | nét | 马 | mã | biểu nghĩa | ngựa, họ ngựa | 户 | hộ | biểu âm | cửa — cho âm lǘ gần | 驴 = 马 (Mã, biểu nghĩa: ngựa) + 户 (Hộ, biểu âm); chữ hình thanh. Phồn thể 驢 dùng 盧 (lô) làm âm phù rõ hơn. Dạng giản thể thay 盧 bằng 户. Bộ mã chỉ đây là loài vật họ ngựa.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lư\": ngựa (马) của nhà (户) — con lừa kéo xe cho gia đình nghèo, tai to hơn ngựa thật. | Gương Hán-Việt | lư trong \"lư mã\" — con lừa, loài vật thồ hàng | Mở khoá kiến thức | Biết 驴 mở khoá: 驴车 (xe lừa), 毛驴 (lừa nhỏ), 驴友 (bạn đồng hành phượt — chơi chữ với 旅友).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 驢 (phồn thể) là hình thanh: 馬 (mã) biểu nghĩa ngựa, 盧 (lô) biểu âm. Dạng giản thể 驴 thay 盧 bằng 户 để đơn giản hoá. Con lừa là loài vật họ ngựa, tai to, sức bền cao, dùng để thồ hàng. Dạng tiểu triện còn lưu. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con lừa", "Hạng Tần Suất (Jun Da)": "2538.0", "Tần Suất % (Jun Da)": "98.5584981496", "GavinGrover_Once (Chiết tự trực tiếp)": "马 + 户", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰马户", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "户", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "马", "Unihan_Simplified (Chữ Giản thể)": "驴", "Unihan_Traditional (Chữ Phồn thể)": "馿", "Pinyin_Xie": "lǘ", "Âm Hán Việt_Xie": "lư", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng độc lập hoặc kết hợp với lượng từ chỉ con vật. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('朽', '{"9000": "2539.0", "Chữ Trung Quốc": "朽", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 6 | nét | 木 | mộc | biểu nghĩa | gỗ, cây — chất liệu bị mục | 丂 | khảo | biểu âm | uốn cong — góp âm xiǔ | 朽 = 木 (Mộc, biểu nghĩa: gỗ) + 丂 (Khảo, biểu âm: góp âm xiǔ). Chữ hình thanh — 木 chỉ nghĩa gỗ mục nát, 丂 góp âm. Xuất hiện trong kim văn và tiểu triện, là chữ cổ chỉ tình trạng gỗ bị mục.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hủ\": 木 (mộc — gỗ) bị 丂 (khảo — uốn cong, biến dạng) — gỗ hủ mục, cong vênh theo năm tháng. | Gương Hán-Việt | hủ trong 腐朽 (hủ hủ — thối rữa), 不朽 (bất hủ — bất tử) | Mở khoá kiến thức | Biết 朽 (hủ) mở khoá: 腐朽 (thối rữa, mục nát), 不朽 (bất hủ, bất tử), 永垂不朽 (lưu danh muôn đời).", "Tự nguyên_Xie": "Kim văn | Tiểu triện | Lục thư thông | Theo Wiktionary, 朽 là chữ hình thanh: 木 (mộc, gỗ/cây) làm biểu nghĩa, 丂 (khảo) làm biểu âm. Nghĩa gốc là gỗ mục nát, thối rữa. Mở rộng sang nghĩa cũ kỹ, suy tàn. Thành ngữ 不朽 (bất hủ) — không bị mục nát — có nghĩa bất tử, lưu danh muôn đời. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "gỗ mục", "Hạng Tần Suất (Jun Da)": "2539.0", "Tần Suất % (Jun Da)": "98.560320334", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 丂", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木丂", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "丂", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "朽", "Unihan_Traditional (Chữ Phồn thể)": "朽", "Pinyin_Xie": "xiǔ", "Âm Hán Việt_Xie": "hủ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường làm tính từ đứng trước danh từ hoặc làm vị ngữ để miêu tả trạng thái mục nát, suy tàn. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('靖', '{"9000": "2540.0", "Chữ Trung Quốc": "靖", "Bộ thủ & thành phần_Xie": "Bộ thủ | 青 | Số nét | 13 | nét | 立 | lập | biểu nghĩa | đứng vững, thiết lập | 青 | thanh | biểu âm | xanh — cho âm jìng | 靖 = 立 (Lập, biểu nghĩa: đứng vững) + 青 (Thanh, biểu âm); chữ hình thanh. Bộ lập gợi ý thiết lập trật tự, bình định; phần thanh cho âm jìng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tĩnh\": đứng vững (立) dưới bầu trời xanh (青) — tĩnh lặng, bình yên sau khi dẹp loạn. | Gương Hán-Việt | tĩnh trong \"tĩnh bình\" — bình định, dẹp yên | Mở khoá kiến thức | Biết 靖 mở khoá: 靖国 (Tĩnh Quốc — tên đền gây tranh cãi ở Nhật), 绥靖 (tuy tĩnh — chính sách nhượng bộ), tên riêng Văn Tĩnh.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 靖 là hình thanh: 立 (lập, đứng vững, thiết lập) biểu nghĩa, 青 (thanh) biểu âm. Nghĩa là bình định, yên ổn, thường dùng trong văn ngôn và tên riêng. Dạng tiểu triện còn lưu. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "yên lặng; yên ổn", "Hạng Tần Suất (Jun Da)": "2540.0", "Tần Suất % (Jun Da)": "98.5621399345", "GavinGrover_Once (Chiết tự trực tiếp)": "立 + 青", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰立青", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "青", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "立", "Unihan_Simplified (Chữ Giản thể)": "靖", "Unihan_Traditional (Chữ Phồn thể)": "靖", "Pinyin_Xie": "jìng", "Âm Hán Việt_Xie": "tĩnh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Chữ này làm tính từ chỉ sự yên ổn hoặc làm động từ với nghĩa dẹp loạn, bình định. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('佣', '{"9000": "2541.0", "Chữ Trung Quốc": "佣", "Bộ thủ & thành phần_Xie": "Bộ thủ | 人 | Số nét | 7 | nét | 亻 | nhân | biểu nghĩa | người — chỉ người làm thuê | 用 | dụng | biểu âm | dùng — góp âm yōng | 佣 = 亻(Nhân, biểu nghĩa: người) + 用 (Dụng, biểu âm: góp âm yōng). Chữ hình thanh — 亻chỉ người đi làm thuê, 用 góp âm. Wiktionary chỉ ghi {{Han etym}} không có phân tích chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"dong\": 亻(người) được 用 (dụng — sử dụng) cho công việc — người dong (làm thuê), được thuê làm việc. | Gương Hán-Việt | dong trong 雇佣 (cố dong — thuê mướn), 佣金 (dong kim — hoa hồng) | Mở khoá kiến thức | Biết 佣 (dong) mở khoá: 雇佣 (thuê mướn), 佣金 (tiền hoa hồng), 佣工 (công nhân làm thuê).", "Tự nguyên_Xie": "Tiểu triện | 佣 gồm 亻(nhân, người) làm biểu nghĩa và 用 (dụng) làm biểu âm — chữ hình thanh. Nghĩa gốc là người đi làm thuê, lao động. Mở rộng sang nghĩa tiền hoa hồng (commission). Wiktionary không cung cấp phân tích chi tiết. Chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "làm thuê", "Hạng Tần Suất (Jun Da)": "2541.0", "Tần Suất % (Jun Da)": "98.5639574678", "GavinGrover_Once (Chiết tự trực tiếp)": "亻 + 用", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰亻用", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "用", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "亻", "Unihan_Simplified (Chữ Giản thể)": "佣", "Unihan_Traditional (Chữ Phồn thể)": "佣", "Pinyin_Xie": "yōng", "Âm Hán Việt_Xie": "dong, dung", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường làm động từ chỉ việc thuê mướn hoặc làm danh từ chỉ tiền công xá. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('汝', '{"9000": "2542.0", "Chữ Trung Quốc": "汝", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 6 | nét | 氵 | thuỷ | biểu nghĩa | nước, sông | 女 | nữ | biểu âm | người nữ — cho âm rǔ | 汝 = 氵(Thuỷ, biểu nghĩa: nước) + 女 (Nữ, biểu âm); chữ hình thanh. Nghĩa gốc là tên sông Nhữ (Nhữ Hà), sau mượn dùng làm đại từ nhân xưng ngôi hai (mày, ngươi) trong văn ngôn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nhữ\": nước (氵) chảy như người nữ (女) — dòng sông Nhữ, sau mượn âm làm đại từ \"mày\" trong thơ văn cổ. | Gương Hán-Việt | nhữ trong \"nhữ đẳng\" (汝等) — các ngươi, chúng mày (văn ngôn) | Mở khoá kiến thức | Biết 汝 mở khoá loạt đại từ văn ngôn: 汝 (ngươi), 余/吾 (ta) — cặp xưng hô cổ điển trong thơ Đường, Tống.", "Tự nguyên_Xie": "Theo Wiktionary, 汝 là hình thanh: 水 (thuỷ) biểu nghĩa sông/nước, 女 (nữ) biểu âm. Nghĩa gốc là tên sông Nhữ Hà (汝河) ở Hà Nam, Trung Quốc. Về sau được mượn dùng làm đại từ nhân xưng ngôi hai (\"ngươi, mày\") trong văn ngôn cổ điển, tương đương 你 trong hiện đại. Không có hình ảnh cổ. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1373.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thủy (082) Nữ (038)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Thủy (số 082 - nước/ 氵/chỉ ý) ở bên trái bộ Nữ (số 038 - phụ nữ/chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Bộ Nữ chỉ âm, bộ Thủy chỉ ý. Nhữ vốn là tên một con sông (sông Nhữ). Sau này được mượn làm đại từ nhân xưng ngôi thứ hai (mày, ngươi, anh, chị).", "Nghĩa Tiếng Việt_Xie": "mày (đại từ nhân xưng ngôi thứ hai); sông Nhữ", "Hạng Tần Suất (Jun Da)": "2542.0", "Tần Suất % (Jun Da)": "98.5657677661", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 女", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵女", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "女", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "汝", "Unihan_Traditional (Chữ Phồn thể)": "汝", "Pinyin_Xie": "rǔ", "Âm Hán Việt_Xie": "nhữ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Đại từ | 代词 | Danh từ | 名词 | Dùng làm đại từ nhân xưng ngôi thứ hai trong văn ngôn hoặc làm danh từ riêng chỉ tên sông. | Đại từ | 代词 | Thay cho người hoặc vật đã nhắc tới (我, 这, 谁). Dùng đúng ở vị trí của danh từ. Chỉ người thì thêm 们 để thành số nhiều: 我们. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('碌', '{"9000": "2543.0", "Chữ Trung Quốc": "碌", "Bộ thủ & thành phần_Xie": "Bộ thủ | 石 | Số nét | 13 | nét | 石 | thạch | biểu nghĩa | đá — gợi thứ gồ ghề, sần sùi | 录 | lục | biểu âm | ghi chép — góp âm lù | 碌 = 石 (Thạch, biểu nghĩa: đá) + 录 (Lục, biểu âm: góp âm lù). Chữ hình thanh — 石 gợi bề mặt đá gồ ghề, không bằng phẳng; 录 góp âm. Nghĩa mở rộng sang tầm thường, bận rộn (忙碌).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lựu\": 石 (thạch — đá) lăn lộn 录 (lục — ghi dấu) — viên đá lựu lăn mãi, bận rộn, tầm thường không ngơi tay. | Gương Hán-Việt | lựu trong 忙碌 (mang lựu — bận rộn), 碌碌 (lựu lựu — tầm thường) | Mở khoá kiến thức | Biết 碌 (lựu) mở khoá: 忙碌 (bận rộn), 碌碌无为 (sống tầm thường vô nghĩa), 庸碌 (tầm thường).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Theo Wiktionary, 碌 là chữ hình thanh: 石 (thạch, đá) làm biểu nghĩa — gợi bề mặt sần sùi, gồ ghề; 彔 (lục) làm biểu âm. Nghĩa gốc là gồ ghề, không bằng phẳng. Mở rộng sang tầm thường (碌碌无为 — sống tầm thường vô nghĩa) và bận rộn (忙碌). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: lục lục 碌碌)", "Hạng Tần Suất (Jun Da)": "2543.0", "Tần Suất % (Jun Da)": "98.5675749637", "GavinGrover_Once (Chiết tự trực tiếp)": "石 + 录", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰石录", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "录", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "石", "Unihan_Simplified (Chữ Giản thể)": "碌", "Unihan_Traditional (Chữ Phồn thể)": "碌", "Pinyin_Xie": "lù", "Âm Hán Việt_Xie": "lục, lựu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường dùng làm tính từ trong từ ghép để tả trạng thái bận rộn hoặc tầm thường. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('迄', '{"9000": "2544.0", "Chữ Trung Quốc": "迄", "Bộ thủ & thành phần_Xie": "Bộ thủ | 辵 | Số nét | 6 | nét | 辶 | sước | biểu nghĩa | bước đi, di chuyển — đến tận | 乞 | khất | biểu âm | cầu xin — góp âm qì | 迄 = 辶(Sước, biểu nghĩa: đi, di chuyển) + 乞 (Khất, biểu âm: góp âm qì). Chữ hình thanh — 辶gợi nghĩa đi đến tận nơi, 乞 góp âm. Nghĩa là \"cho đến\", dùng chủ yếu trong 迄今 (cho đến nay).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hất\": 辶(đi đến) mãi như 乞 (khất — kẻ ăn xin) lang thang — hất đến tận bây giờ, từ xưa đến nay không ngừng. | Gương Hán-Việt | hất trong 迄今 (hất kim — cho đến nay), 迄今为止 (hất kim vi chỉ) | Mở khoá kiến thức | Biết 迄 (hất) mở khoá: 迄今 (cho đến nay), 迄今为止 (từ xưa đến nay, cho đến nay).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 迄 là chữ hình thanh: 辵 (sước, bước đi) viết tắt thành 辶làm biểu nghĩa — đi đến tận điểm cuối; 乞 (khất) làm biểu âm. Nghĩa là đến tận, cho đến. Dùng nhiều trong văn viết trang trọng. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đến; bèn", "Hạng Tần Suất (Jun Da)": "2544.0", "Tần Suất % (Jun Da)": "98.5693816446", "GavinGrover_Once (Chiết tự trực tiếp)": "辶 + 乞", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴辶乞", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "乞", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "辶", "Unihan_Simplified (Chữ Giản thể)": "迄", "Unihan_Traditional (Chữ Phồn thể)": "迄", "Pinyin_Xie": "qì", "Âm Hán Việt_Xie": "hất", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Giới từ | 介词 | Động từ | 动词 | Thường làm giới từ biểu thị giới hạn thời gian, đứng trước danh từ chỉ thời gian. | Giới từ | 介词 | Ghép với danh từ hoặc đại từ thành cụm chỉ nơi chốn, thời gian, đối tượng: 在家, 跟他. Cụm giới từ đứng TRƯỚC động từ — 我在家吃饭 — ngược với trật tự tiếng Việt. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('冀', '{"9000": "2545.0", "Chữ Trung Quốc": "冀", "Bộ thủ & thành phần_Xie": "Bộ thủ | 八 | Số nét | 16 | nét | 北 | bắc | biểu nghĩa | phương bắc | 異 | dị | biểu âm | khác lạ — cho âm jì | 冀 = 北 (Bắc, biểu nghĩa) + 異 (Dị, biểu âm); chữ hình thanh. Nghĩa gốc là tên vùng đất Ký (phía bắc — tỉnh Hà Bắc ngày nay), sau mở rộng sang nghĩa \"hy vọng, mong muốn\" trong văn ngôn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ký\": đất phương bắc (北) của vùng lạ (異) — đất Ký Châu, và lòng hy vọng hướng về phương bắc xa xôi. | Gương Hán-Việt | ký trong \"ký vọng\" (冀望) — hy vọng, trông mong | Mở khoá kiến thức | Biết 冀 mở khoá: 冀望 (kỳ vọng), 希冀 (hy ký — mong mỏi), 冀州 (Ký Châu — tên lịch sử tỉnh Hà Bắc).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 冀 là hình thanh: 北 (bắc) biểu nghĩa, 異 (dị) biểu âm. Chữ này là tên cổ của vùng đất Ký Châu (冀州), nay tương ứng tỉnh Hà Bắc (河北). Nghĩa phái sinh \"hy vọng, trông mong\" xuất hiện sớm trong văn ngôn. Dạng tiểu triện còn lưu. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "hy vọng; mong muốn; mong mỏi; kỳ vọng; Ký (tên khác của tỉnh Hà Bắc, Trung Quốc); ký; họ Ký", "Hạng Tần Suất (Jun Da)": "2545.0", "Tần Suất % (Jun Da)": "98.5711836743", "GavinGrover_Once (Chiết tự trực tiếp)": "北 + 異", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱北異", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "異", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "北", "Unihan_Simplified (Chữ Giản thể)": "冀", "Unihan_Traditional (Chữ Phồn thể)": "冀", "Pinyin_Xie": "jì", "Âm Hán Việt_Xie": "kí", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Làm động từ thể hiện sự mong mỏi hoặc làm danh từ chỉ tên viết tắt của tỉnh Hà Bắc. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('荆', '{"9000": "2546.0", "Chữ Trung Quốc": "荆", "Bộ thủ & thành phần_Xie": "Bộ thủ | 刀 | Số nét | 9 | nét | 艹 | thảo | biểu nghĩa | cỏ cây | 开 | khai | biểu nghĩa | mở, khai | 刂 | đao | biểu nghĩa | dao, lưỡi cắt | 荆 = 艹 (Thảo) + 开 (Khai) + 刂 (Đao); cấu trúc không có lscodes rõ ràng từ Wiktionary. Hình ảnh gợi lên bụi cây gai (艹) có lưỡi sắc (刂) — cây kinh, loài cây có gai dùng làm roi hoặc hàng rào. Kim văn và lục thư thông còn lưu nhiều dạng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"kinh\": bụi cây gai (艹刂) — kinh gai, roi kinh mà người vợ cầm khi chồng về muộn (điển tích \"kinh thoa bố quần\"). | Gương Hán-Việt | kinh trong \"kinh gai\" — bụi cây gai, khó đi qua | Mở khoá kiến thức | Biết 荆 mở khoá: 荆棘 (kinh cức — bụi gai), 荆州 (Kinh Châu — địa danh lịch sử), 负荆请罪 (cõng roi đến tạ tội — điển tích nổi tiếng).", "Tự nguyên_Xie": "Kim văn | Lục thư thông | 荆 (phồn thể 荊) là tên loài cây gai (cây kinh, Vitex negundo), dùng làm roi hoặc bó củi. Wiktionary ghi {{Han etym}} nhưng không cung cấp phân tích lscodes cụ thể. Kim văn có nhiều dạng khác nhau, lục thư thông lưu nhiều biến thể. Cũng là tên cổ của vùng đất Kinh Châu (荆州). Chưa có nguồn học thuật xác nhận rõ hội ý hay hình thanh. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cây kinh; cái roi; châu Kinh (Trung Quốc)", "Hạng Tần Suất (Jun Da)": "2546.0", "Tần Suất % (Jun Da)": "98.5729815698", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 刑", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰艹刑", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "刑", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "荆", "Unihan_Traditional (Chữ Phồn thể)": "荊", "Pinyin_Xie": "jīng", "Âm Hán Việt_Xie": "kinh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ một loại cây bụi có gai hoặc tượng trưng cho sự nghèo khó, thô sơ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('崔', '{"9000": "2547.0", "Chữ Trung Quốc": "崔", "Bộ thủ & thành phần_Xie": "Bộ thủ | 山 | Số nét | 11 | nét | 山 | sơn | biểu nghĩa | núi, cao | 隹 | chuy | biểu âm | chim đuôi ngắn — cho âm cuī | 崔 = 山 (Sơn, biểu nghĩa: núi cao) + 隹 (Chuy, biểu âm); chữ hình thanh. Bộ sơn chỉ sự cao lớn, chót vót; phần 隹 cho âm cuī. Dùng chủ yếu làm họ người và tính từ \"cao ngất\" trong thơ văn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thôi\": núi (山) có chim (隹) đậu trên đỉnh — cao chót vót như họ Thôi, một trong những họ lớn của Trung Quốc. | Gương Hán-Việt | thôi trong \"thôi nguy\" (崔嵬) — núi cao đứng sừng sững | Mở khoá kiến thức | Biết 崔 mở khoá: họ Thôi (崔), 崔嵬 (thôi nguy — cao ngất), tên Daniel C. Tsui (Thôi Kỳ — Nobel Vật lý).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Theo Wiktionary, 崔 là hình thanh: 山 (sơn) biểu nghĩa núi, 隹 (chuy) biểu âm. Nghĩa là cao chót vót, ngất ngưởng. Dùng nhiều làm họ người (họ Thôi). Dạng tiểu triện và nhiều dạng lục thư thông còn lưu qua hanziyuan. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cao lớn", "Hạng Tần Suất (Jun Da)": "2547.0", "Tần Suất % (Jun Da)": "98.5747779149", "GavinGrover_Once (Chiết tự trực tiếp)": "山 + 隹", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱山隹", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "隹", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "山", "Unihan_Simplified (Chữ Giản thể)": "崔", "Unihan_Traditional (Chữ Phồn thể)": "崔", "Pinyin_Xie": "cuī", "Âm Hán Việt_Xie": "thôi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Làm tính từ miêu tả núi non cao vút hoặc làm danh từ chỉ họ của người. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('雁', '{"9000": "2548.0", "Chữ Trung Quốc": "雁", "Bộ thủ & thành phần_Xie": "Bộ thủ | 隹 | Số nét | 12 | nét | 厂 | hán | biểu âm | vách đá — cho âm | 亻 | nhân | biểu nghĩa | người | 隹 | chuy | biểu nghĩa | chim đuôi ngắn | 雁 = 厂 (Hán, biểu âm) + 人 (Nhân, biểu nghĩa) + 隹 (Chuy, biểu nghĩa: chim); chữ hình thanh. Theo Wiktionary: 厂 cho âm, 人 và 隹 cùng biểu nghĩa — con chim bay theo đàn như người đi theo nhau có trật tự.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nhạn\": chim (隹) bay như người (亻) có trật tự — nhạn bay thành đàn hình chữ nhất, biểu tượng thư tình xa xứ. | Gương Hán-Việt | nhạn trong \"nhạn thư\" — thư gửi qua chim nhạn, điển tích tình yêu xa cách | Mở khoá kiến thức | Biết 雁 mở khoá: 大雁 (đại nhạn — ngỗng trời), 雁阵 (đàn nhạn xếp hàng), 鸿雁 (hồng nhạn — biểu tượng thư tín).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 雁 là hình thanh (psc): 厂 (hán) biểu âm, 人 (nhân) và 隹 (chuy, chim) biểu nghĩa. Chim nhạn (ngỗng trời) nổi tiếng bay thành đàn hình chữ V, biểu tượng cho sự trung thành và thư tín trong thơ văn cổ. Dạng tiểu triện còn lưu. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "303.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Hán (301) Nhân (42) Chuy (175)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Nhân (12) và Hán (301) tạo thành chữ \"Nhan\" để chỉ âm. Chữ Chuy (175 - con chim đuôi ngắn) để chỉ ý (đây là một loài chim). Giải thích sự chuyển ý: Chữ Nhan (nhan sắc) chỉ âm, chữ Điểu (chim) chỉ ý. Nhạn là một loài chim (Điểu) di cư, có tập tính bay theo hàng ngũ rất đẹp (Nhan). *(Biến âm Hán Việt: Trong Hán ngữ cổ, chữ Nhan và chữ Nhạn có cách phát âm tương đồng hoặc chung gốc phụ âm. Quá trình Việt hóa đã làm âm đọc bị chênh lệch thành Nhan và Nhạn).*", "Nghĩa Tiếng Việt_Xie": "chim nhạn", "Hạng Tần Suất (Jun Da)": "2548.0", "Tần Suất % (Jun Da)": "98.5765732265", "GavinGrover_Once (Chiết tự trực tiếp)": "厂 + 倠", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴厂倠", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "倠", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "厂", "Unihan_Simplified (Chữ Giản thể)": "雁", "Unihan_Traditional (Chữ Phồn thể)": "雁", "Pinyin_Xie": "yàn", "Âm Hán Việt_Xie": "nhạn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ loài chim di cư, thường xuất hiện trong văn thơ cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('绅', '{"9000": "2549.0", "Chữ Trung Quốc": "绅", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 8 | nét | 纟 | mịch | biểu nghĩa | sợi tơ, vải — dải lụa quan phục | 申 | thân | biểu âm | thân, can chi — góp âm shēn | 绅 = 纟(Mịch, biểu nghĩa: sợi tơ/vải) + 申 (Thân, biểu âm: góp âm shēn). Chữ hình thanh — 纟chỉ nghĩa dải lụa thắt lưng quan phục, 申 góp âm. Dải 绅 là vật phân biệt sĩ phu với thường dân trong xã hội phong kiến.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thân\": 纟(vải tơ) buộc quanh 申 (thân mình) — dải thân thắt lưng áo quan, biểu tượng của quý ông thân thế. | Gương Hán-Việt | thân trong 绅士 (thân sĩ — quý ông), 乡绅 (hương thân — hào lý địa phương) | Mở khoá kiến thức | Biết 绅 (thân) mở khoá: 绅士 (quý ông, gentleman), 乡绅 (hào lý địa phương), 士绅 (sĩ thân — tầng lớp quan lại, trí thức).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 绅 (dạng phồn thể 紳) là chữ hình thanh: 糸 (mịch, sợi tơ/vải) làm biểu nghĩa, 申 làm biểu âm. Dải lụa lớn thắt quanh áo triều phục của quan lại — gọi là \"đại đai\" (large obi). Người mang dải 绅 là kẻ sĩ, quý ông. Nghĩa mở rộng thành 绅士 (gentleman). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái đai áo, dải áo", "Hạng Tần Suất (Jun Da)": "2549.0", "Tần Suất % (Jun Da)": "98.5783675045", "GavinGrover_Once (Chiết tự trực tiếp)": "纟 + 申", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰纟申", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "申", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "纟", "Unihan_Simplified (Chữ Giản thể)": "绅", "Unihan_Traditional (Chữ Phồn thể)": "紳", "Pinyin_Xie": "shēn", "Âm Hán Việt_Xie": "thân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Làm danh từ chỉ dải đai to của quan lại thời xưa, sau chỉ tầng lớp thân sĩ, quý tộc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('珊', '{"9000": "2550.0", "Chữ Trung Quốc": "珊", "Bộ thủ & thành phần_Xie": "Bộ thủ | 玉 | Số nét | 9 | nét | 王 | vương | biểu nghĩa | ngọc quý (bộ 玉 viết tắt) | 册 | sách | biểu âm | sách thẻ tre — cho âm shān | 珊 = 王/玉 (Vương/Ngọc, biểu nghĩa: đá quý) + 册 (Sách, biểu âm); cấu trúc hình thanh khả năng cao. Wiktionary không cung cấp lscodes, nhưng bộ 王 (玉) gợi chất liệu quý như san hô, phần 册 cho âm. Dạng tiểu triện còn lưu.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"san\": ngọc (王) từ sách (册) của biển — san hô là \"ngọc\" của đại dương, óng ánh như trang sách quý. | Gương Hán-Việt | san trong \"san hô\" (珊瑚) — loài sinh vật biển tạo nên rạn san hô | Mở khoá kiến thức | Biết 珊 mở khoá: 珊瑚 (san hô), 珊瑚礁 (rạn san hô), 闌珊 (lan san — tàn tạ, hiu hắt trong thơ).", "Tự nguyên_Xie": "Tiểu triện | 珊 dùng để chỉ san hô (珊瑚), bộ 王 thực ra là bộ 玉 (ngọc) viết tắt — chỉ chất liệu quý giá. Wiktionary không phân tích lscodes cụ thể. Theo cấu trúc, nhiều khả năng là hình thanh với 玉 biểu nghĩa và 册 biểu âm. San hô từng được xem là đá quý của biển, dùng làm đồ trang sức. Dạng tiểu triện còn lưu. Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: san hô 珊瑚)", "Hạng Tần Suất (Jun Da)": "2550.0", "Tần Suất % (Jun Da)": "98.580158165", "GavinGrover_Once (Chiết tự trực tiếp)": "王 + 册", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰王册", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "册", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "王", "Unihan_Simplified (Chữ Giản thể)": "珊", "Unihan_Traditional (Chữ Phồn thể)": "珊", "Pinyin_Xie": "shān", "Âm Hán Việt_Xie": "san", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ ghép để chỉ rạn san hô hoặc mô tả âm thanh leng keng của ngọc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('榜', '{"9000": "2551.0", "Chữ Trung Quốc": "榜", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 14 | nét | 木 | mộc | biểu nghĩa | gỗ — tấm gỗ treo thông báo | 旁 | bàng | biểu âm | bên cạnh — góp âm bǎng | 榜 = 木 (Mộc, biểu nghĩa: gỗ) + 旁 (Bàng, biểu âm: góp âm bǎng). Chữ hình thanh — 木 chỉ tấm bảng gỗ treo niêm yết công khai, 旁 góp âm. Bảng thi đỗ ngày xưa là tấm gỗ hoặc giấy treo công khai danh sách người đỗ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bảng\": tấm 木 (mộc — gỗ) dài rộng 旁 (bàng — sang ngang) — bảng niêm yết treo danh sách đỗ thi trước cửa quan. | Gương Hán-Việt | bảng trong 榜样 (bảng dạng — hình mẫu), 排行榜 (bảng xếp hạng) | Mở khoá kiến thức | Biết 榜 (bảng) mở khoá: 榜样 (hình mẫu, tấm gương), 排行榜 (bảng xếp hạng), 标榜 (khoe khoang, tự phụ).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Theo Wiktionary, 榜 là chữ hình thanh: 木 (mộc, gỗ) làm biểu nghĩa, 旁 (bàng) làm biểu âm. Nghĩa gốc là tấm gỗ hoặc biển bảng thông báo công khai. Từ đó mở nghĩa thành danh sách thi cử, bảng xếp hạng. 榜样 (bảng dạng — tấm gương, hình mẫu) là nghĩa phái sinh quan trọng. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chèo thuyền; đánh đập; bảng, danh sách; công văn", "Hạng Tần Suất (Jun Da)": "2551.0", "Tần Suất % (Jun Da)": "98.581945208", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 旁", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木旁", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "旁", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "榜", "Unihan_Traditional (Chữ Phồn thể)": "牓", "Pinyin_Xie": "bǎng", "Âm Hán Việt_Xie": "bảng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Làm danh từ chỉ bảng thông báo, danh sách trúng tuyển hoặc làm động từ chỉ việc công bố. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('诵', '{"9000": "2552.0", "Chữ Trung Quốc": "诵", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 9 | nét | 讠 | ngôn | biểu nghĩa | lời nói — đọc to, tụng | 甬 | dũng | biểu âm | ống, đường — góp âm sòng | 诵 = 讠(Ngôn, biểu nghĩa: lời nói) + 甬 (Dũng, biểu âm: góp âm sòng). Chữ hình thanh — 讠chỉ nghĩa dùng giọng nói lớn tụng đọc, 甬 góp âm. Dạng giản thể của 誦.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tụng\": 讠(lời nói) vang như 甬 (dũng — ống dẫn âm) — giọng tụng niệm vang vọng, đọc to và rõ ràng. | Gương Hán-Việt | tụng trong 背诵 (bội tụng — thuộc lòng), 朗诵 (lãng tụng — ngâm thơ) | Mở khoá kiến thức | Biết 诵 (tụng) mở khoá: 背诵 (thuộc lòng), 朗诵 (ngâm thơ, đọc diễn cảm), 诵经 (tụng kinh).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Theo Wiktionary, 诵 (dạng phồn thể 誦) là chữ hình thanh: 言 (ngôn, lời nói) làm biểu nghĩa, 甬 (dũng) làm biểu âm. Nghĩa gốc là đọc to, tụng niệm. Mở nghĩa sang: thuộc lòng (背诵), ngâm thơ (朗诵), tụng kinh (诵经). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đọc to và rõ; tụng kinh", "Hạng Tần Suất (Jun Da)": "2552.0", "Tần Suất % (Jun Da)": "98.5837265663", "GavinGrover_Once (Chiết tự trực tiếp)": "讠 + 甬", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰讠甬", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "甬", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "讠", "Unihan_Simplified (Chữ Giản thể)": "诵", "Unihan_Traditional (Chữ Phồn thể)": "誦", "Pinyin_Xie": "sòng", "Âm Hán Việt_Xie": "tụng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước tân ngữ chỉ văn bản, kinh Phật hoặc thơ ca để diễn tả hành động đọc to. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('傍', '{"9000": "2553.0", "Chữ Trung Quốc": "傍", "Bộ thủ & thành phần_Xie": "Bộ thủ | 人 | Số nét | 12 | nét | 亻 | nhân | biểu nghĩa | người | 旁 | bàng | biểu âm | bên cạnh — cho âm bàng | 傍 = 亻(Nhân, biểu nghĩa: người) + 旁 (Bàng, biểu âm); chữ hình thanh. Wiktionary ghi: {{Han compound|人|alt1=亻|旁|ls=psc|c1=s|c2=p}}. Bộ nhân chỉ liên quan đến người, 旁 cho âm bàng (bāng/bàng). Nghĩa: ở bên cạnh người, tiếp cận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bàng\": người (亻-Nhân) đứng Bàng cạnh (旁) — 傍晚 là lúc trời xế chiều, đứng bên cạnh buổi tối. | Gương Hán-Việt | bàng trong ''bàng quan'' — đứng bên cạnh nhìn; 傍 mang nghĩa tiếp cận, kề bên | Mở khoá kiến thức | Biết 傍 mở khoá: 傍晚 (bàng vãn – buổi chiều tối), 依傍 (y bàng – nương tựa).", "Tự nguyên_Xie": "傍 là chữ hình thanh: 亻(nhân – người) biểu nghĩa, 旁 (bàng) biểu âm. Wiktionary xác nhận cấu trúc này rõ ràng. Nghĩa gốc là ''tiếp cận, bên cạnh'' — người (亻) đứng kề bên (旁). Trong tiếng Trung hiện đại, 傍晚 (xế chiều, lúc trời gần tối) là từ thông dụng nhất; ngoài ra 依傍 (dựa vào). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "một bên; bên cạnh", "Hạng Tần Suất (Jun Da)": "2553.0", "Tần Suất % (Jun Da)": "98.5855063743", "GavinGrover_Once (Chiết tự trực tiếp)": "亻 + 旁", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰亻旁", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "旁", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "亻", "Unihan_Simplified (Chữ Giản thể)": "傍", "Unihan_Traditional (Chữ Phồn thể)": "傍", "Pinyin_Xie": "bàng", "Âm Hán Việt_Xie": "bàng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Giới từ | 介词 | Từ chỉ phương vị | 方位词 | Thường làm động từ chỉ sự tiếp cận về thời gian hoặc không gian, hoặc làm giới từ mang nghĩa dựa vào, kề bên. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Giới từ | 介词 | Ghép với danh từ hoặc đại từ thành cụm chỉ nơi chốn, thời gian, đối tượng: 在家, 跟他. Cụm giới từ đứng TRƯỚC động từ — 我在家吃饭 — ngược với trật tự tiếng Việt. | Từ chỉ phương vị | 方位词 | Chỉ vị trí và đứng SAU danh từ — 桌子上, 家里 — chứ không đứng trước như ''trên bàn'', ''trong nhà''. Thường đi cùng 在.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('彦', '{"9000": "2554.0", "Chữ Trung Quốc": "彦", "Bộ thủ & thành phần_Xie": "Bộ thủ | 彡 | Số nét | 9 | nét | 产 | sản | biểu nghĩa | sản sinh, tài năng xuất hiện | 彡 | sam | biểu nghĩa | lông vũ, vân hoa — gợi văn vẻ | 彦 = 产 (Sản) + 彡 (Sam); cấu trúc không có lscodes từ Wiktionary. Bộ 彡 gợi văn vẻ, tài hoa; cùng với 产 (sinh ra) — người tài đức kiêm toàn được sinh ra. Dạng tiểu triện còn lưu.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ngạn\": tài hoa (彡) được sinh ra (产) — ngạn sĩ, kẻ tài đức vẹn toàn được thiên phú. | Gương Hán-Việt | ngạn trong \"俊彦\" (tuấn ngạn) — người tài giỏi xuất sắc | Mở khoá kiến thức | Biết 彦 mở khoá: 俊彦 (tuấn ngạn — người tài xuất sắc), tên riêng phổ biến trong văn hoá Hán-Việt.", "Tự nguyên_Xie": "Tiểu triện | 彦 có dạng tiểu triện còn lưu nhưng Wiktionary không phân tích lscodes cụ thể. Cấu trúc gồm 产 (sản, sinh ra) và 彡 (vân hoa, tài hoa). Nghĩa là người có cả tài lẫn đức — kẻ sĩ toàn vẹn. Dùng nhiều trong tên riêng. Chưa có nguồn học thuật xác nhận chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "kẻ sĩ gồm cả tài đức", "Hạng Tần Suất (Jun Da)": "2554.0", "Tần Suất % (Jun Da)": "98.5872825649", "GavinGrover_Once (Chiết tự trực tiếp)": "产 + 彡", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱产彡", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "产", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "彡", "Unihan_Simplified (Chữ Giản thể)": "彦", "Unihan_Traditional (Chữ Phồn thể)": "彥", "Pinyin_Xie": "yàn", "Âm Hán Việt_Xie": "ngạn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong văn viết cổ hoặc cấu tạo danh từ riêng để chỉ người có tài đức. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('醇', '{"9000": "2555.0", "Chữ Trung Quốc": "醇", "Bộ thủ & thành phần_Xie": "Bộ thủ | 酉 | Số nét | 15 | nét | 酉 | dậu | biểu nghĩa | bình rượu, năm Dậu | 享 | hưởng | biểu âm | dâng lên hưởng thụ — cho âm chún | 醇 = 酉 (Dậu, biểu nghĩa: rượu) + 享/𦎧 (biểu âm); chữ hình thanh. Bộ 酉 chỉ đây liên quan đến rượu, phần 享 cho âm. Nghĩa là rượu ngon, thuần khiết, sau mở rộng sang \"thuần hậu, đậm đà\".", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thuần\": bình rượu (酉) dâng hưởng (享) — thuần rượu, đậm đà nguyên chất, không pha tạp. | Gương Hán-Việt | thuần trong \"thuần hậu\" — đậm đà, chất phác không giả tạo | Mở khoá kiến thức | Biết 醇 mở khoá: 醇厚 (thuần hậu — đậm đà), 乙醇 (ethanol), 胆固醇 (cholesterol) — nhóm từ rượu và hoá học.", "Tự nguyên_Xie": "Giáp cốt văn | Kim văn | Tiểu triện | Lục thư thông | Theo Wiktionary, 醇 là hình thanh: 酉 (dậu, bình rượu) biểu nghĩa, 𦎧 biểu âm (dạng chữ thể hiện qua 享). Nghĩa gốc là rượu đậm, rượu nguyên chất không pha. Về sau mở rộng: \"thuần hậu, đậm đà\" (醇厚), và trong hoá học là rượu/alcohol. Giáp cốt văn và kim văn phong phú còn lưu qua hanziyuan. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "rượu ngon; thuần hậu", "Hạng Tần Suất (Jun Da)": "2555.0", "Tần Suất % (Jun Da)": "98.5890566882", "GavinGrover_Once (Chiết tự trực tiếp)": "酉 + 享", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰酉享", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "享", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "酉", "Unihan_Simplified (Chữ Giản thể)": "醇", "Unihan_Traditional (Chữ Phồn thể)": "醇", "Pinyin_Xie": "chún", "Âm Hán Việt_Xie": "thuần", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường làm tính từ đứng trước danh từ hoặc sau phó từ chỉ mức độ để miêu tả tính chất thuần khiết, đậm đà. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('笛', '{"9000": "2556.0", "Chữ Trung Quốc": "笛", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 11 | nét | 竹 | trúc | biểu nghĩa | tre, trúc | 由 | do | biểu âm | do, từ đó — cho âm dí | 笛 = 竹 (Trúc, biểu nghĩa: tre) + 由 (Do, biểu âm); chữ hình thanh. Bộ trúc chỉ nhạc cụ bằng tre, phần 由 cho âm dí. Cây sáo trúc là nhạc cụ làm từ ống tre.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"địch\": cây trúc (竹) từ đó (由) mà ra tiếng — địch tiêu, sáo trúc phát âm thanh du dương. | Gương Hán-Việt | địch trong \"tiêu địch\" — sáo trúc, nhạc cụ dân tộc Trung Hoa | Mở khoá kiến thức | Biết 笛 mở khoá: 笛子 (địch tử — cây sáo), 竹笛 (trúc địch), 短笛 (đoản địch — flute nhỏ).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Theo Wiktionary, 笛 là hình thanh: 竹 (trúc) biểu nghĩa tre, 由 (do) biểu âm. Nghĩa là cây sáo trúc (ống tre được khoét lỗ để thổi). Dạng tiểu triện và lục thư thông còn lưu qua hanziyuan. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1875.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Trúc (118) Do (102)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Trúc (số 118 - cây tre trúc/ 竹 /chỉ ý) nằm trên chữ Do (số 102 - nguyên do/ 由 /chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Do chỉ âm, bộ Trúc chỉ ý. Địch là một loại nhạc cụ được làm từ cây trúc. Địch chính là ống sáo thổi ngang (trúc địch).", "Nghĩa Tiếng Việt_Xie": "cái sáo (để thổi)", "Hạng Tần Suất (Jun Da)": "2556.0", "Tần Suất % (Jun Da)": "98.5908184087", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 由", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮由", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "由", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "笛", "Unihan_Traditional (Chữ Phồn thể)": "笛", "Pinyin_Xie": "dí", "Âm Hán Việt_Xie": "địch", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Làm danh từ chỉ nhạc cụ hoặc thiết bị phát âm thanh, thường làm tân ngữ cho động từ thổi hoặc thổi còi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('禽', '{"9000": "2557.0", "Chữ Trung Quốc": "禽", "Bộ thủ & thành phần_Xie": "Bộ thủ | 禸 | Số nét | 12 | nét | 禽 | cầm | tượng hình | chim muông — hình ảnh lưới bắt chim với âm 今 thêm vào | 禽 là chữ phức tạp có lịch sử lâu đời. Trong giáp cốt văn, 禽 là tượng hình vẽ cái lưới bắt chim — nguyên cùng gốc với 𠦒 và 畢. Thời kim văn, thêm 今 (kim) làm biểu âm, biến thành chữ hình thanh-tượng hình. Dạng hiện đại: 今 biến thành 人, phần lưới biến thành 离. Nghĩa \"bắt chim\" sau chuyển sang chữ 擒.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cầm\": hình cái lưới (离) giăng bắt người (人) — đó là cầm chim muông, bắt gia cầm. | Gương Hán-Việt | cầm trong 家禽 (gia cầm — gia súc gia cầm), 飞禽 (phi cầm — chim bay) | Mở khoá kiến thức | Biết 禽 (cầm) mở khoá: 家禽 (gia cầm), 飞禽走兽 (phi cầm tẩu thú — chim thú), 禽兽 (cầm thú — loài cầm thú; nghĩa bóng: kẻ tàn nhẫn).", "Tự nguyên_Xie": "Giáp cốt văn | Theo Wiktionary, trong giáp cốt văn 禽 là tượng hình vẽ cái lưới bắt chim, gốc chung với 𠦒 (畢). Thời kim văn, thêm âm 今 (kim) tạo chữ hình thanh. Nghĩa gốc là bắt chim bằng lưới; sau đó mượn chỉ \"chim và thú\", nghĩa \"bắt\" chuyển sang chữ 擒. Trong dạng hiện đại, 今 biến dạng thành 人, và phần lưới thành 离. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1376.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Nhân (009) Hung (086) Nhựu (202)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Gồm chữ Nhân (số 009 - người/ 人), chữ Hung (số 086 - hung ác/ 凶) và bộ Nhựu (số 202 - vết chân thú/ 禸). Người thợ săn hay giăng lưới ở những nơi có nhiều dấu chân chim thú để bắt. Giải thích sự chuyển ý: Đây là chữ Hội ý. Cầm là loài chim hoặc muông thú nói chung (phi cầm, cầm thú). Nghĩa cổ còn là bắt sống (sinh cầm).", "Nghĩa Tiếng Việt_Xie": "loài chim", "Hạng Tần Suất (Jun Da)": "2557.0", "Tần Suất % (Jun Da)": "98.5925796125", "GavinGrover_Once (Chiết tự trực tiếp)": "人 + 离", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱人离", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "离", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "人", "Unihan_Simplified (Chữ Giản thể)": "禽", "Unihan_Traditional (Chữ Phồn thể)": "禽", "Pinyin_Xie": "qín", "Âm Hán Việt_Xie": "cầm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Làm danh từ chỉ các loài chim hoặc động vật hai chân có lông vũ, thường xuất hiện trong các từ ghép. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('勿', '{"9000": "2558.0", "Chữ Trung Quốc": "勿", "Bộ thủ & thành phần_Xie": "Bộ thủ | 勹 | Số nét | 4 | nét | 勿 | vật | tượng hình | hình ảnh dao có máu — chữ tượng hình cổ | 勿 là chữ tượng hình. Wiktionary ghi: {{liushu|p}} — hình ảnh máu trên dao, chữ gốc của 刎 (chém cắt). Sau đó mượn dùng để biểu đạt hư từ ''chớ, đừng'' từ thời giáp cốt văn. Cấu trúc ⿹勹⿱丿丿 hiện tại là dạng kết hợp thứ cấp, không phản ánh tượng hình gốc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"vật\": vật cản — 勿 như cái dao kèm dấu ''chớ lại gần!'' Dùng trong biển cấm: 请勿 (xin đừng). | Gương Hán-Việt | vật trong ''vật phẩm, sự vật'' — cùng âm nhưng 勿 là hư từ phủ định, không liên quan nghĩa | Mở khoá kiến thức | Biết 勿 mở khoá: 请勿 (thỉnh vật – xin đừng), 勿忘 (vật vong – đừng quên), 勿动 (vật động – không được động vào).", "Tự nguyên_Xie": "勿 theo Wiktionary là chữ tượng hình: hình ảnh máu (丿丿) trên dao (勹), nguyên là chữ gốc của 刎 (văn – chém cổ). Từ thời giáp cốt văn, 勿 được mượn (giả tá) để biểu đạt hư từ phủ định ''chớ, đừng, không được'' vì âm đọc trùng hoặc gần. Ý nghĩa tượng hình gốc (dao+máu) không còn được dùng; nghĩa hiện dùng hoàn toàn là nghĩa mượn. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "25.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Bao (24) Khúc (11)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Bao (chữ số 24) + 2 nét phẩy (hình thức viết tắt của chữ Khúc - số 11 biểu thị sự bất chính). Khuyên răn con người đừng nên vươn tay dài ra để nuôi tham vọng bất chính.", "Nghĩa Tiếng Việt_Xie": "dừng lại; đừng, chớ", "Hạng Tần Suất (Jun Da)": "2558.0", "Tần Suất % (Jun Da)": "98.5943366819", "GavinGrover_Once (Chiết tự trực tiếp)": "勹 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴勹", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "勿", "Unihan_Traditional (Chữ Phồn thể)": "勿", "Pinyin_Xie": "wù", "Âm Hán Việt_Xie": "vật", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Phó từ | 副词 | Làm phó từ phủ định mang tính khuyên ngăn hoặc cấm đoán, luôn đứng trước động từ hoặc tính từ. | Phó từ | 副词 | Bổ nghĩa cho động từ hoặc tính từ và luôn đứng TRƯỚC chúng — 都是, 很好. Không đứng sau như tiếng Việt và không bổ nghĩa cho danh từ.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | wù | / | đừng | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Từ chức năng và phụ từ I | HSK | HSK 6 | · | Các từ chức năng và bổ trợ", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('娟', '{"9000": "2559.0", "Chữ Trung Quốc": "娟", "Bộ thủ & thành phần_Xie": "Bộ thủ | 女 | Số nét | 10 | nét | 女 | nữ | biểu nghĩa | phụ nữ | 肙 | biểu âm | sâu nhỏ — cho âm juān | 娟 = 女 (Nữ, biểu nghĩa: phụ nữ) + 肙 (biểu âm, không có Hán-Việt riêng, gồm 口+月); chữ hình thanh. Bộ nữ chỉ đây mô tả vẻ đẹp người phụ nữ, phần 肙 cho âm juān.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quyên\": người nữ (女) có vẻ đẹp trăng (月) sáng dịu dàng — quyên tú, xinh đẹp như ánh trăng. | Gương Hán-Việt | quyên trong \"quyên tú\" — xinh đẹp duyên dáng | Mở khoá kiến thức | Biết 娟 mở khoá: 娟秀 (quyên tú — xinh tú), 嫦娟 (Hằng Nga — nàng tiên cung trăng), tên riêng nữ phổ biến.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Theo Wiktionary, 娟 là hình thanh: 女 (nữ) biểu nghĩa, 肙 biểu âm. Nghĩa là dáng vẻ xinh đẹp, uyển chuyển. Dùng chủ yếu trong tên riêng nữ và một số từ miêu tả vẻ đẹp như 嫦娟 (hằng nga), 娟秀 (xinh đẹp tú lệ). Dạng tiểu triện và lục thư thông còn lưu qua hanziyuan. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "xinh đẹp", "Hạng Tần Suất (Jun Da)": "2559.0", "Tần Suất % (Jun Da)": "98.5960859996", "GavinGrover_Once (Chiết tự trực tiếp)": "女 + 肙", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰女肙", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "肙", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "女", "Unihan_Simplified (Chữ Giản thể)": "娟", "Unihan_Traditional (Chữ Phồn thể)": "娟", "Pinyin_Xie": "juān", "Âm Hán Việt_Xie": "quyên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Làm tính từ miêu tả vẻ đẹp thanh tú của người phụ nữ hoặc ánh trăng, thường dùng trong văn thơ và tên riêng. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('瞄', '{"9000": "2560.0", "Chữ Trung Quốc": "瞄", "Bộ thủ & thành phần_Xie": "Bộ thủ | 目 | Số nét | 13 | nét | 目 | mục | biểu nghĩa | mắt — liên quan đến nhìn, ngắm | 苗 | miêu | biểu âm | mầm cây — góp âm miáo | 瞄 = 目 (Mục, biểu nghĩa: mắt) + 苗 (Miêu, biểu âm: góp âm miáo). Chữ hình thanh — 目 chỉ nghĩa dùng mắt ngắm nhắm, 苗 góp âm. Nghĩa là nhắm vào mục tiêu, nhìn chăm chú.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"miêu\": 目 (mắt) nhìn chằm chằm vào 苗 (miêu — cây mầm nhỏ) từ xa — hành động miêu (ngắm, nhắm) mục tiêu. | Gương Hán-Việt | miêu trong 瞄准 (miêu chuẩn — nhắm chuẩn) | Mở khoá kiến thức | Biết 瞄 (miêu) mở khoá: 瞄准 (nhắm vào mục tiêu), 瞄一眼 (liếc nhìn một cái).", "Tự nguyên_Xie": "Theo Wiktionary, 瞄 là chữ hình thanh: 目 (mục, mắt) làm biểu nghĩa, 苗 (miêu) làm biểu âm. Chữ không có hình thức cổ trong giáp cốt hay kim văn. Nghĩa là nhắm vào, ngắm mục tiêu. Dùng rộng trong 瞄准 (nhắm chuẩn). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ngắm, nhắm, nhằm", "Hạng Tần Suất (Jun Da)": "2560.0", "Tần Suất % (Jun Da)": "98.5978342837", "GavinGrover_Once (Chiết tự trực tiếp)": "目 + 苗", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰目苗", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "苗", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "目", "Unihan_Simplified (Chữ Giản thể)": "瞄", "Unihan_Traditional (Chữ Phồn thể)": "瞄", "Pinyin_Xie": "miáo", "Âm Hán Việt_Xie": "miểu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Làm động từ chỉ hành động tập trung ánh mắt vào mục tiêu, thường đi kèm giới từ chỉ hướng hoặc bổ ngữ xu hướng. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('幢', '{"9000": "2561.0", "Chữ Trung Quốc": "幢", "Bộ thủ & thành phần_Xie": "Bộ thủ | 巾 | Số nét | 15 | nét | 巾 | cân | biểu nghĩa | vải, khăn — vải che, cờ hiệu | 童 | đồng | biểu âm | đồng — góp âm chuáng | 幢 = 巾 (Cân, biểu nghĩa: vải/khăn) + 童 (Đồng, biểu âm: góp âm chuáng/zhuàng). Chữ hình thanh — 巾 gợi nghĩa vật bằng vải (cờ, màn, rèm), 童 góp âm. Chữ đa âm: chuáng (lá cờ, tán che) và zhuàng (lượng từ đếm nhà).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tràng\": 巾 (vải) rộng như 童 (đồng — trẻ em) kéo lên — tràng phan (lá cờ/tán), dùng để đếm toà nhà cao tràng. | Gương Hán-Việt | tràng trong 幢幢 (tràng tràng — lung lay như bóng ma), 经幢 (kinh tràng — cột kinh) | Mở khoá kiến thức | Biết 幢 (tràng) mở khoá: 幢幢 (bóng ma lờ mờ), 经幢 (cột kinh Phật), dùng đếm toà nhà: 一幢楼 (một toà nhà).", "Tự nguyên_Xie": "Tiểu triện | 幢 là chữ hình thanh: 巾 (cân, vải/khăn) làm biểu nghĩa, 童 (đồng) làm biểu âm. Nghĩa gốc là cột gỗ chống đỡ, lá cờ hoặc tán lọng. Nghĩa lượng từ (đếm toà nhà) phát triển sau. Wiktionary cung cấp hai âm đọc với hai nghĩa khác nhau cho chữ này. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "căn; toà; ngôi (dùng cho nhà cửa)", "Hạng Tần Suất (Jun Da)": "2561.0", "Tần Suất % (Jun Da)": "98.5995789503", "GavinGrover_Once (Chiết tự trực tiếp)": "巾 + 童", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰巾童", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "童", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "巾", "Unihan_Simplified (Chữ Giản thể)": "幢", "Unihan_Traditional (Chữ Phồn thể)": "幢", "Pinyin_Xie": "chuáng", "Âm Hán Việt_Xie": "tràng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Lượng từ | 量词 | Danh từ | 名词 | Thường dùng làm lượng từ đứng trước danh từ chỉ tòa nhà, hoặc làm danh từ chỉ cái phướn trong Phật giáo. | Lượng từ | 量词 | Đứng giữa số từ (hoặc 这/那) và danh từ: 一杯茶, 这本书. Mỗi danh từ đi với lượng từ riêng; 个 là lượng từ dùng chung phổ biến nhất. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | zhuàng | / | đoàn | Xuất hiện trong lộ trình | HSK | HSK 6 | · | Căn nhà | New HSK | New HSK 7-9 | · | Вuildings và công trình xây dựng", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('寇', '{"9000": "2562.0", "Chữ Trung Quốc": "寇", "Bộ thủ & thành phần_Xie": "Bộ thủ | 宀 | Số nét | 11 | nét | 宀 | miên | biểu nghĩa | mái nhà, nơi ở | 元 | nguyên | biểu nghĩa | đầu người | 攴 | phộc | biểu nghĩa | tay cầm gậy đánh | 寇 = 宀 (Miên) + 元 (Nguyên, đầu người) + 攴 (Phộc, tay cầm gậy); chữ hội ý. Theo Wiktionary: người cầm gậy (攴) đánh vào đầu (元) của kẻ khác ngay dưới mái nhà của họ (宀) — cảnh kẻ cướp xông vào nhà.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khấu\": dưới mái nhà (宀), kẻ cầm gậy (攴) đập đầu (元) người — khấu tặc, giặc xông vào nhà cướp bóc. | Gương Hán-Việt | khấu trong \"hải khấu\" — cướp biển, giặc biển | Mở khoá kiến thức | Biết 寇 mở khoá: 海寇 (hải khấu — cướp biển), 倭寇 (oa khấu — giặc Nhật), 盗寇 (đạo khấu — giặc cướp).", "Tự nguyên_Xie": "Giáp cốt văn | Đại triện | Tiểu triện | Theo Wiktionary, 寇 là hội ý (ic): 宀 (miên, mái nhà) + 元 (đầu người) + 攴 (tay cầm gậy đánh). Hình ảnh: kẻ cầm gậy xông vào nhà đánh đầu người — giặc cướp. Trong giáp cốt văn, hai tay cầm gậy; dạng hiện đại 卜 và 又 đã gộp thành 攴. Giáp cốt văn, đại triện và tiểu triện còn lưu. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "kẻ cướp; giặc, kẻ thù", "Hạng Tần Suất (Jun Da)": "2562.0", "Tần Suất % (Jun Da)": "98.6013122477", "GavinGrover_Once (Chiết tự trực tiếp)": "宀 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱宀", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "寇", "Unihan_Traditional (Chữ Phồn thể)": "㓂", "Pinyin_Xie": "kòu", "Âm Hán Việt_Xie": "khấu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường làm danh từ chỉ kẻ thù, giặc cướp hoặc làm động từ mang nghĩa xâm lược, cướp bóc trong văn viết. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('睹', '{"9000": "2563.0", "Chữ Trung Quốc": "睹", "Bộ thủ & thành phần_Xie": "Bộ thủ | 目 | Số nét | 13 | nét | 目 | mục | biểu nghĩa | mắt — nhìn, chứng kiến | 者 | giả | biểu âm | kẻ, người — góp âm dǔ | 睹 = 目 (Mục, biểu nghĩa: mắt) + 者 (Giả, biểu âm: góp âm dǔ). Chữ hình thanh — 目 chỉ nghĩa nhìn thấy tận mắt, 者 góp âm. Thường dùng trong 目睹 (mục đổ — tận mắt chứng kiến).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đổ\": 目 (mắt) của 者 (giả — người đó) nhìn thẳng — đổ (trông thấy) tận mắt không qua trung gian. | Gương Hán-Việt | đổ trong 目睹 (mục đổ — tận mắt chứng kiến), 耳闻目睹 (nhĩ văn mục đổ) | Mở khoá kiến thức | Biết 睹 (đổ) mở khoá: 目睹 (chứng kiến tận mắt), 耳闻目睹 (tai nghe mắt thấy), 有目共睹 (ai cũng nhìn thấy — rõ ràng).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 睹 là chữ hình thanh: 目 (mục, mắt) làm biểu nghĩa, 者 (giả) làm biểu âm. Nghĩa gốc là nhìn thấy, chứng kiến. Dùng nhiều trong văn viết trang trọng, thành ngữ 目睹 (mắt thấy), 耳闻目睹 (tai nghe mắt thấy). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "trông thấy", "Hạng Tần Suất (Jun Da)": "2563.0", "Tần Suất % (Jun Da)": "98.6030414107", "GavinGrover_Once (Chiết tự trực tiếp)": "目 + 者", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰目者", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "者", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "目", "Unihan_Simplified (Chữ Giản thể)": "睹", "Unihan_Traditional (Chữ Phồn thể)": "睹", "Pinyin_Xie": "dǔ", "Âm Hán Việt_Xie": "đổ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Làm động từ chỉ hành động nhìn thấy trực tiếp, thường xuất hiện trong các thành ngữ hoặc từ ghép song âm tiết. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('贿', '{"9000": "2564.0", "Chữ Trung Quốc": "贿", "Bộ thủ & thành phần_Xie": "Bộ thủ | 貝 | Số nét | 10 | nét | 贝 | bối | biểu nghĩa | vỏ sò/tiền — của cải, tiền bạc | 有 | hữu | biểu âm | có — góp âm huì | 贿 = 贝 (Bối, biểu nghĩa: vỏ sò/tiền) + 有 (Hữu, biểu âm: góp âm huì). Chữ hình thanh — 贝 chỉ nghĩa tiền bạc được dùng để mua chuộc, 有 góp âm. Nghĩa gốc là của cải, mở rộng sang hối lộ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hối\": 贝 (tiền bạc) chuyển tay cho 有 (hữu — kẻ có quyền) — đó là hối lộ, mua chuộc bằng của cải. | Gương Hán-Việt | hối trong 贿赂 (hối lộ — hối lộ), 受贿 (thụ hối — nhận hối lộ) | Mở khoá kiến thức | Biết 贿 (hối) mở khoá: 贿赂 (hối lộ), 受贿 (nhận hối lộ), 行贿 (đưa hối lộ).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Theo Wiktionary, 贿 (dạng phồn thể 賄) là chữ hình thanh: 貝 (bối, vỏ sò/tiền) làm biểu nghĩa, 有 (hữu) làm biểu âm. Nghĩa gốc là của cải, tài sản. Sau mở nghĩa sang dùng tiền của để mua chuộc quan lại — hối lộ. Thành từ ghép quan trọng: 贿赂 (hối lộ). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "của cải; hối lộ, đút lót", "Hạng Tần Suất (Jun Da)": "2564.0", "Tần Suất % (Jun Da)": "98.6047705738", "GavinGrover_Once (Chiết tự trực tiếp)": "贝 + 有", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰贝有", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "有", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "贝", "Unihan_Simplified (Chữ Giản thể)": "贿", "Unihan_Traditional (Chữ Phồn thể)": "賄", "Pinyin_Xie": "huì", "Âm Hán Việt_Xie": "hối", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chữ này thường làm động từ trong các từ ghép chỉ hành vi đút lót hoặc làm danh từ chỉ tiền của đem đi đút lót. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('踩', '{"9000": "2565.0", "Chữ Trung Quốc": "踩", "Bộ thủ & thành phần_Xie": "Bộ thủ | 足 | Số nét | 15 | nét | 𧾷 | biểu nghĩa | bộ túc (chân), biến thể của 足 | 采 | thái | biểu âm | hái — cho âm thái/thải | 踩 = 足 (biểu nghĩa: chân) + 采 (Thái, biểu âm); chữ hình thanh. Wiktionary ghi: {{Han compound|足|采|ls=psc|c1=s|c2=p|t1=foot}}. Bộ túc chỉ hành động chân — giẫm lên bằng chân; 采 cho âm cǎi gần với thái.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thải\": chân (足) hái (采-Thái) mặt đất — giẫm chân xuống như đang hái từ đất. Thải = giẫm. | Gương Hán-Việt | thải trong ''đào thải'' — âm gần; 踩 đặc chỉ hành động giẫm bằng chân | Mở khoá kiến thức | Biết 踩 mở khoá: 踩踏 (thải đạp – giẫm đạp), 踩油门 (thải du môn – đạp ga xe).", "Tự nguyên_Xie": "踩 là chữ hình thanh: 足 (túc – chân) biểu nghĩa, 采 (thái – hái) biểu âm. Wiktionary xác nhận cấu trúc psc này. Nghĩa là giẫm lên bằng bàn chân. Không có glyphOrigin chi tiết hơn trong Wiktionary. Chữ khá gần nghĩa với 踏 (đạp, giẫm), nhưng 踩 thiên về giẫm nhẹ/vô tình hơn. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "giẫm lên", "Hạng Tần Suất (Jun Da)": "2565.0", "Tần Suất % (Jun Da)": "98.6064981865", "GavinGrover_Once (Chiết tự trực tiếp)": "⻊ + 采", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰⻊采", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "采", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⻊", "Unihan_Simplified (Chữ Giản thể)": "踩", "Unihan_Traditional (Chữ Phồn thể)": "跴", "Pinyin_Xie": "cǎi", "Âm Hán Việt_Xie": "thải", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước tân ngữ chỉ vật bị giẫm lên hoặc kết hợp với bổ ngữ xu hướng. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | Từ đơn | Từ vựng HSK 5: giẫm | / | cǎi | / | giẫm | Xuất hiện trong lộ trình | HSK | HSK 5 | · | Động từ hàng ngày | New HSK | New HSK 6 | · | Thân hình", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('霆', '{"9000": "2566.0", "Chữ Trung Quốc": "霆", "Bộ thủ & thành phần_Xie": "Bộ thủ | 雨 | Số nét | 14 | nét | 雨 | vũ | biểu nghĩa | mưa, thời tiết | 廷 | đình | biểu âm | triều đình — cho âm tíng | 霆 = 雨 (Vũ, biểu nghĩa: mưa/thời tiết) + 廷 (Đình, biểu âm); chữ hình thanh. Bộ vũ chỉ hiện tượng thời tiết, phần 廷 cho âm tíng. Nghĩa là sét lớn, sấm sét dữ dội.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đình\": mưa (雨) sét như triều đình (廷) phán xử — đình lôi, sét đánh ngang trời như mệnh lệnh thiên tử. | Gương Hán-Việt | đình trong \"lôi đình\" (雷霆) — sấm sét, cơn thịnh nộ | Mở khoá kiến thức | Biết 霆 mở khoá: 雷霆 (lôi đình — sấm sét), 大发雷霆 (nổi giận sấm sét), 雷霆万钧 (sức mạnh khủng khiếp).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 霆 là hình thanh: 雨 (vũ) biểu nghĩa thời tiết, 廷 (đình) biểu âm. Nghĩa là tiếng sét lớn, sét đánh mạnh. Thường dùng trong 雷霆 (lôi đình) — sấm sét, cũng dùng ẩn dụ cho cơn giận dữ dội. Dạng tiểu triện còn lưu. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sét dữ, sét lớn", "Hạng Tần Suất (Jun Da)": "2566.0", "Tần Suất % (Jun Da)": "98.6082252824", "GavinGrover_Once (Chiết tự trực tiếp)": "雨 + 廷", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱雨廷", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "廷", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "雨", "Unihan_Simplified (Chữ Giản thể)": "霆", "Unihan_Traditional (Chữ Phồn thể)": "霆", "Pinyin_Xie": "tíng", "Âm Hán Việt_Xie": "đình", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong văn viết hoặc kết hợp thành từ ghép để chỉ uy thế sấm sét. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('呜', '{"9000": "2567.0", "Chữ Trung Quốc": "呜", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 7 | nét | 口 | khẩu | biểu nghĩa | miệng, âm thanh | 乌 | ô | biểu âm | con quạ — cho âm wū | 呜 = 口 (Khẩu, biểu nghĩa: miệng) + 乌 (Ô, biểu âm); chữ hình thanh. Phồn thể 嗚 dùng 烏 thay 乌. Bộ khẩu chỉ âm thanh từ miệng, phần ô cho âm wū — tiếng khóc nức nở.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ô\": miệng (口) kêu như quạ (乌) — ô ô, tiếng khóc nức nở, ai oán não nùng. | Gương Hán-Việt | ô trong \"ô hô\" (呜呼) — than ôi, tiếng than trong văn tế | Mở khoá kiến thức | Biết 呜 mở khoá: 呜咽 (ô yết — khóc nức nở), 呜呼 (ô hô — than ôi, chết rồi), 呜呜 (ô ô — tiếng khóc).", "Tự nguyên_Xie": "Theo Wiktionary, 嗚 (phồn thể) là hình thanh: 口 (khẩu) biểu nghĩa miệng, 烏 (ô, quạ) biểu âm. Nghĩa là âm thanh khóc nức nở hoặc âm thanh u ám, kéo dài. Giản thể 呜 thay 烏 bằng 乌. Không có hình ảnh cổ. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(tiếng than)", "Hạng Tần Suất (Jun Da)": "2567.0", "Tần Suất % (Jun Da)": "98.6099518616", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 乌", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口乌", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "乌", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "呜", "Unihan_Traditional (Chữ Phồn thể)": "嗚", "Pinyin_Xie": "wū", "Âm Hán Việt_Xie": "ô", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Từ tượng thanh | 象声词 | Thán từ | 叹词 | Thường dùng làm từ tượng thanh mô phỏng tiếng còi, tiếng gió hoặc làm thán từ biểu thị sự than thở. | Từ tượng thanh | 象声词 | Mô phỏng âm thanh: 哗哗, 汪汪. Có thể làm định ngữ, trạng ngữ hoặc đứng độc lập. | Thán từ | 叹词 | Bộc lộ cảm xúc hoặc dùng để gọi đáp: 啊, 哦, 喂. Đứng tách riêng ở đầu câu, không làm thành phần câu.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('拱', '{"9000": "2568.0", "Chữ Trung Quốc": "拱", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 9 | nét | 扌 | thủ | biểu nghĩa | tay | 共 | cộng | biểu nghĩa | cùng nhau | 拱 = 扌(Thủ, biểu nghĩa: tay) + 共 (Cộng, biểu nghĩa: cùng nhau); chữ hội ý (hoặc hình thanh theo ls2=psc). Theo Wiktionary: tay (扌) cùng nhau (共) — hai tay khum lại chắp trước ngực để cúi chào. Cũng có nghĩa hình vòm (arch).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"củng\": tay (扌) cùng nhau (共) khum lại — củng thủ, chắp tay cung kính trước mặt người lớn. | Gương Hán-Việt | củng trong \"củng thủ\" — chắp tay cúi chào kiểu cổ | Mở khoá kiến thức | Biết 拱 mở khoá: 拱手 (củng thủ — chắp tay), 拱桥 (củng kiều — cầu vòm), 众星拱月 (chúng tinh củng nguyệt — mọi sao bao quanh mặt trăng).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 拱 có thể là hội ý (ic) hoặc hình thanh (psc): 手 (thủ) biểu nghĩa tay, 共 (cộng) vừa có thể biểu nghĩa cùng nhau vừa biểu âm. Nghĩa gốc: hai tay khum lại chắp trước ngực — cử chỉ chào kính. Mở rộng sang: bao quanh, vươn lên, hình vòm. Dạng tiểu triện còn lưu. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chắp tay cung kính", "Hạng Tần Suất (Jun Da)": "2568.0", "Tần Suất % (Jun Da)": "98.6116774071", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 共", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌共", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "共", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "拱", "Unihan_Traditional (Chữ Phồn thể)": "拱", "Pinyin_Xie": "gǒng", "Âm Hán Việt_Xie": "củng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Tính từ | 形容词 | Thường làm động từ chỉ hành động chắp tay chào hoặc làm danh từ chỉ hình dạng vòm cong. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | gǒng | / | chắp tay trước ngực | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Giao tiếp I", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('妃', '{"9000": "2569.0", "Chữ Trung Quốc": "妃", "Bộ thủ & thành phần_Xie": "Bộ thủ | 女 | Số nét | 6 | nét | 女 | nữ | biểu nghĩa | phụ nữ | 己 | kỷ | biểu âm | bản thân — cho âm fēi (gốc là 卩) | 妃 = 女 (Nữ, biểu nghĩa: phụ nữ) + 卩/己 (biểu nghĩa: người quỳ); chữ hội ý. Theo Wiktionary: nữ (女) + người quỳ gối (卩) — người phụ nữ quỳ phục bên cạnh. Hiện đại viết 己 thay 卩.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phi\": người nữ (女) quỳ bên cạnh (己/卩) — phi tần, vợ của thiên tử, địa vị cao quý trong cung đình. | Gương Hán-Việt | phi trong \"phi tần\" — vợ lẽ của vua, địa vị sau hoàng hậu | Mở khoá kiến thức | Biết 妃 mở khoá: 王妃 (vương phi), 太子妃 (thái tử phi), 妃嫔 (phi tần — hậu cung).", "Tự nguyên_Xie": "Giáp cốt văn | Kim văn | Tiểu triện | Lục thư thông | Theo Wiktionary, 妃 là hội ý (ic): 女 (nữ, phụ nữ) + 卩 (người quỳ gối). Hình ảnh gốc: người phụ nữ trong tư thế cúi phục — vợ, người hầu cận. Nghĩa là vợ, đặc biệt là phi tần của vua. Giáp cốt văn, kim văn, tiểu triện và lục thư thông còn lưu qua hanziyuan. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "phi (vợ vua); sánh đôi cùng nhau", "Hạng Tần Suất (Jun Da)": "2569.0", "Tần Suất % (Jun Da)": "98.6134024359", "GavinGrover_Once (Chiết tự trực tiếp)": "女 + 己", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰女己", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "己", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "女", "Unihan_Simplified (Chữ Giản thể)": "妃", "Unihan_Traditional (Chữ Phồn thể)": "妃", "Pinyin_Xie": "fēi", "Âm Hán Việt_Xie": "phi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng sau tên hoặc tước hiệu để chỉ vợ của hoàng đế hoặc vương hầu. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蔑', '{"9000": "2570.0", "Chữ Trung Quốc": "蔑", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 14 | nét | 艹 | thảo | biểu nghĩa | cỏ — phần trên | 罒 | võng | biểu nghĩa | lưới, mắt — đôi mắt | 戍 | thú | biểu nghĩa | lính canh — người + vũ khí | 蔑 là chữ hội ý, phức tạp. Theo Wiktionary: nguyên gồm 𦰋 (người có mắt) + 戈 (qua — vũ khí): hình ảnh vũ khí chặt vào cẳng chân người — tiêu diệt. Trong dạng hiện đại, 𦰋 (mắt+lông mày+người) biến thành ⿱⻀罒 và 人 kết hợp với 戈 thành 戍. Chữ hội ý: tiêu diệt bằng vũ lực.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"miệt\": hình ảnh vũ khí 戈 (qua) chặt vào cẳng chân người — miệt thị, tiêu diệt hoàn toàn, không còn gì. | Gương Hán-Việt | miệt trong 蔑视 (miệt thị — coi thường), 轻蔑 (khinh miệt — khinh thường) | Mở khoá kiến thức | Biết 蔑 (miệt) mở khoá: 蔑视 (coi thường, miệt thị), 轻蔑 (khinh miệt), 污蔑 (vu khống, bôi nhọ).", "Tự nguyên_Xie": "Giáp cốt văn | Kim văn | Theo Wiktionary, 蔑 là chữ hội ý: 𦰋 (người có mắt và lông mày — 眉 trên 人) + 戈 (qua, vũ khí/rìu) → vũ khí giáng vào cẳng chân người — tiêu diệt. Phần 𦰋 ngày nay viết thành ⿱⻀罒 (mắt lông mày), 人 hợp với 戈 thành 戍. Nghĩa gốc là tiêu diệt; mở nghĩa sang khinh thường, coi thường. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tất (đi vào chân)", "Hạng Tần Suất (Jun Da)": "2570.0", "Tần Suất % (Jun Da)": "98.6151233304", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "蔑", "Unihan_Traditional (Chữ Phồn thể)": "蔑", "Pinyin_Xie": "miè", "Âm Hán Việt_Xie": "miệt", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Phó từ | 副词 | Thường làm động từ thể hiện thái độ coi thường hoặc làm phó từ mang nghĩa phủ định. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Phó từ | 副词 | Bổ nghĩa cho động từ hoặc tính từ và luôn đứng TRƯỚC chúng — 都是, 很好. Không đứng sau như tiếng Việt và không bổ nghĩa cho danh từ.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('谕', '{"9000": "2571.0", "Chữ Trung Quốc": "谕", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 11 | nét | 讠 | biểu nghĩa | lời nói (bộ ngôn giản thể) | 俞 | du | biểu âm | du, vâng — cho âm yù | 谕 = 讠(Ngôn giản thể, biểu nghĩa: lời nói) + 俞 (Du, biểu âm); chữ hình thanh. Giản thể của 諭. Bộ ngôn chỉ đây là lời nói/văn bản chính thức, phần 俞 cho âm yù.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"dụ\": lời nói (讠) từ trên truyền xuống (俞) — dụ chỉ, chiếu dụ của vua ban xuống thần dân. | Gương Hán-Việt | dụ trong \"chiếu dụ\" — lệnh vua ban bố | Mở khoá kiến thức | Biết 谕 mở khoá: 圣谕 (thánh dụ — chiếu chỉ), 谕旨 (dụ chỉ — lệnh vua), 晓谕 (hiểu dụ — giải thích rõ ràng cho dân biết).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 谕 là giản thể của 諭, thay bộ 言 bằng 讠. Nghĩa là chỉ bảo từ trên xuống, chiếu dụ của nhà vua hoặc quan lại. Cấu trúc hình thanh: 言 (ngôn) biểu nghĩa lời nói, 俞 biểu âm. Dạng tiểu triện và lục thư thông còn lưu qua hanziyuan. | Suy từ bộ phận cấu thành · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chỉ bảo, hiểu dụ; tỏ rõ", "Hạng Tần Suất (Jun Da)": "2571.0", "Tần Suất % (Jun Da)": "98.6168442249", "GavinGrover_Once (Chiết tự trực tiếp)": "讠 + 俞", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰讠俞", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "俞", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "讠", "Unihan_Simplified (Chữ Giản thể)": "谕", "Unihan_Traditional (Chữ Phồn thể)": "諭", "Pinyin_Xie": "yù", "Âm Hán Việt_Xie": "dụ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường làm danh từ chỉ lời dạy bảo của bề trên hoặc làm động từ chỉ việc truyền đạt ý chí. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('缚', '{"9000": "2572.0", "Chữ Trung Quốc": "缚", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 13 | nét | 纟 | mịch | biểu nghĩa | sợi tơ/vải — trói buộc bằng dây | 尃 | phu | biểu âm | rộng khắp — góp âm fù | 缚 = 纟(Mịch, biểu nghĩa: sợi tơ/dây) + 尃 (Phu, biểu âm: góp âm fù). Chữ hình thanh — 纟chỉ nghĩa dùng dây buộc trói, 尃 góp âm. Dạng giản thể của 縛.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"buộc\": 纟(sợi dây) 尃 (phu — rộng khắp) quấn quanh — buộc chặt, ràng buộc không thoát được. | Gương Hán-Việt | buộc trong 束缚 (thúc buộc — trói buộc), 缚住 (buộc chặt) | Mở khoá kiến thức | Biết 缚 (buộc) mở khoá: 束缚 (trói buộc, hạn chế), 缚手缚脚 (bó tay bó chân — bị hạn chế).", "Tự nguyên_Xie": "Tiểu triện | 缚 là dạng giản thể của 縛, chữ hình thanh: 糸 (mịch, sợi tơ/dây) làm biểu nghĩa, 尃 (phu) làm biểu âm. Nghĩa gốc là trói buộc bằng dây. Mở nghĩa sang ràng buộc (nghĩa bóng), hạn chế tự do. Wiktionary chỉ ghi là dạng giản thể. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "trói buộc, ràng buộc", "Hạng Tần Suất (Jun Da)": "2572.0", "Tần Suất % (Jun Da)": "98.6185630523", "GavinGrover_Once (Chiết tự trực tiếp)": "纟 + 尃", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰纟尃", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "尃", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "纟", "Unihan_Simplified (Chữ Giản thể)": "缚", "Unihan_Traditional (Chữ Phồn thể)": "縛", "Pinyin_Xie": "fù", "Âm Hán Việt_Xie": "phược, phọc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước tân ngữ chỉ người hoặc vật bị trói, hoặc kết hợp trong các từ ghép trừu tượng. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('诡', '{"9000": "2573.0", "Chữ Trung Quốc": "诡", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 8 | nét | 讠 | biểu nghĩa | lời nói (bộ ngôn giản thể) | 危 | nguy | biểu âm | nguy hiểm — cho âm guǐ | 诡 = 讠(Ngôn giản thể, biểu nghĩa: lời nói) + 危 (Nguy, biểu âm); chữ hình thanh. Giản thể của 詭. Bộ ngôn chỉ lời nói, phần 危 cho âm guǐ. Lời nói nguy hiểm, gian dối.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quỷ\": lời nói (讠) đầy nguy hiểm (危) — quỷ kế, mưu lược dối trá như lời của quỷ. | Gương Hán-Việt | quỷ trong \"quỷ kế\" — kế gian, mưu hiểm | Mở khoá kiến thức | Biết 诡 mở khoá: 诡计 (quỷ kế — kế gian), 诡异 (quỷ dị — kỳ lạ), 诡辩 (quỷ biện — nguỵ biện).", "Tự nguyên_Xie": "Tiểu triện | 诡 là giản thể của 詭. Cấu trúc hình thanh: 言 (ngôn) biểu nghĩa lời nói, 危 (nguy) biểu âm. Nghĩa là dối trá, quỷ quyệt, kỳ lạ. Dạng tiểu triện còn lưu. | Suy từ bộ phận cấu thành · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "dối trá, quỷ quyệt", "Hạng Tần Suất (Jun Da)": "2573.0", "Tần Suất % (Jun Da)": "98.6202803293", "GavinGrover_Once (Chiết tự trực tiếp)": "讠 + 危", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰讠危", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "危", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "讠", "Unihan_Simplified (Chữ Giản thể)": "诡", "Unihan_Traditional (Chữ Phồn thể)": "詭", "Pinyin_Xie": "guǐ", "Âm Hán Việt_Xie": "quỷ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường làm tính từ đứng trước danh từ để tu sức hoặc làm định ngữ trong câu. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('篷', '{"9000": "2574.0", "Chữ Trung Quốc": "篷", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 16 | nét | 竹 | trúc | biểu nghĩa | tre — vật liệu làm mái che | 逢 | phùng | biểu âm | gặp — góp âm péng | 篷 = 竹 (Trúc, biểu nghĩa: tre) + 逢 (Phùng, biểu âm: góp âm péng). Chữ hình thanh — 竹 chỉ vật liệu tre làm mái che thuyền hoặc lều, 逢 góp âm. Nghĩa chính là mái che bằng tre, lều bạt.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bồng\": 竹 (tre) đan lại 逢 (phùng — gặp nhau, chắp lại) tạo mái bồng che trên thuyền. | Gương Hán-Việt | bồng trong 帐篷 (trướng bồng — lều bạt), 船篷 (thuyền bồng — mái thuyền) | Mở khoá kiến thức | Biết 篷 (bồng) mở khoá: 帐篷 (lều bạt), 船篷 (mái che thuyền), 车篷 (mui xe).", "Tự nguyên_Xie": "Theo Wiktionary, 篷 là chữ hình thanh: 竹 (trúc, tre) làm biểu nghĩa, 逢 (phùng) làm biểu âm. Nghĩa gốc là mái che bằng tre trên thuyền hoặc xe ngựa. Mở rộng sang lều, bạt căng. 帐篷 (lều bạt) là từ ghép thông dụng nhất. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: bồng bột 篷勃)", "Hạng Tần Suất (Jun Da)": "2574.0", "Tần Suất % (Jun Da)": "98.621993472", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 逢", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮逢", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "逢", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "篷", "Unihan_Traditional (Chữ Phồn thể)": "篷", "Pinyin_Xie": "péng", "Âm Hán Việt_Xie": "bồng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ các loại tấm che bằng vải bạt, tre nứa trên xe, thuyền hoặc dựng ngoài trời. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('淹', '{"9000": "2575.0", "Chữ Trung Quốc": "淹", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 11 | nét | 氵 | thuỷ | biểu nghĩa | nước — liên quan đến chất lỏng che ngập | 奄 | yểm | biểu âm | bỗng nhiên, che phủ — góp âm yān | 淹 = 氵(Thuỷ, biểu nghĩa: nước) + 奄 (Yểm, biểu âm: góp âm yān). Chữ hình thanh — 氵chỉ nghĩa nước bao phủ, nhấn chìm; 奄 góp âm. Nghĩa gốc là ngâm ngập trong nước.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"yêm\": 氵(nước) bất ngờ 奄 (yểm — ập đến, che phủ) — ngập lụt yêm trùm, chìm trong nước. | Gương Hán-Việt | yêm trong 淹没 (yêm một — chìm ngập), 淹死 (yêm tử — chết đuối) | Mở khoá kiến thức | Biết 淹 (yêm) mở khoá: 淹没 (chìm ngập, nhấn chìm), 淹死 (chết đuối), 淹水 (ngập nước).", "Tự nguyên_Xie": "Tiểu triện | 淹 là chữ hình thanh: 氵(thuỷ, nước) làm biểu nghĩa, 奄 (yểm) làm biểu âm. Nghĩa gốc là ngâm trong nước, nhấn chìm, lụt. Mở rộng sang nghĩa bóng: sống lâu ở một chỗ (淹留), sâu rộng (淹博). Wiktionary cung cấp chi tiết về phát âm nhưng không có phân tích chiết tự chi tiết. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1773.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thủy (085) Yểm (1772)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Thủy (số 085 - dòng nước/ 氵/chỉ ý) ở bên trái chữ Yểm (số 1772 - bao trùm/ 奄 /chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Yểm chỉ âm, bộ Thủy chỉ ý. Yêm là bị nước bao trùm lên, nhấn chìm trong nước (yêm một, chết yêm).", "Nghĩa Tiếng Việt_Xie": "ngâm nước", "Hạng Tần Suất (Jun Da)": "2575.0", "Tần Suất % (Jun Da)": "98.6237066147", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 奄", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵奄", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "奄", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "淹", "Unihan_Traditional (Chữ Phồn thể)": "淹", "Pinyin_Xie": "yān", "Âm Hán Việt_Xie": "yêm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ chỉ hành động bị nước nhấn chìm hoặc ngâm trong chất lỏng. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | yān | / | ngập lụt | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Thiên tai", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('腕', '{"9000": "2576.0", "Chữ Trung Quốc": "腕", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 12 | nét | 月 | nguyệt | biểu nghĩa | thịt (bộ nhục viết như nguyệt) | 宛 | uyển | biểu âm | uyển chuyển — cho âm wàn | 腕 = 月/肉 (Nhục, biểu nghĩa: bộ phận cơ thể) + 宛 (Uyển, biểu âm); chữ hình thanh. Bộ nhục (viết giống 月) chỉ đây là bộ phận cơ thể, phần 宛 cho âm wàn. Nghĩa là cổ tay.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"oản\": thịt (月/肉) uyển chuyển (宛) nối bàn tay — oản là cổ tay, khớp mềm nhất trên cánh tay. | Gương Hán-Việt | oản trong \"thủ oản\" (手腕) — cổ tay, cũng có nghĩa thủ đoạn | Mở khoá kiến thức | Biết 腕 mở khoá: 手腕 (thủ oản — cổ tay, thủ đoạn), 大腕 (đại oản — ngôi sao lớn, tên tuổi), 铁腕 (thiết oản — bàn tay sắt).", "Tự nguyên_Xie": "Lục thư thông | Theo Wiktionary, 腕 là hình thanh: 肉 (nhục, bộ phận cơ thể, viết tắt là ⺼) biểu nghĩa, 宛 (uyển) biểu âm. Nghĩa là cổ tay. Dạng lục thư thông còn lưu qua hanziyuan. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cổ tay", "Hạng Tần Suất (Jun Da)": "2576.0", "Tần Suất % (Jun Da)": "98.6254192406", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 宛", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月宛", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "宛", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "腕", "Unihan_Traditional (Chữ Phồn thể)": "腕", "Pinyin_Xie": "wàn", "Âm Hán Việt_Xie": "oản", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ bộ phận cổ tay hoặc năng lực hành động, thường kết hợp thành từ ghép như thủ oản. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('煮', '{"9000": "2577.0", "Chữ Trung Quốc": "煮", "Bộ thủ & thành phần_Xie": "Bộ thủ | 火 | Số nét | 12 | nét | 者 | giả | biểu âm | người (gần âm zhǔ) | 灬 | hoả | biểu nghĩa | lửa (bộ hoả nằm dưới) | 煮 = 者 (Giả, biểu âm) + 灬 (Hoả, biểu nghĩa: lửa); chữ hình thanh. Đun nấu trên lửa, gốc nghĩa ''đun, nấu sôi''.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chử\": 者 (Giả) + 灬 (lửa) — nấu trên lửa, đúng nghĩa ''nấu, đun sôi'' trong 煮饭 (nấu cơm), 煮面 (nấu mì), 煮鸡蛋 (luộc trứng). | Gương Hán-Việt | ''chử'' trong ''chử củi'' (đun củi) — gần với ''nấu'' trong tiếng Việt | Mở khoá kiến thức | Nắm 煮 mở khoá các từ nấu ăn HSK 5: 煮, 煮饭, 煮面.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Theo Wiktionary, 煮 là hình thanh: 者 (Giả, biểu âm) + 火/灬 (lửa, biểu nghĩa) — nấu trên lửa. Nghĩa gốc ''đun, nấu sôi'' (煮饭, 煮面, 煮汤). Trong khẩu ngữ hiện đại, 煮 còn được mượn nghĩa lóng ''tan chảy, mê đắm'' (主 đồng âm). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1554.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Giả (464) Hỏa (085)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Giả (số 464 - đại từ, người/ 者 /chỉ âm) ở trên bộ Hỏa (số 085 - ngọn lửa/ 灬 /chỉ ý). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Giả chỉ âm, bộ Hỏa chỉ ý. Chử là dùng lửa đun cho chín, luộc, nấu, ninh (chử phạn - nấu cơm).", "Nghĩa Tiếng Việt_Xie": "nấu (cơm)", "Hạng Tần Suất (Jun Da)": "2577.0", "Tần Suất % (Jun Da)": "98.6271313498", "GavinGrover_Once (Chiết tự trực tiếp)": "者 + 灬", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱者灬", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "者", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "灬", "Unihan_Simplified (Chữ Giản thể)": "煮", "Unihan_Traditional (Chữ Phồn thể)": "煑", "Pinyin_Xie": "zhǔ", "Âm Hán Việt_Xie": "chử", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ chỉ hoạt động làm chín thức ăn bằng nước sôi, thường mang theo tân ngữ chỉ thực phẩm phía sau. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | Từ đơn | Từ vựng HSK 5: đun sôi | / | zhǔ | / | đun sôi | Xuất hiện trong lộ trình | New HSK | New HSK 6 | · | Thức ăn và đồ uống | HSK | HSK 5 | · | Thức ăn và đồ uống", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('倩', '{"9000": "2578.0", "Chữ Trung Quốc": "倩", "Bộ thủ & thành phần_Xie": "Bộ thủ | 人 | Số nét | 10 | nét | 亻 | nhân | biểu nghĩa | người | 青 | thanh | biểu âm | xanh — cho âm qiàn | 倩 = 亻(Nhân, biểu nghĩa: người) + 青 (Thanh, biểu âm); chữ hình thanh. Bộ nhân chỉ đây mô tả người (đặc biệt là vẻ đẹp người), phần 青 cho âm. Nghĩa là xinh đẹp, duyên dáng; cũng có nghĩa rể (nhà trai).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thiến\": người (亻) trong sáng như xanh (青) — thiến diện, khuôn mặt xinh tươi duyên dáng. | Gương Hán-Việt | thiến trong \"thiến nữ\" — cô gái xinh đẹp duyên dáng | Mở khoá kiến thức | Biết 倩 mở khoá: 倩影 (thiến ảnh — bóng dáng xinh đẹp), 倩女幽魂 (tên phim kinh điển), tên riêng nữ phổ biến.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Theo Wiktionary, 倩 là hình thanh: 人 (nhân) biểu nghĩa, 青 (thanh) biểu âm. Nghĩa là xinh đẹp, duyên dáng (miêu tả người); đồng thời có nghĩa rể (con trai nhà chồng). Dạng tiểu triện và lục thư thông còn lưu qua hanziyuan. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "xinh đẹp; rể, nhà trai", "Hạng Tần Suất (Jun Da)": "2578.0", "Tần Suất % (Jun Da)": "98.6288424254", "GavinGrover_Once (Chiết tự trực tiếp)": "亻 + 青", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰亻青", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "青", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "亻", "Unihan_Simplified (Chữ Giản thể)": "倩", "Unihan_Traditional (Chữ Phồn thể)": "倩", "Pinyin_Xie": "qiàn", "Âm Hán Việt_Xie": "thiến", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Danh từ | 名词 | Chữ này thường làm tính từ miêu tả vẻ đẹp thanh tú của người con gái hoặc làm động từ mang nghĩa nhờ vả trong văn cổ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('卒', '{"9000": "2579.0", "Chữ Trung Quốc": "卒", "Bộ thủ & thành phần_Xie": "Bộ thủ | 十 | Số nét | 8 | nét | 亠 | đầu | biểu nghĩa | đầu, trên cùng | 从 | tòng | biểu nghĩa | theo sau, đi cùng | 十 | thập | biểu nghĩa | số mười, dấu thập | 卒 là chữ tượng hình/hội ý phức tạp. Theo Wiktionary và nghiên cứu giáp cốt văn: ban đầu là hình ảnh 衣 (áo) có dấu — bộ áo đã hoàn thành được đánh dấu. Nghĩa gốc: hoàn thành, xong. Từ đó: cuối cùng, chết (hoàn thành cuộc đời), người lính thấp cấp (mặc áo có dấu hiệu đặc trưng).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thốt\": áo (衣dạng cổ) đã may xong được đánh dấu (十) — thốt nhiên kết thúc, cuối cùng hoàn thành. Quân tốt là người mặc áo lính có dấu. | Gương Hán-Việt | thốt trong \"thốt nhiên\" — bỗng nhiên, đột ngột | Mở khoá kiến thức | Biết 卒 mở khoá: 卒然 (thốt nhiên — bỗng nhiên), 士卒 (sĩ tốt — binh lính), 小卒 (tiểu tốt — quân tốt cờ tướng).", "Tự nguyên_Xie": "Giáp cốt văn | Kim văn | Bạch thư | Tiểu triện | Theo nghiên cứu giáp cốt văn (Qiu 1990, Xuan 2012), 卒 có 5 dạng trong giáp cốt Thương: dạng phổ biến là 衣 (áo) có dấu — chiếc áo hoàn thành được đánh dấu. Nghĩa gốc là \"hoàn thành, xong\". Từ đó phái sinh: cuối cùng (卒), chết (卒), người lính thấp cấp (mặc đồng phục có dấu). Các dạng giáp cốt, kim văn, bạch thư và tiểu triện còn lưu. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1618.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Đầu (008) Nhân (009) Thập (024)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Gồm bộ Đầu (số 008 - bộ chỉ sự nắp đậy/ 亠), hai chữ Nhân (số 009 - con người/ 人) và chữ Thập (số 024 - mười/ 十). Hình ảnh người lính đầu đội nón (亠), mặc áo có cổ chéo chéo (hai chữ 人), cầm thập tự (十) canh gác. Giải thích sự chuyển ý: Tốt là những người lính phục vụ trong quân đội, lính canh (binh tốt, tốt hầu). Cũng có nghĩa là xong việc, cuối cùng (tốt cục).", "Nghĩa Tiếng Việt_Xie": "cuối cùng", "Hạng Tần Suất (Jun Da)": "2579.0", "Tần Suất % (Jun Da)": "98.630550917", "GavinGrover_Once (Chiết tự trực tiếp)": "亠 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱亠", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "卒", "Unihan_Traditional (Chữ Phồn thể)": "䘚", "Pinyin_Xie": "zú", "Âm Hán Việt_Xie": "thốt, tuất, tốt", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Phó từ | 副词 | Chữ này làm danh từ chỉ người lính cấp thấp hoặc làm động từ chỉ sự kết thúc, qua đời trong văn viết cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Phó từ | 副词 | Bổ nghĩa cho động từ hoặc tính từ và luôn đứng TRƯỚC chúng — 都是, 很好. Không đứng sau như tiếng Việt và không bổ nghĩa cho danh từ.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('勘', '{"9000": "2580.0", "Chữ Trung Quốc": "勘", "Bộ thủ & thành phần_Xie": "Bộ thủ | 力 | Số nét | 11 | nét | 甚 | thậm | biểu âm | rất, quá — góp âm kān | 力 | lực | biểu nghĩa | sức lực — dùng sức tra xét | 勘 = 甚 (Thậm, biểu âm: góp âm kān) + 力 (Lực, biểu nghĩa: sức lực). Chữ hình thanh — 力 chỉ nghĩa dùng sức lực tra xét kỹ lưỡng, 甚 góp âm. Nghĩa là điều tra, thẩm tra, đối chiếu.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khám\": dùng 力 (lực — sức) tra 甚 (thậm — xét thật kỹ) — khám xét, điều tra thực địa. | Gương Hán-Việt | khám trong 勘探 (khám thám — thăm dò), 勘察 (khám sát — khảo sát) | Mở khoá kiến thức | Biết 勘 (khám) mở khoá: 勘探 (thăm dò khoáng sản), 勘察 (khảo sát thực địa), 勘误 (đính chính lỗi in).", "Tự nguyên_Xie": "Đại triện | Theo Wiktionary, 勘 là chữ hình thanh: 力 (lực, sức mạnh) làm biểu nghĩa — xét kỹ, nhìn mạnh; 甚 (thậm) làm biểu âm. Nghĩa gốc là đọc đối chiếu cẩn thận, tra xét. Mở nghĩa sang điều tra thực địa (勘探 — thăm dò khoáng sản). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "so sánh; tra hỏi phạm nhân", "Hạng Tần Suất (Jun Da)": "2580.0", "Tần Suất % (Jun Da)": "98.6322578583", "GavinGrover_Once (Chiết tự trực tiếp)": "甚 + 力", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰甚力", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "甚", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "力", "Unihan_Simplified (Chữ Giản thể)": "勘", "Unihan_Traditional (Chữ Phồn thể)": "勘", "Pinyin_Xie": "kān", "Âm Hán Việt_Xie": "khám", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ chỉ hành vi khảo sát thực địa hoặc tra xét kỹ lưỡng, thường đi kèm tân ngữ phía sau. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('馨', '{"9000": "2581.0", "Chữ Trung Quốc": "馨", "Bộ thủ & thành phần_Xie": "Bộ thủ | 香 | Số nét | 20 | nét | 殸 | thanh | biểu âm | tiếng nhạc cụ — cho âm xīn | 香 | hương | biểu nghĩa | hương thơm | 馨 = 殸 (Thanh, biểu âm) + 香 (Hương, biểu nghĩa: hương thơm); chữ hình thanh. Bộ hương chỉ đây liên quan đến mùi thơm, phần 殸 cho âm. Nghĩa là hương thơm bay xa, mùi thơm phảng phất.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hinh\": hương thơm (香) bay xa theo tiếng nhạc (殸) — hinh hương, mùi thơm ngát bay tận trời xa. | Gương Hán-Việt | hinh trong \"nhiệt hinh\" (温馨) — ấm cúng, dịu dàng | Mở khoá kiến thức | Biết 馨 mở khoá: 温馨 (ôn hinh — ấm cúng), 馨香 (hinh hương — mùi thơm bay xa), tên riêng phổ biến cả nam lẫn nữ.", "Tự nguyên_Xie": "Theo Wiktionary, 馨 là hình thanh: 殸 biểu âm, 香 (hương) biểu nghĩa. Nghĩa là hương thơm bay xa, phảng phất — khác 香 là hương gần. 馨 thường dùng trong ngữ cảnh hương thơm ấm áp, tình cảm (温馨), tên riêng. Không có hình ảnh cổ. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thơm lừng, hương bay ngát ra", "Hạng Tần Suất (Jun Da)": "2581.0", "Tần Suất % (Jun Da)": "98.6339534304", "GavinGrover_Once (Chiết tự trực tiếp)": "殸 + 香", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱殸香", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "殸", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "香", "Unihan_Simplified (Chữ Giản thể)": "馨", "Unihan_Traditional (Chữ Phồn thể)": "馨", "Pinyin_Xie": "xīn", "Âm Hán Việt_Xie": "hinh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Chữ này chủ yếu làm tính từ miêu tả hương thơm ngào ngạt hoặc danh từ chỉ tiếng thơm, đạo đức tốt đẹp. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('逗', '{"9000": "2582.0", "Chữ Trung Quốc": "逗", "Bộ thủ & thành phần_Xie": "Bộ thủ | 辵 | Số nét | 10 | nét | 辶 | sước | biểu nghĩa | đi, di chuyển | 豆 | đậu | biểu âm | đậu hạt — cho âm đậu | 逗 = 辶(Sước, biểu nghĩa: đi) + 豆 (Đậu, biểu âm); chữ hình thanh. Wiktionary ghi: {{Han compound|辵|alt1=辶|豆|ls=psc|c1=s|c2=p}}. Bộ sước chỉ chuyển động; 豆 cho âm dòu. Nghĩa gốc là dừng lại giữa chừng; nghĩa hiện đại là trêu đùa, vui nhộn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đậu\": bộ đi (辶) dừng lại như hạt đậu (豆-Đậu) — trêu ai đó bằng cách dừng lại chọc ghẹo. Đậu = trêu đùa. | Gương Hán-Việt | đậu trong ''đậu hũ, đậu phụ'' — cùng âm; 逗 là trêu đùa, không liên quan hạt đậu | Mở khoá kiến thức | Biết 逗 mở khoá: 逗笑 (đậu tiếu – khiến cười), 逗留 (đậu lưu – lưu lại, nán lại), 好逗 (hảo đậu – vui nhộn).", "Tự nguyên_Xie": "逗 là chữ hình thanh: 辶 (sước – đi, chuyển động) biểu nghĩa, 豆 (đậu) biểu âm. Nghĩa gốc là dừng lại giữa đường. Trong tiếng Trung cổ đại, 逗留 có nghĩa dừng chân. Nghĩa ''trêu đùa, vui nhộn'' (逗笑, 好逗) là phát triển ngữ nghĩa về sau — có lẽ từ hình ảnh dừng lại ''cắt ngang'' dòng chảy bình thường để gây chú ý. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đậu lại, đỗ lại, dừng lại", "Hạng Tần Suất (Jun Da)": "2582.0", "Tần Suất % (Jun Da)": "98.6356438345", "GavinGrover_Once (Chiết tự trực tiếp)": "辶 + 豆", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴辶豆", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "豆", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "辶", "Unihan_Simplified (Chữ Giản thể)": "逗", "Unihan_Traditional (Chữ Phồn thể)": "逗", "Pinyin_Xie": "dòu", "Âm Hán Việt_Xie": "đậu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Chữ này làm động từ chỉ hành động trêu đùa làm cho cười hoặc dừng lại, trì hoãn tại một điểm. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | Từ đơn | Từ vựng HSK 5: vui nhộn | / | dòu | / | vui nhộn | Xuất hiện trong lộ trình | HSK | HSK 5 | · | Thể thao và giải trí | New HSK | New HSK 7-9 | · | Tiếng cười", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('甸', '{"9000": "2583.0", "Chữ Trung Quốc": "甸", "Bộ thủ & thành phần_Xie": "Bộ thủ | 田 | Số nét | 7 | nét | 勹 | bao | biểu nghĩa | bao bọc, vây quanh | 田 | điền | biểu âm | ruộng đồng — cho âm diān | 甸 = 勹 (Bao, biểu nghĩa: vây quanh) + 田 (Điền, biểu âm/biểu nghĩa: ruộng đồng); theo Wiktionary: 人 (nhân) + 田 (điền), hình thanh hoặc hội ý. Nghĩa gốc: người làm ruộng ở vùng ven kinh đô, khu ngoại ô nông nghiệp.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"điện\": ruộng (田) bao quanh (勹) kinh thành — điền giáp, khu ngoại ô nông nghiệp cung cấp lương thực cho kinh đô. | Gương Hán-Việt | điện trong \"kinh điện\" — vùng ngoại ô kinh đô | Mở khoá kiến thức | Biết 甸 mở khoá: 沉甸甸 (trầm điện điện — nặng trĩu), 甸子 (điền tử — thảo nguyên), vùng tên địa lý Đông Nam Á (Miến Điện = Myanmar).", "Tự nguyên_Xie": "Kim văn | Tiểu triện | Theo Wiktionary (ghi {{Han etyl}}), 甸 là hình thanh hoặc hội ý: 人 (nhân) biểu nghĩa người/biểu âm, 田 (điền) biểu nghĩa ruộng. Nghĩa gốc là vùng ngoại ô kinh đô dùng để canh tác và thu thuế ruộng đất. Dạng kim văn và tiểu triện còn lưu. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "khu, cõi; thuế ruộng; một chức quan về ruộng", "Hạng Tần Suất (Jun Da)": "2583.0", "Tần Suất % (Jun Da)": "98.6373337219", "GavinGrover_Once (Chiết tự trực tiếp)": "勹 + 田", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴勹田", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "田", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "勹", "Unihan_Simplified (Chữ Giản thể)": "甸", "Unihan_Traditional (Chữ Phồn thể)": "甸", "Pinyin_Xie": "diān", "Âm Hán Việt_Xie": "điện, điền, thịnh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ vùng đất ngoại ô hoặc khu vực quản lý thời xưa, nay thường xuất hiện trong các địa danh. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('贱', '{"9000": "2584.0", "Chữ Trung Quốc": "贱", "Bộ thủ & thành phần_Xie": "Bộ thủ | 貝 | Số nét | 9 | nét | 贝 | bối | biểu nghĩa | vỏ sò, tiền tệ | 戋 | tiên | biểu âm | nhỏ, ít — cho âm jiàn | 贱 = 贝 (Bối, biểu nghĩa: tiền/giá trị) + 戋 (Tiên, biểu âm); chữ hình thanh. Phồn thể 賤 dùng 貝 và 戔. Bộ bối chỉ giá trị tiền tệ, phần 戋 cho âm. Nghĩa: rẻ tiền, ti tiện, thấp hèn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tiện\": tiền (贝) ít ỏi (戋) — tiện giá, rẻ mạt như đồng tiền nhỏ không đáng kể. | Gương Hán-Việt | tiện trong \"ti tiện\" — thấp hèn, đê tiện | Mở khoá kiến thức | Biết 贱 mở khoá: 贫贱 (bần tiện — nghèo hèn), 低贱 (đê tiện — thấp hèn), 贵贱 (quý tiện — sang hèn).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 賤 là hình thanh: 貝 (bối) biểu nghĩa tiền tệ/giá trị, 戔 (tiên) biểu âm. Nghĩa gốc là rẻ tiền, ít giá trị. Mở rộng: thấp hèn, đê tiện, khinh thường. Dạng tiểu triện còn lưu. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "rẻ mạt; nghèo hèn", "Hạng Tần Suất (Jun Da)": "2584.0", "Tần Suất % (Jun Da)": "98.6390236093", "GavinGrover_Once (Chiết tự trực tiếp)": "贝 + 戋", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰贝戋", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "戋", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "贝", "Unihan_Simplified (Chữ Giản thể)": "贱", "Unihan_Traditional (Chữ Phồn thể)": "賤", "Pinyin_Xie": "jiàn", "Âm Hán Việt_Xie": "tiện", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Chữ này làm tính từ chỉ giá trị vật chất thấp hoặc địa vị xã hội hèn kém, thường đứng trước danh từ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | jiàn | / | rẻ tiền | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Kinh tế và tài chính I", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('炒', '{"9000": "2585.0", "Chữ Trung Quốc": "炒", "Bộ thủ & thành phần_Xie": "Bộ thủ | 火 | Số nét | 8 | nét | 火 | hoả | biểu nghĩa | lửa | 少 | thiểu | biểu âm | ít — cho âm thiểu/sao | 炒 = 火 (Hoả, biểu nghĩa: lửa) + 少 (Thiểu, biểu âm); chữ hình thanh. Wiktionary ghi: {{Han compound|火|少|ls=psc|c1=s|c2=p}}. Bộ hoả chỉ hành động dùng lửa; 少 cho âm chǎo (gần thiểu). Xào là đảo thức ăn trên lửa lớn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sao\": lửa (火-Hoả) ít (少-Thiểu) — dùng ít lửa to đảo nhanh = xào sao. Sao lúa, xào rau đều dùng chữ 炒. | Gương Hán-Việt | sao trong ''sao chép, sao lại'' — âm giống; nhưng 炒 là xào nấu, không liên quan sao chép | Mở khoá kiến thức | Biết 炒 mở khoá: 炒饭 (sao phạn – cơm chiên), 炒菜 (sao thái – xào rau), 炒作 (sao tác – đầu cơ thổi giá).", "Tự nguyên_Xie": "炒 là chữ hình thanh: 火 (hoả – lửa) biểu nghĩa, 少 (thiểu) biểu âm. Kỹ thuật xào (炒) dùng lửa lớn đảo nhanh là đặc trưng nấu ăn Trung Hoa. Từ 炒 mở rộng sang nghĩa ''đầu cơ thổi giá'' (炒作, 炒股) — hình ảnh đảo nhanh như đảo chảo. Wiktionary xác nhận cấu trúc psc. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sào (rau), tráng (trứng), rang (cơm), sao (thuốc)", "Hạng Tần Suất (Jun Da)": "2585.0", "Tần Suất % (Jun Da)": "98.6407083289", "GavinGrover_Once (Chiết tự trực tiếp)": "火 + 少", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰火少", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "少", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "火", "Unihan_Simplified (Chữ Giản thể)": "炒", "Unihan_Traditional (Chữ Phồn thể)": "炒", "Pinyin_Xie": "chǎo", "Âm Hán Việt_Xie": "sao", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ chỉ phương pháp nấu nướng xào rang hoặc hành vi đầu cơ tích trữ trong kinh tế. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | Từ đơn | Từ vựng HSK 5: xào, chiên | / | chǎo | / | xào, chiên | Xuất hiện trong lộ trình | New HSK | New HSK 6 | · | Thức ăn và đồ uống | HSK | HSK 5 | · | Thức ăn và đồ uống", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('灿', '{"9000": "2586.0", "Chữ Trung Quốc": "灿", "Bộ thủ & thành phần_Xie": "Bộ thủ | 火 | Số nét | 7 | nét | 火 | hoả | biểu nghĩa | lửa — ánh sáng rực rỡ | 山 | sơn | biểu âm | núi — góp âm (dạng giản thể của 粲) | 灿 là dạng giản thể của 燦. Cấu trúc phồn thể 燦 = 火 (hoả, biểu nghĩa: lửa) + 粲 (biểu âm: góp âm càn). Dạng giản thể 灿 rút 粲 thành 山 làm biểu âm. Chữ hình thanh — 火 gợi ánh sáng lửa rực rỡ, 粲/山 góp âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"xán\": 火 (lửa) bùng cháy trên 山 (sơn — đỉnh núi) — ánh xán lạn toả ra bốn phương. | Gương Hán-Việt | xán trong 灿烂 (xán lạn — rực rỡ), 灿灿 (xán xán — sáng lóng lánh) | Mở khoá kiến thức | Biết 灿 (xán) mở khoá: 灿烂 (rực rỡ, tươi sáng), 灿灿 (sáng ngời), 灿烂多姿 (rực rỡ muôn màu).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 灿 (dạng phồn thể 燦) là chữ hình thanh: 火 (hoả, lửa) làm biểu nghĩa, 粲 (làm biểu âm góp âm càn). Nghĩa gốc là sáng chói, rực rỡ như ánh lửa. 灿烂 (xán lạn — rực rỡ) là từ ghép chính. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: xán lạn 燦爛)", "Hạng Tần Suất (Jun Da)": "2586.0", "Tần Suất % (Jun Da)": "98.6423899477", "GavinGrover_Once (Chiết tự trực tiếp)": "火 + 山", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰火山", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "山", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "火", "Unihan_Simplified (Chữ Giản thể)": "灿", "Unihan_Traditional (Chữ Phồn thể)": "燦", "Pinyin_Xie": "càn", "Âm Hán Việt_Xie": "xán", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này làm tính từ miêu tả vẻ sáng chói, rực rỡ, thường kết hợp với chữ lạn để tạo thành từ ghép xán lạn. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('敞', '{"9000": "2587.0", "Chữ Trung Quốc": "敞", "Bộ thủ & thành phần_Xie": "Bộ thủ | 攴 | Số nét | 12 | nét | 尚 | thượng | biểu âm | còn, vẫn — góp âm chǎng | 攵 | phộc | biểu nghĩa | gõ nhẹ, hành động — mở ra | 敞 = 尚 (Thượng, biểu âm: góp âm chǎng) + 攵 (Phộc, biểu nghĩa: hành động mở ra). Chữ hình thanh — 攵 gợi hành động mở rộng, 尚 góp âm. Wiktionary chỉ ghi {{Han etym}} không có phân tích chi tiết. Nghĩa là rộng rãi, thoáng đãng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sưởng\": 攵 (tay mở ra) giang rộng như 尚 (thượng — cao rộng) — không gian sưởng đãng, thoáng mát, mở ra tứ phía. | Gương Hán-Việt | sưởng trong 宽敞 (khoan sưởng — rộng rãi), 敞开 (sưởng khai — mở rộng) | Mở khoá kiến thức | Biết 敞 (sưởng) mở khoá: 宽敞 (rộng rãi), 敞开 (mở rộng, cởi mở), 宽敞明亮 (rộng rãi sáng sủa).", "Tự nguyên_Xie": "Đại triện | Tiểu triện | 敞 gồm 尚 (thượng) góp âm và 攵 (phộc) làm biểu nghĩa liên quan đến hành động mở ra, dang rộng. Wiktionary không cung cấp phân tích chi tiết về nguồn gốc chữ này. Nghĩa gốc là rộng, thoáng mát, không bị che khuất. Chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "rộng; thoáng mát; rộng rãi; rộng thoáng (phòng ốc)", "Hạng Tần Suất (Jun Da)": "2587.0", "Tần Suất % (Jun Da)": "98.6440684658", "GavinGrover_Once (Chiết tự trực tiếp)": "尚 + ⺙", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰尚⺙", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "尚", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺙", "Unihan_Simplified (Chữ Giản thể)": "敞", "Unihan_Traditional (Chữ Phồn thể)": "敞", "Pinyin_Xie": "chǎng", "Âm Hán Việt_Xie": "xưởng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Chữ này làm tính từ miêu tả không gian rộng rãi, thoáng mát hoặc làm động từ với nghĩa mở rộng ra. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蜡', '{"9000": "2588.0", "Chữ Trung Quốc": "蜡", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 14 | nét | 虫 | trùng | biểu nghĩa | côn trùng — sáp ong do côn trùng tạo ra | 昔 | tích | biểu âm | ngày xưa — góp âm là | 蜡 = 虫 (Trùng, biểu nghĩa: côn trùng) + 昔 (Tích, biểu âm: góp âm là). Chữ hình thanh — 虫 gợi nguồn gốc từ côn trùng (sáp ong, sâu sáp), 昔 góp âm. Wiktionary chỉ ghi {{Han etym}} không có phân tích chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lạp\": 虫 (côn trùng) 昔 (tích — ngày xưa) tiết ra chất lạp sáp — ong mật cần cù cho ta nến lạp. | Gương Hán-Việt | lạp trong 蜡烛 (lạp chúc — nến sáp), 蜡纸 (lạp chỉ — giấy sáp) | Mở khoá kiến thức | Biết 蜡 (lạp) mở khoá: 蜡烛 (nến sáp), 蜡笔 (bút sáp màu), 蜡纸 (giấy sáp), 蜡像 (tượng sáp).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 蜡 là chữ hình thanh: 虫 (trùng, côn trùng) làm biểu nghĩa — sáp do ong hoặc sâu tiết ra; 昔 (tích) làm biểu âm góp âm là. Nghĩa gốc là sáp, chất dẻo từ côn trùng. Mở rộng sang nến sáp (蜡烛), đánh bóng bằng sáp. Wiktionary không cung cấp phân tích chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sáp; nến; lạp; đèn cầy", "Hạng Tần Suất (Jun Da)": "2588.0", "Tần Suất % (Jun Da)": "98.6457459504", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 昔", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫昔", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "昔", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蜡", "Unihan_Traditional (Chữ Phồn thể)": "蠟", "Pinyin_Xie": "là", "Âm Hán Việt_Xie": "lạp, trá", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng sau các từ chỉ chất liệu hoặc làm định ngữ bổ nghĩa cho danh từ khác như lạp chúc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | là | / | sáp, nến | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Ngôi nhà và cuộc sống hàng ngày II", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('囚', '{"9000": "2589.0", "Chữ Trung Quốc": "囚", "Bộ thủ & thành phần_Xie": "Bộ thủ | 囗 | Số nét | 5 | nét | 囗 | vi | biểu nghĩa | vây quanh, hộp kín | 人 | nhân | biểu nghĩa | người | 囚 = 囗 (Vi, biểu nghĩa: vây kín) + 人 (Nhân, biểu nghĩa: người); chữ hội ý. Người bị giam trong hộp kín — tù nhân. Rõ ràng và trực quan nhất trong tiếng Hán.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tù\": người (人) bị giam trong khuôn (囗) — tù nhân, bị nhốt không thoát ra được. | Gương Hán-Việt | tù trong \"tù nhân\" — người bị giam giữ | Mở khoá kiến thức | Biết 囚 mở khoá: 囚犯 (tù phạm — tù nhân), 囚禁 (tù cầm — giam giữ), 囚笼 (tù lung — chuồng nhốt).", "Tự nguyên_Xie": "Theo Wiktionary, 囚 là hội ý (ic): 囗 (vi, hộp kín/vây quanh) + 人 (nhân, người) — người bị nhốt trong khuôn: tù nhân. Wiktionary lưu ý chữ này tương tự nhưng không liên quan đến 因. Không có hình ảnh cổ riêng. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "133.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Vi (132) Nhân (42)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Nhân (số 12) ở trong chữ Vi (số 132) . Hình ảnh kẻ phạm tội bị nhốt trong 4 bức tường của nhà giam.", "Nghĩa Tiếng Việt_Xie": "tù, giam giữ", "Hạng Tần Suất (Jun Da)": "2589.0", "Tần Suất % (Jun Da)": "98.6474213678", "GavinGrover_Once (Chiết tự trực tiếp)": "囗 + 人", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Bao quanh toàn bộ)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴囗人", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "人", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "囗", "Unihan_Simplified (Chữ Giản thể)": "囚", "Unihan_Traditional (Chữ Phồn thể)": "囚", "Pinyin_Xie": "qiú", "Âm Hán Việt_Xie": "tù", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Làm danh từ chỉ phạm nhân hoặc làm động từ mang tân ngữ với nghĩa giam cầm trong ngục. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('栗', '{"9000": "2590.0", "Chữ Trung Quốc": "栗", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 10 | nét | 栗 | lật | tượng hình | cây dẻ với quả mọc trên cành — tượng hình | 栗 là chữ tượng hình: hình ảnh cây (木) với quả dẻ (覀/果) mọc trên cành. Wiktionary xác nhận đây là pictogram (liushu: p) — mô tả hạt dẻ mọc trên cây. Tương tự 果 và 某 nhưng không liên quan đến 要 hay 票.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lật\": cây (木) có quả tròn mọc trên đầu (覀) — lật tử, hạt dẻ mùa thu rơi từ cây xuống lật đật. | Gương Hán-Việt | lật trong \"bộ lật\" — hạt dẻ, thực phẩm mùa thu đặc trưng | Mở khoá kiến thức | Biết 栗 mở khoá: 栗子 (lật tử — hạt dẻ), 板栗 (bản lật — dẻ Trung Quốc), 战栗 (chiến lật — run rẩy sợ hãi).", "Tự nguyên_Xie": "Giáp cốt văn | Đại triện | Tiểu triện | Theo Wiktionary, 栗 là tượng hình (pictogram): hình cây dẻ với quả mọc trên cành. Nghĩa gốc là cây dẻ (chestnut) và hạt dẻ. Mở rộng sang: bền chắc, run rẩy (sợ hãi). Giáp cốt văn, đại triện và tiểu triện còn lưu. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cây lật, cây dẻ; bền chắc", "Hạng Tần Suất (Jun Da)": "2590.0", "Tần Suất % (Jun Da)": "98.6490957516", "GavinGrover_Once (Chiết tự trực tiếp)": "覀 + 木", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱覀木", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "木", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "覀", "Unihan_Simplified (Chữ Giản thể)": "栗", "Unihan_Traditional (Chữ Phồn thể)": "慄", "Pinyin_Xie": "lì", "Âm Hán Việt_Xie": "lật", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường dùng làm danh từ chỉ hạt dẻ hoặc làm động từ thể hiện trạng thái run sợ trong văn viết. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('辜', '{"9000": "2591.0", "Chữ Trung Quốc": "辜", "Bộ thủ & thành phần_Xie": "Bộ thủ | 辛 | Số nét | 12 | nét | 古 | cổ | biểu âm | cổ xưa — góp âm gū | 辛 | tân | biểu nghĩa | cay đắng, hình phạt — liên quan đến tội lỗi | 辜 = 古 (Cổ, biểu âm: góp âm gū) + 辛 (Tân, biểu nghĩa: liên quan đến hình phạt cay đắng). Chữ hình thanh — 辛 gợi nghĩa tội lỗi gây đau khổ, 古 góp âm. Wiktionary xác nhận cấu trúc này với c1=p (phonetic), c2=s (semantic).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cô\": 辛 (tân — cay đắng, hình phạt) của 古 (cổ — thời xưa) — mang tội cô độc, lỗi lầm cay đắng. | Gương Hán-Việt | cô trong 辜负 (cô phụ — phụ lòng), 无辜 (vô cô — vô tội) | Mở khoá kiến thức | Biết 辜 (cô) mở khoá: 辜负 (phụ lòng, làm thất vọng), 无辜 (vô tội), 死有余辜 (tội chết vẫn chưa đủ).", "Tự nguyên_Xie": "Kim văn | Đại triện | Tiểu triện | Theo Wiktionary, 辜 là chữ hình thanh: 古 (cổ) làm biểu âm, 辛 (tân, cay/hình phạt cổ đại) làm biểu nghĩa — tội lỗi gây khổ đau cay đắng. Nghĩa gốc là tội, lỗi lầm. Mở rộng sang 辜负 (để phụ lòng, phụ bạc). Tên họ Koo/Gu nổi tiếng ở Đài Loan. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tội, lỗi; mổ phanh thây", "Hạng Tần Suất (Jun Da)": "2591.0", "Tần Suất % (Jun Da)": "98.6507675515", "GavinGrover_Once (Chiết tự trực tiếp)": "古 + 辛", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱古辛", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "古", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "辛", "Unihan_Simplified (Chữ Giản thể)": "辜", "Unihan_Traditional (Chữ Phồn thể)": "辜", "Pinyin_Xie": "gū", "Âm Hán Việt_Xie": "cô", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường xuất hiện trong các từ ghép như vô cô hoặc làm động từ trong cô phụ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('垫', '{"9000": "2592.0", "Chữ Trung Quốc": "垫", "Bộ thủ & thành phần_Xie": "Bộ thủ | 土 | Số nét | 9 | nét | 执 | chấp | biểu âm | nắm giữ — góp âm diàn | 土 | thổ | biểu nghĩa | đất — kê lót dưới sàn | 垫 là dạng giản thể của 墊. Cấu trúc: 执 (chấp, biểu âm) + 土 (thổ, biểu nghĩa: đất). Chữ hình thanh — 土 gợi nghĩa kê, lót xuống đất để nâng lên; 执 góp âm. Nghĩa gốc là kê lót, thấp xuống.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"điếm\": 土 (đất) + 执 (chấp — nắm giữ chắc) — kê điếm xuống đất, đệm bên dưới để nâng lên. | Gương Hán-Việt | điếm trong 垫子 (điếm tử — tấm đệm), 坐垫 (toạ điếm — đệm ngồi) | Mở khoá kiến thức | Biết 垫 (điếm) mở khoá: 垫子 (tấm đệm), 垫底 (nền tảng, đặt dưới cùng), 垫付 (trả tiền thay), 坐垫 (đệm ngồi).", "Tự nguyên_Xie": "Tiểu triện | 垫 là dạng giản thể của 墊 (執 + 土). Cấu trúc hình thanh: 土 (thổ, đất) làm biểu nghĩa, 執 (chấp) làm biểu âm. Nghĩa gốc là thứ kê lót dưới, tấm đệm. Mở rộng sang: trả thay (垫付), kê lót, đặt dưới cùng. Wiktionary chỉ ghi là dạng giản thể. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thấp xuống; chết đuối; kê, đệm", "Hạng Tần Suất (Jun Da)": "2592.0", "Tần Suất % (Jun Da)": "98.6524383178", "GavinGrover_Once (Chiết tự trực tiếp)": "执 + 土", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱执土", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "执", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "土", "Unihan_Simplified (Chữ Giản thể)": "垫", "Unihan_Traditional (Chữ Phồn thể)": "墊", "Pinyin_Xie": "diàn", "Âm Hán Việt_Xie": "điếm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Làm động từ chỉ hành động kê lót hoặc trả tiền hộ, hoặc làm danh từ chỉ tấm đệm. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | diàn | / | trả tiền thay | / | diàn | / | lót | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Động từ tôi | New HSK 7-9 | · | Kinh tế và Tài chính II | HSK | HSK 6 | · | Động từ hàng ngày", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('妒', '{"9000": "2593.0", "Chữ Trung Quốc": "妒", "Bộ thủ & thành phần_Xie": "Bộ thủ | 女 | Số nét | 7 | nét | 女 | nữ | biểu nghĩa | phụ nữ — ghen tuông trong quan hệ | 户 | hộ | biểu âm | cửa nhà — góp âm dù | 妒 = 女 (Nữ, biểu nghĩa: người phụ nữ) + 户 (Hộ, biểu âm: góp âm dù). Chữ hình thanh — 女 chỉ nghĩa ghen tuông trong quan hệ, 户 góp âm. Theo Thuyết văn giải tự, 妒 có thể là biến dạng của 妬 (妒 là bộ 女 + 戶 hoặc + 妬). Nghĩa là ghen tỵ, đố kỵ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đố\": 女 (phụ nữ) đứng sau cánh 户 (hộ — cửa) dòm ngó — đố kỵ, ghen tỵ nhìn qua cửa sổ. | Gương Hán-Việt | đố trong 嫉妒 (tật đố — ghen tị), 妒忌 (đố kỵ — ghen ghét) | Mở khoá kiến thức | Biết 妒 (đố) mở khoá: 嫉妒 (ghen tị), 妒忌 (đố kỵ, ghen ghét), 妒贤嫉能 (đố kỵ người tài).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Theo Wiktionary, 妒 là chữ hình thanh: 女 (nữ) làm biểu nghĩa, 戶 (hộ) làm biểu âm. Sách Thuyết văn giải tự chú rằng 妒 là biến dạng viết tay của 妬 (妒 với 女+石). Nghĩa gốc là phụ nữ ghen tuông với chồng hoặc người phụ nữ khác; mở rộng sang mọi loại ghen tị, đố kỵ. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "370.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Nữ (60) Hộ (336)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Hộ (số 336) chỉ âm, chữ Nữ (số 86) chỉ ý. Đố là chỉ người đàn bà (nữ) sinh lòng ghen ghét vì mình không bằng người khác. Giải thích sự chuyển ý: Chữ Hộ (cửa) chỉ âm, chữ Nữ (phụ nữ) chỉ ý. Người đàn bà (Nữ) hay đứng nấp sau cánh cửa (Hộ) để rình rập, ghen tuông (Đố). *(Biến âm Hán Việt: Trong Hán ngữ cổ, chữ Hộ và chữ Đố có cách phát âm tương đồng hoặc chung gốc phụ âm. Quá trình Việt hóa đã làm âm đọc bị chênh lệch thành Hộ và Đố).*", "Nghĩa Tiếng Việt_Xie": "ghét, ghen tỵ", "Hạng Tần Suất (Jun Da)": "2593.0", "Tần Suất % (Jun Da)": "98.6541065003", "GavinGrover_Once (Chiết tự trực tiếp)": "女 + 户", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰女户", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "户", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "女", "Unihan_Simplified (Chữ Giản thể)": "妒", "Unihan_Traditional (Chữ Phồn thể)": "妒", "Pinyin_Xie": "dù", "Âm Hán Việt_Xie": "đố", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Làm động từ thể hiện tâm lý ghen tị, thường kết hợp với các từ chỉ đối tượng bị ghen ghét. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('魁', '{"9000": "2594.0", "Chữ Trung Quốc": "魁", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鬼 | Số nét | 13 | nét | 鬼 | quỷ | biểu âm | ma quỷ — cho âm kuí | 斗 | đẩu | biểu nghĩa | cái gáo múc — cái muôi | 魁 = 鬼 (Quỷ, biểu âm) + 斗 (Đẩu, biểu nghĩa: cái gáo múc canh); chữ hình thanh. Theo Wiktionary: 斗 biểu nghĩa cái muôi, 鬼 biểu âm. Nghĩa gốc là cái gáo múc canh, sau mở rộng: đứng đầu, thủ lĩnh, sao Khôi.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khôi\": gáo múc (斗) lớn như quỷ (鬼) — khôi nguyên, đứng đầu như sao Khôi dẫn đầu Bắc Đẩu. | Gương Hán-Việt | khôi trong \"khôi nguyên\" — người đỗ đầu trong thi cử | Mở khoá kiến thức | Biết 魁 mở khoá: 魁首 (khôi thủ — đứng đầu), 罪魁祸首 (tội khôi hoạ thủ — kẻ chủ mưu), 魁梧 (khôi ngô — vóc người to lớn).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 魁 là hình thanh: 鬼 (quỷ) biểu âm, 斗 (đẩu, cái gáo) biểu nghĩa. Nghĩa gốc là cái muôi múc canh. Mở rộng: to lớn, đứng đầu, thủ lĩnh (kẻ \"múc\" hết phần to nhất). Sao Khôi (魁星) là sao đứng đầu chòm Bắc Đẩu. Dạng tiểu triện còn lưu. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đứng đầu, đầu sỏ; cái muôi múc canh; sao Khôi", "Hạng Tần Suất (Jun Da)": "2594.0", "Tần Suất % (Jun Da)": "98.6557741659", "GavinGrover_Once (Chiết tự trực tiếp)": "鬼 + 斗", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴鬼斗", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "斗", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鬼", "Unihan_Simplified (Chữ Giản thể)": "魁", "Unihan_Traditional (Chữ Phồn thể)": "魁", "Pinyin_Xie": "kuí", "Âm Hán Việt_Xie": "khôi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Thường làm tính từ bổ nghĩa cho danh từ để chỉ sự to lớn, khôi ngô hoặc người đứng đầu. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('谣', '{"9000": "2595.0", "Chữ Trung Quốc": "谣", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 12 | nét | 讠 | ngôn | biểu nghĩa | lời nói — ca dao, tin đồn truyền miệng | 䍃 | biểu âm | góp âm yáo — gồm 爫 (trảo) + 缶 (phữu) | 谣 = 讠(Ngôn, biểu nghĩa: lời nói) + 䍃 (biểu âm: góp âm yáo). Chữ hình thanh — 讠chỉ nghĩa liên quan đến lời nói, ca hát, truyền miệng; 䍃 góp âm. Dạng giản thể của 謠.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"dao\": 讠(lời) truyền miệng như dao dao (謠 — dao ca) từ người này sang người khác — tin đồn hoặc ca dao lan rộng. | Gương Hán-Việt | dao trong 谣言 (dao ngôn — tin đồn), 歌谣 (ca dao — ca dao dân gian) | Mở khoá kiến thức | Biết 谣 (dao) mở khoá: 谣言 (tin đồn), 童谣 (đồng dao), 歌谣 (ca dao), 造谣 (tung tin đồn).", "Tự nguyên_Xie": "Lục thư thông | Theo Wiktionary, 谣 (dạng phồn thể 謠) là chữ hình thanh: 言 (ngôn, lời nói) làm biểu nghĩa, 䍃 làm biểu âm. Nghĩa gốc là hát không nhạc khí, ca dao dân gian. Mở rộng sang tin đồn bịa đặt (谣言). Hai nghĩa chính: ca dao truyền thống và tin đồn thất thiệt. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tin đồn, lời đồn đại; ca dao", "Hạng Tần Suất (Jun Da)": "2595.0", "Tần Suất % (Jun Da)": "98.6574376972", "GavinGrover_Once (Chiết tự trực tiếp)": "讠 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰讠", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "谣", "Unihan_Traditional (Chữ Phồn thể)": "謠", "Pinyin_Xie": "yáo", "Âm Hán Việt_Xie": "dao", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Làm danh từ đứng sau các động từ như tạo hoặc kết hợp thành từ ghép như dao ngôn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('寞', '{"9000": "2596.0", "Chữ Trung Quốc": "寞", "Bộ thủ & thành phần_Xie": "Bộ thủ | 宀 | Số nét | 13 | nét | 宀 | miên | biểu nghĩa | mái nhà, không gian trong nhà | 莫 | mạc | biểu âm | không ai — cho âm mạc/mịch | 寞 = 宀(Miên, mái nhà) + 莫 (Mạc, biểu âm/nghĩa: không ai). Wiktionary không ghi ls code — cấu trúc này có thể vừa là hội ý (nhà [宀] không người [莫] = cô đơn) vừa là hình thanh (莫 cho âm mò). Hai cơ chế hoạt động đồng thời.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mịch\": mái nhà (宀-Miên) vắng không người (莫-Mạc) — căn phòng trong ngôi nhà không ai — cô độc mịch mờ. | Gương Hán-Việt | mịch trong ''tịch mịch'' — yên lặng, cô đơn; 寞 thường đi với 寂 tạo từ 寂寞 | Mở khoá kiến thức | Biết 寞 mở khoá: 寂寞 (tịch mịch – cô đơn), 落寞 (lạc mịch – thất chí buồn tẻ), 索寞 (sách mịch – vắng vẻ).", "Tự nguyên_Xie": "寞 gồm 宀 (miên – mái nhà) và 莫 (mạc – không, không có). Wiktionary không có glyphOrigin chi tiết. Cấu trúc có thể đọc như hội ý: nhà (宀) không có người (莫) = vắng lặng, cô đơn; hoặc hình thanh với 莫 cho âm mò. Không có nguồn học thuật đầy đủ về cơ chế tạo chữ. Chữ thường dùng trong 寂寞 (tịch mịch) và 落寞 (lạc mịch – thất vọng buồn). | Theo Wiktionary · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đơn độc; yên lặng", "Hạng Tần Suất (Jun Da)": "2596.0", "Tần Suất % (Jun Da)": "98.659100195", "GavinGrover_Once (Chiết tự trực tiếp)": "宀 + 莫", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱宀莫", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "莫", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "宀", "Unihan_Simplified (Chữ Giản thể)": "寞", "Unihan_Traditional (Chữ Phồn thể)": "寞", "Pinyin_Xie": "mò", "Âm Hán Việt_Xie": "mịch", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Làm tính từ miêu tả trạng thái cô đơn, thường dùng trong từ ghép tịch mịch hoặc cô mịch. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蜀', '{"9000": "2597.0", "Chữ Trung Quốc": "蜀", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 13 | nét | 罒 | võng | biểu nghĩa | lưới, mắt to | 勹 | bao | biểu nghĩa | bao bọc | 虫 | trùng | biểu nghĩa | sâu, côn trùng | 蜀 là chữ có nguồn gốc phức tạp. Wiktionary cho biết thành phần trên (𦉶) ban đầu là mắt lớn (目) với móc câu, gợi ý \"nhìn chằm chằm\" hay \"đơn độc\". Phần 虫 (trùng) thêm vào từ thời Tây Chu để ghi địa danh nước Thục. Shuowen tái phân tích thành tượng hình con tằm. Cấu trúc không rõ hội ý hay hình thanh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thục\": con sâu (虫) trong lưới (罒) — nước Thục xứ Tứ Xuyên, nơi con tằm nhả tơ dệt lụa nổi tiếng cổ đại. | Gương Hán-Việt | thục trong \"Thục Hán\" — nước Thục thời Tam Quốc, đất của Lưu Bị | Mở khoá kiến thức | Biết 蜀 mở khoá: 蜀汉 (Thục Hán — nước của Lưu Bị thời Tam Quốc), 蜀道 (Thục đạo — đường Thục nổi tiếng hiểm trở), 独 (đồng gốc?).", "Tự nguyên_Xie": "Giáp cốt văn | Kim văn | Đại triện | Tiểu triện | Theo Wiktionary, 蜀 có nguồn gốc phức tạp: thành phần trên (𦉶) trong giáp cốt Thương là mắt lớn (目) với móc — có thể là nguyên tự của 獨 (đơn độc) hoặc 矚 (nhìn chăm chú). Phần 虫 (trùng) được thêm vào từ thời Tây Chu khi dùng làm địa danh Shu (nước Thục). Shuowen Jiezi tái phân tích thành con tằm. Giáp cốt văn, kim văn, đại triện và tiểu triện còn lưu. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1178.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Võng (122) Bao (055) Trùng (142)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Võng (số 122 - cái lưới/ 罒) ở trên chữ Bao (số 055 - bao bọc) và bộ Trùng (số 142 - con sâu). Hình ảnh con sâu con ngài đang nằm trong cái tổ, cái kén của nó. Giải thích sự chuyển ý: Đây là chữ Hội ý (hoặc Tượng hình). Thục vốn là con sâu bướm, con tằm. Cũng là tên nước Thục thời Tam Quốc.", "Nghĩa Tiếng Việt_Xie": "con ngài; đất Thục, nước Thục", "Hạng Tần Suất (Jun Da)": "2597.0", "Tần Suất % (Jun Da)": "98.6607580417", "GavinGrover_Once (Chiết tự trực tiếp)": "罒 + 𠣜", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱罒𠣜", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "𠣜", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "罒", "Unihan_Simplified (Chữ Giản thể)": "蜀", "Unihan_Traditional (Chữ Phồn thể)": "蜀", "Pinyin_Xie": "shǔ", "Âm Hán Việt_Xie": "thục", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chủ yếu làm danh từ riêng chỉ vùng đất Tứ Xuyên hoặc nước Thục thời cổ đại. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('甩', '{"9000": "2598.0", "Chữ Trung Quốc": "甩", "Bộ thủ & thành phần_Xie": "Bộ thủ | 用 | Số nét | 5 | nét | 甩 | suý | tượng hình | vẽ động tác vung ném | 甩 không có anchor Wiktionary chi tiết. Cấu trúc nhìn giống biến thể của 用 (用 + nét cong xuống) — gợi động tác hất, vung tay. Vì cấu trúc đơn lẻ, không tách bộ có nghĩa rõ ràng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"suý\": 甩 trông như 用 (dùng) thêm nét cong vung xuống — đúng nghĩa ''vung, hất, ném, bỏ rơi'' trong 甩, 甩开, 甩掉. | Gương Hán-Việt | ''suý'' (âm Hán-Việt ít phổ biến trong tiếng Việt) | Mở khoá kiến thức | Nắm 甩 mở khoá khẩu ngữ HSK 5: 甩, 甩开, 甩掉.", "Tự nguyên_Xie": "Anchor Wiktionary cho 甩 không có giải thích cấu tạo cụ thể. Về tự dạng, 甩 trông giống biến thể của 用 với một nét cong kéo xuống — gợi ý động tác ''vung tay, hất, ném đi''. Nghĩa hiện đại ''vung, ném, hất, bỏ rơi'' giữ nguyên trong 甩 (vung), 甩开 (vung ra), 甩掉 (bỏ rơi). Vì thiếu nguồn học thuật rõ ràng, đặt confidence ở mức trung bình. | Suy từ bộ phận cấu thành · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "vung lên; ném đi; bỏ rơi", "Hạng Tần Suất (Jun Da)": "2598.0", "Tần Suất % (Jun Da)": "98.6624158884", "GavinGrover_Once (Chiết tự trực tiếp)": "用 + 乚", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱用乚", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "乚", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "用", "Unihan_Simplified (Chữ Giản thể)": "甩", "Unihan_Traditional (Chữ Phồn thể)": "甩", "Pinyin_Xie": "shuǎi", "Âm Hán Việt_Xie": "súy", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Làm động từ biểu thị hành động vung, ném vật gì đó hoặc bỏ rơi người yêu. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | Từ đơn | Từ vựng HSK 5: vung | / | shuǎi | / | ném | / | shuǎi | / | vung | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Phong trào I | HSK | HSK 5 | · | Động từ hàng ngày", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('涯', '{"9000": "2599.0", "Chữ Trung Quốc": "涯", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 11 | nét | 氵 | thuỷ | biểu nghĩa | nước, dòng chảy | 厓 | nhai | biểu âm | vách đá, bờ — cho âm yá | 涯 = 氵(Thuỷ, biểu nghĩa: nước) + 厓 (Nhai, biểu âm/biểu nghĩa: vách đá, bờ); chữ hình thanh hoặc hội ý. Theo Wiktionary: vách đá (厓) bên nước (氵) — bờ sông, bến nước. Phần 厓 vừa cho âm vừa cho nghĩa.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nhai\": nước (氵) bên vách đá (厓) — nhai biên, bờ nước xa tít tắp như đường chân trời. | Gương Hán-Việt | nhai trong \"sinh nhai\" (生涯) — sự nghiệp, đường đời | Mở khoá kiến thức | Biết 涯 mở khoá: 生涯 (sinh nhai — sự nghiệp, cuộc đời), 天涯 (thiên nhai — chân trời), 无涯 (vô nhai — vô biên, không có bờ bến).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 涯 là hình thanh (psc, cũng có thể ic): 氵(thuỷ) biểu nghĩa nước, 厓 (nhai) biểu âm và cũng mang nghĩa vách đá/giới hạn. Hình ảnh: vách đá bên dòng nước — bờ sông, đường chân trời. Mở rộng sang: ranh giới, giới hạn, nghề nghiệp (生涯). Dạng tiểu triện còn lưu. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bờ, bến", "Hạng Tần Suất (Jun Da)": "2599.0", "Tần Suất % (Jun Da)": "98.6640727016", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 厓", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵厓", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "厓", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "涯", "Unihan_Traditional (Chữ Phồn thể)": "涯", "Pinyin_Xie": "yá", "Âm Hán Việt_Xie": "nhai", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Làm danh từ chỉ ranh giới, thường kết hợp trong các từ ghép như thiên nhai hay vô nhai. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('枕', '{"9000": "2600.0", "Chữ Trung Quốc": "枕", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 8 | nét | 木 | mộc | biểu nghĩa | gỗ — gối đầu gỗ | 冘 | dâm | biểu âm | do dự — góp âm zhěn | 枕 = 木 (Mộc, biểu nghĩa: gỗ) + 冘 (Dâm, biểu âm: góp âm zhěn). Chữ hình thanh — 木 chỉ nghĩa gối làm bằng gỗ (gối đầu gỗ cứng thời xưa), 冘 góp âm. Nghĩa gốc là gối đầu bằng gỗ, từ đó mở rộng sang mọi loại gối.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chẩm\": 木 (gỗ) cứng như 冘 (dâm — phân vân, nằm yên) — cái gối chẩm (gối đầu) gỗ cứng thời xưa. | Gương Hán-Việt | chẩm trong 枕头 (chẩm đầu — cái gối), 枕边 (chẩm biên — bên gối) | Mở khoá kiến thức | Biết 枕 (chẩm) mở khoá: 枕头 (cái gối), 枕边人 (người nằm cạnh gối — bạn đời), 高枕无忧 (đầu cao gối thấp — không lo gì).", "Tự nguyên_Xie": "Đại triện | Tiểu triện | Theo Wiktionary, 枕 là chữ hình thanh: 木 (mộc, gỗ) làm biểu nghĩa, 冘 (dâm) làm biểu âm. Nghĩa gốc là chiếc gối đầu làm bằng gỗ — thời cổ đại người Trung Hoa dùng gối gỗ. Từ đó mở nghĩa thành gối nói chung, gối đầu lên. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "909.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Mộc (075) Dâm (908)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Mộc (số 075 - gỗ) ở bên trái chữ Dâm (số 908 - do dự/chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Dâm chỉ âm, bộ Mộc chỉ ý. Chẩm là cái gối đầu (được làm từ gỗ).", "Nghĩa Tiếng Việt_Xie": "xương trong óc cá; cái gối đầu", "Hạng Tần Suất (Jun Da)": "2600.0", "Tần Suất % (Jun Da)": "98.6657295147", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 冘", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木冘", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "冘", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "枕", "Unihan_Traditional (Chữ Phồn thể)": "枕", "Pinyin_Xie": "zhěn", "Âm Hán Việt_Xie": "chẩm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này thường làm danh từ chỉ cái gối hoặc làm động từ với nghĩa gối đầu lên vật gì đó. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('丐', '{"9000": "2601.0", "Chữ Trung Quốc": "丐", "Bộ thủ & thành phần_Xie": "Bộ thủ | 一 | Số nét | 4 | nét | 丐 | cái | tượng hình | người ăn xin — biến dạng từ 匄; nghĩa gốc có thể là gây hại | 丐 là chữ độc thể, biến dạng từ 匄. Theo Wiktionary, nghĩa gốc chưa rõ ràng, có thể là \"gây hại\". Chữ hiện dùng với nghĩa người ăn xin (乞丐) và xin xỏ. Không có thành phần tách rời được phân tích — xếp loại tượng hình tự nghi.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cái\": chữ 丐 trông như người cúi người xuống xin xỏ — kẻ ăn xin cái gì đó từ người qua đường. | Gương Hán-Việt | cái trong 乞丐 (khất cái — người ăn xin), 丐帮 (cái bang — bang hội ăn mày) | Mở khoá kiến thức | Biết 丐 (cái) mở khoá: 乞丐 (người ăn xin), 丐帮 (bang ăn mày — trong tiểu thuyết võ hiệp Kim Dung).", "Tự nguyên_Xie": "Giáp cốt văn | Kim văn | Tiểu triện | Theo Wiktionary, 丐 là dạng biến thể của 匄 — nghĩa gốc chưa xác định rõ, có thể là \"gây hại\". Xuất hiện trong giáp cốt văn và kim văn. Dần mang nghĩa xin xỏ và người ăn xin. 乞丐 (kẻ ăn mày) là từ ghép thông dụng nhất trong HSK 6. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "kẻ ăn mày; cầu xin", "Hạng Tần Suất (Jun Da)": "2601.0", "Tần Suất % (Jun Da)": "98.6673837439", "GavinGrover_Once (Chiết tự trực tiếp)": "下 + ㇉", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱下㇉", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "㇉", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "下", "Unihan_Simplified (Chữ Giản thể)": "丐", "Unihan_Traditional (Chữ Phồn thể)": "丐", "Pinyin_Xie": "gài", "Âm Hán Việt_Xie": "cái", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường dùng làm động từ chỉ hành vi xin xỏ hoặc kết hợp tạo danh từ chỉ người ăn xin. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('泳', '{"9000": "2602.0", "Chữ Trung Quốc": "泳", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 8 | nét | 氵 | thuỷ | biểu nghĩa | biến thể của 水 – nước | 永 | vĩnh | biểu âm | vĩnh – cho âm | 泳 = 氵 (Thuỷ, biểu nghĩa: nước) + 永 (Vĩnh, biểu âm); chữ hình thanh – ở dưới nước, tức là bơi.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"vịnh\": người ngụp xuống “nước” 氵 “vĩnh viễn” 永 – tức là bơi mãi dưới nước, đó là 泳. | Gương Hán-Việt | “vịnh” trong vịnh thơ (mượn âm), du vịnh, bơi vịnh. | Mở khoá kiến thức | Biết 泳 mở khoá 游泳, 游泳池, 仰泳, 蛙泳.", "Tự nguyên_Xie": "Giáp cốt văn | Đại triện | Tiểu triện | 泳 là chữ hình thanh thuần: 水 (đứng cạnh thành 氵) cho nghĩa “nước” + 永 (vĩnh) cho âm. Nghĩa cơ bản là “bơi lội, lặn dưới nước”. Phần 永 vốn cũng có gốc liên quan đến dòng nước dài, nên trong cảm nhận người học, 永 vừa cho âm vừa gợi ý “nước chảy dài”. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lặn dưới nước", "Hạng Tần Suất (Jun Da)": "2602.0", "Tần Suất % (Jun Da)": "98.6690364228", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 永", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵永", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "永", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "泳", "Unihan_Traditional (Chữ Phồn thể)": "泳", "Pinyin_Xie": "yǒng", "Âm Hán Việt_Xie": "vịnh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường dùng làm động từ chỉ hoạt động bơi lội hoặc kết hợp tạo danh từ liên quan đến môn bơi. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('奎', '{"9000": "2603.0", "Chữ Trung Quốc": "奎", "Bộ thủ & thành phần_Xie": "Bộ thủ | 大 | Số nét | 9 | nét | 大 | đại | biểu nghĩa | lớn, người đứng thẳng | 圭 | khuê | biểu âm | ngọc khuê, thanh ngọc hình tam giác | 奎 = 大 (Đại, biểu nghĩa: người đứng thẳng) + 圭 (Khuê, biểu âm); chữ hình thanh. Thành phần 圭 ban đầu có thể tượng trưng cho cặp lưỡi rìu ngọc, không liên quan đến nghĩa đất; mối liên hệ với đất xuất phát từ dân gian hoặc từ hình dạng trong tiểu triện.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khuê\": sao Khuê chủ văn chương — người (大) cầm ngọc khuê (圭) ngước nhìn bầu trời đêm, ứng với khoa cử văn học. | Gương Hán-Việt | Khuê trong \"Khuê Văn Các\" (gác Khuê Văn ở Văn Miếu Hà Nội), \"khuê tú\" (văn chương xuất sắc). | Mở khoá kiến thức | Biết 奎 (khuê) mở khóa: 奎星 (sao Khuê), 奎章 (văn chương khoa cử), tên riêng như Khuê Văn Các.", "Tự nguyên_Xie": "Kim văn | Tiểu triện | 奎 là chữ hình thanh: 大 (đại) biểu nghĩa người/lớn, 圭 (khuê) biểu âm. Theo Wiktionary, thành phần 圭 trong dạng gốc có thể là hình cặp lưỡi rìu làm bằng ngọc bích, không phải đất (土). Sự liên hệ với đất là từ dân gian hoặc do dạng tiểu triện. Chữ 奎 ban đầu chỉ bước chân người, sau dùng chỉ một trong Nhị thập bát tú (sao Khuê, chủ văn chương). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sao Khuê (một trong Nhị thập bát tú, tượng trưng cho văn chương)", "Hạng Tần Suất (Jun Da)": "2603.0", "Tần Suất % (Jun Da)": "98.6706870345", "GavinGrover_Once (Chiết tự trực tiếp)": "大 + 圭", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱大圭", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "圭", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "大", "Unihan_Simplified (Chữ Giản thể)": "奎", "Unihan_Traditional (Chữ Phồn thể)": "奎", "Pinyin_Xie": "kuí", "Âm Hán Việt_Xie": "khuê", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chủ yếu dùng làm danh từ để chỉ chòm sao Khuê trong thiên văn cổ hoặc dùng trong tên người. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('泌', '{"9000": "2604.0", "Chữ Trung Quốc": "泌", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 8 | nét | 氵 | thuỷ | biểu nghĩa | nước | 必 | tất | biểu âm | nhất định | 泌 = 氵(Thuỷ, biểu nghĩa: nước) + 必 (Tất, biểu âm); chữ hình thanh. Bộ thuỷ chỉ nghĩa liên quan đến chất lỏng, 必 cho âm đọc gần bì/mì.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bí\": nước (氵) chảy ra theo lẽ tất nhiên (必) — như tuyến bí tiết ra dịch. | Gương Hán-Việt | \"bí\" trong 分泌 (phân bí — tiết ra, bài tiết) | Mở khoá kiến thức | Biết 泌 mở khoá từ y học: 分泌 (phân bí, tiết ra), 泌尿 (bí niệu, tiết niệu).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 泌 là chữ hình thanh: 水 (nước) đóng vai biểu nghĩa, 必 đóng vai biểu âm. Chữ mang nghĩa gốc là nước rỉ ra, tiết ra. Trong tiểu triện đã có dạng tương tự hiện đại. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sông Bí", "Hạng Tần Suất (Jun Da)": "2604.0", "Tần Suất % (Jun Da)": "98.6723366127", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 必", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵必", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "必", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "泌", "Unihan_Traditional (Chữ Phồn thể)": "泌", "Pinyin_Xie": "mì", "Âm Hán Việt_Xie": "bí", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ trong các từ ghép chỉ sự bài tiết chất lỏng của cơ thể hoặc sinh vật. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('逾', '{"9000": "2605.0", "Chữ Trung Quốc": "逾", "Bộ thủ & thành phần_Xie": "Bộ thủ | 辵 | Số nét | 12 | nét | 辶 | sước | biểu nghĩa | đi, di chuyển | 俞 | du | biểu âm | đồng ý, vượt qua | 逾 = 辶 (Sước, biểu nghĩa: đi/di chuyển) + 俞 (Du, biểu âm); chữ hình thanh. Bộ thủy 辶 (biến thể của 辵) cho thấy ý nghĩa di chuyển, vượt qua; 俞 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"du\": bước (辶) vượt qua ranh giới — như con thuyền (俞) lướt qua bờ, 逾 nghĩa là vượt quá, quá hạn. | Gương Hán-Việt | Du trong \"vượt du\" (vượt quá), \"du kỳ\" (quá hạn kỳ). | Mở khoá kiến thức | Biết 逾 (du) mở khóa: 逾期 (quá hạn), 逾越 (vượt quá), 逾矩 (vượt khuôn phép).", "Tự nguyên_Xie": "逾 là chữ hình thanh: 辶 (辵, sước) biểu nghĩa hành động đi/vượt qua, 俞 (du) biểu âm. Nghĩa gốc là vượt qua, đi qua; mở rộng sang nghĩa vượt quá giới hạn, quá hạn. Trong văn ngữ còn mang nghĩa càng thêm (even more). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "quá, vượt ra ngoài", "Hạng Tần Suất (Jun Da)": "2605.0", "Tần Suất % (Jun Da)": "98.6739846405", "GavinGrover_Once (Chiết tự trực tiếp)": "辶 + 俞", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴辶俞", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "俞", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "辶", "Unihan_Simplified (Chữ Giản thể)": "逾", "Unihan_Traditional (Chữ Phồn thể)": "踰", "Pinyin_Xie": "yú", "Âm Hán Việt_Xie": "du", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Phó từ | 副词 | Thường làm động từ chỉ sự vượt quá giới hạn thời gian hoặc số lượng, đôi khi làm phó từ bổ nghĩa cho động từ khác. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Phó từ | 副词 | Bổ nghĩa cho động từ hoặc tính từ và luôn đứng TRƯỚC chúng — 都是, 很好. Không đứng sau như tiếng Việt và không bổ nghĩa cho danh từ.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('叮', '{"9000": "2606.0", "Chữ Trung Quốc": "叮", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 5 | nét | 口 | khẩu | biểu nghĩa | miệng | 丁 | đinh | biểu âm | định, đinh | 叮 = 口 (Khẩu, biểu nghĩa: miệng) + 丁 (Đinh, biểu âm); chữ hình thanh. Bộ khẩu chỉ hành động nói, 丁 cho âm đinh/dīng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đinh\": miệng (口) gõ đinh (丁) vào tai người nghe — nhắc đi nhắc lại như đóng đinh. | Gương Hán-Việt | \"đinh\" trong 叮嘱 (đinh chúc — dặn dò), 叮咛 (đinh ninh — nhắc nhở ân cần) | Mở khoá kiến thức | Biết 叮 mở khoá từ giao tiếp: 叮嘱 (đinh chúc, dặn dò), 叮咛 (đinh ninh, căn dặn tha thiết).", "Tự nguyên_Xie": "Theo Wiktionary, 叮 là chữ hình thanh: 丁 đóng vai biểu âm, 口 đóng vai biểu nghĩa (miệng/lời). Nghĩa gốc là dặn dò, nhắc nhở liên tục bằng lời. Chưa thấy dạng giáp cốt hay kim văn riêng. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1023.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Khẩu (030) Đinh (015)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Khẩu (số 030 - miệng) ở bên trái chữ Đinh (số 015 - can Đinh/chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Đinh chỉ âm, bộ Khẩu chỉ ý. Đinh là dặn bảo kỹ càng, nhắc đi nhắc lại (đinh ninh).", "Nghĩa Tiếng Việt_Xie": "(xem: đinh ninh 丁寧)", "Hạng Tần Suất (Jun Da)": "2606.0", "Tần Suất % (Jun Da)": "98.6756321515", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 丁", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口丁", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "丁", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "叮", "Unihan_Traditional (Chữ Phồn thể)": "叮", "Pinyin_Xie": "dīng", "Âm Hán Việt_Xie": "đinh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ chỉ hành động dặn dò kỹ lưỡng hoặc côn trùng đốt, chích. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('黛', '{"9000": "2607.0", "Chữ Trung Quốc": "黛", "Bộ thủ & thành phần_Xie": "Bộ thủ | 黑 | Số nét | 17 | nét | 代 | đại | biểu âm | thay thế, đời | 黑 | hắc | biểu nghĩa | đen, tối | 黛 = 代 (Đại, biểu âm) + 黑 (Hắc, biểu nghĩa: đen); chữ hình thanh. Bộ 黑 chỉ màu đen, cho biết đây là loại thuốc nhuộm màu đen; 代 (đại) cho âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đại\": thuốc kẻ lông mày đen (黑) của đại mỹ nhân thời xưa — 黛 gợi hình ảnh lông mày cong như núi xa xanh thẫm. | Gương Hán-Việt | Đại trong \"phấn đại\" (phấn son trang điểm), \"mày đại\" (lông mày vẽ đen). | Mở khoá kiến thức | Biết 黛 (đại) mở khóa: 黛眉 (mày kẻ đen), 粉黛 (phấn son), 青黛 (xanh đen, vị thuốc), tên nhân vật Lâm Đại Ngọc trong Hồng Lâu Mộng.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 黛 là chữ hình thanh: 代 biểu âm (đọc gần âm dài/đại), 黑 biểu nghĩa màu đen. Nghĩa gốc là thuốc kẻ lông mày màu đen dùng trong trang điểm thời cổ đại; phụ nữ dùng 黛 để vẽ lông mày, tạo nên vẻ đẹp cổ điển. Mở rộng sang nghĩa màu đen, lông mày phụ nữ. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thuốc vẽ lông mày (trang điểm)", "Hạng Tần Suất (Jun Da)": "2607.0", "Tần Suất % (Jun Da)": "98.6772791457", "GavinGrover_Once (Chiết tự trực tiếp)": "代 + 黑", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱代黑", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "代", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "黑", "Unihan_Simplified (Chữ Giản thể)": "黛", "Unihan_Traditional (Chữ Phồn thể)": "黛", "Pinyin_Xie": "dài", "Âm Hán Việt_Xie": "đại", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Thường dùng làm danh từ chỉ chất màu vẽ lông mày thời xưa hoặc làm tính từ chỉ màu xanh đen của núi non. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('燥', '{"9000": "2608.0", "Chữ Trung Quốc": "燥", "Bộ thủ & thành phần_Xie": "Bộ thủ | 火 | Số nét | 17 | nét | 火 | hoả | biểu nghĩa | lửa, khô nóng | 喿 | táo | biểu âm | tiếng chim kêu — cho âm táo | 燥 = 火 (Hoả, biểu nghĩa: lửa/khô) + 喿 (Táo, biểu âm); chữ hình thanh. Wiktionary ghi: {{Han compound|火|喿|ls=psc|c1=s|c2=p|t1=fire}}. Bộ hoả biểu nghĩa khô ráo (liên quan lửa); 喿 cho âm zào/táo.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"táo\": lửa (火-Hoả) kêu táo (喿-Táo) — như tiếng lửa bùng cháy làm khô héo mọi thứ. Táo = khô hanh. | Gương Hán-Việt | táo trong ''táo bạo, nóng táo'' — âm giống; 燥 chỉ khô ráo, 躁 chỉ nóng vội | Mở khoá kiến thức | Biết 燥 mở khoá: 干燥 (can táo – khô), 枯燥 (khô táo – nhàm chán khô khan), 燥热 (táo nhiệt – hanh nóng).", "Tự nguyên_Xie": "燥 là chữ hình thanh: 火 (hoả – lửa) biểu nghĩa, 喿 (táo) biểu âm. Lửa làm khô — nghĩa là hanh, khô ráo. Wiktionary xác nhận: ''dry, parched, arid''. Phân biệt với 躁 (táo – nóng vội, nóng tính) — cùng phần âm 喿 nhưng nghĩa khác. Khí hậu khô hanh (干燥) hay thứ tẻ nhạt không hấp dẫn (枯燥) đều dùng 燥. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "khô ráo, hanh", "Hạng Tần Suất (Jun Da)": "2608.0", "Tần Suất % (Jun Da)": "98.6789178714", "GavinGrover_Once (Chiết tự trực tiếp)": "火 + 喿", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰火喿", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "喿", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "火", "Unihan_Simplified (Chữ Giản thể)": "燥", "Unihan_Traditional (Chữ Phồn thể)": "燥", "Pinyin_Xie": "zào", "Âm Hán Việt_Xie": "táo", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường làm tính từ miêu tả trạng thái khô hanh của thời tiết hoặc tính khí nóng nảy của con người. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('掷', '{"9000": "2609.0", "Chữ Trung Quốc": "掷", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 11 | nét | 扌 | thủ | biểu nghĩa | tay | 郑 | trịnh | biểu âm | họ Trịnh | 掷 = 扌(Thủ, biểu nghĩa: tay) + 郑 (Trịnh, biểu âm); chữ hình thanh. Giản thể của 擲, thay 鄭 bằng 郑. Bộ thủ chỉ hành động dùng tay ném, 郑 cho âm gần zhì.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trịch\": tay (扌) họ Trịnh (郑) ném đồ vật — hình ảnh người ném lao mang họ Trịnh. | Gương Hán-Việt | \"trịch\" trong 投掷 (đầu trịch — ném, phóng) | Mở khoá kiến thức | Biết 掷 mở khoá từ thể thao: 投掷 (đầu trịch, ném), 掷铁饼 (ném đĩa).", "Tự nguyên_Xie": "Lục thư thông | 掷 là dạng giản thể của 擲 (trịch). 擲 là chữ hình thanh với bộ 手 (tay) biểu nghĩa và 鄭 biểu âm. Chỉ thấy dạng Lục thư thông — chữ tạo muộn. Nghĩa gốc là ném, phóng bằng tay. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "rơi xuống", "Hạng Tần Suất (Jun Da)": "2609.0", "Tần Suất % (Jun Da)": "98.6805560802", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 郑", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌郑", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "郑", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "掷", "Unihan_Traditional (Chữ Phồn thể)": "擲", "Pinyin_Xie": "zhì", "Âm Hán Việt_Xie": "trịch", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước tân ngữ để chỉ hành động ném hoặc quăng một vật đi. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('枢', '{"9000": "2610.0", "Chữ Trung Quốc": "枢", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 8 | nét | 木 | mộc | biểu nghĩa | gỗ, cây | 区 | khu | biểu âm | khu vực, phân khu | 枢 = 木 (Mộc, biểu nghĩa: gỗ) + 区 (Khu, biểu âm); chữ hình thanh. Bộ 木 cho thấy vật thể bằng gỗ; 区 cho âm. Đây là chữ giản thể của 樞, then cửa bằng gỗ xoay.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"xu\": then cửa (木) là trục xoay trung tâm — 枢 nghĩa là chỗ then chốt, trung khu, như then gỗ là điểm tựa của toàn bộ cánh cửa. | Gương Hán-Việt | Xu trong \"trung xu\" (trung tâm quyền lực), \"xu mật\" (xu mật viện — cơ quan mật của triều đình). | Mở khoá kiến thức | Biết 枢 (xu) mở khóa: 中枢 (trung xu, trung tâm), 枢纽 (then chốt, nút giao), 枢密院 (Xu Mật Viện).", "Tự nguyên_Xie": "Tiểu triện | 枢 là chữ giản thể của 樞. Cấu trúc: 木 (mộc, gỗ) + 区 (khu, biểu âm). Nghĩa gốc là then cửa bằng gỗ — bộ phận xoay của cánh cửa. Từ đó mở rộng sang nghĩa trục, trung tâm, điểm then chốt. Hình ảnh then cửa là trục xoay quan trọng dẫn đến nghĩa bóng là trung tâm quyền lực. chưa có nguồn học thuật chi tiết cho dạng giản thể. | Suy từ bộ phận cấu thành · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái then cửa; cây xu; sao Xu", "Hạng Tần Suất (Jun Da)": "2610.0", "Tần Suất % (Jun Da)": "98.6838314644", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 区", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木区", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "区", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "枢", "Unihan_Traditional (Chữ Phồn thể)": "樞", "Pinyin_Xie": "shū", "Âm Hán Việt_Xie": "xu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ hoặc định ngữ trong từ ghép để chỉ bộ phận trọng yếu, trung tâm điều hành. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('憎', '{"9000": "2611.0", "Chữ Trung Quốc": "憎", "Bộ thủ & thành phần_Xie": "Bộ thủ | 心 | Số nét | 15 | nét | 忄 | tâm | biểu nghĩa | tâm, lòng, cảm xúc | 曾 | tăng | biểu âm | đã từng, thêm vào | 憎 = 忄 (Tâm, biểu nghĩa: cảm xúc/lòng) + 曾 (Tăng, biểu âm); chữ hình thanh. Bộ tâm 忄 cho biết đây là cảm xúc trong lòng; 曾 (tăng) cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tăng\": lòng (忄) ngày càng tăng (曾) sự căm ghét — 憎 là ghét, thù oán sâu sắc. | Gương Hán-Việt | Tăng trong \"tăng ố\" (ghét bỏ), \"khả tăng\" (đáng ghét). | Mở khoá kiến thức | Biết 憎 (tăng) mở khóa: 憎恨 (căm ghét), 憎恶 (ghét bỏ), 面目可憎 (bộ mặt đáng ghét).", "Tự nguyên_Xie": "Tiểu triện | 憎 là chữ hình thanh: 忄 (tâm) biểu nghĩa cảm xúc tâm lý, 曾 (tăng) biểu âm. Nghĩa là ghét, căm ghét — cảm xúc tiêu cực mạnh trong lòng. Cùng họ với 增 (tăng thêm), 赠 (tặng), đều mượn 曾 làm âm. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ghét, không thích", "Hạng Tần Suất (Jun Da)": "2611.0", "Tần Suất % (Jun Da)": "98.6854691565", "GavinGrover_Once (Chiết tự trực tiếp)": "忄 + 曾", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰忄曾", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "曾", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "忄", "Unihan_Simplified (Chữ Giản thể)": "憎", "Unihan_Traditional (Chữ Phồn thể)": "憎", "Pinyin_Xie": "zēng", "Âm Hán Việt_Xie": "tăng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này thường làm động từ đứng trước tân ngữ để biểu thị sự ghét bỏ hoặc căm hận. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鲸', '{"9000": "2612.0", "Chữ Trung Quốc": "鲸", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 16 | nét | 鱼 | ngư | biểu nghĩa | cá | 京 | kinh | biểu âm | kinh đô, lớn | 鲸 = 鱼 (Ngư, biểu nghĩa: cá) + 京 (Kinh, biểu âm); chữ hình thanh. Bộ ngư 鱼 cho biết đây là loài thủy sinh; 京 (kinh) cho âm đọc — gợi ý con vật cực kỳ to lớn như kinh đô.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"kình\": con cá (鱼) to như kinh đô (京) — 鲸 là cá voi, sinh vật biển khổng lồ. | Gương Hán-Việt | Kình trong \"kình ngư\" (cá kình/cá voi), \"kình địch\" (kẻ thù mạnh ngang sức). | Mở khoá kiến thức | Biết 鲸 (kình) mở khóa: 鲸鱼 (cá voi), 鲸吞 (nuốt chửng như cá voi), 鲸波 (sóng lớn).", "Tự nguyên_Xie": "Tiểu triện | 鲸 là chữ hình thanh: 鱼 (ngư, cá) biểu nghĩa, 京 (kinh) biểu âm. Chữ chỉ con cá voi — loài động vật biển lớn nhất. 京 ngoài vai trò biểu âm còn gợi ý sự to lớn (nghĩa kinh đô, vĩ đại). Cá voi trong thế giới quan cổ đại Trung Hoa được xem là sinh vật biển khổng lồ bí ẩn. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cá kình, cá voi", "Hạng Tần Suất (Jun Da)": "2612.0", "Tần Suất % (Jun Da)": "98.687101164", "GavinGrover_Once (Chiết tự trực tiếp)": "鱼 + 京", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰鱼京", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "京", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鱼", "Unihan_Simplified (Chữ Giản thể)": "鲸", "Unihan_Traditional (Chữ Phồn thể)": "鯨", "Pinyin_Xie": "jīng", "Âm Hán Việt_Xie": "kình", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ loài cá voi, thường kết hợp với các danh từ khác để tạo từ ghép. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('弘', '{"9000": "2613.0", "Chữ Trung Quốc": "弘", "Bộ thủ & thành phần_Xie": "Bộ thủ | 弓 | Số nét | 5 | nét | 弓 | cung | biểu nghĩa | cung tên | 厶 | tư | biểu nghĩa | tư riêng (biến thể của 口 — miệng) | 弘 = 弓 (Cung) + 厶 (biến thể của 口, miệng); chữ hội ý kiêm hình thanh. Theo Wiktionary: gốc là 弓 + 口, hội ý âm thanh của cung — tiếng vang lớn của dây cung; 厶 là dạng biến thể muộn của 口, và cũng là dạng cổ của 肱 (cánh tay). Chữ hội ý, nghĩa gốc là tiếng vang rền của cung, mở rộng sang to lớn, rộng rãi.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hoằng\": tiếng cung (弓) vang lên (厶/口) rền vang — 弘 nghĩa là to lớn, rộng rãi, hoằng dương. | Gương Hán-Việt | Hoằng trong \"hoằng dương\" (phát triển rộng rãi), \"hoằng pháp\" (truyền bá Phật pháp). | Mở khoá kiến thức | Biết 弘 (hoằng) mở khóa: 弘扬 (hoằng dương, phát huy), 弘大 (to lớn), 宏弘 (rộng lớn).", "Tự nguyên_Xie": "Kim văn | Tiểu triện | 弘 là chữ hội ý: 弓 (cung) + 口 (miệng/âm thanh), ghi âm tiếng vang của dây cung kéo căng. Sau đó 口 bị biến thể thành 厶 (dạng cổ của 肱, cánh tay). Nghĩa gốc là âm thanh lớn, rền vang; mở rộng sang to lớn, rộng lớn, vĩ đại. Đây là chữ hội ý kết hợp âm thanh và hình ảnh. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lớn, mở rộng ra", "Hạng Tần Suất (Jun Da)": "2613.0", "Tần Suất % (Jun Da)": "98.6887305875", "GavinGrover_Once (Chiết tự trực tiếp)": "弓 + 厶", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰弓厶", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "厶", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "弓", "Unihan_Simplified (Chữ Giản thể)": "弘", "Unihan_Traditional (Chữ Phồn thể)": "弘", "Pinyin_Xie": "hóng", "Âm Hán Việt_Xie": "hoằng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Chữ này làm tính từ chỉ sự to lớn hoặc làm động từ mang nghĩa mở rộng, phát triển. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('倚', '{"9000": "2614.0", "Chữ Trung Quốc": "倚", "Bộ thủ & thành phần_Xie": "Bộ thủ | 人 | Số nét | 10 | nét | 亻 | nhân | biểu nghĩa | người | 奇 | kỳ | biểu âm | kỳ lạ, số lẻ | 倚 = 亻 (Nhân, biểu nghĩa: người) + 奇 (Kỳ, biểu âm); chữ hình thanh. Bộ nhân 亻 cho biết hành động của con người; 奇 (kỳ, đọc gần ỷ/yǐ) cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ỷ\": người (亻) tựa vào điều kỳ lạ (奇) — 倚 nghĩa là tựa vào, dựa vào, ỷ lại vào ai đó. | Gương Hán-Việt | Ỷ trong \"ỷ lại\" (dựa dẫm, phụ thuộc), \"ỷ thế\" (cậy thế lực). | Mở khoá kiến thức | Biết 倚 (ỷ) mở khóa: 倚靠 (tựa vào, dựa vào), 倚重 (trông cậy, trọng dụng), 倚赖 (ỷ lại).", "Tự nguyên_Xie": "Tiểu triện | 倚 là chữ hình thanh: 亻 (nhân) biểu nghĩa người/hành động của người, 奇 (kỳ) biểu âm. Nghĩa gốc là tựa lưng, ngả người vào vật gì; mở rộng sang nương nhờ, dựa dẫm, dốc một bên. Hình ảnh người tựa vào vật gì đó gợi sự nương tựa, phụ thuộc. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "dựa vào", "Hạng Tần Suất (Jun Da)": "2614.0", "Tần Suất % (Jun Da)": "98.6903579439", "GavinGrover_Once (Chiết tự trực tiếp)": "亻 + 奇", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰亻奇", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "奇", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "亻", "Unihan_Simplified (Chữ Giản thể)": "倚", "Unihan_Traditional (Chữ Phồn thể)": "倚", "Pinyin_Xie": "yǐ", "Âm Hán Việt_Xie": "ỷ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ đứng trước danh từ chỉ vật tựa vào hoặc đối tượng nương tựa. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Từ III", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('侮', '{"9000": "2615.0", "Chữ Trung Quốc": "侮", "Bộ thủ & thành phần_Xie": "Bộ thủ | 人 | Số nét | 9 | nét | 亻 | nhân | biểu nghĩa | người | 每 | mỗi | biểu âm | mỗi | 侮 = 亻(Nhân, biểu nghĩa: người) + 每 (Mỗi, biểu âm); chữ hình thanh. Bộ nhân chỉ hành động liên quan đến người, 每 cho âm gần wǔ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"vũ\": người (亻) bị mỗi người (每) đều chà đạp — hình ảnh bị khinh nhờn từ nhiều phía. | Gương Hán-Việt | \"vũ\" trong 侮辱 (vũ nhục — xúc phạm, lăng mạ), 欺侮 (khi vũ — ức hiếp) | Mở khoá kiến thức | Biết 侮 mở khoá từ nhân quyền: 侮辱 (vũ nhục, xúc phạm), 欺侮 (khi vũ, bắt nạt), 外侮 (ngoại vũ, xâm lăng).", "Tự nguyên_Xie": "Kim văn | Tiểu triện | Theo Wiktionary, 侮 là chữ hình thanh: 人 (người) biểu nghĩa, 每 biểu âm. Kim văn và tiểu triện đã có dạng tương tự. Nghĩa gốc là khinh nhờn, xúc phạm người khác. Thành ngữ cổ: 人必自侮而後人侮之 — người tự khinh mình thì người khác mới khinh được. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1711.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Nhân (009) Mỗi (080)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Nhân đứng (số 009 - con người/ 亻/chỉ ý) ở bên trái chữ Mỗi (số 080 - mỗi/ 每 /chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Mỗi chỉ âm, bộ Nhân chỉ ý. Vũ là coi thường người khác, bắt nạt (vũ nhục, khinh vũ).", "Nghĩa Tiếng Việt_Xie": "khinh nhờn; kẻ lấn áp", "Hạng Tần Suất (Jun Da)": "2615.0", "Tần Suất % (Jun Da)": "98.6919827163", "GavinGrover_Once (Chiết tự trực tiếp)": "亻 + 每", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰亻每", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "每", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "亻", "Unihan_Simplified (Chữ Giản thể)": "侮", "Unihan_Traditional (Chữ Phồn thể)": "侮", "Pinyin_Xie": "wǔ", "Âm Hán Việt_Xie": "vũ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ thường mang tân ngữ chỉ người bị khinh miệt hoặc bắt nạt. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('藩', '{"9000": "2616.0", "Chữ Trung Quốc": "藩", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 18 | nét | 艹 | thảo | biểu nghĩa | cỏ, thực vật | 潘 | phiên | biểu âm | (tên người, nước chảy) | 藩 = 艹 (Thảo, biểu nghĩa: cỏ/hàng rào cây) + 潘 (Phiên, biểu âm); chữ hình thanh. Bộ thảo 艹 gợi hình ảnh hàng rào cây, bờ giậu; 潘 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phiên\": hàng rào cỏ cây (艹) bảo vệ biên phiên — 藩 là phên dậu, phiên thuộc, vùng chư hầu che chắn triều đình. | Gương Hán-Việt | Phiên trong \"phiên thuộc\" (chư hầu), \"phiên bang\" (nước phiên thuộc), \"phiên trấn\" (藩鎮 — lãnh địa quân sự). | Mở khoá kiến thức | Biết 藩 (phiên) mở khóa: 藩篱 (hàng rào, phòng thủ), 藩国 (nước chư hầu), 藩王 (phiên vương), 藩镇 (phiên trấn).", "Tự nguyên_Xie": "Tiểu triện | 藩 là chữ hình thanh: 艹 (thảo) biểu nghĩa hàng rào cây cỏ, 潘 (phiên) biểu âm. Nghĩa gốc là hàng rào cây, bờ giậu để bảo vệ biên giới; mở rộng sang phên dậu, phên che, chư hầu bảo vệ triều đình (藩国 — nước chư hầu). Trong hệ thống phong kiến, 藩 chỉ vùng đất biên cương do chư hầu quản lý. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bờ rào", "Hạng Tần Suất (Jun Da)": "2616.0", "Tần Suất % (Jun Da)": "98.6936043881", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 潘", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹潘", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "潘", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "藩", "Unihan_Traditional (Chữ Phồn thể)": "藩", "Pinyin_Xie": "fān", "Âm Hán Việt_Xie": "phiên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ hàng rào bảo vệ hoặc vùng đất biên ải che chở cho kinh đô. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('拂', '{"9000": "2617.0", "Chữ Trung Quốc": "拂", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 8 | nét | 扌 | thủ | biểu nghĩa | tay | 弗 | phất | biểu âm | không, phủ định | 拂 = 扌 (Thủ, biểu nghĩa: tay) + 弗 (Phất, biểu âm); chữ hình thanh. Bộ thủ 扌 cho biết hành động của tay; 弗 (phất) cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bật\": tay (扌) phất (弗) nhẹ — 拂 là phủi đi, phẩy tay, phất qua, cũng có nghĩa trái với, cưỡng lại. | Gương Hán-Việt | Bật trong \"phất bật\" (phất phới), \"bật nghịch\" (cưỡng lại, trái ý). | Mở khoá kiến thức | Biết 拂 (bật) mở khóa: 拂去 (phủi đi), 拂袖 (phẩy tay áo = bực bội bỏ đi), 拂晓 (tảng sáng — ánh sáng nhẹ lướt qua), 拂逆 (cưỡng lại).", "Tự nguyên_Xie": "Tiểu triện | 拂 là chữ hình thanh: 扌 (thủ, tay) biểu nghĩa hành động của tay, 弗 (phất) biểu âm. Nghĩa gốc là phủi nhẹ, phẩy tay để gạt đi; mở rộng sang cưỡng lại, trái ý. Hình ảnh tay phẩy nhẹ loại bỏ vật gì đó. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1220.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thủ (064) Phất (1219)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Thủ (số 064 - cái tay/ 扌/chỉ ý) ở bên trái chữ Phất (số 1219 - không/chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Phất chỉ âm, bộ Thủ chỉ ý. Phất là dùng tay lau chùi, phủi qua phủi lại (phất trần).", "Nghĩa Tiếng Việt_Xie": "phất, phẩy quét", "Hạng Tần Suất (Jun Da)": "2617.0", "Tần Suất % (Jun Da)": "98.6952245095", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 弗", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌弗", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "弗", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "拂", "Unihan_Traditional (Chữ Phồn thể)": "拂", "Pinyin_Xie": "fú", "Âm Hán Việt_Xie": "phất", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ chỉ hành động gạt bỏ nhẹ nhàng hoặc gió thổi lướt qua. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鹤', '{"9000": "2618.0", "Chữ Trung Quốc": "鹤", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鳥 | Số nét | 15 | nét | 隺 | biểu âm | (hình hạc — cò trắng đầu đỏ) | 鸟 | điểu | biểu nghĩa | chim | 鹤 = 隺 (biểu âm, hình hạc cò) + 鸟 (Điểu, biểu nghĩa: chim); chữ hình thanh. 隺 tự nó có hình của loài chim lội nước (冖 + 隹), vừa cho âm vừa gợi hình; 鸟 xác nhận đây là loài chim.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hạc\": chim (鸟) hạc trắng — biểu tượng tiên nhân, thanh cao vượt trội. 鹤立鸡群 là thành ngữ quen thuộc nhất. | Gương Hán-Việt | Hạc trong \"tiên hạc\" (hạc tiên), \"hạc lập kê quần\" (nổi bật giữa đám đông). | Mở khoá kiến thức | Biết 鹤 (hạc) mở khóa: 仙鹤 (tiên hạc), 白鹤 (hạc trắng), 鹤立鸡群 (hạc đứng giữa bầy gà), 松鹤延年 (tùng hạc trường thọ).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 鹤 (phồn thể 鶴) là chữ hình thanh: 隺 biểu âm (đọc hè), 鸟 (điểu) biểu nghĩa chim. Chữ chỉ con hạc — loài chim lội nước cao gầy, trắng toát, là biểu tượng của sự thanh cao, trường thọ và tiên đạo trong văn hóa Đông Á. Thành ngữ 鹤立鸡群 (hạc đứng giữa bầy gà) chỉ người nổi bật hơn hẳn. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chim hạc, con sếu", "Hạng Tần Suất (Jun Da)": "2618.0", "Tần Suất % (Jun Da)": "98.6968435973", "GavinGrover_Once (Chiết tự trực tiếp)": "隺 + 鸟", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰隺鸟", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "隺", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鸟", "Unihan_Simplified (Chữ Giản thể)": "鹤", "Unihan_Traditional (Chữ Phồn thể)": "鶴", "Pinyin_Xie": "hè", "Âm Hán Việt_Xie": "hạc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ loài chim hạc, thường đứng độc lập hoặc làm định ngữ trong cụm danh từ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蚀', '{"9000": "2619.0", "Chữ Trung Quốc": "蚀", "Bộ thủ & thành phần_Xie": "Bộ thủ | 食 | Số nét | 9 | nét | 饣 | thực | biểu nghĩa | ăn | 虫 | trùng | biểu nghĩa | sâu bọ | 蚀 = 饣(Thực, nghĩa: ăn) + 虫 (Trùng, nghĩa: sâu bọ); có thể đọc là hội ý — sâu bọ (虫) ăn gặm (饣). Dạng truyền thống 蝕 có cấu trúc phức tạp hơn và Wiktionary không có phân tích ls rõ ràng cho giản thể. Chưa có nguồn học thuật đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thực\": sâu bọ (虫) ăn (饣) mòn vật liệu — như gỉ sét ăn kim loại, như nguyệt thực ''ăn'' vầng trăng. | Gương Hán-Việt | \"thực\" trong 腐蚀 (phủ thực — ăn mòn), 侵蚀 (xâm thực — xói mòn) | Mở khoá kiến thức | Biết 蚀 mở khoá từ khoa học: 腐蚀 (ăn mòn), 侵蚀 (xâm thực), 日蚀 (nhật thực), 月蚀 (nguyệt thực).", "Tự nguyên_Xie": "Đại triện | 蚀 là dạng giản thể, dạng phồn thể là 蝕 (thực). Đại triện đã có dạng ghi chép. Nghĩa gốc liên quan đến việc bị sâu mọt đục khoét, ăn mòn. Từ đó mở rộng sang thiên thực (nhật thực, nguyệt thực) — như mặt trăng bị ''ăn'' khuất. Chưa có nguồn học thuật đầy đủ. | Theo Wiktionary · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bị sâu mọt đục khoét; nhật thực, nguyệt thực", "Hạng Tần Suất (Jun Da)": "2619.0", "Tần Suất % (Jun Da)": "98.6984616516", "GavinGrover_Once (Chiết tự trực tiếp)": "饣 + 虫", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰饣虫", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "虫", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "饣", "Unihan_Simplified (Chữ Giản thể)": "蚀", "Unihan_Traditional (Chữ Phồn thể)": "蝕", "Pinyin_Xie": "shí", "Âm Hán Việt_Xie": "thực", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ chỉ sự xói mòn, hao tổn dần dần hoặc hiện tượng nhật thực, nguyệt thực. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('浆', '{"9000": "2620.0", "Chữ Trung Quốc": "浆", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 10 | nét | 将 | tương | biểu âm | tướng, sắp sửa | 水 | thuỷ | biểu nghĩa | nước, chất lỏng | 浆 (phồn thể 漿) = 將 (Tương, biểu âm) + 水 (Thuỷ, biểu nghĩa: chất lỏng); chữ hình thanh. Bộ thuỷ 水 chỉ chất lỏng đặc; 將 (tương) cho âm. Dạng giản thể biến 將 thành 浆 bằng cách đơn giản hóa thành phần.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tương\": nước (水) tương sánh đặc — 浆 là chất lỏng đặc, nước sánh như sữa đậu, nước gạo đặc. | Gương Hán-Việt | Tương trong \"đậu tương\" (浆 là nước đậu nành, không phải tương mắm), \"tương thạch\" (nước hoa quả đặc). | Mở khoá kiến thức | Biết 浆 (tương) mở khóa: 豆浆 (sữa đậu nành), 泥浆 (bùn loãng), 纸浆 (bột giấy), 浆果 (quả mọng).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 浆 (phồn thể 漿) là chữ hình thanh: 將 (tương) biểu âm, 水 (thuỷ) biểu nghĩa chất lỏng. Nghĩa gốc là chất lỏng đặc sánh như nước vo gạo, nước cháo; mở rộng sang các loại dịch lỏng sánh đặc như sữa đậu nành (豆浆), nước mía (甘蔗汁). Trong Hán văn cổ, 浆 chỉ đồ uống chua nhẹ dùng tiếp đón khách. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chất lỏng đặc", "Hạng Tần Suất (Jun Da)": "2620.0", "Tần Suất % (Jun Da)": "98.7000791891", "GavinGrover_Once (Chiết tự trực tiếp)": "No glyph available + 水", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱水", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "浆", "Unihan_Traditional (Chữ Phồn thể)": "漿", "Pinyin_Xie": "jiāng", "Âm Hán Việt_Xie": "tương", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ các loại chất lỏng đặc hoặc nước ép từ hoa quả. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('芙', '{"9000": "2621.0", "Chữ Trung Quốc": "芙", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 7 | nét | 艹 | thảo | biểu nghĩa | cỏ, thực vật | 夫 | phu | biểu âm | người đàn ông | 芙 = 艹 (Thảo, biểu nghĩa: thực vật) + 夫 (Phu, biểu âm); chữ hình thanh suy luận từ cấu trúc (Wiktionary không có phân tích). Chỉ dùng trong 芙蓉 (phù dung — hoa sen/hoa phù dung).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phù\": cỏ hoa (艹) đẹp như người đàn ông quý phái (夫) — 芙 chỉ dùng trong 芙蓉 (phù dung), tên đẹp của hoa sen hoặc hoa phù dung. | Gương Hán-Việt | Phù trong \"phù dung\" (芙蓉 — hoa sen, hoặc hoa phù dung/mộc liên), \"xuất thủy phù dung\" (sen mới nở khỏi mặt nước — sắc đẹp tự nhiên thuần khiết). | Mở khoá kiến thức | Biết 芙 (phù) mở khóa: 芙蓉 (phù dung — hoa sen/hoa phù dung), 出水芙蓉 (vẻ đẹp thiên nhiên thuần khiết), 芙蕖 (tên thơ của hoa sen).", "Tự nguyên_Xie": "Tiểu triện | Wiktionary không cung cấp phân tích cấu trúc chi tiết cho 芙. Từ cấu trúc: 艹 (thảo) + 夫 (phu), có thể là chữ hình thanh với 艹 biểu nghĩa thực vật và 夫 biểu âm. Chữ chỉ dùng trong tổ hợp 芙蓉 (phù dung — tên gọi của hoa sen hoặc hoa phù dung/mộc phù dung). chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "422.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thảo (276) Phu (34)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Thảo (số 80 - cỏ cây) và chữ Phu (số 141 - người đàn ông) . Loài cây (Thảo) có dáng vẻ thanh cao như người trượng phu (Phu) gọi là hoa phù dung. Giải thích sự chuyển ý: Chữ Phu (đàn ông) chỉ âm, chữ Thảo (cỏ cây) chỉ ý. Tên một loài hoa (Thảo) đẹp (Phù). *(Biến âm Hán Việt: Phu -> Phù)*", "Nghĩa Tiếng Việt_Xie": "(xem: phù dung 芙蓉)", "Hạng Tần Suất (Jun Da)": "2621.0", "Tần Suất % (Jun Da)": "98.7016967265", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 夫", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹夫", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "夫", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "芙", "Unihan_Traditional (Chữ Phồn thể)": "芙", "Pinyin_Xie": "fú", "Âm Hán Việt_Xie": "phù", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ nhưng hầu như chỉ dùng trong từ ghép để chỉ các loài hoa đẹp như sen hay phù dung. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('垃', '{"9000": "2622.0", "Chữ Trung Quốc": "垃", "Bộ thủ & thành phần_Xie": "Bộ thủ | 土 | Số nét | 8 | nét | 土 | thổ | biểu nghĩa | đất — rác bẩn | 立 | lập | biểu âm | gợi âm lā | 垃 = 土 (Thổ: đất) + 立 (Lập, biểu âm); chữ hình thanh. Chuyên dùng trong từ 垃圾 (rác).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lạp\": chữ 土 (đất) đứng cạnh 立 (đứng) — đống đất bỏ đi, đó là ''lạp'' trong rác (垃圾). chưa có nguồn học thuật | Gương Hán-Việt | lạp trong từ Hán-Việt cổ; người Việt thường dùng \"rác\" | Mở khoá kiến thức | Biết 垃 mở khoá từ chuyên dụng cho rác: 垃圾, 垃圾桶.", "Tự nguyên_Xie": "Wiktionary không có giải thích đầy đủ. Phân tích thành phần: 土 (đất bẩn) cho nghĩa, 立 cho âm lā. Dùng trong 垃圾 (lā jī, rác). | Suy từ bộ phận cấu thành · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "rác rưởi", "Hạng Tần Suất (Jun Da)": "2622.0", "Tần Suất % (Jun Da)": "98.7033127136", "GavinGrover_Once (Chiết tự trực tiếp)": "土 + 立", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰土立", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "立", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "土", "Unihan_Simplified (Chữ Giản thể)": "垃", "Unihan_Traditional (Chữ Phồn thể)": "垃", "Pinyin_Xie": "lā", "Âm Hán Việt_Xie": "lạp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ và hầu như chỉ xuất hiện trong từ ghép để chỉ rác thải sinh hoạt. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('烤', '{"9000": "2623.0", "Chữ Trung Quốc": "烤", "Bộ thủ & thành phần_Xie": "Bộ thủ | 火 | Số nét | 10 | nét | 火 | hoả | biểu nghĩa | lửa — dùng lửa nướng | 考 | khảo | biểu âm | phần biểu âm — gần âm ''khảo'' | 烤 là chữ hình thanh (psc): 火 (lửa, biểu nghĩa) + 考 (biểu âm). Dùng lửa nướng/quay thức ăn — nghĩa ''nướng, quay, sấy''.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Khảo\": dùng lửa (火) khảo nghiệm (考) miếng thịt — đó là ''khảo'', nướng, quay. | Gương Hán-Việt | ''Khảo'' (烤) ít gặp trong Hán-Việt; có thể nhớ qua âm ''khảo'' trong ''khảo cứu''. | Mở khoá kiến thức | Biết 烤 mở khoá 烤肉 (khảo nhục, thịt nướng), 烤鸭 (khảo áp, vịt quay), 烧烤 (thiêu khảo, đồ nướng).", "Tự nguyên_Xie": "Theo Wiktionary, 烤 là chữ hình thanh gồm 火 (lửa — biểu nghĩa: dùng lửa để làm chín thức ăn) + 考 (biểu âm). Nghĩa ''nướng, quay, sấy (thức ăn) bằng lửa''. Trong tiếng Hán hiện đại chủ yếu xuất hiện trong các từ ghép 烤肉, 烧烤, 烤鸭, 烤面包. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sấy, nướng", "Hạng Tần Suất (Jun Da)": "2623.0", "Tần Suất % (Jun Da)": "98.7049276672", "GavinGrover_Once (Chiết tự trực tiếp)": "火 + 考", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰火考", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "考", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "火", "Unihan_Simplified (Chữ Giản thể)": "烤", "Unihan_Traditional (Chữ Phồn thể)": "烤", "Pinyin_Xie": "kǎo", "Âm Hán Việt_Xie": "khảo", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này thường làm động từ đứng trước danh từ chỉ thực phẩm để chỉ phương pháp chế biến món ăn bằng nhiệt. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | kǎo | / | nướng | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Thực phẩm II", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('晒', '{"9000": "2624.0", "Chữ Trung Quốc": "晒", "Bộ thủ & thành phần_Xie": "Bộ thủ | 日 | Số nét | 10 | nét | 日 | nhật | biểu nghĩa | mặt trời | 西 | tây | biểu âm | phía tây — cho âm tây/sái | 晒 = 日 (Nhật, biểu nghĩa: mặt trời) + 西 (Tây, biểu âm). Wiktionary không ghi ls code chi tiết nhưng cấu trúc 日+西 điển hình hình thanh: bộ nhật chỉ ánh nắng, 西 cho âm shài (gần tây). Phơi nắng là để mặt trời làm khô.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sái\": mặt trời (日-Nhật) hướng tây (西-Tây) — buổi chiều mặt trời tây chiếu mạnh, phơi đồ dưới nắng. Sái = phơi nắng. | Gương Hán-Việt | sái trong ''sái cổ tay'' — âm giống; 晒 chỉ phơi nắng, không liên quan trật khớp | Mở khoá kiến thức | Biết 晒 mở khoá: 晒太阳 (sái thái dương – tắm nắng), 晒干 (sái can – phơi khô), 日晒 (nhật sái – phơi nắng).", "Tự nguyên_Xie": "晒 gồm 日 (nhật – mặt trời) và 西 (tây). Wiktionary không có glyphOrigin chi tiết cho 晒. Cấu trúc gợi ý: mặt trời (日) ở phía tây (西) — hình ảnh mặt trời buổi chiều gay gắt nhất để phơi. Hoặc đơn giản là hình thanh: 日 biểu nghĩa, 西 cho âm. Chưa có nguồn học thuật đầy đủ. | Theo Wiktionary · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1115.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Nhật (072) Tây (185)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Nhật (số 072 - mặt trời) ở bên trái chữ Tây (số 185 - phương tây). Giải thích sự chuyển ý: Đây là chữ Hội ý. Sái là dùng ánh mặt trời để làm khô, phơi nắng. Đây là một chữ biến thể giản dị của chữ Sái 曬.", "Nghĩa Tiếng Việt_Xie": "phơi", "Hạng Tần Suất (Jun Da)": "2624.0", "Tần Suất % (Jun Da)": "98.7065421039", "GavinGrover_Once (Chiết tự trực tiếp)": "日 + 西", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰日西", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "西", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "日", "Unihan_Simplified (Chữ Giản thể)": "晒", "Unihan_Traditional (Chữ Phồn thể)": "晒", "Pinyin_Xie": "shài", "Âm Hán Việt_Xie": "sái", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường làm động từ mang tân ngữ chỉ đồ vật cần phơi hoặc dùng trong khẩu ngữ với nghĩa là chia sẻ hình ảnh lên mạng xã hội. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | shài | / | phơi nắng; làm khô dưới ánh mặt trời | Xuất hiện trong lộ trình | New HSK | New HSK 4 | · | Hộ gia đình | HSK | HSK 5 | · | Thiên nhiên và động vật", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('霜', '{"9000": "2625.0", "Chữ Trung Quốc": "霜", "Bộ thủ & thành phần_Xie": "Bộ thủ | 雨 | Số nét | 17 | nét | 雨 | vũ | biểu nghĩa | mưa, thời tiết | 相 | tương | biểu âm | nhau, tướng | 霜 = 雨 (Vũ, biểu nghĩa: mưa/hiện tượng khí hậu) + 相 (Tương, biểu âm); chữ hình thanh. Bộ vũ chỉ các hiện tượng thời tiết từ trên trời, 相 cho âm gần shuāng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sương\": trời (雨) lạnh tương (相) ứng — sương giá phủ trắng mặt đất mỗi sáng đông. | Gương Hán-Việt | \"sương\" trong 霜雪 (sương tuyết), 雪上加霜 (tuyết thượng gia sương — họa vô đơn chí) | Mở khoá kiến thức | Biết 霜 mở khoá thành ngữ: 雪上加霜 (thêm khó chồng khó), 风霜 (phong sương, gian khổ), 霜降 (tiết khí mùa thu).", "Tự nguyên_Xie": "Giáp cốt văn | Tiểu triện | Lục thư thông | Theo Wiktionary, 霜 là chữ hình thanh: 雨 (mưa) biểu nghĩa, 相 biểu âm. Giáp cốt văn đã có dạng sớm. Sương giá hình thành khi hơi nước đóng băng trực tiếp trên bề mặt lạnh vào ban đêm, khác với tuyết hay đá. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "471.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Vũ (90) Tương (127)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Vũ (số 173 - cơn mưa) ở trên chữ Tương (số 109 - cùng nhau/tương tự) . Giọt mưa (Vũ) lạnh lẽo rơi xuống đọng lại trên cây tương tự như (Tương) những hạt sương giá. Giải thích sự chuyển ý: Chữ Tương (tương tự) chỉ âm, chữ Vũ (mưa) chỉ ý. Hơi nước (Vũ) trong không khí ngưng tụ lại trên mặt đất thành lớp trắng mỏng lạnh lẽo gọi là sương (Sương). *(Biến âm Hán Việt: Tương -> Sương)*", "Nghĩa Tiếng Việt_Xie": "sương", "Hạng Tần Suất (Jun Da)": "2625.0", "Tần Suất % (Jun Da)": "98.7081539568", "GavinGrover_Once (Chiết tự trực tiếp)": "雨 + 相", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱雨相", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "相", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "雨", "Unihan_Simplified (Chữ Giản thể)": "霜", "Unihan_Traditional (Chữ Phồn thể)": "霜", "Pinyin_Xie": "shuāng", "Âm Hán Việt_Xie": "sương", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng độc lập để chỉ hiện tượng thời tiết hoặc kết hợp làm tên các loại mỹ phẩm dạng kem. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | shuāng | / | sương giá | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Sự kiện tự nhiên II", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('剿', '{"9000": "2626.0", "Chữ Trung Quốc": "剿", "Bộ thủ & thành phần_Xie": "Bộ thủ | 刀 | Số nét | 13 | nét | 巢 | sào | biểu âm | tổ chim, hang ổ | 刂 | đao | biểu nghĩa | dao, tiêu diệt | 剿 = 巢 (Sào, biểu âm) + 刂 (Đao, biểu nghĩa: dao/tiêu diệt); chữ hình thanh. Bộ đao 刂 cho biết hành động cắt/tiêu diệt; 巢 (sào) cho âm đọc. Hình ảnh phá tổ (sào) bằng dao gợi nghĩa tiễu trừ, đánh dẹp.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tiễu\": dao (刂) phá tổ (巢) — 剿 là tiễu trừ, đánh dẹp, triệt phá hang ổ kẻ thù. | Gương Hán-Việt | Tiễu trong \"tiễu phỉ\" (đánh dẹp giặc cướp), \"tiễu trừ\" (triệt tiêu, tiêu diệt). | Mở khoá kiến thức | Biết 剿 (tiễu) mở khóa: 围剿 (vây tiễu, bao vây đánh dẹp), 剿灭 (tiêu diệt), 剿匪 (tiễu phỉ).", "Tự nguyên_Xie": "Đại triện | 剿 là chữ hình thanh (gốc từ 劋): 刀 (đao, dao) biểu nghĩa, 巢 (sào) biểu âm. Nghĩa gốc là chặt phá tổ/hang ổ; mở rộng sang tiễu trừ, đánh dẹp, triệt hạ (thường dùng cho việc trấn áp nghĩa quân, thổ phỉ). Chữ gốc là 劋, sau đơn giản hóa thành 剿. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chặn lại, trừ khử", "Hạng Tần Suất (Jun Da)": "2626.0", "Tần Suất % (Jun Da)": "98.7097621921", "GavinGrover_Once (Chiết tự trực tiếp)": "巢 + 刂", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰巢刂", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "巢", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "刂", "Unihan_Simplified (Chữ Giản thể)": "剿", "Unihan_Traditional (Chữ Phồn thể)": "剿", "Pinyin_Xie": "jiǎo", "Âm Hán Việt_Xie": "tiễu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đi kèm tân ngữ chỉ giặc giã hoặc thế lực phản động để chỉ hành động dẹp loạn. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蕴', '{"9000": "2627.0", "Chữ Trung Quốc": "蕴", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 15 | nét | 艹 | thảo | biểu nghĩa | cỏ, thực vật | 缊 | uân | biểu âm | chỉ cuộn, rối | 蕴 = 艹(Thảo, biểu nghĩa: cỏ) + 缊 (Uân, biểu âm); chữ hình thanh. Nghĩa gốc liên quan đến cỏ chất đống, tích tụ, từ đó mở rộng sang nghĩa chứa đựng, tích lũy sâu xa.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"uẩn\": cỏ (艹) cuộn lại uẩn khúc (缊) — điều gì đó tích tụ sâu bên trong, không dễ nhìn thấy. | Gương Hán-Việt | \"uẩn\" trong 蕴藏 (uẩn tàng — chứa đựng), 底蕴 (để uẩn — nội hàm), 五蕴 (ngũ uẩn — Phật giáo) | Mở khoá kiến thức | Biết 蕴 mở khoá từ triết học: 蕴藏 (uẩn tàng), 底蕴 (để uẩn), 含蕴 (hàm uẩn), ngũ uẩn trong Phật giáo.", "Tự nguyên_Xie": "Theo Wiktionary, 蕴 (dạng phồn thể 蘊) là chữ hình thanh: 艸 (cỏ) biểu nghĩa, 縕 biểu âm. Nghĩa gốc là chất cỏ, tích trữ. Từ đó mở rộng sang nghĩa chứa đựng sâu xa, hàm súc. Trong Phật giáo, 蕴 (uẩn) là thuật ngữ chỉ ngũ uẩn tạo nên con người. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tích chứa, góp; sâu xa; giấu, cất; chất cỏ", "Hạng Tần Suất (Jun Da)": "2627.0", "Tần Suất % (Jun Da)": "98.7113693939", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 缊", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹缊", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "缊", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "蕴", "Unihan_Traditional (Chữ Phồn thể)": "蘊", "Pinyin_Xie": "yùn", "Âm Hán Việt_Xie": "uẩn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường kết hợp với các chữ khác để tạo thành động từ hoặc danh từ chỉ sự tích tụ, chứa đựng bên trong. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('圾', '{"9000": "2628.0", "Chữ Trung Quốc": "圾", "Bộ thủ & thành phần_Xie": "Bộ thủ | 土 | Số nét | 6 | nét | 土 | thổ | biểu nghĩa | đất — rác đổ ra đất | 及 | cập | biểu âm | gợi âm ''jī'' | 圾 = 土 (Thổ, đất) + 及 (Cập, biểu âm). Chữ hình thanh: nghĩa hiện đại ''rác''. Phần lớn chỉ dùng trong từ ghép 垃圾.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt ''Sắc'': đổ ra đất (土) cho kịp (及) gom — đó là ''sắc'', là rác rưởi (chỉ dùng trong 垃圾). | Gương Hán-Việt | ''Sắc'' (Hán-Việt cổ); trong tiếng Việt hiện đại 圾 chỉ thấy trong 垃圾 (lā jī, rác). | Mở khoá kiến thức | Biết 圾 mở khóa 垃圾 (rác), 垃圾桶 (thùng rác), 垃圾车 (xe rác), 垃圾食品 (đồ ăn vặt).", "Tự nguyên_Xie": "Theo Wiktionary, 圾 là chữ hình thanh: 土 biểu nghĩa, 及 biểu âm. Chỉ dùng trong 垃圾 (lā jī, rác). Nguồn gốc cổ của hai chữ này là đôi từ ghép cố định. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "rác; rác rưởi", "Hạng Tần Suất (Jun Da)": "2628.0", "Tần Suất % (Jun Da)": "98.7129724614", "GavinGrover_Once (Chiết tự trực tiếp)": "土 + 及", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰土及", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "及", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "土", "Unihan_Simplified (Chữ Giản thể)": "圾", "Unihan_Traditional (Chữ Phồn thể)": "圾", "Pinyin_Xie": "jī", "Âm Hán Việt_Xie": "ngập", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Hầu như chỉ xuất hiện trong từ ghép song âm tiết để chỉ rác thải sinh hoạt. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('绸', '{"9000": "2629.0", "Chữ Trung Quốc": "绸", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 11 | nét | 纟 | mịch | biểu nghĩa | sợi chỉ, vải lụa | 周 | chu | biểu âm | xung quanh — cho âm chu/trù | 绸 = 纟(Mịch, biểu nghĩa: tơ sợi) + 周 (Chu, biểu âm). Wiktionary ghi đây là chữ giản thể của 綢 (nạp f=糹 t=纟). Cấu trúc hình thanh: bộ mịch (tơ) biểu nghĩa lụa, 周 cho âm chóu (gần trù/chu). Lụa được dệt từ tơ tằm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trù\": tơ sợi (纟-Mịch) bao quanh (周-Chu) — những sợi tơ dệt vòng quanh nhau thành lụa. Trù = lụa tơ. | Gương Hán-Việt | trù trong ''trù bị'' — âm giống; 绸 là lụa tơ, không liên quan trù bị | Mở khoá kiến thức | Biết 绸 mở khoá: 丝绸 (ty trù – lụa tơ tằm), 绸缎 (trù đoạn – lụa và gấm), 绸子 (trù tử – vải lụa).", "Tự nguyên_Xie": "绸 (giản thể của 綢) là chữ hình thanh: 纟(mịch – sợi tơ) biểu nghĩa, 周 (chu) biểu âm. Wiktionary ghi: {{Han simp|綢|f=糹|t=纟}}. Chữ truyền thống là 綢 với bộ 糹(mịch). Nghĩa là lụa, vải lụa tơ tằm. 丝绸 (ty trù) là từ thông dụng chỉ lụa Trung Hoa. Chưa có glyphOrigin chi tiết hơn. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lụa; tơ", "Hạng Tần Suất (Jun Da)": "2629.0", "Tần Suất % (Jun Da)": "98.7145734617", "GavinGrover_Once (Chiết tự trực tiếp)": "纟 + 周", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰纟周", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "周", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "纟", "Unihan_Simplified (Chữ Giản thể)": "绸", "Unihan_Traditional (Chữ Phồn thể)": "綢", "Pinyin_Xie": "chóu", "Âm Hán Việt_Xie": "trù", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng trước danh từ khác để chỉ chất liệu của trang phục hoặc làm tân ngữ trong câu. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('屿', '{"9000": "2630.0", "Chữ Trung Quốc": "屿", "Bộ thủ & thành phần_Xie": "Bộ thủ | 山 | Số nét | 6 | nét | 山 | sơn | biểu nghĩa | núi | 与 | dư | biểu âm | và, cho (gần âm yǔ) | 屿 là dạng giản thể của 嶼 — hình thanh: 山 (Sơn, biểu nghĩa: núi) + 与 (Dư, biểu âm, giản thể từ 與). Núi nhỏ giữa biển, gốc nghĩa ''đảo nhỏ''.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tự\": 山 (núi) + 与 (Dư) — núi nổi lên giữa biển = đảo nhỏ, đúng nghĩa ''đảo nhỏ'' trong 岛屿. | Gương Hán-Việt | ''tự'' (Hán-Việt) — gần với ''đảo'' trong tiếng Việt | Mở khoá kiến thức | Nắm 屿 mở khoá từ HSK 6: 岛屿.", "Tự nguyên_Xie": "Theo Wiktionary, 屿 là giản thể của 嶼 — hình thanh: 山 (núi, biểu nghĩa) + 與/与 (Dư, biểu âm). Nghĩa ''đảo nhỏ, hòn đảo'' giữ nguyên trong 岛屿. Cùng nhóm với 岛 (đảo) nhưng 屿 thường chỉ đảo nhỏ hoặc các quần đảo trong tổ hợp 岛屿. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đảo nhỏ", "Hạng Tần Suất (Jun Da)": "2630.0", "Tần Suất % (Jun Da)": "98.7161744621", "GavinGrover_Once (Chiết tự trực tiếp)": "山 + 与", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰山与", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "与", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "山", "Unihan_Simplified (Chữ Giản thể)": "屿", "Unihan_Traditional (Chữ Phồn thể)": "嶼", "Pinyin_Xie": "yǔ", "Âm Hán Việt_Xie": "tự", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường kết hợp với danh từ khác để tạo thành danh từ ghép chỉ địa danh hoặc các hòn đảo nhỏ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('氢', '{"9000": "2631.0", "Chữ Trung Quốc": "氢", "Bộ thủ & thành phần_Xie": "Bộ thủ | 气 | Số nét | 9 | nét | 气 | khí | biểu nghĩa | khí, hơi | 𢀖 | biểu âm | (thành phần biểu âm trong dạng giản thể) | 氢 (phồn thể 氫) = 气 (Khí, biểu nghĩa: khí/hơi) + thành phần biểu âm; chữ hình thanh. Bộ khí 气 chỉ chất khí; phần còn lại cho âm đọc qīng. Đây là chữ tạo muộn để phiên âm tên nguyên tố hóa học Hydro.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khinh\": khí (气) khinh nhất — 氢 là Hydro, nguyên tố nhẹ nhất trong bảng tuần hoàn. | Gương Hán-Việt | Khinh trong \"khinh khí\" (氢气 — khí hydro), liên hệ với \"khinh\" (nhẹ) trong tiếng Việt. | Mở khoá kiến thức | Biết 氢 (khinh) mở khóa: 氢气 (khí hydro), 氢弹 (bom hydro), 液氢 (hydro lỏng), 氢能 (năng lượng hydro).", "Tự nguyên_Xie": "氢 (phồn thể 氫) là chữ khoa học tạo muộn: 气 (khí) biểu nghĩa chất khí, thành phần biểu âm cho âm qīng. Chữ được tạo ra để ký hiệu nguyên tố Hydro (H) — chất khí nhẹ nhất, không màu, không mùi. Hán-Việt \"khinh\" (nhẹ) phản ánh đặc tính nhẹ nhất của Hydro. Chữ tạo muộn, không có giáp cốt/kim văn. | Suy từ bộ phận cấu thành · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "khinh khí, khí hidro", "Hạng Tần Suất (Jun Da)": "2631.0", "Tần Suất % (Jun Da)": "98.7177723617", "GavinGrover_Once (Chiết tự trực tiếp)": "气 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴气", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "氢", "Unihan_Traditional (Chữ Phồn thể)": "氫", "Pinyin_Xie": "qīng", "Âm Hán Việt_Xie": "khinh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ trong các thuật ngữ hóa học hoặc kết hợp để chỉ các hợp chất chứa hi-đrô. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | qīng | / | hydro | Xuất hiện trong lộ trình | HSK | HSK 6 | · | Hoá học", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('驼', '{"9000": "2632.0", "Chữ Trung Quốc": "驼", "Bộ thủ & thành phần_Xie": "Bộ thủ | 馬 | Số nét | 8 | nét | 马 | mã | biểu nghĩa | ngựa, động vật | 它 | tha | biểu âm | nó (đại từ ngôi 3 trung tính) | 驼 (phồn thể 駝) = 马 (Mã, biểu nghĩa: động vật, liên quan ngựa/thú vật) + 它 (Tha, biểu âm); chữ hình thanh. Bộ mã 马 chỉ loài thú vật lớn; 它 (tha) cho âm đọc tuó. Đây là chữ giản thể của 駝.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đà\": thú vật (马) mang cái \"tha\" trên lưng — 驼 là lạc đà, vật mang nặng qua sa mạc, cũng chỉ lưng gù. | Gương Hán-Việt | Đà trong \"lạc đà\" (骆驼 — con lạc đà), \"đà bối\" (lưng gù). | Mở khoá kiến thức | Biết 驼 (đà) mở khóa: 骆驼 (lạc đà), 驼背 (lưng gù), 驼峰 (bướu lạc đà), 驼色 (màu be/lạc đà).", "Tự nguyên_Xie": "驼 (phồn thể 駝) là chữ hình thanh: 马 (mã) biểu nghĩa loài thú, 它 (tha) biểu âm. Chữ chỉ con lạc đà (骆驼 luòtuó) — loài thú sa mạc có bướu lưng đặc trưng. Mở rộng sang nghĩa bướu, lưng còng (驼背 — lưng gù). Hán-Việt \"đà\" trong \"lạc đà\" (骆驼). chưa có nguồn học thuật chi tiết cho dạng giản thể. | Suy từ bộ phận cấu thành · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: lạc đà 駱駝,骆驼)", "Hạng Tần Suất (Jun Da)": "2632.0", "Tần Suất % (Jun Da)": "98.7193661271", "GavinGrover_Once (Chiết tự trực tiếp)": "马 + 它", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰马它", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "它", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "马", "Unihan_Simplified (Chữ Giản thể)": "驼", "Unihan_Traditional (Chữ Phồn thể)": "駝", "Pinyin_Xie": "tuó", "Âm Hán Việt_Xie": "đà", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Tính từ | 形容词 | Thường làm danh từ trong từ ghép chỉ con lạc đà hoặc làm động từ với nghĩa là cõng, thồ hàng trên lưng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('妆', '{"9000": "2633.0", "Chữ Trung Quốc": "妆", "Bộ thủ & thành phần_Xie": "Bộ thủ | 女 | Số nét | 6 | nét | 丬 | biểu âm | hình dáng giường/ván (biểu âm cho zhuāng) | 女 | nữ | biểu nghĩa | phụ nữ | 妆 = 丬(biểu âm, dạng thu gọn của 爿, cho âm zhuāng) + 女 (Nữ, biểu nghĩa: phụ nữ); chữ hình thanh. Dạng phồn thể là 妝. Bộ nữ chỉ đối tượng là phụ nữ, 爿 (丬) cho âm trang/zhuāng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trang\": phụ nữ (女) trang điểm bằng ván gương (丬) — hình ảnh cô gái trước gương trang sức. | Gương Hán-Việt | \"trang\" trong 化妆 (hoá trang — trang điểm), 嫁妆 (giá trang — của hồi môn) | Mở khoá kiến thức | Biết 妆 mở khoá từ vẻ đẹp: 化妆 (hoá trang), 嫁妆 (giá trang), 卸妆 (tả trang, tẩy trang).", "Tự nguyên_Xie": "Kim văn | Tiểu triện | Theo Wiktionary, 妝 (妆) là chữ hình thanh: 爿 biểu âm cho zhuāng, 女 (phụ nữ) biểu nghĩa. Kim văn và tiểu triện đã có dạng ghi nhận. Nghĩa gốc là trang điểm, trang sức cho phụ nữ. Từ đó mở rộng sang của hồi môn (嫁妆), trang phục biểu diễn. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đồ trang điểm, trang sức", "Hạng Tần Suất (Jun Da)": "2633.0", "Tần Suất % (Jun Da)": "98.7209593756", "GavinGrover_Once (Chiết tự trực tiếp)": "丬 + 女", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰丬女", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "女", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "丬", "Unihan_Simplified (Chữ Giản thể)": "妆", "Unihan_Traditional (Chữ Phồn thể)": "妝", "Pinyin_Xie": "zhuāng", "Âm Hán Việt_Xie": "trang", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường làm danh từ chỉ lớp trang điểm hoặc làm động từ chỉ hành động tô son điểm phấn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('捆', '{"9000": "2634.0", "Chữ Trung Quốc": "捆", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 10 | nét | 扌 | thủ | biểu nghĩa | tay | 困 | khốn | biểu âm | khốn khó | 捆 = 扌(Thủ, biểu nghĩa: tay) + 困 (Khốn, biểu âm); chữ hình thanh. Bộ thủ chỉ hành động dùng tay buộc, 困 cho âm gần kǔn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khổn\": tay (扌) làm cho khốn (困) — trói chặt tay chân, người bị khổn khó di chuyển. | Gương Hán-Việt | \"khổn\" trong 捆绑 (khổn bằng — trói, ràng buộc) | Mở khoá kiến thức | Biết 捆 mở khoá từ hành động: 捆绑 (khổn bằng, trói), 捆包 (khổn bao, gói bó), lượng từ 一捆 (một bó).", "Tự nguyên_Xie": "Theo Wiktionary, 捆 là chữ hình thanh: 手 (tay, bộ 扌) biểu nghĩa, 困 biểu âm. Nghĩa gốc là trói buộc, bó lại bằng tay. Từ đó mở rộng thành lượng từ đếm bó đồ vật. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1845.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thủ (064) Khốn (401)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Thủ (số 064 - cái tay/ 扌/chỉ ý) ở bên trái chữ Khốn (số 401 - khốn khổ/ 困 /chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Khốn chỉ âm, bộ Thủ chỉ ý. Khổn là dùng tay để trói buộc, cột lại, bó chặt lại (khổn phược).", "Nghĩa Tiếng Việt_Xie": "ghép chặt; trói", "Hạng Tần Suất (Jun Da)": "2634.0", "Tần Suất % (Jun Da)": "98.7225505571", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 困", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌困", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "困", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "捆", "Unihan_Traditional (Chữ Phồn thể)": "捆", "Pinyin_Xie": "kǔn", "Âm Hán Việt_Xie": "khổn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Lượng từ | 量词 | Thường làm động từ chỉ hành động buộc đồ vật hoặc làm lượng từ cho các vật được bó lại thành cụm. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Lượng từ | 量词 | Đứng giữa số từ (hoặc 这/那) và danh từ: 一杯茶, 这本书. Mỗi danh từ đi với lượng từ riêng; 个 là lượng từ dùng chung phổ biến nhất.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | kǔn | / | buộc lại với nhau | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Từ III", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('铅', '{"9000": "2635.0", "Chữ Trung Quốc": "铅", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 10 | nét | 钅 | kim | biểu nghĩa | bộ kim — kim loại | 㕣 | duyên | biểu âm | thanh phù (𠘧 + 口), gợi âm ''qiān'' | 铅 (giản thể của 鉛) = 钅 (Kim, biểu nghĩa: kim loại) + 㕣 (Duyên, biểu âm — gồm 𠘧 ở trên và 口 ở dưới); chữ hình thanh. Nghĩa ''chì — một kim loại mềm dùng làm ruột bút''.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"duyên\": kim loại (钅) gọi tên là duyên (㕣) — kim loại mềm này làm ruột bút, nên 铅 nghĩa ''chì, bút chì''. | Gương Hán-Việt | ''duyên'' Hán-Việt của 铅 (chì) hiếm gặp; tham chiếu ''duyên'' trong ''duyên cớ'' (缘) là chữ khác — cần phân biệt | Mở khoá kiến thức | Nắm 铅 mở khoá 铅笔 — vật dụng học tập cơ bản, và 铅球 (môn ném tạ), 铅字.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Theo Wiktionary, 铅 là dạng giản thể của 鉛, là chữ hình thanh: 金/钅 (kim — kim loại) làm nghĩa phù, 㕣 (duyên) làm thanh phù. Khi giản thể, 金 rút thành 钅. Nghĩa ''chì'' (kim loại Pb), về sau đặc biệt được dùng trong 铅笔 (bút chì) — ruột bút làm từ than chì. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "kim loại chì, Pb", "Hạng Tần Suất (Jun Da)": "2635.0", "Tần Suất % (Jun Da)": "98.7241396714", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "铅", "Unihan_Traditional (Chữ Phồn thể)": "鉛", "Pinyin_Xie": "qiān", "Âm Hán Việt_Xie": "diên, duyên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ đứng độc lập hoặc làm định ngữ bổ nghĩa cho danh từ khác để chỉ đồ vật làm bằng chì. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | qiān | / | chì | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Hóa học và Sinh học I", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('逛', '{"9000": "2636.0", "Chữ Trung Quốc": "逛", "Bộ thủ & thành phần_Xie": "Bộ thủ | 辵 | Số nét | 10 | nét | 辶 | sước | biểu nghĩa | đi, di chuyển | 狂 | cuồng | biểu âm | gợi âm guàng | 逛 = 辶 (Sước, biểu nghĩa: đi) + 狂 (Cuồng, biểu âm); chữ hình thanh. Đi vòng vòng tự do — ''dạo, rong chơi''.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cuống\": 辶 (đi) + 狂 (cuồng) — đi cuồng nhiệt khắp nơi, ấy là ''cuống/dạo''; nhớ 逛街 (đi dạo phố), 闲逛 (rong chơi). | Gương Hán-Việt | ''cuống'' theo Hán-Việt hiếm dùng; nghĩa thông dụng = ''dạo phố, rong chơi'' | Mở khoá kiến thức | Biết 逛 là mở 逛街, 闲逛, 逛商店 — nhóm động từ về giải trí HSK 4-6.", "Tự nguyên_Xie": "Theo Wiktionary, 逛 là chữ hình thanh: 辶 (biểu nghĩa: đi) ghép với 狂 (biểu âm). Nghĩa: đi dạo, rong chơi, lang thang vô định. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đi đủng đỉnh", "Hạng Tần Suất (Jun Da)": "2636.0", "Tần Suất % (Jun Da)": "98.7257282689", "GavinGrover_Once (Chiết tự trực tiếp)": "辶 + 狂", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴辶狂", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "狂", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "辶", "Unihan_Simplified (Chữ Giản thể)": "逛", "Unihan_Traditional (Chữ Phồn thể)": "逛", "Pinyin_Xie": "guàng", "Âm Hán Việt_Xie": "cuống", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ thường mang theo tân ngữ chỉ địa điểm như phố xá, công viên hoặc cửa hàng. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | guàng | / | dạo quanh | Xuất hiện trong lộ trình | New HSK | New HSK 4 | · | Mua sắm | HSK | HSK 4 | · | Mua sắm", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('淑', '{"9000": "2637.0", "Chữ Trung Quốc": "淑", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 11 | nét | 氵 | thuỷ | biểu nghĩa | nước, trong sạch | 叔 | thúc | biểu âm | chú, chú bác | 淑 = 氵 (Thuỷ, biểu nghĩa: nước/trong sáng) + 叔 (Thúc, biểu âm); chữ hình thanh. Bộ thuỷ 氵 gợi ý trong sáng như nước; 叔 (thúc) cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thục\": nước (氵) trong sáng như đức thục (叔) hạnh — 淑 là hiền thục, trong sáng, dịu dàng; thường dùng trong tên con gái. | Gương Hán-Việt | Thục trong \"hiền thục\" (淑女 — phụ nữ hiền thục), \"ôn nhu thục đức\" (ôn hòa hiền thục). | Mở khoá kiến thức | Biết 淑 (thục) mở khóa: 淑女 (thục nữ — người phụ nữ hiền thục), 贤淑 (hiền thục), 温淑 (ôn thục dịu dàng).", "Tự nguyên_Xie": "Tiểu triện | 淑 là chữ hình thanh: 氵 (thuỷ) biểu nghĩa nước trong, sạch sẽ, 叔 (thúc) biểu âm. Nghĩa gốc là nước trong, limpid; mở rộng sang trong sáng, thanh khiết, dịu dàng — phẩm chất của người phụ nữ hiền thục. Thường dùng trong tên phụ nữ và tính từ chỉ vẻ đẹp đức hạnh. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "hiền lành", "Hạng Tần Suất (Jun Da)": "2637.0", "Tần Suất % (Jun Da)": "98.7273142824", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 叔", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵叔", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "叔", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "淑", "Unihan_Traditional (Chữ Phồn thể)": "淑", "Pinyin_Xie": "shū", "Âm Hán Việt_Xie": "thục", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này làm tính từ thường dùng để miêu tả phẩm hạnh tốt đẹp của người phụ nữ hoặc dùng trong tên riêng. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('榴', '{"9000": "2638.0", "Chữ Trung Quốc": "榴", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 14 | nét | 木 | mộc | biểu nghĩa | cây, gỗ | 留 | lưu | biểu âm | ở lại, lưu lại | 榴 = 木 (Mộc, biểu nghĩa: cây) + 留 (Lưu, biểu âm); chữ hình thanh. Bộ mộc 木 chỉ loài cây; 留 (lưu) cho âm đọc liú.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lựu\": cây (木) có quả lưu lại lâu (留) — 榴 là cây lựu, quả lựu (石榴), quả đỏ hồng hạt nhiều. | Gương Hán-Việt | Lựu trong \"thạch lựu\" (石榴 — quả lựu), \"lựu đạn\" (lựu đạn, hình dáng như quả lựu). | Mở khoá kiến thức | Biết 榴 (lựu) mở khóa: 石榴 (thạch lựu — cây/quả lựu), 榴莲 (sầu riêng), 手榴弹 (lựu đạn).", "Tự nguyên_Xie": "榴 là chữ hình thanh: 木 (mộc, cây) biểu nghĩa, 留 (lưu) biểu âm. Chữ chỉ cây lựu (石榴 shíliu), một loài cây ăn quả du nhập vào Trung Hoa từ vùng Trung Á qua con đường tơ lụa. Tên 石榴 (thạch lựu) được cho là phiên âm từ tên địa danh nơi loài cây này có nguồn gốc. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cây lựu", "Hạng Tần Suất (Jun Da)": "2638.0", "Tần Suất % (Jun Da)": "98.7288997792", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 留", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木留", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "留", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "榴", "Unihan_Traditional (Chữ Phồn thể)": "榴", "Pinyin_Xie": "liú", "Âm Hán Việt_Xie": "lựu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ thường kết hợp với các từ khác để chỉ các loại cây quả như thạch lựu hay sầu riêng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('丙', '{"9000": "2639.0", "Chữ Trung Quốc": "丙", "Bộ thủ & thành phần_Xie": "Bộ thủ | 一 | Số nét | 5 | nét | 丙 | bính | tượng hình | Can thứ ba trong Thiên Can | 丙 là chữ tượng hình độc lập. Theo Wiktionary có nhiều thuyết về hình gốc: vai gánh, đuôi cá, bộ phận cỗ xe, bệ đỡ. Dù nguồn gốc hình ảnh đã mờ, chữ được dùng ổn định làm Thiên Can thứ ba từ thời cổ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bính\": Bính là Can thứ Ba — Giáp Ất Bính Đinh, như ABC chỉ thứ tự, hạng mục. | Gương Hán-Việt | \"bính\" trong 丙级 (bính cấp — hạng C), 丙午 (bính ngọ — năm Bính Ngọ) | Mở khoá kiến thức | Biết 丙 mở khoá hệ thống Can Chi: 甲乙丙丁 (giáp ất bính đinh) — thứ tự, phân loại văn hoá Hán.", "Tự nguyên_Xie": "Giáp cốt văn | Kim văn | Bạch thư | Đại triện | Tiểu triện | Theo Wiktionary, 丙 có nhiều thuyết tượng hình: có thể là hai vai (Thuyết Văn), đuôi cá (Nhĩ Nhã), bộ phận cỗ xe (như trong 更 cổ), hoặc bệ đỡ nhỏ. Một thuyết cho rằng đây là dạng gốc của 柄 (cán). Giáp cốt văn, kim văn, bạch thư đều ghi nhận. Dù nghĩa gốc thất lạc, 丙 được dùng ổn định làm vị trí thứ ba trong Thiên Can. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1550.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Nhất (001) Nội (012)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Nhất (số 001 - một/ 一) ở trên bộ Nội (số 012 - bên trong/ 內). Giải thích sự chuyển ý: Đây là chữ Tượng hình. Bính là ngọn lửa cháy rực rỡ, sáng tỏ, hiện rõ ra ngoài. Nó là tên của thiên can thứ 3 trong 10 Thiên Can (can Bính).", "Nghĩa Tiếng Việt_Xie": "Bính (ngôi thứ 3 của hàng Can)", "Hạng Tần Suất (Jun Da)": "2639.0", "Tần Suất % (Jun Da)": "98.7304785578", "GavinGrover_Once (Chiết tự trực tiếp)": "一 + 内", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱一内", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "内", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "一", "Unihan_Simplified (Chữ Giản thể)": "丙", "Unihan_Traditional (Chữ Phồn thể)": "丙", "Pinyin_Xie": "bǐng", "Âm Hán Việt_Xie": "bính", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Số từ | 数词 | Chữ này làm danh từ chỉ thiên can hoặc làm số từ biểu thị thứ hạng ba trong xếp loại học lực, chất lượng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Số từ | 数词 | Chỉ số lượng hoặc thứ tự. Hầu như không đứng thẳng trước danh từ mà phải chèn lượng từ ở giữa: 两个人.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | Từ đơn | Từ vựng HSK 5: thứ ba | / | bǐng | / | thứ ba | Xuất hiện trong lộ trình | HSK | HSK 5 | · | Đo đạc | New HSK | New HSK 7-9 | · | Toán học và Hình học", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('痒', '{"9000": "2640.0", "Chữ Trung Quốc": "痒", "Bộ thủ & thành phần_Xie": "Bộ thủ | 疒 | Số nét | 11 | nét | 疒 | nạch | biểu nghĩa | bệnh tật, ốm đau | 羊 | dương | biểu âm | con dê — cho âm dương | 痒 = 疒(Nạch, biểu nghĩa: bệnh) + 羊 (Dương, biểu âm); chữ hình thanh. Wiktionary ghi: {{Han compound|疒|羊|ls=psc|c1=s|c2=p|t1=illness}}. Bộ nạch chỉ cảm giác khó chịu trên da; 羊 cho âm yǎng (gần dương). Ngứa là cảm giác bệnh ngoài da.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"dưỡng\": bệnh (疒-Nạch) + Dương (羊-con dê) — da ngứa ngáy khó chịu như lông dê cọ vào người. Dưỡng = ngứa. | Gương Hán-Việt | dưỡng trong ''dưỡng sinh, nuôi dưỡng'' — âm giống 养 (dưỡng); 痒 là ngứa, 养 là nuôi | Mở khoá kiến thức | Biết 痒 mở khoá: 发痒 (phát dưỡng – nổi ngứa), 痒痒 (dưỡng dưỡng – ngứa ngáy), 手痒 (thủ dưỡng – ngứa tay muốn làm).", "Tự nguyên_Xie": "痒 là chữ hình thanh: 疒 (nạch – bệnh) biểu nghĩa, 羊 (dương – con dê) biểu âm. Wiktionary xác nhận cấu trúc psc này. Bộ nạch xuất hiện trong các chữ chỉ bệnh tật/cảm giác khó chịu như 病, 痛, 疼. Ngứa (痒) là cảm giác khó chịu trên da, xếp vào nhóm ''bệnh'' (疒) về mặt cấu tạo chữ. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ốm; ngứa", "Hạng Tần Suất (Jun Da)": "2640.0", "Tần Suất % (Jun Da)": "98.7320573364", "GavinGrover_Once (Chiết tự trực tiếp)": "疒 + 羊", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴疒羊", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "羊", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "疒", "Unihan_Simplified (Chữ Giản thể)": "痒", "Unihan_Traditional (Chữ Phồn thể)": "痒", "Pinyin_Xie": "yǎng", "Âm Hán Việt_Xie": "dương", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Chữ này làm tính từ chỉ cảm giác ngứa hoặc làm động từ biểu thị trạng thái ngứa ngáy ở da. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | Từ đơn | Từ vựng HSK 5: | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Bệnh I | HSK | HSK 5 | · | Sức khỏe", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('钞', '{"9000": "2641.0", "Chữ Trung Quốc": "钞", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 9 | nét | 钅 | kim | biểu nghĩa | kim loại, tiền | 少 | thiểu | biểu âm | ít | 钞 = 钅(Kim, biểu nghĩa: kim loại/tiền) + 少 (Thiểu, biểu âm); chữ hình thanh. Giản thể của 鈔. Bộ kim chỉ tiền bạc, 少 cho âm chāo.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sao\": tiền kim loại (钅) ít đi (少) khi đổi thành giấy — tiền giấy (钞票) nhẹ hơn vàng bạc. | Gương Hán-Việt | \"sao\" trong 钞票 (sao phiếu — tờ tiền, giấy bạc) | Mở khoá kiến thức | Biết 钞 mở khoá từ tài chính: 钞票 (sao phiếu, tờ tiền), 外钞 (ngoại sao, ngoại tệ tiền mặt).", "Tự nguyên_Xie": "Tiểu triện | 钞 là dạng giản thể của 鈔 (sao). 鈔 là chữ hình thanh với bộ 釒 biểu nghĩa và 少 biểu âm. Tiểu triện đã có dạng. Nghĩa gốc liên quan đến chép tay/sao chép, sau mở rộng thành tiền giấy (vì tiền giấy xưa được khắc in như sao chép). | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đáp úp, lén đánh; cướp bóc; tịch biên tài sản", "Hạng Tần Suất (Jun Da)": "2641.0", "Tần Suất % (Jun Da)": "98.7336330143", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 少", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅少", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "少", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "钞", "Unihan_Traditional (Chữ Phồn thể)": "鈔", "Pinyin_Xie": "chāo", "Âm Hán Việt_Xie": "sao", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này làm danh từ chỉ tiền giấy hoặc làm động từ với nghĩa sao chép, tịch thu tài sản. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蹄', '{"9000": "2642.0", "Chữ Trung Quốc": "蹄", "Bộ thủ & thành phần_Xie": "Bộ thủ | 足 | Số nét | 16 | nét | 𧾷 | túc | biểu nghĩa | chân, bàn chân | 帝 | đế | biểu âm | vua, hoàng đế | 蹄 = 𧾷/足 (Túc, biểu nghĩa: chân) + 帝 (Đế, biểu âm); chữ hình thanh. Bộ túc 足 chỉ bàn chân/chân; 帝 (đế) cho âm đọc tí.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đề\": chân (足) đế vương (帝) giẫm xuống — 蹄 là móng guốc, phần chân cứng của thú vật. | Gương Hán-Việt | Đề trong \"mã đề\" (móng ngựa), \"trư đề\" (móng lợn — món ăn). | Mở khoá kiến thức | Biết 蹄 (đề) mở khóa: 猪蹄 (móng lợn), 马蹄 (móng ngựa), 蹄子 (guốc, móng), 蹄形 (hình móng guốc).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 蹄 là chữ hình thanh: 足 (túc, chân) biểu nghĩa, 帝 (đế) biểu âm. Nghĩa là móng guốc của động vật (ngựa, bò, lợn…) — phần chân có móng cứng. Mở rộng sang chỉ cái chân của động vật có móng nói chung. 猪蹄 (móng lợn) là món ăn phổ biến. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "móng, vó (ngựa)", "Hạng Tần Suất (Jun Da)": "2642.0", "Tần Suất % (Jun Da)": "98.735206625", "GavinGrover_Once (Chiết tự trực tiếp)": "⻊ + 帝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰⻊帝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "帝", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⻊", "Unihan_Simplified (Chữ Giản thể)": "蹄", "Unihan_Traditional (Chữ Phồn thể)": "蹄", "Pinyin_Xie": "tí", "Âm Hán Việt_Xie": "đề", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ móng của các loài thú móng guốc như ngựa, lợn, trâu. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('犬', '{"9000": "2643.0", "Chữ Trung Quốc": "犬", "Bộ thủ & thành phần_Xie": "Bộ thủ | 犬 | Số nét | 4 | nét | 犬 | khuyển | tượng hình | con chó nhìn từ bên cạnh | 犬 là chữ tượng hình độc lập — hình vẽ con chó nhìn nghiêng từ bên cạnh. Đây là bộ thủ số 94. Khi đứng bên trái các chữ khác, 犬 biến dạng thành bộ 犭.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khuyển\": nét chữ 犬 như hình con chó (大) thêm một chấm trên lưng — khuyển mã (nói khiêm về thú cưng nhà mình). | Gương Hán-Việt | \"khuyển\" trong 猎犬 (liệp khuyển — chó săn), 犬儒 (khuyển nho — triết gia Cynics) | Mở khoá kiến thức | Biết 犬 mở khoá bộ 犭: 狗 (cẩu, chó), 狼 (lang, sói), 猫 (miêu, mèo), 猛 (mãnh, dữ tợn).", "Tự nguyên_Xie": "Giáp cốt văn | Kim văn | Bạch thư | Đại triện | Tiểu triện | Theo Wiktionary, 犬 là chữ tượng hình: hình vẽ con chó nhìn từ bên cạnh. Giáp cốt văn, kim văn, bạch thư, đại triện và tiểu triện đều có dạng ghi nhận phong phú, phản ánh hình ảnh con chó qua nhiều thời đại. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "502.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Hình ảnh vẽ lại con chó đang đứng ngước lên sủa, có một dấu chấm nhỏ ở trên lưng tượng trưng cho cái tai vểnh lên hoặc cái đuôi. Giải thích sự chuyển ý: Đây là chữ Tượng hình. Khắc họa hình dáng con chó nhà đang đứng sủa (Khuyển).", "Nghĩa Tiếng Việt_Xie": "con chó", "Hạng Tần Suất (Jun Da)": "2643.0", "Tần Suất % (Jun Da)": "98.7367786854", "GavinGrover_Once (Chiết tự trực tiếp)": "大 + 丶", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴大丶", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "丶", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "大", "Unihan_Simplified (Chữ Giản thể)": "犬", "Unihan_Traditional (Chữ Phồn thể)": "犬", "Pinyin_Xie": "quǎn", "Âm Hán Việt_Xie": "khuyển", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ loài chó, thường dùng trong văn viết hoặc các từ ghép Hán-Việt. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | quǎn | / | chó | Xuất hiện trong lộ trình | HSK | HSK 6 | · | Sinh học", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('躬', '{"9000": "2644.0", "Chữ Trung Quốc": "躬", "Bộ thủ & thành phần_Xie": "Bộ thủ | 身 | Số nét | 10 | nét | 身 | thân | biểu nghĩa | thân thể | 弓 | cung | biểu âm | cái cung | 躬 = 身 (Thân, biểu nghĩa: thân thể) + 弓 (Cung, biểu âm); chữ hình thanh. Bộ thân chỉ cơ thể người, 弓 cho âm gōng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cung\": thân (身) cong như cung (弓) — cúi mình kính cẩn, tự mình thân hành. | Gương Hán-Việt | \"cung\" trong 鞠躬 (cúc cung — cúi đầu chào), 躬行 (cung hành — thân hành) | Mở khoá kiến thức | Biết 躬 mở khoá từ lễ nghĩa: 鞠躬 (cúc cung, cúi chào), 躬行 (cung hành, thân hành), 躬身 (cung thân, cúi mình).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Theo Wiktionary, 躬 là chữ hình thanh: 身 (thân thể) biểu nghĩa, 弓 biểu âm. Tiểu triện và Lục thư thông có dạng ghi chép. Nghĩa gốc là thân mình, cơ thể. Từ đó mở rộng sang đích thân làm (躬行), cúi người chào (鞠躬). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1595.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thân (158) Cung (057)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Thân (số 158 - thân thể/ 身 /chỉ ý) ở bên trái bộ Cung (số 057 - cây cung/ 弓 /chỉ âm). Thân thể khom cong lại như hình cây cung. Giải thích sự chuyển ý: Đây là chữ Hình thanh kiêm Hội ý. Cung là hành động cúi rạp người xuống, khom lưng tỏ ý kính trọng (cúc cung). Nghĩa khác là tự bản thân mình làm lấy (cung thân).", "Nghĩa Tiếng Việt_Xie": "thân thể, mình", "Hạng Tần Suất (Jun Da)": "2644.0", "Tần Suất % (Jun Da)": "98.7383481618", "GavinGrover_Once (Chiết tự trực tiếp)": "身 + 弓", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰身弓", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "弓", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "身", "Unihan_Simplified (Chữ Giản thể)": "躬", "Unihan_Traditional (Chữ Phồn thể)": "躬", "Pinyin_Xie": "gōng", "Âm Hán Việt_Xie": "cung", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Phó từ | 副词 | Chữ này làm động từ chỉ hành động cúi người hoặc làm phó từ với nghĩa tự bản thân làm việc gì. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Phó từ | 副词 | Bổ nghĩa cho động từ hoặc tính từ và luôn đứng TRƯỚC chúng — 都是, 很好. Không đứng sau như tiếng Việt và không bổ nghĩa cho danh từ.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('昼', '{"9000": "2645.0", "Chữ Trung Quốc": "昼", "Bộ thủ & thành phần_Xie": "Bộ thủ | 尸 | Số nét | 9 | nét | 尺 | xích | biểu hình | thước đo (đại diện dạng giản của 聿) | 旦 | đán | biểu nghĩa | bình minh, mặt trời | 昼 (phồn 晝) có cấu trúc phức tạp: gốc là 聿 + 日. Theo Wiktionary có hai thuyết: (1) hội ý — 聿 + 日 diễn tả ban ngày; (2) hình thanh — 聿 biểu âm, 日 biểu nghĩa. Dạng giản thể đơn giản hoá còn 尺 + 旦. Nghĩa rõ: ban ngày.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trú\": mặt trời (旦) mọc lên — đó là giờ trú ngụ của ánh sáng ban ngày. | Gương Hán-Việt | \"trú\" trong 昼夜 (trú dạ — ngày và đêm), 白昼 (bạch trú — ban ngày rõ ràng) | Mở khoá kiến thức | Biết 昼 mở khoá từ thời gian: 昼夜 (trú dạ, ngày đêm), 白昼 (bạch trú, ban ngày), 昼间 (trú gian, ban ngày).", "Tự nguyên_Xie": "Kim văn | Tiểu triện | Lục thư thông | Theo Wiktionary, 晝 (昼) ban đầu kết hợp 聿 và 日 (mặt trời). Hai thuyết: hội ý (ban ngày khi mặt trời lên) hoặc hình thanh (聿 biểu âm, 日 biểu nghĩa). Vai trò của 聿 trong giáp cốt văn chưa được giải thích rõ. Kim văn và tiểu triện đã ghi nhận. Nghĩa ''ban ngày'' ổn định từ văn bản cổ đại. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ban ngày", "Hạng Tần Suất (Jun Da)": "2645.0", "Tần Suất % (Jun Da)": "98.7399171215", "GavinGrover_Once (Chiết tự trực tiếp)": "尺 + 旦", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴尺旦", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "旦", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "尺", "Unihan_Simplified (Chữ Giản thể)": "昼", "Unihan_Traditional (Chữ Phồn thể)": "晝", "Pinyin_Xie": "zhòu", "Âm Hán Việt_Xie": "trú", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ thời gian ban ngày, thường đối lập với dạ là ban đêm. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('藻', '{"9000": "2646.0", "Chữ Trung Quốc": "藻", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 19 | nét | 艹 | thảo | biểu nghĩa | cỏ, thực vật | 澡 | táo | biểu âm | tắm gội | 藻 = 艹 (Thảo, biểu nghĩa: thực vật) + 澡 (Táo, biểu âm); chữ hình thanh. Bộ thảo 艹 chỉ loài thực vật; 澡 (táo) cho âm đọc zǎo. Chữ gốc là 薻.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tảo\": cỏ thủy sinh (艹) tắm mình (澡) dưới nước — 藻 là rong tảo, cũng chỉ văn phong hoa mỹ. | Gương Hán-Việt | Tảo trong \"hải tảo\" (tảo biển), \"từ tảo\" (văn chương hoa mỹ). | Mở khoá kiến thức | Biết 藻 (tảo) mở khóa: 海藻 (rong biển), 水藻 (rong nước), 藻类 (tảo, rong — thực vật bậc thấp).", "Tự nguyên_Xie": "Đại triện | Tiểu triện | 藻 (gốc 薻) là chữ hình thanh: 艹 (thảo) biểu nghĩa thực vật thủy sinh, 澡 (táo) biểu âm. Nghĩa gốc là rong rêu, tảo — thực vật mọc dưới nước. Mở rộng sang nghĩa bóng là văn chương hoa mỹ, lời lẽ trau chuốt (藻饰 — trang sức bằng ngôn từ đẹp). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "rong, rêu", "Hạng Tần Suất (Jun Da)": "2646.0", "Tần Suất % (Jun Da)": "98.7414855644", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 澡", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹澡", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "澡", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "藻", "Unihan_Traditional (Chữ Phồn thể)": "藻", "Pinyin_Xie": "zǎo", "Âm Hán Việt_Xie": "tảo", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ các loài thực vật thủy sinh hoặc chỉ sự hoa mỹ trong văn chương. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蛛', '{"9000": "2647.0", "Chữ Trung Quốc": "蛛", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 12 | nét | 虫 | trùng | biểu nghĩa | sâu, côn trùng | 朱 | chu | biểu âm | màu đỏ son | 蛛 = 虫 (Trùng, biểu nghĩa: côn trùng/sâu bọ) + 朱 (Chu, biểu âm); chữ hình thanh. Gốc là tượng hình con nhện; sau thêm 朱 để chỉ âm. Bộ trùng 虫 xác nhận đây là loài sâu bọ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chu\": sâu bọ (虫) đỏ (朱) giăng tơ — 蛛 là con nhện, nổi tiếng với mạng tơ. | Gương Hán-Việt | Chu trong \"chu sa\" (màu đỏ son — cùng chữ 朱), \"nhện chu\" không dùng; nhện Hán văn là 蜘蛛. | Mở khoá kiến thức | Biết 蛛 (chu) mở khóa: 蜘蛛 (nhện), 蛛网 (mạng nhện), 蛛丝马迹 (dấu vết mờ nhạt như tơ nhện).", "Tự nguyên_Xie": "Tiểu triện | 蛛 ban đầu là chữ tượng hình vẽ con nhện. Sau đó 朱 (chu, màu đỏ) được thêm vào làm thành phần biểu âm trong tiểu triện. 虫 (trùng) biểu nghĩa côn trùng. Chữ chỉ con nhện — loài chân đốt tám chân giăng tơ. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1493.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Trùng (143) Chu (095)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Trùng (số 143 - côn trùng/ 虫 /chỉ ý) ở bên trái chữ Chu (số 095 - màu đỏ/ 朱 /chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Chu chỉ âm, bộ Trùng chỉ ý. Thù là con nhện (thù võng - mạng nhện / chi thù - con nhện).", "Nghĩa Tiếng Việt_Xie": "(xem: tri chu 蜘蛛,鼅鼄)", "Hạng Tần Suất (Jun Da)": "2647.0", "Tần Suất % (Jun Da)": "98.7430529737", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 朱", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫朱", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "朱", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蛛", "Unihan_Traditional (Chữ Phồn thể)": "蛛", "Pinyin_Xie": "zhū", "Âm Hán Việt_Xie": "chu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ và thường chỉ xuất hiện trong từ ghép để chỉ loài nhện. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('褐', '{"9000": "2648.0", "Chữ Trung Quốc": "褐", "Bộ thủ & thành phần_Xie": "Bộ thủ | 衣 | Số nét | 14 | nét | 衤 | y | biểu nghĩa | quần áo, vải | 曷 | hạt | biểu âm | tại sao, sao lại | 褐 = 衤 (Y, biểu nghĩa: vải/quần áo) + 曷 (Hạt, biểu âm); chữ hình thanh. Bộ y 衤 chỉ vải vóc quần áo; 曷 (hạt) cho âm đọc hè.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hạt\": vải (衤) thô màu hạt (曷) — 褐 là màu nâu, màu của vải thô xưa, người nghèo mặc áo nâu. | Gương Hán-Việt | Hạt trong \"hạt sắc\" (màu nâu), \"bần hạt\" (người nghèo mặc áo vải thô). | Mở khoá kiến thức | Biết 褐 (hạt) mở khóa: 褐色 (màu nâu), 深褐 (nâu sẫm), 褐煤 (than nâu), 棕褐 (nâu vàng).", "Tự nguyên_Xie": "Tiểu triện | Wiktionary không cung cấp phân tích chi tiết cho 褐. Từ cấu trúc: 衤 (y, vải) biểu nghĩa, 曷 (hạt) biểu âm. Nghĩa gốc là vải thô dệt từ sợi thô (cỏ hoặc gai); màu nâu xám của vải thô ấy trở thành nghĩa chính. 褐色 (màu nâu) là ứng dụng phổ biến nhất ngày nay. chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "áo vải to", "Hạng Tần Suất (Jun Da)": "2648.0", "Tần Suất % (Jun Da)": "98.7446198662", "GavinGrover_Once (Chiết tự trực tiếp)": "衤 + 曷", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰衤曷", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "曷", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "衤", "Unihan_Simplified (Chữ Giản thể)": "褐", "Unihan_Traditional (Chữ Phồn thể)": "褐", "Pinyin_Xie": "hè", "Âm Hán Việt_Xie": "hạt", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Thường dùng làm tính từ chỉ màu sắc hoặc danh từ trong các từ cổ chỉ trang phục thô sơ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('颊', '{"9000": "2649.0", "Chữ Trung Quốc": "颊", "Bộ thủ & thành phần_Xie": "Bộ thủ | 頁 | Số nét | 12 | nét | 夹 | giáp | biểu âm | kẹp, kẹp giữa | 页 | hiệt | biểu nghĩa | đầu, mặt (bộ thủ chỉ phần đầu) | 颊 (phồn thể 頰) = 夹 (Giáp, biểu âm) + 页/頁 (Hiệt, biểu nghĩa: đầu/mặt); chữ hình thanh. Bộ hiệt 页 chỉ phần đầu/mặt người; 夹 (giáp) cho âm đọc jiá. Hình ảnh hai má kẹp hai bên mặt.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"giáp\": mặt (页) bị kẹp (夹) hai bên — 颊 là má, phần hai bên khuôn mặt. | Gương Hán-Việt | Giáp trong \"lưỡng giáp\" (hai má), \"giáp xa\" (xương hàm má). | Mở khoá kiến thức | Biết 颊 (giáp) mở khóa: 脸颊 (má mặt), 双颊 (hai má), 颊骨 (xương gò má).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 颊 (phồn thể 頰) là chữ hình thanh: 頁 (hiệt, phần đầu) biểu nghĩa, 夾 (giáp) biểu âm. Nghĩa là má — phần hai bên mặt người. 夹 (kẹp) có thể gợi hình ảnh hai má kẹp hai bên miệng. Chữ giản thể 颊 đơn giản hóa 頁 thành 页. chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "má", "Hạng Tần Suất (Jun Da)": "2649.0", "Tần Suất % (Jun Da)": "98.7461831413", "GavinGrover_Once (Chiết tự trực tiếp)": "夹 + 页", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰夹页", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "夹", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "页", "Unihan_Simplified (Chữ Giản thể)": "颊", "Unihan_Traditional (Chữ Phồn thể)": "頰", "Pinyin_Xie": "jiá", "Âm Hán Việt_Xie": "giáp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Làm danh từ chỉ bộ phận trên khuôn mặt, thường kết hợp với các tính từ miêu tả. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('奠', '{"9000": "2650.0", "Chữ Trung Quốc": "奠", "Bộ thủ & thành phần_Xie": "Bộ thủ | 大 | Số nét | 12 | nét | 酋 | tù | biểu nghĩa | bình rượu có nắp | 大 | đại | biểu hình | bệ/chiếu (do biến đổi từ 丌) | 奠 là chữ tượng hình phức hợp. Giáp cốt văn vẽ bình rượu (酉) đặt trên chiếu (一). Kim văn thêm hai nét trên bình tượng trưng rượu tràn. Phần dưới (bệ 丌) sau đổi thành 大 do lệ biến. Đây là hội ý: dâng rượu trên bệ trong nghi lễ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"điện\": bình rượu (酋) đặt lên bệ lớn (大) — nghi thức dâng cúng điện thờ. | Gương Hán-Việt | \"điện\" trong 奠定 (điện định — thiết lập nền tảng), 祭奠 (tế điện — tưởng niệm) | Mở khoá kiến thức | Biết 奠 mở khoá từ nghi lễ: 奠定 (điện định, đặt nền móng), 祭奠 (tế điện, tưởng niệm), 奠基 (điện cơ, đặt nền).", "Tự nguyên_Xie": "Giáp cốt văn | Kim văn | Đại triện | Tiểu triện | Theo Wiktionary, 奠 trong giáp cốt văn là tượng hình: bình rượu (酉) đặt trên tấm chiếu (一). Kim văn thêm hai nét trên bình tượng rượu trào ra thành 酋. Phần dưới ban đầu là 丌 (bệ), sau qua lệ biến thành 大. Nghĩa gốc: đặt xuống trong nghi thức, dâng cúng người chết, sau mở rộng thành thiết lập, định vị. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "định yên; tiến cúng", "Hạng Tần Suất (Jun Da)": "2650.0", "Tần Suất % (Jun Da)": "98.7477438324", "GavinGrover_Once (Chiết tự trực tiếp)": "酋 + 大", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱酋大", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "酋", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "大", "Unihan_Simplified (Chữ Giản thể)": "奠", "Unihan_Traditional (Chữ Phồn thể)": "奠", "Pinyin_Xie": "diàn", "Âm Hán Việt_Xie": "điện", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Làm động từ đứng trước tân ngữ để chỉ hành động cúng tế hoặc thiết lập nền móng. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('募', '{"9000": "2651.0", "Chữ Trung Quốc": "募", "Bộ thủ & thành phần_Xie": "Bộ thủ | 力 | Số nét | 12 | nét | 莫 | mạc | biểu âm | không, chớ | 力 | lực | biểu nghĩa | sức mạnh, cố gắng | 募 = 莫 (Mạc, biểu âm) + 力 (Lực, biểu nghĩa: sức lực, nỗ lực); chữ hình thanh. Bộ lực 力 gợi nỗ lực kêu gọi; 莫 (mạc) cho âm đọc mù.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mộ\": dùng lực (力) theo lệnh (莫) kêu gọi người — 募 là chiêu mộ, quyên góp, tập hợp người hay tiền. | Gương Hán-Việt | Mộ trong \"chiêu mộ\" (招募 — tuyển mộ), \"mộ quyên\" (quyên góp). | Mở khoá kiến thức | Biết 募 (mộ) mở khóa: 募捐 (quyên góp), 招募 (tuyển mộ), 募集 (thu hút, kêu gọi), 募兵 (chiêu binh).", "Tự nguyên_Xie": "Đại triện | Tiểu triện | 募 là chữ hình thanh: 力 (lực, sức mạnh) biểu nghĩa, 莫 (mạc) biểu âm. Nghĩa gốc là chiêu mộ, kêu gọi người dùng sức lực/tài năng tham gia; mở rộng sang quyên góp (募捐), tuyển dụng (招募). Hình ảnh dùng sức lực (力) để thu hút/chiêu tập người. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tuyển mộ", "Hạng Tần Suất (Jun Da)": "2651.0", "Tần Suất % (Jun Da)": "98.7493034899", "GavinGrover_Once (Chiết tự trực tiếp)": "莫 + 力", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱莫力", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "莫", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "力", "Unihan_Simplified (Chữ Giản thể)": "募", "Unihan_Traditional (Chữ Phồn thể)": "募", "Pinyin_Xie": "mù", "Âm Hán Việt_Xie": "mộ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Làm động từ mang tân ngữ phía sau để biểu thị việc kêu gọi quyên góp hoặc tuyển dụng. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('耽', '{"9000": "2652.0", "Chữ Trung Quốc": "耽", "Bộ thủ & thành phần_Xie": "Bộ thủ | 耳 | Số nét | 10 | nét | 耳 | nhĩ | biểu nghĩa | tai | 冘 | dâm | biểu âm | cho âm dâm/đam | 耽 = 耳 (Nhĩ, biểu nghĩa: tai) + 冘 (Dâm, biểu âm); chữ hình thanh. Wiktionary ghi: {{Han compound|耳|冘|ls=psc|c1=s|c2=p}}. Bộ nhĩ chỉ tai — nghe đắm say; 冘 cho âm dān (gần đam). Mê mải lắng nghe đến quên thời gian.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đam\": tai (耳-Nhĩ) mê đắm (冘-Dâm) — tai nghe mê say không rứt ra được = đam mê, trì hoãn vì mải mê. Đam = mải. | Gương Hán-Việt | đam trong ''đam mê'' — tiếng Việt mượn thẳng nghĩa này; 耽 chính là gốc của ''đam mê'' | Mở khoá kiến thức | Biết 耽 mở khoá: 耽误 (đam ngộ – trì hoãn, bỏ lỡ), 耽搁 (đam các – trì hoãn), 耽于 (đam ư – đắm mình vào).", "Tự nguyên_Xie": "耽 là chữ hình thanh: 耳 (nhĩ – tai) biểu nghĩa, 冘 (dâm) biểu âm. Nghĩa gốc gắn với tai: say mê nghe đến quên thời gian (耽溺, 耽误). Wiktionary xác nhận cấu trúc psc. Nghĩa ''trì hoãn, lãng phí thời gian'' (耽误) phát triển từ nghĩa ''đắm đuối quá mức''. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mê mải, đắm đuối", "Hạng Tần Suất (Jun Da)": "2652.0", "Tần Suất % (Jun Da)": "98.7508564292", "GavinGrover_Once (Chiết tự trực tiếp)": "耳 + 冘", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰耳冘", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "冘", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "耳", "Unihan_Simplified (Chữ Giản thể)": "耽", "Unihan_Traditional (Chữ Phồn thể)": "耽", "Pinyin_Xie": "dān", "Âm Hán Việt_Xie": "đam", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ liên kết với các từ khác để chỉ sự ham mê hoặc làm chậm trễ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蹈', '{"9000": "2653.0", "Chữ Trung Quốc": "蹈", "Bộ thủ & thành phần_Xie": "Bộ thủ | 足 | Số nét | 17 | nét | 𧾷 | biểu nghĩa | bộ túc (chân) | 舀 | yểu | biểu âm | múc | 蹈 = 足 (bộ túc, biểu nghĩa: chân) + 舀 (Yểu, biểu âm); chữ hình thanh. Bộ túc chỉ hành động dùng chân, 舀 cho âm gần dǎo.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đạo\": chân (足) giậm theo nhịp múc (舀) — nhảy đạo, múa dân gian giậm chân theo nhịp trống. | Gương Hán-Việt | \"đạo\" trong 舞蹈 (vũ đạo — nhảy múa), 循規蹈矩 (tuần quy đạo củ — theo khuôn phép) | Mở khoá kiến thức | Biết 蹈 mở khoá thành ngữ: 舞蹈 (vũ đạo), 赴汤蹈火 (lao vào nguy hiểm), 重蹈覆辙 (lặp lại sai lầm cũ).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 蹈 là chữ hình thanh: 足 (chân) biểu nghĩa, 舀 biểu âm. Tiểu triện đã có dạng. Nghĩa gốc là giẫm, bước lên. Mở rộng sang nhảy múa (手舞足蹈), tuân thủ (循規蹈矩), liều lĩnh (赴湯蹈火). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "giẫm, xéo", "Hạng Tần Suất (Jun Da)": "2653.0", "Tần Suất % (Jun Da)": "98.7524088518", "GavinGrover_Once (Chiết tự trực tiếp)": "⻊ + 舀", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰⻊舀", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "舀", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⻊", "Unihan_Simplified (Chữ Giản thể)": "蹈", "Unihan_Traditional (Chữ Phồn thể)": "蹈", "Pinyin_Xie": "dǎo", "Âm Hán Việt_Xie": "đạo", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Làm động từ thường kết hợp với các từ khác để chỉ hành động giẫm lên hoặc nhảy múa. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('陋', '{"9000": "2654.0", "Chữ Trung Quốc": "陋", "Bộ thủ & thành phần_Xie": "Bộ thủ | 阜 | Số nét | 8 | nét | 阝 | phụ | biểu nghĩa | gò đất, bậc thềm | 𫠥 | biểu âm | thành phần biểu âm phức hợp chứa 丙 | 陋 = 阝(Phụ, biểu nghĩa: gò đất/khu vực) + thành phần biểu âm phức hợp. Wiktionary không cung cấp phân tích ls rõ ràng. Dựa trên cấu trúc, bộ 阜 (gò) gợi ý không gian hẹp, bị bao quanh — từ đó nghĩa là chật hẹp, tầm thường. Chưa có nguồn học thuật đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lậu\": gò đất (阝) chật hẹp — căn phòng lậu là nơi tối tăm, chật chội không ai muốn ở. | Gương Hán-Việt | \"lậu\" trong 简陋 (giản lậu — đơn sơ thô sơ), 丑陋 (xú lậu — xấu xí), 陋室 (lậu thất — gian phòng tồi tàn) | Mở khoá kiến thức | Biết 陋 mở khoá từ đánh giá chất lượng: 简陋 (giản lậu), 丑陋 (xú lậu), 孤陋寡闻 (cô lậu quả văn, thiếu hiểu biết).", "Tự nguyên_Xie": "Đại triện | Tiểu triện | Wiktionary không có phân tích hình thanh/hội ý đầy đủ cho 陋. Đại triện và tiểu triện có dạng ghi chép. Dựa trên cấu trúc, bộ 阜 (gò đất) gợi ý không gian hẹp — từ đó nghĩa là chật hẹp, tầm thường. Nghĩa chính là hẹp, xấu xí, thô lậu, kiến thức nông cạn. Chưa có nguồn học thuật đầy đủ. | Theo Wiktionary · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "hẹp, nhỏ; xấu xí", "Hạng Tần Suất (Jun Da)": "2654.0", "Tần Suất % (Jun Da)": "98.7539566233", "GavinGrover_Once (Chiết tự trực tiếp)": "阝 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰阝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "陋", "Unihan_Traditional (Chữ Phồn thể)": "陋", "Pinyin_Xie": "lòu", "Âm Hán Việt_Xie": "lậu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Làm tính từ bổ nghĩa cho danh từ hoặc làm vị ngữ để miêu tả sự đơn sơ, xấu xí. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('侣', '{"9000": "2655.0", "Chữ Trung Quốc": "侣", "Bộ thủ & thành phần_Xie": "Bộ thủ | 人 | Số nét | 8 | nét | 亻 | nhân | biểu nghĩa | người | 吕 | lữ | biểu âm | họ Lữ, hai vòng nối | 侣 = 亻(Nhân, biểu nghĩa: người) + 吕 (Lữ, biểu âm); chữ hình thanh. Dạng phồn thể 侶. Bộ nhân chỉ người, 吕 cho âm lǚ. Nghĩa là bạn đồng hành.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lữ\": người (亻) cùng họ Lữ (吕) đi bên cạnh — hai vòng 吕 như hai người kề vai sát cánh. | Gương Hán-Việt | \"lữ\" trong 伴侣 (bạn lữ — bạn đời), 情侣 (tình lữ — cặp đôi) | Mở khoá kiến thức | Biết 侣 mở khoá từ quan hệ: 伴侣 (bạn lữ, bạn đời), 情侣 (tình lữ, người yêu), 僧侣 (tăng lữ, tăng sĩ).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary (Digital Shinjigen 2017), 侶 là chữ hình thanh: 人 (bộ 亻) biểu nghĩa, 呂 biểu âm. Tiểu triện đã có dạng. Chữ mang nghĩa người bạn đồng hành, đặc biệt trong bối cảnh tu hành hay lữ hành. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bạn bè", "Hạng Tần Suất (Jun Da)": "2655.0", "Tần Suất % (Jun Da)": "98.755503878", "GavinGrover_Once (Chiết tự trực tiếp)": "亻 + 吕", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰亻吕", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "吕", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "亻", "Unihan_Simplified (Chữ Giản thể)": "侣", "Unihan_Traditional (Chữ Phồn thể)": "侶", "Pinyin_Xie": "lǚ", "Âm Hán Việt_Xie": "lữ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Làm danh từ chỉ người đồng hành, thường xuất hiện trong các từ ghép chỉ mối quan hệ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('魅', '{"9000": "2656.0", "Chữ Trung Quốc": "魅", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鬼 | Số nét | 14 | nét | 鬼 | quỷ | biểu nghĩa | ma quỷ | 未 | vị | biểu âm | chưa — cho âm vị/mị | 魅 = 鬼 (Quỷ, biểu nghĩa: ma) + 未 (Vị, biểu âm); chữ hình thanh. Wiktionary ghi: {{Han compound|未|鬼|c1=p|c2=s|ls=psc|t2=spirit}}. Bộ quỷ chỉ loại thực thể thuộc cõi âm; 未 cho âm mèi (gần mị). Loài ma đặc biệt hấp dẫn, mê hoặc người.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mị\": ma quỷ (鬼-Quỷ) chưa thành hình (未-Vị) — yêu ma mờ ảo, mị hoặc người ta. Mị = quyến rũ huyền bí. | Gương Hán-Việt | mị trong ''mị dân, mị hoặc'' — tiếng Việt dùng mị theo nghĩa gốc; 魅 trong 魅力 là sức hút ma mị | Mở khoá kiến thức | Biết 魅 mở khoá: 魅力 (mị lực – sức hấp dẫn), 魑魅 (ly mị – yêu ma rừng núi), 魅惑 (mị hoặc – mê hoặc).", "Tự nguyên_Xie": "魅 là chữ hình thanh: 鬼 (quỷ – ma) biểu nghĩa, 未 (vị) biểu âm. Wiktionary ghi: ''a kind of legendary evil spirit'' — loài yêu ma trong truyền thuyết. Từ nghĩa ''ma mị'' phát triển thành ''sức hấp dẫn ma lực'' trong tiếng Trung hiện đại: 魅力 (mị lực – sức hút, sức hấp dẫn). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ma quỷ", "Hạng Tần Suất (Jun Da)": "2656.0", "Tần Suất % (Jun Da)": "98.7570495823", "GavinGrover_Once (Chiết tự trực tiếp)": "鬼 + 未", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴鬼未", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "未", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鬼", "Unihan_Simplified (Chữ Giản thể)": "魅", "Unihan_Traditional (Chữ Phồn thể)": "魅", "Pinyin_Xie": "mèi", "Âm Hán Việt_Xie": "mị", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Làm danh từ chỉ loài yêu quái hoặc sức hấp dẫn đặc biệt, thường dùng trong từ ghép. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('岚', '{"9000": "2657.0", "Chữ Trung Quốc": "岚", "Bộ thủ & thành phần_Xie": "Bộ thủ | 山 | Số nét | 7 | nét | 山 | sơn | biểu nghĩa | núi | 风 | phong | biểu nghĩa | gió | 岚 (phồn thể 嵐) = 山 (Sơn: núi) + 风 (Phong: gió); chữ hội ý từ cấu trúc (Wiktionary không có phân tích chi tiết). Bộ sơn 山 và phong 风 kết hợp tạo hình ảnh sương mù trên núi cuộn theo gió.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lam\": gió (风) trên núi (山) tạo sương lam — 岚 là khí núi, sương mù huyền ảo trên đỉnh núi, màu lam xanh mờ ảo. | Gương Hán-Việt | Lam trong \"sơn lam\" (khí núi rừng), \"lam chướng\" (sương lam độc hại trong rừng núi nhiệt đới). | Mở khoá kiến thức | Biết 岚 (lam) mở khóa: 山岚 (sương núi), 岚气 (khí núi), 云岚 (mây sương), tên địa danh như Phú Lam, Sơn Lam.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 岚 (phồn thể 嵐) là chữ giản thể, đơn giản hóa phần 風 thành 风. Từ cấu trúc: 山 (sơn, núi) + 风 (phong, gió), hội ý chỉ làn sương mù khói mây bay qua núi theo gió. Nghĩa là khí núi, sương núi — làn hơi ẩm mờ ảo trên đỉnh núi, đặc biệt sáng sớm. chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "khí núi bốc lên", "Hạng Tần Suất (Jun Da)": "2657.0", "Tần Suất % (Jun Da)": "98.7585937363", "GavinGrover_Once (Chiết tự trực tiếp)": "山 + 风", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱山风", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "风", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "山", "Unihan_Simplified (Chữ Giản thể)": "岚", "Unihan_Traditional (Chữ Phồn thể)": "嵐", "Pinyin_Xie": "lán", "Âm Hán Việt_Xie": "lam", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Làm danh từ chỉ hơi nước hoặc sương mù bao quanh núi, thường dùng trong văn chương. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('侄', '{"9000": "2658.0", "Chữ Trung Quốc": "侄", "Bộ thủ & thành phần_Xie": "Bộ thủ | 人 | Số nét | 8 | nét | 亻 | nhân | biểu nghĩa | người | 至 | chí | biểu âm | đến, tận cùng | 侄 = 亻(Nhân, biểu nghĩa: người) + 至 (Chí, biểu âm); chữ hình thanh. Bộ nhân chỉ người, 至 cho âm zhí. Dạng truyền thống là 姪 (bộ 女).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"điệt\": người (亻) đến (至) sau — cháu (điệt) là người trong gia đình thế hệ sau bác/cô/chú. | Gương Hán-Việt | \"điệt\" trong 侄子 (điệt tử — cháu trai), 侄女 (điệt nữ — cháu gái) | Mở khoá kiến thức | Biết 侄 mở khoá từ gia đình: 侄子 (điệt tử, cháu trai), 侄女 (điệt nữ, cháu gái), 外侄 (ngoại điệt, cháu bên ngoại).", "Tự nguyên_Xie": "Giáp cốt văn | Kim văn | Tiểu triện | Lục thư thông | Theo Wiktionary, 侄 là chữ hình thanh: 人 (bộ 亻) biểu nghĩa, 至 biểu âm. Giáp cốt văn, kim văn, tiểu triện và Lục thư thông đều có dạng ghi nhận. Đây là biến thể của 姪 (bộ 女 — cháu gái), còn 侄 bộ 人 dùng cho cháu trai. Tiếng Hán hiện đại 侄 dùng chung. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bền", "Hạng Tần Suất (Jun Da)": "2658.0", "Tần Suất % (Jun Da)": "98.7601373735", "GavinGrover_Once (Chiết tự trực tiếp)": "亻 + 至", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰亻至", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "至", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "亻", "Unihan_Simplified (Chữ Giản thể)": "侄", "Unihan_Traditional (Chữ Phồn thể)": "侄", "Pinyin_Xie": "zhí", "Âm Hán Việt_Xie": "điệt", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Làm danh từ chỉ quan hệ họ hàng, thường kết hợp với các từ chỉ người để xưng hô. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('虐', '{"9000": "2659.0", "Chữ Trung Quốc": "虐", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虍 | Số nét | 9 | nét | 虍 | hô | biểu nghĩa | đầu hổ | 爪 | biểu nghĩa | móng vuốt | 虐 là chữ hội ý. Theo Wiktionary, giáp cốt văn là hội ý 虎 (hổ) + 人 (người) — hình ảnh hổ sắp ăn người. Dạng hiện đại còn lại bộ 虍 (đầu hổ) và nét tượng trưng móng vuốt.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ngược\": đầu hổ (虍) với vuốt nanh — ngược đãi là đối xử như hổ với con mồi. | Gương Hán-Việt | \"ngược\" trong 虐待 (ngược đãi — đối xử tàn ác), 暴虐 (bạo ngược — hung bạo) | Mở khoá kiến thức | Biết 虐 mở khoá từ nhân quyền: 虐待 (ngược đãi), 暴虐 (bạo ngược), 自虐 (tự ngược — tự hành xác).", "Tự nguyên_Xie": "Giáp cốt văn | Kim văn | Đại triện | Tiểu triện | Theo Wiktionary, 虐 trong giáp cốt văn là chữ hội ý: hổ (虎) và người (人) — hình tượng hổ sắp ăn thịt người, ý nghĩa hung tàn, bạo ngược. Giáp cốt văn, kim văn, đại triện và tiểu triện đều có dạng ghi nhận. Nghĩa mở rộng từ hung ác sang áp bức, ngược đãi. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ác nghiệt, tai ngược", "Hạng Tần Suất (Jun Da)": "2659.0", "Tần Suất % (Jun Da)": "98.7616768764", "GavinGrover_Once (Chiết tự trực tiếp)": "虍 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴虍", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "虐", "Unihan_Traditional (Chữ Phồn thể)": "虐", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "ngược", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Chữ này thường làm tính từ bổ nghĩa cho danh từ hoặc kết hợp với động từ khác để chỉ hành vi tàn nhẫn. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('堕', '{"9000": "2660.0", "Chữ Trung Quốc": "堕", "Bộ thủ & thành phần_Xie": "Bộ thủ | 土 | Số nét | 11 | nét | 陏 | tuỳ | biểu âm | theo, tùy | 土 | thổ | biểu nghĩa | đất | 堕 = 陏 (Tuỳ, biểu âm) + 土 (Thổ, biểu nghĩa: đất); chữ hình thanh. Giản thể của 墮 (đoạ). Đất (土) rơi xuống — gợi hình ảnh sụp đổ, sa ngã. Chưa có nguồn học thuật đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đoạ\": đất (土) trôi theo (陏) — sa đoạ như đất lở, rơi thẳng xuống không cưỡng được. | Gương Hán-Việt | \"đoạ\" trong 堕落 (đoạ lạc — suy đồi, sa ngã), 堕胎 (đoạ thai — phá thai) | Mở khoá kiến thức | Biết 堕 mở khoá từ đạo đức: 堕落 (đoạ lạc, sa ngã), 堕胎 (đoạ thai, phá thai), 堕入 (đoạ nhập, lao vào).", "Tự nguyên_Xie": "堕 là dạng giản thể của 墮 (đoạ). Wiktionary không có phân tích đầy đủ cho dạng giản thể. Theo dạng phồn thể, 墮 là chữ hình thanh với bộ 土 (đất) biểu nghĩa. Nghĩa gốc là rơi xuống, đổ nát. Từ đó mở rộng thành sa ngã (堕落), suy đồi về đạo đức. Chưa có nguồn học thuật đầy đủ. | Theo Wiktionary · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "rơi xuống, đổ; đổ nát", "Hạng Tần Suất (Jun Da)": "2660.0", "Tần Suất % (Jun Da)": "98.7632153457", "GavinGrover_Once (Chiết tự trực tiếp)": "陏 + 土", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱陏土", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "陏", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "土", "Unihan_Simplified (Chữ Giản thể)": "堕", "Unihan_Traditional (Chữ Phồn thể)": "墮", "Pinyin_Xie": "duò", "Âm Hán Việt_Xie": "đoạ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước danh từ chỉ nơi chốn hoặc trạng thái để biểu thị sự rơi rụng, sa ngã. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('陛', '{"9000": "2661.0", "Chữ Trung Quốc": "陛", "Bộ thủ & thành phần_Xie": "Bộ thủ | 阜 | Số nét | 9 | nét | 阝 | phụ | biểu nghĩa | đồi, mô đất (bộ phụ) | 坒 | bệ | biểu âm | nối tiếp nhau (bậc thang) | 陛 = 阝/阜 (Phụ, biểu nghĩa: mô đất/đồi dốc) + 坒 (Bệ, biểu âm); chữ hình thanh. Bộ phụ 阝 (biến thể của 阜) gợi bậc đất cao; 坒 cho âm đọc bì.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bệ\": bậc thềm đất cao (阝) — 陛 là bậc điện rồng; 陛下 (bệ hạ) là cách xưng hô trang trọng với vua. | Gương Hán-Việt | Bệ trong \"bệ hạ\" (陛下 — tâu vua), \"ngọc bệ\" (thềm ngọc, điện rồng). | Mở khoá kiến thức | Biết 陛 (bệ) mở khóa: 陛下 (bệ hạ — kính xưng vua), 御陛 (bậc thềm điện), 天陛 (thềm trời — chỉ cung điện).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 陛 là chữ hình thanh: 阜 (phụ, mô đất/bậc) biểu nghĩa, 坒 (bệ) biểu âm. Nghĩa gốc là bậc thang dẫn lên điện rồng, thềm cao của cung đình; sau thành kính ngữ chỉ vua (陛下 — bệ hạ, người ở dưới bậc thềm — cách gọi khiêm tốn của bề tôi tâu vua). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sân hè", "Hạng Tần Suất (Jun Da)": "2661.0", "Tần Suất % (Jun Da)": "98.7647532983", "GavinGrover_Once (Chiết tự trực tiếp)": "阝 + 坒", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰阝坒", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "坒", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "阝", "Unihan_Simplified (Chữ Giản thể)": "陛", "Unihan_Traditional (Chữ Phồn thể)": "陛", "Pinyin_Xie": "bì", "Âm Hán Việt_Xie": "bệ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng trong các từ ghép tôn xưng hoàng đế hoặc chỉ bậc thềm nơi cung điện. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('莹', '{"9000": "2662.0", "Chữ Trung Quốc": "莹", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 10 | nét | 艹 | thảo | biểu nghĩa | cỏ (bộ thủ phần trên) | 玉 | ngọc | biểu nghĩa | ngọc, đá quý | 莹 (phồn thể 瑩) = 𫇦 (艹 + 冖) + 玉 (Ngọc, biểu nghĩa: đá quý); chữ hình thanh từ dạng giản thể. Bộ ngọc 玉 cho biết liên quan đến độ sáng trong suốt của ngọc; phần trên cho âm. Nghĩa là trong suốt, long lanh như ngọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"oánh\": ngọc (玉) long lanh sáng — 莹 là trong suốt, rực sáng như ngọc bích; 晶莹 là long lanh trong vắt. | Gương Hán-Việt | Oánh trong \"tinh oánh\" (晶莹 — long lanh trong suốt), \"oánh bạch\" (trắng trong như ngọc). | Mở khoá kiến thức | Biết 莹 (oánh) mở khóa: 晶莹 (long lanh, trong suốt), 莹白 (trắng trong như ngọc), 玲莹 (nhỏ xinh long lanh).", "Tự nguyên_Xie": "Tiểu triện | 莹 (phồn thể 瑩) là chữ giản thể, đơn giản hóa theo phương án 1956. Phồn thể 瑩 có 玉 (ngọc) biểu nghĩa, cho thấy chữ liên quan đến vẻ sáng trong của ngọc bích. Nghĩa là long lanh, trong sáng, sáng rực — như ánh sáng phản chiếu từ ngọc. Wiktionary không có phân tích cấu trúc chi tiết. chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "trong suốt", "Hạng Tần Suất (Jun Da)": "2662.0", "Tần Suất % (Jun Da)": "98.7662897005", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "莹", "Unihan_Traditional (Chữ Phồn thể)": "瑩", "Pinyin_Xie": "yíng", "Âm Hán Việt_Xie": "oánh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường làm tính từ đứng trước danh từ để miêu tả vẻ trong sáng, lấp lánh của ngọc hay nước. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('荫', '{"9000": "2663.0", "Chữ Trung Quốc": "荫", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 9 | nét | 艹 | thảo | biểu nghĩa | cỏ cây | 阴 | âm | biểu âm | âm, bóng tối, âm khí | 荫 = 艹 (Thảo, biểu nghĩa: cây cối) + 阴 (Âm, biểu âm kiêm biểu nghĩa: bóng mát); chữ hình thanh kiêm hội ý. Bộ thảo 艹 chỉ cây cối; 阴 vừa cho âm vừa gợi bóng mát che phủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ấm\": cây (艹) tạo bóng âm mát (阴) — 荫 là bóng cây che mát, cũng là sự che chở của bề trên (ấm phong, ấm tử). | Gương Hán-Việt | Ấm trong \"ấm phong\" (荫封 — con cháu được phong tước nhờ công cha ông), \"thụ ấm\" (được bảo hộ, nhờ bóng che). | Mở khoá kiến thức | Biết 荫 (ấm) mở khóa: 树荫 (bóng cây), 荫庇 (che chở, bảo hộ), 林荫道 (đại lộ có cây bóng mát).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 荫 là chữ hình thanh kiêm hội ý: 艹 (thảo, cây) biểu nghĩa, 阴 (âm) vừa biểu âm vừa biểu nghĩa bóng mát. Nghĩa gốc là bóng cây che phủ; mở rộng sang nghĩa được che chở nhờ thế lực người khác (荫庇 — được bóng che, được bảo hộ). Trong chế độ phong kiến, con cái quan lại được hưởng 荫庇 (ấm phong). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bóng râm; che chở", "Hạng Tần Suất (Jun Da)": "2663.0", "Tần Suất % (Jun Da)": "98.7678255859", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 阴", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹阴", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "阴", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "荫", "Unihan_Traditional (Chữ Phồn thể)": "廕", "Pinyin_Xie": "yīn", "Âm Hán Việt_Xie": "âm, ấm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường làm danh từ chỉ bóng mát của cây cối hoặc làm động từ mang tân ngữ với nghĩa che chở. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('狡', '{"9000": "2664.0", "Chữ Trung Quốc": "狡", "Bộ thủ & thành phần_Xie": "Bộ thủ | 犬 | Số nét | 9 | nét | 犭 | khuyển | biểu nghĩa | loài chó/dã thú | 交 | giao | biểu âm | giao, qua lại (gần âm jiǎo) | 狡 = 犭 (Khuyển, biểu nghĩa: loài dã thú) + 交 (Giao, biểu âm); chữ hình thanh. Loài thú khôn ranh, gốc nghĩa ''xảo quyệt, gian xảo''.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"giảo\": 犭 (dã thú) + 交 (Giao) — con thú đi đường vòng để lừa, đúng nghĩa ''xảo quyệt, gian ngoan'' trong 狡猾. | Gương Hán-Việt | ''giảo'' trong ''giảo quyệt'', ''gian giảo'' | Mở khoá kiến thức | Nắm 狡 mở khoá từ HSK 5: 狡猾.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 狡 là hình thanh: 犭/犬 (loài chó/dã thú, biểu nghĩa) + 交 (Giao, biểu âm). Anchor Wiktionary không có thuyết giải chi tiết về cấu tạo nhưng dấu chỉ rõ là hình thanh. Nghĩa ''xảo quyệt, gian ngoan'' (狡猾, 狡诈) phản ánh hình ảnh con thú khôn ranh. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "xảo quyệt", "Hạng Tần Suất (Jun Da)": "2664.0", "Tần Suất % (Jun Da)": "98.7693609546", "GavinGrover_Once (Chiết tự trực tiếp)": "犭 + 交", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰犭交", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "交", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "犭", "Unihan_Simplified (Chữ Giản thể)": "狡", "Unihan_Traditional (Chữ Phồn thể)": "狡", "Pinyin_Xie": "jiǎo", "Âm Hán Việt_Xie": "giảo", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường làm tính từ đứng trước danh từ hoặc làm vị ngữ để miêu tả tính cách gian trá, xảo quyệt. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('阀', '{"9000": "2665.0", "Chữ Trung Quốc": "阀", "Bộ thủ & thành phần_Xie": "Bộ thủ | 門 | Số nét | 9 | nét | 门 | môn | biểu nghĩa | cửa, cổng | 伐 | phiệt | biểu âm | đánh, chặt | 阀 = 门 (Môn, biểu nghĩa: cửa/cổng) + 伐 (Phiệt, biểu âm); chữ hình thanh. Bộ môn 门 gợi hình ảnh cổng/van; 伐 (phiệt) cho âm đọc fá.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phiệt\": cổng lớn (门) ghi công (伐) của gia tộc — 阀 là phiệt tộc quyền lực, cũng là van (阀门) điều khiển. | Gương Hán-Việt | Phiệt trong \"quân phiệt\" (军阀 — sứ quân, lãnh chúa quân sự), \"tài phiệt\" (tập đoàn tài phiệt). | Mở khoá kiến thức | Biết 阀 (phiệt) mở khóa: 军阀 (quân phiệt), 财阀 (tài phiệt), 阀门 (van/cửa van), 门阀 (môn phiệt — danh gia vọng tộc).", "Tự nguyên_Xie": "Tiểu triện | 阀 là chữ hình thanh: 門 (môn, cửa) biểu nghĩa, 伐 (phiệt) biểu âm. Nghĩa gốc là cổng nhà có ghi công tích của gia đình (danh gia vọng tộc có 阀阅 — bảng ghi công trạng bên cổng); mở rộng sang nghĩa tập đoàn quyền lực (军阀 — quân phiệt), van kỹ thuật (阀门 — van điều tiết dòng chảy). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tờ ghi công trạng", "Hạng Tần Suất (Jun Da)": "2665.0", "Tần Suất % (Jun Da)": "98.7708958064", "GavinGrover_Once (Chiết tự trực tiếp)": "门 + 伐", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿵ (Bao quanh phía trên)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴门伐", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "伐", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "门", "Unihan_Simplified (Chữ Giản thể)": "阀", "Unihan_Traditional (Chữ Phồn thể)": "閥", "Pinyin_Xie": "fá", "Âm Hán Việt_Xie": "phiệt", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng sau các danh từ khác để chỉ tập đoàn thế lực hoặc các loại van kiểm soát chất lưu. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('绞', '{"9000": "2666.0", "Chữ Trung Quốc": "绞", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 9 | nét | 纟 | mịch | biểu nghĩa | sợi, tơ lụa | 交 | giao | biểu âm | giao nhau, chéo nhau | 绞 = 纟 (Mịch, biểu nghĩa: sợi/tơ) + 交 (Giao, biểu âm); chữ hình thanh. Bộ mịch 纟 chỉ dây sợi; 交 (giao) cho âm đọc jiǎo, đồng thời gợi hình ảnh các sợi chéo nhau/bện vào nhau.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"giảo\": sợi (纟) bện giao nhau (交) — 绞 là xoắn chặt, thắt cổ, đau thắt ruột gan. | Gương Hán-Việt | Giảo trong \"giảo hình\" (绞刑 — tử hình bằng treo cổ), \"giảo sách\" (xiết/vặn dây). | Mở khoá kiến thức | Biết 绞 (giảo) mở khóa: 绞刑 (tử hình bằng cổ), 绞痛 (đau thắt), 绞肉 (xay thịt), 绞尽脑汁 (vắt óc suy nghĩ).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 绞 là chữ hình thanh: 糸 (mịch, sợi/tơ) biểu nghĩa, 交 (giao) biểu âm. Nghĩa gốc là bện sợi, vặn xoắn dây; mở rộng sang thắt cổ (绞刑 — tử hình bằng treo cổ), siết chặt, đau thắt lòng. Hình ảnh các sợi chéo nhau bện lại. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "vặn, xoắn; treo cổ", "Hạng Tần Suất (Jun Da)": "2666.0", "Tần Suất % (Jun Da)": "98.7724270408", "GavinGrover_Once (Chiết tự trực tiếp)": "纟 + 交", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰纟交", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "交", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "纟", "Unihan_Simplified (Chữ Giản thể)": "绞", "Unihan_Traditional (Chữ Phồn thể)": "絞", "Pinyin_Xie": "jiǎo", "Âm Hán Việt_Xie": "giảo", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước danh từ chỉ vật bị vặn xoắn hoặc phương thức hình phạt. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('膏', '{"9000": "2667.0", "Chữ Trung Quốc": "膏", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 14 | nét | 高 | cao | biểu âm | gợi âm gāo | 月 | nguyệt | biểu nghĩa | biến thể của 肉 — mỡ, chất nhờn | 膏 = 高 (Cao, biểu âm) + 月 (biến thể của 肉: mỡ); chữ hình thanh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cao\": chữ 高 đứng trên thịt 月 — mỡ tinh tuý đặc sánh, đó là ''cao'' (cao thuốc, mỡ). | Gương Hán-Việt | cao trong \"cao thuốc\" 膏藥, \"nha cao\" 牙膏 | Mở khoá kiến thức | Biết 膏 mở khoá nhóm từ về kem/mỡ: 牙膏, 药膏, 膏药.", "Tự nguyên_Xie": "Giáp cốt văn | Tiểu triện | Wiktionary chú 膏 = 高 + 肉 (ls=psc, c1=p c2=s, t2=''meat'') — 高 cho âm gāo, 肉 (cơ thể, mỡ) cho nghĩa ''chất nhờn từ cơ thể''. Nghĩa gốc ''mỡ động vật'', mở rộng thành ''cao thuốc, dầu mỡ, kem''. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "dầu, mỡ, cao (thuốc)", "Hạng Tần Suất (Jun Da)": "2667.0", "Tần Suất % (Jun Da)": "98.7739556912", "GavinGrover_Once (Chiết tự trực tiếp)": "No glyph available + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "膏", "Unihan_Traditional (Chữ Phồn thể)": "膏", "Pinyin_Xie": "gāo", "Âm Hán Việt_Xie": "cao, cáo", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Thường làm danh từ chỉ các chất dạng đặc sệt hoặc làm tính từ bổ nghĩa cho đất đai màu mỡ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('垮', '{"9000": "2668.0", "Chữ Trung Quốc": "垮", "Bộ thủ & thành phần_Xie": "Bộ thủ | 土 | Số nét | 9 | nét | 土 | thổ | biểu nghĩa | đất | 夸 | khoa | biểu âm | khoác lác, khoa trương | 垮 = 土 (Thổ, biểu nghĩa: đất/công trình) + 夸 (Khoa, biểu âm); chữ hình thanh. Bộ thổ 土 gợi công trình đất/xây dựng sụp đổ; 夸 (khoa) cho âm đọc kuǎ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khoả\": đất (土) khoa trương (夸) rồi sụp — 垮 là đổ sập, sụp đổ hoàn toàn, tan tành. | Gương Hán-Việt | Khoả ít dùng trong tiếng Việt; nghĩa 垮 thường dùng trong từ ghép như 垮台 (sụp đổ), 打垮 (đánh bại hoàn toàn). | Mở khoá kiến thức | Biết 垮 (khoả) mở khóa: 垮台 (sụp đổ, mất chức), 打垮 (đánh tan), 拖垮 (kéo đến kiệt sức), 累垮 (mệt mỏi suy sụp).", "Tự nguyên_Xie": "Wiktionary không cung cấp phân tích chi tiết về cấu trúc của 垮. Từ cấu trúc: 土 (thổ) biểu nghĩa đất/công trình, 夸 (khoa) biểu âm. Nghĩa là sụp đổ, đổ vỡ (công trình), thất bại hoàn toàn, suy sụp (sức khỏe). Chữ tương đối muộn. chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "vỡ; đổ vỡ; sập; sụp đổ; suy sụp", "Hạng Tần Suất (Jun Da)": "2668.0", "Tần Suất % (Jun Da)": "98.7754843416", "GavinGrover_Once (Chiết tự trực tiếp)": "土 + 夸", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰土夸", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "夸", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "土", "Unihan_Simplified (Chữ Giản thể)": "垮", "Unihan_Traditional (Chữ Phồn thể)": "垮", "Pinyin_Xie": "kuǎ", "Âm Hán Việt_Xie": "khoa", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng sau động từ khác làm bổ ngữ kết quả hoặc làm vị ngữ chính trong câu. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | kuǎ | / | sụp đổ | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Thiên tai", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('茎', '{"9000": "2669.0", "Chữ Trung Quốc": "茎", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 8 | nét | 艹 | thảo | biểu nghĩa | cỏ, thực vật | 𢀖 | kinh | biểu âm | âm kinh | 茎 = 艹(Thảo, biểu nghĩa: cỏ/thực vật) + 𢀖 (Kinh, biểu âm); chữ hình thanh. Dạng phồn thể là 莖. Bộ thảo chỉ thực vật, 巠 (𢀖) cho âm jīng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hành\": cỏ (艹) mọc thẳng như kinh (𢀖) — thân cây vươn lên thẳng đứng như cột sống của cây. | Gương Hán-Việt | \"hành\" trong 茎秆 (hành can — thân cây), 花茎 (hoa hành — cuống hoa) | Mở khoá kiến thức | Biết 茎 mở khoá từ thực vật học: 茎 (thân cây), 根茎 (căn hành, thân rễ), 花茎 (hoa hành, cuống hoa).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Theo Wiktionary, 莖 (茎) là chữ hình thanh: 艹 (cỏ) biểu nghĩa, 巠 biểu âm. Tiểu triện và Lục thư thông có dạng ghi chép. Nghĩa gốc là thân cây cỏ, cái cán. Từ đó mở rộng sang thân cây nói chung trong thực vật học. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thân cây cỏ; cái chuôi", "Hạng Tần Suất (Jun Da)": "2669.0", "Tần Suất % (Jun Da)": "98.7770119585", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "茎", "Unihan_Traditional (Chữ Phồn thể)": "莖", "Pinyin_Xie": "jīng", "Âm Hán Việt_Xie": "hành", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ bộ phận nâng đỡ của thực vật hoặc làm lượng từ cho các vật có dạng thân dài. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | jīng | / | thân cây | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Thực vật | HSK | HSK 6 | · | Sinh học", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('缅', '{"9000": "2670.0", "Chữ Trung Quốc": "缅", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 12 | nét | 纟 | mịch | biểu nghĩa | sợi, tơ lụa | 面 | diện | biểu âm | mặt, bề mặt | 缅 = 纟 (Mịch, biểu nghĩa: sợi/tơ) + 面 (Diện, biểu âm); chữ hình thanh. Bộ mịch 纟 gợi ý sợi chỉ dài liên tục; 面 (diện) cho âm đọc miǎn. Nghĩa là xa xăm, miên man, nhớ nhung dai dẳng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"miến\": sợi tơ (纟) dài miên man (面) — 缅 là xa xăm, tưởng nhớ dai dẳng; 缅怀 là miên man tưởng nhớ người hay sự vật đã qua. | Gương Hán-Việt | Miến trong \"miến hoài\" (缅怀 — tưởng nhớ), \"miến điện\" (缅甸 — Myanmar, Miến Điện). | Mở khoá kiến thức | Biết 缅 (miến) mở khóa: 缅怀 (tưởng nhớ, miên hoài), 缅甸 (Myanmar — Miến Điện), 缅想 (miên man suy nghĩ về quá khứ).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 缅 là chữ hình thanh: 糸 (mịch, sợi) biểu nghĩa, 面 (diện) biểu âm. Nghĩa gốc là sợi tơ dài miên man; mở rộng sang nghĩa xa xăm, miên miên (dài dặc), hướng về xa, tưởng nhớ sâu sắc. 缅怀 (tưởng nhớ, miên hoài) là từ phổ biến nhất. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "xa tít; nghĩ triền miên", "Hạng Tần Suất (Jun Da)": "2670.0", "Tần Suất % (Jun Da)": "98.7785338907", "GavinGrover_Once (Chiết tự trực tiếp)": "纟 + 面", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰纟面", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "面", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "纟", "Unihan_Simplified (Chữ Giản thể)": "缅", "Unihan_Traditional (Chữ Phồn thể)": "緬", "Pinyin_Xie": "miǎn", "Âm Hán Việt_Xie": "miến, diến", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường kết hợp với các động từ tâm lý để chỉ sự tưởng nhớ về quá khứ hoặc nơi xa xôi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('喇', '{"9000": "2671.0", "Chữ Trung Quốc": "喇", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 12 | nét | 口 | khẩu | biểu nghĩa | miệng | 剌 | lạt | biểu âm | âm lạt | 喇 = 口 (Khẩu, biểu nghĩa: miệng) + 剌 (Lạt, biểu âm). Wiktionary không có anchor Etymology cho 喇. Dựa trên cấu trúc, bộ 口 gợi âm thanh phát ra từ miệng/nhạc cụ, 剌 cho âm lǎ. Chưa có nguồn học thuật đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lạt\": miệng (口) thổi lạt (剌) — tiếng kèn lạt ba kêu vang, như tiếng gọi của đất Tạng. | Gương Hán-Việt | \"lạt\" trong 喇叭 (lạt bá — kèn, loa), 喇嘛 (lạt ma — tăng Tạng) | Mở khoá kiến thức | Biết 喇 mở khoá từ âm nhạc và tôn giáo: 喇叭 (lạt bá, kèn/loa), 喇嘛 (lạt ma, tăng Tạng).", "Tự nguyên_Xie": "Wiktionary không có anchor Etymology cho 喇. Dựa trên cấu trúc có thể đọc là hình thanh: 口 (miệng) biểu nghĩa, 剌 biểu âm. Nghĩa liên quan đến âm thanh phát ra từ nhạc cụ thổi (喇叭 — kèn), cũng dùng phiên âm tiếng Tạng/Tạng ngữ (lạt ma). Chưa có nguồn học thuật đầy đủ. | Theo Wiktionary · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: lạt bá 喇叭)", "Hạng Tần Suất (Jun Da)": "2671.0", "Tần Suất % (Jun Da)": "98.7800527222", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 剌", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口剌", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "剌", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "喇", "Unihan_Traditional (Chữ Phồn thể)": "喇", "Pinyin_Xie": "lǎ", "Âm Hán Việt_Xie": "lạt", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này thường dùng làm danh từ trong các từ ghép chỉ nhạc cụ hoặc thiết bị phát thanh như lạt bá. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('绒', '{"9000": "2672.0", "Chữ Trung Quốc": "绒", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 9 | nét | 纟 | mịch | biểu nghĩa | sợi, vải | 戎 | nhung | biểu âm | vũ trang | 绒 = 纟(Mịch, biểu nghĩa: sợi/vải) + 戎 (Nhung, biểu âm); chữ hình thanh. Dạng phồn thể là 絨. Bộ mịch chỉ chất liệu vải, 戎 cho âm róng/nhung.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nhung\": sợi (纟) nhung (戎) — vải nhung mềm mại như lông thú, ấm áp trong mùa đông. | Gương Hán-Việt | \"nhung\" trong 羽绒服 (vũ nhung phục — áo lông vũ), 绒布 (nhung bố — vải nhung) | Mở khoá kiến thức | Biết 绒 mở khoá từ vải vóc: 羽绒服 (áo phao lông vũ), 绒布 (vải nhung), 天鹅绒 (thiên nga nhung, nhung mịn).", "Tự nguyên_Xie": "Theo Wiktionary, 絨 (绒) có dạng phồn thể. Wiktionary không có phân tích ls chi tiết, chỉ ghi nhận {{Han etym}}. Dựa trên cấu trúc là hình thanh: 糸 (sợi) biểu nghĩa, 戎 biểu âm. Nghĩa gốc là vải lông mềm, sau mở rộng sang mọi loại vải nhung, nỉ. Chưa có nguồn học thuật đầy đủ. | Theo Wiktionary · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nhung, bằng lông thú", "Hạng Tần Suất (Jun Da)": "2672.0", "Tần Suất % (Jun Da)": "98.7815663859", "GavinGrover_Once (Chiết tự trực tiếp)": "纟 + 戎", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰纟戎", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "戎", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "纟", "Unihan_Simplified (Chữ Giản thể)": "绒", "Unihan_Traditional (Chữ Phồn thể)": "絨", "Pinyin_Xie": "róng", "Âm Hán Việt_Xie": "nhung", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Chữ này làm danh từ chỉ chất liệu vải nhung hoặc lông mịn, và làm tính từ khi bổ nghĩa cho danh từ khác. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('搅', '{"9000": "2673.0", "Chữ Trung Quốc": "搅", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 12 | nét | 扌 | thủ | biểu nghĩa | tay | 觉 | giáo | biểu âm | giác ngộ, cảm nhận | 搅 = 扌(Thủ, biểu nghĩa: tay) + 觉 (Giáo, biểu âm); chữ hình thanh. Dạng phồn thể là 攪 (với 覺). Bộ thủ chỉ hành động dùng tay khuấy, 觉 cho âm jiǎo.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"giảo\": tay (扌) giảo hoạt (觉) khuấy đảo — dùng tay khuấy liên tục, không cho vật yên. | Gương Hán-Việt | \"giảo\" trong 搅拌 (giảo bàn — khuấy, trộn), 打搅 (đả giảo — quấy rầy) | Mở khoá kiến thức | Biết 搅 mở khoá từ nấu ăn và giao tiếp: 搅拌 (giảo bàn, khuấy trộn), 打搅 (đả giảo, làm phiền), 搅局 (giảo cục, phá đám).", "Tự nguyên_Xie": "Đại triện | Tiểu triện | Theo Wiktionary, 攪 (搅) là chữ hình thanh: 手 (tay, bộ 扌) biểu nghĩa, 覺 biểu âm. Đại triện và tiểu triện có dạng ghi chép. Nghĩa gốc là dùng tay khuấy đảo, quấy rối. Từ đó mở rộng sang quấy rầy, làm rối loạn. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "quấy, đảo; quấy rối, làm loạn", "Hạng Tần Suất (Jun Da)": "2673.0", "Tần Suất % (Jun Da)": "98.783076432", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 觉", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌觉", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "觉", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "搅", "Unihan_Traditional (Chữ Phồn thể)": "攪", "Pinyin_Xie": "jiǎo", "Âm Hán Việt_Xie": "giảo", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ đứng trước tân ngữ để biểu thị hành động khuấy trộn chất lỏng hoặc gây rối. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | jiǎo | / | quấy rối | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Thực phẩm II | New HSK 7-9 | · | Nỗi khó khăn", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('凳', '{"9000": "2674.0", "Chữ Trung Quốc": "凳", "Bộ thủ & thành phần_Xie": "Bộ thủ | 几 | Số nét | 14 | nét | 登 | đăng | biểu âm | leo lên, đăng quang | 几 | cơ | biểu nghĩa | bàn nhỏ, ghế nhỏ | 凳 = 登 (Đăng, biểu âm) + 几 (Cơ, biểu nghĩa: bàn nhỏ/ghế); chữ hình thanh. Bộ cơ 几 chỉ đồ vật ngồi/kê nhỏ; 登 (đăng) cho âm đọc dèng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đắng\": leo lên (登) cái bàn nhỏ (几) — 凳 là ghế đẩu, ghế không có tựa lưng. | Gương Hán-Việt | Đắng ít dùng trong tiếng Việt; ghế đẩu trong Hán văn là 凳子. | Mở khoá kiến thức | Biết 凳 (đắng) mở khóa: 凳子 (ghế đẩu), 长凳 (ghế dài, băng ghế), 板凳 (ghế gỗ đơn giản).", "Tự nguyên_Xie": "凳 là chữ hình thanh: 几 (cơ, bàn nhỏ/ghế thấp) biểu nghĩa, 登 (đăng) biểu âm. Nghĩa là ghế đẩu không có tựa lưng — loại ghế đơn giản nhất. 几 gợi hình ảnh vật thấp để ngồi hoặc kê; 登 gợi ý leo lên/ngồi lên. Chữ tương đối muộn. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái ghế ngồi", "Hạng Tần Suất (Jun Da)": "2674.0", "Tần Suất % (Jun Da)": "98.7845859614", "GavinGrover_Once (Chiết tự trực tiếp)": "癶 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱癶", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "凳", "Unihan_Traditional (Chữ Phồn thể)": "凳", "Pinyin_Xie": "dèng", "Âm Hán Việt_Xie": "đắng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ các loại ghế ngồi không có chỗ tựa lưng và thường kết hợp với lượng từ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('梭', '{"9000": "2675.0", "Chữ Trung Quốc": "梭", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 11 | nét | 木 | mộc | biểu nghĩa | gỗ, cây | 夋 | biểu âm | (thành phần biểu âm) | 梭 = 木 (Mộc, biểu nghĩa: gỗ) + 夋 (biểu âm); chữ hình thanh. Bộ mộc 木 chỉ vật thể bằng gỗ; 夋 (đọc gần âm suō) cho âm đọc. Con thoi dệt vải làm bằng gỗ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thoa\": gỗ (木) thon nhọn qua lại — 梭 là con thoi dệt vải, cũng chỉ vật gì chuyển động nhanh qua lại như thoi. | Gương Hán-Việt | Thoa trong \"thoi thoa\" (con thoi), \"phi thoa\" (con thoi bay — chỉ thời gian trôi nhanh). | Mở khoá kiến thức | Biết 梭 (thoa) mở khóa: 梭子 (con thoi), 梭鱼 (cá nhồng — hình thon như thoi), 穿梭 (đi lại như con thoi), 棱梭 (hình thoi).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 梭 là chữ hình thanh: 木 (mộc, gỗ) biểu nghĩa, 夋 biểu âm. Nghĩa gốc là con thoi dệt vải — công cụ gỗ nhỏ dùng để dệt, lăn đi lăn lại giữa các sợi dọc. Từ đó mở rộng sang hình dạng thoi (hình thoi — thon hai đầu), chuyển động qua lại như con thoi. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái thoi dệt cửi; quan chức đi lại đốc suất binh phu", "Hạng Tần Suất (Jun Da)": "2675.0", "Tần Suất % (Jun Da)": "98.7860913565", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 夋", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木夋", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "夋", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "梭", "Unihan_Traditional (Chữ Phồn thể)": "梭", "Pinyin_Xie": "suō", "Âm Hán Việt_Xie": "thoa", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này làm danh từ chỉ con thoi dệt vải hoặc làm động từ chỉ sự di chuyển qua lại nhanh chóng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('丫', '{"9000": "2676.0", "Chữ Trung Quốc": "丫", "Bộ thủ & thành phần_Xie": "Bộ thủ | 丨 | Số nét | 3 | nét | 丫 | nha | tượng hình | hình chạc cây, nhánh cây chẽ đôi | 丫 là chữ tượng hình: vẽ hình chạc cây hoặc đường phân nhánh. Xuất hiện khoảng năm 1000, muộn hơn các dạng biến thể khác. Hình ảnh trực tiếp của một nhánh cây chẽ đôi hoặc ngã rẽ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nha\": hình chữ Y — chạc cây chẽ đôi, 丫 gợi hình tóc cột hai búi của cô gái nhỏ (丫头). | Gương Hán-Việt | Nha trong \"nha đầu\" (丫头 — cô gái nhỏ, a hoàn phục vụ), \"phân nha\" (chẽ nhánh). | Mở khoá kiến thức | Biết 丫 (nha) mở khóa: 丫头 (cô bé, a hoàn), 丫杈 (chạc cây), 发丫 (tóc hai búi), 丫鬟 (a hoàn kẻ hầu).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 丫 là chữ tượng hình (象形): vẽ hình một nhánh cây chẽ đôi hoặc một ngã rẽ. Chữ xuất hiện khoảng năm 1000, muộn hơn các dạng khác. Nghĩa gốc là chạc cây, chỗ nhánh chẽ ra; mở rộng sang cô gái nhỏ (丫头 — đứa trẻ gái, a hoàn), chỉ tóc cột hai búi. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "xoè ra", "Hạng Tần Suất (Jun Da)": "2676.0", "Tần Suất % (Jun Da)": "98.7875962348", "GavinGrover_Once (Chiết tự trực tiếp)": "丷 + 丨", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱丷丨", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "丨", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "丷", "Unihan_Simplified (Chữ Giản thể)": "丫", "Unihan_Traditional (Chữ Phồn thể)": "丫", "Pinyin_Xie": "yā", "Âm Hán Việt_Xie": "nha", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Chữ này làm danh từ chỉ nhánh cây hoặc búi tóc của trẻ nhỏ, và làm tính từ chỉ hình dạng chia ngả. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('姬', '{"9000": "2677.0", "Chữ Trung Quốc": "姬", "Bộ thủ & thành phần_Xie": "Bộ thủ | 女 | Số nét | 10 | nét | 女 | nữ | biểu nghĩa | phụ nữ | 𦣞 | biểu âm | (thành phần biểu âm cổ) | 姬 = 女 (Nữ, biểu nghĩa: phụ nữ) + 𦣞 (biểu âm); chữ hình thanh. Bộ nữ 女 chỉ phụ nữ; 𦣞 cho âm đọc jī. Chữ có giáp cốt văn và kim văn, là họ tổ của nhà Chu.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cơ\": người phụ nữ (女) quý tộc — 姬 là họ của nhà Chu, cũng chỉ cung phi, ca kỹ, người đẹp trong văn học cổ. | Gương Hán-Việt | Cơ trong \"cơ tử\" (姬子 — con cháu họ Cơ), \"ca cơ\" (ca kỹ), \"ái cơ\" (người thiếp được sủng ái). | Mở khoá kiến thức | Biết 姬 (cơ) mở khóa: 姬姓 (họ Cơ — họ của nhà Chu), 爱姬 (ái cơ — thiếp yêu), 歌姬 (ca kỹ), 侍姬 (thị cơ — người hầu gái).", "Tự nguyên_Xie": "Giáp cốt văn | Kim văn | 姬 là chữ hình thanh: 女 (nữ) biểu nghĩa, 𦣞 biểu âm. Chữ có nguồn gốc rất cổ (giáp cốt văn, kim văn). Nghĩa gốc là họ của vua Chu (nhà Chu — triều đại 1046-256 TCN) và tổ tiên huyền thoại Hoàng Đế. Mở rộng sang chỉ thê thiếp, ca kỹ, phụ nữ đẹp trong văn học cổ. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tiếng gọi đàn bà quý phái", "Hạng Tần Suất (Jun Da)": "2677.0", "Tần Suất % (Jun Da)": "98.7890995628", "GavinGrover_Once (Chiết tự trực tiếp)": "女 + 𦣞", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰女𦣞", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "𦣞", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "女", "Unihan_Simplified (Chữ Giản thể)": "姬", "Unihan_Traditional (Chữ Phồn thể)": "姬", "Pinyin_Xie": "jī", "Âm Hán Việt_Xie": "cơ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ dùng để chỉ người phụ nữ quý phái, ca nữ hoặc tỳ thiếp trong thời phong kiến. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('诏', '{"9000": "2678.0", "Chữ Trung Quốc": "诏", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 7 | nét | 讠 | biểu nghĩa | lời nói, ngôn ngữ | 召 | thiệu | biểu âm | triệu tập, gọi đến | 诏 (phồn thể 詔) = 讠/言 (biểu nghĩa: lời nói) + 召 (Thiệu, biểu âm); chữ hình thanh. Bộ ngôn 讠 chỉ lời nói/sắc lệnh bằng lời; 召 (thiệu) cho âm đọc zhào. Chiếu chỉ nhà vua ban xuống.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chiếu\": lời nói (讠) triệu tập (召) — 诏 là chiếu chỉ, chiếu thư của hoàng đế ban xuống. | Gương Hán-Việt | Chiếu trong \"chiếu chỉ\" (诏旨 — lệnh vua), \"chiếu thư\" (诏书 — văn bản chiếu chỉ), \"phụng chiếu\" (phụng mệnh chiếu chỉ). | Mở khoá kiến thức | Biết 诏 (chiếu) mở khóa: 诏书 (chiếu thư), 诏令 (chiếu lệnh), 圣诏 (thánh chiếu), 奉诏 (phụng chiếu).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 诏 (phồn thể 詔) là chữ giản thể của 詔. Cấu trúc: 言 (ngôn) biểu nghĩa lời nói/ban lời, 召 (thiệu) biểu âm. Nghĩa gốc là chiếu chỉ của vua — lời ban xuống của thiên tử. Mở rộng sang thông tri, dạy bảo từ trên xuống. chưa có phân tích chi tiết từ Wiktionary cho dạng giản thể. | Suy từ bộ phận cấu thành · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chiếu chỉ", "Hạng Tần Suất (Jun Da)": "2678.0", "Tần Suất % (Jun Da)": "98.7906018572", "GavinGrover_Once (Chiết tự trực tiếp)": "讠 + 召", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰讠召", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "召", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "讠", "Unihan_Simplified (Chữ Giản thể)": "诏", "Unihan_Traditional (Chữ Phồn thể)": "詔", "Pinyin_Xie": "zhào", "Âm Hán Việt_Xie": "chiếu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này làm danh từ chỉ mệnh lệnh viết bằng văn bản của hoàng đế hoặc làm động từ với nghĩa ban truyền mệnh lệnh. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('钮', '{"9000": "2679.0", "Chữ Trung Quốc": "钮", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 9 | nét | 钅 | kim | biểu nghĩa | kim loại | 丑 | sửu | biểu âm | xấu xí, chi sửu | 钮 (phồn thể 鈕) = 钅/金 (Kim, biểu nghĩa: kim loại) + 丑 (Sửu, biểu âm); chữ hình thanh. Bộ kim 钅 chỉ vật bằng kim loại; 丑 (sửu) cho âm đọc niǔ. Đây là chữ giản thể của 鈕 (nút/núm bằng kim loại).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nữu\": kim loại (钅) nhỏ như chi sửu (丑) — 钮 là nút, núm, nút bấm kim loại nhỏ. | Gương Hán-Việt | Nữu trong \"khấu nữu\" (扣钮 — cài cúc), \"nữu khấu\" (纽扣 — khuy/cúc áo). | Mở khoá kiến thức | Biết 钮 (nữu) mở khóa: 按钮 (nút bấm), 纽扣 (cúc áo), 旋钮 (núm xoay), 电钮 (nút điện).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 钮 (phồn thể 鈕) là chữ hình thanh: 金 (kim, kim loại) biểu nghĩa, 丑 biểu âm. Nghĩa gốc là nút/núm kim loại dùng để cài áo hoặc làm tay nắm (núm kiếm, nút ấn). Mở rộng sang nút bấm nói chung, tên riêng. chưa có phân tích chi tiết trong Wiktionary cho dạng giản thể. | Suy từ bộ phận cấu thành · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chỗ để buộc dây; cúc áo", "Hạng Tần Suất (Jun Da)": "2679.0", "Tần Suất % (Jun Da)": "98.7921036348", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 丑", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅丑", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "丑", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "钮", "Unihan_Traditional (Chữ Phồn thể)": "鈕", "Pinyin_Xie": "niǔ", "Âm Hán Việt_Xie": "nữu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ cúc áo hoặc các nút bấm, núm vặn điều khiển trên thiết bị. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('棺', '{"9000": "2680.0", "Chữ Trung Quốc": "棺", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 12 | nét | 木 | mộc | biểu nghĩa | gỗ | 官 | quan | biểu âm | quan chức, chính quyền | 棺 = 木 (Mộc, biểu nghĩa: gỗ) + 官 (Quan, biểu âm); chữ hình thanh. Bộ mộc 木 chỉ vật bằng gỗ; 官 (quan) cho âm đọc guān. Quan tài là hộp gỗ đựng người chết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quan\": gỗ (木) hình quan (官) — 棺 là quan tài, hộp gỗ để đặt thi hài. \"Quan tài\" trong tiếng Việt mượn từ 棺材. | Gương Hán-Việt | Quan trong \"quan tài\" (棺材 — hộp chứa thi thể), \"nhập quan\" (nhập quan — đặt thi hài vào quan tài). | Mở khoá kiến thức | Biết 棺 (quan) mở khóa: 棺材 (quan tài), 入棺 (nhập quan), 盖棺定论 (nắp quan đóng lại mới định được — kết luận sau khi chết).", "Tự nguyên_Xie": "Kim văn | Tiểu triện | Lục thư thông | 棺 là chữ hình thanh: 木 (mộc, gỗ) biểu nghĩa, 官 (quan) biểu âm. Nghĩa gốc và duy nhất là quan tài — hộp gỗ để đặt thi hài người chết. 棺材 (quan tài) là từ phổ biến nhất. Chữ có kim văn và tiểu triện, thể hiện tầm quan trọng của nghi lễ tang ma trong văn hóa Trung Hoa. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "áo quan (cho người chết)", "Hạng Tần Suất (Jun Da)": "2680.0", "Tần Suất % (Jun Da)": "98.7936028284", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 官", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木官", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "官", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "棺", "Unihan_Traditional (Chữ Phồn thể)": "棺", "Pinyin_Xie": "guān", "Âm Hán Việt_Xie": "quan", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ hòm đựng thi hài người chết và thường đi kèm với lượng từ chỉ chiếc hoặc cỗ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('耿', '{"9000": "2681.0", "Chữ Trung Quốc": "耿", "Bộ thủ & thành phần_Xie": "Bộ thủ | 耳 | Số nét | 10 | nét | 耳 | nhĩ | biểu nghĩa | tai — mang nghĩa lắng nghe, tâm trạng bất an | 火 | hoả | biểu âm | lửa — cho âm gěng | 耿 = 耳 (Nhĩ, biểu nghĩa: tai) + 火 (Hoả, biểu âm); chữ hình thanh. Phần âm 火 cho âm gěng (biến thể 烓/聖 cũng được ghi nhận). Nghĩa gốc liên quan đến cảm giác bất an, băn khoăn trong lòng — như lửa âm ỉ bên tai.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cảnh\": tai (耳) bên ngọn lửa (火) — người ngay thẳng luôn cảnh giác, lòng không yên như lửa bên tai. | Gương Hán-Việt | cảnh trong 耿直 (cảnh trực — ngay thẳng, trực tính) | Mở khoá kiến thức | Biết 耿 mở khoá: 耿直 (ngay thẳng), 耿耿 (lo lắng không yên, tận tâm).", "Tự nguyên_Xie": "bronze | seal | liushutong | Theo Wiktionary, 耿 là chữ hình thanh (形聲): 耳 (nhĩ) biểu nghĩa, 烓 hoặc 聖 biểu âm, rút gọn thành 火. Nghĩa cổ là ''sáng, rực rỡ''; mở rộng sang ''ngay thẳng, chính trực'' và ''lo lắng, bất an''. Dạng kim văn và triện thư đã có mặt. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sáng; thắc mắc", "Hạng Tần Suất (Jun Da)": "2681.0", "Tần Suất % (Jun Da)": "98.7951009885", "GavinGrover_Once (Chiết tự trực tiếp)": "耳 + 火", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰耳火", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "火", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "耳", "Unihan_Simplified (Chữ Giản thể)": "耿", "Unihan_Traditional (Chữ Phồn thể)": "耿", "Pinyin_Xie": "gěng", "Âm Hán Việt_Xie": "cảnh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này làm tính từ để miêu tả tính cách ngay thẳng, trung trực hoặc trạng thái lo lắng không yên. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('缔', '{"9000": "2682.0", "Chữ Trung Quốc": "缔", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 12 | nét | 纟 | mịch | biểu nghĩa | sợi, ràng buộc | 帝 | đế | biểu âm | hoàng đế | 缔 = 纟(Mịch, biểu nghĩa: sợi/ràng buộc) + 帝 (Đế, biểu âm); chữ hình thanh. Giản thể của 締. Bộ mịch chỉ ràng buộc kết nối, 帝 cho âm dì.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đế\": sợi (纟) như sắc chỉ hoàng đế (帝) — ràng buộc chặt chẽ như lệnh từ hoàng đế. | Gương Hán-Việt | \"đế\" trong 缔结 (đế kết — ký kết, thiết lập), 取缔 (thủ đế — cấm, giải tán) | Mở khoá kiến thức | Biết 缔 mở khoá từ pháp lý và ngoại giao: 缔结 (đế kết, ký kết), 取缔 (thủ đế, cấm đoán), 缔约 (đế ước, ký điều ước).", "Tự nguyên_Xie": "Tiểu triện | 缔 là dạng giản thể của 締 (đế). Wiktionary chỉ ghi giản thể của 締, không có phân tích ls riêng. Dựa trên dạng phồn thể, 締 là hình thanh: 糸 (sợi) biểu nghĩa, 帝 biểu âm. Tiểu triện có dạng ghi chép. Nghĩa gốc là ràng buộc, kết nối bằng sợi dây. Từ đó mở rộng sang ký kết, thiết lập (缔结, 缔约). | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ràng buộc", "Hạng Tần Suất (Jun Da)": "2682.0", "Tần Suất % (Jun Da)": "98.7965981151", "GavinGrover_Once (Chiết tự trực tiếp)": "纟 + 帝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰纟帝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "帝", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "纟", "Unihan_Simplified (Chữ Giản thể)": "缔", "Unihan_Traditional (Chữ Phồn thể)": "締", "Pinyin_Xie": "dì", "Âm Hán Việt_Xie": "đế", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ thường kết hợp với các danh từ trừu tượng để chỉ việc ký kết hiệp ước hoặc thiết lập quan hệ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('懈', '{"9000": "2683.0", "Chữ Trung Quốc": "懈", "Bộ thủ & thành phần_Xie": "Bộ thủ | 心 | Số nét | 16 | nét | 忄 | tâm | biểu nghĩa | tim, lòng — chỉ trạng thái tinh thần | 解 | giải | biểu âm | cởi mở, tháo ra — cho âm xiè | 懈 = 忄(Tâm, biểu nghĩa: tâm trí) + 解 (Giải, biểu âm); chữ hình thanh. 解 vừa cho âm xiè vừa gợi ý nghĩa ''buông lỏng'', kết hợp với bộ tâm thành ''tâm trạng lơi lỏng, lười biếng''.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"giải\": khi tâm (忄) bắt đầu tháo gỡ, giải phóng (解) — đó là lúc lười biếng, lơi lỏng nảy sinh. | Gương Hán-Việt | giải trong 懈怠 (giải đãi — lười biếng, lơ đễnh) | Mở khoá kiến thức | Biết 懈 mở khoá: 懈怠 (lơi lỏng), 不懈 (không ngừng nghỉ), 坚持不懈 (kiên trì không mệt mỏi).", "Tự nguyên_Xie": "seal | liushutong | Theo Wiktionary, 懈 là chữ hình thanh (形聲): 忄(tâm) biểu nghĩa, 解 biểu âm. Nghĩa gốc là trạng thái buông lỏng, lơi lỏng ý chí. Dùng chủ yếu trong vău phủ định 不懈 (không ngừng nghỉ). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lười nhác", "Hạng Tần Suất (Jun Da)": "2683.0", "Tần Suất % (Jun Da)": "98.7980931745", "GavinGrover_Once (Chiết tự trực tiếp)": "忄 + 解", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰忄解", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "解", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "忄", "Unihan_Simplified (Chữ Giản thể)": "懈", "Unihan_Traditional (Chữ Phồn thể)": "懈", "Pinyin_Xie": "xiè", "Âm Hán Việt_Xie": "giải", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường làm tính từ bổ nghĩa cho danh từ hoặc kết hợp trong từ ghép như giải đãi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('嫉', '{"9000": "2684.0", "Chữ Trung Quốc": "嫉", "Bộ thủ & thành phần_Xie": "Bộ thủ | 女 | Số nét | 13 | nét | 女 | nữ | biểu nghĩa | phụ nữ | 疾 | tật | biểu âm | bệnh tật, ghét | 嫉 = 女 (Nữ, biểu nghĩa: phụ nữ) + 疾 (Tật, biểu âm); chữ hình thanh. Bộ nữ chỉ cảm xúc liên quan đến phụ nữ, 疾 cho âm jí và cũng gợi nghĩa ghét/bệnh. Nghĩa là ghen tị, đố kỵ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tật\": phụ nữ (女) mang bệnh tật (疾) — ghen tị là căn bệnh tật nguyền dày vò tâm hồn. | Gương Hán-Việt | \"tật\" trong 嫉妒 (tật đố — ghen tị), 嫉恨 (tật hận — ghen ghét) | Mở khoá kiến thức | Biết 嫉 mở khoá từ cảm xúc: 嫉妒 (tật đố, ghen tị), 嫉恨 (tật hận, oán ghét), 憤世嫉俗 (phẫn thế tật tục, bất mãn xã hội).", "Tự nguyên_Xie": "Đại triện | Tiểu triện | Theo Wiktionary, 嫉 là chữ hình thanh: 女 (phụ nữ) biểu nghĩa, 疾 biểu âm. Đại triện và tiểu triện có dạng ghi chép. Nghĩa gốc là ghen ghét, đố kỵ. Lưu ý 疾 vừa cho âm vừa gợi nghĩa ''bệnh'' — cảm giác ghen tị như một thứ bệnh dày vò. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "căm ghét; ghen ghét, đố kỵ, ganh tị", "Hạng Tần Suất (Jun Da)": "2684.0", "Tần Suất % (Jun Da)": "98.7995877171", "GavinGrover_Once (Chiết tự trực tiếp)": "女 + 疾", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰女疾", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "疾", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "女", "Unihan_Simplified (Chữ Giản thể)": "嫉", "Unihan_Traditional (Chữ Phồn thể)": "嫉", "Pinyin_Xie": "jí", "Âm Hán Việt_Xie": "tật", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ mang tân ngữ chỉ đối tượng bị ghen ghét hoặc kết hợp thành tật đố. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('灶', '{"9000": "2685.0", "Chữ Trung Quốc": "灶", "Bộ thủ & thành phần_Xie": "Bộ thủ | 火 | Số nét | 7 | nét | 火 | hoả | biểu nghĩa | lửa | 土 | thổ | biểu nghĩa | đất | 灶 = 火 (Hoả, biểu nghĩa: lửa) + 土 (Thổ, biểu nghĩa: đất); chữ hội ý. Lửa (火) đặt trên đất/bệ đất (土) — hình ảnh bếp nấu ăn. Chỉ thấy Lục thư thông.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"táo\": lửa (火) trên đất (土) — bếp táo là nơi lửa cháy trên bệ đất, trung tâm bếp núc. | Gương Hán-Việt | \"táo\" trong 炉灶 (lô táo — bếp lò), 灶台 (táo đài — mặt bếp) | Mở khoá kiến thức | Biết 灶 mở khoá từ bếp núc: 炉灶 (lô táo, bếp lò), 灶台 (táo đài, mặt bếp), 灶王 (táo vương, thần bếp).", "Tự nguyên_Xie": "Lục thư thông | Theo Wiktionary, 灶 là chữ hội ý: 火 (lửa) và 土 (đất) kết hợp — lửa đặt trên bệ đất, hình ảnh bếp nấu ăn. Chỉ thấy trong Lục thư thông — chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. Nghĩa gốc là bếp nấu, cái lò. Từ đó mở rộng sang bếp củi, bếp lò. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "262.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Hỏa (140) Thổ (255)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Hỏa (số 140 - biến thể) và chữ Thổ (số 255) . Lửa cháy trong cái lò/bếp làm bằng đất. Táo là cái bếp (vd: Táo quân).", "Nghĩa Tiếng Việt_Xie": "cái bếp", "Hạng Tần Suất (Jun Da)": "2685.0", "Tần Suất % (Jun Da)": "98.8010817429", "GavinGrover_Once (Chiết tự trực tiếp)": "火 + 土", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰火土", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "土", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "火", "Unihan_Simplified (Chữ Giản thể)": "灶", "Unihan_Traditional (Chữ Phồn thể)": "灶", "Pinyin_Xie": "zào", "Âm Hán Việt_Xie": "táo", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Làm danh từ chỉ cái bếp, thường đứng sau các động từ hành động hoặc làm định ngữ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('匀', '{"9000": "2686.0", "Chữ Trung Quốc": "匀", "Bộ thủ & thành phần_Xie": "Bộ thủ | 勹 | Số nét | 4 | nét | 勹 | bao | hình thể | thành phần hình thể, gốc âm cổ | 冫 | băng | hình thể | thành phần hình thể | 匀 = 勹 + 冫. Wiktionary ghi đây là chữ hình thanh phức tạp: gốc là 螾 (âm) + 呂 (nghĩa: hai tấm vàng, đơn vị cân). Cả hai thành phần đã biến dạng — 螾 → 勹, 呂 → 冫(二). Dạng hiện tại không còn phản ánh cơ chế nguyên thủy. Nghĩa ''đều đặn'' là nghĩa phát triển từ đơn vị cân lường.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quân\": quân bình, quân đều — 匀 đọc quân, cùng gốc với 均 (quân – đều). Cân bằng đều đặn. | Gương Hán-Việt | quân trong ''quân bình, quân sự'' — cùng âm; 匀 đặc chỉ nghĩa ''đều, phân đều'' | Mở khoá kiến thức | Biết 匀 mở khoá: 均匀 (quân quân – đều đặn), 匀称 (quân xứng – cân đối), 分匀 (phân quân – chia đều).", "Tự nguyên_Xie": "匀 theo Wiktionary là chữ hình thanh gốc: phonetic 螾 (nay là 勹) + semantic 呂 (hai tấm vàng, đơn vị cân lường). Qua biến dạng lịch sử, 螾 → 勹, 呂 → 二 (tức 冫). Nghĩa gốc là đơn vị cân (原形 của 鈞). Nghĩa ''đều đặn, phân bố đều'' là nghĩa phát triển muộn. Chữ tạo muộn so với nhiều chữ khác, chưa thấy dạng giáp cốt rõ ràng. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "28.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Bao (24) Nhị (27)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Gồm chữ Bao (số 24) và chữ Nhị (số 27) . Khi phân chia mà bao quát, bao gồm cả 2 bên không thiên lệch bên nào, như vậy là đều nhau.", "Nghĩa Tiếng Việt_Xie": "đều đặn", "Hạng Tần Suất (Jun Da)": "2686.0", "Tần Suất % (Jun Da)": "98.802575252", "GavinGrover_Once (Chiết tự trực tiếp)": "勹 + 亠", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴勹亠", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "亠", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "勹", "Unihan_Simplified (Chữ Giản thể)": "匀", "Unihan_Traditional (Chữ Phồn thể)": "勻", "Pinyin_Xie": "yún", "Âm Hán Việt_Xie": "quân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Làm tính từ miêu tả trạng thái phân bố đều hoặc làm động từ với nghĩa chia bớt. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('嗣', '{"9000": "2687.0", "Chữ Trung Quốc": "嗣", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 13 | nét | 口 | khẩu | biểu nghĩa | miệng — chỉ lời nói, tuyên bố | 冂 | quynh | biểu hình | khung bao quanh | 卄 | nhập | biểu hình | hai mươi, nét kép | 司 | ti | biểu âm | cai quản — cho âm sì | 嗣 = 口 (Khẩu) + 𠕁 (khung tài liệu) + 司 (Ti, biểu âm); chữ hình thanh. Theo Wiktionary, nguyên nghĩa là ''bổ nhiệm người kế thừa qua lời nói và văn bản'', gồm khẩu (lời nói), 冊 (văn bản) và 司 (biểu âm). Chữ hội tụ ý nghĩa kế thừa quyền lực.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tự\": miệng (口) đọc tờ văn bản (冊), quan (司) chứng kiến — nghi lễ phong người kế tự. | Gương Hán-Việt | tự trong 嗣子 (tự tử — con trai nối dõi) và 嗣位 (tự vị — kế thừa ngôi vị) | Mở khoá kiến thức | Biết 嗣 mở khoá: 嗣子 (con nối dõi), 嗣位 (kế vị), 嗣后 (từ đó về sau).", "Tự nguyên_Xie": "bronze | seal | liushutong | Theo Wiktionary, 嗣 là chữ hình thanh (形聲): 口 và 冊 biểu nghĩa (lời nói và văn bản trong lễ bổ nhiệm người kế vị), 司 biểu âm. Nghĩa gốc: bổ nhiệm người kế thừa; mở rộng sang nghĩa ''kế tục, nối dõi''. Dạng giáp cốt và kim văn đã xuất hiện với cấu trúc tương tự. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nối tiếp, thừa hưởng; hậu duệ", "Hạng Tần Suất (Jun Da)": "2687.0", "Tần Suất % (Jun Da)": "98.8040682442", "GavinGrover_Once (Chiết tự trực tiếp)": "No glyph available + 司", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰司", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "嗣", "Unihan_Traditional (Chữ Phồn thể)": "嗣", "Pinyin_Xie": "sì", "Âm Hán Việt_Xie": "tự", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường dùng trong văn viết cổ làm động từ nối ngôi hoặc danh từ chỉ người thừa kế. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鸽', '{"9000": "2688.0", "Chữ Trung Quốc": "鸽", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鳥 | Số nét | 11 | nét | 合 | cáp | biểu âm | hợp lại | 鸟 | điểu | biểu nghĩa | chim | 鸽 = 合 (Cáp, biểu âm) + 鸟 (Điểu, biểu nghĩa: chim); chữ hình thanh. Giản thể của 鴿 (thay 鳥 bằng 鸟). Bộ điểu chỉ loài chim, 合 cho âm gē.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cáp\": chim (鸟) hợp (合) lại — bồ câu bay thành đàn, tụ họp cùng nhau, biểu tượng hoà thuận. | Gương Hán-Việt | \"cáp\" trong 鸽子 (cáp tử — chim bồ câu), 信鸽 (tín cáp — bồ câu đưa thư) | Mở khoá kiến thức | Biết 鸽 mở khoá từ chim chóc và hoà bình: 鸽子 (cáp tử, bồ câu), 信鸽 (tín cáp, bồ câu đưa thư), 鸽派 (cáp phái, phe bồ câu/hoà bình).", "Tự nguyên_Xie": "Tiểu triện | 鸽 là dạng giản thể của 鴿. Wiktionary ghi 鸽 là giản thể của 鴿 (không có phân tích thêm). Tiểu triện có dạng ghi chép. Theo cấu trúc truyền thống, 鴿 là hình thanh: 鳥 (chim) biểu nghĩa, 合 biểu âm. Nghĩa là chim bồ câu, biểu tượng hoà bình. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chim bồ câu", "Hạng Tần Suất (Jun Da)": "2688.0", "Tần Suất % (Jun Da)": "98.8055596861", "GavinGrover_Once (Chiết tự trực tiếp)": "合 + 鸟", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰合鸟", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "合", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鸟", "Unihan_Simplified (Chữ Giản thể)": "鸽", "Unihan_Traditional (Chữ Phồn thể)": "鴿", "Pinyin_Xie": "gē", "Âm Hán Việt_Xie": "cáp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Làm danh từ chỉ loài chim bồ câu, thường đi kèm lượng từ chỉ con vật như chích. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('澡', '{"9000": "2689.0", "Chữ Trung Quốc": "澡", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 16 | nét | 氵 | thuỷ | biểu nghĩa | nước | 喿 | táo | biểu âm | tiếng chim kêu trên cây | 澡 = 氵 (Thuỷ, biểu nghĩa: nước) + 喿 (Táo, biểu âm); chữ hình thanh — tắm rửa bằng nước.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"táo\": nước 氵 dùng để táo 喿 sạch người — đó là tắm, là rửa. | Gương Hán-Việt | Âm ''táo'' Hán-Việt xuất hiện trong ''tẩy táo'' (洗澡 tắm). Tiếng Việt thường nói ''tắm'' chứ ít dùng ''táo''. | Mở khoá kiến thức | Biết 澡 mở khoá từ vựng vệ sinh cá nhân tiếng Trung: 洗澡 (tắm), 澡堂 (nhà tắm công cộng).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 澡 là chữ hình thanh: bộ 氵 (nước) cho nghĩa liên quan đến tắm rửa, 喿 cho âm. Nghĩa gốc ''rửa tay, tắm'', hiện đại dùng cố định trong từ 洗澡 (tắm). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: tẩy táo 洗澡)", "Hạng Tần Suất (Jun Da)": "2689.0", "Tần Suất % (Jun Da)": "98.8070490609", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 喿", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵喿", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "喿", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "澡", "Unihan_Traditional (Chữ Phồn thể)": "澡", "Pinyin_Xie": "zǎo", "Âm Hán Việt_Xie": "táo", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường kết hợp với động từ tẩy để tạo thành động từ ly hợp tẩy táo mang nghĩa là tắm. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('凿', '{"9000": "2690.0", "Chữ Trung Quốc": "凿", "Bộ thủ & thành phần_Xie": "Bộ thủ | 凵 | Số nét | 12 | nét | 凵 | khảm | biểu nghĩa | cái hố, cái cối — chỉ vật rỗng bên trong | 丵 | trác | biểu nghĩa | cái đục, dụng cụ đục | 凿 là chữ hội ý (會意): 丵 (dụng cụ đục) bên trong 凵 (cái cối/hố rỗng) — hình ảnh mũi đục trong cối đá. Theo Wiktionary, đây là dạng giản của 鑿, xuất hiện từ giáp cốt văn, sau được thêm bộ 殳 và 金 vào dạng phồn thể.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tạc\": cái đục (丵) cắm vào hố cối (凵) — hành động tạc, đục đẽo vào đá. | Gương Hán-Việt | tạc trong 雕凿 (điêu tạc — chạm khắc) và 确凿 (xác tạc — chắc chắn, rõ ràng) | Mở khoá kiến thức | Biết 凿 mở khoá: 确凿 (chắc chắn), 凿壁 (đục tường — điển tích học dưới ánh đèn láng giềng).", "Tự nguyên_Xie": "oracle | bronze | seal | liushutong | Theo Wiktionary, 凿 (phồn thể: 鑿) là chữ hội ý (會意), nguồn gốc từ giáp cốt: mô tả mũi đục (丵) trong lòng cối đá (凵). Dạng cổ đã có hình ảnh công cụ đục lỗ. Các bộ phận 殳 và 金 được thêm vào sau ở dạng phồn thể. Nghĩa gốc: đục lỗ, khoét; mở rộng sang ''rõ ràng, chắc chắn'' (như 确凿). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đào, đục", "Hạng Tần Suất (Jun Da)": "2690.0", "Tần Suất % (Jun Da)": "98.8085374021", "GavinGrover_Once (Chiết tự trực tiếp)": "业 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱业", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "凿", "Unihan_Traditional (Chữ Phồn thể)": "鑿", "Pinyin_Xie": "záo", "Âm Hán Việt_Xie": "tạc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Làm động từ chỉ hành động đục đẽo hoặc làm danh từ chỉ cái đục. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | záo | / | đục | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Xây dựng và cải tạo", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('纬', '{"9000": "2691.0", "Chữ Trung Quốc": "纬", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 7 | nét | 纟 | mịch | biểu nghĩa | sợi chỉ, dệt | 韦 | vi | biểu âm | da mềm, thuộc da | 纬 = 纟(Mịch, biểu nghĩa: sợi/dệt) + 韦 (Vi, biểu âm); chữ hình thanh. Dạng phồn thể là 緯. Bộ mịch chỉ sợi chỉ dệt vải, 韦 cho âm wěi. Nghĩa là sợi ngang trong dệt, vĩ tuyến.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"vĩ\": sợi (纟) dệt ngang theo vi (韦) — vĩ độ là các đường ngang trên bản đồ, như sợi ngang trong tấm vải. | Gương Hán-Việt | \"vĩ\" trong 纬度 (vĩ độ — vĩ tuyến), 经纬 (kinh vĩ — kinh độ và vĩ độ) | Mở khoá kiến thức | Biết 纬 mở khoá từ địa lý: 纬度 (vĩ độ), 经纬 (kinh vĩ), 北纬 (bắc vĩ, vĩ độ Bắc).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 緯 (纬) là chữ hình thanh: 糸 (sợi) biểu nghĩa, 韋 biểu âm. Lưu ý: trong dạng cổ của 韋, các thành phần trên dưới 囗 là bàn chân quay ngang trái-phải — cũng mang nghĩa ngang, phù hợp với nghĩa sợi ngang. Tiểu triện có dạng. Nghĩa gốc là sợi ngang (weft) trong dệt, đối với sợi dọc (經). Mở rộng sang vĩ độ địa lý. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sợi ngang; vĩ tuyến", "Hạng Tần Suất (Jun Da)": "2691.0", "Tần Suất % (Jun Da)": "98.8100226425", "GavinGrover_Once (Chiết tự trực tiếp)": "纟 + 韦", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰纟韦", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "韦", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "纟", "Unihan_Simplified (Chữ Giản thể)": "纬", "Unihan_Traditional (Chữ Phồn thể)": "緯", "Pinyin_Xie": "wěi", "Âm Hán Việt_Xie": "vĩ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Làm danh từ chỉ đường vĩ tuyến trên bản đồ hoặc sợi dệt ngang, đối lập với kinh. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('沸', '{"9000": "2692.0", "Chữ Trung Quốc": "沸", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 8 | nét | 氵 | thuỷ | biểu nghĩa | nước | 弗 | phất | biểu âm | phủ nhận | 沸 = 氵(Thuỷ, biểu nghĩa: nước) + 弗 (Phất, biểu âm); chữ hình thanh. Bộ thuỷ chỉ nước, 弗 cho âm fèi gần fú. Nghĩa là sôi, bong bóng nổi lên.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phí\": nước (氵) phất (弗) sôi sục — nước sôi bùng lên như trái tim phí sức sống. | Gương Hán-Việt | \"phí\" trong 沸腾 (phí đằng — sôi, sôi sục), 沸沸扬扬 (phí phí dương dương — ồn ào náo động) | Mở khoá kiến thức | Biết 沸 mở khoá từ trạng thái: 沸腾 (phí đằng, sôi/sôi sục), 沸点 (phí điểm, điểm sôi), 沸沸扬扬 (ồn ào bàn tán).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Theo Wiktionary, 沸 là chữ hình thanh: 水 (nước, bộ 氵) biểu nghĩa, 弗 biểu âm. Tiểu triện và Lục thư thông có dạng ghi chép. Nghĩa gốc là nước sôi, bong bóng nổi lên. Từ đó mở rộng sang sôi sục, náo loạn (沸腾, 沸沸扬扬). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sôi (nước)", "Hạng Tần Suất (Jun Da)": "2692.0", "Tần Suất % (Jun Da)": "98.811500648", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 弗", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵弗", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "弗", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "沸", "Unihan_Traditional (Chữ Phồn thể)": "沸", "Pinyin_Xie": "fèi", "Âm Hán Việt_Xie": "phí", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Làm động từ chỉ nước sôi hoặc tính từ miêu tả trạng thái náo nhiệt, sục sôi. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('畴', '{"9000": "2693.0", "Chữ Trung Quốc": "畴", "Bộ thủ & thành phần_Xie": "Bộ thủ | 田 | Số nét | 12 | nét | 田 | điền | biểu nghĩa | ruộng đồng | 寿 | thọ | biểu âm | thọ lâu | 畴 = 田 (Điền, biểu nghĩa: ruộng) + 寿 (Thọ, biểu âm); chữ hình thanh. Dạng phồn thể là 疇. Bộ điền chỉ đất nông nghiệp, 壽 (寿) cho âm chóu.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trù\": ruộng (田) thọ (寿) lâu — cánh đồng trù phú là nền tảng sinh kế lâu dài của nông dân. | Gương Hán-Việt | \"trù\" trong 范畴 (phạm trù — lĩnh vực, thể loại), 畴昔 (trù tích — ngày xưa) | Mở khoá kiến thức | Biết 畴 mở khoá từ học thuật: 范畴 (phạm trù, lĩnh vực), 范畴论 (lý thuyết phạm trù).", "Tự nguyên_Xie": "Giáp cốt văn | Theo Wiktionary, 疇 (畴) là chữ hình thanh: 田 (ruộng) biểu nghĩa, 壽 biểu âm. Giáp cốt văn đã có dạng. Nghĩa gốc là ruộng lúa, đất canh tác. Từ đó mở rộng sang loài, loại, phạm trù (范畴 — phạm trù, lĩnh vực). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ruộng lúa; loài, loại", "Hạng Tần Suất (Jun Da)": "2693.0", "Tần Suất % (Jun Da)": "98.8129776199", "GavinGrover_Once (Chiết tự trực tiếp)": "田 + 寿", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰田寿", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "寿", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "田", "Unihan_Simplified (Chữ Giản thể)": "畴", "Unihan_Traditional (Chữ Phồn thể)": "疇", "Pinyin_Xie": "chóu", "Âm Hán Việt_Xie": "trù", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Làm danh từ chỉ ruộng đất hoặc phạm vi lĩnh vực khi kết hợp thành trù vực. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('刃', '{"9000": "2694.0", "Chữ Trung Quốc": "刃", "Bộ thủ & thành phần_Xie": "Bộ thủ | 刀 | Số nét | 3 | nét | 刃 | nhận | tượng hình | dao (刀) với nét chấm đánh dấu lưỡi sắc | 刃 là chữ chỉ sự (指事): lấy chữ 刀 (dao) rồi thêm nét nhấn (丿) vào phần lưỡi để chỉ rõ ''đây là lưỡi dao''. Không phải hình thanh, không phải hội ý — đây là phương pháp biểu ý bằng dấu hiệu.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nhận\": dao (刀) với nét chấm trên lưỡi — nét đó chính là nhận, lưỡi sắc bén. | Gương Hán-Việt | nhận trong 刃具 (nhận cụ — dụng cụ có lưỡi sắc) và 刀刃 (đao nhận — lưỡi dao) | Mở khoá kiến thức | Biết 刃 mở khoá: 刀刃 (lưỡi dao), 白刃 (lưỡi kiếm trần), 刃具 (dụng cụ cắt).", "Tự nguyên_Xie": "oracle | bronze | seal | liushutong | Theo Wiktionary, 刃 là chữ chỉ sự (指事): một con dao (刀) với nét nhấn đánh dấu vào lưỡi sắc. Nghĩa gốc: lưỡi dao; mở rộng sang ''sắc bén'' và ''giết chóc bằng lưỡi dao''. Xuất hiện từ giáp cốt văn với cấu trúc đơn giản. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1011.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Đao (022) Chủ (003)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Dấu chấm (Chủ) nằm ở trên lưỡi của chữ Đao (số 022 - con dao). Chỉ ý đây là mũi nhọn của con dao. Giải thích sự chuyển ý: Đây là chữ Chỉ sự. Nhận là mũi nhọn của lưỡi dao (huyết xuy mao nhận - máu dính đầu mũi dao).", "Nghĩa Tiếng Việt_Xie": "mũi nhọn", "Hạng Tần Suất (Jun Da)": "2694.0", "Tần Suất % (Jun Da)": "98.8144545918", "GavinGrover_Once (Chiết tự trực tiếp)": "刀 + 丶", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴刀丶", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "丶", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "刀", "Unihan_Simplified (Chữ Giản thể)": "刃", "Unihan_Traditional (Chữ Phồn thể)": "刃", "Pinyin_Xie": "rèn", "Âm Hán Việt_Xie": "nhận", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Làm danh từ chỉ phần sắc bén của dao kéo hoặc làm động từ với nghĩa giết bằng dao. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('遏', '{"9000": "2695.0", "Chữ Trung Quốc": "遏", "Bộ thủ & thành phần_Xie": "Bộ thủ | 辵 | Số nét | 12 | nét | 辶 | sước | biểu nghĩa | đi, di chuyển | 曷 | hạt | biểu âm | tại sao, khi nào | 遏 = 辶(Sước, biểu nghĩa: đi/di chuyển) + 曷 (Hạt, biểu âm); chữ hình thanh. Bộ sước chỉ hành động di chuyển, 曷 cho âm è.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"át\": đi (辶) mà bị hỏi tại sao (曷) — ngăn chặn người đang đi, kiểm tra, chặn đứng. | Gương Hán-Việt | \"át\" trong 遏制 (át chế — kiềm chế), 阻遏 (trở át — ngăn cản) | Mở khoá kiến thức | Biết 遏 mở khoá từ kiểm soát: 遏制 (át chế, kiềm chế), 阻遏 (trở át, ngăn cản), 遏止 (át chỉ, chặn đứng).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 遏 là chữ hình thanh: 辵 (đi) biểu nghĩa, 曷 biểu âm. Tiểu triện có dạng ghi chép. Nghĩa gốc là ngăn cản, dừng lại sự di chuyển. Từ đó mở rộng sang kiềm chế, ngăn chặn (遏制). Thành ngữ 响遏行云 (tiếng vang ngăn mây trời bay — ám chỉ giọng hát tuyệt vời). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ngăn cấm", "Hạng Tần Suất (Jun Da)": "2695.0", "Tần Suất % (Jun Da)": "98.8159269127", "GavinGrover_Once (Chiết tự trực tiếp)": "辶 + 曷", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴辶曷", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "曷", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "辶", "Unihan_Simplified (Chữ Giản thể)": "遏", "Unihan_Traditional (Chữ Phồn thể)": "遏", "Pinyin_Xie": "è", "Âm Hán Việt_Xie": "át", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này thường làm động từ đứng trước tân ngữ để chỉ hành động ngăn chặn hoặc kiềm chế. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('烁', '{"9000": "2696.0", "Chữ Trung Quốc": "烁", "Bộ thủ & thành phần_Xie": "Bộ thủ | 火 | Số nét | 9 | nét | 火 | hoả | biểu nghĩa | lửa | 乐 | lạc | biểu âm | vui vẻ | 烁 = 火 (Hoả, biểu nghĩa: lửa) + 乐 (Lạc, biểu âm); chữ hình thanh. Dạng phồn thể là 爍 (với 樂). Bộ hoả chỉ ánh sáng/lửa, 乐 cho âm shuò.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thước\": lửa (火) vui lạc (乐) nhấp nháy — ánh lửa vui vẻ thước thước, như sao nhấp nháy trên bầu trời. | Gương Hán-Việt | \"thước\" trong 闪烁 (thiểm thước — nhấp nháy, lấp lánh) | Mở khoá kiến thức | Biết 烁 mở khoá từ ánh sáng: 闪烁 (thiểm thước, nhấp nháy), 烁烁 (thước thước, lấp lánh).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 爍 (烁) là chữ hình thanh: 火 (lửa) biểu nghĩa, 樂 biểu âm. Tiểu triện có dạng ghi chép. Nghĩa gốc là sáng lấp lánh như lửa. Từ đó mở rộng sang nhấp nháy, lấp lánh. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sáng", "Hạng Tần Suất (Jun Da)": "2696.0", "Tần Suất % (Jun Da)": "98.8173982", "GavinGrover_Once (Chiết tự trực tiếp)": "火 + 乐", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰火乐", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "乐", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "火", "Unihan_Simplified (Chữ Giản thể)": "烁", "Unihan_Traditional (Chữ Phồn thể)": "爍", "Pinyin_Xie": "shuò", "Âm Hán Việt_Xie": "thước", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường dùng làm tính từ miêu tả ánh sáng lấp lánh hoặc kết hợp tạo thành từ ghép chỉ sự nhấp nháy. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('嗅', '{"9000": "2697.0", "Chữ Trung Quốc": "嗅", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 13 | nét | 口 | khẩu | biểu nghĩa | miệng, mũi (cơ quan cảm giác) | 臭 | xú | biểu âm | mùi hôi | 嗅 = 口 (Khẩu, biểu nghĩa: miệng/mũi) + 臭 (Xú, biểu âm); chữ hình thanh. Theo Wiktionary, dạng cổ là 齅 (bộ 鼻 — mũi), sau giản thành 嗅 (bộ 口). Bộ 口 gợi cơ quan cảm nhận, 臭 cho âm xiù.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khứu\": miệng/mũi (口) đón mùi xú (臭) — khứu giác là giác quan nhận biết mùi thơm hay hôi. | Gương Hán-Việt | \"khứu\" trong 嗅觉 (khứu giác — khứu giác), 嗅神经 (khứu thần kinh — thần kinh khứu giác) | Mở khoá kiến thức | Biết 嗅 mở khoá từ giải phẫu/cảm giác: 嗅觉 (khứu giác), 嗅神经 (thần kinh khứu giác), 嗅腺 (tuyến mùi).", "Tự nguyên_Xie": "Theo Wiktionary, 嗅 là dạng giản hoá của 齅 (với bộ 鼻 — mũi biểu nghĩa). Trong dạng hiện đại là hình thanh: 口 biểu nghĩa, 臭 biểu âm. Nghĩa gốc là ngửi, dùng mũi nhận biết mùi. Không thấy giáp cốt hay kim văn riêng. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ngửi (mùi)", "Hạng Tần Suất (Jun Da)": "2697.0", "Tần Suất % (Jun Da)": "98.8188674201", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 臭", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口臭", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "臭", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "嗅", "Unihan_Traditional (Chữ Phồn thể)": "嗅", "Pinyin_Xie": "xiù", "Âm Hán Việt_Xie": "khứu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước danh từ chỉ mùi vị hoặc cảm giác để thể hiện hành động ngửi. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('叭', '{"9000": "2698.0", "Chữ Trung Quốc": "叭", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 5 | nét | 口 | khẩu | biểu nghĩa | miệng | 八 | bát | biểu âm | tám | 叭 = 口 (Khẩu, biểu nghĩa: miệng) + 八 (Bát, biểu âm). Wiktionary không có anchor Etymology cho 叭. Dựa trên cấu trúc là hình thanh: 口 biểu nghĩa, 八 biểu âm cho bā. Thường dùng ghép 喇叭 (kèn, loa). Chưa có nguồn học thuật đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bá\": miệng (口) hở ra như số tám (八) chia đôi — tiếng kèn bá bá từ miệng loa phát ra. | Gương Hán-Việt | \"bá\" trong 喇叭 (lạt bá — kèn, loa phóng thanh) | Mở khoá kiến thức | Biết 叭 mở khoá từ âm thanh: 喇叭 (lạt bá, kèn/loa), 哑叭 (á bá, câm).", "Tự nguyên_Xie": "Wiktionary không có anchor Etymology cho 叭. Dựa trên cấu trúc có thể đọc là hình thanh: 口 (miệng) biểu nghĩa, 八 biểu âm cho bā. Chữ này chủ yếu dùng trong từ ghép 喇叭 (kèn, loa phóng thanh). Chưa có nguồn học thuật đầy đủ. | Theo Wiktionary · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: lạt bá 唰叭)", "Hạng Tần Suất (Jun Da)": "2698.0", "Tần Suất % (Jun Da)": "98.8203361235", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 八", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口八", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "八", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "叭", "Unihan_Traditional (Chữ Phồn thể)": "叭", "Pinyin_Xie": "bā", "Âm Hán Việt_Xie": "bá", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Từ tượng thanh | 象声词 | Danh từ | 名词 | Thường dùng làm từ tượng thanh mô tả tiếng động hoặc kết hợp tạo danh từ chỉ cái loa. | Từ tượng thanh | 象声词 | Mô phỏng âm thanh: 哗哗, 汪汪. Có thể làm định ngữ, trạng ngữ hoặc đứng độc lập. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('熬', '{"9000": "2699.0", "Chữ Trung Quốc": "熬", "Bộ thủ & thành phần_Xie": "Bộ thủ | 火 | Số nét | 14 | nét | 敖 | ngao | biểu âm | ngao du — cho âm ngao | 灬 | hoả | biểu nghĩa | lửa (dạng biến thể bên dưới) | 熬 = 敖 (Ngao, biểu âm) + 灬 (Hoả, biểu nghĩa: lửa). Wiktionary không ghi ls code cụ thể. Cấu trúc gợi ý hình thanh: 灬 (lửa) biểu nghĩa nấu sắc; 敖 cho âm áo/ngao. Nấu nhừ bằng lửa lâu.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ngao\": ngao du (敖) qua lửa (灬) — nấu lửa âm ỉ lâu giờ như cuộc ngao du dài. Ngao = ninh lâu, chịu đựng. | Gương Hán-Việt | ngao trong ''ngao du'' — cùng âm; 熬 dùng cho việc nấu lửa nhỏ lâu, hoặc chịu đựng | Mở khoá kiến thức | Biết 熬 mở khoá: 熬夜 (ngao dạ – thức khuya), 煎熬 (tiên ngao – giày vò, đau khổ), 熬药 (ngao dược – sắc thuốc).", "Tự nguyên_Xie": "熬 gồm 敖 (ngao) phần trên và 灬 (biến thể của 火 – lửa) phần dưới. Wiktionary không có glyphOrigin chi tiết. Cấu trúc gợi ý: dùng lửa (灬) nấu lâu giống như ngao du (敖) không vội vã. Nghĩa là ninh nhừ, sắc thuốc, chịu đựng lâu dài (熬夜 – thức khuya). Chưa có nguồn học thuật đầy đủ về glyphOrigin. | Theo Wiktionary · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nấu, ninh, sắc, rang khô", "Hạng Tần Suất (Jun Da)": "2699.0", "Tần Suất % (Jun Da)": "98.82180431", "GavinGrover_Once (Chiết tự trực tiếp)": "敖 + 灬", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱敖灬", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "敖", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "灬", "Unihan_Simplified (Chữ Giản thể)": "熬", "Unihan_Traditional (Chữ Phồn thể)": "熬", "Pinyin_Xie": "áo", "Âm Hán Việt_Xie": "ngao", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Làm động từ đứng trước danh từ chỉ món ăn, thuốc bắc hoặc dùng nghĩa bóng để chỉ sự chịu đựng gian khổ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | áo | / | nấu nhừ | Xuất hiện trong lộ trình | HSK | HSK 6 | · | Thức ăn và đồ uống | New HSK | New HSK 7-9 | · | Thức ăn tôi", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('瞥', '{"9000": "2700.0", "Chữ Trung Quốc": "瞥", "Bộ thủ & thành phần_Xie": "Bộ thủ | 目 | Số nét | 16 | nét | 敝 | tệ | biểu âm | cũ nát — cho âm piē | 目 | mục | biểu nghĩa | mắt — chỉ hành động nhìn | 瞥 = 敝 (Tệ, biểu âm) + 目 (Mục, biểu nghĩa: mắt); chữ hình thanh. Phần âm 敝 cho âm piē, bộ 目 cho biết liên quan đến thị giác — cái nhìn thoáng qua, liếc nhanh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"miết\": mắt (目) nhìn theo kiểu cũ nát (敝) — liếc vội một cái rồi thôi, miết qua. | Gương Hán-Việt | miết trong 瞥见 (miết kiến — thoáng thấy) | Mở khoá kiến thức | Biết 瞥 mở khoá: 瞥见 (thoáng thấy), 一瞥 (một cái liếc nhanh).", "Tự nguyên_Xie": "seal | liushutong | Theo Wiktionary, 瞥 là chữ hình thanh (形聲): 目 (mắt) biểu nghĩa, 敝 biểu âm. Nghĩa duy nhất: nhìn thoáng qua, liếc nhanh rồi quay đi. Xuất hiện trong trung cổ tiếng Hán. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "liếc mắt qua", "Hạng Tần Suất (Jun Da)": "2700.0", "Tần Suất % (Jun Da)": "98.8232719798", "GavinGrover_Once (Chiết tự trực tiếp)": "敝 + 目", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱敝目", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "敝", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "目", "Unihan_Simplified (Chữ Giản thể)": "瞥", "Unihan_Traditional (Chữ Phồn thể)": "瞥", "Pinyin_Xie": "piē", "Âm Hán Việt_Xie": "miết", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước tân ngữ để diễn tả hành động nhìn lướt qua rất nhanh. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('骸', '{"9000": "2701.0", "Chữ Trung Quốc": "骸", "Bộ thủ & thành phần_Xie": "Bộ thủ | 骨 | Số nét | 15 | nét | 骨 | cốt | biểu nghĩa | xương — chỉ cấu trúc xương | 亥 | hợi | biểu âm | hợi (chi thứ 12) — cho âm hái | 骸 = 骨 (Cốt, biểu nghĩa: xương) + 亥 (Hợi, biểu âm); chữ hình thanh. Bộ 骨 chỉ liên quan đến xương cốt, 亥 cho âm hái. Nghĩa: xương cốt, thi thể (thường dùng trong 骸骨 — hài cốt).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hài\": xương (骨) mang dấu hợi (亥) — hài cốt, những gì còn lại sau khi chết. | Gương Hán-Việt | hài trong 骸骨 (hài cốt — xương người đã khuất) | Mở khoá kiến thức | Biết 骸 mở khoá: 骸骨 (hài cốt), 形骸 (hình hài — thân xác), 遗骸 (di hài).", "Tự nguyên_Xie": "seal | liushutong | Theo Wiktionary (Digital Shinjigen 2017), 骸 là chữ hình thanh (形聲): 骨 (cốt — xương) biểu nghĩa, 亥 biểu âm. Nghĩa gốc và nghĩa hiện tại đều chỉ xương cốt của thi hài. Thường xuất hiện trong 骸骨 (hài cốt — xương còn lại sau khi chết). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "xương đùi; hình hài", "Hạng Tần Suất (Jun Da)": "2701.0", "Tần Suất % (Jun Da)": "98.8247375825", "GavinGrover_Once (Chiết tự trực tiếp)": "骨 + 亥", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰骨亥", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "亥", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "骨", "Unihan_Simplified (Chữ Giản thể)": "骸", "Unihan_Traditional (Chữ Phồn thể)": "骸", "Pinyin_Xie": "hái", "Âm Hán Việt_Xie": "hài", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng độc lập hoặc kết hợp trong các từ ghép để chỉ xương cốt hoặc thể xác. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('奢', '{"9000": "2702.0", "Chữ Trung Quốc": "奢", "Bộ thủ & thành phần_Xie": "Bộ thủ | 大 | Số nét | 11 | nét | 大 | đại | biểu nghĩa | lớn, vĩ đại | 者 | giả | biểu âm | người, kẻ | 奢 = 大 (Đại, biểu nghĩa: lớn/thái quá) + 者 (Giả, biểu âm); chữ hình thanh. Theo Wiktionary không có phân tích ls chi tiết. Dựa trên cấu trúc, bộ 大 gợi ý quá mức, 者 cho âm shē. Nghĩa là xa hoa, phung phí, quá đỗi.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"xa\": kẻ (者) lớn (大) tiêu xài — xa hoa phung phí là người tiêu xài quá mức lớn lao. | Gương Hán-Việt | \"xa\" trong 奢侈 (xa xỉ — xa hoa), 奢望 (xa vọng — ước muốn xa vời) | Mở khoá kiến thức | Biết 奢 mở khoá từ lối sống: 奢侈 (xa xỉ, xa hoa), 奢望 (xa vọng, ước muốn quá cao), 奢华 (xa hoa, sang trọng).", "Tự nguyên_Xie": "Tiểu triện | Wiktionary không có phân tích hình thanh/hội ý chi tiết cho 奢 trong anchor. Dựa trên cấu trúc là hình thanh: 大 (lớn) gợi ý quá mức, 者 biểu âm. Tiểu triện có dạng. Nghĩa gốc là xa xỉ, phung phí. Từ đó mở rộng sang quá đỗi, ước muốn xa vời. Chưa có nguồn học thuật đầy đủ. | Theo Wiktionary · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "xa xỉ; quá đỗi, nhiều", "Hạng Tần Suất (Jun Da)": "2702.0", "Tần Suất % (Jun Da)": "98.8262026683", "GavinGrover_Once (Chiết tự trực tiếp)": "大 + 者", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱大者", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "者", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "大", "Unihan_Simplified (Chữ Giản thể)": "奢", "Unihan_Traditional (Chữ Phồn thể)": "奢", "Pinyin_Xie": "shē", "Âm Hán Việt_Xie": "xa", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường làm tính từ đứng trước danh từ hoặc kết hợp thành từ ghép để chỉ sự xa xỉ, lãng phí. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('拙', '{"9000": "2703.0", "Chữ Trung Quốc": "拙", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 8 | nét | 扌 | thủ | biểu nghĩa | tay | 出 | xuất | biểu âm | ra ngoài | 拙 = 扌(Thủ, biểu nghĩa: tay) + 出 (Xuất, biểu âm); chữ hình thanh. Bộ thủ chỉ kỹ năng tay, 出 cho âm zhuō. Nghĩa là vụng về, kém khéo tay.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chuyết\": tay (扌) làm ra (出) kết quả vụng — tay xuất kém, vụng về không khéo léo. | Gương Hán-Việt | \"chuyết\" trong 笨拙 (bản chuyết — vụng về, thô kệch), 拙劣 (chuyết liệt — vụng về, kém cỏi) | Mở khoá kiến thức | Biết 拙 mở khoá từ kỹ năng: 笨拙 (bản chuyết, vụng về), 拙劣 (chuyết liệt, kém cỏi), 守拙 (thủ chuyết, giữ chất thực thà).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Theo Wiktionary, 拙 là chữ hình thanh: 手 (tay, bộ 扌) biểu nghĩa, 出 biểu âm. Tiểu triện và Lục thư thông có dạng phong phú. Nghĩa gốc là vụng tay, không khéo léo. Từ đó mở rộng sang thô thiển, chậm chạp về trí tuệ. Trong tiếng Hán cổ cũng dùng 拙 để tự khiêm: 拙作 (tác phẩm vụng của tôi). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "vụng về", "Hạng Tần Suất (Jun Da)": "2703.0", "Tần Suất % (Jun Da)": "98.8276667206", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 出", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌出", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "出", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "拙", "Unihan_Traditional (Chữ Phồn thể)": "拙", "Pinyin_Xie": "zhuō", "Âm Hán Việt_Xie": "chuyết", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường làm tính từ bổ nghĩa cho danh từ hoặc làm vị ngữ để chỉ sự vụng về, thiếu khéo léo. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('栋', '{"9000": "2704.0", "Chữ Trung Quốc": "栋", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 9 | nét | 木 | mộc | biểu nghĩa | gỗ, cây | 东 | đông | biểu âm | phía đông | 栋 = 木 (Mộc, biểu nghĩa: gỗ/cây) + 东 (Đông, biểu âm); chữ hình thanh. Giản thể của 棟 (thay 東 bằng 东). Bộ mộc chỉ vật liệu gỗ, 东 cho âm dòng. Nghĩa là xà nóc, cột chính chịu lực.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đống\": gỗ (木) hướng đông (东) đỡ mái — xà đống là thanh gỗ chính ở đỉnh mái nhà, trụ cột cả ngôi nhà. | Gương Hán-Việt | \"đống\" trong 栋梁 (đống lương — trụ cột, nhân tài kiệt xuất), 一栋楼 (nhất đống lâu — một tòa nhà) | Mở khoá kiến thức | Biết 栋 mở khoá từ kiến trúc: 栋梁 (đống lương, nhân tài trụ cột), 一栋 (lượng từ đếm nhà), 主栋 (trụ đống, xà chính).", "Tự nguyên_Xie": "Tiểu triện | 栋 là dạng giản thể của 棟 (đống). Wiktionary chỉ ghi giản thể của 棟, không có phân tích ls riêng. Tiểu triện có dạng. Theo cấu trúc truyền thống, 棟 là hình thanh: 木 (gỗ) biểu nghĩa, 東 biểu âm. Nghĩa gốc là xà chính (main beam) chống đỡ mái nhà, sau mở rộng thành lượng từ đếm nhà (一栋楼 — một tòa nhà). | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái cột", "Hạng Tần Suất (Jun Da)": "2704.0", "Tần Suất % (Jun Da)": "98.8291292225", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 东", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木东", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "东", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "栋", "Unihan_Traditional (Chữ Phồn thể)": "棟", "Pinyin_Xie": "dòng", "Âm Hán Việt_Xie": "đống", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Lượng từ | 量词 | Danh từ | 名词 | Thường dùng làm lượng từ đứng trước danh từ chỉ tòa nhà hoặc làm danh từ chỉ rường cột. | Lượng từ | 量词 | Đứng giữa số từ (hoặc 这/那) và danh từ: 一杯茶, 这本书. Mỗi danh từ đi với lượng từ riêng; 个 là lượng từ dùng chung phổ biến nhất. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | dòng | / | căn (đơn vị đo nhà) | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Вuildings và công trình xây dựng | HSK | HSK 6 | · | Địa điểm", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('毯', '{"9000": "2705.0", "Chữ Trung Quốc": "毯", "Bộ thủ & thành phần_Xie": "Bộ thủ | 毛 | Số nét | 12 | nét | 毛 | mao | biểu nghĩa | lông, sợi lông | 炎 | viêm | biểu âm | lửa bùng — cho âm viêm/thảm | 毯 = 毛 (Mao, biểu nghĩa: lông) + 炎 (Viêm, biểu âm); chữ hình thanh. Wiktionary ghi: {{Han compound|毛|炎|ls=psc|c1=s|c2=p}}. Bộ mao chỉ chất liệu lông sợi; 炎 cho âm tǎn (gần thảm). Thảm/đệm được dệt từ sợi lông.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thảm\": lông (毛-Mao) bùng viêm (炎-Viêm) — lông ấm áp như tấm thảm. Thảm = tấm thảm lông. | Gương Hán-Việt | thảm trong ''thảm họa, thảm khốc'' — cùng âm; 毯 chỉ tấm thảm/chăn, không liên quan thảm họa | Mở khoá kiến thức | Biết 毯 mở khoá: 地毯 (địa thảm – tấm thảm), 毯子 (thảm tử – chăn đệm), 毛毯 (mao thảm – chăn lông).", "Tự nguyên_Xie": "毯 là chữ hình thanh: 毛 (mao – lông, sợi lông) biểu nghĩa, 炎 (viêm) biểu âm. Wiktionary xác nhận cấu trúc psc. Nghĩa là tấm thảm, chăn đệm dệt từ sợi lông động vật. Âm tǎn trong tiếng Trung gần với 炎 (yán→tǎn). Từ thông dụng: 地毯 (địa thảm – tấm thảm sàn). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "143.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Mao (38) Viêm (142)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Viêm (số 142) nằm trong chữ Mao (số 38) . Đệm làm bằng lông (Mao) giúp làm ấm cơ thể (Viêm). Giải thích sự chuyển ý: Chữ Viêm (lửa cháy) chỉ âm, chữ Mao (lông) chỉ ý. Tấm thảm (Thảm) làm bằng lông thú (Mao) mang lại cảm giác ấm áp như ngọn lửa (Viêm). *(Biến âm Hán Việt: Trong Hán ngữ cổ, chữ Viêm và chữ Thảm có cách phát âm tương đồng hoặc chung gốc phụ âm. Quá trình Việt hóa đã làm âm đọc bị chênh lệch thành Viêm và Thảm).*", "Nghĩa Tiếng Việt_Xie": "cái đệm lông", "Hạng Tần Suất (Jun Da)": "2705.0", "Tần Suất % (Jun Da)": "98.8305901741", "GavinGrover_Once (Chiết tự trực tiếp)": "毛 + 炎", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴毛炎", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "炎", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "毛", "Unihan_Simplified (Chữ Giản thể)": "毯", "Unihan_Traditional (Chữ Phồn thể)": "毯", "Pinyin_Xie": "tǎn", "Âm Hán Việt_Xie": "thảm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng sau lượng từ hoặc kết hợp với các từ khác để chỉ các loại thảm. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('桐', '{"9000": "2706.0", "Chữ Trung Quốc": "桐", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 10 | nét | 木 | mộc | biểu nghĩa | cây, gỗ — chỉ loại cây | 同 | đồng | biểu âm | cùng nhau — cho âm tóng | 桐 = 木 (Mộc, biểu nghĩa: cây) + 同 (Đồng, biểu âm); chữ hình thanh. Bộ 木 chỉ đây là tên một loài cây, 同 cho âm tóng. Nghĩa: cây ngô đồng (梧桐), cây cọ dầu tung.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đồng\": cây (木) cùng (同) nhau mọc thành hàng — cây ngô đồng, nơi phượng hoàng tìm đến. | Gương Hán-Việt | đồng trong 梧桐 (ngô đồng — cây thiêng gắn với phượng hoàng) | Mở khoá kiến thức | Biết 桐 mở khoá: 梧桐 (ngô đồng), 油桐 (tung — cây lấy dầu), 桐油 (dầu tung).", "Tự nguyên_Xie": "seal | liushutong | Theo Wiktionary, 桐 là chữ hình thanh (形聲): 木 (mộc — cây) biểu nghĩa, 同 biểu âm. Nghĩa gốc chỉ cây ngô đồng (梧桐 Firmiana simplex) — loài cây thiêng trong văn hóa Hoa Hạ, nơi phượng hoàng đậu. Cũng chỉ cây tung (油桐) lấy dầu. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "397.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Mộc (108) Đồng (93)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Mộc (số 79 - cây gỗ) và chữ Đồng (số 184 - cùng nhau) . Đồng là tên một loài cây quý, gỗ thường dùng làm đàn (cây ngô đồng). Giải thích sự chuyển ý: Chữ Đồng (cùng nhau) chỉ âm, chữ Mộc (gỗ) chỉ ý. Tên một loài cây (Mộc) đặc biệt gọi là ngô đồng (Đồng).", "Nghĩa Tiếng Việt_Xie": "(xem: ngô đồng 梧桐)", "Hạng Tần Suất (Jun Da)": "2706.0", "Tần Suất % (Jun Da)": "98.832048025", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 同", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木同", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "同", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "桐", "Unihan_Traditional (Chữ Phồn thể)": "桐", "Pinyin_Xie": "tóng", "Âm Hán Việt_Xie": "đồng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng độc lập hoặc kết hợp để chỉ cây ngô đồng hoặc các loại cây thân gỗ tương tự. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('砂', '{"9000": "2707.0", "Chữ Trung Quốc": "砂", "Bộ thủ & thành phần_Xie": "Bộ thủ | 石 | Số nét | 9 | nét | 石 | thạch | biểu nghĩa | đá — chỉ chất liệu khoáng | 少 | thiểu | biểu âm | ít — rút gọn từ 沙, cho âm shā | 砂 = 石 (Thạch, biểu nghĩa: đá) + 少 (Thiểu, biểu âm rút gọn từ 沙); chữ hình thanh. Ban đầu là biến thể của 沙 (cát ven sông), sau được viết với bộ 石 để nhấn mạnh chất liệu khoáng vật. Nghĩa: cát, hạt thạch nhỏ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sa\": đá (石) nhỏ li ti ít ỏi (少) — sa mạc, cát sỏi. | Gương Hán-Việt | sa trong 砂糖 (sa đường — đường cát) và 金砂 (kim sa — cát vàng) | Mở khoá kiến thức | Biết 砂 mở khoá: 砂糖 (đường cát), 砂锅 (nồi đất), 砂纸 (giấy nhám).", "Tự nguyên_Xie": "Theo Wiktionary, 砂 là chữ hình thanh (形聲): 石 (thạch — đá) biểu nghĩa, 沙 rút gọn thành 少 biểu âm. Nguyên gốc là biến thể của 沙 — chữ tượng hình mô tả cát ven bờ sông. Khi thêm bộ 石 thì nhấn mạnh tính khoáng vật hơn. Hai chữ 砂 và 沙 hiện vẫn thay thế nhau trong nhiều từ. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đá vụn, sỏi vụn; cát, sạn", "Hạng Tần Suất (Jun Da)": "2707.0", "Tần Suất % (Jun Da)": "98.833505359", "GavinGrover_Once (Chiết tự trực tiếp)": "石 + 少", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰石少", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "少", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "石", "Unihan_Simplified (Chữ Giản thể)": "砂", "Unihan_Traditional (Chữ Phồn thể)": "砂", "Pinyin_Xie": "shā", "Âm Hán Việt_Xie": "sa", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này thường làm danh từ đứng độc lập hoặc kết hợp để chỉ các loại cát và khoáng sản dạng hạt. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('莽', '{"9000": "2708.0", "Chữ Trung Quốc": "莽", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 10 | nét | 艹 | thảo | biểu nghĩa | cỏ — chỉ thực vật hoang dại | 犬 | khuyển | biểu nghĩa/biểu âm | chó — gợi nghĩa hoang dã hoặc cho âm | 廾 | củng | biểu hình | hai tay | 莽 là chữ vừa hình thanh vừa hội ý (theo hai học giả): 茻 (thảo — cỏ rậm) + 犬 (khuyển — chó). Nhìn theo hội ý: chó chạy trong bụi cỏ um tùm → hoang dã, liều lĩnh. Nhìn theo hình thanh: 茻 cho âm mǎng. Nghĩa: cỏ rậm, hoang vu; bộp chộp, liều lĩnh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mãng\": cỏ (艹) rậm có chó (犬) chạy vào — vùng hoang mãng, hành động mãng muội, bộp chộp. | Gương Hán-Việt | mãng trong 鲁莽 (lỗ mãng — bộp chộp, hấp tấp) và 莽撞 (mãng chàng — liều lĩnh) | Mở khoá kiến thức | Biết 莽 mở khoá: 鲁莽 (bộp chộp), 莽撞 (liều lĩnh), 莽原 (thảo nguyên rộng lớn).", "Tự nguyên_Xie": "oracle | bronze | seal | liushutong | Theo Wiktionary, 莽 có hai cách phân tích: (1) hình thanh — 茻 biểu âm, 犬 biểu nghĩa (Li Xueqin 2012); (2) hội ý — cả 茻 (cỏ rậm) và 犬 (chó) cùng biểu nghĩa, hình ảnh chó lao vào bụi rậm. Nghĩa gốc: vùng cỏ rậm rạp, hoang vu; mở rộng sang tính cách bộp chộp, liều lĩnh không suy nghĩ. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cỏ mọc rậm, bụi cỏ; lớn, to; lỗ mãng, thô lỗ", "Hạng Tần Suất (Jun Da)": "2708.0", "Tần Suất % (Jun Da)": "98.834960626", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "莽", "Unihan_Traditional (Chữ Phồn thể)": "莽", "Pinyin_Xie": "mǎng", "Âm Hán Việt_Xie": "mãng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Chữ này thường làm tính từ bổ nghĩa cho danh từ hoặc kết hợp thành từ ghép chỉ sự thô lỗ, hoang dã. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('泻', '{"9000": "2709.0", "Chữ Trung Quốc": "泻", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 8 | nét | 氵 | thuỷ | biểu nghĩa | nước | 写 | tả | biểu âm | viết | 泻 = 氵(Thuỷ, biểu nghĩa: nước) + 写 (Tả, biểu âm); chữ hình thanh. Dạng phồn thể là 瀉. Bộ thuỷ chỉ nước chảy, 写 cho âm xiè.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tả\": nước (氵) chảy ra khi tả (写) vội — như nước đổ xuống dốc, không kìm được. | Gương Hán-Việt | \"tả\" trong 腹泻 (phúc tả — tiêu chảy), 泻药 (tả dược — thuốc nhuận tràng) | Mở khoá kiến thức | Biết 泻 mở khoá từ y tế và địa hình: 腹泻 (phúc tả, tiêu chảy), 泻药 (tả dược, thuốc nhuận tràng), 一泻千里 (nhất tả thiên lý, chảy xuống ngàn dặm).", "Tự nguyên_Xie": "Theo Wiktionary, 泻 là chữ hình thanh: 水 (nước, bộ 氵) biểu nghĩa, 写 biểu âm. Nghĩa gốc là nước chảy mạnh, đổ xuống. Từ đó mở rộng sang tiêu chảy (腹泻). Chưa thấy dạng giáp cốt hay kim văn riêng. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "dòng nước", "Hạng Tần Suất (Jun Da)": "2709.0", "Tần Suất % (Jun Da)": "98.8364158929", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 写", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵写", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "写", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "泻", "Unihan_Traditional (Chữ Phồn thể)": "瀉", "Pinyin_Xie": "xiè", "Âm Hán Việt_Xie": "tả", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước tân ngữ để chỉ dòng nước chảy mạnh hoặc hiện tượng tiêu chảy. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | xiè | / | chảy ra | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Words II", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('坪', '{"9000": "2710.0", "Chữ Trung Quốc": "坪", "Bộ thủ & thành phần_Xie": "Bộ thủ | 土 | Số nét | 8 | nét | 土 | thổ | biểu nghĩa | đất — chỉ mặt đất, địa hình | 平 | bình | biểu âm | bằng phẳng — cho âm píng | 坪 = 土 (Thổ, biểu nghĩa: đất) + 平 (Bình, biểu âm); chữ hình thanh. Bộ 土 chỉ liên quan đến địa hình, 平 cho âm píng. Nghĩa: vùng đất bằng phẳng, bãi cỏ; đơn vị diện tích đất (ở Nhật/Đài Loan).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bình\": đất (土) bằng phẳng (平) — bãi cỏ bình thản, mặt bằng rộng rãi. | Gương Hán-Việt | bình trong 草坪 (thảo bình — bãi cỏ) và 坪坝 (bình bá — vùng đất bằng) | Mở khoá kiến thức | Biết 坪 mở khoá: 草坪 (bãi cỏ), 坪坝 (bình nguyên nhỏ), 停车坪 (bãi đỗ xe).", "Tự nguyên_Xie": "seal | liushutong | Theo Wiktionary, 坪 là chữ hình thanh (形聲): 土 (thổ — đất) biểu nghĩa, 平 biểu âm. Nghĩa gốc: mảnh đất phẳng, đồng bằng nhỏ. Cũng dùng như đơn vị đo diện tích (~3.3 m²) trong tiếng Nhật và Đài Loan. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chỗ đất bằng phẳng", "Hạng Tần Suất (Jun Da)": "2710.0", "Tần Suất % (Jun Da)": "98.8378706431", "GavinGrover_Once (Chiết tự trực tiếp)": "土 + 平", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰土平", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "平", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "土", "Unihan_Simplified (Chữ Giản thể)": "坪", "Unihan_Traditional (Chữ Phồn thể)": "坪", "Pinyin_Xie": "píng", "Âm Hán Việt_Xie": "bình", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng sau các từ chỉ địa điểm hoặc loại cỏ để cấu tạo danh từ ghép. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('梳', '{"9000": "2711.0", "Chữ Trung Quốc": "梳", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 11 | nét | 木 | mộc | biểu nghĩa | gỗ | 㐬 | sơ | biểu âm | dạng giản của 疏 (thưa, lùa) | 梳 = 木 (Mộc, biểu nghĩa: gỗ — cái lược gỗ) + 㐬 (biểu âm, dạng giản của 疏); chữ hình thanh. Cái lược bằng gỗ để lùa tóc, gốc nghĩa ''lược, chải tóc''.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sơ\": 木 (gỗ) + 㐬 (giản từ 疏 — lùa tóc) — cái lược gỗ chải lùa tóc, đúng nghĩa ''lược, chải'' trong 梳子 (lược), 梳理 (chải gỡ). | Gương Hán-Việt | ''sơ'' trong ''sơ tóc'', ''sơ lược'' (gần nghĩa) | Mở khoá kiến thức | Nắm 梳 mở khoá loạt từ HSK 5-7: 梳, 梳子, 梳理.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Theo Wiktionary, 梳 là hình thanh: 木 (gỗ, biểu nghĩa — cái lược gỗ) + 疏 (biểu âm, viết tắt thành 㐬). Phần biểu âm 疏 mang nghĩa ''thưa, lùa'' nên cũng hỗ trợ nghĩa: dùng cái lược lùa tóc. Nghĩa ''lược, chải'' giữ nguyên trong 梳, 梳子, 梳理. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "866.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Mộc (075) Lưu (864)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Mộc (số 075 - gỗ) ở bên trái chữ Lưu (số 864 - dải cờ/chỉ âm). Cái lược gỗ dùng để chải tóc khiến mái tóc dài óng mượt phất phơ (Lưu). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Lưu chỉ âm, bộ Mộc chỉ ý. Sơ là cái lược chải tóc.", "Nghĩa Tiếng Việt_Xie": "cái lược; chải (tóc)", "Hạng Tần Suất (Jun Da)": "2711.0", "Tần Suất % (Jun Da)": "98.8393207422", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 㐬", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木㐬", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "㐬", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "梳", "Unihan_Traditional (Chữ Phồn thể)": "梳", "Pinyin_Xie": "shū", "Âm Hán Việt_Xie": "sơ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường làm động từ mang tân ngữ chỉ tóc hoặc làm danh từ chỉ dụng cụ chải đầu. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | shū | / | chải | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Vẻ bề ngoài", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('杉', '{"9000": "2712.0", "Chữ Trung Quốc": "杉", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 7 | nét | 木 | mộc | biểu nghĩa | cây, gỗ — chỉ loài cây | 彡 | sam | biểu âm | ba nét lông — cho âm shān | 杉 = 木 (Mộc, biểu nghĩa: cây) + 彡 (Sam, biểu âm); chữ hình thanh. Bộ 木 chỉ đây là tên cây, 彡 cho âm shān/shā. Chữ 彡 cũng gợi hình ảnh những cành lá rủ xuống của cây sam/tùng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sam\": cây (木) với những nét lông (彡) — cây sam thẳng tắp, lá nhọn như bút lông. | Gương Hán-Việt | sam trong 杉木 (sam mộc — gỗ sam) và 水杉 (thuỷ sam — cây thủy sam) | Mở khoá kiến thức | Biết 杉 mở khoá: 杉木 (gỗ sam), 水杉 (thủy sam), 红杉 (sam đỏ — redwood).", "Tự nguyên_Xie": "Theo Wiktionary, 杉 là chữ hình thanh (形聲): 木 (mộc — cây) biểu nghĩa, 彡 biểu âm. Nghĩa: cây sam (杉木 — Cunninghamia lanceolata), loại cây lấy gỗ quan trọng ở miền nam Trung Quốc. Cũng đọc shā trong một số từ. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cây sam (một loài giống cây thông)", "Hạng Tần Suất (Jun Da)": "2712.0", "Tần Suất % (Jun Da)": "98.8407703245", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 彡", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木彡", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "彡", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "杉", "Unihan_Traditional (Chữ Phồn thể)": "杉", "Pinyin_Xie": "shān", "Âm Hán Việt_Xie": "sam", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng độc lập hoặc kết hợp với các từ khác để chỉ loài cây thuộc họ thông. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('晤', '{"9000": "2713.0", "Chữ Trung Quốc": "晤", "Bộ thủ & thành phần_Xie": "Bộ thủ | 日 | Số nét | 11 | nét | 日 | nhật | biểu nghĩa | mặt trời, ngày, sáng | 吾 | ngô | biểu âm | ta, tôi | 晤 = 日 (Nhật, biểu nghĩa: mặt trời/sáng) + 吾 (Ngô, biểu âm); chữ hình thanh. Bộ nhật gợi ánh sáng, gặp mặt trong sáng, 吾 cho âm wù. Nghĩa là gặp gỡ, hội ngộ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ngộ\": ngày sáng (日) tôi (吾) gặp mặt — ngộ diện là khoảnh khắc hai người gặp nhau trong sáng tỏ. | Gương Hán-Việt | \"ngộ\" trong 会晤 (hội ngộ — hội đàm, gặp gỡ), 晤面 (ngộ diện — gặp mặt) | Mở khoá kiến thức | Biết 晤 mở khoá từ ngoại giao: 会晤 (hội ngộ, hội đàm), 晤面 (ngộ diện, gặp mặt), 晤谈 (ngộ đàm, nói chuyện trực tiếp).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Wiktionary không có phân tích ls chi tiết cho 晤. Tiểu triện và Lục thư thông có dạng ghi chép. Dựa trên cấu trúc là hình thanh: 日 (mặt trời) biểu nghĩa gợi sáng tỏ/gặp mặt, 吾 biểu âm. Nghĩa gốc là gặp mặt, hội đàm. Từ đó mở rộng sang hội ngộ trang trọng (会晤 — hội đàm cấp cao). Chưa có nguồn học thuật đầy đủ. | Theo Wiktionary · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "gặp, đối mặt nhau; sáng", "Hạng Tần Suất (Jun Da)": "2713.0", "Tần Suất % (Jun Da)": "98.8422199068", "GavinGrover_Once (Chiết tự trực tiếp)": "日 + 吾", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰日吾", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "吾", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "日", "Unihan_Simplified (Chữ Giản thể)": "晤", "Unihan_Traditional (Chữ Phồn thể)": "晤", "Pinyin_Xie": "wù", "Âm Hán Việt_Xie": "ngộ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ trong văn viết trang trọng để chỉ việc gặp gỡ và đàm thoại. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('稚', '{"9000": "2714.0", "Chữ Trung Quốc": "稚", "Bộ thủ & thành phần_Xie": "Bộ thủ | 禾 | Số nét | 13 | nét | 禾 | hoà | biểu nghĩa | lúa, ngũ cốc | 隹 | chuy | biểu âm | chim đuôi ngắn (thay thế cho 屖 từ thời Hán) | 稚 = 禾 (Hoà, biểu nghĩa: lúa non) + 隹 (Chuy, biểu âm; nguyên bản là 屖, bị thay thế vào thời Hán). Chữ hình thanh — 禾 chỉ nghĩa lúa/cây non, 隹 cho âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trĩ\": cây lúa (禾) còn non như con chim (隹) mới ra ràng — hình ảnh sự non nớt, ấu thơ. | Gương Hán-Việt | \"trĩ\" trong \"ấu trĩ\" (non nớt, ngây thơ) | Mở khoá kiến thức | Biết 稚 (trĩ) mở khoá: 幼稚 (ấu trĩ — trẻ con, ngây thơ), 稚嫩 (trĩ nộn — non nớt).", "Tự nguyên_Xie": "Tiểu triện | Chữ hình thanh. Theo Wiktionary, 稚 nguyên là 禾 (lúa) + 屖 (biểu âm). Đến thời Hán, thành phần biểu âm 屖 bị thay bằng 隹 (chim đuôi ngắn) do gần âm. Ý nghĩa gốc là lúa non, sau mở rộng sang ''trẻ con, non nớt''. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1525.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Hòa (115) Truy (034)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Hòa (số 115 - cây lúa/ 禾 /chỉ ý) ở bên trái bộ Truy (số 034 - con chim/ 隹 /chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Bộ Truy chỉ âm, bộ Hòa chỉ ý. Trĩ vốn là lúa gieo cấy muộn, lúa non. Mở rộng là trẻ nhỏ, sự non nớt, chưa chín chắn, trẻ trâu (ấu trĩ, ngây trĩ).", "Nghĩa Tiếng Việt_Xie": "lúa non; trẻ con", "Hạng Tần Suất (Jun Da)": "2714.0", "Tần Suất % (Jun Da)": "98.8436684555", "GavinGrover_Once (Chiết tự trực tiếp)": "禾 + 隹", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰禾隹", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "隹", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "禾", "Unihan_Simplified (Chữ Giản thể)": "稚", "Unihan_Traditional (Chữ Phồn thể)": "稚", "Pinyin_Xie": "zhì", "Âm Hán Việt_Xie": "trĩ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường làm tính từ đứng trước danh từ hoặc kết hợp thành từ ghép để chỉ sự non nớt, ngây thơ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蔬', '{"9000": "2715.0", "Chữ Trung Quốc": "蔬", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 15 | nét | 艹 | thảo | biểu nghĩa | cỏ, thực vật | 疏 | sơ | biểu âm | thưa, khai thông — cho âm sơ | 蔬 = 艹(Thảo, biểu nghĩa: thực vật) + 疏 (Sơ, biểu âm); chữ hình thanh. Wiktionary ghi: {{Han compound|艹|疏|ls=psc|c1=s|c2=p|t1=grass; plant}}. Bộ thảo chỉ thực vật; 疏 cho âm shū (gần sơ). Rau là thực vật ăn được.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sơ\": cỏ (艹-Thảo) thưa (疏-Sơ) — rau mọc thưa trong vườn. Sơ = rau xanh. | Gương Hán-Việt | sơ trong ''sơ hở, sơ suất'' — cùng âm; 蔬 chỉ rau xanh, không liên quan sơ suất | Mở khoá kiến thức | Biết 蔬 mở khoá: 蔬菜 (sơ thái – rau củ), 蔬果 (sơ quả – rau và quả), 素蔬 (tố sơ – rau ăn chay).", "Tự nguyên_Xie": "蔬 là chữ hình thanh: 艹(thảo – cỏ, thực vật) biểu nghĩa, 疏 (sơ) biểu âm. Wiktionary xác nhận cấu trúc psc. Nghĩa là rau xanh, thực vật ăn được. 蔬菜 (sơ thái) là từ phổ thông chỉ rau củ. 疏 có nghĩa ''thưa, lọc ra'' — rau là thứ mọc thưa, không đặc như lúa. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "rau, cỏ ăn được", "Hạng Tần Suất (Jun Da)": "2715.0", "Tần Suất % (Jun Da)": "98.8451149371", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 疏", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹疏", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "疏", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "蔬", "Unihan_Traditional (Chữ Phồn thể)": "蔬", "Pinyin_Xie": "shū", "Âm Hán Việt_Xie": "sơ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ liên kết với các từ khác để chỉ chung các loại rau củ quả. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蝇', '{"9000": "2716.0", "Chữ Trung Quốc": "蝇", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 14 | nét | 虫 | trùng | biểu nghĩa | sâu, côn trùng — chỉ loài côn trùng | 黾 | mãnh | biểu âm | ếch/bò sát — cho âm yíng | 蝇 = 虫 (Trùng, biểu nghĩa: côn trùng) + 黾 (Mãnh, biểu âm); chữ hình thanh. Bộ 虫 chỉ đây là loài côn trùng, 黾 cho âm yíng. Phồn thể: 蠅.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"dăng\": côn trùng (虫) kêu vo ve như ếch (黾) — con dăng (ruồi), loài vật ồn ào khó chịu. | Gương Hán-Việt | dăng trong 苍蝇 (thương dăng — con ruồi xanh) | Mở khoá kiến thức | Biết 蝇 mở khoá: 苍蝇 (con ruồi), 蝇头小利 (lợi ích nhỏ nhoi như đầu ruồi).", "Tự nguyên_Xie": "seal | liushutong | Theo Wiktionary, 蝇 (phồn thể: 蠅) là chữ hình thanh (形聲): 虫 (trùng — côn trùng) biểu nghĩa, 黽 biểu âm. Nghĩa duy nhất: con ruồi. Xuất hiện từ trung cổ tiếng Hán. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con ruồi; nhỏ bé", "Hạng Tần Suất (Jun Da)": "2716.0", "Tần Suất % (Jun Da)": "98.8465417809", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 黾", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫黾", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "黾", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蝇", "Unihan_Traditional (Chữ Phồn thể)": "蠅", "Pinyin_Xie": "yíng", "Âm Hán Việt_Xie": "dăng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng độc lập hoặc kết hợp để chỉ loài ruồi hoặc những thứ nhỏ nhen, bẩn thỉu. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('捣', '{"9000": "2717.0", "Chữ Trung Quốc": "捣", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 10 | nét | 扌 | thủ | biểu nghĩa | tay | 岛 | đảo | biểu âm | đảo (cho âm dǎo) | 捣 = 扌 (Thủ, biểu nghĩa: tay) + 岛 (Đảo, biểu âm). Chữ hình thanh — bộ thủ chỉ hành động bằng tay, 岛 cho âm dǎo.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đảo\": dùng tay (扌) đập mạnh như người đi đảo (岛) xa về — giã, đập, gây rối. | Gương Hán-Việt | \"đảo\" trong \"đảo lộn\" (lộn xộn, gây rối) | Mở khoá kiến thức | Biết 捣 (đảo) mở khoá: 捣乱 (đảo loạn — gây rối), 捣毁 (đảo huỷ — phá huỷ), 捣蛋 (đảo đản — nghịch ngợm).", "Tự nguyên_Xie": "Lục thư thông | Chữ hình thanh, nguyên dạng phồn thể là 搗. Theo Wiktionary: 手 (tay, biểu nghĩa) + 島 (biểu âm). Nghĩa gốc là giã, đập bằng chày — hành động dùng tay mạnh để nghiền nát. Từ đó mở rộng sang ''gây rối, tấn công''. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "giã, đập", "Hạng Tần Suất (Jun Da)": "2717.0", "Tần Suất % (Jun Da)": "98.8479644903", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 岛", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌岛", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "岛", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "捣", "Unihan_Traditional (Chữ Phồn thể)": "搗", "Pinyin_Xie": "dǎo", "Âm Hán Việt_Xie": "đảo", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đi kèm tân ngữ chỉ hành động giã thuốc, giã gạo hoặc gây rối. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('顷', '{"9000": "2718.0", "Chữ Trung Quốc": "顷", "Bộ thủ & thành phần_Xie": "Bộ thủ | 頁 | Số nét | 8 | nét | 匕 | chuỷ | biểu hình | cái muỗng, nét nghiêng | 页 | hiệt | biểu nghĩa | đầu, trang — chỉ sự nghiêng về | 顷 là dạng giản thể của 頃. Theo cấu trúc: 匕 (chuỷ — nét nghiêng) + 页 (hiệt — đầu). Nguyên nghĩa là đầu nghiêng về một phía; mở rộng sang ''khoảnh khắc ngắn'' và ''đơn vị diện tích 100 mẫu''. Không có dữ liệu hình thanh rõ ràng từ Wiktionary cho dạng giản.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khuynh\": đầu (页) nghiêng (匕) — khuynh, nghiêng về một phía; chỉ một khoảnh khắc ngắn. | Gương Hán-Việt | khuynh trong 公顷 (công khuynh — héc-ta) và 顷刻 (khuynh khắc — chốc lát) | Mở khoá kiến thức | Biết 顷 mở khoá: 公顷 (héc-ta), 顷刻 (chốc lát), 少顷 (một lúc sau).", "Tự nguyên_Xie": "seal | liushutong | 顷 là giản thể của 頃. Theo Wiktionary, 頃 có cấu trúc chỉ sự: 匕 (nét nghiêng) + 頁 (đầu) — đầu nghiêng về một bên. Từ đó mở rộng nghĩa sang ''khoảnh khắc ngắn'' (顷刻) và đơn vị ruộng đất (公顷 — héc-ta). Chưa có nguồn học thuật đầy đủ cho dạng giản thể hiện đại. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mảnh đất; phúc chốc, nhanh chóng; nửa bước chân", "Hạng Tần Suất (Jun Da)": "2718.0", "Tần Suất % (Jun Da)": "98.8493871998", "GavinGrover_Once (Chiết tự trực tiếp)": "匕 + 页", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰匕页", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "页", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "匕", "Unihan_Simplified (Chữ Giản thể)": "顷", "Unihan_Traditional (Chữ Phồn thể)": "頃", "Pinyin_Xie": "qǐng", "Âm Hán Việt_Xie": "khoảnh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Lượng từ | 量词 | Phó từ | 副词 | Danh từ | 名词 | Thường làm lượng từ đo diện tích đất hoặc làm phó từ chỉ thời gian ngắn ngủi trong văn viết. | Lượng từ | 量词 | Đứng giữa số từ (hoặc 这/那) và danh từ: 一杯茶, 这本书. Mỗi danh từ đi với lượng từ riêng; 个 là lượng từ dùng chung phổ biến nhất. | Phó từ | 副词 | Bổ nghĩa cho động từ hoặc tính từ và luôn đứng TRƯỚC chúng — 都是, 很好. Không đứng sau như tiếng Việt và không bổ nghĩa cho danh từ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('麽', '{"9000": "2719.0", "Chữ Trung Quốc": "麽", "Bộ thủ & thành phần_Xie": "Bộ thủ | 麻 | Số nét | 14 | nét | 麻 | ma | biểu âm | cây gai dầu — cho âm ma | 么 | yêu | biểu nghĩa | nhỏ bé, tí ti | 麽 = 麻 (Ma, biểu âm) + 么 (Yêu, biểu nghĩa: nhỏ); chữ hình thanh. 麻 cho âm ma, 么 biểu thị nghĩa ''nhỏ bé''. Nghĩa: nhỏ, tí tẹo; dùng trong hư từ ''gì, sao'' (么/麼) trong tiếng Hán cổ và một số phương ngữ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ma\": dưới mái gai (麻) ẩn cái nhỏ xíu (么) — ma mị, điều nhỏ nhặt khó nắm bắt. | Gương Hán-Việt | ma trong 麽麽 (ma ma — bà vú; điều vặt vãnh) và dùng như trợ từ nghi vấn | Mở khoá kiến thức | Biết 麽 mở khoá cách đọc hư từ trong văn cổ và cách phân biệt 么/麽/麼.", "Tự nguyên_Xie": "liushutong | Theo Wiktionary, 麽 là chữ hình thanh (形聲): 麻 biểu âm, 幺 (rút gọn thành 么) biểu nghĩa — nhỏ bé. Nghĩa gốc: nhỏ tí, tí xíu. Trong tiếng Hán hiện đại, 麽/麼 chủ yếu là hư từ cuối câu nghi vấn hoặc cấu trúc ''như thế nào''. Phồn thể: 麼. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bé nhỏ; vậy (trợ ngữ)", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "麻 + 么", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴麻么", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "么", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "麻", "Unihan_Simplified (Chữ Giản thể)": "麽", "Unihan_Traditional (Chữ Phồn thể)": "麽", "Pinyin_Xie": "mó", "Âm Hán Việt_Xie": "ma", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Trợ từ | 助词 | Chữ này thường làm tính từ chỉ sự nhỏ bé hoặc làm trợ từ ngữ khí ở cuối câu hỏi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Trợ từ | 助词 | Không mang nghĩa riêng, gắn vào câu để đánh dấu ngữ pháp hoặc ngữ khí: 的 / 地 / 得 (kết cấu), 了 / 着 / 过 (thể), 吗 / 呢 / 吧 (nghi vấn, ngữ khí).", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('尴', '{"9000": "2720.0", "Chữ Trung Quốc": "尴", "Bộ thủ & thành phần_Xie": "Bộ thủ | 尢 | Số nét | 13 | nét | 尢 | uông | biểu nghĩa | người tàn tật, đi khập khiễng | 监 | giam | biểu âm | giám sát (cho âm gān) | 尴 = 尢 (Uông, biểu nghĩa: người đi khập khiễng) + 监 (Giam, biểu âm). Đây là dạng giản thể của 尷. Chỉ dùng trong tổ hợp 尴尬 (xấu hổ, lúng túng).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"giam\": như bị giam (监) trong thân xác vụng về (尢) — cảm giác bối rối, xấu hổ không thoát ra được. | Gương Hán-Việt | \"giam\" — ít dùng độc lập trong tiếng Việt, chủ yếu qua 尴尬 | Mở khoá kiến thức | Biết 尴 (giam) mở khoá: 尴尬 (giam giới — xấu hổ, lúng túng); luôn đi cùng 尬.", "Tự nguyên_Xie": "尴 là dạng giản thể của 尷, rút gọn 監 thành 监. Chữ gốc 尷 chứa bộ 尢 (người đi khập khiễng, không bình thường) — ẩn dụ cho trạng thái không tự nhiên, lúng túng. Chưa có nguồn học thuật chi tiết cho glyph origin riêng của 尴. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: dam giới 尷尬,尲尬,尴尬)", "Hạng Tần Suất (Jun Da)": "2720.0", "Tần Suất % (Jun Da)": "98.8522290013", "GavinGrover_Once (Chiết tự trực tiếp)": "尢 + 监", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴尢监", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "监", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "尢", "Unihan_Simplified (Chữ Giản thể)": "尴", "Unihan_Traditional (Chữ Phồn thể)": "尷", "Pinyin_Xie": "gān", "Âm Hán Việt_Xie": "giam", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường kết hợp với chữ Giới để tạo thành từ ghép chỉ sự lúng túng, khó xử. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('镖', '{"9000": "2721.0", "Chữ Trung Quốc": "镖", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 16 | nét | 钅 | kim | biểu nghĩa | kim loại — chỉ vũ khí bằng sắt | 票 | phiếu | biểu âm | phiếu, giấy — cho âm biāo | 镖 = 钅(Kim, biểu nghĩa: kim loại) + 票 (Phiếu, biểu âm); chữ hình thanh. Bộ 钅chỉ đây là vật bằng kim loại, 票 cho âm biāo. Nghĩa: phi tiêu, vũ khí ném; người áp tải hàng hóa (镖师).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tiêu\": kim loại (钅) bay như tờ phiếu (票) — phi tiêu, vũ khí tiêu của võ lâm. | Gương Hán-Việt | tiêu trong 镖局 (tiêu cục — công ty áp tải) và 飞镖 (phi tiêu — phi tiêu ném) | Mở khoá kiến thức | Biết 镖 mở khoá: 飞镖 (phi tiêu), 镖局 (tiêu cục), 镖师 (tiêu sư — người áp tiêu).", "Tự nguyên_Xie": "seal | liushutong | Wiktionary ghi nhận 镖 là chữ hình thanh, nhưng phần glyphOrigin không chi tiết hơn ngoài thông tin phát âm. Cấu trúc rõ ràng: 钅(kim loại) biểu nghĩa + 票 biểu âm. Nghĩa gốc: phi tiêu (vũ khí ném bằng kim loại). Mở rộng sang nghĩa người áp tiêu (护镖), và tiêu cục (công ty áp tải). Chưa có nguồn học thuật thêm. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cây lao, cái lao", "Hạng Tần Suất (Jun Da)": "2721.0", "Tần Suất % (Jun Da)": "98.8536470597", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 票", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅票", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "票", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "镖", "Unihan_Traditional (Chữ Phồn thể)": "鏢", "Pinyin_Xie": "biāo", "Âm Hán Việt_Xie": "phiêu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ các loại vũ khí phóng hoặc tiêu cục bảo vệ ngày xưa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('诧', '{"9000": "2722.0", "Chữ Trung Quốc": "诧", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 8 | nét | 讠 | biểu nghĩa | lời nói (bộ ngôn giản thể) | 宅 | trạch | biểu âm | nhà ở (cho âm chà) | 诧 = 讠 (bộ ngôn, biểu nghĩa: lời nói) + 宅 (Trạch, biểu âm). Dạng giản thể của 詫. Chữ hình thanh — bộ ngôn chỉ liên quan đến lời/cảm xúc biểu đạt, 宅 cho âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sá\": đứng trong nhà (宅) bỗng thốt lên lời (讠) kinh ngạc — cảm giác bị bất ngờ hoàn toàn. | Gương Hán-Việt | \"sá\" — ít dùng độc lập, chủ yếu qua 诧异 | Mở khoá kiến thức | Biết 诧 (sá) mở khoá: 诧异 (sá dị — ngạc nhiên, sửng sốt).", "Tự nguyên_Xie": "诧 là dạng giản thể của 詫 (言→讠). Chữ gốc 詫 chứa 言 (lời nói) + 宅 (biểu âm). Nghĩa gốc là kinh ngạc, sửng sốt — phản ứng bộc phát qua lời nói khi gặp điều bất ngờ. Chưa có nguồn glyph origin riêng cho 诧 từ Wiktionary. Chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "khoe; lạ lùng; lừa dối", "Hạng Tần Suất (Jun Da)": "2722.0", "Tần Suất % (Jun Da)": "98.8550646013", "GavinGrover_Once (Chiết tự trực tiếp)": "讠 + 宅", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰讠宅", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "宅", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "讠", "Unihan_Simplified (Chữ Giản thể)": "诧", "Unihan_Traditional (Chữ Phồn thể)": "詫", "Pinyin_Xie": "chà", "Âm Hán Việt_Xie": "sá", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Thường dùng làm động từ hoặc tính từ trong các từ ghép chỉ sự kinh ngạc, sửng sốt. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('尬', '{"9000": "2723.0", "Chữ Trung Quốc": "尬", "Bộ thủ & thành phần_Xie": "Bộ thủ | 尢 | Số nét | 7 | nét | 尢 | uông | biểu nghĩa | người đi khập khiễng, không bình thường | 介 | giới | biểu âm | kẹp giữa, trung gian (cho âm gà) | 尬 = 尢 (Uông, biểu nghĩa: người tàn tật, đi vướng víu) + 介 (Giới, biểu âm). Chữ hình thanh — 尢 gợi tư thế lúng túng, 介 cho âm gà.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"giới\": người đi khập khiễng (尢) mắc kẹt giữa hai ranh giới (介) — hình ảnh của sự lúng túng, không thoát ra được. | Gương Hán-Việt | \"giới\" trong \"giới hạn\" — cảm giác bị kẹt, không vượt qua được | Mở khoá kiến thức | Biết 尬 (giới) mở khoá: 尴尬 (giam giới — xấu hổ, lúng túng); luôn đi cùng 尴.", "Tự nguyên_Xie": "Tiểu triện | Chữ hình thanh theo Wiktionary: 尢 (biểu nghĩa: người đi khập khiễng) + 介 (biểu âm). Kết hợp với 尴 tạo thành 尴尬 — trạng thái lúng túng, xấu hổ như người không đứng vững được. Có dạng tiểu triện. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: dam giới 尲尬)", "Hạng Tần Suất (Jun Da)": "2723.0", "Tần Suất % (Jun Da)": "98.8564821429", "GavinGrover_Once (Chiết tự trực tiếp)": "尢 + 介", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴尢介", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "介", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "尢", "Unihan_Simplified (Chữ Giản thể)": "尬", "Unihan_Traditional (Chữ Phồn thể)": "尬", "Pinyin_Xie": "gà", "Âm Hán Việt_Xie": "giới", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường đi kèm với chữ Giam để tạo thành tính từ chỉ trạng thái khó xử, ngượng ngùng. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('硫', '{"9000": "2724.0", "Chữ Trung Quốc": "硫", "Bộ thủ & thành phần_Xie": "Bộ thủ | 石 | Số nét | 12 | nét | 石 | thạch | biểu nghĩa | đá, khoáng vật — chỉ chất khoáng | 㐬 | lưu | biểu âm | rút gọn từ 流 — cho âm liú | 硫 = 石 (Thạch, biểu nghĩa: đá/khoáng) + 㐬 (rút gọn từ 流, biểu âm); chữ hình thanh. Bộ 石 chỉ đây là khoáng vật, 㐬 (dạng rút gọn của 流) cho âm liú. Nghĩa: lưu huỳnh (nguyên tố S).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lưu\": đá (石) chảy (流~㐬) màu vàng — lưu huỳnh, khoáng chất vàng nóng chảy được. | Gương Hán-Việt | lưu trong 硫黄 (lưu hoàng — lưu huỳnh) và 硫酸 (lưu toan — axit sulfuric) | Mở khoá kiến thức | Biết 硫 mở khoá: 硫黄 (lưu huỳnh), 硫酸 (axit sulfuric), 二氧化硫 (SO₂).", "Tự nguyên_Xie": "Theo Wiktionary, 硫 là chữ hình thanh (形聲): 石 (thạch — đá/khoáng) biểu nghĩa, 流 rút gọn thành 㐬 biểu âm. Nghĩa: lưu huỳnh (sulfur), nguyên tố hóa học số 16. Tên chữ phản ánh tính chất khoáng vật tự nhiên của lưu huỳnh. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: lưu hoàng, lưu huỳnh 硫黃)", "Hạng Tần Suất (Jun Da)": "2724.0", "Tần Suất % (Jun Da)": "98.8578991678", "GavinGrover_Once (Chiết tự trực tiếp)": "石 + 㐬", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰石㐬", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "㐬", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "石", "Unihan_Simplified (Chữ Giản thể)": "硫", "Unihan_Traditional (Chữ Phồn thể)": "硫", "Pinyin_Xie": "liú", "Âm Hán Việt_Xie": "lưu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng trước các danh từ khác để chỉ hợp chất hóa học liên quan đến lưu huỳnh. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('嚼', '{"9000": "2725.0", "Chữ Trung Quốc": "嚼", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 20 | nét | 口 | khẩu | biểu nghĩa | miệng | 爵 | tước | biểu âm | tước vị귀족 (cho âm jué) | 嚼 = 口 (Khẩu, biểu nghĩa: miệng) + 爵 (Tước, biểu âm). Chữ hình thanh — 口 chỉ hành động của miệng, 爵 cho âm jué.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tước\": tước vị cao sang (爵) mà vẫn phải dùng miệng (口) để nhai — ai cũng phải nhai, không kể sang hèn. | Gương Hán-Việt | \"tước\" trong \"tước vị\" — cùng âm nhưng khác nghĩa | Mở khoá kiến thức | Biết 嚼 (tước) mở khoá: 咀嚼 (thư tước — nhai, nghiền ngẫm); 嚼舌 (tước thiệt — nói hành).", "Tự nguyên_Xie": "Tiểu triện | Chữ hình thanh theo Wiktionary: 口 (miệng, biểu nghĩa) + 爵 (biểu âm). Nghĩa gốc là nhai — hành động dùng miệng nghiền nhỏ thức ăn. Có dạng tiểu triện còn lưu. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nhấm, nhai", "Hạng Tần Suất (Jun Da)": "2725.0", "Tần Suất % (Jun Da)": "98.8593146422", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 爵", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口爵", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "爵", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "嚼", "Unihan_Traditional (Chữ Phồn thể)": "嚼", "Pinyin_Xie": "jué", "Âm Hán Việt_Xie": "tước", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước tân ngữ chỉ thức ăn để diễn tả hành động nhai. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | jiáo | / | nhai | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Thức ăn tôi", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('羡', '{"9000": "2726.0", "Chữ Trung Quốc": "羡", "Bộ thủ & thành phần_Xie": "Bộ thủ | 羊 | Số nét | 12 | nét | 𦍌 | dương | biểu nghĩa | con dê — vật ngon, đẹp | 次 | thứ | biểu nghĩa | vốn là 㳄 — nước miếng chảy | 羡 là chữ hội ý (ic): 羊 (𦍌, con dê — vật ngon, đẹp) + 㳄 (sau viết 次, nước miếng) — thấy con dê ngon mà chảy nước miếng, biểu thị ''thèm muốn, ngưỡng mộ''.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Tiện\": nhìn con dê ngon (𦍌) mà chảy nước miếng (次, vốn là 㳄) — đó là ''tiện'', ngưỡng mộ, thèm muốn. | Gương Hán-Việt | ''Tiện'' (羡) trong ''tiện mộ'' (ngưỡng mộ), ''tiện ngư'' (cá thừa). | Mở khoá kiến thức | Biết 羡 mở khoá 羡慕 (tiện mộ, ngưỡng mộ), 艳羡 (diễm tiện, hâm mộ).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 羡 là chữ hội ý gồm 羊 (𦍌, con dê — chỉ vật ngon, đẹp; so sánh 美, 善) + 㳄 (nay viết thành 次, nước miếng) — vẽ cảnh thấy con dê ngon mà chảy nước miếng, biểu thị ''thèm muốn, ngưỡng mộ''. Khang Hi tự điển, theo 《佩觿》, tách 羡 (etym 2 — ''mộ'') khỏi 羨 (etym 1 — ''dư thừa, ngạch''), nhưng các từ điển hiện đại như Hán ngữ Đại tự điển thường gộp lại. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ham muốn, thích", "Hạng Tần Suất (Jun Da)": "2726.0", "Tần Suất % (Jun Da)": "98.8607301167", "GavinGrover_Once (Chiết tự trực tiếp)": "羊 + 次", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱羊次", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "次", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "羊", "Unihan_Simplified (Chữ Giản thể)": "羡", "Unihan_Traditional (Chữ Phồn thể)": "羨", "Pinyin_Xie": "xiàn", "Âm Hán Việt_Xie": "tiện", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ mang tân ngữ để biểu thị sự ngưỡng mộ hoặc thèm muốn điều gì đó. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('沦', '{"9000": "2727.0", "Chữ Trung Quốc": "沦", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 7 | nét | 氵 | thuỷ | biểu nghĩa | nước — chỉ liên quan đến nước | 仑 | luân | biểu âm | rút gọn từ 侖 — cho âm lún | 沦 = 氵(Thuỷ, biểu nghĩa: nước) + 仑 (Luân, biểu âm); chữ hình thanh. Dạng giản của 淪. Bộ 氵chỉ liên quan đến nước, 仑 cho âm lún. Nghĩa: chìm xuống, sa đọa; gợn sóng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"luân\": nước (氵) xoáy luân (仑) — sóng xoáy kéo chìm, sa đọa, luân lạc. | Gương Hán-Việt | luân trong 沦落 (luân lạc — sa đọa, lưu lạc) và 沦陷 (luân hãm — thất thủ) | Mở khoá kiến thức | Biết 沦 mở khoá: 沦落 (sa đọa), 沦陷 (thất thủ), 沦丧 (mất mát, suy đồi).", "Tự nguyên_Xie": "seal | liushutong | 沦 là giản thể của 淪. Theo Wiktionary, 淪 = 氵(thuỷ — nước) + 侖 biểu âm. Nghĩa gốc: gợn sóng nước nhỏ; mở rộng sang ''chìm xuống, sa vào'', như 沦落 (sa đọa), 沦陷 (thất thủ, bị chiếm). Hình ảnh sóng nước xoáy chìm dần rất phù hợp với nghĩa mở rộng. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chìm, đắm", "Hạng Tần Suất (Jun Da)": "2727.0", "Tần Suất % (Jun Da)": "98.8621450744", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 仑", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵仑", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "仑", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "沦", "Unihan_Traditional (Chữ Phồn thể)": "淪", "Pinyin_Xie": "lún", "Âm Hán Việt_Xie": "luân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ biểu thị trạng thái rơi vào hoàn cảnh tồi tệ hoặc bị chìm ngập. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('沪', '{"9000": "2728.0", "Chữ Trung Quốc": "沪", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 7 | nét | 氵 | thuỷ | biểu nghĩa | nước — chỉ con sông, vùng nước | 户 | hộ | biểu âm | cửa, hộ — cho âm hù | 沪 = 氵(Thuỷ, biểu nghĩa: nước) + 户 (Hộ, biểu âm); chữ hình thanh. Dạng giản của phồn thể 滬. Bộ 氵chỉ sông nước, 户 cho âm hù. Nghĩa: tên cũ của dòng sông tại Thượng Hải (吴淞江 đoạn cũ gọi là 沪渎); nay dùng làm biệt danh cho Thượng Hải.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hỗ\": nước (氵) bên cửa nhà (户) — bến nước nơi nhà nhà đặt bẫy cá, tức thành phố Hỗ — Thượng Hải. | Gương Hán-Việt | hỗ trong 沪上 (hỗ thượng — trên đất Thượng Hải) và 京沪 (kinh hỗ — Bắc Kinh–Thượng Hải) | Mở khoá kiến thức | Biết 沪 mở khoá tên tắt Thượng Hải trong địa danh: 沪深 (Thượng Hải–Thâm Quyến), 京沪高铁.", "Tự nguyên_Xie": "Theo Wiktionary, 沪 (phồn thể: 滬) là chữ hình thanh: 水 (nước) biểu nghĩa, 扈 biểu âm rút gọn thành 户. Nghĩa gốc: dụng cụ đánh cá bằng tre (hộ — rổ bẫy cá) trên sông; hoặc tên đoạn sông 沪渎 ở vùng Thượng Hải. Nay là tên tắt chính thức của Thượng Hải (上海). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Thượng Hải", "Hạng Tần Suất (Jun Da)": "2728.0", "Tần Suất % (Jun Da)": "98.8635595153", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 户", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵户", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "户", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "沪", "Unihan_Traditional (Chữ Phồn thể)": "滬", "Pinyin_Xie": "hù", "Âm Hán Việt_Xie": "hỗ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ riêng hoặc yếu tố cấu tạo từ để chỉ các sự vật liên quan đến Thượng Hải. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('旷', '{"9000": "2729.0", "Chữ Trung Quốc": "旷", "Bộ thủ & thành phần_Xie": "Bộ thủ | 日 | Số nét | 7 | nét | 日 | nhật | biểu nghĩa | mặt trời, ánh sáng | 广 | nghiễm | biểu âm | mái hiên rộng (cho âm kuàng) | 旷 = 日 (Nhật, biểu nghĩa: ánh sáng mặt trời) + 广 (Nghiễm, biểu âm). Dạng giản thể của 曠. Ánh sáng mặt trời trải rộng trên không gian bao la.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khoáng\": mặt trời (日) soi xuống không gian rộng mênh mông (广) — cảm giác khoáng đãng, thoáng đãng hoàn toàn. | Gương Hán-Việt | \"khoáng\" trong \"khoáng đạt\" (rộng rãi, thoáng đãng) và \"khoáng sản\" (tài nguyên khoáng vật) | Mở khoá kiến thức | Biết 旷 (khoáng) mở khoá: 旷野 (khoáng dã — đồng hoang); 空旷 (không khoáng — rộng rãi, trống trải); 旷课 (khoáng khoá — trốn học).", "Tự nguyên_Xie": "旷 là dạng giản thể của 曠 (日+廣→广). Chữ gốc 曠 gồm 日 (mặt trời) + 廣 (rộng lớn, biểu âm và biểu nghĩa). Nghĩa gốc là nơi trống rộng, ánh sáng mặt trời chiếu không bị che khuất. Từ đó có nghĩa ''trống trải, thảnh thơi, bỏ lỡ''. Chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "rộng lớn; thanh thản, thảnh thơi", "Hạng Tần Suất (Jun Da)": "2729.0", "Tần Suất % (Jun Da)": "98.8649708555", "GavinGrover_Once (Chiết tự trực tiếp)": "日 + 广", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰日广", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "广", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "日", "Unihan_Simplified (Chữ Giản thể)": "旷", "Unihan_Traditional (Chữ Phồn thể)": "曠", "Pinyin_Xie": "kuàng", "Âm Hán Việt_Xie": "khoáng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường làm tính từ chỉ không gian rộng lớn hoặc làm động từ với nghĩa bỏ bê, trốn học. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('彬', '{"9000": "2730.0", "Chữ Trung Quốc": "彬", "Bộ thủ & thành phần_Xie": "Bộ thủ | 彡 | Số nét | 11 | nét | 林 | lâm | biểu âm | rừng cây — rút gọn từ 焚/棼 cho âm bīn | 彡 | sam | biểu nghĩa | ba nét lông — biểu trưng cho vẻ đẹp văn vẻ | 彬 = 林 (Lâm, biểu âm rút gọn từ 焚 hoặc 棼) + 彡 (Sam, biểu nghĩa: vẻ đẹp văn hoa); chữ hình thanh. Bộ 彡 biểu trưng cho sự đẹp đẽ, tao nhã; 林 cho âm bīn. Nghĩa: văn nhã, lịch sự, tao nhã.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bân\": rừng (林) điểm thêm nét hoa văn (彡) — bân bân, vẻ người văn nhã, lịch lãm. | Gương Hán-Việt | bân trong 彬彬有礼 (bân bân hữu lễ — lịch sự đúng mực) | Mở khoá kiến thức | Biết 彬 mở khoá: 彬彬有礼 (rất lịch sự), tên người (Bân — tao nhã).", "Tự nguyên_Xie": "seal | liushutong | Theo Wiktionary, 彬 là chữ hình thanh (形聲): 彡 (vẻ đẹp, hoa văn) biểu nghĩa, 焚 hoặc 棼 rút gọn thành 林 biểu âm. Nghĩa gốc và hiện tại: văn nhã, lịch sự (彬彬有礼 — lịch sự đúng mực). Chỉ dùng trong 彬彬 và tên người. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "vẻ đẹp mộc mạc", "Hạng Tần Suất (Jun Da)": "2730.0", "Tần Suất % (Jun Da)": "98.8663785782", "GavinGrover_Once (Chiết tự trực tiếp)": "林 + 彡", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰林彡", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "林", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "彡", "Unihan_Simplified (Chữ Giản thể)": "彬", "Unihan_Traditional (Chữ Phồn thể)": "彬", "Pinyin_Xie": "bīn", "Âm Hán Việt_Xie": "bân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường làm tính từ xuất hiện trong từ ghép để miêu tả phong thái lịch thiệp, nhã nhặn của con người. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('芽', '{"9000": "2731.0", "Chữ Trung Quốc": "芽", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 7 | nét | 艹 | thảo | biểu nghĩa | cỏ, thực vật | 牙 | nha | biểu âm | răng (cho âm yá) | 芽 = 艹 (Thảo, biểu nghĩa: cỏ, thực vật) + 牙 (Nha, biểu âm). Chữ hình thanh — 艹 chỉ đây là cây cỏ, 牙 cho âm yá. Hình ảnh mầm cây nhú lên như chiếc răng nhỏ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nha\": cây cỏ (艹) mọc lên như chiếc răng (牙) nhỏ — hình ảnh mầm non vừa nhú. | Gương Hán-Việt | \"nha\" trong \"mầm nha\" — chồi non, mầm cây; cũng qua \"nha khoa\" (牙科) vì 牙 là răng | Mở khoá kiến thức | Biết 芽 (nha) mở khoá: 发芽 (phát nha — nảy mầm); 豆芽 (đậu nha — giá đỗ); 嫩芽 (nộn nha — chồi non).", "Tự nguyên_Xie": "Chữ hình thanh theo Wiktionary: 艹 (thảo, biểu nghĩa) + 牙 (biểu âm). Nghĩa gốc là mầm cây, chồi non — phần cây đang nhú lên từ hạt hoặc cành. Hình ảnh sinh động: mầm non nhú lên giống như chiếc răng (牙) nhỏ của cây. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1419.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thảo (140) Nha (166)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Thảo (số 140 - cỏ/ 艹 /chỉ ý) ở trên bộ Nha (số 166 - răng non/ 牙 /chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Bộ Nha chỉ âm, bộ Thảo chỉ ý. Nha là chồi non, mầm non của cây cỏ (mạch nha). Cũng có ý chỉ sự việc mới bắt đầu nảy sinh, phát sinh (mầm mống).", "Nghĩa Tiếng Việt_Xie": "mầm, chồi", "Hạng Tần Suất (Jun Da)": "2731.0", "Tần Suất % (Jun Da)": "98.8677826835", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 牙", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹牙", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "牙", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "芽", "Unihan_Traditional (Chữ Phồn thể)": "芽", "Pinyin_Xie": "yá", "Âm Hán Việt_Xie": "nha", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường dùng làm danh từ chỉ mầm cây hoặc làm động từ khi kết hợp để chỉ sự nảy mầm. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | yá | / | chồi, mầm | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Thực vật", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('狸', '{"9000": "2732.0", "Chữ Trung Quốc": "狸", "Bộ thủ & thành phần_Xie": "Bộ thủ | 犬 | Số nét | 10 | nét | 犭 | khuyển | biểu nghĩa | chó/thú — chỉ loài thú | 里 | lý | biểu âm | làng, dặm — cho âm lí | 狸 = 犭(Khuyển, biểu nghĩa: thú vật) + 里 (Lý, biểu âm); chữ hình thanh. Bộ 犭chỉ đây là loài thú, 里 cho âm lí. Theo Wiktionary, ban đầu là biến thể thông dụng của 貍 (cáo mèo). Nghĩa: cáo mèo, chồn hương.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ly\": thú (犭) sống trong làng (里) — con ly, cáo mèo lén lút gần người. | Gương Hán-Việt | ly trong 狐狸 (hồ ly — con cáo) và 狸猫 (ly miêu — cáo mèo) | Mở khoá kiến thức | Biết 狸 mở khoá: 狐狸 (con cáo), 狸猫 (cáo mèo), 狸猫换太子 (điển tích đánh tráo thái tử).", "Tự nguyên_Xie": "seal | liushutong | Theo Wiktionary, 狸 vốn là biến thể thông tục (俗字) của 貍 (cáo mèo). Hình thanh: 犭(thú) biểu nghĩa, 里 biểu âm. Nghĩa: cáo mèo hoang (Felis bengalensis biến thể), chồn hương; trong thành ngữ 猫鼠狸 ám chỉ sự đồng lõa. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con báo", "Hạng Tần Suất (Jun Da)": "2732.0", "Tần Suất % (Jun Da)": "98.8691857551", "GavinGrover_Once (Chiết tự trực tiếp)": "犭 + 里", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰犭里", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "里", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "犭", "Unihan_Simplified (Chữ Giản thể)": "狸", "Unihan_Traditional (Chữ Phồn thể)": "狸", "Pinyin_Xie": "lí", "Âm Hán Việt_Xie": "li", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ để chỉ các loài thú nhỏ giống mèo hoặc cáo như ly miêu. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('冥', '{"9000": "2733.0", "Chữ Trung Quốc": "冥", "Bộ thủ & thành phần_Xie": "Bộ thủ | 冖 | Số nét | 10 | nét | 冖 | mịch | biểu nghĩa | tấm che phủ — chỉ bóng tối che lấp | 日 | nhật | biểu nghĩa | mặt trời — bị che khuất | 六 | lục | biểu hình | biến thể của 廾 (hai tay) — do biến đổi chữ viết | 冥 là chữ hội ý (會意): 冖 (tấm phủ) che lên 日 (mặt trời) với 廾 (hai tay) bên dưới — hình ảnh bàn tay che mặt trời tạo ra bóng tối. Bộ phận 廾 về sau bị đọc nhầm và viết thành 六. Nghĩa: tối tăm, u minh; âm ty, cõi chết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"minh\": tấm che (冖) phủ mặt trời (日) — không phải sáng minh mà là u minh, cõi tối. | Gương Hán-Việt | minh trong 冥界 (minh giới — cõi âm) và 冥想 (minh tưởng — thiền định) | Mở khoá kiến thức | Biết 冥 mở khoá: 冥界 (cõi âm ty), 冥想 (thiền định sâu), 冥冥 (u ám, huyền bí).", "Tự nguyên_Xie": "oracle | bronze | seal | liushutong | Theo Wiktionary, 冥 là chữ hội ý (會意) gốc: 冖 (vải che) + 日 (mặt trời) + 廾 (hai tay) — tay che mặt trời → tối tăm. Phần 廾 sau bị biến thể thành 六 trong lối viết. Nghĩa gốc: tối tăm; mở rộng sang ''u minh, cõi chết'' (冥界), ''sâu xa, thần bí'' (冥想 — thiền định). Cũng có lớp hình thanh (lsCodes: ic+psc). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mù mịt; ngu dốt", "Hạng Tần Suất (Jun Da)": "2733.0", "Tần Suất % (Jun Da)": "98.8705888267", "GavinGrover_Once (Chiết tự trực tiếp)": "冖 + 昗", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱冖昗", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "昗", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "冖", "Unihan_Simplified (Chữ Giản thể)": "冥", "Unihan_Traditional (Chữ Phồn thể)": "㝠", "Pinyin_Xie": "míng", "Âm Hán Việt_Xie": "minh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Thường làm tính từ bổ nghĩa cho danh từ hoặc kết hợp tạo từ chỉ cõi âm, sự ngu muội. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('碳', '{"9000": "2734.0", "Chữ Trung Quốc": "碳", "Bộ thủ & thành phần_Xie": "Bộ thủ | 石 | Số nét | 14 | nét | 石 | thạch | biểu nghĩa | đá, chất rắn phi kim | 炭 | thán | biểu âm | than (cho âm tàn/tān) | 碳 = 石 (Thạch, biểu nghĩa: chất rắn phi kim trong danh pháp hoá học) + 炭 (Thán, biểu âm). Chữ hình thanh — đây là chữ tạo ra trong thời hiện đại để đặt tên nguyên tố carbon, chưa thấy trong giáp cốt/kim văn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thán\": đá (石) than (炭) — carbon là nguyên tố cơ bản trong than đá, trong sự sống. | Gương Hán-Việt | \"thán\" trong \"thán khí\" (CO₂) và \"than thán\" (than vãn) | Mở khoá kiến thức | Biết 碳 (thán) mở khoá: 碳水化合物 (thán thuỷ hoá hợp vật — carbohydrate); 二氧化碳 (nhị dưỡng hoá thán — CO₂); 碳排放 (thán bài phóng — phát thải carbon).", "Tự nguyên_Xie": "Chữ hình thanh, được tạo ra trong thời hiện đại cho danh pháp hoá học. Theo Wiktionary: 石 (đá/chất rắn phi kim, biểu nghĩa trong danh pháp hoá học) + 炭 (than, biểu âm). 碳 chỉ nguyên tố carbon (C), phân biệt với 炭 (than đốt). Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "than củi", "Hạng Tần Suất (Jun Da)": "2734.0", "Tần Suất % (Jun Da)": "98.8719898312", "GavinGrover_Once (Chiết tự trực tiếp)": "石 + 炭", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰石炭", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "炭", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "石", "Unihan_Simplified (Chữ Giản thể)": "碳", "Unihan_Traditional (Chữ Phồn thể)": "碳", "Pinyin_Xie": "tàn", "Âm Hán Việt_Xie": "thán", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng độc lập hoặc ghép với các từ khác để chỉ hợp chất hóa học chứa các-bon. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | tàn | / | cacbon | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Hóa học và Sinh học II", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('咧', '{"9000": "2735.0", "Chữ Trung Quốc": "咧", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 9 | nét | 口 | khẩu | biểu nghĩa | miệng — chỉ động tác của miệng | 列 | liệt | biểu âm | xếp hàng — cho âm liě | 咧 = 口 (Khẩu, biểu nghĩa: miệng) + 列 (Liệt, biểu âm); chữ hình thanh. Bộ 口 chỉ liên quan đến miệng, 列 cho âm liě. Nghĩa: há miệng, nhe răng; thành ngữ 大大咧咧 (cẩu thả, không cẩn thận).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"liệt\": miệng (口) mở xếp hàng (列) — liệt miệng ra, nhe răng cười toe. | Gương Hán-Việt | liệt trong 咧嘴 (liệt chủy — nhe răng, mở miệng rộng) | Mở khoá kiến thức | Biết 咧 mở khoá: 咧嘴 (nhe răng), 大大咧咧 (cẩu thả, thoải mái quá mức).", "Tự nguyên_Xie": "Theo Wiktionary, 咧 là chữ hình thanh (形聲): 口 (khẩu — miệng) biểu nghĩa, 列 biểu âm. Nghĩa: nhe răng (咧嘴), mở rộng miệng cười; trong 大大咧咧 mang nghĩa thoải mái cẩu thả. Cũng là trợ từ trong phương ngữ phương bắc. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nói bậy, nói ba hoa; khóc nhèo nhẹo; nhếch mép; hài hước, buồn cười, thú vị", "Hạng Tần Suất (Jun Da)": "2735.0", "Tần Suất % (Jun Da)": "98.8733887686", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 列", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口列", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "列", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "咧", "Unihan_Traditional (Chữ Phồn thể)": "咧", "Pinyin_Xie": "liě", "Âm Hán Việt_Xie": "liệt", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Trợ từ | 助词 | Thường dùng làm động từ chỉ động tác của miệng hoặc làm trợ từ ngữ khí ở cuối câu. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Trợ từ | 助词 | Không mang nghĩa riêng, gắn vào câu để đánh dấu ngữ pháp hoặc ngữ khí: 的 / 地 / 得 (kết cấu), 了 / 着 / 过 (thể), 吗 / 呢 / 吧 (nghi vấn, ngữ khí).", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('惕', '{"9000": "2736.0", "Chữ Trung Quốc": "惕", "Bộ thủ & thành phần_Xie": "Bộ thủ | 心 | Số nét | 11 | nét | 忄 | tâm | biểu nghĩa | tâm trạng, lòng | 易 | dịch | biểu âm | dễ dàng, thay đổi (cho âm tì) | 惕 = 忄 (Tâm, biểu nghĩa: lòng, tâm trạng) + 易 (Dịch, biểu âm). Chữ hình thanh — bộ tâm chỉ đây là cảm xúc/tâm lý, 易 cho âm tì.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thích\": lòng (忄) luôn thay đổi (易), không lơ là — trạng thái cảnh giác, cẩn thận không ngừng. | Gương Hán-Việt | \"thích\" trong \"cảnh thích\" (cảnh giác, đề phòng) | Mở khoá kiến thức | Biết 惕 (thích) mở khoá: 警惕 (cảnh thích — cảnh giác, đề phòng); 惕然 (thích nhiên — sợ hãi, cảnh giác).", "Tự nguyên_Xie": "Chữ hình thanh. Theo Wiktionary, 惕 gồm 忄 (tâm, biểu nghĩa) + 易 (biểu âm). Nghĩa gốc là cẩn thận, lo lắng, cảnh giác — trạng thái tâm lý chú tâm phòng bị. Chưa có nguồn học thuật chi tiết cho glyph origin riêng. | Suy từ bộ phận cấu thành · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "kính sợ", "Hạng Tần Suất (Jun Da)": "2736.0", "Tần Suất % (Jun Da)": "98.8747830549", "GavinGrover_Once (Chiết tự trực tiếp)": "忄 + 易", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰忄易", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "易", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "忄", "Unihan_Simplified (Chữ Giản thể)": "惕", "Unihan_Traditional (Chữ Phồn thể)": "惕", "Pinyin_Xie": "tì", "Âm Hán Việt_Xie": "thích", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Thường dùng làm động từ hoặc tính từ trong các từ ghép chỉ sự cảnh giác, đề phòng. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('暑', '{"9000": "2737.0", "Chữ Trung Quốc": "暑", "Bộ thủ & thành phần_Xie": "Bộ thủ | 日 | Số nét | 12 | nét | 日 | nhật | biểu nghĩa | mặt trời — nóng | 者 | giả | biểu âm | gợi âm ''shǔ'' | 暑 = 日 (Nhật, mặt trời) + 者 (Giả, biểu âm). Chữ hình thanh: mặt trời gay gắt — nghĩa ''nóng bức, mùa hè''.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt ''Thử'': mặt trời (日) chiếu gắt — đó là ''thử'', là nóng bức mùa hè. | Gương Hán-Việt | ''Thử'' trong thử kỳ (mùa hè), tỵ thử (tránh nóng), trung thử (trúng nắng). Cùng âm Hán-Việt ''thử'' với 此, 鼠 (chuột). | Mở khoá kiến thức | Biết 暑 mở khóa 暑假 (thử giả / kỳ nghỉ hè), 暑期 (thử kỳ), 避暑 (tỵ thử / tránh nóng), 中暑 (trúng nắng).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 暑 là chữ hình thanh: 日 biểu nghĩa, 者 biểu âm. Nghĩa ''nóng bức, mùa hè, thời gian nắng''. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1448.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Nhật (072) Giả (464)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Nhật (số 072 - mặt trời/ 日 /chỉ ý) ở trên chữ Giả (số 464 - người, đại từ/ 者 /chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Giả chỉ âm, bộ Nhật chỉ ý. Thử là tiết trời nóng nực, oi bức của ngày hè (thử khí, nắng thử).", "Nghĩa Tiếng Việt_Xie": "nóng bức; nắng; mùa hè", "Hạng Tần Suất (Jun Da)": "2737.0", "Tần Suất % (Jun Da)": "98.8761768244", "GavinGrover_Once (Chiết tự trực tiếp)": "日 + 者", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱日者", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "者", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "日", "Unihan_Simplified (Chữ Giản thể)": "暑", "Unihan_Traditional (Chữ Phồn thể)": "暑", "Pinyin_Xie": "shǔ", "Âm Hán Việt_Xie": "thử", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Thường dùng làm danh từ chỉ thời tiết nóng bức hoặc mùa hè trong năm. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('咯', '{"9000": "2738.0", "Chữ Trung Quốc": "咯", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 9 | nét | 口 | khẩu | biểu nghĩa | miệng — chỉ âm thanh phát ra | 各 | các | biểu âm | mỗi, các — cho âm gē/kǎ/lo | 咯 = 口 (Khẩu, biểu nghĩa: miệng) + 各 (Các, biểu âm); chữ hình thanh. Đa âm: gē (tiếng cười giòn), kǎ (khạc ra — 咯血), lo (trợ từ phương ngữ). Bộ 口 chỉ âm thanh hoặc động tác miệng, 各 cho âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khách\": miệng (口) phát tiếng ''các'' (各) — khách sáo nói cạc cạc, hoặc tiếng khạc họng. | Gương Hán-Việt | khách trong 咯血 (khách huyết — khạc ra máu) | Mở khoá kiến thức | Biết 咯 mở khoá: 咯血 (khạc ra máu), 咯咯笑 (cười khúc khích), trợ từ 咯 trong tiếng Quảng.", "Tự nguyên_Xie": "Theo Wiktionary, 咯 là chữ hình thanh (形聲): 口 (khẩu — miệng) biểu nghĩa, 各 biểu âm. Chữ đa âm: (1) gē — âm thanh cười, tiếng gà gáy; (2) kǎ — khạc đờm/máu; (3) lo — trợ từ cuối câu trong tiếng Quảng Đông và phương ngữ phương nam. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "khạc ra máu", "Hạng Tần Suất (Jun Da)": "2738.0", "Tần Suất % (Jun Da)": "98.8775690436", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 各", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口各", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "各", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "咯", "Unihan_Traditional (Chữ Phồn thể)": "咯", "Pinyin_Xie": "gē", "Âm Hán Việt_Xie": "cách, lạc, khạc, khách", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Trợ từ | 助词 | Từ tượng thanh | 象声词 | Thường dùng làm động từ chỉ việc khạc nhổ hoặc làm trợ từ ngữ khí cuối câu. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Trợ từ | 助词 | Không mang nghĩa riêng, gắn vào câu để đánh dấu ngữ pháp hoặc ngữ khí: 的 / 地 / 得 (kết cấu), 了 / 着 / 过 (thể), 吗 / 呢 / 吧 (nghi vấn, ngữ khí). | Từ tượng thanh | 象声词 | Mô phỏng âm thanh: 哗哗, 汪汪. Có thể làm định ngữ, trạng ngữ hoặc đứng độc lập.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('萝', '{"9000": "2739.0", "Chữ Trung Quốc": "萝", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 11 | nét | 艹 | thảo | biểu nghĩa | cỏ, thực vật — chỉ loài cây leo | 罗 | la | biểu âm | lưới, la hét — cho âm luó | 萝 = 艹 (Thảo, biểu nghĩa: thực vật) + 罗 (La, biểu âm); chữ hình thanh. Dạng giản của 蘿. Bộ 艹 chỉ đây là thực vật, 罗 cho âm luó. Nghĩa: củ cải (萝卜), cây leo có rễ củ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"la\": cây (艹) như cái lưới la (罗) bò lan — dây leo la đà, hay củ la-bô (萝卜). | Gương Hán-Việt | la trong 萝卜 (la bặc — củ cải) và 藤萝 (đằng la — cây đằng leo) | Mở khoá kiến thức | Biết 萝 mở khoá: 萝卜 (củ cải), 胡萝卜 (cà rốt), 藤萝 (cây đằng leo).", "Tự nguyên_Xie": "seal | liushutong | 萝 là giản thể của 蘿. Theo Wiktionary, 蘿 = 艹 (thảo) biểu nghĩa + 羅 biểu âm. Nghĩa: loài cây leo, đặc biệt là 萝卜 (củ cải trắng/đỏ) và 藤萝 (cây leo dây). Chưa có nguồn học thuật chi tiết hơn về nguồn gốc xa. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "một loài nấm", "Hạng Tần Suất (Jun Da)": "2739.0", "Tần Suất % (Jun Da)": "98.8789612627", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 罗", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹罗", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "罗", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "萝", "Unihan_Traditional (Chữ Phồn thể)": "蘿", "Pinyin_Xie": "luó", "Âm Hán Việt_Xie": "la", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong tên gọi các loại cây dây leo hoặc củ cải. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('汹', '{"9000": "2740.0", "Chữ Trung Quốc": "汹", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 7 | nét | 氵 | thuỷ | biểu nghĩa | nước | 凶 | hung | biểu âm | hung dữ (cho âm xiōng) | 汹 = 氵 (Thuỷ, biểu nghĩa: nước) + 凶 (Hung, biểu âm). Chữ hình thanh — bộ thuỷ chỉ đây là nước, 凶 cho âm và gợi tính hung tợn của sóng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hung\": nước (氵) hung (凶) dữ — sóng cuộn dữ dội, chẳng ai dám vượt qua. | Gương Hán-Việt | \"hung\" trong \"hung hăng\" — cùng gợi sự mạnh mẽ, dữ dội | Mở khoá kiến thức | Biết 汹 (hung) mở khoá: 汹涌 (hung dũng — sóng cuồn cuộn, dữ dội); 气势汹汹 (khí thế hung hung — khí thế hung hăng).", "Tự nguyên_Xie": "Chữ hình thanh. 氵 (nước, biểu nghĩa) + 凶 (biểu âm, đồng thời gợi tính hung hãn). Nghĩa gốc là sóng to dữ dội, nước cuộn xoáy — thường dùng trong 汹涌 (sóng cuồn cuộn). Chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: hung dũng 洶湧,汹涌)", "Hạng Tần Suất (Jun Da)": "2740.0", "Tần Suất % (Jun Da)": "98.880348314", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 凶", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵凶", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "凶", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "汹", "Unihan_Traditional (Chữ Phồn thể)": "洶", "Pinyin_Xie": "xiōng", "Âm Hán Việt_Xie": "hung", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường làm tính từ miêu tả thế nước chảy mạnh mẽ hoặc khí thế hung hãn. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('腥', '{"9000": "2741.0", "Chữ Trung Quốc": "腥", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 13 | nét | 月 | nguyệt | biểu nghĩa | thịt, cơ thể (bộ nhục dạng trăng) | 星 | tinh | biểu âm | sao (cho âm xīng) | 腥 = 月 (bộ nhục, biểu nghĩa: thịt/cơ thể) + 星 (Tinh, biểu âm). Chữ hình thanh — bộ nhục chỉ đây là mùi từ thịt/cá sống, 星 cho âm xīng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tinh\": thịt (月/nhục) tanh như sao (星) mùi nồng nặc — mùi tanh của cá thịt sống, không thể chịu được. | Gương Hán-Việt | \"tinh\" trong \"tanh tinh\" — mùi tanh của thức ăn sống | Mở khoá kiến thức | Biết 腥 (tinh) mở khoá: 腥臭 (tinh xú — mùi tanh hôi); 腥味 (tinh vị — mùi tanh); 血腥 (huyết tinh — đẫm máu, man rợ).", "Tự nguyên_Xie": "Chữ hình thanh theo Wiktionary: 肉 (biểu nghĩa: thịt/cơ thể, viết tắt thành 月 trong chữ kép) + 星 (biểu âm). Nghĩa gốc là mùi tanh của thịt cá sống. Có thể liên quan đến màu đỏ thịt sống tươi. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thịt sống; tanh", "Hạng Tần Suất (Jun Da)": "2741.0", "Tần Suất % (Jun Da)": "98.8817317478", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 星", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月星", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "星", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "腥", "Unihan_Traditional (Chữ Phồn thể)": "腥", "Pinyin_Xie": "xīng", "Âm Hán Việt_Xie": "tinh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Thường dùng làm tính từ bổ nghĩa cho danh từ để chỉ mùi vị tanh của cá thịt. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | xīng | / | có mùi cá | / | xīng | / | thịt sống hoặc cá sống | Xuất hiện trong lộ trình | HSK | HSK 6 | · | Thức ăn và đồ uống | New HSK | New HSK 7-9 | · | Thực phẩm II", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('窥', '{"9000": "2742.0", "Chữ Trung Quốc": "窥", "Bộ thủ & thành phần_Xie": "Bộ thủ | 穴 | Số nét | 13 | nét | 穴 | huyệt | biểu nghĩa | hang, lỗ hổng — chỉ việc nhìn qua kẽ hở | 规 | quy | biểu âm | quy tắc, compa — cho âm kuī | 窥 = 穴 (Huyệt, biểu nghĩa: hang/lỗ hổng) + 规 (Quy, biểu âm); chữ hình thanh. Dạng giản của 窺. Bộ 穴 gợi hình ảnh nhìn qua lỗ, 规 cho âm kuī. Nghĩa: nhìn lén, rình mò.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khuy\": qua cái hang (穴) nhìn theo quy (规) tắc của kẻ rình — khuy phá, rình mò qua lỗ hổng. | Gương Hán-Việt | khuy trong 窥探 (khuy thám — dò xét) và 偷窥 (thâu khuy — nhìn lén) | Mở khoá kiến thức | Biết 窥 mở khoá: 偷窥 (nhìn lén), 窥探 (dò xét), 窥视 (quan sát bí mật).", "Tự nguyên_Xie": "seal | liushutong | 窥 là giản thể của 窺. Theo Wiktionary, 窺 = 穴 (huyệt — hang) biểu nghĩa + 規 biểu âm. Hình ảnh nhìn qua kẽ hở/cửa sổ nhỏ. Nghĩa gốc: nhìn qua kẽ hở; mở rộng sang ''rình mò, nhìn lén'' (偷窥), ''thăm dò, tìm hiểu'' (窥探). Chưa có nguồn học thuật chi tiết. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "dòm, ngó, nhìn trộm", "Hạng Tần Suất (Jun Da)": "2742.0", "Tần Suất % (Jun Da)": "98.8831131145", "GavinGrover_Once (Chiết tự trực tiếp)": "穴 + 规", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱穴规", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "规", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "穴", "Unihan_Simplified (Chữ Giản thể)": "窥", "Unihan_Traditional (Chữ Phồn thể)": "窺", "Pinyin_Xie": "kuī", "Âm Hán Việt_Xie": "khuy", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường dùng làm động từ đứng trước tân ngữ để chỉ hành vi nhìn lén hoặc thăm dò. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('俺', '{"9000": "2743.0", "Chữ Trung Quốc": "俺", "Bộ thủ & thành phần_Xie": "Bộ thủ | 人 | Số nét | 10 | nét | 亻 | nhân | biểu nghĩa | người — chỉ đại từ nhân xưng | 奄 | yểm | biểu âm | bao phủ — cho âm ǎn | 俺 = 亻(Nhân, biểu nghĩa: người) + 奄 (Yểm, biểu âm); chữ hình thanh. Bộ 亻chỉ đây là đại từ nhân xưng, 奄 cho âm ǎn. Nghĩa: tôi, tao (đại từ nhân xưng ngôi I trong phương ngữ Bắc Trung Quốc).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"yêm\": người (亻) bị bao phủ (奄) — tôi, cái tôi thu mình lại, kiểu nói dân dã. | Gương Hán-Việt | yêm trong cách dùng đại từ ngôi I dân dã miền Bắc Trung Quốc | Mở khoá kiến thức | Biết 俺 giúp nhận ra đại từ ngôi I trong phương ngữ và tiểu thuyết lịch sử Trung Quốc.", "Tự nguyên_Xie": "seal | liushutong | Theo Wiktionary (Digital Shinjigen 2017), 俺 là chữ hình thanh: 亻(nhân — người) biểu nghĩa, 奄 biểu âm. Vốn là đại từ nhân xưng ngôi I trong phương ngữ Sơn Đông và miền Bắc Trung Quốc. Cũng có nghĩa là ''ngươi, anh'' trong văn cổ (ngôi II). Hiện nay chủ yếu là đại từ ngôi I thân mật/thô dân dã. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ta, tôi", "Hạng Tần Suất (Jun Da)": "2743.0", "Tần Suất % (Jun Da)": "98.8844934476", "GavinGrover_Once (Chiết tự trực tiếp)": "亻 + 奄", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰亻奄", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "奄", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "亻", "Unihan_Simplified (Chữ Giản thể)": "俺", "Unihan_Traditional (Chữ Phồn thể)": "俺", "Pinyin_Xie": "ǎn", "Âm Hán Việt_Xie": "yêm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Đại từ | 代词 | Chữ này làm đại từ nhân xưng ngôi thứ nhất, thường đứng ở vị trí chủ ngữ hoặc định ngữ trong câu. | Đại từ | 代词 | Thay cho người hoặc vật đã nhắc tới (我, 这, 谁). Dùng đúng ở vị trí của danh từ. Chỉ người thì thêm 们 để thành số nhiều: 我们.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('潭', '{"9000": "2744.0", "Chữ Trung Quốc": "潭", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 15 | nét | 氵 | thuỷ | biểu nghĩa | nước — chỉ vùng nước sâu | 覃 | đàm | biểu âm | sâu, lan rộng — cho âm tán | 潭 = 氵(Thuỷ, biểu nghĩa: nước) + 覃 (Đàm, biểu âm); chữ hình thanh. Bộ 氵chỉ liên quan đến nước, 覃 cho âm tán. Nghĩa: vũng nước sâu, đầm, hồ sâu.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đàm\": nước (氵) sâu đằm đằm (覃) — hồ đàm, vũng nước sâu tĩnh lặng. | Gương Hán-Việt | đàm trong 泥潭 (nê đàm — vũng bùn lầy) và 深潭 (thâm đàm — hồ sâu) | Mở khoá kiến thức | Biết 潭 mở khoá: 泥潭 (vũng bùn), 深潭 (hồ sâu), 日月潭 (hồ Nhật Nguyệt Đài Loan).", "Tự nguyên_Xie": "seal | liushutong | Theo Wiktionary, 潭 là chữ hình thanh (形聲): 氵(thuỷ — nước) biểu nghĩa, 覃 biểu âm. Nghĩa gốc: vũng nước sâu, đầm lầy; mở rộng sang ''sâu thẳm''. Thường dùng trong địa danh (日月潭 — hồ Nhật Nguyệt ở Đài Loan). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái đầm", "Hạng Tần Suất (Jun Da)": "2744.0", "Tần Suất % (Jun Da)": "98.88587068", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "潭", "Unihan_Traditional (Chữ Phồn thể)": "潭", "Pinyin_Xie": "tán", "Âm Hán Việt_Xie": "đàm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ vực nước sâu, thường đứng sau các danh từ riêng hoặc kết hợp với lượng từ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('崎', '{"9000": "2745.0", "Chữ Trung Quốc": "崎", "Bộ thủ & thành phần_Xie": "Bộ thủ | 山 | Số nét | 11 | nét | 山 | sơn | biểu nghĩa | núi — chỉ địa hình núi non | 奇 | cơ | biểu âm | kỳ lạ — cho âm qí | 崎 = 山 (Sơn, biểu nghĩa: núi) + 奇 (Cơ, biểu âm); chữ hình thanh. Bộ 山 chỉ địa hình núi non, 奇 cho âm qí. Nghĩa: gồ ghề, hiểm trở — thường dùng trong 崎岖 (đường núi gập ghềnh).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khi\": núi (山) kỳ lạ gồ ghề (奇) — đường khi khúc khuỷu, hiểm trở. | Gương Hán-Việt | khi trong 崎岖 (khi khu — đường núi gập ghềnh, gồ ghề) | Mở khoá kiến thức | Biết 崎 mở khoá: 崎岖 (gập ghềnh, gồ ghề), dùng cả nghĩa bóng về cuộc đời gian nan.", "Tự nguyên_Xie": "Theo Wiktionary, 崎 là chữ hình thanh (形聲): 山 (sơn — núi) biểu nghĩa, 奇 biểu âm. Nghĩa: địa hình gồ ghề, hiểm trở; thường chỉ đường núi khó đi (崎岖). Chưa có nguồn học thuật chi tiết về nguồn gốc xa. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: khi khu 崎嶇,崎岖)", "Hạng Tần Suất (Jun Da)": "2745.0", "Tần Suất % (Jun Da)": "98.887246362", "GavinGrover_Once (Chiết tự trực tiếp)": "山 + 奇", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰山奇", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "奇", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "山", "Unihan_Simplified (Chữ Giản thể)": "崎", "Unihan_Traditional (Chữ Phồn thể)": "崎", "Pinyin_Xie": "qí", "Âm Hán Việt_Xie": "khi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này thường kết hợp với chữ Khu tạo thành từ ghép để làm tính từ miêu tả đường sá hiểm trở. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('麟', '{"9000": "2746.0", "Chữ Trung Quốc": "麟", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鹿 | Số nét | 23 | nét | 鹿 | lộc | biểu nghĩa | hươu — chỉ loài thú linh thiêng | 粦 | lân | biểu âm | ma trơi — cho âm lín | 麟 = 鹿 (Lộc, biểu nghĩa: hươu) + 粦 (Lân, biểu âm); chữ hình thanh. Bộ 鹿 chỉ đây là loài thú thuộc họ hươu, 粦 cho âm lín. Nghĩa: con lân (kỳ lân), linh vật thiêng liêng trong thần thoại Trung Hoa.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lân\": hươu (鹿) phát sáng như lửa ma (粦) — con lân kỳ diệu, linh vật bước qua không hại cỏ. | Gương Hán-Việt | lân trong 麒麟 (kỳ lân — linh vật) và 麟凤 (lân phụng — điềm lành) | Mở khoá kiến thức | Biết 麟 mở khoá: 麒麟 (kỳ lân), 麟儿 (con trai quý giá), 凤毛麟角 (hiếm hoi như lông phượng sừng lân).", "Tự nguyên_Xie": "seal | liushutong | Theo Wiktionary, 麟 là chữ hình thanh (形聲): 鹿 (lộc — hươu) biểu nghĩa, 粦 biểu âm. Nghĩa: kỳ lân (麒麟), linh vật thần thoại hình thù như hươu có vảy và một sừng. Tượng trưng cho điều lành, bậc thánh nhân. Xuất hiện từ Chu Lễ. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con kỳ lân (như: kỳ lân 麒麟)", "Hạng Tần Suất (Jun Da)": "2746.0", "Tần Suất % (Jun Da)": "98.8886204937", "GavinGrover_Once (Chiết tự trực tiếp)": "鹿 + 粦", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴鹿粦", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "粦", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鹿", "Unihan_Simplified (Chữ Giản thể)": "麟", "Unihan_Traditional (Chữ Phồn thể)": "麐", "Pinyin_Xie": "lín", "Âm Hán Việt_Xie": "lân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ loài linh thú cát tường, thường đi kèm với chữ Kỳ hoặc đứng độc lập. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('捡', '{"9000": "2747.0", "Chữ Trung Quốc": "捡", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 10 | nét | 扌 | thủ | biểu nghĩa | tay | 佥 | thiêm | biểu âm | đều, tất cả — cho âm thiêm/kiểm | 捡 = 扌(Thủ, biểu nghĩa: tay) + 佥 (Thiêm, biểu âm). Wiktionary ghi đây là chữ giản thể của 撿 (giản hoá 僉 thành 佥). Hình thanh: bộ thủ chỉ hành động tay; 佥 cho âm jiǎn (gần kiểm). Nhặt lên bằng tay.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"kiểm\": tay (扌-Thủ) kiểm tra (佥-Thiêm) — dùng tay kiểm nhặt đồ rơi. Kiểm = nhặt lên. | Gương Hán-Việt | kiểm trong ''kiểm tra'' — cùng âm; 捡 là nhặt vật rơi, không liên quan kiểm soát | Mở khoá kiến thức | Biết 捡 mở khoá: 捡到 (kiểm đáo – nhặt được), 捡起 (kiểm khởi – nhặt lên), 拾捡 (thập kiểm – nhặt nhạnh).", "Tự nguyên_Xie": "捡 là chữ giản thể của 撿. Wiktionary ghi: {{Han simp|撿|f=僉|t=佥}}. Chữ truyền thống 撿 = 扌+ 僉, là chữ hình thanh: 扌(thủ – tay) biểu nghĩa, 僉 (thiêm) biểu âm. Nghĩa là nhặt lên, bắt được vật rơi. Không có glyphOrigin chi tiết hơn cho chữ gốc. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nhặt lên; bắt được, nhặt được", "Hạng Tần Suất (Jun Da)": "2747.0", "Tần Suất % (Jun Da)": "98.8899915246", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 佥", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌佥", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "佥", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "捡", "Unihan_Traditional (Chữ Phồn thể)": "撿", "Pinyin_Xie": "jiǎn", "Âm Hán Việt_Xie": "kiểm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ chỉ hành động nhặt vật gì đó lên, thường mang theo tân ngữ phía sau. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | Từ đơn | Từ vựng HSK 5: nhặt lên | / | jiǎn | / | nhặt lên | Xuất hiện trong lộ trình | New HSK | New HSK 6 | · | Động từ | HSK | HSK 5 | · | Động từ hàng ngày", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('拯', '{"9000": "2748.0", "Chữ Trung Quốc": "拯", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 9 | nét | 扌 | thủ | biểu nghĩa | tay — chỉ hành động dùng tay | 丞 | thừa | biểu âm | giúp đỡ, phụ tá — gợi nghĩa và cho âm zhěng | 拯 = 扌(Thủ, biểu nghĩa: tay) + 丞 (Thừa, biểu âm và gợi nghĩa); chữ vừa hình thanh vừa hội ý (lsCodes: ic + psc). Bộ 扌chỉ hành động dùng tay, 丞 vừa cho âm zhěng vừa gợi ý ''giúp đỡ, hỗ trợ''. Nghĩa: cứu vớt, giải thoát.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chửng\": bàn tay (扌) của người thừa (丞) quan — chửng, kéo người lên khỏi nạn. | Gương Hán-Việt | chửng trong 拯救 (chửng cứu — cứu vớt, giải thoát) | Mở khoá kiến thức | Biết 拯 mở khoá: 拯救 (cứu vớt), 拯民 (chửng dân — cứu dân).", "Tự nguyên_Xie": "oracle | bronze | seal | liushutong | Theo Wiktionary, 拯 là chữ hình thanh (形聲): 手 (thủ — tay) biểu nghĩa, 丞 biểu âm. Cũng có thể phân tích theo hội ý: tay giúp đỡ (丞 — phụ tá, giúp đỡ). Nghĩa gốc và hiện tại: cứu vớt, giải cứu. Dùng chủ yếu trong 拯救 (cứu vớt). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cứu", "Hạng Tần Suất (Jun Da)": "2748.0", "Tần Suất % (Jun Da)": "98.8913610052", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 丞", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌丞", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "丞", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "拯", "Unihan_Traditional (Chữ Phồn thể)": "拯", "Pinyin_Xie": "zhěng", "Âm Hán Việt_Xie": "chửng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ chỉ hành động cứu vớt, thường kết hợp với chữ Cứu thành từ ghép trước một tân ngữ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('厥', '{"9000": "2749.0", "Chữ Trung Quốc": "厥", "Bộ thủ & thành phần_Xie": "Bộ thủ | 厂 | Số nét | 12 | nét | 厂 | hán | biểu nghĩa | vách đá, mái che — chỉ nơi che khuất | 欮 | quyết | biểu âm | phức hợp gồm 屮 và 欠 — cho âm jué | 厥 = 厂 (Hán, biểu nghĩa: vách đá) + 欮 (biểu âm: gồm 屰 và 欠); chữ hình thanh. Bộ 厂 biểu nghĩa môi trường che khuất/sụp đổ, 欮 cho âm jué. Nghĩa: ngã ra bất tỉnh (厥逆); đại từ chỉ sở hữu trong văn cổ (''của nó, của họ'').", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quyết\": dưới mái đá (厂) hơi thở (欠) trào ngược (屰) — quyết ngã, bất tỉnh nhân sự. | Gương Hán-Việt | quyết trong 昏厥 (hôn quyết — ngất xỉu) và 厥逆 (quyết nghịch — khí nghịch lên) | Mở khoá kiến thức | Biết 厥 mở khoá: 昏厥 (ngất xỉu), 厥逆 (khí huyết nghịch), 厥功甚伟 (công lao to lớn — văn cổ).", "Tự nguyên_Xie": "oracle | bronze | seal | liushutong | Theo Wiktionary, 厥 là chữ hình thanh (形聲): 厂 (hán — mái đá) biểu nghĩa, 欮 biểu âm. Nghĩa gốc liên quan đến sụp đổ, ngã ra; trong y học cổ: 厥逆 (ngất xỉu, khí huyết nghịch lên). Trong văn ngôn: đại từ sở hữu ngôi ba ''của nó''. Hiện đại: hôn mê, ngất (昏厥). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "của hắn, của anh ta", "Hạng Tần Suất (Jun Da)": "2749.0", "Tần Suất % (Jun Da)": "98.8927304858", "GavinGrover_Once (Chiết tự trực tiếp)": "厂 + 欮", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴厂欮", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "欮", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "厂", "Unihan_Simplified (Chữ Giản thể)": "厥", "Unihan_Traditional (Chữ Phồn thể)": "厥", "Pinyin_Xie": "jué", "Âm Hán Việt_Xie": "quyết", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Đại từ | 代词 | Động từ | 动词 | Chữ này làm đại từ chỉ thị hoặc sở hữu trong văn ngôn, thường đứng trước danh từ để bổ nghĩa. | Đại từ | 代词 | Thay cho người hoặc vật đã nhắc tới (我, 这, 谁). Dùng đúng ở vị trí của danh từ. Chỉ người thì thêm 们 để thành số nhiều: 我们. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('澄', '{"9000": "2750.0", "Chữ Trung Quốc": "澄", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 15 | nét | 氵 | thuỷ | biểu nghĩa | nước | 登 | đăng | biểu âm | lên (cho âm chéng) | 澄 = 氵 (Thuỷ, biểu nghĩa: nước) + 登 (Đăng, biểu âm). Chữ hình thanh — nước trong, lắng đọng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trừng\": nước (氵) lắng xuống như leo lên (登) đỉnh cao — trừng mắt nhìn thấy tận đáy vì nước quá trong. | Gương Hán-Việt | \"trừng\" trong \"trừng mắt\" (nhìn chòng chọc) và \"thanh trừng\" (làm trong sạch) | Mở khoá kiến thức | Biết 澄 (trừng) mở khoá: 澄清 (trừng thanh — làm trong sạch, làm rõ); 清澄 (thanh trừng — trong vắt).", "Tự nguyên_Xie": "Chữ hình thanh theo Wiktionary: 氵 (nước, biểu nghĩa) + 登 (biểu âm) — nước trong, lắng đọng. Nghĩa gốc là nước trong vắt, không vẩn đục. Từ đó có thêm nghĩa ''làm trong, làm rõ''. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "trong (nước); lọc", "Hạng Tần Suất (Jun Da)": "2750.0", "Tần Suất % (Jun Da)": "98.8940994497", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 登", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵登", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "登", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "澄", "Unihan_Traditional (Chữ Phồn thể)": "澂", "Pinyin_Xie": "chéng", "Âm Hán Việt_Xie": "trừng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Chữ này làm tính từ miêu tả trạng thái nước trong suốt hoặc làm động từ chỉ việc lọc nước cho trong. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('萎', '{"9000": "2751.0", "Chữ Trung Quốc": "萎", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 11 | nét | 艹 | thảo | biểu nghĩa | cỏ, thực vật | 委 | uỷ | biểu âm | uỷ thác, rũ xuống (cho âm wěi) | 萎 = 艹 (Thảo, biểu nghĩa: cây cỏ) + 委 (Uỷ, biểu âm). Chữ hình thanh — 艹 chỉ đây là thực vật, 委 cho âm wěi và gợi hình ảnh rũ xuống, héo úa.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"uỷ\": cây cỏ (艹) uỷ rũ (委) xuống — hình ảnh bông hoa héo tàn, rủ xuống không còn sức sống. | Gương Hán-Việt | \"uỷ\" trong \"suy uỷ\" (suy tàn, héo úa) | Mở khoá kiến thức | Biết 萎 (uỷ) mở khoá: 枯萎 (khô uỷ — héo tàn, khô héo); 萎缩 (uỷ súc — teo tóp, suy giảm); 凋萎 (điêu uỷ — điêu tàn).", "Tự nguyên_Xie": "Chữ hình thanh theo Wiktionary: 艹 (thảo, biểu nghĩa) + 委 (biểu âm). Nghĩa gốc là cây cỏ héo, tàn lụi. 委 vừa cho âm vừa gợi ý nghĩa ''rủ xuống, mềm nhũn'' — đúng hình ảnh cây héo rũ. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "khô héo; (xem: nuy nhuy 萎蕤)", "Hạng Tần Suất (Jun Da)": "2751.0", "Tần Suất % (Jun Da)": "98.8954673799", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 委", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹委", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "委", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "萎", "Unihan_Traditional (Chữ Phồn thể)": "萎", "Pinyin_Xie": "wēi", "Âm Hán Việt_Xie": "uỷ, uy", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Chữ này làm động từ hoặc tính từ chỉ trạng thái khô héo của hoa cỏ hoặc sự suy giảm tinh thần. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('哉', '{"9000": "2752.0", "Chữ Trung Quốc": "哉", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 9 | nét | 𢦏 | tai | biểu âm | phức hợp gồm 戈 và 十 — cho âm zāi | 口 | khẩu | biểu nghĩa | miệng — chỉ lời than/cảm thán | 哉 = 𢦏 (biểu âm: gồm 戈 và 十) + 口 (Khẩu, biểu nghĩa: miệng); chữ hình thanh. Bộ 口 chỉ đây là tiếng thốt ra từ miệng, 𢦏 cho âm zāi. Nghĩa: trợ từ cảm thán trong văn ngôn, tương đương ''ôi'', ''thay'', ''vậy thay''.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tai\": miệng (口) thốt lên khi thấy giáo (戈) trên thập (十) — tai ôi, lời than thở xúc động. | Gương Hán-Việt | tai trong 善哉 (thiện tai — hay lắm thay!) và 悲哉 (bi tai — thương thay!) | Mở khoá kiến thức | Biết 哉 giúp đọc hiểu văn ngôn: 善哉, 何其...哉, 不亦...乎.", "Tự nguyên_Xie": "oracle | bronze | seal | liushutong | Theo Wiktionary, 哉 là chữ hình thanh (形聲): 口 (khẩu — miệng) biểu nghĩa, 𢦏 biểu âm. Nghĩa gốc và hiện tại: trợ từ cảm thán cuối câu trong văn ngôn Hán. Xuất hiện từ giáp cốt văn và kim văn, rất phổ biến trong Kinh Thi, Luận Ngữ. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "rất, lắm (ý nhấn mạnh); vừa mới; sao, đâu (trong câu hỏi); vậy, thay (trong câu cảm thán)", "Hạng Tần Suất (Jun Da)": "2752.0", "Tần Suất % (Jun Da)": "98.8968353102", "GavinGrover_Once (Chiết tự trực tiếp)": "𢦏 + 口", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴𢦏口", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "𢦏", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "哉", "Unihan_Traditional (Chữ Phồn thể)": "哉", "Pinyin_Xie": "zāi", "Âm Hán Việt_Xie": "tai", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Trợ từ | 助词 | Chữ này làm trợ từ ngữ khí đặt ở cuối câu để biểu thị sự cảm thán hoặc nghi vấn trong văn ngôn. | Trợ từ | 助词 | Không mang nghĩa riêng, gắn vào câu để đánh dấu ngữ pháp hoặc ngữ khí: 的 / 地 / 得 (kết cấu), 了 / 着 / 过 (thể), 吗 / 呢 / 吧 (nghi vấn, ngữ khí).", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('涡', '{"9000": "2753.0", "Chữ Trung Quốc": "涡", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 10 | nét | 氵 | thuỷ | biểu nghĩa | nước — chỉ hiện tượng nước | 呙 | qua | biểu âm | rút gọn từ 咼 — cho âm wō | 涡 = 氵(Thuỷ, biểu nghĩa: nước) + 呙 (Qua, biểu âm rút gọn từ 咼); chữ hình thanh. Dạng giản của 渦. Bộ 氵chỉ liên quan đến nước, 呙 cho âm wō. Nghĩa: dòng xoáy nước, vòng xoáy.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"qua\": nước (氵) xoáy vòng như cái miệng (呙) — qua vòng xoáy, dòng nước cuộn tròn. | Gương Hán-Việt | qua trong 漩涡 (toàn qua — vòng xoáy nước) và 涡流 (qua lưu — dòng xoáy) | Mở khoá kiến thức | Biết 涡 mở khoá: 漩涡 (vòng xoáy), 涡流 (dòng xoáy — eddy current), 气涡 (xoáy khí).", "Tự nguyên_Xie": "涡 là giản thể của 渦. Theo Wiktionary, 渦 = 氵(thuỷ) biểu nghĩa + 咼 biểu âm, giản thể thành 呙. Nghĩa gốc: dòng nước xoáy tròn; mở rộng sang bất cứ thứ gì xoáy tròn (漩涡 — vòng xoáy, xoáy nước). Chưa có nguồn học thuật chi tiết. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sông Qua (ở tỉnh An Huy của Trung Quốc)", "Hạng Tần Suất (Jun Da)": "2753.0", "Tần Suất % (Jun Da)": "98.8982016901", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 呙", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵呙", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "呙", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "涡", "Unihan_Traditional (Chữ Phồn thể)": "渦", "Pinyin_Xie": "wō", "Âm Hán Việt_Xie": "oa, qua", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ vùng nước xoáy hoặc tên sông, thường kết hợp với các từ chỉ bộ phận cơ thể. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('滔', '{"9000": "2754.0", "Chữ Trung Quốc": "滔", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 13 | nét | 氵 | thuỷ | biểu nghĩa | nước | 舀 | yểu | biểu âm | múc nước (cho âm tāo) | 滔 = 氵 (Thuỷ, biểu nghĩa: nước) + 舀 (Yểu, biểu âm). Chữ hình thanh — bộ thuỷ chỉ đây là nước, 舀 cho âm tāo.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thao\": nước (氵) múc (舀) không cạn — sóng cuộn cuộn như dòng chữ thao thao bất tuyệt. | Gương Hán-Việt | \"thao\" trong \"thao thao\" (nói không ngừng) và \"thao lược\" (tài năng chiến lược) | Mở khoá kiến thức | Biết 滔 (thao) mở khoá: 滔滔不绝 (thao thao bất tuyệt — nói không ngừng); 滔天 (thao thiên — tày trời, cực lớn).", "Tự nguyên_Xie": "Chữ hình thanh. 氵 (nước, biểu nghĩa) + 舀 (biểu âm). Nghĩa gốc là nước tràn bờ, cuộn chảy ào ạt. Chưa có nguồn học thuật chi tiết cho glyph origin riêng. | Suy từ bộ phận cấu thành · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: thao thao 滔滔)", "Hạng Tần Suất (Jun Da)": "2754.0", "Tần Suất % (Jun Da)": "98.8995670364", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 舀", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵舀", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "舀", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "滔", "Unihan_Traditional (Chữ Phồn thể)": "滔", "Pinyin_Xie": "tāo", "Âm Hán Việt_Xie": "thao", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Chữ này thường dùng làm tính từ trong từ láy để miêu tả dòng nước chảy xiết hoặc lời nói liên tục. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('暇', '{"9000": "2755.0", "Chữ Trung Quốc": "暇", "Bộ thủ & thành phần_Xie": "Bộ thủ | 日 | Số nét | 13 | nét | 日 | nhật | biểu nghĩa | mặt trời, ngày — chỉ thời gian | 叚 | giả | biểu âm | vay mượn — cho âm xiá | 暇 = 日 (Nhật, biểu nghĩa: ngày/thời gian) + 叚 (Giả, biểu âm); chữ hình thanh. Bộ 日 chỉ liên quan đến thời gian, 叚 cho âm xiá. Nghĩa: thời gian rảnh rỗi, lúc nhàn hạ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hạ\": ngày (日) mượn thêm (叚) — hạ, khoảng thời gian vay thêm được để nghỉ ngơi. | Gương Hán-Việt | hạ trong 闲暇 (nhàn hạ — thời gian rảnh) và 无暇 (vô hạ — không có rảnh) | Mở khoá kiến thức | Biết 暇 mở khoá: 闲暇 (thời gian nhàn rỗi), 无暇 (không có thời gian), 自顾不暇 (lo thân không xuể).", "Tự nguyên_Xie": "seal | liushutong | Theo Wiktionary, 暇 là chữ hình thanh (形聲): 日 (nhật — ngày) biểu nghĩa, 叚 biểu âm. Nghĩa gốc: thời gian rảnh rỗi, không bận bịu. Dùng trong 闲暇 (nhàn hạ), 无暇 (không có thời gian rảnh). Xuất hiện từ cổ văn. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "rảnh rỗi; thôi, nghỉ", "Hạng Tần Suất (Jun Da)": "2755.0", "Tần Suất % (Jun Da)": "98.9009318659", "GavinGrover_Once (Chiết tự trực tiếp)": "日 + 叚", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰日叚", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "叚", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "日", "Unihan_Simplified (Chữ Giản thể)": "暇", "Unihan_Traditional (Chữ Phồn thể)": "暇", "Pinyin_Xie": "xiá", "Âm Hán Việt_Xie": "hạ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ làm tân ngữ trong cụm từ chỉ thời gian rảnh rỗi như vô hạ, đắc hạ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('溯', '{"9000": "2756.0", "Chữ Trung Quốc": "溯", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 13 | nét | 氵 | thuỷ | biểu nghĩa | nước — chỉ dòng sông, hướng đi ngược | 朔 | sóc | biểu âm | mồng một, phương bắc — cho âm sù | 溯 = 氵(Thuỷ, biểu nghĩa: nước/sông) + 朔 (Sóc, biểu âm); chữ hình thanh. Bộ 氵chỉ liên quan đến sông nước, 朔 cho âm sù. Nghĩa: ngược dòng, truy tìm về nguồn gốc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tố\": nước (氵) ngược về hướng sóc (朔 — phương bắc) — tố nguyên, truy ngược về nguồn. | Gương Hán-Việt | tố trong 追溯 (truy tố — truy nguyên, truy về quá khứ) | Mở khoá kiến thức | Biết 溯 mở khoá: 追溯 (truy nguyên), 溯源 (tìm về nguồn gốc), 溯流而上 (ngược dòng đi lên).", "Tự nguyên_Xie": "seal | liushutong | Theo Wiktionary, 溯 là chữ hình thanh (形聲): 氵(thuỷ — nước) biểu nghĩa, 朔 biểu âm. Nghĩa gốc: đi ngược dòng nước; mở rộng sang ''truy nguồn, tìm về gốc'' (追溯 — truy nguyên). Từ 朔 (sóc — hướng bắc, mồng một) gợi hình ảnh đi về phía nguồn, phía trên. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ngoi lên, bơi ngược dòng", "Hạng Tần Suất (Jun Da)": "2756.0", "Tần Suất % (Jun Da)": "98.9022956619", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 朔", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵朔", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "朔", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "溯", "Unihan_Traditional (Chữ Phồn thể)": "溯", "Pinyin_Xie": "sù", "Âm Hán Việt_Xie": "tố", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước tân ngữ chỉ nguồn gốc hoặc thời gian để biểu thị việc truy tìm lại quá khứ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鳞', '{"9000": "2757.0", "Chữ Trung Quốc": "鳞", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 20 | nét | 鱼 | ngư | biểu nghĩa | cá — chỉ bộ phận của cá | 粦 | lân | biểu âm | ma trơi — cho âm lín | 鳞 = 鱼 (Ngư, biểu nghĩa: cá) + 粦 (Lân, biểu âm); chữ hình thanh. Bộ 鱼 chỉ liên quan đến cá, 粦 cho âm lín. Nghĩa: vảy cá; bất cứ thứ gì có hình dạng như vảy.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lân\": cá (鱼) sáng lên như lửa ma (粦) — vảy lân, vảy cá ánh lên dưới nước. | Gương Hán-Việt | lân trong 鱼鳞 (ngư lân — vảy cá) và 鳞片 (lân phiến — mảnh vảy) | Mở khoá kiến thức | Biết 鳞 mở khoá: 鱼鳞 (vảy cá), 鳞次栉比 (san sát dày đặc), 遍体鳞伤 (thương tích đầy mình).", "Tự nguyên_Xie": "seal | liushutong | Theo Wiktionary, 鳞 (phồn thể: 鱗) là chữ hình thanh (形聲): 魚 (ngư — cá) biểu nghĩa, 粦 biểu âm. Nghĩa gốc: vảy cá; mở rộng sang ''bất cứ vật có vảy'' như vảy rồng, vảy rắn (鳞片). Cũng dùng trong thành ngữ 鳞次栉比 (san sát như vảy cá lược). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "vẩy cá, vảy cá; xếp hàng lần lượt", "Hạng Tần Suất (Jun Da)": "2757.0", "Tần Suất % (Jun Da)": "98.9036573907", "GavinGrover_Once (Chiết tự trực tiếp)": "鱼 + 粦", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰鱼粦", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "粦", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鱼", "Unihan_Simplified (Chữ Giản thể)": "鳞", "Unihan_Traditional (Chữ Phồn thể)": "鱗", "Pinyin_Xie": "lín", "Âm Hán Việt_Xie": "lân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng sau định ngữ hoặc kết hợp tạo thành từ ghép chỉ các loài có vảy. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('酿', '{"9000": "2758.0", "Chữ Trung Quốc": "酿", "Bộ thủ & thành phần_Xie": "Bộ thủ | 酉 | Số nét | 14 | nét | 酉 | dậu | biểu nghĩa | bình rượu, men rượu | 良 | lương | biểu âm | tốt lành (cho âm niàng) | 酿 = 酉 (Dậu, biểu nghĩa: bình rượu/men rượu) + 良 (Lương, biểu âm). Chữ hình thanh — bộ dậu chỉ liên quan đến rượu, 良 cho âm niàng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nhưỡng\": bình rượu (酉) ủ điều tốt lành (良) — ủ men, tạo ra kết quả theo thời gian. | Gương Hán-Việt | \"nhưỡng\" trong \"nhưỡng tạo\" (ủ tạo ra) | Mở khoá kiến thức | Biết 酿 (nhưỡng) mở khoá: 酿酒 (nhưỡng tửu — ủ rượu); 酿成 (nhưỡng thành — gây ra, dẫn đến); 酿造 (nhưỡng tạo — ủ, sản xuất bằng lên men).", "Tự nguyên_Xie": "Chữ hình thanh. 酉 (bình rượu, biểu nghĩa) + 良 (biểu âm). Nghĩa gốc là ủ rượu, lên men — quy trình tạo ra rượu bằng cách để nguyên liệu lên men trong bình. Từ đó mở rộng sang nghĩa ''gây ra, tạo thành'' (thường trong ngữ cảnh tiêu cực: 酿成悲剧). Chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "gây nên; dựng, cất", "Hạng Tần Suất (Jun Da)": "2758.0", "Tần Suất % (Jun Da)": "98.905018086", "GavinGrover_Once (Chiết tự trực tiếp)": "酉 + 良", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰酉良", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "良", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "酉", "Unihan_Simplified (Chữ Giản thể)": "酿", "Unihan_Traditional (Chữ Phồn thể)": "釀", "Pinyin_Xie": "niàng", "Âm Hán Việt_Xie": "nhưỡng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước tân ngữ chỉ sản phẩm lên men hoặc hậu quả do sự việc gây ra. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('茵', '{"9000": "2759.0", "Chữ Trung Quốc": "茵", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 9 | nét | 艹 | thảo | biểu nghĩa | cỏ — chỉ thực vật, thảm cỏ | 因 | nhân | biểu âm | nhân tố, vì — cho âm yīn | 茵 = 艹 (Thảo, biểu nghĩa: thực vật) + 因 (Nhân, biểu âm); chữ hình thanh. Bộ 艹 chỉ đây là thực vật, 因 cho âm yīn. Nghĩa: thảm cỏ, nệm cỏ; lớp lót mềm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nhân\": cỏ (艹) là nhân tố (因) tạo thảm xanh — thảm nhân, lớp cỏ mềm mại trải dưới chân. | Gương Hán-Việt | nhân trong 绿茵 (lục nhân — thảm cỏ xanh) và 茵陈 (nhân trần — thảo dược) | Mở khoá kiến thức | Biết 茵 mở khoá: 绿茵茵 (cỏ xanh mướt), 茵陈 (nhân trần thảo dược), 绿茵场 (sân cỏ xanh).", "Tự nguyên_Xie": "seal | liushutong | Theo Wiktionary, 茵 là chữ hình thanh (形聲): 艹 (thảo — cỏ) biểu nghĩa, 因 biểu âm. Nghĩa gốc: thảm cỏ, nệm cỏ làm lớp lót. Trong thơ cổ, 绿茵茵 mô tả thảm cỏ xanh mướt. Cũng dùng trong 茵陈 (nhân trần — cây thảo dược). | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đệm, chiếu kép; (xem: nhân trần 茵陳,茵蔯,茵陈)", "Hạng Tần Suất (Jun Da)": "2759.0", "Tần Suất % (Jun Da)": "98.9063777477", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 因", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹因", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "因", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "茵", "Unihan_Traditional (Chữ Phồn thể)": "茵", "Pinyin_Xie": "yīn", "Âm Hán Việt_Xie": "nhân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ trong văn viết để chỉ tấm đệm êm ái hoặc thảm cỏ xanh mướt. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('愕', '{"9000": "2760.0", "Chữ Trung Quốc": "愕", "Bộ thủ & thành phần_Xie": "Bộ thủ | 心 | Số nét | 12 | nét | 忄 | tâm | biểu nghĩa | tim, lòng — chỉ trạng thái tâm lý | 咢 | ngạc | biểu âm | kêu la — cho âm è | 愕 = 忄(Tâm, biểu nghĩa: tâm trí) + 咢 (Ngạc, biểu âm); chữ hình thanh. Bộ 忄chỉ đây là trạng thái cảm xúc, 咢 cho âm è. Nghĩa: kinh ngạc, sửng sốt.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ngạc\": lòng (忄) phát tiếng kêu ngạc (咢) — ngạc nhiên sửng sốt, há hốc mồm. | Gương Hán-Việt | ngạc trong 愕然 (ngạc nhiên — sửng sốt) và 惊愕 (kinh ngạc — kinh hãi sửng sốt) | Mở khoá kiến thức | Biết 愕 mở khoá: 愕然 (sửng sốt), 惊愕 (kinh ngạc), 目瞪口愕 (biến thể của 目瞪口呆).", "Tự nguyên_Xie": "Wiktionary ghi nhận 愕 là chữ hình thanh với cấu trúc 忄+ 咢, nhưng không có chi tiết glyphOrigin học thuật. Cấu trúc rõ ràng: 忄(tâm — cảm xúc) biểu nghĩa + 咢 biểu âm. Nghĩa: kinh ngạc đến mức lặng người. Gần đồng nghĩa với 愣 (sửng sốt) nhưng mang sắc thái sốc mạnh hơn. Chưa có nguồn học thuật chi tiết. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ngạc nhiên, kinh ngạc", "Hạng Tần Suất (Jun Da)": "2760.0", "Tần Suất % (Jun Da)": "98.9077374094", "GavinGrover_Once (Chiết tự trực tiếp)": "忄 + 咢", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰忄咢", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "咢", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "忄", "Unihan_Simplified (Chữ Giản thể)": "愕", "Unihan_Traditional (Chữ Phồn thể)": "愕", "Pinyin_Xie": "è", "Âm Hán Việt_Xie": "ngạc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường làm tính từ đứng trước động từ để chỉ trạng thái kinh ngạc hoặc kết hợp thành từ ghép như kinh ngạc. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('瞅', '{"9000": "2761.0", "Chữ Trung Quốc": "瞅", "Bộ thủ & thành phần_Xie": "Bộ thủ | 目 | Số nét | 14 | nét | 目 | mục | biểu nghĩa | mắt — chỉ hành động nhìn | 秋 | thu | biểu âm | mùa thu — cho âm chǒu | 瞅 = 目 (Mục, biểu nghĩa: mắt) + 秋 (Thu, biểu âm); chữ hình thanh. Theo Wiktionary, đây là chữ hậu khởi (後起字 — tạo muộn). Bộ 目 chỉ hành động mắt, 秋 cho âm chǒu. Nghĩa: nhìn, liếc (phương ngữ Bắc Trung Quốc).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thu\": mắt (目) nhìn màu thu (秋) — liếc mắt nhìn thoáng qua như ánh thu. | Gương Hán-Việt | thu trong cách dùng 瞅一眼 (nhìn một cái) trong phương ngữ Bắc | Mở khoá kiến thức | Biết 瞅 giúp đọc hiểu hội thoại khẩu ngữ miền Bắc Trung Quốc: 瞅什么 (nhìn gì vậy?).", "Tự nguyên_Xie": "Theo Wiktionary, 瞅 là chữ hậu khởi (後起字 — tạo muộn, không có trong giáp cốt hay kim văn cổ): 目 (mục — mắt) biểu nghĩa, 秋 biểu âm (tr2=qiū). Nghĩa: nhìn, liếc; chủ yếu dùng trong phương ngữ Bắc Trung Quốc (口语). Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nhìn, trông thấy; (xem: thu thải 瞅睬)", "Hạng Tần Suất (Jun Da)": "2761.0", "Tần Suất % (Jun Da)": "98.9090944871", "GavinGrover_Once (Chiết tự trực tiếp)": "目 + 秋", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰目秋", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "秋", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "目", "Unihan_Simplified (Chữ Giản thể)": "瞅", "Unihan_Traditional (Chữ Phồn thể)": "瞅", "Pinyin_Xie": "chǒu", "Âm Hán Việt_Xie": "thu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ vị ngữ trong khẩu ngữ để chỉ hành động nhìn hoặc quan sát ai đó. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | chǒu | / | nhìn | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Động từ tôi", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('暮', '{"9000": "2762.0", "Chữ Trung Quốc": "暮", "Bộ thủ & thành phần_Xie": "Bộ thủ | 日 | Số nét | 14 | nét | 莫 | mạc | biểu âm | hoàng hôn (nguyên tự) | 日 | nhật | biểu nghĩa | mặt trời | 暮 là chữ hình thanh: 莫 (Mạc) biểu âm, 日 (Nhật) biểu nghĩa chỉ mặt trời. Ban đầu 莫 chính là chữ tượng hình biểu thị hoàng hôn; sau đó thêm 日 để phân biệt nghĩa.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mộ\": mặt trời (日) chìm dưới lùm cây (莫) — khắc hoạ khoảnh khắc hoàng hôn rực rỡ. | Gương Hán-Việt | mộ trong 暮色 (mộ sắc — cảnh hoàng hôn), 暮年 (mộ niên — tuổi già) | Mở khoá kiến thức | Biết 暮 mở khoá: 朝三暮四, 日暮途窮, 暮色, 垂暮之年.", "Tự nguyên_Xie": "Lục thư thông | Theo Wiktionary, 暮 là chữ hình thanh, 莫 vốn là tượng hình gốc của từ này (mặt trời lặn sau cây cỏ), sau thêm 日 để tách biệt nghĩa ''chiều tối'' khỏi 莫. Trong giáp cốt văn, 莫 đã mang nghĩa hoàng hôn. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "buổi chiều tối", "Hạng Tần Suất (Jun Da)": "2762.0", "Tần Suất % (Jun Da)": "98.9104515649", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "暮", "Unihan_Traditional (Chữ Phồn thể)": "暮", "Pinyin_Xie": "mù", "Âm Hán Việt_Xie": "mộ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Thường làm danh từ chỉ thời gian hoặc làm tính từ bổ nghĩa cho danh từ để chỉ giai đoạn cuối. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('衙', '{"9000": "2763.0", "Chữ Trung Quốc": "衙", "Bộ thủ & thành phần_Xie": "Bộ thủ | 行 | Số nét | 13 | nét | 行 | hành | biểu nghĩa | đường, di chuyển | 吾 | ngô | biểu âm | ta, tôi | 衙 là chữ hình thanh: 行 (Hành) biểu nghĩa chỉ đường sá, nơi chốn; 吾 (Ngô) biểu âm. Dạng viết hiện tại tách 行 thành 彳 và 亍 hai bên 吾.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nha\": con đường (行) của quan (吾 biểu âm) — nơi làm việc của quan chức, tức công nha. | Gương Hán-Việt | nha trong 衙門 (nha môn — cơ quan công quyền), 公衙 (công nha) | Mở khoá kiến thức | Biết 衙 mở khoá: 衙門, 衙役, 公衙 — nhóm từ chỉ bộ máy quan liêu xưa.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Theo Wiktionary, 衙 là chữ hình thanh gồm 行 (biểu nghĩa: nơi chốn, đường sá) và 吾 (biểu âm). Nghĩa gốc chỉ dinh thự quan lại, nơi xét xử và điều hành công vụ. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sở quan", "Hạng Tần Suất (Jun Da)": "2763.0", "Tần Suất % (Jun Da)": "98.9118081259", "GavinGrover_Once (Chiết tự trực tiếp)": "行 + 吾", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴行吾", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "吾", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "行", "Unihan_Simplified (Chữ Giản thể)": "衙", "Unihan_Traditional (Chữ Phồn thể)": "衙", "Pinyin_Xie": "yá", "Âm Hán Việt_Xie": "nha", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng sau định ngữ để chỉ nơi làm việc của quan lại thời phong kiến. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('诫', '{"9000": "2764.0", "Chữ Trung Quốc": "诫", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 9 | nét | 讠 | biểu nghĩa | lời nói (bộ ngôn giản thể) | 戒 | giới | biểu âm | giới luật, kiêng cữ (cho âm jiè) | 诫 = 讠 (bộ ngôn, biểu nghĩa: lời nói) + 戒 (Giới, biểu âm). Dạng giản thể của 誡. Chữ hình thanh — lời nói để răn dạy, cảnh giới.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"giới\": lời nói (讠) đặt ra giới hạn (戒) — lời cảnh cáo, răn dạy để không vượt qua ranh giới. | Gương Hán-Việt | \"giới\" trong \"cảnh giới\" (cảnh báo, nhắc nhở) và \"giới luật\" (quy tắc cần tuân theo) | Mở khoá kiến thức | Biết 诫 (giới) mở khoá: 告诫 (cáo giới — cảnh cáo, nhắc nhở); 训诫 (huấn giới — răn dạy).", "Tự nguyên_Xie": "诫 là dạng giản thể của 誡 (言→讠). Chữ gốc 誡 gồm 言 (lời nói, biểu nghĩa) + 戒 (biểu âm, đồng thời gợi nghĩa ''cảnh giới, răn bảo''). Nghĩa gốc là lời răn dạy, cảnh cáo. Chưa có nguồn học thuật chi tiết cho glyph origin riêng. | Suy từ bộ phận cấu thành · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bài văn răn bảo", "Hạng Tần Suất (Jun Da)": "2764.0", "Tần Suất % (Jun Da)": "98.9131590022", "GavinGrover_Once (Chiết tự trực tiếp)": "讠 + 戒", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰讠戒", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "戒", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "讠", "Unihan_Simplified (Chữ Giản thể)": "诫", "Unihan_Traditional (Chữ Phồn thể)": "誡", "Pinyin_Xie": "jiè", "Âm Hán Việt_Xie": "giới", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường làm động từ để khuyên răn hoặc làm danh từ chỉ lời răn dạy trong gia đình, xã hội. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('斧', '{"9000": "2765.0", "Chữ Trung Quốc": "斧", "Bộ thủ & thành phần_Xie": "Bộ thủ | 斤 | Số nét | 8 | nét | 父 | phụ | biểu âm | cha, bậc trưởng thượng | 斤 | cân | biểu nghĩa | búa, rìu | 斧 là chữ hình thanh: 斤 (Cân) biểu nghĩa chỉ rìu/búa; 父 (Phụ) biểu âm. Cấu trúc trên-dưới: 父 trên, 斤 dưới.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phủ\": cái rìu (斤) cầm tay — người cha (父) xưa dùng rìu phát rẫy. | Gương Hán-Việt | phủ trong 斧頭 (phủ đầu — cái rìu), 斧鉞 (phủ việt — rìu và búa) | Mở khoá kiến thức | Biết 斧 mở khoá: 斧頭, 斧鉞, 刀斧手 — nhóm từ về vũ khí và dụng cụ.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 斧 là chữ hình thanh gồm 父 (biểu âm) và 斤 (biểu nghĩa: rìu, dụng cụ chặt). Hình tiểu triện cho thấy rõ bộ 斤 ở dưới. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "465.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Cân (196) Phụ (165)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Phụ (số 88 - cha) ở trên chữ Cân (số 69 - cái rìu) . Vật dụng như cái rìu (Cân) mà người cha (Phụ) trụ cột gia đình thường hay dùng để chẻ củi, làm mộc gọi là cái búa (phủ). Giải thích sự chuyển ý: Chữ Phụ (người cha) chỉ âm, chữ Cân (cái rìu) chỉ ý. Dụng cụ lao động bằng sắt dùng để đốn cây, chặt gỗ (Phủ). *(Biến âm Hán Việt: Phụ -> Phủ)*", "Nghĩa Tiếng Việt_Xie": "cái rìu, cái búa", "Hạng Tần Suất (Jun Da)": "2765.0", "Tần Suất % (Jun Da)": "98.91450161", "GavinGrover_Once (Chiết tự trực tiếp)": "父 + 斤", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱父斤", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "斤", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "父", "Unihan_Simplified (Chữ Giản thể)": "斧", "Unihan_Traditional (Chữ Phồn thể)": "斧", "Pinyin_Xie": "fǔ", "Âm Hán Việt_Xie": "phủ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ công cụ chặt đốn, có thể kết hợp với các từ chỉ hành động thủ công. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('兮', '{"9000": "2766.0", "Chữ Trung Quốc": "兮", "Bộ thủ & thành phần_Xie": "Bộ thủ | 八 | Số nét | 4 | nét | 八 | bát | biểu hình | hai nét tách ra | 丂 | khảo | biểu hình | cành cây chạc ba | 兮 là chữ tượng hình / chỉ sự: dạng giáp cốt gồm 丂 (chạc cây) và hai nét thẳng song song phía trên, có thể gợi tiếng gió qua cành cây. Ban đầu đồng dạng với 乎; cấu trúc không phải hình thanh thuần tuý.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hề\": gió (nét trên) qua cành cây (丂) — âm thanh vang lên thành tiếng thở dài, trợ từ than thở trong thơ cổ. | Gương Hán-Việt | hề trong 兮 dùng làm trợ từ thơ cổ (歸去來兮 — về thôi, hề!) | Mở khoá kiến thức | Biết 兮 mở khoá đọc hiểu thơ Sở Từ và văn ngôn cổ điển Trung Hoa.", "Tự nguyên_Xie": "Giáp cốt văn | Kim văn | Đại triện | Tiểu triện | Theo Wiktionary, 兮 vốn cùng chữ với 乎. Dạng giáp cốt gồm 丂 (chạc cây) và hai nét song song phía trên, có thể tượng trưng tiếng gió xuyên qua cành — âm thanh gợi cảm thán. Dùng làm trợ từ cảm thán trong thơ cổ điển. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(phụ từ) hề, chừ", "Hạng Tần Suất (Jun Da)": "2766.0", "Tần Suất % (Jun Da)": "98.915843701", "GavinGrover_Once (Chiết tự trực tiếp)": "八 + 丂", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱八丂", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "丂", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "八", "Unihan_Simplified (Chữ Giản thể)": "兮", "Unihan_Traditional (Chữ Phồn thể)": "兮", "Pinyin_Xie": "xī", "Âm Hán Việt_Xie": "hề", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Trợ từ | 助词 | Thường làm trợ từ ngữ khí đứng ở cuối hoặc giữa câu trong thơ ca cổ để kéo dài giọng hoặc biểu thị cảm xúc. | Trợ từ | 助词 | Không mang nghĩa riêng, gắn vào câu để đánh dấu ngữ pháp hoặc ngữ khí: 的 / 地 / 得 (kết cấu), 了 / 着 / 过 (thể), 吗 / 呢 / 吧 (nghi vấn, ngữ khí).", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('焕', '{"9000": "2767.0", "Chữ Trung Quốc": "焕", "Bộ thủ & thành phần_Xie": "Bộ thủ | 火 | Số nét | 11 | nét | 火 | hoả | biểu nghĩa | lửa | 奂 | hoán | biểu âm | đẹp rực rỡ | 焕 là dạng giản thể của 煥. Chữ hình thanh: 火 (Hoả) biểu nghĩa chỉ lửa, sáng rực; 奂 (Hoán) biểu âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hoán\": lửa (火) bùng sáng rực rỡ — 焕发 tức rạng rỡ tươi tắn như ngọn lửa. | Gương Hán-Việt | hoán trong 焕发 (hoán phát — tỏa sáng), 焕然一新 (hoán nhiên nhất tân — đổi mới hoàn toàn) | Mở khoá kiến thức | Biết 焕 mở khoá: 焕发, 焕然一新, 容光焕发 — nhóm từ chỉ sự rạng rỡ, đổi mới.", "Tự nguyên_Xie": "Tiểu triện | 焕 là giản thể của 煥. Theo cấu trúc, 煥 gồm 火 (biểu nghĩa: lửa, ánh sáng) và 奐 (biểu âm). Nghĩa gốc chỉ ánh sáng rực rỡ như lửa bùng lên. Chữ tạo muộn, chưa thấy dạng giáp cốt/kim văn độc lập. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sáng sủa, rực rỡ", "Hạng Tần Suất (Jun Da)": "2767.0", "Tần Suất % (Jun Da)": "98.9171847584", "GavinGrover_Once (Chiết tự trực tiếp)": "火 + 奂", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰火奂", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "奂", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "火", "Unihan_Simplified (Chữ Giản thể)": "焕", "Unihan_Traditional (Chữ Phồn thể)": "煥", "Pinyin_Xie": "huàn", "Âm Hán Việt_Xie": "hoán", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường làm tính từ bổ nghĩa cho danh từ hoặc kết hợp trong động từ như hoán phát, hoán nhiên. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('棕', '{"9000": "2768.0", "Chữ Trung Quốc": "棕", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 12 | nét | 木 | mộc | biểu nghĩa | cây, gỗ | 宗 | tông | biểu âm | tổ tông (cho âm zōng) | 棕 = 木 (Mộc, biểu nghĩa: cây) + 宗 (Tông, biểu âm). Chữ hình thanh — 木 chỉ đây là cây, 宗 cho âm zōng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tông\": cây (木) tông lư (宗) — cây cọ có sợi nâu đặc trưng, từ đó tông màu nâu đất. | Gương Hán-Việt | \"tông\" trong \"nâu tông\" — màu nâu đất như sợi cọ | Mở khoá kiến thức | Biết 棕 (tông) mở khoá: 棕色 (tông sắc — màu nâu); 棕榈 (tông lư — cây cọ dừa); 棕熊 (tông hùng — gấu nâu).", "Tự nguyên_Xie": "Chữ hình thanh, nguyên viết là 椶. Theo Wiktionary: 木 (cây, biểu nghĩa) + 㚇 (nguyên bản, biểu âm), sau được thay bằng 宗 vì gần âm. Chỉ cây cọ dừa (cây tông lư), có sợi nâu đặc trưng. Sau dùng để chỉ màu nâu. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cây cọ, cây gồi; xơ cọ", "Hạng Tần Suất (Jun Da)": "2768.0", "Tần Suất % (Jun Da)": "98.9185232319", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 宗", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木宗", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "宗", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "棕", "Unihan_Traditional (Chữ Phồn thể)": "棕", "Pinyin_Xie": "zōng", "Âm Hán Việt_Xie": "tông", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Thường làm danh từ chỉ cây cọ hoặc làm tính từ chỉ màu nâu trong tiếng Trung hiện đại. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('佑', '{"9000": "2769.0", "Chữ Trung Quốc": "佑", "Bộ thủ & thành phần_Xie": "Bộ thủ | 人 | Số nét | 7 | nét | 亻 | nhân | biểu nghĩa | người | 右 | hữu | biểu âm | bên phải, giúp đỡ | 佑 là chữ hình thanh: 亻 (Nhân) biểu nghĩa chỉ người; 右 (Hữu) biểu âm. Nghĩa gốc: người giúp đỡ, phù hộ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hựu\": người (亻) đứng bên phải (右) che chở — ý nghĩa phù hộ, bảo trợ. | Gương Hán-Việt | hựu trong 保佑 (bảo hựu — phù hộ bảo vệ), 天佑 (thiên hựu — trời phù hộ) | Mở khoá kiến thức | Biết 佑 mở khoá: 保佑, 天佑, 神佑 — nhóm từ chỉ sự che chở từ trên cao.", "Tự nguyên_Xie": "Theo Wiktionary, 佑 là chữ hình thanh gồm 亻 (人, biểu nghĩa: người) và 右 (biểu âm). Nghĩa là phù hộ, bảo vệ — hành động của người đứng bên cạnh che chở. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bảo hộ; phù hộ; giúp đỡ", "Hạng Tần Suất (Jun Da)": "2769.0", "Tần Suất % (Jun Da)": "98.9198611886", "GavinGrover_Once (Chiết tự trực tiếp)": "亻 + 右", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰亻右", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "右", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "亻", "Unihan_Simplified (Chữ Giản thể)": "佑", "Unihan_Traditional (Chữ Phồn thể)": "佑", "Pinyin_Xie": "yòu", "Âm Hán Việt_Xie": "hữu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước danh từ chỉ đối tượng được thần phật che chở, bảo vệ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('嘶', '{"9000": "2770.0", "Chữ Trung Quốc": "嘶", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 15 | nét | 口 | khẩu | biểu nghĩa | miệng, âm thanh | 斯 | tư | biểu âm | này, khi đó | 嘶 là chữ hình thanh: 口 (Khẩu) biểu nghĩa chỉ miệng, âm thanh; 斯 (Tư) biểu âm. Dùng để mô tả tiếng hí ngựa hoặc giọng khàn khàn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tê\": miệng (口) phát ra âm 斯 (tư) — tiếng hí ngựa vang rền, khàn khàn. | Gương Hán-Việt | tê trong 嘶鸣 (tê minh — hí vang), 嘶哑 (tê á — khàn giọng) | Mở khoá kiến thức | Biết 嘶 mở khoá: 嘶鸣, 嘶哑, 马嘶 — nhóm từ tả âm thanh ngựa và giọng khàn.", "Tự nguyên_Xie": "Lục thư thông | Theo Wiktionary, 嘶 là chữ hình thanh gồm 口 (biểu nghĩa: miệng, âm thanh) và 斯 (biểu âm). Chỉ tiếng hí của ngựa, hoặc tiếng la khàn giọng. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "kêu lên, hí (ngựa)", "Hạng Tần Suất (Jun Da)": "2770.0", "Tần Suất % (Jun Da)": "98.9211981118", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 斯", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口斯", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "斯", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "嘶", "Unihan_Traditional (Chữ Phồn thể)": "嘶", "Pinyin_Xie": "sī", "Âm Hán Việt_Xie": "tê", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Từ tượng thanh | 象声词 | Thường làm động từ mô tả tiếng kêu của ngựa hoặc trạng thái giọng nói bị khàn đi. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Từ tượng thanh | 象声词 | Mô phỏng âm thanh: 哗哗, 汪汪. Có thể làm định ngữ, trạng ngữ hoặc đứng độc lập.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('妓', '{"9000": "2771.0", "Chữ Trung Quốc": "妓", "Bộ thủ & thành phần_Xie": "Bộ thủ | 女 | Số nét | 7 | nét | 女 | nữ | biểu nghĩa | người phụ nữ | 支 | chi | biểu âm | nhánh, chi | 妓 là chữ hình thanh: 女 (Nữ) biểu nghĩa chỉ người phụ nữ; 支 (Chi) biểu âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"kỹ\": người phụ nữ (女) có kỹ năng (支 biểu âm) ca múa — kỹ nữ thời xưa. | Gương Hán-Việt | kỹ trong 妓女 (kỹ nữ), 歌妓 (ca kỹ — ca nữ) | Mở khoá kiến thức | Biết 妓 mở khoá: 妓女, 歌妓, 舞妓 — nhóm từ lịch sử về nghệ nhân nữ.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 妓 là chữ hình thanh gồm 女 (biểu nghĩa: phụ nữ) và 支 (biểu âm). Nghĩa gốc chỉ người phụ nữ làm nghề ca múa, sau mang nghĩa kỹ nữ. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "kỹ nữ; gái điếm; đĩ", "Hạng Tần Suất (Jun Da)": "2771.0", "Tần Suất % (Jun Da)": "98.922532451", "GavinGrover_Once (Chiết tự trực tiếp)": "女 + 支", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰女支", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "支", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "女", "Unihan_Simplified (Chữ Giản thể)": "妓", "Unihan_Traditional (Chữ Phồn thể)": "妓", "Pinyin_Xie": "jì", "Âm Hán Việt_Xie": "kỹ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng độc lập hoặc kết hợp thành các từ ghép chỉ người phụ nữ làm nghề ca hát, bán nghệ ngày xưa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('喧', '{"9000": "2772.0", "Chữ Trung Quốc": "喧", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 12 | nét | 口 | khẩu | biểu nghĩa | miệng, tiếng nói | 宣 | tuyên | biểu âm | tuyên bố (cho âm xuān) | 喧 = 口 (Khẩu, biểu nghĩa: miệng) + 宣 (Tuyên, biểu âm). Chữ hình thanh — 口 chỉ đây là tiếng ồn từ miệng, 宣 cho âm xuān.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"huyên\": nhiều miệng (口) cùng tuyên (宣) bố — tiếng ồn ào của đám đông. | Gương Hán-Việt | \"huyên\" trong \"ồn huyên\" và \"huyên náo\" (náo nhiệt, ồn ào) | Mở khoá kiến thức | Biết 喧 (huyên) mở khoá: 喧哗 (huyên hoa — ồn ào, náo nhiệt); 喧嚣 (huyên tiêu — ầm ĩ, hỗn loạn); 喧闹 (huyên náo — ồn ào).", "Tự nguyên_Xie": "Chữ hình thanh theo Wiktionary: 口 (miệng, biểu nghĩa) + 宣 (biểu âm). Nghĩa gốc là tiếng ồn ào, ầm ĩ — nhiều người cùng nói to cùng lúc như tuyên bố. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ồn ào, ầm ĩ", "Hạng Tần Suất (Jun Da)": "2772.0", "Tần Suất % (Jun Da)": "98.9238652398", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 宣", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口宣", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "宣", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "喧", "Unihan_Traditional (Chữ Phồn thể)": "喧", "Pinyin_Xie": "xuān", "Âm Hán Việt_Xie": "huyên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường làm tính từ miêu tả âm thanh ồn ào hoặc làm động từ trong các từ ghép như huyên hoa, huyên truyền. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蓉', '{"9000": "2773.0", "Chữ Trung Quốc": "蓉", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 13 | nét | 艹 | thảo | biểu nghĩa | cỏ, thực vật | 容 | dung | biểu âm | chứa đựng, dung mạo | 蓉 là chữ hình thanh: 艹 (Thảo) biểu nghĩa chỉ thực vật; 容 (Dung) biểu âm. Dùng trong 芙蓉 (phù dung — hoa sen hoặc hoa mộc phù dung).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"dung\": cỏ (艹) mang âm 容 (dung) — bông hoa dung dị, đẹp đẽ như hoa phù dung. | Gương Hán-Việt | dung trong 芙蓉 (phù dung — hoa sen/mộc phù dung), 蓉城 (Dung thành — Thành Đô) | Mở khoá kiến thức | Biết 蓉 mở khoá: 芙蓉, 蓉城, 莲蓉 — nhóm từ về thực vật và địa danh.", "Tự nguyên_Xie": "Tiểu triện | Theo cấu trúc chữ, 蓉 gồm 艹 (biểu nghĩa: thực vật) và 容 (biểu âm). Chủ yếu dùng trong từ ghép 芙蓉 chỉ hoa sen hoặc mộc phù dung; cũng là tên gọi tắt của Thành Đô. Chưa thấy dạng giáp cốt/kim văn riêng biệt. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "423.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thảo (276) Dung (322)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Thảo (số 80 - cỏ cây) và chữ Dung (số 132 - bao dung) . Loài hoa (Thảo) mang dáng vẻ bao dung, chứa đựng (Dung) vẻ đẹp rực rỡ gọi là hoa phù dung. Giải thích sự chuyển ý: Chữ Dung (bao dung) chỉ âm, chữ Thảo (cỏ cây) chỉ ý. Tên gọi chung với chữ Phù để chỉ hoa phù dung (Dung).", "Nghĩa Tiếng Việt_Xie": "(xem: phù dung 芙蓉)", "Hạng Tần Suất (Jun Da)": "2773.0", "Tần Suất % (Jun Da)": "98.9251975119", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 容", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹容", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "容", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "蓉", "Unihan_Traditional (Chữ Phồn thể)": "蓉", "Pinyin_Xie": "róng", "Âm Hán Việt_Xie": "dung", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ xuất hiện trong tên các loài hoa như phù dung hoặc dùng làm tên người, tên địa danh. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('删', '{"9000": "2774.0", "Chữ Trung Quốc": "删", "Bộ thủ & thành phần_Xie": "Bộ thủ | 刀 | Số nét | 7 | nét | 册 | sách | biểu âm | quyển sách (thẻ tre) — cho âm sách/san | 刂 | đao | biểu nghĩa | dao (bộ đao bên phải) | 删 = 册 (Sách, biểu âm) + 刂 (Đao, biểu nghĩa: dao); chữ hình thanh. Wiktionary ghi: {{Han compound|冊|刀|ls=psc|c1=p|c2=s|t2=knife}}. Bộ đao chỉ hành động cắt bỏ; 册 cho âm shān (gần san). Cắt bỏ chữ trên thẻ tre = xóa, chỉnh sửa.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"san\": dao (刂-Đao) cắt sách (册-Sách) — dùng dao gọt xóa chữ trên thẻ tre. San = cắt bỏ, xóa. | Gương Hán-Việt | san trong ''san phẳng, san bằng'' — âm giống; 删 là xóa bỏ văn bản, không liên quan san đất | Mở khoá kiến thức | Biết 删 mở khoá: 删除 (san trừ – xóa bỏ), 删改 (san cải – sửa đổi cắt bỏ), 删减 (san giảm – cắt bớt).", "Tự nguyên_Xie": "删 là chữ hình thanh: 刀/刂(đao – dao) biểu nghĩa, 冊 (sách) biểu âm. Wiktionary xác nhận: dùng dao (刀) cắt bỏ chữ trên thẻ tre (冊) — đây là cách xóa và chỉnh sửa văn bản thời cổ đại khi chưa có giấy. Nghĩa hiện đại là xóa bỏ, loại bỏ văn bản. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "335.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Sách (334) Đao (324)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Sách (số 334) và chữ Đao (số 324 - 刂) . Lấy con dao (đao) gọt đẽo cắt xén bớt phần dư thừa của cuốn sách (sách) cho đẹp, gọn gàng.", "Nghĩa Tiếng Việt_Xie": "lọc bỏ", "Hạng Tần Suất (Jun Da)": "2774.0", "Tần Suất % (Jun Da)": "98.9265292672", "GavinGrover_Once (Chiết tự trực tiếp)": "册 + 刂", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰册刂", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "册", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "刂", "Unihan_Simplified (Chữ Giản thể)": "删", "Unihan_Traditional (Chữ Phồn thể)": "刪", "Pinyin_Xie": "shān", "Âm Hán Việt_Xie": "san", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước tân ngữ chỉ văn bản, tài liệu cần lược bỏ hoặc chỉnh sửa. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | shān | / | xóa bỏ | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Động từ tôi", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('樱', '{"9000": "2775.0", "Chữ Trung Quốc": "樱", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 15 | nét | 木 | mộc | biểu nghĩa | cây gỗ | 婴 | anh | biểu âm | trẻ sơ sinh | 樱 là chữ hình thanh: 木 (Mộc) biểu nghĩa chỉ cây gỗ; 婴 (Anh, dạng giản thể của 嬰) biểu âm. Dùng chỉ cây anh đào.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"anh\": cây (木) có âm 婴 (anh) — cây anh đào với hoa trắng hồng rực rỡ. | Gương Hán-Việt | anh trong 樱桃 (anh đào — quả anh đào), 樱花 (anh hoa — hoa anh đào) | Mở khoá kiến thức | Biết 樱 mở khoá: 樱桃, 樱花, 山樱 — nhóm từ về anh đào Nhật Bản và Trung Quốc.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, chữ phồn thể 櫻 gồm 木 (biểu nghĩa: cây) và 嬰 (biểu âm). Nghĩa chỉ cây anh đào (cherry). Dạng giản thể 樱 rút gọn 嬰 thành 婴. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: anh đào 櫻桃,樱桃)", "Hạng Tần Suất (Jun Da)": "2775.0", "Tần Suất % (Jun Da)": "98.9278584386", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 婴", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木婴", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "婴", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "樱", "Unihan_Traditional (Chữ Phồn thể)": "櫻", "Pinyin_Xie": "yīng", "Âm Hán Việt_Xie": "anh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ kết hợp với các từ khác để chỉ hoa anh đào hoặc quả anh đào. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('伺', '{"9000": "2776.0", "Chữ Trung Quốc": "伺", "Bộ thủ & thành phần_Xie": "Bộ thủ | 人 | Số nét | 7 | nét | 亻 | nhân | biểu nghĩa | người | 司 | ti | biểu âm | quan ti, quản lý (cho âm sì/cì) | 伺 = 亻 (Nhân, biểu nghĩa: người) + 司 (Ti, biểu âm). Chữ hình thanh — người đứng bên cạnh, phục vụ, quan sát chờ đợi.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tứ\": người (亻) đứng như quan ti (司) — hầu hạ, chờ đợi để phục vụ chủ nhân. | Gương Hán-Việt | \"tứ\" trong \"phục tứ\" (hầu hạ, chờ đợi) | Mở khoá kiến thức | Biết 伺 (tứ) mở khoá: 伺机 (tứ cơ — chờ thời cơ); 伺候 (tứ hậu — hầu hạ, phục vụ); 窥伺 (khuy tứ — rình rập, do thám).", "Tự nguyên_Xie": "Chữ hình thanh theo Wiktionary: 人/亻 (người, biểu nghĩa) + 司 (biểu âm) — người đứng bên cạnh chờ đợi, quan sát. Nghĩa gốc là hầu hạ, phục vụ, rình chờ. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "dò xét, thăm dò", "Hạng Tần Suất (Jun Da)": "2776.0", "Tần Suất % (Jun Da)": "98.9291865764", "GavinGrover_Once (Chiết tự trực tiếp)": "亻 + 司", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰亻司", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "司", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "亻", "Unihan_Simplified (Chữ Giản thể)": "伺", "Unihan_Traditional (Chữ Phồn thể)": "伺", "Pinyin_Xie": "cì", "Âm Hán Việt_Xie": "tứ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước tân ngữ chỉ đối tượng cần rình rập hoặc hầu hạ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('嗡', '{"9000": "2777.0", "Chữ Trung Quốc": "嗡", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 13 | nét | 口 | khẩu | biểu nghĩa | miệng, âm thanh | 翁 | ông | biểu âm | ông lão | 嗡 là chữ hình thanh: 口 (Khẩu) biểu nghĩa chỉ âm thanh; 翁 (Ông) biểu âm. Dùng tả tiếng vo ve của ong, tiếng vù vù của máy bay.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ông\": miệng (口) phát âm như 翁 (ông) — tiếng vo ve của con ong vù vù. | Gương Hán-Việt | ông trong 嗡嗡 (ông ông — vo ve liên tục) | Mở khoá kiến thức | Biết 嗡 mở khoá từ tượng thanh: 嗡嗡叫, 嗡嗡声 — tiếng vo ve.", "Tự nguyên_Xie": "Theo Wiktionary, 嗡 là chữ hình thanh gồm 口 (biểu nghĩa: âm thanh) và 翁 (biểu âm). Dùng mô phỏng âm thanh vo ve liên tục của côn trùng hoặc động cơ. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1071.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Khẩu (030) Ông (1070)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Khẩu (số 030 - miệng/âm thanh) ở bên trái chữ Ông (số 1070 - ông lão/chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Ông chỉ âm, bộ Khẩu chỉ ý. Ông là tiếng vo ve, vù vù (như tiếng do côn trùng bay tạo thành).", "Nghĩa Tiếng Việt_Xie": "vo ve, vù vù", "Hạng Tần Suất (Jun Da)": "2777.0", "Tần Suất % (Jun Da)": "98.9305121302", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 翁", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口翁", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "翁", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "嗡", "Unihan_Traditional (Chữ Phồn thể)": "嗡", "Pinyin_Xie": "wēng", "Âm Hán Việt_Xie": "ông", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Từ tượng thanh | 象声词 | Thường làm từ tượng thanh mô tả tiếng kêu của côn trùng như ong, muỗi hoặc tiếng máy móc kêu ù ù. | Từ tượng thanh | 象声词 | Mô phỏng âm thanh: 哗哗, 汪汪. Có thể làm định ngữ, trạng ngữ hoặc đứng độc lập.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('娥', '{"9000": "2778.0", "Chữ Trung Quốc": "娥", "Bộ thủ & thành phần_Xie": "Bộ thủ | 女 | Số nét | 10 | nét | 女 | nữ | biểu nghĩa | người phụ nữ | 我 | ngã | biểu âm | ta, tôi | 娥 là chữ hình thanh: 女 (Nữ) biểu nghĩa chỉ người phụ nữ; 我 (Ngã) biểu âm. Chỉ người phụ nữ đẹp, đặc biệt dùng trong 嫦娥.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nga\": người phụ nữ (女) duyên dáng như 我 (ngã) — Hằng Nga bay lên cung trăng với vẻ đẹp tuyệt trần. | Gương Hán-Việt | nga trong 嫦娥 (Hằng Nga — cô gái trăng), 娥眉 (nga mi — lông mày đẹp) | Mở khoá kiến thức | Biết 娥 mở khoá: 嫦娥, 娥眉, 月娥 — nhóm từ liên quan thần thoại và vẻ đẹp phụ nữ.", "Tự nguyên_Xie": "Giáp cốt văn | Tiểu triện | Lục thư thông | Theo Wiktionary, 娥 là chữ hình thanh gồm 女 (biểu nghĩa: phụ nữ) và 我 (biểu âm). Nghĩa gốc là người phụ nữ đẹp. Nay chủ yếu dùng trong tên riêng như 嫦娥 (Hằng Nga) và 娥眉 (mi ngài — lông mày đẹp). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tốt đẹp", "Hạng Tần Suất (Jun Da)": "2778.0", "Tần Suất % (Jun Da)": "98.9318335498", "GavinGrover_Once (Chiết tự trực tiếp)": "女 + 我", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰女我", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "我", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "女", "Unihan_Simplified (Chữ Giản thể)": "娥", "Unihan_Traditional (Chữ Phồn thể)": "娥", "Pinyin_Xie": "é", "Âm Hán Việt_Xie": "nga", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Thường làm danh từ chỉ mỹ nhân hoặc tính từ miêu tả vẻ đẹp của phụ nữ trong văn học cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('梢', '{"9000": "2779.0", "Chữ Trung Quốc": "梢", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 11 | nét | 木 | mộc | biểu nghĩa | cây, gỗ | 肖 | tiêu | biểu âm | giống, tương tự (cho âm shāo) | 梢 = 木 (Mộc, biểu nghĩa: cây) + 肖 (Tiêu, biểu âm). Chữ hình thanh — 木 chỉ đây là bộ phận của cây, 肖 cho âm shāo.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sao\": cây (木) vươn tới điểm cuối (肖) — ngọn cây cao nhất, mỏng nhất, như ngọn sào chống trời. | Gương Hán-Việt | \"sao\" trong \"ngọn sào\" (đầu cây sào) — phần chót nhọn | Mở khoá kiến thức | Biết 梢 (sao) mở khoá: 树梢 (thụ sao — ngọn cây); 梢头 (sao đầu — ngọn, chóp); 船梢 (thuyền sao — đuôi thuyền).", "Tự nguyên_Xie": "Chữ hình thanh theo Wiktionary: 木 (cây, biểu nghĩa) + 肖 (biểu âm). Nghĩa gốc là ngọn cây, phần đầu mỏng của cành cây — phần xa nhất, nhỏ nhất của thân cây. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ngọn cây; mốc, dấu hiệu; nhãn hiệu; đánh dấu; giá thầu", "Hạng Tần Suất (Jun Da)": "2779.0", "Tần Suất % (Jun Da)": "98.9331539359", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 肖", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木肖", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "肖", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "梢", "Unihan_Traditional (Chữ Phồn thể)": "梢", "Pinyin_Xie": "shāo", "Âm Hán Việt_Xie": "sao", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ để chỉ phần ngọn hoặc phần cuối cùng của cây cối và vật thể dài. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | shāo | / | ngọn cây | Xuất hiện trong lộ trình | HSK | HSK 6 | · | Sinh học", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('坝', '{"9000": "2780.0", "Chữ Trung Quốc": "坝", "Bộ thủ & thành phần_Xie": "Bộ thủ | 土 | Số nét | 7 | nét | 土 | thổ | biểu nghĩa | đất | 贝 | bối | biểu âm | vỏ sò (rút gọn từ 霸, cho âm bà) | 坝 = 土 (Thổ, biểu nghĩa: đất) + 贝 (Bối, thay thế giản thể cho 霸, biểu âm). Chữ hình thanh — đất đắp thành đập ngăn nước.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bá\": đất (土) chắn vỏ sò (贝) dưới nước — hình ảnh đập đất ngăn dòng chảy mạnh. | Gương Hán-Việt | \"bá\" trong \"đập bá\" (đập nước, đê) | Mở khoá kiến thức | Biết 坝 (bá) mở khoá: 堤坝 (đê bá — đê đập); 大坝 (đại bá — đập lớn); 拦河坝 (lan hà bá — đập ngăn sông).", "Tự nguyên_Xie": "Chữ hình thanh theo Wiktionary: 土 (đất, biểu nghĩa) + 霸 (biểu âm, rút gọn thành 贝 trong giản thể). Nghĩa gốc là đập nước, đê ngăn — khối đất đắp để ngăn dòng chảy. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "máng nước", "Hạng Tần Suất (Jun Da)": "2780.0", "Tần Suất % (Jun Da)": "98.9344727715", "GavinGrover_Once (Chiết tự trực tiếp)": "土 + 贝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰土贝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "贝", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "土", "Unihan_Simplified (Chữ Giản thể)": "坝", "Unihan_Traditional (Chữ Phồn thể)": "壩", "Pinyin_Xie": "bà", "Âm Hán Việt_Xie": "bá", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường đứng sau danh từ riêng hoặc kết hợp với các từ chỉ nguồn nước để làm danh từ chỉ công trình ngăn nước. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | bà | / | đập | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Вuildings và công trình xây dựng", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蚕', '{"9000": "2781.0", "Chữ Trung Quốc": "蚕", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 10 | nét | 天 | thiên | biểu hình | trời | 虫 | trùng | biểu nghĩa | sâu bọ, côn trùng | 蚕 là dạng giản thể của 蠶. Cấu trúc gồm 天 phía trên và 虫 phía dưới. Không phải hội ý thuần tuý; 天 ở đây là biến thể hình thức của thành phần âm trong chữ gốc 蠶.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tằm\": con sâu (虫) dưới trời (天) — con tằm nhả tơ từ lá dâu trời cho. | Gương Hán-Việt | tằm trong 蚕丝 (tằm ti — tơ tằm), 养蚕 (dưỡng tằm — nuôi tằm) | Mở khoá kiến thức | Biết 蚕 mở khoá: 蚕丝, 养蚕, 蚕茧, 蚕食 — nhóm từ nghề tơ lụa truyền thống.", "Tự nguyên_Xie": "Đại triện | Tiểu triện | 蚕 là giản thể của 蠶. Theo chữ gốc, 蠶 là chữ tượng hình mô tả con tằm. Dạng đại triện và tiểu triện đã cho thấy hình dạng con tằm rõ rệt. Chữ giản thể rút gọn mạnh nhưng giữ 虫 biểu nghĩa. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con tằm", "Hạng Tần Suất (Jun Da)": "2781.0", "Tần Suất % (Jun Da)": "98.9357900568", "GavinGrover_Once (Chiết tự trực tiếp)": "天 + 虫", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱天虫", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "天", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蚕", "Unihan_Traditional (Chữ Phồn thể)": "蠶", "Pinyin_Xie": "cán", "Âm Hán Việt_Xie": "tàm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng độc lập hoặc kết hợp để tạo thành các từ ghép liên quan đến nghề nuôi tằm dệt lụa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('敷', '{"9000": "2782.0", "Chữ Trung Quốc": "敷", "Bộ thủ & thành phần_Xie": "Bộ thủ | 攴 | Số nét | 15 | nét | 旉 | biểu âm | phân phát (biểu âm, gốc là 尃) | 攵 | phộc | biểu nghĩa | tay cầm roi, hành động | 敷 = 旉/尃 (biểu âm: phân phát) + 攵 (Phộc, biểu nghĩa: tay cầm roi/hành động). Chữ hình thanh kiêm hội ý — vừa có âm từ 尃, vừa có nghĩa hành động từ 攵. Nghĩa gốc là trải ra, phân phát.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phu\": tay (攵) trải (旉) ra khắp — bôi thuốc, phủ lên bề mặt, hoặc làm qua loa cho xong. | Gương Hán-Việt | \"phu\" trong \"phu diễn\" (làm qua loa) và \"phu thuốc\" (bôi thuốc) | Mở khoá kiến thức | Biết 敷 (phu) mở khoá: 敷衍 (phu diễn — làm qua loa, đối phó); 敷药 (phu dược — bôi thuốc); 敷面膜 (phu diện mô — đắp mặt nạ).", "Tự nguyên_Xie": "Biến thể của 𢾭. Theo Wiktionary: chữ hình thanh kiêm hội ý — 尃 (biểu âm: phân phát/trải rộng) + 攴/攵 (hành động). Phần 寸 bên dưới trái được thay bằng 方. Nghĩa gốc là trải rộng, phân phát, từ đó có nghĩa ''bôi, thoa, phủ lên''. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bày, mở rộng ra", "Hạng Tần Suất (Jun Da)": "2782.0", "Tần Suất % (Jun Da)": "98.9371068253", "GavinGrover_Once (Chiết tự trực tiếp)": "旉 + ⺙", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰旉⺙", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "旉", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺙", "Unihan_Simplified (Chữ Giản thể)": "敷", "Unihan_Traditional (Chữ Phồn thể)": "敷", "Pinyin_Xie": "fū", "Âm Hán Việt_Xie": "phu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Thường làm động từ mang tân ngữ chỉ thuốc hoặc chất lỏng để diễn tả hành động bôi, đắp lên bề mặt da. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | fū | / | áp dụng | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Động từ tôi", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('澜', '{"9000": "2783.0", "Chữ Trung Quốc": "澜", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 15 | nét | 氵 | thuỷ | biểu nghĩa | nước | 阑 | lan | biểu âm | lan can, rào cản | 澜 là dạng giản thể của 瀾. Chữ hình thanh: 氵 (Thuỷ) biểu nghĩa chỉ nước; 阑 (Lan) biểu âm. Nghĩa là sóng lớn, sóng cuộn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lan\": nước (氵) bị chặn bởi 阑 (lan — rào) rồi vỡ thành sóng lớn cuộn trào. | Gương Hán-Việt | lan trong 波澜 (ba lan — làn sóng), 澜沧江 (Lan Thương Giang — sông Mê Kông thượng nguồn) | Mở khoá kiến thức | Biết 澜 mở khoá: 波澜, 波澜壮阔, 澜沧江 — nhóm từ tả sóng nước hùng vĩ.", "Tự nguyên_Xie": "Tiểu triện | 澜 là giản thể của 瀾 (rút gọn 門 thành 门 trong 阑). Theo cấu trúc 瀾, gồm 氵 (biểu nghĩa: nước) và 覽/阑 (biểu âm). Nghĩa chỉ sóng lớn, nước tràn cuộn. Tiểu triện đã có dạng rõ. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sóng lớn", "Hạng Tần Suất (Jun Da)": "2783.0", "Tần Suất % (Jun Da)": "98.9384189428", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 阑", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵阑", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "阑", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "澜", "Unihan_Traditional (Chữ Phồn thể)": "瀾", "Pinyin_Xie": "lán", "Âm Hán Việt_Xie": "lan", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng trong văn viết làm danh từ để chỉ những con sóng lớn hoặc ẩn dụ cho những biến động mạnh mẽ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('杏', '{"9000": "2784.0", "Chữ Trung Quốc": "杏", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 7 | nét | 木 | mộc | biểu nghĩa | cây gỗ | 口 | khẩu | biểu hình | miệng, vị ngon | 杏 là chữ hội ý: 木 (Mộc) chỉ cây; 口 (Khẩu) gợi ý vị ngon của quả. Kết hợp 木+口 = cây cho quả ngon miệng. Có thuyết khác coi 口 là biểu âm (Khẩu/Khả) nhưng hội ý mộc+khẩu được dùng phổ biến hơn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hạnh\": cây (木) cho quả ngon (口) — quả hạnh đào ngọt mát, tên gọi Hán-Việt là ''hạnh''. | Gương Hán-Việt | hạnh trong 杏仁 (hạnh nhân — hạt hạnh đào), 杏花 (hạnh hoa — hoa hạnh) | Mở khoá kiến thức | Biết 杏 mở khoá: 杏仁, 杏花, 银杏 — nhóm từ về cây hạnh và sản phẩm từ hạnh.", "Tự nguyên_Xie": "Giáp cốt văn | Đại triện | Tiểu triện | Theo Wiktionary, 杏 là chữ hội ý gồm 木 (cây) và 口 (miệng) — ám chỉ vị ngon của quả hạnh. Có thuyết Thuyết Văn cho là hình thanh (木+可) nhưng bị coi là ít khả năng. Dạng giáp cốt và đại triện đã có. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1522.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Mộc (075) Khẩu (030)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Mộc (số 075 - cây cối/ 木) ở trên bộ Khẩu (số 030 - cái miệng/ 口). Nhìn thấy quả trên cây khiến cho miệng ứa nước miếng thèm ăn. Giải thích sự chuyển ý: Hạnh là tên gọi của cây hoa mai hoặc cây mơ (hạnh nhân).", "Nghĩa Tiếng Việt_Xie": "cây hạnh (một loại cây như cây mận)", "Hạng Tần Suất (Jun Da)": "2784.0", "Tần Suất % (Jun Da)": "98.9397305435", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 口", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱木口", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "口", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "杏", "Unihan_Traditional (Chữ Phồn thể)": "杏", "Pinyin_Xie": "xìng", "Âm Hán Việt_Xie": "hạnh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng trước các từ chỉ bộ phận của cây như hoa, quả, nhân để chỉ các sản phẩm từ cây hạnh. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('绥', '{"9000": "2785.0", "Chữ Trung Quốc": "绥", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 10 | nét | 纟 | mịch | biểu nghĩa | sợi tơ, dây | 妥 | thoả | biểu âm | ổn thoả, yên | 绥 là dạng giản thể của 綏. Chữ hội ý kiêm hình thanh (ic + psc): 纟 (tơ, dây) biểu nghĩa, 妥 (thoả) vừa biểu âm vừa gợi ý nghĩa an bình. Kết hợp: sợi dây giúp an bình, vỗ về.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tuy\": sợi dây (纟) giúp an thoả (妥) — dây cầm vào xe ngựa để giữ thăng bằng, từ đó nghĩa là bình định, vỗ về. | Gương Hán-Việt | tuy trong 绥靖 (tuy tĩnh — xoa dịu, thoả hiệp), 绥抚 (tuy phủ — vỗ về) | Mở khoá kiến thức | Biết 绥 mở khoá: 绥靖, 绥靖政策, 绥抚 — nhóm từ chính trị lịch sử.", "Tự nguyên_Xie": "Giáp cốt văn | Kim văn | Tiểu triện | Lục thư thông | Theo Wiktionary, 綏 (phồn thể) gồm 糸 (sợi tơ) và 妥 (an bình), vừa là hội ý vừa là hình thanh. Nghĩa gốc là sợi dây cầm khi lên xe ngựa, mở rộng thành vỗ về, bình định. Có xuất hiện trong giáp cốt văn. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "dây chằng xe; bình định, yên định; lui quân; cờ tinh", "Hạng Tần Suất (Jun Da)": "2785.0", "Tần Suất % (Jun Da)": "98.9410374931", "GavinGrover_Once (Chiết tự trực tiếp)": "纟 + 妥", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰纟妥", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "妥", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "纟", "Unihan_Simplified (Chữ Giản thể)": "绥", "Unihan_Traditional (Chữ Phồn thể)": "綏", "Pinyin_Xie": "suí", "Âm Hán Việt_Xie": "tuy", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ trong văn viết cổ hoặc tên riêng với nghĩa bình định, mang lại sự yên ổn cho vùng miền. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('冶', '{"9000": "2786.0", "Chữ Trung Quốc": "冶", "Bộ thủ & thành phần_Xie": "Bộ thủ | 冫 | Số nét | 7 | nét | 冫 | băng | biểu nghĩa | băng, lạnh; ý đông lại rồi tan chảy | 台 | đài | biểu âm | đài, nơi cao | 冶 là chữ hình thanh: 冫 (Băng) biểu nghĩa — theo giải thích cổ, băng tan chảy gợi ý kim loại nóng chảy; 台 (Đài) biểu âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"dã\": băng (冫) tan chảy thành kim loại lỏng — đó là nghề đúc luyện kim (冶). | Gương Hán-Việt | dã trong 冶炼 (dã luyện — luyện kim), 陶冶 (đào dã — tôi luyện tâm hồn) | Mở khoá kiến thức | Biết 冶 mở khoá: 冶炼, 冶金, 陶冶, 冶容 — nhóm từ về luyện kim và vẻ đẹp quyến rũ.", "Tự nguyên_Xie": "Kim văn | Đại triện | Tiểu triện | Theo Wiktionary, 冶 là chữ hình thanh gồm 冫 (biểu nghĩa: băng, quá trình mềm hóa) và 台 (biểu âm). Ý tượng: như băng mềm và tan ra, kim loại được nung chảy để đúc khuôn. Dạng kim văn, đại triện và tiểu triện đều có. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đúc (tạo hình cho kim loại nóng chảy rồi để đông lại); con gái đẹp", "Hạng Tần Suất (Jun Da)": "2786.0", "Tần Suất % (Jun Da)": "98.9423423755", "GavinGrover_Once (Chiết tự trực tiếp)": "冫 + 台", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰冫台", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "台", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "冫", "Unihan_Simplified (Chữ Giản thể)": "冶", "Unihan_Traditional (Chữ Phồn thể)": "冶", "Pinyin_Xie": "yě", "Âm Hán Việt_Xie": "dã", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Thường làm động từ trong các từ ghép liên quan đến ngành luyện kim hoặc làm tính từ mô tả vẻ đẹp lòe loẹt. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('庇', '{"9000": "2787.0", "Chữ Trung Quốc": "庇", "Bộ thủ & thành phần_Xie": "Bộ thủ | 广 | Số nét | 7 | nét | 广 | nghiễm | biểu nghĩa | mái nhà dựa vào vách đá | 比 | tỷ | biểu âm | so sánh (cho âm bì) | 庇 = 广 (Nghiễm, biểu nghĩa: mái hiên/nhà dựa vào vách) + 比 (Tỷ, biểu âm). Chữ hình thanh — mái nhà che chắn, bảo vệ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tý\": mái nhà (广) che tất cả (比) — bảo vệ, che chắn cho kẻ yếu thế. | Gương Hán-Việt | \"tý\" trong \"bảo tý\" (che chở, bảo vệ) và \"bao tý\" (bao che) | Mở khoá kiến thức | Biết 庇 (tý) mở khoá: 包庇 (bao tý — bao che, bảo vệ kẻ xấu); 庇护 (tý hộ — che chở, bảo hộ); 庇荫 (tý ấm — che mát, bảo trợ).", "Tự nguyên_Xie": "Chữ hình thanh theo Wiktionary: 广 (nhà dựa vào vách đá, biểu nghĩa) + 比 (biểu âm). Nghĩa gốc là che chắn, bảo vệ — như mái nhà che người bên dưới. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "che chở; che phủ; che lấp; bao che; bênh", "Hạng Tần Suất (Jun Da)": "2787.0", "Tần Suất % (Jun Da)": "98.9436462244", "GavinGrover_Once (Chiết tự trực tiếp)": "广 + 比", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴广比", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "比", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "广", "Unihan_Simplified (Chữ Giản thể)": "庇", "Unihan_Traditional (Chữ Phồn thể)": "庇", "Pinyin_Xie": "bì", "Âm Hán Việt_Xie": "tí", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đi kèm với các từ chỉ sự che chở, bảo vệ hoặc dung túng cho hành vi xấu. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('挠', '{"9000": "2788.0", "Chữ Trung Quốc": "挠", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 9 | nét | 扌 | thủ | biểu nghĩa | tay | 尧 | nghiêu | biểu âm | vua Nghiêu (cho âm náo) | 挠 = 扌 (Thủ, biểu nghĩa: tay) + 尧 (Nghiêu, biểu âm). Chữ hình thanh — tay cào, gãi, hoặc cản trở.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nạo\": tay (扌) của vua Nghiêu (尧) — cào gãi, hay cản trở không cho qua. | Gương Hán-Việt | \"nạo\" trong \"cản nạo\" (cản trở, gây khó) | Mở khoá kiến thức | Biết 挠 (nạo) mở khoá: 阻挠 (trở nạo — cản trở, ngăn chặn); 挠头 (nạo đầu — gãi đầu, băn khoăn); 不屈不挠 (bất khuất bất nạo — kiên cường không chịu khuất).", "Tự nguyên_Xie": "Chữ hình thanh theo Wiktionary: 手/扌 (tay, biểu nghĩa) + 堯 (biểu âm, giản thể thành 尧). Nghĩa gốc là gãi, cào — hành động dùng tay cào nhẹ. Từ đó mở rộng sang nghĩa ''làm rối loạn, cản trở''. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "quấy nhiễu; cong, chùng, chùn", "Hạng Tần Suất (Jun Da)": "2788.0", "Tần Suất % (Jun Da)": "98.9449500733", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 尧", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌尧", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "尧", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "挠", "Unihan_Traditional (Chữ Phồn thể)": "撓", "Pinyin_Xie": "náo", "Âm Hán Việt_Xie": "nạo", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ chỉ hành động gãi ngứa vật lý hoặc ẩn dụ cho việc cản trở, khuất phục trước khó khăn. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | náo | / | gãi | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Từ III", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('搂', '{"9000": "2789.0", "Chữ Trung Quốc": "搂", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 12 | nét | 扌 | thủ | biểu nghĩa | tay | 娄 | lâu | biểu âm | (cho âm lǒu) | 搂 = 扌 (Thủ, biểu nghĩa: tay) + 娄 (Lâu, biểu âm). Chữ hình thanh — tay ôm, kéo vào gần.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lâu\": tay (扌) kéo vào lâu (娄) đài — hành động ôm, kéo vào gần, giữ chặt. | Gương Hán-Việt | \"lâu\" trong \"lâu đài\" — ôm người như ở trong lâu đài an toàn | Mở khoá kiến thức | Biết 搂 (lâu) mở khoá: 搂抱 (lâu bão — ôm ấp); 搂住 (lâu trú — ôm chặt); 搂钱 (lâu tiền — vơ vét tiền bạc).", "Tự nguyên_Xie": "Chữ hình thanh theo Wiktionary: 手/扌 (tay, biểu nghĩa) + 婁 (biểu âm, giản thể thành 娄). Nghĩa gốc là ôm, kéo vào lòng — hành động dùng tay giữ chặt người khác. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "kéo bè, kéo hội, gạ gẫm; ôm ấp", "Hạng Tần Suất (Jun Da)": "2789.0", "Tần Suất % (Jun Da)": "98.9462482376", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 娄", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌娄", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "娄", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "搂", "Unihan_Traditional (Chữ Phồn thể)": "摟", "Pinyin_Xie": "lǒu", "Âm Hán Việt_Xie": "lâu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ biểu thị hành động dùng hai tay ôm giữ người hoặc vật vào lòng. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | lǒu | / | ôm | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Từ III | HSK | HSK 6 | · | Gia đình và trẻ em", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('倏', '{"9000": "2790.0", "Chữ Trung Quốc": "倏", "Bộ thủ & thành phần_Xie": "Bộ thủ | 人 | Số nét | 10 | nét | 亻 | nhân | biểu nghĩa | người | 夂 | tri | biểu hình | bàn chân đi | 犬 | khuyển | biểu nghĩa | con chó | 倏 là chữ hình thanh theo Wiktionary: 攸 (biểu âm) và 犬 (biểu nghĩa — con chó chạy nhanh). Dạng viết hiện tại phân tích thành 亻+夂+犬 nhưng cấu trúc gốc là 攸+犬. Nghĩa là đột ngột, chớp nhoáng như chó vụt qua.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thúc\": con chó (犬) vụt qua mắt — chớp nhoáng, đột ngột như bóng chó chạy qua. | Gương Hán-Việt | thúc trong 倏忽 (thúc hốt — chợt, bỗng nhiên), 倏然 (thúc nhiên — đột ngột) | Mở khoá kiến thức | Biết 倏 mở khoá: 倏忽, 倏然, 倏地 — nhóm từ văn ngôn chỉ sự nhanh chóng bất ngờ.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Theo Wiktionary, 倏 là chữ hình thanh gồm 攸 (biểu âm) và 犬 (biểu nghĩa: chó — chạy rất nhanh). Nghĩa là đột ngột, chớp nhoáng. Dạng tiểu triện và lục thư thông đều có. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chợt, chớp nhoáng", "Hạng Tần Suất (Jun Da)": "2790.0", "Tần Suất % (Jun Da)": "98.9475427844", "GavinGrover_Once (Chiết tự trực tiếp)": "No glyph available + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "倏", "Unihan_Traditional (Chữ Phồn thể)": "倏", "Pinyin_Xie": "shū", "Âm Hán Việt_Xie": "thúc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Phó từ | 副词 | Thường làm phó từ đứng trước động từ trong văn viết để diễn tả hành động xảy ra cực kỳ nhanh chóng, đột ngột. | Phó từ | 副词 | Bổ nghĩa cho động từ hoặc tính từ và luôn đứng TRƯỚC chúng — 都是, 很好. Không đứng sau như tiếng Việt và không bổ nghĩa cho danh từ.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('聂', '{"9000": "2791.0", "Chữ Trung Quốc": "聂", "Bộ thủ & thành phần_Xie": "Bộ thủ | 耳 | Số nét | 10 | nét | 耳 | nhĩ | biểu nghĩa | tai | 双 | song | biểu hình | đôi, hai | 聂 là dạng giản thể của 聶. Chữ gốc 聶 gồm ba chữ 耳 chồng nhau (ba tai), gợi ý nhiều tai nghe cùng lúc — ý nghĩa thì thầm vào tai. Không phải hình thanh; đây là hội ý thuần tuý.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nhiếp\": ba cái tai (耳耳耳) — người này ghé tai người kia thì thầm, ý chỉ nói nhỏ bí mật. | Gương Hán-Việt | nhiếp trong họ 聂 (Nhiếp), 聂耳 (Nhiếp Nhĩ — tên nhạc sĩ) | Mở khoá kiến thức | Biết 聂 mở khoá: 聂耳, 聂聂 — dùng chủ yếu trong tên riêng và từ văn ngôn.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 聶 (phồn thể) được cấu tạo từ ba chữ 耳 (ba tai) — biểu thị hành động thì thầm vào tai người. Dạng giản thể 聂 rút gọn thành 耳+双. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nói thầm; thịt thái mỏng", "Hạng Tần Suất (Jun Da)": "2791.0", "Tần Suất % (Jun Da)": "98.9488362975", "GavinGrover_Once (Chiết tự trực tiếp)": "耳 + 双", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱耳双", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "双", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "耳", "Unihan_Simplified (Chữ Giản thể)": "聂", "Unihan_Traditional (Chữ Phồn thể)": "聶", "Pinyin_Xie": "niè", "Âm Hán Việt_Xie": "niếp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chữ này thường dùng làm động từ chỉ hành động nói thầm hoặc làm danh từ chỉ họ người. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('婉', '{"9000": "2792.0", "Chữ Trung Quốc": "婉", "Bộ thủ & thành phần_Xie": "Bộ thủ | 女 | Số nét | 11 | nét | 女 | nữ | biểu nghĩa | người phụ nữ | 宛 | uyển | biểu âm | cong uốn, uyển chuyển | 婉 là chữ hình thanh: 女 (Nữ) biểu nghĩa chỉ phụ nữ; 宛 (Uyển) biểu âm, đồng thời gợi ý uyển chuyển. Nghĩa là dịu dàng, khéo léo, uyển chuyển.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"uyển\": người phụ nữ (女) uyển chuyển (宛) — dịu dàng, khéo léo như dáng liễu rủ. | Gương Hán-Việt | uyển trong 委婉 (uỷ uyển — khéo léo, tế nhị), 婉转 (uyển chuyển — uốn lượn dịu dàng) | Mở khoá kiến thức | Biết 婉 mở khoá: 委婉, 婉转, 温婉, 婉拒 — nhóm từ chỉ sự dịu dàng tế nhị.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Theo cấu trúc chữ, 婉 gồm 女 (biểu nghĩa: phụ nữ) và 宛 (biểu âm). Dạng tiểu triện và lục thư thông đã có. Nghĩa là dịu dàng, đoan trang, khéo léo. Chưa tìm thấy dạng giáp cốt riêng. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: uyển vãn 婉娩)", "Hạng Tần Suất (Jun Da)": "2792.0", "Tần Suất % (Jun Da)": "98.9501298107", "GavinGrover_Once (Chiết tự trực tiếp)": "女 + 宛", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰女宛", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "宛", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "女", "Unihan_Simplified (Chữ Giản thể)": "婉", "Unihan_Traditional (Chữ Phồn thể)": "婉", "Pinyin_Xie": "wǎn", "Âm Hán Việt_Xie": "uyển", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường làm tính từ bổ nghĩa cho danh từ hoặc kết hợp tạo từ ghép chỉ sự khéo léo, dịu dàng. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('噪', '{"9000": "2793.0", "Chữ Trung Quốc": "噪", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 16 | nét | 口 | khẩu | biểu nghĩa | miệng | 喿 | táo | biểu âm | chim kêu (cho âm zào) | 噪 = 口 (Khẩu, biểu nghĩa: miệng) + 喿 (Táo, biểu âm, đồng thời hội ý: tiếng kêu). Chữ hình thanh kiêm hội ý — tiếng ồn ào như nhiều con chim cùng kêu.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"táo\": miệng (口) kêu táo (喿) lên như bầy chim — tiếng ồn ào hỗn loạn không ai chịu nổi. | Gương Hán-Việt | \"táo\" trong \"táo loạn\" (ồn ào, hỗn loạn) | Mở khoá kiến thức | Biết 噪 (táo) mở khoá: 噪音 (táo âm — tiếng ồn); 噪声 (táo thanh — tiếng ồn, tạp âm); 名噪一时 (danh táo nhất thời — nổi tiếng một thời).", "Tự nguyên_Xie": "Chữ hình thanh kiêm hội ý theo Wiktionary: 口 (miệng, biểu nghĩa) + 喿 (biểu âm: tiếng chim kêu). Nguyên bản viết là 喿. Nghĩa gốc là tiếng ồn ào, kêu la — như bầy chim cùng hót một lúc. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1501.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Khẩu (030) Táo (1177)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Khẩu (số 030 - cái miệng/ 口 /chỉ ý) ở bên trái chữ Táo (số 1177 - tiếng chim/ 喿 /chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Táo (喿) chỉ âm, bộ Khẩu chỉ ý. Táo là tiếng kêu ầm ĩ, ồn ào nhức tai (huyên táo, táo âm).", "Nghĩa Tiếng Việt_Xie": "tiếng chim kêu; reo hò ầm ĩ; chê trách", "Hạng Tần Suất (Jun Da)": "2793.0", "Tần Suất % (Jun Da)": "98.9514222904", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 喿", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口喿", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "喿", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "噪", "Unihan_Traditional (Chữ Phồn thể)": "噪", "Pinyin_Xie": "zào", "Âm Hán Việt_Xie": "táo", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường làm động từ chỉ việc làm ồn, kêu gào hoặc làm danh từ chỉ tiếng ồn ào. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('稼', '{"9000": "2794.0", "Chữ Trung Quốc": "稼", "Bộ thủ & thành phần_Xie": "Bộ thủ | 禾 | Số nét | 15 | nét | 禾 | hoà | biểu nghĩa | lúa, ngũ cốc | 家 | gia | biểu âm | nhà (cho âm jià) | 稼 = 禾 (Hoà, biểu nghĩa: lúa) + 家 (Gia, biểu âm). Chữ hình thanh — lúa của nhà nông, mùa màng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"giá\": lúa (禾) của nhà (家) — mùa màng, cây trồng của người nông dân. | Gương Hán-Việt | \"giá\" trong \"giá trị\" (giá trị mùa màng) | Mở khoá kiến thức | Biết 稼 (giá) mở khoá: 庄稼 (trang giá — cây trồng, hoa màu); 稼穑 (giá sắc — trồng trọt và thu hoạch).", "Tự nguyên_Xie": "Chữ hình thanh theo Wiktionary: 禾 (lúa, biểu nghĩa) + 家 (biểu âm). Nghĩa gốc là gieo trồng, mùa màng — cây lúa của gia đình nông dân. Chủ yếu dùng trong 庄稼 (cây trồng, hoa màu). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cấy lúa", "Hạng Tần Suất (Jun Da)": "2794.0", "Tần Suất % (Jun Da)": "98.9527142532", "GavinGrover_Once (Chiết tự trực tiếp)": "禾 + 家", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰禾家", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "家", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "禾", "Unihan_Simplified (Chữ Giản thể)": "稼", "Unihan_Traditional (Chữ Phồn thể)": "稼", "Pinyin_Xie": "jià", "Âm Hán Việt_Xie": "giá", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường làm động từ chỉ việc trồng trọt hoặc kết hợp thành danh từ chỉ cây lương thực. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鳍', '{"9000": "2795.0", "Chữ Trung Quốc": "鳍", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 18 | nét | 鱼 | ngư | biểu nghĩa | cá | 耆 | kỳ | biểu âm | người cao tuổi, đứng đầu | 鳍 là dạng giản thể của 鰭. Chữ hình thanh: 鱼 (Ngư) biểu nghĩa chỉ cá; 耆 (Kỳ) biểu âm. Nghĩa là vây cá.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"kỳ\": con cá (鱼) dùng vây để bơi — 鳍 là vây cá, giúp cá điều hướng trong nước. | Gương Hán-Việt | kỳ trong 鱼鳍 (ngư kỳ — vây cá), 背鳍 (bối kỳ — vây lưng) | Mở khoá kiến thức | Biết 鳍 mở khoá: 鱼鳍, 背鳍, 胸鳍, 尾鳍 — nhóm từ giải phẫu học cá.", "Tự nguyên_Xie": "鳍 là giản thể của 鰭. Theo cấu trúc, 鰭 gồm 魚 (biểu nghĩa: cá) và một thành phần biểu âm. Nghĩa chỉ vây cá — bộ phận giúp cá bơi và giữ thăng bằng. Chưa tìm thấy nguồn Wiktionary glyph-origin riêng biệt. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "vây cá", "Hạng Tần Suất (Jun Da)": "2795.0", "Tần Suất % (Jun Da)": "98.954001565", "GavinGrover_Once (Chiết tự trực tiếp)": "鱼 + 耆", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰鱼耆", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "耆", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鱼", "Unihan_Simplified (Chữ Giản thể)": "鳍", "Unihan_Traditional (Chữ Phồn thể)": "鰭", "Pinyin_Xie": "qí", "Âm Hán Việt_Xie": "kì", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng sau các từ chỉ loài cá hoặc đứng độc lập làm tân ngữ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('菱', '{"9000": "2796.0", "Chữ Trung Quốc": "菱", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 11 | nét | 艹 | thảo | biểu nghĩa | cỏ, thực vật | 夌 | lăng | biểu âm | vượt qua | 菱 là chữ hình thanh: 艹 (Thảo) biểu nghĩa chỉ thực vật; 夌 (Lăng) biểu âm. Chỉ cây ấu nước — loại thực vật thủy sinh có quả góc nhọn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lăng\": cây cỏ (艹) với âm lăng (夌) — cây ấu nước cho củ hình thoi có gai nhọn. | Gương Hán-Việt | lăng trong 菱形 (lăng hình — hình thoi), 菱角 (lăng giác — quả ấu, củ ấu) | Mở khoá kiến thức | Biết 菱 mở khoá: 菱形, 菱角, 菱花 — nhóm từ về hình học và thực vật.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Theo Wiktionary, 菱 là chữ hình thanh gồm 艹 (biểu nghĩa: thực vật) và 夌 (biểu âm). Nghĩa chỉ cây ấu (water chestnut), thực vật thủy sinh với quả có gai góc. Dạng tiểu triện và lục thư thông đều có. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cây ấu", "Hạng Tần Suất (Jun Da)": "2796.0", "Tần Suất % (Jun Da)": "98.9552878432", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 夌", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹夌", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "夌", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "菱", "Unihan_Traditional (Chữ Phồn thể)": "菱", "Pinyin_Xie": "líng", "Âm Hán Việt_Xie": "lăng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ cây củ ấu hoặc dùng làm định ngữ chỉ hình thoi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('盏', '{"9000": "2797.0", "Chữ Trung Quốc": "盏", "Bộ thủ & thành phần_Xie": "Bộ thủ | 皿 | Số nét | 10 | nét | 戋 | tiên | biểu âm | nhỏ, ít | 皿 | mãnh | biểu nghĩa | dụng cụ đựng, bát đĩa | 盏 là dạng giản thể của 盞. Chữ hình thanh: 皿 (Mãnh) biểu nghĩa chỉ vật đựng; 戋 (Tiên, giản thể của 戔) biểu âm gợi ý nhỏ bé. Nghĩa là chén nhỏ, đèn dầu nhỏ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trản\": cái bát (皿) nhỏ bé (戋) — chiếc chén rượu nhỏ hoặc ngọn đèn dầu. | Gương Hán-Việt | trản trong 灯盏 (đăng trản — ngọn đèn dầu), 茶盏 (trà trản — chén trà nhỏ) | Mở khoá kiến thức | Biết 盏 mở khoá: 灯盏, 茶盏, 油灯一盏 — nhóm từ về dụng cụ uống và đèn.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 盏 là giản thể của 盞 (rút gọn 戔 thành 戋). Theo cấu trúc 盞, gồm 皿 (biểu nghĩa: dụng cụ đựng) và 戔 (biểu âm, gợi ý nhỏ). Nghĩa là chén nhỏ hoặc dùng làm lượng từ đếm đèn. Dạng tiểu triện và lục thư thông đã có. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái chén nhỏ", "Hạng Tần Suất (Jun Da)": "2797.0", "Tần Suất % (Jun Da)": "98.956572571", "GavinGrover_Once (Chiết tự trực tiếp)": "戋 + 皿", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱戋皿", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "戋", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "皿", "Unihan_Simplified (Chữ Giản thể)": "盏", "Unihan_Traditional (Chữ Phồn thể)": "盞", "Pinyin_Xie": "zhǎn", "Âm Hán Việt_Xie": "trản", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Lượng từ | 量词 | Danh từ | 名词 | Thường dùng làm lượng từ cho đèn hoặc làm danh từ chỉ cái chén nhỏ. | Lượng từ | 量词 | Đứng giữa số từ (hoặc 这/那) và danh từ: 一杯茶, 这本书. Mỗi danh từ đi với lượng từ riêng; 个 là lượng từ dùng chung phổ biến nhất. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | zhǎn | / | cái (đèn) | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Từ chức năng và phụ từ II", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('匿', '{"9000": "2798.0", "Chữ Trung Quốc": "匿", "Bộ thủ & thành phần_Xie": "Bộ thủ | 匸 | Số nét | 10 | nét | 匚 | phương | biểu nghĩa | cái hộp, ẩn kín | 若 | nhược | biểu âm | như, yếu | 匿 là chữ hình thanh: 匸 (Phương — bộ hộp che giấu) biểu nghĩa; 若 (Nhược) biểu âm. Nghĩa là giấu kín, ẩn náu.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nặc\": trong hộp kín (匸) như 若 (nhược — như ai đó) — ẩn nặc, giấu mình không để ai biết. | Gương Hán-Việt | nặc trong 匿名 (nặc danh — ẩn danh), 藏匿 (tàng nặc — che giấu, ẩn náu) | Mở khoá kiến thức | Biết 匿 mở khoá: 匿名, 藏匿, 隐匿 — nhóm từ về sự che giấu, bí mật.", "Tự nguyên_Xie": "Kim văn | Bạch thư | Tiểu triện | Theo Wiktionary, 匿 là chữ hình thanh gồm 匸 (biểu nghĩa: che giấu, hộp kín) và 若 (biểu âm). Dạng kim văn, bạch thư và tiểu triện đều có. Nghĩa là trốn ẩn, che giấu. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1248.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Hệ (022) Nhược (1198)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Hệ (số 022 - cái hộp giấu đồ/ 匸) che lấy chữ Nhược (số 1198 - giả sử/chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Nhược chỉ âm, bộ Hệ chỉ ý. Nặc là che giấu, cất giấu đi, ẩn trốn (nặc danh, tàng nặc).", "Nghĩa Tiếng Việt_Xie": "giấu kín", "Hạng Tần Suất (Jun Da)": "2798.0", "Tần Suất % (Jun Da)": "98.9578536814", "GavinGrover_Once (Chiết tự trực tiếp)": "匚 + 若", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿷ (Bao quanh phía trái)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴匚若", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "若", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "匚", "Unihan_Simplified (Chữ Giản thể)": "匿", "Unihan_Traditional (Chữ Phồn thể)": "匿", "Pinyin_Xie": "nì", "Âm Hán Việt_Xie": "nặc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước tân ngữ để chỉ hành vi che giấu hoặc ẩn nấp. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('吱', '{"9000": "2799.0", "Chữ Trung Quốc": "吱", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 7 | nét | 口 | khẩu | biểu nghĩa | miệng, âm thanh | 支 | chi | biểu âm | nhánh, chi | 吱 là chữ hình thanh: 口 (Khẩu) biểu nghĩa chỉ âm thanh; 支 (Chi) biểu âm. Dùng mô phỏng tiếng cọt kẹt, chiêm chiếp, tiếng kẽo kẹt.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chi\": miệng (口) phát âm chi chi (支) — tiếng kẽo kẹt nhỏ như cửa cũ mở ra. | Gương Hán-Việt | chi trong 吱吱 (chi chi — tiếng kẽo kẹt liên tục) | Mở khoá kiến thức | Biết 吱 mở khoá: 吱吱, 吱声, 嘎吱 — từ tượng thanh về tiếng nhỏ, kẽo kẹt.", "Tự nguyên_Xie": "Theo Wiktionary, 吱 là chữ hình thanh gồm 口 (biểu nghĩa: âm thanh) và 支 (biểu âm). Từ tượng thanh chỉ tiếng kẽo kẹt, tiếng cọt kẹt nhỏ liên tục. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tiếng kêu chiêm chiếp, chíu chít", "Hạng Tần Suất (Jun Da)": "2799.0", "Tần Suất % (Jun Da)": "98.9591342749", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 支", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口支", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "支", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "吱", "Unihan_Traditional (Chữ Phồn thể)": "吱", "Pinyin_Xie": "zhī", "Âm Hán Việt_Xie": "chi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Từ tượng thanh | 象声词 | Động từ | 动词 | Thường dùng làm từ tượng thanh mô tả tiếng kêu của chuột hoặc tiếng cọt kẹt của cửa gỗ. | Từ tượng thanh | 象声词 | Mô phỏng âm thanh: 哗哗, 汪汪. Có thể làm định ngữ, trạng ngữ hoặc đứng độc lập. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('寝', '{"9000": "2800.0", "Chữ Trung Quốc": "寝", "Bộ thủ & thành phần_Xie": "Bộ thủ | 宀 | Số nét | 13 | nét | 宀 | miên | biểu nghĩa | mái nhà | 爿 | biểu nghĩa | giường (hình bộ phận của giường) | 𠬶 | biểu âm | chổi và tay (cho âm qǐn) | 寝 = 宀 (Miên, mái nhà) + 爿 (giường) + 𠬶 (biểu âm: chổi và tay). Chữ hình thanh kiêm hội ý — mái nhà có giường ngủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tẩm\": mái nhà (宀) có giường (爿) để tẩm bổ giấc ngủ — phòng ngủ, chỗ nghỉ ngơi. | Gương Hán-Việt | \"tẩm\" trong \"tẩm mình\" (ngâm mình) và \"tẩm bổ\" (bồi dưỡng) | Mở khoá kiến thức | Biết 寝 (tẩm) mở khoá: 寝室 (tẩm thất — phòng ngủ, ký túc xá); 废寝忘食 (phế tẩm vong thực — bỏ ngủ quên ăn); 就寝 (tựu tẩm — đi ngủ).", "Tự nguyên_Xie": "Chữ hình thanh kiêm hội ý theo Wiktionary: 宀 (mái nhà) + 爿 (giường) + 𠬶 (biểu âm: chổi và tay). Nghĩa gốc là phòng ngủ, giường ngủ — nơi nghỉ ngơi dưới mái nhà. Có từ ghép nổi tiếng là 废寝忘食 (bỏ ngủ quên ăn). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ngủ; lăng mộ", "Hạng Tần Suất (Jun Da)": "2800.0", "Tần Suất % (Jun Da)": "98.9604133181", "GavinGrover_Once (Chiết tự trực tiếp)": "宀 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱宀", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "寝", "Unihan_Traditional (Chữ Phồn thể)": "寑", "Pinyin_Xie": "qǐn", "Âm Hán Việt_Xie": "tẩm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường làm động từ chỉ việc ngủ hoặc làm danh từ chỉ phòng ngủ, lăng mộ hoàng gia. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('揽', '{"9000": "2801.0", "Chữ Trung Quốc": "揽", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 12 | nét | 扌 | thủ | biểu nghĩa | tay | 览 | lãm | biểu âm | xem khắp, bao quát | 揽 là dạng giản thể của 攬. Chữ hình thanh: 扌 (Thủ) biểu nghĩa chỉ tay; 览 (Lãm, giản thể của 覽) biểu âm. Nghĩa là nắm cả, ôm hết, độc quyền.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lãm\": tay (扌) vươn ra ôm tất cả (览 — xem khắp) — lãm hết, không để ai khác tham gia. | Gương Hán-Việt | lãm trong 揽权 (lãm quyền — nắm quyền), 招揽 (chiêu lãm — thu hút), 一揽子 (nhất lãm tử — toàn diện) | Mở khoá kiến thức | Biết 揽 mở khoá: 招揽, 揽权, 揽活, 一揽子 — nhóm từ về nắm giữ, thu hút.", "Tự nguyên_Xie": "Tiểu triện | 揽 là giản thể của 攬 (rút gọn 覽 thành 览). Theo cấu trúc 攬, gồm 扌 (biểu nghĩa: tay) và 覽 (biểu âm). Nghĩa là vươn tay ôm hết, nắm trọn, độc quyền. Dạng tiểu triện đã có. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nắm cả, giữ hết; nhận thầu", "Hạng Tần Suất (Jun Da)": "2801.0", "Tần Suất % (Jun Da)": "98.9616918446", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 览", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌览", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "览", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "揽", "Unihan_Traditional (Chữ Phồn thể)": "攬", "Pinyin_Xie": "lǎn", "Âm Hán Việt_Xie": "lãm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước tân ngữ để chỉ hành động ôm giữ hoặc thâu tóm quyền lực, công việc. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | lǎn | / | đảm nhận | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Từ III", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('髓', '{"9000": "2802.0", "Chữ Trung Quốc": "髓", "Bộ thủ & thành phần_Xie": "Bộ thủ | 骨 | Số nét | 21 | nét | 骨 | cốt | biểu nghĩa | xương | 遀 | biểu âm | thành phần âm (辶+左+月) | 髓 là chữ hình thanh: 骨 (Cốt) biểu nghĩa chỉ xương; phần còn lại (遀, bao gồm 辶+左+月) biểu âm. Nghĩa là tủy xương — phần mềm bên trong xương.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tuỷ\": bên trong xương (骨) là tinh chất — 精髓 tức tinh tủy, phần cốt lõi quan trọng nhất. | Gương Hán-Việt | tuỷ trong 精髓 (tinh tuỷ — tinh hoa, cốt lõi), 骨髓 (cốt tuỷ — tủy xương) | Mở khoá kiến thức | Biết 髓 mở khoá: 精髓, 骨髓, 脑髓 — nhóm từ giải phẫu và ẩn dụ về cốt lõi.", "Tự nguyên_Xie": "Theo cấu trúc, 髓 gồm 骨 (biểu nghĩa: xương) và thành phần biểu âm phức tạp. Wiktionary chỉ có {{Han etym}} chung, không có glyph-origin chi tiết. Nghĩa là tủy xương, phần tinh chất bên trong. Chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tuỷ trong xương", "Hạng Tần Suất (Jun Da)": "2802.0", "Tần Suất % (Jun Da)": "98.962970371", "GavinGrover_Once (Chiết tự trực tiếp)": "骨 + 遀", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰骨遀", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "遀", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "骨", "Unihan_Simplified (Chữ Giản thể)": "髓", "Unihan_Traditional (Chữ Phồn thể)": "髓", "Pinyin_Xie": "suǐ", "Âm Hán Việt_Xie": "tuỷ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ tủy trong xương hoặc nghĩa bóng là phần tinh hoa, cốt lõi của sự vật. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('秉', '{"9000": "2803.0", "Chữ Trung Quốc": "秉", "Bộ thủ & thành phần_Xie": "Bộ thủ | 禾 | Số nét | 8 | nét | 禾 | hoà | biểu nghĩa | lúa, cây ngũ cốc | 又 | hựu | biểu nghĩa | bàn tay | 秉 là chữ hội ý: 禾 (Hoà — cây lúa) và 又 (bàn tay) — bàn tay cầm bó lúa. So sánh 兼 là tay cầm hai bó lúa. Nghĩa gốc: cầm nắm, sau mở rộng thành giữ vững, nắm giữ quyền hành.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bỉnh\": bàn tay (又) nắm bó lúa (禾) — cầm chắc, nắm vững như người thợ gặt giữ lúa. | Gương Hán-Việt | bỉnh trong 秉承 (bỉnh thừa — tuân theo, kế thừa), 秉公 (bỉnh công — công bằng, vô tư) | Mở khoá kiến thức | Biết 秉 mở khoá: 秉承, 秉公, 秉性, 秉烛 — nhóm từ chỉ giữ vững, tuân theo nguyên tắc.", "Tự nguyên_Xie": "Giáp cốt văn | Kim văn | Đại triện | Tiểu triện | Theo Wiktionary, 秉 là chữ hội ý gồm 禾 (cây lúa) và 又 (bàn tay) — hình ảnh bàn tay cầm cây lúa bằng thân. Dạng giáp cốt, kim văn, đại triện và tiểu triện đều có và rõ ràng. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "184.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Hòa (117) Hựu (159)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Hựu (số 159) nằm giữa chữ Hòa (số 117) . Hình ảnh bàn tay đang cầm một bó lúa (Hòa).", "Nghĩa Tiếng Việt_Xie": "cầm nắm", "Hạng Tần Suất (Jun Da)": "2803.0", "Tần Suất % (Jun Da)": "98.9642478638", "GavinGrover_Once (Chiết tự trực tiếp)": "禾 + ⺕", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴禾⺕", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "⺕", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "禾", "Unihan_Simplified (Chữ Giản thể)": "秉", "Unihan_Traditional (Chữ Phồn thể)": "秉", "Pinyin_Xie": "bǐng", "Âm Hán Việt_Xie": "bỉnh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường làm động từ đứng trước danh từ để chỉ việc cầm nắm hoặc giữ vững nguyên tắc, ý chí. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('哺', '{"9000": "2804.0", "Chữ Trung Quốc": "哺", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 10 | nét | 口 | khẩu | biểu nghĩa | miệng | 甫 | phủ | biểu âm | người đàn ông trưởng thành (cho âm bǔ) | 哺 = 口 (Khẩu, biểu nghĩa: miệng) + 甫 (Phủ, biểu âm). Chữ hình thanh — miệng mớm thức ăn, nuôi dưỡng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bú\": miệng (口) người lớn (甫) mớm cho con — hành động cho bú, nuôi dưỡng từ miệng. | Gương Hán-Việt | \"bú\" trong \"cho bú\" — trẻ bú mẹ, được nuôi dưỡng | Mở khoá kiến thức | Biết 哺 (bú) mở khoá: 哺乳 (bú nhũ — cho con bú, động vật có vú); 哺育 (bú dục — nuôi dưỡng); 哺乳动物 (bú nhũ động vật — động vật có vú).", "Tự nguyên_Xie": "Chữ hình thanh theo Wiktionary: 口 (miệng, biểu nghĩa) + 甫 (biểu âm). Nghĩa gốc là mớm thức ăn — hành động dùng miệng nhai rồi đút cho con bú. Từ đó mở rộng sang nghĩa ''nuôi dưỡng''. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bú sữa", "Hạng Tần Suất (Jun Da)": "2804.0", "Tần Suất % (Jun Da)": "98.965522256", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 甫", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口甫", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "甫", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "哺", "Unihan_Traditional (Chữ Phồn thể)": "哺", "Pinyin_Xie": "bǔ", "Âm Hán Việt_Xie": "bộ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ kết hợp với các từ chỉ việc nuôi dưỡng hoặc sinh sản để tạo thành động từ song âm tiết. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('矢', '{"9000": "2805.0", "Chữ Trung Quốc": "矢", "Bộ thủ & thành phần_Xie": "Bộ thủ | 矢 | Số nét | 5 | nét | 矢 | thỉ | tượng hình | mũi tên — chữ tự thân là tượng hình | 矢 là chữ tượng hình độc lập: hình dạng mũi tên với đầu nhọn và đuôi tua. Các dạng giáp cốt, kim văn rõ ràng cho thấy hình mũi tên. Không phân tích thêm thành phần.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thỉ\": hình mũi tên — 矢 vẽ thẳng đứng như tên đang bay thẳng, biểu thị sự chính xác và quyết tâm (有的放矢 — có mục tiêu rõ ràng). | Gương Hán-Việt | thỉ trong 有的放矢 (hữu đích phóng thỉ — bắn tên có mục tiêu), 矢志 (thỉ chí — thề quyết tâm) | Mở khoá kiến thức | Biết 矢 mở khoá: 有的放矢, 矢志, 矢口否认 — nhóm từ về mục tiêu và thề nguyện.", "Tự nguyên_Xie": "Giáp cốt văn | Kim văn | Đại triện | Tiểu triện | Theo Wiktionary, 矢 là chữ tượng hình (象形) mô tả mũi tên. Dạng giáp cốt, kim văn, đại triện và tiểu triện đều cho thấy hình dạng mũi tên với đầu và đuôi rõ ràng. So sánh với 至 và 畀 cũng dùng hình ảnh tên bay. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "798.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Nhân (008) Đại (017)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Nhân (số 008 - người/viết biến thể) và chữ Đại (số 017 - to/người). Hình người đang đứng giương cung bắn mũi tên. Giải thích sự chuyển ý: Đây là chữ Tượng hình. Thỉ là mũi tên.", "Nghĩa Tiếng Việt_Xie": "tên (bắn cung)", "Hạng Tần Suất (Jun Da)": "2805.0", "Tần Suất % (Jun Da)": "98.9667966481", "GavinGrover_Once (Chiết tự trực tiếp)": "𠂉 + 大", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱𠂉大", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "𠂉", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "大", "Unihan_Simplified (Chữ Giản thể)": "矢", "Unihan_Traditional (Chữ Phồn thể)": "矢", "Pinyin_Xie": "shǐ", "Âm Hán Việt_Xie": "thỉ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường dùng làm danh từ trong văn cổ hoặc kết hợp làm động từ trong các từ ghép mang nghĩa thề thốt. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('啪', '{"9000": "2806.0", "Chữ Trung Quốc": "啪", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 11 | nét | 口 | khẩu | biểu nghĩa | miệng, âm thanh | 拍 | phách | biểu âm | vỗ, đập | 啪 là chữ hình thanh: 口 (Khẩu) biểu nghĩa chỉ âm thanh; 拍 (Phách) biểu âm. Tuy nhiên cấu trúc gốc có thể không chính thức ghi nhận — chữ tạo muộn dùng mô phỏng âm bộp, bốp.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ba\": miệng (口) phát ra âm đập (拍 phách) — tiếng bốp bộp khi vỗ tay hoặc đập mạnh. | Gương Hán-Việt | ba trong 啪嗒 (ba đạp — tiếng đập lộp cộp), 啪啪 (ba ba — tiếng vỗ liên tiếp) | Mở khoá kiến thức | Biết 啪 mở khoá từ tượng thanh: 啪啪, 啪嗒, 啪的一声 — tiếng vỗ, đập.", "Tự nguyên_Xie": "Không có nguồn Wiktionary glyph-origin cho 啪. Theo cấu trúc, gồm 口 (biểu nghĩa: âm thanh) và 拍 (biểu âm: vỗ, đập). Đây là chữ tạo muộn để mô phỏng tiếng bộp, bốp khi vỗ hoặc đập. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bốp, bộp (tiếng động)", "Hạng Tần Suất (Jun Da)": "2806.0", "Tần Suất % (Jun Da)": "98.9680638053", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 拍", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口拍", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "拍", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "啪", "Unihan_Traditional (Chữ Phồn thể)": "啪", "Pinyin_Xie": "pā", "Âm Hán Việt_Xie": "ba", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Từ tượng thanh | 象声词 | Dùng làm từ tượng thanh mô tả tiếng động đột ngột như tiếng vỗ tay, tiếng gõ hoặc tiếng nổ nhỏ. | Từ tượng thanh | 象声词 | Mô phỏng âm thanh: 哗哗, 汪汪. Có thể làm định ngữ, trạng ngữ hoặc đứng độc lập.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('帜', '{"9000": "2807.0", "Chữ Trung Quốc": "帜", "Bộ thủ & thành phần_Xie": "Bộ thủ | 巾 | Số nét | 8 | nét | 巾 | cân | biểu nghĩa | khăn, vải | 只 | chỉ | biểu âm | chỉ (cho âm zhì) | 帜 = 巾 (Cân, biểu nghĩa: vải) + 只 (Chỉ, biểu âm). Dạng giản thể của 幟. Chữ hình thanh — vải/lụa làm cờ hiệu.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"xí\": vải (巾) phất (只) — lá cờ, hiệu kỳ phất cao để nhận diện. | Gương Hán-Việt | \"xí\" trong \"kỳ xí\" (cờ hiệu) và \"độc thụ nhất xí\" (cờ riêng, nổi bật) | Mở khoá kiến thức | Biết 帜 (xí) mở khoá: 旗帜 (kỳ xí — cờ hiệu, lập trường); 独树一帜 (độc thụ nhất xí — có phong cách riêng, nổi bật).", "Tự nguyên_Xie": "帜 là dạng giản thể của 幟 (rút gọn 戠 thành 只). Chữ gốc 幟 gồm 巾 (vải, biểu nghĩa) + 戠 (biểu âm). Nghĩa gốc là cờ hiệu, cờ trận — mảnh vải phất để nhận biết hiệu lệnh. Chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cờ hiệu", "Hạng Tần Suất (Jun Da)": "2807.0", "Tần Suất % (Jun Da)": "98.9693309624", "GavinGrover_Once (Chiết tự trực tiếp)": "巾 + 只", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰巾只", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "只", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "巾", "Unihan_Simplified (Chữ Giản thể)": "帜", "Unihan_Traditional (Chữ Phồn thể)": "幟", "Pinyin_Xie": "zhì", "Âm Hán Việt_Xie": "xí", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng sau các từ chỉ tính chất hoặc kết hợp thành từ ghép để chỉ lá cờ, biểu ngữ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('邵', '{"9000": "2808.0", "Chữ Trung Quốc": "邵", "Bộ thủ & thành phần_Xie": "Bộ thủ | 邑 | Số nét | 7 | nét | 召 | thiệu | biểu âm | gọi, triệu tập | 阝 | phụ | biểu nghĩa | vùng đất, địa danh | 邵 là chữ hình thanh: 阝 (Phụ — bộ địa danh bên phải) biểu nghĩa chỉ vùng đất; 召 (Thiệu) biểu âm. Dùng chủ yếu làm họ tên và tên địa danh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thiệu\": vùng đất (阝) mang âm 召 (thiệu) — tên địa danh cổ, nay là họ Thiệu. | Gương Hán-Việt | thiệu trong 邵兴 (Thiệu Hưng — địa danh Chiết Giang), 姓邵 (họ Thiệu) | Mở khoá kiến thức | Biết 邵 mở khoá tên riêng Trung Quốc: 邵逸夫, 邵阳, 邵武.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 邵 là chữ hình thanh gồm 召 (biểu âm) và 邑/阝 (biểu nghĩa: vùng đất). Nghĩa gốc là tên đất. Nay chủ yếu dùng làm họ (姓邵) và tên địa danh. Dạng tiểu triện đã có. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(tên đất)", "Hạng Tần Suất (Jun Da)": "2808.0", "Tần Suất % (Jun Da)": "98.9705945021", "GavinGrover_Once (Chiết tự trực tiếp)": "召 + 阝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰召阝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "召", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "阝", "Unihan_Simplified (Chữ Giản thể)": "邵", "Unihan_Traditional (Chữ Phồn thể)": "邵", "Pinyin_Xie": "shào", "Âm Hán Việt_Xie": "thiệu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chủ yếu dùng làm danh từ riêng để chỉ họ người hoặc địa danh cổ trong tiếng Trung. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('嗽', '{"9000": "2809.0", "Chữ Trung Quốc": "嗽", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 14 | nét | 口 | khẩu | biểu nghĩa | miệng | 欶 | sóc | biểu âm | gợi âm sòu | 嗽 = 口 (Khẩu, biểu nghĩa: miệng) + 欶 (Sóc, biểu âm); chữ hình thanh (ls=psc). Miệng phát ra tiếng ho — ''ho''.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thấu\": 口 (miệng) + 欶 (sóc) — miệng phát tiếng, ấy là ''thấu'' (ho); nhớ 咳嗽 (khái thấu = ho). | Gương Hán-Việt | ''thấu'' theo Hán-Việt; nghĩa thông dụng = ''ho'' trong tiếng Việt | Mở khoá kiến thức | Biết 嗽 là mở 咳嗽 — chìa khoá từ vựng y tế HSK 4.", "Tự nguyên_Xie": "Theo Wiktionary, 嗽 là chữ hình thanh: 口 (biểu nghĩa: miệng) ghép với 欶 (biểu âm). Nghĩa: ho, có đờm; cũng dùng nghĩa ''súc miệng'' (漱) trong văn cổ. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ho có đờm; mút", "Hạng Tần Suất (Jun Da)": "2809.0", "Tần Suất % (Jun Da)": "98.9718544242", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 欶", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口欶", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "欶", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "嗽", "Unihan_Traditional (Chữ Phồn thể)": "嗽", "Pinyin_Xie": "sòu", "Âm Hán Việt_Xie": "thấu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường kết hợp với chữ Khái để tạo thành động từ chỉ hành động ho. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('挟', '{"9000": "2810.0", "Chữ Trung Quốc": "挟", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 9 | nét | 扌 | thủ | biểu nghĩa | tay | 夹 | giáp | biểu âm | kẹp, cắp | 挟 là dạng giản thể của 挾. Chữ hình thanh: 扌 (Thủ) biểu nghĩa chỉ tay; 夹 (Giáp, giản thể của 夾) biểu âm. Nghĩa là cắp vào nách, kẹp, ép, dựa vào.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"giáp\": tay (扌) kẹp (夹 giáp) chặt — cắp vật vào nách hoặc ép người khác phải theo. | Gương Hán-Việt | giáp trong 挟持 (giáp trì — bắt làm con tin), 挟制 (giáp chế — khống chế) | Mở khoá kiến thức | Biết 挟 mở khoá: 挟持, 挟制, 要挟 — nhóm từ về cưỡng bức, khống chế.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 挟 là giản thể của 挾 (rút gọn 夾 thành 夹). Theo cấu trúc 挾, gồm 扌 (biểu nghĩa: tay) và 夾 (biểu âm: kẹp). Nghĩa là cắp vào nách, kẹp chặt, hoặc ép buộc bằng ưu thế. Dạng tiểu triện và lục thư thông đã có. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cắp, xách, xốc, gắp; cậy, nhờ, dựa vào; cái đũa", "Hạng Tần Suất (Jun Da)": "2810.0", "Tần Suất % (Jun Da)": "98.9731143464", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 夹", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌夹", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "夹", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "挟", "Unihan_Traditional (Chữ Phồn thể)": "挾", "Pinyin_Xie": "xié", "Âm Hán Việt_Xie": "hiệp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Làm động từ đứng trước tân ngữ để chỉ hành động kẹp, mang theo bên mình hoặc khống chế người khác. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('缸', '{"9000": "2811.0", "Chữ Trung Quốc": "缸", "Bộ thủ & thành phần_Xie": "Bộ thủ | 缶 | Số nét | 9 | nét | 缶 | phữu | biểu nghĩa | bình gốm, cái chum | 工 | công | biểu âm | thợ, công việc | 缸 là chữ hình thanh: 缶 (Phữu) biểu nghĩa chỉ bình gốm, đồ đựng; 工 (Công) biểu âm. Nghĩa là cái vại, chum sành lớn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cang\": cái bình gốm (缶) do thợ (工 công) làm ra — cái vại, chum sành lớn. | Gương Hán-Việt | cang trong 水缸 (thuỷ cang — chum nước), 鱼缸 (ngư cang — bể cá), 气缸 (khí cang — xi lanh) | Mở khoá kiến thức | Biết 缸 mở khoá: 水缸, 鱼缸, 气缸, 缸瓦 — nhóm từ về đồ gốm và kỹ thuật.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Theo cấu trúc, 缸 gồm 缶 (biểu nghĩa: bình gốm) và 工 (biểu âm). Wiktionary chỉ có {{Han etym}} chung. Nghĩa là cái vại, chum gốm lớn để đựng nước hoặc cá. Dạng tiểu triện và lục thư thông đã có. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "782.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Phẫu (781) Công (023)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Phẫu (số 781 - đồ sành sứ) ở bên trái chữ Công (số 023 - người thợ/chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Công chỉ âm, bộ Phẫu chỉ ý. Cang là cái vại, cái chum làm bằng sành sứ.", "Nghĩa Tiếng Việt_Xie": "cái ang, vại, sành, cái chum to", "Hạng Tần Suất (Jun Da)": "2811.0", "Tần Suất % (Jun Da)": "98.9743737518", "GavinGrover_Once (Chiết tự trực tiếp)": "缶 + 工", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰缶工", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "工", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "缶", "Unihan_Simplified (Chữ Giản thể)": "缸", "Unihan_Traditional (Chữ Phồn thể)": "缸", "Pinyin_Xie": "gāng", "Âm Hán Việt_Xie": "hang", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Lượng từ | 量词 | Thường làm danh từ chỉ đồ chứa bằng sành sứ hoặc làm lượng từ cho lượng nước chứa trong chum. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Lượng từ | 量词 | Đứng giữa số từ (hoặc 这/那) và danh từ: 一杯茶, 这本书. Mỗi danh từ đi với lượng từ riêng; 个 là lượng từ dùng chung phổ biến nhất.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | gāng | / | vại | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Thức ăn tôi", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('揉', '{"9000": "2812.0", "Chữ Trung Quốc": "揉", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 12 | nét | 扌 | thủ | biểu nghĩa | tay | 柔 | nhu | biểu âm | mềm mại (cho âm róu) | 揉 = 扌 (Thủ, biểu nghĩa: tay) + 柔 (Nhu, biểu âm). Chữ hình thanh — tay xoa, nhào, nhồi nhẹ nhàng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nhu\": tay (扌) nhu nhuyễn (柔) — xoa bóp nhẹ nhàng, nhào nặn mềm mại. | Gương Hán-Việt | \"nhu\" trong \"nhu mì\" (mềm mại, hiền lành) và \"nhu cầu\" (cần thiết) | Mở khoá kiến thức | Biết 揉 (nhu) mở khoá: 揉搓 (nhu toa — chà xát, xoa bóp); 揉眼睛 (nhu nhãn tinh — dụi mắt); 揉面 (nhu diện — nhào bột).", "Tự nguyên_Xie": "Chữ hình thanh theo Wiktionary: 手/扌 (tay, biểu nghĩa) + 柔 (biểu âm). Nghĩa gốc là xoa, bóp nhẹ — hành động dùng tay nhào nặn, xoa dịu. 柔 vừa cho âm vừa gợi tính chất mềm mại của hành động. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "uốn, nắn", "Hạng Tần Suất (Jun Da)": "2812.0", "Tần Suất % (Jun Da)": "98.9756279893", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 柔", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌柔", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "柔", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "揉", "Unihan_Traditional (Chữ Phồn thể)": "揉", "Pinyin_Xie": "róu", "Âm Hán Việt_Xie": "nhu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Làm động từ chỉ hành động dùng tay xoa, vò hoặc nắn một vật thể nào đó. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | róu | / | xoa bóp | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Từ III | HSK | HSK 6 | · | Động từ", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('腻', '{"9000": "2813.0", "Chữ Trung Quốc": "腻", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 13 | nét | 月 | nguyệt | biểu nghĩa | thịt, cơ thể (bộ nhục dạng trăng) | 贰 | nhị | biểu âm | hai (cho âm nì) | 腻 = 月 (bộ nhục, biểu nghĩa: thịt/béo) + 贰 (Nhị, biểu âm). Chữ hình thanh — thịt mỡ béo ngậy.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nhị\": thịt (月) béo gấp đôi (贰) — béo ngậy, nhờn, ăn nhiều quá sẽ thấy ngán. | Gương Hán-Việt | \"nhị\" trong \"nhị trùng\" (gấp đôi) — béo nhờn gấp bội | Mở khoá kiến thức | Biết 腻 (nhị) mở khoá: 油腻 (du nhị — béo ngậy, nhờn); 细腻 (tế nhị — mịn màng, tỉ mỉ); 腻烦 (nhị phiền — chán ngán).", "Tự nguyên_Xie": "Chữ hình thanh theo Wiktionary: 肉/月 (thịt, biểu nghĩa) + 貳/贰 (biểu âm). Nghĩa gốc là béo ngậy, mỡ màng — cảm giác của thức ăn quá béo. Từ đó mở rộng sang nghĩa ''nhờn, dính, chán ngấy''. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "béo, đồ ăn ngậy; trơn nhẵn; cáu bẩn", "Hạng Tần Suất (Jun Da)": "2813.0", "Tần Suất % (Jun Da)": "98.9768811932", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 贰", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月贰", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "贰", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "腻", "Unihan_Traditional (Chữ Phồn thể)": "膩", "Pinyin_Xie": "nì", "Âm Hán Việt_Xie": "nị, nhị", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường làm tính từ miêu tả thức ăn nhiều dầu mỡ hoặc làm bổ ngữ kết quả sau động từ để chỉ sự chán ngấy. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('驯', '{"9000": "2814.0", "Chữ Trung Quốc": "驯", "Bộ thủ & thành phần_Xie": "Bộ thủ | 馬 | Số nét | 6 | nét | 马 | mã | biểu nghĩa | ngựa | 川 | xuyên | biểu âm | sông, dòng chảy | 驯 là dạng giản thể của 馴. Chữ hình thanh: 马 (Mã) biểu nghĩa chỉ ngựa; 川 (Xuyên) biểu âm. Nghĩa là thuần hóa, ngựa lành.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tuần\": con ngựa (马) chảy êm như sông (川 xuyên) — ngựa thuần, hiền lành nghe lệnh. | Gương Hán-Việt | tuần trong 驯服 (tuần phục — thuần phục), 驯化 (tuần hoá — thuần hóa) | Mở khoá kiến thức | Biết 驯 mở khoá: 驯服, 驯化, 驯兽师, 温驯 — nhóm từ về thuần hóa động vật.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 驯 là giản thể của 馴 (rút gọn 馬 thành 马). Theo cấu trúc 馴, gồm 馬 (biểu nghĩa: ngựa) và 川 (biểu âm). Nghĩa là thuần hóa, nghe lời. Dạng tiểu triện và lục thư thông đã có. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thuần, lành (thú)", "Hạng Tần Suất (Jun Da)": "2814.0", "Tần Suất % (Jun Da)": "98.9781333636", "GavinGrover_Once (Chiết tự trực tiếp)": "马 + 川", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰马川", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "川", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "马", "Unihan_Simplified (Chữ Giản thể)": "驯", "Unihan_Traditional (Chữ Phồn thể)": "馴", "Pinyin_Xie": "xún", "Âm Hán Việt_Xie": "tuần", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường làm tính từ miêu tả tính cách động vật hoặc làm động từ chỉ quá trình thuần hóa thú hoang. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | xùn | / | thuần hóa | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Động vật và côn trùng", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('缆', '{"9000": "2815.0", "Chữ Trung Quốc": "缆", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 12 | nét | 纟 | mịch | biểu nghĩa | sợi tơ, dây | 览 | lãm | biểu âm | xem khắp, bao quát | 缆 là dạng giản thể của 纜. Chữ hình thanh: 纟 (Mịch) biểu nghĩa chỉ sợi, dây; 览 (Lãm, giản thể của 覽) biểu âm. Nghĩa là dây cáp lớn, dây neo thuyền.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lãm\": sợi dây (纟) to như bao quát tất cả (览 lãm) — dây cáp lớn neo thuyền, cáp treo. | Gương Hán-Việt | lãm trong 光缆 (quang lãm — cáp quang), 缆车 (lãm xa — cáp treo), 电缆 (điện lãm — cáp điện) | Mở khoá kiến thức | Biết 缆 mở khoá: 光缆, 缆车, 电缆, 缆绳 — nhóm từ về dây cáp và vận tải.", "Tự nguyên_Xie": "缆 là giản thể của 纜. Theo Wiktionary, 纜 gồm 糸 (biểu nghĩa: sợi tơ, dây) và 覽 (biểu âm). Nghĩa là dây thừng lớn, dây cáp neo thuyền. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "dây cáp; dây neo thuyền, dây chão buộc thuyền; buộc thuyền bằng dây to", "Hạng Tần Suất (Jun Da)": "2815.0", "Tần Suất % (Jun Da)": "98.9793788158", "GavinGrover_Once (Chiết tự trực tiếp)": "纟 + 览", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰纟览", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "览", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "纟", "Unihan_Simplified (Chữ Giản thể)": "缆", "Unihan_Traditional (Chữ Phồn thể)": "纜", "Pinyin_Xie": "lǎn", "Âm Hán Việt_Xie": "lãm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này làm danh từ chỉ dây cáp hoặc làm động từ khi biểu thị hành động buộc thuyền bằng dây thừng lớn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('晌', '{"9000": "2816.0", "Chữ Trung Quốc": "晌", "Bộ thủ & thành phần_Xie": "Bộ thủ | 日 | Số nét | 10 | nét | 日 | nhật | biểu nghĩa | mặt trời, ngày | 向 | hướng | biểu âm | hướng, phía | 晌 là chữ hình thanh: 日 (Nhật) biểu nghĩa chỉ mặt trời, thời gian trong ngày; 向 (Hướng) biểu âm. Nghĩa là buổi trưa, một khoảng thời gian trong ngày.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thưởng\": mặt trời (日) hướng (向 hướng) cao nhất — đỉnh trưa, buổi giữa ngày. | Gương Hán-Việt | thưởng trong 晌午 (thưởng ngọ — buổi trưa), 半晌 (bán thưởng — nửa buổi, một lúc) | Mở khoá kiến thức | Biết 晌 mở khoá: 晌午, 半晌, 晌饭 — nhóm từ chỉ thời điểm trong ngày.", "Tự nguyên_Xie": "Theo Wiktionary, 晌 vốn viết là 曏. Gồm 日 (biểu nghĩa: mặt trời, thời gian) và 向 (biểu âm). Nghĩa là buổi trưa, nửa ngày, hoặc khoảnh khắc ngắn. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "một buổi; một chặp; buổi trưa", "Hạng Tần Suất (Jun Da)": "2816.0", "Tần Suất % (Jun Da)": "98.9806196169", "GavinGrover_Once (Chiết tự trực tiếp)": "日 + 向", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰日向", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "向", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "日", "Unihan_Simplified (Chữ Giản thể)": "晌", "Unihan_Traditional (Chữ Phồn thể)": "晌", "Pinyin_Xie": "shǎng", "Âm Hán Việt_Xie": "thưởng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ thời gian buổi trưa hoặc một khoảng thời gian ngắn trong ngày. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('瘫', '{"9000": "2817.0", "Chữ Trung Quốc": "瘫", "Bộ thủ & thành phần_Xie": "Bộ thủ | 疒 | Số nét | 15 | nét | 疒 | nạch | biểu nghĩa | bệnh tật | 难 | nan | biểu âm | khó khăn (cho âm tān) | 瘫 = 疒 (Nạch, biểu nghĩa: bệnh) + 难 (Nan, biểu âm). Dạng giản thể của 癱. Chữ hình thanh — bệnh làm người không cử động được.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"than\": bệnh (疒) nặng khó (难) vượt qua — liệt, bại liệt, không còn cử động được. | Gương Hán-Việt | \"than\" trong \"bại than\" (liệt, bại liệt) | Mở khoá kiến thức | Biết 瘫 (than) mở khoá: 瘫痪 (than hoán — bại liệt); 瘫软 (than nhuyễn — liệt mềm, mềm nhũn); 偏瘫 (thiên than — liệt nửa người).", "Tự nguyên_Xie": "瘫 là dạng giản thể của 癱 (rút gọn 難 thành 难). Chữ gốc 癱 gồm 疒 (bệnh, biểu nghĩa) + 難 (biểu âm). Nghĩa gốc là bại liệt — bệnh tật khiến người không di chuyển được. Chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chân tay tê liệt", "Hạng Tần Suất (Jun Da)": "2817.0", "Tần Suất % (Jun Da)": "98.9818593844", "GavinGrover_Once (Chiết tự trực tiếp)": "疒 + 难", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴疒难", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "难", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "疒", "Unihan_Simplified (Chữ Giản thể)": "瘫", "Unihan_Traditional (Chữ Phồn thể)": "癱", "Pinyin_Xie": "tān", "Âm Hán Việt_Xie": "than", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Chữ này làm động từ hoặc tính từ để chỉ trạng thái cơ thể bị tê liệt, không thể cử động. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | tān | / | bị liệt | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Bệnh I", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('贮', '{"9000": "2818.0", "Chữ Trung Quốc": "贮", "Bộ thủ & thành phần_Xie": "Bộ thủ | 貝 | Số nét | 8 | nét | 贝 | bối | biểu nghĩa | tiền, của cải | 㝉 | biểu âm | thành phần âm (biến thể của 宁) | 贮 là dạng giản thể của 貯. Chữ hình thanh: 贝 (Bối) biểu nghĩa chỉ của cải, tiền bạc; 㝉 (biến thể của 宁) biểu âm. Nghĩa là cất giữ, tích trữ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trữ\": cất giữ của cải (贝) trong kho — tích trữ để dành cho ngày sau. | Gương Hán-Việt | trữ trong 贮藏 (trữ tàng — tích trữ, bảo quản), 贮存 (trữ tồn — lưu trữ) | Mở khoá kiến thức | Biết 贮 mở khoá: 贮藏, 贮存, 贮量, 贮备 — nhóm từ về lưu trữ và tích luỹ.", "Tự nguyên_Xie": "Giáp cốt văn | Kim văn | Đại triện | Tiểu triện | 贮 là giản thể của 貯 (rút gọn 貝 thành 贝, và 宁 thành 㝉). Theo cấu trúc 貯, gồm 貝 (biểu nghĩa: của cải) và 宁 (biểu âm). Nghĩa là tích trữ, cất giấu. Dạng giáp cốt, kim văn, đại triện và tiểu triện đều có. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chứa cất", "Hạng Tần Suất (Jun Da)": "2818.0", "Tần Suất % (Jun Da)": "98.9830986352", "GavinGrover_Once (Chiết tự trực tiếp)": "贝 + 㝉", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰贝㝉", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "㝉", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "贝", "Unihan_Simplified (Chữ Giản thể)": "贮", "Unihan_Traditional (Chữ Phồn thể)": "貯", "Pinyin_Xie": "zhù", "Âm Hán Việt_Xie": "trữ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ đứng trước danh từ để chỉ hành động tích trữ hoặc lưu trữ hàng hóa, tiền của. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('觅', '{"9000": "2819.0", "Chữ Trung Quốc": "觅", "Bộ thủ & thành phần_Xie": "Bộ thủ | 爪 | Số nét | 8 | nét | 觅 | mịch | tượng hình | tìm kiếm, cào bới để tìm | 觅 = 爫 (Trảo: bàn tay cào bới) + 见 (Kiến: nhìn thấy). Chữ hội ý — dùng tay cào bới (爫) để nhìn tìm (见) thứ gì đó. Không có nguồn glyph origin từ Wiktionary.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mịch\": tay cào (爫) nhìn tìm (见) — mịch mò, tìm kiếm khắp nơi. | Gương Hán-Việt | \"mịch\" trong \"tầm mịch\" (tìm kiếm) và \"mịch mò\" (mò mẫm tìm) | Mở khoá kiến thức | Biết 觅 (mịch) mở khoá: 寻觅 (tầm mịch — tìm kiếm); 觅食 (mịch thực — kiếm ăn); 觅得 (mịch đắc — tìm được).", "Tự nguyên_Xie": "Chữ hội ý, không có anchor Wiktionary riêng. Cấu tạo: 爫 (tay cào, trảo) + 见 (nhìn thấy). Nghĩa gốc là tìm kiếm — dùng tay bới và mắt nhìn để tìm thứ đã mất. Chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tìm kiếm", "Hạng Tần Suất (Jun Da)": "2819.0", "Tần Suất % (Jun Da)": "98.9843368524", "GavinGrover_Once (Chiết tự trực tiếp)": "爫 + 见", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱爫见", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "见", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "爫", "Unihan_Simplified (Chữ Giản thể)": "觅", "Unihan_Traditional (Chữ Phồn thể)": "覓", "Pinyin_Xie": "mì", "Âm Hán Việt_Xie": "mịch", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ chỉ hành động tìm kiếm, thường kết hợp với các danh từ chỉ vật cần tìm. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('朦', '{"9000": "2820.0", "Chữ Trung Quốc": "朦", "Bộ thủ & thành phần_Xie": "Bộ thủ | 月 | Số nét | 17 | nét | 月 | nguyệt | biểu nghĩa | mặt trăng | 蒙 | mông | biểu âm | che phủ, mờ mịt | 朦 là chữ hình thanh: 月 (Nguyệt) biểu nghĩa chỉ mặt trăng (không phải thịt — 肉); 蒙 (Mông) biểu âm, đồng thời gợi ý sự mờ mịt. Đây là trường hợp hiếm: 月 trong 朦 là trăng thật, không phải bộ 肉 biến thể.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mông\": ánh trăng (月) bị che mông (蒙 mông) — trăng lu mờ ảo trong sương, tạo cảnh朦胧. | Gương Hán-Việt | mông trong 朦胧 (mông lung — mờ mịt, ảo diệu), 朦朦 (mông mông — lu mờ) | Mở khoá kiến thức | Biết 朦 mở khoá: 朦胧, 朦朦胧胧 — nhóm từ tả ánh sáng mờ ảo, cảm xúc mơ hồ.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 朦 là chữ hình thanh gồm 月 (biểu nghĩa: mặt trăng) và 蒙 (biểu âm). Khác với nhiều chữ có 月 bên trái (vốn là 肉), 朦 dùng 月 thật chỉ ánh trăng mờ ảo. Nghĩa là ánh trăng mờ, mờ mịt. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "không rõ ràng; lừa lọc", "Hạng Tần Suất (Jun Da)": "2820.0", "Tần Suất % (Jun Da)": "98.985574036", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 蒙", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月蒙", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "蒙", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "朦", "Unihan_Traditional (Chữ Phồn thể)": "朦", "Pinyin_Xie": "méng", "Âm Hán Việt_Xie": "mông", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này làm tính từ miêu tả trạng thái ánh trăng mờ ảo hoặc cảnh vật không rõ ràng. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('僻', '{"9000": "2821.0", "Chữ Trung Quốc": "僻", "Bộ thủ & thành phần_Xie": "Bộ thủ | 人 | Số nét | 15 | nét | 亻 | nhân | biểu nghĩa | người | 辟 | tích | biểu âm | mở ra, khai hoang (cho âm pì) | 僻 = 亻 (Nhân, biểu nghĩa: người) + 辟 (Tích, biểu âm). Chữ hình thanh — người ở nơi hẻo lánh, xa xôi.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tích\": người (亻) khai khẩn (辟) đất xa — sống nơi hẻo lánh, tách biệt, kỳ lạ. | Gương Hán-Việt | \"tích\" trong \"thiên tích\" (lệch lạc, kỳ quặc) | Mở khoá kiến thức | Biết 僻 (tích) mở khoá: 偏僻 (thiên tích — hẻo lánh, xa xôi); 僻静 (tích tĩnh — hiu quạnh, vắng vẻ); 僻远 (tích viễn — xa xôi hẻo lánh).", "Tự nguyên_Xie": "Chữ hình thanh. 亻 (người, biểu nghĩa) + 辟 (biểu âm). Nghĩa gốc là hẻo lánh, xa xôi — nơi người ở biệt lập, xa trung tâm. Từ đó mở rộng sang nghĩa ''kỳ quặc, lập dị''. Chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "hẹp hòi", "Hạng Tần Suất (Jun Da)": "2821.0", "Tần Suất % (Jun Da)": "98.9868096692", "GavinGrover_Once (Chiết tự trực tiếp)": "亻 + 辟", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰亻辟", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "辟", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "亻", "Unihan_Simplified (Chữ Giản thể)": "僻", "Unihan_Traditional (Chữ Phồn thể)": "僻", "Pinyin_Xie": "pì", "Âm Hán Việt_Xie": "tích", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này làm tính từ bổ nghĩa cho danh từ chỉ nơi chốn hẻo lánh hoặc tính cách con người kỳ quặc. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('隋', '{"9000": "2822.0", "Chữ Trung Quốc": "隋", "Bộ thủ & thành phần_Xie": "Bộ thủ | 阜 | Số nét | 11 | nét | 阝 | phụ | biểu nghĩa | vùng đất, đồi | 左 | tả | biểu hình | bên trái | 月 | nguyệt | biểu âm | thịt (biến thể 肉) | 隋 là chữ hình thanh: 隓 (biểu âm, abb.) kết hợp 肉 (biểu nghĩa: thịt). Theo Wiktionary, cấu trúc gốc là 隓 (biểu âm) + 肉 (biểu nghĩa). Tên nhà Tuỳ do vua Tuỳ Văn Đế tạo ra từ 隨 bằng cách rút gọn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tuỳ\": chữ do Tuỳ Văn Đế tạo từ 隨 — tên triều đại Tuỳ ngắn ngủi (581-618) nối liền Nam Bắc Triều. | Gương Hán-Việt | tuỳ trong 隋朝 (Tuỳ triều — nhà Tuỳ), 隋唐 (Tuỳ Đường — thời Tuỳ Đường) | Mở khoá kiến thức | Biết 隋 mở khoá lịch sử: 隋朝, 隋文帝, 隋炀帝, 隋唐演义.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 隋 là chữ hình thanh gồm 隓 (biểu âm, rút gọn) và 肉 (biểu nghĩa: thịt). Chữ này được Tuỳ Văn Đế tạo ra từ 隨 để đặt tên triều đại. Nghĩa gốc liên quan đến 墮 (rơi xuống) và 惰 (lười biếng). Dạng tiểu triện đã có. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1095.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Phụ (164) Tả (072) Nhục (250)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Phụ (số 164 - gò đất/ 阝), chữ Tả (số 072 - bên trái/ 𠂇) và bộ Nhục (số 250 - thịt/ 月). Giải thích sự chuyển ý: Đây là chữ Hội ý. Tùy (hoặc Đọa) là phần thịt bị thái ra, đồ thịt thừa của súc vật hoặc vật tế tự.", "Nghĩa Tiếng Việt_Xie": "đời nhà Tuỳ (Trung Quốc)", "Hạng Tần Suất (Jun Da)": "2822.0", "Tần Suất % (Jun Da)": "98.9880453025", "GavinGrover_Once (Chiết tự trực tiếp)": "阝 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰阝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "隋", "Unihan_Traditional (Chữ Phồn thể)": "隋", "Pinyin_Xie": "suí", "Âm Hán Việt_Xie": "tuỳ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ riêng để chỉ triều đại nhà Tùy trong lịch sử Trung Quốc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蔓', '{"9000": "2823.0", "Chữ Trung Quốc": "蔓", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 14 | nét | 艹 | thảo | biểu nghĩa | cỏ, thực vật | 曼 | mạn | biểu âm | dài dằng dặc (cho âm màn) | 蔓 = 艹 (Thảo, biểu nghĩa: cây cỏ) + 曼 (Mạn, biểu âm). Chữ hình thanh — cây leo dây dài.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"man\": cỏ (艹) man mán (曼) leo dài — dây leo trườn xa, lan rộng không kiểm soát. | Gương Hán-Việt | \"man\" trong \"mạn diên\" (lan rộng, trải ra) và \"man dài\" (dài mạn) | Mở khoá kiến thức | Biết 蔓 (man) mở khoá: 蔓延 (mạn diên — lan rộng, trải rộng); 蔓草 (mạn thảo — cỏ leo); 瓜蔓 (qua mạn — dây bầu/dưa).", "Tự nguyên_Xie": "Chữ hình thanh theo Wiktionary: 艹 (thảo, biểu nghĩa) + 曼 (biểu âm). Nghĩa gốc là dây leo, cây bò — loại thực vật có dây thân dài lan rộng. Từ đó có nghĩa ''lan rộng, trải dài''. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lan rộng; cây cỏ bò dưới mặt đất", "Hạng Tần Suất (Jun Da)": "2823.0", "Tần Suất % (Jun Da)": "98.989280419", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 曼", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹曼", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "曼", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "蔓", "Unihan_Traditional (Chữ Phồn thể)": "蔓", "Pinyin_Xie": "màn", "Âm Hán Việt_Xie": "man, mạn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này làm danh từ chỉ các loại dây leo hoặc làm động từ chỉ sự lan rộng, bò lan của cây cỏ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('咋', '{"9000": "2824.0", "Chữ Trung Quốc": "咋", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 8 | nét | 口 | khẩu | biểu nghĩa | miệng | 乍 | sạ | biểu âm | bỗng nhiên (cho âm zǎ/zhā/zé) | 咋 = 口 (Khẩu, biểu nghĩa: miệng) + 乍 (Sạ, biểu âm). Chữ hình thanh — tiếng kêu hoặc câu hỏi từ miệng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trách\": miệng (口) bỗng nhiên (乍) lên tiếng — hỏi ngay ''sao vậy?'', trách móc tức thì. | Gương Hán-Việt | \"trách\" trong \"trách móc\" (hỏi vặn, chê bai) | Mở khoá kiến thức | Biết 咋 (trách) mở khoá: 咋了 (trách liễu — sao vậy?); 咋回事 (trách hồi sự — chuyện gì vậy?); thường dùng trong văn nói thông tục.", "Tự nguyên_Xie": "Chữ hình thanh. 口 (miệng, biểu nghĩa) + 乍 (biểu âm). Nghĩa gốc là cắn, ngậm. Trong tiếng phổ thông hiện đại, 咋 dùng như đại từ nghi vấn thông tục ''tại sao, làm sao'' (âm zǎ). Chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tiếng động lớn", "Hạng Tần Suất (Jun Da)": "2824.0", "Tần Suất % (Jun Da)": "98.9905150187", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 乍", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口乍", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "乍", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "咋", "Unihan_Traditional (Chữ Phồn thể)": "咋", "Pinyin_Xie": "zǎ", "Âm Hán Việt_Xie": "trách, trá", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Đại từ | 代词 | Thán từ | 叹词 | Chữ này làm đại từ nghi vấn dùng trong khẩu ngữ để hỏi về cách thức hoặc nguyên nhân. | Đại từ | 代词 | Thay cho người hoặc vật đã nhắc tới (我, 这, 谁). Dùng đúng ở vị trí của danh từ. Chỉ người thì thêm 们 để thành số nhiều: 我们. | Thán từ | 叹词 | Bộc lộ cảm xúc hoặc dùng để gọi đáp: 啊, 哦, 喂. Đứng tách riêng ở đầu câu, không làm thành phần câu.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | zǎ | / | tại sao | Xuất hiện trong lộ trình | HSK | HSK 6 | · | Các từ chức năng và bổ trợ", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('嵌', '{"9000": "2825.0", "Chữ Trung Quốc": "嵌", "Bộ thủ & thành phần_Xie": "Bộ thủ | 山 | Số nét | 12 | nét | 山 | sơn | biểu nghĩa | núi, đá | 歁 | biểu âm | (rút gọn, cho âm qiàn) | 嵌 = 山 (Sơn, biểu nghĩa: núi/đá) + 歁 (biểu âm, rút gọn). Chữ hình thanh — đá núi được khảm, nhúng vào nhau chặt.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khảm\": núi (山) gắn chặt vào nền — như đá quý khảm vào kim loại, không thể tách rời. | Gương Hán-Việt | \"khảm\" trong \"khảm trai\" (khảm xà cừ) và \"khảm vào\" (gắn chặt) | Mở khoá kiến thức | Biết 嵌 (khảm) mở khoá: 镶嵌 (tương khảm — khảm, cài vào); 嵌入 (khảm nhập — nhúng vào, cài vào); 嵌套 (khảm sáo — lồng nhau).", "Tự nguyên_Xie": "Chữ hình thanh theo Wiktionary (Quảng Đông): 山 (núi, biểu nghĩa) + 歁 (biểu âm, rút gọn). Nghĩa gốc là khảm, nhúng vào, cài vào — như đá quý được gắn chặt vào nền. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lõm vào", "Hạng Tần Suất (Jun Da)": "2825.0", "Tần Suất % (Jun Da)": "98.9917485848", "GavinGrover_Once (Chiết tự trực tiếp)": "山 + 𣢟", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱山𣢟", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "𣢟", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "山", "Unihan_Simplified (Chữ Giản thể)": "嵌", "Unihan_Traditional (Chữ Phồn thể)": "嵌", "Pinyin_Xie": "qiàn", "Âm Hán Việt_Xie": "khảm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ chỉ hành động khảm, nạm hoặc gắn một vật nhỏ vào bề mặt của vật khác. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('虔', '{"9000": "2826.0", "Chữ Trung Quốc": "虔", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虍 | Số nét | 10 | nét | 虍 | hô | biểu nghĩa | hổ (đầu hổ) | 文 | văn | biểu âm | văn tự, hoa văn | 虔 là chữ hình thanh: 虍 (Hô — đầu hổ) biểu nghĩa (có thuyết cho là biểu âm theo Li Xueqin), 文 (Văn) biểu âm (theo Thuyết Văn) hoặc biểu nghĩa (theo Li Xueqin). Nghĩa là thành kính, sùng mộ. Học giới có hai ý kiến về vai trò các thành phần.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"kiền\": uy nghiêm như hổ (虍) mà vẫn văn nhã (文) — sự thành kính vừa mạnh mẽ vừa nhã nhặn. | Gương Hán-Việt | kiền trong 虔诚 (kiền thành — thành tâm, thành kính), 虔心 (kiền tâm — tâm thành) | Mở khoá kiến thức | Biết 虔 mở khoá: 虔诚, 虔心, 虔敬 — nhóm từ về lòng thành kính, đạo tâm.", "Tự nguyên_Xie": "Kim văn | Đại triện | Tiểu triện | Theo Wiktionary, 虔 là chữ hình thanh; Thuyết Văn cho 文 là biểu âm và 虍 là biểu nghĩa, trong khi Li Xueqin (2012) cho rằng 虍 mới là thành phần biểu âm. Nghĩa là thành kính, mộ đạo. Dạng kim văn, đại triện và tiểu triện đều có. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bền chặt", "Hạng Tần Suất (Jun Da)": "2826.0", "Tần Suất % (Jun Da)": "98.9929785334", "GavinGrover_Once (Chiết tự trực tiếp)": "虍 + 文", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴虍文", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "文", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虍", "Unihan_Simplified (Chữ Giản thể)": "虔", "Unihan_Traditional (Chữ Phồn thể)": "虔", "Pinyin_Xie": "qián", "Âm Hán Việt_Xie": "kiền", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này làm tính từ thể hiện thái độ thành kính, tôn nghiêm, thường kết hợp với các từ liên quan đến tâm linh. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('畔', '{"9000": "2827.0", "Chữ Trung Quốc": "畔", "Bộ thủ & thành phần_Xie": "Bộ thủ | 田 | Số nét | 10 | nét | 田 | điền | biểu nghĩa | ruộng, đồng ruộng | 半 | bán | biểu âm | nửa (cho âm pàn) | 畔 = 田 (Điền, biểu nghĩa: ruộng) + 半 (Bán, biểu âm). Chữ hình thanh — bên cạnh ruộng, bờ bãi.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bạn\": ruộng (田) chia đôi (半) — đường bờ giữa hai khoảnh ruộng, bờ bên cạnh. | Gương Hán-Việt | \"bạn\" trong \"hồ bạn\" (bên hồ) và \"bạn bè\" (người ở cạnh mình) | Mở khoá kiến thức | Biết 畔 (bạn) mở khoá: 河畔 (hà bạn — bờ sông); 湖畔 (hồ bạn — bên hồ); 田畔 (điền bạn — bờ ruộng).", "Tự nguyên_Xie": "Chữ hình thanh theo Wiktionary: 田 (ruộng, biểu nghĩa) + 半 (biểu âm). Nghĩa gốc là bờ ruộng, bên cạnh ruộng đồng. Từ đó mở rộng sang ''bờ bãi, bên cạnh'' nói chung (hồ畔, sông畔). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1164.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Điền (024) Bán (1080)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Điền (số 024 - thửa ruộng) ở bên trái chữ Bán (số 1080 - một nửa/chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Bán chỉ âm, bộ Điền chỉ ý. Bạn là ranh giới giữa các thửa ruộng, bờ ruộng. Nó cũng mang nghĩa là bờ hồ, ven bờ.", "Nghĩa Tiếng Việt_Xie": "bờ", "Hạng Tần Suất (Jun Da)": "2827.0", "Tần Suất % (Jun Da)": "98.9942074484", "GavinGrover_Once (Chiết tự trực tiếp)": "田 + 半", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰田半", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "半", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "田", "Unihan_Simplified (Chữ Giản thể)": "畔", "Unihan_Traditional (Chữ Phồn thể)": "畔", "Pinyin_Xie": "pàn", "Âm Hán Việt_Xie": "bạn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Từ chỉ phương vị | 方位词 | Chữ này thường làm danh từ chỉ phương vị đứng sau danh từ khác để chỉ bờ hoặc bên cạnh của một thực thể địa lý. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Từ chỉ phương vị | 方位词 | Chỉ vị trí và đứng SAU danh từ — 桌子上, 家里 — chứ không đứng trước như ''trên bàn'', ''trong nhà''. Thường đi cùng 在.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | pàn | / | bên | Xuất hiện trong lộ trình | HSK | HSK 6 | · | Địa điểm", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('琐', '{"9000": "2828.0", "Chữ Trung Quốc": "琐", "Bộ thủ & thành phần_Xie": "Bộ thủ | 玉 | Số nét | 11 | nét | 王 | vương | biểu nghĩa | ngọc (bộ 玉 viết liền) | 𭕆 | biểu âm | phần âm (⺌+贝) | 琐 = 王(Vương, bộ ngọc — biểu nghĩa: liên quan đến ngọc) + 𭕆 (biểu âm). Chữ hình thanh. Nguyên nghĩa: mảnh vỡ ngọc nhỏ, tiếng ngọc chạm nhau — chuyển nghĩa sang ''vụn vặt''.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"toả\": bộ 玉 (ngọc) ghép với phần âm — mảnh ngọc li ti rơi vỡ, tượng trưng cho những chuyện vụn vặt không đáng kể. | Gương Hán-Việt | toả trong ''phồn toả'' (繁瑣 — rườm rà, lôi thôi) | Mở khoá kiến thức | Biết 琐 (toả) mở khoá: 繁琐 (phồn toả — rườm rà), 琐事 (tiểu tiết), 琐碎 (vụn vặt).", "Tự nguyên_Xie": "Tiểu triện | Chữ hình thanh. Bộ 玉 (ngọc) biểu nghĩa, phần còn lại biểu âm. Trong tiểu triện thấy rõ cấu trúc ghép. Wiktionary ghi nghĩa cổ: tiếng ngọc vỡ, mảnh ngọc nhỏ — từ đó mở rộng sang ''nhỏ nhặt, vụn vặt''. Chữ 瑣 (phồn thể) là dạng gốc. Chưa có phân tích lục thư chi tiết hơn. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "vụn vặt, lặt vặt", "Hạng Tần Suất (Jun Da)": "2828.0", "Tần Suất % (Jun Da)": "98.9954358467", "GavinGrover_Once (Chiết tự trực tiếp)": "王 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰王", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "琐", "Unihan_Traditional (Chữ Phồn thể)": "瑣", "Pinyin_Xie": "suǒ", "Âm Hán Việt_Xie": "toả", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này thường làm tính từ đứng trước danh từ hoặc kết hợp tạo từ ghép để chỉ sự vụn vặt, phiền toái. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('碟', '{"9000": "2829.0", "Chữ Trung Quốc": "碟", "Bộ thủ & thành phần_Xie": "Bộ thủ | 石 | Số nét | 14 | nét | 石 | thạch | biểu nghĩa | đá, vật cứng, dẹt | 枼 | biểu âm | phần âm (世+木 — lá mỏng dẹt) | 碟 = 石(Thạch, biểu nghĩa: vật cứng dẹt) + 枼 (biểu âm). Chữ hình thanh. Gợi ý vật phẳng, dẹt như đĩa đá. Wiktionary chỉ có {{Han etym}} không có phân tích cụ thể.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"điệp\": bộ 石 (đá cứng) + phần âm 枼 (lá mỏng) — cái đĩa phẳng, cứng như đá, mỏng như lá. | Gương Hán-Việt | điệp trong ''quang điệp'' (光碟 — đĩa CD) | Mở khoá kiến thức | Biết 碟 (điệp) mở khoá: 光碟 (đĩa quang), 碟片 (đĩa nhạc/phim), 飞碟 (đĩa bay).", "Tự nguyên_Xie": "Chữ hình thanh, bộ 石 (thạch) biểu nghĩa chỉ vật cứng dẹt, phần 枼 biểu âm. Wiktionary không cung cấp phân tích nguồn gốc chi tiết cho chữ này. Từ cấu trúc suy: đĩa dẹt làm từ vật liệu cứng. Chưa có nguồn học thuật đủ chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái đĩa", "Hạng Tần Suất (Jun Da)": "2829.0", "Tần Suất % (Jun Da)": "98.9966632114", "GavinGrover_Once (Chiết tự trực tiếp)": "石 + 枼", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰石枼", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "枼", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "石", "Unihan_Simplified (Chữ Giản thể)": "碟", "Unihan_Traditional (Chữ Phồn thể)": "碟", "Pinyin_Xie": "dié", "Âm Hán Việt_Xie": "điệp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Lượng từ | 量词 | Chữ này làm danh từ chỉ cái đĩa hoặc làm lượng từ cho các món ăn đựng trong đĩa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Lượng từ | 量词 | Đứng giữa số từ (hoặc 这/那) và danh từ: 一杯茶, 这本书. Mỗi danh từ đi với lượng từ riêng; 个 là lượng từ dùng chung phổ biến nhất.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('涩', '{"9000": "2830.0", "Chữ Trung Quốc": "涩", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 10 | nét | 氵 | thuỷ | biểu nghĩa | nước | 涩 | sáp | tượng hình | cảm giác chát, sít (toàn bộ chữ tự biểu đạt) | 涩 = 氵 (Thuỷ, biểu nghĩa: nước) + 刃止 (biểu âm, rút gọn từ 歰). Dạng giản thể của 澀. Cảm giác chát, không trơn tru.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sáp\": nước (氵) mà lại sáp sít (刃止) — không trơn, không ngọt, vị chát khó chịu. | Gương Hán-Việt | \"sáp\" trong \"chất sáp\" (sáp bề mặt) và \"sáp nhập\" (gắn vào không rời) | Mở khoá kiến thức | Biết 涩 (sáp) mở khoá: 苦涩 (khổ sáp — đắng chát, khó chịu); 生涩 (sinh sáp — ngượng ngùng, chưa thành thục); 晦涩 (hối sáp — tối nghĩa, khó hiểu).", "Tự nguyên_Xie": "涩 là dạng giản thể của 澀 (rút gọn 歰 thành 刃止). Chữ gốc 澀 gốc là 歰 — hình tượng hai bàn chân đi ngược chiều nhau, gợi sự cản trở, không thuận. Thêm 水 để nhấn mạnh cảm giác chất lỏng không trơn. Nghĩa gốc là chát, sít — cảm giác khi uống trà đặc hay nước quả chưa chín. Chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "rít, ráp, sáp, không trơn tru; chát sít", "Hạng Tần Suất (Jun Da)": "2830.0", "Tần Suất % (Jun Da)": "98.9978895425", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "涩", "Unihan_Traditional (Chữ Phồn thể)": "澀", "Pinyin_Xie": "sè", "Âm Hán Việt_Xie": "sáp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này làm tính từ bổ nghĩa cho danh từ hoặc làm vị ngữ để tả vị chát, bề mặt thô ráp hoặc văn chương khúc khuỷu. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('胧', '{"9000": "2831.0", "Chữ Trung Quốc": "胧", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 9 | nét | 月 | nguyệt | biểu nghĩa | mặt trăng (không phải 肉 — Wiktionary xác nhận rõ) | 龙 | long | biểu âm | rồng — cho âm lóng | 胧 = 月(Nguyệt, biểu nghĩa: ánh trăng) + 龙/龍 (Long, biểu âm: âm lóng). Chữ hình thanh. Lưu ý: bộ 月 ở đây là trăng thật, không phải 肉 (thịt) — Wiktionary ghi rõ điều này. Dùng trong 朦胧 (mờ mịt ánh trăng).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lung\": 月 (trăng) + 龙 (rồng — âm lung) — ánh trăng mờ ảo như rồng ẩn trong sương, đó là cảm giác 朦胧. | Gương Hán-Việt | lung trong ''mông lung'' (朦胧 — mờ mịt, huyền ảo) | Mở khoá kiến thức | Biết 胧 (lung) mở khoá: 朦胧 (mông lung — mờ ảo), 朦胧诗 (thơ朦胧派).", "Tự nguyên_Xie": "Tiểu triện | Chữ hình thanh: 月 (nguyệt, biểu nghĩa — ánh trăng) + 龍 (long, biểu âm). Wiktionary xác nhận: khác với hầu hết chữ có bộ 月 bên trái (thường là biến thể của 肉), chữ 胧 dùng 月 thật chỉ trăng. 朦朧 nguyên chỉ ánh trăng mờ ảo, sau mở rộng sang mọi trạng thái mờ nhạt. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: mông lung 朦朧,曚曨,朦胧)", "Hạng Tần Suất (Jun Da)": "2831.0", "Tần Suất % (Jun Da)": "98.9991117394", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 龙", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月龙", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "龙", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "胧", "Unihan_Traditional (Chữ Phồn thể)": "朧", "Pinyin_Xie": "lóng", "Âm Hán Việt_Xie": "lung", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này chủ yếu làm tính từ trong từ ghép để miêu tả trạng thái mờ ảo, không rõ nét của ánh trăng hoặc cảnh vật. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('嘟', '{"9000": "2832.0", "Chữ Trung Quốc": "嘟", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 13 | nét | 口 | khẩu | biểu nghĩa | miệng — âm thanh | 都 | đô | biểu âm | đô — cho âm dū | 嘟 = 口(Khẩu, biểu nghĩa: miệng, tiếng kêu) + 都 (Đô, biểu âm: âm dū). Chữ hình thanh, chỉ tiếng kêu bíp/bó của còi, hoặc hành động bĩu môi. Wiktionary không có phân tích nguồn gốc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đô\": 口 (miệng) + 都 (đô, âm dū) — miệng phát ra tiếng bíp-bó của còi xe hoặc tiếng bĩu môi hờn dỗi. | Gương Hán-Việt | đô trong ''đô đô'' (嘟嘟 — bíp bíp, tiếng còi) | Mở khoá kiến thức | Biết 嘟 (đô) mở khoá: 嘟嘟 (tiếng còi), 嘟囔 (lẩm bẩm), 嘟嘴 (bĩu môi).", "Tự nguyên_Xie": "Chữ hình thanh: 口 (khẩu) biểu nghĩa chỉ âm thanh phát ra từ miệng hoặc còi; 都 biểu âm. Không có phân tích nguồn gốc trong Wiktionary. Từ cấu trúc suy: chữ mô tả âm thanh bíp-bíp hoặc tiếng bĩu môi. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tiếng kêu bí bo; bĩu môi", "Hạng Tần Suất (Jun Da)": "2832.0", "Tần Suất % (Jun Da)": "99.0003313523", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 都", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口都", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "都", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "嘟", "Unihan_Traditional (Chữ Phồn thể)": "嘟", "Pinyin_Xie": "dū", "Âm Hán Việt_Xie": "đô", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Từ tượng thanh | 象声词 | Động từ | 动词 | Chữ này thường dùng làm từ tượng thanh mô phỏng tiếng còi hoặc làm động từ chỉ hành động bĩu môi, lẩm bẩm. | Từ tượng thanh | 象声词 | Mô phỏng âm thanh: 哗哗, 汪汪. Có thể làm định ngữ, trạng ngữ hoặc đứng độc lập. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蹦', '{"9000": "2833.0", "Chữ Trung Quốc": "蹦", "Bộ thủ & thành phần_Xie": "Bộ thủ | 足 | Số nét | 18 | nét | 𧾷 | biểu nghĩa | bộ chân (足 biến thể, gồm khẩu + chỉ) | 崩 | băng | biểu âm | sụp đổ, âm gần bèng | 蹦 = 𧾷 (bộ chân, biểu nghĩa: hành động bằng chân) + 崩 (Băng, biểu âm, âm bèng gần băng); chữ hình thanh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bính\": đôi chân (𧾷) bật mạnh như tòa nhà sụp (崩 — băng) — bật lên, nảy ra. | Gương Hán-Việt | \"bính\" ít dùng độc lập; xuất hiện trong tổ hợp như 蹦跳 (nhảy múa). | Mở khoá kiến thức | Biết 蹦 (bính) giúp nhận ra nhóm chữ chỉ hành động chân: 跑, 跳, 跃, 蹦 — tất cả đều có bộ 足.", "Tự nguyên_Xie": "Theo Wiktionary, 蹦 là chữ hình thanh: bộ 足 (𧾷) biểu nghĩa hành động chân, 崩 biểu âm. Nghĩa gốc là nhảy, bật lên. Chữ xuất hiện khá muộn trong văn viết Trung Hoa cổ, chưa thấy trong giáp cốt hay kim văn. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nhảy lên; nảy ra, phát sinh ra", "Hạng Tần Suất (Jun Da)": "2833.0", "Tần Suất % (Jun Da)": "99.0015499316", "GavinGrover_Once (Chiết tự trực tiếp)": "⻊ + 崩", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰⻊崩", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "崩", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⻊", "Unihan_Simplified (Chữ Giản thể)": "蹦", "Unihan_Traditional (Chữ Phồn thể)": "蹦", "Pinyin_Xie": "bèng", "Âm Hán Việt_Xie": "bính", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ chỉ hành động nhảy lên bằng cả hai chân hoặc chuyển động nảy lên đột ngột. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | bèng | / | nhảy, nhảy lò cò | Xuất hiện trong lộ trình | HSK | HSK 6 | · | Thể thao, giải trí, sở thích | New HSK | New HSK 7-9 | · | Phong trào I", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('冢', '{"9000": "2834.0", "Chữ Trung Quốc": "冢", "Bộ thủ & thành phần_Xie": "Bộ thủ | 冖 | Số nét | 10 | nét | 冖 | mịch | biểu nghĩa | tấm vải phủ (biến thể của 勹 — bao phủ) | 豖 | súc | biểu âm | lợn bị trói — cho âm zhǒng | 冢 = 勹/冖 (Mịch, biểu nghĩa: bao phủ, vải liệm) + 豖 (Súc, biểu âm: âm zhǒng). Chữ hình thanh. Wiktionary: nguyên nghĩa là xác người được bọc trong vải liệm chôn cất — gò mả. Phần trên (冖) đơn giản hoá từ 勹.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trủng\": 冖 (vải liệm phủ lên) + 豖 (lợn — âm zhǒng) — xác được phủ vải liệm, đắp thành gò cao, đó là ngôi mộ 冢. | Gương Hán-Việt | trủng trong ''cổ trủng'' (古冢 — ngôi mộ cổ) | Mở khoá kiến thức | Biết 冢 (trủng) mở khoá: 冢墓 (mộ phần), 坟冢 (gò mả), 冢子 (con cả — nghĩa cổ).", "Tự nguyên_Xie": "Tiểu triện | Chữ hình thanh: 勹 (bao phủ, biểu nghĩa: liệm xác) + 豖 (biểu âm). Wiktionary ghi rõ: hình ảnh xác người bọc vải liệm (burial shroud). Phần trên về sau đơn giản thành 冖. Nghĩa gốc: mộ đắp cao. Nghĩa phụ: lớn nhất, đứng đầu (như ''đông cung'' — con cả). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mồ, mả đắp cao; lớn nhất, cao nhất", "Hạng Tần Suất (Jun Da)": "2834.0", "Tần Suất % (Jun Da)": "99.0027679942", "GavinGrover_Once (Chiết tự trực tiếp)": "冖 + 豖", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱冖豖", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "豖", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "冖", "Unihan_Simplified (Chữ Giản thể)": "冢", "Unihan_Traditional (Chữ Phồn thể)": "冢", "Pinyin_Xie": "zhǒng", "Âm Hán Việt_Xie": "trủng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Chữ này làm danh từ chỉ ngôi mộ cổ đắp cao hoặc làm tính từ chỉ vị trí lớn nhất, đứng đầu trong gia tộc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('浏', '{"9000": "2835.0", "Chữ Trung Quốc": "浏", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 9 | nét | 氵 | thuỷ | biểu nghĩa | nước | 刘 | lưu | biểu âm | giản thể của 劉 (gần âm liú) | 浏 là dạng giản thể của 瀏 — hình thanh: 氵 (Thuỷ, biểu nghĩa: nước) + 刘 (giản từ 劉, Lưu — biểu âm). Cấu trúc 汶+刂 trong giản thể là biến hình, nhưng vai trò biểu âm là 刘. Nghĩa gốc ''nước trong vắt'', mở rộng sang ''duyệt lướt'' trong 浏览.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lưu\": 氵 (nước) + 刘 (Lưu) — nước trong vắt chảy nhanh, đúng nghĩa ''duyệt lướt'' trong 浏览 (lướt web), 浏览器 (trình duyệt). | Gương Hán-Việt | ''lưu'' trong ''lưu loát'', ''lưu thông'' — gần nghĩa ''lướt'' trong tiếng Việt | Mở khoá kiến thức | Nắm 浏 mở khoá các từ HSK 5-7: 浏览, 浏览器.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 浏 (phồn 瀏) là hình thanh: 水/氵 (nước, biểu nghĩa) + 劉/刘 (biểu âm). Nghĩa gốc văn cổ ''nước trong, sâu'' (瀏瀏, 瀏亮). Trong tiếng Trung hiện đại chủ yếu dùng cho 浏览 (duyệt, đọc lướt) và 浏览器 (trình duyệt web). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nước trong vắt", "Hạng Tần Suất (Jun Da)": "2835.0", "Tần Suất % (Jun Da)": "99.0039850232", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 刘", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵刘", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "刘", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "浏", "Unihan_Traditional (Chữ Phồn thể)": "瀏", "Pinyin_Xie": "liú", "Âm Hán Việt_Xie": "lưu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Chữ này thường làm động từ trong từ ghép với nghĩa xem lướt qua hoặc làm tính từ tả dòng nước trong vắt. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('裔', '{"9000": "2836.0", "Chữ Trung Quốc": "裔", "Bộ thủ & thành phần_Xie": "Bộ thủ | 衣 | Số nét | 13 | nét | 衣 | y | biểu nghĩa | áo, quần áo | 冏 | quýnh | biểu âm | sáng — cho âm quýnh/duệ | 裔 = 衣 (Y, biểu nghĩa: áo) + 㕯 (biểu âm). Wiktionary ghi: {{Han compound|衣|㕯|c1=s|c2=p|t1=cloth|ls=psc}}. Bộ y chỉ áo/vải — rìa, tua vải áo ở mép; nghĩa mở rộng sang ''con cháu, hậu duệ'' (những người ở rìa/ngoài dòng chính).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"duệ\": áo (衣-Y) mép tua — rìa vải áo như con cháu ở ngoài rìa dòng họ. Duệ = hậu duệ. | Gương Hán-Việt | duệ trong ''hậu duệ'' — tiếng Việt dùng thẳng; 华裔 là người Hoa ở nước ngoài (hậu duệ người Hoa) | Mở khoá kiến thức | Biết 裔 mở khoá: 华裔 (Hoa duệ – người gốc Hoa), 后裔 (hậu duệ – con cháu), 海外华裔 (hải ngoại Hoa duệ – người Hoa kiều).", "Tự nguyên_Xie": "裔 là chữ hình thanh: 衣 (y – áo/vải) biểu nghĩa, 㕯 biểu âm. Wiktionary ghi: t1=cloth, ls=psc. Nghĩa gốc là tua/rìa vải ở mép áo. Từ đó mở rộng sang nghĩa ''con cháu, hậu duệ'' — người ở ngoài rìa dòng họ chính. Từ thông dụng: 华裔 (Hoa duệ – người gốc Hoa), 后裔 (hậu duệ – con cháu). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con cháu", "Hạng Tần Suất (Jun Da)": "2836.0", "Tần Suất % (Jun Da)": "99.0051994683", "GavinGrover_Once (Chiết tự trực tiếp)": "衣 + 冏", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱衣冏", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "冏", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "衣", "Unihan_Simplified (Chữ Giản thể)": "裔", "Unihan_Traditional (Chữ Phồn thể)": "裔", "Pinyin_Xie": "yì", "Âm Hán Việt_Xie": "duệ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ thường xuất hiện trong từ ghép để chỉ dòng dõi hậu duệ hoặc người gốc của một quốc gia. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('襟', '{"9000": "2837.0", "Chữ Trung Quốc": "襟", "Bộ thủ & thành phần_Xie": "Bộ thủ | 衣 | Số nét | 18 | nét | 衤 | y | biểu nghĩa | quần áo (biến thể của 衣) | 禁 | cầm | biểu âm | cầm/cấm — cho âm jīn | 襟 = 衤(Y, biểu nghĩa: quần áo) + 禁 (Cầm, biểu âm: âm jīn). Chữ hình thanh. Wiktionary: chỉ đường may nơi cổ áo, vạt trước — ý niệm ''cổ áo''.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khâm\": 衤 (áo) + 禁 (cầm — âm jīn) — phần áo ''kẹp chặt'' ở cổ, đó là vạt cổ áo 襟, cũng ẩn dụ tâm hung (lồng ngực rộng mở). | Gương Hán-Việt | khâm trong ''khâm phục'' — nhưng đây là chữ khác; 襟 thường trong ''hung khâm'' (胸襟 — khí phách) | Mở khoá kiến thức | Biết 襟 (khâm) mở khoá: 胸襟 (hung khâm — khí phách), 连襟 (liên khâm — anh em rể), 正襟危坐 (ngồi thẳng nghiêm túc).", "Tự nguyên_Xie": "Đại triện | Chữ hình thanh: 衣 (y, biểu nghĩa: quần áo) + 禁 (biểu âm). Wiktionary dẫn Digital Shinjigen 2017: chữ chỉ đường may của áo, chuyển sang nghĩa cổ áo, vạt trước. Từ đó mở rộng sang ''lồng ngực, tâm trạng'' (胸襟). Hình đại triện còn rõ cấu trúc 衣+禁. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cổ áo, vạt áo", "Hạng Tần Suất (Jun Da)": "2837.0", "Tần Suất % (Jun Da)": "99.0064118462", "GavinGrover_Once (Chiết tự trực tiếp)": "衤 + 禁", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰衤禁", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "禁", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "衤", "Unihan_Simplified (Chữ Giản thể)": "襟", "Unihan_Traditional (Chữ Phồn thể)": "襟", "Pinyin_Xie": "jīn", "Âm Hán Việt_Xie": "khâm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ vạt áo trước hoặc dùng theo nghĩa bóng để chỉ tấm lòng, chí hướng của con người. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('叨', '{"9000": "2838.0", "Chữ Trung Quốc": "叨", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 5 | nét | 口 | khẩu | biểu nghĩa | miệng, lời nói | 刀 | đao | biểu âm | con dao, âm dāo gần đao | 叨 = 口 (Khẩu, biểu nghĩa: miệng) + 刀 (Đao, biểu âm, âm dāo); chữ hình thanh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đao\": miệng (口) sắc như dao (刀) — cứ cắt vào tai người khác mãi, tức là lải nhải. | Gương Hán-Việt | \"đao\" ít gặp riêng lẻ; hay thấy trong 唠叨 (lao đao — lải nhải). | Mở khoá kiến thức | Biết 叨 (đao) giúp đọc ngay 唠叨 (lải nhải) và 絮叨 (nói dài dòng) — hai từ HSK 6 hay gặp.", "Tự nguyên_Xie": "Kim văn | Tiểu triện | Theo Wiktionary, 叨 là chữ hình thanh: 口 biểu nghĩa hành động miệng, 刀 biểu âm. Kim văn và tiểu triện đã ghi nhận hình dạng này. Nghĩa nguyên thủy liên quan đến nói năng lải nhải, sau mở rộng sang nghĩa \"chịu ơn\" (dùng trong thư tín lịch sự). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chịu ơn người khác", "Hạng Tần Suất (Jun Da)": "2838.0", "Tần Suất % (Jun Da)": "99.0076231905", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 刀", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口刀", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "刀", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "叨", "Unihan_Traditional (Chữ Phồn thể)": "叨", "Pinyin_Xie": "dāo", "Âm Hán Việt_Xie": "đao, thao", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ chỉ việc nói năng lải nhải hoặc dùng trong khẩu ngữ lịch sự khi nhận sự giúp đỡ, tiếp đãi. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('诀', '{"9000": "2839.0", "Chữ Trung Quốc": "诀", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 6 | nét | 讠 | biểu nghĩa | lời nói (biến thể của 言) | 夬 | quái | biểu âm | quyết/quái — cho âm jué | 诀 = 讠(biểu nghĩa: lời nói, ngôn ngữ) + 夬 (Quái, biểu âm: âm jué). Chữ hình thanh. Là dạng giản thể của 訣 (訁thay bằng 讠). Nghĩa gốc: lời từ biệt, lời truyền bí quyết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quyết\": 讠 (lời nói) + 夬 (quyết — âm jué) — lời nói quyết định, hoặc bí quyết được truyền miệng mà không ghi lại. | Gương Hán-Việt | quyết trong ''bí quyết'' (秘诀) và ''quyết biệt'' (诀别 — từ biệt vĩnh viễn) | Mở khoá kiến thức | Biết 诀 (quyết) mở khoá: 秘诀 (bí quyết), 诀别 (quyết biệt — từ biệt mãi mãi), 诀窍 (bí quyết, mẹo).", "Tự nguyên_Xie": "Tiểu triện | 诀 là giản thể của 訣, thay 訁 bằng 讠. Wiktionary dẫn sang 訣 để tra cứu. Cấu trúc hình thanh: 言/訁 (biểu nghĩa: lời nói) + 夬 (biểu âm). Nghĩa cổ: lời nói vĩnh biệt; nghĩa phái sinh: phép bí truyền, bí quyết. Chữ 夬 trong giáp cốt có nghĩa ''quyết đoán, dứt khoát'' — phù hợp với ''lời nói dứt khoát khi chia tay''. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lời chăng chối (khi đi xa, khi chết); phép bí truyền", "Hạng Tần Suất (Jun Da)": "2839.0", "Tần Suất % (Jun Da)": "99.0088329845", "GavinGrover_Once (Chiết tự trực tiếp)": "讠 + 夬", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰讠夬", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "夬", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "讠", "Unihan_Simplified (Chữ Giản thể)": "诀", "Unihan_Traditional (Chữ Phồn thể)": "訣", "Pinyin_Xie": "jué", "Âm Hán Việt_Xie": "quyết", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường dùng làm danh từ trong các từ ghép chỉ bí quyết hoặc làm động từ với nghĩa từ biệt. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('旭', '{"9000": "2840.0", "Chữ Trung Quốc": "旭", "Bộ thủ & thành phần_Xie": "Bộ thủ | 日 | Số nét | 6 | nét | 九 | cửu | biểu âm | chín — cho âm xù | 日 | nhật | biểu nghĩa | mặt trời | 旭 = 九(Cửu, biểu âm: âm xù) + 日 (Nhật, biểu nghĩa: mặt trời). Chữ hình thanh. Wiktionary: 九 là phần biểu âm (c1=p), 日 là phần biểu nghĩa (c2=s). Nghĩa: ánh sáng mặt trời mới mọc, rực rỡ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"húc\": 日 (mặt trời) + 九 (cửu, âm xù) — mặt trời lúc rạng đông, rực rỡ như ánh lửa (húc — nóng bừng). | Gương Hán-Việt | húc trong ''húc nhật'' (旭日 — mặt trời mọc) | Mở khoá kiến thức | Biết 旭 (húc) mở khoá: 旭日 (mặt trời buổi sáng), 旭日东升 (mặt trời mọc ở phương đông).", "Tự nguyên_Xie": "Đại triện | Tiểu triện | Chữ hình thanh: 九 (cửu, biểu âm) + 日 (nhật, biểu nghĩa: mặt trời). Wiktionary xác nhận cấu trúc này qua {{Han compound|九|日|c1=p|c2=s|ls=psc}}. Có hình đại triện và tiểu triện. Nghĩa gốc: mặt trời mới mọc; nghĩa mở rộng: rực rỡ, sáng ngời. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ánh sáng lúc mặt trời mới mọc", "Hạng Tần Suất (Jun Da)": "2840.0", "Tần Suất % (Jun Da)": "99.0100427785", "GavinGrover_Once (Chiết tự trực tiếp)": "九 + 日", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴九日", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "九", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "日", "Unihan_Simplified (Chữ Giản thể)": "旭", "Unihan_Traditional (Chữ Phồn thể)": "旭", "Pinyin_Xie": "xù", "Âm Hán Việt_Xie": "húc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Thường dùng làm danh từ chỉ buổi sớm hoặc tính từ mô tả sự ấm áp của bình minh. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('虾', '{"9000": "2841.0", "Chữ Trung Quốc": "虾", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 9 | nét | 虫 | trùng | biểu nghĩa | côn trùng/động vật nhỏ | 叚 | hạ | biểu âm | giả/hạ — cho âm xiā (dạng giản thể dùng 下) | 虾 = 虫(Trùng, biểu nghĩa: động vật nhỏ) + 叚 (Hạ, biểu âm: âm xiā). Chữ hình thanh. Wiktionary: {{Han compound|虫|叚|ls=psc|c1=s|c2=p}}. Con tôm được xếp vào nhóm côn trùng/động vật nhỏ trong phân loại Hán tự cổ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hà\": 虫 (động vật) + âm hà — con tôm dưới nước, cũng gọi ''hà'' trong tiếng Việt cổ (tôm hà). | Gương Hán-Việt | hà trong ''long hà'' (龙虾 — tôm hùm) và ''hà binh'' (虾兵 — quân tôm — trong truyện thần thoại) | Mở khoá kiến thức | Biết 虾 (hà) mở khoá: 龙虾 (tôm hùm), 虾仁 (thịt tôm), 对虾 (tôm he).", "Tự nguyên_Xie": "Tiểu triện | Chữ hình thanh: 虫 (trùng, biểu nghĩa: động vật nhỏ) + 叚 (biểu âm, âm gần với xiā). Wiktionary xác nhận cấu trúc psc. Tiểu triện rõ ràng. Nghĩa gốc và duy nhất: con tôm (shrimp/prawn). Trong tiếng Việt cổ, tôm cũng gọi là ''hà'' — trùng khớp với HV. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con tôm", "Hạng Tần Suất (Jun Da)": "2841.0", "Tần Suất % (Jun Da)": "99.0112510222", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 下", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫下", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "下", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "虾", "Unihan_Traditional (Chữ Phồn thể)": "蝦", "Pinyin_Xie": "xiā", "Âm Hán Việt_Xie": "hà", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Làm danh từ đứng độc lập hoặc kết hợp với các từ khác để chỉ các loại tôm cụ thể. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | xiā | / | tôm | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Động vật và côn trùng", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('簿', '{"9000": "2842.0", "Chữ Trung Quốc": "簿", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 19 | nét | 竹 | trúc | biểu nghĩa | tre — sổ sách cổ làm từ thẻ tre | 溥 | phổ | biểu âm | phổ/phổ — cho âm bù | 簿 = 竹(Trúc, biểu nghĩa: tre, vật liệu làm sổ sách cổ) + 溥 (Phổ, biểu âm: âm bù). Chữ hình thanh. Wiktionary: {{Han compound|竹|溥|ls=psc|c1=s|t1=bamboo|c2=p}}. Sổ sách thời cổ làm từ thẻ tre buộc lại.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bạ\": 竹 (tre) + 溥 (phổ, âm bù) — sổ sách làm từ thẻ tre, người Việt gọi là ''sổ bạ'' (学籍簿). | Gương Hán-Việt | bạ trong ''học bạ'' (học籍簿 — sổ học bạ) và ''sổ bạ'' (账簿 — sổ kế toán) | Mở khoá kiến thức | Biết 簿 (bạ) mở khoá: 账簿 (sổ kế toán), 名簿 (danh sách), 电话簿 (danh bạ điện thoại).", "Tự nguyên_Xie": "Chữ hình thanh: 竹 (trúc, biểu nghĩa: tre — vì sổ sách thời cổ làm từ thẻ tre) + 溥 (biểu âm, âm gần bù). Wiktionary xác nhận qua {{Han compound}}. Nghĩa gốc: sổ sách, tập ghi chép. Dạng chữ ổn định từ tiểu triện. Không có hình ảnh etymology. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sổ sách", "Hạng Tần Suất (Jun Da)": "2842.0", "Tần Suất % (Jun Da)": "99.0124566819", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 溥", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮溥", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "溥", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "簿", "Unihan_Traditional (Chữ Phồn thể)": "簿", "Pinyin_Xie": "bù", "Âm Hán Việt_Xie": "bộ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng sau các từ chỉ nội dung ghi chép để tạo thành tên loại sổ sách. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('啤', '{"9000": "2843.0", "Chữ Trung Quốc": "啤", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 11 | nét | 口 | khẩu | biểu nghĩa | bộ miệng – uống, ăn | 卑 | ti | biểu âm | gợi âm pí | 啤 = 口 (Khẩu, biểu nghĩa: miệng) + 卑 (Ti, biểu âm); chữ hình thanh hiện đại, được tạo để phiên âm chữ \"beer\" trong tiếng Anh. Dùng riêng trong 啤酒 (bia).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bia\": dùng miệng 口 uống thứ làm từ lúa 卑 – chính là bia (phiên âm \"beer\"); nên 啤 chỉ xuất hiện trong 啤酒. | Gương Hán-Việt | chữ vay mượn phiên âm; tiếng Việt cũng dùng \"bia\" cho cùng nguồn gốc \"beer\". | Mở khoá kiến thức | Nhớ 啤 mở khoá: 啤酒, 啤酒厂, 黑啤, 生啤, 扎啤.", "Tự nguyên_Xie": "啤 là chữ hình thanh (psc) gồm 口 \"miệng\" làm bộ biểu nghĩa và 卑 làm bộ biểu âm. Đây là một chữ được tạo muộn để phiên âm từ \"beer\" trong tiếng Anh – tiếng Trung gọi 啤酒 (pí jiǔ – bia). Bộ 口 nhấn mạnh hành động uống, bộ 卑 chỉ cung cấp âm. Chữ này gần như chỉ dùng trong các từ ghép liên quan đến bia (啤酒, 啤酒厂, 黑啤). | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bia", "Hạng Tần Suất (Jun Da)": "2843.0", "Tần Suất % (Jun Da)": "99.0136618248", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 卑", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口卑", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "卑", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "啤", "Unihan_Traditional (Chữ Phồn thể)": "啤", "Pinyin_Xie": "pí", "Âm Hán Việt_Xie": "ti", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường kết hợp với chữ tửu tạo thành từ ghép chỉ bia hoặc đứng trước các danh từ khác. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('擒', '{"9000": "2844.0", "Chữ Trung Quốc": "擒", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 15 | nét | 扌 | thủ | biểu nghĩa | tay — hành động bắt | 禽 | cầm | biểu âm | cầm — cho âm qín | 擒 = 扌(Thủ, biểu nghĩa: tay) + 禽 (Cầm, biểu âm: âm qín). Chữ hình thanh. Wiktionary: {{Han compound|手|alt1=扌|禽|ls=psc|c1=s|c2=p}}. Nghĩa: dùng tay bắt, tóm, bắt sống.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cầm\": 扌 (tay) + 禽 (cầm — chim/thú) — tay túm lấy con thú, bắt sống, đó là hành động 擒. | Gương Hán-Việt | cầm trong ''sinh cầm'' (生擒 — bắt sống) và ''cầm tung'' (擒纵 — bắt rồi thả) | Mở khoá kiến thức | Biết 擒 (cầm) mở khoá: 生擒 (bắt sống), 擒拿 (khống chế, bắt giữ), 欲擒故纵 (muốn bắt cố ý thả).", "Tự nguyên_Xie": "Đại triện | Chữ hình thanh: 扌/手 (thủ, biểu nghĩa: tay) + 禽 (cầm, biểu âm). Wiktionary xác nhận cấu trúc psc. Hình đại triện còn rõ. Nghĩa gốc: bắt (bằng tay). Lý thú: 禽 vừa là thành phần biểu âm vừa gợi nghĩa (cầm thú — con vật bị bắt). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bắt bớ", "Hạng Tần Suất (Jun Da)": "2844.0", "Tần Suất % (Jun Da)": "99.0148649006", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 禽", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌禽", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "禽", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "擒", "Unihan_Traditional (Chữ Phồn thể)": "擒", "Pinyin_Xie": "qín", "Âm Hán Việt_Xie": "cầm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Làm động từ làm vị ngữ trong câu, thường đi kèm với tân ngữ chỉ đối tượng bị bắt. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('枣', '{"9000": "2845.0", "Chữ Trung Quốc": "枣", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 8 | nét | 朿 | thứ | tượng hình | cây gai (gốc của 刺 — gai nhọn) | ⺀ | tượng hình | nét chấm đôi — biểu thị quả trên cây | 枣 là giản thể của 棗. Dạng gốc 棗 = 朿+朿 (hai cây gai chồng lên nhau — hội ý). Wiktionary: {{Han simp|棗|f=朿|t=⺀}} — giản thể thay cành gai dưới bằng hai chấm. Hình kim văn và đại triện cho thấy rõ hình ảnh cây táo gai.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"táo\": hai cây gai (朿+朿) — cây táo tàu đầy gai nhọn; quả nhỏ ngọt lịm dù cây trông hung dữ. | Gương Hán-Việt | táo trong ''táo tàu'' (红枣 — táo đỏ) và ''táo nhân'' (枣仁 — hạt táo) | Mở khoá kiến thức | Biết 枣 (táo) mở khoá: 红枣 (táo đỏ), 枣子 (quả táo), 枣泥 (bột/nhân táo).", "Tự nguyên_Xie": "Kim văn | Đại triện | Chữ giản thể của 棗. Dạng phồn thể 棗 là hội ý: hai chữ 朿 (cây gai) chồng lên nhau — cây táo tàu nổi tiếng có gai. Kim văn và đại triện rõ ràng. Wiktionary dẫn sang 棗 cho tra cứu đầy đủ. Chữ giản thể 枣 chỉ giữ lại 朿 trên và thêm hai chấm bên dưới. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "quả táo, cây táo", "Hạng Tần Suất (Jun Da)": "2845.0", "Tần Suất % (Jun Da)": "99.0160633254", "GavinGrover_Once (Chiết tự trực tiếp)": "朿 + ⺀", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱朿⺀", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "朿", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺀", "Unihan_Simplified (Chữ Giản thể)": "枣", "Unihan_Traditional (Chữ Phồn thể)": "棗", "Pinyin_Xie": "zǎo", "Âm Hán Việt_Xie": "táo", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Làm danh từ chỉ quả hoặc cây táo, thường kết hợp với các từ chỉ màu sắc hoặc đặc điểm. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | zǎo | / | quả chà là | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Thực phẩm II", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('嘎', '{"9000": "2846.0", "Chữ Trung Quốc": "嘎", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 14 | nét | 口 | khẩu | biểu nghĩa | miệng — âm thanh | 戛 | kiết | biểu âm | kiết/gā — cho âm gā | 嘎 = 口(Khẩu, biểu nghĩa: miệng/âm thanh) + 戛 (Kiết, biểu âm: âm gā). Chữ hình thanh. Wiktionary: {{Han compound|口|戛|ls=psc|c1=s|c2=p|t1=mouth}}. Mô tả tiếng kêu ngắn, vang như tiếng cười the thé hoặc tiếng két.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ca\": 口 (miệng) + 戛 (kiết, âm gā) — tiếng kêu ''gắt'' phát ra từ miệng, như tiếng cười the thé 嘎嘎. | Gương Hán-Việt | ca trong tiếng kêu mô phỏng âm (嘎嘎 — tiếng vịt kêu) | Mở khoá kiến thức | Biết 嘎 (ca) mở khoá: 嘎嘎 (gà/vịt kêu, tiếng cười khẽ), 嘎然 (đột ngột dừng lại), 嘎吱 (tiếng cọt kẹt).", "Tự nguyên_Xie": "Chữ hình thanh: 口 (khẩu, biểu nghĩa: âm thanh từ miệng) + 戛 (biểu âm). Wiktionary xác nhận cấu trúc psc. Nghĩa: tiếng kêu ngắn vang (như tiếng cười the thé, tiếng két). Không có hình etymology. Chữ mô phỏng âm thanh. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "két (tiếng kêu ngắn và vang)", "Hạng Tần Suất (Jun Da)": "2846.0", "Tần Suất % (Jun Da)": "99.0172555487", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 戛", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口戛", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "戛", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "嘎", "Unihan_Traditional (Chữ Phồn thể)": "嘎", "Pinyin_Xie": "gā", "Âm Hán Việt_Xie": "ca", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Từ tượng thanh | 象声词 | Tính từ | 形容词 | Thường dùng làm từ tượng thanh mô tả âm thanh sắc nhọn hoặc tính từ chỉ tính cách bướng bỉnh. | Từ tượng thanh | 象声词 | Mô phỏng âm thanh: 哗哗, 汪汪. Có thể làm định ngữ, trạng ngữ hoặc đứng độc lập. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('苑', '{"9000": "2847.0", "Chữ Trung Quốc": "苑", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 8 | nét | 艹 | thảo | biểu nghĩa | cỏ cây — vườn | 夗 | uyển | biểu âm | uyển — cho âm yuàn | 苑 = 艹(Thảo, biểu nghĩa: cỏ cây, vườn) + 夗 (Uyển, biểu âm: âm yuàn). Chữ hình thanh. Wiktionary: {{Han compound|艸|alt1=艹|夗|ls=psc|c1=s|c2=p}}. Nghĩa: vườn ngự uyển, nơi chăn nuôi và trồng trọt của hoàng gia.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"uyển\": 艹 (cỏ cây) + 夗 (uyển, âm yuàn) — khu vườn xanh tươi của hoàng gia, nơi nuôi thú và trồng hoa — vườn ngự uyển. | Gương Hán-Việt | uyển trong ''văn uyển'' (文苑 — vườn văn chương) và ''lâm uyển'' (林苑 — rừng vườn) | Mở khoá kiến thức | Biết 苑 (uyển) mở khoá: 文苑 (vườn văn), 御苑 (ngự uyển), 林苑 (rừng vườn của triều đình).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Chữ hình thanh: 艹/艸 (thảo, biểu nghĩa: cỏ cây, vườn) + 夗 (biểu âm, âm yuàn). Wiktionary xác nhận cấu trúc. Tiểu triện và hình Lục thư thông còn lưu. Nghĩa gốc: vườn thú, vườn ngự của hoàng đế. Mở rộng: trung tâm văn nghệ (như 文苑 — vườn văn chương). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "vườn hoa", "Hạng Tần Suất (Jun Da)": "2847.0", "Tần Suất % (Jun Da)": "99.0184457048", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 夗", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹夗", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "夗", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "苑", "Unihan_Traditional (Chữ Phồn thể)": "苑", "Pinyin_Xie": "yuàn", "Âm Hán Việt_Xie": "uyển", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ trong các danh từ riêng chỉ vườn hoa hoàng gia hoặc khu vực học thuật. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('牟', '{"9000": "2848.0", "Chữ Trung Quốc": "牟", "Bộ thủ & thành phần_Xie": "Bộ thủ | 牛 | Số nét | 6 | nét | 牟 | mưu | tượng hình | con bò với ký hiệu âm thanh tiếng rống | 牟 là chữ hội ý: 牛 (bò) + 厶 (ký hiệu tượng trưng tiếng rống). Wiktionary: {{liushu|i}} — con bò với ký hiệu chỉ tiếng kêu rống. Kim văn và tiểu triện còn rõ hình ảnh. Nghĩa gốc: tiếng bò rống; nghĩa mở rộng: tìm kiếm, kiếm lợi.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mưu\": 牛 (bò) + 厶 (tiếng rống) — con bò đang rống tìm đàn, như kẻ mưu cầu lợi ích — 牟利 (kiếm chác). | Gương Hán-Việt | mưu trong ''mưu lợi'' (牟利 — kiếm lợi bất chính) | Mở khoá kiến thức | Biết 牟 (mưu) mở khoá: 牟利 (mưu lợi — kiếm lợi), 牟取 (chiếm đoạt, vơ vét).", "Tự nguyên_Xie": "Kim văn | Tiểu triện | Chữ hội ý (liushu: i): 牛 (con bò) + 厶 (ký hiệu biểu thị tiếng kêu rống của bò). Wiktionary ghi rõ: ''An ox with a symbol to represent its lowing''. Kim văn cho thấy rõ cấu trúc này. Nghĩa gốc: tiếng bò rống. Nghĩa mở rộng: kiếm tìm (như con bò tìm thức ăn, sau chuyển sang kiếm lợi nhuận). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "kiếm; kiếm lấy; họ Mâu", "Hạng Tần Suất (Jun Da)": "2848.0", "Tần Suất % (Jun Da)": "99.0196337939", "GavinGrover_Once (Chiết tự trực tiếp)": "厶 + 牛", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱厶牛", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "牛", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "厶", "Unihan_Simplified (Chữ Giản thể)": "牟", "Unihan_Traditional (Chữ Phồn thể)": "牟", "Pinyin_Xie": "móu", "Âm Hán Việt_Xie": "mâu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường làm động từ trong các cụm từ chỉ việc mưu cầu lợi ích cá nhân. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('呕', '{"9000": "2849.0", "Chữ Trung Quốc": "呕", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 7 | nét | 口 | khẩu | biểu nghĩa | miệng | 区 | âu | biểu âm | khu vực, âm ōu/qū gần ǒu | 呕 = 口 (Khẩu, biểu nghĩa: miệng) + 区 (Âu, biểu âm, dạng phồn thể 區); chữ hình thanh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ẩu\": miệng (口) co rúm lại như cái hố (区) — dạ dày co thắt, ẩu ra ngoài. | Gương Hán-Việt | \"ẩu\" thấy trong 呕吐 (ẩu thổ — nôn mửa). | Mở khoá kiến thức | Biết 呕 (ẩu) mở khoá từ 呕吐 (nôn) — từ y tế quan trọng ở HSK 6.", "Tự nguyên_Xie": "Theo Wiktionary, chữ phồn thể 嘔: 口 biểu nghĩa hành động miệng, 區 biểu âm. Nghĩa gốc là nôn mửa, thổ ra, sau mở rộng sang nghĩa làm bực bội. Chữ giản thể 呕 thay 區 bằng 区. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thổ ra, hộc ra, nôn mửa", "Hạng Tần Suất (Jun Da)": "2849.0", "Tần Suất % (Jun Da)": "99.0208182654", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 区", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口区", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "区", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "呕", "Unihan_Traditional (Chữ Phồn thể)": "嘔", "Pinyin_Xie": "ǒu", "Âm Hán Việt_Xie": "ẩu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Làm động từ chỉ hành động nôn mửa, thường kết hợp với các từ chỉ máu hoặc thức ăn. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('骆', '{"9000": "2850.0", "Chữ Trung Quốc": "骆", "Bộ thủ & thành phần_Xie": "Bộ thủ | 馬 | Số nét | 9 | nét | 马 | mã | biểu nghĩa | ngựa | 各 | các | biểu âm | các — cho âm luò | 骆 = 马(Mã, biểu nghĩa: ngựa) + 各 (Các, biểu âm: âm luò). Chữ hình thanh. Wiktionary: {{Han compound|馬|各|ls=psc|c1=s|c2=p|t1=horse}}. Nghĩa gốc: ngựa trắng bờm đen; nghĩa phổ biến hiện đại: lạc đà (骆驼).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lạc\": 马 (ngựa) + 各 (các, âm luò) — con ngựa bờm đen trên lưng trắng, trông như ''dát đốm'', nay dùng chủ yếu trong 骆驼 (lạc đà). | Gương Hán-Việt | lạc trong ''lạc đà'' (骆驼 — con lạc đà) và ''Lạc Việt'' (骆越 — tộc người Việt cổ) | Mở khoá kiến thức | Biết 骆 (lạc) mở khoá: 骆驼 (lạc đà), 骆驿 (xe ngựa nối tiếp), cũng liên hệ lịch sử Lạc Việt.", "Tự nguyên_Xie": "Tiểu triện | Chữ hình thanh: 馬 (mã, biểu nghĩa: ngựa) + 各 (biểu âm, âm luò). Wiktionary xác nhận, có tiểu triện. Nghĩa gốc: ngựa trắng bờm đen — loài ngựa quý cổ đại. Nghĩa mở rộng quan trọng: dùng trong 骆驼 (lạc đà). Tên gọi Lạc Việt (người Việt cổ) cũng dùng chữ này. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ngựa trắng bờm đen", "Hạng Tần Suất (Jun Da)": "2850.0", "Tần Suất % (Jun Da)": "99.0220017033", "GavinGrover_Once (Chiết tự trực tiếp)": "马 + 各", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰马各", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "各", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "马", "Unihan_Simplified (Chữ Giản thể)": "骆", "Unihan_Traditional (Chữ Phồn thể)": "駱", "Pinyin_Xie": "luò", "Âm Hán Việt_Xie": "lạc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường kết hợp với chữ đà để tạo thành danh từ chỉ con lạc đà. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('凸', '{"9000": "2851.0", "Chữ Trung Quốc": "凸", "Bộ thủ & thành phần_Xie": "Bộ thủ | 凵 | Số nét | 5 | nét | 凸 | đột | tượng hình | hình vẽ mô phỏng vật lồi, nhô lên | 凸 là chữ tượng hình: hình dạng chữ mô phỏng trực tiếp một vật nhô lên, lồi ra — phần giữa cao hơn hai bên. Không có thành phần biểu âm hay biểu nghĩa riêng biệt.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đột\": chữ trông y như cái gì đó nhô lên đột ngột — phần giữa lồi ra, đúng nghĩa đột khởi. | Gương Hán-Việt | \"đột\" trong 突出 (đột xuất — nổi bật, nhô ra). | Mở khoá kiến thức | Biết 凸 (đột) giúp nhớ cặp đối lập 凸 (lồi) / 凹 (lõm) — cặp từ hay xuất hiện cùng nhau.", "Tự nguyên_Xie": "Theo Wiktionary, 凸 là chữ tượng hình (liushu: p — pictograph), hình vẽ mô tả vật lồi ra. Không có giáp cốt hay kim văn được ghi nhận; chữ xuất hiện khá muộn. Chưa có nguồn học thuật về giáp cốt. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lồi, nhô ra, gồ lên", "Hạng Tần Suất (Jun Da)": "2851.0", "Tần Suất % (Jun Da)": "99.0231835909", "GavinGrover_Once (Chiết tự trực tiếp)": "丄", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "Ký hiệu: mo", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "丄", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "凸", "Unihan_Traditional (Chữ Phồn thể)": "凸", "Pinyin_Xie": "tū", "Âm Hán Việt_Xie": "đột", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Chữ này thường làm tính từ đứng trước danh từ hoặc làm động từ kết hợp với bổ ngữ xu hướng để chỉ trạng thái nhô ra. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | tū | / | lồi | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Tính chất vật lý", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('熄', '{"9000": "2852.0", "Chữ Trung Quốc": "熄", "Bộ thủ & thành phần_Xie": "Bộ thủ | 火 | Số nét | 14 | nét | 火 | hoả | biểu nghĩa | lửa | 息 | tức | biểu âm | hơi thở, nghỉ ngơi — âm xī gần tức | 熄 = 火 (Hoả, biểu nghĩa: lửa) + 息 (Tức, biểu âm, âm xī); chữ hình thanh — lửa (火) tắt nghỉ (息).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tức\": lửa (火) thở hơi cuối cùng rồi tắt nghỉ (息 — tức thở) — tức là dập tắt. | Gương Hán-Việt | \"tức\" trong 熄灭 (tức diệt — dập tắt hẳn). | Mở khoá kiến thức | Biết 熄 (tức) mở khoá 熄灭, 熄火 — hai từ chỉ việc tắt lửa, tắt máy ở HSK 6.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 熄 là chữ hình thanh: 火 biểu nghĩa lửa, 息 biểu âm. Tiểu triện ghi nhận hình dạng này. Nghĩa gốc là dập tắt lửa hoặc ánh sáng; tiếng Quảng Đông còn dùng theo nghĩa tắt thiết bị điện. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1634.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Hỏa (085) Tức (1633)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Hỏa (số 085 - ngọn lửa/ 火 /chỉ ý) ở bên trái chữ Tức (số 1633 - hơi thở/ngừng/ 息 /chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh kiêm Hội ý. Chữ Tức chỉ âm, bộ Hỏa chỉ ý. Tức là làm cho ngọn lửa dừng cháy, ngừng thở, dập tắt đi (tức hỏa, dập tức).", "Nghĩa Tiếng Việt_Xie": "dập lửa, tắt lửa", "Hạng Tần Suất (Jun Da)": "2852.0", "Tần Suất % (Jun Da)": "99.0243639282", "GavinGrover_Once (Chiết tự trực tiếp)": "火 + 息", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰火息", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "息", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "火", "Unihan_Simplified (Chữ Giản thể)": "熄", "Unihan_Traditional (Chữ Phồn thể)": "熄", "Pinyin_Xie": "xī", "Âm Hán Việt_Xie": "tức", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này thường làm động từ đứng trước danh từ chỉ nguồn sáng hoặc nguồn lửa để biểu thị hành động dập tắt. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('兀', '{"9000": "2853.0", "Chữ Trung Quốc": "兀", "Bộ thủ & thành phần_Xie": "Bộ thủ | 儿 | Số nét | 3 | nét | 兀 | ngột | tượng hình | người không đầu hoặc bị chặt chân — hình người với một nét trên đầu | 兀 là chữ tượng hình độc lập. Cấu trúc: 儿 (người) với một nét ngang — biểu thị người bị chặt chân (hình phạt cổ đại) hoặc hình ảnh cao và bằng đầu (như mặt đất phẳng). Kim văn và tiểu triện còn rõ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ngột\": 儿 (người) với nét chặt bên trên — người bị chặt (ngột ngạt, ngột lên), hoặc tảng đá cao chót vót, đứng chơ vơ giữa trời. | Gương Hán-Việt | ngột trong ''ngột lập'' (兀立 — đứng chơ vơ) và ''đột ngột'' (突兀 — bất ngờ) | Mở khoá kiến thức | Biết 兀 (ngột) mở khoá: 突兀 (đột ngột, chơ vơ), 兀自 (vẫn cứ — phương ngữ cổ), 兀立 (đứng sừng sững).", "Tự nguyên_Xie": "Kim văn | Tiểu triện | Chữ tượng hình. Wiktionary chỉ có {{Han etym}} không có phân tích chi tiết. Từ cấu trúc: 儿 (người) + nét ngang trên đầu — có thể chỉ người bị chặt chân (刖刑 — hình phạt cổ), hoặc hình ảnh vật thể cao bằng phẳng. Nghĩa gốc: cắt chân; nghĩa mở rộng: cao mà bằng đỉnh, nhô lên. Chưa có nguồn học thuật chi tiết hơn. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1029.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Nhất (001) Nhân (019)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Nét Nhất (số 001 - một) ở trên bộ Nhân (số 019 - người đi/ 儿). Giải thích sự chuyển ý: Đây là chữ Hội ý. Ngột là cao mà bằng phẳng ở trên đỉnh đầu.", "Nghĩa Tiếng Việt_Xie": "cao mà bằng đầu", "Hạng Tần Suất (Jun Da)": "2853.0", "Tần Suất % (Jun Da)": "99.0255437487", "GavinGrover_Once (Chiết tự trực tiếp)": "一 + 儿", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱一儿", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "儿", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "一", "Unihan_Simplified (Chữ Giản thể)": "兀", "Unihan_Traditional (Chữ Phồn thể)": "兀", "Pinyin_Xie": "wù", "Âm Hán Việt_Xie": "ngột, ô", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Phó từ | 副词 | Chữ này thường làm tính từ miêu tả trạng thái trơ trọi hoặc làm phó từ đứng trước động từ để biểu thị sự đột ngột. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Phó từ | 副词 | Bổ nghĩa cho động từ hoặc tính từ và luôn đứng TRƯỚC chúng — 都是, 很好. Không đứng sau như tiếng Việt và không bổ nghĩa cho danh từ.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('喔', '{"9000": "2854.0", "Chữ Trung Quốc": "喔", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 12 | nét | 口 | khẩu | biểu nghĩa | miệng — âm thanh | 屋 | ốc | biểu âm | ốc — cho âm ō/wō | 喔 = 口(Khẩu, biểu nghĩa: miệng, âm thanh) + 屋 (Ốc, biểu âm: âm ō). Chữ hình thanh. Wiktionary: {{Han compound|口|屋|c1=s|c2=p|t1=mouth|ls=psc}}. Chữ mô phỏng âm thanh: tiếng gà gáy hoặc tiếng thán từ ''ồ/ờ''.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ô\": 口 (miệng) + 屋 (ốc, âm ō) — miệng phát tiếng ''ồ!'' khi ngạc nhiên hoặc tiếng gà gáy ó-ó-o. | Gương Hán-Việt | ô trong ''y ốc'' (咿喔 — tiếng gà gáy) | Mở khoá kiến thức | Biết 喔 (ô) mở khoá: 咿喔 (tiếng gà gáy), dùng như thán từ 喔 (ồ, ờ — biểu đạt hiểu ra).", "Tự nguyên_Xie": "Tiểu triện | Chữ hình thanh: 口 (khẩu, biểu nghĩa: âm thanh từ miệng) + 屋 (biểu âm, âm ō). Wiktionary xác nhận cấu trúc psc. Tiểu triện còn lưu. Chữ mô phỏng âm thanh: tiếng gà gáy (咿喔), hoặc thán từ thể hiện sự hiểu/ngạc nhiên nhẹ. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "752.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Khẩu (012) Ốc (751)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Khẩu (số 012 - miệng) ở bên trái chữ Ốc (số 751 - ngôi nhà/chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Ốc chỉ âm, bộ Khẩu chỉ ý. Ác là tiếng gà kêu cục ta cục tác.", "Nghĩa Tiếng Việt_Xie": "ờ (thán từ); (xem: y ốc 咿喔)", "Hạng Tần Suất (Jun Da)": "2854.0", "Tần Suất % (Jun Da)": "99.0267199516", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 屋", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口屋", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "屋", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "喔", "Unihan_Traditional (Chữ Phồn thể)": "喔", "Pinyin_Xie": "ō", "Âm Hán Việt_Xie": "ác, ốc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Thán từ | 叹词 | Trợ từ | 助词 | Chữ này thường đứng đầu câu làm thán từ biểu thị sự hiểu ra hoặc đứng cuối câu làm trợ từ ngữ khí. | Thán từ | 叹词 | Bộc lộ cảm xúc hoặc dùng để gọi đáp: 啊, 哦, 喂. Đứng tách riêng ở đầu câu, không làm thành phần câu. | Trợ từ | 助词 | Không mang nghĩa riêng, gắn vào câu để đánh dấu ngữ pháp hoặc ngữ khí: 的 / 地 / 得 (kết cấu), 了 / 着 / 过 (thể), 吗 / 呢 / 吧 (nghi vấn, ngữ khí).", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('裳', '{"9000": "2855.0", "Chữ Trung Quốc": "裳", "Bộ thủ & thành phần_Xie": "Bộ thủ | 衣 | Số nét | 14 | nét | 尚 | thượng | biểu âm | còn, vẫn; cao quý — âm shang/cháng gần thường | 衣 | y | biểu nghĩa | áo, quần áo | 裳 = 尚 (Thượng, biểu âm) + 衣 (Y, biểu nghĩa: y phục); chữ hình thanh. Phần trên 𫩠 là biến thể viết của 尚. Nghĩa gốc là chiếc váy (loại y phục mặc phần dưới cơ thể trong Trung Hoa cổ đại).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thường\": áo (衣) mang vẻ thượng lưu (尚) — chiếc thường phục đẹp của người xưa. | Gương Hán-Việt | \"thường\" trong 衣裳 (y thường — quần áo); 霓裳 (nghê thường — áo vũ tiên). | Mở khoá kiến thức | Biết 裳 (thường) mở khoá 衣裳 (quần áo) — từ HSK 6 hay xuất hiện trong văn học và hội thoại lịch sự.", "Tự nguyên_Xie": "Bạch thư | Tiểu triện | Theo Wiktionary, 裳 là chữ hình thanh: 衣 biểu nghĩa y phục, 尚 biểu âm (phát âm cháng/shāng). Bạch thư và tiểu triện ghi nhận chữ này. Nghĩa gốc là loại váy dài mặc phần dưới thời cổ đại Trung Hoa, khác với áo trên. Sau thu hẹp vào từ 衣裳 chỉ quần áo nói chung. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "478.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Y (295) Thượng (338)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Thượng (ưa chuộng, coi trọng) ở trên chữ Y (áo quần) . Trang phục quần áo (Y) mà mọi người đều thích mặc, ưa chuộng (Thượng) từ thời xưa gọi là y thường (quần áo). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Thượng (coi trọng) chỉ âm, chữ Y (quần áo) chỉ ý. Trang phục quần áo (Y) mặc phổ biến ở phần thân dưới như quần, váy (Thường). *(Biến âm Hán Việt: Thượng -> Thường)*", "Nghĩa Tiếng Việt_Xie": "áo xiêm", "Hạng Tần Suất (Jun Da)": "2855.0", "Tần Suất % (Jun Da)": "99.027895121", "GavinGrover_Once (Chiết tự trực tiếp)": "No glyph available + 衣", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱衣", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "裳", "Unihan_Traditional (Chữ Phồn thể)": "裳", "Pinyin_Xie": "shang", "Âm Hán Việt_Xie": "thường", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này thường kết hợp với chữ y để tạo thành danh từ ghép chỉ quần áo nói chung. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('凹', '{"9000": "2856.0", "Chữ Trung Quốc": "凹", "Bộ thủ & thành phần_Xie": "Bộ thủ | 凵 | Số nét | 5 | nét | 凹 | ao | tượng hình | hình vẽ mô phỏng vật lõm vào, trũng xuống | 凹 là chữ tượng hình: hình dạng chữ mô phỏng trực tiếp một vật lõm vào — phần giữa thấp hơn hai bên. Không có thành phần biểu âm hay biểu nghĩa riêng biệt.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ao\": chữ trông y như cái ao — phần giữa trũng xuống, nước đọng lại, đúng nghĩa lõm vào. | Gương Hán-Việt | \"ao\" ít thấy trong từ ghép Hán-Việt; hay xuất hiện trong cặp 凹凸 (ao đột — lồi lõm). | Mở khoá kiến thức | Biết 凹 (ao) giúp nắm cặp đối lập 凸/凹 (lồi/lõm) — cặp từ cơ bản khi mô tả địa hình hay bề mặt.", "Tự nguyên_Xie": "Theo Wiktionary, 凹 là chữ tượng hình (liushu: p — pictograph), hình vẽ mô tả vật lõm xuống. Không có giáp cốt hay kim văn được ghi nhận; chưa có nguồn học thuật về giai đoạn cổ. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lõm vào", "Hạng Tần Suất (Jun Da)": "2856.0", "Tần Suất % (Jun Da)": "99.0290697736", "GavinGrover_Once (Chiết tự trực tiếp)": "凵", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "Ký hiệu: mo", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "凵", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "凹", "Unihan_Traditional (Chữ Phồn thể)": "凹", "Pinyin_Xie": "āo", "Âm Hán Việt_Xie": "ao", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Chữ này thường làm tính từ bổ nghĩa cho danh từ hoặc làm động từ chỉ trạng thái lõm xuống của bề mặt. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | āo | / | lõm | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Tính chất vật lý", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('赎', '{"9000": "2857.0", "Chữ Trung Quốc": "赎", "Bộ thủ & thành phần_Xie": "Bộ thủ | 貝 | Số nét | 12 | nét | 贝 | bối | biểu nghĩa | vỏ sò — tiền bạc, tài sản | 卖 | mại | biểu âm | mại (dạng hiển thị) — biểu âm gốc là 𧷏, sau thành giống 賣 | 赎 = 贝(Bối, biểu nghĩa: tiền bạc) + phần biểu âm (nguyên là 𧷏, sau biến thành dạng giống 賣/卖). Chữ hình thanh. Wiktionary ghi chú: ''phonetic was originally 𧷏 and has later become graphically similar to the unrelated 賣''. Nghĩa: dùng tiền chuộc lại.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chuộc\": 贝 (tiền) + phần âm — dùng tiền (bối) để ''mua lại'' (trông giống mại) thứ đã mất, đó là hành động chuộc. | Gương Hán-Việt | chuộc trong ''chuộc tội'' (赎罪) và ''chuộc lại'' (赎回) | Mở khoá kiến thức | Biết 赎 (chuộc) mở khoá: 赎罪 (chuộc tội), 赎回 (chuộc lại), 赎金 (tiền chuộc).", "Tự nguyên_Xie": "Đại triện | Tiểu triện | Chữ hình thanh: 貝 (bối, biểu nghĩa: tiền/tài sản) + phần biểu âm. Wiktionary cẩn thận ghi: phần biểu âm gốc là 𧷏 (không liên quan đến 賣/mại), nhưng qua thời gian biến dạng trông giống 賣. Đây là trường hợp biến dạng hình thức đáng chú ý. Hình đại triện và tiểu triện còn lưu. Nghĩa: dùng tiền chuộc vật/người về. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lấy tiền chuộc đồ", "Hạng Tần Suất (Jun Da)": "2857.0", "Tần Suất % (Jun Da)": "99.0302433927", "GavinGrover_Once (Chiết tự trực tiếp)": "贝 + 卖", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰贝卖", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "卖", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "贝", "Unihan_Simplified (Chữ Giản thể)": "赎", "Unihan_Traditional (Chữ Phồn thể)": "贖", "Pinyin_Xie": "shú", "Âm Hán Việt_Xie": "thục", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ mang tân ngữ chỉ đồ vật bị cầm cố hoặc tội lỗi cần sửa chữa. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | shú | / | chuộc lại | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Thương mại và kinh doanh II", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('屯', '{"9000": "2858.0", "Chữ Trung Quốc": "屯", "Bộ thủ & thành phần_Xie": "Bộ thủ | 屮 | Số nét | 4 | nét | 屯 | đồn | tượng hình | mầm cây đang nhú lên khỏi mặt đất — hình tượng trưng | 屯 là chữ tượng hình: hình một mầm cây (芚) đang nảy mầm, phình to ở dưới chưa thoát khỏi đất. Wiktionary: {{liushu|p}} — mầm cây phình to đang trồi lên. Kim văn, bạch thư và tiểu triện đều còn. Nghĩa mở rộng: đóng quân, tụ tập (như cây mọc tập trung).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đồn\": hình mầm cây phình dưới đất — quân lính tụ lại thành đồn như mầm cây tập trung dưới đất trước khi bung lên. | Gương Hán-Việt | đồn trong ''đồn điền'' (屯田 — quân điền, ruộng đồn) và ''tích đồn'' (屯积 — tích trữ) | Mở khoá kiến thức | Biết 屯 (đồn) mở khoá: 屯田 (đồn điền), 屯积 (tích trữ), 屯兵 (đóng quân).", "Tự nguyên_Xie": "Kim văn | Bạch thư | Tiểu triện | Chữ tượng hình: hình mầm cây phình to đang trồi lên khỏi đất — dạng gốc của 芚. Wiktionary: ''a swollen sprout or bud beginning to emerge''. Kim văn rõ ràng. Nghĩa gốc: mầm cây nảy; nghĩa mở rộng: đồn trú (quân đóng tập trung như mầm tụ lại), làng xóm (tụ cư). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "270.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Nhất (1) Triệt (269)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Nhất (số 1) ở trên chữ Triệt (số 269) . Cỏ non (triệt) bị vật (nhất) chặn trên nên phần thân bị quặn sang bên, chỉ sự khó khăn, gian truân.", "Nghĩa Tiếng Việt_Xie": "đồn bốt; đống đất", "Hạng Tần Suất (Jun Da)": "2858.0", "Tần Suất % (Jun Da)": "99.0314154614", "GavinGrover_Once (Chiết tự trực tiếp)": "十 + 𡳾", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱十𡳾", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "𡳾", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "十", "Unihan_Simplified (Chữ Giản thể)": "屯", "Unihan_Traditional (Chữ Phồn thể)": "屯", "Pinyin_Xie": "tún", "Âm Hán Việt_Xie": "đồn, truân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chữ này thường làm động từ mang tân ngữ chỉ lương thực, binh lính hoặc làm danh từ chỉ thôn xóm, đồn trại. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | tún | / | tích trữ | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Words II", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('膛', '{"9000": "2859.0", "Chữ Trung Quốc": "膛", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 15 | nét | 月 | nguyệt | biểu nghĩa | bộ nhục (月) chỉ thân thể, cơ thể | 堂 | đường | biểu âm | sảnh đường, âm táng gần thang | 膛 = 月 (bộ nhục, Nguyệt — biểu nghĩa: cơ thể) + 堂 (Đường, biểu âm, âm táng); chữ hình thanh. Chữ xuất hiện muộn trong 玉篇 thời hậu cổ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thang\": cái khoang rỗng (月/nhục) trong cái sảnh đường (堂) to rộng — ngực người như một đại sảnh bên trong cơ thể. | Gương Hán-Việt | \"thang\" trong 胸膛 (hung thang — lồng ngực). | Mở khoá kiến thức | Biết 膛 (thang) mở khoá 胸膛 (ngực) và các từ chỉ khoang rỗng như 炉膛 (lò), 枪膛 (nòng súng).", "Tự nguyên_Xie": "Theo Wiktionary, 膛 là chữ hình thanh hậu kỳ: bộ 肉 (月) biểu nghĩa thân thể, 堂 biểu âm. Chữ xuất hiện lần đầu trong từ điển 玉篇, không thấy trong giáp cốt hay kim văn. Nghĩa là khoang rỗng trong cơ thể (ngực) hoặc khoang rỗng của đồ vật (nòng súng, lò). | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ngực; chỗ trống rỗng", "Hạng Tần Suất (Jun Da)": "2859.0", "Tần Suất % (Jun Da)": "99.0325864965", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 堂", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月堂", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "堂", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "膛", "Unihan_Traditional (Chữ Phồn thể)": "膛", "Pinyin_Xie": "táng", "Âm Hán Việt_Xie": "thang", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ các bộ phận có khoang rỗng bên trong cơ thể hoặc đồ vật. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('浇', '{"9000": "2860.0", "Chữ Trung Quốc": "浇", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 9 | nét | 氵 | thuỷ | biểu nghĩa | nước | 尧 | nghiêu | biểu âm | vua Nghiêu — cho âm nghiêu/kiêu | 浇 = 氵(Thuỷ, biểu nghĩa: nước) + 尧 (Nghiêu, biểu âm). Wiktionary ghi đây là chữ giản thể của 澆 (giản 堯 thành 尧). Hình thanh: bộ thủy chỉ nước; 尧 cho âm jiāo (gần kiêu). Tưới là đổ nước lên.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"kiêu\": nước (氵-Thuỷ) vua Nghiêu (尧-Nghiêu) — vua Nghiêu tưới nước ban phát — 浇水 (tưới nước). Kiêu = tưới. | Gương Hán-Việt | kiêu trong ''kiêu ngạo'' — cùng âm; 浇 là tưới nước, không liên quan kiêu ngạo | Mở khoá kiến thức | Biết 浇 mở khoá: 浇水 (kiêu thuỷ – tưới nước), 浇灌 (kiêu quán – tưới tiêu), 浇筑 (kiêu trúc – đổ bê tông).", "Tự nguyên_Xie": "浇 là chữ giản thể của 澆. Wiktionary ghi: {{Han simp|澆|f=堯|t=尧}}. Chữ truyền thống 澆 = 氵+ 堯, là chữ hình thanh: 氵(thuỷ – nước) biểu nghĩa, 堯 (nghiêu) biểu âm. Nghĩa là tưới, đổ nước lên. Không có glyphOrigin chi tiết hơn. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bạc, mỏng; tưới", "Hạng Tần Suất (Jun Da)": "2860.0", "Tần Suất % (Jun Da)": "99.0337570148", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 尧", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵尧", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "尧", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "浇", "Unihan_Traditional (Chữ Phồn thể)": "澆", "Pinyin_Xie": "jiāo", "Âm Hán Việt_Xie": "kiêu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Chữ này chủ yếu làm động từ mang tân ngữ chỉ cây cối hoặc khuôn đúc để biểu thị hành động tưới, đổ chất lỏng. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | Từ đơn | Từ vựng HSK 5: tưới | / | jiāo | / | tưới | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Nông nghiệp | HSK | HSK 5 | · | Ngôi nhà và cuộc sống hàng ngày", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('灼', '{"9000": "2861.0", "Chữ Trung Quốc": "灼", "Bộ thủ & thành phần_Xie": "Bộ thủ | 火 | Số nét | 7 | nét | 火 | hoả | biểu nghĩa | lửa | 勺 | thược | biểu âm | thược/chước — cho âm zhuó | 灼 = 火(Hoả, biểu nghĩa: lửa) + 勺 (Thược, biểu âm: âm zhuó). Chữ hình thanh. Wiktionary: {{Han compound|火|勺|c1=s|c2=p|t1=fire|ls=psc}}. Nghĩa: đốt cháy, nướng; ánh sáng rực rỡ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chước\": 火 (lửa) + 勺 (thược — cái môi, như múc lửa lên) — múc lửa đổ lên, đốt cháy bỏng da — 灼热 (nóng bỏng). | Gương Hán-Việt | chước trong ''chước nhiệt'' (灼热 — nóng bỏng) và ''chước kiến'' (灼见 — nhận định sắc bén) | Mở khoá kiến thức | Biết 灼 (chước) mở khoá: 灼热 (nóng bỏng), 灼见 (nhận định sắc bén), 灼伤 (bỏng lửa).", "Tự nguyên_Xie": "Bạch thư | Tiểu triện | Chữ hình thanh: 火 (hoả, biểu nghĩa: lửa) + 勺 (thược, biểu âm). Wiktionary xác nhận. Bạch thư và tiểu triện còn lưu. Nghĩa gốc: đốt, nướng bằng lửa. Nghĩa mở rộng: sáng rực, nóng bỏng (灼热 — nóng bỏng như lửa). Cũng dùng trong y học cổ: cứu (đốt ngải cứu trị bệnh). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1566.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Hỏa (085) Thược (199)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Hỏa (số 085 - ngọn lửa/ 火 /chỉ ý) ở bên trái chữ Thược (số 199 - cái thìa/ 勺 /chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Thược chỉ âm, bộ Hỏa chỉ ý. Chước là dùng lửa để nướng, đốt. Từ đó chỉ sự sáng rực rỡ, chiếu sáng rõ ràng, hiển nhiên (chói chước).", "Nghĩa Tiếng Việt_Xie": "đốt, nướng", "Hạng Tần Suất (Jun Da)": "2861.0", "Tần Suất % (Jun Da)": "99.0349259828", "GavinGrover_Once (Chiết tự trực tiếp)": "火 + 勺", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰火勺", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "勺", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "火", "Unihan_Simplified (Chữ Giản thể)": "灼", "Unihan_Traditional (Chữ Phồn thể)": "灼", "Pinyin_Xie": "zhuó", "Âm Hán Việt_Xie": "chước", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Chữ này thường làm động từ chỉ sự thiêu đốt hoặc làm tính từ bổ nghĩa cho danh từ để chỉ sự nóng bỏng, sáng rõ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('裘', '{"9000": "2862.0", "Chữ Trung Quốc": "裘", "Bộ thủ & thành phần_Xie": "Bộ thủ | 衣 | Số nét | 13 | nét | 求 | cầu | biểu âm | cầu — cho âm qiú | 衣 | y | biểu nghĩa | quần áo | 裘 = 求(Cầu, biểu âm: âm qiú) + 衣 (Y, biểu nghĩa: quần áo). Chữ hình thanh. Wiktionary: {{Han compound|求|衣|c1=p|c2=s|t2=clothes|ls=psc}} — lưu ý 求 là biểu âm (c1=p), 衣 là biểu nghĩa (c2=s). Giáp cốt văn còn lưu hình ảnh cổ nhất.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cừu\": 衣 (áo) + 求 (cầu, âm qiú) — áo lông thú quý giá, người ta phải ''cầu'' mà có — tấm áo cừu lông ấm áp. | Gương Hán-Việt | cừu trong ''cừu y'' (裘衣 — áo lông thú) — lưu ý khác với 仇 (thù) | Mở khoá kiến thức | Biết 裘 (cừu) mở khoá: 裘皮 (da lông thú), 轻裘 (áo lông nhẹ — chỉ người phú quý).", "Tự nguyên_Xie": "Giáp cốt văn | Chữ hình thanh: 求 (cầu, biểu âm) + 衣 (y, biểu nghĩa: quần áo). Wiktionary xác nhận, trong đó 求 là phonetic và 衣 là semantic — thứ tự ngược với trực giác thông thường. Giáp cốt văn có hình ảnh cổ nhất. Nghĩa gốc và duy nhất: áo lông thú — loại áo quý thời cổ đại. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "áo lông cừu", "Hạng Tần Suất (Jun Da)": "2862.0", "Tần Suất % (Jun Da)": "99.0360949508", "GavinGrover_Once (Chiết tự trực tiếp)": "求 + 衣", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱求衣", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "求", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "衣", "Unihan_Simplified (Chữ Giản thể)": "裘", "Unihan_Traditional (Chữ Phồn thể)": "裘", "Pinyin_Xie": "qiú", "Âm Hán Việt_Xie": "cừu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ đứng sau các từ chỉ chất liệu lông thú để chỉ loại áo khoác ấm áp. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('砰', '{"9000": "2863.0", "Chữ Trung Quốc": "砰", "Bộ thủ & thành phần_Xie": "Bộ thủ | 石 | Số nét | 10 | nét | 石 | thạch | biểu nghĩa | đá — vật cứng va đập | 平 | bình | biểu âm | bình — cho âm pēng | 砰 = 石(Thạch, biểu nghĩa: đá, vật cứng) + 平 (Bình, biểu âm: âm pēng). Chữ hình thanh mô phỏng âm. Wiktionary: onomatopoeia — tiếng va đập mạnh (bang, thump). Không có hình etymology.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phanh\": 石 (đá) + 平 (bình, âm pēng) — viên đá ném mạnh xuống đất tạo tiếng ''phanh!'' — bùm, đùng, phịch. | Gương Hán-Việt | phanh trong từ mô phỏng âm 砰砰 — tiếng tim đập mạnh hoặc tiếng nổ | Mở khoá kiến thức | Biết 砰 (phanh) mở khoá: 砰砰 (tiếng đập mạnh), 砰然 (tiếng bùng lớn).", "Tự nguyên_Xie": "Chữ hình thanh: 石 (thạch, biểu nghĩa: tiếng đá va đập) + 平 (biểu âm). Wiktionary xác nhận đây là chữ mô phỏng âm thanh (onomatopoeia): tiếng vật cứng đập vào nhau hoặc nổ bùng. Nghĩa gốc và hiện tại: tiếng động mạnh, đột ngột. Chưa có nguồn học thuật chi tiết. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bịch, phịch, uỵch, đùng, đốp, đoàng, bùng, bốp (tiếng động)", "Hạng Tần Suất (Jun Da)": "2863.0", "Tần Suất % (Jun Da)": "99.0372634019", "GavinGrover_Once (Chiết tự trực tiếp)": "石 + 平", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰石平", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "平", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "石", "Unihan_Simplified (Chữ Giản thể)": "砰", "Unihan_Traditional (Chữ Phồn thể)": "砰", "Pinyin_Xie": "pēng", "Âm Hán Việt_Xie": "phanh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Từ tượng thanh | 象声词 | Chữ này thường dùng làm từ tượng thanh mô tả tiếng va chạm mạnh hoặc tiếng súng nổ. | Từ tượng thanh | 象声词 | Mô phỏng âm thanh: 哗哗, 汪汪. Có thể làm định ngữ, trạng ngữ hoặc đứng độc lập.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('棘', '{"9000": "2864.0", "Chữ Trung Quốc": "棘", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 12 | nét | 朿 | thứ | tượng hình | cây gai (thành phần trái) | 朿 | thứ | tượng hình | cây gai (thành phần phải) | 棘 = 朿 + 朿 (hai chữ gai ghép lại — hội ý). Hai cây gai (朿) đứng cạnh nhau biểu thị bụi gai dày, cây táo gai nhỏ (khác với 枣 là táo tàu). Wiktionary chỉ có {{Han etym}} không phân tích chi tiết, nhưng giáp cốt văn và kim văn rõ ràng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cức\": hai chữ 朿 (gai) sát nhau — bụi gai dày đặc, sờ vào đâu cũng bị đâm. 棘手 nghĩa đen: tay dính gai — việc khó. | Gương Hán-Việt | cức trong ''kinh cức'' (荆棘 — bụi gai) và ''cức thủ'' (棘手 — khó giải quyết) | Mở khoá kiến thức | Biết 棘 (cức) mở khoá: 棘手 (khó giải quyết), 荆棘 (bụi gai chông gai), 棘刺 (gai nhọn).", "Tự nguyên_Xie": "Giáp cốt văn | Kim văn | Chữ hội ý: hai chữ 朿 (cây gai) ghép lại. Giáp cốt văn và kim văn còn hình ảnh cổ. Wiktionary không cung cấp phân tích lục thư cụ thể cho chữ này. Từ cấu trúc suy: hai cây gai tượng trưng cho bụi gai dày. Nghĩa gốc: cây gai nhỏ (táo gai nhỏ — khác với 棗 táo tàu). Nghĩa mở rộng: gai góc, khó khăn (棘手 — gai tay, nghĩa: khó giải quyết). | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cây gai", "Hạng Tần Suất (Jun Da)": "2864.0", "Tần Suất % (Jun Da)": "99.0384292692", "GavinGrover_Once (Chiết tự trực tiếp)": "朿", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴朿", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "棘", "Unihan_Traditional (Chữ Phồn thể)": "棘", "Pinyin_Xie": "jí", "Âm Hán Việt_Xie": "cức", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Chữ này thường làm danh từ chỉ cây gai hoặc làm tính từ trong các từ ghép chỉ sự khó khăn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('橡', '{"9000": "2865.0", "Chữ Trung Quốc": "橡", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 15 | nét | 木 | mộc | biểu nghĩa | cây | 象 | tượng | biểu âm | gợi âm xiàng | 橡 = 木 (Mộc: cây) + 象 (Tượng, biểu âm); chữ hình thanh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tượng\": cây 木 to như con voi 象 — cây cao to, đó là ''tượng'' (cây sồi, cao su). | Gương Hán-Việt | tượng trong \"tượng thụ\" 橡樹, \"tượng giao\" 橡膠 (cao su) | Mở khoá kiến thức | Biết 橡 mở khoá nhóm từ về cây sồi và cao su: 橡皮, 橡胶, 橡树.", "Tự nguyên_Xie": "Wiktionary ghi ''Han etym'' đơn giản. Phân tích: 木 (cây) cho nghĩa ''một loài cây'', 象 cho âm xiàng. Nghĩa: cây sồi, cây hạt dẻ; hiện đại còn dùng cho cao su (橡胶 = cao su). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cây hạt dẻ; cây cao su; cây sồi", "Hạng Tần Suất (Jun Da)": "2865.0", "Tần Suất % (Jun Da)": "99.0395925525", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 象", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木象", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "象", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "橡", "Unihan_Traditional (Chữ Phồn thể)": "橡", "Pinyin_Xie": "xiàng", "Âm Hán Việt_Xie": "tượng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này thường làm danh từ đứng trước danh từ khác để chỉ các sản phẩm làm từ cao su. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('碱', '{"9000": "2866.0", "Chữ Trung Quốc": "碱", "Bộ thủ & thành phần_Xie": "Bộ thủ | 石 | Số nét | 14 | nét | 石 | thạch | biểu nghĩa | đá, khoáng chất | 咸 | hàm | biểu âm | hàm/kiềm — cho âm jiǎn (anchor dùng 僉) | 碱 = 石(Thạch, biểu nghĩa: khoáng chất) + 咸/僉 (biểu âm: âm jiǎn). Wiktionary dùng 僉 làm thành phần biểu âm trong dạng gốc, dạng hiển thị dùng 咸. Chữ hình thanh chỉ chất kiềm (base, alkali) trong đất hoặc hóa học.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"kiềm\": 石 (đá, khoáng) + 咸 (mặn — âm jiǎn) — khoáng chất mặn nồng trong đất, đó là chất kiềm 碱 (bazơ). | Gương Hán-Việt | kiềm trong 碱性 (tính kiềm) và 盐碱地 (đất nhiễm kiềm) | Mở khoá kiến thức | Biết 碱 (kiềm) mở khoá: 碱性 (tính kiềm/bazơ), 盐碱地 (đất kiềm), 纯碱 (soda).", "Tự nguyên_Xie": "Chữ hình thanh: 石 (thạch, biểu nghĩa: khoáng chất) + 僉 (biểu âm, âm jiǎn). Wiktionary ghi {{Han compound|石|僉|ls=psc|c1=s|c2=p}}. Nghĩa: chất kiềm, alkali — vị mặn nồng trong đất, như muối kiềm dùng giặt giũ. Chưa có thông tin glyph-origin chi tiết ngoài cấu trúc hình thanh. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chất kiềm, chất dảm (trong đất, như xà phòng, dùng để giặt), bazơ", "Hạng Tần Suất (Jun Da)": "2866.0", "Tần Suất % (Jun Da)": "99.0407553191", "GavinGrover_Once (Chiết tự trực tiếp)": "石 + 咸", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰石咸", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "咸", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "石", "Unihan_Simplified (Chữ Giản thể)": "碱", "Unihan_Traditional (Chữ Phồn thể)": "鹻", "Pinyin_Xie": "jiǎn", "Âm Hán Việt_Xie": "giảm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này thường làm danh từ trong hóa học hoặc nông nghiệp để chỉ chất kiềm hay đất phèn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('聋', '{"9000": "2867.0", "Chữ Trung Quốc": "聋", "Bộ thủ & thành phần_Xie": "Bộ thủ | 耳 | Số nét | 11 | nét | 龙 | long | biểu âm | rồng, âm lóng gần lung | 耳 | nhĩ | biểu nghĩa | tai | 聋 = 龙 (Long, biểu âm, âm lóng) + 耳 (Nhĩ, biểu nghĩa: tai); chữ hình thanh — tai (耳) không nghe được như con rồng (龙) chỉ là âm vay mượn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lung\": tai (耳) nghe tiếng rồng (龙 — long) gầm lớn đến mức bị điếc — lung điếc tai. | Gương Hán-Việt | \"lung\" trong 聋哑 (lung á — điếc và câm). | Mở khoá kiến thức | Biết 聋 (lung) mở khoá 聋哑人 (người điếc câm) và 聋人 (người điếc) — từ ngữ y tế xã hội HSK 6.", "Tự nguyên_Xie": "Đại triện | Theo Wiktionary, chữ phồn thể 聾: 龍 biểu âm, 耳 biểu nghĩa. Đại triện đã ghi nhận hình dạng này. Nghĩa là điếc — tai không nghe được. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "điếc, nghễnh ngãng", "Hạng Tần Suất (Jun Da)": "2867.0", "Tần Suất % (Jun Da)": "99.0419180856", "GavinGrover_Once (Chiết tự trực tiếp)": "龙 + 耳", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱龙耳", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "耳", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "龙", "Unihan_Simplified (Chữ Giản thể)": "聋", "Unihan_Traditional (Chữ Phồn thể)": "聾", "Pinyin_Xie": "lóng", "Âm Hán Việt_Xie": "lung", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này thường làm tính từ đứng trước danh từ hoặc làm vị ngữ để chỉ trạng thái mất thính lực. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | lóng | / | điếc | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Bệnh I", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('姥', '{"9000": "2868.0", "Chữ Trung Quốc": "姥", "Bộ thủ & thành phần_Xie": "Bộ thủ | 女 | Số nét | 9 | nét | 女 | nữ | biểu âm | phụ nữ — cũng cho âm lão/mỗ | 老 | lão | biểu âm | già — cho âm lão | 姥 = 女 (Nữ, biểu nghĩa và biểu âm) + 老 (Lão, biểu âm). Wiktionary ghi hai etymologies: psc (女 biểu nghĩa, 老 biểu âm) và ic (hội ý: phụ nữ [女] già [老] = bà lão). Đây là trường hợp vừa hình thanh vừa hội ý. Nghĩa: bà ngoại, bà lão.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lão\": phụ nữ (女-Nữ) già (老-Lão) — bà lão ngoại. Lão = bà ngoại. Đơn giản và trực tiếp. | Gương Hán-Việt | lão trong ''lão thành, cụ lão'' — cùng nghĩa già; 姥 dùng đặc biệt cho bà ngoại hoặc bà lão | Mở khoá kiến thức | Biết 姥 mở khoá: 姥姥 (lão lão – bà ngoại), 姥爷 (lão gia – ông ngoại), 老姥 (lão lão – bà già).", "Tự nguyên_Xie": "姥 vừa là hình thanh vừa là hội ý. Wiktionary ghi: Etymology 1: {{Han compound|女|老|c1=s|c2=p|ls=psc}} — 女 biểu nghĩa, 老 biểu âm. Etymology 2: {{Han compound|女|老|ls=ic}} — phụ nữ (女) già (老) = bà lão. Nghĩa phổ biến nhất là bà ngoại (姥姥 – lão lão). Hình ảnh hội ý rất trực tiếp: người phụ nữ già. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bà lão", "Hạng Tần Suất (Jun Da)": "2868.0", "Tần Suất % (Jun Da)": "99.0430803354", "GavinGrover_Once (Chiết tự trực tiếp)": "女 + 老", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰女老", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "老", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "女", "Unihan_Simplified (Chữ Giản thể)": "姥", "Unihan_Traditional (Chữ Phồn thể)": "姥", "Pinyin_Xie": "lǎo", "Âm Hán Việt_Xie": "mỗ, lão", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này thường dùng trong khẩu ngữ để gọi bà ngoại hoặc kết hợp thành từ chỉ bà lão lớn tuổi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('瑜', '{"9000": "2869.0", "Chữ Trung Quốc": "瑜", "Bộ thủ & thành phần_Xie": "Bộ thủ | 玉 | Số nét | 13 | nét | 王 | vương | biểu nghĩa | ngọc (bộ 玉 viết liền) | 俞 | du | biểu âm | du — cho âm yú | 瑜 = 王(Vương — bộ 玉, biểu nghĩa: ngọc) + 俞 (Du, biểu âm: âm yú). Chữ hình thanh. Wiktionary: {{Han compound|玉|俞|ls=psc|t1=jade|c1=s|c2=p}}. Nghĩa: ngọc sáng đẹp, ánh sáng của ngọc; ẩn dụ: đức hạnh tốt.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"du\": 王/玉 (ngọc) + 俞 (du, âm yú) — viên ngọc sáng trong, không tì vết — như trong câu 瑕不掩瑜 (khuyết điểm không che được ưu điểm). | Gương Hán-Việt | du trong ''du già'' (瑜伽 — yoga) và tên Chu Du (周瑜) | Mở khoá kiến thức | Biết 瑜 (du) mở khoá: 瑜伽 (yoga), 瑕不掩瑜 (ưu điểm lấn át khuyết điểm), 周瑜 (tên riêng).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Chữ hình thanh: 玉 (ngọc, biểu nghĩa) + 俞 (du, biểu âm). Wiktionary xác nhận. Tiểu triện và Lục thư thông còn hình ảnh. Nghĩa gốc: ngọc quý, ánh sáng ngọc. Mở rộng: phẩm chất tốt đẹp (như ngọc sáng). Nổi tiếng qua tên Chu Du (周瑜), danh tướng Tam Quốc. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ánh sáng của ngọc", "Hạng Tần Suất (Jun Da)": "2869.0", "Tần Suất % (Jun Da)": "99.0442374173", "GavinGrover_Once (Chiết tự trực tiếp)": "王 + 俞", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰王俞", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "俞", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "王", "Unihan_Simplified (Chữ Giản thể)": "瑜", "Unihan_Traditional (Chữ Phồn thể)": "瑜", "Pinyin_Xie": "yú", "Âm Hán Việt_Xie": "du", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này thường dùng làm danh từ trong văn viết hoặc đặt tên người để chỉ phẩm chất tốt đẹp. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('毋', '{"9000": "2870.0", "Chữ Trung Quốc": "毋", "Bộ thủ & thành phần_Xie": "Bộ thủ | 毋 | Số nét | 4 | nét | 毋 | vô | tượng hình | chữ độc lập — gốc từ 母 (mẹ) được chuyên hoá | 毋 là chữ độc lập. Wiktionary: ''In the oracle bone script, 母 was borrowed to represent this character. It was later specialized to distinguish it from ''mother'', replacing the two dots with one stroke.'' Chữ tượng hình mượn dùng, sau chuyên hoá thành chữ phủ định.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"vô\": gốc từ 母 (mẹ) — hình ảnh người mẹ giơ tay ngăn lại, nói ''vô'' (đừng!). Một nét thẳng thay hai chấm để phân biệt với chữ mẹ. | Gương Hán-Việt | vô trong ''vô luận'' (毋论 — chớ bàn) và ''vô súc vô quân'' (毋 — không, đừng, cổ ngữ) | Mở khoá kiến thức | Biết 毋 (vô) mở khoá: 毋庸 (không cần thiết), 毋须 (không cần), 毋宁 (thà rằng).", "Tự nguyên_Xie": "Lệ thư | Trong giáp cốt văn, 母 (mẹ) được mượn để viết 毋 (chớ, đừng). Sau đó để phân biệt, hai chấm của 母 được thay bằng một nét. Wiktionary xác nhận quá trình mượn và chuyên hoá này. Lệ thư còn hình ảnh. Nghĩa gốc: phủ định mệnh lệnh (chớ, đừng làm). Nghĩa mở rộng: không có. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "64.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Nữ (60)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Có một nét cong (sự bất chính) nằm trong bụng chữ Nữ (số 60) . Tượng trưng cho lòng dạ không ngay thẳng, phải luôn kiềm chế chớ để nó cong vạy.", "Nghĩa Tiếng Việt_Xie": "chớ, đừng", "Hạng Tần Suất (Jun Da)": "2870.0", "Tần Suất % (Jun Da)": "99.0453908818", "GavinGrover_Once (Chiết tự trực tiếp)": "No glyph available + 𠂇", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "Ký hiệu: built", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "𠂇", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "毋", "Unihan_Traditional (Chữ Phồn thể)": "毋", "Pinyin_Xie": "wú", "Âm Hán Việt_Xie": "vô", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Phó từ | 副词 | Chữ này thường làm phó từ phủ định đứng trước động từ trong văn ngôn hoặc các thành ngữ cổ. | Phó từ | 副词 | Bổ nghĩa cho động từ hoặc tính từ và luôn đứng TRƯỚC chúng — 都是, 很好. Không đứng sau như tiếng Việt và không bổ nghĩa cho danh từ.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('娅', '{"9000": "2871.0", "Chữ Trung Quốc": "娅", "Bộ thủ & thành phần_Xie": "Bộ thủ | 女 | Số nét | 9 | nét | 女 | nữ | biểu nghĩa | phụ nữ — quan hệ hôn nhân | 亚 | á | biểu âm | á — cho âm yà | 娅 = 女(Nữ, biểu nghĩa: liên quan phụ nữ/hôn nhân) + 亚 (Á, biểu âm: âm yà). Chữ hình thanh. Wiktionary chỉ có phiên âm, không có glyph-origin. Nghĩa cổ: từ xưng hô giữa chồng của các chị em (anh em rể với nhau).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"á\": 女 (phụ nữ, hôn nhân) + 亚 (á, âm yà) — qua người phụ nữ (chị/em) mà trở thành ''á anh em'', tức anh em rể. | Gương Hán-Việt | á trong ''nhân á'' (姻娅 — thông gia, họ hàng thông gia) | Mở khoá kiến thức | Biết 娅 (á) mở khoá: 姻娅 (thông gia), 婭奼 (yàchà — cổ ngữ: thiếu nữ đẹp).", "Tự nguyên_Xie": "Chữ hình thanh: 女 (nữ, biểu nghĩa: quan hệ phụ nữ/hôn nhân) + 亚 (biểu âm). Wiktionary không có phân tích glyph-origin. Nghĩa gốc: cách gọi nhau giữa chồng của các chị em (婚姻关系中的称谓). Dùng trong 姻娅 (婚姻 — hôn nhân và hàng xóm/thân thuộc). Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "anh em rể", "Hạng Tần Suất (Jun Da)": "2871.0", "Tần Suất % (Jun Da)": "99.0465433126", "GavinGrover_Once (Chiết tự trực tiếp)": "女 + 亚", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰女亚", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "亚", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "女", "Unihan_Simplified (Chữ Giản thể)": "娅", "Unihan_Traditional (Chữ Phồn thể)": "婭", "Pinyin_Xie": "yà", "Âm Hán Việt_Xie": "á", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này thường dùng trong từ ghép để chỉ mối quan hệ họ hàng giữa những người cùng làm rể. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('沮', '{"9000": "2872.0", "Chữ Trung Quốc": "沮", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 8 | nét | 氵 | thuỷ | biểu nghĩa | nước, sông | 且 | thả | biểu âm | và, hơn nữa — âm jǔ gần trở | 沮 = 氵 (Thuỷ, biểu nghĩa: nước) + 且 (Thả, biểu âm, âm jǔ). Cấu trúc hình thanh nhưng Wiktionary không ghi rõ ls code; có thể là hình thanh. Nghĩa gốc là tên sông, sau mở rộng sang nghĩa ngăn chặn, nản lòng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trở\": nước (氵) gặp đá ngáng (且) — dòng chảy bị cản trở, như lòng người nản chí khi bị ngăn chặn. | Gương Hán-Việt | \"trở\" trong 沮丧 (trở táng — nản lòng, thất vọng). | Mở khoá kiến thức | Biết 沮 (trở) mở khoá 沮丧 (nản lòng) — từ cảm xúc HSK 6 hay gặp.", "Tự nguyên_Xie": "Đại triện | Tiểu triện | Wiktionary không ghi rõ cấu trúc hình thanh hay hội ý cho 沮; glyph origin chỉ ghi phát âm. Dựa vào cấu trúc: 氵 biểu nghĩa nước (tên sông), 且 có khả năng biểu âm. Đại triện và tiểu triện ghi nhận chữ này. Nghĩa chính là tên sông 沮水 và mở rộng sang: ngăn chặn, chấm dứt, nản chí. Chưa có nguồn học thuật xác định dứt khoát ls cho chữ này. | Theo Wiktionary · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đất lầy trũng", "Hạng Tần Suất (Jun Da)": "2872.0", "Tần Suất % (Jun Da)": "99.0476952267", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 且", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵且", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "且", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "沮", "Unihan_Traditional (Chữ Phồn thể)": "沮", "Pinyin_Xie": "jǔ", "Âm Hán Việt_Xie": "trở, tự", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Chữ này thường làm động từ chỉ sự ngăn cản hoặc làm tính từ chỉ tâm trạng chán nản, thất vọng. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('萌', '{"9000": "2873.0", "Chữ Trung Quốc": "萌", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 11 | nét | 艹 | thảo | biểu nghĩa | bộ cỏ, cây cối | 明 | minh | biểu âm | sáng, rõ ràng — âm míng gần méng | 萌 = 艹 (Thảo, biểu nghĩa: cỏ, thực vật) + 明 (Minh, biểu âm, âm míng); chữ hình thanh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"manh\": dưới ánh sáng ban mai (明 — minh), mầm cỏ (艹) xanh nảy lên — manh nha, khởi đầu mới. | Gương Hán-Việt | \"manh\" trong 萌芽 (manh nha — nảy mầm, khởi sinh) và 萌发 (phát manh — nảy mầm). | Mở khoá kiến thức | Biết 萌 (manh) mở khoá 萌芽 (manh nha) — từ cả nghĩa đen (hạt nảy mầm) lẫn nghĩa bóng (ý tưởng nhen nhóm) ở HSK 6.", "Tự nguyên_Xie": "Giáp cốt văn | Lục thư thông | Theo Wiktionary, 萌 là chữ hình thanh: bộ 艸 (艹) biểu nghĩa cỏ cây, 明 biểu âm. Giáp cốt văn đã ghi nhận chữ này. Nghĩa gốc là mầm cây mới nhú lên, sau mở rộng sang nghĩa bắt đầu nảy sinh (một ý tưởng, một sự kiện). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mầm cỏ; bừa cỏ", "Hạng Tần Suất (Jun Da)": "2873.0", "Tần Suất % (Jun Da)": "99.0488471407", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 明", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹明", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "明", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "萌", "Unihan_Traditional (Chữ Phồn thể)": "萌", "Pinyin_Xie": "méng", "Âm Hán Việt_Xie": "manh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Danh từ | 名词 | Chữ này thường làm động từ chỉ sự nảy mầm hoặc làm tính từ chỉ sự dễ thương trong ngôn ngữ mạng. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('俏', '{"9000": "2874.0", "Chữ Trung Quốc": "俏", "Bộ thủ & thành phần_Xie": "Bộ thủ | 人 | Số nét | 9 | nét | 亻 | nhân | biểu nghĩa | người | 肖 | tiêu | biểu âm | tiêu — cho âm qiào | 俏 = 亻(Nhân, biểu nghĩa: người) + 肖 (Tiêu, biểu âm: âm qiào). Chữ hình thanh. Wiktionary chỉ có phiên âm, không có glyph-origin chi tiết. Nghĩa: đẹp, duyên dáng, xinh xắn (về người).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tiếu\": 亻 (người) + 肖 (tiêu, giống — âm qiào) — người trông rất giống mẫu lý tưởng, đẹp và xinh xắn — 俊俏 (tuấn tú duyên dáng). | Gương Hán-Việt | tiếu trong ''tuấn tiếu'' (俊俏 — tuấn tú duyên dáng) | Mở khoá kiến thức | Biết 俏 (tiếu) mở khoá: 俊俏 (tuấn tú, xinh đẹp), 俏皮 (dí dỏm, hoạt bát), 走俏 (bán chạy).", "Tự nguyên_Xie": "Chữ hình thanh: 亻/人 (nhân, biểu nghĩa: người) + 肖 (tiêu, biểu âm). Wiktionary không có phân tích glyph-origin. Nghĩa gốc: đẹp, duyên dáng; nghĩa mở rộng: hàng bán chạy (phương ngữ Hạ Môn), có duyên, lôi cuốn. Chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "giống; đẹp", "Hạng Tần Suất (Jun Da)": "2874.0", "Tần Suất % (Jun Da)": "99.0499990548", "GavinGrover_Once (Chiết tự trực tiếp)": "亻 + 肖", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰亻肖", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "肖", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "亻", "Unihan_Simplified (Chữ Giản thể)": "俏", "Unihan_Traditional (Chữ Phồn thể)": "俏", "Pinyin_Xie": "qiào", "Âm Hán Việt_Xie": "tiếu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này thường làm tính từ đứng trước danh từ hoặc làm vị ngữ để miêu tả vẻ đẹp thanh tú. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('黯', '{"9000": "2875.0", "Chữ Trung Quốc": "黯", "Bộ thủ & thành phần_Xie": "Bộ thủ | 音 | Số nét | 21 | nét | 黑 | hắc | biểu nghĩa | đen | 音 | âm | biểu âm | âm — cho âm àn | 黯 = 黑(Hắc, biểu nghĩa: đen, tối) + 音 (Âm, biểu âm: âm àn). Chữ hình thanh. Wiktionary chỉ có phiên âm. Nghĩa: tối đen, ảm đạm; cũng dùng ẩn dụ: tâm trạng u ám (黯然 — buồn bã, tàn lụi).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ảm\": 黑 (đen) + 音 (âm — vừa cho âm vừa gợi ''âm u'') — đen tối và âm u như đêm không trăng — 黯然 (ảm đạm, lịm tắt). | Gương Hán-Việt | ảm trong ''ảm đạm'' (黯淡 — tối tăm, ảm đạm) | Mở khoá kiến thức | Biết 黯 (ảm) mở khoá: 黯然 (ảm đạm, hiu quạnh), 黯淡 (mờ nhạt, ảm đạm), 黯然失色 (lu mờ hẳn).", "Tự nguyên_Xie": "Chữ hình thanh: 黑 (hắc, biểu nghĩa: đen) + 音 (âm, biểu âm). Wiktionary không có phân tích glyph-origin chi tiết. Nghĩa gốc: màu đen sẫm, tối tăm. Nghĩa ẩn dụ quan trọng: 黯然 (ảm đạm, mất đi vẻ sáng — như 黯然失色: mất sắc, lu mờ hẳn). Chưa có nguồn học thuật chi tiết hơn. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "màu đen sẫm; tối", "Hạng Tần Suất (Jun Da)": "2875.0", "Tần Suất % (Jun Da)": "99.0511468346", "GavinGrover_Once (Chiết tự trực tiếp)": "黑 + 音", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰黑音", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "音", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "黑", "Unihan_Simplified (Chữ Giản thể)": "黯", "Unihan_Traditional (Chữ Phồn thể)": "黯", "Pinyin_Xie": "àn", "Âm Hán Việt_Xie": "ảm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này thường làm định ngữ hoặc vị ngữ để miêu tả cảnh sắc tối tăm hoặc tâm trạng u sầu. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('撇', '{"9000": "2876.0", "Chữ Trung Quốc": "撇", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 14 | nét | 扌 | thủ | biểu nghĩa | bàn tay | 敝 | tệ | biểu âm | rách nát, thô tệ — âm bì gần phiết | 撇 = 扌 (Thủ, biểu nghĩa: tay) + 敝 (Tệ, biểu âm, âm bì/piē); chữ hình thanh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phiết\": tay (扌) vứt đi thứ gì tệ (敝) — phiết bỏ, nét phảy vứt bút sang trái. | Gương Hán-Việt | \"phiết\" trong thuật ngữ viết chữ: nét phiết (nét phảy); hoặc 撇开 (phiết khai — gạt ra, bỏ qua). | Mở khoá kiến thức | Biết 撇 (phiết) mở khoá cả tên nét viết (nét phảy) lẫn từ 撇开 (gạt sang một bên) trong giao tiếp HSK 6.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 撇 là chữ hình thanh: bộ 手 (扌) biểu nghĩa hành động tay, 敝 biểu âm. Tiểu triện ghi nhận hình dạng này. Nghĩa gốc là ném, vứt bỏ bằng tay; trong viết chữ Hán, 撇 còn chỉ nét phảy (nét xiên trái). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nét phảy; vứt đi, quẳng đi", "Hạng Tần Suất (Jun Da)": "2876.0", "Tần Suất % (Jun Da)": "99.0522935808", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 敝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌敝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "敝", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "撇", "Unihan_Traditional (Chữ Phồn thể)": "撇", "Pinyin_Xie": "piē", "Âm Hán Việt_Xie": "phiết", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường dùng làm động từ chỉ hành động gạt bỏ, bỏ lại hoặc làm danh từ chỉ nét phẩy trong chữ Hán. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | piē | / | ném | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Từ III", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('粟', '{"9000": "2877.0", "Chữ Trung Quốc": "粟", "Bộ thủ & thành phần_Xie": "Bộ thủ | 米 | Số nét | 12 | nét | 覀 | á | biểu âm | á (biến dạng từ 角 — Wiktionary ghi rõ) | 米 | mễ | biểu nghĩa | gạo, ngũ cốc | 粟 gốc là tượng hình (giáp cốt văn). Thời Chiến Quốc chuyển thành hình thanh: 角 (biểu âm) + 米 (mễ, biểu nghĩa). Wiktionary: 角 biến dạng qua trung gian 𠧪 rồi thành 西. Tiểu triện và giáp cốt văn còn lưu rõ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"túc\": 米 (gạo/ngũ cốc) + 覀 (âm sù) — hạt kê còn vỏ, lương thực cơ bản của người xưa — ''túc'' là lương thực đủ ăn. | Gương Hán-Việt | túc trong ''túc mễ'' (粟米 — hạt kê) và thành ngữ ''túc túc'' (粒粒皆辛苦 — hạt hạt đều gian khổ) | Mở khoá kiến thức | Biết 粟 (túc) mở khoá: 粟米 (kê, ngô — phương ngữ), 沧海一粟 (hạt cát trong biển — rất nhỏ bé).", "Tự nguyên_Xie": "Giáp cốt văn | Tiểu triện | Lục thư thông | Giáp cốt văn: chữ tượng hình vẽ cây kê (millet). Thời Chiến Quốc biến thành hình thanh: 角 (biểu âm) + 米 (mễ, biểu nghĩa: ngũ cốc). Wiktionary ghi: 角 biến dạng qua 𠧪 thành 𥻆 rồi thành dạng có 西. Giáp cốt văn có nhiều biến thể. 粟 nguyên chỉ kê còn vỏ trấu; 米 chỉ gạo đã xay. Có nhiều hình giáp cốt văn và tiểu triện còn lưu. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cây ngô; thóc lúa", "Hạng Tần Suất (Jun Da)": "2877.0", "Tần Suất % (Jun Da)": "99.053440327", "GavinGrover_Once (Chiết tự trực tiếp)": "覀 + 米", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱覀米", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "米", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "覀", "Unihan_Simplified (Chữ Giản thể)": "粟", "Unihan_Traditional (Chữ Phồn thể)": "粟", "Pinyin_Xie": "sù", "Âm Hán Việt_Xie": "túc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng độc lập hoặc kết hợp thành từ ghép để chỉ các loại lương thực, ngũ cốc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('粪', '{"9000": "2878.0", "Chữ Trung Quốc": "粪", "Bộ thủ & thành phần_Xie": "Bộ thủ | 米 | Số nét | 12 | nét | 米 | mễ | biểu nghĩa | gạo — thứ đã qua tiêu hoá | 共 | cộng | biểu âm | cộng — cho âm fèn (phần biểu âm gốc là 田 trong phồn thể 糞) | 粪 là giản thể của 糞, xuất hiện trong Phương án giản hoá 1956. Wiktionary: {{Han simp|糞|f=田|t= }}. Chữ 糞 gốc có bộ 田 (ruộng — phân bón cho ruộng). Dạng giản thể 粪 thay bộ 田 bằng khoảng trống, giữ 米+共.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phân\": 米 (gạo đã tiêu hoá) + 共 (cộng, âm fèn) — gạo ăn vào ''cộng lại'' thành phân — trực tiếp nhưng dễ nhớ. Phân bón cho đất, sinh ra 米 mới. | Gương Hán-Việt | phân trong ''phân tiện'' (粪便 — phân, chất thải) và ''thí phân'' (施粪 — bón phân) | Mở khoá kiến thức | Biết 粪 (phân) mở khoá: 粪便 (phân — chất thải), 施肥/粪 (bón phân), 粪坑 (hố phân).", "Tự nguyên_Xie": "粪 là giản thể của 糞 (xuất hiện lần đầu 1956). Wiktionary dẫn sang 糞 để tra cứu đầy đủ. Chữ phồn thể 糞 có cấu trúc cổ liên quan đến 田 (ruộng), vì phân dùng bón ruộng. Trong dạng giản 粪, phần 米 (gạo đã tiêu) + 共 (cộng — biểu âm). Không có hình etymology cho dạng giản. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "phân, cứt; bón phân", "Hạng Tần Suất (Jun Da)": "2878.0", "Tần Suất % (Jun Da)": "99.0545860397", "GavinGrover_Once (Chiết tự trực tiếp)": "米 + 共", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱米共", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "共", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "米", "Unihan_Simplified (Chữ Giản thể)": "粪", "Unihan_Traditional (Chữ Phồn thể)": "糞", "Pinyin_Xie": "fèn", "Âm Hán Việt_Xie": "phân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường làm danh từ chỉ chất thải động vật hoặc làm động từ với nghĩa bón phân, dọn dẹp. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | fèn | / | phân | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Nông nghiệp", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('尹', '{"9000": "2879.0", "Chữ Trung Quốc": "尹", "Bộ thủ & thành phần_Xie": "Bộ thủ | 尸 | Số nét | 4 | nét | 丿 | biểu nghĩa | gậy (nét phẩy — hội ý) | 又 | hựu | biểu nghĩa | bàn tay | 尹 là chữ hội ý: 丿 (gậy/que) + 又 (hựu — bàn tay). Wiktionary: {{Han compound|ls=ic|丿|又|t1=stick|t2=hand}} — ''bàn tay cầm gậy chỉ huy, tương tự 事 và 支''. Giáp cốt văn, kim văn và tiểu triện còn rõ hình ảnh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"doãn\": bàn tay (又) cầm gậy (丿) — vị quan cầm gậy chỉ huy, đó là 尹 (doãn — quan trưởng, lệnh doãn). | Gương Hán-Việt | doãn trong ''lệnh doãn'' (令尹 — chức tể tướng nước Sở) và ''kinh triệu doãn'' (京兆尹 — quan đứng đầu kinh thành) | Mở khoá kiến thức | Biết 尹 (doãn) mở khoá: 令尹 (lệnh doãn), 府尹 (phủ doãn — tri phủ), 京兆尹 (quan kinh thành).", "Tự nguyên_Xie": "Giáp cốt văn | Kim văn | Tiểu triện | Chữ hội ý: 丿 (gậy) + 又 (bàn tay). Wiktionary: ''A hand holding a rod or brush, indicating control, similar to 事 and 支''. Giáp cốt văn rõ ràng — hình ảnh bàn tay cầm bút/gậy biểu thị quyền hành. Nghĩa gốc: cai quản, giám sát. Nghĩa mở rộng: quan chức, tên họ. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "179.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Hựu (159)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Hình bàn tay (Hựu - biến thể) cầm một cái gậy tượng trưng cho uy quyền để thực hiện quyền trị dân (Phủ doãn, Lệnh doãn).", "Nghĩa Tiếng Việt_Xie": "viên quan, chức trưởng, tên chùm", "Hạng Tần Suất (Jun Da)": "2879.0", "Tần Suất % (Jun Da)": "99.0557317523", "GavinGrover_Once (Chiết tự trực tiếp)": "⺕ + 丨", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺕丨", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "丨", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺕", "Unihan_Simplified (Chữ Giản thể)": "尹", "Unihan_Traditional (Chữ Phồn thể)": "尹", "Pinyin_Xie": "yǐn", "Âm Hán Việt_Xie": "doãn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ chỉ chức quan thời xưa hoặc dùng làm họ trong tên người. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('苟', '{"9000": "2880.0", "Chữ Trung Quốc": "苟", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 8 | nét | 艹 | thảo | biểu nghĩa | bộ cỏ (nghĩa gốc: một loại cỏ) | 句 | câu | biểu âm | câu, cong — âm gǒu gần cẩu | 苟 = 艹 (Thảo, biểu nghĩa: cỏ — nghĩa gốc) + 句 (Câu, biểu âm, âm gǒu); chữ hình thanh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cẩu\": cỏ (艹) mọc cong quẹo (句 — câu cong) — ẩu tả, không thẳng thớm, không cẩn thận. | Gương Hán-Việt | \"cẩu\" trong 一丝不苟 (nhất ti bất cẩu — tỉ mỉ đến từng chi tiết, không cẩu thả chút nào). | Mở khoá kiến thức | Biết 苟 (cẩu) mở khoá thành ngữ 一丝不苟 (HSK 6) — cực kỳ tỉ mỉ, đối lập với cẩu thả.", "Tự nguyên_Xie": "Theo Wiktionary, 苟 là chữ hình thanh: bộ 艸 (艹) biểu nghĩa cỏ (nghĩa gốc là tên một loại cỏ), 句 biểu âm. Nghĩa gốc là tên cỏ, sau chuyển sang dùng như hư từ (nếu như, chỉ cần) và tính từ (ẩu, tuỳ tiện, cẩu thả). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "636.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thảo (146) Cú (026)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Thảo (số 146 - cỏ cây) ở trên chữ Cú (số 026 - câu cú). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Cú (câu cú) chỉ âm, bộ Thảo (cỏ) chỉ ý. Đám cỏ hoang mọc lộn xộn bừa bãi. Cẩu là sự lộn xộn, cẩu thả, không nghiêm chỉnh. *(Biến âm Hán Việt: Cú -> Cẩu)*", "Nghĩa Tiếng Việt_Xie": "ẩu, tuỳ tiện", "Hạng Tần Suất (Jun Da)": "2880.0", "Tần Suất % (Jun Da)": "99.0568753978", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 句", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹句", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "句", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "苟", "Unihan_Traditional (Chữ Phồn thể)": "苟", "Pinyin_Xie": "gǒu", "Âm Hán Việt_Xie": "cẩu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Phó từ | 副词 | Tính từ | 形容词 | Liên từ | 连词 | Thường làm phó từ bổ nghĩa cho động từ để chỉ sự tạm bợ, cẩu thả hoặc làm liên từ biểu thị giả thuyết. | Phó từ | 副词 | Bổ nghĩa cho động từ hoặc tính từ và luôn đứng TRƯỚC chúng — 都是, 很好. Không đứng sau như tiếng Việt và không bổ nghĩa cho danh từ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Liên từ | 连词 | Nối từ, cụm từ hoặc mệnh đề: 和, 但是, 因为…所以…. Lưu ý 和 chỉ nối danh từ, không nối hai câu như ''và'' tiếng Việt.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('癫', '{"9000": "2881.0", "Chữ Trung Quốc": "癫", "Bộ thủ & thành phần_Xie": "Bộ thủ | 疒 | Số nét | 21 | nét | 疒 | nạch | biểu nghĩa | bệnh tật | 颠 | điên | biểu âm | điên — cho âm diān | 癫 = 疒(Nạch, biểu nghĩa: bệnh tật) + 颠 (Điên, biểu âm: âm diān). Chữ hình thanh. Là giản thể của 癲, thay 頁 bằng 页. Wiktionary: {{Han simp|癲|f=頁|t=页}} và dẫn sang 癲. Nghĩa: điên, bệnh tâm thần.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"điên\": 疒 (bệnh) + 颠 (điên — âm diān, cũng chính là ''điên'') — bệnh của người điên, hoàn toàn khớp Hán-Việt lẫn nghĩa. | Gương Hán-Việt | điên trong ''điên cuồng'' (癫狂) và ''điên giản'' (癫痫 — động kinh) | Mở khoá kiến thức | Biết 癫 (điên) mở khoá: 癫狂 (điên cuồng), 癫痫 (động kinh), 疯癫 (điên khùng).", "Tự nguyên_Xie": "癫 là giản thể của 癲, thay 頁 bằng 页. Wiktionary dẫn sang 癲 để tra. Cấu trúc hình thanh: 疒 (nạch, biểu nghĩa: bệnh) + 顛/颠 (điên, biểu âm). Nghĩa: điên cuồng, bệnh tâm thần (癫痫 — động kinh). Chữ giản hoá không có hình etymology riêng. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "điên, rồ, dại", "Hạng Tần Suất (Jun Da)": "2881.0", "Tần Suất % (Jun Da)": "99.0580174929", "GavinGrover_Once (Chiết tự trực tiếp)": "疒 + 颠", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴疒颠", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "颠", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "疒", "Unihan_Simplified (Chữ Giản thể)": "癫", "Unihan_Traditional (Chữ Phồn thể)": "癲", "Pinyin_Xie": "diān", "Âm Hán Việt_Xie": "điên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Thường làm tính từ miêu tả trạng thái điên dại hoặc làm danh từ chỉ chứng bệnh tâm thần. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蚂', '{"9000": "2882.0", "Chữ Trung Quốc": "蚂", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 9 | nét | 虫 | trùng | biểu nghĩa | sâu bọ, côn trùng | 马 | mã | biểu âm | ngựa, âm mǎ | 蚂 = 虫 (Trùng, biểu nghĩa: côn trùng) + 马 (Mã, biểu âm, âm mǎ); chữ hình thanh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mã\": con trùng (虫) mạnh như ngựa (马 — mã) — con kiến khuân đồ nặng gấp nhiều lần trọng lượng cơ thể. | Gương Hán-Việt | \"mã\" trong 蚂蚁 (mã nghĩ — con kiến) và 蚂蟥 (mã hoàng — con đỉa). | Mở khoá kiến thức | Biết 蚂 (mã) mở khoá 蚂蚁 (kiến), 蚂蟥 (đỉa) — hai từ ghép chỉ côn trùng hay gặp trong HSK.", "Tự nguyên_Xie": "Theo Wiktionary, chữ phồn thể 螞: 虫 biểu nghĩa côn trùng, 馬 biểu âm. Chữ giản thể 蚂 thay 馬 bằng 马. Dùng trong các từ ghép chỉ côn trùng như 螞蟻 (kiến) và 螞蟥 (đỉa). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: mã hoàng 螞蟥); (xem: mã nghĩ 螞蟻); con nhặng", "Hạng Tần Suất (Jun Da)": "2882.0", "Tần Suất % (Jun Da)": "99.059157521", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 马", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫马", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "马", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蚂", "Unihan_Traditional (Chữ Phồn thể)": "螞", "Pinyin_Xie": "mǎ", "Âm Hán Việt_Xie": "mã", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường không đứng một mình mà kết hợp với các chữ khác để tạo thành danh từ chỉ các loài côn trùng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('禹', '{"9000": "2883.0", "Chữ Trung Quốc": "禹", "Bộ thủ & thành phần_Xie": "Bộ thủ | 禸 | Số nét | 9 | nét | 禹 | vũ | tượng hình | hình con vật (rắn/sâu) — Shuowen và kim văn xác nhận | 禹 là chữ tượng hình độc lập. Wiktionary: Shuowen diễn giải là tượng hình con vật; kim văn rõ ràng có bộ 虫 (côn trùng/rắn). Nghĩa gốc: con vật (loài bò sát?); nghĩa lịch sử quan trọng: tên vua Vũ (禹) — vị vua trị thủy lập ra nhà Hạ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"vũ\": hình con rắn/bò sát trong kim văn — vua Đại Vũ trị thủy, như con rắn bơi trị thủy lụt trong 13 năm, lập nên nhà Hạ. | Gương Hán-Việt | vũ trong ''Đại Vũ'' (大禹 — vua trị thủy), ''Vũ vương'' (禹王) | Mở khoá kiến thức | Biết 禹 (vũ) mở khoá: 大禹 (Đại Vũ — vua trị thủy), 禹贡 (Vũ Cống — thiên trong Kinh Thư), 夏禹 (Hạ Vũ).", "Tự nguyên_Xie": "Kim văn | Bạch thư | Tiểu triện | Lệ thư | Chữ tượng hình. Wiktionary: ''The Shuowen interprets the character as a pictograph of an animal. The bronze-script character clearly shows the 虫 component.'' Có hình kim văn, bạch thư, tiểu triện và lệ thư. Nghĩa lịch sử: tên vua Đại Vũ (大禹), người trị thủy và lập nhà Hạ. Chữ dùng chủ yếu làm danh từ riêng trong tiếng Trung hiện đại. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "vua Vũ (đời nhà Hạ)", "Hạng Tần Suất (Jun Da)": "2883.0", "Tần Suất % (Jun Da)": "99.0602939315", "GavinGrover_Once (Chiết tự trực tiếp)": "䖝 + 冂", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱䖝冂", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "䖝", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "冂", "Unihan_Simplified (Chữ Giản thể)": "禹", "Unihan_Traditional (Chữ Phồn thể)": "禹", "Pinyin_Xie": "yǔ", "Âm Hán Việt_Xie": "vũ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chủ yếu dùng làm danh từ riêng để chỉ vua Hạ Vũ thời cổ đại hoặc dùng trong tên người. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('廖', '{"9000": "2884.0", "Chữ Trung Quốc": "廖", "Bộ thủ & thành phần_Xie": "Bộ thủ | 广 | Số nét | 14 | nét | 广 | nghiễm | biểu nghĩa | mái hiên rộng, nhà lớn | 翏 | liệu | biểu âm | liệu — cho âm liào | 廖 = 广(Nghiễm, biểu nghĩa: nhà/mái rộng) + 翏 (Liệu, biểu âm: âm liào). Chữ hình thanh. Wiktionary: {{Han compound|广|翏|ls=psc|c1=s|c2=p}}. Chủ yếu dùng làm họ người (Liêu 廖), cũng là tên nước cổ thời Chu.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"liệu\": 广 (nhà rộng) + 翏 (liệu, âm liào) — họ người ở trong ngôi nhà rộng, dòng họ Liêu nổi tiếng miền Nam Trung Quốc. | Gương Hán-Việt | liệu trong ''Liêu Hóa'' (廖化 — tướng Thục Hán) và ''Liêu'' họ người Việt gốc Hoa | Mở khoá kiến thức | Biết 廖 (liệu) mở khoá: 廖化 (tướng thời Tam Quốc), họ 廖 thường gặp trong cộng đồng Hoa Kiều.", "Tự nguyên_Xie": "Tiểu triện | Chữ hình thanh: 广 (nghiễm, biểu nghĩa: nhà rộng) + 翏 (biểu âm, âm liào). Wiktionary xác nhận cấu trúc psc. Tiểu triện còn lưu. Nghĩa chính: họ người (Liao/Liêu). Cũng là tên nước thời Chu (廖國). Trong lịch sử Trung Quốc, 廖 là họ phổ biến ở miền Nam. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "họ Liêu", "Hạng Tần Suất (Jun Da)": "2884.0", "Tần Suất % (Jun Da)": "99.0614293084", "GavinGrover_Once (Chiết tự trực tiếp)": "广 + 翏", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴广翏", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "翏", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "广", "Unihan_Simplified (Chữ Giản thể)": "廖", "Unihan_Traditional (Chữ Phồn thể)": "廖", "Pinyin_Xie": "liào", "Âm Hán Việt_Xie": "liệu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chủ yếu dùng làm danh từ riêng chỉ họ của người trong tiếng Trung. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('俭', '{"9000": "2885.0", "Chữ Trung Quốc": "俭", "Bộ thủ & thành phần_Xie": "Bộ thủ | 人 | Số nét | 9 | nét | 亻 | nhân | biểu nghĩa | người | 佥 | thiêm | biểu âm | tất cả, cùng nhau — âm qiān gần kiệm | 俭 = 亻 (Nhân, biểu nghĩa: người) + 佥 (Thiêm, biểu âm; phồn thể là 儉 với phần 僉); chữ hình thanh — người (亻) biết tiết kiệm, sống giản dị.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"kiệm\": người (亻) biết gom góp tất cả (佥 — thiêm nghĩa tất cả) một cách dè sẻn — kiệm ước, tiết kiệm. | Gương Hán-Việt | \"kiệm\" trong 勤俭 (cần kiệm — chăm chỉ và tiết kiệm) và 节俭 (tiết kiệm). | Mở khoá kiến thức | Biết 俭 (kiệm) mở khoá 勤俭节约 (cần kiệm tiết ước — tiết kiệm trong mọi mặt) — giá trị truyền thống Trung Hoa quan trọng ở HSK 6.", "Tự nguyên_Xie": "Đại triện | Tiểu triện | Theo Wiktionary, chữ phồn thể 儉: 人 biểu nghĩa người, 僉 biểu âm. Đại triện và tiểu triện ghi nhận hình dạng này. Nghĩa gốc là tiết kiệm, thận trọng trong chi tiêu; sau mở rộng sang nghĩa khiêm tốn, điều độ. Khổng Tử dùng 儉 như một trong năm đức tính (温良恭儉讓). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tiết kiệm", "Hạng Tần Suất (Jun Da)": "2885.0", "Tần Suất % (Jun Da)": "99.0625626182", "GavinGrover_Once (Chiết tự trực tiếp)": "亻 + 佥", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰亻佥", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "佥", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "亻", "Unihan_Simplified (Chữ Giản thể)": "俭", "Unihan_Traditional (Chữ Phồn thể)": "儉", "Pinyin_Xie": "jiǎn", "Âm Hán Việt_Xie": "kiệm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường làm tính từ làm vị ngữ hoặc định ngữ để chỉ lối sống tiết kiệm, không hoang phí. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('帖', '{"9000": "2886.0", "Chữ Trung Quốc": "帖", "Bộ thủ & thành phần_Xie": "Bộ thủ | 巾 | Số nét | 8 | nét | 巾 | cân | biểu nghĩa | khăn vải, miếng vải vuông | 占 | chiêm | biểu âm | chiếm, xem bói — âm zhān/tiē gần thiếp | 帖 = 巾 (Cân, biểu nghĩa: vải, khăn — vật phẳng) + 占 (Chiêm, biểu âm, âm tiē); chữ hình thanh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thiếp\": miếng vải (巾) nhỏ đặt ngay ngắn (占) — tờ thiếp phẳng mỏng, gửi lời mời. | Gương Hán-Việt | \"thiếp\" trong 请帖 (thỉnh thiếp — thiếp mời) và 帖子 (thiếp tử — bài viết, thư mục). | Mở khoá kiến thức | Biết 帖 (thiếp) mở khoá 请帖 (thiếp mời) và 帖子 (bài đăng trên mạng) — từ cả truyền thống lẫn hiện đại ở HSK.", "Tự nguyên_Xie": "Theo Wiktionary, 帖 là chữ hình thanh: 巾 biểu nghĩa khăn vải vuông, 占 biểu âm. Nghĩa gốc có thể là tấm vật phẳng; từ đó mở rộng sang nhiều nghĩa: thiếp mời, vâng lời (phục tùng như vải mềm), sách chép chữ mẫu (thiệp học). Chữ đa âm: tiē (phục tùng), tiě (thiếp mời), tiè (sách chép mẫu). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "449.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Cân (196) Chiêm (106)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Cân (số 50 - cái khăn) và chữ Chiêm (số 25 - bói toán / chiếm lấy) . Dùng tấm vải, khăn (Cân) để viết lời bói toán (Chiêm) gửi cho người khác gọi là tấm thiếp, danh thiếp. Giải thích sự chuyển ý: Chữ Chiêm (bói toán) chỉ âm, chữ Cân (khăn/vải) chỉ ý. Mảnh lụa hoặc vải (Cân) viết chữ lên gọi là danh thiếp, thiệp mời (Thiếp). *(Biến âm Hán Việt: Chiêm -> Thiếp)*", "Nghĩa Tiếng Việt_Xie": "tấm thiếp, tấm thiệp", "Hạng Tần Suất (Jun Da)": "2886.0", "Tần Suất % (Jun Da)": "99.0636948944", "GavinGrover_Once (Chiết tự trực tiếp)": "巾 + 占", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰巾占", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "占", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "巾", "Unihan_Simplified (Chữ Giản thể)": "帖", "Unihan_Traditional (Chữ Phồn thể)": "帖", "Pinyin_Xie": "tiē", "Âm Hán Việt_Xie": "thiếp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Lượng từ | 量词 | Thường làm danh từ chỉ các loại thiệp, giấy tờ hoặc làm lượng từ cho liều thuốc bắc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Lượng từ | 量词 | Đứng giữa số từ (hoặc 这/那) và danh từ: 一杯茶, 这本书. Mỗi danh từ đi với lượng từ riêng; 个 là lượng từ dùng chung phổ biến nhất.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('煎', '{"9000": "2887.0", "Chữ Trung Quốc": "煎", "Bộ thủ & thành phần_Xie": "Bộ thủ | 火 | Số nét | 13 | nét | 前 | tiền | biểu âm | trước, phía trước — âm qián gần chiên | 灬 | hoả | biểu nghĩa | bộ lửa (火 biến thể) | 煎 = 前 (Tiền, biểu âm, âm qián) + 灬 (Hoả biến thể, biểu nghĩa: lửa); chữ hình thanh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chiên\": lửa (灬) phía trước (前 — tiền) bếp — chiên xào, rán sôi xèo xèo. | Gương Hán-Việt | \"chiên\" trong 煎 (chiên — rán); tiếng Việt mượn luôn: chiên cá, chiên trứng. | Mở khoá kiến thức | Biết 煎 (chiên) mở khoá từ chỉ phương pháp nấu nướng HSK 5-6: 煎, 炸, 炒 — ba cách dùng dầu mỡ khác nhau.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Theo Wiktionary, 煎 là chữ hình thanh: 前 biểu âm, 火 (灬) biểu nghĩa lửa. Tiểu triện ghi nhận hình dạng này. Nghĩa gốc là đun sôi, sắc thuốc; sau mở rộng sang nghĩa chiên, rán bằng dầu mỡ. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nấu, sắc, cất; ngâm", "Hạng Tần Suất (Jun Da)": "2887.0", "Tần Suất % (Jun Da)": "99.0648230364", "GavinGrover_Once (Chiết tự trực tiếp)": "前 + 灬", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱前灬", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "前", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "灬", "Unihan_Simplified (Chữ Giản thể)": "煎", "Unihan_Traditional (Chữ Phồn thể)": "煎", "Pinyin_Xie": "jiān", "Âm Hán Việt_Xie": "tiên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này thường làm động từ đứng trước danh từ chỉ món ăn hoặc vị thuốc để chỉ cách chế biến. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | Từ đơn | Từ vựng HSK 5: rán | / | jiān | / | rán | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Thức ăn tôi | HSK | HSK 5 | · | Thức ăn và đồ uống", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('缕', '{"9000": "2888.0", "Chữ Trung Quốc": "缕", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 12 | nét | 纟 | mịch | biểu nghĩa | tơ lụa, sợi | 娄 | lâu | biểu âm | lâu — cho âm lǚ | 缕 = 纟(Mịch, biểu nghĩa: tơ sợi) + 娄 (Lâu, biểu âm: âm lǚ). Chữ hình thanh. Wiktionary chỉ có phiên âm. Nghĩa: sợi tơ, sợi chỉ; lượng từ cho những thứ mảnh như chỉ, khói.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lũ\": 纟 (tơ sợi) + 娄 (lâu, âm lǚ) — sợi tơ mảnh ''lũ lũ'' kéo dài không đứt, như 千丝万缕 (nghìn sợi muôn vương). | Gương Hán-Việt | lũ trong ''thiên ti vạn lũ'' (千丝万缕 — nghìn sợi muôn vương — liên hệ chằng chịt) | Mở khoá kiến thức | Biết 缕 (lũ) mở khoá: 千丝万缕 (liên hệ chằng chịt), 一缕 (một sợi/làn), 篳路蓝缕 (gian khổ tạo dựng).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Chữ hình thanh: 纟/糸 (mịch, biểu nghĩa: tơ sợi) + 娄 (biểu âm, âm lǚ). Wiktionary không có phân tích glyph-origin. Tiểu triện và Lục thư thông còn hình. Nghĩa gốc: sợi tơ mảnh. Dùng làm lượng từ: một 缕 khói, một 缕 ánh sáng — luôn chỉ thứ mảnh, dài. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sợi tơ", "Hạng Tần Suất (Jun Da)": "2888.0", "Tần Suất % (Jun Da)": "99.0659501448", "GavinGrover_Once (Chiết tự trực tiếp)": "纟 + 娄", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰纟娄", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "娄", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "纟", "Unihan_Simplified (Chữ Giản thể)": "缕", "Unihan_Traditional (Chữ Phồn thể)": "縷", "Pinyin_Xie": "lǚ", "Âm Hán Việt_Xie": "lũ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Lượng từ | 量词 | Chữ này làm danh từ chỉ sợi chỉ hoặc làm lượng từ cho những thứ nhỏ, dài như sợi khói, sợi tóc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Lượng từ | 量词 | Đứng giữa số từ (hoặc 这/那) và danh từ: 一杯茶, 这本书. Mỗi danh từ đi với lượng từ riêng; 个 là lượng từ dùng chung phổ biến nhất.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | lǚ | / | sợi xoăn | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Từ chức năng và phụ từ II", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('窦', '{"9000": "2889.0", "Chữ Trung Quốc": "窦", "Bộ thủ & thành phần_Xie": "Bộ thủ | 穴 | Số nét | 13 | nét | 穴 | huyệt | biểu nghĩa | hang, lỗ hổng | 卖 | mại | biểu âm | mại (dạng hiện tại) — gốc là 𧶠, biểu âm cho âm dòu | 窦 = 穴(Huyệt, biểu nghĩa: hang, lỗ) + 𧶠/卖 (biểu âm). Chữ hình thanh. Wiktionary: {{Han compound|ls=psc|穴|𧶠|c1=s|t1=hole|c2=p}}. Hình đại triện còn lưu. Nghĩa: cái lỗ, cái hang; dùng nhiều trong y học: xoang (鼻窦 — xoang mũi).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đậu\": 穴 (hang, lỗ) + phần âm dòu — cái hang sâu trong núi, hoặc khoang rỗng trong cơ thể như xoang mũi (鼻窦). | Gương Hán-Việt | đậu trong ''tỵ đậu'' (鼻窦 — xoang mũi) và họ ''Đậu'' (窦 — họ người) | Mở khoá kiến thức | Biết 窦 (đậu) mở khoá: 鼻窦 (xoang mũi), 窦房结 (nút xoang nhĩ — tim mạch), 心窦 (xoang tim).", "Tự nguyên_Xie": "Đại triện | Chữ hình thanh: 穴 (huyệt, biểu nghĩa: hang, lỗ hổng) + 𧶠 (biểu âm). Wiktionary xác nhận. Hình đại triện còn. Nghĩa gốc: cái lỗ, cái hang. Nghĩa hiện đại quan trọng: xoang (sinus) trong giải phẫu — 鼻窦 (xoang mũi), 窦房结 (nút xoang nhĩ). Cũng là họ người (窦 — họ Đậu). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái lỗ", "Hạng Tần Suất (Jun Da)": "2889.0", "Tần Suất % (Jun Da)": "99.0670772531", "GavinGrover_Once (Chiết tự trực tiếp)": "穴 + 卖", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱穴卖", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "卖", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "穴", "Unihan_Simplified (Chữ Giản thể)": "窦", "Unihan_Traditional (Chữ Phồn thể)": "竇", "Pinyin_Xie": "dòu", "Âm Hán Việt_Xie": "đậu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ thường xuất hiện trong các thuật ngữ y học chỉ các xoang, hốc trong cơ thể hoặc họ người. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('簇', '{"9000": "2890.0", "Chữ Trung Quốc": "簇", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 17 | nét | 竹 | trúc | biểu nghĩa | tre — chỉ vật mọc thành cụm | 族 | tộc | biểu âm | tộc — cho âm cù | 簇 = 竹(Trúc, biểu nghĩa: tre — mọc thành cụm) + 族 (Tộc, biểu âm: âm cù). Chữ hình thanh. Wiktionary: {{Han compound|竹|族|ls=psc|c1=s|c2=p|t1=bamboo}}. Nghĩa: tụ tập thành cụm, đám; lượng từ chỉ vật mọc thành bó/chùm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thốc\": 竹 (tre, mọc thành bụi) + 族 (tộc, nhóm người — âm cù) — như bụi tre tụ thành nhóm, đó là 簇 — tụ thành cụm. | Gương Hán-Việt | thốc trong ''thốc ủng'' (簇拥 — vây quanh đông đảo) | Mở khoá kiến thức | Biết 簇 (thốc) mở khoá: 簇拥 (vây quanh), 花团锦簇 (hoa đẹp rực rỡ), 簇新 (mới tinh).", "Tự nguyên_Xie": "Chữ hình thanh: 竹 (trúc, biểu nghĩa: tre — mọc thành cụm dày đặc) + 族 (tộc, biểu âm). Wiktionary xác nhận. Nghĩa gốc: tụ lại thành cụm (như tre mọc). Nghĩa lượng từ: một 簇 hoa, một 簇 người. Nghĩa phó từ: 簇新 (hoàn toàn mới). Không có hình etymology. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sum họp, súm xít; mũi tên", "Hạng Tần Suất (Jun Da)": "2890.0", "Tần Suất % (Jun Da)": "99.0682002272", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 族", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮族", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "族", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "簇", "Unihan_Traditional (Chữ Phồn thể)": "簇", "Pinyin_Xie": "cù", "Âm Hán Việt_Xie": "thốc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Lượng từ | 量词 | Động từ | 动词 | Danh từ | 名词 | Chữ này thường làm lượng từ cho hoa hoặc vật tụ lại thành cụm, hoặc làm động từ chỉ sự vây quanh, tụ tập. | Lượng từ | 量词 | Đứng giữa số từ (hoặc 这/那) và danh từ: 一杯茶, 这本书. Mỗi danh từ đi với lượng từ riêng; 个 là lượng từ dùng chung phổ biến nhất. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('棱', '{"9000": "2891.0", "Chữ Trung Quốc": "棱", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 12 | nét | 木 | mộc | biểu nghĩa | gỗ | 夌 | lăng | biểu âm | lăng — cho âm léng | 棱 = 木(Mộc, biểu nghĩa: gỗ) + 夌 (Lăng, biểu âm: âm léng). Chữ hình thanh. Wiktionary: {{Han compound|木|夌|c1=s|c2=p|ls=psc}} và dẫn sang 稜 (dạng gốc). Nghĩa: góc cạnh của gỗ xẻ vuông; ẩn dụ: oai phong, cạnh sắc bén (棱角).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lăng\": 木 (gỗ) + 夌 (lăng, âm léng) — thanh gỗ xẻ vuông có góc cạnh sắc nét, như ''lăng'' (lăng mộ) cũng có cạnh góc uy nghi. | Gương Hán-Việt | lăng trong ''lăng giác'' (棱角 — góc cạnh) và ''lăng uy'' (棱威 — uy phong) | Mở khoá kiến thức | Biết 棱 (lăng) mở khoá: 棱角 (góc cạnh), 棱角分明 (cá tính rõ ràng), 棱镜 (lăng kính quang học).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Chữ hình thanh: 木 (mộc, biểu nghĩa: gỗ) + 夌 (lăng, biểu âm). Wiktionary dẫn sang 稜 để tra đầy đủ. Tiểu triện và Lục thư thông còn hình. Nghĩa gốc: gỗ xẻ thành thanh vuông, có góc cạnh. Nghĩa mở rộng: góc cạnh (hình học), oai phong (棱威), rắn chắc có khí phách (棱角分明). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "oai linh; góc, cạnh", "Hạng Tần Suất (Jun Da)": "2891.0", "Tần Suất % (Jun Da)": "99.0693206174", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 夌", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木夌", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "夌", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "棱", "Unihan_Traditional (Chữ Phồn thể)": "棱", "Pinyin_Xie": "léng", "Âm Hán Việt_Xie": "lăng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ để chỉ các góc cạnh của đồ vật hoặc kết hợp tạo từ ghép chỉ hình lăng trụ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('叩', '{"9000": "2892.0", "Chữ Trung Quốc": "叩", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 5 | nét | 口 | khẩu | biểu âm | miệng | 卩 | tiết | biểu nghĩa | người quỳ gối | 叩 = 口 (Khẩu, biểu âm) + 卩 (Tiết, biểu nghĩa: người quỳ gối). Chữ hình thanh — 卩 vẽ hình người quỳ rập đầu, cho nghĩa; 口 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khấu\": miệng (口) chạm đất khi người (卩) quỳ rập đầu — động tác kính cẩn nhất. | Gương Hán-Việt | \"khấu\" xuất hiện trong \"khấu đầu\" (rập đầu lạy), \"tam quỳ cửu khấu\" (ba lạy chín rập đầu). | Mở khoá kiến thức | Biết 叩 mở khoá: 叩门 (gõ cửa), 叩头 (rập đầu), 叩谢 (cúi đầu cảm ơn).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 叩 là chữ hình thanh: bộ 卩 (tiết) vẽ người quỳ gối làm thành phần biểu nghĩa — hành động rập đầu, quỳ lạy; bộ 口 (khẩu) cho âm đọc. Nghĩa gốc: gõ, đập; mở rộng sang rập đầu, cúi lạy, thưa hỏi. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "gõ (cửa); lạy, rập đầu", "Hạng Tần Suất (Jun Da)": "2892.0", "Tần Suất % (Jun Da)": "99.0704394572", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 卩", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口卩", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "卩", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "叩", "Unihan_Traditional (Chữ Phồn thể)": "叩", "Pinyin_Xie": "kòu", "Âm Hán Việt_Xie": "khấu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ thường đi kèm tân ngữ như cửa hoặc đầu để chỉ hành động gõ cửa hoặc dập đầu bái lạy. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('呐', '{"9000": "2893.0", "Chữ Trung Quốc": "呐", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 7 | nét | 口 | khẩu | biểu nghĩa | miệng, lời nói | 内 | nội | biểu âm | bên trong | 呐 = 口 (Khẩu, biểu nghĩa: miệng) + 内 (Nội, biểu âm). Chữ hình thanh — miệng (口) cho nghĩa nói năng; 内 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nột\": miệng (口) hướng vào bên trong (内) — người nói năng cẩn thận, giữ lời. | Gương Hán-Việt | \"nột\" ít dùng độc lập; trong tiếng Việt chữ Nôm 呐 ghi âm \"nói\". | Mở khoá kiến thức | Biết 呐 mở khoá: 呐喊 (hô hào, hét lên), chữ Nôm cho động từ \"nói\".", "Tự nguyên_Xie": "Theo Wiktionary, 呐 là chữ Nôm ghi âm từ \"nói\" trong tiếng Việt, cấu tạo hình thanh: 口 (khẩu, miệng — biểu nghĩa) + 内 (nội — biểu âm, gần âm \"nói\"). Chữ này chủ yếu dùng trong văn bản Nôm để ghi động từ \"nói\". | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nói năng cẩn trọng", "Hạng Tần Suất (Jun Da)": "2893.0", "Tần Suất % (Jun Da)": "99.0715572635", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 内", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口内", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "内", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "呐", "Unihan_Traditional (Chữ Phồn thể)": "吶", "Pinyin_Xie": "nà", "Âm Hán Việt_Xie": "niệt, nột", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Chữ này làm tính từ hoặc động từ để miêu tả trạng thái nói năng chậm rãi, không lưu loát. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('瑶', '{"9000": "2894.0", "Chữ Trung Quốc": "瑶", "Bộ thủ & thành phần_Xie": "Bộ thủ | 玉 | Số nét | 14 | nét | 王 | vương | biểu nghĩa | ngọc (bộ ngọc 玉) | 䍃 | biểu âm | phần cho âm, gồm 爪+缶 | 瑶 = 王/玉 (Vương/Ngọc, biểu nghĩa: ngọc quý) + 䍃 (biểu âm). Chữ có khả năng là hình thanh — bộ ngọc (王) cho nghĩa đá quý; phần còn lại cho âm. Anchor không có lsCodes rõ ràng nên phân loại dựa vào cấu trúc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"dao\": ngọc (王/玉) sáng lung linh như ánh trăng — đồ vật quý nhất của người xưa. | Gương Hán-Việt | \"dao\" trong \"Dao tộc\" (瑶族 — dân tộc Dao), \"dao cầm\" (đàn quý). | Mở khoá kiến thức | Biết 瑶 mở khoá: 瑶族 (dân tộc Dao), 瑶台 (đài ngọc, cung điện tiên), 瑶池 (ao tiên trong thần thoại).", "Tự nguyên_Xie": "Tiểu triện | Wiktionary không cung cấp phân tích hợp tự chi tiết cho 瑶. Dựa vào cấu trúc: bộ 王 (ngọc — biểu nghĩa) + phần phức hợp 䍃 (爪+缶). Nghĩa gốc: ngọc dao, loại đá quý. Mở rộng sang nghĩa: đẹp đẽ, quý giá. Tộc người Dao (瑶族) dùng chữ này. Chưa có nguồn học thuật xác nhận đường nét chữ cổ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ngọc dao", "Hạng Tần Suất (Jun Da)": "2894.0", "Tần Suất % (Jun Da)": "99.0726699019", "GavinGrover_Once (Chiết tự trực tiếp)": "王 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰王", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "瑶", "Unihan_Traditional (Chữ Phồn thể)": "瑤", "Pinyin_Xie": "yáo", "Âm Hán Việt_Xie": "dao", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Chữ này làm danh từ chỉ ngọc quý hoặc làm tính từ trong các từ ghép để chỉ vẻ đẹp thanh tao, quý phái. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('墅', '{"9000": "2895.0", "Chữ Trung Quốc": "墅", "Bộ thủ & thành phần_Xie": "Bộ thủ | 土 | Số nét | 14 | nét | 野 | dã | biểu âm | đồng nội, hoang dã — âm yě gần thự | 土 | thổ | biểu nghĩa | đất | 墅 = 野 (Dã, biểu âm) + 土 (Thổ, biểu nghĩa: đất); chữ hình thanh — ngôi nhà trên đất ở vùng ngoại ô, quê.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thự\": mảnh đất (土) ở vùng quê hoang dã (野 — dã) — biệt thự ngoại ô, biệt thự thự. | Gương Hán-Việt | \"thự\" trong 别墅 (biệt thự — biệt thự, nhà riêng sang trọng). | Mở khoá kiến thức | Biết 墅 (thự) mở khoá từ 别墅 (biệt thự) — từ tiếng Việt mượn thẳng từ Hán-Việt, ai cũng biết nhưng ít người nhận ra chữ.", "Tự nguyên_Xie": "Theo Wiktionary, 墅 là chữ hình thanh: 野 biểu âm, 土 biểu nghĩa đất. Có thể đọc là yě theo nghĩa cổ (đồng nghĩa với 野 là vùng quê). Nghĩa chính là biệt thự, nhà nghỉ ở ngoại ô hoặc vùng quê. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nhà để nghỉ ngơi", "Hạng Tần Suất (Jun Da)": "2895.0", "Tần Suất % (Jun Da)": "99.0737820235", "GavinGrover_Once (Chiết tự trực tiếp)": "野 + 土", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱野土", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "野", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "土", "Unihan_Simplified (Chữ Giản thể)": "墅", "Unihan_Traditional (Chữ Phồn thể)": "墅", "Pinyin_Xie": "shù", "Âm Hán Việt_Xie": "thự", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ thường kết hợp với các từ khác để chỉ loại hình nhà ở biệt thự hoặc trang viên nghỉ dưỡng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('莺', '{"9000": "2896.0", "Chữ Trung Quốc": "莺", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 10 | nét | 𦰯 | biểu âm | phần trên gồm 艹+卝 | 鸟 | điểu | biểu nghĩa | chim | 莺 = phần trên (艹草+卝mịch — biểu âm) + 鸟 (Điểu, biểu nghĩa: chim). Cấu trúc khả năng hình thanh — bộ điểu cho biết đây là loài chim; phần trên cho âm. Anchor không cung cấp lsCodes.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"oanh\": chim (鸟) hót giữa cỏ cây (艹) — tiếng oanh vàng líu lo mùa xuân. | Gương Hán-Việt | \"oanh\" trong \"hoàng oanh\" (chim vàng anh), \"oanh ca\" (tiếng hát như chim oanh). | Mở khoá kiến thức | Biết 莺 mở khoá: 黄莺 (hoàng oanh — chim vàng anh), 夜莺 (dạ oanh — con nightingale), 莺歌燕舞 (oanh ca yến vũ).", "Tự nguyên_Xie": "Tiểu triện | Wiktionary không phân tích hợp tự chi tiết cho 莺 (giản thể của 鶯). Nghĩa gốc: chim hoàng anh (oriole), tiếng hót trong trẻo. Bộ 鸟 xác nhận đây là tên loài chim. Chưa có nguồn học thuật xác nhận thêm. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chim oanh", "Hạng Tần Suất (Jun Da)": "2896.0", "Tần Suất % (Jun Da)": "99.0748941451", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "莺", "Unihan_Traditional (Chữ Phồn thể)": "鶯", "Pinyin_Xie": "yīng", "Âm Hán Việt_Xie": "oanh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ loài chim oanh, thường xuất hiện trong thơ ca để tả cảnh xuân. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('烫', '{"9000": "2897.0", "Chữ Trung Quốc": "烫", "Bộ thủ & thành phần_Xie": "Bộ thủ | 火 | Số nét | 10 | nét | 汤 | thang | biểu âm | nước nóng (gần âm tàng) | 火 | hoả | biểu nghĩa | lửa | 烫 là dạng giản thể của 燙 — hình thanh: 汤 (Thang, biểu âm — vốn 湯) + 火 (Hoả, biểu nghĩa: lửa). Nước nóng hoặc lửa làm bỏng, gốc nghĩa ''bỏng, làm nóng''.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"năng\": 汤 (canh nóng) + 火 (lửa) — nước sôi/lửa làm bỏng, đúng nghĩa ''bỏng, nóng, là ủi, uốn'' trong 烫, 烫衣服, 烫头发. | Gương Hán-Việt | ''năng'' (âm Hán-Việt cho 烫 — ít gặp trong tiếng Việt; gần ''nóng'' khẩu ngữ) | Mở khoá kiến thức | Nắm 烫 mở khoá khẩu ngữ HSK 5: 烫, 烫伤, 烫衣服, 烫头发.", "Tự nguyên_Xie": "Theo Wiktionary, 烫 là giản thể của 燙 — hình thanh: 湯/汤 (Thang, biểu âm — vốn nghĩa ''nước nóng, canh'') + 火 (lửa, biểu nghĩa). Vừa có nghĩa biểu âm vừa có nghĩa phụ trợ: nước nóng + lửa = nóng bỏng. Nghĩa gốc ''làm bỏng, làm nóng'', mở rộng sang ''là (ủi quần áo), uốn (tóc)'' trong 烫衣服, 烫头发. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bỏng; phỏng; sấy; hâm; là; ủi; uốn tóc", "Hạng Tần Suất (Jun Da)": "2897.0", "Tần Suất % (Jun Da)": "99.0760047163", "GavinGrover_Once (Chiết tự trực tiếp)": "汤 + 火", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱汤火", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "汤", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "火", "Unihan_Simplified (Chữ Giản thể)": "烫", "Unihan_Traditional (Chữ Phồn thể)": "燙", "Pinyin_Xie": "tàng", "Âm Hán Việt_Xie": "thang", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Chữ này làm tính từ chỉ nhiệt độ rất cao gây bỏng hoặc làm động từ chỉ hành động là ủi, uốn tóc, hâm nóng. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | Từ đơn | Từ vựng HSK 5: đốt, bỏng; nóng | / | tàng | / | đốt, bỏng; nóng | Xuất hiện trong lộ trình | HSK | HSK 5 | · | Thức ăn và đồ uống | New HSK | New HSK 7-9 | · | Thức ăn tôi", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蛙', '{"9000": "2898.0", "Chữ Trung Quốc": "蛙", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 12 | nét | 虫 | trùng | biểu nghĩa | sâu bọ, sinh vật nhỏ | 圭 | khuê | biểu âm | ngọc khuê (cho âm) | 蛙 = 虫 (Trùng, biểu nghĩa: sinh vật) + 圭 (Khuê, biểu âm). Chữ hình thanh — bộ trùng cho biết đây là loài động vật nhỏ; 圭 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"oa\": con ếch (虫) có đôi chân thoát nước như ngọc khuê (圭) — tiếng \"oa oa\" là âm thanh đặc trưng. | Gương Hán-Việt | \"oa\" trong \"oa thanh\" (tiếng ếch kêu), \"điền oa\" (ếch đồng). | Mở khoá kiến thức | Biết 蛙 mở khoá: 青蛙 (ếch xanh), 牛蛙 (ếch bò), 蛙泳 (bơi ếch).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 蛙 là chữ hình thanh: 虫 (trùng — biểu nghĩa, chỉ loài sinh vật) + 圭 (khuê — biểu âm). Nghĩa gốc và duy nhất: con ếch (frog). Chữ xuất hiện trong giáp cốt văn. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con ếch", "Hạng Tần Suất (Jun Da)": "2898.0", "Tần Suất % (Jun Da)": "99.0771152876", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 圭", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫圭", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "圭", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蛙", "Unihan_Traditional (Chữ Phồn thể)": "蛙", "Pinyin_Xie": "wā", "Âm Hán Việt_Xie": "oa", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ con ếch, thường đứng độc lập hoặc làm thành phần trong các từ ghép chỉ động vật. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('歹', '{"9000": "2899.0", "Chữ Trung Quốc": "歹", "Bộ thủ & thành phần_Xie": "Bộ thủ | 歹 | Số nét | 4 | nét | 歹 | tồi | tượng hình | hình vẽ xương người chết hoặc xương khô — biểu trưng cho cái xấu, cái chết | 歹 là bộ thủ kiêm chính tự: hình vẽ xương tàn hoặc xương người chết (biến thể của 死). Không có thành phần biểu âm. Dùng làm bộ thủ cho các chữ chỉ sự chết, xấu ác như 死, 殊, 残.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tồi\": chữ trông như xương tàn (夕 + nét ngang) — tồi tệ, xấu xa như hài cốt bỏ hoang. | Gương Hán-Việt | \"tồi\" trong 歹徒 (tồi đồ — tội phạm, kẻ xấu). | Mở khoá kiến thức | Biết 歹 (tồi) giúp nhận ra các chữ cùng bộ: 死 (tử), 残 (tàn), 歼 (tiêu diệt) — nhóm chữ chỉ hủy diệt, cái chết.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary không có glyph origin cho 歹. Dựa vào cấu trúc và bộ thủ: 歹 là biến thể rút gọn của 死 (tử — chết), hình vẽ xương tàn. Tiểu triện ghi nhận hình dạng này. Nghĩa là xấu xa, tà ác; cũng dùng làm bộ thủ chỉ sự chết chóc. Chưa có nguồn học thuật đầy đủ về giáp cốt. | Theo Wiktionary · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "947.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Nhất (001) Tịch (036)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Nhất (số 001 - một nét) ở trên chữ Tịch (số 036 - chiều tối/chỉ sự mờ ám). Là hình bộ xương tàn. Giải thích sự chuyển ý: Đây là chữ Tượng hình (hoặc Hội ý). Đãi (Ngạt) mang nghĩa xấu, không tốt, cũng có ý chỉ sự tử vong.", "Nghĩa Tiếng Việt_Xie": "việc xấu, tồi, trái, bậy", "Hạng Tần Suất (Jun Da)": "2899.0", "Tần Suất % (Jun Da)": "99.0782253421", "GavinGrover_Once (Chiết tự trực tiếp)": "一 + 夕", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱一夕", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "夕", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "一", "Unihan_Simplified (Chữ Giản thể)": "歹", "Unihan_Traditional (Chữ Phồn thể)": "歹", "Pinyin_Xie": "dǎi", "Âm Hán Việt_Xie": "đãi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Thường làm tính từ bổ nghĩa cho danh từ hoặc làm danh từ chỉ việc xấu, kẻ xấu. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('伶', '{"9000": "2900.0", "Chữ Trung Quốc": "伶", "Bộ thủ & thành phần_Xie": "Bộ thủ | 人 | Số nét | 7 | nét | 亻 | nhân | biểu nghĩa | người | 令 | lệnh | biểu âm | lệnh, âm líng gần linh | 伶 = 亻 (Nhân, biểu nghĩa: người) + 令 (Lệnh, biểu âm, âm líng); chữ hình thanh — người nhạc công, diễn viên trong cung.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"linh\": người (亻) linh hoạt như tiếng lệnh (令 — lệnh) vang vang — diễn viên tài lanh linh mẫn. | Gương Hán-Việt | \"linh\" trong 伶俐 (linh lợi — thông minh, lanh lợi). | Mở khoá kiến thức | Biết 伶 (linh) mở khoá 伶俐 (thông minh, lanh lợi) và 伶仃 (cô đơn lẻ loi) — HSK 6.", "Tự nguyên_Xie": "Theo Wiktionary, 伶 là chữ hình thanh: 人 biểu nghĩa người, 令 biểu âm. Nghĩa gốc là nhạc công hoặc diễn viên cung đình; sau mở rộng sang nghĩa cô đơn, lanh lợi (伶俐). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "diễn viên, người diễn, đào kép; lẻ loi, cô độc; nhanh nhẹn, lanh lợi", "Hạng Tần Suất (Jun Da)": "2900.0", "Tần Suất % (Jun Da)": "99.0793353965", "GavinGrover_Once (Chiết tự trực tiếp)": "亻 + 令", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰亻令", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "令", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "亻", "Unihan_Simplified (Chữ Giản thể)": "伶", "Unihan_Traditional (Chữ Phồn thể)": "伶", "Pinyin_Xie": "líng", "Âm Hán Việt_Xie": "linh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Thường dùng làm danh từ chỉ người diễn kịch hoặc tính từ trong các từ ghép chỉ sự lanh lợi, cô đơn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('葱', '{"9000": "2901.0", "Chữ Trung Quốc": "葱", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 12 | nét | 艹 | thảo | biểu nghĩa | cỏ, thực vật | 怱 | thông | biểu âm | vội vàng (cho âm) | 葱 = 艹 (Thảo, biểu nghĩa: thực vật) + 怱 (Thông, biểu âm). Chữ hình thanh — bộ thảo cho biết đây là loài cây; 怱 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thông\": cây hành (艹) mọc xanh thông đứng như mũi tên — mùi thơm xuyên suốt. | Gương Hán-Việt | \"thông\" trong \"thông thanh\" (màu xanh hành), các từ nấu ăn có 葱. | Mở khoá kiến thức | Biết 葱 mở khoá: 葱 (hành lá), 葱白 (hành trắng), 葱绿 (xanh tươi), 葱花 (hành hoa).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 葱 là chữ hình thanh: 艹 (thảo — biểu nghĩa, chỉ thực vật) + 怱 (thông — biểu âm). Đây là dị thể giản hoá của 蔥. Nghĩa gốc: cây hành (scallion, green onion). Mở rộng: màu xanh tươi (葱绿). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cây hành; màu xanh; tươi tốt", "Hạng Tần Suất (Jun Da)": "2901.0", "Tần Suất % (Jun Da)": "99.0804449342", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 怱", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹怱", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "怱", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "葱", "Unihan_Traditional (Chữ Phồn thể)": "蔥", "Pinyin_Xie": "cōng", "Âm Hán Việt_Xie": "thông", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Thường làm danh từ chỉ cây hành hoặc tính từ chỉ màu xanh tươi như lá hành. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | cōng | / | hành lá | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Thức ăn tôi", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('哮', '{"9000": "2902.0", "Chữ Trung Quốc": "哮", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 10 | nét | 口 | khẩu | biểu nghĩa | miệng, âm thanh | 孝 | hiếu | biểu âm | hiếu thảo (cho âm) | 哮 = 口 (Khẩu, biểu nghĩa: miệng/âm thanh) + 孝 (Hiếu, biểu âm). Anchor không có lsCodes; dựa cấu trúc khả năng hình thanh — 口 cho nghĩa âm thanh, 孝 cho âm gần.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hao\": miệng (口) phát ra tiếng gầm khàn khàn như tiếng thở khò khè của bệnh nhân hen suyễn. | Gương Hán-Việt | \"hao\" trong \"咆哮\" (bào hao — gầm thét), \"哮喘\" (hao suyễn — hen suyễn). | Mở khoá kiến thức | Biết 哮 mở khoá: 咆哮 (gầm thét), 哮喘 (hen suyễn), 哮吼 (gầm hú).", "Tự nguyên_Xie": "Tiểu triện | Wiktionary không cung cấp phân tích hợp tự cho 哮. Dựa vào cấu trúc: 口 (khẩu — biểu nghĩa, âm thanh phát ra từ miệng) + 孝 (hiếu — biểu âm). Nghĩa gốc: thở nặng, thở khò khè; mở rộng sang gầm, hú (咆哮). Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "gầm, hét, sủa", "Hạng Tần Suất (Jun Da)": "2902.0", "Tần Suất % (Jun Da)": "99.0815539551", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 孝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口孝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "孝", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "哮", "Unihan_Traditional (Chữ Phồn thể)": "哮", "Pinyin_Xie": "xiāo", "Âm Hán Việt_Xie": "hao", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước tân ngữ hoặc kết hợp thành từ ghép chỉ tiếng gầm rú, hen suyễn. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('眩', '{"9000": "2903.0", "Chữ Trung Quốc": "眩", "Bộ thủ & thành phần_Xie": "Bộ thủ | 目 | Số nét | 10 | nét | 目 | mục | biểu nghĩa | mắt | 玄 | huyền | biểu âm | sâu thẳm, huyền bí (cho âm) | 眩 = 目 (Mục, biểu nghĩa: mắt) + 玄 (Huyền, biểu âm). Chữ hình thanh — bộ mục cho biết liên quan đến mắt; 玄 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"huyễn\": mắt (目) nhìn vào chỗ huyền bí sâu thẳm (玄) — chóng mặt, hoa mắt không định hướng được. | Gương Hán-Việt | \"huyễn\" trong \"huyễn hoặc\" (眩惑 — làm mê hoặc), \"huyễn vận\" (眩晕 — chóng mặt). | Mở khoá kiến thức | Biết 眩 mở khoá: 眩晕 (chóng mặt), 眩惑 (mê hoặc), 目眩 (hoa mắt).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 眩 là chữ hình thanh: 目 (mục — biểu nghĩa, mắt) + 玄 (huyền — biểu âm). Nghĩa gốc: hoa mắt, chóng mặt, mắt nhìn không rõ. Mở rộng: mê hoặc, làm lóa mắt. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "hoa mắt", "Hạng Tần Suất (Jun Da)": "2903.0", "Tần Suất % (Jun Da)": "99.0826624592", "GavinGrover_Once (Chiết tự trực tiếp)": "目 + 玄", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰目玄", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "玄", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "目", "Unihan_Simplified (Chữ Giản thể)": "眩", "Unihan_Traditional (Chữ Phồn thể)": "眩", "Pinyin_Xie": "xuàn", "Âm Hán Việt_Xie": "huyễn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường làm tính từ miêu tả trạng thái đầu óc hoặc động từ chỉ sự mê hoặc, làm lóa mắt. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('坤', '{"9000": "2904.0", "Chữ Trung Quốc": "坤", "Bộ thủ & thành phần_Xie": "Bộ thủ | 土 | Số nét | 8 | nét | 土 | thổ | biểu nghĩa | đất | 申 | thân | biểu âm | con khỉ, giờ thân (cho âm) | 坤 = 土 (Thổ, biểu nghĩa: đất) + 申 (Thân, biểu âm). Cấu trúc khả năng hình thanh; tuy nhiên anchor ghi nhận dạng cổ 坤 viết là 川 trong bản Hán Thạch Kinh và 𡘩 trong trúc giản Tsinghua — có thể là tượng hình quẻ Khôn xoay 90°.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khôn\": đất (土) bền vững như quẻ Khôn — âm nhu, mẹ hiền che chở vạn vật. | Gương Hán-Việt | \"khôn\" trong \"càn khôn\" (乾坤 — trời đất), \"khôn đạo\" (đạo của đất, đức mẹ). | Mở khoá kiến thức | Biết 坤 mở khoá: 乾坤 (trời đất, vũ trụ), 坤卦 (quẻ Khôn), 坤角 (diễn viên nữ trong kinh kịch).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, trong các văn bản cổ (Hán Thạch Kinh, trúc giản Hải Hôn Hầu), 坤 được viết là 川 (có thể là quẻ Khôn xoay 90°). Dạng trúc giản Wangjiatai viết là 𡘩. Dạng hiện tại 坤 = 土 (thổ, đất) + 申 (thân, cho âm). Nghĩa: quẻ Khôn trong Kinh Dịch — tượng Địa (đất), mẹ, hành Thổ. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "quẻ Khôn (lục đoạn) trong Kinh Dịch (3 vạch đứt, tượng Địa (đất), tượng trưng cho cho người mẹ, hành Thổ, tuổi Mùi, hướng Đông Nam)", "Hạng Tần Suất (Jun Da)": "2904.0", "Tần Suất % (Jun Da)": "99.0837688962", "GavinGrover_Once (Chiết tự trực tiếp)": "土 + 申", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰土申", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "申", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "土", "Unihan_Simplified (Chữ Giản thể)": "坤", "Unihan_Traditional (Chữ Phồn thể)": "坤", "Pinyin_Xie": "kūn", "Âm Hán Việt_Xie": "khôn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Thường làm danh từ chỉ đất, quẻ Khôn hoặc tính từ chỉ những gì thuộc về phái nữ, người mẹ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('廓', '{"9000": "2905.0", "Chữ Trung Quốc": "廓", "Bộ thủ & thành phần_Xie": "Bộ thủ | 广 | Số nét | 13 | nét | 广 | nghiễm | biểu nghĩa | mái hiên rộng, không gian rộng lớn | 郭 | quách | biểu âm | thành quách, âm guō gần khuếch | 廓 = 广 (Nghiễm, biểu nghĩa: mái hiên rộng, không gian mở) + 郭 (Quách, biểu âm, âm guō); chữ hình thanh — không gian rộng mở, bao la.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khuếch\": mái nhà (广) rộng như tòa thành quách (郭 — quách) — khuếch trương, mở rộng ra mọi phía. | Gương Hán-Việt | \"khuếch\" trong 廓清 (khuếch thanh — dẹp sạch) và 輪廓 (luân khuếch — đường nét, hình dáng). | Mở khoá kiến thức | Biết 廓 (khuếch) mở khoá 轮廓 (đường nét, hình dáng tổng quát) — từ HSK 6 dùng cả trong nghệ thuật lẫn mô tả.", "Tự nguyên_Xie": "Lục thư thông | Theo Wiktionary, 廓 là chữ hình thanh: 广 biểu nghĩa không gian rộng, 郭 biểu âm. Nghĩa gốc là rộng lớn, mở ra, trống trải; sau mở rộng sang nghĩa đường nét (輪廓 — đường viền, hình dáng). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mở rộng ra, nới rộng", "Hạng Tần Suất (Jun Da)": "2905.0", "Tần Suất % (Jun Da)": "99.0848753332", "GavinGrover_Once (Chiết tự trực tiếp)": "广 + 郭", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴广郭", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "郭", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "广", "Unihan_Simplified (Chữ Giản thể)": "廓", "Unihan_Traditional (Chữ Phồn thể)": "廓", "Pinyin_Xie": "kuò", "Âm Hán Việt_Xie": "khuếch", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Danh từ | 名词 | Thường làm tính từ chỉ sự rộng lớn hoặc động từ mở rộng, danh từ chỉ đường nét giới hạn bên ngoài. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('讳', '{"9000": "2906.0", "Chữ Trung Quốc": "讳", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 6 | nét | 讠 | biểu nghĩa | bộ ngôn (言 giản thể), lời nói | 韦 | vi | biểu âm | da thuộc, âm wéi gần huý | 讳 = 讠 (bộ ngôn, biểu nghĩa: lời nói) + 韦 (Vi, biểu âm, âm wéi; phồn thể là 諱 với 韋); chữ hình thanh — lời nói bị kiêng kỵ, không được phép nói.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"huý\": lời nói (讠) bị che đậy như da thuộc bọc kín (韦 — vi) — huý kỵ, kiêng nói thẳng tên người. | Gương Hán-Việt | \"huý\" trong 忌讳 (kỵ huý — kiêng kỵ) và tên \"huý\" của vua chúa. | Mở khoá kiến thức | Biết 讳 (huý) mở khoá 忌讳 (điều kiêng kỵ) và 直言不讳 (nói thẳng không kiêng dè) — HSK 6.", "Tự nguyên_Xie": "Kim văn | Tiểu triện | Lục thư thông | Wiktionary ghi 讳 là giản thể của 諱, thay 言 bằng 讠 và 韋 bằng 韦. Kim văn, tiểu triện và lục thư thông đều ghi nhận chữ phồn thể 諱. Nghĩa là tên huý (tên người đã khuất hoặc bề trên không được phép gọi thẳng), sau mở rộng sang nghĩa kiêng kỵ, tránh né. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "kiêng, kỵ huý; chết; tên huý (tên người đã chết)", "Hạng Tần Suất (Jun Da)": "2906.0", "Tần Suất % (Jun Da)": "99.0859807366", "GavinGrover_Once (Chiết tự trực tiếp)": "讠 + 韦", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰讠韦", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "韦", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "讠", "Unihan_Simplified (Chữ Giản thể)": "讳", "Unihan_Traditional (Chữ Phồn thể)": "諱", "Pinyin_Xie": "huì", "Âm Hán Việt_Xie": "húy", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường làm động từ chỉ việc kiêng tránh nói đến hoặc danh từ chỉ tên riêng cần tránh phạm phải. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('啼', '{"9000": "2907.0", "Chữ Trung Quốc": "啼", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 12 | nét | 口 | khẩu | biểu nghĩa | miệng, âm thanh | 帝 | đế | biểu âm | đế vương (cho âm) | 啼 = 口 (Khẩu, biểu nghĩa: miệng) + 帝 (Đế, biểu âm). Chữ hình thanh — bộ khẩu cho biết liên quan đến âm thanh; 帝 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đề\": miệng (口) mở to như đế vương (帝) ban lệnh — tiếng khóc vang vọng, tiếng chim hót thanh. | Gương Hán-Việt | \"đề\" trong \"khốc đề\" (khóc lóc), \"đề minh\" (chim hót), \"yên đề\" (tiếng chim trong thơ cổ). | Mở khoá kiến thức | Biết 啼 mở khoá: 啼哭 (khóc lóc), 啼叫 (kêu, hót), 啼鸣 (chim hót), 猿啼 (tiếng vượn kêu).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 啼 là chữ hình thanh: 口 (khẩu — biểu nghĩa, miệng) + 帝 (đế — biểu âm). Nghĩa gốc: tiếng khóc, tiếng hót (chim). Mở rộng: cất tiếng kêu (động vật). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "754.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Khẩu (012) Đế (753)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Khẩu (số 012 - miệng) ở bên trái chữ Đế (số 753 - vua/chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Đế chỉ âm, bộ Khẩu chỉ ý. Đề là tiếng chim kêu, gà gáy hoặc tiếng người khóc.", "Nghĩa Tiếng Việt_Xie": "khóc lóc; hót (chim)", "Hạng Tần Suất (Jun Da)": "2907.0", "Tần Suất % (Jun Da)": "99.0870856232", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 帝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口帝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "帝", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "啼", "Unihan_Traditional (Chữ Phồn thể)": "啼", "Pinyin_Xie": "tí", "Âm Hán Việt_Xie": "đề", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ chỉ hành động khóc hoặc tiếng kêu, tiếng hót của chim muông. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('乍', '{"9000": "2908.0", "Chữ Trung Quốc": "乍", "Bộ thủ & thành phần_Xie": "Bộ thủ | 丿 | Số nét | 5 | nét | 乍 | sạ | tượng hình | hình chiếc rìu chặt gỗ — gốc của 柞 | 乍 là tượng hình — vẽ hình chiếc rìu chặt gỗ. Đây là dạng gốc của chữ 柞 (cây sồi). Theo thời gian, nghĩa chuyển sang: đột nhiên, thoạt đầu.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sạ\": nhát rìu chặt gỗ bất ngờ — 乍 gợi hành động đột ngột, thoắt cái đã xảy ra. | Gương Hán-Việt | \"sạ\" ít dùng độc lập trong tiếng Việt; trong Hán văn cổ dùng với nghĩa mới, thoạt. | Mở khoá kiến thức | Biết 乍 mở khoá: 乍看 (thoạt nhìn), 乍然 (đột nhiên), 乍暖还寒 (lúc ấm lúc lạnh — thời tiết giao mùa).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 乍 là chữ tượng hình (liushu: p) — vẽ chiếc rìu chặt gỗ. Đây là dạng gốc của 柞 (cây sồi). Nghĩa gốc đã mất; nghĩa hiện dùng: đột nhiên, thoạt đầu, mới vừa. Đây là chữ tạo muộn hơn so với chữ cổ giáp cốt/kim văn. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "614.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Phiệt (613) Nhân (009) Nhất (001) Nhị (002)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Nhân (người) cùng các nét gạch ngang (Nhất, Nhị) và sổ phẩy (Phiệt). Giải thích sự chuyển ý: Đây là chữ Hội ý. Con người sinh ra trong trời đất rồi bỗng nhiên biến mất. Sạ là dừng lại rồi biến mất, nghĩa là chợt, vừa mới, bỗng nhiên.", "Nghĩa Tiếng Việt_Xie": "mới; thoạt đầu; lúc đầu; đột nhiên; bỗng nhiên; thình lình; lúc; đột ngột", "Hạng Tần Suất (Jun Da)": "2908.0", "Tần Suất % (Jun Da)": "99.0881868923", "GavinGrover_Once (Chiết tự trực tiếp)": "No glyph available + 二", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴二", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "乍", "Unihan_Traditional (Chữ Phồn thể)": "乍", "Pinyin_Xie": "zhà", "Âm Hán Việt_Xie": "sạ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Phó từ | 副词 | Thường làm phó từ đứng trước động từ để chỉ hành động xảy ra đột ngột hoặc vừa mới bắt đầu. | Phó từ | 副词 | Bổ nghĩa cho động từ hoặc tính từ và luôn đứng TRƯỚC chúng — 都是, 很好. Không đứng sau như tiếng Việt và không bổ nghĩa cho danh từ.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('瓣', '{"9000": "2909.0", "Chữ Trung Quốc": "瓣", "Bộ thủ & thành phần_Xie": "Bộ thủ | 瓜 | Số nét | 19 | nét | 辛 | tân | biểu âm | cay đắng, vất vả (nhân đôi thành 辡, biểu âm cho biện) | 瓜 | qua | biểu nghĩa | dưa, quả | 辛 | tân | biểu âm | thành phần thứ hai của 辡 | 瓣 = 辡 (Biện, biểu âm — hai chữ 辛 kẹp nhau, âm biàn) + 瓜 (Qua, biểu nghĩa: quả dưa, múi quả); chữ hình thanh. Wiktionary ghi chú: phần biểu âm 辡 (hai dao kẹp hai tù nhân tố cáo nhau) mang ý phân biệt, tách rời → nghĩa múi, phần được tách ra.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"biện\": quả dưa (瓜) bị chia ra hai nửa cân nhau (辡 — biện) — từng cánh hoa, từng múi quả được tách biện rõ ràng. | Gương Hán-Việt | \"biện\" trong 花瓣 (hoa biện — cánh hoa). | Mở khoá kiến thức | Biết 瓣 (biện) mở khoá 花瓣 (cánh hoa) và cách đếm múi quả — từ miêu tả thiên nhiên HSK 6.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 瓣 là chữ hình thanh: 瓜 biểu nghĩa quả dưa, 辡 biểu âm. Phần biểu âm 辡 (hai 辛) vốn biểu trưng sự phân chia, phân biệt — từ đó mở rộng sang nghĩa múi, phần được tách ra từ quả. Tiểu triện ghi nhận hình dạng này. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cánh hoa; múi quả", "Hạng Tần Suất (Jun Da)": "2909.0", "Tần Suất % (Jun Da)": "99.0892860943", "GavinGrover_Once (Chiết tự trực tiếp)": "辡 + 瓜", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴辡瓜", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "辡", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "瓜", "Unihan_Simplified (Chữ Giản thể)": "瓣", "Unihan_Traditional (Chữ Phồn thể)": "瓣", "Pinyin_Xie": "bàn", "Âm Hán Việt_Xie": "biện", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Lượng từ | 量词 | Danh từ | 名词 | Thường làm lượng từ cho cánh hoa, múi tỏi, múi cam hoặc làm danh từ chỉ các bộ phận này. | Lượng từ | 量词 | Đứng giữa số từ (hoặc 这/那) và danh từ: 一杯茶, 这本书. Mỗi danh từ đi với lượng từ riêng; 个 là lượng từ dùng chung phổ biến nhất. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('矫', '{"9000": "2910.0", "Chữ Trung Quốc": "矫", "Bộ thủ & thành phần_Xie": "Bộ thủ | 矢 | Số nét | 11 | nét | 矢 | thỉ | biểu nghĩa | mũi tên — nghĩa nắn thẳng | 乔 | kiều | biểu âm | cao (cho âm) | 矫 = 矢 (Thỉ, biểu nghĩa: mũi tên — nắn thẳng như cán tên) + 乔 (Kiều, biểu âm). Chữ hình thanh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"kiểu\": mũi tên (矢) được nắn thẳng cao (乔) — hành động chỉnh sửa điều cong lệch. | Gương Hán-Việt | \"kiểu\" trong \"kiểu chính\" (矫正 — sửa chữa), \"kiểu tình\" (矫情 — giả tạo cầu kỳ). | Mở khoá kiến thức | Biết 矫 mở khoá: 矫正 (sửa chữa, chỉnh sửa), 矫情 (giả tạo, cầu kỳ), 矫健 (mạnh khoẻ, dũng mãnh).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 矫 là chữ hình thanh: 矢 (thỉ — biểu nghĩa, mũi tên: nắn cho thẳng như cán tên) + 喬 (kiều — biểu âm). Nghĩa gốc: nắn thẳng, chỉnh sửa. Mở rộng: mạnh mẽ, dũng cảm, giả tạo (矫情). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nắn thẳng ra", "Hạng Tần Suất (Jun Da)": "2910.0", "Tần Suất % (Jun Da)": "99.0903847795", "GavinGrover_Once (Chiết tự trực tiếp)": "矢 + 乔", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰矢乔", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "乔", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "矢", "Unihan_Simplified (Chữ Giản thể)": "矫", "Unihan_Traditional (Chữ Phồn thể)": "矯", "Pinyin_Xie": "jiǎo", "Âm Hán Việt_Xie": "kiểu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Thường làm động từ chỉ việc uốn nắn, sửa sai hoặc tính từ chỉ sự giả tạo, cường điệu. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('跋', '{"9000": "2911.0", "Chữ Trung Quốc": "跋", "Bộ thủ & thành phần_Xie": "Bộ thủ | 足 | Số nét | 12 | nét | 𧾷 | biểu nghĩa | bộ túc (chân) — liên quan đến chân, đi lại | 犮 | bạt | biểu âm | kéo ra (cho âm) | 跋 = 𧾷 (bộ túc, biểu nghĩa: chân, đi lại) + 犮 (Bạt, biểu âm). Chữ hình thanh — bộ túc cho biết liên quan đến chân; 犮 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bạt\": chân (足) kéo mạnh (犮) vượt qua địa hình khó — leo núi, vượt rừng, rồi viết lời bạt kể lại. | Gương Hán-Việt | \"bạt\" trong \"bạt văn\" (lời bạt), \"bạt hổ\" (chuyên quyền lộng hành). | Mở khoá kiến thức | Biết 跋 mở khoá: 跋涉 (lặn lội vượt khó), 跋扈 (lộng hành, tự tiện), 跋文 (lời bạt cuối sách).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 跋 là chữ hình thanh: 足 (túc — biểu nghĩa, chân) + 犮 (bạt — biểu âm). Nghĩa gốc: leo núi, vượt qua chướng ngại. Mở rộng: lời bạt cuối sách (跋文), tự tiện, lộng hành (跋扈). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "leo, trèo lên; lời tựa cuối sách", "Hạng Tần Suất (Jun Da)": "2911.0", "Tần Suất % (Jun Da)": "99.0914824311", "GavinGrover_Once (Chiết tự trực tiếp)": "⻊ + 犮", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰⻊犮", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "犮", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⻊", "Unihan_Simplified (Chữ Giản thể)": "跋", "Unihan_Traditional (Chữ Phồn thể)": "跋", "Pinyin_Xie": "bá", "Âm Hán Việt_Xie": "bạt", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường làm động từ trong từ ghép chỉ sự vượt núi băng rừng hoặc làm danh từ chỉ phần lời cuối sách. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('枉', '{"9000": "2912.0", "Chữ Trung Quốc": "枉", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 8 | nét | 木 | mộc | biểu nghĩa | gỗ, cây — vật có thể bị uốn cong | 王 | vương | biểu âm | vua, âm wáng gần uổng | 枉 = 木 (Mộc, biểu nghĩa: gỗ, cây cong) + 王 (Vương, biểu âm, âm wǎng); cấu trúc hình thanh suy ra từ thành phần, Wiktionary không xác định ls code dứt khoát.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"uổng\": cây gỗ (木) bị vua (王 — vương) bẻ cong — bị oan, bị xử sai, uổng công. | Gương Hán-Việt | \"uổng\" trong 冤枉 (oan uổng — đối xử bất công, oan ức). | Mở khoá kiến thức | Biết 枉 (uổng) mở khoá 冤枉 (oan uổng) và 枉费 (uổng phí — tốn công vô ích) — HSK 6.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Wiktionary ghi 枉 có glyph origin nhưng chỉ dẫn đến {{Han etym}} không có nội dung cụ thể. Dựa vào cấu trúc: 木 biểu nghĩa gỗ cong (nghĩa gốc có thể là cây cong, lệch), 王 biểu âm. Tiểu triện và lục thư thông ghi nhận. Nghĩa: cong, lệch; oan uổng (xử oan); uổng phí (làm vô ích). Chưa có nguồn học thuật xác nhận ls dứt khoát. | Theo Wiktionary · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tà, cong; oan uổng; uổng phí", "Hạng Tần Suất (Jun Da)": "2912.0", "Tần Suất % (Jun Da)": "99.0925800828", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 王", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木王", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "王", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "枉", "Unihan_Traditional (Chữ Phồn thể)": "枉", "Pinyin_Xie": "wǎng", "Âm Hán Việt_Xie": "uổng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Phó từ | 副词 | Động từ | 动词 | Thường làm phó từ đứng trước động từ để chỉ sự vô ích hoặc làm tính từ chỉ sự bất công. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Phó từ | 副词 | Bổ nghĩa cho động từ hoặc tính từ và luôn đứng TRƯỚC chúng — 都是, 很好. Không đứng sau như tiếng Việt và không bổ nghĩa cho danh từ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('梗', '{"9000": "2913.0", "Chữ Trung Quốc": "梗", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 11 | nét | 木 | mộc | biểu nghĩa | cây, gỗ | 更 | canh | biểu âm | thay đổi, canh giờ (cho âm) | 梗 = 木 (Mộc, biểu nghĩa: cây) + 更 (Canh, biểu âm). Chữ hình thanh — bộ mộc cho biết loài thực vật; 更 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cành\": thân cây (木) cứng như canh thức (更) — cành cây ngang bướng, cản trở đường đi. | Gương Hán-Việt | \"cành\" trong \"trở cành\" (làm cản trở), \"cành thẳng\" (ngay thẳng cứng cỏi). | Mở khoá kiến thức | Biết 梗 mở khoá: 梗塞 (tắc nghẽn), 作梗 (gây cản trở), 梗直 (thẳng thắn cứng cỏi), 梗概 (khái quát).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 梗 là chữ hình thanh: 木 (mộc — biểu nghĩa, cây) + 更 (canh — biểu âm). Nghĩa gốc: cuống cây, cành nhỏ. Mở rộng: ngoan cố, ngang bướng (梗直); cản trở, trở ngại (作梗); trong tiếng Trung hiện đại: câu chuyện cười/meme (梗). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cành cây; cánh bèo; ngang ngạnh; ngay thẳng", "Hạng Tần Suất (Jun Da)": "2913.0", "Tần Suất % (Jun Da)": "99.093676184", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 更", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木更", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "更", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "梗", "Unihan_Traditional (Chữ Phồn thể)": "梗", "Pinyin_Xie": "gěng", "Âm Hán Việt_Xie": "ngạnh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Tính từ | 形容词 | Thường làm danh từ chỉ cành cây hoặc làm động từ chỉ sự tắc nghẽn, cản trở. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('厕', '{"9000": "2914.0", "Chữ Trung Quốc": "厕", "Bộ thủ & thành phần_Xie": "Bộ thủ | 厂 | Số nét | 8 | nét | 厂 | hán | biểu nghĩa | vách núi, mái lán — nơi che kín | 则 | tắc | biểu âm | phần biểu âm — gần âm ''xí/tắc'' | 厕 là chữ hình thanh (psc): 厂 (mái lán/vách che, biểu nghĩa) + 则 (giản thể của 則, biểu âm). Nơi che kín dùng cho việc đi vệ sinh — nghĩa ''nhà xí, nhà vệ sinh''.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Xí\": chỗ có mái che (厂) theo nguyên tắc (则) kín đáo — đó là ''xí'', nhà xí, nhà vệ sinh. | Gương Hán-Việt | ''Xí'' trong ''nhà xí'', ''xí sở'' (nơi xí); cũng đọc ''trắc'' trong ''trắc thân'' (ở kề bên). | Mở khoá kiến thức | Biết 厕 mở khoá 厕所 (xí sở, nhà vệ sinh), 公共厕所 (công cộng xí sở), 男厕 (nam xí).", "Tự nguyên_Xie": "Theo Wiktionary, 厕 là chữ hình thanh gồm 广 (厂, mái lán/vách che — biểu nghĩa: chỗ kín đáo) + 則 (则, biểu âm). Nghĩa gốc ''nhà xí, nơi đi vệ sinh được che kín''. Đây là dạng giản thể (廁 → 厕). Cũng đọc ''cè'' khi nghĩa ''ở bên, kề bên'' (trắc). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nhà xí, nhà tiêu", "Hạng Tần Suất (Jun Da)": "2914.0", "Tần Suất % (Jun Da)": "99.0947707349", "GavinGrover_Once (Chiết tự trực tiếp)": "厂 + 则", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴厂则", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "则", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "厂", "Unihan_Simplified (Chữ Giản thể)": "厕", "Unihan_Traditional (Chữ Phồn thể)": "厠", "Pinyin_Xie": "cè", "Âm Hán Việt_Xie": "xí", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng độc lập hoặc kết hợp thành từ ghép chỉ nơi đi vệ sinh. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('琢', '{"9000": "2915.0", "Chữ Trung Quốc": "琢", "Bộ thủ & thành phần_Xie": "Bộ thủ | 玉 | Số nét | 12 | nét | 王 | vương | biểu nghĩa | bộ ngọc (玉 biến thể王), chỉ ngọc bích | 豖 | súc | biểu âm | lợn đang đi — âm zhú gần trác | 琢 = 王 (bộ ngọc, biểu nghĩa: ngọc bích — 玉 viết cạnh chữ thành 王) + 豖 (Súc, biểu âm, âm zhú); chữ hình thanh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trác\": bộ ngọc (王/玉) phải trác giũa mài dũa mới sáng — trác luyện, rèn giũa tài năng như mài ngọc. | Gương Hán-Việt | \"trác\" trong 琢磨 (trác ma — suy nghĩ, nghiền ngẫm; cũng là mài giũa). | Mở khoá kiến thức | Biết 琢 (trác) mở khoá 琢磨 (nghiền ngẫm, cân nhắc kỹ) và 精雕细琢 (tinh vi, tỉ mỉ) — HSK 6.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 琢 là chữ hình thanh: bộ 玉 (王 cạnh chữ) biểu nghĩa ngọc bích, 豖 biểu âm. Tiểu triện ghi nhận hình dạng này. Nghĩa gốc là chạm, mài, đục ngọc; mở rộng sang nghĩa rèn giũa, tu dưỡng phẩm chất. Thành ngữ kinh điển: 玉不琢不成器 (ngọc không mài không thành đồ quý). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mài giũa", "Hạng Tần Suất (Jun Da)": "2915.0", "Tần Suất % (Jun Da)": "99.0958647691", "GavinGrover_Once (Chiết tự trực tiếp)": "王 + 豖", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰王豖", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "豖", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "王", "Unihan_Simplified (Chữ Giản thể)": "琢", "Unihan_Traditional (Chữ Phồn thể)": "琢", "Pinyin_Xie": "zuó", "Âm Hán Việt_Xie": "trác", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ trong từ ghép chỉ việc gọt giũa ngọc đá hoặc suy ngẫm sâu sắc. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('讥', '{"9000": "2916.0", "Chữ Trung Quốc": "讥", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 4 | nét | 讠 | biểu nghĩa | bộ ngôn (言 giản thể), lời nói | 几 | cơ | biểu âm | bàn nhỏ, âm jī gần cơ | 讥 = 讠 (bộ ngôn, biểu nghĩa: lời nói) + 几 (Cơ, biểu âm, âm jī; phồn thể là 譏 với 幾); chữ hình thanh — lời nói chỉ trích, chê bai.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cơ\": lời nói (讠) sắc như lưỡi dao nhỏ (几 — cơ, cái bàn sắc góc) — cơ mỉa, chế giễu. | Gương Hán-Việt | \"cơ\" trong 讥笑 (cơ tiếu — chế nhạo) và 讥讽 (cơ phúng — mỉa mai). | Mở khoá kiến thức | Biết 讥 (cơ) mở khoá 讥笑 (chế nhạo) và 讥讽 (mỉa mai) — HSK 6.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Theo Wiktionary, chữ phồn thể 譏: 言 biểu nghĩa lời nói, 幾 biểu âm. Tiểu triện và lục thư thông ghi nhận. Nghĩa là chế giễu, chỉ trích; cổ văn còn có nghĩa thẩm vấn, tra hỏi. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "quở trách, chê; hỏi vặn, kiểm tra", "Hạng Tần Suất (Jun Da)": "2916.0", "Tần Suất % (Jun Da)": "99.0969572528", "GavinGrover_Once (Chiết tự trực tiếp)": "讠 + 几", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰讠几", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "几", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "讠", "Unihan_Simplified (Chữ Giản thể)": "讥", "Unihan_Traditional (Chữ Phồn thể)": "譏", "Pinyin_Xie": "jī", "Âm Hán Việt_Xie": "cơ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước tân ngữ để biểu thị sự chế giễu hoặc châm chọc. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('釉', '{"9000": "2917.0", "Chữ Trung Quốc": "釉", "Bộ thủ & thành phần_Xie": "Bộ thủ | 釆 | Số nét | 12 | nét | 采 | biện | biểu nghĩa | màu sắc, hái (cho nghĩa màu men) | 由 | do | biểu âm | do, từ (cho âm) | 釉 = 采 (Biện, biểu nghĩa: màu sắc) + 由 (Do, biểu âm). Chữ hình thanh — 采 cho nghĩa liên quan đến màu sắc; 由 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"dứu\": màu sắc (采) nung chảy cùng gốc do (由) — men sứ bóng loáng phủ lên đồ gốm. | Gương Hán-Việt | \"dứu\" ít dùng trong tiếng Việt hiện đại; trong gốm sứ học dùng \"men\" thay thế. | Mở khoá kiến thức | Biết 釉 mở khoá: 釉料 (men gốm), 上釉 (tráng men), 釉色 (màu men).", "Tự nguyên_Xie": "Theo Wiktionary, 釉 là chữ hình thanh: 采 (biện — biểu nghĩa, màu sắc) + 由 (do — biểu âm). Nghĩa gốc và duy nhất: men gốm sứ (glaze) — lớp phủ bóng trên đồ gốm. Chưa tìm thấy dạng chữ cổ. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "men làm sứ", "Hạng Tần Suất (Jun Da)": "2917.0", "Tần Suất % (Jun Da)": "99.0980492198", "GavinGrover_Once (Chiết tự trực tiếp)": "釆 + 由", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰釆由", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "由", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "釆", "Unihan_Simplified (Chữ Giản thể)": "釉", "Unihan_Traditional (Chữ Phồn thể)": "釉", "Pinyin_Xie": "yòu", "Âm Hán Việt_Xie": "dứu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng sau các từ chỉ chất liệu để chỉ lớp men tráng trên đồ gốm. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('窟', '{"9000": "2918.0", "Chữ Trung Quốc": "窟", "Bộ thủ & thành phần_Xie": "Bộ thủ | 穴 | Số nét | 13 | nét | 穴 | huyệt | biểu nghĩa | hang, hố | 屈 | khuất | biểu âm | cong, khuất (cho âm) | 窟 = 穴 (Huyệt, biểu nghĩa: hang, hố) + 屈 (Khuất, biểu âm). Chữ hình thanh — bộ huyệt cho biết là hang, hầm; 屈 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quật\": hang (穴) khuất kín (屈) trong lòng đất — sào huyệt bí mật, hang động sâu tối. | Gương Hán-Việt | \"quật\" trong \"động quật\" (hang động), \"quật trạch\" (hang ổ, chỗ ở tạm bợ). | Mở khoá kiến thức | Biết 窟 mở khoá: 石窟 (hang đá — như Mạc Cao Quật), 窟窿 (lỗ hổng), 巢窟 (sào huyệt).", "Tự nguyên_Xie": "Theo Wiktionary, 窟 là chữ hình thanh: 穴 (huyệt — biểu nghĩa, hang, hố) + 屈 (khuất — biểu âm). Nghĩa gốc: cái hang, nhà hầm. Mở rộng: sào huyệt, chỗ ẩn náu. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái hang, nhà hầm", "Hạng Tần Suất (Jun Da)": "2918.0", "Tần Suất % (Jun Da)": "99.0991391197", "GavinGrover_Once (Chiết tự trực tiếp)": "穴 + 屈", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱穴屈", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "屈", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "穴", "Unihan_Simplified (Chữ Giản thể)": "窟", "Unihan_Traditional (Chữ Phồn thể)": "窟", "Pinyin_Xie": "kū", "Âm Hán Việt_Xie": "quật", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ hang hốc tự nhiên hoặc nơi trú ẩn của người và động vật. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('敛', '{"9000": "2919.0", "Chữ Trung Quốc": "敛", "Bộ thủ & thành phần_Xie": "Bộ thủ | 攴 | Số nét | 11 | nét | 佥 | thiêm | biểu âm | tất cả cùng (cho âm) | 攴 | phộc | biểu nghĩa | đánh nhẹ, hành động có chủ ý | 敛 là giản thể của 斂 = 佥 (Thiêm, biểu âm) + 攴 (Phộc, biểu nghĩa: hành động). Anchor ghi lsCodes rỗng — khả năng hình thanh dựa cấu trúc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"liễm\": hành động (攴) gom tất cả (佥) về một chỗ — thu gom, vén lại, kiềm chế. | Gương Hán-Việt | \"liễm\" trong \"thu liễm\" (thu gom), \"liễm dung\" (kiềm chế biểu hiện). | Mở khoá kiến thức | Biết 敛 mở khoá: 收敛 (tự kiềm chế), 敛财 (vơ vét của cải), 敛迹 (thu mình lại).", "Tự nguyên_Xie": "Tiểu triện | Wiktionary ghi 敛 là giản thể của 斂, dùng 佥 thay cho 僉. 斂 = 僉 (thiêm — biểu âm) + 攴 (phộc — biểu nghĩa). Nghĩa gốc: thu gom lại, vén lên. Mở rộng: thu thuế, kiềm chế bản thân (收敛). | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thu góp lại; vén lên", "Hạng Tần Suất (Jun Da)": "2919.0", "Tần Suất % (Jun Da)": "99.100227986", "GavinGrover_Once (Chiết tự trực tiếp)": "佥 + ⺙", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰佥⺙", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "佥", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺙", "Unihan_Simplified (Chữ Giản thể)": "敛", "Unihan_Traditional (Chữ Phồn thể)": "斂", "Pinyin_Xie": "liǎn", "Âm Hán Việt_Xie": "liễm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước danh từ để chỉ hành động thu gom tiền của hoặc kiềm chế cảm xúc. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('轼', '{"9000": "2920.0", "Chữ Trung Quốc": "轼", "Bộ thủ & thành phần_Xie": "Bộ thủ | 車 | Số nét | 10 | nét | 车 | xa | biểu nghĩa | xe | 式 | thức | biểu âm | hình thức, chuẩn mực (cho âm) | 轼 = 车 (Xa, biểu nghĩa: xe) + 式 (Thức, biểu âm). Chữ hình thanh — bộ xa cho biết liên quan đến xe; 式 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thức\": xe (车) có thanh ngang theo chuẩn thức (式) — đòn tựa phía trước xe thời cổ để bày tỏ kính lễ. | Gương Hán-Việt | \"thức\" xuất hiện trong tên riêng: Tô Thức (蘇軾 — nhà thơ Tô Đông Pha thời Tống). | Mở khoá kiến thức | Biết 轼 mở khoá: hiểu tên riêng 苏轼 (Tô Thức — Tô Đông Pha), các từ Hán văn cổ về xe ngựa.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 轼 là chữ hình thanh: 車 (xa — biểu nghĩa, xe) + 式 (thức — biểu âm). Nghĩa gốc: thanh ngang phía trước xe ngựa (cổ đại) để người ngồi tựa hoặc nắm khi đứng chào. Ít dùng trong tiếng Trung hiện đại. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đòn ngang trước xe", "Hạng Tần Suất (Jun Da)": "2920.0", "Tần Suất % (Jun Da)": "99.1013132347", "GavinGrover_Once (Chiết tự trực tiếp)": "车 + 式", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰车式", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "式", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "车", "Unihan_Simplified (Chữ Giản thể)": "轼", "Unihan_Traditional (Chữ Phồn thể)": "軾", "Pinyin_Xie": "shì", "Âm Hán Việt_Xie": "thức", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ trong văn ngôn chỉ bộ phận tay vịn trên xe ngựa cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('庐', '{"9000": "2921.0", "Chữ Trung Quốc": "庐", "Bộ thủ & thành phần_Xie": "Bộ thủ | 广 | Số nét | 7 | nét | 广 | nghiễm | biểu nghĩa | mái nhà, công trình | 户 | hộ | biểu âm | cửa, hộ gia đình (cho âm) | 庐 là giản thể của 廬 = 广 (Nghiễm, biểu nghĩa: mái nhà) + 户 (Hộ, biểu âm). Anchor lsCodes rỗng; dựa cấu trúc khả năng hình thanh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lư\": mái nhà (广) đơn sơ như cánh cửa (户) — túp lều tranh, chỗ trú nơi đồng ruộng. | Gương Hán-Việt | \"lư\" trong \"lư xá\" (nhà tranh), \"thảo lư\" (草庐 — lều tranh, điển tích Khổng Minh ở lều tranh). | Mở khoá kiến thức | Biết 庐 mở khoá: 草庐 (lều tranh — điển tích Tam Quốc), 庐山 (núi Lư Sơn), 庐舍 (nhà tranh).", "Tự nguyên_Xie": "Tiểu triện | Wiktionary ghi 庐 là giản thể của 廬 (dùng 卢 thay phần phức tạp). 廬 = bộ 广 (nghiễm — mái nhà, biểu nghĩa) + phần biểu âm. Nghĩa gốc: nhà tranh, lều tạm ở ngoài đồng; lều gác. Mở rộng: nơi ở giản dị. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nhà tranh, lều ở ngoài đồng; lều gác", "Hạng Tần Suất (Jun Da)": "2921.0", "Tần Suất % (Jun Da)": "99.1023969332", "GavinGrover_Once (Chiết tự trực tiếp)": "广 + 户", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴广户", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "户", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "广", "Unihan_Simplified (Chữ Giản thể)": "庐", "Unihan_Traditional (Chữ Phồn thể)": "廬", "Pinyin_Xie": "lú", "Âm Hán Việt_Xie": "lư", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ ngôi nhà nhỏ đơn sơ hoặc lều tạm ở vùng nông thôn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('胚', '{"9000": "2922.0", "Chữ Trung Quốc": "胚", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 9 | nét | 月 | nguyệt | biểu nghĩa | bộ nhục (肉) — thịt, cơ thể | 丕 | phi | biểu âm | lớn, vĩ đại (cho âm) | 胚 = 月/肉 (Nguyệt/Nhục, biểu nghĩa: cơ thể, mô) + 丕 (Phi, biểu âm). Anchor lsCodes rỗng; dựa cấu trúc khả năng hình thanh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phôi\": cơ thể (月/肉) mới bắt đầu hình thành lớn lên (丕) — phôi thai nhỏ bé ban đầu. | Gương Hán-Việt | \"phôi\" trong \"phôi thai\" (胚胎 — phôi thai), \"phôi nha\" (胚芽 — mầm phôi). | Mở khoá kiến thức | Biết 胚 mở khoá: 胚胎 (phôi thai), 胚芽 (mầm phôi), 胚珠 (noãn châu), 受精卵 (trứng đã thụ tinh).", "Tự nguyên_Xie": "Tiểu triện | Wiktionary không phân tích hợp tự chi tiết cho 胚. Dựa vào cấu trúc: 月/肉 (nhục — biểu nghĩa, mô cơ thể) + 丕 (phi — biểu âm). Nghĩa gốc: phôi thai, mầm sống chưa hình thành đầy đủ. Chưa có nguồn học thuật xác nhận thêm. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bào thai; vật chưa làm xong", "Hạng Tần Suất (Jun Da)": "2922.0", "Tần Suất % (Jun Da)": "99.1034785645", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 丕", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月丕", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "丕", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "胚", "Unihan_Traditional (Chữ Phồn thể)": "肧", "Pinyin_Xie": "pēi", "Âm Hán Việt_Xie": "phôi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng trước hoặc sau các danh từ khác để chỉ trạng thái ban đầu của sự sống hoặc vật thể. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('呻', '{"9000": "2923.0", "Chữ Trung Quốc": "呻", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 8 | nét | 口 | khẩu | biểu nghĩa | miệng, âm thanh phát ra | 申 | thân | biểu âm | thân (địa chi thứ 9), âm shēn | 呻 = 口 (Khẩu, biểu nghĩa: miệng) + 申 (Thân, biểu âm, âm shēn); cấu trúc có thể là hình thanh, Wiktionary không xác định ls code dứt khoát.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thân\": miệng (口) kéo dài âm thanh như địa chi 申 (thân) — rên thân thân, tiếng rên rỉ kéo dài. | Gương Hán-Việt | \"thân\" trong 呻吟 (thân ngâm — rên rỉ). | Mở khoá kiến thức | Biết 呻 (thân) mở khoá 呻吟 (rên rỉ) và thành ngữ 无病呻吟 (than vãn vô cớ) — HSK 6.", "Tự nguyên_Xie": "Wiktionary có phát âm chi tiết nhưng không ghi rõ ls code cho 呻. Dựa vào cấu trúc: 口 biểu nghĩa miệng, 申 biểu âm. Nghĩa gốc là ngâm ngợi, đọc có âm điệu; sau mở rộng sang nghĩa rên rỉ, rên la. Tiếng Quảng Đông còn dùng theo nghĩa phàn nàn. Chưa có nguồn học thuật xác nhận ls dứt khoát. | Theo Wiktionary · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "rên rỉ; rên", "Hạng Tần Suất (Jun Da)": "2923.0", "Tần Suất % (Jun Da)": "99.104559679", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 申", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口申", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "申", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "呻", "Unihan_Traditional (Chữ Phồn thể)": "呻", "Pinyin_Xie": "shēn", "Âm Hán Việt_Xie": "thân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này thường làm động từ đứng trước tân ngữ hoặc kết hợp thành từ ghép như thân ngâm để chỉ tiếng rên rỉ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('绰', '{"9000": "2924.0", "Chữ Trung Quốc": "绰", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 11 | nét | 纟 | mịch | biểu nghĩa | tơ, sợi — liên quan đến dệt | 卓 | trác | biểu âm | xuất sắc, cao vời (cho âm) | 绰 là giản thể của 綽 = 纟 (Mịch, biểu nghĩa: tơ sợi) + 卓 (Trác, biểu âm). Anchor lsCodes rỗng; dựa cấu trúc khả năng hình thanh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"xước\": sợi tơ (纟) mềm mại cao vút (卓) — dáng điệu thong thả uyển chuyển như lụa bay. | Gương Hán-Việt | \"xước\" trong \"xước hiệu\" (biệt hiệu), các từ chỉ phong thái rộng rãi. | Mở khoá kiến thức | Biết 绰 mở khoá: 绰号 (biệt hiệu, nickname), 绰绰有余 (dư dả, thừa thãi), 绰约 (uyển chuyển thướt tha).", "Tự nguyên_Xie": "Tiểu triện | Wiktionary ghi 绰 là giản thể của 綽 (dùng 纟 thay 糹). 綽 = 糹 (mịch — biểu nghĩa, tơ, liên quan đến sự mềm mại, rộng rãi) + 卓 (trác — biểu âm). Nghĩa gốc: rộng rãi, thong thả. Mở rộng: biệt hiệu (绰号), phong thái uyển chuyển. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thong thả; rộng rãi", "Hạng Tần Suất (Jun Da)": "2924.0", "Tần Suất % (Jun Da)": "99.1056392431", "GavinGrover_Once (Chiết tự trực tiếp)": "纟 + 卓", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰纟卓", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "卓", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "纟", "Unihan_Simplified (Chữ Giản thể)": "绰", "Unihan_Traditional (Chữ Phồn thể)": "綽", "Pinyin_Xie": "chuò", "Âm Hán Việt_Xie": "xước", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này thường làm tính từ bổ nghĩa cho danh từ hoặc kết hợp thành từ ghép như xước ước, phong xước. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('扼', '{"9000": "2925.0", "Chữ Trung Quốc": "扼", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 7 | nét | 扌 | thủ | biểu nghĩa | tay | 厄 | ách | biểu âm | tai họa, chỗ hiểm (cho âm) | 扼 = 扌 (Thủ, biểu nghĩa: tay) + 厄 (Ách, biểu âm). Chữ hình thanh — bộ thủ cho biết hành động của tay; 厄 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ách\": bàn tay (扌) siết vào chỗ hiểm (厄) — bóp chặt, kiểm soát yết hầu. | Gương Hán-Việt | \"ách\" trong \"ách thủ\" (扼守 — trấn giữ), \"ách chế\" (扼制 — kiềm chế, chặn đứng). | Mở khoá kiến thức | Biết 扼 mở khoá: 扼守 (trấn giữ yếu địa), 扼制 (kiềm chế), 扼杀 (bóp chết, tiêu diệt), 扼要 (tóm lược trọng yếu).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 扼 là chữ hình thanh: 手/扌 (thủ — biểu nghĩa, tay) + 厄 (ách — biểu âm). Nghĩa gốc: bóp cổ, nắm chặt. Mở rộng: kiểm soát, trấn giữ (扼守), bóp nghẹt. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bóp, chèn ép, giữ", "Hạng Tần Suất (Jun Da)": "2925.0", "Tần Suất % (Jun Da)": "99.1067177737", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 厄", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌厄", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "厄", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "扼", "Unihan_Traditional (Chữ Phồn thể)": "扼", "Pinyin_Xie": "è", "Âm Hán Việt_Xie": "ách", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ thường mang tân ngữ chỉ vị trí hiểm yếu hoặc hành động khống chế như ách thủ, ách sát. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('懿', '{"9000": "2926.0", "Chữ Trung Quốc": "懿", "Bộ thủ & thành phần_Xie": "Bộ thủ | 心 | Số nét | 22 | nét | 壹 | nhất | biểu âm | một (dạng trang trọng, cho âm) | 忄/心 | tứ | biểu nghĩa | lòng, tâm ý | 懿 = 壹 (Nhất, biểu âm) + 㣺/心 (Tứ, biểu nghĩa: lòng). Anchor lsCodes rỗng. Dựa cấu trúc: phần tâm ý bên dưới cho nghĩa đức hạnh tốt đẹp; phần trên cho âm. Khả năng hình thanh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ý\": lòng (心) thuần nhất (壹) hướng thiện — đức hạnh cao quý, phẩm chất đáng kính ngưỡng. | Gương Hán-Việt | \"ý\" trong \"懿旨\" (chỉ dụ Hoàng Thái hậu), \"懿德\" (đức hạnh tốt đẹp). | Mở khoá kiến thức | Biết 懿 mở khoá: 懿旨 (ý chỉ — chỉ dụ của Hoàng Thái hậu), 懿德 (đức hạnh cao quý), 嘉言懿行 (lời hay hành động đẹp).", "Tự nguyên_Xie": "Tiểu triện | Wiktionary không phân tích hợp tự chi tiết cho 懿. Dựa vào cấu trúc: phần trên (壹 hoặc dạng biến thể) cho âm; phần dưới 㣺/心 (tâm, lòng — biểu nghĩa). Nghĩa gốc: đức hạnh tốt đẹp, cao quý, đáng kính. Dùng nhiều trong văn ngôn và tên riêng. Chưa có nguồn học thuật xác nhận thêm. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tốt lành", "Hạng Tần Suất (Jun Da)": "2926.0", "Tần Suất % (Jun Da)": "99.1077957875", "GavinGrover_Once (Chiết tự trực tiếp)": "壹 + 恣", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰壹恣", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "恣", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "壹", "Unihan_Simplified (Chữ Giản thể)": "懿", "Unihan_Traditional (Chữ Phồn thể)": "懿", "Pinyin_Xie": "yì", "Âm Hán Việt_Xie": "ý", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này làm tính từ thường dùng để ca ngợi đức hạnh của phụ nữ hoặc người bề trên trong văn cổ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('炯', '{"9000": "2927.0", "Chữ Trung Quốc": "炯", "Bộ thủ & thành phần_Xie": "Bộ thủ | 火 | Số nét | 9 | nét | 火 | hoả | biểu nghĩa | lửa, sáng | 囧 | quýnh | biểu âm | cửa sổ sáng (cho âm) | 炯 = 火 (Hoả, biểu nghĩa: lửa, sáng) + 囧 (Quýnh, biểu âm). Anchor lsCodes rỗng; dựa cấu trúc khả năng hình thanh — bộ hoả cho nghĩa sáng rực; 囧 cho âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quýnh\": lửa (火) chiếu qua cửa sổ sáng (囧) — ánh mắt sáng rực như ngọn lửa. | Gương Hán-Việt | \"quýnh\" trong \"quýnh mục\" (炯目 — đôi mắt sáng), \"quýnh quýnh\" (炯炯 — sáng rực, tinh anh). | Mở khoá kiến thức | Biết 炯 mở khoá: 炯炯有神 (ánh mắt sáng rực tinh anh), 炯目 (đôi mắt sáng), 明炯 (sáng rõ).", "Tự nguyên_Xie": "Wiktionary không phân tích hợp tự chi tiết cho 炯. Dựa vào cấu trúc: 火 (hoả — biểu nghĩa, lửa, ánh sáng) + 囧 (quýnh — biểu âm, cũng có nghĩa cửa sổ sáng). Nghĩa gốc: sáng chói, rực rỡ. Chưa có nguồn học thuật xác nhận thêm. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sáng chói, soi tỏ", "Hạng Tần Suất (Jun Da)": "2927.0", "Tần Suất % (Jun Da)": "99.1088727677", "GavinGrover_Once (Chiết tự trực tiếp)": "火 + 冋", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰火冋", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "冋", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "火", "Unihan_Simplified (Chữ Giản thể)": "炯", "Unihan_Traditional (Chữ Phồn thể)": "炯", "Pinyin_Xie": "jiǒng", "Âm Hán Việt_Xie": "quýnh, huỳnh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này làm tính từ thường dùng để miêu tả ánh mắt sáng ngời hoặc sự việc rõ ràng như quýnh quýnh, quýnh giới. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('竿', '{"9000": "2928.0", "Chữ Trung Quốc": "竿", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 9 | nét | 竹 | trúc | biểu nghĩa | tre | 干 | can | biểu âm | gốc, can (cho âm) | 竿 = 竹 (Trúc, biểu nghĩa: tre) + 干 (Can, biểu âm). Chữ hình thanh — bộ trúc cho biết làm từ tre; 干 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"can\": cây tre (竹) thẳng như gốc cây (干) — cần câu, sào tre dài thẳng. | Gương Hán-Việt | \"can\" trong \"trúc can\" (竹竿 — cây tre), \"câu can\" (cần câu). | Mở khoá kiến thức | Biết 竿 mở khoá: 竹竿 (cây tre), 钓竿 (cần câu), 旗竿 (cột cờ), 百尺竿头 (đỉnh cao thành công).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 竿 là chữ hình thanh: 竹 (trúc — biểu nghĩa, tre) + 干 (can — biểu âm). Nghĩa gốc: cần câu tre, cây sào tre dài. Mở rộng: bất kỳ cây sào, cần dài. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1241.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Trúc (108) Can (051)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Trúc (số 108 - tre trúc/chỉ ý) ở trên chữ Can (số 051 - can thiệp/chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Can chỉ âm, bộ Trúc chỉ ý. Can là cái cần, cái sào làm bằng tre (cần câu).", "Nghĩa Tiếng Việt_Xie": "cái cần câu", "Hạng Tần Suất (Jun Da)": "2928.0", "Tần Suất % (Jun Da)": "99.1099492311", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 干", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮干", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "干", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "竿", "Unihan_Traditional (Chữ Phồn thể)": "竿", "Pinyin_Xie": "gān", "Âm Hán Việt_Xie": "can", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ các vật dụng làm bằng tre có dạng ống dài như cần câu hoặc cây sào. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('慷', '{"9000": "2929.0", "Chữ Trung Quốc": "慷", "Bộ thủ & thành phần_Xie": "Bộ thủ | 心 | Số nét | 14 | nét | 忄 | tâm | biểu nghĩa | lòng, trái tim (心 viết cạnh chữ) | 康 | khang | biểu âm | khỏe mạnh, sung túc — âm kāng | 慷 = 忄 (Tâm, biểu nghĩa: lòng, cảm xúc) + 康 (Khang, biểu âm, âm kāng); chữ hình thanh. Wiktionary ghi chú: nguyên thủy viết là 忼, sau thêm 康 làm biểu âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khảng\": lòng (忄) mạnh khỏe sung túc (康 — khang) — khảng khái, hào phóng nhiệt tình không ngần ngại. | Gương Hán-Việt | \"khảng\" trong 慷慨 (khảng khái — hào phóng, nhiệt tình). | Mở khoá kiến thức | Biết 慷 (khảng) mở khoá 慷慨 (hào phóng) và 慷慨激昂 (hùng hồn phẫn khích) — HSK 6.", "Tự nguyên_Xie": "Theo Wiktionary, 慷 nguyên thủy là 忼, sau thêm 康 làm biểu âm, trở thành chữ hình thanh: 心 biểu nghĩa lòng, 康 biểu âm. Nghĩa chỉ dùng trong từ ghép 慷慨 (hào phóng, nhiệt huyết) và 慷慨激昂 (phẫn khích hùng tráng). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: khảng khái 慷慨,忼慨)", "Hạng Tần Suất (Jun Da)": "2929.0", "Tần Suất % (Jun Da)": "99.1110231106", "GavinGrover_Once (Chiết tự trực tiếp)": "忄 + 康", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰忄康", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "康", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "忄", "Unihan_Simplified (Chữ Giản thể)": "慷", "Unihan_Traditional (Chữ Phồn thể)": "慷", "Pinyin_Xie": "kāng", "Âm Hán Việt_Xie": "khảng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này làm tính từ thường kết hợp với khái để tạo thành từ ghép khảng khái chỉ khí phách hào hiệp. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('虞', '{"9000": "2930.0", "Chữ Trung Quốc": "虞", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虍 | Số nét | 13 | nét | 虍 | hô | biểu nghĩa | đầu hổ — liên quan đến thú dữ, sự cảnh giác | 吴 | ngô | biểu âm | nước Ngô (cho âm) | 虞 = 虍 (Hô, biểu nghĩa: đầu hổ — gợi sự cảnh giác) + 吴 (Ngô, biểu âm). Chữ hình thanh — bộ hô gợi cần đề phòng; 吴 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ngu\": đầu hổ (虍) nhắc nhở luôn đề phòng như Ngô (吴) — lo tính trước, không để bất ngờ. | Gương Hán-Việt | \"ngu\" trong \"bất ngu\" (không ngờ), \"ngu nhân\" (người lo lắng, người quản lý rừng núi thời cổ). | Mở khoá kiến thức | Biết 虞 mở khoá: 不虞 (bất ngờ, không lường trước), 虞诈 (lừa dối), 朝虞 (lo lắng từ sáng đến tối — sống trong lo âu).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 虞 là chữ hình thanh: 虍 (hô — biểu nghĩa, đầu hổ; gợi sự lo lắng, đề phòng) + 吳 (ngô — biểu âm). Nghĩa gốc: dự liệu trước, lo lắng đề phòng. Mở rộng: vui vẻ, yên ổn; tên nước Ngu thời cổ. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "dự liệu, tính toán trước; yên vui; họ Ngu, nước Ngu, đời nhà Ngu", "Hạng Tần Suất (Jun Da)": "2930.0", "Tần Suất % (Jun Da)": "99.1120938894", "GavinGrover_Once (Chiết tự trực tiếp)": "虍 + 吴", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴虍吴", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "吴", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虍", "Unihan_Simplified (Chữ Giản thể)": "虞", "Unihan_Traditional (Chữ Phồn thể)": "虞", "Pinyin_Xie": "yú", "Âm Hán Việt_Xie": "ngu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chữ này làm động từ chỉ sự lo liệu, đề phòng hoặc làm danh từ chỉ triều đại cổ, họ người. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('锤', '{"9000": "2931.0", "Chữ Trung Quốc": "锤", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 13 | nét | 钅 | kim | biểu nghĩa | bộ kim loại (金 giản thể) | 垂 | thuỳ | biểu âm | rũ xuống, âm chuí gần chuỳ | 锤 = 钅 (Kim, biểu nghĩa: kim loại) + 垂 (Thuỳ, biểu âm, âm chuí); chữ hình thanh. Chữ giản thể của 錘.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chuỳ\": kim loại (钅) rũ nặng xuống (垂 — thuỳ) — cái chuỳ, búa nặng giáng xuống mạnh. | Gương Hán-Việt | \"chuỳ\" trong 锤 (chuỳ — búa) và 锤子 (chuỳ tử — cái búa). | Mở khoá kiến thức | Biết 锤 (chuỳ) mở khoá 锤子 (búa) và các từ về dụng cụ thủ công — HSK 6.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary ghi 锤 là giản thể của 錘 (thay 釒 bằng 钅). Tiểu triện ghi nhận chữ phồn thể. Cấu trúc: 金 biểu nghĩa kim loại, 垂 biểu âm. Nghĩa là quả cân (vật kim loại nặng rủ xuống) và cái búa — công cụ kim loại nặng dùng để đập. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "quả cân; nặng; cái búa lớn", "Hạng Tần Suất (Jun Da)": "2931.0", "Tần Suất % (Jun Da)": "99.1131641515", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 垂", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅垂", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "垂", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "锤", "Unihan_Traditional (Chữ Phồn thể)": "錘", "Pinyin_Xie": "chuí", "Âm Hán Việt_Xie": "chuỳ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này làm danh từ chỉ công cụ gõ đập hoặc làm động từ với nghĩa nện, rèn luyện. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | chuí | / | búa | Xuất hiện trong lộ trình | HSK | HSK 6 | · | Xây dựng và cải tạo", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('栓', '{"9000": "2932.0", "Chữ Trung Quốc": "栓", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 10 | nét | 木 | mộc | biểu nghĩa | gỗ, cây | 全 | toàn | biểu âm | hoàn toàn (cho âm) | 栓 = 木 (Mộc, biểu nghĩa: gỗ) + 全 (Toàn, biểu âm). Chữ hình thanh — bộ mộc cho biết làm từ gỗ; 全 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"xuyên\": cái chốt gỗ (木) cài hoàn toàn (全) vào ổ — then cửa khoá chặt, không để lọt. | Gương Hán-Việt | \"xuyên\" trong \"huyết xuyên\" (血栓 — cục máu đông xuyên trong mạch). | Mở khoá kiến thức | Biết 栓 mở khoá: 血栓 (cục máu đông), 门栓 (then cửa), 栓塞 (tắc nghẽn mạch máu).", "Tự nguyên_Xie": "Theo Wiktionary, 栓 là chữ hình thanh: 木 (mộc — biểu nghĩa, gỗ) + 全 (toàn — biểu âm). Nghĩa gốc: cái chốt gỗ, cái then cài cửa. Mở rộng: nút chặn, van (trong y học: 血栓 — cục máu đông). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái then cài cửa", "Hạng Tần Suất (Jun Da)": "2932.0", "Tần Suất % (Jun Da)": "99.1142328631", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 全", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木全", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "全", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "栓", "Unihan_Traditional (Chữ Phồn thể)": "栓", "Pinyin_Xie": "shuān", "Âm Hán Việt_Xie": "thuyên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ các loại chốt cửa, nút chai hoặc các bộ phận có chức năng khóa, chặn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('桨', '{"9000": "2933.0", "Chữ Trung Quốc": "桨", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 10 | nét | 丬 | biểu nghĩa | mảnh gỗ (biến thể của 片/爿) | 夕 | tịch | biểu âm | buổi chiều — âm xī/jiǎng (thông qua 将) | 木 | mộc | biểu nghĩa | gỗ | 桨 (giản thể của 槳): cấu trúc phức, phần trên có 丬 và 夕 (hoặc 将 rút gọn), phần dưới là 木 (Mộc, biểu nghĩa: gỗ). Cấu trúc ls không được Wiktionary xác định rõ. Đây là công cụ bằng gỗ dùng để chèo thuyền.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tưởng\": khúc gỗ (木) được đẽo thành mái chèo để tưởng tượng vượt sóng — tưởng lướt, chèo thuyền. | Gương Hán-Việt | \"tưởng\" trong 桨 (tưởng — mái chèo); ít gặp trong từ Hán-Việt tiếng Việt. | Mở khoá kiến thức | Biết 桨 (tưởng) giúp nhận ra 船桨 (mái chèo thuyền) và 螺旋桨 (chân vịt, cánh quạt) — từ kỹ thuật và văn học HSK 6.", "Tự nguyên_Xie": "Wiktionary chỉ ghi phát âm và định nghĩa cho 槳, không ghi rõ cấu trúc hình thanh hay hội ý. Dựa vào thành phần: 木 biểu nghĩa gỗ, phần còn lại có thể là biểu âm. Nghĩa là mái chèo, cánh quạt. Chưa có nguồn học thuật xác nhận ls dứt khoát. | Theo Wiktionary · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mái chèo; cánh quạt (máy bay, tàu thuyền)", "Hạng Tần Suất (Jun Da)": "2933.0", "Tần Suất % (Jun Da)": "99.115301058", "GavinGrover_Once (Chiết tự trực tiếp)": "No glyph available + 木", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱木", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "桨", "Unihan_Traditional (Chữ Phồn thể)": "槳", "Pinyin_Xie": "jiǎng", "Âm Hán Việt_Xie": "tưởng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ dụng cụ dùng để chèo thuyền hoặc bộ phận đẩy của tàu thuyền. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | jiǎng | / | mái chèo | Xuất hiện trong lộ trình | HSK | HSK 6 | · | Vận chuyển", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蚊', '{"9000": "2934.0", "Chữ Trung Quốc": "蚊", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 10 | nét | 虫 | trùng | biểu nghĩa | sâu bọ, côn trùng | 文 | văn | biểu âm | chữ viết, hoa văn (cho âm) | 蚊 = 虫 (Trùng, biểu nghĩa: côn trùng) + 文 (Văn, biểu âm). Chữ hình thanh — bộ trùng cho biết là côn trùng; 文 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"văn\": côn trùng (虫) có hoa văn (文) trên cánh — con muỗi vằn với cánh có vân hoa. | Gương Hán-Việt | \"văn\" trong \"văn trùng\" (蚊虫 — muỗi và côn trùng), \"văn trướng\" (màn chống muỗi). | Mở khoá kiến thức | Biết 蚊 mở khoá: 蚊子 (con muỗi), 蚊帐 (màn chống muỗi), 蚊香 (nhang đuổi muỗi).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 蚊 là chữ hình thanh: 虫 (trùng — biểu nghĩa, côn trùng) + 文 (văn — biểu âm). Nghĩa gốc và duy nhất: con muỗi (mosquito). Thú vị: cả 文 (văn) và 蚊 (muỗi) cùng đọc wén — con muỗi có \"hoa văn\" trên thân. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con muỗi", "Hạng Tần Suất (Jun Da)": "2934.0", "Tần Suất % (Jun Da)": "99.1163682193", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 文", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫文", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "文", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蚊", "Unihan_Traditional (Chữ Phồn thể)": "蚊", "Pinyin_Xie": "wén", "Âm Hán Việt_Xie": "văn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ loài côn trùng hút máu, thường kết hợp với các danh từ khác như văn hương, văn chướng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('磅', '{"9000": "2935.0", "Chữ Trung Quốc": "磅", "Bộ thủ & thành phần_Xie": "Bộ thủ | 石 | Số nét | 15 | nét | 石 | thạch | biểu nghĩa | đá, vật nặng | 旁 | bàng | biểu âm | bên cạnh, âm bàng | 磅 = 石 (Thạch, biểu nghĩa: đá, vật đo trọng lượng) + 旁 (Bàng, biểu âm, âm páng/bàng); chữ hình thanh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bảng\": đá (石) nặng bên cạnh (旁 — bàng) — cái bảng cân, một pound đá nặng. | Gương Hán-Việt | \"bảng\" trong 磅 (bảng — đơn vị pound); liên hệ với bảng Anh (GBP). | Mở khoá kiến thức | Biết 磅 (bảng) giúp đọc ngay đơn vị trọng lượng 磅 trong văn bản khoa học và thương mại HSK 6.", "Tự nguyên_Xie": "Theo Wiktionary, 磅 là chữ hình thanh: 石 biểu nghĩa đá, 旁 biểu âm. Nghĩa gốc là đá rơi với âm thanh lớn (bàng bàng); sau dùng để phiên âm đơn vị trọng lượng tiếng Anh \"pound\" (磅 = bàng ≈ 453g) và chỉ thiết bị cân. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đá rơi lộp cộp; pao (cân Anh, bằng 450g); cái cân", "Hạng Tần Suất (Jun Da)": "2935.0", "Tần Suất % (Jun Da)": "99.1174348638", "GavinGrover_Once (Chiết tự trực tiếp)": "石 + 旁", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰石旁", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "旁", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "石", "Unihan_Simplified (Chữ Giản thể)": "磅", "Unihan_Traditional (Chữ Phồn thể)": "磅", "Pinyin_Xie": "bàng", "Âm Hán Việt_Xie": "bảng, bàng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Lượng từ | 量词 | Danh từ | 名词 | Chữ này thường dùng làm lượng từ chỉ đơn vị đo khối lượng hoặc danh từ chỉ cái cân lớn. | Lượng từ | 量词 | Đứng giữa số từ (hoặc 这/那) và danh từ: 一杯茶, 这本书. Mỗi danh từ đi với lượng từ riêng; 个 là lượng từ dùng chung phổ biến nhất. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | bàng | / | pao | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Kinh tế và tài chính I | HSK | HSK 6 | · | Khoa học chính xác", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('孽', '{"9000": "2936.0", "Chữ Trung Quốc": "孽", "Bộ thủ & thành phần_Xie": "Bộ thủ | 子 | Số nét | 19 | nét | 薛 | tiết | biểu âm | họ Tiết, cây lau (cho âm) | 子 | tử | biểu nghĩa | con, đứa trẻ | 孽 = 薛 (Tiết, biểu âm) + 子 (Tử, biểu nghĩa: con, chồi cây). Chữ hình thanh — bộ tử cho nghĩa gốc là chồi mới mọc; 薛 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nghiệt\": chồi cây (子) mọc từ gốc bị chặt — nghiệt căn ăn sâu, nghiệp báo không thoát. | Gương Hán-Việt | \"nghiệt\" trong \"nghiệt báo\" (孽报 — quả báo), \"nghiệt căn\" (孽根 — cội nguồn tội nghiệt). | Mở khoá kiến thức | Biết 孽 mở khoá: 孽障 (nghiệt chướng — tội lỗi, đứa con hư), 孽子 (con ngoài giá thú), 作孽 (gây tội lỗi).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 孽 là chữ hình thanh: 薛 (tiết — biểu âm) + 子 (tử — biểu nghĩa, con, chồi). Nghĩa gốc: chồi cây mọc ra sau khi đã chặt thân mẹ. Mở rộng: con ngoài giá thú, nghiệp báo, tội nghiệt. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chồi cây đâm lên sau khi đã chặt cây mẹ", "Hạng Tần Suất (Jun Da)": "2936.0", "Tần Suất % (Jun Da)": "99.1185009915", "GavinGrover_Once (Chiết tự trực tiếp)": "薛 + 子", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱薛子", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "薛", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "子", "Unihan_Simplified (Chữ Giản thể)": "孽", "Unihan_Traditional (Chữ Phồn thể)": "孼", "Pinyin_Xie": "niè", "Âm Hán Việt_Xie": "nghiệt", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng sau các tính từ hoặc động từ để chỉ nghiệp chướng, tai ương. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('惭', '{"9000": "2937.0", "Chữ Trung Quốc": "惭", "Bộ thủ & thành phần_Xie": "Bộ thủ | 心 | Số nét | 11 | nét | 忄 | tâm | biểu nghĩa | tâm, lòng | 斩 | trảm | biểu âm | chém — cho âm trảm/tàm | 惭 = 忄(Tâm, biểu nghĩa: lòng) + 斩 (Trảm, biểu âm); chữ hình thanh. Wiktionary ghi: {{Han compound|斬|心|ls=psc|c1=p|c2=s|t2=heart}}. Bộ tâm chỉ cảm xúc; 斩 cho âm cán (gần tàm). Xấu hổ là cảm xúc trong lòng như bị chém cắt.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tàm\": lòng (忄-Tâm) bị chém (斩-Trảm) — lòng như bị chém đứt vì xấu hổ. Tàm = hổ thẹn. | Gương Hán-Việt | tàm trong ''tàm quý, hổ thẹn'' — tiếng Việt dùng tàm quý; 惭愧 = tàm quý | Mở khoá kiến thức | Biết 惭 mở khoá: 惭愧 (tàm quý – xấu hổ), 惭色 (tàm sắc – vẻ hổ thẹn), 自惭 (tự tàm – tự xấu hổ).", "Tự nguyên_Xie": "惭 là chữ hình thanh: 忄/心 (tâm – lòng, cảm xúc) biểu nghĩa, 斬 (trảm – chém) biểu âm. Wiktionary xác nhận cấu trúc psc. Nghĩa là xấu hổ, hổ thẹn. Hình ảnh: lòng (tâm) bị ''chém'' (斩) — tâm trạng tổn thương vì xấu hổ. Từ thông dụng: 惭愧 (tàm quý – xấu hổ, hổ thẹn). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tủi thẹn", "Hạng Tần Suất (Jun Da)": "2937.0", "Tần Suất % (Jun Da)": "99.1195666025", "GavinGrover_Once (Chiết tự trực tiếp)": "忄 + 斩", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰忄斩", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "斩", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "忄", "Unihan_Simplified (Chữ Giản thể)": "惭", "Unihan_Traditional (Chữ Phồn thể)": "慙", "Pinyin_Xie": "cán", "Âm Hán Việt_Xie": "tàm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường làm tính từ bổ nghĩa cho danh từ hoặc làm vị ngữ biểu thị trạng thái hổ thẹn. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('戳', '{"9000": "2938.0", "Chữ Trung Quốc": "戳", "Bộ thủ & thành phần_Xie": "Bộ thủ | 戈 | Số nét | 18 | nét | 翟 | địch | biểu âm | lông chim trĩ dài (cho âm) | 戈 | qua | biểu nghĩa | giáo, vũ khí — đâm | 戳 = 翟 (Địch, biểu âm) + 戈 (Qua, biểu nghĩa: giáo, vũ khí). Anchor lsCodes rỗng; dựa cấu trúc khả năng hình thanh — bộ qua cho nghĩa đâm chọc; 翟 cho âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trạc\": giáo (戈) đâm mạnh như lông chim trĩ (翟) xuyên qua — động tác đâm chọc dứt khoát. | Gương Hán-Việt | \"trạc\" ít dùng độc lập trong tiếng Việt hiện đại; trong Hán văn dùng với nghĩa đâm, đóng dấu. | Mở khoá kiến thức | Biết 戳 mở khoá: 戳穿 (đâm thủng, vạch trần), 戳子 (con dấu), 盖戳 (đóng dấu).", "Tự nguyên_Xie": "Wiktionary không phân tích hợp tự chi tiết cho 戳. Dựa vào cấu trúc: 翟 (địch — biểu âm) + 戈 (qua — biểu nghĩa, giáo). Nghĩa gốc: đâm, chọc. Mở rộng: đóng dấu, con dấu (戳子). Chưa có nguồn học thuật xác nhận thêm. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đâm dao; châm, chọc, day; sái, trẹo", "Hạng Tần Suất (Jun Da)": "2938.0", "Tần Suất % (Jun Da)": "99.1206265288", "GavinGrover_Once (Chiết tự trực tiếp)": "翟 + 戈", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰翟戈", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "翟", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "戈", "Unihan_Simplified (Chữ Giản thể)": "戳", "Unihan_Traditional (Chữ Phồn thể)": "戳", "Pinyin_Xie": "chuō", "Âm Hán Việt_Xie": "trạc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường làm động từ đứng trước tân ngữ để chỉ hành động đâm chọc hoặc đóng dấu ấn. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | chuō | / | chọc | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Words II", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('禀', '{"9000": "2939.0", "Chữ Trung Quốc": "禀", "Bộ thủ & thành phần_Xie": "Bộ thủ | 示 | Số nét | 13 | nét | 𠁨 | biểu âm | phần trên gồm 亠+囗+回 — cho âm | 示 | thị | biểu nghĩa | thần linh, nghi lễ — dâng lên | 禀 là dị thể của 稟 = phần trên (亠+囗 — biểu âm) + 示 (Thị, biểu nghĩa: thần linh, lễ nghi). Anchor lsCodes rỗng. Bộ thị gợi hành động dâng lên, báo cáo lên trên; phần trên cho âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bẩm\": trình lên thần linh (示) — cúi đầu thưa bẩm, bẩm báo với bề trên. | Gương Hán-Việt | \"bẩm\" trong \"bẩm báo\" (thưa báo), \"thiên bẩm\" (禀赋 — thiên phú, bẩm sinh). | Mở khoá kiến thức | Biết 禀 mở khoá: 禀告 (thưa báo lên cấp trên), 禀赋 (bẩm sinh, thiên phú), 禀承 (vâng theo, tiếp nhận).", "Tự nguyên_Xie": "Tiểu triện | Wiktionary ghi 禀 là dị thể của 稟 (cùng nghĩa). 稟 = phần trên (biểu âm) + 示 (thị — biểu nghĩa, thần linh). Nghĩa gốc: thưa bẩm, dâng lên cấp trên; vâng theo mệnh lệnh. Mở rộng: bẩm tính trời sinh (禀赋). | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "vâng mệnh, tuân theo; thưa bẩm", "Hạng Tần Suất (Jun Da)": "2939.0", "Tần Suất % (Jun Da)": "99.1216849048", "GavinGrover_Once (Chiết tự trực tiếp)": "亠 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱亠", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "禀", "Unihan_Traditional (Chữ Phồn thể)": "稟", "Pinyin_Xie": "bǐng", "Âm Hán Việt_Xie": "bẩm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước các từ chỉ bề trên hoặc nội dung cần trình báo. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鄂', '{"9000": "2940.0", "Chữ Trung Quốc": "鄂", "Bộ thủ & thành phần_Xie": "Bộ thủ | 邑 | Số nét | 11 | nét | 咢 | ngạc | biểu âm | kinh ngạc, hét lên (cho âm) | 阝 | phụ | biểu nghĩa | bộ ấp (邑) — địa danh, vùng đất | 鄂 = 咢 (Ngạc, biểu âm) + 阝/邑 (Phụ, biểu nghĩa: ấp, địa danh). Chữ hình thanh — bộ ấp/邑 cho biết liên quan đến địa danh; 咢 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ngạc\": ấp (阝) nơi vùng biên kinh ngạc (咢) — vùng Hồ Bắc, quê hương của Vũ Hán. | Gương Hán-Việt | \"ngạc\" trong \"Ngạc Châu\" (Ech Zhou — tên cũ của Hồ Bắc), \"Ngạc quân\" (người Hồ Bắc). | Mở khoá kiến thức | Biết 鄂 mở khoá: 湖鄂 (Hồ Bắc — tên tắt 鄂), 鄂州 (Ngạc Châu — thành phố ở Hồ Bắc).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 鄂 là chữ hình thanh: 咢 (ngạc — biểu âm) + 阝/邑 (phụ — biểu nghĩa, ấp, vùng đất). Nghĩa gốc: địa danh, vùng biên cương. Hiện đại: tên tắt của tỉnh Hồ Bắc (湖北 — Hồ Bắc viết tắt là 鄂). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ngoài cõi, ven cõi ngoài; họ Ngạc", "Hạng Tần Suất (Jun Da)": "2940.0", "Tần Suất % (Jun Da)": "99.1227427639", "GavinGrover_Once (Chiết tự trực tiếp)": "咢 + 阝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰咢阝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "咢", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "阝", "Unihan_Simplified (Chữ Giản thể)": "鄂", "Unihan_Traditional (Chữ Phồn thể)": "鄂", "Pinyin_Xie": "è", "Âm Hán Việt_Xie": "ngạc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ riêng chỉ địa danh hoặc ranh giới hành chính. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('馈', '{"9000": "2941.0", "Chữ Trung Quốc": "馈", "Bộ thủ & thành phần_Xie": "Bộ thủ | 食 | Số nét | 12 | nét | 饣 | thực | biểu nghĩa | bộ thực phẩm (食 giản thể), đồ ăn | 贵 | quý | biểu âm | quý giá, âm guì gần quỹ | 馈 = 饣 (Thực, biểu nghĩa: thực phẩm, đồ ăn) + 贵 (Quý, biểu âm, âm guì; phồn thể là 饋 với 貴); chữ hình thanh — tặng thức ăn quý cho bề trên.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quỹ\": thức ăn (饣) quý giá (贵 — quý) dâng lên — quỹ tặng, dâng tặng thịnh soạn. | Gương Hán-Việt | \"quỹ\" trong 反馈 (phản quỹ — phản hồi) và 回馈 (hồi quỹ — trả lại). | Mở khoá kiến thức | Biết 馈 (quỹ) mở khoá 反馈 (phản hồi — feedback) — từ HSK 6 cực phổ biến trong giao tiếp công sở và học thuật.", "Tự nguyên_Xie": "Giáp cốt văn | Tiểu triện | Lục thư thông | Wiktionary ghi 馈 là giản thể của 饋 (thay 飠 bằng 饣 và 貴 bằng 贵). Giáp cốt văn, tiểu triện và lục thư thông ghi nhận chữ phồn thể. Cấu trúc: 食 biểu nghĩa thức ăn, 貴 biểu âm. Nghĩa gốc là dâng thức ăn cho bề trên; mở rộng sang nghĩa tặng quà, phản hồi (反馈). | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đưa tặng, tặng quà", "Hạng Tần Suất (Jun Da)": "2941.0", "Tần Suất % (Jun Da)": "99.1237928713", "GavinGrover_Once (Chiết tự trực tiếp)": "饣 + 贵", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰饣贵", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "贵", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "饣", "Unihan_Simplified (Chữ Giản thể)": "馈", "Unihan_Traditional (Chữ Phồn thể)": "餽", "Pinyin_Xie": "kuì", "Âm Hán Việt_Xie": "quỹ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước tân ngữ chỉ người nhận hoặc vật phẩm được tặng. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('垣', '{"9000": "2942.0", "Chữ Trung Quốc": "垣", "Bộ thủ & thành phần_Xie": "Bộ thủ | 土 | Số nét | 9 | nét | 土 | thổ | biểu nghĩa | đất | 亘 | biểu âm | kéo dài liên tục (cho âm), gồm 旦 (đán) | 垣 = 土 (Thổ, biểu nghĩa: đất) + 亘 (biểu âm: kéo dài, từ 旦). Chữ hình thanh — bộ thổ cho biết làm từ đất; 亘 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"viên\": đất (土) kéo dài liên tục (亘) bao quanh — tường thấp vây kín khuôn viên. | Gương Hán-Việt | \"viên\" trong \"tường viên\" (城垣 — thành tường), \"viên tường\" (tường thấp vây quanh). | Mở khoá kiến thức | Biết 垣 mở khoá: 城垣 (thành tường), 短垣 (tường thấp), 垣墙 (tường vây).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 垣 là chữ hình thanh: 土 (thổ — biểu nghĩa, đất) + 亘 (biểu âm, từ 旦 đán). Nghĩa gốc: tường thấp, tường vây. Mở rộng: hàng rào, phạm vi bảo vệ. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tường thấp", "Hạng Tần Suất (Jun Da)": "2942.0", "Tần Suất % (Jun Da)": "99.1248419451", "GavinGrover_Once (Chiết tự trực tiếp)": "土 + 亘", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰土亘", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "亘", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "土", "Unihan_Simplified (Chữ Giản thể)": "垣", "Unihan_Traditional (Chữ Phồn thể)": "垣", "Pinyin_Xie": "yuán", "Âm Hán Việt_Xie": "viên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng độc lập hoặc kết hợp tạo thành từ ghép chỉ tường vách. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('溅', '{"9000": "2943.0", "Chữ Trung Quốc": "溅", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 12 | nét | 氵 | thuỷ | biểu nghĩa | nước | 贱 | tiện | biểu âm | rẻ mạt, âm jiàn gần tiễn | 溅 = 氵 (Thuỷ, biểu nghĩa: nước) + 贱 (Tiện, biểu âm, âm jiàn; phồn thể là 濺 với 賤); chữ hình thanh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tiễn\": nước (氵) bắn vẩy như tiễn người đi xa (tiễn) — tiễn nước vẩy ướt áo. | Gương Hán-Việt | \"tiễn\" trong 溅 (tiễn — bắn vẩy nước); ít gặp trong từ Hán-Việt tiếng Việt độc lập. | Mở khoá kiến thức | Biết 溅 (tiễn) giúp nhận ra các từ miêu tả hành động nước: 溅, 泼, 喷 — ba mức độ bắn nước khác nhau.", "Tự nguyên_Xie": "Wiktionary ghi 溅 là giản thể của 濺 (thay 賤 bằng 贱). Nghĩa là nước bắn tung toé, bắn vẩy. Cấu trúc: 氵 biểu nghĩa nước, 賤 biểu âm. Chưa có nguồn học thuật xác nhận đầy đủ ls cho chữ phồn thể. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "vẩy ướt", "Hạng Tần Suất (Jun Da)": "2943.0", "Tần Suất % (Jun Da)": "99.1258853343", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 贱", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵贱", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "贱", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "溅", "Unihan_Traditional (Chữ Phồn thể)": "濺", "Pinyin_Xie": "jiàn", "Âm Hán Việt_Xie": "tiễn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ biểu thị hành động chất lỏng bắn lên người hoặc vật khác. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | jiàn | / | rắc, bắn | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Động từ tôi | YCT | YCT 4 | · | Động từ tôi | HSK | HSK 6 | · | Động từ hàng ngày", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('咚', '{"9000": "2944.0", "Chữ Trung Quốc": "咚", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 8 | nét | 口 | khẩu | biểu nghĩa | miệng, âm thanh | 冬 | đông | biểu âm | mùa đông (cho âm) | 咚 = 口 (Khẩu, biểu nghĩa: âm thanh) + 冬 (Đông, biểu âm). Anchor lsCodes rỗng và không có glyphOrigin; dựa cấu trúc khả năng hình thanh — 口 cho biết là tiếng động; 冬 cho âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đông\": miệng (口) phát ra tiếng đông đông — tiếng trống thùng thùng vang lên mùa đông. | Gương Hán-Việt | \"đông\" trong \"咚咚\" (đông đông — tiếng trống), ít dùng trong văn bản trang trọng. | Mở khoá kiến thức | Biết 咚 mở khoá: 咚咚 (tiếng trống đều đều), 咚咚锵 (tiếng chiêng trống trong lễ hội).", "Tự nguyên_Xie": "Anchor không cung cấp phân tích hợp tự cho 咚. Dựa cấu trúc: 口 (khẩu — biểu nghĩa, âm thanh) + 冬 (đông — biểu âm). Đây là từ tượng thanh ghi âm tiếng trống thùng thùng. Chưa có nguồn học thuật xác nhận thêm. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tiếng thùng thùng; mùa đông (như chữ 冬)", "Hạng Tần Suất (Jun Da)": "2944.0", "Tần Suất % (Jun Da)": "99.1269287235", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 冬", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口冬", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "冬", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "咚", "Unihan_Traditional (Chữ Phồn thể)": "咚", "Pinyin_Xie": "dōng", "Âm Hán Việt_Xie": "đông", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Từ tượng thanh | 象声词 | Thường dùng làm từ tượng thanh đứng độc lập hoặc lặp lại để mô tả âm thanh va đập. | Từ tượng thanh | 象声词 | Mô phỏng âm thanh: 哗哗, 汪汪. Có thể làm định ngữ, trạng ngữ hoặc đứng độc lập.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('钙', '{"9000": "2945.0", "Chữ Trung Quốc": "钙", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 9 | nét | 钅 | kim | biểu nghĩa | bộ kim loại (金 giản thể) | 丐 | cái | biểu âm | người ăn xin, âm gài gần cái | 钙 = 钅 (Kim, biểu nghĩa: kim loại) + 丐 (Cái, biểu âm, âm gài); chữ hình thanh. Đây là chữ tạo muộn để phiên âm nguyên tố calcium (Ca) trong hóa học hiện đại, chưa thấy trong giáp cốt/kim văn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cái\": kim loại (钅) mà người ăn xin (丐 — cái) cũng cần — canxi (cái) thiết yếu cho xương, ai cũng cần. | Gương Hán-Việt | \"cái\" trong 钙 (cái — calcium); chủ yếu dùng trong văn bản khoa học và y tế. | Mở khoá kiến thức | Biết 钙 (cái) giúp đọc các tài liệu y tế và dinh dưỡng: 缺钙 (thiếu canxi), 补钙 (bổ sung canxi).", "Tự nguyên_Xie": "Wiktionary không có glyph origin cho 钙 — đây là chữ tạo muộn, không có giáp cốt hay kim văn. Cấu trúc: 钅 biểu nghĩa kim loại, 丐 biểu âm (gài). Chữ được tạo ra trong thời hiện đại để phiên âm nguyên tố calcium (Ca) trong bảng tuần hoàn. Chưa có nguồn học thuật về giai đoạn cổ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nguyên tố calci, Ca", "Hạng Tần Suất (Jun Da)": "2945.0", "Tần Suất % (Jun Da)": "99.1279710791", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 丐", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅丐", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "丐", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "钙", "Unihan_Traditional (Chữ Phồn thể)": "鈣", "Pinyin_Xie": "gài", "Âm Hán Việt_Xie": "cái", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng trong các thuật ngữ y học, hóa học hoặc dinh dưỡng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | gài | / | canxi | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Hóa học và Sinh học II", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('礁', '{"9000": "2946.0", "Chữ Trung Quốc": "礁", "Bộ thủ & thành phần_Xie": "Bộ thủ | 石 | Số nét | 17 | nét | 石 | thạch | biểu nghĩa | đá | 焦 | tiêu | biểu âm | cháy xém (cho âm) | 礁 = 石 (Thạch, biểu nghĩa: đá) + 焦 (Tiêu, biểu âm). Chữ hình thanh — bộ thạch cho biết là đá; 焦 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tiêu\": đá (石) bị sóng biển xói mòn như bị đốt cháy (焦) — đá ngầm nguy hiểm dưới mặt nước. | Gương Hán-Việt | \"tiêu\" trong \"ám tiêu\" (暗礁 — đá ngầm nguy hiểm), \"tiêu thạch\" (礁石 — đá ngầm). | Mở khoá kiến thức | Biết 礁 mở khoá: 暗礁 (đá ngầm), 礁石 (đá ngầm, đá rạn), 珊瑚礁 (rạn san hô).", "Tự nguyên_Xie": "Theo Wiktionary, 礁 là chữ hình thanh: 石 (thạch — biểu nghĩa, đá) + 焦 (tiêu — biểu âm). Nghĩa gốc: đá ngầm dưới nước, rạn san hô. Dùng trong hàng hải. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đá ngầm; san hô", "Hạng Tần Suất (Jun Da)": "2946.0", "Tần Suất % (Jun Da)": "99.1290134347", "GavinGrover_Once (Chiết tự trực tiếp)": "石 + 焦", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰石焦", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "焦", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "石", "Unihan_Simplified (Chữ Giản thể)": "礁", "Unihan_Traditional (Chữ Phồn thể)": "礁", "Pinyin_Xie": "jiāo", "Âm Hán Việt_Xie": "tiêu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng sau các từ chỉ vị trí hoặc kết hợp tạo từ ghép địa lý biển. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('彰', '{"9000": "2947.0", "Chữ Trung Quốc": "彰", "Bộ thủ & thành phần_Xie": "Bộ thủ | 彡 | Số nét | 14 | nét | 章 | chương | biểu âm | huy hiệu, chương mục — âm zhāng | 彡 | sam | biểu nghĩa | bộ hoa văn, màu sắc rực rỡ | 彰 = 章 (Chương, biểu âm, âm zhāng) + 彡 (Sam, biểu nghĩa: hoa văn rực rỡ, nổi bật); chữ hình thanh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chương\": hoa văn rực rỡ (彡) trên huy hiệu (章 — chương) — chương hiển, sáng rõ không che giấu được. | Gương Hán-Việt | \"chương\" trong 表彰 (biểu chương — tôn vinh, khen thưởng) và 彰显 (chương hiển — thể hiện rõ ràng). | Mở khoá kiến thức | Biết 彰 (chương) mở khoá 表彰 (khen thưởng công khai) và 彰显 (thể hiện rõ) — HSK 6.", "Tự nguyên_Xie": "Đại triện | Tiểu triện | Theo Wiktionary, 彰 là chữ hình thanh: 章 biểu âm (huy hiệu, cờ hiệu), 彡 biểu nghĩa hoa văn màu sắc, sự nổi bật. Đại triện và tiểu triện ghi nhận. Nghĩa là rõ ràng, nổi bật, hiển nhiên; dùng trong 表彰 (khen thưởng, tôn vinh công khai) và 彰显 (thể hiện rõ ràng). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "rực rỡ, rõ rệt", "Hạng Tần Suất (Jun Da)": "2947.0", "Tần Suất % (Jun Da)": "99.13005424", "GavinGrover_Once (Chiết tự trực tiếp)": "章 + 彡", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰章彡", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "章", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "彡", "Unihan_Simplified (Chữ Giản thể)": "彰", "Unihan_Traditional (Chữ Phồn thể)": "彰", "Pinyin_Xie": "zhāng", "Âm Hán Việt_Xie": "chương", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Chữ này thường làm tính từ chỉ sự rõ ràng hoặc làm động từ mang nghĩa biểu dương, làm lộ rõ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('豁', '{"9000": "2948.0", "Chữ Trung Quốc": "豁", "Bộ thủ & thành phần_Xie": "Bộ thủ | 谷 | Số nét | 17 | nét | 害 | hại | biểu âm | thiệt hại (cho âm — gần âm huò) | 谷 | cốc | biểu nghĩa | thung lũng, trống rỗng | 豁 = 害 (Hại, biểu âm) + 谷 (Cốc, biểu nghĩa: thung lũng). Anchor lsCodes rỗng; dựa cấu trúc khả năng hình thanh — bộ cốc gợi không gian rộng mở; 害 cho âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khoát\": thung lũng (谷) rộng thông suốt — lòng khoáng đạt, rộng lượng, bỏ qua mọi chuyện. | Gương Hán-Việt | \"khoát\" trong \"khoát đạt\" (豁达 — khoáng đạt), \"khoát nhiên\" (豁然 — thốt nhiên thông suốt). | Mở khoá kiến thức | Biết 豁 mở khoá: 豁达 (khoáng đạt, cởi mở), 豁然 (thốt nhiên sáng tỏ), 豁免 (miễn trừ), 豁出去 (đánh liều).", "Tự nguyên_Xie": "Tiểu triện | Wiktionary cung cấp anchor cho 豁 nhưng lsCodes rỗng. Dựa cấu trúc: 害 (hại — biểu âm) + 谷 (cốc — biểu nghĩa, thung lũng trống rỗng). Nghĩa gốc: hang thông hai đầu, khoảng rộng. Mở rộng: thông suốt, cởi mở (豁达), bỏ qua (豁免). | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "hang thông cả 2 đầu; thông suốt", "Hạng Tần Suất (Jun Da)": "2948.0", "Tần Suất % (Jun Da)": "99.1310945285", "GavinGrover_Once (Chiết tự trực tiếp)": "害 + 谷", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰害谷", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "害", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "谷", "Unihan_Simplified (Chữ Giản thể)": "豁", "Unihan_Traditional (Chữ Phồn thể)": "豁", "Pinyin_Xie": "huō", "Âm Hán Việt_Xie": "hoát, khoát", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Thường dùng làm động từ chỉ sự thông suốt, miễn trừ hoặc làm tính từ chỉ sự rộng rãi, cởi mở. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | huō | / | mở rộng | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Động từ tôi", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('眯', '{"9000": "2949.0", "Chữ Trung Quốc": "眯", "Bộ thủ & thành phần_Xie": "Bộ thủ | 目 | Số nét | 11 | nét | 目 | mục | biểu nghĩa | mắt | 米 | mễ | biểu âm | gạo, hạt — âm mǐ gần mị | 眯 = 目 (Mục, biểu nghĩa: mắt) + 米 (Mễ, biểu âm, âm mǐ); chữ hình thanh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mị\": mắt (目) nhỏ như hạt gạo (米 — mễ) — nheo mắt lại, mị người xem mê hoặc. | Gương Hán-Việt | \"mị\" trong 眯眼 (mị nhãn — nheo mắt) và 眯缝 (nheo mắt lim dim). | Mở khoá kiến thức | Biết 眯 (mị) giúp nhận ra các từ miêu tả trạng thái mắt: 眯眼, 闭眼, 睁眼 — ba mức độ mắt mở/nhắm.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 眯 là chữ hình thanh: 目 biểu nghĩa mắt, 米 biểu âm. Tiểu triện ghi nhận hình dạng này. Nghĩa là bị vật lạ bay vào mắt (mí mắt không nhắm hẳn); sau mở rộng sang nghĩa nheo mắt, nhắm mắt lim dim. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bị vật gì bay vào mắt", "Hạng Tần Suất (Jun Da)": "2949.0", "Tần Suất % (Jun Da)": "99.132134817", "GavinGrover_Once (Chiết tự trực tiếp)": "目 + 米", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰目米", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "米", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "目", "Unihan_Simplified (Chữ Giản thể)": "眯", "Unihan_Traditional (Chữ Phồn thể)": "眯", "Pinyin_Xie": "mī", "Âm Hán Việt_Xie": "mị", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ chỉ hành động híp mắt lại hoặc khi bị bụi bay vào mắt gây khó chịu. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | mī | / | nheo mắt | Xuất hiện trong lộ trình | HSK | HSK 6 | · | Cơ thể và ngoại hình tôi", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('磷', '{"9000": "2950.0", "Chữ Trung Quốc": "磷", "Bộ thủ & thành phần_Xie": "Bộ thủ | 石 | Số nét | 17 | nét | 石 | thạch | biểu nghĩa | đá, khoáng chất | 粦 | lân | biểu âm | lân tinh (ma trơi, cho âm) | 磷 = 石 (Thạch, biểu nghĩa: đá, khoáng chất) + 粦 (Lân, biểu âm). Chữ hình thanh — bộ thạch cho biết là chất khoáng; 粦 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lân\": khoáng chất (石) phát sáng ma quái như ma trơi (粦) — phốt-pho phát ánh sáng xanh trong đêm tối. | Gương Hán-Việt | \"lân\" trong \"lân tinh\" (磷 — ma trơi, phốt-pho phát quang), \"lân quang\" (ánh sáng phốt-pho). | Mở khoá kiến thức | Biết 磷 mở khoá: 磷火 (ma trơi, lửa phốt-pho), 磷酸 (axit phốt-phoric), 白磷 (phốt-pho trắng).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 磷 là chữ hình thanh: 石 (thạch — biểu nghĩa, đá, khoáng vật) + 粦 (lân — biểu âm). Nghĩa gốc: nước chảy ở khe đá. Hiện đại: phốt-pho (nguyên tố hoá học P). Liên hệ: 鬼火 (ma trơi) do 磷 phát sáng. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nước chảy ở khe đá", "Hạng Tần Suất (Jun Da)": "2950.0", "Tần Suất % (Jun Da)": "99.1331745887", "GavinGrover_Once (Chiết tự trực tiếp)": "石 + 粦", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰石粦", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "粦", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "石", "Unihan_Simplified (Chữ Giản thể)": "磷", "Unihan_Traditional (Chữ Phồn thể)": "燐", "Pinyin_Xie": "lín", "Âm Hán Việt_Xie": "lân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ để chỉ nguyên tố hóa học phốt-pho hoặc hiện tượng lân quang. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('雯', '{"9000": "2951.0", "Chữ Trung Quốc": "雯", "Bộ thủ & thành phần_Xie": "Bộ thủ | 雨 | Số nét | 12 | nét | 雨 | vũ | biểu nghĩa | mưa, mây | 文 | văn | biểu âm | hoa văn, chữ viết (cho âm) | 雯 = 雨 (Vũ, biểu nghĩa: mưa, mây) + 文 (Văn, biểu âm). Chữ hình thanh — bộ vũ cho biết liên quan đến mây; 文 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"văn\": mây (雨) có hoa văn (文) uốn lượn — đám mây đẹp như tranh thêu. | Gương Hán-Việt | \"văn\" trong tên người như Lâm Tân Như (林心如 — tên Việt hoá), 雯雯 (Văn Văn — tên con gái). | Mở khoá kiến thức | Biết 雯 mở khoá: tên nữ như 雯雯, 雯靖; hiểu vì sao tên con gái hay dùng 雯.", "Tự nguyên_Xie": "Theo Wiktionary, 雯 là chữ hình thanh: 雨 (vũ — biểu nghĩa, mưa) + 文 (văn — biểu âm). Nghĩa gốc: đám mây có hoa văn, vân mây đẹp. Chủ yếu dùng trong tên người (tên con gái). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đám mây có hình", "Hạng Tần Suất (Jun Da)": "2951.0", "Tần Suất % (Jun Da)": "99.1342143603", "GavinGrover_Once (Chiết tự trực tiếp)": "雨 + 文", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱雨文", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "文", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "雨", "Unihan_Simplified (Chữ Giản thể)": "雯", "Unihan_Traditional (Chữ Phồn thể)": "雯", "Pinyin_Xie": "wén", "Âm Hán Việt_Xie": "văn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chủ yếu dùng làm danh từ chỉ những đám mây có hoa văn đẹp, thường xuất hiện trong tên người. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('墟', '{"9000": "2952.0", "Chữ Trung Quốc": "墟", "Bộ thủ & thành phần_Xie": "Bộ thủ | 土 | Số nét | 14 | nét | 土 | thổ | biểu nghĩa | đất, địa hình | 虚 | hư | biểu âm | trống rỗng, hư không — âm xū gần khư | 墟 = 土 (Thổ, biểu nghĩa: đất) + 虚 (Hư, biểu âm, âm xū; phồn thể dùng 虛); chữ hình thanh — mảnh đất hoang tàn, trống rỗng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khư\": đất (土) trống rỗng hư không (虚 — hư) — nơi khư cũ hoang tàn, chỉ còn phế tích. | Gương Hán-Việt | \"khư\" trong 废墟 (phế khư — phế tích, đống đổ nát). | Mở khoá kiến thức | Biết 墟 (khư) mở khoá 废墟 (đống đổ nát, phế tích) — từ HSK 6 hay gặp trong văn học và báo chí.", "Tự nguyên_Xie": "Theo Wiktionary, 墟 là chữ hình thanh: 土 biểu nghĩa đất, 虛 biểu âm. Nghĩa gốc là gò đất cao hoặc làng cổ bỏ hoang; sau mở rộng sang nghĩa đống đổ nát, nơi hoang tàn. Dùng phổ biến trong 废墟 (đống đổ nát). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái gò lớn", "Hạng Tần Suất (Jun Da)": "2952.0", "Tần Suất % (Jun Da)": "99.1352530985", "GavinGrover_Once (Chiết tự trực tiếp)": "土 + 虚", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰土虚", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "虚", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "土", "Unihan_Simplified (Chữ Giản thể)": "墟", "Unihan_Traditional (Chữ Phồn thể)": "墟", "Pinyin_Xie": "xū", "Âm Hán Việt_Xie": "hư", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ khu đất trống, gò đất lớn hoặc đống đổ nát hoang tàn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('迂', '{"9000": "2953.0", "Chữ Trung Quốc": "迂", "Bộ thủ & thành phần_Xie": "Bộ thủ | 辵 | Số nét | 6 | nét | 辶 | sước | biểu nghĩa | đi, di chuyển (bộ xước) | 于 | vu | biểu âm | ở, tại (cho âm) | 迂 = 辶 (Sước, biểu nghĩa: đi, di chuyển) + 于 (Vu, biểu âm). Anchor lsCodes rỗng; dựa cấu trúc khả năng hình thanh — bộ xước gợi đường đi vòng vèo; 于 cho âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"vu\": đi (辶) vòng vèo xa xôi như từ \"vu\" cổ điển — lối suy nghĩ lòng vòng, cổ hủ xa thực tế. | Gương Hán-Việt | \"vu\" trong \"vu hồi\" (迂回 — vòng vèo, đi vòng), \"vu nho\" (迂儒 — nhà nho sách vở, cổ hủ). | Mở khoá kiến thức | Biết 迂 mở khoá: 迂回 (đi vòng, tấn công từ bên sườn), 迂腐 (cổ hủ, sách vở), 迂曲 (quanh co).", "Tự nguyên_Xie": "Tiểu triện | Wiktionary không phân tích hợp tự chi tiết cho 迂. Dựa cấu trúc: 辶 (sước — biểu nghĩa, đi lại) + 于 (vu — biểu âm). Nghĩa gốc: đường xa, đi vòng. Mở rộng: cổ hủ, sách vở, không thực tế (迂腐). Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đường xa", "Hạng Tần Suất (Jun Da)": "2953.0", "Tần Suất % (Jun Da)": "99.1362902862", "GavinGrover_Once (Chiết tự trực tiếp)": "辶 + 于", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴辶于", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "于", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "辶", "Unihan_Simplified (Chữ Giản thể)": "迂", "Unihan_Traditional (Chữ Phồn thể)": "迂", "Pinyin_Xie": "yū", "Âm Hán Việt_Xie": "vu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường làm tính từ bổ nghĩa cho hành động đi đường vòng hoặc tính cách bảo thủ, hủ lậu. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('瞻', '{"9000": "2954.0", "Chữ Trung Quốc": "瞻", "Bộ thủ & thành phần_Xie": "Bộ thủ | 目 | Số nét | 18 | nét | 目 | mục | biểu nghĩa | mắt | 詹 | chiêm | biểu âm | nói nhiều, âm zhān gần chiêm | 瞻 = 目 (Mục, biểu nghĩa: mắt) + 詹 (Chiêm, biểu âm, âm zhān); chữ hình thanh — nhìn lên, chiêm ngưỡng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chiêm\": mắt (目) ngước nhìn lên như tự nói với lòng (詹 — chiêm, nói nhiều) — chiêm bái, ngưỡng vọng. | Gương Hán-Việt | \"chiêm\" trong 瞻仰 (chiêm ngưỡng — chiêm bái, nhìn lên tôn kính). | Mở khoá kiến thức | Biết 瞻 (chiêm) mở khoá 瞻仰 (chiêm ngưỡng) và 高瞻远瞩 (nhìn xa trông rộng) — HSK 6.", "Tự nguyên_Xie": "Đại triện | Tiểu triện | Theo Wiktionary, 瞻 là chữ hình thanh: 目 biểu nghĩa mắt, 詹 biểu âm. Đại triện và tiểu triện ghi nhận hình dạng này. Nghĩa gốc là ngước nhìn lên; mở rộng sang nghĩa tôn kính chiêm ngưỡng, và chiêm bái (瞻仰). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ngửa mặt lên nhìn", "Hạng Tần Suất (Jun Da)": "2954.0", "Tần Suất % (Jun Da)": "99.1373264404", "GavinGrover_Once (Chiết tự trực tiếp)": "目 + 詹", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰目詹", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "詹", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "目", "Unihan_Simplified (Chữ Giản thể)": "瞻", "Unihan_Traditional (Chữ Phồn thể)": "瞻", "Pinyin_Xie": "zhān", "Âm Hán Việt_Xie": "chiêm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ chỉ hành động nhìn lên cao hoặc hướng về phía trước với thái độ tôn kính. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('颅', '{"9000": "2955.0", "Chữ Trung Quốc": "颅", "Bộ thủ & thành phần_Xie": "Bộ thủ | 頁 | Số nét | 11 | nét | 卢 | lô | biểu âm | họ Lư, lò đen (cho âm) | 页 | hiệt | biểu nghĩa | đầu, trang (bộ hiệt) | 颅 = 卢 (Lô, biểu âm) + 页 (Hiệt, biểu nghĩa: đầu người). Chữ hình thanh — bộ hiệt cho biết liên quan đến đầu người; 卢 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lâu\": cái đầu (页) đen như lò (卢) — hộp sọ bảo vệ não. | Gương Hán-Việt | \"lâu\" trong \"đầu lâu\" (颅骨 — xương đầu, hộp sọ), \"khai lâu\" (phẫu thuật não). | Mở khoá kiến thức | Biết 颅 mở khoá: 头颅 (đầu, hộp sọ), 颅骨 (xương sọ), 颅内 (trong hộp sọ).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 颅 là chữ hình thanh: 盧 (lô — biểu âm) + 頁 (hiệt — biểu nghĩa, đầu người). Nghĩa gốc và duy nhất: xương sọ (skull). Dùng trong giải phẫu học. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái sọ", "Hạng Tần Suất (Jun Da)": "2955.0", "Tần Suất % (Jun Da)": "99.1383620778", "GavinGrover_Once (Chiết tự trực tiếp)": "卢 + 页", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰卢页", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "卢", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "页", "Unihan_Simplified (Chữ Giản thể)": "颅", "Unihan_Traditional (Chữ Phồn thể)": "顱", "Pinyin_Xie": "lú", "Âm Hán Việt_Xie": "lô", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ phần đầu hoặc hộp sọ của người và động vật. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('琉', '{"9000": "2956.0", "Chữ Trung Quốc": "琉", "Bộ thủ & thành phần_Xie": "Bộ thủ | 玉 | Số nét | 11 | nét | 𤣩 | ngọc (biến thể của 玉) | biểu nghĩa | ngọc | 㐬 | lưu | biểu âm | 琉 = 𤣩 (ngọc — biểu nghĩa) + 㐬 (biểu âm, gợi âm liú/lưu); chữ hình thanh. Bộ ngọc chỉ đây là loại đá quý hoặc vật liệu giống ngọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lưu\": bộ Ngọc (𤣩) bên cạnh 㐬 gợi tiếng — \"lưu ly\" là viên ngọc óng ánh chảy dài như ánh sáng lưu lại. | Gương Hán-Việt | \"lưu\" xuất hiện trong \"lưu ly\" (琉璃 — thủy tinh màu, ngói men) và \"Lưu Cầu\" (琉球 — quần đảo Ryukyu). | Mở khoá kiến thức | Biết 琉 (lưu) là nhận ra ngay 琉璃 (lưu ly — gốm men, thủy tinh) và địa danh 琉球 (Lưu Cầu).", "Tự nguyên_Xie": "Theo Wiktionary, 琉 là chữ hình thanh: phần 𤣩 (biến thể của 玉 — ngọc, biểu nghĩa) kết hợp với 㐬 (biểu âm). Chữ dùng chủ yếu trong 琉璃 (lưu ly — thủy tinh màu, gốm men), chỉ loại vật liệu óng ánh như ngọc. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: lưu ly 琉璃)", "Hạng Tần Suất (Jun Da)": "2956.0", "Tần Suất % (Jun Da)": "99.1393956481", "GavinGrover_Once (Chiết tự trực tiếp)": "王 + 㐬", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰王㐬", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "㐬", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "王", "Unihan_Simplified (Chữ Giản thể)": "琉", "Unihan_Traditional (Chữ Phồn thể)": "琉", "Pinyin_Xie": "liú", "Âm Hán Việt_Xie": "lưu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ và hầu như chỉ xuất hiện trong từ ghép để chỉ một loại đá quý hoặc thủy tinh màu. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('悼', '{"9000": "2957.0", "Chữ Trung Quốc": "悼", "Bộ thủ & thành phần_Xie": "Bộ thủ | 心 | Số nét | 11 | nét | 忄 | tâm | biểu nghĩa | lòng, cảm xúc (心 viết cạnh chữ) | 卓 | trác | biểu âm | kiệt xuất, cao vời — âm zhuó gần điệu | 悼 = 忄 (Tâm, biểu nghĩa: lòng, cảm xúc) + 卓 (Trác, biểu âm, âm zhuó); chữ hình thanh — lòng đau thương vì người mất.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"điệu\": lòng (忄) đau như người kiệt xuất (卓 — trác) vừa ra đi — điệu thương, bi thương tưởng niệm. | Gương Hán-Việt | \"điệu\" trong 悼念 (điệu niệm — tưởng niệm) và 追悼 (truy điệu — lễ truy điệu). | Mở khoá kiến thức | Biết 悼 (điệu) mở khoá 追悼 (lễ truy điệu), 悼念 (tưởng niệm), 哀悼 (tỏ lòng thương tiếc) — HSK 6.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Theo Wiktionary, 悼 là chữ hình thanh: 心 (忄) biểu nghĩa lòng, 卓 biểu âm. Tiểu triện và lục thư thông ghi nhận hình dạng này. Nghĩa là thương tiếc, khóc thương người đã mất; dùng trong 哀悼, 追悼. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thương tiếc; viếng người chết", "Hạng Tần Suất (Jun Da)": "2957.0", "Tần Suất % (Jun Da)": "99.140427668", "GavinGrover_Once (Chiết tự trực tiếp)": "忄 + 卓", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰忄卓", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "卓", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "忄", "Unihan_Simplified (Chữ Giản thể)": "悼", "Unihan_Traditional (Chữ Phồn thể)": "悼", "Pinyin_Xie": "dào", "Âm Hán Việt_Xie": "điệu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ thể hiện sự đau buồn, thương tiếc đối với người đã khuất. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蝴', '{"9000": "2958.0", "Chữ Trung Quốc": "蝴", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 15 | nét | 虫 | trùng | biểu nghĩa | côn trùng | 胡 | hồ | biểu âm | người Hồ — cho âm hồ | 蝴 = 虫 (Trùng, biểu nghĩa: côn trùng) + 胡 (Hồ, biểu âm); chữ hình thanh. Wiktionary ghi: {{Han compound|虫|胡|ls=psc|c1=s|c2=p|t1=insect}}. Bộ trùng chỉ loài côn trùng; 胡 cho âm hú (gần hồ). Chữ chỉ dùng trong 蝴蝶 (bướm).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hồ\": trùng (虫-Trùng) Hồ (胡-Hồ) — con trùng người Hồ = con bướm hồ điệp. Hồ điệp 蝴蝶. | Gương Hán-Việt | hồ trong ''hồ điệp'' — tiếng Việt mượn từ 蝴蝶; 蝴 chỉ dùng trong từ ghép này | Mở khoá kiến thức | Biết 蝴 mở khoá duy nhất: 蝴蝶 (hồ điệp – con bướm) — từ quan trọng và đẹp trong tiếng Trung.", "Tự nguyên_Xie": "蝴 là chữ hình thanh: 虫 (trùng – côn trùng) biểu nghĩa, 胡 (hồ) biểu âm. Wiktionary ghi: ''only used in 蝴蝶 (butterfly)''. Chữ không dùng độc lập. Bướm (蝴蝶) là từ ghép: 蝴 + 蝶. Cả hai thành phần đều có bộ 虫. Chưa có nguồn học thuật về glyphOrigin. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1061.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Trùng (142) Hồ (1060)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Trùng (số 142 - côn trùng) ở bên trái chữ Hồ (số 1060 - họ Hồ/chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Hồ chỉ âm, bộ Trùng chỉ ý. Hồ là từ dùng để gọi tên một loại côn trùng (hồ điệp - con bươm bướm).", "Nghĩa Tiếng Việt_Xie": "(xem: hồ điệp 蝴蝶)", "Hạng Tần Suất (Jun Da)": "2958.0", "Tần Suất % (Jun Da)": "99.1414565872", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 胡", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫胡", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "胡", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蝴", "Unihan_Traditional (Chữ Phồn thể)": "蝴", "Pinyin_Xie": "hú", "Âm Hán Việt_Xie": "hồ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Là danh từ liên kết, hầu như chỉ dùng trong từ ghép để chỉ loài bướm. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('拣', '{"9000": "2959.0", "Chữ Trung Quốc": "拣", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 8 | nét | 扌 | thủ | biểu nghĩa | bàn tay | 𫠣 | biểu âm | biến thể giản thể của 柬, âm jiǎn gần giản | 拣 = 扌 (Thủ, biểu nghĩa: tay) + 𫠣 (biến thể giản của 柬, biểu âm, âm jiǎn); chữ hình thanh. Giản thể của 揀.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"giản\": bàn tay (扌) chọn lọc giản dị (giản) từng thứ một — giản chọn, lựa chọn cẩn thận. | Gương Hán-Việt | \"giản\" trong 拣 (giản — lựa chọn); cùng Hán-Việt với 简 (giản dị) và 检 (kiểm tra). | Mở khoá kiến thức | Biết 拣 (giản) giúp đọc 挑拣 (lựa chọn kỹ càng) và 拣择 (chọn lọc) — từ chỉ hành động lựa chọn HSK 6.", "Tự nguyên_Xie": "Wiktionary ghi 拣 là giản thể của 揀 (thay 柬 bằng 𫠣). Cấu trúc: 手 (扌) biểu nghĩa tay, 柬 biểu âm. Nghĩa là chọn lựa bằng tay, nhặt ra, lọc lấy. Chưa có nguồn học thuật đầy đủ về giai đoạn cổ cho chữ này. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chọn lựa", "Hạng Tần Suất (Jun Da)": "2959.0", "Tần Suất % (Jun Da)": "99.1424803386", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "拣", "Unihan_Traditional (Chữ Phồn thể)": "揀", "Pinyin_Xie": "jiǎn", "Âm Hán Việt_Xie": "giản", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này thường làm động từ đứng trước danh từ làm tân ngữ để chỉ hành động lựa chọn hoặc nhặt đồ vật. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | jiǎn | / | lựa chọn | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Words II | HSK | HSK 6 | · | Động từ", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('渺', '{"9000": "2960.0", "Chữ Trung Quốc": "渺", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 12 | nét | 氵 | thuỷ | biểu nghĩa | nước, sông | 眇 | miễu | biểu âm | mờ mịt, mù quáng — âm miǎo gần miểu | 渺 = 氵 (Thuỷ, biểu nghĩa: nước) + 眇 (Miễu, biểu âm, âm miǎo); chữ hình thanh — mặt nước mênh mông xa tít.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"miểu\": nước (氵) mờ mịt như con mắt hỏng (眇 — miễu, mù một mắt) — miểu mang, xa tít không thấy đáy. | Gương Hán-Việt | \"miểu\" trong 渺小 (miểu tiểu — nhỏ bé, tầm thường) và 渺茫 (miểu mang — mờ mịt, xa vời). | Mở khoá kiến thức | Biết 渺 (miểu) mở khoá 渺小 (nhỏ bé), 渺茫 (mờ mịt) và 飘渺 (hư ảo) — HSK 6.", "Tự nguyên_Xie": "Theo Wiktionary, 渺 là chữ hình thanh: 氵 biểu nghĩa nước, 眇 biểu âm. Nghĩa gốc là mặt nước bao la mênh mông; mở rộng sang nghĩa mờ mịt, nhỏ bé, xa xôi không rõ. Dùng trong 渺小 (nhỏ bé, tầm thường), 渺茫 (xa mờ, mơ hồ), 飘渺 (hư ảo). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mù mịt; mờ mịt; mịt mùng; xa tít mù khơi; nhỏ; nhỏ bé; mênh mông; bao la (nước)", "Hạng Tần Suất (Jun Da)": "2960.0", "Tần Suất % (Jun Da)": "99.1435035731", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 眇", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵眇", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "眇", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "渺", "Unihan_Traditional (Chữ Phồn thể)": "渺", "Pinyin_Xie": "miǎo", "Âm Hán Việt_Xie": "miểu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường làm tính từ đứng sau phó từ chỉ mức độ để miêu tả sự nhỏ bé hoặc xa xăm. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('眷', '{"9000": "2961.0", "Chữ Trung Quốc": "眷", "Bộ thủ & thành phần_Xie": "Bộ thủ | 目 | Số nét | 11 | nét | 龹 | biểu âm | 目 | mục | biểu nghĩa | mắt | 眷 = 龹 (biểu âm, gợi âm juàn/quyến) + 目 (Mục — mắt, biểu nghĩa); chữ hình thanh. Mắt nhìn lại gợi ý nghĩa lưu luyến, nhớ nhung.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quyến\": đôi mắt (目) cứ nhìn quay lại — đó là 眷 (quyến luyến) người thân, không nỡ rời. | Gương Hán-Việt | \"quyến\" xuất hiện trong \"quyến luyến\" (眷戀 — nhớ nhung), \"quyến thuộc\" (眷屬 — người thân). | Mở khoá kiến thức | Biết 眷 (quyến) là nắm được 眷顾 (quyến cố — quan tâm), 眷恋 (quyến luyến), 眷属 (quyến thuộc — người thân).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 眷 là chữ hình thanh: 龹 (biểu âm) kết hợp với 目 (mục — mắt, biểu nghĩa). Nghĩa gốc là \"quay đầu nhìn lại\", từ đó mở rộng sang \"quan tâm, lưu luyến\" và \"người thân\". | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "người thân; lưu luyến, nhớ nhung", "Hạng Tần Suất (Jun Da)": "2961.0", "Tần Suất % (Jun Da)": "99.1445231902", "GavinGrover_Once (Chiết tự trực tiếp)": "龹 + 目", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱龹目", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "龹", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "目", "Unihan_Simplified (Chữ Giản thể)": "眷", "Unihan_Traditional (Chữ Phồn thể)": "眷", "Pinyin_Xie": "juàn", "Âm Hán Việt_Xie": "quyến", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường làm danh từ chỉ người thân hoặc làm động từ thể hiện sự nhớ nhung, lưu luyến. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('悯', '{"9000": "2962.0", "Chữ Trung Quốc": "悯", "Bộ thủ & thành phần_Xie": "Bộ thủ | 心 | Số nét | 10 | nét | 悯 | mẫn | tượng hình | thương xót, trắc ẩn | 悯 là dạng giản thể của 憫. Chữ phồn thể 憫 gồm 忄 (tâm — tim, biểu nghĩa) + 閔 (biểu âm). Chưa xác định rõ cấu trúc chữ giản thể từ nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mẫn\": trái tim (忄) rung lên trước nỗi đau của người khác — đó là 悯 (mẫn) lòng trắc ẩn, thương xót. | Gương Hán-Việt | \"mẫn\" xuất hiện trong \"trắc mẫn\" (惻憫 — thương xót), \"khả mẫn\" (可憫 — đáng thương). | Mở khoá kiến thức | Biết 悯 (mẫn) là nắm được 怜悯 (liên mẫn — thương xót), 悲悯 (bi mẫn — từ bi).", "Tự nguyên_Xie": "悯 là dạng giản thể của 憫. Chữ phồn thể 憫 cấu tạo từ 忄(心 — tâm, tim) làm phần biểu nghĩa và 閔 làm phần biểu âm. Nghĩa là thương xót, trắc ẩn với người gặp khó khăn. Chưa có nguồn học thuật chi tiết cho dạng giản thể. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thương nhớ", "Hạng Tần Suất (Jun Da)": "2962.0", "Tần Suất % (Jun Da)": "99.1455412569", "GavinGrover_Once (Chiết tự trực tiếp)": "忄 + 闵", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰忄闵", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "闵", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "忄", "Unihan_Simplified (Chữ Giản thể)": "悯", "Unihan_Traditional (Chữ Phồn thể)": "憫", "Pinyin_Xie": "mǐn", "Âm Hán Việt_Xie": "mẫn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ mang tân ngữ để biểu thị lòng thương hại hoặc sự cảm thông với người khác. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('汰', '{"9000": "2963.0", "Chữ Trung Quốc": "汰", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 7 | nét | 氵 | thuỷ | biểu nghĩa | nước | 太 | thái | biểu âm | quá mức (cho âm) | 汰 = 氵(Thuỷ, biểu nghĩa: nước) + 太 (Thái, biểu âm); chữ hình thanh. Bộ thuỷ gợi hành động rửa trôi bằng nước; 太 cho âm đọc gần với tài.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thải\": nước (氵) cuốn trôi đồ cặn — hình ảnh vo gạo, thải bỏ những hạt kém chất lượng. | Gương Hán-Việt | ''thải'' trong ''đào thải'' (loại bỏ), ''thải'' trong ''ưu thắng liệt thải'' (mạnh còn yếu mất) | Mở khoá kiến thức | Biết 汰 mở khoá: 淘汰 (đào thải), 汰换 (thay thế), 优胜劣汰 (chọn lọc tự nhiên)", "Tự nguyên_Xie": "汰 là chữ hình thanh: bộ 氵(nước) biểu nghĩa hành động rửa, vo; 太 biểu âm. Nghĩa gốc là ''rửa sạch, vo gạo''; từ đó mở rộng sang ''loại bỏ'' (thải đi thứ không dùng được) và ''kiêu ngạo, xa xỉ''. Trong thành ngữ 优胜劣汰, chữ thể hiện quá trình tự nhiên sàng lọc. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "410.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thủy (306) Thái (18)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Thủy (số 76) và chữ Thái (số 144 - quá mức) . Dùng nước (Thủy) rửa trôi đi những phần dư thừa, quá mức (Thái) gọi là đào thải. Giải thích sự chuyển ý: Chữ Thái (quá đỗi) chỉ âm, chữ Thủy (nước) chỉ ý. Nước (Thủy) chảy xiết cuốn trôi đi cặn bã (Thái - đào thải).", "Nghĩa Tiếng Việt_Xie": "quá mức; thải đi, bỏ đi", "Hạng Tần Suất (Jun Da)": "2963.0", "Tần Suất % (Jun Da)": "99.1465582901", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 太", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵太", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "太", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "汰", "Unihan_Traditional (Chữ Phồn thể)": "汰", "Pinyin_Xie": "tài", "Âm Hán Việt_Xie": "thải, thái", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ trong các từ ghép để chỉ việc lọc bỏ, đào thải những thứ không đạt yêu cầu. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('慑', '{"9000": "2964.0", "Chữ Trung Quốc": "慑", "Bộ thủ & thành phần_Xie": "Bộ thủ | 心 | Số nét | 13 | nét | 心 | tâm | biểu nghĩa | tim, tâm trạng | 聶 | nhiếp | biểu âm | 慑 = 忄(心 — Tâm, biểu nghĩa: tâm trạng, cảm xúc) + 聶 (Nhiếp, biểu âm); chữ hình thanh. Trái tim (tâm) bị nhân vật âm thanh 聶 chèn ép — gợi cảm giác sợ hãi, run rẩy.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nhiếp\": trái tim (忄) bị 聶 (ba cái tai nghe chằm chằm) — bị áp đảo đến 慑 (nhiếp) run sợ. | Gương Hán-Việt | \"nhiếp\" xuất hiện trong \"chấn nhiếp\" (震慑 — khiến sợ hãi), \"nhiếp phục\" (慑服 — khuất phục vì sợ). | Mở khoá kiến thức | Biết 慑 (nhiếp) là nắm được 震慑 (chấn nhiếp — răn đe), 威慑 (uy nhiếp — uy lực răn đe).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 慑 (phồn thể: 懾) là chữ hình thanh: 忄(心 — tâm, biểu nghĩa) kết hợp với 聶 (nhiếp, biểu âm). Nghĩa gốc là sợ hãi, khiếp sợ; sau mở rộng sang ý nghĩa uy hiếp, làm cho người khác run sợ. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sợ oai, sợ uy; uy hiếp", "Hạng Tần Suất (Jun Da)": "2964.0", "Tần Suất % (Jun Da)": "99.1475742896", "GavinGrover_Once (Chiết tự trực tiếp)": "忄 + 聂", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰忄聂", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "聂", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "忄", "Unihan_Simplified (Chữ Giản thể)": "慑", "Unihan_Traditional (Chữ Phồn thể)": "慴", "Pinyin_Xie": "shè", "Âm Hán Việt_Xie": "nhiếp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ mang tân ngữ để chỉ việc dùng uy thế làm cho người khác sợ hãi. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('婶', '{"9000": "2965.0", "Chữ Trung Quốc": "婶", "Bộ thủ & thành phần_Xie": "Bộ thủ | 女 | Số nét | 11 | nét | 婶 | thẩm | tượng hình | thím, vợ chú | 婶 là dạng giản thể của 嬸. Chữ phồn thể 嬸 gồm 女 (nữ — phụ nữ, biểu nghĩa) + 審 (thẩm — biểu âm). Chữ giản thể rút gọn 審 thành 审.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thẩm\": chữ Nữ (女) đi kèm âm \"thẩm\" — 婶 (thẩm) là thím, người phụ nữ vai vế trong gia tộc. | Gương Hán-Việt | \"thẩm\" ít gặp riêng lẻ; chủ yếu dùng trong \"thím\" (婶子 — cách gọi thím ở miền Bắc Trung Quốc). | Mở khoá kiến thức | Biết 婶 (thẩm) là nhận ra 婶子 (thím), 婶婶 (thím thím — cách gọi thân mật).", "Tự nguyên_Xie": "婶 là dạng giản thể của 嬸, được giản hóa theo nguyên tắc thay 審 bằng 审. Chữ phồn thể 嬸 là hình thanh: 女 (nữ, biểu nghĩa) + 審/审 (thẩm, biểu âm). Chỉ người phụ nữ là vợ chú ruột hoặc người em dâu của cha. Chưa có nguồn học thuật riêng cho dạng giản thể. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thím, vợ của chú; em dâu", "Hạng Tần Suất (Jun Da)": "2965.0", "Tần Suất % (Jun Da)": "99.1485897724", "GavinGrover_Once (Chiết tự trực tiếp)": "女 + 审", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰女审", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "审", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "女", "Unihan_Simplified (Chữ Giản thể)": "婶", "Unihan_Traditional (Chữ Phồn thể)": "嬸", "Pinyin_Xie": "shěn", "Âm Hán Việt_Xie": "thẩm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng độc lập hoặc kết hợp với từ chỉ quan hệ gia đình để xưng hô. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('斐', '{"9000": "2966.0", "Chữ Trung Quốc": "斐", "Bộ thủ & thành phần_Xie": "Bộ thủ | 文 | Số nét | 12 | nét | 斐 | phỉ | tượng hình | văn vẻ, rực rỡ | 斐 là chữ độc thể, không có phân tích hình thanh hay hội ý rõ ràng từ nguồn học thuật. Theo một số thuyết, chữ có thể liên quan đến hoa văn trang trí (文) kết hợp bộ phận khác, nhưng Wiktionary không cung cấp phân tích cụ thể.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phỉ\": 斐然 — nổi bật, rực rỡ; 斐 (phỉ) gợi vẻ đẹp văn chương được khen ngợi, giống chữ phỉ báng nhưng lại mang nghĩa tốt đẹp. | Gương Hán-Việt | \"phỉ\" ít gặp trong tiếng Việt gốc Hán hiện đại; chủ yếu qua từ 斐然 (phỉ nhiên — nổi bật, xuất sắc). | Mở khoá kiến thức | Biết 斐 (phỉ) là nhận ra 斐然 (phỉ nhiên — xuất sắc), 斐济 (Phỉ Tế — Fiji), 成绩斐然 (thành tích nổi bật).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Wiktionary ghi {{Han etym}} nhưng không có phân tích cụ thể về cấu trúc 斐. Chữ mang nghĩa \"rực rỡ, văn vẻ, xuất sắc\" (như trong 斐然 — nổi bật, 斐然成章 — viết đẹp đáng khen). Một thuyết cho rằng đây là chữ hội ý hoặc tượng hình liên quan đến hoa văn, nhưng chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "văn vẻ", "Hạng Tần Suất (Jun Da)": "2966.0", "Tần Suất % (Jun Da)": "99.1496042217", "GavinGrover_Once (Chiết tự trực tiếp)": "非 + 文", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱非文", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "文", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "非", "Unihan_Simplified (Chữ Giản thể)": "斐", "Unihan_Traditional (Chữ Phồn thể)": "斐", "Pinyin_Xie": "fěi", "Âm Hán Việt_Xie": "phỉ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường làm tính từ trong văn viết để mô tả sự rực rỡ, nổi bật của thành tích hoặc văn chương. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('嘘', '{"9000": "2967.0", "Chữ Trung Quốc": "嘘", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 14 | nét | 嘘 | hư | tượng hình | thở ra, hà hơi | 嘘 là dạng giản thể (biến thể) của 噓. Chữ phồn thể 噓 gồm 口 (khẩu — miệng, biểu nghĩa) + 虛 (hư — biểu âm). Dạng giản thể thay 虛 bằng 虚, xuất hiện từ thời Tống.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hư\": miệng (口) thở ra tiếng \"hư\" — 嘘 là âm thở dài, lời suỵt \"suỵt\" bảo người khác im lặng. | Gương Hán-Việt | \"hư\" xuất hiện trong tiếng Việt qua 嘘寒问暖 (hư hàn — hỏi thăm), nhưng chủ yếu dùng như âm thanh (tiếng suỵt). | Mở khoá kiến thức | Biết 嘘 (hư) là nhận ra 嘘寒问暖 (hư hàn vấn noãn — hỏi han ân cần), 唏嘘 (hi hư — thở dài thương tiếc).", "Tự nguyên_Xie": "Tiểu triện | 嘘 là biến thể giản thể của 噓, được ghi nhận trong từ điển Tập Vận (集韻) thời Tống (1039 SCN). Chữ phồn thể 噓 là hình thanh: 口 (miệng, biểu nghĩa) + 虛 (hư, biểu âm). Nghĩa gốc là thở ra từ từ, hà hơi; sau mở rộng sang than thở, tiếng suỵt giữ im lặng. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thở ra từ từ, hà hơi; than thở, thở dài", "Hạng Tần Suất (Jun Da)": "2967.0", "Tần Suất % (Jun Da)": "99.1506160869", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 虚", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口虚", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "虚", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "嘘", "Unihan_Traditional (Chữ Phồn thể)": "噓", "Pinyin_Xie": "xū", "Âm Hán Việt_Xie": "hư", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thán từ | 叹词 | Thường làm động từ chỉ hành động thở ra, hà hơi hoặc làm thán từ để ra hiệu im lặng. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Thán từ | 叹词 | Bộc lộ cảm xúc hoặc dùng để gọi đáp: 啊, 哦, 喂. Đứng tách riêng ở đầu câu, không làm thành phần câu.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('镶', '{"9000": "2968.0", "Chữ Trung Quốc": "镶", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 22 | nét | 钅 | kim | biểu nghĩa | kim loại | 襄 | tương | biểu âm | trợ giúp, bao bọc (cho âm xiāng) | 镶 = 钅(Kim, biểu nghĩa: kim loại) + 襄 (Tương, biểu âm); chữ hình thanh. Bộ kim chỉ chất liệu; 襄 cho âm đọc xiāng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tương\": kim loại (钅) bao bọc (襄) quanh viên ngọc — thợ kim hoàn khảm đá quý vào trang sức. | Gương Hán-Việt | ''tương'' trong ''khảm tương'' (khảm bạc), dùng trong nghề kim hoàn truyền thống | Mở khoá kiến thức | Biết 镶 mở khoá: 镶嵌 (khảm, nạm), 镶边 (viền), 镶牙 (bọc răng)", "Tự nguyên_Xie": "Tiểu triện | 镶 (phồn thể: 鑲) là chữ hình thanh: bộ 钅(金, kim loại) biểu nghĩa; 襄 biểu âm với âm xiāng. Nghĩa gốc và nghĩa hiện dùng đều là ''khảm, nạm'' — chèn một vật liệu quý (đá, ngọc) vào nền kim loại hoặc gỗ. Mở rộng sang ''viền, lót, trám''. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "các vật hoà hợp với nhau; vá, trám, nạm", "Hạng Tần Suất (Jun Da)": "2968.0", "Tần Suất % (Jun Da)": "99.151623818", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 襄", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅襄", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "襄", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "镶", "Unihan_Traditional (Chữ Phồn thể)": "鑲", "Pinyin_Xie": "xiāng", "Âm Hán Việt_Xie": "tương", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước danh từ chỉ vật liệu để diễn tả hành động khảm, nạm hoặc viền trang trí. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | xiāng | / | khảm | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Từ III", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('炕', '{"9000": "2969.0", "Chữ Trung Quốc": "炕", "Bộ thủ & thành phần_Xie": "Bộ thủ | 火 | Số nét | 8 | nét | 炕 | kháng | tượng hình | giường sưởi bằng lửa | 炕 là chữ hình thanh gồm 火/灬 (hoả — lửa, biểu nghĩa) + 亢 (kháng — biểu âm). Lửa (火) dưới sàn làm nóng giường nằm, gợi đúng nghĩa giường kháng (sưởi ấm).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"kháng\": lửa (火) nung nóng sàn nhà — 炕 (kháng) là chiếc giường sưởi ấm mùa đông phương Bắc, nơi cả nhà quây quần. | Gương Hán-Việt | \"kháng\" ít gặp trong tiếng Việt hiện đại; 炕 là từ văn hóa Trung-Triều đặc thù. | Mở khoá kiến thức | Biết 炕 (kháng) là nhận ra 土炕 (thổ kháng — giường đất sưởi), 上炕 (thượng kháng — lên giường sưởi).", "Tự nguyên_Xie": "Tiểu triện | 炕 có {{Han etym}} nhưng Wiktionary không cung cấp phân tích chi tiết về nguồn gốc. Theo cấu trúc chữ, đây là hình thanh: 火 (lửa, biểu nghĩa) + 亢 (biểu âm). Chỉ loại giường sưởi bằng lò lửa đặt bên dưới, phổ biến ở miền Bắc Trung Quốc và Triều Tiên. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "khô ráo; nướng, sấy; hé ra, mở ra", "Hạng Tần Suất (Jun Da)": "2969.0", "Tần Suất % (Jun Da)": "99.1526310322", "GavinGrover_Once (Chiết tự trực tiếp)": "火 + 亢", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰火亢", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "亢", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "火", "Unihan_Simplified (Chữ Giản thể)": "炕", "Unihan_Traditional (Chữ Phồn thể)": "匟", "Pinyin_Xie": "kàng", "Âm Hán Việt_Xie": "kháng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường làm danh từ chỉ loại giường đất sưởi ấm ở miền bắc Trung Quốc hoặc làm động từ chỉ việc sấy khô. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('宦', '{"9000": "2970.0", "Chữ Trung Quốc": "宦", "Bộ thủ & thành phần_Xie": "Bộ thủ | 宀 | Số nét | 9 | nét | 宀 | miên | bộ phận | mái nhà, phủ quan | 臣 | thần | bộ phận | bề tôi, quan lại | 宦 = 宀 (Miên — mái nhà/phủ quan, biểu nghĩa) + 臣 (Thần — bề tôi, biểu nghĩa); chữ hội ý. Bề tôi (臣) trong phủ quan (宀) — hình ảnh người hầu hạ trong triều đình.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hoạn\": bề tôi (臣) sống trong phủ quan (宀) — đó là 宦 (hoạn) người làm quan, tôi tớ triều đình. | Gương Hán-Việt | \"hoạn\" xuất hiện trong \"hoạn quan\" (宦官 — thái giám), \"hoạn lộ\" (宦路 — con đường làm quan), \"hoạn nạn\" (hoạn 患 khác — tai họa). | Mở khoá kiến thức | Biết 宦 (hoạn) là nắm được 宦官 (hoạn quan — thái giám), 仕宦 (sĩ hoạn — làm quan), 宦途 (hoạn đồ — con đường quan lộ).", "Tự nguyên_Xie": "Kim văn | Bạch thư | Theo Wiktionary, 宦 là chữ hội ý: 宀 (mái nhà, phủ quan) + 臣 (bề tôi, tôi tớ). Nghĩa gốc là nô lệ, tôi tớ trong nhà; sau mở rộng sang làm quan trong triều. Từ đó có 宦官 (hoạn quan — quan thái giám). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "làm quan; hầu hạ", "Hạng Tần Suất (Jun Da)": "2970.0", "Tần Suất % (Jun Da)": "99.1536377296", "GavinGrover_Once (Chiết tự trực tiếp)": "宀 + 臣", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱宀臣", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "臣", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "宀", "Unihan_Simplified (Chữ Giản thể)": "宦", "Unihan_Traditional (Chữ Phồn thể)": "宦", "Pinyin_Xie": "huàn", "Âm Hán Việt_Xie": "hoạn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường làm danh từ trong các từ ghép chỉ quan lại hoặc làm động từ chỉ việc ra làm quan. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('趴', '{"9000": "2971.0", "Chữ Trung Quốc": "趴", "Bộ thủ & thành phần_Xie": "Bộ thủ | 足 | Số nét | 9 | nét | 𧾷 | biểu nghĩa | chân (biến thể của 足: khẩu + chỉ) | 八 | bát | biểu âm | tám (cho âm pā) | 趴 = 足(biến thể 𧾷, biểu nghĩa: chân) + 八 (Bát, biểu âm); chữ hình thanh. Bộ chân chỉ tư thế cơ thể; 八 cho âm pā.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bát\": chân (足) xoè ra như chữ 八 (tám) — hình ảnh người nằm sấp, tứ chi duỗi ra bốn phía. | Gương Hán-Việt | ''bát'' ít dùng độc lập; chữ này chủ yếu gặp trong khẩu ngữ Trung Quốc hiện đại | Mở khoá kiến thức | Biết 趴 mở khoá: 趴下 (nằm sấp xuống), 趴在桌子上 (úp mặt xuống bàn)", "Tự nguyên_Xie": "趴 là chữ hình thanh: thành phần trái là biến thể của 足 (chân) biểu nghĩa tư thế cơ thể; 八 biểu âm với âm pā. Chữ mô tả tư thế nằm sấp, chân duỗi ra như số tám. Đây là chữ tương đối muộn, chủ yếu dùng trong bạch thoại. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nằm sấp, nằm rạp xuống, nằm phục xuống", "Hạng Tần Suất (Jun Da)": "2971.0", "Tần Suất % (Jun Da)": "99.1546413264", "GavinGrover_Once (Chiết tự trực tiếp)": "⻊ + 八", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰⻊八", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "八", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⻊", "Unihan_Simplified (Chữ Giản thể)": "趴", "Unihan_Traditional (Chữ Phồn thể)": "趴", "Pinyin_Xie": "pā", "Âm Hán Việt_Xie": "bát", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này thường làm động từ vị ngữ trong câu để biểu thị tư thế nằm sấp hoặc tựa người vào vật khác. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | pā | / | nghiêng người | / | pā | / | nằm sấp | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Động từ tôi | HSK | HSK 6 | · | Cơ thể và ngoại hình tôi", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('绷', '{"9000": "2972.0", "Chữ Trung Quốc": "绷", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 11 | nét | 绷 | bằng | tượng hình | căng ra, bó chặt | 绷 là dạng giản thể của 繃. Chữ phồn thể 繃 gồm 糸 (mịch — sợi chỉ/dây, biểu nghĩa) + 崩 (băng — biểu âm). Sợi chỉ (糸) căng ra như vật bị bục — gợi nghĩa căng, bó.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bằng\": sợi chỉ (糸) bị kéo căng đến mức bằng phẳng rồi bật ra — 绷 (bằng) là trạng thái căng cứng sắp đứt. | Gương Hán-Việt | \"bằng\" ít gặp trong tiếng Việt; 绷 chủ yếu dùng trong văn nói (绷脸 — mặt lạnh, 绷带 — băng vải). | Mở khoá kiến thức | Biết 绷 (bằng) là nhận ra 绷带 (bằng đới — băng vải y tế), 绷脸 (bằng kiểm — mặt lạnh, không cười).", "Tự nguyên_Xie": "Tiểu triện | 绷 là dạng giản thể của 繃. Wiktionary ghi {{Han etym}} không có chi tiết cụ thể. Theo cấu trúc, 繃 là hình thanh: 糸 (sợi chỉ, biểu nghĩa) + 崩 (biểu âm). Nghĩa chính là căng ra, kéo căng; còn có nghĩa bó chặt, và khi bật ra thì là bung tung. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "căng, trải ra; bó chặt; văng, bật ra, bung ra", "Hạng Tần Suất (Jun Da)": "2972.0", "Tần Suất % (Jun Da)": "99.1556444063", "GavinGrover_Once (Chiết tự trực tiếp)": "纟 + 朋", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰纟朋", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "朋", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "纟", "Unihan_Simplified (Chữ Giản thể)": "绷", "Unihan_Traditional (Chữ Phồn thể)": "綳", "Pinyin_Xie": "běng", "Âm Hán Việt_Xie": "băng, bắng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Thường làm động từ biểu thị hành động căng ra hoặc làm tính từ miêu tả trạng thái căng thẳng của nét mặt. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | běng | / | kéo dài mặt | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Động từ tôi", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('窘', '{"9000": "2973.0", "Chữ Trung Quốc": "窘", "Bộ thủ & thành phần_Xie": "Bộ thủ | 穴 | Số nét | 12 | nét | 窘 | quẫn | tượng hình | túng quẫn, khốn khó | 窘 gồm 穴 (huyệt — lỗ hổng, phòng nhỏ, biểu nghĩa) + 君 (quân — biểu âm). Bị giam trong lỗ nhỏ (穴) gợi cảm giác bị kẹt, túng quẫn, không lối thoát.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quẫn\": bị nhốt trong lỗ hổng (穴) chật hẹp — đó là 窘 (quẫn) cảm giác túng quẫn, không biết xoay sở thế nào. | Gương Hán-Việt | \"quẫn\" xuất hiện trong \"túng quẫn\" (窘迫 — quẫn bách), \"quẫn cảnh\" (窘境 — tình cảnh khó khăn). | Mở khoá kiến thức | Biết 窘 (quẫn) là nắm được 窘迫 (quẫn bách — túng thiếu, khó khăn), 困窘 (khốn quẫn — túng quẫn).", "Tự nguyên_Xie": "Tiểu triện | 窘 có {{Han etym}} nhưng Wiktionary không cung cấp phân tích cụ thể. Theo cấu trúc, đây là hình thanh: 穴 (lỗ hổng, biểu nghĩa) + 君 (biểu âm). Nghĩa là túng thiếu, quẫn bách, rơi vào tình cảnh khó khăn không lối thoát. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "túng thiếu, quẫn bách", "Hạng Tần Suất (Jun Da)": "2973.0", "Tần Suất % (Jun Da)": "99.1566443855", "GavinGrover_Once (Chiết tự trực tiếp)": "穴 + 君", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱穴君", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "君", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "穴", "Unihan_Simplified (Chữ Giản thể)": "窘", "Unihan_Traditional (Chữ Phồn thể)": "窘", "Pinyin_Xie": "jiǒng", "Âm Hán Việt_Xie": "quẫn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường làm tính từ bổ nghĩa cho danh từ hoặc làm vị ngữ để miêu tả hoàn cảnh khó khăn, lúng túng. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('襄', '{"9000": "2974.0", "Chữ Trung Quốc": "襄", "Bộ thủ & thành phần_Xie": "Bộ thủ | 衣 | Số nét | 17 | nét | 𤕦 | biểu âm | 衣 | y | biểu nghĩa | áo, trang phục | 襄 = 𤕦 (biểu âm) + 衣 (Y — áo, biểu nghĩa); chữ hình thanh theo Li Xueqin (2012). Tuy nhiên, trên giáp cốt văn chữ có hình một người hai tay giơ lên trong lúc cởi áo; sau được bổ sung thêm bộ Thủ (tay) và bộ Y (áo).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tương\": hình người (𤕦) trong áo (衣) giơ tay trợ giúp — 襄 (tương) là yểm trợ, phò tá, như \"tương trợ\" giúp đỡ lẫn nhau. | Gương Hán-Việt | \"tương\" xuất hiện trong \"tương trợ\" (襄助 — giúp đỡ), địa danh 襄阳 (Tương Dương). | Mở khoá kiến thức | Biết 襄 (tương) là nhận ra 襄助 (tương trợ — yểm trợ), 赞襄 (tán tương — hỗ trợ), 襄阳 (Tương Dương — tên thành phố).", "Tự nguyên_Xie": "Giáp cốt văn | Kim văn | Theo Wiktionary và Li Xueqin (2012), 襄 là hình thanh gồm 𤕦 (biểu âm) + 衣 (y — biểu nghĩa). Nhưng trên giáp cốt văn, chữ có hình một người đang giơ tay cởi trang phục; về sau thêm bộ tay và bộ áo. Nghĩa gốc liên quan đến việc trợ giúp, nâng đỡ; sau mở rộng sang hỗ trợ trong triều chính. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1077.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Y (034) Tỉnh (106) Khẩu (030)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Tỉnh (số 106 - hình mảnh ruộng vuông vức) và hai chữ Khẩu (số 030 - miệng) nằm ở trong chữ Y (số 034 - áo/bị tách làm hai nửa trên dưới). Khi cày ruộng, cả người và trâu đều thở hồng hộc, nóng quá nên phải cởi áo ra. Giải thích sự chuyển ý: Đây là chữ Hội ý. Tương mang nghĩa là cởi áo khi cày ruộng. Cũng có nghĩa là trợ giúp, giúp đỡ (tương trợ).", "Nghĩa Tiếng Việt_Xie": "sửa trị giúp; ngựa kéo xe; sao đổi ngôi", "Hạng Tần Suất (Jun Da)": "2974.0", "Tần Suất % (Jun Da)": "99.157643848", "GavinGrover_Once (Chiết tự trực tiếp)": "衣 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴衣", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "襄", "Unihan_Traditional (Chữ Phồn thể)": "襄", "Pinyin_Xie": "xiāng", "Âm Hán Việt_Xie": "tương", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường dùng trong văn viết cổ hoặc kết hợp thành từ ghép để chỉ sự trợ giúp, hoàn thành công việc. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('珀', '{"9000": "2975.0", "Chữ Trung Quốc": "珀", "Bộ thủ & thành phần_Xie": "Bộ thủ | 玉 | Số nét | 9 | nét | 玉 | ngọc | biểu nghĩa | ngọc | 白 | bạch | biểu âm | 珀 = 玉 (Ngọc — đá quý, biểu nghĩa) + 白 (Bạch, biểu âm); chữ hình thanh. Ngọc (玉) kết hợp âm Bạch (白) tạo ra tên cho một loại đá quý.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phách\": ngọc (玉) mang âm Bạch (白) — 珀 (phách) là hổ phách, viên nhựa hóa thạch màu vàng cam quý như ngọc, sáng như bạch ngọc. | Gương Hán-Việt | \"phách\" xuất hiện duy nhất trong \"hổ phách\" (琥珀 — amber, nhựa cây hóa thạch màu vàng). | Mở khoá kiến thức | Biết 珀 (phách) là nhận ra 琥珀 (hổ phách — amber), 琥珀色 (màu hổ phách — màu vàng cam).", "Tự nguyên_Xie": "Theo Wiktionary, 珀 là hình thanh: 玉 (ngọc, biểu nghĩa) + 白 (bạch, biểu âm). Chữ hầu như chỉ xuất hiện trong từ 琥珀 (hổ phách — amber), chỉ loại nhựa cây hóa thạch màu vàng cam. Chưa có hình ảnh giáp cốt/kim văn riêng cho chữ này. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: hổ phách 琥珀)", "Hạng Tần Suất (Jun Da)": "2975.0", "Tần Suất % (Jun Da)": "99.1586422769", "GavinGrover_Once (Chiết tự trực tiếp)": "王 + 白", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰王白", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "白", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "王", "Unihan_Simplified (Chữ Giản thể)": "珀", "Unihan_Traditional (Chữ Phồn thể)": "珀", "Pinyin_Xie": "pò", "Âm Hán Việt_Xie": "phách", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường không đứng độc lập mà kết hợp với chữ hổ để tạo thành danh từ ghép hổ phách chỉ một loại đá quý. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('嚣', '{"9000": "2976.0", "Chữ Trung Quốc": "嚣", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 18 | nét | 㗊 | bộ phận | bốn miệng, huyên náo | 頁 | hiệt | bộ phận | đầu người | 嚣 = 㗊 (bốn cái miệng đang la hét, biểu nghĩa) + 頁 (Hiệt — đầu người, biểu nghĩa); chữ hội ý. Bốn miệng (㗊) trên đầu người (頁) gợi cảnh đám đông ồn ào, huyên náo.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hiêu\": bốn miệng (㗊) la hét trên đầu người (頁) — 嚣 (hiêu) là tiếng ồn huyên náo, đám đông hiêu chiến. | Gương Hán-Việt | \"hiêu\" xuất hiện trong \"hiêu trương\" (嚣张 — ngạo mạn), \"huyên hiêu\" (喧嚣 — ồn ào náo động). | Mở khoá kiến thức | Biết 嚣 (hiêu) là nắm được 嚣张 (hiêu trương — ngạo mạn), 喧嚣 (huyên hiêu — ồn ào), 叫嚣 (khiếu hiêu — kêu la).", "Tự nguyên_Xie": "Kim văn | Đại triện | Theo Wiktionary, 嚣 (phồn thể: 囂) là hội ý: 㗊 (bốn miệng, ồn ào) + 頁 (đầu người). Hình ảnh đám đông nhiều miệng la hét trên đầu — gợi cảnh huyên náo, ồn ào. Nghĩa mở rộng: ngạo mạn, kiêu căng. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "rầm rĩ", "Hạng Tần Suất (Jun Da)": "2976.0", "Tần Suất % (Jun Da)": "99.1596396722", "GavinGrover_Once (Chiết tự trực tiếp)": "㗊 + 页", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴㗊页", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "㗊", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "页", "Unihan_Simplified (Chữ Giản thể)": "嚣", "Unihan_Traditional (Chữ Phồn thể)": "囂", "Pinyin_Xie": "xiāo", "Âm Hán Việt_Xie": "hiêu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường làm tính từ miêu tả âm thanh ồn ào hoặc làm động từ trong các từ ghép chỉ sự huyên náo. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('拚', '{"9000": "2977.0", "Chữ Trung Quốc": "拚", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 8 | nét | 扌 | thủ | biểu nghĩa | tay | 弁 | biện | biểu âm | 拚 = 扌 (Thủ — tay, biểu nghĩa) + 弁 (Biện, biểu âm); chữ hình thanh. Tay (扌) hành động với âm 弁, tạo ra chữ chỉ hành động mạnh bạo, liều lĩnh bằng tay.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phấn\": hai tay (扌) ra sức với âm 弁 — 拚 (phấn) là liều lĩnh, phấn đấu hết mình không tiếc bản thân. | Gương Hán-Việt | \"phấn\" ít gặp trong tiếng Việt hiện đại; 拚命 (phấn mệnh — liều mình) là cụm quan trọng nhất. | Mở khoá kiến thức | Biết 拚 (phấn) là nhận ra 拚命 (phấn mệnh — liều mạng, cố hết sức), 拚死 (phấn tử — liều chết).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 拚 là hình thanh: 扌 (tay, biểu nghĩa) + 弁 (biểu âm). Có hai cách đọc: pàn (quét rác, nghĩa gốc) và pīn (liều mình, cố hết sức — nghĩa phổ biến hiện đại). Trong tiếng Trung hiện đại, 拚 thường dùng với nghĩa cố hết sức, liều thân (同义词 của 拼). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1717.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thủ (064) Biện (1716)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Thủ (số 064 - cái tay/ 扌/chỉ ý) ở bên trái chữ Biện (số 1716 - cái mũ/ 弁 /chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Biện chỉ âm, bộ Thủ chỉ ý. Biện là hành động dùng tay vỗ, đánh (vỗ tay).", "Nghĩa Tiếng Việt_Xie": "quét rác", "Hạng Tần Suất (Jun Da)": "2977.0", "Tần Suất % (Jun Da)": "99.1606365507", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 弁", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌弁", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "弁", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "拚", "Unihan_Traditional (Chữ Phồn thể)": "拚", "Pinyin_Xie": "pàn", "Âm Hán Việt_Xie": "biện", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ biểu thị hành động quét dọn hoặc liều mạng, dốc sức làm việc gì đó. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('酌', '{"9000": "2978.0", "Chữ Trung Quốc": "酌", "Bộ thủ & thành phần_Xie": "Bộ thủ | 酉 | Số nét | 10 | nét | 酉 | dậu | biểu nghĩa | bình rượu, rượu | 勺 | thược | biểu âm | cái muỗng (cho âm zhuó) | 酌 = 酉 (Dậu, biểu nghĩa: bình rượu) + 勺 (Thược, biểu âm); chữ hình thanh. Bộ dậu chỉ đồ đựng rượu; 勺 (cái muỗng múc) vừa cho âm vừa gợi hành động múc rót.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chước\": bình rượu (酉) và cái muỗng (勺) — rót từng muỗng rượu đòi hỏi sự cẩn thận, giống như ''châm chước'' (cân nhắc cẩn thận). | Gương Hán-Việt | ''chước'' trong ''châm chước'' (xem xét linh hoạt), 斟酌 (cân nhắc kỹ) | Mở khoá kiến thức | Biết 酌 mở khoá: 斟酌 (cân nhắc), 酌情 (tuỳ tình hình), 对酌 (uống rượu cùng nhau)", "Tự nguyên_Xie": "Giáp cốt văn | Kim văn | Tiểu triện | 酌 là chữ hình thanh: 酉 (bình rượu) biểu nghĩa; 勺 biểu âm gần với âm zhuó. Nghĩa gốc là ''rót rượu, múc rượu bằng muỗng''. Từ hành động cẩn thận múc từng muỗng rượu, chữ mở rộng sang nghĩa ''cân nhắc, xem xét kỹ'' (như trong 斟酌). Gặp trong giáp cốt văn và kim văn với hình bình rượu và muỗng. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "rót rượu, uống rượu", "Hạng Tần Suất (Jun Da)": "2978.0", "Tần Suất % (Jun Da)": "99.1616329124", "GavinGrover_Once (Chiết tự trực tiếp)": "酉 + 勺", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰酉勺", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "勺", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "酉", "Unihan_Simplified (Chữ Giản thể)": "酌", "Unihan_Traditional (Chữ Phồn thể)": "酌", "Pinyin_Xie": "zhuó", "Âm Hán Việt_Xie": "chước", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ chỉ hành động rót rượu, uống rượu hoặc cân nhắc, suy xét kỹ lưỡng. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('浊', '{"9000": "2979.0", "Chữ Trung Quốc": "浊", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 9 | nét | 氵 | thuỷ | biểu nghĩa | nước | 虫 | trùng | biểu âm | sâu bọ (cho âm zhuó trong phồn thể 濁=蜀+氵) | 浊 là chữ giản thể của 濁. Phồn thể 濁 = 氵(Thuỷ, biểu nghĩa: nước) + 蜀 (Thục, biểu âm); chữ hình thanh. Khi giản thể hoá, 蜀 rút gọn thành 虫.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trọc\": nước (氵) có sâu bọ (虫) lội — ao tù đục ngầu như \"ô trọc\" trong tiếng Việt. | Gương Hán-Việt | ''trọc'' trong ''ô trọc'' (dơ bẩn, đục ngầu), ''trọc thế'' (thế giới ô uế) | Mở khoá kiến thức | Biết 浊 mở khoá: 混浊 (đục ngầu), 浑浊 (vẩn đục), 清浊 (trong và đục)", "Tự nguyên_Xie": "Kim văn | Bạch thư | Đại triện | Tiểu triện | 浊 là dạng giản thể của 濁, xuất hiện trong từ điển thời Minh và được Trung Quốc chính thức hoá năm 1956. Phồn thể 濁 gồm bộ 氵(nước) biểu nghĩa nước đục, và 蜀 biểu âm (âm cổ gần zhuó). Ý nghĩa cốt lõi là nước vẩn đục, không trong, đối lập với 清 (trong). Hình ảnh kim văn và bạch thư đã xác nhận cấu trúc này. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đục (nước)", "Hạng Tần Suất (Jun Da)": "2979.0", "Tần Suất % (Jun Da)": "99.162627207", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 虫", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵虫", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "虫", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "浊", "Unihan_Traditional (Chữ Phồn thể)": "濁", "Pinyin_Xie": "zhuó", "Âm Hán Việt_Xie": "trọc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường làm tính từ đứng trước danh từ hoặc làm vị ngữ để miêu tả trạng thái không trong suốt của chất lỏng. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('毓', '{"9000": "2980.0", "Chữ Trung Quốc": "毓", "Bộ thủ & thành phần_Xie": "Bộ thủ | 毋 | Số nét | 14 | nét | 母 | mẫu | bộ phận | người mẹ, phụ nữ | 子 | tử | bộ phận | đứa trẻ, con | 毓 = 母 (Mẫu — người mẹ) + 子 (Tử — đứa trẻ); chữ tượng hình ban đầu. Wiktionary ghi ls=p (pictograph): hình người mẹ sinh con. Về sau được cách điệu thành 每 + 㐬. Đây là dạng gốc của chữ 育 (dục — nuôi nấng).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"dục\": hình mẹ (母) ôm con (子) — 毓 (dục) là sinh nở, nuôi nấng, như \"dục\" trong \"giáo dục\" mang hàm nghĩa vun bồi. | Gương Hán-Việt | \"dục\" xuất hiện trong \"chung linh dục tú\" (钟灵毓秀 — nơi linh thiêng sinh người tài giỏi), và nhiều tên người Việt gốc Hán. | Mở khoá kiến thức | Biết 毓 (dục) là nhận ra 钟灵毓秀 (chung linh dục tú — vùng đất sinh anh tài), 毓婷 (tên thuốc tránh thai phổ biến ở Trung Quốc).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 毓 có nguồn gốc là tượng hình (ls=p): hình một người mẹ (母) đang sinh đứa trẻ (子). Đây là dạng nguyên thủy của 育 (nuôi nấng). Sau này được cách điệu và trang trí thêm, trở thành dạng mỗi (每) + lưu (㐬). Chữ mang nghĩa sinh ra, sinh đẻ, nuôi nấng; dùng nhiều trong tên người (vì nghĩa tốt đẹp). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nuôi nấng", "Hạng Tần Suất (Jun Da)": "2980.0", "Tần Suất % (Jun Da)": "99.1636215016", "GavinGrover_Once (Chiết tự trực tiếp)": "每 + 㐬", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰每㐬", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "㐬", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "每", "Unihan_Simplified (Chữ Giản thể)": "毓", "Unihan_Traditional (Chữ Phồn thể)": "毓", "Pinyin_Xie": "yù", "Âm Hán Việt_Xie": "dục", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ trong văn viết cổ hoặc dùng trong tên riêng để chỉ việc nuôi dưỡng, giáo dục. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('撼', '{"9000": "2981.0", "Chữ Trung Quốc": "撼", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 16 | nét | 扌 | thủ | biểu nghĩa | tay | 感 | cảm | biểu âm | cảm xúc (cho âm hàn/hám) | 撼 = 扌(Thủ, biểu nghĩa: tay) + 感 (Cảm, biểu âm); chữ hình thanh. Bộ thủ chỉ hành động dùng tay lay; 感 cho âm hàn. Chữ tạo muộn, chỉ thấy trong Lục thư thông (thời Minh), chưa thấy giáp cốt/kim văn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hám\": bàn tay (扌) tác động gây ra cảm xúc mạnh (感) — khi bạn bị chấn 撼 (震撼), trái tim thực sự bị lay động. | Gương Hán-Việt | ''hám'' ít gặp độc lập; thường gặp trong 震撼 (chấn hám — rung chuyển mạnh) | Mở khoá kiến thức | Biết 撼 mở khoá: 震撼 (chấn động, rung chuyển), 撼动 (làm lay chuyển)", "Tự nguyên_Xie": "Lục thư thông | 撼 là chữ hình thanh tương đối muộn: 扌(tay) biểu nghĩa hành động; 感 biểu âm. Wiktionary chỉ ghi pronunciation và định nghĩa, không có mô tả glyph-origin chi tiết. Nghĩa chính là ''lắc, rung, làm lay động''. Hình ảnh duy nhất còn lưu trong Lục thư thông (chữ tạo muộn, chưa thấy trong giáp cốt/kim văn). | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lay, động", "Hạng Tần Suất (Jun Da)": "2981.0", "Tần Suất % (Jun Da)": "99.1646147627", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 感", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌感", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "感", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "撼", "Unihan_Traditional (Chữ Phồn thể)": "撼", "Pinyin_Xie": "hàn", "Âm Hán Việt_Xie": "hám", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ mang tân ngữ để biểu thị tác động làm rung chuyển hoặc lay động lòng người. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('嗜', '{"9000": "2982.0", "Chữ Trung Quốc": "嗜", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 13 | nét | 嗜 | thị | tượng hình | ham thích, nghiện | 嗜 gồm 口 (khẩu — miệng, biểu nghĩa) + 耆 (kỳ/kỳ lão — biểu âm). Miệng (口) theo đuổi điều mình thèm muốn — gợi nghĩa ham thích, nghiện ngập. Chưa có phân tích học thuật chi tiết trên Wiktionary.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thị\": miệng (口) cứ theo đuổi điều mình thèm — 嗜 (thị) là ham muốn, nghiện ngập không bỏ được. | Gương Hán-Việt | \"thị\" trong ngữ cảnh này ít gặp trong tiếng Việt hiện đại; 嗜好 (thị hiếu — sở thích/thói quen) là cụm quan trọng. | Mở khoá kiến thức | Biết 嗜 (thị) là nắm được 嗜好 (thị hiếu — sở thích, thói quen), 嗜酒 (thị tửu — nghiện rượu), 嗜睡 (thị thụy — ngủ gà ngủ gật).", "Tự nguyên_Xie": "嗜 có {{Han etym}} nhưng Wiktionary không cung cấp phân tích cụ thể. Theo cấu trúc, đây là hình thanh: 口 (miệng, biểu nghĩa) + 耆 (biểu âm). Nghĩa là ham thích, nghiện ngập; miệng cứ thèm muốn thứ gì đó không thôi. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ham thích", "Hạng Tần Suất (Jun Da)": "2982.0", "Tần Suất % (Jun Da)": "99.1656080237", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 耆", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口耆", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "耆", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "嗜", "Unihan_Traditional (Chữ Phồn thể)": "嗜", "Pinyin_Xie": "shì", "Âm Hán Việt_Xie": "thị", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ tâm lý đứng trước danh từ chỉ sở thích hoặc thói quen để biểu thị sự đam mê. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('扛', '{"9000": "2983.0", "Chữ Trung Quốc": "扛", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 6 | nét | 扌 | thủ | biểu nghĩa | tay | 工 | công | biểu âm | công việc, thợ (cho âm gāng/káng) | 扛 = 扌(Thủ, biểu nghĩa: tay) + 工 (Công, biểu âm); chữ hình thanh. Bộ thủ chỉ hành động dùng tay, vai vác đồ; 工 cho âm gāng/káng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khiêng\": đôi bàn tay (扌) làm công việc nặng (工) — hình ảnh người thợ vác gỗ trên vai, đúng với ''khiêng'' trong tiếng Việt. | Gương Hán-Việt | ''khiêng'' trong tiếng Việt vay mượn ý nghĩa ''vác, khiêng'' từ chữ này; cũng đọc là ''kháng'' trong từ Hán-Việt | Mở khoá kiến thức | Biết 扛 mở khoá: 扛活 (làm việc nặng nhọc), 扛着 (gánh chịu, vác), 一肩扛 (một mình gánh vác)", "Tự nguyên_Xie": "Tiểu triện | 扛 là chữ hình thanh: 扌(手, tay) biểu nghĩa; 工 biểu âm. Nghĩa gốc là ''nâng bằng hai tay'' hoặc ''khiêng chung nhiều người''; nghĩa phổ biến hiện nay là ''vác trên vai'' (một người). Tiểu triện đã xác nhận cấu trúc này. Có hai âm: gāng (vác nâng bằng hai tay) và káng (vác trên vai). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mang, vác, cõng, khiêng", "Hạng Tần Suất (Jun Da)": "2983.0", "Tần Suất % (Jun Da)": "99.1666007679", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 工", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌工", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "工", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "扛", "Unihan_Traditional (Chữ Phồn thể)": "扛", "Pinyin_Xie": "káng", "Âm Hán Việt_Xie": "giang, cang", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước danh từ chỉ vật để biểu thị hành động mang vác trên vai. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | káng | / | vác | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Phong trào II | HSK | HSK 6 | · | Sự chuyển động", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('峭', '{"9000": "2984.0", "Chữ Trung Quốc": "峭", "Bộ thủ & thành phần_Xie": "Bộ thủ | 山 | Số nét | 10 | nét | 山 | sơn | biểu nghĩa | núi | 肖 | tiêu | biểu âm | giống, nhỏ (cho âm qiào) | 峭 = 山 (Sơn, biểu nghĩa: núi) + 肖 (Tiêu, biểu âm); chữ hình thanh. Ban đầu dùng bộ 阜 (gò đất), sau thay bằng 山. Bộ sơn chỉ địa hình núi; 肖 cho âm qiào.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tiễu\": núi (山) cao mà nhỏ (肖 ~ tiểu) bề ngang — vách đá dựng đứng, tưởng như chỉ cần đứng ngắm là đã chóng mặt. | Gương Hán-Việt | ''tiễu'' trong ''tiễu bích'' (vách đá dốc đứng), 陡峭 (dốc đứng) | Mở khoá kiến thức | Biết 峭 mở khoá: 陡峭 (dốc đứng), 峭壁 (vách đá dựng đứng), 悬崖峭壁 (vực thẳm vách đá)", "Tự nguyên_Xie": "Tiểu triện | 峭 là chữ hình thanh, theo Wiktionary ban đầu được viết với bộ 阜 (gò đất cao) + 肖 biểu âm, sau đổi sang bộ 山 (núi). Nghĩa chính là ''dốc đứng, chót vót'' — mô tả vách núi dựng thẳng. Nghĩa mở rộng là tính khí ''nóng nảy, gay gắt''. Tiểu triện xác nhận cấu trúc hiện tại. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cao chót vót; tính nóng nảy", "Hạng Tần Suất (Jun Da)": "2984.0", "Tần Suất % (Jun Da)": "99.1675919618", "GavinGrover_Once (Chiết tự trực tiếp)": "山 + 肖", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰山肖", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "肖", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "山", "Unihan_Simplified (Chữ Giản thể)": "峭", "Unihan_Traditional (Chữ Phồn thể)": "峭", "Pinyin_Xie": "qiào", "Âm Hán Việt_Xie": "tiễu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường làm tính từ đứng trước danh từ hoặc sau phó từ để miêu tả địa hình hiểm trở hoặc tính cách. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('磕', '{"9000": "2985.0", "Chữ Trung Quốc": "磕", "Bộ thủ & thành phần_Xie": "Bộ thủ | 石 | Số nét | 15 | nét | 石 | thạch | biểu nghĩa | đá | 盍 | hạp | biểu âm | sao không (cho âm kē) | 磕 = 石 (Thạch, biểu nghĩa: đá) + 盍 (Hạp, biểu âm); chữ hình thanh. Bộ thạch chỉ vật cứng va chạm; 盍 cho âm kē.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khái\": đá (石) va vào nhau — tiếng ''khái khái'' khi đầu chạm đất khi lạy, hay khi đồ đạc va nhau. | Gương Hán-Việt | ''khái'' ít dùng độc lập trong tiếng Việt hiện đại; chủ yếu gặp trong 磕头 (khẩu đầu — lạy sát đất) | Mở khoá kiến thức | Biết 磕 mở khoá: 磕头 (lạy sát đất), 磕碰 (va chạm, sứt mẻ), 磕磕绊绊 (vấp váp, trắc trở)", "Tự nguyên_Xie": "Tiểu triện | 磕 là chữ hình thanh: 石 (đá) biểu nghĩa tiếng đá chạm nhau hoặc vật cứng va đập; 盍 biểu âm với âm kē. Nghĩa gốc là ''tiếng đá chọi nhau''; mở rộng sang ''va đầu xuống đất'' (磕头), ''va chạm, sứt mẻ'' (磕碰). Tiểu triện xác nhận cấu trúc. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tiếng đá chọi nhau", "Hạng Tần Suất (Jun Da)": "2985.0", "Tần Suất % (Jun Da)": "99.1685785047", "GavinGrover_Once (Chiết tự trực tiếp)": "石 + 盍", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰石盍", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "盍", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "石", "Unihan_Simplified (Chữ Giản thể)": "磕", "Unihan_Traditional (Chữ Phồn thể)": "磕", "Pinyin_Xie": "kē", "Âm Hán Việt_Xie": "khái", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đi kèm tân ngữ chỉ bộ phận cơ thể hoặc đồ vật bị va chạm. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | kē | / | khấu đầu | / | kē | / | đụng | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Động từ tôi | HSK | HSK 6 | · | Động từ", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('翘', '{"9000": "2986.0", "Chữ Trung Quốc": "翘", "Bộ thủ & thành phần_Xie": "Bộ thủ | 羽 | Số nét | 12 | nét | 尧 | nghiêu | biểu âm | vua Nghiêu (cho âm qiào/qiáo) | 羽 | vũ | biểu nghĩa | lông vũ, cánh chim | 翘 là giản thể của 翹, rút gọn 堯 thành 尧. Chữ gồm 尧 (Nghiêu, biểu âm) + 羽 (Vũ, biểu nghĩa: lông vũ); chữ hình thanh. Bộ vũ gợi hình ảnh lông đuôi chim cong vểnh lên.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"kiều\": lông vũ (羽) của chim kiêu hãnh (尧 ~ cao sang) — cái đuôi vểnh lên hãnh diện, như chim công xoè cánh. | Gương Hán-Việt | ''kiều'' trong ''kiều hãnh'' (ngẩng cao đầu tự hào), 翘首 (trông ngóng) | Mở khoá kiến thức | Biết 翘 mở khoá: 翘首 (trông ngóng), 翘起 (vểnh lên), 翘尾巴 (vênh váo, tự kiêu)", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 翘 là giản thể của 翹, phồn thể gồm 堯 (biểu âm) + 羽 (lông vũ, biểu nghĩa). Nghĩa gốc là ''lông đuôi chim dài, cong vểnh''. Từ hình ảnh lông chim vểnh lên cao, mở rộng sang ''ngẩng lên, nâng cao''. Chữ tạo muộn, chỉ thấy trong tiểu triện và Lục thư thông, chưa thấy giáp cốt/kim văn rõ ràng. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lông dài ở đuôi chim; nâng lên, cất lên, ngẩng lên", "Hạng Tần Suất (Jun Da)": "2986.0", "Tần Suất % (Jun Da)": "99.1695650475", "GavinGrover_Once (Chiết tự trực tiếp)": "尧 + 羽", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴尧羽", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "尧", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "羽", "Unihan_Simplified (Chữ Giản thể)": "翘", "Unihan_Traditional (Chữ Phồn thể)": "翹", "Pinyin_Xie": "qiào", "Âm Hán Việt_Xie": "kiều", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Thường làm động từ biểu thị hành động ngẩng đầu hoặc nâng một đầu của vật lên. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | qiào | / | vểnh lên | Xuất hiện trong lộ trình | HSK | HSK 6 | · | Động từ | New HSK | New HSK 7-9 | · | Động từ tôi", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('槽', '{"9000": "2987.0", "Chữ Trung Quốc": "槽", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 15 | nét | 木 | mộc | biểu nghĩa | gỗ, cây | 曹 | tào | biểu âm | 槽 = 木 (Mộc — gỗ, biểu nghĩa) + 曹 (Tào, biểu âm); chữ hình thanh. Gỗ (木) làm thành máng ăn cho gia súc — hình ảnh cái máng gỗ lõm ở giữa.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tào\": gỗ (木) ghép với Tào (曹) — 槽 (tào) là cái máng gỗ cho ngựa ăn, sau gợi bất kỳ vật hình lõm. | Gương Hán-Việt | \"tào\" xuất hiện trong \"mã tào\" (马槽 — máng ngựa), \"tào mộc\" (槽木 — gỗ máng). | Mở khoá kiến thức | Biết 槽 (tào) là nhận ra 马槽 (mã tào — máng ngựa), 水槽 (thủy tào — bể nước), 跳槽 (bước tào — nhảy việc).", "Tự nguyên_Xie": "Theo Wiktionary, 槽 là hình thanh: 木 (gỗ, biểu nghĩa) + 曹 (tào, biểu âm). Nghĩa gốc là cái máng gỗ cho gia súc ăn uống. Sau mở rộng sang mọi vật hình chữ nhật lõm ở giữa: bể, rãnh, máng dây đàn tỳ bà. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái máng cho muông thú ăn; cái gác dây đàn tỳ bà; cao hai bên, trũng ở giữa", "Hạng Tần Suất (Jun Da)": "2987.0", "Tần Suất % (Jun Da)": "99.1705510735", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 曹", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木曹", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "曹", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "槽", "Unihan_Traditional (Chữ Phồn thể)": "槽", "Pinyin_Xie": "cáo", "Âm Hán Việt_Xie": "tào", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ các loại máng đựng thức ăn cho gia súc hoặc đường rãnh kỹ thuật. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | cáo | / | máng ăn, máng nước | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Ngôi nhà và cuộc sống hàng ngày I", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('淌', '{"9000": "2988.0", "Chữ Trung Quốc": "淌", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 11 | nét | 淌 | thảng | tượng hình | chảy nhỏ giọt, trickle | 淌 gồm 氵 (thủy — nước, biểu nghĩa) + 尚 (thượng — biểu âm). Nước (氵) chảy nhỏ giọt xuống — gợi nghĩa nhỏ giọt, chảy xuôi. Wiktionary không cung cấp phân tích cụ thể.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thảng\": nước (氵) cứ chảy xuôi thảng xuống — 淌 (thảng) là nước nhỏ giọt, nước mắt lặng lẽ chảy dài. | Gương Hán-Việt | \"thảng\" ít gặp riêng lẻ trong tiếng Việt; 淌 chủ yếu dùng trong văn miêu tả (流淌 — lưu thảng, chảy xuôi). | Mở khoá kiến thức | Biết 淌 (thảng) là nhận ra 流淌 (lưu thảng — chảy xuôi), 淌泪 (thảng lệ — nhỏ lệ), 淌汗 (thảng hãn — chảy mồ hôi).", "Tự nguyên_Xie": "淌 có {{Han etym}} nhưng Wiktionary không cung cấp phân tích chi tiết. Theo cấu trúc: 氵 (nước, biểu nghĩa) + 尚 (biểu âm). Nghĩa chính là nước chảy nhỏ giọt xuống, nhỏ lệ, chảy; cũng dùng để chỉ sóng lớn và lội qua (phương ngữ). Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sóng to; nước chảy xuôi; nhỏ giọt", "Hạng Tần Suất (Jun Da)": "2988.0", "Tần Suất % (Jun Da)": "99.171536066", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 尚", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵尚", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "尚", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "淌", "Unihan_Traditional (Chữ Phồn thể)": "淌", "Pinyin_Xie": "tǎng", "Âm Hán Việt_Xie": "thảng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ biểu thị trạng thái chất lỏng như mồ hôi, nước mắt chảy xuống. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | tǎng | / | nhỏ giọt | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Words II", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('栅', '{"9000": "2989.0", "Chữ Trung Quốc": "栅", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 9 | nét | 木 | mộc | biểu nghĩa | cây, gỗ | 冊 | sách | biểu âm | cuộn thẻ tre xếp thành hàng | 栅 = 木 (Mộc — gỗ, biểu nghĩa) + 冊 (Sách — biểu âm, và cũng biểu nghĩa: các thẻ tre xếp hàng); chữ hình thanh kiêm hội ý. Gỗ (木) xếp thành hàng như các thẻ tre (冊) — gợi hình ảnh hàng rào cọc gỗ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sách\": gỗ (木) xếp như sách thẻ (冊) — 栅 (sách) là hàng rào cọc gỗ, mỗi thanh như một trang sách đứng thẳng. | Gương Hán-Việt | \"sách\" ít gặp trong tiếng Việt hiện đại với nghĩa này; 栅栏 (sách lan — hàng rào) là cụm phổ biến nhất. | Mở khoá kiến thức | Biết 栅 (sách) là nhận ra 栅栏 (sách lan — hàng rào), 光栅 (quang sách — cách tử quang học).", "Tự nguyên_Xie": "Giáp cốt văn | Tiểu triện | Theo Wiktionary (Digital Shinjigen 2017), 栅 (phồn thể: 柵) là hình thanh kiêm hội ý: 木 (gỗ, biểu nghĩa) + 冊 (vừa biểu âm vừa biểu nghĩa: hình dạng các thanh gỗ/thẻ tre xếp thành hàng và buộc lại với nhau). Nghĩa là hàng rào, rào chắn làm bằng gỗ. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "hàng rào, rào chắn", "Hạng Tần Suất (Jun Da)": "2989.0", "Tần Suất % (Jun Da)": "99.1725210585", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 册", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木册", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "册", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "栅", "Unihan_Traditional (Chữ Phồn thể)": "柵", "Pinyin_Xie": "zhà", "Âm Hán Việt_Xie": "sách, san", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ để chỉ hàng rào làm bằng tre, gỗ hoặc sắt. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('颓', '{"9000": "2990.0", "Chữ Trung Quốc": "颓", "Bộ thủ & thành phần_Xie": "Bộ thủ | 頁 | Số nét | 13 | nét | 颓 | đồi | tượng hình | sụp đổ, suy tàn | 颓 (phồn thể: 頹) gồm 禿 (trọc — đầu hói, biểu nghĩa/biểu âm) + 頁 (hiệt — đầu). Theo Wiktionary, chữ có nét nghĩa ban đầu liên quan đến đầu hói; sau mở rộng sang sụp đổ, suy tàn. Phân tích đầy đủ không có trên nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đồi\": hình ảnh thứ gì đó sụp đổ không vực lại được — 颓 (đồi) là suy đồi, tinh thần đổ vỡ như 颓废 (đồi phế — trụy lạc). | Gương Hán-Việt | \"đồi\" xuất hiện trong \"đồi phế\" (颓废 — trụy lạc, bỏ bê), \"đồi thế\" (颓势 — thế lực suy yếu). | Mở khoá kiến thức | Biết 颓 (đồi) là nắm được 颓废 (đồi phế — trụy lạc), 颓势 (đồi thế — đà suy), 颓然 (đồi nhiên — buồn chán).", "Tự nguyên_Xie": "Đại triện | 颓 (phồn thể 頹) có {{Han etym}} nhưng Wiktionary không cung cấp phân tích chi tiết. Theo cấu trúc có thể nhận ra bộ 頁 (đầu). Nghĩa gốc liên quan đến ngã xuống, sụp đổ; mở rộng sang suy tàn, sa đọa, tinh thần suy sụp. Một số từ điển ghi liên quan đến 禿 (đầu hói), nhưng chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sụt, lở; suy đồi", "Hạng Tần Suất (Jun Da)": "2990.0", "Tần Suất % (Jun Da)": "99.1735029502", "GavinGrover_Once (Chiết tự trực tiếp)": "秃 + 页", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰秃页", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "秃", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "页", "Unihan_Simplified (Chữ Giản thể)": "颓", "Unihan_Traditional (Chữ Phồn thể)": "穨", "Pinyin_Xie": "tuí", "Âm Hán Việt_Xie": "đồi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường làm tính từ miêu tả trạng thái suy sụp tinh thần hoặc sự suy thoái của sự vật. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('熏', '{"9000": "2991.0", "Chữ Trung Quốc": "熏", "Bộ thủ & thành phần_Xie": "Bộ thủ | 火 | Số nét | 14 | nét | 熏 | huân | tượng hình | chữ tượng hình: bó thảo mộc bốc khói (bộ hoả ở dưới, cây bó ở trên) | 熏 là chữ tượng hình phức hợp: hình gốc là bó thảo mộc/thảo dược (phần trên) đặt trên lửa (火 hoặc 炎 ở dưới). Theo Wiktionary, không liên quan đến chữ 黑 (đen). Chữ hiện tại đã bị cách điệu hoá nhiều qua các thời đại.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"huân\": khói bốc từ bó thảo mộc đặt trên lửa — như người thợ hun cá, hun thịt, hay hương khói huân đúc tính cách người ta theo năm tháng. | Gương Hán-Việt | ''huân'' trong ''huân tập'' (ảnh hưởng dần dần), 熏陶 (huân đào — rèn giũa, ảnh hưởng lâu dài) | Mở khoá kiến thức | Biết 熏 mở khoá: 熏陶 (ảnh hưởng, hun đúc), 熏鱼 (cá hun khói), 烟熏 (hun khói)", "Tự nguyên_Xie": "Kim văn | Đại triện | Tiểu triện | Theo Wiktionary, 熏 ban đầu là hình ảnh bó thảo mộc/thảo dược đặt trong túi buộc (phần 東-like) với lửa (火) ở dưới — nghĩa gốc là ''thảo dược hun khói''. Hai dạng bảo tồn hơn là 𡴦 và 𡽽. Nghĩa gốc nay chuyển sang 薰. Chữ 熏 hiện dùng với nghĩa ''hun, xông khói'' và ''ảnh hưởng dần dần''. Kim văn và đại triện xác nhận cấu trúc này. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "hun lửa", "Hạng Tần Suất (Jun Da)": "2991.0", "Tần Suất % (Jun Da)": "99.174484842", "GavinGrover_Once (Chiết tự trực tiếp)": "No glyph available + 灬", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱灬", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "熏", "Unihan_Traditional (Chữ Phồn thể)": "熏", "Pinyin_Xie": "xūn", "Âm Hán Việt_Xie": "huân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ chỉ hành động dùng khói hoặc hơi nóng để tác động lên vật thể. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | xūn | / | xông khói | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Thực phẩm II", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('瑛', '{"9000": "2992.0", "Chữ Trung Quốc": "瑛", "Bộ thủ & thành phần_Xie": "Bộ thủ | 玉 | Số nét | 12 | nét | 瑛 | anh | tượng hình | ánh sáng ngọc, đá đẹp như ngọc | 瑛 gồm 玉 (ngọc — đá quý, biểu nghĩa) + 英 (anh — biểu âm). Ngọc (玉) tỏa ánh sáng long lanh, gợi nghĩa ánh sáng của ngọc hoặc viên đá đẹp như ngọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"anh\": ngọc (玉) tỏa ánh anh (英) như hoa anh đào — 瑛 (anh) là ánh ngọc long lanh, thường dùng đặt tên con gái. | Gương Hán-Việt | \"anh\" ở đây là âm ngọc/ánh sáng (khác với 英 anh — anh hùng); 瑛 dùng trong tên người Việt gốc Hán. | Mở khoá kiến thức | Biết 瑛 (anh) là nhận ra chữ thường dùng trong tên người (Văn Anh, Thúy Anh) với nghĩa trong sáng, quý giá như ngọc.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 瑛 có {{Han etym}} nhưng Wiktionary không cung cấp phân tích cụ thể. Theo cấu trúc, đây là hình thanh: 玉 (ngọc, biểu nghĩa) + 英 (anh, biểu âm). Nghĩa là ánh lấp lánh của ngọc, đá quý đẹp như ngọc. Chủ yếu dùng trong tên người (vì nghĩa đẹp đẽ, tao nhã). Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ánh sáng của viên ngọc; viên ngọc trong suốt", "Hạng Tần Suất (Jun Da)": "2992.0", "Tần Suất % (Jun Da)": "99.1754667337", "GavinGrover_Once (Chiết tự trực tiếp)": "王 + 英", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰王英", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "英", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "王", "Unihan_Simplified (Chữ Giản thể)": "瑛", "Unihan_Traditional (Chữ Phồn thể)": "瑛", "Pinyin_Xie": "yīng", "Âm Hán Việt_Xie": "anh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ dùng trong tên người để chỉ vẻ đẹp sáng trong của ngọc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('颐', '{"9000": "2993.0", "Chữ Trung Quốc": "颐", "Bộ thủ & thành phần_Xie": "Bộ thủ | 頁 | Số nét | 13 | nét | 𦣞 | biểu âm | cằm | 頁 | hiệt | biểu nghĩa | đầu người | 颐 (phồn thể: 頤) có thể là hội ý hoặc hình thanh tùy nguồn: 𦣞 (hình cái cằm, cũng biểu âm) + 頁 (đầu, biểu nghĩa). Wiktionary ghi \"có thể là tượng hình ban đầu (𦣞), sau kết hợp 頁 thành hình thanh hoặc hội ý\".", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"di\": đầu người (頁) với phần cằm (𦣞) — 颐 (di) là cái cằm, và \"di dưỡng\" là nuôi dưỡng thân tâm như Vườn Di Hòa (颐和园). | Gương Hán-Việt | \"di\" xuất hiện trong \"Di Hòa Viên\" (颐和园 — Cung Điện Mùa Hè Bắc Kinh), \"di dưỡng\" (颐养 — nuôi dưỡng sức khỏe). | Mở khoá kiến thức | Biết 颐 (di) là nhận ra 颐和园 (Di Hòa Viên), 颐养天年 (di dưỡng thiên niên — sống thọ), 颐指气使 (di chỉ khí sử — ra lệnh kiêu ngạo).", "Tự nguyên_Xie": "Đại triện | Tiểu triện | Theo Wiktionary, 颐 (phồn thể 頤) ban đầu có thể được viết là 𦣞, một chữ tượng hình của cái cằm. Dạng hiện đại là hội ý kiêm hình thanh: 𦣞 (cằm, biểu âm) + 頁 (đầu, biểu nghĩa). Nghĩa gốc là cằm, má; mở rộng sang nuôi dưỡng, dưỡng sinh (nuôi dưỡng thân thể). | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "môi, má; nuôi nấng, nuôi dưỡng; họ Di", "Hạng Tần Suất (Jun Da)": "2993.0", "Tần Suất % (Jun Da)": "99.1764434576", "GavinGrover_Once (Chiết tự trực tiếp)": "𦣞 + 页", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰𦣞页", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "𦣞", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "页", "Unihan_Simplified (Chữ Giản thể)": "颐", "Unihan_Traditional (Chữ Phồn thể)": "頤", "Pinyin_Xie": "yí", "Âm Hán Việt_Xie": "di", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường dùng trong các từ ghép chỉ việc dưỡng sinh hoặc các bộ phận trên khuôn mặt. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('忖', '{"9000": "2994.0", "Chữ Trung Quốc": "忖", "Bộ thủ & thành phần_Xie": "Bộ thủ | 心 | Số nét | 6 | nét | 忄 | tâm | biểu nghĩa | trái tim, tâm trạng | 寸 | thốn | biểu âm | 忖 = 忄(心 — Tâm, trái tim, biểu nghĩa) + 寸 (Thốn, biểu âm); chữ hình thanh. Trái tim (忄) suy nghĩ đo lường từng \"tấc\" (寸) — gợi nghĩa suy nghĩ kỹ lưỡng, đong đo.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thốn\": trái tim (忄) đo đếm từng \"tấc\" (寸) — 忖 (thốn) là suy nghĩ đong đo, cân nhắc kỹ trong lòng. | Gương Hán-Việt | \"thốn\" ít gặp riêng lẻ trong tiếng Việt; 忖度 (thốn độ — ước đoán, suy xét) là cụm quan trọng. | Mở khoá kiến thức | Biết 忖 (thốn) là nắm được 忖度 (thốn độ — ước đoán, suy xét tâm lý người khác), 忖量 (thốn lượng — cân nhắc).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 忖 là hình thanh: 忄(心 — tâm, biểu nghĩa) + 寸 (thốn, biểu âm). Nghĩa là suy nghĩ kỹ, đo lường, cân nhắc trong tâm trí. Chữ thường xuất hiện trong văn cổ và thành ngữ. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nghĩ kỹ", "Hạng Tần Suất (Jun Da)": "2994.0", "Tần Suất % (Jun Da)": "99.1774201815", "GavinGrover_Once (Chiết tự trực tiếp)": "忄 + 寸", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰忄寸", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "寸", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "忄", "Unihan_Simplified (Chữ Giản thể)": "忖", "Unihan_Traditional (Chữ Phồn thể)": "忖", "Pinyin_Xie": "cǔn", "Âm Hán Việt_Xie": "thốn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ biểu thị hoạt động suy nghĩ, tự nhủ thầm trong lòng. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('牡', '{"9000": "2995.0", "Chữ Trung Quốc": "牡", "Bộ thủ & thành phần_Xie": "Bộ thủ | 牛 | Số nét | 7 | nét | 牛 | ngưu | bộ phận | trâu, bò | 丄 | bộ phận | biểu tượng dương vật, giống đực | 牡 = 牛 (Ngưu — trâu/bò, biểu nghĩa) + 丄 (biểu nghĩa: một số thuyết cho rằng 丄 mô phỏng dương vật, chỉ giới đực); chữ hội ý. Sau này 丄 được viết thành 土. Tổng thể: con trâu đực.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mẫu\": trâu (牛) + ký hiệu giống đực (丄/土) — 牡 (mẫu) là con đực, như \"mẫu đơn\" (牡丹) hoa đực — hoa nở lớn kiêu hùng. | Gương Hán-Việt | \"mẫu\" xuất hiện trong \"mẫu đơn\" (牡丹 — hoa mẫu đơn, peony), và từ cổ 牡牛 (mẫu ngưu — bò đực). | Mở khoá kiến thức | Biết 牡 (mẫu) là nhận ra 牡丹 (mẫu đơn — hoa peony), 牡蛎 (mẫu lệ — con hàu), 牡鹿 (mẫu lộc — hươu đực).", "Tự nguyên_Xie": "Kim văn | Tiểu triện | Theo Wiktionary, 牡 là hội ý: 牛 (trâu/bò) + 丄 (có thuyết cho là mô phỏng dương vật, chỉ giới đực — sau này viết thành 土). Nghĩa là con đực của các loài gia súc, chim muông. Mở rộng sang mọi loài đực. Xem thêm nguồn gốc chữ này trong từ điển từ nguyên học. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "giống đực, con đực thuộc các loài chim muông", "Hạng Tần Suất (Jun Da)": "2995.0", "Tần Suất % (Jun Da)": "99.1783963886", "GavinGrover_Once (Chiết tự trực tiếp)": "牛 + 土", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰牛土", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "土", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "牛", "Unihan_Simplified (Chữ Giản thể)": "牡", "Unihan_Traditional (Chữ Phồn thể)": "牡", "Pinyin_Xie": "mǔ", "Âm Hán Việt_Xie": "mẫu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Chữ này thường làm định ngữ đứng trước danh từ để chỉ giới tính đực của động vật hoặc thực vật. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('缀', '{"9000": "2996.0", "Chữ Trung Quốc": "缀", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 11 | nét | 纟 | mịch | biểu nghĩa | sợi tơ, vải | 叕 | chuyết | biểu âm | nối liên tiếp (cho âm zhuì) | 缀 = 纟(Mịch, biểu nghĩa: sợi tơ) + 叕 (Chuyết, biểu âm); chữ hình thanh. Phồn thể 綴 dùng 糸 thay 纟. Bộ mịch chỉ hành động khâu, nối; 叕 cho âm zhuì.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chuyết\": sợi tơ (纟) nối liên tiếp (叕) từng mảnh vải lại — hình ảnh người thợ khâu điểm xuyết hoa văn lên áo. | Gương Hán-Việt | ''chuyết'' trong ''điểm chuyết'' (điểm xuyết — trang trí điểm xuyết), 点缀 (điểm trang) | Mở khoá kiến thức | Biết 缀 mở khoá: 点缀 (điểm xuyết, trang trí), 缀合 (ghép lại), 辍学 (nghỉ học — khác chữ nhưng hay nhầm)", "Tự nguyên_Xie": "缀 (phồn thể 綴) là chữ hình thanh: 糸/纟(sợi tơ) biểu nghĩa hành động khâu nối; 叕 biểu âm. Nghĩa gốc là ''nối liền, khâu lại bằng chỉ''. Từ đó mở rộng sang ''kết hợp, ghép lại'' và ''trang trí bằng cách thêm vào'' (điểm chuyet). Chưa có nguồn học thuật về glyph-origin cổ đại. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nối liền, khâu lại", "Hạng Tần Suất (Jun Da)": "2996.0", "Tần Suất % (Jun Da)": "99.1793715622", "GavinGrover_Once (Chiết tự trực tiếp)": "纟 + 叕", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰纟叕", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "叕", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "纟", "Unihan_Simplified (Chữ Giản thể)": "缀", "Unihan_Traditional (Chữ Phồn thể)": "綴", "Pinyin_Xie": "zhuì", "Âm Hán Việt_Xie": "xuyết", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ đứng trước tân ngữ để chỉ hành động khâu vá hoặc trang trí, tô điểm. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('徊', '{"9000": "2997.0", "Chữ Trung Quốc": "徊", "Bộ thủ & thành phần_Xie": "Bộ thủ | 彳 | Số nét | 9 | nét | 彳 | xích | biểu nghĩa | bước chân, di chuyển | 回 | hồi | biểu âm | quay lại (cho âm huái) | 徊 = 彳(Xích, biểu nghĩa: bước đi) + 回 (Hồi, biểu âm và biểu nghĩa gợi ý ''quay đi quay lại''); chữ hình thanh có gợi ý hội ý. Bộ xích chỉ hành trình; 回 vừa cho âm huái vừa gợi sự xoay vòng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hồi\": bước chân (彳) cứ quay về (回) mãi một chỗ — hình ảnh người bồi hồi đứng trước cửa nhà cũ, không nỡ rời đi. | Gương Hán-Việt | ''hồi'' trong ''bồi hồi'' (徘徊 — đi lại do dự), gợi cảm giác lưu luyến không muốn rời | Mở khoá kiến thức | Biết 徊 mở khoá: 徘徊 (bồi hồi, lưỡng lự), 低徊 (dùng dằng thấp thỏm)", "Tự nguyên_Xie": "徊 gần như chỉ dùng trong từ 徘徊 (bồi hồi, đi lại lưỡng lự). Wiktionary chỉ ghi Han etym mà không có mô tả glyph-origin cụ thể. Cấu trúc gồm 彳(bước đi) + 回 (quay vòng), gợi hành động đi đi lại lại không thoát ra được, không có nguồn học thuật chi tiết hơn. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: bồi hồi 徘徊)", "Hạng Tần Suất (Jun Da)": "2997.0", "Tần Suất % (Jun Da)": "99.1803457022", "GavinGrover_Once (Chiết tự trực tiếp)": "彳 + 回", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰彳回", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "回", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "彳", "Unihan_Simplified (Chữ Giản thể)": "徊", "Unihan_Traditional (Chữ Phồn thể)": "徊", "Pinyin_Xie": "huái", "Âm Hán Việt_Xie": "hồi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này chủ yếu kết hợp với chữ Bồi để tạo thành động từ liên miên chỉ hành động đi đi lại lại. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('梨', '{"9000": "2998.0", "Chữ Trung Quốc": "梨", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 11 | nét | 利 | lợi | biểu âm | lợi ích, sắc bén — cho âm lợi/lê | 木 | mộc | biểu nghĩa | cây, gỗ | 梨 = 利 (Lợi, biểu âm) + 木 (Mộc, biểu nghĩa: cây); chữ hình thanh. Wiktionary ghi: {{Han compound|利|木|ls=psc|c1=p|c2=s}}. Bộ mộc chỉ cây; 利 cho âm lí (gần lê). Cây lê thuộc loài cây ăn quả.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lê\": cây (木-Mộc) lợi (利-Lợi) — cây lê sinh lợi quả ngọt. Lê = quả lê. Giống tên tiếng Việt: quả lê. | Gương Hán-Việt | lê trong ''quả lê'' tiếng Việt — mượn thẳng từ Hán-Việt; 梨 đọc lê chính là tên quả này | Mở khoá kiến thức | Biết 梨 mở khoá: 梨花 (lê hoa – hoa lê), 梨子 (lê tử – quả lê), 梨园 (lê viên – sân khấu kịch truyền thống Trung Hoa).", "Tự nguyên_Xie": "梨 là chữ hình thanh: 木 (mộc – cây) biểu nghĩa, 利 (lợi) biểu âm. Wiktionary xác nhận cấu trúc psc. Nghĩa là cây lê, quả lê. Quả lê là loại quả phổ biến ở Trung Hoa từ cổ đại. Âm lí trong tiếng Trung gần với 利 (lì/lí). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "333.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Lợi (332) Mộc (108)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Lợi (số 332) ở trên chữ Mộc (số 108) . Chữ Lợi để chỉ âm, chữ Mộc (cây cối) để chỉ ý đây là tên một loại cây (cây lê). Giải thích sự chuyển ý: Chữ Lợi (sắc bén/lợi ích) chỉ âm, chữ Mộc (cây) chỉ ý. Cây (Mộc) cho ra loại quả nhiều nước, mang lại lợi ích (Lợi) sức khỏe là cây lê (Lê). *(Biến âm Hán Việt: Trong Hán ngữ cổ, chữ Lợi và chữ Lê có cách phát âm tương đồng hoặc chung gốc phụ âm. Quá trình Việt hóa đã làm âm đọc bị chênh lệch thành Lợi và Lê).*", "Nghĩa Tiếng Việt_Xie": "cây lê, quả lê", "Hạng Tần Suất (Jun Da)": "2998.0", "Tần Suất % (Jun Da)": "99.1813193254", "GavinGrover_Once (Chiết tự trực tiếp)": "利 + 木", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱利木", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "利", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "梨", "Unihan_Traditional (Chữ Phồn thể)": "梨", "Pinyin_Xie": "lí", "Âm Hán Việt_Xie": "lê", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ cây lê hoặc quả lê, thường đứng sau lượng từ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | Từ đơn | Từ vựng HSK 5: quả lê | / | lí | / | quả lê | Xuất hiện trong lộ trình | New HSK | New HSK 5 | · | Thức ăn và đồ uống | YCT | YCT 4 | · | Đồ ăn và đồ uống | HSK | HSK 5 | · | Thức ăn và đồ uống", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('肪', '{"9000": "2999.0", "Chữ Trung Quốc": "肪", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 8 | nét | 月 | nguyệt | biểu nghĩa | thịt, cơ thể (bộ nhục 肉 biến thể thành 月) | 方 | phương | biểu âm | phương hướng (cho âm fáng) | 肪 = 月/肉 (Nguyệt/Nhục, biểu nghĩa: thịt, cơ thể) + 方 (Phương, biểu âm); chữ hình thanh. Bộ nhục chỉ chất liệu cơ thể; 方 cho âm fáng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phương\": thịt (月/肉) theo hướng vuông (方) — mỡ lá bọc đều xung quanh nội tạng như một tấm đệm vuông vức. | Gương Hán-Việt | ''phương'' trong ''chất béo'' — 脂肪 (chi phương), ít gặp độc lập trong tiếng Việt | Mở khoá kiến thức | Biết 肪 mở khoá: 脂肪 (chất béo, mỡ), 脂肪酸 (axit béo), 脂肪肝 (gan nhiễm mỡ)", "Tự nguyên_Xie": "Tiểu triện | 肪 là chữ hình thanh: bộ 肉 (thịt) biểu nghĩa mỡ lá của động vật; 方 biểu âm với âm fáng. Nghĩa gốc và duy nhất là ''mỡ''. Hầu như chỉ dùng trong từ 脂肪 (chất béo). Tiểu triện xác nhận cấu trúc. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mỡ lá", "Hạng Tần Suất (Jun Da)": "2999.0", "Tần Suất % (Jun Da)": "99.182291915", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 方", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月方", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "方", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "肪", "Unihan_Traditional (Chữ Phồn thể)": "肪", "Pinyin_Xie": "fáng", "Âm Hán Việt_Xie": "phương", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này thường kết hợp với chữ Chỉ để tạo thành danh từ chỉ chất béo hoặc mỡ động vật. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('涕', '{"9000": "3000.0", "Chữ Trung Quốc": "涕", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 10 | nét | 氵 | thuỷ | biểu nghĩa | nước | 弟 | đệ | biểu âm | em trai (cho âm tì) | 涕 = 氵(Thuỷ, biểu nghĩa: chất lỏng, nước) + 弟 (Đệ, biểu âm); chữ hình thanh. Bộ thuỷ chỉ chất lỏng tiết ra; 弟 cho âm tì.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thế\": nước (氵) chảy ra như người em (弟) khóc nhớ anh — vừa nước mắt vừa nước mũi chảy xuống. | Gương Hán-Việt | ''thế'' trong ''thanh thế'' (nước mắt, khóc), ít dùng độc lập; 鼻涕 là từ thông dụng nhất | Mở khoá kiến thức | Biết 涕 mở khoá: 鼻涕 (nước mũi), 涕泪 (nước mắt nước mũi), 痛哭流涕 (khóc lóc thảm thiết)", "Tự nguyên_Xie": "Kim văn | Tiểu triện | Lục thư thông | 涕 là chữ hình thanh: 氵(水, nước) biểu nghĩa chất lỏng chảy ra từ cơ thể; 弟 biểu âm với âm tì. Nghĩa gốc bao gồm cả ''nước mắt'' và ''nước mũi''. Trong văn cổ, 涕 thường chỉ nước mắt; 泣 chỉ khóc thút thít. Kim văn và Lục thư thông xác nhận cấu trúc này. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nước mắt; nước mũi", "Hạng Tần Suất (Jun Da)": "3000.0", "Tần Suất % (Jun Da)": "99.183263471", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 弟", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵弟", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "弟", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "涕", "Unihan_Traditional (Chữ Phồn thể)": "涕", "Pinyin_Xie": "tì", "Âm Hán Việt_Xie": "thế", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ dịch tiết từ mắt hoặc mũi, thường làm tân ngữ cho động từ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
